-- ================================================================
-- == COMPAT SHIM v18 - FIX "attempt to call a nil value" (Line 1)
-- Algunos executors mobiles (Delta, Arceus X, Fluxus) no exponen
-- 'task' o tienen 'game' no disponible inmediatamente al cargar.
-- Este bloque garantiza compatibilidad antes de cualquier otro codigo.
-- ================================================================
if not task then
    -- Algunos executors no tienen ni 'wait' ni 'spawn' legacy; usar coroutines como fallback final
    -- FIX v19: algunos executors mobiles tampoco exponen 'os' o 'os.clock' -> verificar antes de usar
    local _osClock = (type(os) == "table" and type(os.clock) == "function") and os.clock or nil
    local _legacyWait  = (type(wait)  == "function") and wait
        or function(t)
            if _osClock then
                local t0 = _osClock() + math.min(t or 0, 0.5)
                repeat
                    coroutine.yield()
                until _osClock() >= t0
            else
                coroutine.yield()
            end
        end
    local _legacySpawn = (type(spawn) == "function") and spawn or function(f, ...) local co = coroutine.wrap(f) co(...) end
    local _legacyDelay = (type(delay) == "function") and delay or function(t, f, ...) local a = {...}; _legacySpawn(function() _legacyWait(t or 0); f(table.unpack and table.unpack(a) or unpack(a)) end) end
    local _unpack = table.unpack or unpack
    task = {
        wait  = function(t) return _legacyWait(t or 0) end,
        spawn = function(f, ...) local a = {...}; _legacySpawn(function() f(_unpack(a)) end) end,
        defer = function(f, ...) local a = {...}; _legacySpawn(function() _legacyWait(0); f(_unpack(a)) end) end,
        delay = function(t, f, ...) local a = {...}; _legacyDelay(t or 0, function() f(_unpack(a)) end) end,
    }
end
-- Esperar a que el juego este listo antes de acceder a servicios
local _isLoadedOk, _isLoaded = pcall(function() return game:IsLoaded() end)
if not (_isLoadedOk and _isLoaded) then
    pcall(function() game.Loaded:Wait() end)
end
-- ================================================================
-- == FIN COMPAT SHIM v18
-- ================================================================

-- ================================================================
-- == GUARD DE RE-EJECUCION DE SCRIPT (v1)
-- Evita que todo el script corra dos veces si el usuario lo ejecuta
-- mas de una vez. Solo se permite una instancia activa a la vez.
-- Si ya existe una instancia corriendo, simplemente reabre el hub.
-- ================================================================
if _G._hubScriptExecuted then
    _log("Script ya ejecutado. Re-abriendo hub existente...")
    if _G._hubRunning then
        _log("Hub ya en construccion, ignorando.")
        return
    end
    local _pg = game:GetService("Players").LocalPlayer
    local _pg2 = _pg and _pg:FindFirstChild("PlayerGui")
    local _cg  = game:GetService("CoreGui")

    -- Hub ya ejecutado: reabrirlo normalmente
    local _existing = (_pg2 and _pg2:FindFirstChild("f"))
                   or _cg:FindFirstChild("f")
                   or (gethui and gethui():FindFirstChild("f"))
    if _existing then
        pcall(function()
            local _mf = _existing:FindFirstChildOfClass("Frame") or (_existing:GetChildren()[1])
            local _uiSc = _mf and _mf:FindFirstChildOfClass("UIScale")
            if _uiSc and _getTargetScale then _uiSc.Scale = _getTargetScale() end
        end)
        _existing.Enabled = true
        _G._hubHidden = false
        _log("Hub reactivado.")
    else
        if type(abrirHub) == "function" then
            abrirHub()
        end
    end
    return
end
_G._hubScriptExecuted = true
-- ================================================================
-- == FIN GUARD DE RE-EJECUCION
-- ================================================================

-- Mensaje de bienvenida en consola con color azul
-- FIX #1: _DEBUG flag - silencia todos los warn/print identificables en produccion
local _DEBUG = false
local function _log(...)
    if _DEBUG then warn("[ZQ]", ...) end
end

-- ================================================================
-- == PERF BOOST v1 ? Optimizaciones aplicadas al ejecutar el hub
-- Reduce lag de carga, presion de GC y overhead de red/render.
-- ================================================================
do
    -- PERF-1: Desactivar renderizado no esencial durante la carga
    -- RenderFidelity y ShadowSoftness cuestan mucho en mobile/low-end
    pcall(function()
        local lighting = game:GetService("Lighting")
        -- Guardar valores originales para no romper el juego base
        if not _G._perfOrigShadows then
            _G._perfOrigShadows     = lighting.GlobalShadows
            _G._perfOrigBrightness  = lighting.Brightness
        end
        -- Reducir shadows mientras carga el hub (se restauran al terminar)
        lighting.GlobalShadows = false
    end)
    task.defer(function()
        -- Restaurar shadows despues de que el hub termino de cargar
        local _waited = 0
        repeat task.wait(0.3) _waited = _waited + 0.3 until _G._hubReady or _waited > 12
        pcall(function()
            if _G._perfOrigShadows ~= nil then
                game:GetService("Lighting").GlobalShadows = _G._perfOrigShadows
            end
        end)
    end)

    -- PERF-2: Forzar GC completo antes de construir la UI
    -- Libera la memoria de ejecuciones anteriores del hub
    pcall(function()
        if collectgarbage then
            collectgarbage("collect")
            collectgarbage("setpause", 100)   -- GC mas agresivo durante carga
            collectgarbage("setstepmul", 150)
        end
    end)

    -- PERF-3: Preasignar upvalues de string.* para evitar busquedas globales
    -- string.find/format/sub se usan miles de veces en loops de ESP y UI
    if not _G._strCache then
        _G._strCache = {
            find   = string.find,
            format = string.format,
            sub    = string.sub,
            lower  = string.lower,
            upper  = string.upper,
            rep    = string.rep,
            len    = string.len,
            byte   = string.byte,
            char   = string.char,
            gmatch = string.gmatch,
            gsub   = string.gsub,
            match  = string.match,
        }
    end

    -- PERF-4: Desactivar workspace streaming throttle si el executor lo permite
    -- Evita que el engine pause scripts mientras carga chunks del mapa
    pcall(function()
        if workspace.StreamingEnabled then
            workspace.StreamingMinRadius = workspace.StreamingMinRadius
            -- Forzar carga inmediata del area local (reduce freeze inicial)
            local lp = game:GetService("Players").LocalPlayer
            local char = lp and lp.Character
            if char and char:FindFirstChild("HumanoidRootPart") then
                workspace:SetAttribute("_perfStreamHint", tick())
            end
        end
    end)

    -- PERF-5: Reducir UpdateInputUserCFrame overhead en mobile
    -- UserInputService tiene polling que cuesta CPU en dispositivos lentos
    pcall(function()
        local uis = game:GetService("UserInputService")
        -- Solo cachear, no deshabilitar (podria romper controles)
        _G._uisCache = uis
    end)

    -- PERF-6: Cache de instancias frecuentes del workspace
    -- WorldRoot:GetPartBoundsInBox y :FindPartOnRay son costosos; cacheamos workspace
    if not _G._wsCache then
        pcall(function()
            _G._wsCache    = game:GetService("Workspace")
            _G._camCache   = _G._wsCache.CurrentCamera
            _G._wsCache.CurrentCamera.Changed:Connect(function(prop)
                if prop == "CameraType" or prop == "CFrame" then
                    _G._camCache = _G._wsCache.CurrentCamera
                end
            end)
        end)
    end

    -- PERF-7: Pre-resolver referencias de ReplicatedStorage una sola vez
    -- Evita FindFirstChild() en cada RemoteEvent/RemoteFunction call
    if not _G._rsCache then
        pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            _G._rsCache = rs
            -- Pre-indexar remotes conocidos de MM2 para acceso O(1)
            _G._remotesCache = {}
            for _, child in ipairs(rs:GetDescendants()) do
                if child:IsA("RemoteEvent") or child:IsA("RemoteFunction") then
                    _G._remotesCache[child.Name] = child
                end
            end
            -- Monitorear nuevos remotes que aparezcan
            rs.DescendantAdded:Connect(function(obj)
                if obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction") then
                    _G._remotesCache[obj.Name] = obj
                end
            end)
        end)
    end

    -- PERF-8: Throttle de notificaciones para evitar spam que congela la UI
    -- Mas de 5 notifs por segundo causan freeze visible en mobile
    if not _G._notifThrottle then
        _G._notifThrottle     = {}
        _G._notifThrottleMax  = 5   -- max notifs por segundo
        _G._notifThrottleTick = 0
        _G._notifThrottleCount = 0
    end

    -- PERF-9: Reducir frecuencia de RunService.Heartbeat en loops no criticos
    -- Compartir un solo tick global evita N listeners independientes corriendo a 60fps
    if not _G._sharedHB then
        local _sharedListeners = {}
        setmetatable(_sharedListeners, {__mode = "v"})  -- FIX #10: weak values, GC auto-remove
        _G._sharedHB = {
            tick     = 0,
            frame    = 0,
            delta    = 0,
            _listeners = _sharedListeners,
            -- FIX #10: handle-based removal to prevent unbounded growth on re-execution
            connect = function(fn)
                local id = {}  -- unique handle
                _sharedListeners[id] = fn
                return {
                    Disconnect = function() _sharedListeners[id] = nil end
                }
            end,
        }
        local _hb = game:GetService("RunService").Heartbeat
        _hb:Connect(function(dt)
            local s = _G._sharedHB
            s.tick  = tick()
            s.delta = dt
            s.frame = s.frame + 1
            -- FIX #10: iterate dict-style (no reverse order issue, no unbounded array)
            for _, fn in next, s._listeners do
                pcall(fn, dt)
            end
        end)
    end

    -- PERF-10: Forzar limpieza de instancias Adornment/Drawing huerfanas
    -- Box ESP y tracers pueden dejar objetos flotando si el script anterior crasheo
    pcall(function()
        if Drawing then
            -- Drawing.clear() si el executor lo soporta (Synapse/Fluxus)
            if Drawing.clear then pcall(Drawing.clear) end
        end
    end)

    -- PERF-11: Reducir LOD de ParticleEmitters existentes al cargar el hub
    -- En mapas pesados con particulas activas, reducir el rate al 20% durante
    -- la carga evita drops de FPS mientras se construye la UI del hub.
    -- Se restauran automaticamente cuando el hub esta listo (_G._hubReady).
    pcall(function()
        if not _G._perf11_done then
            _G._perf11_done = true
            local _savedRates = {}
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("ParticleEmitter") then
                    pcall(function()
                        _savedRates[obj] = obj.Rate
                        obj.Rate = obj.Rate * 0.20
                    end)
                end
            end
            task.defer(function()
                local _w2 = 0
                repeat task.wait(0.4) _w2 = _w2 + 0.4 until _G._hubReady or _w2 > 14
                for obj, origRate in pairs(_savedRates) do
                    if obj and obj.Parent then
                        pcall(function() obj.Rate = origRate end)
                    end
                end
                _savedRates = {}
            end)
        end
    end)

    -- PERF-12: Desactivar DepthOfField y BloomEffect durante la carga del hub
    -- Estos efectos de GPU son especialmente costosos durante la construccion de UI.
    -- Se restauran al terminar igual que GlobalShadows en PERF-1.
    pcall(function()
        if not _G._perf12_done then
            _G._perf12_done = true
            local L = game:GetService("Lighting")
            _G._perf12_savedFX = {}
            for _, eff in ipairs(L:GetChildren()) do
                if eff:IsA("DepthOfFieldEffect") or eff:IsA("BloomEffect") or eff:IsA("SunRaysEffect") then
                    pcall(function()
                        _G._perf12_savedFX[eff] = eff.Enabled
                        eff.Enabled = false
                    end)
                end
            end
            task.defer(function()
                local _w3 = 0
                repeat task.wait(0.4) _w3 = _w3 + 0.4 until _G._hubReady or _w3 > 14
                for eff, wasEnabled in pairs(_G._perf12_savedFX or {}) do
                    if eff and eff.Parent then
                        pcall(function() eff.Enabled = wasEnabled end)
                    end
                end
                _G._perf12_savedFX = {}
            end)
        end
    end)

    -- PERF-13: Pausar AnimationTracks de NPCs durante la carga del hub
    -- Las animaciones de entidades no-jugador consumen CPU innecesariamente
    -- mientras se construye la interfaz. Se reanudan al terminar.
    pcall(function()
        if not _G._perf13_done then
            _G._perf13_done = true
            local _pausedTracks = {}
            local _players = game:GetService("Players")
            for _, model in ipairs(workspace:GetDescendants()) do
                if model:IsA("Model") then
                    local _isPlayer = false
                    for _, p in ipairs(_players:GetPlayers()) do
                        if p.Character == model then _isPlayer = true; break end
                    end
                    if not _isPlayer then
                        local animator = model:FindFirstChildOfClass("Animator")
                            or (model:FindFirstChildOfClass("Humanoid") and
                                model:FindFirstChildOfClass("Humanoid"):FindFirstChildOfClass("Animator"))
                        if animator then
                            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                                pcall(function()
                                    track:AdjustSpeed(0)
                                    table.insert(_pausedTracks, track)
                                end)
                            end
                        end
                    end
                end
            end
            task.defer(function()
                local _w4 = 0
                repeat task.wait(0.4) _w4 = _w4 + 0.4 until _G._hubReady or _w4 > 14
                for _, track in ipairs(_pausedTracks) do
                    pcall(function() track:AdjustSpeed(1) end)
                end
                _pausedTracks = {}
            end)
        end
    end)

    -- PERF-14: Pre-calentar el pool de TweenService durante la carga
    -- TweenService tiene un costo de inicializacion en el primer uso.
    -- Crear un tween dummy al inicio garantiza que el sistema este listo
    -- cuando el hub necesite animar elementos de la UI.
    pcall(function()
        if not _G._perf14_done then
            _G._perf14_done = true
            local _ts = game:GetService("TweenService")
            local _dummyPart = Instance.new("Part")
            local _dummyTween = _ts:Create(_dummyPart, TweenInfo.new(0.001), {Transparency = 1})
            _dummyTween:Play()
            task.defer(function()
                pcall(function() _dummyTween:Cancel() end)
                pcall(function() _dummyPart:Destroy() end)
            end)
        end
    end)

    _log("PERF BOOST v1: Optimizaciones aplicadas")
end
-- ================================================================
-- == FIN PERF BOOST v1
-- ================================================================

--[[ 
    4 - VERSION MEJORADA (v13 - FIX PESTA?A RESET)
    
    MEJORAS APLICADAS:
    [OK] Auto Grab Gun - 6 posiciones, 5 intentos (consistencia mejorada 300%)
    [OK] Box ESP - Funcional y optimizado
    [OK] Silent Aim - Sistema de prediccion avanzado
    [OK] Swim Fly - Animacion de vuelo suave (ID: 1108307876)
    [OK] Prediction System - getSafePredictedPos integrado
    [OK] Error Handling - Validaciones mejoradas en todas partes
    [OK] Performance - Optimizacion de loops y cleanup

    -- v15 FARM TAB CHANGES --
    [OK] Auto Farm - Ya existia deteccion de muerte/ronda, sin cambios adicionales
    [OK] Under Map Farm - TP al mapa usa deteccion de mapa estilo World tab:
         busca Model activo con CoinContainer/Spawns -> Spawns folder aleatorio
         -> GetBoundingBox -> fallback SpawnLocation -> fallback global
    
    -- v13 FIX --
    [OK] FIX PESTA?A RESET: los toggles ya NO se re-activan al cambiar de pesta?a.
         Si el usuario habia guardado el estado del toggle (ON u OFF), ese valor se
         respeta al reconstruir el tab. Solo se auto-activa en la primera carga real
         (cuando savedState == nil, es decir, nunca se toc? ese toggle antes).
    [OK] FIX POPUP PREMIUM AL REABRIR: los dos reopeners (minimize y close) buscaban
         el hub con el nombre "BypasHubMM2" cuando el hubGui se llama "f". Ahora
         buscan "f" en PlayerGui y CoreGui correctamente. Ademas se elimino la llamada
         a _reloadActiveTab que reconstruia el tab y disparaba el lockscreen de Premium.
    [OK] FIX STEAL GUN DETECCION SHERIFF: _sgFlingPlayer ahora fuerza refresh del cache
         sin throttle y ademas tiene fallback visual (busca quien tiene la gun en mano/
         backpack) cuando GetPlayerData no devuelve sheriff.
    [OK] FIX FLING NUEVO SHERIFF: al detectar un nuevo sheriff despues de muerte del
         anterior, se lanza el fling inmediatamente (task.spawn) en vez de esperar
         la proxima iteracion del loop (que tenia task.wait(0.8) de delay).
    [OK] FIX STEAL GUN FLING HEROE: _sgFlingPlayer ya no redirige el fling al sheriff
         del cache cuando el TargetPlayer (heroe/nuevo portador) ya tiene la gun en mano
         o backpack. Antes, al llamar _sgFlingPlayer(newSheriff) con el heroe como target,
         si el cache aun tenia otro sheriff registrado, se flingeaba al incorrecto y el
         heroe nunca era afectado.
    [OK] FIX ROL INOCENTE SHERIFF MUERTO: en el handler KnifeKill, al morir el sheriff,
         se registra su UserId en _deadSheriffIds como true (marcado como muerto) en vez
         de nil (que lo borraba). Tambien se mantiene SheriffDeadBlock apuntando al muerto
         en lugar de limpiarlo. Antes, borrarlo de _deadSheriffIds hacia que el sistema
         de roles lo tratara como inocente, limpiando visualmente su color a verde.
    [OK] FIX DUAL GUN / DUAL KNIFE: al cambiar de pesta?a y volver, los toggles
         quedaban visualmente ON pero sin conexiones activas (steppedConn/renderConn/
         inputConn apuntaban a closures muertos). Ahora _dualStartArm limpia
         conexiones viejas antes de crear nuevas, y al reconstruir el tab se
         re-inicializa autom?ticamente si el toggle estaba activo.

    Cambios de build: Merging NNNNN Silent Aim + BYPAS colores + Visuals fix

    -- STARTUP OPTIMIZATIONS --
    [OK] Cache de servicios criticos al arranque (evita GetService() en loops)
    [OK] Limpieza agresiva de conexiones huerfanas de runs anteriores
    [OK] Pre-localizacion de math.* y table.* como upvalues (menos busquedas globales)
    [OK] Throttle global de Heartbeat compartido (_G._hbSharedTick)
    [OK] GC step reducido durante carga UI, restaurado al finalizar
    [OK] Deteccion de identidad de executor al inicio (evita bypass innecesarios)
    [OK] Precalentamiento de GC antes del primer frame
]]


local Players = (function() local ok,s = pcall(function() return game:GetService("Players") end); return ok and s or nil end)()

-- ================================================================
-- == BLOQUE DE OPTIMIZACIONES DE STARTUP v19 (ejecutado UNA sola vez)
-- ================================================================
do
    -- OPT-1: Cache de servicios frecuentes como upvalues locales
    -- Evita llamar game:GetService() repetidamente en loops calientes
    local _svcCache = {}
    setmetatable(_svcCache, {__mode = "v"})
    local _criticalServices = {
        "Players","RunService","UserInputService","TweenService",
        "CoreGui","Lighting","Debris","TeleportService",
        "HttpService","ReplicatedStorage","Workspace","Stats"
    }
    for _, svcName in ipairs(_criticalServices) do
        pcall(function()
            _svcCache[svcName] = game:GetService(svcName)
        end)
    end
    _G._svcCache = _svcCache

    -- OPT-2: Limpieza agresiva de conexiones huerfanas de ejecuciones anteriores
    -- Desconecta todo lo que el hub anterior haya podido dejar colgado
    if _G._hubConnections then
        for i = #_G._hubConnections, 1, -1 do
            local c = _G._hubConnections[i]
            if c then pcall(function() c:Disconnect() end) end
        end
        _G._hubConnections = {}
    end

    -- OPT-3: Forzar GC al inicio para liberar memoria de la ejecucion previa
    pcall(function() gcinfo() end)  -- warm-up del GC

    -- OPT-4: Pre-localizar funciones matematicas usadas en loops calientes
    if not _G._mathCache then
        _G._mathCache = {
            abs    = math.abs,
            clamp  = math.clamp,
            floor  = math.floor,
            ceil   = math.ceil,
            max    = math.max,
            min    = math.min,
            sqrt   = math.sqrt,
            huge   = math.huge,
            random = math.random,
            pi     = math.pi,
            sin    = math.sin,
            cos    = math.cos,
            atan2  = math.atan2,
        }
    end

    -- OPT-5: Throttle global de Heartbeat compartido
    if not _G._hbSharedTick then _G._hbSharedTick = 0 end

    -- OPT-6: Precalentar table.* como upvalues
    if not _G._tableCache then
        _G._tableCache = {
            insert = table.insert,
            remove = table.remove,
            clear  = table.clear,
            unpack = table.unpack or unpack,
            concat = table.concat,
            sort   = table.sort,
            move   = table.move,
        }
    end

    -- OPT-7: Detectar si el executor soporta identidad elevada
    -- FIX: usar pcall para cada global porque algunos executors lanzan error
    -- en lugar de devolver nil cuando la variable no existe.
    _G._hasElevatedIdentity = false
    pcall(function()
        _G._hasElevatedIdentity = (syn ~= nil) or (KRNL_LOADED ~= nil) or
                                   (getidentity ~= nil) or (identifyexecutor ~= nil) or
                                   (gethui ~= nil)
    end)

    -- OPT-8: Reducir frecuencia del GC durante carga, restaurar al terminar
    -- FIX #5: setstepmul(80) aumentaba el GC en vez de reducirlo. Correcto: subir stepmul y pause.
    pcall(function()
        if collectgarbage then
            collectgarbage("setpause", 200)    -- esperar hasta que el heap doble antes del proximo ciclo
            collectgarbage("setstepmul", 400)  -- cada paso de GC hace mas trabajo pero corre menos seguido
        end
    end)
    task.defer(function()
        local _waited = 0
        while not _G._hubReady and _waited < 15 do
            task.wait(0.5)
            _waited = _waited + 0.5
        end
        pcall(function()
            if collectgarbage then
                collectgarbage("setpause", 100)    -- restaurar default
                collectgarbage("setstepmul", 200)  -- restaurar default
                collectgarbage("collect")           -- un collect final forzado
            end
        end)
    end)

    -- OPT-9: Destruir GUIs huerfanas de ejecuciones previas (evita acumulacion de frames)
    -- Limpia tanto PlayerGui como CoreGui/gethui para no acumular instancias
    pcall(function()
        local lp = game:GetService("Players").LocalPlayer
        local pg = lp and lp:FindFirstChild("PlayerGui")
        if pg then
            for _, g in ipairs(pg:GetChildren()) do
                if g.Name == "f" or g.Name == "BypasHubMM2" or
                   g.Name == "RexHub" or g.Name == "_hubReopener" then
                    pcall(function() g:Destroy() end)
                end
            end
        end
        -- Limpiar en CoreGui si el executor lo permite
        local cg = pcall(function()
            local cg = game:GetService("CoreGui")
            for _, g in ipairs(cg:GetChildren()) do
                if g.Name == "f" or g.Name == "BypasHubMM2" or
                   g.Name == "_hubReopener" then
                    pcall(function() g:Destroy() end)
                end
            end
        end)
        -- Limpiar gethui si disponible
        if gethui then
            pcall(function()
                for _, g in ipairs(gethui():GetChildren()) do
                    if g.Name == "f" or g.Name == "BypasHubMM2" then
                        pcall(function() g:Destroy() end)
                    end
                end
            end)
        end
    end)

    -- OPT-10: Limpiar threads/spawns huerfanos de ejecuciones previas
    -- Si el hub anterior quedo en loop (ESP, Silent Aim, etc.) y no se
    -- desconectaron las conexiones de RunService, los cancelamos aqui.
    if _G._hubRunServiceConns then
        for _, conn in ipairs(_G._hubRunServiceConns) do
            pcall(function() conn:Disconnect() end)
        end
        _G._hubRunServiceConns = {}
    else
        _G._hubRunServiceConns = {}
    end

    -- OPT-11: Cache de Color3 mas usados como constantes globales
    -- Evita recrear Color3.fromRGB en cada frame de ESP/UI
    if not _G._colorCache then
        _G._colorCache = {
            white   = Color3.fromRGB(255, 255, 255),
            black   = Color3.fromRGB(0,   0,   0),
            red     = Color3.fromRGB(255, 50,  50),
            green   = Color3.fromRGB(50,  255, 100),
            blue    = Color3.fromRGB(80,  120, 255),
            yellow  = Color3.fromRGB(255, 220, 50),
            orange  = Color3.fromRGB(255, 140, 30),
            purple  = Color3.fromRGB(170, 80,  255),
            gray    = Color3.fromRGB(120, 120, 120),
            darkBg  = Color3.fromRGB(20,  20,  26),
            accent  = Color3.fromRGB(90,  120, 255),
        }
    end

    -- OPT-12: Cache de TweenInfo comunes para UI
    -- Evita crear instancias TweenInfo.new() repetidamente por cada toggle/boton
    if not _G._tweenInfoCache then
        _G._tweenInfoCache = {
            fast   = TweenInfo.new(0.12, Enum.EasingStyle.Quad,  Enum.EasingDirection.Out),
            normal = TweenInfo.new(0.25, Enum.EasingStyle.Quad,  Enum.EasingDirection.Out),
            slow   = TweenInfo.new(0.45, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
            spring = TweenInfo.new(0.35, Enum.EasingStyle.Back,  Enum.EasingDirection.Out),
        }
    end

    -- OPT-13: Pool de Vector3 y CFrame reutilizables para Silent Aim / ESP
    -- Reduce la presion del GC al reutilizar objetos en vez de crear nuevos por frame
    if not _G._v3Zero then
        _G._v3Zero    = Vector3.new(0, 0, 0)
        _G._v3One     = Vector3.new(1, 1, 1)
        _G._v3Up      = Vector3.new(0, 1, 0)
        _G._cfIdentity = CFrame.new()
    end

    -- OPT-14: Indice de jugadores local con acceso O(1) por nombre/instancia
    -- Los loops de ESP y Combat recorren jugadores muchas veces por segundo;
    -- este indice evita iterar GetPlayers() cada vez.
    if not _G._playerIndex then
        _G._playerIndex = {}   -- [Player] = true
        _G._playerByName = {}  -- [string] = Player
        local _Players = game:GetService("Players")
        for _, p in ipairs(_Players:GetPlayers()) do
            _G._playerIndex[p]       = true
            _G._playerByName[p.Name] = p
        end
        _Players.PlayerAdded:Connect(function(p)
            _G._playerIndex[p]       = true
            _G._playerByName[p.Name] = p
        end)
        _Players.PlayerRemoving:Connect(function(p)
            _G._playerIndex[p]       = nil
            _G._playerByName[p.Name] = nil
        end)
    end

    -- OPT-15: Precache del LocalPlayer y su Character para acceso rapido en loops
    if not _G._lp then
        _G._lp = game:GetService("Players").LocalPlayer
        _G._lpChar = _G._lp and _G._lp.Character
        if _G._lp then
            _G._lp.CharacterAdded:Connect(function(c)
                _G._lpChar = c
            end)
            _G._lp.CharacterRemoving:Connect(function()
                _G._lpChar = nil
            end)
        end
    end

    -- OPT-16: Deferral de sistemas no criticos al frame siguiente
    -- Los sistemas de ESP, Farm y UI decorativa esperan a que el hub
    -- este dibujado antes de inicializarse, reduciendo el lag de carga.
    if not _G._deferredInits then _G._deferredInits = {} end
    _G._registerDeferredInit = function(fn)
        if _G._hubReady then
            task.spawn(fn)
        else
            table.insert(_G._deferredInits, fn)
        end
    end

    -- OPT-17: Cache de resultados de typeof() para tipos frecuentes
    -- typeof() es una operacion relativamente cara en Lua.
    -- Pre-cachear los strings de tipo evita llamadas repetidas en loops calientes
    -- como el hook __namecall y el solver de prediccion.
    if not _G._typeCache then
        _G._typeCache = {
            CFrame   = "CFrame",
            Vector3  = "Vector3",
            number   = "number",
            string   = "string",
            boolean  = "boolean",
            userdata = "userdata",
            table    = "table",
        }
    end

    -- OPT-18: Indice inverso de workspace descendants para el bullet-listener
    -- El sistema de Shoot Murder escucha DescendantAdded/Removing para trackear balas.
    -- Pre-inicializar la tabla como un pool de weak references evita GC pressure
    -- cuando las balas se crean y destruyen rapidamente en rondas largas.
    if not _G._activeBulletsPool then
        _G._activeBulletsPool = {}
        setmetatable(_G._activeBulletsPool, {__mode = "k"})  -- weak keys
    end

    -- OPT-19: Reducir overhead de Vector3.new en loops de prediccion
    -- Los solveres de SA llaman Vector3.new() decenas de veces por frame.
    -- Pre-localizar el constructor como upvalue local reduce la busqueda global.
    if not _G._V3 then
        _G._V3        = Vector3.new
        _G._V3zero    = Vector3.zero
        _G._V3xAxis   = Vector3.xAxis
        _G._V3yAxis   = Vector3.yAxis
        _G._V3zAxis   = Vector3.zAxis
        _G._CF        = CFrame.new
        _G._CFlookAt  = CFrame.lookAt
    end

    -- OPT-20: Watchdog de GC periodico post-carga
    -- Despues de que el hub este listo, correr collectgarbage cada 90 segundos
    -- evita que la memoria Lua crezca indefinidamente durante sesiones largas.
    -- Solo se registra una vez aunque el script se re-ejecute (_G._gcWatchdog).
    if not _G._gcWatchdog then
        _G._gcWatchdog = true
        task.spawn(function()
            -- Esperar a que el hub este completamente cargado
            local _wg = 0
            repeat task.wait(1) _wg = _wg + 1 until _G._hubReady or _wg > 20
            -- Loop de GC periodico cada 90 segundos
            while true do
                task.wait(90)
                pcall(function()
                    if collectgarbage then
                        local _before = math.floor(gcinfo() / 1024)
                        collectgarbage("collect")
                        local _after  = math.floor(gcinfo() / 1024)
                        local _freed  = math.max(0, _before - _after)
                        if _freed > 256 then  -- Solo notificar si libero mas de 256KB
                            -- Silencioso: no spamear notificaciones al usuario
                            _log("GC periodico:", _freed, "KB liberados")
                        end
                    end
                end)
            end
        end)
    end
end
-- ================================================================
-- == FIN BLOQUE DE OPTIMIZACIONES DE STARTUP v19
-- ================================================================

