-- =====================================================================
-- AUTO-SAFE POR TOGGLE: cada toggle activo guarda su propio archivo .txt
-- Logica identica al LocalScript de referencia (fly_autosave_config.txt)
-- Al salir/unirse de nuevo: lee cada archivo y auto-activa si dice "true"
-- Carpeta: rex_toggles_<UserId>/  para no mezclar con el JSON global
-- =====================================================================
local _UID_STR      = tostring(Players.LocalPlayer and Players.LocalPlayer.UserId or "unknown")
local _TOGGLE_DIR   = "rex_toggles_" .. _UID_STR

-- Crear carpeta si no existe (makefolder es estandar en Synapse/Wave/Krnl)
pcall(function()
    if makefolder and not isfolder(_TOGGLE_DIR) then
        makefolder(_TOGGLE_DIR)
    end
end)

-- Convierte nombre del toggle a nombre de archivo seguro (sin chars raros)
local function _toggleFileName(nombre)
    -- Reemplazar caracteres no permitidos en nombres de archivo
    local safe = nombre:gsub("[%[%]%/%\\%:%*%?%\"%<%>%|%s]", "_"):gsub("__+", "_")
    return _TOGGLE_DIR .. "/" .. safe .. "_" .. _UID_STR .. ".txt"
end

-- Guardar estado de un toggle individual en su propio .txt
local function _saveToggleFile(nombre, enabled)
    pcall(function()
        if not (makefolder and isfolder) then return end
        if not isfolder(_TOGGLE_DIR) then makefolder(_TOGGLE_DIR) end
        local path = _toggleFileName(nombre)
        if type(writefile) == "function" then
            writefile(path, tostring(enabled))
        elseif type(syn) == "table" and syn.write_file then
            syn.write_file(path, tostring(enabled))
        end
        -- FIX LAG: actualizar el cache para que _readToggleFile no vuelva a disco
        if _toggleFileCache then _toggleFileCache[nombre] = enabled end
        _toggleFileStates[path] = enabled
    end)
end

-- Tabla de nombres de toggles que tienen archivo .txt guardado como true
-- FIX: declarada ANTES de _readToggleFile para evitar "attempt to index nil"
local _toggleFileStates = {}

-- Leer estado de un toggle individual desde su .txt
-- FIX LAG: usa el cache precargado (_toggleFileStates) en lugar de hacer I/O en cada llamada.
local _toggleFileCache = {}  -- cache por nombre: nombre -> true/false/nil
local function _readToggleFile(nombre)
    -- 1. Cache por nombre (hit mas comun)
    if _toggleFileCache[nombre] ~= nil then
        return _toggleFileCache[nombre]
    end
    -- 2. Cache por path (precargado al inicio con listfiles)
    local path = _toggleFileName(nombre)
    if _toggleFileStates[path] ~= nil then
        _toggleFileCache[nombre] = _toggleFileStates[path]
        return _toggleFileStates[path]
    end
    -- 3. Fallback a disco solo si no esta en ningun cache
    local result = nil
    pcall(function()
        if not (isfile and isfile(path)) then return end
        local ok, data
        if type(readfile) == "function" then
            ok, data = pcall(readfile, path)
        elseif type(syn) == "table" and syn.read_file then
            ok, data = pcall(syn.read_file, path)
        end
        if ok and type(data) == "string" then
            result = (data:lower():find("true") ~= nil)
        end
    end)
    _toggleFileCache[nombre] = result
    return result
end

-- _toggleFileStates declarado arriba (movido para fix orden de declaracion)

-- Escanear carpeta y precargar estados de todos los toggles guardados
pcall(function()
    if not (listfiles and isfolder and isfolder(_TOGGLE_DIR)) then return end
    local files = listfiles(_TOGGLE_DIR)
    for _, fpath in ipairs(files or {}) do
        -- Extraer nombre del archivo (sin extension)
        local fname = fpath:match("[/\\]([^/\\]+)$") or fpath
        if fname:sub(-4) == ".txt" then
            local ok2, content
            if type(readfile) == "function" then
                ok2, content = pcall(readfile, fpath)
            end
            if ok2 and type(content) == "string" then
                local isOn = (content:lower():find("true") ~= nil)
                -- Guardar por path para lookup rapido
                _toggleFileStates[fpath] = isOn
            end
        end
    end
end)

-- COMPAT FILE I/O: soporta Synapse X, Wave, Krnl, Fluxus, Delta, Arceus X, Comet
-- Intenta todos los metodos conocidos en orden de preferencia
local function _hubWriteFile(path, data)
    -- Synapse X v3 / Wave / Krnl / Delta / Comet
    if type(writefile) == "function" then
        local ok = (type(writefile)=="function") and pcall(function() writefile(path,data) end) or false
        if ok then return end
    end
    -- Synapse X v2
    if syn and syn.write_file then
        local ok = pcall(syn.write_file, path, data)
        if ok then return end
    end
    -- Fluxus
    if fluxus and fluxus.write_file then
        local ok = pcall(fluxus.write_file, path, data)
        if ok then return end
    end
    -- Arceus X / generic fallback
    if saveFile then
        pcall(saveFile, path, data)
    end
end

local function _hubReadFile(path)
    local ok, data
    -- Synapse X v3 / Wave / Krnl / Delta / Comet
    if type(readfile) == "function" then
        ok, data = (type(readfile)=="function") and pcall(function() return readfile(path) end) or false, nil
        if ok and type(data) == "string" and #data > 0 then return data end
    end
    -- Synapse X v2
    if syn and syn.read_file then
        ok, data = pcall(syn.read_file, path)
        if ok and type(data) == "string" and #data > 0 then return data end
    end
    -- Fluxus
    if fluxus and fluxus.read_file then
        ok, data = pcall(fluxus.read_file, path)
        if ok and type(data) == "string" and #data > 0 then return data end
    end
    -- Arceus X / generic fallback
    if loadFile then
        ok, data = pcall(loadFile, path)
        if ok and type(data) == "string" and #data > 0 then return data end
    end
    return nil
end

-- Verificar si el executor soporta escritura de archivos
local function _hubCanSaveFiles()
    local ok1 = pcall(function() return type(writefile) end)
    local ok2 = pcall(function() return type(readfile) end)
    if not ok1 or not ok2 then return false end
    return (type(writefile) == "function")
        or (type(syn) == "table" and type(syn.write_file) == "function")
        or (type(fluxus) == "table" and type(fluxus.write_file) == "function")
        or (type(saveFile) == "function")
end

