local HttpService = (function() local ok,s = pcall(function() return game:GetService("HttpService") end); return ok and s or nil end)()

local function _saveConfig()
    if not _G._autoSaveEnabled then return end
    if type(writefile) ~= "function" then return end
    local toSave = {}
    for k, v in pairs(_G._toggleStates or {}) do
        if not (_neverRestoreToggles and _neverRestoreToggles[k]) then
            toSave[k] = v
        end
    end
    if _G._hubSettings then
        local hs = _G._hubSettings
        -- Persistir TODOS los campos de _hubSettings
        local _hsPersistKeys = {
            "hubScale","hubOpacity","fontMode",
            "notifDuration","notifMuted","fpsLimit",
            "crosshairHidden","hudHidden","chatHidden",
            "lowRenderQuality","disableShadows","fullbright",
            "noParticles","noDecals","noDecoration","noSounds",
            "noPostFX","renderDistance","noBillboards","doubleColumn",
            "noTabAnimations","noMinMaxAnimations","disableClickSound",
            "disableKeybinds","undraggableButtons","allowHubDrag",
        }
        for _, k in ipairs(_hsPersistKeys) do
            if hs[k] ~= nil then toSave["__hs_" .. k] = hs[k] end
        end
        -- Forzar hubScale = 70 siempre en el guardado
        toSave["__hs_hubScale"] = 70
        -- Compatibilidad con saves anteriores (claves sin prefijo __hs_)
        toSave["__hubScale"] = 70
        if hs.hubOpacity then toSave["__hubOpacity"] = hs.hubOpacity end
    end
    -- FIX FONDOS: guardar ?ndice de fondo activo y tema previo para restaurarlos al reabrir
    if _G._hubBackgrounds then
        toSave["__bgIndex"] = _G._hubBackgrounds.current or 0
    end
    -- No guardar bgPrevTheme para evitar restaurar temas viejos
    -- Siempre guardar tema rosa
    toSave["__currentTheme"] = "Neon Green"
    local ok, json = pcall(function() return HttpService:JSONEncode(toSave) end)
    if ok and json then
        if type(writefile)=="function" then pcall(function() writefile(_CONFIG_FILE,json) end) end
    end
end

-- FIX LAG AUTOSAVE: throttle para que multiples toggles rapidos no llamen writefile en cada uno.
-- Los saves se agrupan y se ejecutan en un thread separado, nunca bloqueando el frame actual.
local _saveThrottlePending = false
local _saveThrottleDelay   = 1.5  -- segundos de espera antes de guardar (agrupa rafagas de toggles)

local _saveConfigThrottled = (function()
    return function()
        if not _G._autoSaveEnabled then return end
        if _saveThrottlePending then return end  -- ya hay un save programado, el estado actual se capturara cuando ejecute
        _saveThrottlePending = true
        task.delay(_saveThrottleDelay, function()
            _saveThrottlePending = false
            -- Correr el save en un spawn separado para no bloquear el hilo que llamo esto
            task.spawn(function()
                pcall(_saveConfig)
            end)
        end)
    end
end)()

local function _flushConfig()
    -- Flush inmediato (ej: al cerrar el juego): cancelar pending y guardar ya
    _saveThrottlePending = false
    task.spawn(function()
        pcall(_saveConfig)
    end)
end

local function _loadConfig()
    if not (isfile and isfile(_CONFIG_FILE)) then return end
    local ok, raw = (type(readfile)=="function") and pcall(function() return readfile(_CONFIG_FILE) end) or false, nil
    if not ok or type(raw) ~= "string" or raw == "" then return end
    local ok2, saved = pcall(function() return HttpService:JSONDecode(raw) end)
    if not ok2 or type(saved) ~= "table" then return end
    -- Forzar siempre tema rosa antes de procesar el resto
    saved["__currentTheme"] = "Neon Green"
    saved["__bgPrevTheme"]  = "Neon Green"
    local _restoredActiveCount = 0
    for k, v in pairs(saved) do
        if k:sub(1, 5) == "__hs_" then
            -- Restaurar campo de _hubSettings por clave prefijada
            _G._hubSettings = _G._hubSettings or {}
            local field = k:sub(6)
            -- NUNCA restaurar hubLayoutMode: siempre forzar Sidebar izquierda (modo 1)
            if field ~= "hubLayoutMode" then
                _G._hubSettings[field] = v
            end
        elseif k == "__hubScale" or k == "__hubOpacity" then
            -- Compatibilidad con saves anteriores
            _G._hubSettings = _G._hubSettings or {}
            if k == "__hubScale"   then _G._hubSettings.hubScale   = v end
            if k == "__hubOpacity" then _G._hubSettings.hubOpacity = v end
        elseif k == "__bgIndex" then
            -- FIX FONDOS: restaurar ?ndice de fondo guardado
            _G._hubBackgrounds = _G._hubBackgrounds or { current = 0 }
            local idx = tonumber(v) or 0
            _G._hubBackgrounds.current = idx
        elseif k == "__bgPrevTheme" then
            -- Siempre usar tema rosa, ignorar tema previo guardado
            _G._hubBgPrevTheme = "Neon Green"
        elseif k == "__currentTheme" then
            -- Siempre usar tema rosa (Neon Green redefinido como rosa)
            _G._hubSavedTheme = "Neon Green"
        elseif not (_neverRestoreToggles and _neverRestoreToggles[k]) then
            _G._toggleStates[k] = v
            if v == true then _restoredActiveCount = _restoredActiveCount + 1 end
        end
    end
    -- Restaurar flag de auto-save y sincronizar estado del toggle en UI
    if saved["Auto Save"] ~= nil then
        _G._autoSaveEnabled = saved["Auto Save"]
        _G._toggleStates["Auto Save"] = saved["Auto Save"]
    end
    _G._restoredActiveCount = _restoredActiveCount
    _G._restoredForPlayer = Players.LocalPlayer and Players.LocalPlayer.Name or nil
end

