-- Registros de etiquetas con clave de traduccion {obj, key, prefix, suffix}
local _LangObjects = {}
function RegisterLangLabel(obj, key, prefix, suffix)
    prefix = prefix or ""
    suffix = suffix or ""
    table.insert(_LangObjects, {obj=obj, key=key, prefix=prefix, suffix=suffix})
end

function ApplyLanguage(langName)
    _G.HubLanguage = langName
    local dict = _LangStrings[langName] or _LangStrings[" English"]
    for _, entry in ipairs(_LangObjects) do
        if entry.obj and entry.obj.Parent then
            local translated = dict[entry.key] or entry.obj.Text
 pcall(function() entry.obj.Text = entry.prefix .. translated .. entry.suffix end)
        end
    end
end



-- ===============================================================
-- FIX "exceeded limit 200 locals": colores + log envueltos en do..end
-- para liberar registros del scope top-level
-- ===============================================================
do
    local _P  = "\27[38;2;0;200;255m"
    local _S  = "\27[38;2;0;160;255m"
    local _A  = "\27[38;2;100;230;255m"
    local _D  = "\27[38;2;60;180;220m"
    local _R  = "\27[0m"
    local _B  = "\27[1m"
    local function _log(tag, msg, colorCode)
        local c = colorCode or _P
        print(c .. _B .. "[8]" .. _R .. " " .. c .. tag .. _R .. " " .. _D .. msg .. _R)
    end
    -- _logOK/_logINFO/_logWARN deben ser globales para usarse fuera del do
    function _logOK(msg)   _log("", msg, _S) end
    function _logINFO(msg) _log("*", msg, _P) end
    function _logWARN(msg) _log("", msg, _A) end
end


-- SafeCall y validators en do..end para liberar mas registros top-level
do
    function SafeCall(func, ...)
        if type(func) == "function" then
            return pcall(func, ...)
        end
        return false
    end

    function ValidatePlayer()
        if not LocalPlayer or not LocalPlayer.Character then
            return false
        end
        local hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        return hum and hum.Health > 0
    end

    function ValidateTarget(target)
        if not target or not target.Character then return false end
        local hum = target.Character:FindFirstChildOfClass("Humanoid")
        return hum and hum.Health > 0
    end
end

