-- ===================================================================
--  SISTEMA DE TOGGLES PREMIUM - ESTILO EXACTO
-- Basado en el codigo proporcionado
-- ===================================================================

function CreatePremiumToggle(parent, titleText, subtitleText, callback, defaultState)
    local mainFrame = Instance.new("Frame", parent)
    mainFrame.Size = UDim2.new(1, 0, 0, subtitleText and subtitleText ~= "" and 56 or 48)
    mainFrame.BackgroundTransparency = 1   -- sin fondo
    mainFrame.BorderSizePixel = 0

    _G._toggleStates = _G._toggleStates or {}
    local _ptKey = "PT_" .. titleText
    local savedPT = _G._toggleStates[_ptKey]
    local isToggled = (savedPT ~= nil) and savedPT or (defaultState or false)

    local C_STROKE_OFF  = Color3.fromRGB(30, 60, 180)
    local C_STROKE_ON   = Color3.fromRGB(  0, 200, 160)
    local C_TRACK_OFF   = Color3.fromRGB(30, 35, 90)
    local C_TRACK_ON    = Color3.fromRGB(  0, 180, 140)
    local C_TRACK_S_OFF = Color3.fromRGB(30, 60, 180)
    local C_TRACK_S_ON  = Color3.fromRGB(  0, 200, 160)

    -- ptStroke eliminado (sin rectangulo)
    local ptStroke = {Color = C_STROKE_OFF}  -- stub para que el resto del codigo no rompa

    local titleLabel = Instance.new("TextLabel", mainFrame)
    titleLabel.Name = "Title"
    titleLabel.Size = UDim2.new(1, -100, subtitleText and subtitleText ~= "" and 0.55 or 1, 0)
    titleLabel.Position = UDim2.new(0, 12, 0, 0)
    titleLabel.BackgroundTransparency = 1
    titleLabel.Text = titleText
    titleLabel.TextColor3 = Color3.fromRGB(255,255,255)
    titleLabel.TextSize = 13
    titleLabel.Font = Enum.Font.GothamBold
    titleLabel.TextXAlignment = Enum.TextXAlignment.Left
    titleLabel.TextTruncate = Enum.TextTruncate.AtEnd

    if subtitleText and subtitleText ~= "" then
        local subLabel = Instance.new("TextLabel", mainFrame)
        subLabel.Name = "Subtitle"
        subLabel.Size = UDim2.new(1, -80, 0.45, 0)
        subLabel.Position = UDim2.new(0, 12, 0.55, 0)
        subLabel.BackgroundTransparency = 1
        subLabel.Text = subtitleText
        subLabel.TextColor3 = ThemeColors.TextSecondary
        subLabel.TextSize = 10
        subLabel.Font = Enum.Font.Gotham
        subLabel.TextXAlignment = Enum.TextXAlignment.Left
        subLabel.TextTruncate = Enum.TextTruncate.AtEnd
    end

    local TRACK_W, TRACK_H = 110, 22
    local THUMB_W, THUMB_H = 44, 14
    local THUMB_PAD = 4

    local track = Instance.new("Frame", mainFrame)
    track.Size = UDim2.new(0, TRACK_W, 0, TRACK_H)
    track.Position = UDim2.new(1, -(TRACK_W + 10), 0.5, -TRACK_H/2)
    track.BackgroundColor3 = isToggled and C_TRACK_ON or C_TRACK_OFF
    track.BackgroundTransparency = 0.0
    track.BorderSizePixel = 0
    track.ZIndex = 11
    track.ClipsDescendants = false
    Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

    local trackStroke = Instance.new("UIStroke", track)
    trackStroke.Color = isToggled and C_TRACK_S_ON or C_TRACK_S_OFF
    trackStroke.Thickness = 0
    trackStroke.Transparency = 1

    local POS_ON  = UDim2.new(1, -(THUMB_W + THUMB_PAD), 0.5, -THUMB_H/2)
    local POS_OFF = UDim2.new(0, THUMB_PAD, 0.5, -THUMB_H/2)

    local thumb = Instance.new("Frame", track)
    thumb.Size = UDim2.new(0, THUMB_W, 0, THUMB_H)
    thumb.Position = isToggled and POS_ON or POS_OFF
    thumb.BackgroundColor3 = Color3.fromRGB(200, 220, 255)
    thumb.BackgroundTransparency = 0
    thumb.BorderSizePixel = 0
    thumb.ZIndex = 14
    Instance.new("UICorner", thumb).CornerRadius = UDim.new(0, 4)

    local numLabel = Instance.new("TextLabel", track)
    numLabel.Size = UDim2.new(0.5, 0, 1, 0)
    numLabel.Position = isToggled and UDim2.new(0, THUMB_PAD, 0, 0) or UDim2.new(0.5, 0, 0, 0)
    numLabel.BackgroundTransparency = 1
    numLabel.Text = isToggled and "1" or "0"
    numLabel.Font = Enum.Font.GothamBold
    numLabel.TextSize = 10
    numLabel.TextColor3 = ThemeColors.TextPrimary
    numLabel.TextXAlignment = Enum.TextXAlignment.Center
    numLabel.ZIndex = 13

    local clickBtn = Instance.new("TextButton", mainFrame)
    clickBtn.Size = UDim2.new(1, 0, 1, 0)
    clickBtn.BackgroundTransparency = 1
    clickBtn.Text = ""
    clickBtn.ZIndex = 15
    clickBtn.AutoButtonColor = false

    local function updateToggle(animate)
        local ti  = TweenInfo.new(animate and 0.20 or 0, Enum.EasingStyle.Quad)
        local tiB = TweenInfo.new(animate and 0.22 or 0, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        if animate then
            TweenService:Create(thumb,       tiB, {Position        = isToggled and POS_ON or POS_OFF}):Play()
            TweenService:Create(track,       ti,  {BackgroundColor3= isToggled and C_TRACK_ON or C_TRACK_OFF}):Play()
            TweenService:Create(trackStroke, ti,  {Color           = isToggled and C_TRACK_S_ON or C_TRACK_S_OFF}):Play()
            TweenService:Create(numLabel,    ti,  {Position        = isToggled and UDim2.new(0, THUMB_PAD, 0, 0) or UDim2.new(0.5, 0, 0, 0)}):Play()
            -- Animacion estrella: pulso de brillo al activar
            if isToggled then
                local thumbColor = Color3.fromRGB(180, 255, 230)
                TweenService:Create(thumb, TweenInfo.new(0.10, Enum.EasingStyle.Quad), {BackgroundColor3 = thumbColor, BackgroundTransparency = 0}):Play()
                task.delay(0.12, function()
                    TweenService:Create(thumb, TweenInfo.new(0.25, Enum.EasingStyle.Quad), {BackgroundColor3 = Color3.fromRGB( 50, 255, 180), BackgroundTransparency = 0}):Play()
                    -- pulso del stroke: brilla y vuelve
                    -- trackStroke hidden (border removed)
                end)
            else
                TweenService:Create(thumb, TweenInfo.new(0.20), {BackgroundColor3 = Color3.fromRGB(  3,   8,  18), BackgroundTransparency = 0}):Play()
            end
        else
            thumb.Position = isToggled and POS_ON or POS_OFF
            track.BackgroundColor3 = isToggled and C_TRACK_ON or C_TRACK_OFF
            trackStroke.Color = isToggled and C_TRACK_S_ON or C_TRACK_S_OFF
            numLabel.Position = isToggled and UDim2.new(0, THUMB_PAD, 0, 0) or UDim2.new(0.5, 0, 0, 0)
        end
        numLabel.Text = isToggled and "1" or "0"
        titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLabel.Font = Enum.Font.GothamBold
    end

    -- FIX MOBILE: Activated funciona en PC y touch; MouseButton1Click no detecta tap en celu
    clickBtn.Activated:Connect(function()
        isToggled = not isToggled
        _G._toggleStates[_ptKey] = isToggled
        updateToggle(true)
        PlayToggleSound(isToggled)
        if callback then callback(isToggled) end
    end)

    -- Sin hover de fondo (toggle completamente transparente)
    mainFrame.MouseEnter:Connect(function() end)
    mainFrame.MouseLeave:Connect(function() end)

    updateToggle(false)

    if isToggled and callback then
        local lower = titleText:lower()
        local isPhysical = lower:find("swim fly") or lower:find("fly %+") or lower:find("fly+")
            or (lower:find("fly") and not lower:find("firefly"))
            or lower:find("noclip") or lower:find("no%-clip")
            or lower:find("swim") or lower:find("float")
            or lower:find("spinbot") or lower:find("spin bot")
            or lower:find("ragdoll") or lower:find("orbit")
            or lower:find("bhop") or lower:find("bunny hop")
            or lower:find("fling self") or lower:find("auto fling")
        if not isPhysical then
            task.defer(function() pcall(callback, true) end)
        end
    end

    mainFrame.SetState = function(state)
        if isToggled ~= state then
            isToggled = state
            updateToggle(true)
        end
    end

    mainFrame.GetState = function()
        return isToggled
    end

    return mainFrame
end

