-- ===================================================================
-- SISTEMA DE ROLES -- reescrito simple y robusto
-- Fuente unica de verdad: evento RoundStart del servidor.
-- Sin GetPlayerData polling que sobreescribe con datos incompletos.
-- ===================================================================
local _roleCache = {
    murderer = nil, sheriff = nil, hero = nil,
    -- FIX ROLES: roles secundarios -- nunca estaban en cache, siempre aparecian como "Innocent"
    assassin = nil, zombie  = nil, survivor = nil,
    lastUpdate = 0, localRole = "Innocent"
}
-- FIX FLICKER: grace period -- no remover ESP si roundActive fue true en los ultimos 2s
_lastRoundActiveTs = 0
local _ROUND_ACTIVE_GRACE = 2.0  -- segundos de gracia antes de apagar ESP

-- Cache separado para el portador de la gun luego de que el sheriff muere.
-- NO se borra con _refreshRoleCache: el servidor tarda segundos en asignar "Hero"
-- y durante ese tiempo _roleCache.hero queda nil, rompiendo el fling al nuevo portador.
_heroGunCache = nil

-- FIX #5: usar _G para que el estado persista entre recargas del script sin colisiones globales
_G._roundStartRoleCallbacks = _G._roundStartRoleCallbacks or {}
_roundStartRoleCallbacks = _G._roundStartRoleCallbacks

task.spawn(function()
    local ok, rem = pcall(function()
        return game:GetService("ReplicatedStorage")
            :WaitForChild("Remotes", 10)
            :WaitForChild("Gameplay", 10)
            :WaitForChild("RoundStart", 10)
    end)
    if not ok or not rem then return end
    rem.OnClientEvent:Connect(function(_, playerData)
        if type(playerData) ~= "table" then return end

        _G._rolesCacheReady = false

        -- Resetear estado de ronda
        _G._visualRoundOver = false
        _G._murdererDied    = false
        _G._betweenRounds   = false
        _G._roundStartTime  = os.clock()  -- FIX #3: usar os.clock() para consistencia con polling loop
        _hlRoundEndDone     = false

        -- Farm BelowMap hook eliminado: el nuevo AutoFarm maneja su propia posicion

        -- Desconectar hook del murder anterior
        if _murdererDeathConn then
            pcall(function() _murdererDeathConn:Disconnect() end)
            _murdererDeathConn = nil
        end
        -- Desconectar hook del sheriff anterior
        if _sheriffDeathConn then
            pcall(function() _sheriffDeathConn:Disconnect() end)
            _sheriffDeathConn = nil
        end

        -- Limpiar espejos de skin al inicio de ronda (evita que queden de ronda anterior)
        local _rsChar = LocalPlayer.Character
        if _rsChar then
            local _rsSGL = _rsChar:FindFirstChild("SkinGunL")
            if _rsSGL then pcall(function() _rsSGL:Destroy() end) end
            local _rsDADN = _rsChar:FindFirstChild("DualADN_L")
            if _rsDADN then pcall(function() _rsDADN:Destroy() end) end
        end

        -- FIX STEAL GUN: limpiar sheriff viejo al inicio de cada ronda
        if StealGunSystem then
            -- FIX BUG 4: incrementar token para matar while-true de ronda anterior
            StealGunSystem._roundToken = (StealGunSystem._roundToken or 0) + 1
            StealGunSystem.sheriffOriginalFound = nil
            StealGunSystem.sheriffDeadDetected  = false
            StealGunSystem.roleCheckDisabled    = false
            StealGunSystem.gunInBackpackMode    = false
            -- FIX BUG 2: limpiar conns del cache de la ronda anterior
            if StealGunSystem._sgCacheConn then
                pcall(function() StealGunSystem._sgCacheConn:Disconnect() end)
                StealGunSystem._sgCacheConn = nil
            end
            if StealGunSystem._sgRemoveConn then
                pcall(function() StealGunSystem._sgRemoveConn:Disconnect() end)
                StealGunSystem._sgRemoveConn = nil
            end
        end
        if SheriffDeadBlock then
            SheriffDeadBlock.isDeadSheriffID = nil
            SheriffDeadBlock.deadSheriffName = nil
        end
        _detectSheriffDeathActive = false
        -- FIX: limpiar conn de DetectSheriffDeath para que la proxima ronda pueda re-hookear
        if _detectSheriffDeathConn then
            pcall(function() _detectSheriffDeathConn:Disconnect() end)
            _detectSheriffDeathConn = nil
        end

        -- Limpiar roleCache antes de repoblar
        _roleCache.murderer = nil
        _roleCache.sheriff  = nil
        _roleCache.hero     = nil
        -- FIX ROLES: limpiar tambien roles secundarios
        _roleCache.assassin = nil
        _roleCache.zombie   = nil
        _roleCache.survivor = nil
        _heroGunCache = nil

        -- Repoblar _roleCache con los roles nuevos
        for name, info in pairs(playerData) do
            if type(info) == "table" and info.Role then
                local role = tostring(info.Role)
                if name == Players.LocalPlayer.Name then
                    _roleCache.localRole = role
                end
                for _, p in ipairs(_cachedPlayers) do
                    if p.Name == name then
                        if     role == "Murderer" then _roleCache.murderer = p
                        elseif role == "Sheriff"  then _roleCache.sheriff  = p
                        elseif role == "Hero"     then _roleCache.hero     = p
                        -- FIX ROLES: guardar roles secundarios en cache
                        elseif role == "Assassin" then _roleCache.assassin = p
                        elseif role == "Zombie"   then _roleCache.zombie   = p
                        elseif role == "Survivor" then _roleCache.survivor = p
                        end
                        break
                    end
                end
            end
        end
        _roleCache.lastUpdate = 0

        -- PASO 1: Limpiar visuals SINCRONICAMENTE mientras _rolesCacheReady=false.
        -- El loop esta bloqueado en este intervalo, asi que no hay race condition.
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer then
                pcall(removeCham,    p)
                pcall(removeOutline, p)
                pcall(removeBox,     p)
            end
        end

        -- PASO 2: Limpiar _lastRoleCache DESPUES de limpiar visuals y repoblar roleCache.
        -- Asi el loop ve _lastRole[p]=nil vs curRole="Murderer" -> detecta cambio -> pinta.
        -- FIX ORDEN: antes se limpiaba antes de repoblar -> el loop podia correr entre
        -- repoblar y habilitar, ver el cambio, llamar removeCham, y tirar los visuals recien creados.
        if _G._lastRoleCache then
            for k in next, _G._lastRoleCache do
                _G._lastRoleCache[k] = nil
            end
        end

        -- PASO 3: Habilitar cache + forzar tick inmediato.
        -- A partir de aqui el loop detecta todos los cambios de rol y pinta de inmediato.
        _G._forceInstanceTick = true
        _G._rolesCacheReady = true

        -- FIX REPINTADO ROLES: limpiar hooks de ronda anterior para que se re-conecten en la nueva
        if _G._deathHookDone then
            for k in next, _G._deathHookDone do _G._deathHookDone[k] = nil end
        end
        if _G._deathHookChar then
            for k in next, _G._deathHookChar do _G._deathHookChar[k] = nil end
        end
        if _G._gunHookDone then
            for k in next, _G._gunHookDone do _G._gunHookDone[k] = nil end
        end
        -- FIX HERO DETECTION: limpiar flags de hero hook para que se re-hookeen en la nueva ronda
        if _G._heroHookDoneP then
            for k in next, _G._heroHookDoneP do _G._heroHookDoneP[k] = nil end
        end
        -- Re-hookear todos los jugadores para deteccion de hero en la nueva ronda
        if _G._hookPlayerHero then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then
                    task.defer(function() pcall(_G._hookPlayerHero, p) end)
                end
            end
        end
        -- FIX COLOR MUERTOS: limpiar _deadRoles al inicio de ronda
        -- para que los jugadores de la ronda anterior no queden pintados gris
        if _G._deadRoles then
            for k in next, _G._deadRoles do _G._deadRoles[k] = nil end
        end
        -- FIX: limpiar _deadSheriffIds -- si no se limpia, el mismo jugador que fue
        -- sheriff la ronda anterior queda bloqueado en StartSheriffDeathMonitor
        -- y nunca se registra como nuevo sheriff aunque lo sea esta ronda.
        if _G._deadSheriffIds then
            for k in next, _G._deadSheriffIds do _G._deadSheriffIds[k] = nil end
        end

        -- -- FIX SA RONDAS (Bugs 1 y 2) ---------------------------------------
        -- _posHistory y _predHistories acumulaban datos del murderer ANTERIOR.
        -- El solver los usaba en la ronda siguiente -> prediccion degradada.
        -- _pingEMA global arrastraba sesgos de lag de rondas previas.
        if _posHistory   then for k in next, _posHistory   do _posHistory[k]   = nil end end
        if _predHistories then for k in next, _predHistories do _predHistories[k] = nil end end
        if _histTimers   then for k in next, _histTimers   do _histTimers[k]   = nil end end
        _G._pingEMA = nil  -- forzar recalibracion limpia del EMA de ping
        -- ----------------------------------------------------------------------

        -- Hookear muerte del murderer, sheriff y hero inmediatamente
        if _roleCache.murderer then task.defer(function() _hookMurdererDeath(_roleCache.murderer) end) end
        if _roleCache.sheriff  then task.defer(function() _hookSheriffDeath(_roleCache.sheriff)  end) end
        if _roleCache.hero     then task.defer(function() _hookHeroDeath(_roleCache.hero)        end) end
        -- Hookear StealGun al nuevo sheriff si esta activo
        -- Ahora independiente de _roleCache: FindOriginalSheriff detecta por gun directo
        if StealGunSystem and StealGunSystem.enabled then
            task.defer(function()
                FindOriginalSheriff()
                -- Reiniciar el loop -- el token ya fue incrementado arriba,
                -- lo que mato el loop de la ronda anterior. Hay que crear uno nuevo.
                StealGunLoop()
            end)
        end

        local myRole = _roleCache.localRole or "Innocent"
        task.spawn(function()
            task.wait(0.1)
            for _, cb in pairs(_roundStartRoleCallbacks) do
                pcall(cb, myRole)
            end
        end)

        -- Lobby guard eliminado: el nuevo AutoFarm no usa _gMakePhysics
    end)
end)
Players.LocalPlayer.CharacterAdded:Connect(function()
    -- FIX DELAY 10s: NO limpiar _roleCache.murderer/sheriff/hero al respawnear.
    -- Antes se borraba todo aqui -> los visuals no sabian quien era el murderer/sheriff
    -- hasta el PROXIMO RoundStart (~10s de espera). El cache solo se limpia en RoundStart.
    _roleCache.localRole  = "Innocent"
    _roleCache.lastUpdate = 0
    -- Limpiar display de rol en pantalla (si Notify ROL activo)
    pcall(function()
        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            local sg = pg:FindFirstChild("BYPAS_NotifyRol")
            if sg then sg:Destroy() end
        end
    end)
    -- Limpiar Dead Cham ESP al respawnear (nueva ronda o muerte propia)
    task.defer(function()
        if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
        _deadBodies = {}
    end)
end)

-- ================================================================
-- FIX HERO DETECTION: hookear ChildAdded en Character Y Backpack
-- de todos los jugadores para detectar INSTANTANEAMENTE cuando un
-- inocente agarra la gun (no esperar el poll de GetPlayerData).
-- El rol Hero se asigna tanto si la gun esta en Backpack (sin equipar)
-- como si esta en Character (equipada). Sin este hook, el rol solo
-- se detecta cuando el jugador EQUIPA la gun (delay de 0.08-1s).
-- ================================================================
do
    local _heroHookConns  = {}  -- [player] = lista de conexiones
    local _heroHookDoneP  = {}  -- [player] = true (ya se hookeo esta ronda)

    local _HERO_GUN_NAMES = {
        GunDrop=true, DropGun=true, Gun=true,
        SheriffGun=true, HeroGun=true, GunModel=true,
    }

    local function _isGunTool(obj)
        if not obj or not obj:IsA("Tool") then return false end
        if _HERO_GUN_NAMES[obj.Name] then return true end
        local n = obj.Name:lower()
        return n:find("gun") or n:find("revolver") or n:find("pistol") or n:find("sheriff")
    end

    -- Promueve a p como Hero en roleCache (solo si no es Murderer/Sheriff)
    local function _promoteHero(p)
        if _G._visualRoundOver or _G._betweenRounds then return end
        if not _roleCache.murderer then return end  -- sin ronda activa
        if _roleCache.murderer == p then return end
        if _roleCache.sheriff  == p then return end
        if _roleCache.hero     == p then return end  -- ya es hero
        _roleCache.hero       = p
        _roleCache.lastUpdate = 0
        if p == LocalPlayer then
            _roleCache.localRole = "Hero"
        end
        _G._forceInstanceTick = true
    end

    local function _hookPlayerHero(p)
        if _heroHookDoneP[p] then return end
        _heroHookDoneP[p] = true

        -- Desconectar hooks anteriores si existen
        if _heroHookConns[p] then
            for _, c in ipairs(_heroHookConns[p]) do pcall(function() c:Disconnect() end) end
        end
        _heroHookConns[p] = {}
        local conns = _heroHookConns[p]

        local function _watchContainer(container)
            if not container then return end
            -- Detectar gun ya presente (ej: Sheriff que ya tenia gun antes del hook)
            for _, obj in ipairs(container:GetChildren()) do
                if _isGunTool(obj) then
                    _promoteHero(p)
                    return
                end
            end
            -- Detectar gun que llega
            local conn = container.ChildAdded:Connect(function(obj)
                if _isGunTool(obj) then
                    _promoteHero(p)
                end
            end)
            table.insert(conns, conn)
        end

        -- Hook Character actual (gun equipada aparece aqui)
        if p.Character then _watchContainer(p.Character) end
        -- Hook Backpack actual (gun agarrada sin equipar aparece aqui)
        local bp = p:FindFirstChildOfClass("Backpack")
        if bp then _watchContainer(bp) end

        -- Re-hookear cuando el jugador respawnee (nuevo Character)
        local charConn = p.CharacterAdded:Connect(function(newChar)
            _heroHookDoneP[p] = nil
            task.defer(function()
                if not _heroHookDoneP[p] then
                    _hookPlayerHero(p)
                end
            end)
        end)
        table.insert(conns, charConn)
    end

    -- Hookear todos los jugadores actuales y futuros
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            pcall(_hookPlayerHero, p)
        end
    end
    Players.PlayerAdded:Connect(function(p)
        if p ~= LocalPlayer then
            pcall(_hookPlayerHero, p)
        end
    end)
    Players.PlayerRemoving:Connect(function(p)
        if _heroHookConns[p] then
            for _, c in ipairs(_heroHookConns[p]) do pcall(function() c:Disconnect() end) end
            _heroHookConns[p] = nil
        end
        _heroHookDoneP[p] = nil
    end)

    -- Exponer globalmente para que RoundStart limpie flags al inicio de ronda
    _G._heroHookDoneP  = _heroHookDoneP
    _G._heroHookConns  = _heroHookConns
    _G._hookPlayerHero = _hookPlayerHero
end
-- ================================================================

function _detectLocalRole()
    -- REMOVIDO: deteccion por knife/gun en el Character/Backpack.
    -- Solo usar _roleCache (RoundStart) y GUI del juego para el rol local.
    -- Fallback: leer el label de rol del GUI del juego
    local ok, roleText = pcall(function()
        local pg = LocalPlayer.PlayerGui
        for _, gui in pairs(pg:GetChildren()) do
            for _, desc in pairs(gui:GetDescendants()) do
                if desc:IsA("TextLabel") and desc.Name == "Role" then
                    local t = tostring(desc.Text):lower()
                    if t:find("murder") or t:find("sheriff") or t:find("hero") then
                        return desc.Text
                    end
                end
            end
        end
        local rg = pg:FindFirstChild("CrossPlatform") or pg:FindFirstChild("MainGUI")
        if not rg then return "" end
        local rs = rg:FindFirstChild("RoleSelection") or rg:FindFirstChild("Game")
        if not rs then return "" end
        local desktop = rs:FindFirstChild("Desktop") or rs:FindFirstChild("RoleSelector")
        if not desktop then return "" end
        local roleLabel = desktop:FindFirstChild("Role")
        return roleLabel and roleLabel.Text or ""
    end)
    if ok and roleText and roleText ~= "" then
        local r = tostring(roleText):lower()
        if     r:find("murder")  then return "Murderer"
        elseif r:find("hero")    then return "Hero"
        elseif r:find("sheriff") then return "Sheriff"
        end
    end
    -- Fallback final: usar el cache de RoundStart si existe
    if _roleCache.localRole and _roleCache.localRole ~= "" then
        return _roleCache.localRole
    end
    return "Innocent"
end
function _refreshRoleCache()
    local now = os.clock()
    if now - _roleCache.lastUpdate < 0.25 then return end
    _roleCache.lastUpdate = now

    _roleCache.localRole = _detectLocalRole()

    -- Intentar GetPlayerData del servidor (fuente mas confiable de roles de otros jugadores)
    local GetPlayerData = ReplicatedStorage:FindFirstChild("GetPlayerData", true)
    if GetPlayerData then
        local ok, data = pcall(function() return GetPlayerData:InvokeServer() end)
        if ok and type(data) == "table" then
            _roleCache.murderer = nil
            _roleCache.sheriff  = nil
            _roleCache.hero     = nil
            -- FIX ROLES: limpiar roles secundarios antes de repoblar
            _roleCache.assassin = nil
            _roleCache.zombie   = nil
            _roleCache.survivor = nil
            for plrName, pdata in pairs(data) do
                local p = Players:FindFirstChild(plrName)
                if p and type(pdata) == "table" and pdata.Role then
                    if p == LocalPlayer then
                        _roleCache.localRole = pdata.Role
                    end
                    if p ~= LocalPlayer then
                        if     pdata.Role == "Murderer" then _roleCache.murderer = p
                        elseif pdata.Role == "Sheriff"  then _roleCache.sheriff  = p
                        elseif pdata.Role == "Hero"     then _roleCache.hero     = p
                        -- FIX ROLES: guardar roles secundarios
                        elseif pdata.Role == "Assassin" then _roleCache.assassin = p
                        elseif pdata.Role == "Zombie"   then _roleCache.zombie   = p
                        elseif pdata.Role == "Survivor" then _roleCache.survivor = p
                        end
                    end
                end
            end
            return  -- GetPlayerData funciono, no necesitamos fallback visual
        end
    end

    -- FALLBACK HERO: si GetPlayerData fallo y no hay hero en cache,
    -- buscar quien tiene la gun entre jugadores que NO son Murderer ni Sheriff.
    -- Esto NO causa falsos positivos porque:
    --   1. Solo aplica cuando GetPlayerData fallo (retorno arriba si funciono)
    --   2. Solo asigna Hero, nunca Murderer/Sheriff
    --   3. Solo busca si hay ronda activa (murderer conocido)
    if _G._visualRoundOver then return end
    if _roleCache.hero == nil and _roleCache.murderer ~= nil and _findGunIn then
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer
            and p ~= _roleCache.murderer
            and p ~= _roleCache.sheriff
            and p.Character then
                local hasGun = _findGunIn(p.Character)
                if not hasGun then
                    local bp = p:FindFirstChildOfClass("Backpack")
                    hasGun = bp and _findGunIn(bp)
                end
                if hasGun then
                    _roleCache.hero = p
                    break
                end
            end
        end
    end
end

-- FIX #8: Separar lectura de roles del refresh con InvokeServer.
-- Estas funciones son llamadas desde ESP/SA/Aimbot a 60fps; no deben hacer server calls.
-- Solo el loop de polling dedicado (Issue #2) llama InvokeServer.
function findMurderer()
    return _roleCache.murderer  -- FIX #8: pure read, sin side effects de servidor
end

function findSheriffPlayer()
    return _roleCache.sheriff  -- FIX #8: pure read
end

function findHeroPlayer()
    return _roleCache.hero  -- FIX #8: pure read; el polling loop se encarga del refresh
end

-- ==========================================================
-- HOOKS ADICIONALES DE ESTADO DE RONDA
-- ==========================================================
_G._roundStartTime  = _G._roundStartTime  or 0
_G._visualRoundOver   = _G._visualRoundOver   or false
_G._murdererDied      = _G._murdererDied      or false
-- FIX COLOR MUERTOS: tabla de jugadores muertos esta ronda con su rol original.
-- Cuando sheriff/murderer/hero muere, _roleCache.X se limpia (= nil),
-- pero sin esta tabla updateCham los ve como "Innocent" y los pinta verde.
-- Con esta tabla los pinta gris aunque ya no esten en _roleCache.
_G._deadRoles = _G._deadRoles or {}  -- [player] = "Sheriff"|"Murderer"|"Hero"
_G._betweenRounds     = _G._betweenRounds     or false  -- TRUE durante transicion entre rondas (mapa viejo destruido, RoundStart no llego aun)
_G._rolesCacheReady   = true  -- TRUE = cache listo para pintar. FALSE = repoblando (RoundStart en curso)
_G._roundTimerRunning = _G._roundTimerRunning or false  -- TRUE mientras el contador de ronda (RoundTimerPart) esta activo; oculta NotifyRol

-- WATCHDOG: nunca dejar _betweenRounds=true o _rolesCacheReady=false por mas de 4s sin RoundStart
task.spawn(function()
    local _lastBetweenTrue = 0
    local _lastCacheNotReady = 0
    while true do
        task.wait(2)  -- OPT: 1s?2s, watchdog no necesita 1Hz
        local now = tick()
        if _G._betweenRounds then
            if _lastBetweenTrue == 0 then _lastBetweenTrue = now end
            if (now - _lastBetweenTrue) > 4 then
                _G._betweenRounds   = false
                _G._rolesCacheReady = true
                _G._forceInstanceTick = true
                _lastBetweenTrue = 0
            end
        else
            _lastBetweenTrue = 0
        end
        if _G._rolesCacheReady == false then
            if _lastCacheNotReady == 0 then _lastCacheNotReady = now end
            if (now - _lastCacheNotReady) > 2 then
                _G._rolesCacheReady = true
                _G._forceInstanceTick = true
                _lastCacheNotReady = 0
            end
        else
            _lastCacheNotReady = 0
        end
    end
end)

-- Hook muerte del Murder: limpia su rol inmediatamente
_murdererDeathConn = nil
function _hookMurdererDeath(murderer)
    if not murderer or not murderer.Character then return end
    if _murdererDeathConn then
        pcall(function() _murdererDeathConn:Disconnect() end)
        _murdererDeathConn = nil
    end
    local mHum = murderer.Character:FindFirstChildOfClass("Humanoid")
    if not mHum then return end
    -- FIX RONDAS: snapshot del token en el momento de hookear
    -- Si el token cambia (nueva ronda), el handler no escribe en _deadRoles
    local _hookRoundToken = _G._sgRoundToken or 0
    _murdererDeathConn = mHum.Died:Connect(function()
        -- FIX: ignorar si ya pasamos a una ronda nueva
        if (_G._sgRoundToken or 0) ~= _hookRoundToken then return end
        _G._murdererDied      = true
        _roleCache.murderer   = nil
        _roleCache.lastUpdate = 0
        if _murdererDeathConn then
            pcall(function() _murdererDeathConn:Disconnect() end)
            _murdererDeathConn = nil
        end
        -- DEATH HL: limpiar highlight del murderer inmediatamente y pintar verde
        task.defer(function()
            if (_G._sgRoundToken or 0) ~= _hookRoundToken then return end
            local dc = murderer and murderer.Character
            if dc then
                -- Limpiar highlight rol (murderer rojo -> quitar)
                if _hl_remove then pcall(_hl_remove, dc) end
                -- Pintar verde cham (Piece chams)
                local GREEN_COL = Color3.fromRGB(  0, 255, 160)
                pcall(function() _aplicarPieceChams(dc, GREEN_COL) end)
                if chamHighlight then chamHighlight[murderer] = dc end
            end
        end)
        task.delay(1.5, function()
            if (_G._sgRoundToken or 0) ~= _hookRoundToken then return end
            if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
            _deadBodies = {}
        end)
    end)
end

-- ================================================================
-- Hook muerte del Sheriff via KnifeKill remote (reemplaza sHum.Died)
-- Detecta KnifeKill en RS.Remotes.Gameplay, pinta al sheriff de verde
-- y limpia todos los datos del sheriff viejo.
-- ================================================================
_sheriffDeathConn = nil
_G._knifeKillConn = _G._knifeKillConn or nil

task.spawn(function()
    local _kkOk, _kkRemote = pcall(function()
        return game:GetService("ReplicatedStorage")
            :WaitForChild("Remotes", 10)
            :WaitForChild("Gameplay", 10)
            :WaitForChild("KnifeKill", 10)
    end)
    if not _kkOk or not _kkRemote then return end
    if _G._knifeKillConn then
        pcall(function() _G._knifeKillConn:Disconnect() end)
        _G._knifeKillConn = nil
    end
    -- FIX: KnifeKill puede ser RemoteEvent o BindableEvent segun el servidor.
    -- RemoteEvent usa OnClientEvent, BindableEvent usa Event.
    local _kkSignal = nil
    if _kkRemote:IsA("RemoteEvent") then
        _kkSignal = _kkRemote.OnClientEvent
    elseif _kkRemote:IsA("BindableEvent") then
        _kkSignal = _kkRemote.Event
    end
    if not _kkSignal then return end
    _G._knifeKillConn = _kkSignal:Connect(function(killedPlayer)
        local sheriff = _roleCache and _roleCache.sheriff
        if not sheriff or killedPlayer ~= sheriff then return end
        local _roundToken = _G._sgRoundToken or 0
        task.defer(function()
            -- Limpiar datos del sheriff viejo
            _roleCache.sheriff    = nil
            _roleCache.lastUpdate = 0
            if sheriff == LocalPlayer then _roleCache.localRole = "Innocent" end
            if _sheriffDeathConn then
                pcall(function() _sheriffDeathConn:Disconnect() end)
                _sheriffDeathConn = nil
            end
            -- FIX ROL INOCENTE: mantener SheriffDeadBlock apuntando al sheriff muerto
            -- para que StartSheriffDeathMonitor y el sistema de chams lo reconozcan como muerto.
            -- Antes se limpiaba a nil aqui, haciendo que el sheriff muerto perdiera su rol
            -- y apareciera como inocente (verde) en los chams y en GetPlayerRole.
            if SheriffDeadBlock then
                SheriffDeadBlock.isDeadSheriffID = sheriff.UserId
                SheriffDeadBlock.deadSheriffName = sheriff.Name
            end
            -- FIX ROL INOCENTE: marcar al sheriff como muerto (= true), NO borrarlo (= nil).
            -- Poner nil lo eliminaba de la tabla -> el sistema dejaba de reconocerlo como sheriff muerto
            -- y lo trataba como inocente en _refreshRoleCache / StartSheriffDeathMonitor.
            if _G._deadSheriffIds and sheriff.UserId then
                _G._deadSheriffIds[sheriff.UserId] = true
            end
            if StealGunSystem then
                StealGunSystem.sheriffDeadDetected = true
                StealGunSystem.roleCheckDisabled   = true
            end
            -- Pintar sheriff muerto de verde
            local dc = sheriff.Character
            if dc then
                if _hl_remove then pcall(_hl_remove, dc) end
                pcall(function() _aplicarPieceChams(dc, Color3.fromRGB(0, 255, 160)) end)
                if chamHighlight then chamHighlight[sheriff] = dc end
            end
            -- Promover Hero a nuevo Sheriff visual
            local prevHero = _roleCache and _roleCache.hero
            if prevHero and prevHero.Character then
                _roleCache.sheriff    = prevHero
                _roleCache.hero       = nil
                _roleCache.lastUpdate = 0
                local hc = prevHero.Character
                if hc then
                    if _hl_remove then pcall(_hl_remove, hc) end
                    pcall(function() _aplicarPieceChams(hc, Color3.fromRGB(0, 140, 255)) end)
                    if chamHighlight then chamHighlight[prevHero] = hc end
                end
                task.defer(function()
                    if (_G._sgRoundToken or 0) ~= _roundToken then return end
                    pcall(_hookSheriffDeath, prevHero)
                end)
            end
            _G._forceInstanceTick = true
        end)
    end)
end)

function _hookSheriffDeath(sheriff)
    -- La deteccion de muerte usa KnifeKill (listener arriba).
    -- Esta funcion solo limpia conns viejas y actualiza SheriffDeadBlock.
    if _sheriffDeathConn then
        pcall(function() _sheriffDeathConn:Disconnect() end)
        _sheriffDeathConn = nil
    end
    if sheriff and SheriffDeadBlock then
        SheriffDeadBlock.isDeadSheriffID = sheriff.UserId
        SheriffDeadBlock.deadSheriffName = sheriff.Name
    end
end

-- BLOQUE ELIMINADO (logica antigua de sHum.Died - reemplazada por KnifeKill)
-- Se deja como do..end vacio para no romper el scope de Lua
do local _LEGACY_SHERIFF_DIED_REMOVED = true -- bloque eliminado; cierra el do..end abajo
--[[ ELIMINADO: cuerpo antiguo de sHum.Died que detectaba muerte del sheriff.
     Fue reemplazado por el listener de KnifeKill (RS.Remotes.Gameplay.KnifeKill).
     Se conserva el do..end para no romper el scope de Lua. ]]
end  -- cierra do local _LEGACY_SHERIFF_DIED_REMOVED

-- Hook muerte del Hero: limpia su rol y HL inmediatamente
_heroDeathConn = nil
function _hookHeroDeath(hero)
    if not hero or not hero.Character then return end
    if _heroDeathConn then
        pcall(function() _heroDeathConn:Disconnect() end)
        _heroDeathConn = nil
    end
    local hHum = hero.Character:FindFirstChildOfClass("Humanoid")
    if not hHum then return end
    local _hookRoundToken = _G._sgRoundToken or 0
    _heroDeathConn = hHum.Died:Connect(function()
        if (_G._sgRoundToken or 0) ~= _hookRoundToken then return end
        _roleCache.hero       = nil
        _roleCache.lastUpdate = 0
        if _heroDeathConn then
            pcall(function() _heroDeathConn:Disconnect() end)
            _heroDeathConn = nil
        end
        -- DEATH HL: Hero muere -> verde (inocente), sin mas rol
        task.defer(function()
            if (_G._sgRoundToken or 0) ~= _hookRoundToken then return end
            local dc = hero and hero.Character
            if dc then
                if _hl_remove then pcall(_hl_remove, dc) end
                local GREEN_COL = Color3.fromRGB(  0, 255, 160)
                pcall(function() _aplicarPieceChams(dc, GREEN_COL) end)
                if chamHighlight then chamHighlight[hero] = dc end
            end
        end)
    end)
end

-- Hook global RoundEnd: marca ronda terminada
task.spawn(function()
    local ok, reEv = pcall(function()
        return game:GetService("ReplicatedStorage")
            :WaitForChild("Remotes", 10)
            :WaitForChild("Gameplay", 10)
            :WaitForChild("RoundEnd", 10)
    end)
    if not ok or not reEv then return end
    reEv.OnClientEvent:Connect(function()
        _G._visualRoundOver  = true
        _G._murdererDied     = false
        _G._betweenRounds    = true
        -- FIX SHERIFF VIEJO: incrementar token para matar loop StealGun activo
        _G._sgRoundToken     = (_G._sgRoundToken or 0) + 1
        -- Limpiar monitor de GunDrop al fin de ronda
        if _G._gunDropMonitorConn then
            pcall(function() _G._gunDropMonitorConn:Disconnect() end)
            _G._gunDropMonitorConn = nil
        end
        _roleCache.murderer  = nil
        _roleCache.sheriff   = nil
        _roleCache.hero      = nil
        -- FIX ROLES: limpiar roles secundarios en RoundEnd
        _roleCache.assassin  = nil
        _roleCache.zombie    = nil
        _roleCache.survivor  = nil
        _roleCache.localRole = "Innocent"
        _roleCache.lastUpdate = 0
        _hlRoundEndDone = false
        -- FIX LIMPIEZA ROLES: el instanceLoop pasa a 1.2s al detectar _visualRoundOver,
        -- dejando roles pintados hasta 1.2s despues. Forzar tick inmediato + limpiar visuals
        -- para que murderer/sheriff/hero queden en el color correcto de fin de ronda al instante.
        _G._forceInstanceTick = true
        -- Limpiar tablas de muertos -- no deben persistir entre rondas
        if _G._deadRoles      then for k in next, _G._deadRoles      do _G._deadRoles[k]      = nil end end
        if _G._deadSheriffIds then for k in next, _G._deadSheriffIds do _G._deadSheriffIds[k] = nil end end
        task.defer(function()
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer then
                    pcall(removeCham,    p)
                    pcall(removeOutline, p)
                    pcall(removeBox,     p)
                end
            end
        end)
        _predCache.pos = nil; _predCache.target = nil; _predCache.ts = 0
        if CombatState then
            CombatState._trackGunCache = nil
            CombatState._asGunCache = nil
        end
        _knifeSA_posHistory = table.create(90); _ksa_head = 1; _ksa_count = 0

        -- FIX VISUALS: si RoundStart no llega en 3s tras RoundEnd,
        -- resetear _betweenRounds para que los visuals vuelvan a funcionar
        local _reToken = _G._sgRoundToken
        task.delay(3, function()
            if _G._betweenRounds and (_G._sgRoundToken == _reToken) then
                _G._betweenRounds   = false
                _G._rolesCacheReady = true
                _G._forceInstanceTick = true
            end
        end)

        -- -- LIMPIAR DEAD CHAM / ESP AL FIN DE RONDA ---------------
        task.defer(function()
            -- 1. Apagar y limpiar Cham Raggy
            if ChamRaggyState and ChamRaggyState.enabled then
                if type(_removeAllRaggyHighlights) == "function" then
                    pcall(_removeAllRaggyHighlights)
                end
            end
            -- 2. Limpiar TODOS los clones del Dead Cham (DeathPoseState + DeadBodyESP + estatuas en workspace)
            if type(_clearAllDeadCham) == "function" then
                pcall(_clearAllDeadCham)
            end
            -- 3. Restaurar LocalTransparencyModifier y limpiar tabla
            pcall(function()
                for model, _ in pairs(_deadBodies or {}) do
                    pcall(function()
                        if model and model.Parent then
                            for _, part in ipairs(model:GetDescendants()) do
                                if part:IsA("BasePart") then
                                    part.LocalTransparencyModifier = 0
                                end
                            end
                        end
                    end)
                end
            end)
            _deadBodies = {}
            -- 4. Re-escanear si el toggle dead cham sigue activo (para la siguiente ronda)
            task.delay(2, function()
                if ChamRaggyState and ChamRaggyState.enabled then
                    pcall(_scanWorkspaceForRaggy)
                end
            end)
        end)
    end)
end)

