-- LIMPIEZA DE ROLES ROBUSTA -- detecta fin de ronda por multiples vias
-- Cubre: victoria de inocentes, empate, RoundEnd que no llega por lag
-- ===============================================================
task.spawn(function()
    -- Metodo 1: monitorear RoundTimerPart -- desaparece al terminar la ronda
    local function _watchTimerPart()
        local timerPart = workspace:FindFirstChild("RoundTimerPart")
        if not timerPart then return end
        timerPart.AncestryChanged:Connect(function()
            if timerPart.Parent == nil then
                -- Timer desaparecio = ronda terminada
                task.wait(0.1)
                -- Habilitar NotifyRol de nuevo (RoundTimerPart desaparecio)
                _G._roundTimerRunning = false
                _G._visualRoundOver = true
                _G._betweenRounds   = true
                -- FIX SHERIFF VIEJO: matar loop StealGun
                _G._sgRoundToken    = (_G._sgRoundToken or 0) + 1
                _roleCache.murderer  = nil
                _roleCache.sheriff   = nil
                _roleCache.hero      = nil
                -- FIX ROLES: limpiar roles secundarios
                _roleCache.assassin  = nil
                _roleCache.zombie    = nil
                _roleCache.survivor  = nil
                _roleCache.localRole = "Innocent"
                _roleCache.lastUpdate = 0
                -- FIX: limpiar tablas de muertos para que no persistan a la siguiente ronda
                if _G._deadRoles     then for k in next, _G._deadRoles     do _G._deadRoles[k]     = nil end end
                if _G._deadSheriffIds then for k in next, _G._deadSheriffIds do _G._deadSheriffIds[k] = nil end end
                -- FIX DELAY: si RoundStart no llega en 3s, desbloquear visuals
                local _tpToken = _G._sgRoundToken
                task.delay(3, function()
                    if _G._betweenRounds and (_G._sgRoundToken == _tpToken) then
                        _G._betweenRounds   = false
                        _G._rolesCacheReady = true
                        _G._forceInstanceTick = true
                    end
                end)
                _G._forceInstanceTick = true
                task.defer(function()
                    if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
                    _deadBodies = {}
                    for _, p in ipairs(_cachedPlayers) do
                        if p ~= LocalPlayer then
                            pcall(removeCham,    p)
                            pcall(removeOutline, p)
                            pcall(removeBox,     p)
                        end
                    end
                end)
            end
        end)
    end
    _watchTimerPart()
    -- Re-hookear cuando aparezca un nuevo TimerPart (nueva ronda)
    workspace.ChildAdded:Connect(function(obj)
        if obj.Name == "RoundTimerPart" then
            task.wait(0.1)
            _watchTimerPart()
        end
    end)

    -- Metodo 2: monitorear el mapa -- cuando se destruye termina la ronda
    -- FIX LAG: debounce para que no dispare miles de veces al destruirse el mapa
    local _roundEndMapDebounce = false
    workspace.ChildRemoved:Connect(function(obj)
        -- MM2 nombra el mapa como "Map", "MM2Map", etc.
        local n = obj.Name:lower()
        if n == "map" or n:find("mm2map") or n:find("_map") then
            if _roundEndMapDebounce then return end
            _roundEndMapDebounce = true
            task.wait(0.15)
            _roundEndMapDebounce = false
            if _roleCache.murderer or _roleCache.sheriff or _roleCache.hero then
                _G._visualRoundOver = true
                _G._betweenRounds   = true
                -- FIX SHERIFF VIEJO: matar loop StealGun cuando el mapa se destruye
                _G._sgRoundToken    = (_G._sgRoundToken or 0) + 1
                _roleCache.murderer  = nil
                _roleCache.sheriff   = nil
                _roleCache.hero      = nil
                -- FIX ROLES: limpiar roles secundarios
                _roleCache.assassin  = nil
                _roleCache.zombie    = nil
                _roleCache.survivor  = nil
                _roleCache.localRole = "Innocent"
                _roleCache.lastUpdate = 0
                -- FIX: limpiar tablas de muertos para que no persistan a la siguiente ronda
                if _G._deadRoles     then for k in next, _G._deadRoles     do _G._deadRoles[k]     = nil end end
                if _G._deadSheriffIds then for k in next, _G._deadSheriffIds do _G._deadSheriffIds[k] = nil end end
                _G._forceInstanceTick = true
                -- FIX DELAY: si RoundStart no llega en 3s, desbloquear visuals
                local _mapToken = _G._sgRoundToken
                task.delay(3, function()
                    if _G._betweenRounds and (_G._sgRoundToken == _mapToken) then
                        _G._betweenRounds   = false
                        _G._rolesCacheReady = true
                        _G._forceInstanceTick = true
                    end
                end)
                task.defer(function()
                    if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
                    _deadBodies = {}
                    for _, p in ipairs(_cachedPlayers) do
                        if p ~= LocalPlayer then
                            pcall(removeCham,    p)
                            pcall(removeOutline, p)
                            pcall(removeBox,     p)
                        end
                    end
                end)
            end
        end
    end)

    -- Nuevo mapa cargado: limpiar residuos del Dead Cham del mapa anterior
    local _newMapDebounce = false
    workspace.ChildAdded:Connect(function(obj)
        local n = obj.Name:lower()
        if n == "map" or n:find("mm2map") or n:find("_map") then
            if _newMapDebounce then return end
            _newMapDebounce = true
            -- Esperar que el mapa termine de cargar y limpiar cuerpos viejos
            task.delay(0.5, function()
                _newMapDebounce = false
                _G._visualRoundOver = false
                -- _betweenRounds se mantiene true hasta que RoundStart llegue con los nuevos roles
                -- asi updateCham no aplica chams con roles viejos durante la transicion
                if type(_clearAllDeadCham) == "function" then
                    pcall(_clearAllDeadCham)
                end
                _deadBodies = {}
            end)
            -- FIX VISUALS: timeout de seguridad -- si RoundStart no llega en 3s,
            -- bajar _betweenRounds igual para que los visuals vuelvan a funcionar
            task.delay(3, function()
                if _G._betweenRounds then
                    _G._betweenRounds = false
                    _G._rolesCacheReady = true
                    _G._forceInstanceTick = true
                end
            end)
        end
    end)

    -- Metodo 3: detectar cuando el murderer/sheriff mueren Y no hay ronda activa
    -- Corre cada 2s como fallback -- solo limpia si todos los roles estan muertos
    while true do
        task.wait(2)
        -- Si la ronda termino, seguir limpiando el Dead Cham cada ciclo
        -- por si quedaron residuos (clones, highlights) de rondas anteriores
        if _G._visualRoundOver then
            if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
            _deadBodies = {}
            continue
        end
        -- Si hay murderer en cache pero su Humanoid esta muerto -> limpiar SOLO su rol
        local m = _roleCache.murderer
        if m and m.Character then
            local mh = m.Character:FindFirstChildOfClass("Humanoid")
            if mh and mh.Health <= 0 then
                _G._murdererDied      = true
                _roleCache.murderer   = nil
                _roleCache.lastUpdate = 0
            end
        end
        -- Si hay sheriff en cache pero murio -> limpiar SOLO su rol
        local s = _roleCache.sheriff
        if s and s.Character then
            local sh = s.Character:FindFirstChildOfClass("Humanoid")
            if sh and sh.Health <= 0 then
                _roleCache.sheriff    = nil
                _roleCache.lastUpdate = 0
            end
        end
    end
end)

-- Callback que se ejecuta cuando RoundStart termina de poblar el cache
-- Engancha al murderer para detectar su muerte
_G._roundStartRoleCallbacks = _G._roundStartRoleCallbacks or {}
_roundStartRoleCallbacks = _G._roundStartRoleCallbacks
-- _murderDeathHook: ya no necesita resetear flags (RoundStart lo hace directo)
-- Solo existe por compatibilidad con otros callbacks del sistema
_roundStartRoleCallbacks["_murderDeathHook"] = function()
    -- Si el RoundStart ya tenia roles en playerData, hookear inmediatamente
    if _roleCache.murderer and not _murdererDeathConn then
        pcall(_hookMurdererDeath, _roleCache.murderer)
    end
end

-- ===============================================================
-- POLLING INDEPENDIENTE DE ROLES -- no depende del loop visual
-- Corre en su propio task cada 1s garantizado, sin yields del Heartbeat
-- ===============================================================
task.spawn(function()
    -- Esperar que ReplicatedStorage este listo
    local GetPlayerData = nil
    for _ = 1, 20 do
        GetPlayerData = ReplicatedStorage:FindFirstChild("GetPlayerData", true)
        if GetPlayerData then break end
        task.wait(0.5)
    end
    if not GetPlayerData then return end

    -- FIX #2: exponential backoff en vez de polling a 0.08s (12.5 llamadas/seg)
    -- Empieza en 500ms, sube a 2s cuando los roles estan confirmados
    local _backoff = 0.5
    while true do
        task.wait(_backoff)

        -- No pollear si la ronda termino
        if _G._visualRoundOver then _backoff = 2; continue end

        -- FIX #2: ya tenemos ambos roles y pasaron los primeros 8s -> slow poll
        local elapsed = os.clock() - (_G._roundStartTime or 0)
        if _roleCache.murderer and _roleCache.sheriff and elapsed > 8 then
            _backoff = 2; continue
        end

        local ok, data = pcall(function() return GetPlayerData:InvokeServer() end)
        if not ok or type(data) ~= "table" then
            _backoff = math.min(_backoff * 2, 5)  -- FIX #2: backoff en fallo
            continue
        end

        -- FIX: asignar roles ATOMICAMENTE -- nunca nil el cache antes de llenar.
        -- El window entre nil y re-fill causaba que todos se pinten de verde (Innocent)
        -- por hasta 1-10s hasta el siguiente poll exitoso.
        local hadMurderer = _roleCache.murderer
        local newMurderer, newSheriff, newHero = nil, nil, nil
        local newLocalRole = nil

        for plrName, pdata in pairs(data) do
            local p = Players:FindFirstChild(plrName)
            if p and type(pdata) == "table" and pdata.Role then
                if p == LocalPlayer then
                    newLocalRole = pdata.Role
                end
                if     pdata.Role == "Murderer" then newMurderer = p
                elseif pdata.Role == "Sheriff"  then newSheriff  = p
                elseif pdata.Role == "Hero"     then newHero     = p
                end
            end
        end

        -- Asignar todo junto (sin window de nil)
        _roleCache.murderer  = newMurderer
        _roleCache.sheriff   = newSheriff
        _roleCache.hero      = newHero
        if newLocalRole then _roleCache.localRole = newLocalRole end
        _roleCache.lastUpdate = os.clock()  -- FIX #3: os.clock() consistente con _refreshRoleCache

        -- FIX #2: ajustar backoff segun estado del cache
        if _roleCache.murderer and _roleCache.sheriff then
            _backoff = 1.5  -- roles confirmados: poll cada 1.5s
        else
            _backoff = 0.4  -- buscando roles: poll cada 400ms (no 80ms)
        end

        -- ACELERADO: si el roleCache acaba de detectar un sheriff, notificar a StealGun inmediatamente
        if newSheriff and StealGunSystem and StealGunSystem.enabled
        and StealGunSystem.sheriffOriginalFound ~= newSheriff then
            task.defer(FindOriginalSheriff)
        end

        -- Hookear al murderer cuando se detecta por primera vez en esta ronda
        if _roleCache.murderer and not hadMurderer and not _murdererDeathConn then
            pcall(_hookMurdererDeath, _roleCache.murderer)
        end
    end
end)

_cachedShootRemote = nil
-- Cache con invalidacion por tiempo para detectar cambios de ronda
_cachedShootRemoteTime = 0
_SHOOT_CACHE_TTL = 3  -- OPT: cache de remote de disparo de 2s?3s

function getShootRemote(gun)
    -- FIX LAG: cache por instancia de gun (evita GetDescendants cada Heartbeat)
    if gun and _cachedShootRemote and _cachedShootRemote.Parent
    and _cachedShootRemote:IsDescendantOf(gun) then
        return _cachedShootRemote
    end
    _cachedShootRemote = nil  -- limpiar si la gun cambio

    -- 1) Buscar DENTRO de la gun primero -- siempre mas confiable que RS global
    if gun then
        -- Exacto "Shoot" en raiz de la gun
        local direct = gun:FindFirstChild("Shoot")
        if direct and direct:IsA("RemoteEvent") then _cachedShootRemote = direct; return direct end
        -- GunServer/Shoot (estructura comun en MM2)
        local gs = gun:FindFirstChild("GunServer")
        if gs then
            local gsShoot = gs:FindFirstChild("Shoot")
            if gsShoot and gsShoot:IsA("RemoteEvent") then return gsShoot end
            for _, v in ipairs(gs:GetDescendants()) do
                if v:IsA("RemoteEvent") then
                    local n = v.Name:lower()
                    if n == "shoot" or n == "fire" or n:find("shoot") or n:find("fire") then
                        return v
                    end
                end
            end
        end
        -- Cualquier RemoteEvent en la gun con nombre de disparo
        for _, v in ipairs(gun:GetDescendants()) do
            if v:IsA("RemoteEvent") then
                local n = v.Name:lower()
                if n == "shoot" or n == "fire" or n:find("shoot") or n:find("gunfire") or n:find("bullet") then
                    return v
                end
            end
        end
    end

    -- 2) Cache con TTL
    local now = tick()
    if _cachedShootRemote and _cachedShootRemote.Parent
    and (now - _cachedShootRemoteTime) < _SHOOT_CACHE_TTL then
        return _cachedShootRemote
    end
    _cachedShootRemote = nil
    local RS = game:GetService("ReplicatedStorage")

    local function tryPath(root, ...)
        local cur = root
        for _, k in ipairs({...}) do
            if not cur then return nil end
            cur = cur:FindFirstChild(k)
        end
        return (cur and cur:IsA("RemoteEvent")) and cur or nil
    end

    -- Paths conocidos de MM2 -- solo remotes reales de disparo
    -- REMOVIDOS: GunKill, FakeGun (son eventos de gameplay, no de disparo directo)
    local found =
        tryPath(gun, "Shoot")                                           or
        tryPath(gun, "GunServer", "Shoot")                             or
        tryPath(RS, "Remotes", "Gameplay", "Shoot")                    or
        tryPath(RS, "Remotes", "Gun")                                  or
        tryPath(RS, "ClientServices", "WeaponService", "GunFired")     or
        tryPath(RS, "WeaponEvents", "GunBeam")                         or
        tryPath(RS, "WeaponEvents", "Shoot")                           or
        tryPath(RS, "Events", "Shoot")                                 or
        tryPath(RS, "Shoot")

    -- Fallback scan: "shoot" exacto primero
    if not found then
        for _, v in ipairs(RS:GetDescendants()) do
            if v:IsA("RemoteEvent") and v.Name:lower() == "shoot" then
                found = v; break
            end
        end
    end
    -- Fallback scan: contiene keyword
    if not found then
        local keywords = {"shoot","gunfire","gunfired","weaponfire","bullet","gunshot"}
        for _, v in ipairs(RS:GetDescendants()) do
            if v:IsA("RemoteEvent") then
                local n = v.Name:lower()
                for _, kw in ipairs(keywords) do
                    if n:find(kw) then found = v; break end
                end
                if found then break end
            end
        end
    end
    -- Ultimo recurso: cualquier remote en la gun
    if not found and gun then
        for _, v in ipairs(gun:GetDescendants()) do
            if v:IsA("RemoteEvent") then found = v; break end
        end
    end

    if found then
        _cachedShootRemote = found
        _cachedShootRemoteTime = now
    end
    return found
end

function getGunAttachment(gun, hrp)
    -- 1) Attachment exacto en HRP (mas preciso para raycast origin)
    if hrp then
        local gra = hrp:FindFirstChild("GunRaycastAttachment")
        if gra and gra:IsA("Attachment") then return gra end
        -- Buscar cualquier attachment con nombre relacionado a gun/raycast
        for _, v in ipairs(hrp:GetChildren()) do
            if v:IsA("Attachment") then
                local n = v.Name:lower()
                if n:find("gun") or n:find("ray") or n:find("shoot") or n:find("barrel") then
                    return v
                end
            end
        end
    end
    -- 2) En el Handle de la gun (barrel position mas realista)
    if gun then
        local handle = gun:FindFirstChild("Handle")
        if handle then
            -- Buscar attachment de barrel
            for _, v in ipairs(handle:GetDescendants()) do
                if v:IsA("Attachment") then
                    local n = v.Name:lower()
                    if n:find("barrel") or n:find("shoot") or n:find("muzzle") or n:find("gun") then
                        return v
                    end
                end
            end
            -- Cualquier attachment del handle
            for _, v in ipairs(handle:GetChildren()) do
                if v:IsA("Attachment") then return v end
            end
        end
        -- 3) GunServer descendants
        local gs = gun:FindFirstChild("GunServer")
        if gs then
            for _, v in ipairs(gs:GetDescendants()) do
                if v:IsA("Attachment") then return v end
            end
        end
        for _, v in ipairs(gun:GetDescendants()) do
            if v:IsA("Attachment") then return v end
        end
    end
    -- 4) Fallback a cualquier attachment en HRP
    if hrp then
        for _, v in ipairs(hrp:GetChildren()) do
            if v:IsA("Attachment") then return v end
        end
    end
    return nil
end

-- ==================================================================
-- _fireGunMM2 -- Replica exacta del shootGun() del GunClient original de MM2
-- Firma: gun.Shoot:FireServer(GunRaycastAttachment.WorldCFrame, targetCF)
-- Usar SIEMPRE en vez de gun:Activate() para disparos manuales del hub
-- ==================================================================
function _fireGunMM2(gun, targetCF)
    if not gun then return false end
    local c   = LocalPlayer.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end

    -- 1. Origen: GunRaycastAttachment.WorldCFrame (igual que el GunClient original)
    local gra      = hrp:FindFirstChild("GunRaycastAttachment")
    local originCF = gra and gra.WorldCFrame or hrp.CFrame

    -- 2. Target: si no se pasa, usar camara LookVector como fallback
    if not targetCF then
        local cam = workspace.CurrentCamera
        targetCF = cam and CFrame.new(cam.CFrame.Position + cam.CFrame.LookVector * 500) or originCF
    end

    -- 3. Shoot RemoteEvent directo en la gun (como GunClient original: v1.Shoot:FireServer)
    local shootRemote = gun:FindFirstChild("Shoot")
    if shootRemote and shootRemote:IsA("RemoteEvent") then
        pcall(function() shootRemote:FireServer(originCF, targetCF) end)
        return true
    end

    -- 4. Fallback para guns con estructura distinta
    local fallback = getShootRemote(gun)
    if fallback and fallback:IsA("RemoteEvent") then
        pcall(function() fallback:FireServer(originCF, targetCF) end)
        return true
    end

    -- 5. No se encontro ningun remote de disparo
    return false
end

function getMurdererHead()
    local murderer = findMurderer()
    if murderer and murderer.Character then
        return murderer.Character:FindFirstChild("Head")
    end
    return nil
end

-- Cache de RaycastParams para wallCheck -- evita alocar objeto nuevo en cada throw
local _wcParams = RaycastParams.new()
_wcParams.FilterType = Enum.RaycastFilterType.Exclude

-- FIX #7: lista de exclusion cacheada, reconstruida solo cuando cambian characters
-- (antes se reconstruia en CADA llamada a 60fps - O(n) players + new table allocation)
local _wcIgnoreList  = {}
local _wcIgnoreDirty = true
local function _markWcDirty() _wcIgnoreDirty = true end
Players.PlayerAdded:Connect(_markWcDirty)
Players.PlayerRemoving:Connect(_markWcDirty)
LocalPlayer.CharacterAdded:Connect(_markWcDirty)

local function _rebuildWcIgnore(targetPos)
    _wcIgnoreList = {}
    if LocalPlayer.Character then
        _wcIgnoreList[1] = LocalPlayer.Character
    end
    for _, p in ipairs(_cachedPlayers) do  -- FIX #7: usar cache pre-construido en vez de GetPlayers()
        if p ~= LocalPlayer and p.Character then
            local hrp = p.Character:FindFirstChild("HumanoidRootPart")
            if hrp and hrp.Position then
                if (hrp.Position - targetPos).Magnitude < 8 then
                    _wcIgnoreList[#_wcIgnoreList + 1] = p.Character
                end
            end
        end
    end
    _wcParams.FilterDescendantsInstances = _wcIgnoreList
    _wcIgnoreDirty = false
end

function wallCheckRaycast(from, to, extraExclude)
    -- FIX #7: solo reconstruir si hubo cambios de characters (no en cada frame)
    if _wcIgnoreDirty then
        _rebuildWcIgnore(to)
    else
        -- Mismo params pero el extraExclude puede variar por llamada
        -- Para mantener el comportamiento original con extraExclude, reconstruir si hay uno
        if extraExclude then
            _rebuildWcIgnore(to)
        else
            _wcParams.FilterDescendantsInstances = _wcIgnoreList
        end
    end
    if extraExclude then
        local extList = {}
        for i, v in ipairs(_wcIgnoreList) do extList[i] = v end
        extList[#extList + 1] = extraExclude
        _wcParams.FilterDescendantsInstances = extList
    end

    local direction = (to - from)
    local result = workspace:Raycast(from, direction, _wcParams)

    if not result then return true end
    if result.Instance then
        if result.Instance.Transparency >= 0.95 or not result.Instance.CanCollide then
            return true
        end
    end
    return false
end

-- FIX: MM2 usa hitscan -- la "velocidad de bala" no existe fisicamente.
-- El valor alto evita que el TOF del solver distorsione la prediccion por distancia.
BULLET_SPEED       = 9999

-- SWIM FLY ANIMATIONS - Configuracion de IDs
SWIM_FLY_ANIMS = {
    idle = "rbxassetid://1108307876",      -- Floating idle
    forward = "rbxassetid://1109219222",   -- Flying forward
    up = "rbxassetid://1119029669",        -- Flying up
    down = "rbxassetid://1119029669",      -- Flying down
}

SA_PRED_MAX_OFFSET = 6  -- reducido: max 6 studs de offset horizontal total
SA_GRAVITY_COMP    = true -- en trayectoria

-- ============================================================
-- PER-TARGET HISTORY SYSTEM
-- Each murderer gets their own history, keyed by UserId.
-- Updated by a dedicated RunService loop at fixed intervals.
-- ============================================================
_predHistories  = {}
PRED_HIST_SIZE  = 48
HIST_INTERVAL   = 0.016
_histTimers     = {}

-- -- RING BUFFER: _head = proximo slot a escribir, _count = validos --
-- Reemplaza table.remove(entries,1) O(n) -> escritura O(1) siempre.
-- Con 12 jugadores x 48 entries, el viejo approach hacia O(576) shifts/frame.
function _resetHist(userId)
    local entries = table.create(PRED_HIST_SIZE)
    for i = 1, PRED_HIST_SIZE do entries[i] = false end  -- preallocar slots
    _predHistories[userId] = {
        entries      = entries,
        _head        = 1,   -- proximo slot a escribir (wraps around)
        _count       = 0,   -- cuantos slots validos
        emaVel       = Vector3.zero,
        prevDir      = nil,
        dirFlips     = 0,
        lastAccelMag = 0,
        lastPredicted = nil,
        -- [WIFI PRED] Per-player network estimation
        pingEMA       = 80,   -- EMA del lag del jugador en ms (estimado)
        pingJitter    = 0,    -- varianza reciente del lag
        pingHistory   = {},   -- ultimas N estimaciones para tendencia
        lastSeenT     = 0,    -- tick() de la ultima posicion recibida
        lastSeenPos   = nil,  -- ultima posicion guardada
        receiveDeltas = {},   -- ring buffer de intervalos (~ lag del target)
        receiveDeltasIdx = 0, -- indice actual del ring buffer (O(1) insert)
    }
    _histTimers[userId] = 0
end

function _getHist(userId)
    if not _predHistories[userId] then
        _resetHist(userId)
    end
    return _predHistories[userId]
end

-- -- RING BUFFER READER --------------------------------------------------------
-- Devuelve `count` entradas en orden cronologico (mas vieja -> mas nueva).
-- Sustituye patrones e[i] / e[n] en los readers que antes asumian array lineal.
-- count = nil -> devuelve todos los validos.
function _ringRead(h, count)
    local n = h._count
    if n == 0 then return {} end
    count = math.min(count or n, n)
    local out = table.create(count)
    -- _head apunta al PROXIMO slot a escribir -> el mas viejo esta en _head (si full) o en 1
    local startIdx = ((h._head - 1 - n + count - 1) % PRED_HIST_SIZE) + 1  -- mas viejo de los ultimos `count`
    for i = 1, count do
        local idx = ((startIdx - 1 + i - 1) % PRED_HIST_SIZE) + 1
        out[i] = h.entries[idx]
    end
    return out
end

-- FIX BUG #1: limpiar historial cuando un jugador respawnea
-- Sin esto el sistema predice al jugador en su posicion anterior durante ~1-2s
-- causando que aparezca "en otro lado del mapa" mientras camina
function _hookPlayerHistReset(p)
    p.CharacterAdded:Connect(function()
        _resetHist(p.UserId)
    end)
end
Players.PlayerAdded:Connect(_hookPlayerHistReset)
for _, p in ipairs(_cachedPlayers) do
    _hookPlayerHistReset(p)
end

-- Limpiar datos del jugador al salir del juego
Players.PlayerRemoving:Connect(function(p)
    -- Limpiar historial de prediccion
    if _predHistories then _predHistories[p.UserId] = nil end
    if _histTimers    then _histTimers[p.UserId]    = nil end
    -- Limpiar cache de indices de jugadores
    if _G._playerIndex   then _G._playerIndex[p]       = nil end
    if _G._playerByName  then _G._playerByName[p.Name] = nil end
    -- Reconstruir cache de jugadores activos
    task.defer(function()
        if _rebuildPlayerCache then _rebuildPlayerCache() end
    end)
end)

-- Call this every frame from the main tracking loop
function updatePredHistoryFor(userId, pos, vel)
    local now  = tick()
    local last = _histTimers[userId] or 0
    if now - last < HIST_INTERVAL then return end
    _histTimers[userId] = now

    local h = _getHist(userId)

    -- -- DETECCION DE TELEPORT / RESPAWN -------------------------------------
    -- Si el jugador salto mas de 15 studs en un frame -> teleport o respawn.
    -- Limpiar TODO el historial para no apuntar al lugar antiguo.
    -- OPT: ring buffer -- ultimo slot escrito esta en ((_head-2) % SIZE)+1
    local _lastSlot = h._count > 0 and h.entries[((h._head - 2) % PRED_HIST_SIZE) + 1] or nil
    local prevPos = _lastSlot and _lastSlot.pos
    -- FIX BUG #3: umbral subido 15->50 studs.
    -- Con 15 un jugador rapido (WalkSpeed 20+) podia disparar falsos resets cada frame.
    -- Con 50 solo se limpia en teleports/respawns reales.
    if prevPos and (pos - prevPos).Magnitude > 50 then
        _resetHist(userId)
        h = _getHist(userId)
        h.emaVel = vel
    end

    -- Alpha adaptativo v3: responde rapido a cambios bruscos, estable en movimiento constante
    -- Base mas alta (0.45) para tracking mas reactivo en general
    local rawAccelMag = (vel - h.emaVel).Magnitude
    local speed = vel.Magnitude
    local jerk = math.abs(rawAccelMag - (h.lastAccelMag or 0))
    local alphaAccel = math.clamp(rawAccelMag * 0.040, 0, 0.50)  -- mas reactivo a aceleracion
    local alphaSpeed = math.clamp(speed * 0.007, 0, 0.15)
    local alphaJerk  = math.clamp(jerk * 0.030, 0, 0.25)         -- mas reactivo a cambios bruscos
    -- Base 0.50 -- responde mas rapido a cambios de direccion
    local alpha = math.clamp(0.50 + alphaAccel + alphaSpeed + alphaJerk, 0.50, 0.97)
    h.emaVel = h.emaVel:Lerp(vel, alpha)
    h.lastAccelMag = rawAccelMag

    -- Detect direction flip (dot < 0 means sudden reversal)
    local flatVel = Vector3.new(vel.X, 0, vel.Z)
    if flatVel.Magnitude > 2 then
        local dir = flatVel.Unit
        if h.prevDir then
            local dot = h.prevDir:Dot(dir)
            if dot < -0.3 then
                -- Cambio brusco: resetear EMA al valor actual y recortar historial agresivamente
                h.dirFlips = (h.dirFlips or 0) + 1
                h.emaVel = vel  -- resetear EMA al valor actual
                -- OPT: ring buffer -- en vez de remove(1) n veces, resetear _count
                h._count = math.min(h._count, 3)
            elseif dot < 0.15 then
                -- Cambio moderado: reducir historial parcialmente
                h._count = math.min(h._count, 8)
            end
        end
        h.prevDir = dir
    end

    -- OPT: ring buffer write -- O(1) siempre (antes era O(n) con table.remove)
    h.entries[h._head] = { pos = pos, vel = vel, t = now }
    h._head = (h._head % PRED_HIST_SIZE) + 1
    if h._count < PRED_HIST_SIZE then h._count = h._count + 1 end
end

-- Legacy wrapper so old call-sites still work
function updatePredHistory(pos, vel)
    local murderer = findMurderer and findMurderer()
    local uid = murderer and murderer.UserId or 0
    updatePredHistoryFor(uid, pos, vel)
end

-- ============================================================
-- HISTORY UPDATER LOOP
-- Runs independently so history is always fresh.
-- ============================================================
-- Historia a 60 Hz usando Heartbeat (mas preciso que task.wait)
-- BUG FIX: ahora trackea a TODOS los jugadores relevantes, no solo al murderer.
-- El sheriff (con gun) y otros roles tambien necesitan historial actualizado.
HIST_INTERVAL_HZ = 1/8   -- OPT: 8Hz suficiente para prediccion (reducido de 10Hz)
_histLastUpdate  = 0
-- GUARD: desconectar conexion anterior si existe (evita duplicados al re-ejecutar)
if _G._histUpdaterConn then pcall(function() _G._histUpdaterConn:Disconnect() end) end
_G._histUpdaterConn = RunService.Heartbeat:Connect(function()
    -- Guard: solo correr si algun Silent Aim esta activo
    if not KnifeSAState.enabled and not (CombatTabState and CombatTabState.silentAimEnabled) then return end
    local now = tick()
    if now - _histLastUpdate < HIST_INTERVAL_HZ then return end
    _histLastUpdate = now
    if _G._visualRoundOver then return end
    for _, p in ipairs(_cachedPlayers) do
        if p == LocalPlayer then continue end
        local char = p.Character
        if not char then continue end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then
            local vel = hrp.AssemblyLinearVelocity or Vector3.zero
            updatePredHistoryFor(p.UserId, hrp.Position, vel)

            -- [WIFI PRED] Estimar ping del jugador midiendo el intervalo entre
            -- actualizaciones de posicion que llegan al cliente.
            -- En Roblox, las posiciones se replican al ritmo del ping del dueno.
            -- Si el intervalo entre updates es mayor al nuestro -> ese jugador tiene mas lag.
            local _h = _getHist(p.UserId)
            local _now = now
            if _h.lastSeenPos then
                local _moved = (hrp.Position - _h.lastSeenPos).Magnitude
                -- Solo contar si se movio (filtra frames sin movimiento real)
                if _moved > 0.02 then
                    local _delta = (_now - _h.lastSeenT) * 1000  -- ms entre updates
                    -- Clamp: ignora deltas absurdos (lag spikes > 800ms o < 8ms)
                    _delta = math.clamp(_delta, 8, 800)
                    -- Guardar ultimas 16 deltas para EMA y jitter
                    -- FIX LAG: ring buffer O(1) ? table.remove(_rd,1) era O(N) desplazando todo
                    local _rd = _h.receiveDeltas
                    _h.receiveDeltasIdx = (_h.receiveDeltasIdx % 16) + 1
                    _rd[_h.receiveDeltasIdx] = _delta
                    -- EMA del delta (~ ping estimado del jugador)
                    _h.pingEMA = _h.pingEMA * 0.70 + _delta * 0.30
                    -- Jitter = varianza suavizada del delta
                    local _jRaw = math.abs(_delta - _h.pingEMA)
                    _h.pingJitter = _h.pingJitter * 0.75 + _jRaw * 0.25
                    -- Guardar en pingHistory para tendencia
                    local _ph = _h.pingHistory
                    table.insert(_ph, _h.pingEMA)
                    if #_ph > 20 then table.remove(_ph, 1) end
                    _h.lastSeenT = _now
                    _h.lastSeenPos = hrp.Position
                end
            else
                -- Primera vez que vemos este jugador
                _h.lastSeenT   = _now
                _h.lastSeenPos = hrp.Position
            end
        end
    end
end)

-- ============================================================
-- HELPER: recent acceleration -- minimos cuadrados ponderados
-- Usa hasta 6 muestras con peso exponencial (recientes mas peso)
-- ============================================================
function getAccelerationFor(userId)
    local h = _getHist(userId)
    if h._count < 3 then return Vector3.zero end
    local e = _ringRead(h, 10)  -- ultimas 10 muestras en orden
    local n = #e
    if n < 3 then return Vector3.zero end
    local accum  = Vector3.zero
    local wTotal = 0
    for i = 2, n do
        local a, b = e[i-1], e[i]
        local dt = b.t - a.t
        if dt >= 0.003 then
            local w = math.exp((i - n) * 0.45)
            accum  = accum  + (b.vel - a.vel) / dt * w
            wTotal = wTotal + w
        end
    end
    if wTotal < 0.001 then return Vector3.zero end
    return accum / wTotal
end

-- Legacy
function getAcceleration()
    local murderer = findMurderer and findMurderer()
    local uid = murderer and murderer.UserId or 0
    return getAccelerationFor(uid)
end

-- ============================================================
-- HELPER: movement trend -- desplazamiento ponderado reciente
-- Combina ventana completa (largo plazo) + ultimas 4 muestras (corto plazo)
-- ============================================================
function getMovementTrendFor(userId)
    local h = _getHist(userId)
    if h._count < 3 then return Vector3.zero end
    local e = _ringRead(h, 12)  -- ultimas 12 muestras (~0.2s @ 60Hz)
    local n = #e
    if n < 3 then return Vector3.zero end

    local totalDt = e[n].t - e[1].t
    if totalDt < 0.04 then return Vector3.zero end
    local globalTrend = (e[n].pos - e[1].pos) / totalDt

    local recentStart = math.max(1, n - 5)
    local recentDt = e[n].t - e[recentStart].t
    local recentTrend = recentDt > 0.015
        and (e[n].pos - e[recentStart].pos) / recentDt
        or globalTrend

    local ultraStart = math.max(1, n - 2)
    local ultraDt = e[n].t - e[ultraStart].t
    local ultraTrend = ultraDt > 0.01
        and (e[n].pos - e[ultraStart].pos) / ultraDt
        or recentTrend

    return globalTrend * 0.10 + recentTrend * 0.40 + ultraTrend * 0.50
end

-- Legacy
function getMovementTrend()
    local murderer = findMurderer and findMurderer()
    local uid = murderer and murderer.UserId or 0
    return getMovementTrendFor(uid)
end

-- ============================================================
-- [WIFI PRED] HELPER: obtener ping estimado del jugador target
-- Devuelve: pingMs (EMA), jitterMs, trendSlope (subiendo/bajando)
-- ============================================================
function getTargetPingFor(userId)
    local h = _getHist(userId)
    local pingMs  = h.pingEMA   or 80
    local jitter  = h.pingJitter or 0
    local ph      = h.pingHistory or {}
    -- Tendencia: comparar mitad reciente vs mitad antigua del historial
    local trend = 0
    if #ph >= 6 then
        local half = math.floor(#ph / 2)
        local oldSum, newSum = 0, 0
        for i = 1, half do oldSum = oldSum + ph[i] end
        for i = half+1, #ph do newSum = newSum + ph[i] end
        local oldAvg = oldSum / half
        local newAvg = newSum / (#ph - half)
        trend = newAvg - oldAvg  -- positivo = ping subiendo, negativo = bajando
    end
    return pingMs, jitter, trend
end

-- ============================================================
-- [PRED] TOF conservador: solo el ping propio dividido en dos (one-way estimado)
-- El ping del target fue removido -- inflaba el tof en 30-50ms extra causando
-- over-prediction constante independientemente de la velocidad del jugador.
-- ============================================================
function getEffectiveTOF(userId, myPingMs)
    -- Usar simplemente el ping one-way del jugador local, clampeado
    local effectivePingMs = math.clamp(myPingMs / 2, 10, 120)
    return math.max(effectivePingMs / 1000, 0.010)
end


-- Usa hasta 8 muestras recientes con peso exponencial
-- ============================================================
function getAngularVelocityFor(userId)
    local h = _getHist(userId)
    if h._count < 4 then return 0 end
    local e = _ringRead(h, 12)
    local n = #e
    if n < 4 then return 0 end
    local totalOmega = 0
    local wTotal = 0
    for i = 2, n do
        local prev = e[i-1]
        local curr = e[i]
        local dt   = curr.t - prev.t
        if dt > 0.005 then
            local v1 = Vector3.new(prev.vel.X, 0, prev.vel.Z)
            local v2 = Vector3.new(curr.vel.X, 0, curr.vel.Z)
            local m1, m2 = v1.Magnitude, v2.Magnitude
            if m1 > 5 and m2 > 5 then
                local dot    = math.clamp(v1:Dot(v2) / (m1 * m2), -1, 1)
                local angle  = math.acos(dot)
                -- Cross product Y -> signo de rotacion (+ horario, - antihorario)
                local cross  = v1.X * v2.Z - v1.Z * v2.X
                local signed = (cross >= 0) and (angle / dt) or -(angle / dt)
                local w      = math.exp((i - n) * 0.4)
                totalOmega   = totalOmega + signed * w
                wTotal       = wTotal + w
            end
        end
    end
    return wTotal > 0.001 and (totalOmega / wTotal) or 0
end

-- ============================================================
-- CORE SILENT AIM -- UNIFIED BALLISTIC SOLVER v3
-- Prediccion de alta precision para hitscan (MM2)
-- Mejoras v3:
--   1. EMA split XZ/Y -- strafe reactivo, Y suave
--   2. Historial de posiciones reales (6 frames) -- blend 55/45
--   3. MoveDirection 60/40 -- mas peso a intencion real
--   4. Aceleracion solo cuando importa (tof>40ms y mag>0.5)
--   5. Ping EMA agresiva 35/65 -- reacciona rapido
--   6. Clamp adaptativo 2.5x/3.0x segun ping
--   7. NaN/Inf guard completo
--   8. Server tick compensation +16.6ms fijo (MM2 @ 60Hz)
-- ============================================================

KnifeSAState  = nil
Settings      = nil
CombatState   = nil
scopeNames    = nil  -- definido en CreatePremiumTab, usado en Visuals tambien
-- Pre-inicializar scopeNames con las miras disponibles (mismo orden que CursorScopes en UpdateCustomCursor)
scopeNames = {"CRUZ HOLOGRAFICA","FUEGO ARDIENTE","DIAMANTE DUAL","RAYO ELECTRICO","LUNA OSCURA","PUNTO ROJO","VORTICE MORTAL","OJO VIGILANTE","OBJETIVO PRECISO","EXPLOSION TACTICA","ESTRELLA NEON","DIAMANTE AZUL","PRISMA LETAL"}
CombatTabState = nil
_GUN_NAMES    = nil
_findGunIn    = nil
_findGun      = nil

_BS             = 9999
_GRAVITY        = workspace.Gravity
_BULLET_GRAVITY = 0.0
_BASE_MAX_OFFSET = 6  -- reducido: mismo techo que SA_PRED_MAX_OFFSET
_MAX_CHAR_SPEED  = 220

-- Historial de posiciones reales por jugador
_posHistory    = {}
_POS_HIST_SIZE = 6

local function _pushPosHist(uid, pos, t)
    if not _posHistory[uid] then _posHistory[uid] = {} end
    local h = _posHistory[uid]
    table.insert(h, {pos = pos, t = t})
    if #h > _POS_HIST_SIZE then table.remove(h, 1) end
end

local function _getPosHistVel(uid, fallbackVel)
    local h = _posHistory[uid]
    if not h or #h < 2 then return fallbackVel end
    local newest = h[#h]; local oldest = h[1]
    local dt = newest.t - oldest.t
    if dt < 0.005 then return fallbackVel end
    local hv = (newest.pos - oldest.pos) / dt
    if hv.Magnitude > _MAX_CHAR_SPEED * 1.5 then return fallbackVel end
    return hv
end

function _isGrounded(hrp)
    if not hrp then return true end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { hrp.Parent }
    return workspace:Raycast(hrp.Position, Vector3.new(0, -4.5, 0), rp) ~= nil
end

function _clampVel(vel)
    local m = vel.Magnitude
    return m > _MAX_CHAR_SPEED and vel.Unit * _MAX_CHAR_SPEED or vel
end

-- -- SOLVER v3 ---------------------------------------------------------------
function _unifiedBalisticSolver(targetPart, rootPart, flags, murderer)
    if not targetPart or not rootPart then return nil, nil, 0 end
    local f       = flags or {}
    local usePred = (f.usePrediction == true)
    local myChar  = LocalPlayer.Character
    local myHRP   = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myHRP then return targetPart.Position, murderer, 0 end

    local uid    = murderer and murderer.UserId or 0
    local h      = _getHist(uid)
    local now    = os.clock()
    local rawVel = rootPart.AssemblyLinearVelocity or Vector3.zero
    local rawSpd = rawVel.Magnitude * (_gDistScale or 1.0)  -- FIX CERCA: escala a 0 si esta cerca

    _pushPosHist(uid, rootPart.Position, now)

    if not usePred then
        -- Sin prediccion: retornar posicion exacta sin ningun offset de velocidad
        return targetPart.Position, murderer, 0
    end
    if rawSpd < 2.0 then
        return targetPart.Position, murderer, 0
    end

    -- Ping one-way, EMA suave y conservadora
    local _rawPing = 60
    pcall(function() _rawPing = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 800) end)
    if not _G._pingEMA then _G._pingEMA = _rawPing end
    -- Alpha fijo y conservador: 0.20 (antes 0.40-0.70 adaptativo -- era demasiado reactivo)
    local _pingAlpha = 0.20
    _G._pingEMA = _G._pingEMA * (1 - _pingAlpha) + _rawPing * _pingAlpha
    local pingMs = _G._pingEMA
    pcall(function()
        if Settings and Settings.combat and Settings.combat.predPing then
            pingMs = pingMs + (Settings.combat.predPing or 0)
        end
    end)

    -- TOF conservador: solo el ping propio, sin extras por server tick
    -- Antes: ping alto -> pingMs + serverTick + 15% extra -> sobreprediccion masiva
    -- Ahora: tof = ping / 2 (one-way estimado), clampeado a max 120ms efectivo
    local tof = math.clamp(pingMs / 2 / 1000, 0.010, 0.080)  -- reducido: max 80ms evita over-shoot
    -- FIX CERCA: escalar prediccion a 0 si el target esta muy cerca
    local _gDist = math.max(0.1, (rootPart.Position - targetPart.Position).Magnitude)
    local _gDistScale = math.clamp((_gDist - 4) / 12, 0, 1)
    local livePos = rootPart.Position

    -- EMA split XZ/Y -- alfas reducidos para suavizar mas y evitar over-shoot
    local velXZ = Vector3.new(rawVel.X, 0, rawVel.Z)
    local velY  = Vector3.new(0, rawVel.Y, 0)

    if h.emaVelXZ then
        -- aXZ: 0.25 normal, 0.50 al cambiar direccion (antes 0.40 / 0.75)
        local dotXZ = (velXZ.Magnitude > 0.1 and h.emaVelXZ.Magnitude > 0.1)
            and Vector3.new(velXZ.X,0,velXZ.Z).Unit:Dot(Vector3.new(h.emaVelXZ.X,0,h.emaVelXZ.Z).Unit) or 1.0
        local aXZ = dotXZ > 0.6 and 0.18 or 0.35  -- mas suave: menos sobre-correccion en giros
        h.emaVelXZ = h.emaVelXZ + (velXZ - h.emaVelXZ) * aXZ
    else h.emaVelXZ = velXZ end

    if h.emaVelY then
        h.emaVelY = h.emaVelY + (velY - h.emaVelY) * 0.14  -- mas suave en Y
    else h.emaVelY = velY end

    local smoothVel = _clampVel(Vector3.new(h.emaVelXZ.X, h.emaVelY.Y, h.emaVelXZ.Z))
    local histVel   = _getPosHistVel(uid, smoothVel)
    -- Blend conservador: 80% EMA + 20% historial (antes hasta 50/50 en ping alto)
    local _blendHist = 0.12  -- menos peso al historial para no arrastrar la prediccion
    local _blendEMA  = 1 - _blendHist
    local blendVel   = Vector3.new(
        smoothVel.X * _blendEMA + histVel.X * _blendHist,
        smoothVel.Y * _blendEMA + histVel.Y * _blendHist,
        smoothVel.Z * _blendEMA + histVel.Z * _blendHist
    )

    -- Aceleracion desactivada: causaba over-shoot en targets que frenan/giran
    local accel = Vector3.zero
    h.prevRawVel = rawVel

    -- MoveDirection: peso minimo -- la velocidad real manda (antes 75/25)
    local moveDir = Vector3.zero
    pcall(function()
        local tHum = rootPart.Parent and rootPart.Parent:FindFirstChildOfClass("Humanoid")
        if tHum and tHum.MoveDirection.Magnitude > 0.1 then
            moveDir = tHum.MoveDirection * math.max(tHum.WalkSpeed, 1)
        end
    end)

    local velX = blendVel.X; local velZ = blendVel.Z; local velYf = blendVel.Y
    if moveDir.Magnitude > 0.1 then
        velX = blendVel.X * 0.94 + moveDir.X * 0.06  -- minimo peso intencion
        velZ = blendVel.Z * 0.94 + moveDir.Z * 0.06
    end

    local multH = math.clamp((Settings and Settings.combat and Settings.combat.mult and Settings.combat.mult.horiz or 100)/100, 0.05, 3)
    local multV = math.clamp((Settings and Settings.combat and Settings.combat.mult and Settings.combat.mult.vert  or 100)/100, 0.05, 3)
    velX = velX * multH; velZ = velZ * multH; velYf = velYf * multV

    if f.predictJump and not _isGrounded(rootPart) then
        local vy = rawVel.Y
        if math.abs(vy) > 0.5 then
            local _cs  = Settings and Settings.combatSettings or {}
            local gEff = math.clamp((_cs.gravityComp or 0.5), 0, 2) * _GRAVITY
            velYf = (vy * tof - 0.5 * gEff * tof * tof) / math.max(tof, 0.001) * multV
        end
    end

    -- Cinematica: sin termino de aceleracion (accel = 0 siempre)
    local predicted = Vector3.new(
        livePos.X + velX  * tof,
        livePos.Y + velYf * tof,
        livePos.Z + velZ  * tof
    )
    predicted = predicted + (targetPart.Position - livePos)  -- offset HRP->parte

    -- NaN/Inf guard
    if predicted ~= predicted or predicted.Magnitude ~= predicted.Magnitude then
        return targetPart.Position, murderer, rawSpd
    end
    h.lastPredicted = predicted

    -- Clamp conservador: max 8 studs fijos (antes 12-22 segun ping)
    -- Evita que un spike de ping catapulte el aim metros por delante del target
    local maxOff = math.clamp(rawSpd * tof * 0.9, 0.3, 5.0)  -- clamp mas conservador: max 5 studs
    local rawOff = predicted - targetPart.Position
    if rawOff.Magnitude > maxOff then
        predicted = targetPart.Position + rawOff.Unit * maxOff
    end

    return predicted, murderer, rawSpd
end

-- -- WRAPPERS -----------------------------------------------------------------

function getSafePredictedPos(targetPart, rootPart, flags)
    local f = flags or {}
    local anyPred = (f.saPredAccel or f.saPredTrend or f.saPredLag or f.saPredStrafe) and true or false
    local murd = findMurderer and findMurderer()
    local pos  = _unifiedBalisticSolver(targetPart, rootPart, {
        usePrediction = anyPred, predictJump = false,
        predictAccel  = f.saPredAccel, predictTrend = f.saPredTrend,
        predictLag    = f.saPredLag,   predictStrafe = f.saPredStrafe,
    }, murd)
    return pos or targetPart.Position
end

function getPredictedPos()
    local murderer = findMurderer()
    if not murderer or not murderer.Character then return nil end
    local rp = murderer.Character:FindFirstChild("HumanoidRootPart")
    if not rp then return nil end
    local tp = murderer.Character:FindFirstChild(CombatTabState and CombatTabState.saTargetPart or "Head") or rp
    local pos = _unifiedBalisticSolver(tp, rp, {
        usePrediction = true, predictJump = not _isGrounded(rp),
        predictAccel  = true, predictTrend = true,
        predictLag    = true, predictStrafe = true,
    }, murderer)
    return pos or tp.Position
end

_predCache = { pos = nil, target = nil, spd = 0, ts = 0 }
_PRED_TTL  = 0.025  -- 1.5 frames @ 60fps

function _getCachedPrediction(explicitTarget)
    local now = os.clock()
    if not explicitTarget and _predCache.pos and (now - _predCache.ts) < _PRED_TTL then
        return _predCache.pos, _predCache.target, _predCache.spd
    end
    local pos, tgt, spd = getAdvancedPredictedPos(explicitTarget)
    if not explicitTarget then
        _predCache.pos = pos; _predCache.target = tgt
        _predCache.spd = spd or 0; _predCache.ts = now
    end
    return pos, tgt, spd
end

function getAdvancedPredictedPos(explicitTarget)
    local murderer = explicitTarget
        or (_G._getEffectiveTarget and _G._getEffectiveTarget())
        or findMurderer()
    if not murderer or not murderer.Character then return nil, nil, 0 end
    local ch  = murderer.Character
    local rp  = ch:FindFirstChild("HumanoidRootPart")
    if not rp then return nil, nil, 0 end
    local tp  = ch:FindFirstChild((CombatTabState and CombatTabState.saTargetPart)
        or (Settings and Settings.combatSettings and Settings.combatSettings.targetBodyPart)
        or "Head") or ch:FindFirstChild("Head") or rp

    local _up     = CombatTabState and CombatTabState.saUsePrediction or false
    local _air    = not _isGrounded(rp)
    -- FIX: respetar cada flag individual en lugar de usar _up para todos
    local _accel  = _up and (CombatTabState.saPredAccel  or false)
    local _trend  = _up and (CombatTabState.saPredTrend  or false)
    -- Prioritize Your Ping: si est? ON, desactivar lag pred del target (usar solo nuestro ping)
    local _lag    = _up and (CombatTabState.saPredLag or false) and not (_G._saPrioritizeOwnPing or false)
    local _strafe = _up and (CombatTabState.saPredStrafe or false)
    local _jump   = _up and (CombatTabState.saPredJump   or false) and _air
    local _any    = _accel or _trend or _lag or _strafe or _jump
    local pos, murd, spd = _unifiedBalisticSolver(tp, rp, {
        usePrediction = _any,   predictJump = _jump,
        predictAccel  = _accel, predictTrend = _trend,
        predictLag    = _lag,   predictStrafe = _strafe,
    }, murderer)

    if pos and Settings and Settings.combat and Settings.combat.offset then
        local o = Settings.combat.offset
        pos = pos + Vector3.new((o.x or 0)/10, (o.y or 0)/10, (o.z or 0)/10)
    end
    return pos or tp.Position, murderer, spd or 0
end

lastShotTime = 0
shotDelay = 0.1  -- solo para compatibilidad; se lee directo de CombatState.autoShootDelay

-- Funcion global de construccion de CFrames para disparos -- usada por SA Button,
-- Auto Shoot Condition y cualquier otro sistema que dispare al servidor.
function buildShootCFrames(originPos, targetPos, graWorldCF)
    local dir = targetPos - originPos
    if dir.Magnitude < 0.01 then return nil, nil end
    local dirUnit = dir.Unit
    local up = math.abs(dirUnit.Y) > 0.95 and Vector3.xAxis or Vector3.yAxis
    local originCF
    if graWorldCF then
        originCF = CFrame.new(graWorldCF.Position) * CFrame.lookAt(Vector3.zero, dirUnit, up)
    else
        originCF = CFrame.lookAt(originPos, targetPos, up)
    end
    local backDir = (originPos - targetPos)
    local backU   = backDir.Magnitude > 0.01 and backDir.Unit or -dirUnit
    local bkUp    = math.abs(backU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
    local targetCF = CFrame.lookAt(targetPos, targetPos + backU, bkUp)
    return originCF, targetCF
end

function startAutoShoot(mode)
    if CombatState.autoShootConnection then
        CombatState.autoShootConnection:Disconnect()
        CombatState.autoShootConnection = nil
    end

    if mode == "Disabled" then return end

    -- Lee el fire rate real de la gun para no disparar mas rapido de lo que acepta el servidor
    local function _getGunFireRate(gun)
        if not gun then return 0.45 end
        for _, v in ipairs(gun:GetDescendants()) do
            if v:IsA("NumberValue") or v:IsA("IntValue") then
                local n = v.Name:lower()
                if n == "firerate" or n == "fire_rate" or n == "cooldown" or n == "delay" then
                    local fr = tonumber(v.Value)
                    if fr and fr > 0 then
                        return fr > 1 and (1 / fr) or fr
                    end
                end
            end
        end
        local gs = gun:FindFirstChild("GunServer")
        if gs then
            local cfg = gs:FindFirstChild("Config") or gs:FindFirstChild("GunConfig")
            if cfg then
                for _, v in ipairs(cfg:GetChildren()) do
                    if v:IsA("NumberValue") or v:IsA("IntValue") then
                        local n = v.Name:lower()
                        if n:find("cooldown") or n:find("rate") or n:find("delay") then
                            local fr = tonumber(v.Value)
                            if fr and fr > 0 then return fr > 1 and (1/fr) or fr end
                        end
                    end
                end
            end
        end
        return 0.45  -- MM2 sheriff revolver ~0.45s entre disparos
    end

    -- Construye los dos CFrames que MM2 espera: ambos apuntan en la MISMA direccion origen->target
    local function _buildShootCFrames(originPos, targetPos, graWorldCF)
        local dir = targetPos - originPos
        if dir.Magnitude < 0.01 then return nil, nil end
        local dirUnit = dir.Unit
        local up = math.abs(dirUnit.Y) > 0.95 and Vector3.xAxis or Vector3.yAxis

        -- graCF: usar WorldCFrame real del attachment si esta disponible
        -- Replica exactamente lo que hace GunClient 2: GunRaycastAttachment.WorldCFrame
        local originCF
        if graWorldCF then
            originCF = CFrame.new(graWorldCF.Position) * CFrame.lookAt(Vector3.zero, dirUnit, up)
        else
            originCF = CFrame.lookAt(originPos, targetPos, up)
        end

        -- targetCF: CFrame en targetPos mirando hacia el origen
        -- Replica WeaponService:GetMouseTargetCFrame() del GunClient 2
        local backDir = (originPos - targetPos)
        local backU   = backDir.Magnitude > 0.01 and backDir.Unit or -dirUnit
        local bkUp    = math.abs(backU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
        local targetCF = CFrame.lookAt(targetPos, targetPos + backU, bkUp)

        return originCF, targetCF
    end

    local _asFrameTick = 0
    CombatState.autoShootConnection = RunService.Heartbeat:Connect(function()
        -- OPT LAG FIX: throttle 2 frames (30Hz) -- el cooldown de la gun ya limita la cadencia real.
        -- Reducir de 60Hz a 30Hz elimina la mitad de los checks de wall/prediction/FindFirstChild.
        _asFrameTick = _asFrameTick + 1; if _asFrameTick < 2 then return end; _asFrameTick = 0
        if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda

        -- OPT: cachear gun cada 0.12s -- evita GetChildren() en cada Heartbeat (60Hz)
        local _asNow = os.clock()
        if not CombatState._asGunCache or not CombatState._asGunCache.Parent
            or (_asNow - (CombatState._asGunTs or 0)) > 0.12 then
            CombatState._asGunCache = LocalPlayer.Character and _findGunIn(LocalPlayer.Character)
            CombatState._asGunTs = _asNow
        end
        local gun = CombatState._asGunCache
        if not gun then return end

        local cooldown = CombatState.autoShootDelay or _getGunFireRate(gun)
        local now = tick()
        if now - CombatState.lastShotTime < cooldown then return end

        local predictedPos, murderer = _getCachedPrediction()
        if not predictedPos or not murderer then return end

        local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not myHRP then return end

        -- Floor guard
        local mHRP = murderer.Character and murderer.Character:FindFirstChild("HumanoidRootPart")
        if mHRP then
            if predictedPos.Y < mHRP.Position.Y - 3 then
                predictedPos = Vector3.new(predictedPos.X, mHRP.Position.Y, predictedPos.Z)
            end
            local fgDir = predictedPos - myHRP.Position
            if fgDir.Magnitude > 0.01 and fgDir.Unit.Y < -0.85 then return end
        end
        if not mHRP then return end

        -- Wall check
        if CombatState and CombatState.simpleAutoShootWallCheck then
            if not wallCheckRaycast(myHRP.Position, predictedPos) then return end
        end

        -- FIX: origen desde barrel attachment -> camara -> HRP+1.5.
        -- MM2 usa la camara como origen del raycast del sheriff, no el HRP.
        -- Usar HRP+1.5 causaba que el raycast saliera desde el cuerpo -> miss
        -- contra targets tapados por la geometria entre el cuerpo y la camara.
        local barrelAtt   = getGunAttachment(gun, myHRP)
        local graWorldCF_as = barrelAtt and barrelAtt.WorldCFrame  -- CFrame completo
        local _cam = workspace.CurrentCamera
        local originPos = (barrelAtt and barrelAtt.WorldPosition)
                       or (_cam and _cam.CFrame.Position)
                       or (myHRP.Position + Vector3.new(0, 1.5, 0))

        CombatState.lastShotTime = now

        if mode == "Auto Shoot" then
            -- FIX: usar shootRemote si existe (no mueve la camara, mas confiable).
            -- Solo hacer snap+Activate como fallback si no hay remote.
            local shootR_as = getShootRemote(gun)
            if shootR_as then
                local oCF_as, tCF_as = _buildShootCFrames(originPos, predictedPos, graWorldCF_as)
                if oCF_as and tCF_as then
                    pcall(function() shootR_as:FireServer(oCF_as, tCF_as) end)
                end
            else
                -- FIX: sin redireccion de camara -- Activate directo sin snap
                _fireGunMM2(gun)
            end

        elseif mode == "Auto Shoot + Prediction" or mode == "Smart Shoot (Best)" then
            local shootR = getShootRemote(gun)
            if shootR then
                local oCF, tCF = _buildShootCFrames(originPos, predictedPos, graWorldCF_as)
                if oCF and tCF then
                    pcall(function() shootR:FireServer(oCF, tCF) end)
                end
            else
                -- Sin remote: Activate directo sin redirigir camara
                _fireGunMM2(gun)
            end
        end
    end)
end

function startAutoReload()
    if CombatState.autoReloadConnection then
        CombatState.autoReloadConnection:Disconnect()
        CombatState.autoReloadConnection = nil
    end

    local C = Settings.combatSettings
    if not C.autoReload then return end

    local _hbTautoReload = 0
    local _arTick=0
    CombatState.autoReloadConnection = RunService.Heartbeat:Connect(function()
        _arTick=_arTick+1; if _arTick<6 then return end; _arTick=0  -- OPT: ~10Hz para auto-reload
        _hbTautoReload=_hbTautoReload+1; if _hbTautoReload<3 then return end; _hbTautoReload=0
        if not C.autoReload then return end
        if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda
        -- FIX: buscar gun por _GUN_NAMES igual que autoShoot (no solo literal "Gun")
        local gun = nil
        if LocalPlayer.Character then
            for _, t in ipairs(LocalPlayer.Character:GetChildren()) do
                if t:IsA("Tool") then
                    local n = t.Name:lower()
                    if (_GUN_NAMES and _GUN_NAMES[t.Name]) or n:find("gun") or n:find("sheriff") or n:find("revolver") then
                        gun = t; break
                    end
                end
            end
        end
        if not gun then return end
        local ammo = gun:FindFirstChild("Ammo")
        if ammo and ammo.Value <= 0 then
            if C.instantReload then
                local maxAmmo = gun:FindFirstChild("MaxAmmo")
                ammo.Value = maxAmmo and maxAmmo.Value or 8
            else
                pcall(function()
                    local ev = gun:FindFirstChild("ReloadEvent")
                    if ev then ev:FireServer("Reload") end
                end)
            end
        end
    end)
end

function resetShootCache()
    _cachedShootRemote = nil
end

_gunPickupSavedCF = nil

function _getGunDropPart(obj)
    if obj:IsA("BasePart") then return obj end
    if obj:IsA("Tool") or obj:IsA("Model") then
        return obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart")
    end
    return nil
end

_fluidGrabThrottle = 0
-- AUTO GRAB GUN -- sin lag (event-driven, un solo grab pendiente a la vez)
_grabGunLastTime = 0
_grabGunPending  = false
-- FIX: nombres de gun que MM2 usa en distintas versiones
_GUN_NAMES = {
    Gun=true, GunDrop=true, DropGun=true,
    gun=true, gundrop=true, dropgun=true,
    SheriffGun=true, HeroGun=true, GunModel=true,
}
-- FIX: alias para setupGunPickup (DescendantAdded usa _gunDropNames)
_gunDropNames = _GUN_NAMES

-- -- HELPER: buscar gun por _GUN_NAMES o keyword en cualquier contenedor ------
-- Reemplaza todos los FindFirstChild("Gun") que solo detectaban el nombre exacto
-- y fallaban con SheriffGun, HeroGun, GunDrop, etc.
_findGunIn = function(container)
    if not container then return nil end
    for _, t in ipairs(container:GetChildren()) do
        if t:IsA("Tool") then
            local n = t.Name:lower()
            if _GUN_NAMES[t.Name] or n:find("gun") or n:find("sheriff") or n:find("revolver") then
                return t
            end
        end
    end
    return nil
end

_findGun = function(charOrNil)
    local char = charOrNil or (LocalPlayer and LocalPlayer.Character)
    local found = char and _findGunIn(char)
    if found then return found end
    local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    return bp and _findGunIn(bp) or nil
end

function _hasGun()
    local char = LocalPlayer.Character
    local bp   = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
    -- FIX: usar _findGun que busca por _GUN_NAMES Y keyword
    -- Antes solo buscaba en _GUN_NAMES, faltaba SheriffRevolver, etc.
    return _findGun(char) ~= nil
end

function _fluidGrabGun(child)
    -- -- Throttle global ----------------------------------------------
    local now = os.clock()
    if now - _grabGunLastTime < 0.01 then return false end  -- 0 delay efectivo (solo antiflood m?nimo)
    _grabGunLastTime = now

    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hrp or not hum or hum.Health <= 0 then return false end
    if _hasGun() then return true end

    local myRole = _roleCache and _roleCache.localRole or "Innocent"
    if myRole == "Murderer" then return false end

    -- FIX v5: aceptar todos los nombres que MM2 usa para la gun suelta
    local childName = child and child.Name or ""
    local childNameL = childName:lower()
    local isGunDrop = (childName == "GunDrop"  -- solo GunDrop exacto
        or childNameL == "gun" or childNameL:find("sheriff") or childNameL:find("revolver"))
    if not isGunDrop then return false end

    -- Obtener la BasePart handle de la gun
    local part = nil
    if child:IsA("BasePart") then
        part = child
    elseif child:IsA("Tool") or child:IsA("Model") then
        part = child:FindFirstChild("Handle") or child:FindFirstChildWhichIsA("BasePart")
    end
    if not part then return false end

    -- Filtro rango murderer
    if Settings.combat.onlyIfMurdererRange then
        local mHead = getMurdererHead()
        if mHead and (part.Position - mHead.Position).Magnitude > Settings.combat.murdererRange then
            return false
        end
    end

    -- -- METODO: La GUN viene hacia el jugador (NO el jugador a la gun) --
    -- Movemos la parte de la gun al HRP usando CFrame client-side.
    -- El servidor detecta la proximidad y da la gun al jugador.
    -- El personaje NUNCA se teletransporta. 0 delay entre pasos.

    -- PASO 1: EquipTool directo (funciona si ya esta en backpack/workspace)
    if child:IsA("Tool") then
        pcall(function() hum:EquipTool(child) end)
        if _hasGun() then return true end
    end

    -- PASO 1.5: ProximityPrompt trigger (MM2 usa esto en algunos modos)
    pcall(function()
        local pp = child:FindFirstChildOfClass("ProximityPrompt")
                or (part and part:FindFirstChildOfClass("ProximityPrompt"))
        if pp then
            fireproximityprompt(pp)
        end
    end)
    if _hasGun() then return true end

    -- PASO 2: mover la gun al jugador (gun viene hacia nosotros, sin TP del HRP, sin delays)
    local targetPos = hrp.Position + Vector3.new(0, -1.2, 0)
    local origCF    = part.CFrame
    local origAnch  = part.Anchored
    pcall(function()
        part.Anchored = false
        part.CFrame = CFrame.new(targetPos)
        if child:IsA("Tool") then child:PivotTo(CFrame.new(targetPos)) end
    end)

    -- PASO 3: firetouchinterest para simular el contacto (mismo frame, sin yield)
    pcall(function()
        firetouchinterest(hrp, part, 0)
        firetouchinterest(hrp, part, 1)
    end)
    if _hasGun() then return true end

    -- PASO 4: segundo intento directo sobre el HRP (mismo frame, sin yield)
    pcall(function()
        part.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 0.5, 0))
        if child:IsA("Tool") then child:PivotTo(CFrame.new(hrp.Position + Vector3.new(0, 0.5, 0))) end
    end)
    pcall(function()
        firetouchinterest(hrp, part, 0)
        firetouchinterest(hrp, part, 1)
    end)
    if _hasGun() then return true end

    -- PASO 5: EquipTool forzado si la gun sigue en workspace
    task.defer(function()
        if _hasGun() then return end
        if child:IsA("Tool") and child.Parent then
            pcall(function() hum:EquipTool(child) end)
        end
        if _hasGun() then return end
        -- Restaurar posicion original si no se agarro (limpieza)
        pcall(function()
            part.CFrame   = origCF
            part.Anchored = origAnch
        end)
    end)

    return true
end

_grabGunPendingObj = nil
function setupGunPickup()
    if CombatState.gunConnection then
        CombatState.gunConnection:Disconnect()
        CombatState.gunConnection = nil
    end
    if CombatState.gunConnectionChild then
        CombatState.gunConnectionChild:Disconnect()
        CombatState.gunConnectionChild = nil
    end

    local function _isGunDrop(obj)
        if not obj then return false end
        -- Solo "GunDrop" exacto -- el nombre que MM2 usa para la gun suelta
        return obj:IsA("Tool") and obj.Name == "GunDrop"
    end

    local function _scheduleGrab(child)
        if not (CombatState and CombatState.autoEquipEnabled) then return end
        if _hasGun() then return end
        if not _isGunDrop(child) then return end
        -- Deduplicar: no lanzar multiples grabs para el mismo objeto
        if _grabGunPendingObj == child then return end
        _grabGunPendingObj = child
        task.defer(function()
            if CombatState and CombatState.autoEquipEnabled and not _hasGun() then
                pcall(_fluidGrabGun, child)
            end
            if _grabGunPendingObj == child then _grabGunPendingObj = nil end
        end)
    end

    -- ChildAdded en workspace: detecta GunDrop suelto en la raiz
    CombatState.gunConnection = workspace.ChildAdded:Connect(function(child)
        _scheduleGrab(child)
    end)

    -- DescendantAdded: para GunDrop dentro de modelos del mapa
    -- Pero con filtro estricto para no spamear con cada parte del mapa
    CombatState.gunConnectionChild = workspace.DescendantAdded:Connect(function(child)
        -- Solo procesar si es un Tool con nombre de GunDrop
        -- El check :IsA("Tool") ya filtra 99.9% de los descendantes
        if child:IsA("Tool") and _gunDropNames[child.Name] then
            _scheduleGrab(child)
        end
    end)

    -- Chequear guns YA existentes al activar
    task.defer(function()
        if not (CombatState and CombatState.autoEquipEnabled) then return end
        if _hasGun() then return end
        -- Buscar en hijos directos de workspace
        for _, obj in ipairs(workspace:GetChildren()) do
            if _isGunDrop(obj) then
                pcall(_fluidGrabGun, obj)
                if _hasGun() then return end
            end
        end
        -- Buscar en hijos de modelos del mapa (un nivel mas)
        if not _hasGun() then
            for _, mapObj in ipairs(workspace:GetChildren()) do
                if mapObj:IsA("Model") or mapObj:IsA("Folder") then
                    for _, obj in ipairs(mapObj:GetChildren()) do
                        if _isGunDrop(obj) then
                            pcall(_fluidGrabGun, obj)
                            if _hasGun() then return end
                        end
                    end
                end
            end
        end
    end)
end

function startCameraTracking()
    if CombatState.trackingConnection then
        CombatState.trackingConnection:Disconnect()
        CombatState.trackingConnection = nil
    end

    local C = Settings.combatSettings
    if not C.trackingEnabled then
        CombatState.trackingActive = false
        return
    end

    -- OPT LAG FIX: trackingConnection ahora usa Heartbeat en vez de RenderStepped.
    -- RenderStepped bloquea el frame renderer; para modos Lerp (Magnetic/Dynamic/Smooth)
    -- es completamente innecesario y causa micro-stutters. Solo "Instant" y perfectTracking
    -- REALMENTE necesitan RenderStepped -- pero el Heartbeat a 60Hz es indistinguible visualmente.
    local _trackTick = 0
    CombatState.trackingConnection = RunService.Heartbeat:Connect(function()
        if not C.trackingEnabled then
            CombatState.trackingActive = false
            return
        end
        -- OPT LAG FIX: throttle 2 frames para modos suaves (Magnetic/Dynamic/Smooth).
        -- Instant y perfectTracking necesitan maxima frecuencia -> no throttlear.
        local _isInstant = (C.trackingMode == "Instant") or C.perfectTracking
        if not _isInstant then
            _trackTick = _trackTick + 1; if _trackTick < 2 then return end; _trackTick = 0
        end
        -- OPT: cachear gun cada 0.1s -- _findGunIn itera GetChildren() cada frame sin esto
        local _now = os.clock()
        if not CombatState._trackGunCache or (_now - (CombatState._trackGunTs or 0)) > 0.1 then
            CombatState._trackGunCache = LocalPlayer.Character and _findGunIn(LocalPlayer.Character)
            CombatState._trackGunTs = _now
        end
        local hasGun = CombatState._trackGunCache
        if not hasGun then
            CombatState.trackingActive = false
            CombatState.currentTrackedTarget = nil
            return
        end

        local predictedPos, murderer = _getCachedPrediction()
        if not predictedPos then
            CombatState.trackingActive = false
            CombatState.currentTrackedTarget = nil
            return
        end

        CombatState.currentTrackedTarget = murderer
        CombatState.trackingActive = true

        local cam = workspace.CurrentCamera
        local targetCF = CFrame.new(cam.CFrame.Position, predictedPos)
        local mode = C.trackingMode

        if mode == "Instant" or C.perfectTracking then
            cam.CFrame = targetCF
        elseif mode == "Magnetic" then
            local screenPred, onScreen = cam:WorldToViewportPoint(predictedPos)
            local center = Vector2.new(cam.ViewportSize.X/2, cam.ViewportSize.Y/2)
            local screenDist = (Vector2.new(screenPred.X, screenPred.Y) - center).Magnitude
            if screenDist <= C.magneticRadius then
                cam.CFrame = cam.CFrame:Lerp(targetCF, C.trackingSpeed)
            end
        elseif mode == "Dynamic" then
            local dist = 0
            if murderer and murderer.Character and murderer.Character:FindFirstChild("HumanoidRootPart")
            and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                local _mDynHRP = murderer.Character:FindFirstChild("HumanoidRootPart")
                local _myDynHRP = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if _mDynHRP and _myDynHRP then
                    dist = (_mDynHRP.Position - _myDynHRP.Position).Magnitude
                end
            end
            local dynamicSpeed = math.clamp(C.trackingSpeed * (dist / 50), 0.1, 1)
            cam.CFrame = cam.CFrame:Lerp(targetCF, dynamicSpeed)
        else
            local spd = C.trackingSpeed
            if C.aggressiveTracking then
                spd = math.min(spd * 1.5, 1)
            end
            cam.CFrame = cam.CFrame:Lerp(targetCF, spd)
        end

        if C.autoFirePerfect then
            local screenPred, onScreen = cam:WorldToViewportPoint(predictedPos)
            local center = Vector2.new(cam.ViewportSize.X/2, cam.ViewportSize.Y/2)
            local aim_dist = (Vector2.new(screenPred.X, screenPred.Y) - center).Magnitude
            if aim_dist <= C.perfectThreshold then
                local gun = LocalPlayer.Character and _findGunIn(LocalPlayer.Character)
                if gun then _fireGunMM2(gun) end
            end
        end
    end)
end


