ThemeObjects = {}

function RegisterThemeObject(obj, property, colorKey)
    table.insert(ThemeObjects, {obj = obj, property = property, colorKey = colorKey})
end

-- ==================================================================
-- ApplyTheme v3 -- remap completo de colores en todo el hub
-- Estrategia: guardar el tema anterior, hacer un mapa viejo->nuevo
-- y recorrer TODOS los descendants remplazando colores en vivo.
-- ==================================================================
_prevThemeSnapshot = nil

local function _colorsClose(a, b, tol)
    tol = tol or 18
    return math.abs(a.R*255 - b.R*255) < tol
       and math.abs(a.G*255 - b.G*255) < tol
       and math.abs(a.B*255 - b.B*255) < tol
end

local function _remapColor(oldColor, oldTheme, newTheme)
    -- Busca a que clave del tema viejo corresponde oldColor y devuelve el nuevo
    local keys = {"Primary","Secondary","Accent","Background","BackgroundLight","TextPrimary","TextSecondary","Aurora1","Aurora2","Aurora3","Aurora4"}
    local bestKey = nil
    local bestDist = math.huge
    for _, k in ipairs(keys) do
        local tc = oldTheme[k]
        local dr = (oldColor.R - tc.R)*255
        local dg = (oldColor.G - tc.G)*255
        local db = (oldColor.B - tc.B)*255
        local dist = dr*dr + dg*dg + db*db
        if dist < bestDist then
            bestDist = dist
            bestKey = k
        end
    end
    -- Mapear SIEMPRE al color del nuevo tema m?s cercano (sin l?mite de distancia)
    if bestKey then
        return newTheme[bestKey]
    end
    return nil
end

function ApplyTheme(themeName)
    local newT = Themes[themeName]
    if not newT then return end

    -- Snapshot del tema actual ANTES de cambiar ThemeColors
    local oldT = {}
    local keys = {"Primary","Secondary","Accent","Background","BackgroundLight","TextPrimary","TextSecondary","Aurora1","Aurora2","Aurora3","Aurora4"}
    for _, k in ipairs(keys) do
        oldT[k] = Color3.new(ThemeColors[k].R, ThemeColors[k].G, ThemeColors[k].B)
    end

    -- Actualizar ThemeColors global
    currentThemeName = themeName
    for k, v in pairs(newT) do
        ThemeColors[k] = v
    end

    -- Actualizar ThemeObjects registrados
    for _, entry in ipairs(ThemeObjects) do
        if entry.obj and entry.obj.Parent then
            pcall(function()
                entry.obj[entry.property] = ThemeColors[entry.colorKey]
            end)
        end
    end

    local ti = TweenInfo.new(0.35, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)

    -- -- Recorrer TODOS los descendants del hub ---------------------
    pcall(function()
        if not (mainFrame and mainFrame.Parent) then return end

        -- El frame raiz
        TweenService:Create(mainFrame, ti, {BackgroundColor3 = newT.Background}):Play()

        for _, obj in ipairs(mainFrame:GetDescendants()) do
            pcall(function()
                -- PROTEGER toggles: saltar ToggleBackground (pildora), Knob y sus hijos
                local objName = obj.Name or ""
                if objName == "Knob" or objName == "ToggleBackground" then return end
                if objName == "TOGGLE_ROW_TAG" or objName == "TOGGLE_STROKE_PROTECTED" or objName == "TOGGLE_TRACK_STROKE" then return end
                local parentName = (obj.Parent and obj.Parent.Name) or ""
                if parentName == "ToggleBackground" then return end
                -- Saltar el rowFrame del toggle y todos sus hijos
                if obj:IsA("Frame") and obj.Name:sub(1,16) == "AuroraToggleRow_" then return end
                if objName == "TOGGLE_STROKE_PROTECTED" then return end
                -- Saltar hijos directos e indirectos de AuroraToggleRow_
                local _p = obj.Parent
                while _p do
                    if _p.Name and _p.Name:sub(1,16) == "AuroraToggleRow_" then return end
                    _p = _p.Parent
                    if _p == mainFrame then break end
                end
                -- Saltar el fondo de imagen del hub (HubBackground): nunca remap su color
                if objName == "HubBackground" then return end
                -- Saltar el header rectangular del hub
                if objName == "HubHeaderBar" then return end

                if obj:IsA("Frame") or obj:IsA("ScrollingFrame") or obj:IsA("TextButton") or obj:IsA("ImageButton") then
                    -- Saltar botones de pestana protegidos
                    if obj:FindFirstChild("TAB_BTN_PROTECTED") then return end
                    local mapped = _remapColor(obj.BackgroundColor3, oldT, newT)
                    if mapped then
                        TweenService:Create(obj, ti, {BackgroundColor3 = mapped}):Play()
                    end
                elseif obj:IsA("TextLabel") or obj:IsA("TextBox") then
                    local mappedTxt = _remapColor(obj.TextColor3, oldT, newT)
                    if mappedTxt then
                        TweenService:Create(obj, ti, {TextColor3 = mappedTxt}):Play()
                    end
                    local mappedBg = _remapColor(obj.BackgroundColor3, oldT, newT)
                    if mappedBg and obj.BackgroundTransparency < 0.95 then
                        TweenService:Create(obj, ti, {BackgroundColor3 = mappedBg}):Play()
                    end
                elseif obj:IsA("UIStroke") then
                    local mapped = _remapColor(obj.Color, oldT, newT)
                    if mapped then
                        TweenService:Create(obj, ti, {Color = mapped}):Play()
                    end
                elseif obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                    if obj.ImageColor3 ~= Color3.new(1,1,1) then
                        local mapped = _remapColor(obj.ImageColor3, oldT, newT)
                        if mapped then
                            TweenService:Create(obj, ti, {ImageColor3 = mapped}):Play()
                        end
                    end
                    local mappedBg = _remapColor(obj.BackgroundColor3, oldT, newT)
                    if mappedBg and obj.BackgroundTransparency < 0.95 then
                        TweenService:Create(obj, ti, {BackgroundColor3 = mappedBg}):Play()
                    end
                end
            end)
        end
    end)

    -- -- Sidebar y botones laterales --------------------------------
    pcall(function()
        if sideButtons then
            for _, btnData in ipairs(sideButtons) do
                if btnData and btnData.btn and btnData.btn.Parent then
                    local stroke = btnData.btn:FindFirstChildOfClass("UIStroke")
                    if stroke then
                        TweenService:Create(stroke, ti, {Color = newT.Primary}):Play()
                    end
                    local mapped = _remapColor(btnData.btn.BackgroundColor3, oldT, newT)
                    if mapped then
                        TweenService:Create(btnData.btn, ti, {BackgroundColor3 = mapped}):Play()
                    end
                    for _, child in ipairs(btnData.btn:GetDescendants()) do
                        pcall(function()
                            if child:IsA("TextLabel") then
                                local mc = _remapColor(child.TextColor3, oldT, newT)
                                if mc then TweenService:Create(child, ti, {TextColor3 = mc}):Play() end
                            elseif child:IsA("UIStroke") then
                                local mc = _remapColor(child.Color, oldT, newT)
                                if mc then TweenService:Create(child, ti, {Color = mc}):Play() end
                            end
                        end)
                    end
                end
            end
        end
    end)

    -- -- Orbs de aurora --------------------------------------------
    pcall(function()
        if glowBorder and glowBorder.Parent then
            TweenService:Create(glowBorder, ti, {Color = newT.Primary}):Play()
        end
        if orb1 and orb1.Parent then TweenService:Create(orb1, ti, {BackgroundColor3 = newT.Aurora1}):Play() end
        if orb2 and orb2.Parent then TweenService:Create(orb2, ti, {BackgroundColor3 = newT.Aurora2}):Play() end
        if orb3 and orb3.Parent then TweenService:Create(orb3, ti, {BackgroundColor3 = newT.Aurora3}):Play() end
    end)
    -- Siempre restaurar el fondo de imagen del hub al final del tema
    pcall(function()
        local _bg = _G._hubBgMainImageRef
        if not (_bg and _bg.Parent) then
            _bg = mainFrame and mainFrame:FindFirstChild("HubBackground")
            _G._hubBgMainImageRef = _bg
        end
        if _bg then
            _bg.ImageTransparency = 0
            _bg.ImageColor3 = Color3.new(1, 1, 1)
        end
        if mainFrame and mainFrame.Parent then
            mainFrame.BackgroundTransparency = 1
        end
    end)
end

