-- ============================================================================
-- THROWING KNIFE SYSTEM v3
-- Basado en debug real:
--   - ThrowingKnife (Model) -> KnifeVisual (MeshPart, Transp=0) para posicion
--   - TrailPart (Part, Transp=1) en workspace top-level -- ignorar
--   - StucKnife (MeshPart) en workspace top-level -- cuando se clava
-- El expand usa getnilinstances() para obtener TrailPart como dice el usuario
-- ============================================================================

-- [TK vars moved to _G to free local registers]
_G._TK_ENABLED  = false
_G._TK_RANGE    = 50
_G._TK_mainConn = nil
_G._TK_hbConns  = {}

-- Obtener KnifeThrown remote del knife en char o backpack
function _TK_getEvents()
    local char = LocalPlayer.Character
    if not char then return nil end
    local bp = LocalPlayer:FindFirstChild("Backpack")
    local knife = char:FindFirstChild("Knife")
        or (bp and bp:FindFirstChild("Knife"))
    if not knife then return nil end
    return knife:FindFirstChild("Events")
end

-- == _TK_fire -- dispara todos los remotes conocidos del knife ==============
-- Estructura confirmada del knife (ver screenshot):
--   Knife
--   +- Events/
--   |   +- KnifeThrown    <- trayectoria del throw (CFrame blade, CFrame target)
--   |   +- KnifeStabbed   <- stab cuerpo a cuerpo
--   |   +- HandleTouched  <- colision del handle (sin args)
--   +- Handle/
--       +- Kill           <- remote que registra la MUERTE en el servidor
function _TK_fire(kPos, tHRP)
    local myChar = LocalPlayer.Character
    local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if myHRP and tHRP:IsDescendantOf(myChar) then return end  -- no suicidarse

    local bp    = LocalPlayer:FindFirstChild("Backpack")
    local knife = myChar and myChar:FindFirstChild("Knife")
               or (bp and bp:FindFirstChild("Knife"))
    if not knife then return end

    local ev     = knife:FindFirstChild("Events")
    local handle = knife:FindFirstChild("Handle")
    if not ev then return end

    local tPos   = tHRP.Position
    local dir    = (tPos - kPos)
    -- bladeCF: origen en kPos, apuntando al target
    local bladeCF = dir.Magnitude > 0.01
        and CFrame.new(kPos, tPos)
        or  CFrame.new(kPos)
    -- targetCF: en la posicion del target, orientado igual que el blade
    local targetCF = CFrame.new(tPos, tPos + (dir.Magnitude > 0.01 and dir.Unit or Vector3.new(0,0,1)))

    -- 1. KnifeThrown -- firma correcta: (bladeCF, targetCF), UNA sola vez
    local thrown = ev:FindFirstChild("KnifeThrown")
    if thrown then
        pcall(function() thrown:FireServer(bladeCF, targetCF) end)
    end

    -- 2. HandleTouched -- simula colision con el target
    local touched = ev:FindFirstChild("HandleTouched")
    if touched then
        pcall(function() touched:FireServer(tHRP) end)
    end

    -- 3. KnifeStabbed
    local stabbed = ev:FindFirstChild("KnifeStabbed")
    if stabbed then pcall(function() stabbed:FireServer() end) end

    -- 4. Handle.Kill -- firma: (tHRP), luego (Character), luego sin args
    if handle then
        local kill = handle:FindFirstChild("Kill")
        if kill then
            pcall(function() kill:FireServer(tHRP) end)
            pcall(function() kill:FireServer(tHRP.Parent) end)
            pcall(function() kill:FireServer() end)
        end
        -- Buscar cualquier RemoteEvent en handle por nombre alternativo
        for _, re in ipairs(handle:GetChildren()) do
            if re:IsA("RemoteEvent") and re.Name ~= "Kill" then
                pcall(function() re:FireServer(tHRP) end)
            end
        end
    end
end

-- Expandir hitbox de un knife object usando getnilinstances (TrailPart)
-- + la propia KnifeVisual/StucKnife
function _TK_expandHitbox(knifeObj)
    pcall(function()
        -- Expandir la part visible principal
        if knifeObj:IsA("BasePart") or knifeObj:IsA("MeshPart") then
            knifeObj.Size = Vector3.new(_TK_RANGE * 2, _TK_RANGE * 2, _TK_RANGE * 2)
            knifeObj.Transparency = 0.9  -- casi invisible pero detectable
            knifeObj.CanCollide = false
        elseif knifeObj:IsA("Model") then
            -- KnifeVisual dentro del ThrowingKnife model
            local kv = knifeObj:FindFirstChild("KnifeVisual")
                or knifeObj:FindFirstChildWhichIsA("MeshPart")
                or knifeObj:FindFirstChildWhichIsA("BasePart")
            if kv then
                kv.Size = Vector3.new(_TK_RANGE * 2, _TK_RANGE * 2, _TK_RANGE * 2)
                kv.Transparency = 0.9
                kv.CanCollide = false
            end
        end

        -- TrailPart via getnilinstances (como especifico el usuario)
        if getnilinstances then
            for _, v in next, getnilinstances() do
                if v.ClassName == "Part" and v.Name == "TrailPart" then
                    pcall(function()
                        v.Size = Vector3.new(_TK_RANGE * 2, _TK_RANGE * 2, _TK_RANGE * 2)
                        v.Transparency = 0.9
                        v.CanCollide = false
                    end)
                end
            end
        end
    end)
end

-- Escalar el knife visualmente mientras vuela (ThrowingKnife)
function _TK_scaleFlyingKnife(knifeObj)
    task.spawn(function()
        local t = 0
        while knifeObj and knifeObj.Parent do
            t = t + 0.016
            -- Crece de 1x a 3x en 0.4s luego se mantiene
            local scale = math.min(3, 1 + t * 5)
            local posRef2 = knifeObj:IsA("Model")
                and (knifeObj:FindFirstChild("KnifeVisual")
                    or knifeObj:FindFirstChildWhichIsA("MeshPart"))
                or knifeObj
            if posRef2 and posRef2:IsA("BasePart") then
                pcall(function()
                    posRef2.Size = Vector3.new(
                        math.max(posRef2.Size.X, 0.3 * scale),
                        math.max(posRef2.Size.Y, 0.3 * scale),
                        math.max(posRef2.Size.Z, 0.3 * scale)
                    )
                end)
            end
            task.wait()
        end
    end)
end

-- Monitorear un knife object (ThrowingKnife Model o StucKnife MeshPart)
function _TK_monitor(knifeObj)
    if not _TK_ENABLED then return end

    local isFlying = (knifeObj.Name == "ThrowingKnife")
    local isStuck  = (knifeObj.Name == "StucKnife")

    -- Obtener la part de posicion correcta segun debug:
    -- ThrowingKnife (Model) -> KnifeVisual (MeshPart, Transp=0) tiene la pos real
    -- StucKnife -> es MeshPart directamente
    local posRef
    if knifeObj:IsA("Model") then
        posRef = knifeObj:FindFirstChild("KnifeVisual")
            or knifeObj:FindFirstChildWhichIsA("MeshPart")
            or knifeObj:FindFirstChildWhichIsA("BasePart")
    else
        posRef = knifeObj  -- StucKnife es MeshPart directamente
    end
    if not posRef then return end

    -- Expandir hitbox inmediatamente al detectar
    _TK_expandHitbox(knifeObj)

    -- Si esta volando: escalar progresivamente mientras vuela
    if isFlying then
        _TK_scaleFlyingKnife(knifeObj)
    end

    -- -- ANTI-RESET: mantener el hitbox expandido aunque Roblox lo restablezca --
    -- La pantalla negra (o el server) puede resetear BasePart.Size al original.
    -- Este loop lo fuerza a mantenerse expandido cada 0.05s mientras el knife vive.
    local _antiResetConn
    local function _getTargetSize()
        -- StucKnife usa 3x, ThrowingKnife usa 2x
        local mult = isStuck and 3 or 2
        return Vector3.new(_TK_RANGE * mult, _TK_RANGE * mult, _TK_RANGE * mult)
    end

    local _arT = 0
    _antiResetConn = RunService.Heartbeat:Connect(function()
        _arT = _arT + 1; if _arT < 3 then return end; _arT = 0  -- ~20Hz
        if not posRef or not posRef.Parent then
            pcall(function() _antiResetConn:Disconnect() end)
            return
        end
        local targetSize = _getTargetSize()
        -- Solo re-expandir si el servidor lo reseto (ahorra sets innecesarios)
        if (posRef.Size - targetSize).Magnitude > 1 then
            pcall(function()
                posRef.Size        = targetSize
                posRef.Transparency = isStuck and 0.95 or 0.9
                posRef.CanCollide   = false
            end)
        end
    end)

    local killed = {}
    local conn

    -- Si se clava (StucKnife): expansion masiva + fire+kill inmediato a todos en rango
    if isStuck then
        task.spawn(function()
            local kPos = posRef.Position
            -- Expansion de hitbox masiva al clavarse
            pcall(function()
                posRef.Size = Vector3.new(_TK_RANGE * 3, _TK_RANGE * 3, _TK_RANGE * 3)
                posRef.Transparency = 0.95
                posRef.CanCollide = false
            end)
            -- FIX: matar solo al jugador MAS CERCANO al knife (no a todos)
            local bestP, bestDist, bestHRP = nil, math.huge, nil
            for _, p in ipairs(_cachedPlayers) do
                if p == LocalPlayer then continue end
                local pc = p.Character
                if not pc then continue end
                local phrp = pc:FindFirstChild("HumanoidRootPart")
                if not phrp then continue end
                local dist = (kPos - phrp.Position).Magnitude
                if dist <= _TK_RANGE and dist < bestDist then
                    bestP = p; bestDist = dist; bestHRP = phrp
                end
            end
            if bestHRP then
                _TK_fire(kPos, bestHRP)
                CreateCustomNotification(" STUCK KNIFE", "Kill @ " .. math.floor(bestDist) .. " studs!", 1.5)
            end
        end)
    end

    local _tkHbT = 0
    conn = RunService.Heartbeat:Connect(function()
        if not _TK_ENABLED then pcall(function() conn:Disconnect() end); return end
        _tkHbT = _tkHbT + 1; if _tkHbT < 2 then return end; _tkHbT = 0  -- OPT: throttle 30Hz

        -- Cleanup si el knife desaparecio
        if not knifeObj.Parent or not posRef.Parent then
            pcall(function() conn:Disconnect() end)
            pcall(function() if _antiResetConn then _antiResetConn:Disconnect() end end)
            return
        end

        local kPos = posRef.Position
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")

        for _, p in ipairs(_cachedPlayers) do
            if p == LocalPlayer or killed[p] then continue end
            local pc   = p.Character
            if not pc then continue end
            local phrp = pc:FindFirstChild("HumanoidRootPart")
            if not phrp then continue end

            local dist = (kPos - phrp.Position).Magnitude
            if dist <= _TK_RANGE then
                killed[p] = true
                _TK_fire(kPos, phrp)
 CreateCustomNotification(" THROWING KNIFE", "Kill!", 1)
            end
        end
    end)
    table.insert(_TK_hbConns, conn)

    -- Cleanup automatico de conns viejas
    if #_TK_hbConns > 30 then
        for i = 1, 10 do
            pcall(function() _TK_hbConns[1]:Disconnect() end)
            table.remove(_TK_hbConns, 1)
        end
    end
end

function _TK_stopAll()
    _TK_ENABLED = false
    if _TK_mainConn then
        pcall(function() _TK_mainConn:Disconnect() end)
        _TK_mainConn = nil
    end
    if _TK_descConn then
        pcall(function() _TK_descConn:Disconnect() end)
        _TK_descConn = nil
    end
    for _, c in ipairs(_TK_hbConns) do
        pcall(function() c:Disconnect() end)
    end
    _TK_hbConns = {}
end

function _TK_startGlobal()
    _TK_stopAll()
    _TK_ENABLED = true

    -- ChildAdded: ThrowingKnife (directo en workspace)
    -- Set anti-duplicado (evita que ChildAdded + DescendantAdded procesen el mismo knife)
    local _tkDone = {}
    local function _tkProcess(obj, delayT)
        local id = tostring(obj)
        if _tkDone[id] then return end
        _tkDone[id] = true
        if delayT and delayT > 0 then
            task.wait(delayT)
            if not obj.Parent then _tkDone[id] = nil; return end
        end
        _TK_monitor(obj)
        task.spawn(function()
            while obj and obj.Parent do task.wait(0.5) end
            _tkDone[id] = nil
        end)
    end

    _TK_mainConn = workspace.ChildAdded:Connect(function(obj)
        if not _TK_ENABLED then return end
        local n = obj.Name
        if n == "ThrowingKnife" and obj:IsA("Model") then
            _tkProcess(obj, 0.02)
        elseif n == "StucKnife" then
            _tkProcess(obj, 0)
        end
    end)

    -- FIX: DescendantAdded -- StucKnife a veces aparece dentro de un Model, no directo en workspace
    _TK_descConn = workspace.DescendantAdded:Connect(function(obj)
        if not _TK_ENABLED then return end
        if obj.Name == "StucKnife" and obj:IsA("BasePart") then
            _tkProcess(obj, 0)
        end
    end)

    -- Tambien detectar los que ya estan en workspace al activar
    for _, obj in ipairs(workspace:GetChildren()) do
        local n = obj.Name
        if n == "ThrowingKnife" or n == "StucKnife" then
            _TK_monitor(obj)
        end
    end

    -- Escanear knives ya en workspace al activar
    for _, obj in ipairs(workspace:GetChildren()) do
        local n = obj.Name
        if n == "ThrowingKnife" or n == "StucKnife" then
            _tkProcess(obj, 0)
        end
    end
end

