-- =============================================
-- KNIFE SILENT AIM - NUEVO SISTEMA (reemplaza KnifeClient)
-- C?mara 100% libre ? no mueve ni rota la c?mara
-- =============================================
function _KnifeSA_getBestTarget()
    local myChar = LocalPlayer.Character
    if not myChar then return nil end
    local myHRP = myChar:FindFirstChild("HumanoidRootPart")
    if not myHRP then return nil end
    local knifeSAState = KnifeSAState
    local cam = workspace.CurrentCamera

    if knifeSAState.target == "Murderer" then
        local murder = findMurderer()
        if murder and murder.Character then
            local hrp = murder.Character:FindFirstChild("HumanoidRootPart")
            local hum = murder.Character:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then return murder end
        end
        return nil
    elseif knifeSAState.target == "Sheriff" then
        local sher = findSheriffPlayer and findSheriffPlayer()
        if sher and sher.Character then
            local hrp = sher.Character:FindFirstChild("HumanoidRootPart")
            local hum = sher.Character:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then return sher end
        end
        return nil
    elseif knifeSAState.target == "Select Player" then
        local sp = knifeSAState.specificTarget
        if sp and sp.Parent and sp.Character then
            local hrp = sp.Character:FindFirstChild("HumanoidRootPart")
            local hum = sp.Character:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then return sp end
        end
        return nil
    elseif knifeSAState.target == "All Players" then
        -- Apunta al jugador vivo m?s cercano (cualquiera)
        local best, bestDist = nil, math.huge
        for _, p in pairs(_cachedPlayers) do
            if p ~= LocalPlayer and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local d = (hrp.Position - myHRP.Position).Magnitude
                    if d < bestDist then bestDist = d; best = p end
                end
            end
        end
        return best
    elseif knifeSAState.target == "From Mouse" then
        local mousePos = UserInputService:GetMouseLocation()
        local best, bestDist = nil, math.huge
        local fovR = knifeSAState.mouseFovRadius or 9999
        for _, p in pairs(_cachedPlayers) do
            if p ~= LocalPlayer and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local _skip = false
                    -- Team check
                    if knifeSAState.teamCheck and p.Team and LocalPlayer.Team and p.Team == LocalPlayer.Team then _skip = true end
                    -- ForceField check
                    if not _skip and knifeSAState.forceFieldCheck and p.Character:FindFirstChildOfClass("ForceField") then _skip = true end
                    if not _skip then
                        local sp, onScreen = cam:WorldToViewportPoint(hrp.Position)
                        if onScreen then
                            local d = (Vector2.new(sp.X, sp.Y) - mousePos).Magnitude
                            if d < bestDist and d <= fovR then bestDist = d; best = p end
                        end
                    end
                end
            end
        end
        return best
    else -- Closest
        local best, bestDist = nil, math.huge
        for _, p in pairs(_cachedPlayers) do
            if p ~= LocalPlayer and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local _skip = false
                    -- Team check
                    if knifeSAState.teamCheck and p.Team and LocalPlayer.Team and p.Team == LocalPlayer.Team then _skip = true end
                    -- ForceField check
                    if not _skip and knifeSAState.forceFieldCheck and p.Character:FindFirstChildOfClass("ForceField") then _skip = true end
                    if not _skip then
                        local d = (hrp.Position - myHRP.Position).Magnitude
                        if d < bestDist then bestDist = d; best = p end
                    end
                end
            end
        end
        return best
    end
end

-- Historial de posiciones para predicci?n avanzada ? actualizado continuamente
_knifeSA_posHistory = table.create(90)
_ksa_head = 1
_ksa_count = 0
-- Helper para leer en orden cronol?gico
function _ksaRead(n)
    n = math.min(n or _ksa_count, _ksa_count)
    if n == 0 then return {} end
    local out = table.create(n)
    local startIdx = ((_ksa_head - 1 - _ksa_count + ((_ksa_count - n))) % 90) + 1
    for i = 1, n do
        out[i] = _knifeSA_posHistory[((startIdx - 1 + i - 1) % 90) + 1]
    end
    return out
end
_knifeSA_lastHistoryTime = 0

-- Loop continuo de historial ? 30 Hz para mayor precisi?n de predicci?n
task.spawn(function()
    repeat task.wait(0.1) until _G._hubReady  -- esperar hub cargado
    while true do
        task.wait(1/24)  -- OPT: 30?24 Hz (suficiente para prediccion de cuchillo)
        if not KnifeSAState.enabled then continue end
        local target = _KnifeSA_getBestTarget and _KnifeSA_getBestTarget()
        if target and target.Character then
            local hrp = target.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                -- FIX #5: limpiar AMBOS historiales al cambiar de target para sincronizarlos
                -- Sin esto habia una ventana donde un historial ya estaba limpio y el otro no,
                -- causando predicciones inconsistentes entre knife SA y gun SA
                local tid = target.UserId
                if tid ~= KnifeSAState._lastTargetId then
                    _knifeSA_posHistory = table.create(90); _ksa_head = 1; _ksa_count = 0
                    _knifeSA_lastHistoryTime = 0
                    KnifeSAState._lastTargetId = tid
                    _resetHist(tid)  -- FIX: sincronizar con el historial principal
                end
                local now = os.clock()
                local vel = hrp.AssemblyLinearVelocity or Vector3.new(0,0,0)
                _knifeSA_posHistory[_ksa_head] = {pos = hrp.Position, vel = vel, t = now}
                _ksa_head = (_ksa_head % 90) + 1
                if _ksa_count < 90 then _ksa_count = _ksa_count + 1 end
            end
        end
    end
end)

function _KnifeSA_updatePosHistory(hrp)
    local now = os.clock()
    if now - _knifeSA_lastHistoryTime < 0.03 then return end
    _knifeSA_lastHistoryTime = now
    local vel = hrp.AssemblyLinearVelocity or Vector3.new(0,0,0)
    _knifeSA_posHistory[_ksa_head] = {pos = hrp.Position, vel = vel, t = now}
    _ksa_head = (_ksa_head % 90) + 1
    if _ksa_count < 90 then _ksa_count = _ksa_count + 1 end
end

function _KnifeSA_getPredictedPos(targetHRP, targetChar)
    local myChar = LocalPlayer.Character
    local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")

    -- -- PUNTO BASE (parte a apuntar) -----------------------------------------
    local _partFallbacks = {
        Head             = Vector3.new(0,  2.5, 0),
        UpperTorso       = Vector3.new(0,  1.2, 0),
        LowerTorso       = Vector3.new(0, -0.5, 0),
        HumanoidRootPart = Vector3.new(0,  0.0, 0),
        LeftUpperArm     = Vector3.new(-1.5, 1.0, 0),
        RightUpperArm    = Vector3.new( 1.5, 1.0, 0),
        LeftUpperLeg     = Vector3.new(-0.6,-1.0, 0),
        RightUpperLeg    = Vector3.new( 0.6,-1.0, 0),
    }
    local selectedPart = KnifeSAState.targetPart
    local basePos
    if selectedPart and selectedPart ~= "HumanoidRootPart" then
        local realPart = targetChar and targetChar:FindFirstChild(selectedPart)
        if realPart and realPart:IsA("BasePart") then
            basePos = realPart.Position
        else
            basePos = targetHRP.Position + (_partFallbacks[selectedPart] or Vector3.new(0, 1.4, 0))
        end
    else
        basePos = targetHRP.Position
    end
    if basePos.Y < 0.3 then basePos = Vector3.new(basePos.X, 0.3, basePos.Z) end

    if KnifeSAState.prediction == "None" or not myHRP then return basePos end

    -- -- ORIGEN DEL LANZAMIENTO ------------------------------------------------
    local throwOrigin = myHRP.Position + Vector3.new(0, 1.5, 0)

    -- --------------------------------------------------------------------------
    -- STATIC: predicci?n simple basada en vel*tof sin historial.
    -- ?til cuando el target tiene comportamiento muy lineal y predecible.
    -- --------------------------------------------------------------------------
    if KnifeSAState.prediction == "Static" then
        local pingMs_s = 80
        pcall(function() pingMs_s = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
        -- FIX: one-way ping, no RTT (GetNetworkPing es one-way)
        -- [WIFI PRED] Sumar mitad del ping estimado del target
        local _stPingMs, _stJitter = getTargetPingFor(_knifeTargetUid)
        local ping_s = (pingMs_s + 25 + KnifeSAState.pingComp + (_stPingMs * 0.5) + (_stJitter * 0.1)) / 1000
        local kSpeed_s   = math.max(10, KnifeSAState.knifeSpeed)
        local dist_s     = math.max(0.1, (throwOrigin - basePos).Magnitude)
        local tof_s      = math.clamp(dist_s / kSpeed_s + ping_s, 0.01, 4.0)
        local rawVel_s   = targetHRP.AssemblyLinearVelocity or Vector3.new(0,0,0)
        local multH_s    = KnifeSAState.multH / 100
        local multV_s    = KnifeSAState.multV / 100
        -- Solver iterativo simple (5 iter ? suficiente para l?nea recta)
        local pred_s = basePos
        for _ = 1, 5 do
            local np = Vector3.new(
                basePos.X + rawVel_s.X * multH_s * tof_s,
                basePos.Y + rawVel_s.Y * multV_s * tof_s,
                basePos.Z + rawVel_s.Z * multH_s * tof_s
            ) + Vector3.new(
                KnifeSAState.offsetX / 10,
                KnifeSAState.offsetY / 10,
                KnifeSAState.offsetZ / 10
            )
            local delta_s = (np - pred_s).Magnitude
            pred_s = np
            if delta_s < 0.001 then break end
            tof_s = math.clamp((throwOrigin - pred_s).Magnitude / kSpeed_s + ping_s, 0.01, 4.0)
        end
        -- Clamp vertical de seguridad
        pred_s = Vector3.new(
            pred_s.X,
            math.clamp(pred_s.Y, basePos.Y - 2.4, basePos.Y + 3.2),
            pred_s.Z
        )
        local hOff_s = Vector3.new(pred_s.X - basePos.X, 0, pred_s.Z - basePos.Z)
        if hOff_s.Magnitude > SA_PRED_MAX_OFFSET then
            local cl = basePos + Vector3.new(hOff_s.Unit.X, 0, hOff_s.Unit.Z) * SA_PRED_MAX_OFFSET
            pred_s = Vector3.new(cl.X, pred_s.Y, cl.Z)
        end
        if pred_s ~= pred_s then return basePos end
        return pred_s
    end

    -- --------------------------------------------------------------------------
    -- DYNAMIC: predicci?n completa con historial, EMA triple, strafe, jump,
    -- aceleraci?n, solver iterativo de 32 iter. M?xima precisi?n.
    -- --------------------------------------------------------------------------

    -- -- PAR?METROS CONFIGURABLES ----------------------------------------------
    local pingMs     = 80
    pcall(function() pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
    -- FIX: GetNetworkPing() devuelve one-way (no RTT).
    -- Antes multiplicaba * 0.48 asumiendo RTT ? subestimaba el ping real.
    -- Ahora: ping one-way + 22ms overhead fijo del knife server-side.
    -- [WIFI PRED] A?adir estimaci?n del ping del target al pingComp del knife
    local _knifeTargetUid = 0
    pcall(function()
        local _ktarget = _KnifeSA_getBestTarget and _KnifeSA_getBestTarget()
        if _ktarget then _knifeTargetUid = _ktarget.UserId end
    end)
    local _ktPingMs, _ktJitter, _ktTrend = getTargetPingFor(_knifeTargetUid)
    -- Predecir hacia d?nde va el ping del target
    local _ktPredPing = math.clamp(_ktPingMs + _ktTrend * 0.3, 10, 500)
    -- TOF knife = mi ping + overhead + mitad del ping del target + jitter parcial
    local pingComp = (pingMs + 22 + KnifeSAState.pingComp + (_ktPredPing * 0.5) + (_ktJitter * 0.1)) / 1000
    local knifeSpeed = math.max(10, KnifeSAState.knifeSpeed)  -- studs/s
    local multH      = KnifeSAState.multH   / 100
    local multV      = KnifeSAState.multV   / 100
    local accelW     = KnifeSAState.accelFactor / 100  -- 0..1

    local _ksaBuf = _ksaRead()  -- leer en orden cronol?gico
    local n = #_ksaBuf
    local rawVel = targetHRP.AssemblyLinearVelocity or Vector3.new(0, 0, 0)

    -- --------------------------------------------------------------------------
    -- VELOCIDAD: Kalman-lite mejorado con 3 capas EMA adaptativas
    -- Cada capa reacciona a ritmo diferente: EMA1 r?pida, EMA3 suave.
    -- El blend final prioriza la capa media (balance entre latencia y ruido).
    -- --------------------------------------------------------------------------
    local vel = rawVel

    if n >= 4 then
        local ema1, ema2, ema3 = rawVel, rawVel, rawVel
        -- Inicializar desde la muestra m?s antigua
        ema1 = _ksaBuf[1].vel
        ema2 = _ksaBuf[1].vel
        ema3 = _ksaBuf[1].vel
        local prevVel = ema1

        for i = 2, n do
            local s = _ksaBuf[i]
            local dt = math.max(s.t - (_ksaBuf[i-1] and _ksaBuf[i-1].t or s.t), 0.001)

            -- Magnitud de aceleraci?n instant?nea (studs/s?)
            local accel = (s.vel - prevVel).Magnitude / dt
            -- Jerk (cambio de aceleraci?n) para detectar cambios bruscos de direcci?n
            local prevAccel = i >= 3
                and ((_ksaBuf[i-1].vel - _ksaBuf[i-2].vel).Magnitude / dt)
                or 0
            local jerk = math.abs(accel - prevAccel)

            -- Alpha adaptativo: alto cuando hay aceleraci?n/jerk, bajo en estado estable
            -- Rangos calibrados para MM2 (walkSpeed 16, runSpeed ~20, dash ~50):
            --   Idle/walk: alpha ~0.20 (suave, sin ruido)
            --   Run/strafe: alpha ~0.50
            --   Dash/cambio brusco: alpha ~0.85
            local alpha = math.clamp(
                0.20 + accel * 0.012 + jerk * 0.008,
                0.18, 0.90
            )
            ema1 = ema1:Lerp(s.vel, alpha)
            ema2 = ema2:Lerp(ema1, math.clamp(alpha * 0.55, 0.12, 0.65))
            ema3 = ema3:Lerp(ema2, math.clamp(alpha * 0.35, 0.08, 0.45))
            prevVel = s.vel
        end
        -- Blend mejorado: 8% raw + 60% EMA1 (reactiva) + 32% EMA2 (estable)
        -- Mayor peso en EMA1 = respuesta m?s r?pida a cambios de direcci?n
        vel = rawVel * 0.08 + ema1 * 0.60 + ema2 * 0.32

    elseif n >= 2 then
        local ema = _ksaBuf[1].vel
        for i = 2, n do ema = ema:Lerp(_ksaBuf[i].vel, 0.45) end
        vel = ema:Lerp(rawVel, 0.30)
    end

    -- Clamp de velocidad a m?ximo f?sico de Roblox (~60 studs/s normal, ~110 con dash)
    local velMag = vel.Magnitude
    if velMag > 110 then vel = vel * (110 / velMag) end

    -- --------------------------------------------------------------------------
    -- ACELERACI?N: m?nimos cuadrados ponderados sobre las ?ltimas 10 muestras
    -- Detecta si el target est? acelerando/frenando y a?ade ese t?rmino a la predicci?n.
    -- --------------------------------------------------------------------------
    local accelVec = Vector3.new(0, 0, 0)
    if n >= 5 then
        local accum, wTot = Vector3.new(0, 0, 0), 0
        local lim = math.min(n, 10)
        for i = math.max(2, n - lim + 1), n do
            local ea = _knifeSA_posHistory[i - 1]
            local eb = _ksaBuf[i]
            local dt2 = eb.t - ea.t
            if dt2 > 0.002 then
                local rawA = (eb.vel - ea.vel) / dt2
                -- Ignorar spikes imposibles (teleport, lag) ? umbral 280 studs/s?
                if rawA.Magnitude < 280 then
                    -- Peso exp: m?s peso a las muestras m?s recientes
                    local w = math.exp((i - n) * 0.55)
                    accum = accum + rawA * w
                    wTot  = wTot  + w
                end
            end
        end
        if wTot > 0.001 then
            accelVec = (accum / wTot) * accelW
            -- Clamp total de aceleraci?n: m?x 40 studs/s? (valor f?sico razonable)
            if accelVec.Magnitude > 40 then
                accelVec = accelVec * (40 / accelVec.Magnitude)
            end
        end
    end

    -- --------------------------------------------------------------------------
    -- DETECCI?N DE STRAFE
    -- Cuando el target cambia de direcci?n horizontal frecuentemente, reducimos
    -- la predicci?n horizontal para no disparar al lado contrario.
    -- --------------------------------------------------------------------------
    local strafeFactor = 1.0
    if n >= 6 then
        local dotSum, dotCount = 0, 0
        for i = math.max(2, n - 5), n do
            local va = Vector3.new(_ksaBuf[i-1].vel.X, 0, _ksaBuf[i-1].vel.Z)
            local vb = Vector3.new(_knifeSA_posHistory[i  ].vel.X, 0, _knifeSA_posHistory[i  ].vel.Z)
            if va.Magnitude > 1.5 and vb.Magnitude > 1.5 then
                dotSum   = dotSum   + va.Unit:Dot(vb.Unit)
                dotCount = dotCount + 1
            end
        end
        if dotCount > 0 then
            local avgDot = dotSum / dotCount
            -- avgDot = +1 ? movimiento recto (predicci?n completa)
            -- avgDot = -1 ? strafe duro (predicci?n reducida a 40%)
            -- Curva: cuadr?tica para penalizar strafes moderados tambi?n
            local t_sf = math.clamp((avgDot + 1) / 2, 0, 1)
            strafeFactor = 0.50 + 0.50 * (t_sf * t_sf)
        end
    end

    -- --------------------------------------------------------------------------
    -- DETECCI?N DE SALTO / CA?DA
    -- Separamos vel.Y del target en componentes y ajustamos la predicci?n vertical.
    -- --------------------------------------------------------------------------
    local jumpFactor = 1.0
    if n >= 4 then
        -- Velocidad vertical promedio de las ?ltimas 5 muestras
        local sumY, cnt = 0, math.min(n, 5)
        for i = n - cnt + 1, n do sumY = sumY + _ksaBuf[i].vel.Y end
        local avgVelY = sumY / cnt

        -- Tendencia: ?est? acelerando hacia arriba o hacia abajo?
        local velYTrend = 0
        if n >= 3 then
            velYTrend = (_knifeSA_posHistory[n].vel.Y - _knifeSA_posHistory[n-2].vel.Y) / 2
        end

        if avgVelY > 6 then
            -- Sube (saltando): extender predicci?n vertical levemente
            -- El factor es peque?o para no sobre-estimar el arco del salto
            jumpFactor = math.clamp(1.0 + avgVelY * 0.022 + velYTrend * 0.010, 1.0, 1.30)
        elseif avgVelY < -4 then
            -- Cae: comprimir predicci?n vertical (va a estar m?s abajo de lo que indica la vel)
            jumpFactor = math.clamp(1.0 + avgVelY * 0.022, 0.72, 1.0)
        end
    end

    -- --------------------------------------------------------------------------
    -- SOLVER ITERATIVO DE TOF (Time-of-Flight)
    -- El cuchillo de MM2 viaja en l?nea recta sin ca?da f?sica.
    -- En cada iteraci?n actualizamos la posici?n predicha del target ? recalculamos
    -- la distancia ? recalculamos el TOF hasta convergencia (< 0.001 studs de error).
    -- --------------------------------------------------------------------------
    local dist0 = math.max(0.1, (throwOrigin - basePos).Magnitude)
    -- knifeSpeed garantizado > 0, tof clampado entre 0.01s y 4s
    local tof   = math.clamp(dist0 / math.max(1, knifeSpeed) + pingComp, 0.01, 4.0)

    local predicted = basePos

    for iter = 1, 32 do  -- 32 iter: mayor precisi?n en targets con strafe brusco
        -- Desplazamiento horizontal con strafe aplicado
        local dX = vel.X * multH * strafeFactor * tof
        local dZ = vel.Z * multH * strafeFactor * tof

        -- Desplazamiento vertical con jump/fall compensation
        local dY = vel.Y * multV * jumpFactor * tof

        -- Contribuci?n de aceleraci?n (solo horizontal ? aY causaba overshooting)
        -- t?/2 es la f?rmula de cinem?tica; aDecay reduce el impacto a largo plazo
        local t2h = tof * tof * 0.5
        local aDecay = math.clamp(1.0 - tof * 0.12, 0.10, 1.0)
        local aX = accelVec.X * t2h * aDecay
        local aZ = accelVec.Z * t2h * aDecay

        local newPred = Vector3.new(
            basePos.X + dX + aX,
            basePos.Y + dY,    -- sin contribuci?n de aceleraci?n vertical
            basePos.Z + dZ + aZ
        )

        -- Offsets manuales del usuario (en d?cimas de studs)
        newPred = newPred + Vector3.new(
            KnifeSAState.offsetX / 10,
            KnifeSAState.offsetY / 10,
            KnifeSAState.offsetZ / 10
        )

        -- Convergencia
        local delta = (newPred - predicted).Magnitude
        predicted = newPred
        if delta < 0.001 then break end

        -- Recalcular TOF con nueva posici?n predicha
        local newDist = math.max(0.1, (throwOrigin - predicted).Magnitude)
        -- Clamp TOF en el loop para evitar divergencia
        tof = math.clamp(newDist / math.max(1, knifeSpeed) + pingComp, 0.01, 4.0)
    end

    -- -- CLAMPS DE SEGURIDAD ---------------------------------------------------
    -- 1. Limitar desviaci?n vertical: m?x +3.5/-2.8 studs respecto al basePos
    local maxYUp   = basePos.Y + 3.5
    local maxYDown = basePos.Y - 2.8
    predicted = Vector3.new(
        predicted.X,
        math.clamp(predicted.Y, maxYDown, maxYUp),
        predicted.Z
    )

    -- 2. Limitar offset horizontal total
    local hOff = Vector3.new(predicted.X - basePos.X, 0, predicted.Z - basePos.Z)
    if hOff.Magnitude > SA_PRED_MAX_OFFSET then
        local clamped = basePos + Vector3.new(hOff.Unit.X, 0, hOff.Unit.Z) * SA_PRED_MAX_OFFSET
        predicted = Vector3.new(clamped.X, predicted.Y, clamped.Z)
    end

    -- 3. NaN / Inf guard (tambien cubre componentes individuales)
    local function _isValid(v)
        return v == v and v.Magnitude == v.Magnitude
            and math.abs(v.X) < 1e6 and math.abs(v.Y) < 1e6 and math.abs(v.Z) < 1e6
    end
    if not _isValid(predicted) then return basePos end

    return predicted
end

function _KnifeSA_setupKnife(knife)
    if not KnifeSAState.enabled then return end
    local events       = knife:FindFirstChild("Events")
    if not events then return end
    local knifeThrown   = events:FindFirstChild("KnifeThrown")
    local knifeStabbed  = events:FindFirstChild("KnifeStabbed")
    local handleTouched = events:FindFirstChild("HandleTouched")
    if not knifeThrown then return end

    -- Deshabilitar KnifeClient para tomar control del FireServer
    -- Las animaciones las manejamos nosotros manualmente (ver abajo)
    local kc = knife:FindFirstChild("KnifeClient")
    if kc then kc.Disabled = true end

    -- FIX COMBAT #2: guardar CanCollide original en KnifeSAState para restaurarlo desde _deactivate
    KnifeSAState._origCanCollide = KnifeSAState._origCanCollide or {}
    local _knifeOrigCanCollide = KnifeSAState._origCanCollide
    local handle   = knife:FindFirstChild("Handle")
    -- Fix barrera de puertas: desactivar CanCollide del Handle al equipar
    if handle then
        pcall(function()
            _knifeOrigCanCollide[handle] = handle.CanCollide
            handle.CanCollide = false
        end)
        for _, part in ipairs(knife:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function()
                    _knifeOrigCanCollide[part] = part.CanCollide
                    part.CanCollide = false
                end)
            end
        end
    end

    local equipped  = false
    local stabbing  = false
    local lastStab  = -999
    local lastThrow = -999
    local throwSpeed = knife:GetAttribute("ThrowSpeed") or 1
    local cooldown   = 2 * throwSpeed
    local conns = {}
    local function addConn(c) table.insert(conns, c) end  -- FIX COMBAT #1: local para no contaminar el env global

    -- --------------------------------------------------------------
    -- SISTEMA DE ANIMACIONES SIMPLIFICADO
    -- Anim 1 (ThrowCharge): knife.KnifeClient.ThrowCharge
    -- Anim 2 (ThrowKnife):  knife.KnifeClient.ThrowKnife
    -- Al tocar pantalla se reproduce ThrowKnife y sale el knife volando.
    -- --------------------------------------------------------------

    local _animTracks = {}   -- nombre -> AnimationTrack cacheado

    local function _getAnimator()
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        return hum and hum:FindFirstChildOfClass("Animator")
    end

    -- Obtiene el objeto Animation desde KnifeClient del knife actual
    local function _getAnimObj(name)
        local kc = knife:FindFirstChild("KnifeClient")
        if not kc then return nil end
        return kc:FindFirstChild(name)
    end

    -- Carga o reutiliza un AnimationTrack
    local function _loadTrack(name)
        local animator = _getAnimator()
        if not animator then return nil end
        local cached = _animTracks[name]
        if cached then
            local ok = pcall(function() return cached.IsPlaying end)
            if not ok then _animTracks[name] = nil; cached = nil end
        end
        if not cached then
            local animObj = _getAnimObj(name)
            if not animObj then return nil end
            local ok, track = pcall(function() return animator:LoadAnimation(animObj) end)
            if not ok or not track then return nil end
            track.Name     = name
            track.Priority = Enum.AnimationPriority.Action
            _animTracks[name] = track
        end
        return _animTracks[name]
    end

    -- Reproduce una animacion. Devuelve el track si tuvo exito.
    local function _playKnifeAnim(name)
        local track = _loadTrack(name)
        if not track then return nil end
        if track.IsPlaying then
            pcall(function() track:Stop(0) end)
            task.wait()
        end
        pcall(function() track:Play(0.05); track:AdjustSpeed(1.0) end)
        return track
    end

    -- Para una animacion si esta reproduciendose
    local function _stopKnifeAnim(name)
        local t = _animTracks[name]
        if t then pcall(function() if t.IsPlaying then t:Stop(0.08) end end) end
    end

    local _slashAnimNames = {"SlashKnife", "Slash", "Stab", "Hit", "Animation1"}
    local _throwAnimNames  = {"ThrowCharge", "ThrowKnife"}

    -- Exponer sistema al estado global
    KnifeSAState._animTracks = _animTracks

    KnifeSAState._playThrowAnim = function()
        local track = _playKnifeAnim("ThrowCharge")
        KnifeSAState._lastThrowTrackName = track and "ThrowCharge" or nil
    end

    KnifeSAState._playThrowHoldAnim = function()
        -- FIX MOBILE: reproducir ThrowHold si existe en KnifeClient.
        -- Si NO existe, hacer loop de ThrowCharge para congelar el brazo en la
        -- pose de carga hasta que el jugador toque la pantalla para lanzar.
        -- Sin esto, al terminar ThrowCharge el KnifeClient nativo retoma el control
        -- y resetea el brazo a idle (animacion vuelve a posicion neutra).
        local holdTrack = _loadTrack("ThrowHold")
        if holdTrack then
            pcall(function() holdTrack:Play(0.05); holdTrack:AdjustSpeed(1.0) end)
            KnifeSAState._lastThrowHoldTrackName = "ThrowHold"
        else
            -- ThrowHold no existe: loopear ThrowCharge para sostener el brazo
            local chargeTrack = _loadTrack("ThrowCharge")
            if chargeTrack then
                pcall(function()
                    chargeTrack.Looped = true
                    if not chargeTrack.IsPlaying then
                        chargeTrack:Play(0.05)
                        chargeTrack:AdjustSpeed(0)  -- velocidad 0 = fotograma congelado
                    else
                        chargeTrack:AdjustSpeed(0)  -- congelar en el ultimo fotograma
                    end
                end)
            end
            KnifeSAState._lastThrowHoldTrackName = nil
        end
    end

    -- Funcion para liberar el hold (detener loop de ThrowCharge antes de ThrowKnife)
    KnifeSAState._releaseThrowHoldAnim = function()
        -- Si habia un ThrowHold real, detenerlo
        local holdTrack = _animTracks["ThrowHold"]
        if holdTrack and holdTrack.IsPlaying then
            pcall(function() holdTrack.Looped = false; holdTrack:Stop(0) end)
        end
        -- Si habia ThrowCharge en loop (fallback), detenerlo
        local chargeTrack = _animTracks["ThrowCharge"]
        if chargeTrack and chargeTrack.IsPlaying then
            pcall(function() chargeTrack.Looped = false; chargeTrack:Stop(0) end)
        end
    end

    KnifeSAState._playThrowKnifeAnim = function()
        _playKnifeAnim("ThrowKnife")
    end

    KnifeSAState._getThrowTrack = function()
        local name = KnifeSAState._lastThrowTrackName
        return name and _animTracks[name] or nil
    end

    KnifeSAState._lastThrowTrackName     = nil
    KnifeSAState._lastThrowHoldTrackName = nil

    -- Desktop path: ThrowHold (si existe) + ThrowKnife
    -- CORRECCION: esta funcion se llama DESPUES de que ThrowCharge ya termino.
    -- No debe reproducir ThrowCharge de nuevo. Solo reproduce ThrowHold (si existe
    -- como objeto Animation en KnifeClient) y luego ThrowKnife.
    -- Si ThrowHold no existe en el KnifeClient, reproduce ThrowKnife directamente.
    KnifeSAState._waitThrowHold = function()
        -- Intentar reproducir ThrowHold si existe en KnifeClient
        local holdTrack = _loadTrack("ThrowHold")
        if holdTrack then
            pcall(function() holdTrack:Play(0.05); holdTrack:AdjustSpeed(1.0) end)
            KnifeSAState._lastThrowHoldTrackName = "ThrowHold"
            -- Esperar que ThrowHold termine (con timeout de seguridad)
            local t0 = os.clock()
            repeat task.wait(0.033) until (holdTrack.IsPlaying and (holdTrack.Length or 0) > 0.05)
                or (os.clock() - t0 > 0.5)
            local len = holdTrack.Length or 0
            task.wait(len > 0.05 and len or 0.5)
        else
            -- ThrowHold no existe en este knife: pausa breve para que se vea natural
            task.wait(0.15)
        end
        _playKnifeAnim("ThrowKnife")
    end

    -- Bloquear ThrowHold replicado por servidor (post-FireServer)
    local _throwHoldBlocked = false
    local _animPlayedConn   = nil
    local function _hookAnimatorBlock()
        local animator = _getAnimator()
        if not animator then return end
        if _animPlayedConn then pcall(function() _animPlayedConn:Disconnect() end); _animPlayedConn = nil end
        _animPlayedConn = animator.AnimationPlayed:Connect(function(track)
            if not _throwHoldBlocked then return end
            local n = (track.Name or ""):lower()
            if n == "throwhold" or n == "throw_hold" then
                task.defer(function()
                    if track and track.IsPlaying then
                        pcall(function() track.Looped = false end)
                        pcall(function() track:Stop(0) end)
                    end
                end)
            end
        end)
        addConn(_animPlayedConn)
    end
    KnifeSAState._blockThrowHoldAfterThrow = function()
        _throwHoldBlocked = true
        task.delay(1.5, function() _throwHoldBlocked = false end)
        _hookAnimatorBlock()
    end
    pcall(_hookAnimatorBlock)

    -- Precargar ThrowCharge y ThrowKnife al equipar
    task.spawn(function()
        task.wait(0.3)
        _loadTrack("ThrowCharge")
        _loadTrack("ThrowKnife")
    end)

    -- _playSlashAnim se define abajo y se expone via KnifeSAState
    KnifeSAState._playSlashAnim = nil  -- se asigna abajo


    local function _playSlashAnim()
        KnifeSAState._playSlashAnim = _playSlashAnim
        local animSpeed = 1.0
        if KnifeSAState.fastSlash then
            local pct = math.max(0.1, (KnifeSAState.fastSlashSpeed or 5) / 10)
            animSpeed = pct
        end
        -- Buscar animacion de slash en KnifeClient
        local kc = knife:FindFirstChild("KnifeClient")
        for _, name in ipairs(_slashAnimNames) do
            local animObj = kc and kc:FindFirstChild(name)
            if animObj then
                local track = _loadTrack(name)
                if track then
                    if track.IsPlaying then pcall(function() track:Stop(0) end); task.wait() end
                    pcall(function() track:Play(0.05); track:AdjustSpeed(animSpeed) end)
                    return
                end
            end
        end
    end

    addConn(knife.Equipped:Connect(function()
        equipped = true
        if kc then kc.Disabled = true end
        if handle then pcall(function() handle.CanCollide = false end) end
        for _, part in ipairs(knife:GetDescendants()) do
            if part:IsA("BasePart") then pcall(function() part.CanCollide = false end) end
        end
        -- Al equipar: invalidar cache y recargar ThrowCharge/ThrowKnife
        _animTracks = {}
        KnifeSAState._animTracks = _animTracks
        task.spawn(function()
            task.wait(0.3)
            _loadTrack("ThrowCharge")
            _loadTrack("ThrowKnife")
        end)
        KnifeSAState._lastEquipTime = os.clock()
    end))
    addConn(knife.Unequipped:Connect(function()
        equipped = false; stabbing = false
        for name in pairs(_animTracks) do _stopKnifeAnim(name) end
    end))

    -- FIX COMBAT #6: Race condition ? si _KnifeSA_setupKnife se llama dos veces (ej: respawn r?pido),
    -- el loop anterior sigue corriendo y compite con el nuevo. Se usa una flag en el knife para
    -- detectar setups duplicados y desconectar el anterior.
    -- Loop: mantener KnifeClient desactivado y CanCollide=false
    local _hbTknifeNC = 0
    local _knifeSetupId = (knife:GetAttribute("_SA_SetupId") or 0) + 1
    knife:SetAttribute("_SA_SetupId", _knifeSetupId)
    local mySetupId = _knifeSetupId
    local knifeNoCollideConn = RunService.Heartbeat:Connect(function()
        -- Si hay un setup m?s nuevo o SA fue desactivado, este loop es zombie ? parar
        if not KnifeSAState.enabled then return end
        if knife:GetAttribute("_SA_SetupId") ~= mySetupId then return end
        _hbTknifeNC = _hbTknifeNC + 1; if _hbTknifeNC < 12 then return end; _hbTknifeNC = 0  -- OPT: throttle 200ms
        if not knife or not knife.Parent then return end
        if kc and not kc.Disabled then kc.Disabled = true end
        if not equipped then return end
        if handle and handle.CanCollide then pcall(function() handle.CanCollide = false end) end
    end)
    addConn(knifeNoCollideConn)

    -- -- THROW (RMB) ? click derecho lanza el knife ----------------------------
    -- ARREGLADO: El lanzamiento ahora es con RMB (MouseButton2), no LMB
    -- FIX BUG #2 MOBILE SLASH: Touch is intentionally EXCLUDED here.
    -- On mobile a tap fires as Touch; if Touch were included it would trigger
    -- the KnifeSA throw instead of the native slash animation. Mobile throw is
    -- handled separately via the KnifeThrown remote. Desktop (MouseButton2) is unaffected.
    local rmbThrowTime = -999
    addConn(UserInputService.InputBegan:Connect(function(input, gp)
        if gp or not equipped then return end
        -- MOBILE FIX: only MouseButton2 triggers SA throw; Touch is handled by stab/slash path
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            if not KnifeSAState.enabled then return end  -- FIX: salir si SA fue desactivado
            rmbThrowTime = os.clock()
            
            -- EJECUTAR THROW CON RMB
            local effectiveCooldown = cooldown
            if KnifeSAState.instantThrow then
                effectiveCooldown = 0
            elseif KnifeSAState.fastThrow then
                effectiveCooldown = cooldown * math.max(0.05, (KnifeSAState.fastThrowSpeed or 30) / 100)
            end
            if os.clock() - lastThrow < effectiveCooldown then return end
            if os.clock() - lastStab  < 0.3 then return end
            lastThrow = os.clock()

            task.spawn(function()
            -- Anclar visualmente el knife en la mano DURANTE la animacion
            -- (evita que desaparezca / se vea raro mientras carga ThrowCharge)
            -- INSTANT THROW: saltar weld, animacion y espera ? lanzar en el mismo frame
            local _knifeWeld = nil
            if not KnifeSAState.instantThrow then
                pcall(function()
                    local myChar3 = LocalPlayer.Character
                    local rightHand = myChar3 and (
                        myChar3:FindFirstChild("RightHand") or myChar3:FindFirstChild("Right Arm")
                    )
                    local kHandle3 = knife:FindFirstChild("Handle")
                    if rightHand and kHandle3 then
                        _knifeWeld = Instance.new("WeldConstraint")
                        _knifeWeld.Part0 = rightHand
                        _knifeWeld.Part1 = kHandle3
                        _knifeWeld.Parent = kHandle3
                    end
                end)

                task.spawn(_playThrowAnim)

                -- Esperar que la animacion ThrowCharge TERMINE completamente antes de lanzar
                local animFinished = false
                local maxWait      = 0.5  -- m?ximo de espera en segundos

                pcall(function()
                    local animator = _getAnimator()
                    if not animator then return end
                    task.wait(0.016)
                    for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
                        local n = t.Name:lower()
                        -- FIX: buscar especificamente ThrowCharge, no "throw" o "knife" generico
                        -- para no matchear ThrowKnife o ThrowHold que se carguen en paralelo.
                        if n == "throwcharge" or n == "throw_charge" or n == "charge" then
                            local conn_anim
                            conn_anim = t.Stopped:Connect(function()
                                animFinished = true
                                if conn_anim then conn_anim:Disconnect() end
                            end)
                            local len = t.Length
                            if len and len > 0.05 then
                                maxWait = len + 0.05
                            end
                            break
                        end
                    end
                end)

                local t0 = os.clock()
                while not animFinished and (os.clock() - t0) < maxWait do
                    task.wait()
                end

                -- ThrowHold: reproducir entre ThrowCharge y ThrowKnife.
                -- _waitThrowHold ya NO reproduce ThrowCharge de nuevo (fix aplicado).
                -- Solo reproduce ThrowHold (si existe) y luego ThrowKnife.
                if KnifeSAState._waitThrowHold then
                    pcall(KnifeSAState._waitThrowHold)
                end
            else
                -- Instant Throw: matar cualquier animacion de throw en curso ahora mismo
                pcall(function()
                    local animator = _getAnimator()
                    if not animator then return end
                    for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
                        local n = (t.Name or ""):lower()
                        if n:find("throw") or n:find("charge") or n:find("hold") or n:find("knife") then
                            pcall(function() t:Stop(0) end)
                        end
                    end
                end)
            end

            -- Remover el weld justo antes de lanzar (knife vuelve a comportamiento normal)
            pcall(function()
                if _knifeWeld and _knifeWeld.Parent then
                    _knifeWeld:Destroy()
                end
            end)
            local targetCFrame, handleCF
            local myChar2 = LocalPlayer.Character
            local myHRP   = myChar2 and myChar2:FindFirstChild("HumanoidRootPart")

            if KnifeSAState.enabled then
                local target = _KnifeSA_getBestTarget()
                if target and target.Character then
                    local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                    local tHum = target.Character:FindFirstChildOfClass("Humanoid")
                    if tHRP and tHum and tHum.Health > 0 then
                        local myOK = true
                        if KnifeSAState.wallCheck and myHRP then
                            local tChar2  = target.Character
                            local tHead   = tChar2:FindFirstChild("Head")
                            local losHRP  = wallCheckRaycast(myHRP.Position, tHRP.Position, tChar2)
                            -- cortocircuito: solo raycast al Head si HRP ya fall?
                            local losHead = not losHRP and tHead and wallCheckRaycast(myHRP.Position + Vector3.new(0,1.5,0), tHead.Position, tChar2)
                            myOK = losHRP or losHead
                        end
                        if myOK and myHRP then
                            -- NO llamar _KnifeSA_updatePosHistory aqu?: el loop de 60Hz
                            -- ya actualiza el historial. Llamarlo en el throw inyectar?a
                            -- una muestra duplicada con dt?0, corrompiendo accelVec.
                            local predictedPos = _KnifeSA_getPredictedPos(tHRP, target.Character)

                            local throwOrigin = myHRP.Position + Vector3.new(0, 1.5, 0)
                            if throwOrigin.Y < 0.5 then
                                throwOrigin = Vector3.new(throwOrigin.X, 0.5, throwOrigin.Z)
                            end

                            -- Evitar que apunte al suelo: clamp a m?nimo de 0.3 studs sobre el suelo
                            -- y nunca m?s de 2 studs por debajo del HRP del target
                            local minY = math.max(0.3, tHRP.Position.Y - 1.5)
                            if predictedPos.Y < minY then
                                predictedPos = Vector3.new(predictedPos.X, tHRP.Position.Y + 0.5, predictedPos.Z)
                            end

                            local aimVec = predictedPos - throwOrigin
                            if aimVec.Magnitude < 0.01 then aimVec = myHRP.CFrame.LookVector end
                            local aimDir = aimVec.Unit

                            -- Correcci?n downward solo si el target est? a la MISMA altura
                            -- (no cuando el lanzador est? en una posici?n m?s alta, p.ej. rampa/escalera)
                            -- Regla: si aimDir.Y < -0.6 Y la diferencia de altura no la explica ? corregir
                            local heightDiff = throwOrigin.Y - tHRP.Position.Y  -- positivo = yo m?s arriba
                            local naturalDownward = math.atan(heightDiff / math.max((predictedPos - throwOrigin).Magnitude, 0.1))
                            local aimAngleY = math.asin(math.clamp(aimDir.Y, -1, 1))
                            if aimDir.Y < -0.5 and aimAngleY < naturalDownward - 0.15 then
                                -- Solo corregir si el ?ngulo es m?s bajo que lo que justifica la geometr?a
                                local torsoPos = tHRP.Position + Vector3.new(0, 1.0, 0)
                                local av2 = torsoPos - throwOrigin
                                if av2.Magnitude > 0.01 then
                                    aimDir = av2.Unit
                                    predictedPos = torsoPos
                                end
                            end

                            -- FIX: targetCFrame con orientaci?n correcta
                            -- El servidor usa la rotaci?n de targetCFrame para calcular hit
                            -- Debe mirar desde el target de vuelta hacia el origen (backDir)
                            local backDir2 = throwOrigin - predictedPos
                            if backDir2.Magnitude > 0.1 then
                                targetCFrame = CFrame.new(predictedPos, predictedPos + backDir2.Unit)
                            else
                                targetCFrame = CFrame.new(predictedPos)
                            end
                            handleCF = CFrame.new(throwOrigin, throwOrigin + aimDir)
                        end
                    end
                end
            end

            -- Fallback al mouse si no hay target SA
            if not targetCFrame then
                local mouse = LocalPlayer:GetMouse()
                local mousePos = mouse.Hit.Position
                if mousePos.Y < 0.5 then mousePos = Vector3.new(mousePos.X, 0.5, mousePos.Z) end
                if myHRP then
                    local orig3 = myHRP.Position + Vector3.new(0, 1.5, 0)
                    local dir3  = mousePos - orig3
                    handleCF = dir3.Magnitude > 0.01
                        and CFrame.new(orig3, orig3 + dir3.Unit)
                        or  myHRP.CFrame
                    -- FIX: targetCFrame orientado de vuelta hacia el origen
                    local back3 = orig3 - mousePos
                    targetCFrame = back3.Magnitude > 0.1
                        and CFrame.new(mousePos, mousePos + back3.Unit)
                        or  CFrame.new(mousePos)
                else
                    handleCF = CFrame.new(mousePos)
                    targetCFrame = CFrame.new(mousePos)
                end
            end

            -- Disparar ? probar m?ltiples firmas de KnifeThrown
            -- FIX: activar bloqueo de ThrowHold ANTES de FireServer
            -- (el servidor responde despues y manda ThrowHold al Animator)
            if KnifeSAState._blockThrowHoldAfterThrow then
                pcall(KnifeSAState._blockThrowHoldAfterThrow)
            end
            local fired = false
            pcall(function() knifeThrown:FireServer(handleCF, targetCFrame); fired = true end)
            if not fired then pcall(function() knifeThrown:FireServer(targetCFrame, handleCF); fired = true end) end
            if not fired then pcall(function() knifeThrown:FireServer(targetCFrame); fired = true end) end
            if not fired then pcall(function() knifeThrown:FireServer(handleCF) end) end
            end) -- end task.spawn throw
        end
    end))

    -- -- STAB (LMB) ? click izquierdo = golpe cuerpo a cuerpo -------
    -- ARREGLADO: Ahora es LMB (MouseButton1) para pegar, Touch en mobile
    local lmbStabTime = -999
    addConn(UserInputService.InputBegan:Connect(function(input, gp)
        if gp or not equipped then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            lmbStabTime = os.clock()
        end
    end))

    -- Helper compartido para ejecutar el slash (desktop LMB y mobile Touch)
    local function _doSlash()
        if not equipped or stabbing then return end
        local stabCooldown = 0.85
        if KnifeSAState.fastSlash then
            stabCooldown = 0.85 * math.max(0.05, (KnifeSAState.fastSlashSpeed or 5) / 10)
        end
        if os.clock() - lastStab  < stabCooldown then return end
        if os.clock() - lastThrow < 0.3          then return end
        -- FIX MOBILE: lastThrow solo se actualiza por RMB (desktop).
        -- En mobile el throw pasa por _ksaFireKnife que no toca lastThrow.
        -- Usar KnifeSAState._lastMobileThrowTime para bloquear slash post-throw mobile.
        if KnifeSAState._lastMobileThrowTime and (os.clock() - KnifeSAState._lastMobileThrowTime) < 1.0 then return end
        stabbing = true
        lastStab = os.clock()
        task.spawn(_playSlashAnim)
        pcall(function() knifeStabbed:FireServer() end)
        task.wait(stabCooldown)
        for _, name in ipairs(_slashAnimNames) do _stopKnifeAnim(name) end
        stabbing = false
    end

    addConn(UserInputService.InputEnded:Connect(function(input)
        if not equipped or stabbing then return end
        -- Desktop: MouseButton1
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            if os.clock() - lmbStabTime > 0.5 then return end
            task.spawn(_doSlash)
            return
        end
        -- Mobile: Touch (tap rapido = slash, sin drag)
        if input.UserInputType == Enum.UserInputType.Touch then
            -- Solo si el toque fue corto (menos de 0.4s = tap, no drag)
            if os.clock() - lmbStabTime > 0.4 then return end
            -- No reproducir slash si KnifeSA esta lanzando (evita conflicto con throw)
            if KnifeSAState.enabled then return end
            -- FIX MOBILE v6: bloquear slash si el boton Throw esta en secuencia
            -- (CHARGING / HOLDING / THROWING). _G._mobileThrowState lo setea el boton.
            local mts = _G._mobileThrowState
            if mts and mts ~= "IDLE" then return end
            task.spawn(_doSlash)
        end
    end))

    -- Handle touch para stab
    if handle and handleTouched then
        addConn(handle.Touched:Connect(function(part)
            if os.clock() - lastStab > 0.85 then return end
            if not stabbing then return end
            pcall(function() handleTouched:FireServer(part) end)
        end))
    end

    -- Guardar conns para cleanup posterior
    for _, c in ipairs(conns) do
        table.insert(KnifeSAState._knifeConns, c)
    end
end

function _KnifeSA_activate()
    for _, c in ipairs(KnifeSAState._knifeConns) do pcall(function() c:Disconnect() end) end
    KnifeSAState._knifeConns = {}
    local char = LocalPlayer.Character
    if not char then return end
    -- Knife ya equipado en el Character
    local knife = char:FindFirstChild("Knife")
    if knife then task.spawn(function() task.wait(0.1); _KnifeSA_setupKnife(knife) end) end
    -- Knifes futuros en el Character (flujo normal de equip)
    if KnifeSAState._charConn then KnifeSAState._charConn:Disconnect() end
    KnifeSAState._charConn = char.ChildAdded:Connect(function(child)
        if child:IsA("Tool") and child.Name == "Knife" then
            task.wait(0.2)
            _KnifeSA_setupKnife(child)
        end
    end)

    -- FIX MOBILE EQUIP v1 REVISADO: monitorear Backpack SOLO para pre-cachear el knife.
    -- NO mover autom?ticamente al Character (causaba auto-equip no deseado).
    -- El equip real ocurre ?nicamente cuando el jugador presiona el bot?n.
    if KnifeSAState._bpConn then KnifeSAState._bpConn:Disconnect() end
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if bp then
        KnifeSAState._bpConn = bp.ChildAdded:Connect(function(child)
            if not KnifeSAState.enabled then return end
            if not (child:IsA("Tool") and child.Name == "Knife") then return end
            -- Solo cachear la referencia para que _ksaDoThrow la encuentre r?pido.
            -- NO equipar aqu?: el equip lo dispara ?nicamente el bot?n del jugador.
            KnifeSAState._cachedBpKnife = child
        end)
    end
    -- Re-hookear Backpack al respawnear (CharacterAdded limpia el viejo)
    if KnifeSAState._charRespawnConn then KnifeSAState._charRespawnConn:Disconnect() end
    KnifeSAState._charRespawnConn = LocalPlayer.CharacterAdded:Connect(function(newChar)
        if not KnifeSAState.enabled then return end
        -- Re-activar para el nuevo character
        task.wait(0.5)
        _KnifeSA_activate()
    end)
end

function _KnifeSA_deactivate()
    for _, c in ipairs(KnifeSAState._knifeConns) do
        pcall(function()
            if type(c.Disconnect) == "function" then c:Disconnect() end
        end)
    end
    KnifeSAState._knifeConns = {}
    if KnifeSAState._charConn then KnifeSAState._charConn:Disconnect(); KnifeSAState._charConn = nil end
    -- FIX MOBILE EQUIP v1: limpiar conexiones del Backpack watcher y CharacterAdded respawn
    if KnifeSAState._bpConn then KnifeSAState._bpConn:Disconnect(); KnifeSAState._bpConn = nil end
    if KnifeSAState._charRespawnConn then KnifeSAState._charRespawnConn:Disconnect(); KnifeSAState._charRespawnConn = nil end

    -- FIX KNIFE SA OFF: restaurar completamente el knife original
    -- Re-habilita KnifeClient, restaura CanCollide, detiene animaciones del SA
    -- y espera un frame para que KnifeClient retome el control de animaciones
    local function _restoreKnife(knife)
        if not knife then return end
        -- 1) Re-enable KnifeClient (script original de animaciones)
        local kc = knife:FindFirstChild("KnifeClient")
        if kc then
            kc.Disabled = false
        end
        -- 2) Restaurar CanCollide al valor ORIGINAL guardado (no hardcode true)
        local origCC = KnifeSAState._origCanCollide or {}
        local kHandle = knife:FindFirstChild("Handle")
        if kHandle then
            pcall(function()
                kHandle.CanCollide = (origCC[kHandle] ~= nil) and origCC[kHandle] or true
            end)
        end
        for _, part in ipairs(knife:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function()
                    part.CanCollide = (origCC[part] ~= nil) and origCC[part] or true
                end)
            end
        end
        -- 3) Detener TODAS las animaciones del SA (ThrowCharge, SlashKnife, etc.)
        local char2 = LocalPlayer.Character
        local hum2  = char2 and char2:FindFirstChildOfClass("Humanoid")
        local animr = hum2 and hum2:FindFirstChildOfClass("Animator")
        if animr then
            local knifeAnimNames = {
                throwcharge=true, throwknife=true, throw=true, animation2=true,
                slashknife=true, slash=true, stab=true, hit=true, animation1=true,
                knife=true, charge=true, hold=true
            }
            for _, track in ipairs(animr:GetPlayingAnimationTracks()) do
                local tname = (track.Name or ""):lower()
                local animId = track.Animation and track.Animation.AnimationId or ""
                if knifeAnimNames[tname]
                    or tname:find("throw") or tname:find("slash") or tname:find("knife") or tname:find("stab")
                    or animId:find("1108307876") or animId:find("knife") then
                    -- FIX: Looped=false antes de Stop para que el Animator no reactive ThrowHold
                    pcall(function() track.Looped = false end)
                    pcall(function() track:Stop(0) end)
                end
            end
            -- Invalidar cache de ThrowHold para evitar reanudacion implicita
            if KnifeSAState._animTracks then KnifeSAState._animTracks["ThrowHold"] = nil end
            KnifeSAState._lastThrowHoldTrackName = nil
        end
        -- 4) Resetear estados internos del SA sobre este knife
        KnifeSAState._origCanCollide = {}
    end

    local char = LocalPlayer.Character
    if char then
        local knife = char:FindFirstChild("Knife")
        _restoreKnife(knife)
        -- Restaurar tambi?n en backpack (por si se desequip?)
        local bp = LocalPlayer.Backpack
        if bp then
            local bpKnife = bp:FindFirstChild("Knife")
            _restoreKnife(bpKnife)
        end
        -- Esperar y re-habilitar KnifeClient limpiamente (delay para que el SA termine de soltar el control)
        task.delay(0.25, function()
            if KnifeSAState.enabled then return end  -- si se reactiv?, no hacer nada
            local c2 = LocalPlayer.Character
            if not c2 then return end
            -- Re-habilitar en character
            local k2 = c2:FindFirstChild("Knife")
            if k2 then
                local kc2 = k2:FindFirstChild("KnifeClient")
                if kc2 then
                    kc2.Disabled = false
                    -- Forzar re-equip limpio: desequipar y re-equipar para que KnifeClient arranque fresco
                    local hum3 = c2:FindFirstChildOfClass("Humanoid")
                    if hum3 then
                        pcall(function() hum3:UnequipTools() end)
                        task.wait(0.08)
                        if not KnifeSAState.enabled then  -- doble check
                            -- FIX MOBILE EQUIP v1: Parent move replica al servidor; EquipTool como fallback
                            local _reEquipOk = false
                            pcall(function()
                                k2.Parent = c2  -- m?todo primario: mueve al Character
                                _reEquipOk = true
                            end)
                            if not _reEquipOk then
                                pcall(function() hum3:EquipTool(k2) end)
                            end
                        end
                    end
                end
            end
            -- Re-habilitar en backpack tambi?n
            local bp2 = LocalPlayer.Backpack
            local bpk2 = bp2 and bp2:FindFirstChild("Knife")
            if bpk2 then
                local kc3 = bpk2:FindFirstChild("KnifeClient")
                if kc3 then kc3.Disabled = false end
            end
        end)
    end
end

-- Re-setup autom?tico al respawnear si SA est? activo
LocalPlayer.CharacterAdded:Connect(function()
    if KnifeSAState.enabled then
        task.wait(0.5)
        _KnifeSA_activate()
    end
end)

-- ================================================================
-- == KNIFE SA FOV OVERLAY (brujula / compass visual) v1
-- Muestra un circulo tipo brujula centrado en el personaje del
-- jugador mientras Knife Silent Aim esta activo.
-- COLOR: VERDE  = target dentro del cono (buen angulo, tirar!)
--        AMARILLO = target en rango pero angulo medio
--        ROJO   = target fuera del cono o muy lejos
-- ================================================================
do
    local _ksaGui  = nil   -- ScreenGui del overlay
    local _ksaRefs = {}   -- referencias a frames/labels del overlay (no se pueden poner en ScreenGui)

    -- Colores
    local COL_READY  = Color3.fromRGB(0,  230, 80)    -- verde  (tira!)
    local COL_WARN   = Color3.fromRGB(255, 210, 0)    -- amarillo (casi)
    local COL_BAD    = Color3.fromRGB(220, 50,  50)   -- rojo (no conviene)
    local COL_RING   = Color3.fromRGB(0,  200, 255)   -- azul neon (anillo)

    -- Angulos del cono (igual que la imagen: +-25 grados = 50 deg total)
    local CONE_HALF_DEG = 25   -- grados a cada lado del centro
    local CONE_HALF_RAD = math.rad(CONE_HALF_DEG)

    -- Radio visual del circulo en pixeles
    local RING_SIZE = 160

    local function _ksaDestroyOverlay()
        if _ksaGui then
            pcall(function() _ksaGui:Destroy() end)
            _ksaGui = nil
        end
        _ksaRefs = {}
    end

    local function _ksaCreateOverlay()
        _ksaDestroyOverlay()

        -- Contenedor
        local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if not pg then return end

        local gui = Instance.new("ScreenGui")
        gui.Name            = "KnifeSAFOVOverlay"
        gui.ResetOnSpawn    = false
        gui.IgnoreGuiInset  = true
        gui.ZIndexBehavior  = Enum.ZIndexBehavior.Sibling
        pcall(function() gui.Parent = game:GetService("CoreGui") end)
        if not gui.Parent then gui.Parent = pg end
        _ksaGui = gui

        -- Frame raiz: se posiciona debajo del personaje en el loop
        local root = Instance.new("Frame", gui)
        root.Name                 = "Root"
        root.AnchorPoint          = Vector2.new(0.5, 0.5) -- centrado en los pies del personaje
        root.BackgroundTransparency = 1
        root.Size                 = UDim2.new(0, RING_SIZE + 60, 0, RING_SIZE + 60)
        root.Position             = UDim2.new(0.5, 0, 0.5, 0)  -- posicion inicial; el loop la sobreescribe cada frame
        root.ZIndex               = 20

        -- ---- Anillo exterior (ImageLabel con imagen de circulo) ----
        -- Usamos un Frame cuadrado con UICorner para el circulo
        local ring = Instance.new("Frame", root)
        ring.Name                 = "Ring"
        ring.AnchorPoint          = Vector2.new(0.5, 0.5)
        ring.Size                 = UDim2.new(0, RING_SIZE, 0, RING_SIZE)
        ring.Position             = UDim2.new(0.5, 0, 0.5, 0)
        ring.BackgroundTransparency = 1
        ring.ZIndex               = 20
        local ringCorner = Instance.new("UICorner", ring)
        ringCorner.CornerRadius = UDim.new(1, 0)
        local ringStroke = Instance.new("UIStroke", ring)
        ringStroke.Color        = COL_RING
        ringStroke.Thickness    = 2.5
        ringStroke.Transparency = 0.1

        -- ---- Cruz de miras (lineas horizontales) ----
        local function makeLine(parent, hor, size, offset)
            local ln = Instance.new("Frame", parent)
            ln.BackgroundColor3  = COL_RING
            ln.BackgroundTransparency = 0.25
            ln.BorderSizePixel   = 0
            ln.ZIndex            = 21
            if hor then
                ln.Size          = UDim2.new(0, size, 0, 1.5)
                ln.AnchorPoint   = Vector2.new(0.5, 0.5)
                ln.Position      = UDim2.new(0.5, offset, 0.5, 0)
            else
                ln.Size          = UDim2.new(0, 1.5, 0, size)
                ln.AnchorPoint   = Vector2.new(0.5, 0.5)
                ln.Position      = UDim2.new(0.5, 0, 0.5, offset)
            end
            return ln
        end
        local halfR = RING_SIZE / 2
        -- Linea horizontal izquierda y derecha
        makeLine(ring, true,  halfR * 0.35,  -(halfR * 0.825))
        makeLine(ring, true,  halfR * 0.35,   (halfR * 0.825))
        -- Linea vertical arriba y abajo
        makeLine(ring, false, halfR * 0.35,  -(halfR * 0.825))
        makeLine(ring, false, halfR * 0.35,   (halfR * 0.825))

        -- Labels de angulos (0, 25, 25, 180, 180 como en imagen)
        local function makeLabel(parent, text, ax, ay, px, py)
            local lbl = Instance.new("TextLabel", parent)
            lbl.BackgroundTransparency = 1
            lbl.AnchorPoint = Vector2.new(ax, ay)
            lbl.Position    = UDim2.new(px, 0, py, 0)
            lbl.Size        = UDim2.new(0, 40, 0, 18)
            lbl.Text        = text
            lbl.TextColor3  = COL_RING
            lbl.TextSize    = 12
            lbl.Font        = Enum.Font.GothamBold
            lbl.ZIndex      = 22
            return lbl
        end
        makeLabel(root, "0?",    0.5, 1,   0.5, 0.00)   -- arriba centro
        makeLabel(root, "25?",   1,   1,   0.21, 0.04)  -- arriba izq
        makeLabel(root, "25?",   0,   1,   0.79, 0.04)  -- arriba der
        makeLabel(root, "180?",  1,   0.5, 0.00, 0.5)   -- izquierda
        makeLabel(root, "180?",  0,   0.5, 1.00, 0.5)   -- derecha

        -- ---- Canvas para el cono SVG-like con Frame triangular ----
        -- Dibujamos el cono como dos lineas desde el centro hacia el borde
        -- usando Frames rotados (tecnica clasica de Roblox)
        local coneContainer = Instance.new("Frame", ring)
        coneContainer.Name                 = "ConeContainer"
        coneContainer.BackgroundTransparency = 1
        coneContainer.Size                 = UDim2.new(1, 0, 1, 0)
        coneContainer.Position             = UDim2.new(0, 0, 0, 0)
        coneContainer.ClipsDescendants     = false
        coneContainer.ZIndex               = 21

        -- Linea izquierda del cono
        local lineL = Instance.new("Frame", coneContainer)
        lineL.Name                 = "ConeL"
        lineL.AnchorPoint          = Vector2.new(0, 0.5)
        lineL.Size                 = UDim2.new(0, halfR - 4, 0, 2)
        lineL.Position             = UDim2.new(0.5, 0, 0.5, 0)
        lineL.BackgroundColor3     = COL_RING
        lineL.BackgroundTransparency = 0.15
        lineL.BorderSizePixel      = 0
        lineL.Rotation             = -CONE_HALF_DEG  -- -25 deg (izquierda del 0)
        lineL.ZIndex               = 21

        local lineR = Instance.new("Frame", coneContainer)
        lineR.Name                 = "ConeR"
        lineR.AnchorPoint          = Vector2.new(0, 0.5)
        lineR.Size                 = UDim2.new(0, halfR - 4, 0, 2)
        lineR.Position             = UDim2.new(0.5, 0, 0.5, 0)
        lineR.BackgroundColor3     = COL_RING
        lineR.BackgroundTransparency = 0.15
        lineR.BorderSizePixel      = 0
        lineR.Rotation             = CONE_HALF_DEG   -- +25 deg (derecha del 0)
        lineR.ZIndex               = 21

        -- Punto central (personaje)
        local center = Instance.new("Frame", ring)
        center.Name                = "Center"
        center.AnchorPoint         = Vector2.new(0.5, 0.5)
        center.Size                = UDim2.new(0, 8, 0, 8)
        center.Position            = UDim2.new(0.5, 0, 0.5, 0)
        center.BackgroundColor3    = COL_RING
        center.BackgroundTransparency = 0
        center.BorderSizePixel     = 0
        center.ZIndex              = 23
        Instance.new("UICorner", center).CornerRadius = UDim.new(1,0)

        -- Indicador de target (punto que se mueve con el angulo al target)
        local targetDot = Instance.new("Frame", ring)
        targetDot.Name             = "TargetDot"
        targetDot.AnchorPoint      = Vector2.new(0.5, 0.5)
        targetDot.Size             = UDim2.new(0, 10, 0, 10)
        targetDot.Position         = UDim2.new(0.5, 0, 0, 0)  -- arriba por defecto
        targetDot.BackgroundColor3 = COL_BAD
        targetDot.BackgroundTransparency = 0
        targetDot.BorderSizePixel  = 0
        targetDot.ZIndex           = 24
        Instance.new("UICorner", targetDot).CornerRadius = UDim.new(1,0)

        -- Label de estado debajo del circulo
        local statusLbl = Instance.new("TextLabel", root)
        statusLbl.Name             = "StatusLbl"
        statusLbl.BackgroundTransparency = 1
        statusLbl.AnchorPoint      = Vector2.new(0.5, 0)
        statusLbl.Position         = UDim2.new(0.5, 0, 1, -2)
        statusLbl.Size             = UDim2.new(0, 200, 0, 20)
        statusLbl.Text             = "KNIFE SA - Sin target"
        statusLbl.TextColor3       = COL_BAD
        statusLbl.TextSize         = 11
        statusLbl.Font             = Enum.Font.GothamBold
        statusLbl.ZIndex           = 22

        -- Label "KNIFE SA" arriba
        local titleLbl = Instance.new("TextLabel", root)
        titleLbl.Name             = "TitleLbl"
        titleLbl.BackgroundTransparency = 1
        titleLbl.AnchorPoint      = Vector2.new(0.5, 1)
        titleLbl.Position         = UDim2.new(0.5, 0, 0, -2)
        titleLbl.Size             = UDim2.new(0, 150, 0, 18)
        titleLbl.Text             = "? KNIFE SILENT AIM"
        titleLbl.TextColor3       = COL_RING
        titleLbl.TextSize         = 11
        titleLbl.Font             = Enum.Font.GothamBold
        titleLbl.ZIndex           = 22

        -- Guardar referencias en tabla Lua separada (ScreenGui no admite propiedades custom)
        _ksaRefs = {
            _root          = root,
            _ring          = ring,
            _ringStroke    = ringStroke,
            _lineL         = lineL,
            _lineR         = lineR,
            _targetDot     = targetDot,
            _statusLbl     = statusLbl,
            _titleLbl      = titleLbl,
            _coneContainer = coneContainer,
        }

        return gui
    end

    -- Loop de actualizacion del overlay (~20 Hz)
    local _ksaOverlayConn = nil
    local _ksaLastColor   = nil

    local function _ksaStartLoop(gui)
        local cam = workspace.CurrentCamera
        local rs  = game:GetService("RunService")

        _ksaOverlayConn = rs.Heartbeat:Connect(function()
            if not KnifeSAState.enabled or not gui or not gui.Parent then
                if _ksaOverlayConn then _ksaOverlayConn:Disconnect(); _ksaOverlayConn = nil end
                return
            end
            -- Guard: referencias no disponibles aun (overlay destruido o no creado)
            if not _ksaRefs or not _ksaRefs._root then return end

            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local target = _KnifeSA_getBestTarget and _KnifeSA_getBestTarget()

            if not myHRP then
                _ksaRefs._statusLbl.Text      = "Sin personaje"
                _ksaRefs._statusLbl.TextColor3 = COL_BAD
                return
            end

            -- Posicionar el circulo debajo del personaje en pantalla
            -- Usamos WorldToViewportPoint para convertir la posicion 3D del HRP a 2D
            do
                local _cam = workspace.CurrentCamera
                local _vp  = _cam.ViewportSize
                -- Punto de referencia: los pies del personaje (HRP.Position - Y del HRP)
                -- Para obtener los "pies" bajamos un poco desde el HRP
                -- Pies exactos: HRP esta a ~2.8 studs del suelo en R15
                local _feetPos = myHRP.Position - Vector3.new(0, 2.8, 0)
                local _screenPos, _onScreen = _cam:WorldToViewportPoint(_feetPos)
                if _onScreen then
                    -- Posicion en pixeles directamente (UDim2 con offset en pixeles)
                    _ksaRefs._root.Position = UDim2.new(0, _screenPos.X, 0, _screenPos.Y)
                else
                    -- Personaje fuera de pantalla: ocultar overlay
                    _ksaRefs._root.Position = UDim2.new(2, 0, 2, 0)  -- fuera de pantalla
                end
            end

            if not target or not target.Character then
                -- Sin target
                _ksaRefs._targetDot.Position   = UDim2.new(0.5, 0, 0.5, 0)  -- centro
                _ksaRefs._targetDot.BackgroundColor3 = COL_BAD
                _ksaRefs._ringStroke.Color     = COL_RING
                _ksaRefs._statusLbl.Text       = "Sin target"
                _ksaRefs._statusLbl.TextColor3 = COL_BAD
                return
            end

            local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
            if not tHRP then return end

            -- Calcular angulo horizontal entre mi LookVector y la direccion al target
            local toTarget = (tHRP.Position - myHRP.Position)
            local toTarget2D = Vector3.new(toTarget.X, 0, toTarget.Z)
            local look2D     = Vector3.new(myHRP.CFrame.LookVector.X, 0, myHRP.CFrame.LookVector.Z)

            local dist = toTarget.Magnitude

            -- Angulo (con signo) en el plano horizontal
            local angleRad = 0
            if toTarget2D.Magnitude > 0.01 and look2D.Magnitude > 0.01 then
                local dot   = look2D.Unit:Dot(toTarget2D.Unit)
                dot = math.clamp(dot, -1, 1)
                angleRad = math.acos(dot)
                -- Signo: cross product Y para saber izq/der
                local cross = look2D:Cross(toTarget2D)
                if cross.Y < 0 then angleRad = -angleRad end
            end

            local angleDeg = math.deg(angleRad)

            -- Posicion del punto en el circulo (0 deg = arriba = hacia donde mira el player)
            local halfR2 = (RING_SIZE / 2) - 8
            -- Limitamos el punto a que no salga del anillo
            local clampedAngle = math.clamp(angleRad, -math.pi, math.pi)
            local dotX = halfR2 * math.sin(clampedAngle)
            local dotY = -halfR2 * math.cos(clampedAngle)
            _ksaRefs._targetDot.Position = UDim2.new(0.5, dotX, 0.5, dotY)

            -- Color segun angulo
            local absAngle = math.abs(angleDeg)
            local color, statusText, ringCol

            if absAngle <= CONE_HALF_DEG then
                -- Dentro del cono = VERDE = buena punteria!
                color      = COL_READY
                statusText = string.format("? TIRAR! %.1f? / %.0f studs", absAngle, dist)
                ringCol    = COL_READY
            elseif absAngle <= CONE_HALF_DEG * 2.5 then
                -- Angulo medio = AMARILLO = casi
                color      = COL_WARN
                statusText = string.format("? Casi... %.1f? / %.0f studs", absAngle, dist)
                ringCol    = COL_WARN
            else
                -- Muy desviado = ROJO = no conviene
                color      = COL_BAD
                statusText = string.format("? No tirar %.1f? / %.0f studs", absAngle, dist)
                ringCol    = COL_RING
            end

            _ksaRefs._targetDot.BackgroundColor3 = color
            _ksaRefs._statusLbl.Text             = statusText
            _ksaRefs._statusLbl.TextColor3       = color
            _ksaRefs._ringStroke.Color           = ringCol
            _ksaRefs._lineL.BackgroundColor3     = ringCol
            _ksaRefs._lineR.BackgroundColor3     = ringCol
        end)
    end

    -- Hook en los callbacks de activate/deactivate
    -- Guardamos las funciones originales y las wrapeamos
    local _origActivate   = _KnifeSA_activate
    local _origDeactivate = _KnifeSA_deactivate

    _KnifeSA_activate = function(...)
        _origActivate(...)
        -- Crear overlay si KnifeSA esta habilitado
        task.spawn(function()
            task.wait(0.05)
            if KnifeSAState.enabled or true then  -- siempre crear al activar
                local g = _ksaCreateOverlay()
                if g then _ksaStartLoop(g) end
            end
        end)
    end

    _KnifeSA_deactivate = function(...)
        -- Desconectar loop y destruir overlay
        if _ksaOverlayConn then
            _ksaOverlayConn:Disconnect()
            _ksaOverlayConn = nil
        end
        _ksaDestroyOverlay()
        _origDeactivate(...)
    end

    -- Tambien limpiar si el jugador muere o se desconecta
    LocalPlayer.CharacterRemoving:Connect(function()
        if not KnifeSAState.enabled then
            if _ksaOverlayConn then _ksaOverlayConn:Disconnect(); _ksaOverlayConn = nil end
            _ksaDestroyOverlay()
        end
    end)
end
