_G.KnifeAuraState = { enabled = false, range = 10000, conn = nil }
KnifeAuraTState = _G.KnifeAuraTState
FakeBombState = _G.FakeBombState
KillAllState = _G.KillAllState
KnifeAuraState = _G.KnifeAuraState

FlingSystem = {
    active          = false,
    flingAll        = false,
    flingInnocent   = false,
    flingMurder     = false,
    flingSheriff    = false,
    specificTarget  = nil,
    murderWatchConn = nil,
    _loopThread     = nil,
}

-- ---------------------------------------------------------------
-- SKIDFLING ULTRA ? basado en SkidFling 2026
-- Orbita arriba/abajo del target con velocidad extrema
-- Cada 4 segundos TP de vuelta y repite hasta que muera
-- ---------------------------------------------------------------
_boomerangLastPos   = nil
_flingLastSafePos   = nil
_flingPosTrackConn  = nil

-- FIX: pre-llenar _flingLastSafePos con la posicion actual al cargar el script
-- para que Fling Murder tenga un punto de retorno aunque nunca se haya activado FlingSystem
task.defer(function()
    local lp   = game:GetService("Players").LocalPlayer
    local char = lp and lp.Character or (lp and lp.CharacterAdded:Wait(5))
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        local y = hrp.Position.Y
        if y > 2 and y < 800 then
            _flingLastSafePos = hrp.CFrame
            _G.OldPos  = hrp.CFrame
        end
    end
end)

-- Guarda posici?n segura del jugador en loop mientras flingea
function _startFlingPosTracking()
    if _flingPosTrackConn then pcall(function() _flingPosTrackConn:Disconnect() end) end
    local _fptTick = 0
    _flingPosTrackConn = game:GetService("RunService").Heartbeat:Connect(function()
        _fptTick = _fptTick + 1; if _fptTick < 6 then return end; _fptTick = 0  -- ~10Hz
        -- No guardar mientras hay un fling activo, mientras volvemos, ni si la velocidad es alta
        -- (podriamos estar siendo arrastrados por el fling justo antes de que _flingActive sea true)
        if _flingActive or _flingReturning then return end
        local char = game:GetService("Players").LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local vel = hrp.AssemblyLinearVelocity.Magnitude
        local y   = hrp.Position.Y
        -- FIX: umbral bajado a 20 (era 50) para no guardar posiciones con inercia residual del fling
        if vel < 20 and y > 3 and y < 500 then
            _flingLastSafePos = hrp.CFrame
        end
    end)
end

-- Para el tracker de posicion
function _stopFlingPosTracking()
    if _flingPosTrackConn then
        pcall(function() _flingPosTrackConn:Disconnect() end)
        _flingPosTrackConn = nil
    end
end

-- TP de vuelta a la ultima posicion segura guardada
function _flingReturnToLastPos()
    -- FIX: no ejecutar si _flingDoReturn ya est? corriendo (evita TPs en paralelo)
    if _flingReturning then return end
    local char = game:GetService("Players").LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    -- -- 1. Determinar posicion destino ---------------------------
    local target = _flingLastSafePos or _boomerangLastPos
    if target then
        local ty = target.Position and target.Position.Y or 0
        if ty < -10 or ty > 1000 then
            local sp = workspace:FindFirstChildOfClass("SpawnLocation")
            target = sp and CFrame.new(sp.Position + Vector3.new(0, 5, 0)) or CFrame.new(0, 10, 0)
        end
    end

    -- -- 2. Limpiar estado fisico ANTES del TP --------------------
    -- Zerear todas las velocidades para que no haya arrastre residual
    pcall(function()
        hrp.AssemblyLinearVelocity  = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        -- API vieja (por si el executor la expone)
        hrp.Velocity    = Vector3.zero
        hrp.RotVelocity = Vector3.zero
    end)

    -- Restaurar CanCollide en todas las partes del personaje
    pcall(function()
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = true
            end
        end
    end)

    -- -- 3. Restaurar Humanoid -------------------------------------
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum and hum.Parent then
        -- PlatformStand = false es critico: si queda true el personaje
        -- flota sin gravedad y no puede moverse
        pcall(function() hum.PlatformStand = false end)
        -- Esperar un frame para que el motor fisico aplique PlatformStand=false
        -- antes de modificar WalkSpeed / JumpPower
        task.wait()
        pcall(function()
            if hum.WalkSpeed  < 8  then hum.WalkSpeed  = 16 end
            if hum.JumpPower  < 1  then hum.JumpPower  = 50 end
        end)
    end

    -- -- 4. Teleportar ---------------------------------------------
    if target then
        pcall(function()
            hrp.CFrame = target
            -- Zerear de nuevo post-TP para anular cualquier impulso del servidor
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    -- -- 5. Segundo pass: un frame despues, confirmar estado -------
    -- Algunos ejecutores necesitan un frame extra para que PlatformStand
    -- se propague al servidor y la gravedad vuelva a aplicarse
    task.spawn(function()
        task.wait(0.1)
        local c2   = LocalPlayer.Character
        local hrp2 = c2 and c2:FindFirstChild("HumanoidRootPart")
        local hum2 = c2 and c2:FindFirstChildOfClass("Humanoid")
        if not hrp2 or not hum2 then return end
        pcall(function()
            if hum2.PlatformStand then hum2.PlatformStand = false end
            if hum2.WalkSpeed < 8  then hum2.WalkSpeed = 16 end
            if hum2.JumpPower < 1  then hum2.JumpPower = 50 end
            hrp2.AssemblyLinearVelocity  = Vector3.zero
            hrp2.AssemblyAngularVelocity = Vector3.zero
        end)
        -- Restaurar CanCollide de nuevo por si el noclipConn tardo en desconectarse
        pcall(function()
            for _, part in ipairs(c2:GetDescendants()) do
                if part:IsA("BasePart") then part.CanCollide = true end
            end
        end)
    end)
end



-- MONITOREO CONSTANTE: Detectar cuando el sheriff muere
_sheriffDeathCheckConn = nil

function StartSheriffDeathMonitor()
    if _sheriffDeathCheckConn then _sheriffDeathCheckConn:Disconnect() end

    -- FIX CHAM AZUL: monitorear a CUALQUIER sheriff conocido, no solo al de StealGunSystem.
    -- Funciona aunque el usuario nunca haya activado Steal Gun.
    local _shdcTick = 0
    _sheriffDeathCheckConn = RunService.Heartbeat:Connect(function(dt)
        -- FIX LAG: throttle a ~10Hz -- la muerte del sheriff no necesita deteccion frame-perfect
        _shdcTick = _shdcTick + dt
        if _shdcTick < 0.1 then return end
        _shdcTick = 0
        if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda

        _G._deadSheriffIds = _G._deadSheriffIds or {}

        -- Candidatos a monitorear: _roleCache.sheriff + StealGunSystem.sheriffOriginalFound
        local candidates = {}
        if _roleCache and _roleCache.sheriff then
            candidates[#candidates+1] = _roleCache.sheriff
        end
        if StealGunSystem and StealGunSystem.sheriffOriginalFound then
            local s = StealGunSystem.sheriffOriginalFound
            -- evitar duplicar
            local already = false
            for _, c in ipairs(candidates) do if c == s then already = true; break end end
            if not already then candidates[#candidates+1] = s end
        end

        for _, sheriff in ipairs(candidates) do
            if not sheriff or not sheriff.Character then continue end
            local hum = sheriff.Character:FindFirstChildOfClass("Humanoid")
            if not (hum and hum.Health <= 0) then continue end

            local uid = sheriff.UserId
            -- Ya registrado -- skip
            if _G._deadSheriffIds[uid] then continue end

            -- SHERIFF MUERTO DETECTADO -- registrar inmediatamente
            _G._deadSheriffIds[uid] = true
            SheriffDeadBlock.isDeadSheriffID = uid
            SheriffDeadBlock.deadSheriffName = sheriff.Name

            -- Limpiar del roleCache para que no se vuelva a pintar azul
            if _roleCache.sheriff and _roleCache.sheriff.UserId == uid then
                _roleCache.sheriff = nil
            end

            -- Forzar cham/highlight verde inmediato
            local dChar = sheriff.Character
            if dChar then
                -- Destruir PieceChams azules
                local toDestroy = {}
                for _, desc in pairs(dChar:GetDescendants()) do
                    if desc:IsA("BoxHandleAdornment") and desc.Name == "PieceCham" then
                        toDestroy[#toDestroy+1] = desc
                    end
                end
                for _, desc in ipairs(toDestroy) do pcall(function() desc:Destroy() end) end
                -- Destruir Highlight azul
                local oldHL = dChar:FindFirstChild("BYPAS_HL")
                if oldHL then pcall(function() oldHL:Destroy() end) end
                -- Aplicar Highlight verde
                pcall(function()
                    local hl = Instance.new("Highlight")
                    hl.Name                = "BYPAS_HL"
                    hl.FillColor           = (_G._vsColors and _G._vsColors.cham) or Color3.fromRGB(90, 90, 95)
                    hl.FillTransparency    = 0.2
                    hl.OutlineColor        = (_G._vsColors and _G._vsColors.cham) or Color3.fromRGB(90, 90, 95)
                    hl.OutlineTransparency = 0
                    hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                    hl.Adornee             = dChar
                    hl.Parent              = dChar
                end)
            end

            -- Propagar a StealGunSystem si corresponde
            if StealGunSystem and StealGunSystem.sheriffOriginalFound
               and StealGunSystem.sheriffOriginalFound.UserId == uid then
                StealGunSystem.sheriffDeadDetected = true
                -- DESACTIVAR TODOS LOS FLINGS
                FlingSystem.flingMurder   = false
                FlingSystem.flingSheriff  = false
                FlingSystem.flingInnocent = false
                FlingSystem.flingAll      = false
                FlingSystem.specificTarget = nil
                pcall(function() task.cancel(FlingSystem._loopThread) end)
                CreateCustomNotification(" SHERIFF MUERTO", "Fling bloqueado - Sheriff detectado muerto", 3)
            end
        end
    end)
end



-- ===============================================================
-- FLING v3 -- mismo metodo que FlingOrbit (World tab) que SI funciona:
-- Tu propio HRP orbita al target con velocidad angular extrema.
-- El servidor acepta la fisica de tu propio character (NetworkOwner = tu).
-- ===============================================================
local _flingConn = nil  -- conexion PostSimulation del fling activo
local _flingActive = false
local _flingReturning = false  -- FIX: true mientras se hace el TP de vuelta, para no contaminar _flingLastSafePos

-- Helper: TP de vuelta a la ultima posicion segura. Se llama desde TODOS los exit paths de _doStealFling.
local function _flingDoReturn(Character, RootPart, Humanoid)
    if not Character or not RootPart or not RootPart.Parent then return end
    -- FIX: bloquear inmediatamente para que FlingSystem loop no llame _flingReturnToLastPos en paralelo
    if _flingReturning then return end
    -- FIX MUERTE SHERIFF: si el personaje local murio, no hacer TP de retorno
    -- (el servidor ya va a respawnear; el TP causaria el bug de aparecer en la ultima pos del fling)
    if Humanoid and Humanoid.Health <= 0 then return end
    _flingReturning = true
    local OldPos = _G.OldPos
    -- FIX: validar posicion de retorno; si invalida usar _flingLastSafePos como fallback
    local returnCFrame = nil
    if OldPos then
        local oy = (OldPos.Position and OldPos.Position.Y) or 0
        if oy > 2 and oy < 800 then
            returnCFrame = OldPos * CFrame.new(0, 0.5, 0)
        end
    end
    if not returnCFrame and _flingLastSafePos then
        local sy = (_flingLastSafePos.Position and _flingLastSafePos.Position.Y) or 0
        if sy > 2 and sy < 800 then
            returnCFrame = _flingLastSafePos * CFrame.new(0, 0.5, 0)
        end
    end
    if returnCFrame then
        -- FIX: zerear velocidad en GetDescendants (no solo GetChildren) ? 3 passes
        for _pass = 1, 3 do
            pcall(function()
                for _, x in ipairs(Character:GetDescendants()) do
                    if x:IsA("BasePart") then
                        x.Velocity                = Vector3.zero
                        x.RotVelocity             = Vector3.zero
                        x.AssemblyLinearVelocity  = Vector3.zero
                        x.AssemblyAngularVelocity = Vector3.zero
                    end
                end
            end)
        end
        -- FIX: restaurar estado del Humanoid ANTES del TP
        if Humanoid and Humanoid.Parent then
            pcall(function() Humanoid.PlatformStand = false end)
            pcall(function() Humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true) end)
        end
        -- TP
        pcall(function()
            RootPart.CFrame = returnCFrame
            Character:SetPrimaryPartCFrame(returnCFrame)
            if Humanoid and Humanoid.Parent then
                Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end)
        -- FIX: 2 frames de espera + double-zereo para cancelar inercia residual del servidor
        task.wait(0.016)
        pcall(function()
            if RootPart.Parent then
                for _, x in ipairs(Character:GetDescendants()) do
                    if x:IsA("BasePart") then
                        x.Velocity                = Vector3.zero
                        x.RotVelocity             = Vector3.zero
                        x.AssemblyLinearVelocity  = Vector3.zero
                        x.AssemblyAngularVelocity = Vector3.zero
                    end
                end
            end
        end)
        task.wait(0.016)
        pcall(function()
            if RootPart.Parent then
                RootPart.AssemblyLinearVelocity  = Vector3.zero
                RootPart.AssemblyAngularVelocity = Vector3.zero
            end
        end)
        -- FIX: actualizar OldPos y _flingLastSafePos al punto de retorno para evitar loops
        _G.OldPos = returnCFrame
        _flingLastSafePos = returnCFrame
    end
    task.wait(0.1)
    _flingReturning = false
end

function _doStealFling(targetHRP, skipReturn)
    if not targetHRP or not targetHRP.Parent then return end
    local TargetPlayer = game:GetService("Players"):GetPlayerFromCharacter(targetHRP.Parent)
    if not TargetPlayer then return end
    if _flingActive then return end
    _flingActive = true

    local Character = LocalPlayer.Character
    local Humanoid  = Character and Character:FindFirstChildOfClass("Humanoid")
    local RootPart  = Humanoid and Humanoid.RootPart
    if not Character or not Humanoid or not RootPart then _flingActive = false; return end

    local TCharacter = TargetPlayer.Character
    local THumanoid  = TCharacter and TCharacter:FindFirstChildOfClass("Humanoid")
    local TRootPart  = THumanoid and THumanoid.RootPart
    local THead      = TCharacter and TCharacter:FindFirstChild("Head")
    local Accessory  = TCharacter and TCharacter:FindFirstChildOfClass("Accessory")
    local Handle     = Accessory and Accessory:FindFirstChild("Handle")

    -- FIX TP: guardar posicion segura SIEMPRE al inicio, con triple validacion
    -- Prioridad: _flingLastSafePos guardado por tracker > posicion actual valida
    local function _captureSafePos()
        -- Intentar con _flingLastSafePos primero (mas fiable, es cuando estabamos quietos)
        if _flingLastSafePos then
            local sy = _flingLastSafePos.Position.Y
            if sy > 3 and sy < 800 then
                _G.OldPos = _flingLastSafePos
                return
            end
        end
        -- Fallback: posicion actual del RootPart si es valida
        local ry = RootPart.Position.Y
        if ry > 2 and ry < 800 then
            local safeNow = RootPart.CFrame
            _G.OldPos  = safeNow
            _flingLastSafePos = safeNow
        end
    end
    _captureSafePos()

    -- Asegurar que el tracker de posicion este corriendo (para futuros flings)
    if not _flingPosTrackConn and _startFlingPosTracking then
        _startFlingPosTracking()
    end

    if THumanoid and THumanoid.Sit then
        _flingActive = false
        if not skipReturn then _flingDoReturn(Character, RootPart, Humanoid) end
        CreateCustomNotification("FLING", "Target is sitting", 3)
        return
    end

    -- Camara al target
    pcall(function()
        if THead then
            workspace.CurrentCamera.CameraSubject = THead
        elseif Handle then
            workspace.CurrentCamera.CameraSubject = Handle
        else
            workspace.CurrentCamera.CameraSubject = THumanoid
        end
    end)

    if not TCharacter or not TCharacter:FindFirstChildWhichIsA("BasePart") then
        _flingActive = false
        if not skipReturn then _flingDoReturn(Character, RootPart, Humanoid) end
        return
    end

    -- -------------------------------------------------------
    -- ATOMIC GHOST FLING v5
    -- TP al target + velocidad + return a safePos TODO dentro
    -- de un SOLO pcall sin yields entre medio.
    -- El servidor solo ve la posicion final (safePos), nunca
    -- la posicion intermedia dentro del sheriff.
    -- safePos se actualiza cada frame para estar siempre fresh.
    -- -------------------------------------------------------
    local _RS = game:GetService("RunService")
    local _targetLaunched = false
    local _stickyConn

    -- safePos se renueva cada frame ANTES del TP, usando la
    -- posicion actual del jugador (que no cambio, porque aun
    -- no hicimos el TP de colision).
    local _safePos = RootPart.CFrame
    local _stickyTimeout = tick() + 8

    _stickyConn = _RS.Heartbeat:Connect(function()
        if not TRootPart or not TRootPart.Parent then
            _targetLaunched = true
            if _stickyConn then _stickyConn:Disconnect(); _stickyConn = nil end
            return
        end
        if TRootPart.AssemblyLinearVelocity.Magnitude > 120 then
            _targetLaunched = true
            if _stickyConn then _stickyConn:Disconnect(); _stickyConn = nil end
            return
        end
        if tick() > _stickyTimeout then
            _targetLaunched = true
            if _stickyConn then _stickyConn:Disconnect(); _stickyConn = nil end
            return
        end

        -- Capturar safePos AHORA (jugador todavia no se movio este frame)
        local _curPos = RootPart.CFrame
        local _curY   = _curPos.Position.Y
        if _curY > 2 and _curY < 800 then
            _safePos = _curPos
        end

        -- TODO en un solo pcall sin yields: TP -> velocidad -> return
        -- Al ser instrucciones consecutivas en Lua, el engine las agrupa
        -- en el mismo paso de fisica y el servidor recibe solo _safePos.
        pcall(function()
            -- 1) TP al target para registrar colision
            RootPart.CFrame = TRootPart.CFrame
            -- 2) Velocidad extrema al target
            TRootPart.AssemblyLinearVelocity  = Vector3.new(0, 50000, 0)
            TRootPart.AssemblyAngularVelocity = Vector3.new(50000, 50000, 50000)
            -- 3) Volver INMEDIATAMENTE a safePos ? misma instruccion, mismo frame
            RootPart.CFrame                   = _safePos
            RootPart.AssemblyLinearVelocity   = Vector3.zero
            RootPart.AssemblyAngularVelocity  = Vector3.zero
        end)
    end)

    local _waitLimit = 0
    repeat
        task.wait(0.016)
        _waitLimit = _waitLimit + 0.05
    until _targetLaunched or _waitLimit > 9

    if _stickyConn then _stickyConn:Disconnect(); _stickyConn = nil end

    pcall(function()
        RootPart.CFrame                  = _safePos
        RootPart.AssemblyLinearVelocity  = Vector3.zero
        RootPart.AssemblyAngularVelocity = Vector3.zero
    end)
    pcall(function() workspace.CurrentCamera.CameraSubject = Humanoid end)

    _flingActive = false
    if not skipReturn then _flingDoReturn(Character, RootPart, Humanoid) end
end

-- Wrapper compatible con el loop (_doFling recibe myHRP, targetHRP)
function _doFling(myHRP, targetHRP)
    _doStealFling(targetHRP)
end

-- _doGodFling redirige al steal-method fling
-- onDone se llama con true si el target fue expulsado
function _doGodFling(myHRP, targetHRP, onDone)
    if not targetHRP or not targetHRP.Parent then
        if onDone then onDone(false) end; return
    end
    _doStealFling(targetHRP)
    -- Dar un tick para que el servidor registre el movimiento
    task.delay(0.25, function()
        local ok = (not targetHRP.Parent)
                or targetHRP.Position.Y < -100
                or targetHRP.AssemblyLinearVelocity.Magnitude > 60
        if onDone then onDone(ok) end
    end)
end

-- Detecta el sheriff de manera mas robusta: role cache + busqueda por Gun en mochila/personaje
function _findSheriffRobust()
    _refreshRoleCache()
    -- Prioridad 1a: cache sheriff vivo
    local s = _roleCache and _roleCache.sheriff
    if s and s.Character then
        local h = s.Character:FindFirstChild("HumanoidRootPart")
        local u = s.Character:FindFirstChildOfClass("Humanoid")
        if h and u and u.Health > 0 then return h end
    end
    -- Prioridad 1b: cache hero vivo (quien levanto la gun del sheriff muerto = Hero)
    local hero = _roleCache and _roleCache.hero
    if hero and hero.Character then
        local h = hero.Character:FindFirstChild("HumanoidRootPart")
        local u = hero.Character:FindFirstChildOfClass("Humanoid")
        if h and u and u.Health > 0 then return h end
    end
    -- Prioridad 2: escaneo por posesion de Gun (fallback cuando el cache falla)
    -- Solo busca jugadores VIVOS -- excluye al sheriff original muerto por UserId
    local deadID = SheriffDeadBlock and SheriffDeadBlock.isDeadSheriffID
    for _, p in ipairs(_cachedPlayers) do
        if p ~= LocalPlayer and p.Character then
            -- Ignorar al sheriff muerto aunque su cadaver siga en escena
            if deadID and p.UserId == deadID then continue end
            local hasGun = _findGunIn(p.Backpack)
                        or _findGunIn(p.Character)
            if hasGun then
                local h = p.Character:FindFirstChild("HumanoidRootPart")
                local u = p.Character:FindFirstChildOfClass("Humanoid")
                if h and u and u.Health > 0 then return h end
            end
        end
    end
    return nil
end

function _flingGetTarget()
    _refreshRoleCache()
    
    -- BLOQUEO: NO FLINGEAR AL SHERIFF MUERTO (por sheriffDeadDetected)
    local deadSheriffID = nil
    if StealGunSystem and StealGunSystem.sheriffDeadDetected and StealGunSystem.sheriffOriginalFound then
        local sheriff = StealGunSystem.sheriffOriginalFound
        if sheriff and sheriff.Character then
            local hum = sheriff.Character:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health <= 0 then
                deadSheriffID = sheriff.UserId
            end
        end
        -- FIX SHERIFF VIEJO: aunque el viejo sheriff no este muerto todavia,
        -- si ya NO esta en _roleCache como sheriff esta ronda -> bloquearlo igual.
        -- Esto cubre el caso donde entre rondas el viejo sheriff tiene la gun
        -- pero _roleCache.sheriff ya es otro jugador (el nuevo sheriff).
        if StealGunSystem.sheriffOriginalFound
            and _roleCache.sheriff
            and StealGunSystem.sheriffOriginalFound ~= _roleCache.sheriff then
            deadSheriffID = deadSheriffID or StealGunSystem.sheriffOriginalFound.UserId
        end
    end

    -- FIX SHERIFF VIEJO (segunda capa): bloquear cualquier jugador muerto
    -- que alguna vez fue sheriff aunque sheriffDeadDetected no este activo.
    -- Cubre rondas donde DisableStealGun no limpio bien el estado.
    local _currentSheriff = _roleCache and _roleCache.sheriff
    
    -- Funcion auxiliar para verificar si puede ser flingleado
    local function CanBeFlingleado(player)
        if not player or not player.Character then return false end
        local hum = player.Character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false end
        if deadSheriffID and player.UserId == deadSheriffID then return false end
        -- FIX SHERIFF VIEJO: si el player es el sheriff viejo (no en _roleCache esta ronda)
        -- Y StealGunSystem lo tiene como sheriffOriginalFound -> bloquearlo
        if StealGunSystem and StealGunSystem.sheriffOriginalFound
            and StealGunSystem.sheriffOriginalFound == player
            and _currentSheriff and _currentSheriff ~= player then
            return false
        end
        return true
    end
    
    if FlingSystem.flingMurder then
        local m = _roleCache.murderer
        if m and CanBeFlingleado(m) then
            local h = m.Character:FindFirstChild("HumanoidRootPart")
            if h then return h end
        end
    end
    if FlingSystem.flingSheriff then
        local h = _findSheriffRobust()
        if h then
            local char = h.Parent
            local p = Players:GetPlayerFromCharacter(char)
            if p and CanBeFlingleado(p) then return h end
        end
    end
    if FlingSystem.flingInnocent then
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer and p ~= _roleCache.murderer and p ~= _roleCache.sheriff then
                if CanBeFlingleado(p) then
                    local h = p.Character:FindFirstChild("HumanoidRootPart")
                    if h then return h end
                end
            end
        end
    end
    if FlingSystem.flingAll then
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer and CanBeFlingleado(p) then
                local h = p.Character:FindFirstChild("HumanoidRootPart")
                if h then return h end
            end
        end
    end
    if FlingSystem.specificTarget then
        local p = Players:FindFirstChild(FlingSystem.specificTarget)
        if p and CanBeFlingleado(p) then
            local h = p.Character:FindFirstChild("HumanoidRootPart")
            if h then return h end
        end
    end
    return nil
end



function _anyFlingActive()
    return FlingSystem.flingAll or FlingSystem.flingMurder
        or FlingSystem.flingInnocent or FlingSystem.flingSheriff
        or (FlingSystem.specificTarget ~= nil)
end

function StopFlingSystem()
    FlingSystem.active = false
    _G._flingBusyFlag = false  -- liberar el guard de SmartFling si fue cancelado
    if FlingSystem._loopThread then
        pcall(function() task.cancel(FlingSystem._loopThread) end)
        FlingSystem._loopThread = nil
    end
    if FlingSystem.murderWatchConn then
        pcall(function() FlingSystem.murderWatchConn:Disconnect() end)
        FlingSystem.murderWatchConn = nil
    end
end

function StartFlingSystem()
    if FlingSystem.active and FlingSystem._loopThread then
        local st = coroutine.status(FlingSystem._loopThread)
        if st == "dead" then FlingSystem.active = false; FlingSystem._loopThread = nil end
    end
    if FlingSystem.active then return end
    FlingSystem.active = true
    if FlingSystem._loopThread then
        pcall(function() task.cancel(FlingSystem._loopThread) end)
        FlingSystem._loopThread = nil
    end
    if _startFlingPosTracking then _startFlingPosTracking() end
    local _selfDeathConn
    local _selfHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if _selfHum then
        _selfDeathConn = _selfHum.Died:Connect(function()
            pcall(function() if _selfDeathConn then _selfDeathConn:Disconnect() end end)
            FlingSystem.flingMurder=false; FlingSystem.flingSheriff=false
            FlingSystem.flingInnocent=false; FlingSystem.flingAll=false
            FlingSystem.specificTarget=nil
            StopFlingSystem()
            task.spawn(function() task.wait(0.5); if _flingReturnToLastPos and not _flingReturning then _flingReturnToLastPos() end end)
        end)
    end
    FlingSystem._loopThread = task.spawn(function()
        local _RS = game:GetService("RunService")

        -- +----------------------------------------------------------+
        -- ?  Helper: Sticky Force Fling para un target individual    ?
        -- ?  Nos pegamos al target, inyectamos 50000 de velocidad    ?
        -- ?  hasta detectar que sali? volando (vel > 120).           ?
        -- ?  Retorna true si el target fue lanzado.                  ?
        -- +----------------------------------------------------------+
        local function _stickyFlingOne(myChar, myHRP, myHum, tHRP)
            if not tHRP or not tHRP.Parent then return false end
            local launched = false
            local conn
            pcall(function() myHum.PlatformStand = true end)
            local timeout = tick() + 3

            -- Helper: zerear velocidad propia INMEDIATAMENTE (3 passes para anular inercia)
            local function _zeroSelf()
                for _p = 1, 3 do
                    pcall(function()
                        myHRP.AssemblyLinearVelocity  = Vector3.zero
                        myHRP.AssemblyAngularVelocity = Vector3.zero
                        myHRP.Velocity    = Vector3.zero
                        myHRP.RotVelocity = Vector3.zero
                    end)
                end
            end

            conn = _RS.Heartbeat:Connect(function()
                if not tHRP.Parent then
                    launched = true
                    _zeroSelf()  -- FIX: zerear inmediatamente al perder al target
                    if conn then conn:Disconnect(); conn = nil end
                    return
                end
                local tVel = tHRP.AssemblyLinearVelocity.Magnitude
                if tVel > 120 or tick() > timeout then
                    launched = true
                    -- FIX: zerear ANTES de desconectar para no recibir un frame
                    -- mas de velocidad despues del disconnect
                    _zeroSelf()
                    pcall(function()
                        myHum.PlatformStand = false
                    end)
                    if conn then conn:Disconnect(); conn = nil end
                    return
                end
                pcall(function()
                    myHRP.CFrame = tHRP.CFrame
                    myChar:SetPrimaryPartCFrame(tHRP.CFrame)
                end)
                pcall(function()
                    myHRP.AssemblyLinearVelocity  = Vector3.new(0, 50000, 0)
                    myHRP.AssemblyAngularVelocity = Vector3.new(50000, 50000, 50000)
                end)
            end)
            local w = 0
            repeat task.wait(0.016); w = w + 0.05 until launched or w > 4
            if conn then conn:Disconnect(); conn = nil end
            -- FIX: triple zereo post-loop por si quedo inercia de un frame tardio
            pcall(function()
                myHRP.AssemblyLinearVelocity  = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
                myHRP.Velocity    = Vector3.zero
                myHRP.RotVelocity = Vector3.zero
                myHum.PlatformStand = false
            end)
            task.wait(0.016)
            pcall(function()
                myHRP.AssemblyLinearVelocity  = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
            end)
            return launched
        end

        while _anyFlingActive() do
            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myHRP or not myHum or myHum.Health <= 0 then task.wait(0.1); continue end

            -- FIX ANTI-SALIDA: si el jugador est? muy alto o muy bajo, o con velocidad alta,
            -- el fling lo est? arrastrando. Zerear y TP de emergencia inmediato.
            local myY = myHRP.Position.Y
            if myHRP.AssemblyLinearVelocity.Magnitude > 80 or myY < -30 or myY > 900 then
                -- Zerear en 3 passes antes de siquiera esperar
                for _pz = 1, 3 do
                    pcall(function()
                        myHRP.AssemblyLinearVelocity  = Vector3.zero
                        myHRP.AssemblyAngularVelocity = Vector3.zero
                        myHRP.Velocity    = Vector3.zero
                        myHRP.RotVelocity = Vector3.zero
                    end)
                end
                pcall(function() myHum.PlatformStand = false end)
                if _flingReturnToLastPos and not _flingReturning then _flingReturnToLastPos() end
                task.wait(0.2); continue
            end

            if FlingSystem.flingAll then
                -- ---------------------------------------------------
                -- FLING TODOS: iterar cada jugador con Sticky Force
                -- Al terminar todos, TP a la ultima posicion segura
                -- ---------------------------------------------------
                local targets = {}
                for _, p in ipairs(_cachedPlayers) do
                    if p ~= LocalPlayer and p.Character then
                        local h = p.Character:FindFirstChild("HumanoidRootPart")
                        local hum = p.Character:FindFirstChildOfClass("Humanoid")
                        if h and hum and hum.Health > 0 then
                            table.insert(targets, h)
                        end
                    end
                end

                if #targets > 0 then
                    for _, tHRP in ipairs(targets) do
                        if not FlingSystem.flingAll then break end
                        -- Verificar que el jugador local siga vivo
                        local mc = LocalPlayer.Character
                        local mh = mc and mc:FindFirstChild("HumanoidRootPart")
                        local mu = mc and mc:FindFirstChildOfClass("Humanoid")
                        if not mh or not mu or mu.Health <= 0 then break end
                        _stickyFlingOne(mc, mh, mu, tHRP)
                        task.wait(0.3)  -- pausa entre targets
                    end
                    -- TP de retorno al terminar la ronda de flings
                    local mc2 = LocalPlayer.Character
                    local mh2 = mc2 and mc2:FindFirstChild("HumanoidRootPart")
                    local mu2 = mc2 and mc2:FindFirstChildOfClass("Humanoid")
                    if mc2 and mh2 and mu2 and mu2.Health > 0 then
                        _flingDoReturn(mc2, mh2, mu2)
                    end
                    task.wait(0.5)
                else
                    task.wait(0.3)
                end
            else
                -- Modo normal (flingMurder, flingSheriff, etc.) ? Sticky Force individual
                local tHRP = _flingGetTarget()
                if tHRP then
                    local mc = LocalPlayer.Character
                    local mh = mc and mc:FindFirstChild("HumanoidRootPart")
                    local mu = mc and mc:FindFirstChildOfClass("Humanoid")
                    if mc and mh and mu then
                        _stickyFlingOne(mc, mh, mu, tHRP)
                    end
                    task.wait(0.15)
                else
                    task.wait(0.1)
                end
            end

            if not _anyFlingActive() then break end
        end
        FlingSystem.active = false
        FlingSystem._loopThread = nil
        if _selfDeathConn then pcall(function() _selfDeathConn:Disconnect() end) end
        if _stopFlingPosTracking then _stopFlingPosTracking() end
    end)
end
_flingStartLoop = _flingStartLoop or function()
    if not FlingSystem.active then task.spawn(StartFlingSystem) end
end
_flingStopLoop = _flingStopLoop or function()
    StopFlingSystem()
end



-- Verificacion de si el target esta vivo
function IsTargetAlive(target)
    return CanFlingTarget(target)
end

-- Obtener target actual para fling
function GetCurrentFlingTarget()
    if FlingSystem.specificTarget then
        return Players:FindFirstChild(FlingSystem.specificTarget)
    end
    
    -- Si no hay target especifico, buscar por tipo de fling
    if FlingSystem.flingMurder then
        for _, p in pairs(_cachedPlayers) do
            if p ~= LocalPlayer and IsTargetAlive(p) then
                -- Verificar que no sea el sheriff muerto
                if p.Character and p.Character:FindFirstChildOfClass("Humanoid") then
                    if _findGun(p.Character) then
                        -- Es el sheriff con gun - verificar si esta vivo
                        if IsTargetAlive(p) then
                            return p
                        end
                    else
                        -- No tiene gun, es un inocente o el sheriff muerto
                        return p
                    end
                end
            end
        end
    elseif FlingSystem.flingSheriff then
        -- Buscar sheriff vivo
        for _, p in pairs(_cachedPlayers) do
            if p ~= LocalPlayer and IsTargetAlive(p) then
                if p.Character and (_findGun(p.Character)) then
                    return p
                end
            end
        end
    elseif FlingSystem.flingInnocent then
        -- Buscar inocente vivo (sin gun)
        for _, p in pairs(_cachedPlayers) do
            if p ~= LocalPlayer and IsTargetAlive(p) then
                if p.Character and not _findGunIn(p.Character) and not _findGunIn(p.Backpack) then
                    return p
                end
            end
        end
    end
    
    return nil
end



function _flingStartLoop()
    if FlingSystem.active and FlingSystem._loopThread then
        local st = coroutine.status(FlingSystem._loopThread)
        if st == "dead" then FlingSystem.active = false; FlingSystem._loopThread = nil end
    end
    if not FlingSystem.active then task.spawn(StartFlingSystem) end
end
function _flingStopLoop()
    StopFlingSystem()
end


function convertirFuenteCursor(texto)
    local s = tostring(texto)
    s = s:gsub("[\240][\159][\128-\191][\128-\191]", "")  -- 4-byte UTF-8 emojis
    s = s:gsub("[\226][\128-\191][\128-\191]", "")         -- 3-byte symbols (arrows, etc)
    s = s:gsub("[\239][\184-\191][\128-\191]", "")         -- variation selectors
    s = s:gsub("[%z\1-\8\11\12\14-\31\127-\159]", "")
    s = s:gsub(" +", " "):gsub("^ ", ""):gsub(" $", "")
    return s
end

