function GetPlayerRole(player)
    if not player then return "Innocent" end
    _refreshRoleCache()

    -- Fuente 1: cache del servidor (RoundStart / polling)
    -- FIX: revisar cache ANTES de chequear Health para que el murder/sheriff/hero
    -- nunca aparezca como "Dead" por un frame de lag o transicion de ronda.
    if player == Players.LocalPlayer then
        local r = _roleCache.localRole
        if r and r ~= "" then return r end
    end
    if _roleCache.murderer and _roleCache.murderer == player then return "Murderer" end
    if _roleCache.sheriff  and _roleCache.sheriff  == player then return "Sheriff"  end
    if _roleCache.hero     and _roleCache.hero     == player then return "Hero"     end
    if _roleCache.assassin and _roleCache.assassin == player then return "Assassin" end
    if _roleCache.zombie   and _roleCache.zombie   == player then return "Zombie"   end
    if _roleCache.survivor and _roleCache.survivor == player then return "Survivor" end

    -- Solo marcar Dead si no tiene rol conocido Y realmente esta muerto
    if player.Character then
        local hum = player.Character:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health <= 0 then return "Dead" end
        local hrp = player.Character:FindFirstChild("HumanoidRootPart")
        if hrp and not hrp.Parent then return "Dead" end
    end

    -- Fuente 2 removida: NO detectar Murderer por knife.
    -- La deteccion por knife causaba repintado inconsistente:
    -- a veces el knife aparece en el Character ANTES del evento RoundStart
    -- del servidor, otras veces despues -> _roleCache.murderer se llenaba
    -- en momentos distintos cada ronda -> retraso de ~10 segundos en el color.
    -- El rol del Murder SOLO viene de _roleCache (evento RoundStart del servidor).

    return "Innocent"
end

function GetRoleColor(role)
    if role == "Murderer"  then return Color3.fromRGB(255,   0,  40)  end  -- Rojo
    if role == "Sheriff"   then return Color3.fromRGB(  0, 140, 255) end  -- Azul (dodger blue)
    if role == "Hero"      then return Color3.fromRGB(255, 210,   0)   end  -- Dorado
    if role == "Dead"      then return Color3.fromRGB(120, 120, 120) end  -- Gris
    if role == "Grey"      then return Color3.fromRGB(190, 190, 210) end  -- Gris claro
    if role == "GunHolder" then return Color3.fromRGB(255, 210,   0)   end  -- Dorado/Amarillo
    if role == "Assassin"  then return Color3.fromRGB(255, 210,   0)  end  -- Dorado-naranja
    if role == "Zombie"    then return Color3.fromRGB( 40, 255,  40)  end  -- Verde zombie
    if role == "Survivor"  then return Color3.fromRGB(255, 255, 255) end  -- Blanco
    if role == "Innocent"  then return Color3.fromRGB(  0, 255, 160) end  -- Morado
    return Color3.fromRGB(200, 200, 200)
end

function GetCoins()
    local coins = {}
    if _farmCoinSet and next(_farmCoinSet) then
        for coin in pairs(_farmCoinSet) do
            if coin and coin.Parent then
                table.insert(coins, coin)
            end
        end
        return coins
    end
    -- Deteccion directa via RS.Coins.CoinObjects.Coin
    local ok, coinFolder = pcall(function()
        return game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
    end)
    if ok and coinFolder then
        for _, obj in ipairs(coinFolder:GetChildren()) do
            if obj:IsA("BasePart") or obj:IsA("MeshPart") then
                table.insert(coins, obj)
            end
        end
        if #coins > 0 then return coins end
    end
    -- Fallback: buscar en workspace
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("BasePart") or obj:IsA("MeshPart") then
            local name = obj.Name:lower()
            if name == "coin_server" or name:find("coin") or name:find("snowtoken") or name:find("snowflake") or name:find("token") then
                table.insert(coins, obj)
            end
        end
    end
    return coins
end

function GetAllCoins()
    return GetCoins()
end

function EnableNoclip()
    if Settings.connections.noclip then
        Settings.connections.noclip:Disconnect()
        Settings.connections.noclip = nil
    end
    -- FIX LAG: cachear BaseParts al activar -- GetDescendants cada Stepped (~60Hz) causaba lag
    local _noclipParts = {}
    local _noclipChar  = nil
    local function _rebuildCache(char)
        _noclipParts = {}
        _noclipChar  = char
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") then _noclipParts[#_noclipParts+1] = p end
        end
    end
    local _charConn = LocalPlayer.CharacterAdded:Connect(function(c)
        task.wait(0.1)
        _rebuildCache(c)
    end)
    _rebuildCache(LocalPlayer.Character)
    Settings.connections.noclip = RunService.Stepped:Connect(function()
        local char = LocalPlayer.Character
        if not char then return end
        -- Reconstruir cache si el personaje cambio
        if char ~= _noclipChar then _rebuildCache(char) end
        for i = 1, #_noclipParts do
            local p = _noclipParts[i]
            if p and p.Parent then p.CanCollide = false end
        end
    end)
    -- Guardar la conexion CharacterAdded para limpiarla al desactivar
    Settings.connections.noclipCharConn = _charConn
end

function DisableNoclip()
    if Settings.connections.noclip then
        Settings.connections.noclip:Disconnect()
        Settings.connections.noclip = nil
    end
    if Settings.connections.noclipCharConn then
        pcall(function() Settings.connections.noclipCharConn:Disconnect() end)
        Settings.connections.noclipCharConn = nil
    end
    local character = LocalPlayer.Character
    if character then
        local hrp = character:FindFirstChild("HumanoidRootPart")
        local hum = character:FindFirstChildOfClass("Humanoid")
        -- FIX DESYNC: guardar posicion exacta antes de restaurar colisiones
        local _savedPos = hrp and hrp.CFrame or nil
        for _, part in pairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = true
            end
        end
        -- FIX DESYNC: anclar momentaneamente para que el servidor registre
        -- la posicion correcta antes de que la fisica vuelva a mover al jugador.
        -- Sin esto los demas te ven en la posicion anterior (desync clasico de noclip).
        if hrp and _savedPos then
            task.spawn(function()
                pcall(function()
                    local _wasAnchored = hrp.Anchored
                    hrp.Anchored = true
                    hrp.CFrame = _savedPos
                    task.wait(0.05)
                    hrp.Anchored = _wasAnchored
                    if hum and hum.Parent then
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end
                end)
            end)
        end
    end
end

function GetCurrentMap()
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") and obj:FindFirstChild("CoinContainer") then
            local totalCoins = 0
            local coinContainer = obj:FindFirstChild("CoinContainer")
            if coinContainer then
                for _ in pairs(coinContainer:GetChildren()) do
                    totalCoins = totalCoins + 1
                end
            end
            return obj.Name, totalCoins
        end
    end
    return nil, 0
end

function GetCurrentMapName()
    -- Prioridad: Mansion2 siempre activo
    if game:GetService("Workspace"):FindFirstChild("Mansion2") then return "Mansion2" end
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") and not obj.Name:lower():find("lobby") then
            if obj:FindFirstChild("CoinContainer") or obj:FindFirstChild("Spawns") then
                return obj.Name
            end
        end
    end
    local kw = {
        "MilBase","Mansion","School","Hospital","Factory","Station","Carnival",
        "Cave","Castle","Asylum","Island","Dungeon","Lighthouse","Bank","Arena",
        "Facility","Airport","Museum","Cruise","Sewers","Courtyard","Jailbreak",
        "Rocket","Office","Library","Temple","Forest","City","House","Subway",
        "Workshop","Laboratory","Mall","Prison","Church","Funland","Graveyard",
        "Resort","Diner","Pizzeria","Warehouse","Harbor","Camp","Desert","Winter",
        "Haunt","Slaughterhouse","Circus","Apartment","Hotel","Map","Level"
    }
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") and not obj.Name:lower():find("lobby") then
            for _, k in ipairs(kw) do
                if obj.Name:lower():find(k:lower()) then return obj.Name end
            end
        end
    end
    local biggest, biggestCount = nil, 60
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") and obj ~= LocalPlayer.Character
        and not obj.Name:lower():find("lobby") then
            local n = #obj:GetDescendants()
            if n > biggestCount then biggestCount = n; biggest = obj.Name end
        end
    end
    return biggest
end

function FindNearestCoin(coins)
    local character = LocalPlayer.Character
    if not character then return nil, math.huge end
    local hrp = character:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil, math.huge end
    local nearest = nil
    local nearestDistance = math.huge
    for _, coin in ipairs(coins) do
        if coin and coin.Parent then
            local distance = (hrp.Position - coin.Position).Magnitude
            if distance < nearestDistance then
                nearest = coin
                nearestDistance = distance
            end
        end
    end
    return nearest, nearestDistance
end

function SetupSecondLife()
    if not Settings.secondLife.enabled then return end
    Settings.secondLife.used = false
    local character = LocalPlayer.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end

    local slConn
    local _hbTslConn = 0
    local _slTick=0
    slConn = RunService.Heartbeat:Connect(function()
        _slTick=_slTick+1; if _slTick<2 then return end; _slTick=0  -- OPT: 30Hz
        _hbTslConn=_hbTslConn+1; if _hbTslConn<3 then return end; _hbTslConn=0
        if not Settings.secondLife.enabled then
            if slConn then slConn:Disconnect() slConn = nil end
            return
        end
        if LocalPlayer.Character ~= character then
            if slConn then slConn:Disconnect() slConn = nil end
            return
        end
        local hum = character:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        if hum.Health <= 0.5 and not Settings.secondLife.used then
            Settings.secondLife.used = true
            PlayDeathSound()
            pcall(function() hum.Health = hum.MaxHealth end)
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end)
            pcall(function() hum.Health = hum.MaxHealth end)
 CreateCustomNotification("SECOND LIFE", "!Segunda vida activada!", 3)
            task.wait(3)
            Settings.secondLife.used = false
        end
    end)
    LocalPlayer.CharacterAdded:Connect(function()
        Settings.secondLife.used = false
        task.wait(1)
        SetupSecondLife()
    end)
end

