-- FIX: Global bindable GUI registry - tracks ALL bindable ScreenGuis by name
-- Ensures toggle off always destroys the button, even across tab reloads
_G._BindableGuiRegistry = _G._BindableGuiRegistry or {}
function _registerBindableGui(name, gui)
    -- Destroy any previous instance with same name
    local old = _G._BindableGuiRegistry[name]
    if old and old.Parent then pcall(function() old:Destroy() end) end
    _G._BindableGuiRegistry[name] = gui
end
function _destroyNamedBindableGui(name)
    -- Destroy from registry
    local reg = _G._BindableGuiRegistry[name]
    if reg and reg.Parent then pcall(function() reg:Destroy() end) end
    _G._BindableGuiRegistry[name] = nil
    -- Also sweep all GUI containers for safety
    local function sweep(p)
        if not p then return end
        for _, g in ipairs(p:GetChildren()) do
            if g.Name == name then pcall(function() g:Destroy() end) end
        end
    end
    pcall(function() sweep(game:GetService("CoreGui")) end)
    pcall(function() sweep(LocalPlayer:FindFirstChild("PlayerGui")) end)
end

-- =============================================
-- BINDABLE BUTTON LAYOUT SYSTEM
-- Botones en fila al lado del mute icon de Roblox
-- 6 por fila, luego bajan a la siguiente
-- =============================================
_G._bindableSlotIndex = 0
_G._bindableSlotMap   = {}
_G._bindablePosSave   = _G._bindablePosSave or {}

-- Slots activos: siempre fresco al re-ejecutar (evita slots sucios de runs anteriores)
_G._bindableActiveSlots = {}

-- Registro ordenado de bindables activos (orden de activacion)
_G._bindableOrderedList = _G._bindableOrderedList or {}

_BIND_CS    = 76   -- tamano del boton (debe coincidir con BTN_W/BTN_H en MakeCapyBindableFrame)
_BIND_GAP   = 10
_BIND_COLS  = 20   -- fila unica horizontal (todos los bindables en una sola fila)
_BIND_PAD_X = 12
_BIND_PAD_Y = 10   -- margen desde arriba

function _getBindablePosition(slotIndex)
    local col = slotIndex % _BIND_COLS
    local row = math.floor(slotIndex / _BIND_COLS)
    local x   = _BIND_PAD_X + col * (_BIND_CS + _BIND_GAP)
    local y   = _BIND_PAD_Y + row * (_BIND_CS + _BIND_GAP)
    return x, y, _BIND_CS, _BIND_CS
end

-- Reposiciona todos los bindables activos segun su orden en la lista
function _rebuildBindableLayout()
    local list = _G._bindableOrderedList or {}
    for i, label in ipairs(list) do
        local slotIndex = i - 1  -- 0-based
        local x, y = _getBindablePosition(slotIndex)
        -- Buscar el bg Frame del bindable y moverlo con tween suave
        local sg = _G._capyBindRegistry and _G._capyBindRegistry[label]
        if sg and sg.Parent then
            local bg = sg:FindFirstChild("CapyBindBtn")
            if bg then
                pcall(function()
                    TweenService:Create(bg, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        Position = UDim2.fromOffset(x, y)
                    }):Play()
                end)
            end
        end
    end
end

-- Asigna el proximo slot libre y agrega a la lista ordenada
function _assignSlot(label)
    if _G._bindableActiveSlots[label] then
        return _G._bindableActiveSlots[label]  -- ya tiene slot, reusar
    end
    -- Agregar al final de la lista ordenada
    local list = _G._bindableOrderedList
    table.insert(list, label)
    -- El slot es su posicion en la lista (0-based)
    local slot = #list - 1
    _G._bindableActiveSlots[label] = slot
    return slot
end

function _releaseSlot(label)
    _G._bindableActiveSlots[label] = nil
    -- Remover de la lista ordenada
    local list = _G._bindableOrderedList
    for i, l in ipairs(list) do
        if l == label then
            table.remove(list, i)
            break
        end
    end
    -- Recalcular slots de todos los restantes
    for i, l in ipairs(list) do
        _G._bindableActiveSlots[l] = i - 1
    end
    -- Reposicionar todos con animacion suave
    task.defer(_rebuildBindableLayout)
end

-- Registro global: label -> _bindSg, para destruccion directa sin buscar por nombre
-- Al recargar el hub, destruir CapyBindSg existentes.
-- Los toggles activos los recrear?n solos via auto-restore.
_G._capyBindRegistry       = {}
_G._capyBindParentRegistry = {}
_G._bindableActiveSlots    = {}
do
    local function _nukeOldBindSgs(parent)
        if not parent then return end
        pcall(function()
            for _, g in ipairs(parent:GetChildren()) do
                if tostring(g.Name):sub(1,10) == "CapyBindSg" then
                    pcall(function() g:Destroy() end)
                end
            end
        end)
    end
    pcall(function() _nukeOldBindSgs(game:GetService("CoreGui")) end)
    pcall(function() _nukeOldBindSgs(game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")) end)
    pcall(function() if gethui then _nukeOldBindSgs(gethui()) end end)
end

function MakeCapyBindableFrame(guiParent, labelText, callback, optPosX, optPosY)
    -- ======================================================
    -- NUEVO DISENO: boton cuadrado redondeado, borde rojo
    -- animado, colores Soft Gray del hub, feedback visual
    -- ======================================================
    local BTN_W = 76  -- se sobreescribe abajo, se mantiene para calculos de posicion
    local BTN_H = 76
    local _coreGui = game:GetService("CoreGui")
    local _sgName  = "CapyBindSg_" .. tostring(labelText):gsub("%s","")
    local _posKey  = tostring(labelText)

    -- POSICION: siempre slot automatico o posicion manual -- NUNCA restaurar la guardada.
    -- Motivo: al cambiar de pestana el boton se destruye y recrea; restaurar la posicion
    -- guardada lo hacia aparecer en el lugar donde el usuario lo habia dejado antes,
    -- en vez de aparecer siempre en su posicion inicial de slot.
    local vp = workspace.CurrentCamera.ViewportSize
    local posXOff, posYOff
    if optPosX and optPosY then
        posXOff = math.clamp(optPosX, 4, vp.X - BTN_W - 4)
        posYOff = math.clamp(optPosY, 4, vp.Y - BTN_H - 4)
    else
        local mySlot = _assignSlot(tostring(labelText))
        posXOff, posYOff = _getBindablePosition(mySlot)
    end

    -- Destruir instancia anterior si existe
    local _prevSg = _G._capyBindRegistry and _G._capyBindRegistry[labelText]
    if _prevSg then pcall(function() _prevSg:Destroy() end) end
    pcall(function()
        for _, g in ipairs(_coreGui:GetChildren()) do
            if g.Name == _sgName then g:Destroy() end
        end
    end)
    pcall(function()
        local pg = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
        if pg then
            for _, g in ipairs(pg:GetChildren()) do
                if g.Name == _sgName then g:Destroy() end
            end
        end
    end)

    -- FIX TOGGLE-OFF: si el caller ya creo un ScreenGui (guiParent), usarlo directamente
    -- como contenedor en vez de crear un _bindSg separado.
    -- Antes MakeCapyBindableFrame ignoraba guiParent y creaba su propio ScreenGui en CoreGui,
    -- de modo que al destruir el guiParent externo el boton flotante quedaba vivo.
    -- Ahora: si guiParent es un ScreenGui ya montado, el Frame del boton va dentro de el
    -- y cuando el toggle lo destruye, el boton desaparece automaticamente.
    local _bindSg
    local _isExternalSg = guiParent and guiParent:IsA("ScreenGui") and guiParent.Parent ~= nil
    if _isExternalSg then
        -- Usar el ScreenGui del caller como contenedor real (sin crear uno nuevo)
        _bindSg = guiParent
    else
        -- Comportamiento original: crear propio ScreenGui en CoreGui
        _bindSg = Instance.new("ScreenGui")
        _bindSg.Name           = _sgName
        _bindSg.ResetOnSpawn   = false
        _bindSg.DisplayOrder   = 9998
        _bindSg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        _bindSg.IgnoreGuiInset = true
        pcall(function() _bindSg.Parent = _coreGui end)
        if not _bindSg.Parent then
            _bindSg.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
        end
    end
    _G._capyBindRegistry = _G._capyBindRegistry or {}
    _G._capyBindRegistry[labelText] = _bindSg
    -- Reposicionar todos al agregar uno nuevo (layout en fila de 4)
    task.defer(_rebuildBindableLayout)

    -- FIX PERSISTENCIA: NO destruir el bindable cuando el hub se cierra/re-ejecuta.
    -- Antes este AncestryChanged mataba el boton al cerrar el hub, por eso desaparecia
    -- al reabrir. Ahora el bindable sobrevive mientras su toggle este activo.
    -- Solo se destruye cuando el usuario desactiva el toggle manualmente (_animatedDestroy).

    -- Tama?o tecla estilo SHIFT (cuadrado compacto, sin fondo)
    BTN_W = 76
    BTN_H = 76

    -- -- CONTENEDOR RAIZ ----------------------------------
    local bg = Instance.new("Frame", _bindSg)
    bg.Name                   = "CapyBindBtn"
    bg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    bg.Position               = UDim2.fromOffset(posXOff, posYOff)
    bg.AnchorPoint            = Vector2.new(0, 0)
    bg.BackgroundTransparency = 1
    bg.BorderSizePixel        = 0
    bg.ZIndex                 = 200
    bg.Active                 = true

    -- UIScale para animacion de entrada
    local _bindUiScale = Instance.new("UIScale", bg)
    _bindUiScale.Scale = 0

    -- -- FONDO: transparente (sin fondo, estilo tecla SHIFT) --
    local pillBg = Instance.new("Frame", bg)
    pillBg.Name                   = "PillBg"
    pillBg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    pillBg.AnchorPoint            = Vector2.new(0.5, 0.5)
    pillBg.Position               = UDim2.fromScale(0.5, 0.5)
    pillBg.BackgroundColor3       = ThemeColors.Aurora1
    pillBg.BackgroundTransparency = 1   -- sin fondo por defecto
    pillBg.BorderSizePixel        = 0
    pillBg.ZIndex                 = 200
    Instance.new("UICorner", pillBg).CornerRadius = UDim.new(1, 0)  -- circulo completo

    -- -- BORDE del color del hub (principal visible, estilo SHIFT) --
    local borderFrame = Instance.new("Frame", bg)
    borderFrame.Name                   = "BorderFrame"
    borderFrame.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    borderFrame.AnchorPoint            = Vector2.new(0.5, 0.5)
    borderFrame.Position               = UDim2.fromScale(0.5, 0.5)
    borderFrame.BackgroundTransparency = 1
    borderFrame.BorderSizePixel        = 0
    borderFrame.ZIndex                 = 201
    Instance.new("UICorner", borderFrame).CornerRadius = UDim.new(1, 0)  -- sin cuadrado

    local borderStroke = Instance.new("UIStroke", borderFrame)
    borderStroke.Color           = ThemeColors.Aurora1
    borderStroke.Thickness       = 0
    borderStroke.Transparency    = 1
    borderStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Dummy para compatibilidad (no usado en hover/click ahora)
    local iconLbl = Instance.new("TextLabel", bg)
    iconLbl.Size = UDim2.fromOffset(0, 0); iconLbl.BackgroundTransparency = 1
    iconLbl.Text = ""; iconLbl.ZIndex = 199

    local sepLine = Instance.new("Frame", bg)
    sepLine.Size = UDim2.fromOffset(0, 0); sepLine.BackgroundTransparency = 1
    sepLine.ZIndex = 199

    -- -- BOTON PRINCIPAL (captura clicks, muestra texto) --
    local fill = Instance.new("TextButton", bg)
    fill.Name                   = "Fill"
    fill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    fill.AnchorPoint            = Vector2.new(0.5, 0.5)
    fill.Position               = UDim2.fromScale(0.5, 0.5)
    fill.BackgroundTransparency = 1
    fill.BorderSizePixel        = 0
    fill.Text                   = ""
    fill.AutoButtonColor        = false
    fill.Active                 = true
    fill.ZIndex                 = 210
    Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)  -- area click circular

    -- fillStroke (compatibilidad)
    local fillStroke = Instance.new("UIStroke", fill)
    fillStroke.Color           = ThemeColors.Aurora1
    fillStroke.Thickness       = 0
    fillStroke.Transparency    = 1
    fillStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- TextLabel centrado (estilo SHIFT: blanco, bold, centrado)
    local textLabel = Instance.new("TextLabel", bg)
    textLabel.Name                   = "TextLabel"
    textLabel.Size                   = UDim2.fromOffset(BTN_W - 8, BTN_H - 8)
    textLabel.AnchorPoint            = Vector2.new(0.5, 0.5)
    textLabel.Position               = UDim2.fromScale(0.5, 0.5)
    textLabel.BackgroundTransparency = 1
    textLabel.Text                   = tostring(labelText)
    textLabel.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    textLabel.TextSize               = 13
    textLabel.TextColor3             = Color3.fromRGB(255, 255, 255)
    textLabel.TextXAlignment         = Enum.TextXAlignment.Center
    textLabel.TextYAlignment         = Enum.TextYAlignment.Center
    textLabel.TextWrapped            = true
    textLabel.TextScaled             = false
    textLabel.ZIndex                 = 204

    local textStroke = Instance.new("UIStroke", textLabel)
    textStroke.Color        = Color3.fromRGB(0, 0, 0)
    textStroke.Thickness    = 1
    textStroke.Transparency = 0.5

    -- AUTO-REGISTRO de idioma
    if _LangObjects then
        table.insert(_LangObjects, {obj=textLabel, key=tostring(labelText), prefix="", suffix=""})
        if _G.HubLanguage and _LangStrings then
            local _d = _LangStrings[_G.HubLanguage]
            if _d and _d[tostring(labelText)] then textLabel.Text = _d[tostring(labelText)] end
        end
    end

    -- -- GLOW de fondo mejorado (dos capas con pulso + rotacion de color) --
    local glowImg = Instance.new("ImageLabel", bg)
    glowImg.Name                   = "GlowPulse"
    glowImg.AnchorPoint            = Vector2.new(0.5, 0.5)
    glowImg.Position               = UDim2.fromScale(0.5, 0.5)
    glowImg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    glowImg.BackgroundTransparency = 1
    glowImg.Image                  = "rbxassetid://118930676204472"
    glowImg.ImageColor3            = ThemeColors.Aurora1
    glowImg.ImageTransparency      = 0.10
    glowImg.ScaleType              = Enum.ScaleType.Fit
    glowImg.ZIndex                 = 198
    local glowOuter = Instance.new("ImageLabel", bg)
    glowOuter.Name                   = "GlowOuter"
    glowOuter.AnchorPoint            = Vector2.new(0.5, 0.5)
    glowOuter.Position               = UDim2.fromScale(0.5, 0.5)
    glowOuter.Size                   = UDim2.fromOffset(BTN_W * 1.3, BTN_H * 1.3)
    glowOuter.BackgroundTransparency = 1
    glowOuter.Image                  = "rbxassetid://118930676204472"
    glowOuter.ImageColor3            = ThemeColors.Primary
    glowOuter.ImageTransparency      = 0.72
    glowOuter.ScaleType              = Enum.ScaleType.Fit
    glowOuter.ZIndex                 = 197

    -- -- ANIMACION DE ENTRADA ------------------------------
    task.spawn(function()
        task.wait(0.016)
        TweenService:Create(_bindUiScale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
    end)

    -- -- DRAG (variables declaradas aqui para que el float animation las capture como upvalues)
    local _dragConn  = nil
    local _dragging  = false
    local _dragStart = nil
    local _startPos  = nil
    local _moved     = false

    -- Ciclo de colores del hub para el borde y glow (rapido: 1.2s ciclo)
    local _HUB_COLS = {
        ThemeColors.Aurora1, ThemeColors.Aurora2, ThemeColors.Primary,
        ThemeColors.Accent,  ThemeColors.Aurora3, ThemeColors.Primary,
    }
    local _nHC = #_HUB_COLS
    local _BORDER_SPEED = 1.2  -- segundos por ciclo completo del borde
    local _GLOW_SPEED   = 0.8  -- ciclos por segundo del pulso de escala del glow
    local function _lerpC(a, b, t)
        return Color3.new(a.R+(b.R-a.R)*t, a.G+(b.G-a.G)*t, a.B+(b.B-a.B)*t)
    end

    -- -- ANIMACION FLOTANTE + BORDE + GLOW (Heartbeat unificado) --
    local _floatConn  = nil
    local _floatPhase = math.random() * math.pi * 2
    local _floatAmp   = 5
    local _floatSpeed = 1.5
    local _floatBaseY = posYOff
    local _animTick   = 0

    _floatConn = game:GetService("RunService").Heartbeat:Connect(function(dt)
        _animTick = _animTick + dt
        if not bg or not bg.Parent then
            if _floatConn then pcall(function() _floatConn:Disconnect() end) end
            _floatConn = nil; return
        end
        -- Flotacion Y + tilt
        if not _dragging and not _moved then
            local wave = math.sin(_animTick * _floatSpeed * math.pi * 2 + _floatPhase) * _floatAmp
            local tilt = math.sin(_animTick * _floatSpeed * math.pi * 2 + _floatPhase + math.pi * 0.5) * 2
            pcall(function()
                bg.Position = UDim2.fromOffset(bg.Position.X.Offset, _floatBaseY + wave)
                bg.Rotation = tilt
            end)
        else
            _floatBaseY = bg.Position.Y.Offset
        end
        -- Ciclo de color del borde (rapido, sin tween)
        pcall(function()
            local _cp  = (_animTick % _BORDER_SPEED) / _BORDER_SPEED
            local _fi  = _cp * _nHC
            local _iA  = math.floor(_fi) % _nHC + 1
            local _iB  = _iA % _nHC + 1
            local _col = _lerpC(_HUB_COLS[_iA], _HUB_COLS[_iB], _fi - math.floor(_fi))
            borderStroke.Color  = _col
            glowImg.ImageColor3 = _col
        end)
        -- Pulso de escala y transparencia del glow
        pcall(function()
            local _p   = math.sin(_animTick * _GLOW_SPEED * math.pi * 2) * 0.5 + 0.5
            glowImg.Size              = UDim2.fromOffset(BTN_W*(0.95+_p*0.10), BTN_H*(0.95+_p*0.10))
            glowImg.ImageTransparency = 0.05 + _p * 0.15
            local _po  = math.sin(_animTick * _GLOW_SPEED * 0.5 * math.pi * 2 + math.pi) * 0.5 + 0.5
            glowOuter.Size              = UDim2.fromOffset(BTN_W*(1.25+_po*0.15), BTN_H*(1.25+_po*0.15))
            local _co  = ((_animTick + _BORDER_SPEED*0.5) % _BORDER_SPEED) / _BORDER_SPEED
            local _foi = _co * _nHC
            local _oA  = math.floor(_foi) % _nHC + 1
            local _oB  = _oA % _nHC + 1
            glowOuter.ImageColor3       = _lerpC(_HUB_COLS[_oA], _HUB_COLS[_oB], _foi - math.floor(_foi))
            glowOuter.ImageTransparency = 0.80 + _po * 0.15
        end)
    end)

    -- -- FIN ANIMACION UNIFICADA ---------------------------
    -- (El override de _animatedDestroy se hace mas abajo, despues de que la funcion original es definida)

    if pcall(function()
        local dd = Instance.new("UIDragDetector", bg)
        dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
        dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
        dd.Dragged:Connect(function()
            if _G._sliderDragging then return end
            _moved = true
            local vpNow = workspace.CurrentCamera.ViewportSize
            bg.Position = UDim2.fromOffset(
                math.clamp(bg.Position.X.Offset, 0, vpNow.X - BTN_W),
                math.clamp(bg.Position.Y.Offset, 0, vpNow.Y - BTN_H)
            )
            _G._bindablePosSave = _G._bindablePosSave or {}
            _G._bindablePosSave[_posKey] = {x=bg.Position.X.Offset, y=bg.Position.Y.Offset}
        end)
        dd.DragEnd:Connect(function() task.defer(function() _moved = false end) end)
    end) then
        -- UIDragDetector OK
    else
        fill.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                _dragging = true; _moved = false
                -- FIX MOVIL: guardar solo X/Y del inicio
                _dragStart = Vector3.new(input.Position.X, input.Position.Y, 0)
                _startPos = bg.Position
            end
        end)
        _dragConn = UserInputService.InputChanged:Connect(function(input)
            if not _dragging then return end
            if _G._sliderDragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
            -- FIX MOVIL: delta incremental para que no salte a esquina en touch
            local curX = input.Position.X
            local curY = input.Position.Y
            local dX = curX - _dragStart.X
            local dY = curY - _dragStart.Y
            if math.abs(dX) > 4 or math.abs(dY) > 4 then _moved = true end
            _dragStart = Vector3.new(curX, curY, 0)
            local vpNow = workspace.CurrentCamera.ViewportSize
            bg.Position = UDim2.fromOffset(
                math.clamp(bg.Position.X.Offset + dX, 0, vpNow.X - BTN_W),
                math.clamp(bg.Position.Y.Offset + dY, 0, vpNow.Y - BTN_H)
            )
        end)
        fill.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                _dragging = false
                if _moved then
                    _G._bindablePosSave = _G._bindablePosSave or {}
                    _G._bindablePosSave[_posKey] = {x=bg.Position.X.Offset, y=bg.Position.Y.Offset}
                end
                task.defer(function() _moved = false end)
            end
        end)
    end

    -- Colores (estilo tecla SHIFT: texto blanco siempre)
    local _C_TEXT_IDLE  = Color3.fromRGB(255, 255, 255)
    local _C_TEXT_WHITE = Color3.fromRGB(255, 255, 255)

    -- Hover: fondo sutilmente visible + glow mas intenso
    fill.MouseEnter:Connect(function()
        TweenService:Create(glowImg,   TweenInfo.new(0.12), {ImageTransparency=0.00, Size=UDim2.fromOffset(BTN_W*1.1, BTN_H*1.1)}):Play()
        TweenService:Create(glowOuter, TweenInfo.new(0.12), {ImageTransparency=0.50}):Play()
    end)
    fill.MouseLeave:Connect(function()
        -- glow vuelve a ser controlado por Heartbeat (no forzar valor, simplemente dejarlo)
    end)

    -- -- CLICK (press = fondo aparece + scale down, release = vuelve) --
    local _capyIsActive = false
    local _lastActivatedTick = 0
    local function _doActivate()
        if _moved then return end
        local now = tick()
        if now - _lastActivatedTick < 0.15 then return end
        _lastActivatedTick = now
        if callback then task.spawn(function() callback(_capyIsActive) end) end
    end
    fill.MouseButton1Down:Connect(function()
        if _moved then return end
        TweenService:Create(_bindUiScale, TweenInfo.new(0.07), {Scale=0.88}):Play()
        TweenService:Create(glowImg,      TweenInfo.new(0.07), {ImageTransparency=0.00}):Play()
    end)
    fill.MouseButton1Up:Connect(function()
        if _moved then return end
        TweenService:Create(_bindUiScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
        _doActivate()
    end)
    fill.Activated:Connect(function()
        _doActivate()
    end)

    -- -- SetActiveState (toggle ON = fondo visible, OFF = transparente) --
    local function _setActive(on)
        _capyIsActive = on
        -- sin cuadrado: el estado activo se refleja en el brillo del glow
        if on then
            TweenService:Create(glowImg, TweenInfo.new(0.18), {ImageTransparency=0.00}):Play()
        else
            TweenService:Create(glowImg, TweenInfo.new(0.18), {ImageTransparency=0.10}):Play()
        end
    end
    fill.SetActiveState  = function(self, on) _setActive(on) end
    bg.SetActiveState    = function(self, on) _setActive(on) end

    -- -- Shape system (cuadrado fijo, ignorar selector) ----
    local function _applyShape(shape) end
    bg.SetShape = function(self, shape) end

    -- -- Alias para compatibilidad (capyButton) ------------
    local capyButton = fill

    -- -- Destruccion animada -------------------------------
    local _destroying = false
    local function _animatedDestroy()
        if _destroying then return end
        _destroying = true
        if _dragConn then pcall(function() _dragConn:Disconnect() end) end
        -- Animar salida y destruir
        TweenService:Create(textLabel,  TweenInfo.new(0.15, Enum.EasingStyle.Quad), {TextTransparency=1}):Play()
        TweenService:Create(_bindUiScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale=0}):Play()
        task.delay(0.25, function() pcall(function() _bindSg:Destroy() end) end)
    end
    -- Envolver _animatedDestroy para que tambien detenga la animacion flotante
    local _origAnimDestroy = _animatedDestroy
    local function _animatedDestroyFull()
        if _floatConn then pcall(function() _floatConn:Disconnect() end); _floatConn = nil end
        _origAnimDestroy()
    end
    bg._animatedDestroy      = _animatedDestroyFull
    _bindSg._animatedDestroy = _animatedDestroyFull

    -- Limpiar registry al destruirse
    _bindSg.AncestryChanged:Connect(function()
        if not _bindSg.Parent then
            if not (optPosX and optPosY) then pcall(function() _releaseSlot(tostring(labelText)) end) end
            if _G._capyBindRegistry and _G._capyBindRegistry[labelText] == _bindSg then
                _G._capyBindRegistry[labelText] = nil
            end
        end
    end)

    bg._bindSg = _bindSg
    return bg
end

-- Helper global: destruye el ScreenGui interno de un bindable por su label
-- Usar esto en el else de cada toggle en vez de (o ademas de) destruir el sg externo
function DestroyCapyBind(labelText)
    local _sgName = "CapyBindSg_" .. tostring(labelText):gsub("%s","")

    -- 1. Destruir por referencia directa del registry
    local reg = _G._capyBindRegistry
    if reg and reg[labelText] then
        local sg = reg[labelText]
        reg[labelText] = nil
        _releaseSlot(tostring(labelText))
        if sg._animatedDestroy then
            task.spawn(sg._animatedDestroy)
        else
            task.spawn(function() pcall(function() sg:Destroy() end) end)
        end
    else
        _releaseSlot(tostring(labelText))
    end

    -- 2. Barrido por nombre: destruir cualquier ScreenGui con ese nombre en CoreGui y PlayerGui
    -- Esto cubre casos donde el registry no tenia la referencia
    local function _sweepAndDestroy(parent)
        if not parent then return end
        pcall(function()
            for _, g in ipairs(parent:GetChildren()) do
                if g.Name == _sgName and g.Parent then
                    if g._animatedDestroy then
                        task.spawn(g._animatedDestroy)
                    else
                        pcall(function() g:Destroy() end)
                    end
                end
            end
        end)
    end
    _sweepAndDestroy(game:GetService("CoreGui"))
    pcall(function() _sweepAndDestroy(game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")) end)
    pcall(function() if gethui then _sweepAndDestroy(gethui()) end end)
end

-- Helper: agrega selector de forma debajo de cada toggle bindable
_BIND_SHAPES = {"Circulo","Cuadrado","Redondeado","Pill","Diamante"}
_BIND_SHAPE_KEYS = {"circle","square","rounded","pill","diamond"}
function _applyBindShape(fillFrame, shape)
    if not fillFrame or not fillFrame.Parent then return end
    local sz = 62
    local corner = fillFrame:FindFirstChildOfClass("UICorner")
    if shape == "circle" then
        fillFrame.Size = UDim2.fromOffset(sz, sz); fillFrame.Rotation = 0
        if corner then corner.CornerRadius = UDim.new(1, 0) end
    elseif shape == "square" then
        fillFrame.Size = UDim2.fromOffset(sz, sz); fillFrame.Rotation = 0
        if corner then corner.CornerRadius = UDim.new(0, 4) end
    elseif shape == "rounded" then
        fillFrame.Size = UDim2.fromOffset(sz, sz); fillFrame.Rotation = 0
        if corner then corner.CornerRadius = UDim.new(0, 16) end
    elseif shape == "pill" then
        fillFrame.Size = UDim2.fromOffset(sz*1.65, sz*0.62); fillFrame.Rotation = 0
        if corner then corner.CornerRadius = UDim.new(1, 0) end
    elseif shape == "diamond" then
        fillFrame.Size = UDim2.fromOffset(sz, sz); fillFrame.Rotation = 45
        if corner then corner.CornerRadius = UDim.new(0, 2) end
    end
end
function AddBindableShapeSelector(parent, getBindFrame)
    -- FIX: usar _currentMainSectionFrame para quedar DENTRO de la seccion activa
    local _realParent = _currentMainSectionFrame or parent
    CreateNebulaSelector(_realParent, "Forma del bindable", _BIND_SHAPES, _BIND_SHAPES[1], function(selected)
        for i, s in ipairs(_BIND_SHAPES) do
            if s == selected then
                local shapeKey = _BIND_SHAPE_KEYS[i]
                -- Si se pasa un frame especifico, aplicar solo a ese
                if getBindFrame then
                    local bf = type(getBindFrame) == "function" and getBindFrame() or getBindFrame
                    if bf then
                        local fill = bf:FindFirstChild("Fill") or bf:FindFirstChildWhichIsA("Frame")
                        pcall(_applyBindShape, fill, shapeKey)
                    end
                else
                    -- Sin frame especifico: aplicar a TODOS los CapyBindSg activos en pantalla
                    local targets = {}
                    pcall(function()
                        for _, g in ipairs(game:GetService("CoreGui"):GetChildren()) do
                            if g.Name:sub(1, 10) == "CapyBindSg" then table.insert(targets, g) end
                        end
                    end)
                    pcall(function()
                        for _, g in ipairs(LocalPlayer:WaitForChild("PlayerGui"):GetChildren()) do
                            if g.Name:sub(1, 10) == "CapyBindSg" then table.insert(targets, g) end
                        end
                    end)
                    for _, sg in ipairs(targets) do
                        pcall(function()
                            local btn = sg:FindFirstChild("CapyBindBtn")
                            local fill = btn and btn:FindFirstChild("Fill")
                            if fill then _applyBindShape(fill, shapeKey) end
                        end)
                    end
                end
                CreateCustomNotification("BINDABLE", "Forma: " .. selected, 1.5)
                break
            end
        end
    end)
end
function createBindableButton(name, color)
    if _BindableButtons[name] then
        pcall(function() _BindableButtons[name]:Destroy() end)
        _BindableButtons[name] = nil
    end

    local gui = Instance.new("ScreenGui")
    gui.Name           = name .. "_CapyBtn"
    gui.ResetOnSpawn   = false
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.IgnoreGuiInset = true
    gui.DisplayOrder   = 9900
    pcall(function() gui.Parent = game:GetService("CoreGui") end)
    if not gui.Parent then gui.Parent = LocalPlayer.PlayerGui end

    -- ==============================================================
    -- BOTON SA REDISENADO -- estilo tecla SHIFT: sin fondo, borde hub
    -- ==============================================================
    local BTN_W = 76
    local BTN_H = 76
    local vp    = workspace.CurrentCamera.ViewportSize

    -- POSICION: siempre slot automatico -- no restaurar posicion guardada
    local _posKey  = tostring(name)
    local posX, posY
    do
        local slot = _assignSlot(name)
        local sx, sy = _getBindablePosition(slot)
        posX = math.clamp(sx, 4, vp.X - BTN_W - 4)
        posY = math.clamp(sy, 4, vp.Y - BTN_H - 4)
    end
    -- Reposicionar todos al agregar este bindable
    task.defer(_rebuildBindableLayout)

    -- -- CONTENEDOR raiz (invisible, solo para drag) --------------
    local bg = Instance.new("Frame", gui)
    bg.Name                   = "CapyBindBtn"
    bg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    bg.Position               = UDim2.fromOffset(posX, posY)
    bg.BackgroundTransparency = 1
    bg.BorderSizePixel        = 0
    bg.ZIndex                 = 200
    bg.Active                 = true

    local _bgScale = Instance.new("UIScale", bg)
    _bgScale.Scale = 0

    -- -- FONDO transparente (sin fondo, estilo tecla SHIFT) --------
    local pill = Instance.new("Frame", bg)
    pill.Name                   = "Pill"
    pill.AnchorPoint            = Vector2.new(0.5, 0.5)
    pill.Position               = UDim2.fromScale(0.5, 0.5)
    pill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    pill.BackgroundColor3       = ThemeColors.Aurora1
    pill.BackgroundTransparency = 1   -- sin fondo por defecto
    pill.BorderSizePixel        = 0
    pill.ZIndex                 = 201
    Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 10)

    -- Borde del color del hub (estilo SHIFT key, solido y visible)
    local outerRing = Instance.new("Frame", bg)
    outerRing.Name                   = "OuterRing"
    outerRing.AnchorPoint            = Vector2.new(0.5, 0.5)
    outerRing.Position               = UDim2.fromScale(0.5, 0.5)
    outerRing.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    outerRing.BackgroundTransparency = 1
    outerRing.BorderSizePixel        = 0
    outerRing.ZIndex                 = 202
    Instance.new("UICorner", outerRing).CornerRadius = UDim.new(0, 10)

    local outerStroke = Instance.new("UIStroke", outerRing)
    outerStroke.Color           = ThemeColors.Aurora1
    outerStroke.Thickness       = 0
    outerStroke.Transparency    = 1
    outerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local outerGrad = nil  -- sin gradiente rotatorio

    -- -- ESTRELLA centrada (ImageLabel con rbxassetid estrella) -----
    local lbl = Instance.new("ImageLabel", bg)
    lbl.Name                   = "StarIcon"
    lbl.AnchorPoint            = Vector2.new(0.5, 0.5)
    lbl.Position               = UDim2.fromScale(0.5, 0.5)
    lbl.Size                   = UDim2.fromOffset(40, 40)
    lbl.BackgroundTransparency = 1
    lbl.Image                  = "rbxassetid://45428892"
    lbl.ImageColor3            = Color3.fromRGB(255, 255, 255)
    lbl.ScaleType              = Enum.ScaleType.Fit
    lbl.ZIndex                 = 205

    -- Dummies para compatibilidad
    local icon = lbl
    local sep  = Instance.new("Frame", bg)
    sep.Size = UDim2.fromOffset(0, 0); sep.BackgroundTransparency = 1; sep.ZIndex = 199

    -- -- BOTON INVISIBLE encima para capturar clicks ---------------
    local fill = Instance.new("TextButton", bg)
    fill.Name                   = "Fill"
    fill.AnchorPoint            = Vector2.new(0.5, 0.5)
    fill.Position               = UDim2.fromScale(0.5, 0.5)
    fill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
    fill.BackgroundTransparency = 1
    fill.Text                   = ""
    fill.AutoButtonColor        = false
    fill.ZIndex                 = 210
    Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 10)

    -- -- GLOW de fondo (ImageLabel resplandor) ---------------------
    local glow = Instance.new("ImageLabel", bg)
    glow.AnchorPoint            = Vector2.new(0.5, 0.5)
    glow.Position               = UDim2.fromScale(0.5, 0.5)
    glow.Size                   = UDim2.fromOffset(BTN_W * 1.3, BTN_H * 1.8)
    glow.BackgroundTransparency = 1
    glow.Image                  = "rbxassetid://118930676204472"
    glow.ScaleType              = Enum.ScaleType.Fit
    glow.ImageColor3            = ThemeColors.Aurora1
    glow.ImageTransparency      = 0.82
    glow.ZIndex                 = 199

    -- -- ANIMACION DE ENTRADA --------------------------------------
    task.spawn(function()
        task.wait(0.016)
        TweenService:Create(_bgScale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
    end)

    -- Hover: fondo aparece sutilmente
    fill.MouseEnter:Connect(function()
        TweenService:Create(pill,       TweenInfo.new(0.12), {BackgroundTransparency=0.75}):Play()
        TweenService:Create(outerStroke,TweenInfo.new(0.12), {Thickness=3.5}):Play()
    end)
    fill.MouseLeave:Connect(function()
        TweenService:Create(pill,       TweenInfo.new(0.15), {BackgroundTransparency=1}):Play()
        TweenService:Create(outerStroke,TweenInfo.new(0.15), {Thickness=3}):Play()
    end)

    -- -- FEEDBACK DE CLICK (press = hundido + fondo, release = vuelve) --
    fill.MouseButton1Down:Connect(function()
        if _moved then return end
        TweenService:Create(pill,       TweenInfo.new(0.07), {BackgroundTransparency=0.40}):Play()
        TweenService:Create(outerStroke,TweenInfo.new(0.07), {Thickness=2}):Play()
        TweenService:Create(_bgScale,   TweenInfo.new(0.07), {Scale=0.92}):Play()
        TweenService:Create(glow,       TweenInfo.new(0.07), {ImageTransparency=0.55}):Play()
    end)
    fill.MouseButton1Up:Connect(function()
        if _moved then return end
        TweenService:Create(pill,       TweenInfo.new(0.18), {BackgroundTransparency=1}):Play()
        TweenService:Create(outerStroke,TweenInfo.new(0.18), {Thickness=3}):Play()
        TweenService:Create(_bgScale,   TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
        TweenService:Create(glow,       TweenInfo.new(0.25), {ImageTransparency=0.82}):Play()
    end)
    fill.Activated:Connect(function()
        if _moved then return end
        -- feedback flash en glow
        TweenService:Create(glow, TweenInfo.new(0.08), {ImageTransparency=0.42}):Play()
        task.delay(0.12, function()
            TweenService:Create(glow, TweenInfo.new(0.25), {ImageTransparency=0.82}):Play()
        end)
    end)

    -- -- DRAG ------------------------------------------------------
    -- FIX: _moved debe declararse ANTES del bloque de drag (era local aqu? antes)
    local _moved    = false
    local _dragConn = nil

    if pcall(function()
        local dd = Instance.new("UIDragDetector", bg)
        dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
        dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
        dd.Dragged:Connect(function()
            if _G._hubUndraggableButtons then return end
            _moved = true
            local vpN = workspace.CurrentCamera.ViewportSize
            bg.Position = UDim2.fromOffset(
                math.clamp(bg.Position.X.Offset, 0, vpN.X - BTN_W),
                math.clamp(bg.Position.Y.Offset, 0, vpN.Y - BTN_H))
            _G._bindablePosSave = _G._bindablePosSave or {}
            _G._bindablePosSave[_posKey] = {x = bg.Position.X.Offset, y = bg.Position.Y.Offset}
        end)
        dd.DragEnd:Connect(function() task.defer(function() _moved = false end) end)
    end) then
        -- UIDragDetector OK
    else
        -- FIX: fallback manual para cuando UIDragDetector no funciona
        -- (o cuando fill bloquea el input al bg)
        local _dragging  = false
        local _dragStart = nil
        local _startPos  = nil
        fill.InputBegan:Connect(function(input)
            if _G._hubUndraggableButtons then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                _dragging  = true
                _moved     = false
                -- FIX MOVIL: guardar solo X/Y
                _dragStart = Vector3.new(input.Position.X, input.Position.Y, 0)
                _startPos  = bg.Position
            end
        end)
        _dragConn = UserInputService.InputChanged:Connect(function(input)
            if not _dragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
            -- FIX MOVIL: delta incremental (evita salto a esquina en touch)
            local curX = input.Position.X
            local curY = input.Position.Y
            local dX = curX - _dragStart.X
            local dY = curY - _dragStart.Y
            if math.abs(dX) > 4 or math.abs(dY) > 4 then _moved = true end
            _dragStart = Vector3.new(curX, curY, 0)
            local vpN = workspace.CurrentCamera.ViewportSize
            bg.Position = UDim2.fromOffset(
                math.clamp(bg.Position.X.Offset + dX, 0, vpN.X - BTN_W),
                math.clamp(bg.Position.Y.Offset + dY, 0, vpN.Y - BTN_H))
        end)
        fill.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                _dragging = false
                if _moved then
                    _G._bindablePosSave = _G._bindablePosSave or {}
                    _G._bindablePosSave[_posKey] = {x = bg.Position.X.Offset, y = bg.Position.Y.Offset}
                end
                task.defer(function() _moved = false end)
            end
        end)
    end

    _BindableButtons[name] = gui
    _registerBindableGui(name .. "_CapyBtn", gui)
    gui.Frame = fill   -- exponer el boton clickeable como gui.Frame
    return gui
end

function destroyBindableButton(name)
    if _BindableButtons[name] then
        pcall(function() _BindableButtons[name]:Destroy() end)
        _BindableButtons[name] = nil
    end
    _destroyNamedBindableGui(name .. "_CapyBtn")
    _releaseSlot(name)  -- liberar slot del grid (ya llama _rebuildBindableLayout via task.defer)
end

function updateBindables()
    if Settings.combat.bindable.shoot then
        if not shootBtnGui then
            -- == BOTON SHOOT MURDERER: misma estructura y animaciones que createBindableButton ==
            do
                -- FIX BUG #4: Reduced SA button size from 76x76 to 52x52 for cleaner
                -- mobile UI. Same style, colors, animations - just a smaller footprint.
                -- Touch target is still 52px which is comfortably above the 44px minimum.
                local BTN_W = 52
                local BTN_H = 52
                local vp    = workspace.CurrentCamera.ViewportSize

                local _saGui = Instance.new("ScreenGui")
                _saGui.Name           = "SHOOT MURDERER_CapyBtn"
                _saGui.ResetOnSpawn   = false
                _saGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                _saGui.IgnoreGuiInset = true
