                pcall(function() _saGui.Parent = game:GetService("CoreGui") end)
                if not _saGui.Parent then _saGui.Parent = LocalPlayer.PlayerGui end

                local _slot = _assignSlot("SHOOT MURDERER")
                local _sx, _sy = _getBindablePosition(_slot)
                local posX = math.clamp(_sx, 4, vp.X - BTN_W - 4)
                local posY = math.clamp(_sy, 4, vp.Y - BTN_H - 4)

                -- Contenedor raiz (invisible, solo para drag)
                local _saBg = Instance.new("Frame", _saGui)
                _saBg.Name                   = "CapyBindBtn"
                _saBg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
                _saBg.Position               = UDim2.fromOffset(posX, posY)
                _saBg.BackgroundTransparency = 1
                _saBg.BorderSizePixel        = 0
                _saBg.ZIndex                 = 200
                _saBg.Active                 = true

                -- UIScale: 0?1 con Back bounce al aparecer
                local _saScale = Instance.new("UIScale", _saBg)
                _saScale.Scale = 0

                -- Pill (fondo que aparece en hover/press)
                local pill = Instance.new("Frame", _saBg)
                pill.Name                   = "Pill"
                pill.AnchorPoint            = Vector2.new(0.5, 0.5)
                pill.Position               = UDim2.fromScale(0.5, 0.5)
                pill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
                pill.BackgroundColor3       = ThemeColors.Aurora1
                pill.BackgroundTransparency = 1
                pill.BorderSizePixel        = 0
                pill.ZIndex                 = 201
                Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 10)

                -- Borde exterior del color del hub
                local outerRing = Instance.new("Frame", _saBg)
                outerRing.Name                   = "OuterRing"
                outerRing.AnchorPoint            = Vector2.new(0.5, 0.5)
                outerRing.Position               = UDim2.fromScale(0.5, 0.5)
                outerRing.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
                outerRing.BackgroundTransparency = 1
                outerRing.BorderSizePixel        = 0
                outerRing.ZIndex                 = 202
                Instance.new("UICorner", outerRing).CornerRadius = UDim.new(0, 10)

                local outerStroke = Instance.new("UIStroke", outerRing)
                outerStroke.Color           = ThemeColors.Aurora1
                outerStroke.Thickness       = 0
                outerStroke.Transparency    = 1
                outerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

                -- Label centrado con contorno negro
                local lbl = Instance.new("ImageLabel", _saBg)
                lbl.Name                   = "StarIcon"
                lbl.AnchorPoint            = Vector2.new(0.5, 0.5)
                lbl.Position               = UDim2.fromScale(0.5, 0.5)
                lbl.Size                   = UDim2.fromOffset(28, 28)  -- FIX #4: scaled from 40 to 28
                lbl.BackgroundTransparency = 1
                lbl.Image                  = "rbxassetid://45428892"
                lbl.ImageColor3            = Color3.fromRGB(255, 255, 255)
                lbl.ScaleType              = Enum.ScaleType.Fit
                lbl.ZIndex                 = 205


                -- Boton invisible encima para capturar clicks
                local shootButton = Instance.new("TextButton", _saBg)
                shootButton.Name                   = "Fill"
                shootButton.AnchorPoint            = Vector2.new(0.5, 0.5)
                shootButton.Position               = UDim2.fromScale(0.5, 0.5)
                shootButton.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
                shootButton.BackgroundTransparency = 1
                shootButton.Text                   = ""
                shootButton.AutoButtonColor        = false
                shootButton.ZIndex                 = 210
                Instance.new("UICorner", shootButton).CornerRadius = UDim.new(0, 10)

                -- Glow de fondo
                local glow = Instance.new("ImageLabel", _saBg)
                glow.AnchorPoint            = Vector2.new(0.5, 0.5)
                glow.Position               = UDim2.fromScale(0.5, 0.5)
                glow.Size                   = UDim2.fromOffset(BTN_W * 1.3, BTN_H * 1.8)
                glow.BackgroundTransparency = 1
                glow.Image                  = "rbxassetid://118930676204472"
                glow.ScaleType              = Enum.ScaleType.Fit
                glow.ImageColor3            = ThemeColors.Aurora1
                glow.ImageTransparency      = 0.82
                glow.ZIndex                 = 199

                -- _moved declarado ANTES del bloque de drag
                local _saMoved = false

                -- Animacion de entrada: scale 0?1 con Back bounce
                task.spawn(function()
                    task.wait(0.016)
                    TweenService:Create(_saScale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
                end)

                -- Hover
                shootButton.MouseEnter:Connect(function()
                    TweenService:Create(pill,        TweenInfo.new(0.12), {BackgroundTransparency = 0.75}):Play()
                    TweenService:Create(outerStroke, TweenInfo.new(0.12), {Transparency = 1, Thickness = 3.5}):Play()
                end)
                shootButton.MouseLeave:Connect(function()
                    TweenService:Create(pill,        TweenInfo.new(0.15), {BackgroundTransparency = 1}):Play()
                    TweenService:Create(outerStroke, TweenInfo.new(0.15), {Transparency = 1, Thickness = 3}):Play()
                end)

                -- Press / Release: hundido + glow intenso
                shootButton.MouseButton1Down:Connect(function()
                    if _saMoved then return end
                    TweenService:Create(pill,        TweenInfo.new(0.07), {BackgroundTransparency = 0.40}):Play()
                    TweenService:Create(outerStroke, TweenInfo.new(0.07), {Transparency = 1, Thickness = 2}):Play()
                    TweenService:Create(_saScale,    TweenInfo.new(0.07), {Scale = 0.92}):Play()
                    TweenService:Create(glow,        TweenInfo.new(0.07), {ImageTransparency = 0.55}):Play()
                end)
                shootButton.MouseButton1Up:Connect(function()
                    if _saMoved then return end
                    TweenService:Create(pill,        TweenInfo.new(0.18), {BackgroundTransparency = 1}):Play()
                    TweenService:Create(outerStroke, TweenInfo.new(0.18), {Transparency = 1, Thickness = 3}):Play()
                    TweenService:Create(_saScale,    TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
                    TweenService:Create(glow,        TweenInfo.new(0.25), {ImageTransparency = 0.82}):Play()
                end)

                -- Activated: flash glow
                shootButton.Activated:Connect(function()
                    if _saMoved then return end
                    TweenService:Create(glow, TweenInfo.new(0.08), {ImageTransparency = 0.42}):Play()
                    task.delay(0.12, function()
                        TweenService:Create(glow, TweenInfo.new(0.25), {ImageTransparency = 0.82}):Play()
                    end)
                end)

                -- Drag: UIDragDetector con fallback manual
                if pcall(function()
                    local dd = Instance.new("UIDragDetector", _saBg)
                    dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                    dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                    dd.Dragged:Connect(function()
                        if _G._hubUndraggableButtons then return end
                        _saMoved = true
                        local vpN = workspace.CurrentCamera.ViewportSize
                        _saBg.Position = UDim2.fromOffset(
                            math.clamp(_saBg.Position.X.Offset, 0, vpN.X - BTN_W),
                            math.clamp(_saBg.Position.Y.Offset, 0, vpN.Y - BTN_H))
                        _G._bindablePosSave = _G._bindablePosSave or {}
                        _G._bindablePosSave["SHOOT MURDERER"] = {x = _saBg.Position.X.Offset, y = _saBg.Position.Y.Offset}
                    end)
                    dd.DragEnd:Connect(function() task.defer(function() _saMoved = false end) end)
                end) then
                    -- UIDragDetector OK
                else
                    -- Fallback manual
                    local _saDragging = false
                    local _saDragStart = nil
                    local _saStartPos  = nil
                    shootButton.InputBegan:Connect(function(input)
                        if _G._hubUndraggableButtons then return end
                        if input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch then
                            _saDragging  = true
                            _saMoved     = false
                            _saDragStart = input.Position
                            _saStartPos  = _saBg.Position
                        end
                    end)
                    -- FIX BUG #5 PERF: store connection so it can be cleaned up when
                    -- the button is destroyed. Without this it leaked on every rebuild
                    -- of the Bindable layout, accumulating N global InputChanged listeners.
                    local _saDragConn
                    _saDragConn = UserInputService.InputChanged:Connect(function(input)
                        -- Auto-disconnect if the button was destroyed (layout rebuild, etc.)
                        if not _saBg or not _saBg.Parent then
                            if _saDragConn then _saDragConn:Disconnect(); _saDragConn = nil end
                            return
                        end
                        if not _saDragging then return end
                        if input.UserInputType ~= Enum.UserInputType.MouseMovement
                        and input.UserInputType ~= Enum.UserInputType.Touch then return end
                        -- FIX MOVIL: usar delta incremental (frame a frame) en lugar de
                        -- delta acumulado desde _saDragStart. En Touch, inp.Position
                        -- incluye eje Z (profundidad) que rompe el c?lculo acumulado.
                        local curX = input.Position.X
                        local curY = input.Position.Y
                        local dX = curX - _saDragStart.X
                        local dY = curY - _saDragStart.Y
                        if math.abs(dX) > 4 or math.abs(dY) > 4 then _saMoved = true end
                        _saDragStart = Vector3.new(curX, curY, 0)  -- actualizar para siguiente frame
                        local vpN = workspace.CurrentCamera.ViewportSize
                        local curPosX = _saBg.Position.X.Offset
                        local curPosY = _saBg.Position.Y.Offset
                        _saBg.Position = UDim2.fromOffset(
                            math.clamp(curPosX + dX, 0, vpN.X - BTN_W),
                            math.clamp(curPosY + dY, 0, vpN.Y - BTN_H))
                    end)
                    -- Clean up the global drag connection when the GUI is destroyed
                    _saGui.Destroying:Connect(function()
                        if _saDragConn then _saDragConn:Disconnect(); _saDragConn = nil end
                    end)
                    shootButton.InputEnded:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch then
                            _saDragging = false
                            if _saMoved then
                                _G._bindablePosSave = _G._bindablePosSave or {}
                                _G._bindablePosSave["SHOOT MURDERER"] = {x = _saBg.Position.X.Offset, y = _saBg.Position.Y.Offset}
                            end
                            task.defer(function() _saMoved = false end)
                        end
                    end)
                end

                _saGui.Frame = shootButton
                _BindableButtons["SHOOT MURDERER"] = _saGui
                _registerBindableGui("SHOOT MURDERER_CapyBtn", _saGui)
                shootBtnGui = _saGui
            end
            local function _doShootMurderer()
                -- ================================================================
                -- SHOOT MURDER v2 - CON DETECCION DE ROL SHERIFF
                -- 1) Verifica que el local player sea Sheriff
                -- 2) Guarda posicion antes de activar
                -- 3) TP detras del murder a 5 studs
                -- 4) Se mantiene pegado (tracking loop)
                -- 5) Silent Aim - auto shoot con redirect de bala
                -- 6) Al detectar Gunshot ajeno -> TP a posicion guardada
                -- ================================================================

                -- [1] VERIFICAR ROL: solo funciona si somos Sheriff (o Hero)
                local myRole = (_roleCache and _roleCache.localRole) or "Innocent"
                if myRole ~= "Sheriff" and myRole ~= "Hero" then
                    CreateCustomNotification("SHOOT MURDER", "Solo funciona siendo Sheriff!", 2)
                    return
                end

                local myChar = LocalPlayer.Character
                if not myChar then return end
                local myHum = myChar:FindFirstChildOfClass("Humanoid")
                if not myHum or myHum.Health <= 0 then return end
                local myHRP = myChar:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end

                -- Detectar murderer (target)
                local target = findMurderer and findMurderer()
                if not target or not target.Character then
                    CreateCustomNotification("SHOOT", "No hay Murder detectado", 1.5)
                    return
                end
                local tChar = target.Character
                local tHum  = tChar:FindFirstChildOfClass("Humanoid")
                if not tHum or tHum.Health <= 0 then
                    CreateCustomNotification("SHOOT", "Murder sin vida", 1.5)
                    return
                end
                local tHRP = tChar:FindFirstChild("HumanoidRootPart")
                if not tHRP then return end

                -- [2] GUARDAR POSICION ACTUAL (para volver despues del Gunshot)
                local savedCF = myHRP.CFrame

                -- [3] TP DETRAS DEL MURDER A 5 STUDS
                local function _getTpBehindMurder()
                    local mCF = tHRP.CFrame
                    -- -LookVector = detras del murder, 5 studs de distancia
                    local behindPos = mCF.Position - mCF.LookVector * 5
                    return CFrame.new(behindPos, mCF.Position)
                end

                pcall(function() myHRP.CFrame = _getTpBehindMurder() end)
                task.wait(0.08)

                -- Buscar gun
                local gun = nil
                for _, tool in ipairs(myChar:GetChildren()) do
                    if tool:IsA("Tool") then
                        if tool.Name == "DefaultGun"
                        or tool:FindFirstChild("GunClient")
                        or tool:FindFirstChild("GunServer") then
                            gun = tool; break
                        end
                    end
                end
                local _wasInBackpack = false
                if not gun then
                    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
                    if bp then
                        for _, tool in ipairs(bp:GetChildren()) do
                            if tool:IsA("Tool") then
                                if tool.Name == "DefaultGun"
                                or tool:FindFirstChild("GunClient")
                                or tool:FindFirstChild("GunServer") then
                                    gun = tool; _wasInBackpack = true; break
                                end
                            end
                        end
                    end
                    if gun then
                        pcall(function() myHum:EquipTool(gun) end)
                        task.wait(0.06)
                        for _, tool in ipairs(myChar:GetChildren()) do
                            if tool == gun or (tool:IsA("Tool") and (
                                tool.Name == "DefaultGun"
                                or tool:FindFirstChild("GunClient")
                                or tool:FindFirstChild("GunServer"))) then
                                gun = tool; break
                            end
                        end
                    end
                end
                if not gun then
                    gun = _findGunIn and (_findGunIn(myChar) or _findGunIn(LocalPlayer:FindFirstChildOfClass("Backpack")))
                end
                if not gun then
                    CreateCustomNotification("SHOOT", "No hay DefaultGun disponible", 1.5)
                    pcall(function() myHRP.CFrame = savedCF end)
                    return
                end

                -- GunRaycastAttachment
                local gra = myHRP:FindFirstChild("GunRaycastAttachment")
                if not gra then
                    gra = Instance.new("Attachment")
                    gra.Name     = "GunRaycastAttachment"
                    gra.Position = Vector3.new(0, 1.35, -1)
                    gra.Parent   = myHRP
                end

                -- [4] LOOP DE TRACKING (pegado a 5 studs detras del murder)
                -- + [5] SILENT AIM (auto shoot)
                -- + [6] DETECCION DE GUNSHOT -> TP a savedCF

                -- Flag de sesion: se cancela si el murder muere o nos matan
                local _smActive = true
                local _smConn_gunshot = nil  -- conexion para detectar disparo del murder

                -- Detectar si el murder dispara (Gunshot -> volvemos a savedCF)
                -- Hookear el RemoteEvent de shoot del juego (OnClientEvent / DescendantAdded)
                task.spawn(function()
                    -- Buscar el remote de GunFired en ReplicatedStorage (evento global de disparo)
                    local RS = game:GetService("ReplicatedStorage")
                    local gfRemote = nil
                    -- Intentar paths conocidos de MM2
                    local function _tryFindGF()
                        local function tp(root, ...)
                            local cur = root
                            for _, k in ipairs({...}) do
                                if not cur then return nil end
                                cur = cur:FindFirstChild(k)
                            end
                            return (cur and (cur:IsA("RemoteEvent") or cur:IsA("BindableEvent"))) and cur or nil
                        end
                        return
                            tp(RS, "ClientServices", "WeaponService", "GunFired") or
                            tp(RS, "WeaponEvents", "GunBeam")                     or
                            tp(RS, "Remotes", "Gameplay", "Shoot")                or
                            tp(RS, "WeaponEvents", "Shoot")                       or
                            tp(RS, "Events", "GunFired")
                    end
                    gfRemote = _tryFindGF()

                    if gfRemote then
                        local _evt = gfRemote:IsA("RemoteEvent") and gfRemote.OnClientEvent or gfRemote.Event
                        _smConn_gunshot = _evt:Connect(function(shooter, ...)
                            -- Si el que disparo es el murder -> TP a posicion guardada
                            if not _smActive then return end
                            if shooter == target then
                                _smActive = false
                                pcall(function() myHRP.CFrame = savedCF end)
                                CreateCustomNotification("SHOOT MURDER", "Gunshot detectado! TP a posicion guardada", 2)
                            end
                        end)
                    end
                end)

                -- Loop principal: mantener posicion + silent aim
                task.spawn(function()
                    local RS2 = game:GetService("RunService")
                    local _loopConn = nil
                    local _shotFired = false

                    -- SILENT AIM: calcular CFrames y disparar
                    local function _doSilentShot()
                        if _shotFired then return end
                        local c2   = LocalPlayer.Character
                        local h2   = c2 and c2:FindFirstChild("HumanoidRootPart")
                        if not c2 or not h2 then return end
                        local tPart = tChar:FindFirstChild(
                            (CombatTabState and CombatTabState.saTargetPart) or "Head"
                        ) or tChar:FindFirstChild("Head") or tHRP
                        local gra2 = h2:FindFirstChild("GunRaycastAttachment")
                        if not gra2 then
                            gra2 = Instance.new("Attachment")
                            gra2.Name = "GunRaycastAttachment"
                            gra2.Position = Vector3.new(0, 1.35, -1)
                            gra2.Parent = h2
                        end
                        local graCF2 = gra2.WorldCFrame

                        local finalGraCF, finalTargetCF = nil, nil
                        if _saGetTargetCF then
                            local ok3, gCF3, tCF3 = pcall(_saGetTargetCF)
                            if ok3 and gCF3 and tCF3 then
                                finalGraCF, finalTargetCF = gCF3, tCF3
                            end
                        end
                        if not (finalGraCF and finalTargetCF) then
                            local targetPos
                            if CombatTabState and CombatTabState.saUsePrediction and _getCachedPrediction then
                                targetPos = _getCachedPrediction(target) or tPart.Position
                            else
                                targetPos = tPart.Position
                            end
                            local originPos = graCF2.Position
                            local dir = targetPos - originPos
                            if dir.Magnitude < 0.01 then return end
                            local dirU = dir.Unit
                            local upV  = math.abs(dirU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
                            finalGraCF    = CFrame.new(graCF2.Position) * CFrame.lookAt(Vector3.zero, dirU, upV)
                            local backDir = originPos - targetPos
                            local backU   = backDir.Magnitude > 0.01 and backDir.Unit or -dirU
                            local bkUp    = math.abs(backU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
                            finalTargetCF = CFrame.lookAt(targetPos, targetPos + backU, bkUp)
                        end
                        if not (finalGraCF and finalTargetCF) then return end

                        -- Buscar gun actualizado
                        local gun2 = nil
                        for _, tool in ipairs(c2:GetChildren()) do
                            if tool:IsA("Tool") and (
                                tool.Name == "DefaultGun"
                                or tool:FindFirstChild("GunClient")
                                or tool:FindFirstChild("GunServer")) then
                                gun2 = tool; break
                            end
                        end
                        if not gun2 then
                            gun2 = _findGunIn and _findGunIn(c2)
                        end
                        if not gun2 then return end

                        local shootRem2 = gun2:FindFirstChild("Shoot")
                        if not (shootRem2 and shootRem2:IsA("RemoteEvent")) then
                            local gs2 = gun2:FindFirstChild("GunServer")
                            if gs2 then
                                local gsS = gs2:FindFirstChild("Shoot")
                                if gsS and gsS:IsA("RemoteEvent") then shootRem2 = gsS end
                            end
                        end
                        if not (shootRem2 and shootRem2:IsA("RemoteEvent")) and getShootRemote then
                            shootRem2 = getShootRemote(gun2)
                        end

                        if shootRem2 and shootRem2:IsA("RemoteEvent") then
                            _shotFired = true
                            if CombatTabState then CombatTabState._saBypassHook = true end
                            pcall(function() shootRem2:FireServer(finalGraCF, finalTargetCF) end)
                            if CombatTabState then CombatTabState._saBypassHook = false end
                            CreateCustomNotification("SILENT AIM", "-> " .. target.Name, 1.2)
                        elseif _fireGunMM2 then
                            _shotFired = true
                            if CombatTabState then CombatTabState._saBypassHook = true end
                            _fireGunMM2(gun2, finalTargetCF)
                            if CombatTabState then CombatTabState._saBypassHook = false end
                        end
                    end

                    -- Cada heartbeat: mantenerse detras del murder y disparar
                    _loopConn = RS2.Heartbeat:Connect(function()
                        if not _smActive then
                            _loopConn:Disconnect()
                            return
                        end
                        -- Verificar que el murder y nuestro personaje siguen vivos
                        local c3 = LocalPlayer.Character
                        local h3 = c3 and c3:FindFirstChild("HumanoidRootPart")
                        local hm3 = c3 and c3:FindFirstChildOfClass("Humanoid")
                        if not h3 or not hm3 or hm3.Health <= 0 then
                            _smActive = false
                            _loopConn:Disconnect()
                            return
                        end
                        if not tHRP or not tHRP.Parent or not tChar.Parent then
                            _smActive = false
                            _loopConn:Disconnect()
                            pcall(function() h3.CFrame = savedCF end)
                            return
                        end
                        -- TRACKING: mantenerse a 5 studs detras del murder
                        pcall(function()
                            h3.CFrame = _getTpBehindMurder()
                        end)
                        -- SILENT AIM: disparar una vez
                        _doSilentShot()
                    end)

                    -- Esperar a que el disparo ocurra, luego volver a savedCF
                    local _waited = 0
                    while _smActive and not _shotFired and _waited < 5 do
                        task.wait(0.05)
                        _waited = _waited + 0.05
                    end

                    -- Detener el loop
                    _smActive = false
                    pcall(function() if _loopConn then _loopConn:Disconnect() end end)
                    pcall(function() if _smConn_gunshot then _smConn_gunshot:Disconnect() end end)

                    -- [6] TP a posicion guardada (la de antes de apretar el boton)
                    local c4 = LocalPlayer.Character
                    local h4 = c4 and c4:FindFirstChild("HumanoidRootPart")
                    if h4 then
                        pcall(function() h4.CFrame = savedCF end)
                    end

                    if _wasInBackpack then
                        local c5 = LocalPlayer.Character
                        local hm5 = c5 and c5:FindFirstChildOfClass("Humanoid")
                        if hm5 and hm5.Parent then
                            task.delay(0.17, function()
                                pcall(function() hm5:UnequipTools() end)
                            end)
                        end
                    end
                end)
            end
                        -- FIX MOBILE v4: Activated cubre PC (MouseButton1Click) y touch en un solo evento
            shootBtnGui.Frame.Activated:Connect(_doShootMurderer)
        end
    else
        if shootBtnGui then
            shootBtnGui:Destroy()
            shootBtnGui = nil
        end
    end

end

function CreateNebulaSelector(parent, titulo, opciones, default, callback)
    -- ==============================================================
    --  SELECTOR v8 -- colores del hub (ThemeColors) + dropdown
    --  animado con apertura/cierre LENTO (Quint 0.55s)
    --  Layout push-down: la lista empuja los elementos inferiores.
    --  Fila cabecera: Titulo izquierda | Badge pill con opcion + "v"
    -- ==============================================================
    local TWEEN_OPEN  = TweenInfo.new(0.55, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local TWEEN_CLOSE = TweenInfo.new(0.42, Enum.EasingStyle.Quint, Enum.EasingDirection.In)

    local ROW_H    = 30
    local HEADER_H = 58
    local GAP      = 4
    local MAX_ROWS = 5

    -- Colores vivos del hub (referencia global ThemeColors)
    local function C(key) return ThemeColors[key] end

    -- SELECTOR REDISE?ADO: glassmorphism ultra-transparente, estilo USE
    -- Cabecera: una sola fila horizontal con titulo + bot?n selector a la derecha
    local masterFrame = Instance.new("Frame", parent)
    masterFrame.Name             = "NebulaSelector_" .. titulo
    masterFrame.Size             = UDim2.new(1, 0, 0, HEADER_H)
    masterFrame.AutomaticSize    = Enum.AutomaticSize.None
    masterFrame.BackgroundColor3 = Color3.fromRGB(3, 10, 22)
    masterFrame.BackgroundTransparency = 0.45   -- muy transparente de base
    masterFrame.BorderSizePixel  = 0
    masterFrame.ClipsDescendants = false
    masterFrame.ZIndex           = 5
    -- Esquinas poco redondeadas, aspecto rectangular (estilo USE)
    local mCorner = Instance.new("UICorner", masterFrame)
    mCorner.CornerRadius = UDim.new(0, 6)
    -- Borde cian fino brillante
    local mStroke = Instance.new("UIStroke", masterFrame)
    mStroke.Color           = Color3.fromRGB(0, 210, 240)
    mStroke.Thickness       = 1.6
    mStroke.Transparency    = 0.20
    mStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local _mStrokeGrad = Instance.new("UIGradient", mStroke)
    _mStrokeGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(0, 220, 255)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0, 160, 200)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(0, 220, 255)),
    })
    _mStrokeGrad.Rotation = 90
    -- Gradiente de fondo sutil
    local _mBgGrad = Instance.new("UIGradient", masterFrame)
    _mBgGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(6, 18, 40)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(3,  10, 24)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(6, 18, 40)),
    })
    _mBgGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,   0.55),
        NumberSequenceKeypoint.new(0.5, 0.45),
        NumberSequenceKeypoint.new(1,   0.55),
    })
    _mBgGrad.Rotation = 90

    -- Titulo (izquierda)
    local titleLabel = Instance.new("TextLabel", masterFrame)
    titleLabel.Size                   = UDim2.new(0.52, -12, 0, HEADER_H)
    titleLabel.Position               = UDim2.new(0, 12, 0, 0)
    titleLabel.BackgroundTransparency = 1
    titleLabel.Text                   = titulo
    titleLabel.TextColor3             = Color3.fromRGB(180, 230, 255)
    titleLabel.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    titleLabel.TextSize               = 11
    titleLabel.TextXAlignment         = Enum.TextXAlignment.Left
    titleLabel.TextYAlignment         = Enum.TextYAlignment.Center
    titleLabel.TextTruncate           = Enum.TextTruncate.AtEnd
    titleLabel.ZIndex                 = 6

    -- Boton selector derecha: rectangular, esquinas 4px, glassmorphism + borde cian
    local triggerBtn = Instance.new("TextButton", masterFrame)
    triggerBtn.Name                   = "TriggerBadge"
    triggerBtn.Size                   = UDim2.new(0.46, 0, 0, 26)
    triggerBtn.AnchorPoint            = Vector2.new(1, 0)
    triggerBtn.Position               = UDim2.new(1, -8, 0, (HEADER_H - 26) / 2)
    triggerBtn.BackgroundColor3       = Color3.fromRGB(4, 16, 32)
    triggerBtn.BackgroundTransparency = 0.30
    triggerBtn.Text                   = ""
    triggerBtn.BorderSizePixel        = 0
    triggerBtn.AutoButtonColor        = false
    triggerBtn.ZIndex                 = 7
    -- Esquinas cuadradas (rectangulo estilo USE)
    local tCorner = Instance.new("UICorner", triggerBtn)
    tCorner.CornerRadius = UDim.new(0, 4)
    local tStroke = Instance.new("UIStroke", triggerBtn)
    tStroke.Color           = Color3.fromRGB(0, 200, 230)
    tStroke.Thickness       = 1.4
    tStroke.Transparency    = 0.15
    tStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    local selectedText = Instance.new("TextLabel", triggerBtn)
    selectedText.Size                   = UDim2.new(1, -22, 1, 0)
    selectedText.Position               = UDim2.new(0, 8, 0, 0)
    selectedText.Text                   = default
    selectedText.TextColor3             = Color3.fromRGB(160, 240, 255)
    selectedText.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    selectedText.TextSize               = 10
    selectedText.BackgroundTransparency = 1
    selectedText.TextXAlignment         = Enum.TextXAlignment.Left
    selectedText.TextTruncate           = Enum.TextTruncate.AtEnd
    selectedText.TextYAlignment         = Enum.TextYAlignment.Center
    selectedText.ZIndex                 = 8

    local arrow = Instance.new("TextLabel", triggerBtn)
    arrow.Size                   = UDim2.new(0, 16, 1, 0)
    arrow.AnchorPoint            = Vector2.new(1, 0.5)
    arrow.Position               = UDim2.new(1, -4, 0.5, 0)
    arrow.Text                   = "v"
    arrow.TextColor3             = Color3.fromRGB(0, 220, 255)
    arrow.BackgroundTransparency = 1
    arrow.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    arrow.TextSize               = 11
    arrow.TextXAlignment         = Enum.TextXAlignment.Center
    arrow.TextYAlignment         = Enum.TextYAlignment.Center
    arrow.ZIndex                 = 9

    -- Lista dropdown: TRANSPARENCIA FULL al abrir (BackgroundTransparency = 1, solo borde visible)
    local listFrame = Instance.new("ScrollingFrame", masterFrame)
    listFrame.Name                   = "ListContainer"
    listFrame.Size                   = UDim2.new(1, 0, 0, 0)
    listFrame.Position               = UDim2.new(0, 0, 0, HEADER_H + GAP)
    listFrame.BackgroundColor3       = Color3.fromRGB(4, 12, 26)
    listFrame.BackgroundTransparency = 1.0     -- FULL TRANSPARENTE al abrir
    listFrame.BorderSizePixel        = 0
    listFrame.ClipsDescendants       = true
    listFrame.Visible                = false
    listFrame.ScrollBarThickness     = 2
    listFrame.ScrollBarImageColor3   = Color3.fromRGB(0, 200, 240)
    listFrame.CanvasSize             = UDim2.new(0, 0, 0, #opciones * (ROW_H + 3) + 10)
    listFrame.ScrollingDirection     = Enum.ScrollingDirection.Y
    listFrame.ElasticBehavior        = Enum.ElasticBehavior.Never
    listFrame.ZIndex                 = 50
    -- Esquinas poco redondeadas (estilo USE)
    Instance.new("UICorner", listFrame).CornerRadius = UDim.new(0, 5)
    -- Solo borde, sin fondo (efecto full transparente)
    local listStroke = Instance.new("UIStroke", listFrame)
    listStroke.Color           = Color3.fromRGB(0, 210, 240)
    listStroke.Thickness       = 1.4
    listStroke.Transparency    = 0.18
    listStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    local listPad = Instance.new("UIPadding", listFrame)
    listPad.PaddingTop    = UDim.new(0, 5)
    listPad.PaddingBottom = UDim.new(0, 5)
    listPad.PaddingLeft   = UDim.new(0, 4)
    listPad.PaddingRight  = UDim.new(0, 4)

    local listLayout = Instance.new("UIListLayout", listFrame)
    listLayout.SortOrder           = Enum.SortOrder.LayoutOrder
    listLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    listLayout.Padding             = UDim.new(0, 3)

    -- Estado
    local isOpen        = false
    local selectedValue = default
    local optionBtns    = {}
    local _locked       = false
    local _animating    = false

    local function listOpenHeight()
        return math.min(#opciones, MAX_ROWS) * (ROW_H + 3) + 10
    end

    local function refreshIndicators()
        for _, wrapper in ipairs(optionBtns) do
            local row    = wrapper:FindFirstChildWhichIsA("TextButton")
            if not row then continue end
            local stroke  = row:FindFirstChildWhichIsA("UIStroke")
            local rowLbl  = row:FindFirstChild("OptionLabel")
            local active  = (wrapper.Name == selectedValue)
            -- Activo: semi-transparente cian; inactivo: full transparente
            TweenService:Create(row, TweenInfo.new(0.18), {
                BackgroundColor3       = active and Color3.fromRGB(0, 100, 130) or Color3.fromRGB(4, 12, 26),
                BackgroundTransparency = active and 0.55 or 1.0,
            }):Play()
            if stroke then
                TweenService:Create(stroke, TweenInfo.new(0.18), {
                    Color        = active and Color3.fromRGB(0, 220, 255) or Color3.fromRGB(0, 180, 210),
                    Transparency = active and 0 or 0.55,
                    Thickness    = active and 1.6 or 0.8,
                }):Play()
            end
            if rowLbl then
                TweenService:Create(rowLbl, TweenInfo.new(0.18), {
                    TextColor3 = active and Color3.fromRGB(0, 230, 255) or Color3.fromRGB(160, 220, 240),
                }):Play()
            end
        end
    end

    local function openList()
        if _animating then return end
        _animating = true
        isOpen = true
        arrow.Text = "^"
        listFrame.Visible = true
        -- Fondo full transparente al abrir (solo el borde es visible)
        listFrame.BackgroundTransparency = 1.0
        local targetH = listOpenHeight()
        -- masterFrame crece para empujar layout
        TweenService:Create(masterFrame, TWEEN_OPEN, {
            Size = UDim2.new(1, 0, 0, HEADER_H + GAP + targetH),
            BackgroundTransparency = 0.60,   -- mas transparente al abrir
        }):Play()
        TweenService:Create(listFrame, TWEEN_OPEN, {
            Size = UDim2.new(1, 0, 0, targetH)
        }):Play()
        TweenService:Create(tStroke, TWEEN_OPEN, {Transparency = 0.0, Thickness = 2.0}):Play()
        TweenService:Create(triggerBtn, TWEEN_OPEN, {BackgroundTransparency = 0.10}):Play()
        task.delay(0.55, function() _animating = false end)
    end

    local function closeList()
        if _animating then return end
        _animating = true
        isOpen = false
        arrow.Text = "v"
        TweenService:Create(masterFrame, TWEEN_CLOSE, {
            Size = UDim2.new(1, 0, 0, HEADER_H),
            BackgroundTransparency = 0.45,
        }):Play()
        TweenService:Create(listFrame, TWEEN_CLOSE, {
            Size = UDim2.new(1, 0, 0, 0)
        }):Play()
        TweenService:Create(tStroke, TWEEN_CLOSE, {Transparency = 0.20, Thickness = 1.4}):Play()
        TweenService:Create(triggerBtn, TWEEN_CLOSE, {BackgroundTransparency = 0.30}):Play()
        task.delay(0.42, function()
            listFrame.Visible = false
            _animating = false
        end)
    end

    -- Hover del boton selector (estilo USE)
    triggerBtn.MouseEnter:Connect(function()
        TweenService:Create(triggerBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.05, BackgroundColor3 = Color3.fromRGB(6, 24, 46)}):Play()
        TweenService:Create(tStroke, TweenInfo.new(0.15), {Color = Color3.fromRGB(0, 240, 255), Thickness = 2.0, Transparency = 0.0}):Play()
        TweenService:Create(selectedText, TweenInfo.new(0.12), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play()
    end)
    triggerBtn.MouseLeave:Connect(function()
        TweenService:Create(triggerBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.30, BackgroundColor3 = Color3.fromRGB(4, 16, 32)}):Play()
        TweenService:Create(tStroke, TweenInfo.new(0.15), {Color = Color3.fromRGB(0, 200, 230), Thickness = 1.4, Transparency = 0.15}):Play()
        TweenService:Create(selectedText, TweenInfo.new(0.12), {TextColor3 = Color3.fromRGB(160, 240, 255)}):Play()
    end)

    -- FIX MOBILE: usar Activated en vez de MouseButton1Click para que funcione en touch
    triggerBtn.Activated:Connect(function()
        if _locked then return end
        if isOpen then closeList() else openList() end
    end)

    -- Construir opciones
    local function buildOptions(opts)
        for _, b in ipairs(optionBtns) do b:Destroy() end
        optionBtns = {}
        listFrame.CanvasSize = UDim2.new(0, 0, 0, #opts * (ROW_H + 3) + 10)

        for i, name in ipairs(opts) do
            local isActive = (name == selectedValue)

            local wrapper = Instance.new("Frame", listFrame)
            wrapper.Name                   = name
            wrapper.Size                   = UDim2.new(1, -4, 0, ROW_H)
            wrapper.BackgroundTransparency = 1
            wrapper.BorderSizePixel        = 0
            wrapper.LayoutOrder            = i
            wrapper.ZIndex                 = 51

            -- Filas del dropdown: full transparentes, solo borde visible
            local row = Instance.new("TextButton", wrapper)
            row.Size                   = UDim2.new(1, 0, 1, 0)
            row.BackgroundColor3       = isActive and Color3.fromRGB(0, 100, 130) or Color3.fromRGB(4, 12, 26)
            row.BackgroundTransparency = isActive and 0.55 or 1.0   -- activo: semi-visible; inactivo: full transparente
            row.Text                   = ""
            row.BorderSizePixel        = 0
            row.AutoButtonColor        = false
            row.ZIndex                 = 51
            -- Esquinas rectangulares (estilo USE)
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 4)

            local cardStroke = Instance.new("UIStroke", row)
            cardStroke.Color           = isActive and Color3.fromRGB(0, 220, 255) or Color3.fromRGB(0, 180, 210)
            cardStroke.Thickness       = isActive and 1.6 or 0.8
            cardStroke.Transparency    = isActive and 0 or 0.55
            cardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            local lbl = Instance.new("TextLabel", row)
            lbl.Name                   = "OptionLabel"
            lbl.Size                   = UDim2.new(1, -10, 1, 0)
            lbl.Position               = UDim2.new(0, 8, 0, 0)
            lbl.Text                   = convertirFuenteCursor(name)
            lbl.TextColor3             = isActive and Color3.fromRGB(0, 230, 255) or Color3.fromRGB(160, 220, 240)
            lbl.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
            lbl.TextSize               = 10
            lbl.TextXAlignment         = Enum.TextXAlignment.Left
            lbl.TextYAlignment         = Enum.TextYAlignment.Center
            lbl.BackgroundTransparency = 1
            lbl.ZIndex                 = 52

            row.MouseEnter:Connect(function()
                if name ~= selectedValue then
                    TweenService:Create(row, TweenInfo.new(0.12), {
                        BackgroundColor3       = Color3.fromRGB(0, 80, 110),
                        BackgroundTransparency = 0.60,
                    }):Play()
                    TweenService:Create(cardStroke, TweenInfo.new(0.12), {Transparency = 0.20, Thickness = 1.4}):Play()
                    TweenService:Create(lbl, TweenInfo.new(0.12), {TextColor3 = Color3.fromRGB(220, 245, 255)}):Play()
                end
            end)
            row.MouseLeave:Connect(function()
                if name ~= selectedValue then
                    TweenService:Create(row, TweenInfo.new(0.12), {
                        BackgroundColor3       = Color3.fromRGB(4, 12, 26),
                        BackgroundTransparency = 1.0,
                    }):Play()
                    TweenService:Create(cardStroke, TweenInfo.new(0.12), {Transparency = 0.55, Thickness = 0.8}):Play()
                    TweenService:Create(lbl, TweenInfo.new(0.12), {TextColor3 = Color3.fromRGB(160, 220, 240)}):Play()
                end
            end)

            -- FIX MOBILE: Activated funciona tanto en PC como en touch
            row.Activated:Connect(function()
                if _locked then return end
                selectedValue     = name
                selectedText.Text = name
                refreshIndicators()
                if callback then callback(name) end
                closeList()
            end)

            table.insert(optionBtns, wrapper)
        end
    end

    buildOptions(opciones)

    return {
        frame        = masterFrame,
        GetValue     = function() return selectedValue end,
        SetValue     = function(newVal)
            selectedValue     = newVal
            selectedText.Text = newVal
            refreshIndicators()
        end,
        SetOptions   = function(newOpts, newDefault)
            opciones      = newOpts
            selectedValue = newDefault or newOpts[1]
            selectedText.Text = selectedValue
            buildOptions(newOpts)
        end,
        Lock         = function() _locked = true  end,
        Unlock       = function() _locked = false end,
    }
end

-- ==========================================================================
-- CreatePredSelector -- glassmorphism azul indigo (mismo estilo que NebulaSelector)
-- ==========================================================================
function CreatePredSelector(parent, titulo, opciones, default, callback)
    -- Colores glassmorphism -- paleta nocturna
    local COL_BG_HEADER  = ThemeColors.Background    -- ?ndigo visible
    local COL_BG_LIST    = ThemeColors.Secondary     -- azul noche
    local COL_BG_BADGE   = ThemeColors.Primary  -- azul estrella
    local COL_STROKE     = ThemeColors.TextPrimary  -- blanco estrella
    local COL_STROKE_ROW = ThemeColors.Primary  -- azul estrella
    local COL_TEXT       = ThemeColors.TextPrimary  -- blanco azulado
    local COL_ROW_ACTIVE = ThemeColors.Primary  -- azul estrella
    local COL_ROW_IDLE   = ThemeColors.Background    -- ?ndigo visible

    local BTN_H      = 34
    local OPT_H      = 36
    local HEADER_H   = 58

    local selectedValue = default or opciones[1]
    local isOpen        = false

    -- -- HEADER CONTAINER ----------------------------------------------------
    local headerFrame = Instance.new("Frame", parent)
    headerFrame.Name                   = "PredSelector_" .. titulo
    headerFrame.Size                   = UDim2.new(1, 0, 0, HEADER_H)
    headerFrame.BackgroundColor3       = COL_BG_HEADER
    headerFrame.BackgroundTransparency = 0.15
    headerFrame.BorderSizePixel        = 0
    headerFrame.ClipsDescendants       = false
    headerFrame.ZIndex                 = 10
    Instance.new("UICorner", headerFrame).CornerRadius = UDim.new(0, 10)
    local headerStroke = Instance.new("UIStroke", headerFrame)
    headerStroke.Color           = COL_STROKE
    headerStroke.Thickness       = 2
    headerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Titulo a la izquierda
    local titleLbl = Instance.new("TextLabel", headerFrame)
    titleLbl.Size                   = UDim2.new(0.50, -12, 1, 0)
    titleLbl.Position               = UDim2.new(0, 12, 0, 0)
    titleLbl.Text                   = titulo
    titleLbl.TextColor3             = COL_TEXT
    titleLbl.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    titleLbl.TextSize               = 13
    titleLbl.BackgroundTransparency = 1
    titleLbl.TextXAlignment         = Enum.TextXAlignment.Left
    titleLbl.TextYAlignment         = Enum.TextYAlignment.Center
    titleLbl.TextTruncate           = Enum.TextTruncate.AtEnd
    titleLbl.ZIndex                 = 11

    -- Badge-boton a la derecha
    local trigBtn = Instance.new("TextButton", headerFrame)
    trigBtn.Name                   = "TrigBtn"
    trigBtn.Size                   = UDim2.new(0.48, 0, 0, BTN_H)
    trigBtn.AnchorPoint            = Vector2.new(1, 0.5)
    trigBtn.Position               = UDim2.new(1, -10, 0.5, 0)
    trigBtn.BackgroundColor3       = COL_BG_BADGE
    trigBtn.BackgroundTransparency = 0.05
    trigBtn.Text                   = ""
    trigBtn.BorderSizePixel        = 0
    trigBtn.AutoButtonColor        = false
    trigBtn.ZIndex                 = 12
    Instance.new("UICorner", trigBtn).CornerRadius = UDim.new(0, 8)
    local trigStroke = Instance.new("UIStroke", trigBtn)
    trigStroke.Color           = COL_STROKE
    trigStroke.Thickness       = 2
    trigStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Valor actual dentro del badge
    local valLbl = Instance.new("TextLabel", trigBtn)
    valLbl.Size                   = UDim2.new(1, -26, 1, 0)
    valLbl.Position               = UDim2.new(0, 8, 0, 0)
    valLbl.Text                   = selectedValue
    valLbl.TextColor3             = COL_TEXT
    valLbl.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    valLbl.TextSize               = 12
    valLbl.BackgroundTransparency = 1
    valLbl.TextXAlignment         = Enum.TextXAlignment.Left
    valLbl.TextTruncate           = Enum.TextTruncate.AtEnd
    valLbl.TextYAlignment         = Enum.TextYAlignment.Center
    valLbl.ZIndex                 = 13

    -- Flecha
    local arrowLbl = Instance.new("TextLabel", trigBtn)
    arrowLbl.Size                   = UDim2.new(0, 22, 1, 0)
    arrowLbl.AnchorPoint            = Vector2.new(1, 0.5)
    arrowLbl.Position               = UDim2.new(1, -4, 0.5, 0)
    arrowLbl.Text                   = "^"
    arrowLbl.TextColor3             = COL_TEXT
    arrowLbl.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    arrowLbl.TextSize               = 13
    arrowLbl.BackgroundTransparency = 1
    arrowLbl.TextXAlignment         = Enum.TextXAlignment.Center
    arrowLbl.TextYAlignment         = Enum.TextYAlignment.Center
    arrowLbl.ZIndex                 = 13

    -- Hover en el badge
    trigBtn.MouseEnter:Connect(function()
        TweenService:Create(trigBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.20}):Play()
        TweenService:Create(trigStroke, TweenInfo.new(0.15), {Color = ThemeColors.Accent}):Play()
    end)
    trigBtn.MouseLeave:Connect(function()
        TweenService:Create(trigBtn, TweenInfo.new(0.15), {BackgroundTransparency = 1}):Play()
        TweenService:Create(trigStroke, TweenInfo.new(0.15), {Color = COL_STROKE}):Play()
    end)

    -- -- LISTA DESPLEGABLE -------------------------------------------------
    local dropFrame = Instance.new("Frame", headerFrame)
    dropFrame.Name                   = "DropFrame"
    dropFrame.Size                   = UDim2.fromOffset(0, 0)
    dropFrame.AnchorPoint            = Vector2.new(0, 0)
    dropFrame.Position               = UDim2.fromOffset(0, 0)
    dropFrame.BackgroundColor3       = ThemeColors.Background
    dropFrame.BackgroundTransparency = 1
    dropFrame.BorderSizePixel        = 0
    dropFrame.ClipsDescendants       = true
    dropFrame.Visible                = false
    dropFrame.ZIndex                 = 9999
    Instance.new("UICorner", dropFrame).CornerRadius = UDim.new(0, 10)
    local dropStroke = Instance.new("UIStroke", dropFrame)
    dropStroke.Color           = COL_STROKE
    dropStroke.Thickness       = 2.5
    dropStroke.Transparency    = 0
    dropStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    local _dropPad = Instance.new("UIPadding", dropFrame)
    _dropPad.PaddingTop    = UDim.new(0, 5)
    _dropPad.PaddingBottom = UDim.new(0, 5)
    _dropPad.PaddingLeft   = UDim.new(0, 4)
    _dropPad.PaddingRight  = UDim.new(0, 4)

    local dropList = Instance.new("UIListLayout", dropFrame)
    dropList.SortOrder     = Enum.SortOrder.LayoutOrder
    dropList.FillDirection = Enum.FillDirection.Vertical
    dropList.Padding       = UDim.new(0, 4)
    dropList.HorizontalAlignment = Enum.HorizontalAlignment.Center

    local totalDropH = #opciones * (OPT_H + 4) + 10

    -- FIX: guardar referencia al ScreenGui
    local _cachedSG = nil
    local function _getSG()
        if _cachedSG and _cachedSG.Parent then return _cachedSG end
        local p = headerFrame.Parent
        while p do
            if p:IsA("ScreenGui") then _cachedSG = p; return p end
            p = p.Parent
        end
        return nil
    end

    local _openUpward = false

    local function _openDrop()
        local sg = _getSG()
        if not sg then return end
        local absTrig  = trigBtn.AbsolutePosition
        local absTrigS = trigBtn.AbsoluteSize
        local dropW    = headerFrame.AbsoluteSize.X
        local dropH    = totalDropH
        local ok, res  = pcall(function() return game:GetService("GuiService"):GetScreenResolution() end)
        local screenH  = (ok and res) and res.Y or 600
        local spaceBelow = screenH - (absTrig.Y + absTrigS.Y)
        _openUpward = (spaceBelow < dropH + 8) and (absTrig.Y > dropH)
        local dropX  = headerFrame.AbsolutePosition.X
        local dropY  = _openUpward
            and (headerFrame.AbsolutePosition.Y - dropH - 4)
            or  (headerFrame.AbsolutePosition.Y + HEADER_H + 4)
        dropFrame.Parent      = sg
        dropFrame.AnchorPoint = Vector2.new(0, 0)
        dropFrame.ZIndex      = 9999
        if _openUpward then
            dropFrame.Size     = UDim2.fromOffset(dropW, 0)
            dropFrame.Position = UDim2.fromOffset(dropX, headerFrame.AbsolutePosition.Y - 4)
            dropFrame.Visible  = true
            TweenService:Create(dropFrame, TweenInfo.new(0.55, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                {Size = UDim2.fromOffset(dropW, dropH),
                 Position = UDim2.fromOffset(dropX, dropY)}):Play()
        else
            dropFrame.Size     = UDim2.fromOffset(dropW, 0)
            dropFrame.Position = UDim2.fromOffset(dropX, dropY)
            dropFrame.Visible  = true
            TweenService:Create(dropFrame, TweenInfo.new(0.55, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                {Size = UDim2.fromOffset(dropW, dropH)}):Play()
        end
        arrowLbl.Text = "v"
    end

    local function _closeDrop()
        local dropW = math.max(dropFrame.AbsoluteSize.X, 10)
        TweenService:Create(dropFrame, TweenInfo.new(0.38, Enum.EasingStyle.Quint),
            {Size = UDim2.fromOffset(dropW, 0)}):Play()
        arrowLbl.Text = "^"
        task.delay(0.40, function()
            if not isOpen then
                dropFrame.Visible = false
                dropFrame.Parent      = headerFrame
                dropFrame.AnchorPoint = Vector2.new(0, 0)
                dropFrame.Size        = UDim2.fromOffset(0, 0)
                dropFrame.Position    = UDim2.fromOffset(0, 0)
            end
        end)
    end

    -- Construir opciones con estilo glassmorphism
    local optBtns = {}
    for i, name in ipairs(opciones) do
        local isActive = (name == selectedValue)

        local optBtn = Instance.new("TextButton", dropFrame)
        optBtn.Name                   = "Opt_" .. name
        optBtn.Size                   = UDim2.new(1, -4, 0, OPT_H)
        optBtn.BackgroundColor3       = isActive and COL_ROW_ACTIVE or COL_ROW_IDLE
        optBtn.BackgroundTransparency = isActive and 0.10 or 0.20
        optBtn.Text                   = ""
        optBtn.BorderSizePixel        = 0
        optBtn.AutoButtonColor        = false
        optBtn.LayoutOrder            = i
        optBtn.ZIndex                 = 31
        Instance.new("UICorner", optBtn).CornerRadius = UDim.new(0, 8)
        local optStroke = Instance.new("UIStroke", optBtn)
        optStroke.Color           = isActive and ThemeColors.Accent or COL_STROKE_ROW
        optStroke.Thickness       = isActive and 2 or 1.5
        optStroke.Transparency    = isActive and 0 or 0.3
        optStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local optLbl = Instance.new("TextLabel", optBtn)
        optLbl.Size                   = UDim2.new(1, 0, 1, 0)
        optLbl.Text                   = name
        optLbl.TextColor3             = COL_TEXT
        optLbl.FontFace               = Font.fromEnum(isActive and Enum.Font.GothamBold or Enum.Font.GothamSemibold)
        optLbl.TextSize               = 13
        optLbl.BackgroundTransparency = 1
        optLbl.TextXAlignment         = Enum.TextXAlignment.Center
        optLbl.TextYAlignment         = Enum.TextYAlignment.Center
        optLbl.ZIndex                 = 32

        table.insert(optBtns, {name = name, btn = optBtn, lbl = optLbl, stroke = optStroke})

        -- Glitch ultra rapido: parpadeo de borde teal aleatorio
        task.spawn(function()
            while optBtn and optBtn.Parent do
                task.wait(math.random(1, 3) + math.random() * 0.5)
                if not optBtn.Parent then break end
                pcall(function()
                    optStroke.Transparency = 0
                    optStroke.Thickness    = 2.5
                    optStroke.Color        = ThemeColors.Primary
                end)
                task.wait(0.03)
                pcall(function()
                    optStroke.Transparency = 0.8
                    optStroke.Thickness    = 1
                end)
                task.wait(0.02)
                pcall(function()
                    optStroke.Transparency = 0
                    optStroke.Thickness    = 2
                end)
                task.wait(0.025)
                local isAct = (name == selectedValue)
                pcall(function()
                    optStroke.Color        = isAct and ThemeColors.Accent or COL_STROKE_ROW
                    optStroke.Thickness    = isAct and 2 or 1.5
                    optStroke.Transparency = isAct and 0 or 0.3
                end)
            end
        end)

        optBtn.MouseEnter:Connect(function()
            if name ~= selectedValue then
                TweenService:Create(optBtn, TweenInfo.new(0.08), {
                    BackgroundColor3 = ThemeColors.Secondary,
                    BackgroundTransparency = 0.48,
                }):Play()
                TweenService:Create(optStroke, TweenInfo.new(0.08),
                    {Transparency = 0.1, Color = ThemeColors.Accent}):Play()
            end
        end)
        optBtn.MouseLeave:Connect(function()
            if name ~= selectedValue then
                TweenService:Create(optBtn, TweenInfo.new(0.08), {
                    BackgroundColor3 = COL_ROW_IDLE,
                    BackgroundTransparency = 0.10,
                }):Play()
                TweenService:Create(optStroke, TweenInfo.new(0.08),
                    {Transparency = 0.3, Color = COL_STROKE_ROW}):Play()
            end
        end)
        optBtn.Activated:Connect(function()
            if selectedValue ~= name then
                selectedValue = name
                for _, info in ipairs(optBtns) do
                    local act = (info.name == name)
                    TweenService:Create(info.btn, TweenInfo.new(0.12), {
                        BackgroundColor3       = act and COL_ROW_ACTIVE or COL_ROW_IDLE,
                        BackgroundTransparency = act and 0.10 or 0.20,
                    }):Play()
                    info.lbl.FontFace  = Font.fromEnum(act and Enum.Font.GothamBold or Enum.Font.GothamSemibold)
                    info.stroke.Color       = act and ThemeColors.Accent or COL_STROKE_ROW
                    info.stroke.Thickness   = act and 2 or 1.5
                    info.stroke.Transparency = act and 0 or 0.3
                end
                valLbl.Text = name
                if callback then callback(name) end
            end
            isOpen = false
            _closeDrop()
        end)
    end

    -- Abrir/cerrar
    trigBtn.Activated:Connect(function()
        isOpen = not isOpen
        if isOpen then _openDrop() else _closeDrop() end
    end)

    return {
        getValue = function() return selectedValue end,
        setValue = function(v)
            for _, info in ipairs(optBtns) do
                if info.name == v then
                    selectedValue = v
                    valLbl.Text   = v
                    for _, inf2 in ipairs(optBtns) do
                        local act = (inf2.name == v)
                        inf2.btn.BackgroundColor3       = act and COL_ROW_ACTIVE or COL_ROW_IDLE
                        inf2.btn.BackgroundTransparency = act and 0.10 or 0.20
                        inf2.lbl.FontFace  = Font.fromEnum(act and Enum.Font.GothamBold or Enum.Font.GothamSemibold)
                        inf2.stroke.Color       = act and ThemeColors.Accent or COL_STROKE_ROW
                        inf2.stroke.Thickness   = act and 2 or 1.5
                        inf2.stroke.Transparency = act and 0 or 0.3
                    end
                    break
                end
            end
        end,
    }
end

function ToggleFly(enabled)
    Settings.movement.fly.enabled = enabled
    local character = LocalPlayer.Character
    if not character then return end
    local hrp = character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    if Settings.connections.fly then
        Settings.connections.fly:Disconnect()
        Settings.connections.fly = nil
    end
    if enabled then
        local bv = Instance.new("BodyVelocity")
        bv.MaxForce = Vector3.new(100000, 100000, 100000)
        bv.Velocity = Vector3.zero
        bv.Parent = hrp
        local bg = Instance.new("BodyGyro")
        bg.MaxTorque = Vector3.new(100000, 100000, 100000)
        bg.P = 10000
        bg.Parent = hrp
        -- MOBILE SUPPORT UseTab fly
        local _utFlyMobile = (function()
            local ok, res = pcall(function() return UserInputService.TouchEnabled end)
            return ok and res
        end)()
        Settings.connections.fly = RunService.Heartbeat:Connect(function()
            if not Settings.movement.fly.enabled or not hrp.Parent then
                if bv then bv:Destroy() end
                if bg then bg:Destroy() end
                if Settings.connections.fly then Settings.connections.fly:Disconnect() end
                return
            end
            local camera = workspace.CurrentCamera
            local moveDir = Vector3.zero
            if _utFlyMobile then
                -- Usar thumbstick del movil
                local _utChar = LocalPlayer.Character
                local _utHum  = _utChar and _utChar:FindFirstChildOfClass("Humanoid")
                if _utHum then
                    local md = _utHum.MoveDirection
                    if md.Magnitude > 0.1 then
                        moveDir = Vector3.new(md.X, 0, md.Z)
                    end
                end
                -- Usar botones del sistema de fly principal si existen
                if _G._flyUpHeld   then moveDir = moveDir + Vector3.new(0,1,0) end
                if _G._flyDownHeld then moveDir = moveDir - Vector3.new(0,1,0) end
            else
                if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                    moveDir = moveDir + camera.CFrame.LookVector
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                    moveDir = moveDir - camera.CFrame.LookVector
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                    moveDir = moveDir - camera.CFrame.RightVector
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                    moveDir = moveDir + camera.CFrame.RightVector
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                    moveDir = moveDir + Vector3.new(0, 1, 0)
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                    moveDir = moveDir - Vector3.new(0, 1, 0)
                end
            end
            bv.Velocity = moveDir * Settings.movement.fly.speed
            bg.CFrame = camera.CFrame
        end)
    else
        for _, obj in pairs(hrp:GetChildren()) do
            if obj:IsA("BodyVelocity") or obj:IsA("BodyGyro") then
                obj:Destroy()
            end
        end
    end
end

function UpdateFlySpeed(value)
    Settings.movement.fly.speed = value
end

function ToggleXray(enabled)
    Settings.xray.enabled = enabled
    -- Helper: devuelve true si 'part' es descendiente de cualquier personaje de jugador
    local function _isAnyPlayerPartRT(part)
        local par = part.Parent
        while par and par ~= workspace do
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Character and p.Character == par then return true end
            end
            par = par.Parent
        end
        return false
    end
    if enabled then
        -- FIX: restaurar props anteriores antes de re-escanear (evitar acumulacion)
        for part, trans in pairs(Settings.xray.originalProps) do
            pcall(function() if part and part.Parent then part.Transparency = trans end end)
        end
        Settings.xray.originalProps = {}
        for _, part in ipairs(workspace:GetDescendants()) do
            pcall(function()
                -- FIX: verificar en tiempo real contra TODOS los personajes actuales
                if part:IsA("BasePart") and not _isAnyPlayerPartRT(part) then
                    if not Settings.xray.originalProps[part] then
                        Settings.xray.originalProps[part] = part.Transparency
                    end
                    part.Transparency = Settings.xray.transparency / 100
                end
            end)
        end
    else
        -- FIX: al restaurar, saltar partes que sean de jugadores para no dejarlos invisibles
        for part, trans in pairs(Settings.xray.originalProps) do
            pcall(function()
                if part and part.Parent and not _isAnyPlayerPartRT(part) then
                    part.Transparency = trans
                end
            end)
        end
        Settings.xray.originalProps = {}
        -- FIX: forzar Transparency=0 en todas las partes de personajes de jugadores
        -- por si alguna qued? afectada de forma indirecta
        for _, p in ipairs(Players:GetPlayers()) do
            local char = p.Character
            if char then
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                        pcall(function()
                            if part.Transparency > 0 and part.Transparency < 1 then
                                -- solo restaurar si fue afectado por xray (transparencia parcial inusual)
                                -- Transparency == 1 puede ser intencional (headless, etc.)
                            end
                        end)
                    end
                end
            end
        end
    end
end

function UpdateXrayTransparency(value)
    Settings.xray.transparency = value
    if Settings.xray.enabled then
        for part, _ in pairs(Settings.xray.originalProps) do
            if part and part.Parent then
                part.Transparency = value / 100
            end
        end
    end
end

