function CreateESP(player)
    if player == LocalPlayer then return end

    local espConnection = nil
    local characterConnection = nil

    function updateESP()
        if not player or not player.Parent then
            if Settings.esp.objects[player] then
                pcall(function() Settings.esp.objects[player]:Destroy() end)
                Settings.esp.objects[player] = nil
            end
            if espConnection then
                espConnection:Disconnect()
                espConnection = nil
            end
            return
        end

        local character = player.Character
        if not character or not character.Parent then
            if Settings.esp.objects[player] then
                pcall(function() Settings.esp.objects[player]:Destroy() end)
                Settings.esp.objects[player] = nil
            end
            return
        end

        local hrp = character:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then
            if Settings.esp.objects[player] then
                pcall(function() Settings.esp.objects[player]:Destroy() end)
                Settings.esp.objects[player] = nil
            end
            return
        end

        local color = Color3.fromRGB(255, 255, 255)
        local shouldShow = false

        if Settings.esp.enabled.Everyone then
            shouldShow = true
        end

        if not shouldShow then
            if Settings.esp.objects[player] then
                pcall(function() Settings.esp.objects[player]:Destroy() end)
                Settings.esp.objects[player] = nil
            end
            return
        end

        if not Settings.esp.objects[player] or not Settings.esp.objects[player].Parent then
            local success = pcall(function()
                local billboard = Instance.new("BillboardGui")
                billboard.Name = "ESP_" .. player.Name
                billboard.Adornee = hrp
                billboard.Size = UDim2.new(0, 100, 0, 50)
                billboard.StudsOffset = Vector3.new(0, 3, 0)
                billboard.AlwaysOnTop = true
                billboard.Parent = hrp

                local nameLabel = Instance.new("TextLabel", billboard)
                nameLabel.Name = "ESP_NameLabel"
                nameLabel.Size = UDim2.new(1, 0, 1, 0)
                nameLabel.BackgroundTransparency = 1
                nameLabel.Text = player.Name
                nameLabel.TextColor3 = color
                nameLabel.TextStrokeTransparency = 0.5
                nameLabel.FontFace = Font.fromEnum(Enum.Font.Arimo)
                nameLabel.TextSize = 14

                Settings.esp.objects[player] = billboard
            end)

            if not success then
                Settings.esp.objects[player] = nil
            end
        else
            pcall(function()
                local billboard = Settings.esp.objects[player]
                if billboard and billboard.Parent and hrp and hrp.Parent then
                    if billboard.Adornee ~= hrp then
                        billboard.Adornee = hrp
                    end
                    if billboard.Parent ~= hrp then
                        billboard.Parent = hrp
                    end

                    local nameLabel = billboard:FindFirstChild("ESP_NameLabel")
                    if nameLabel then
                        nameLabel.TextColor3 = color
                    end
                end
            end)
        end

        if Settings.esp.enabled.DisplayDistance and Settings.esp.objects[player] then
            pcall(function()
                if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") and hrp and hrp.Parent then
                    local distance = (LocalPlayer.Character.HumanoidRootPart.Position - hrp.Position).Magnitude
                    local billboard = Settings.esp.objects[player]
                    if billboard and billboard.Parent then
                        local nameLabel = billboard:FindFirstChild("ESP_NameLabel")
                        if nameLabel then
                            nameLabel.Text = player.Name .. " [" .. math.floor(distance) .. "m]"
                        end
                    end
                end
            end)
        end
    end

    -- FIX REPAINT: threshold 9999 (~166s) era demasiado alto y causaba que el color
    -- no se actualizara cuando cambiaba el rol (Murder detectado, Sheriff muerto, etc.).
    -- Reducido a 18 (~0.3s) para sincronizar colores sin sobrecargar el Heartbeat.
    do local _espTick=0 espConnection = RunService.Heartbeat:Connect(function()
        _espTick=_espTick+1; if _espTick<144 then return end; _espTick=0  -- OPT: 120?144 frames (~2.4s ciclo de color)
        if not (Settings.esp and (Settings.esp.enabled.Everyone or Settings.esp.enabled.MurdererOnly or Settings.esp.enabled.SheriffOnly)) then return end
        pcall(updateESP)
    end) end

    characterConnection = player.CharacterAdded:Connect(function(character)
        task.wait(0.5)
        pcall(updateESP)
    end)

    player.AncestryChanged:Connect(function()
        if not player.Parent then
            if espConnection then
                espConnection:Disconnect()
                espConnection = nil
            end
            if characterConnection then
                characterConnection:Disconnect()
                characterConnection = nil
            end
            if Settings.esp.objects[player] then
                pcall(function() Settings.esp.objects[player]:Destroy() end)
                Settings.esp.objects[player] = nil
            end
        end
    end)
end

function CreateChams(player)
    if player == LocalPlayer then return end

    local chamConnection = nil
    local characterConnection = nil

    local function updateChams()  -- LOCAL: cada jugador tiene su propia closure (fix: era global y se sobreescribia con cada jugador)
        if not player or not player.Parent then
            if Settings.cham.objects[player] then
                pcall(function() Settings.cham.objects[player]:Destroy() end)
                Settings.cham.objects[player] = nil
            end
            return
        end

        local character = player.Character
        if not character or not character.Parent then
            if Settings.cham.objects[player] then
                pcall(function() Settings.cham.objects[player]:Destroy() end)
                Settings.cham.objects[player] = nil
            end
            return
        end

        local color = Color3.fromRGB(255, 255, 255)
        local shouldShow = false

        -- Muertos: solo mostrar si DeadOnly esta activo
        local _dHum = character:FindFirstChildOfClass("Humanoid")
        local _isDead = _dHum and _dHum.Health <= 0
        if _isDead and not Settings.cham.enabled.DeadOnly then
            if Settings.cham.objects[player] then
                pcall(function() Settings.cham.objects[player]:Destroy() end)
                Settings.cham.objects[player] = nil
            end
            return
        end

        -- Color por rol
        local role = "Innocent"
        if     _roleCache.murderer == player then role = "Murderer"
        elseif _roleCache.sheriff  == player then role = "Sheriff"
        elseif _roleCache.hero     == player then role = "Hero"
        end
        if     role == "Murderer"  then color = Color3.fromRGB(255,   0,  40)
        elseif role == "Sheriff"   then color = Color3.fromRGB(  0, 140, 255)
        elseif role == "Hero"      then color = Color3.fromRGB(255, 210,   0)
        else                            color = Color3.fromRGB(  0, 255, 160)  -- Innocent
        end

        -- FIX CHAM FANTASMA: CreateChams usaba Settings.cham.enabled (sistema viejo)
        -- creando Highlights independientes en paralelo con los PieceChams del
        -- instanceLoop (VisualState.cham). Eso causaba highlights fantasma sobre
        -- jugadores que NO debian tenerlos. El sistema correcto es VisualState.cham
        -- gestionado por instanceLoop/updateCham. Esta funcion solo limpia residuos.
        if Settings.cham.objects[player] then
            pcall(function() Settings.cham.objects[player]:Destroy() end)
            Settings.cham.objects[player] = nil
        end
        -- El cham real lo maneja updateCham() via instanceLoop -- no crear Highlights aqui
    end

    -- FIX HEARTBEAT: _chamTick<9999 equivale a ~166s de delay, nunca actualizaba.
    -- Reducido a 9 (~0.15s) para limpiar Highlights residuos de Settings.cham.objects.
    do local _chamTick=0 chamConnection = RunService.Heartbeat:Connect(function()
        _chamTick=_chamTick+1; if _chamTick<90 then return end; _chamTick=0  -- OPT: 72?90 frames (~1.5s ciclo cham)
        if not (VisualState and (VisualState.cham and next(VisualState.cham))) then return end
        pcall(updateChams)
    end) end

    characterConnection = player.CharacterAdded:Connect(function(character)
        task.wait(0.5)
        pcall(updateChams)
    end)

    player.AncestryChanged:Connect(function()
        if not player.Parent then
            if chamConnection then chamConnection:Disconnect() end
            if characterConnection then characterConnection:Disconnect() end
            if Settings.cham.objects[player] then
                pcall(function() Settings.cham.objects[player]:Destroy() end)
                Settings.cham.objects[player] = nil
            end
        end
    end)
end

function CreateESPBox(player)
    if player == LocalPlayer then return end
    -- Limpiar al respawnear
    player.CharacterAdded:Connect(function(character)
        if _G._deathHookDone then _G._deathHookDone[player] = nil end
        if _G._deathHookChar then _G._deathHookChar[player] = nil end
        if player.Character then
            _chamSamplePart[player.Character] = nil
            _chamPartList[player.Character]   = nil
        end
    end)
end

-- Loop principal de Box ESP con soporte por roles (activado desde el toggle en Visuals)
_G._espBoxConn = nil

local _espBoxColors = {
    everyone = Color3.fromRGB(0, 255, 0),    -- verde: todos
    murderer = Color3.fromRGB(255,   0,  40), -- rojo
    sheriff  = Color3.fromRGB(  0, 140, 255),-- azul
    hero     = Color3.fromRGB(255, 210,   0),  -- amarillo
    assassin = Color3.fromRGB(255, 140,   0),  -- naranja
    innocent = Color3.fromRGB(0,   255, 0),  -- verde
}

local function _espBoxGetRole(char)
    if not _roleCache then return "innocent" end
    if _roleCache.murderer and _roleCache.murderer.Character == char then return "murderer" end
    if _roleCache.sheriff  and _roleCache.sheriff.Character  == char then return "sheriff"  end
    if _roleCache.hero     and _roleCache.hero.Character     == char then return "hero"     end
    if _roleCache.assassin and _roleCache.assassin.Character == char then return "assassin" end
    return "innocent"
end

local function _espBoxShouldShow(role)
    local vb = VisualState and VisualState.box
    if not vb then return false end
    if vb.everyone  then return true end
    if vb.murderer  and role == "murderer"  then return true end
    if vb.sheriff   and role == "sheriff"   then return true end
    if vb.hero      and role == "hero"      then return true end
    if vb.assassin  and role == "assassin"  then return true end
    return false
end

local function _startEspBoxLoop()
    if _G._espBoxConn then return end
    _G._espBoxConn = task.spawn(function()
        while _G._espBoxEnabled do
            wait(0.5)
            -- FIX LAG: iterar solo personajes de jugadores en vez de workspace:GetDescendants()
            -- GetDescendants() aloca miles de objetos cada 0.5s ? innecesario para ESP de jugadores
            local myChar = game.Players.LocalPlayer.Character
            for _, player in ipairs(_cachedPlayers) do
                local box = player.Character
                if box and box ~= myChar then
                    local role  = _espBoxGetRole(box)
                    local show  = _espBoxShouldShow(role)
                    local existing = box:FindFirstChild("EspBox")
                    if show then
                        local col = _espBoxColors[role] or _espBoxColors.innocent
                        if not existing then
                            local esp = Instance.new("BoxHandleAdornment", box)
                            esp.Adornee     = box
                            esp.ZIndex      = 0
                            esp.Size        = Vector3.new(5, 6, 2)
                            esp.Transparency = 0.5
                            esp.Color3      = col
                            esp.AlwaysOnTop = true
                            esp.Name        = "EspBox"
                        else
                            -- Actualizar color si cambi? el rol
                            if existing.Color3 ~= col then
                                existing.Color3 = col
                            end
                        end
                    else
                        -- Este personaje no debe mostrarse: limpiar si existe
                        if existing then pcall(function() existing:Destroy() end) end
                    end
                end
            end
        end
        _G._espBoxConn = nil
    end)
end

local function _stopEspBoxLoop()
    _G._espBoxEnabled = false
    _G._espBoxConn = nil
    -- FIX LAG: limpiar EspBox solo de personajes de jugadores, no de todo workspace
    for _, player in ipairs(_cachedPlayers) do
        pcall(function()
            local char = player.Character
            if char then
                local e = char:FindFirstChild("EspBox")
                if e then e:Destroy() end
            end
        end)
    end
end

function CreateOutline(player)
    if player == LocalPlayer then return end

    local outlineConnection  = nil
    local characterConnection = nil
    local _lastChar  = nil
    local _lastColor = nil
    local _partCache = {}
    local _cacheTs   = 0

    local function _limpiar(char)
        if not char then return end
        _partCache = {}; _cacheTs = 0; _lastColor = nil
        for _, desc in ipairs(char:GetDescendants()) do
            if desc:IsA("BoxHandleAdornment") and desc.Name == "PieceOutline" then
                pcall(function() desc:Destroy() end)
            end
        end
    end

    local function _aplicar(char, color)
        local now = tick()
        if now - _cacheTs > 3 then
            _partCache = {}; _cacheTs = now
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
                    _partCache[#_partCache+1] = part
                end
            end
        end
        for _, part in ipairs(_partCache) do
            if not part.Parent then _partCache = {}; _cacheTs = 0; break end
            local prev = part:FindFirstChild("PieceOutline")
            if prev and prev:IsA("BoxHandleAdornment") then
                if _color3Equals(prev.Color3, color) then continue end
                pcall(function() prev:Destroy() end)
            elseif prev then
                pcall(function() prev:Destroy() end)
            end
            pcall(function()
                local b = Instance.new("BoxHandleAdornment")
                b.Name        = "PieceOutline"
                b.Size        = part.Size + Vector3.new(0.02, 0.02, 0.02)
                b.AlwaysOnTop = true
                b.ZIndex      = 4
                b.Adornee     = part
                b.Color3      = color
                b.Transparency = 0.35
                b.CFrame      = CFrame.new(0, 0, 0)
                b.Parent      = part
            end)
        end
        _lastColor = color
    end

    local function updateOutline()
        if not player or not player.Parent then return end
        local character = player.Character
        -- Si cambio de char, limpiar el viejo
        if _lastChar and _lastChar ~= character then
            pcall(function() _limpiar(_lastChar) end)
            _lastChar = nil
        end
        if not character or not character.Parent then return end

        local role
        if     _roleCache.murderer == player then role = "Murderer"
        elseif _roleCache.sheriff  == player then role = "Sheriff"
        elseif _roleCache.hero     == player then role = "Hero"
        else                                      role = "Innocent"
        end
        local vo         = VisualState and VisualState.outline
        local shouldShow = vo and vsShow(vo, role, player) or false

        if not shouldShow then
            if _lastChar == character then
                pcall(function() _limpiar(character) end)
                _lastChar = nil
            end
            return
        end

        local color
        if     role == "Murderer"  then color = Color3.fromRGB(255,   0,  40)
        elseif role == "Sheriff"   then color = Color3.fromRGB(  0, 140, 255)
        elseif role == "Hero"      then color = Color3.fromRGB(255, 210,   0)
        elseif role == "GunHolder" then color = Color3.fromRGB(255, 210,   0)
        else                            color = Color3.fromRGB(200, 200, 200)
        end

        _lastChar = character
        pcall(function() _aplicar(character, color) end)
    end

    -- LAG FIX: outline solo corre si la feature esta activa
    local _hbToutline = 0
    outlineConnection = RunService.Heartbeat:Connect(function()
        _hbToutline = _hbToutline + 1
        if _hbToutline < 36 then return end
        _hbToutline = 0
        local _vo = VisualState and VisualState.outline
        if not (_vo and (_vo.everyone or _vo.murderer or _vo.sheriff or _vo.hero)) then
            -- Feature desactivada: limpiar si habia algo
            if _lastChar then pcall(function() _limpiar(_lastChar) end); _lastChar = nil end
            return
        end
        pcall(updateOutline)
    end)

    characterConnection = player.CharacterAdded:Connect(function(character)
        task.wait(0.5)
        pcall(updateOutline)
    end)

    player.AncestryChanged:Connect(function()
        if not player.Parent then
            if outlineConnection  then outlineConnection:Disconnect()  end
            if characterConnection then characterConnection:Disconnect() end
            if _lastChar then pcall(function() _limpiar(_lastChar) end) end
        end
    end)
end

function CreateSkeleton(player)
    if player == LocalPlayer then return end

    local skeletonConnections = {}
    local skeletonConnection = nil
    local characterConnection = nil

    function updateSkeleton()
        if not player or not player.Parent then return end

        local character = player.Character
        if not character or not character.Parent then
            for _, conn in pairs(skeletonConnections) do
                pcall(function() if conn then conn:Destroy() end end)
            end
            table.clear(skeletonConnections)
            return
        end

        local color = Color3.fromRGB(255, 255, 255)
        local shouldShow = false

        if Settings.skeleton.enabled.Everyone then
            shouldShow = true
        end

        for _, conn in pairs(skeletonConnections) do
            pcall(function() if conn then conn:Destroy() end end)
        end
        table.clear(skeletonConnections)

        if shouldShow then
            local parts = {
                {"Head", "UpperTorso"}, {"UpperTorso", "LowerTorso"}, {"UpperTorso", "LeftUpperArm"},
                {"UpperTorso", "RightUpperArm"}, {"LeftUpperArm", "LeftLowerArm"}, {"RightUpperArm", "RightLowerArm"},
                {"LeftLowerArm", "LeftHand"}, {"RightLowerArm", "RightHand"}, {"LowerTorso", "LeftUpperLeg"},
                {"LowerTorso", "RightUpperLeg"}, {"LeftUpperLeg", "LeftLowerLeg"}, {"RightUpperLeg", "RightLowerLeg"},
                {"LeftLowerLeg", "LeftFoot"}, {"RightLowerLeg", "RightFoot"}
            }

            for _, pair in pairs(parts) do
                pcall(function()
                    local part1 = character:FindFirstChild(pair[1])
                    local part2 = character:FindFirstChild(pair[2])

                    if part1 and part1.Parent and part2 and part2.Parent then
                        local beam = Instance.new("Beam")
                        local att1 = Instance.new("Attachment", part1)
                        local att2 = Instance.new("Attachment", part2)
                        beam.Attachment0 = att1
                        beam.Attachment1 = att2
                        beam.Color = ColorSequence.new(color)
                        beam.Width0 = 0.1
                        beam.Width1 = 0.1
                        beam.FaceCamera = true
                        beam.Parent = part1
                        table.insert(skeletonConnections, beam)
                        table.insert(skeletonConnections, att1)
                        table.insert(skeletonConnections, att2)
                    end
                end)
            end
        end
    end

    -- LAG FIX: skeleton solo corre si la feature esta activa
    local _hbTskeleton = 0
    skeletonConnection = RunService.Heartbeat:Connect(function()
        _hbTskeleton=_hbTskeleton+1; if _hbTskeleton<36 then return end; _hbTskeleton=0  -- OPT: 30?36 frames
        local _vsk = VisualState and VisualState.skeleton
        if not (_vsk and (_vsk.everyone or _vsk.murderer or _vsk.sheriff)) then return end
        pcall(updateSkeleton)
    end)

    characterConnection = player.CharacterAdded:Connect(function(character)
        task.wait(0.5)
        pcall(updateSkeleton)
    end)

    player.AncestryChanged:Connect(function()
        if not player.Parent then
            if skeletonConnection then skeletonConnection:Disconnect() end
            if characterConnection then characterConnection:Disconnect() end
            for _, conn in pairs(skeletonConnections) do
                pcall(function() if conn then conn:Destroy() end end)
            end
            table.clear(skeletonConnections)
        end
    end)
end

function ApplyAllESPToPlayer(player)
    -- FIX: El sistema viejo (per-player loops) causaba que los jugadores
    -- desaparecieran porque updateESP/updateChams/etc. son funciones GLOBALES
    -- que se sobreescriben con cada jugador nuevo. Solo usamos instanceLoop.
    -- Esta funcion queda como stub para compatibilidad.
    if player == LocalPlayer then return end
    -- instanceLoop (17820) ya maneja todos los jugadores automaticamente
end

_notifQueue = {}
_notifRunning = false
_notifOffset = 0  -- offset Y acumulado para stack

-- ANTI-SPAM: historial reciente de notificaciones [clave] = tick()
-- Evita que la misma notif aparezca varias veces en menos de _NOTIF_COOLDOWN segundos
_notifHistory = {}
local _NOTIF_COOLDOWN   = 8.0   -- segundos minimos entre la misma notif (aumentado para evitar spam en loops)
local _NOTIF_MAX_QUEUE  = 4     -- cola maxima; descarta las mas viejas si se supera
local _NOTIF_MAX_PER_SEC = 3    -- no mas de 3 notifs distintas por segundo
local _notifRateWindow  = 0     -- tick del ultimo "lote" de rate-limit
local _notifRateCount   = 0     -- cuantas notifs se enviaron en ese lote

function _processNotifQueue()
    if _notifRunning then return end
    _notifRunning = true
    task.spawn(function()
        -- Descartar exceso: mantener solo las mas recientes
        while #_notifQueue > _NOTIF_MAX_QUEUE do
            table.remove(_notifQueue, 1)
        end
        while #_notifQueue > 0 do
            local item = table.remove(_notifQueue, 1)
            pcall(item)
            task.wait(0.18)  -- gap minimo entre notifs para evitar superposicion visual
        end
        _notifRunning = false
    end)
end

function _isRoleNotif(titleRaw)
    local t = tostring(titleRaw):lower()
    return t:find("murder") or t:find("sheriff") or t:find("rol") or t:find("role")
end

function _getPlayerUserId(name)
    for _, p in pairs(_cachedPlayers) do
        if p.Name == name then return p.UserId end
    end
    if LocalPlayer.Name == name then return LocalPlayer.UserId end
    return nil
end

function CreateCustomNotification(titleRaw, message, duration)
    -- ANTI-SPAM: construir clave unica para esta notif
    local _nKey = tostring(titleRaw) .. "|" .. tostring(message)
    local _now  = tick()

    -- 1) Bloquear si la misma notif ya aparecio hace menos de _NOTIF_COOLDOWN segundos
    if _notifHistory[_nKey] and (_now - _notifHistory[_nKey]) < _NOTIF_COOLDOWN then
        return  -- duplicado reciente: ignorar silenciosamente
    end

    -- 2) Rate-limit global: no mas de _NOTIF_MAX_PER_SEC notifs distintas por segundo
    if (_now - _notifRateWindow) < 1.0 then
        _notifRateCount = _notifRateCount + 1
        if _notifRateCount > _NOTIF_MAX_PER_SEC then
            return  -- demasiadas notifs en este segundo: descartar
        end
    else
        -- Nueva ventana de 1 segundo
        _notifRateWindow = _now
        _notifRateCount  = 1
    end

    -- 3) Registrar en historial
    _notifHistory[_nKey] = _now

    -- 4) Limpiar entradas viejas del historial (> 10 segundos) para no acumular memoria
    if math.fmod(_notifRateCount, 5) == 0 then
        local _cutoff = _now - 10
        for k, v in pairs(_notifHistory) do
            if v < _cutoff then _notifHistory[k] = nil end
        end
    end

    table.insert(_notifQueue, function()
        duration = duration or (_G._notifDefaultDuration) or 4

        local notifSG = Instance.new("ScreenGui")
        notifSG.Name           = "OverdriveNotif_" .. tostring(titleRaw)
        notifSG.ResetOnSpawn   = false
        notifSG.DisplayOrder   = 9999
        notifSG.IgnoreGuiInset = true
        pcall(function() notifSG.Parent = game:GetService("CoreGui") end)
        if not notifSG.Parent then notifSG.Parent = LocalPlayer.PlayerGui end

        -- Fondo principal (responsive para m?vil)
        local _notifVP = workspace.CurrentCamera.ViewportSize
        local _notifIsMob = _notifVP.X < 600
        local _notifW = _notifIsMob and math.min(math.floor(_notifVP.X * 0.60), 230) or 270
        local _notifH = _notifIsMob and 52 or 60
        -- Forma siempre compacta/minimal para no molestar
        local _notifShape = "Minimal"
        -- Ajustar altura segun forma
        if _notifShape == "Banner" then _notifH = _notifIsMob and 44 or 52 end
        if _notifShape == "Minimal" then _notifH = _notifIsMob and 38 or 46 end

        local mainFrame = Instance.new("Frame")
        mainFrame.Size = UDim2.new(0, _notifW, 0, _notifH)
        mainFrame.Position = UDim2.new(1, -8, 1, -50)
        mainFrame.AnchorPoint = Vector2.new(1, 1)
        mainFrame.BackgroundColor3 = Color3.fromRGB(8, 8, 18)
        mainFrame.BackgroundTransparency = 0.18
        mainFrame.BorderSizePixel = 0
        mainFrame.Parent = notifSG

        -- Radio de esquinas segun forma
        local _cornerRadius = 12
        if _notifShape == "Rounded" then _cornerRadius = 12
        elseif _notifShape == "Sharp"   then _cornerRadius = 0
        elseif _notifShape == "Pill"    then _cornerRadius = 24
        elseif _notifShape == "Banner"  then _cornerRadius = 0
        elseif _notifShape == "Minimal" then _cornerRadius = 12
        end
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, _cornerRadius)
        corner.Parent = mainFrame

        -- Barra lateral de acento (solo en Banner)
        if _notifShape == "Banner" then
            local accentBar = Instance.new("Frame", mainFrame)
            accentBar.Size = UDim2.new(0, 4, 1, 0)
            accentBar.Position = UDim2.new(0, 0, 0, 0)
            accentBar.BackgroundColor3 = ThemeColors.Primary
            accentBar.BorderSizePixel = 0
            accentBar.ZIndex = 2
        end

        -- Borde sutil muy fino
        local stroke = Instance.new("UIStroke")
        stroke.Thickness = 1
        stroke.Color = ThemeColors.Aurora1
        stroke.Transparency = 0.3
        stroke.Parent = mainFrame

        -- Icono checkmark verde (oculto en Minimal/Banner)
        local _iconSize = 0  -- sin icono en modo compacto
        local _iconOffX  = 10
        local icon = Instance.new("ImageLabel")
        icon.Size = UDim2.new(0, 0, 0, 0)
        icon.Position = UDim2.new(0, 0, 0.5, 0)
        icon.BackgroundTransparency = 1
        icon.Image = ""
        icon.ImageColor3 = ThemeColors.Primary
        icon.Visible = false
        icon.Parent = mainFrame

        -- Titulo con RichText
        local _titleOffX = (_notifShape == "Minimal") and 12 or (_notifShape == "Banner") and 14 or 46
        local _titleOffY = (_notifShape == "Minimal") and 0 or (_notifShape == "Banner") and 6 or 8
        local _titleH    = (_notifShape == "Minimal") and math.floor(_notifH * 0.55) or 20
        local titleLbl = Instance.new("TextLabel")
        titleLbl.Size = UDim2.new(1, -(_titleOffX + 8), 0, _titleH)
        titleLbl.Position = UDim2.new(0, _titleOffX, 0, _titleOffY)
        titleLbl.BackgroundTransparency = 1
        titleLbl.RichText = true
        local _pr = ThemeColors.Primary
        local _phex = string.format("#%02X%02X%02X", math.floor(_pr.R*255), math.floor(_pr.G*255), math.floor(_pr.B*255))
        titleLbl.Text = '<font color="' .. _phex .. '">' .. tostring(titleRaw) .. '</font>'
        titleLbl.TextSize = 12
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.TextXAlignment = Enum.TextXAlignment.Left
        titleLbl.Parent = mainFrame

        -- Mensaje (oculto en Minimal)
        local _descOffX = (_notifShape == "Banner") and 14 or 12
        local descLbl = Instance.new("TextLabel")
        descLbl.Size = UDim2.new(1, -(_descOffX + 8), 0, 22)
        descLbl.Position = UDim2.new(0, _descOffX, 0, (_notifShape == "Banner") and 22 or math.floor(_notifH * 0.52))
        descLbl.Visible = true  -- siempre visible en modo compacto
        descLbl.BackgroundTransparency = 1
        descLbl.RichText = true
        descLbl.Text = tostring(message)
        descLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        descLbl.TextSize = 9
        descLbl.Font = Enum.Font.Gotham
        descLbl.TextWrapped = true
        descLbl.TextXAlignment = Enum.TextXAlignment.Left
        descLbl.TextYAlignment = Enum.TextYAlignment.Top
        descLbl.Parent = mainFrame

        -- Barra de progreso verde
        local progressBarBg = Instance.new("Frame")
        progressBarBg.Size = UDim2.new(1, -16, 0, 2)
        progressBarBg.Position = UDim2.new(0, 8, 1, -6)
        progressBarBg.BackgroundColor3 = Color3.fromRGB(30, 30, 50)
        progressBarBg.BackgroundTransparency = 0.3
        progressBarBg.BorderSizePixel = 0
        progressBarBg.Parent = mainFrame

        local progressBar = Instance.new("Frame")
        progressBar.Size = UDim2.new(1, 0, 1, 0)
        progressBar.BackgroundColor3 = Color3.fromRGB(210, 85, 100)  -- celeste neon transparente
        progressBar.BackgroundTransparency = 0.15
        progressBar.BorderSizePixel = 0
        progressBar.Parent = progressBarBg

        -- Gradiente celeste transparente: tono hub celeste/cyan
        local progressGrad = Instance.new("UIGradient")
        progressGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   Color3.fromRGB( 80, 230, 255)),  -- celeste claro neon
            ColorSequenceKeypoint.new(0.35, Color3.fromRGB(  0, 200, 255)),  -- celeste hub puro
            ColorSequenceKeypoint.new(0.7, Color3.fromRGB(  0, 180, 240)),  -- celeste medio
            ColorSequenceKeypoint.new(1,   Color3.fromRGB( 60, 220, 255)),  -- celeste electrico
        })
        progressGrad.Rotation = 0
        progressGrad.Parent = progressBar

        -- Boton transparente encima para cerrar al tocar (version movil)
        local _dismissed = false
        local dismissBtn = Instance.new("TextButton")
        dismissBtn.Size = UDim2.new(1, 0, 1, 0)
        dismissBtn.BackgroundTransparency = 1
        dismissBtn.Text = ""
        dismissBtn.ZIndex = 10
        dismissBtn.AutoButtonColor = false
        dismissBtn.Parent = mainFrame

        local function _doFadeOut()
            if _dismissed then return end
            _dismissed = true
            local fadeInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            TweenService:Create(mainFrame, fadeInfo, {BackgroundTransparency = 1}):Play()
            TweenService:Create(stroke, fadeInfo, {Transparency = 1}):Play()
            TweenService:Create(titleLbl, fadeInfo, {TextTransparency = 1}):Play()
            TweenService:Create(descLbl, fadeInfo, {TextTransparency = 1}):Play()
            TweenService:Create(icon, fadeInfo, {ImageTransparency = 1}):Play()
            task.delay(0.26, function() pcall(function() notifSG:Destroy() end) end)
        end

        dismissBtn.Activated:Connect(_doFadeOut)  -- FIX MOBILE: Activated cubre mouse y touch
        dismissBtn.TouchTap:Connect(_doFadeOut)

        -- Margen inferior para movil: distancia desde el borde inferior de la pantalla
        -- En movil usamos un margen fijo peque?o para que quede bien visible
        local _notifMarginBottom = _notifIsMob and (_notifH + 14) or (_notifH + 20)
        local _notifTargetY = -_notifMarginBottom

        -- Slide in desde derecha (menos intrusivo, rapido)
        mainFrame.Position = UDim2.new(1, _notifW + 20, 1, _notifTargetY)  -- empieza fuera a la derecha
        local tweenIn = TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        TweenService:Create(mainFrame, tweenIn, {Position = UDim2.new(1, -8, 1, _notifTargetY)}):Play()

        -- Barra se encoge durante 'duration' segundos
        local tweenBar = TweenInfo.new(duration, Enum.EasingStyle.Linear)
        TweenService:Create(progressBar, tweenBar, {Size = UDim2.new(0, 0, 1, 0)}):Play()

        task.wait(duration)

        -- Fade out suave (si no fue descartada antes)
        _doFadeOut()
        task.wait(0.3)
        pcall(function() if notifSG and notifSG.Parent then notifSG:Destroy() end end)
    end)
    _processNotifQueue()
end

function TeleportToLobby()
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then
 CreateCustomNotification("TP LOBBY", "No se encontro tu personaje", 2)
        return false
    end

    local lobby = workspace:FindFirstChild("Lobby")
    if lobby then
        local spawns = lobby:FindFirstChild("Spawns")
        if spawns then
            local sp = spawns:FindFirstChildOfClass("SpawnLocation") or spawns:FindFirstChildOfClass("BasePart")
            if sp then
                pcall(function() hrp.CFrame = sp.CFrame + Vector3.new(0, 5, 0) end)
 CreateCustomNotification("TP LOBBY", "Teleportado al Lobby", 2)
                return true
            end
        end
        local sp2 = lobby:FindFirstChildOfClass("SpawnLocation") or lobby:FindFirstChildWhichIsA("BasePart")
        if sp2 then
            pcall(function() hrp.CFrame = sp2.CFrame + Vector3.new(0, 5, 0) end)
 CreateCustomNotification("TP LOBBY", "Teleportado al Lobby", 2)
            return true
        end
    end

    for _, obj in pairs(workspace:GetChildren()) do
        if obj.Name:lower():find("lobby") then
            local sp = obj:FindFirstChildOfClass("SpawnLocation")
                    or obj:FindFirstChildWhichIsA("BasePart")
            if sp then
                pcall(function() hrp.CFrame = sp.CFrame + Vector3.new(0, 5, 0) end)
 CreateCustomNotification("TP LOBBY", "Teleportado -> " .. obj.Name, 2)
                return true
            end
        end
    end

    local rootSpawn = workspace:FindFirstChildOfClass("SpawnLocation")
    if rootSpawn then
        pcall(function() hrp.CFrame = rootSpawn.CFrame + Vector3.new(0, 5, 0) end)
 CreateCustomNotification("TP LOBBY", "Teleportado a spawn raiz", 2)
        return true
    end

 CreateCustomNotification("TP LOBBY", "No se encontro el Lobby -- proba en ronda", 3)
    return false
end

function TeleportToVotepad()
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end

    function findVotepadPart()
        local lobby = workspace:FindFirstChild("Lobby")
        if lobby then
            local mapvote = lobby:FindFirstChild("MapVote")
            if mapvote then
                for _, child in pairs(mapvote:GetChildren()) do
                    local part = child:FindFirstChildOfClass("BasePart") or child:FindFirstChildOfClass("Part")
                    if part then return part end
                    if child:IsA("BasePart") then return child end
                end
            end
            for _, child in pairs(lobby:GetDescendants()) do
                if child.Name:lower():find("votepad") or child.Name:lower():find("vote") then
                    if child:IsA("BasePart") then return child end
                end
            end
        end
        for _, obj in pairs(workspace:GetDescendants()) do
            local n = obj.Name:lower()
            if (n:find("votepad") or n:find("votingpad") or n == "votepad1") and obj:IsA("BasePart") then
                return obj
            end
        end
        return nil
    end

    local part = findVotepadPart()
    if part then
        hrp.CFrame = part.CFrame + Vector3.new(0, 5, 0)
        return true
    end
 CreateCustomNotification("TP VOTEPAD", "No se encontro el VotePad -- ?estas en lobby?", 3)
    return false
end

function TeleportToMap()
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return false end

    -- TP seguro: anula velocidad, teletransporta 2 veces para evitar rebote
    local function doTP(pos, label)
        -- FIX CAIDA STEAL GUN: usar offset Y mas generoso (+2 extra) para no aparecer
        -- justo en el borde del suelo donde la fisica puede empujar al jugador abajo
        local safePos = Vector3.new(pos.X, math.max(pos.Y, 4) + 2, pos.Z)
        -- Primer TP + zereo completo
        pcall(function()
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.Velocity    = Vector3.zero
            hrp.RotVelocity = Vector3.zero
            hrp.CFrame = CFrame.new(safePos)
        end)
        -- Segundo TP 1 frame despues para confirmar posicion
        task.defer(function()
            local c2 = LocalPlayer.Character
            local h2 = c2 and c2:FindFirstChild("HumanoidRootPart")
            if h2 then
                h2.AssemblyLinearVelocity  = Vector3.zero
                h2.AssemblyAngularVelocity = Vector3.zero
                h2.Velocity    = Vector3.zero
                h2.RotVelocity = Vector3.zero
                h2.CFrame = CFrame.new(safePos)
            end
        end)
        -- Tercer TP 0.15s despues por si hay lag de red
        task.delay(0.15, function()
            local c3 = LocalPlayer.Character
            local h3 = c3 and c3:FindFirstChild("HumanoidRootPart")
            if h3 then
                h3.AssemblyLinearVelocity  = Vector3.zero
                h3.AssemblyAngularVelocity = Vector3.zero
                h3.CFrame = CFrame.new(safePos)
            end
        end)
        -- FIX CAIDA: cuarto TP a 0.4s para rescatar si sigue cayendo
        task.delay(0.4, function()
            local c4 = LocalPlayer.Character
            local h4 = c4 and c4:FindFirstChild("HumanoidRootPart")
            if h4 and h4.Position.Y < safePos.Y - 3 then
                h4.AssemblyLinearVelocity  = Vector3.zero
                h4.AssemblyAngularVelocity = Vector3.zero
                h4.CFrame = CFrame.new(safePos)
            end
        end)
 CreateCustomNotification("TP MAP", "-> " .. label, 2)
        return true
    end

    -- Detectar modelo del mapa activo en workspace
    local function findMapModel()
        -- Prioridad 1: CoinContainer o Spawns (estructura real de MM2)
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("Model") and not obj.Name:lower():find("lobby") then
                if obj:FindFirstChild("CoinContainer") or obj:FindFirstChild("Spawns") then
                    return obj
                end
            end
        end
        -- Prioridad 2: nombre de mapa conocido
        local kw = {"Factory","MilBase","Mansion","School","Hospital","Station",
            "Carnival","Cave","Castle","Bank","Arena","Airport","Museum","Cruise",
            "Sewers","Courtyard","Office","Library","Temple","Forest","City",
            "House","Subway","Mall","Prison","Church","Funland","Graveyard",
            "Resort","Diner","Warehouse","Harbor","Camp","Desert","Winter","Hotel",
            "Village","Facility","Workshop","Laboratory","Asylum","Lighthouse","Rocket",
            "BioLab","Bio","Lab","Jungle","Space","Island","Volcano","Mansion2"}
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("Model") and not obj.Name:lower():find("lobby") then
                for _, k in ipairs(kw) do
                    if obj.Name:lower():find(k:lower()) then return obj end
                end
            end
        end
        -- Prioridad 3: modelo con mas descendientes (fallback)
        local best, bestN = nil, 60
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("Model") and obj ~= LocalPlayer.Character
            and not obj.Name:lower():find("lobby") then
                local n = #obj:GetDescendants()
                if n > bestN then bestN = n; best = obj end
            end
        end
        return best
    end

    local map = findMapModel()
    if not map then
 CreateCustomNotification("TP MAP", "No se detecto ningun mapa", 2)
        return false
    end

    -- ==============================================================
    -- PRIORIDAD 0: workspace.<MapName>.Spawns:GetChildren()[12]
    -- El mapa siempre cambia pero SIEMPRE tiene carpeta Spawns.
    -- Spawn #12 (index 12) es un punto de reaparicion valido y seguro.
    -- ==============================================================
    local spawnsFolder0 = map:FindFirstChild("Spawns")
    if spawnsFolder0 then
        local spawnChildren = spawnsFolder0:GetChildren()
        -- Intentar indice 12 primero, luego cualquier BasePart disponible
        local sp0 = spawnChildren[12]
        if sp0 and sp0:IsA("BasePart") then
            return doTP(sp0.Position + Vector3.new(0, sp0.Size.Y / 2 + 3.5, 0), map.Name .. "/Spawns[12]")
        end
        -- Si indice 12 no existe o no es BasePart, usar el primero disponible
        for _, sp in ipairs(spawnChildren) do
            if sp:IsA("BasePart") or sp:IsA("SpawnLocation") then
                return doTP(sp.Position + Vector3.new(0, sp.Size.Y / 2 + 3.5, 0), map.Name .. "/Spawns[1]")
            end
        end
    end

    -- ==============================================================
    -- RUTA MM2 REAL: workspace.<MapName>.Base
    -- En MM2 cada mapa tiene un BasePart/SpawnLocation llamado "Base"
    -- que es el suelo del spawn. Ej: workspace.Factory.Base
    -- ==============================================================

    -- Prioridad 1: .Base directo (ruta workspace.Factory.Base)
    local base = map:FindFirstChild("Base")
    if base and base:IsA("BasePart") then
        local spawnPos = base.Position + Vector3.new(0, base.Size.Y / 2 + 3.5, 0)
        return doTP(spawnPos, map.Name .. "/Base")
    end

    -- Prioridad 2: SpawnLocation dentro del mapa (cualquier nivel)
    local sl = map:FindFirstChildOfClass("SpawnLocation")
                or map:FindFirstChild("SpawnPoint")
    if sl and sl:IsA("BasePart") then
        return doTP(sl.Position + Vector3.new(0, sl.Size.Y / 2 + 3.5, 0), map.Name .. "/Spawn")
    end

    -- Prioridad 3: BoundingBox del mapa con raycast al suelo DESDE ADENTRO
    -- (no desde el centro en el aire -- eso era la causa de las muertes)
    local ok, cf = pcall(function() return map:GetBoundingBox() end)
    if ok and cf then
        -- Buscar el suelo real haciendo raycast desde un punto alto del centro
        local rParams = RaycastParams.new()
        rParams.FilterType = Enum.RaycastFilterType.Include
        rParams.FilterDescendantsInstances = {map}
        -- Raycast hacia abajo desde el tope del bounding box
        local startY = cf.Position.Y + cf.Size.Y / 2 + 5  -- tope del mapa
        local rayOrigin = Vector3.new(cf.Position.X, startY, cf.Position.Z)
        local ray = workspace:Raycast(rayOrigin, Vector3.new(0, -(cf.Size.Y + 20), 0), rParams)
        if ray then
            -- Encontro suelo real del mapa
            return doTP(Vector3.new(ray.Position.X, ray.Position.Y + 4, ray.Position.Z), map.Name)
        else
            -- Sin suelo detectado: usar Y del bounding box + offset generoso
            return doTP(Vector3.new(cf.Position.X, cf.Position.Y + 5, cf.Position.Z), map.Name)
        end
    end

 CreateCustomNotification("TP MAP", "Error: no se encontro punto de spawn en " .. map.Name, 2)
    return false
end
function TeleportToSheriff()
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    _refreshRoleCache()
    local sheriff = findSheriffPlayer()
    if sheriff and sheriff.Character and sheriff.Character:FindFirstChild("HumanoidRootPart") then
        local tHRP = sheriff.Character:FindFirstChild("HumanoidRootPart")
        if tHRP then
            pcall(function() hrp.CFrame = tHRP.CFrame + Vector3.new(3, 0, 0) end)
 CreateCustomNotification("TP SHERIFF", "-> " .. sheriff.Name, 2)
            return true
        end
    end
    for _, player in pairs(_cachedPlayers) do
        if player ~= LocalPlayer then
            local role = GetPlayerRole(player)
            if role == "Sheriff" or role == "Hero" then
                local tChar = player.Character
                local tHRP  = tChar and tChar:FindFirstChild("HumanoidRootPart")
                if tHRP then
                    pcall(function() hrp.CFrame = tHRP.CFrame + Vector3.new(3, 0, 0) end)
 CreateCustomNotification("TP SHERIFF", "-> " .. player.Name, 2)
                    return true
                end
            end
        end
    end
 CreateCustomNotification("TP SHERIFF", "No hay Sheriff detectado", 3)
    return false
end

