function TeleportToRandomPlayer()
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    local players = {}
    for _, player in pairs(_cachedPlayers) do
        if player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
            table.insert(players, player)
        end
    end
    if #players > 0 then
        local target = players[math.random(1, #players)]
        pcall(function()
            local tHRP = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
            if tHRP then hrp.CFrame = tHRP.CFrame + Vector3.new(3, 0, 0) end
        end)
 CreateCustomNotification("TP RANDOM", "-> " .. target.Name, 2)
        return true
    end
 CreateCustomNotification("TP RANDOM", "No hay otros jugadores", 2)
    return false
end

