function CreateGlowTeleportButton(parent, icon, name, glowColor, callback)
    local container = Instance.new("Frame", parent)
    container.Size = UDim2.new(1, -10, 0, 36)
    container.BackgroundTransparency = 1

    local btn = Instance.new("TextButton", container)
    btn.Size = UDim2.new(1, 0, 1, 0)
    btn.BackgroundColor3 = Color3.fromRGB(4, 14, 28)
    btn.BackgroundTransparency = 0.18
    btn.Text = ""
    btn.AutoButtonColor = false
    btn.BorderSizePixel = 0
    btn.ZIndex = 2
    -- Estilo USE: rectangular con esquinas poco redondeadas
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)

    local stroke = Instance.new("UIStroke", btn)
    stroke.Color = Color3.fromRGB(0, 210, 240)
    stroke.Thickness = 1.8
    stroke.Transparency = 0.10

    local nameLabel = Instance.new("TextLabel", btn)
    nameLabel.Size = UDim2.new(1, -12, 1, 0)
    nameLabel.Position = UDim2.new(0, 10, 0, 0)
    nameLabel.BackgroundTransparency = 1
    nameLabel.Text = convertirFuenteCursor(name)
    nameLabel.FontFace = Font.fromEnum(Enum.Font.Arimo)
    nameLabel.TextSize = 13
    nameLabel.TextColor3 = Color3.fromRGB(160, 230, 255)
    nameLabel.TextXAlignment = Enum.TextXAlignment.Left
    nameLabel.ZIndex = 3

    btn.MouseEnter:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.12), {BackgroundColor3 = ThemeColors.Accent, BackgroundTransparency = 0.10}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.12), {Transparency = 0, Thickness = 2}):Play()
        TweenService:Create(nameLabel, TweenInfo.new(0.12), {TextColor3 = ThemeColors.TextPrimary}):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.12), {BackgroundColor3 = ThemeColors.Background, BackgroundTransparency = 0.05}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.12), {Transparency = 0.25, Thickness = 1.5}):Play()
        TweenService:Create(nameLabel, TweenInfo.new(0.12), {TextColor3 = ThemeColors.TextPrimary}):Play()
    end)
    btn.Activated:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.08), {BackgroundColor3 = ThemeColors.Primary, BackgroundTransparency = 0.05}):Play()
        task.wait(0.12)
        TweenService:Create(btn, TweenInfo.new(0.15), {BackgroundColor3 = ThemeColors.Background, BackgroundTransparency = 0.05}):Play()
        if callback then callback() end
    end)
    return container
end

-- ===================================================================
-- MM2 PLACE ID CHECK + LOADING SCREEN OVERDRIVE-STYLE
-- ===================================================================
MM2_UNIVERSE_ID = 155615604
MM2_PLACE_IDS = { [142823291]=true, [189707]=true }
function isMM2()
    if game.GameId == MM2_UNIVERSE_ID then return true end
    if MM2_PLACE_IDS[game.PlaceId] then return true end
    if (game.Name or ""):lower():find("murder") then return true end
    return false
end

function iniciarCarga(onDone)
    -- HUB CARGA INMEDIATA: sin animacion de 3 circulos
    -- El juego carga directo sin pantalla de espera
    local _ok2, _loaded2 = pcall(function() return game:IsLoaded() end)
    if not (_ok2 and _loaded2) then
        pcall(function() game.Loaded:Wait() end)
    end
    if onDone then task.spawn(onDone) end
end


function RegisterTabConn(conn)
    if conn then table.insert(_G._tabConns, conn) end
end
-- -- Registro de reset de sliders (se llama al cambiar de pestana) --
_G._sliderResets = _G._sliderResets or {}
_G._sliderVals   = _G._sliderVals   or {}  -- persiste valores de sliders entre cambios de pestana

function ClearContent()
    if not contentContainer then return end
    _currentMainSectionFrame = nil
    _G._infoSectionCreated = nil  -- reset guard para permitir recreacion limpia

    -- OPT: ya NO reseteamos sliders al defaultVal al cambiar de pestana.
    -- Los valores se persisten en _G._sliderVals y se restauran al recrear la UI.
    _G._sliderResets = {}

    -- FIX SLOTS: resetear mapa de slots al cambiar de pestana para que los
    -- bindables siempre aparezcan en su posicion inicial de slot (0,1,2...)
    -- sin importar que botones existieron antes. Sin esto, entradas fantasma
    -- en _bindableActiveSlots corrompian los indices y movian los botones.
    _G._bindableActiveSlots = {}

    -- Desconectar todas las conexiones de tab registradas
    for _, c in ipairs(_G._tabConns) do
        pcall(function() c:Disconnect() end)
    end
    _G._tabConns = {}

    -- FIX: restaurar camara si CamNoclip estaba activo en Scriptable
    if _G_CamNoclip and _G_CamNoclip.enabled then
        pcall(function()
            local cam = workspace.CurrentCamera
            if cam then
                cam.CameraType    = _G_CamNoclip.origType or Enum.CameraType.Custom
                cam.CameraSubject = _G_CamNoclip.origSub  or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid"))
            end
        end)
        if _G_CamNoclip.conn then pcall(function() _G_CamNoclip.conn:Disconnect() end) end
        _G_CamNoclip.enabled  = false
        _G_CamNoclip.conn     = nil
        _G_CamNoclip.origType = nil
        _G_CamNoclip.origSub  = nil
    end
    for _, child in pairs(contentContainer:GetChildren()) do
        child:Destroy()
    end
end

