-- Auto-balanceo de columnas por altura estimada
-- Asigna cada seccion a la columna mas corta en ese momento
_colHeights = {left = 0, right = 0}

function _autoCol(parent)
    if parent ~= leftColumn and parent ~= rightColumn then return parent end
    -- Elegir la columna mas corta
    if _colHeights.left <= _colHeights.right then
        return leftColumn
    else
        return rightColumn
    end
end

-- Llamar esto despues de CreateSection para registrar la altura del header
function _trackSectionHeight(col, itemCount)
    local h = 36 + (itemCount or 0) * 50 + 16  -- header + items + padding
    if col == leftColumn then
        _colHeights.left = _colHeights.left + h
    else
        _colHeights.right = _colHeights.right + h
    end
end

function CreateBorderedSectionGlobal(parent, title)
    local targetCol = _autoCol(parent)
