-- ======================================================================
-- CreateNeonSection -- seccion con marco de luz animado cian/morado
-- y titulo grande brillante (estilo del codigo NeonInfiniteLoop)
-- ======================================================================
function CreateNeonSection(parent, titulo)
    local targetCol = _autoCol(parent)
    _trackSectionHeight(targetCol, 0)

    -- Contenedor principal
    local section = Instance.new("Frame", targetCol)
    section.Name = "NeonSection_" .. tostring(titulo)
    section.Size = UDim2.new(1, 0, 0, 0)
    section.BackgroundColor3 = ThemeColors.Background
    section.BackgroundTransparency = 1  -- TRANSPARENCIA TOTAL: fondo del juego visible
    section.BorderSizePixel = 0
    section.AutomaticSize = Enum.AutomaticSize.Y
    section.ZIndex = 12
    Instance.new("UICorner", section).CornerRadius = UDim.new(0, 10)

    -- UIStroke que va a brillar con gradiente animado
    local stroke = Instance.new("UIStroke", section)
    stroke.Thickness = 2.5
    stroke.Color = ThemeColors.TextPrimary
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Transparency = 0

    -- Gradiente dinamico en el stroke
    local grad = Instance.new("UIGradient", stroke)
    local C_CYAN   = ThemeColors.Accent   -- amarillo sol
    local C_PURPLE = ThemeColors.Secondary   -- morado neon
    local C_DARK   = ThemeColors.Primary     -- naranja quemado (era gris)
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   C_DARK),
        ColorSequenceKeypoint.new(0.2, C_CYAN),
        ColorSequenceKeypoint.new(0.5, C_PURPLE),
        ColorSequenceKeypoint.new(0.8, C_CYAN),
        ColorSequenceKeypoint.new(1,   C_DARK),
    })

    -- Animacion del gradiente (usa shimmer global)
    RegisterShimmer(grad, 120, math.random(0, 359))

    -- Layout interno
    local padding = Instance.new("UIPadding", section)
    padding.PaddingTop    = UDim.new(0, 0)
    padding.PaddingBottom = UDim.new(0, 0)
    padding.PaddingLeft   = UDim.new(0, 0)
    padding.PaddingRight  = UDim.new(0, 0)
    local layout = Instance.new("UIListLayout", section)
    layout.Padding = UDim.new(0, 0)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center

    -- Titulos removidos: no se muestran para que todo quede pegado
    _currentMainSectionFrame = section
    return section
end


_toggleRestoreRegistry = {}


function _RegisterToggleRestore(nombre, restoreFn)
    _toggleRestoreRegistry[nombre] = restoreFn
end

function _DoToggleRestore(nombre)
    local fn = _toggleRestoreRegistry[nombre]
    if fn then pcall(fn) end
end

function _RestoreCharacterDefaults()
    local char = LocalPlayer.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        if hum.WalkSpeed ~= 16 then hum.WalkSpeed = 16 end
        if hum.JumpPower ~= 50  then hum.JumpPower = 50 end
        hum.AutoRotate = true
    end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp then
        for _, part in pairs(char:GetDescendants()) do
            if (part:IsA("BasePart") or part:IsA("MeshPart")) and part.CanCollide == false then
                pcall(function() part.CanCollide = true end)
            end
        end
    end
end

function CreateToggle(parent, nombre, callback, initialValue)
    -- FIX: muchas llamadas pasan (parent, nombre, initialValue, callback) con los args invertidos
    -- Si el 3er arg es boolean/nil y el 4to es funcion, intercambiarlos
    if type(callback) ~= "function" and type(initialValue) == "function" then
        callback, initialValue = initialValue, callback
    end
    local actualParent = _currentMainSectionFrame or parent

    local function wrappedCallback(enabled)
        if callback then callback(enabled) end
        if not enabled then
            task.spawn(function()
                task.wait(0.016)
                _DoToggleRestore(nombre)
            end)
        end
    end

 return CreateAuroraToggle(actualParent, nombre, wrappedCallback, initialValue)
end

local function _attachScrollPassthrough(...)
    local objs = {...}
    local firstObj = objs[1]

    -- Buscar el ScrollingFrame padre mas cercano (con cache para evitar busqueda en cada frame)
    local _cachedSF = nil
    local function _findScrollParent(obj)
        if _cachedSF and _cachedSF.Parent then return _cachedSF end
        local p = obj and obj.Parent
        while p do
            if p:IsA("ScrollingFrame") then _cachedSF = p; return p end
            p = p.Parent
        end
    end

    -- PC: pasar MouseWheel al ScrollingFrame padre
    local function _pass(i)
        if i.UserInputType ~= Enum.UserInputType.MouseWheel then return end
        local sf = _findScrollParent(firstObj)
        if sf then
            local newY = math.clamp(
                sf.CanvasPosition.Y - i.Position.Z * 36,
                0,
                math.max(0, sf.AbsoluteCanvasSize.Y - sf.AbsoluteSize.Y)
            )
            sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, newY)
        end
    end

    for _, obj in ipairs(objs) do
        pcall(function() obj.InputChanged:Connect(_pass) end)

        -- MOBILE FIX: propagar TouchPan al ScrollingFrame padre para que
        -- el TextButton no bloquee el scroll tactil en celular
        pcall(function()
            local _touchStartY = nil
            local _sfRef = nil

            obj.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    _touchStartY = i.Position.Y
                    -- Usar cache si esta disponible, sino buscar
                    _sfRef = (_cachedSF and _cachedSF.Parent) and _cachedSF or _findScrollParent(firstObj)
                end
            end)

            obj.InputChanged:Connect(function(i)
                if i.UserInputType ~= Enum.UserInputType.Touch then return end
                if not _touchStartY or not _sfRef or not _sfRef.Parent then return end
                local delta = _touchStartY - i.Position.Y
                _touchStartY = i.Position.Y
                local newY = math.clamp(
                    _sfRef.CanvasPosition.Y + delta,
                    0,
                    math.max(0, _sfRef.AbsoluteCanvasSize.Y - _sfRef.AbsoluteSize.Y)
                )
                _sfRef.CanvasPosition = Vector2.new(_sfRef.CanvasPosition.X, newY)
            end)

            obj.InputEnded:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch then
                    _touchStartY = nil
                    _sfRef = nil
                end
            end)
        end)
    end
end

function CreateSlider(parent, nombre, minVal, maxVal, defaultVal, callback, step)
    local actualParent = _currentMainSectionFrame or parent
    local STEP = step or 0.1

    local _sliderKey = nombre .. "|" .. tostring(minVal) .. "|" .. tostring(maxVal)
    local _initVal = (_G._sliderVals and _G._sliderVals[_sliderKey] ~= nil)
                     and _G._sliderVals[_sliderKey] or defaultVal

    -- ==============================================================
    --  SLIDER -- estilo nuevo: fondo azul claro translucido redondeado
    --  Titulo izquierda | Value box derecha con borde | Track grueso 10px
    --  Fill azul claro | Thumb circular blanco 18px
    -- ==============================================================

    -- === SLIDER REDESIGN: sin fondo/recuadro, flotante y elegante ===
    local C_BG_MAIN  = Color3.fromRGB(0, 0, 0)              -- transparente total
    local C_STROKE   = Color3.fromRGB( 50, 255, 180)         -- teal aurora
    local C_TEXT     = Color3.fromRGB(220, 255, 245)         -- texto blanco verdoso
    local C_TRACK_BG = Color3.fromRGB(15, 35, 50)            -- pista oscura azul noche
    local C_TRACK_FG = Color3.fromRGB(0, 220, 170)           -- fill teal brillante
    local C_THUMB    = Color3.fromRGB(255, 255, 255)         -- knob blanco
    local C_VALBG    = Color3.fromRGB(0, 0, 0)               -- fondo value box (trans)
    local CONTAINER_H = 54

    -- Contenedor SIN fondo ni recuadro: completamente transparente
    local container = Instance.new("Frame", actualParent)
    container.Name                   = "SliderWrapper_" .. nombre
    container.Size                   = UDim2.new(1, 0, 0, CONTAINER_H)
    container.BackgroundTransparency = 1   -- SIN fondo
    container.BorderSizePixel        = 0
    container.ClipsDescendants       = false
    container.ZIndex                 = 10
    -- Sin UICorner ni UIStroke (sin recuadro)
    do
        -- Separador sutil debajo: linea de 1px aurora semitransparente
        local _divLine = Instance.new("Frame", container)
        _divLine.Size                   = UDim2.new(0.92, 0, 0, 1)
        _divLine.Position               = UDim2.new(0.04, 0, 1, -1)
        _divLine.BackgroundColor3       = Color3.fromRGB(0, 180, 140)
        _divLine.BackgroundTransparency = 0.72
        _divLine.BorderSizePixel        = 0
        _divLine.ZIndex                 = 10
        local _dg = Instance.new("UIGradient", _divLine)
        _dg.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   Color3.fromRGB(0,0,0)),
            ColorSequenceKeypoint.new(0.2, Color3.fromRGB(0, 200, 160)),
            ColorSequenceKeypoint.new(0.8, Color3.fromRGB(0, 180, 140)),
            ColorSequenceKeypoint.new(1,   Color3.fromRGB(0,0,0)),
        })
    end

    -- Titulo izquierda: texto flotante elegante, sin fondo
    local titleLabel = Instance.new("TextLabel", container)
    titleLabel.Name                   = "TitleLabel"
    titleLabel.Size                   = UDim2.new(1, -86, 0, 28)
    titleLabel.Position               = UDim2.new(0, 10, 0, 4)
    titleLabel.BackgroundTransparency = 1
    titleLabel.Text                   = nombre
    titleLabel.TextXAlignment         = Enum.TextXAlignment.Left
    titleLabel.TextYAlignment         = Enum.TextYAlignment.Center
    titleLabel.TextColor3             = Color3.fromRGB(200, 240, 230)
    titleLabel.FontFace               = Font.fromEnum(Enum.Font.GothamSemibold)
    titleLabel.TextSize               = 13
    titleLabel.TextTruncate           = Enum.TextTruncate.AtEnd
    titleLabel.ZIndex                 = 12
    if _LangObjects then
        table.insert(_LangObjects, {obj=titleLabel, key=nombre, prefix="", suffix=""})
        if _G.HubLanguage and _LangStrings then
            local _d = _LangStrings[_G.HubLanguage]
            if _d and _d[nombre] then titleLabel.Text = _d[nombre] end
        end
    end

    -- Value box: pill flotante sin fondo solido, solo borde aurora sutil
    local valueFrame = Instance.new("Frame", container)
    valueFrame.Name                   = "ValueFrame"
    valueFrame.Size                   = UDim2.new(0, 72, 0, 24)
    valueFrame.Position               = UDim2.new(1, -78, 0, 6)
    valueFrame.BackgroundColor3       = Color3.fromRGB(0, 40, 35)
    valueFrame.BackgroundTransparency = 0.55
    valueFrame.BorderSizePixel        = 0
    valueFrame.ZIndex                 = 12
    do
        local vc = Instance.new("UICorner", valueFrame); vc.CornerRadius = UDim.new(1, 0)
        local vs = Instance.new("UIStroke", valueFrame)
        vs.Color = Color3.fromRGB(0, 220, 170); vs.Thickness = 1.2; vs.Transparency = 0.3
    end

    local valueLabel = Instance.new("TextBox", valueFrame)
    valueLabel.Name                   = "ValueLabel"
    valueLabel.Size                   = UDim2.new(1, 0, 1, 0)
    valueLabel.BackgroundTransparency = 1
    valueLabel.Text                   = string.format("%.2f", _initVal)
    valueLabel.TextXAlignment         = Enum.TextXAlignment.Center
    valueLabel.TextYAlignment         = Enum.TextYAlignment.Center
    valueLabel.TextColor3             = Color3.fromRGB(0, 240, 190)
    valueLabel.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
    valueLabel.TextSize               = 13
    valueLabel.ZIndex                 = 13
    valueLabel.ClearTextOnFocus       = true
    valueLabel.PlaceholderText        = string.format("%.2f", _initVal)
    valueLabel.PlaceholderColor3      = Color3.fromRGB(0, 180, 140)

    -- Track elegante: delgado, sin borde externo, solo fill teal luminoso
    local sliderTrack = Instance.new("Frame", container)
    sliderTrack.Name                   = "SliderTrack"
    sliderTrack.Size                   = UDim2.new(1, -20, 0, 5)
    sliderTrack.Position               = UDim2.new(0, 10, 1, -14)
    sliderTrack.BackgroundColor3       = Color3.fromRGB(8, 30, 40)
    sliderTrack.BackgroundTransparency = 0.3
    sliderTrack.BorderSizePixel        = 0
    sliderTrack.ClipsDescendants       = false
    sliderTrack.ZIndex                 = 12
    do
        Instance.new("UICorner", sliderTrack).CornerRadius = UDim.new(1, 0)
        -- Sin UIStroke en el track (mas limpio)
    end

    local fillRatio = math.clamp((_initVal - minVal) / math.max(maxVal - minVal, 0.001), 0, 1)

    local sliderFill = Instance.new("Frame", sliderTrack)
    sliderFill.Name                   = "FillBar"
    sliderFill.Size                   = UDim2.new(fillRatio, 0, 1, 0)
    sliderFill.BackgroundColor3       = Color3.fromRGB(0, 220, 170)
    sliderFill.BackgroundTransparency = 0
    sliderFill.BorderSizePixel        = 0
    sliderFill.ZIndex                 = 13
    Instance.new("UICorner", sliderFill).CornerRadius = UDim.new(1, 0)
    -- Gradiente en el fill para efecto glow
    local _sfGrad = Instance.new("UIGradient", sliderFill)
    _sfGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(0, 180, 140)),
        ColorSequenceKeypoint.new(0.6, Color3.fromRGB(0, 240, 190)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(80, 255, 210)),
    })

    -- Thumb elegante: anillo teal con nucleo blanco brillante
    local _thumbSize = UserInputService.TouchEnabled and 22 or 14
    local _thumbSizeHover = UserInputService.TouchEnabled and 26 or 18

    local sliderThumb = Instance.new("ImageButton", sliderTrack)
    sliderThumb.Name                   = "SliderThumb"
    sliderThumb.Size                   = UDim2.new(0, _thumbSize, 0, _thumbSize)
    sliderThumb.AnchorPoint            = Vector2.new(0.5, 0.5)
    sliderThumb.Position               = UDim2.new(fillRatio, 0, 0.5, 0)
    sliderThumb.BackgroundColor3       = Color3.fromRGB(255, 255, 255)
    sliderThumb.BackgroundTransparency = 0
    sliderThumb.BorderSizePixel        = 0
    sliderThumb.ZIndex                 = 15
    Instance.new("UICorner", sliderThumb).CornerRadius = UDim.new(1, 0)
    -- Anillo de color aurora alrededor del thumb
    local _thumbRing = Instance.new("UIStroke", sliderThumb)
    _thumbRing.Color           = Color3.fromRGB(0, 220, 170)
    _thumbRing.Thickness       = 2.5
    _thumbRing.Transparency    = 0
    _thumbRing.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Logica
    local currentValue = _initVal
    local dragging     = false

    local function round(v)
        return math.clamp(math.floor(v / STEP + 0.5) * STEP, minVal, maxVal)
    end

    local function applyValue(v)
        v = math.clamp(round(v), minVal, maxVal)
        currentValue = v
        if _G._sliderVals then _G._sliderVals[_sliderKey] = v end
        local ratio = math.clamp((v - minVal) / math.max(maxVal - minVal, 0.001), 0, 1)
        sliderThumb.Position = UDim2.new(ratio, 0, 0.5, 0)
        sliderFill.Size      = UDim2.new(ratio, 0, 1, 0)
        valueLabel.Text      = string.format("%.2f", v)
        if callback then callback(v) end
    end

    applyValue(_initVal)

    -- Permitir escribir un valor directamente en la caja
    valueLabel.FocusLost:Connect(function(enterPressed)
        local typed = tonumber(valueLabel.Text)
        if typed then
            applyValue(typed)
        else
            -- Si escribieron algo invalido, restaurar el valor actual
            valueLabel.Text = string.format("%.2f", currentValue)
        end
    end)

    local function updateFromInput(inputObj)
        local mx
        if inputObj and inputObj.UserInputType == Enum.UserInputType.Touch then
            mx = inputObj.Position.X
        else
            mx = UserInputService:GetMouseLocation().X
        end
        local tp  = sliderTrack.AbsolutePosition.X
        local ts  = sliderTrack.AbsoluteSize.X
        local pct = math.clamp((mx - tp) / math.max(ts, 1), 0, 1)
        applyValue(minVal + pct * (maxVal - minVal))
    end

    local function updateFromMouse()
        updateFromInput(nil)
    end

    sliderThumb.MouseEnter:Connect(function()
        TweenService:Create(sliderThumb, TweenInfo.new(0.10),
            {Size = UDim2.new(0, _thumbSizeHover, 0, _thumbSizeHover)}):Play()
    end)
    sliderThumb.MouseLeave:Connect(function()
        if not dragging then
            TweenService:Create(sliderThumb, TweenInfo.new(0.10),
                {Size = UDim2.new(0, _thumbSize, 0, _thumbSize)}):Play()
        end
    end)

    sliderThumb.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1
        or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            _G._sliderDragging = true
            TweenService:Create(sliderThumb, TweenInfo.new(0.08),
                {Size = UDim2.new(0, _thumbSizeHover, 0, _thumbSizeHover)}):Play()
        end
    end)
    sliderTrack.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1
        or i.UserInputType == Enum.UserInputType.Touch then
            dragging = true; _G._sliderDragging = true; updateFromInput(i)
        end
    end)
    local _c1 = UserInputService.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1
        or i.UserInputType == Enum.UserInputType.Touch then
            dragging = false
            _G._sliderDragging = false
            TweenService:Create(sliderThumb, TweenInfo.new(0.10),
                {Size = UDim2.new(0, _thumbSize, 0, _thumbSize)}):Play()
        end
    end)
    local _c2 = UserInputService.InputChanged:Connect(function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement
                      or i.UserInputType == Enum.UserInputType.Touch) then
            updateFromInput(i)
        end
    end)
    container.AncestryChanged:Connect(function()
        if not container.Parent then _c1:Disconnect(); _c2:Disconnect() end
    end)

    local function _setSliderEnabled(enabled)
        TweenService:Create(sliderThumb, TweenInfo.new(0.18), {
            BackgroundColor3 = enabled and C_THUMB or Color3.fromRGB(140, 140, 150),
        }):Play()
        TweenService:Create(titleLabel, TweenInfo.new(0.18), {
            TextColor3 = enabled and C_TEXT or Color3.fromRGB(120, 130, 160),
        }):Play()
        sliderThumb.Active       = enabled
        sliderThumb.Interactable = enabled
    end

    -- FIX SCROLL: el container del slider no debe absorber el MouseWheel
    pcall(function() _attachScrollPassthrough(container, sliderThumb) end)

    return { frame = container, SetEnabled = _setSliderEnabled }
end
-- Gradiente 45 deg: (0,162,255) -> (79,255,176) -> (138,43,226)
-- Fondo oscuro casi negro para efecto glow premium
-- ==================================================================
function CreateGlowButton(parent, nombre, callback)
    local actualParent = _currentMainSectionFrame or parent

    local container = Instance.new("Frame", actualParent)
    container.Name                   = "GlowButtonContainer"
    container.Size                   = UDim2.new(1, 0, 0, 58)
    container.BackgroundTransparency = 1

    local btn = Instance.new("TextButton", container)
    btn.Size                   = UDim2.new(1, 0, 1, 0)
    btn.BackgroundColor3       = Color3.fromRGB(4, 14, 28)
    btn.BackgroundTransparency = 0.18
    btn.Text                   = ""
    btn.AutoButtonColor        = false
    btn.BorderSizePixel        = 0
    btn.ZIndex                 = 2
    -- Estilo USE: esquinas muy redondeadas, aspecto rectangular glassmorphism
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
    -- Gradiente interior sutil, fondo oscuro translucido
    local _gbGrad = Instance.new("UIGradient", btn)
    _gbGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(8,  30, 60)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(4,  16, 36)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(8,  30, 60)),
    })
    _gbGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,   0.30),
        NumberSequenceKeypoint.new(0.5, 0.20),
        NumberSequenceKeypoint.new(1,   0.30),
    })
    _gbGrad.Rotation = 90

    local stroke = Instance.new("UIStroke", btn)
    stroke.Thickness       = 1.8
    stroke.Transparency    = 0.10
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Color           = Color3.fromRGB(0, 210, 240)
    -- Gradiente en el borde: cian -> teal
    local _gbStrokeGrad = Instance.new("UIGradient", stroke)
    _gbStrokeGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(0, 220, 255)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0, 180, 200)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(0, 220, 255)),
    })
    _gbStrokeGrad.Rotation = 90

    local textLabel = Instance.new("TextLabel", btn)
    textLabel.Size                   = UDim2.new(1, -16, 1, 0)
    textLabel.Position               = UDim2.new(0, 8, 0, 0)
    textLabel.BackgroundTransparency = 1
    textLabel.Text                   = nombre
    textLabel.Font                   = Enum.Font.SourceSans
    textLabel.TextSize               = 20
    textLabel.TextColor3             = ThemeColors.TextPrimary
    textLabel.TextXAlignment         = Enum.TextXAlignment.Center
    textLabel.ZIndex                 = 3

    btn.MouseEnter:Connect(function()
        TweenService:Create(btn,       TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(6, 24, 48), BackgroundTransparency = 0.05}):Play()
        TweenService:Create(stroke,    TweenInfo.new(0.15), {Thickness = 2.5, Transparency = 0.0, Color = Color3.fromRGB(0, 240, 255)}):Play()
        TweenService:Create(textLabel, TweenInfo.new(0.12), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn,       TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(4, 14, 28), BackgroundTransparency = 0.18}):Play()
        TweenService:Create(stroke,    TweenInfo.new(0.15), {Thickness = 1.8, Transparency = 0.10, Color = Color3.fromRGB(0, 210, 240)}):Play()
        TweenService:Create(textLabel, TweenInfo.new(0.12), {TextColor3 = ThemeColors.TextPrimary}):Play()
    end)

    btn.Activated:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.07), {BackgroundColor3 = Color3.fromRGB(0, 180, 210), BackgroundTransparency = 0.05}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.07), {Color = Color3.fromRGB(255, 255, 255), Thickness = 3}):Play()
        task.wait(0.13)
        TweenService:Create(btn, TweenInfo.new(0.18), {BackgroundColor3 = Color3.fromRGB(4, 14, 28), BackgroundTransparency = 0.18}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.18), {Color = Color3.fromRGB(0, 210, 240), Thickness = 1.8}):Play()
        if callback then callback() end
    end)

    return container
end

-- ==================================================================
-- CreateGroupedToggles -- agrupa N toggles en un cuadro con borde
-- de lineas estilo MISCELLANEOUS.
-- groupName  : texto grande en el header (ej: "Bomb")
-- subtitle   : texto pequeno debajo (ej: "UNIVERSAL / MM2 / MMV")
-- toggleDefs : tabla de { name, callback, default }
-- El borde usa el mismo gradiente cyan->menta->purpura del glow button.
-- ==================================================================
function CreateGroupedToggles(parent, groupName, subtitle, toggleDefs)
    local actualParent = _currentMainSectionFrame or parent

    -- -- Contenedor externo con borde gradiente ----------------------
    local outerFrame = Instance.new("Frame", actualParent)
    outerFrame.Name                   = "GroupedToggles_" .. groupName
    outerFrame.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
    outerFrame.BackgroundTransparency = 0.85
    outerFrame.BorderSizePixel        = 0
    outerFrame.ClipsDescendants       = false

    Instance.new("UICorner", outerFrame).CornerRadius = UDim.new(0, 12)

    -- Borde de lineas con colores del hub (Aurora1 -> Aurora2 -> Primary)
    local outerStroke = Instance.new("UIStroke", outerFrame)
    outerStroke.Thickness       = 2.5
    outerStroke.Transparency    = 0
    outerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local outerGrad = Instance.new("UIGradient", outerStroke)
    outerGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   ThemeColors.Aurora1),
        ColorSequenceKeypoint.new(0.5, ThemeColors.Aurora2),
        ColorSequenceKeypoint.new(1,   ThemeColors.Primary),
    })
    outerGrad.Rotation = 45
    RegisterShimmer(outerGrad, 60, 0)  -- usa el shimmer global, sin loop propio

    -- -- Header: nombre grande + subtitulo --------------------------
    local HEADER_H   = 52
    local TOGGLE_H   = 50
    local PADDING    = 8
    local totalH     = HEADER_H + (#toggleDefs * (TOGGLE_H + 4)) + PADDING * 2

    outerFrame.Size = UDim2.new(1, 0, 0, totalH)

    local headerFrame = Instance.new("Frame", outerFrame)
    headerFrame.Size                   = UDim2.new(1, 0, 0, HEADER_H)
    headerFrame.BackgroundTransparency = 1
    headerFrame.BorderSizePixel        = 0

    -- Nombre grande (ej: "MISCELLANEOUS" / "BOMB")
    local titleLbl = Instance.new("TextLabel", headerFrame)
    titleLbl.Size                   = UDim2.new(1, -16, 0, 28)
    titleLbl.Position               = UDim2.new(0, 14, 0, 6)
    titleLbl.BackgroundTransparency = 1
    titleLbl.Text                   = groupName:upper()
    titleLbl.Font                   = Enum.Font.SourceSansBold
    titleLbl.TextSize               = 22
    titleLbl.TextXAlignment         = Enum.TextXAlignment.Left
    -- Gradiente de texto con colores del hub
    local titleGrad = Instance.new("UIGradient", titleLbl)
    titleGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   ThemeColors.Aurora1),
        ColorSequenceKeypoint.new(0.6, ThemeColors.Aurora2),
        ColorSequenceKeypoint.new(1,   ThemeColors.Primary),
    })
    titleGrad.Rotation = 0

    -- Subtitulo pequeno (ej: "UNIVERSAL / MM2 / MMV")
    if subtitle and subtitle ~= "" then
        local subLbl = Instance.new("TextLabel", headerFrame)
        subLbl.Size                   = UDim2.new(1, -16, 0, 16)
        subLbl.Position               = UDim2.new(0, 14, 0, 32)
        subLbl.BackgroundTransparency = 1
        subLbl.Text                   = subtitle
        subLbl.Font                   = Enum.Font.SourceSans
        subLbl.TextSize               = 12
        subLbl.TextColor3             = Color3.fromRGB(255, 170, 40)
        subLbl.TextXAlignment         = Enum.TextXAlignment.Left
    end

    -- Linea separadora bajo el header
    local divLine = Instance.new("Frame", outerFrame)
    divLine.Size                   = UDim2.new(1, -20, 0, 1)
    divLine.Position               = UDim2.new(0, 10, 0, HEADER_H)
    divLine.BackgroundColor3       = ThemeColors.Aurora1
    divLine.BackgroundTransparency = 0.5
    divLine.BorderSizePixel        = 0
    -- Gradiente en la linea divisora con colores del hub
    local divGrad = Instance.new("UIGradient", divLine)
    divGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   ThemeColors.Aurora1),
        ColorSequenceKeypoint.new(0.5, ThemeColors.Aurora2),
        ColorSequenceKeypoint.new(1,   ThemeColors.Primary),
    })
    divGrad.Rotation = 0

    -- -- Toggles dentro del grupo ------------------------------------
    -- Usamos un ScrollingFrame interno si hay muchos toggles
    local innerList = Instance.new("Frame", outerFrame)
    innerList.Name                   = "InnerList"
    innerList.Size                   = UDim2.new(1, -PADDING*2, 0, #toggleDefs * (TOGGLE_H + 4))
    innerList.Position               = UDim2.new(0, PADDING, 0, HEADER_H + 4)
    innerList.BackgroundTransparency = 1
    innerList.BorderSizePixel        = 0
    innerList.ClipsDescendants       = false

    local listLayout = Instance.new("UIListLayout", innerList)
    listLayout.SortOrder    = Enum.SortOrder.LayoutOrder
    listLayout.Padding      = UDim.new(0, 4)
    listLayout.FillDirection = Enum.FillDirection.Vertical

    -- Crear cada toggle dentro del grupo
    -- Guarda el parent original, redirige al innerList
    local _savedFrame = _currentMainSectionFrame
    _currentMainSectionFrame = innerList
    for i, def in ipairs(toggleDefs) do
        CreateAuroraToggle(innerList, def.name, def.callback, def.default)
    end
    _currentMainSectionFrame = _savedFrame

    return outerFrame
end

function CreateButton(parent, nombre, color, callback)
    local actualParent = _currentMainSectionFrame or parent
    local _btnColor = color or ThemeColors.Primary

    -- Derivar colores del tono base pasado
    local _r, _g, _b = _btnColor.R, _btnColor.G, _btnColor.B
    local _darkBg  = Color3.new(_r * 0.08, _g * 0.08, _b * 0.08)   -- fondo muy oscuro del color
    local _midBg   = Color3.new(_r * 0.18, _g * 0.18, _b * 0.18)   -- fondo medio hover
    local _accentC = Color3.new(
        math.min(_r * 1.1 + 0.05, 1),
        math.min(_g * 1.1 + 0.05, 1),
        math.min(_b * 1.1 + 0.05, 1)
    )

    local container = Instance.new("Frame", actualParent)
    container.Size = UDim2.new(1, 0, 0, 50)
    container.BackgroundTransparency = 1

    local padding = Instance.new("UIPadding", container)
    padding.PaddingLeft   = UDim.new(0, 6)
    padding.PaddingRight  = UDim.new(0, 6)
    padding.PaddingTop    = UDim.new(0, 5)
    padding.PaddingBottom = UDim.new(0, 5)

    local btn = Instance.new("TextButton", container)
    btn.Size = UDim2.new(1, 0, 1, 0)
    btn.BackgroundColor3 = Color3.fromRGB(4, 14, 28)
    btn.BackgroundTransparency = 0.18
    btn.Text = ""
    btn.AutoButtonColor = false
    btn.BorderSizePixel = 0
    btn.ZIndex = 2
    -- Estilo USE: esquinas poco redondeadas, aspecto rectangular glassmorphism
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)

    -- Gradiente fondo glassmorphism oscuro translucido
    local _btnGrad = Instance.new("UIGradient", btn)
    _btnGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.new(_r * 0.10 + 0.02, _g * 0.10 + 0.05, _b * 0.15 + 0.08)),
        ColorSequenceKeypoint.new(0.5, Color3.new(_r * 0.06 + 0.01, _g * 0.06 + 0.03, _b * 0.12 + 0.06)),
        ColorSequenceKeypoint.new(1,   Color3.new(_r * 0.10 + 0.02, _g * 0.10 + 0.05, _b * 0.15 + 0.08)),
    })
    _btnGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,   0.28),
        NumberSequenceKeypoint.new(0.5, 0.18),
        NumberSequenceKeypoint.new(1,   0.28),
    })
    _btnGrad.Rotation = 90

    -- Borde neon estilo USE: cian brillante con degradado
    local stroke = Instance.new("UIStroke", btn)
    stroke.Color = Color3.fromRGB(0, 210, 240)
    stroke.Thickness = 1.8
    stroke.Transparency = 0.12
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local _cbStrokeGrad = Instance.new("UIGradient", stroke)
    _cbStrokeGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(0, 220, 255)),
        ColorSequenceKeypoint.new(0.5, Color3.new(math.min(_r + 0.05, 1), math.min(_g * 0.5 + 0.35, 1), math.min(_b * 0.5 + 0.45, 1))),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(0, 220, 255)),
    })
    _cbStrokeGrad.Rotation = 90

    -- Linea de brillo superior (highlight)
    local _topLine = Instance.new("Frame", btn)
    _topLine.Size = UDim2.new(0.6, 0, 0, 1)
    _topLine.Position = UDim2.new(0.2, 0, 0, 2)
    _topLine.BackgroundColor3 = Color3.new(1, 1, 1)
    _topLine.BackgroundTransparency = 0.65
    _topLine.BorderSizePixel = 0
    _topLine.ZIndex = 4
    Instance.new("UICorner", _topLine).CornerRadius = UDim.new(1, 0)

    -- Texto
    local textLabel = Instance.new("TextLabel", btn)
    textLabel.Size = UDim2.new(1, -12, 1, 0)
    textLabel.Position = UDim2.new(0, 6, 0, 0)
    textLabel.BackgroundTransparency = 1
    textLabel.Text = convertirFuenteCursor(nombre)
    textLabel.FontFace = Font.fromEnum(Enum.Font.GothamBold)
    textLabel.TextSize = 13
    textLabel.TextColor3 = Color3.new(
        math.min(_r * 0.5 + 0.7, 1),
        math.min(_g * 0.5 + 0.7, 1),
        math.min(_b * 0.5 + 0.7, 1)
    )
    textLabel.TextXAlignment = Enum.TextXAlignment.Center
    textLabel.ZIndex = 3

    -- Glow en texto
    local textStroke = Instance.new("UIStroke", textLabel)
    textStroke.Color = _btnColor
    textStroke.Thickness = 0.8
    textStroke.Transparency = 0.55

    btn.MouseEnter:Connect(function()
        TweenService:Create(_btnGrad, TweenInfo.new(0.15), {Rotation = 160}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.15), {Transparency = 0, Thickness = 2.0, Color = _accentC}):Play()
        TweenService:Create(textLabel, TweenInfo.new(0.15), {TextColor3 = Color3.new(1, 1, 1)}):Play()
        TweenService:Create(_topLine, TweenInfo.new(0.15), {BackgroundTransparency = 0.45}):Play()
    end)

    btn.MouseLeave:Connect(function()
        TweenService:Create(_btnGrad, TweenInfo.new(0.18), {Rotation = 135}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.18), {Transparency = 0.15, Thickness = 1.4, Color = _btnColor}):Play()
        TweenService:Create(textLabel, TweenInfo.new(0.15), {TextColor3 = Color3.new(
            math.min(_r * 0.5 + 0.7, 1),
            math.min(_g * 0.5 + 0.7, 1),
            math.min(_b * 0.5 + 0.7, 1)
        )}):Play()
        TweenService:Create(_topLine, TweenInfo.new(0.15), {BackgroundTransparency = 0.65}):Play()
    end)

    -- FIX MOBILE: Activated detecta tap en celu y click en PC correctamente
    btn.Activated:Connect(function()
        -- Flash brillante del color
        TweenService:Create(btn, TweenInfo.new(0.06), {BackgroundColor3 = _btnColor}):Play()
        TweenService:Create(stroke, TweenInfo.new(0.06), {Color = Color3.new(1,1,1), Thickness = 2.5}):Play()
        task.delay(0.13, function()
            TweenService:Create(btn, TweenInfo.new(0.2), {BackgroundColor3 = _darkBg}):Play()
            TweenService:Create(stroke, TweenInfo.new(0.2), {Color = _btnColor, Thickness = 1.4}):Play()
        end)
        if callback then callback() end
    end)

    return container
end

function UpdateCustomCursor()
    if Settings.cursor.connections.rotation then
        Settings.cursor.connections.rotation:Disconnect()
        Settings.cursor.connections.rotation = nil
    end
    if Settings.cursor.connections.position then
        Settings.cursor.connections.position:Disconnect()
        Settings.cursor.connections.position = nil
    end
    if Settings.cursor.gui then
        Settings.cursor.gui:Destroy()
        Settings.cursor.gui = nil
        Settings.cursor.image = nil
    end
    -- Desconectar conexiones de gunOnlyMode anteriores
    if Settings.cursor._gunOnlyConn then
        pcall(function() Settings.cursor._gunOnlyConn:Disconnect() end)
        Settings.cursor._gunOnlyConn = nil
    end

    if not Settings.cursor.enabled then
        UserInputService.MouseIconEnabled = true
        return
    end

    -- GUN ONLY MODE: si esta activo, la mira solo aparece cuando la gun esta en mano
    if Settings.cursor.gunOnlyMode then
        UserInputService.MouseIconEnabled = true  -- cursor normal mientras no hay gun
        local function _checkGunEquipped()
            local char = LocalPlayer.Character
            if not char then return false end
            -- Buscar gun equipada (Tool en el Character con nombre que contenga gun/sheriff/pistol/revolver)
            for _, tool in ipairs(char:GetChildren()) do
                if tool:IsA("Tool") then
                    local n = tool.Name:lower()
                    if n:find("gun") or n:find("pistol") or n:find("revolver") or n:find("sheriff") or n:find("weapon") then
                        return true
                    end
                end
            end
            return false
        end
        local function _applyGunCursorState()
            local hasGun = _checkGunEquipped()
            if hasGun then
                UserInputService.MouseIconEnabled = false
                if Settings.cursor.image then
                    Settings.cursor.image.Visible = true
                end
            else
                UserInputService.MouseIconEnabled = true
                if Settings.cursor.image then
                    Settings.cursor.image.Visible = false
                end
            end
        end
        -- Conectar ToolEquipped/Unequipped al Character actual y futuros
        local function _hookChar(char)
            if not char then return end
            char.ChildAdded:Connect(function(child)
                if child:IsA("Tool") then
                    task.defer(_applyGunCursorState)
                end
            end)
            char.ChildRemoved:Connect(function(child)
                if child:IsA("Tool") then
                    task.defer(_applyGunCursorState)
                end
            end)
        end
        Settings.cursor._gunOnlyConn = LocalPlayer.CharacterAdded:Connect(function(newChar)
            _hookChar(newChar)
            task.defer(_applyGunCursorState)
        end)
        _hookChar(LocalPlayer.Character)
        -- Estado inicial
        task.defer(_applyGunCursorState)
    else
        UserInputService.MouseIconEnabled = false
    end

    local CursorScopes = {
        {Name = "CRUZ HOLOGRAFICA",  ID = "1827745860"},
        {Name = "FUEGO ARDIENTE",    ID = "4048495248"},
        {Name = "DIAMANTE DUAL",     ID = "1827745860"},
        {Name = "RAYO ELECTRICO",    ID = "10891594349"},
        {Name = "LUNA OSCURA",       ID = "5998624778"},
        {Name = "PUNTO ROJO",        ID = "311756276"},
        {Name = "VORTICE MORTAL",    ID = "5689419548"},
        {Name = "OJO VIGILANTE",     ID = "2207556771"},
        {Name = "OBJETIVO PRECISO",  ID = "11754490323"},
        {Name = "EXPLOSION TACTICA", ID = "11351620343"},
        {Name = "ESTRELLA NEON",     ID = "11722368307"},
        {Name = "DIAMANTE AZUL",     ID = "11719595104"},
        {Name = "PRISMA LETAL",      ID = "10868459539"},
    }
    -- Poblar scopeNames globalmente para que el selector UI los tenga
    scopeNames = {}
    for _, s in ipairs(CursorScopes) do
        table.insert(scopeNames, s.Name)
    end

    -- Soporte para mira personalizada via ID
    local scopeId
    if Settings.cursor.customMiraId and Settings.cursor.customMiraId ~= "" then
        local customRaw = tostring(Settings.cursor.customMiraId)
        scopeId = customRaw:match("%d+") or CursorScopes[Settings.cursor.currentScopeIndex or 1].ID
    else
        local idx = math.clamp(Settings.cursor.currentScopeIndex or 1, 1, #CursorScopes)
        scopeId = CursorScopes[idx].ID
    end

    local selectedScope = { ID = scopeId }
    Settings.cursor.gui = Instance.new("ScreenGui")
    Settings.cursor.gui.Name = "CustomCursorScope"
    Settings.cursor.gui.ResetOnSpawn = false
    Settings.cursor.gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    Settings.cursor.gui.DisplayOrder = 10000
    Settings.cursor.gui.IgnoreGuiInset = true
    Settings.cursor.gui.Parent = LocalPlayer:WaitForChild("PlayerGui")

    Settings.cursor.image = Instance.new("ImageLabel", Settings.cursor.gui)
    Settings.cursor.image.Name = "ScopeImage"
    Settings.cursor.image.Size = UDim2.new(0, Settings.cursor.size.x, 0, Settings.cursor.size.y)
    Settings.cursor.image.BackgroundTransparency = 1
    Settings.cursor.image.Image = "rbxassetid://" .. selectedScope.ID
    Settings.cursor.image.ImageTransparency = Settings.cursor.transparency
    Settings.cursor.image.ImageColor3 = Settings.cursor.color
    Settings.cursor.image.AnchorPoint = Vector2.new(0.5, 0.5)
    Settings.cursor.image.ZIndex = 10001
    Settings.cursor.image.BorderSizePixel = 0
    -- En gun-only mode empieza oculto hasta que se equipe la gun
    if Settings.cursor.gunOnlyMode then
        Settings.cursor.image.Visible = false
    end
    -- MOVIL: empieza oculto; solo se muestra si Shift Lock esta activo
    if _isMobile and not Settings.cursor.gunOnlyMode then
        local _slInitActive = (UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter)
            or (_G._shiftLockState and _G._shiftLockState.enabled == true)
        if not _slInitActive then
            Settings.cursor.image.Visible = false
        end
    end

    if Settings.cursor.rotation.enabled then
        local rotation = 0
        Settings.cursor.connections.rotation = RunService.RenderStepped:Connect(function()
            if Settings.cursor.image and Settings.cursor.image.Parent and Settings.cursor.rotation.enabled then
                rotation = rotation + Settings.cursor.rotation.speed
                if rotation >= 360 then rotation = 0 end
                Settings.cursor.image.Rotation = rotation
            end
        end)
    else
        Settings.cursor.image.Rotation = 0
    end

    -- Detectar si es movil/tactil
    local _isMobile = (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled)

    local function _getShiftLock()
        local ok, sl = pcall(function()
            return UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter
        end)
        return ok and sl or false
    end

    local function _getViewportCenter()
        local vp = workspace.CurrentCamera.ViewportSize
        return vp.X / 2, vp.Y / 2
    end

    local function _updateCursorPos()
        if not Settings.cursor.image or not Settings.cursor.image.Parent then return end
        if _isMobile then
            -- MOVIL: la mira solo aparece cuando Shift Lock esta activo.
            -- Detectamos shift lock por MouseBehavior (LockCenter) o por el estado
            -- del toggle Shift Lock del hub (_G._shiftLockState.enabled).
            local slActive = _getShiftLock()
                or (_G._shiftLockState and _G._shiftLockState.enabled == true)
            if not slActive then
                Settings.cursor.image.Visible = false
                return
            end
            Settings.cursor.image.Visible = true
            local cx, cy = _getViewportCenter()
            Settings.cursor.image.Position = UDim2.new(0, cx, 0, cy)
        elseif _getShiftLock() then
            -- PC con Shift Lock activo: mira centrada
            local cx, cy = _getViewportCenter()
            Settings.cursor.image.Position = UDim2.new(0, cx, 0, cy)
        else
            -- PC modo normal: seguir al mouse
            local mp = UserInputService:GetMouseLocation()
            Settings.cursor.image.Position = UDim2.new(0, mp.X, 0, mp.Y)
        end
    end

    -- Ocultar cursor nativo siempre que la mira este activa
    -- FIX MOBILE SHOOT: en celu NO deshabilitar MouseIconEnabled porque
    -- Roblox lo necesita para procesar el tap-to-shoot del GunClient original.
    if not _isMobile then
        UserInputService.MouseIconEnabled = false
    end

    _updateCursorPos()
    Settings.cursor.connections.position = RunService.RenderStepped:Connect(function()
        if not Settings.cursor.image or not Settings.cursor.image.Parent then return end
        _updateCursorPos()
        -- FIX MOBILE SHOOT: solo bloquear cursor nativo en PC
        if not _isMobile then
            UserInputService.MouseIconEnabled = false
        end
    end)

    -- PC: reaccionar inmediatamente al entrar/salir de Shift Lock
    if not _isMobile then
        UserInputService:GetPropertyChangedSignal("MouseBehavior"):Connect(function()
            _updateCursorPos()
        end)
    end
end


MainSystem = {
    state = {
        infoEnabled = Settings.infoPanel,
        infoGui = nil,
        xray = {
            enabled = false,
            transparency = 75,
            originalProps = {},
            bindEnabled = false
        },
        antiAFK = { enabled = false, connection = nil },
        antiFling = { enabled = false, connection = nil },
        antiVoid = { enabled = false, connection = nil },
        fly = {
            enabled = false,
            speed = 15,
            bindEnabled = false,
            keyEnabled = false,
            connection = nil,
            bv = nil,
            bg = nil
        },
        walkspeed = { enabled = false, value = 18 },
        jumpPower = { enabled = false, value = 50 },
        fakeHeadless = { enabled = false, originalTransparency = {} },
        fakeKorblox = { enabled = false, originalTransparency = {} },
        infiniteJump = { enabled = false, connection = nil },
        secondLife = { enabled = false, used = false },
        autoNotify = { enabled = false, lastMurderer = "", connection = nil, sheriffEnabled = false, lastSheriff = "", sheriffConnection = nil },
        swim = { enabled = false, connection = nil, bv = nil, keyEnabled = false, speed = 20, swimTrack = nil },
        fakeDead = { enabled = false, connection = nil, keyEnabled = false },
        invisibleGhost = {
            enabled          = false,
            dummyModel       = nil,
            floatConn        = nil,
            dummyHBConn      = nil,
            dummySyncConn    = nil,
            dummyJumpConn    = nil,
            returnPos        = nil,
            dummyHRP         = nil,
            dummyHum         = nil,
            controlConn      = nil,
            animConns        = {},
            _origCamSubject  = nil,  -- CameraSubject original para restaurar
            _origCamType     = nil,  -- CameraType original
            _bp              = nil,
            _bg              = nil,
            _savedCollide    = nil,  -- CanCollide original de cada parte del char
        }
    },

    CreateInfoDisplay = function()
        local S = MainSystem.state
        if S.infoGui then S.infoGui:Destroy() S.infoGui = nil end

        S.infoGui = Instance.new("ScreenGui")
        S.infoGui.Name = "InformationPanel"
        S.infoGui.ResetOnSpawn = false
        S.infoGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        S.infoGui.DisplayOrder = 8000
        -- FIX MOBILE: no bloquear inputs del juego
        pcall(function() S.infoGui.PassThroughNonActiveDescendants = true end)
        S.infoGui.Parent = LocalPlayer:WaitForChild("PlayerGui")

        local mainPanel = Instance.new("Frame", S.infoGui)
        mainPanel.Size = UDim2.new(0, 380, 0, 50)
        mainPanel.Position = UDim2.new(1, -400, 0, 20)
        mainPanel.BackgroundColor3 = ThemeColors.Background
        mainPanel.BackgroundTransparency = 0.4
        mainPanel.BorderSizePixel = 0
        mainPanel.ClipsDescendants = true
        mainPanel.Active = false  -- FIX MOBILE: no bloquear joystick

        Instance.new("UICorner", mainPanel).CornerRadius = UDim.new(0, 12)

        -- FIX SCROLL+DRAG: drag movido al headerBar (ver abajo), no al mainPanel completo
        -- Asi el scroll del mouse sobre el contenido NO arrastra el panel
        local _dragStart1, _startPos1, _dragging1 = nil, nil, false
        local _UIS1 = game:GetService("UserInputService")

        local mainStroke = Instance.new("UIStroke", mainPanel)
        mainStroke.Color = ThemeColors.Primary
        mainStroke.Thickness = 2.5

        local strokeGradient = Instance.new("UIGradient", mainStroke)
        strokeGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,    ThemeColors.Primary),    -- Celeste
            ColorSequenceKeypoint.new(0.33, ThemeColors.Accent),     -- Arena
            ColorSequenceKeypoint.new(0.66, ThemeColors.Secondary),  -- Oceano
            ColorSequenceKeypoint.new(1,    ThemeColors.Primary)     -- Celeste
        })
        RegisterShimmer(strokeGradient, 60, math.random(0, 359))

        local headerBar = Instance.new("Frame", mainPanel)
        headerBar.Size = UDim2.new(1, 0, 0, 38)
        headerBar.BackgroundColor3 = ThemeColors.BackgroundLight
        headerBar.BackgroundTransparency = 0.9
        headerBar.BorderSizePixel = 0
        headerBar.Active = true  -- FIX MOBILE: solo header captura touch para arrastrar

        local titleLabel = Instance.new("TextLabel", headerBar)
        titleLabel.Size = UDim2.new(1, -40, 1, 0)
        titleLabel.Position = UDim2.new(0, 10, 0, 0)
        titleLabel.BackgroundTransparency = 1
 titleLabel.Text = convertirFuenteCursor(" INFORMATION PANEL")
        titleLabel.FontFace = Font.fromEnum(Enum.Font.Arimo)
        titleLabel.TextSize = 15
        titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLabel.TextXAlignment = Enum.TextXAlignment.Left

        local dragIcon = Instance.new("TextLabel", headerBar)
        dragIcon.Size = UDim2.new(0, 30, 1, 0)
        dragIcon.Position = UDim2.new(1, -35, 0, 0)
        dragIcon.BackgroundTransparency = 1
 dragIcon.Text = ""
        dragIcon.FontFace = Font.fromEnum(Enum.Font.Arimo)
        dragIcon.TextSize = 18
        dragIcon.TextColor3 = ThemeColors.Aurora2

        -- FIX SCROLL+DRAG: drag conectado al headerBar (barra de titulo)
        -- Solo arrastra cuando el usuario hace click+drag en el header, no al scrollear
        do
            if not pcall(function()
                local dd = Instance.new("UIDragDetector", headerBar)
                dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                dd.Dragged:Connect(function()
                    local vp = workspace.CurrentCamera.ViewportSize
                    mainPanel.Position = UDim2.fromOffset(
                        math.clamp(mainPanel.Position.X.Offset, 0, vp.X - mainPanel.AbsoluteSize.X),
                        math.clamp(mainPanel.Position.Y.Offset, 0, vp.Y - mainPanel.AbsoluteSize.Y))
                end)
            end) then
                -- Fallback UIS: drag solo desde el header
                headerBar.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                        _dragging1 = true; _dragStart1 = input.Position; _startPos1 = mainPanel.Position
                    end
                end)
                headerBar.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                        _dragging1 = false
                    end
                end)
                _UIS1.InputChanged:Connect(function(input)
                    if not _dragging1 then return end
                    if input.UserInputType ~= Enum.UserInputType.MouseMovement
                    and input.UserInputType ~= Enum.UserInputType.Touch then return end
                    local delta = input.Position - _dragStart1
                    local vp    = workspace.CurrentCamera.ViewportSize
                    mainPanel.Position = UDim2.fromOffset(
                        math.clamp(_startPos1.X.Offset + delta.X, 0, vp.X - mainPanel.AbsoluteSize.X),
                        math.clamp(_startPos1.Y.Offset + delta.Y, 0, vp.Y - mainPanel.AbsoluteSize.Y))
                end)
            end
        end

        local scrollFrame = Instance.new("ScrollingFrame", mainPanel)
        scrollFrame.Size = UDim2.new(1, -20, 1, -48)
        scrollFrame.Position = UDim2.new(0, 10, 0, 42)
        scrollFrame.BackgroundTransparency = 1
        scrollFrame.BorderSizePixel = 0
        scrollFrame.ScrollBarThickness = 3
        scrollFrame.ScrollBarImageColor3 = ThemeColors.Primary
        scrollFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
        scrollFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y

        local listLayout = Instance.new("UIListLayout", scrollFrame)
        listLayout.Padding = UDim.new(0, 3)
        listLayout.SortOrder = Enum.SortOrder.LayoutOrder
        listLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center

        function createInfoLabel(text, color)
 local label = Instance.new("TextLabel", scrollFrame)
            label.Size = UDim2.new(1, -5, 0, 18)
            label.BackgroundTransparency = 1
 label.Text = convertirFuenteCursor(text)
            label.FontFace = Font.fromEnum(Enum.Font.Arimo)
            label.TextSize = 11
            label.TextColor3 = color or ThemeColors.TextPrimary
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.TextWrapped = true
            return label
        end

        task.spawn(function()
            while S.infoGui and S.infoGui.Parent do
                for _, child in pairs(scrollFrame:GetChildren()) do
                    if child:IsA("TextLabel") then child:Destroy() end
                end

                local lineCount = 0


                if S.infoEnabled.murdererInfo then
                    createInfoLabel(" MURDERER ", Color3.fromRGB(87, 87, 87))
                    local murderer = findMurderer()
                    if murderer then
                        createInfoLabel("Name: " .. murderer.Name, ThemeColors.Accent)
                        if murderer.Character and murderer.Character:FindFirstChild("HumanoidRootPart") and
                           LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                            local _mInfoHRP  = murderer.Character:FindFirstChild("HumanoidRootPart")
                            local _myInfoHRP = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                            local dist = _mInfoHRP and _myInfoHRP and (_mInfoHRP.Position - _myInfoHRP.Position).Magnitude or 0
                            createInfoLabel("Dist: " .. math.floor(dist) .. "m", ThemeColors.Aurora4)
                        end
                        lineCount = lineCount + 3
                    else
                        createInfoLabel("NOT FOUND", ThemeColors.TextSecondary)
                        lineCount = lineCount + 2
                    end
                end

                if S.infoEnabled.sheriffInfo then
                    createInfoLabel(" SHERIFF ", Color3.fromRGB(0, 255, 0))
                    local sheriff = findSheriffPlayer()
                    if sheriff then
                        createInfoLabel("Name: " .. sheriff.Name, ThemeColors.Aurora2)
                        if sheriff.Character and sheriff.Character:FindFirstChild("HumanoidRootPart") and
                           LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                            local _sInfoHRP  = sheriff.Character:FindFirstChild("HumanoidRootPart")
                            local _myInfoHRP2 = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                            local dist = _sInfoHRP and _myInfoHRP2 and (_sInfoHRP.Position - _myInfoHRP2.Position).Magnitude or 0
                            createInfoLabel("Dist: " .. math.floor(dist) .. "m", ThemeColors.Aurora4)
                        end
                        lineCount = lineCount + 3
                    else
                        createInfoLabel("NOT FOUND", ThemeColors.TextSecondary)
                        lineCount = lineCount + 2
                    end
                end

                if S.infoEnabled.playerStats then
                    createInfoLabel(" YOUR STATS ", ThemeColors.Primary)
                    local role = GetPlayerRole(LocalPlayer)  -- usa cache GetPlayerData
                    createInfoLabel("Name: " .. LocalPlayer.Name, ThemeColors.Aurora1)
                    createInfoLabel("Role: " .. role, GetRoleColor(role))
                    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then
                        createInfoLabel("HP: " .. math.floor(LocalPlayer.Character.Humanoid.Health), ThemeColors.Aurora1)
                    end
                    lineCount = lineCount + 4
                end

                if S.infoEnabled.mapInfo then
                    createInfoLabel(" MAP ", ThemeColors.Aurora3)
                    local mapName, totalCoins = GetCurrentMap()
                    createInfoLabel("Map: " .. (mapName or "Lobby"), ThemeColors.Aurora2)
                    createInfoLabel("Coins: " .. totalCoins, ThemeColors.Primary)
                    lineCount = lineCount + 3
                end

                if S.infoEnabled.roleInfo then
                    createInfoLabel(" ROLES ", ThemeColors.Aurora4)
                    local innocents, murderers, sheriffs = 0, 0, 0
                    for _, p in ipairs(_cachedPlayers) do
                        local r = GetPlayerRole(p)
                        if r == "Murderer" then murderers += 1
                        elseif r == "Sheriff" then sheriffs += 1
                        else innocents += 1 end
                    end
                    createInfoLabel("Innocents: " .. innocents, ThemeColors.Aurora1)
                    createInfoLabel("Murderers: " .. murderers, ThemeColors.Accent)
                    createInfoLabel("Sheriffs: " .. sheriffs, ThemeColors.Aurora2)
                    lineCount = lineCount + 4
                end

                if S.infoEnabled.performanceInfo then
                    createInfoLabel(" PERFORMANCE ", ThemeColors.Aurora2)
                    -- OPT: usar _lastDt global en vez de RenderStepped:Wait() bloqueante
                    local fps = math.floor(1 / math.max(_lastDt or 1/60, 0.001))
                    createInfoLabel("FPS: " .. fps, ThemeColors.Aurora1)
                    lineCount = lineCount + 2
                end

                if S.infoEnabled.gameInfo then
                    createInfoLabel(" GAME ", ThemeColors.Primary)
                    createInfoLabel("Game: Murder Mystery 2", ThemeColors.Aurora1)
                    createInfoLabel("Version: " .. game.PlaceVersion, ThemeColors.Aurora3)
                    lineCount = lineCount + 3
                end

                if S.infoEnabled.coinInfo then
                    createInfoLabel(" COINS ", ThemeColors.Primary)
                    local allCoins = GetAllCoins()
                    createInfoLabel("On map: " .. #allCoins, ThemeColors.Aurora1)
                    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                        local _, dist = FindNearestCoin(allCoins)
                        if dist < math.huge then
                            createInfoLabel("Nearest: " .. math.floor(dist) .. "m", ThemeColors.Aurora2)
                        end
                    end
                    lineCount = lineCount + 3
                end

                local totalHeight = math.min(math.max(50, lineCount * 22 + 55), 500)
                TweenService:Create(mainPanel, TweenInfo.new(0.3), {
                    Size = UDim2.new(0, 380, 0, totalHeight)
                }):Play()

                task.wait(0.5)
            end
        end)
    end,

    UpdateInfoDisplay = function()
        local S = MainSystem.state
        local anyEnabled = false
        for _, v in pairs(S.infoEnabled) do
            if v then anyEnabled = true break end
        end
        if anyEnabled then
            if not S.infoGui then MainSystem.CreateInfoDisplay() end
        else
            if S.infoGui then S.infoGui:Destroy() S.infoGui = nil end
        end
    end,

    ToggleXray = function(enabled)
        local S = MainSystem.state.xray
        S.enabled = enabled
        if enabled then
            local myChar = LocalPlayer.Character
            local charSet = {}
            for _, p in ipairs(_cachedPlayers) do
                if p.Character then charSet[p.Character] = true end
            end
            local trans  = S.transparency / 100
            for _, part in ipairs(workspace:GetDescendants()) do
                if part:IsA("BasePart")
                    and part.Transparency < 0.95
                    and part.Name ~= "HumanoidRootPart"
                    and not (myChar and part:IsDescendantOf(myChar))
                then
                    local skip = false
                    for char, _ in pairs(charSet) do
                        if part:IsDescendantOf(char) then skip = true break end
                    end
                    if not skip then
                        if not S.originalProps[part] then
                            S.originalProps[part] = part.Transparency
                        end
                        pcall(function() part.Transparency = trans end)
                    end
                end
            end
            if not S.addedConn then
                S.addedConn = workspace.DescendantAdded:Connect(function(part)
                    if not S.enabled then return end
                    local myC = LocalPlayer.Character
                    local charSet2 = {}
                    for _, p in ipairs(_cachedPlayers) do
                        if p.Character then charSet2[p.Character] = true end
                    end
                    if part:IsA("BasePart")
                        and part.Transparency < 0.95
                        and part.Name ~= "HumanoidRootPart"
                        and not (myC and part:IsDescendantOf(myC))
                    then
                        local skip = false
                        for char, _ in pairs(charSet2) do
                            if part:IsDescendantOf(char) then skip = true break end
                        end
                        if not skip then
                            if not S.originalProps[part] then
                                S.originalProps[part] = part.Transparency
                            end
                            pcall(function() part.Transparency = S.transparency / 100 end)
                        end
                    end
                end)
            end
        else
            if S.addedConn then S.addedConn:Disconnect(); S.addedConn = nil end
            for part, trans in pairs(S.originalProps) do
                if part and part.Parent then
                    pcall(function() part.Transparency = trans end)
                end
            end
            S.originalProps = {}
        end
    end,

    UpdateXrayTransparency = function(value)
        local S = MainSystem.state.xray
        S.transparency = value
        if S.enabled then
            for part, _ in pairs(S.originalProps) do
                if part and part.Parent then
                    part.Transparency = value / 100
                end
            end
        end
    end,

    ToggleFly = function(enabled)
        local S = MainSystem.state.fly
        S.enabled = enabled
        local character = LocalPlayer.Character
        if not character then return end
        local hrp = character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end

        if S.connection then
            S.connection:Disconnect()
            S.connection = nil
        end

        if enabled then
            if S.bv then S.bv:Destroy() end
            if S.bg then S.bg:Destroy() end

            S.bv = Instance.new("BodyVelocity")
            S.bv.MaxForce = Vector3.new(100000, 100000, 100000)
            S.bv.Velocity = Vector3.zero
            S.bv.Parent = hrp

            S.bg = Instance.new("BodyGyro")
            S.bg.MaxTorque = Vector3.new(100000, 100000, 100000)
            S.bg.P = 10000
            S.bg.Parent = hrp

            -- MOBILE SUPPORT para SwimFly
            local _sfIsMobile = (function()
                local ok, res = pcall(function() return UserInputService.TouchEnabled end)
                return ok and res
            end)()
            local _sfUpHeld   = false
            local _sfDownHeld = false
            local _sfMobileGui = nil
            if _sfIsMobile then
                _sfMobileGui = Instance.new("ScreenGui")
                _sfMobileGui.Name = "SwimFlyMobile_HUB"
                _sfMobileGui.ResetOnSpawn = false
                _sfMobileGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                _sfMobileGui.IgnoreGuiInset = true
                _sfMobileGui.DisplayOrder = 9994
                pcall(function() _sfMobileGui.Parent = game:GetService("CoreGui") end)
                if not _sfMobileGui.Parent then _sfMobileGui.Parent = LocalPlayer.PlayerGui end
                local vp2 = workspace.CurrentCamera.ViewportSize
                local bs2 = 65
                local function _sfBtn(lbl, color, px, py, downFn, upFn)
                    local b = Instance.new("TextButton", _sfMobileGui)
                    b.Size = UDim2.fromOffset(bs2, bs2)
                    b.Position = UDim2.fromOffset(px, py)
                    b.BackgroundColor3 = color
                    b.BackgroundTransparency = 0.3
                    b.Text = lbl; b.TextColor3 = Color3.fromRGB(255,255,255)
                    b.FontFace = Font.fromEnum(Enum.Font.GothamBold)
                    b.TextSize = 13; b.BorderSizePixel = 0; b.AutoButtonColor = false; b.ZIndex = 300
                    Instance.new("UICorner", b).CornerRadius = UDim.new(1, 0)
                    b.InputBegan:Connect(function(i)
                        if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
                            downFn(); TweenService:Create(b, TweenInfo.new(0.08), {BackgroundTransparency=0.05}):Play()
                        end
                    end)
                    b.InputEnded:Connect(function(i)
                        if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
                            upFn(); TweenService:Create(b, TweenInfo.new(0.08), {BackgroundTransparency=0.3}):Play()
                        end
                    end)
                end
                _sfBtn("?\nSUBIR", Color3.fromRGB(60,120,220), vp2.X-bs2*2-15, vp2.Y-bs2*2-10,
                    function() _sfUpHeld=true end, function() _sfUpHeld=false end)
                _sfBtn("?\nBAJAR", Color3.fromRGB(220,80,60), vp2.X-bs2-8, vp2.Y-bs2*2-10,
                    function() _sfDownHeld=true end, function() _sfDownHeld=false end)
            end

            -- Fly usa RenderStepped para movimiento suave (sincronizado con camara)
            S.connection = RunService.RenderStepped:Connect(function()
                if not S.enabled or not hrp.Parent then
                    if S.bv then S.bv:Destroy() S.bv = nil end
                    if S.bg then S.bg:Destroy() S.bg = nil end
                    if S.connection then S.connection:Disconnect() S.connection = nil end
                    if _sfMobileGui then pcall(function() _sfMobileGui:Destroy() end); _sfMobileGui = nil end
                    return
                end
                local camera = workspace.CurrentCamera
                local moveDir = Vector3.zero
                if _sfIsMobile then
                    -- Usar thumbstick del movil para horizontal
                    local _sfChar2 = LocalPlayer.Character
                    local _sfHum2  = _sfChar2 and _sfChar2:FindFirstChildOfClass("Humanoid")
                    if _sfHum2 then
                        local md = _sfHum2.MoveDirection
                        if md.Magnitude > 0.1 then
                            moveDir = Vector3.new(md.X, 0, md.Z)
                        end
                    end
                    if _sfUpHeld   then moveDir = moveDir + Vector3.new(0, 1, 0) end
                    if _sfDownHeld then moveDir = moveDir - Vector3.new(0, 1, 0) end
                else
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        moveDir = moveDir + camera.CFrame.LookVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        moveDir = moveDir - camera.CFrame.LookVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        moveDir = moveDir - camera.CFrame.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        moveDir = moveDir + camera.CFrame.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                        moveDir = moveDir + Vector3.new(0, 1, 0)
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                        moveDir = moveDir - Vector3.new(0, 1, 0)
                    end
                end
                S.bv.Velocity = moveDir * S.speed
                S.bg.CFrame = camera.CFrame
            end)
        else
            for _, obj in pairs(hrp:GetChildren()) do
                if obj:IsA("BodyVelocity") or obj:IsA("BodyGyro") then
                    obj:Destroy()
                end
            end
        end
    end,

