    ToggleSwim = function(enabled)
        local S = MainSystem.state.swim
        S.enabled = enabled
        local char = LocalPlayer.Character
        if not char then return end
        local hrp  = char:FindFirstChild("HumanoidRootPart")
        local hum  = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        -- Limpiar estado anterior
        if S.connection then S.connection:Disconnect(); S.connection = nil end
        for _, n in ipairs({"SwimBG","SwimBV"}) do
            local obj = hrp:FindFirstChild(n); if obj then obj:Destroy() end
        end
        -- Parar animacion previa
        if S.swimTrack then pcall(function() S.swimTrack:Stop() end); S.swimTrack = nil end

        if enabled then
            -- -- Cargar animacion de nado via Animator (funciona en cualquier lugar) --
            local animator = hum:FindFirstChildOfClass("Animator")
            if not animator then animator = Instance.new("Animator", hum) end

            -- Animaciones de swim -- IDs funcionales probados
            -- 507784897 = Swim oficial Roblox (R15, funciona en todos los juegos)
            -- 481825862 = Swim alternativo suave
            -- 10921264784 = Swim avanzado (del usuario)
            local SWIM_IDS = {
                "507784897",    -- Swim principal (Roblox oficial R15)
                "481825862",    -- Swim alternativo suave
                "10921264784",  -- Swim del juego (usuario)
            }
            local swimTracks = {}
            for _, id in ipairs(SWIM_IDS) do
                local ok, t = pcall(function()
                    local anim = Instance.new("Animation")
                    anim.AnimationId = "rbxassetid://" .. id
                    local tr = animator:LoadAnimation(anim)
                    tr.Priority = Enum.AnimationPriority.Action4
                    return tr
                end)
                if ok and t then table.insert(swimTracks, t) end
            end
            -- Reproducir todas en capas (forward + idle juntos)
            local swimTrack = nil
            for i, t in ipairs(swimTracks) do
                t.Looped = true
                t:Play(0.15)
                if i == 1 then swimTrack = t end  -- guardar el primero como ref
            end
            S.swimTrack = swimTrack
            S._swimTracks = swimTracks

            -- BodyGyro para mantener al jugador upright
            local bg = Instance.new("BodyGyro")
            bg.Name = "SwimBG"; bg.MaxTorque = Vector3.new(4e5,4e5,4e5)
            bg.D = 100; bg.CFrame = CFrame.new(hrp.Position); bg.Parent = hrp

            -- BodyVelocity para vuelo libre
            local bv = Instance.new("BodyVelocity")
            bv.Name = "SwimBV"; bv.MaxForce = Vector3.new(1e5,1e5,1e5)
            bv.Velocity = Vector3.zero; bv.Parent = hrp

            hum.PlatformStand = true  -- evitar que el humanoid interfiera

            local UIS = game:GetService("UserInputService")
            local cam = workspace.CurrentCamera
            local speed = S.speed or 20

            S.connection = RunService.RenderStepped:Connect(function()
                if not S.enabled then
                    pcall(function() bg:Destroy() end)
                    pcall(function() bv:Destroy() end)
                    if S.swimTrack then pcall(function() S.swimTrack:Stop() end); S.swimTrack = nil end
                    if S.connection then S.connection:Disconnect(); S.connection = nil end
                    hum.PlatformStand = false
                    return
                end
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local r = c and c:FindFirstChild("HumanoidRootPart")
                if not h or not r then return end

                h.PlatformStand = true  -- mantener siempre

                -- Movimiento en direccion de la camara (vuelo libre 6DOF)
                -- MOBILE SUPPORT: usar MoveDirection en movil
                local cf    = cam.CFrame
                local vel   = Vector3.zero
                local _sf3Mobile = (function()
                    local ok2, res2 = pcall(function() return UIS.TouchEnabled end)
                    return ok2 and res2
                end)()
                if _sf3Mobile then
                    -- Thumbstick horizontal
                    local _md3 = h and h.MoveDirection or Vector3.zero
                    if _md3.Magnitude > 0.1 then
                        vel = Vector3.new(_md3.X, 0, _md3.Z)
                    end
                    -- Usar botones moviles si existen (del sistema principal de fly)
                    if _G._flyUpHeld   then vel = vel + Vector3.new(0,1,0) end
                    if _G._flyDownHeld then vel = vel - Vector3.new(0,1,0) end
                else
                    if UIS:IsKeyDown(Enum.KeyCode.W) then vel = vel + cf.LookVector end
                    if UIS:IsKeyDown(Enum.KeyCode.S) then vel = vel - cf.LookVector end
                    if UIS:IsKeyDown(Enum.KeyCode.D) then vel = vel + cf.RightVector end
                    if UIS:IsKeyDown(Enum.KeyCode.A) then vel = vel - cf.RightVector end
                    if UIS:IsKeyDown(Enum.KeyCode.Space) then vel = vel + Vector3.new(0,1,0) end
                    if UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.C) then
                        vel = vel - Vector3.new(0,1,0)
                    end
                end
                local spd = speed * ((_sf3Mobile and _G._flyBoostHeld) or (not _sf3Mobile and UIS:IsKeyDown(Enum.KeyCode.LeftShift)) and 2 or 1)
                bv.Velocity = vel.Magnitude > 0 and (vel.Unit * spd) or Vector3.zero

                -- Orientar el personaje en la direccion de movimiento (o camara si quieto)
                local lookDir = vel.Magnitude > 0.1 and vel.Unit or cf.LookVector
                bg.CFrame = CFrame.lookAt(r.Position, r.Position + Vector3.new(lookDir.X, 0, lookDir.Z))
            end)
        else
            for _, tr in ipairs(S._swimTracks or {}) do pcall(function() tr:Stop() end) end
            S.swimTrack = nil; S._swimTracks = {}
            hum.PlatformStand = false
        end
    end,

    ToggleFakeDead = function(enabled)
        local S = MainSystem.state.fakeDead
        S.enabled = enabled
        local char = LocalPlayer.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        if S.connection then S.connection:Disconnect() S.connection = nil end

        if enabled then
            hum.PlatformStand = true
            hum:ChangeState(Enum.HumanoidStateType.FallingDown)
            task.wait(0.016)
            if hrp and hrp.Parent then
                hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, 0, math.pi / 2)
            end

            local _fdTick = 0
            S.connection = RunService.Heartbeat:Connect(function()
                _fdTick = _fdTick + 1
                if _fdTick < 3 then return end  -- OPT: ~20fps suficiente para FakeDead
                _fdTick = 0
                if not S.enabled then
                    hum.PlatformStand = false
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    S.connection:Disconnect()
                    S.connection = nil
                    return
                end
                if not char or not char.Parent then
                    S.connection:Disconnect()
                    S.connection = nil
                    return
                end
                hum.PlatformStand = true
                hum:ChangeState(Enum.HumanoidStateType.FallingDown)
            end)

            task.spawn(function()
 CreateCustomNotification(LocalPlayer.Name .. " Says:", "Down and out -- playing dead, nobody suspects", 4)
            end)
        else
            hum.PlatformStand = false
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            task.spawn(function()
 CreateCustomNotification(LocalPlayer.Name .. " Says:", "Rise and shine -- back in the game", 3)
            end)
        end
    end
}

