-- -- CLICK EFFECT SYSTEM --------------------------------------------------
_clickEffectGui = nil

function _ensureClickEffectGui()
    if _clickEffectGui and _clickEffectGui.Parent then return _clickEffectGui end
    local sg = Instance.new("ScreenGui")
    sg.Name           = "BypassClickFX"
    sg.ResetOnSpawn   = false
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.IgnoreGuiInset = true
    sg.DisplayOrder   = 999
    pcall(function() sg.Parent = game:GetService("CoreGui") end)
    if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
    _clickEffectGui = sg
    return sg
end

_clickEffectEnabled = true

function _spawnClickEffect(screenX, screenY)
    if not _clickEffectEnabled then return end
    local sg = _ensureClickEffectGui()
    if not sg then return end

    -- Colores del tema del hub
    local primary = ThemeColors and ThemeColors.Primary or Color3.fromRGB(50, 50, 50)
    local accent  = ThemeColors and ThemeColors.Accent  or Color3.fromRGB(154, 154, 154)

    -- -- Anillo exterior expansivo --
    local ring = Instance.new("Frame", sg)
    ring.Size                  = UDim2.new(0, 8, 0, 8)
    ring.AnchorPoint           = Vector2.new(0.5, 0.5)
    ring.Position              = UDim2.new(0, screenX, 0, screenY)
    ring.BackgroundTransparency= 1
    ring.BorderSizePixel       = 0
    ring.ZIndex                = 1000
    local rc = Instance.new("UICorner", ring); rc.CornerRadius = UDim.new(1, 0)
    local rs = Instance.new("UIStroke", ring)
    rs.Color       = accent
    rs.Thickness   = 2
    rs.Transparency= 0

    TweenService:Create(ring, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        Size                   = UDim2.new(0, 52, 0, 52),
        BackgroundTransparency = 1,
    }):Play()
    TweenService:Create(rs, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        Transparency = 1,
    }):Play()

    -- -- Punto central --
    local dot = Instance.new("Frame", sg)
    dot.Size                   = UDim2.new(0, 10, 0, 10)
    dot.AnchorPoint            = Vector2.new(0.5, 0.5)
    dot.Position               = UDim2.new(0, screenX, 0, screenY)
    dot.BackgroundColor3       = primary
    dot.BackgroundTransparency = 0
    dot.BorderSizePixel        = 0
    dot.ZIndex                 = 1001
    Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)

    TweenService:Create(dot, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        Size                   = UDim2.new(0, 0, 0, 0),
        BackgroundTransparency = 1,
    }):Play()

    -- -- 4 particulas radiales --
    local dirs = {
        Vector2.new(0, -1), Vector2.new(0, 1),
        Vector2.new(-1, 0), Vector2.new(1, 0),
    }
    for _, dir in ipairs(dirs) do
        local p = Instance.new("Frame", sg)
        p.Size                   = UDim2.new(0, 4, 0, 4)
        p.AnchorPoint            = Vector2.new(0.5, 0.5)
        p.Position               = UDim2.new(0, screenX, 0, screenY)
        p.BackgroundColor3       = accent
        p.BackgroundTransparency = 0
        p.BorderSizePixel        = 0
        p.ZIndex                 = 1000
        Instance.new("UICorner", p).CornerRadius = UDim.new(1, 0)

        local dist2 = 22
        TweenService:Create(p, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Position = UDim2.new(0, screenX + dir.X * dist2, 0, screenY + dir.Y * dist2),
            Size     = UDim2.new(0, 2, 0, 2),
            BackgroundTransparency = 1,
        }):Play()
        task.delay(0.35, function() if p and p.Parent then p:Destroy() end end)
    end

    -- Limpiar despues de la animacion
    task.delay(0.45, function()
        if ring and ring.Parent then ring:Destroy() end
        if dot  and dot.Parent  then dot:Destroy()  end
    end)
end

-- ================================================================
-- FIX MOBILE SHOOT: TouchTap -> gun:Activate() para disparo normal
-- Solo actua si NO hay auto-shoot activo del hub.
-- ================================================================
do
    local _UIS_MF = game:GetService("UserInputService")
    local _isMobileShootFix = _UIS_MF.TouchEnabled and not _UIS_MF.KeyboardEnabled
    if _isMobileShootFix then
        local _msfLastTap = 0
        local _MSF_CD     = 0.15

        local function _msfGetEquippedGun()
            -- FIX MOBILE MM2: usar _findGun global que busca en char, Backpack
            -- y workspace[playerName] -- cubre todos los casos donde MM2 pone la gun.
            -- El bucle anterior solo buscaba en char:GetChildren() y fallaba cuando
            -- la gun estaba en Backpack o en el workspace model del jugador.
            if _findGun then
                local g = _findGun()
                if g then return g end
            end
            -- Fallback local por si _findGun no esta disponible aun
            local char = LocalPlayer.Character
            if not char then return nil end
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") then
                    local n = t.Name:lower()
                    if t:FindFirstChild("Shoot", true)
                    or t:FindFirstChild("GunClient", true)
                    or n:find("gun") or n:find("sheriff") or n:find("revolver") then
                        return t
                    end
                end
            end
            -- Buscar tambien en el Backpack (gun sin equipar pero lista para usar)
            local bp = LocalPlayer and LocalPlayer:FindFirstChildOfClass("Backpack")
            if bp then
                for _, t in ipairs(bp:GetChildren()) do
                    if t:IsA("Tool") then
                        local n = t.Name:lower()
                        if t:FindFirstChild("Shoot", true)
                        or t:FindFirstChild("GunClient", true)
                        or n:find("gun") or n:find("sheriff") or n:find("revolver") then
                            return t
                        end
                    end
                end
            end
            return nil
        end

        -- Helper: disparar la gun usando el remote Shoot directamente (bypass GunClient).
        -- Usado cuando Dual Gun esta activo para evitar que el brazo izquierdo forzado
        -- interfiera con la validacion del GunClient nativo de MM2.
        local function _msfFireDualGun(gun)
            local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            local cam   = workspace.CurrentCamera
            local gra   = myHRP and myHRP:FindFirstChild("GunRaycastAttachment")
            local originPos = (gra and gra.WorldPosition)
                or (cam and cam.CFrame.Position)
                or (myHRP and myHRP.Position + Vector3.new(0, 1.5, 0))
            local targetPos = originPos + (cam and cam.CFrame.LookVector * 500 or Vector3.new(0, 0, -500))
            local graWorldCF = gra and gra.WorldCFrame or nil
            local shootR = getShootRemote and getShootRemote(gun)
            if not shootR then
                pcall(function() gun:Activate() end)
                return
            end
            local originCF, targetCF = buildShootCFrames(originPos, targetPos, graWorldCF)
            if not originCF then
                originCF = graWorldCF or (myHRP and myHRP.CFrame) or cam.CFrame
                local dir = targetPos - originPos
                targetCF = dir.Magnitude > 0.01
                    and CFrame.lookAt(targetPos, originPos)
                    or (cam and cam.CFrame or originCF)
            end
            local ok = pcall(function() shootR:FireServer(originCF, targetCF) end)
            if not ok then pcall(function() shootR:FireServer(1, targetPos) end) end
        end

        _UIS_MF.TouchTap:Connect(function(positions, gameProcessed)
            if gameProcessed then return end
            if _G._autoShootEnabled or _G._ssEnabled then return end
            local now = tick()
            if now - _msfLastTap < _MSF_CD then return end
            _msfLastTap = now
            local gun = _msfGetEquippedGun()
            if not gun then return end
            -- FIX DUAL GUN MOBILE: si Dual Gun esta activo, usar remote Shoot
            -- directamente para evitar que el brazo izquierdo forzado interfiera
            -- con la validacion del GunClient y requiera multiples taps.
            if _G._dualGunState and _G._dualGunState.enabled then
                _msfFireDualGun(gun)
            else
                -- FIX DISPARO MOBILE: intentar gun:Activate() primero (GunClient nativo).
                -- Si falla o la gun no responde (algunos executors bloquean Activate),
                -- usar _fireGunMM2 como fallback directo al remote Shoot.
                local _activated = false
                pcall(function()
                    gun:Activate()
                    _activated = true
                end)
                if not _activated and _fireGunMM2 then
                    _fireGunMM2(gun)
                end
            end
        end)

        _UIS_MF.TouchLongPress:Connect(function(positions, state, gameProcessed)
            if gameProcessed then return end
            if state ~= Enum.UserInputState.Begin then return end
            if _G._autoShootEnabled or _G._ssEnabled then return end
            local gun = _msfGetEquippedGun()
            if not gun then return end
            if _G._dualGunState and _G._dualGunState.enabled then
                _msfFireDualGun(gun)
            else
                -- FIX DISPARO MOBILE: mismo fallback que TouchTap
                local _activated = false
                pcall(function()
                    gun:Activate()
                    _activated = true
                end)
                if not _activated and _fireGunMM2 then
                    _fireGunMM2(gun)
                end
            end
        end)
    end
end
