UserInputService.InputBegan:Connect(function(input, gameProcessed)
    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        _djLastClickTime = tick()
        _djPendingBomb   = true   -- nuevo click = puede haber 1 nueva bomba mia
        -- Marcar ownership en la bomba al momento del click
        _djBombOwnerTag = tick()  -- timestamp unico de este click
        -- FIX v20: reset automatico si no se consumio en 0.5s (evita saltos fantasma)
        local _snapTag = _djBombOwnerTag
        task.delay(0.5, function()
            if _djPendingBomb and _djBombOwnerTag == _snapTag then
                _djPendingBomb = false
            end
        end)
        -- Efecto visual en la posicion del cursor
        task.spawn(function()
            local mouse = LocalPlayer:GetMouse()
            _spawnClickEffect(mouse.X, mouse.Y)
        end)
    end
end)

workspace.ChildAdded:Connect(function(child)
    if not BombJumpSystem.enabled then return end
    if child.Name ~= "Handle" or not child:IsA("BasePart") then return end

    local myChar = LocalPlayer.Character
    if not myChar then return end
    local hrp      = myChar:FindFirstChild("HumanoidRootPart")
    local humanoid = myChar:FindFirstChildOfClass("Humanoid")
    if not hrp or not humanoid then return end
    if humanoid.Health <= 0 then return end

    -- -- FILTRO MEJORADO: solo mi bomba, nunca de otros jugadores ---------
    local now = tick()
    -- 1) Cooldown global entre activaciones
    if (now - _djLastTime) < DJ_COOLDOWN then return end
    -- 2) Debe haber un click reciente del LocalPlayer (< 0.3s) -- muy estricto
    local timeSinceClick = now - _djLastClickTime
    if timeSinceClick > 0.30 then return end
    -- 3) Solo procesar 1 Handle por click (evita doble activacion)
    if not _djPendingBomb then return end
    -- 4) Verificar que nuestro click fue JUSTO antes de este spawn (+/- 0.05s de tolerancia)
    if math.abs(now - _djBombOwnerTag) > 0.32 then return end
    -- 5) La bomba debe aparecer muy cerca del jugador (< 6 studs, mas estricto)
    local dist = (child.Position - hrp.Position).Magnitude
    if dist > 6 then return end   -- bomba de otro jugador aparece mas lejos
    -- 6) Verificar que NINGUN otro jugador lanzo una bomba al mismo tiempo
    --    Si otro jugador tiene una FakeBomb/Handle reciente dentro de 6 studs de ELLOS tambien, ignorar
    for _, otherP in ipairs(_cachedPlayers) do
        if otherP ~= LocalPlayer and otherP.Character then
            local oHRP = otherP.Character:FindFirstChild("HumanoidRootPart")
            if oHRP then
                local oDist = (child.Position - oHRP.Position).Magnitude
                -- Si la bomba aparecio MAS CERCA de otro jugador que de nosotros, es de ellos
                if oDist < dist - 0.5 then return end
            end
        end
    end
    -- FIX v20: check de dot eliminado -- falseaba cuando la bomba iba en angulo lateral
    -- Los filtros 1-6 ya son suficientes para ownership

    -- Es mi bomba: marcar como procesada y avanzar
    _djPendingBomb = false
    _djLastTime = now

    task.wait(0.016)
    pcall(function()
        local cam   = workspace.CurrentCamera
        local speed = child.AssemblyLinearVelocity.Magnitude
        if speed < 10 then speed = 60 end
        child.AssemblyLinearVelocity = cam.CFrame.LookVector * speed
    end)

    task.spawn(function()
        -- FIX: esperar al siguiente RenderStepped para sincronizar con el motor de fisica
        task.wait(0.06)
        local c = LocalPlayer.Character
        if not c then return end
        local r = c:FindFirstChild("HumanoidRootPart")
        if not r then return end

        -- TP justo encima de la bomba: usar posicion actual del Handle
        -- DJ_TP_OFFSET_Y = 3.0 studs -> queda parado encima sin flotar ni traversar
        local bombPos = child.Position
        local tpPos   = Vector3.new(bombPos.X, bombPos.Y + DJ_TP_OFFSET_Y, bombPos.Z)
        pcall(function()
            r.CFrame = CFrame.new(tpPos)
            r.AssemblyLinearVelocity = Vector3.zero
        end)
        -- FIX: task.defer para no bloquear -- sin Stepped:Wait
        -- Salto mejorado: usar AssemblyLinearVelocity con preservacion de velocidad lateral
        local hum = c:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health > 0 then
            local curVel = r.AssemblyLinearVelocity
            -- FIX: preservar velocidad XZ del jugador + impulso vertical
            r.AssemblyLinearVelocity = Vector3.new(
                curVel.X,
                DJ_JUMP_POWER,
                curVel.Z
            )
            -- FIX: JumpHeight sincronizado con MM2 (Humanoid.UseJumpPower = true en MM2)
            hum.JumpHeight = 7.2
            -- Restaurar JumpHeight original despues del salto
            task.delay(0.25, function()
                if hum and hum.Parent then
                    hum.JumpHeight = 7.2
                end
            end)
        end
    end)

    if _G.BombAutoSA then
        task.spawn(function()
            task.wait(0.016)
            local saChar = LocalPlayer.Character
            local bp  = LocalPlayer.Backpack
            local gun = saChar and _findGunIn(saChar)
            if not gun then
                for _, t in pairs(bp:GetChildren()) do
                    if t:IsA("Tool") and t.Name == "Gun" then
                        local saHum2 = saChar and saChar:FindFirstChildOfClass("Humanoid")
                        if saHum2 then pcall(function() saHum2:EquipTool(t) end) end
                        task.wait(0.12)
                        gun = saChar and saChar:FindFirstChild(t.Name)
                        break
                    end
                end
            end
 if not gun then CreateCustomNotification("BOMB SA", "No hay arma en el backpack!", 2); return end
            local murderer = findMurderer()
 if not murderer or not murderer.Character then CreateCustomNotification("BOMB SA", "No hay Murderer!", 2); return end
            local mChar = murderer.Character
            local mHRP = mChar:FindFirstChild("HumanoidRootPart")
            if not mHRP then return end
            local saHRP2 = saChar and saChar:FindFirstChild("HumanoidRootPart")
            local att   = getGunAttachment(gun, saHRP2)
            local tPos  = mHRP.Position
            local oCF   = att and att.WorldCFrame or hrp.CFrame
            local dir   = (tPos - oCF.Position).Unit
            local _gS   = gun:FindFirstChild("Shoot")
            local _gA   = hrp:FindFirstChild("GunRaycastAttachment")
            local _gOCF = (_gA and _gA.WorldCFrame) or oCF
            if _gS and _gS:IsA("RemoteEvent") then
                pcall(function() _gS:FireServer(_gOCF, CFrame.new(tPos, tPos+dir)) end)
            end
            local shootR = getShootRemote(gun)
            if shootR and shootR ~= _gS then
                pcall(function() shootR:FireServer(oCF, CFrame.new(tPos, tPos+dir)) end)
            end
            if not _gS and not shootR then
                -- FIX: sin redireccion de camara
                _fireGunMM2(gun)
            end
 CreateCustomNotification("BOMB SA", "Disparado a " .. murderer.Name, 2)
        end)
    end
end)

function _setupDoubleJumpForChar(character) end  -- kept for compatibility
