-- BOMB JUMP v3 -- workspace.ChildAdded (Handle aparece directo)
-- El Remote no se dispara en cliente -- detectamos el Handle
-- ===============================================================
_bombJumpEnabled = false
_bombJumpCooldown = 0
_bombLastClick = 0

-- Registrar clicks del jugador
UserInputService.InputBegan:Connect(function(inp, gp)
    if gp then return end
    if inp.UserInputType == Enum.UserInputType.MouseButton1
    or inp.UserInputType == Enum.UserInputType.Touch then
        _bombLastClick = tick()
    end
end)

-- Funcion central del salto
function _doBombJumpV3(handle)
    task.spawn(function()
        -- Esperar que vuele un poco
        task.wait(0.1)
        if not handle or not handle.Parent then return end

        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not myHRP or not myHum or myHum.Health <= 0 then return end

        local bombPos = handle.Position
        local tpPos   = Vector3.new(bombPos.X, bombPos.Y + 4, bombPos.Z)

        pcall(function()
            myHRP.CFrame = CFrame.new(tpPos)
            myHRP.AssemblyLinearVelocity = Vector3.zero
        end)

        -- FIX: task.defer em vez de Stepped:Wait -- nao bloqueia thread, sem lag
        task.defer(function()
            if myHRP and myHRP.Parent and myHum.Health > 0 then
                myHRP.AssemblyLinearVelocity = Vector3.new(0, 68, 0)
            end
        end)
    end)
end

-- Detectar Handle en workspace directamente
workspace.ChildAdded:Connect(function(obj)
    if not _bombJumpEnabled then return end
    if obj.Name ~= "Handle" or not obj:IsA("BasePart") then return end

    local now = tick()
    if now - _bombJumpCooldown < 0.5 then return end
    -- FIX v20: si BombJumpSystem ya proceso este frame, no disparar de nuevo
    if now - _djLastTime < DJ_COOLDOWN then return end
    -- FIX: reducido de 0.5 -> 0.4s para menor ventana de false positives
    if now - _bombLastClick > 0.40 then return end

    local myChar = LocalPlayer.Character
    local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
    local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
    if not myHRP or not myHum or myHum.Health <= 0 then return end

    local dist = (obj.Position - myHRP.Position).Magnitude
    -- FIX: reducido de 30 -> 8 studs para no activar con bombas lejanas de otros
    if dist > 8 then return end

    -- FIX: la bomba debe ser MAS CERCANA a nosotros que a CUALQUIER otro jugador
    -- (antes solo se chequeaba < dist-1, fallaba cuando otros estaban cerca)
    for _, p in ipairs(_cachedPlayers) do
        if p ~= LocalPlayer and p.Character then
            local oHRP = p.Character:FindFirstChild("HumanoidRootPart")
            if oHRP then
                local oDist = (obj.Position - oHRP.Position).Magnitude
                -- Si otro jugador esta igual o mas cerca de la bomba -> no es mia
                if oDist < dist then return end
            end
        end
    end

    _bombJumpCooldown = now
    _doBombJumpV3(obj)
end)

-- Funcion para sincronizar con BombJumpSystem.enabled
function _syncBombJump(enabled)
    _bombJumpEnabled       = enabled
    BombJumpSystem.enabled = enabled
end

-- Boton flotante BOMB -- separado del hub
_bombBtnRef = nil

function _createBombBtn()
    pcall(function()
        local cg = game:GetService("CoreGui")
        local o = cg:FindFirstChild("BombJumpBtn")
        if o then o:Destroy() end
    end)
    pcall(function()
        local o = LocalPlayer.PlayerGui:FindFirstChild("BombJumpBtn")
        if o then o:Destroy() end
    end)

    local sg = Instance.new("ScreenGui")
    sg.Name           = "BombJumpBtn"
    sg.ResetOnSpawn   = false
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.IgnoreGuiInset = true
    sg.DisplayOrder   = 9500
    pcall(function() sg.Parent = game:GetService("CoreGui") end)
    if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end

    local container = Instance.new("Frame", sg)
    container.Size                   = UDim2.new(0, 110, 0, 46)
    container.Position               = UDim2.new(0.5, -55, 1, -130)
    container.BackgroundTransparency = 1
    container.BorderSizePixel        = 0
    container.Active                 = true

    local btn = Instance.new("TextButton", container)
    btn.Size                   = UDim2.new(1, 0, 1, 0)
    btn.BackgroundColor3       = Color3.fromRGB(35, 35, 40)
    btn.BackgroundTransparency = 0.85
    btn.BorderSizePixel        = 0
    btn.Text                   = "BOMB"
    btn.FontFace = Font.fromEnum(Enum.Font.Arimo)
    btn.TextSize               = 15
    btn.TextColor3             = Color3.fromRGB(210, 210, 215)
    btn.AutoButtonColor        = false
    btn.ZIndex                 = 10
    btn.Active                 = true
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)
    local bStroke = Instance.new("UIStroke", btn)
    bStroke.Color        = ThemeColors.Primary
    bStroke.Thickness    = 1.5
    bStroke.Transparency = 0.3

    local dot = Instance.new("Frame", btn)
    dot.Size             = UDim2.new(0, 9, 0, 9)
    dot.Position         = UDim2.new(1, -12, 0, 4)
    dot.BackgroundColor3 = Color3.fromRGB(200, 30, 30)
    dot.BorderSizePixel  = 0
    dot.ZIndex           = 11
    Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)

    _bombBtnRef = {btn=btn, dot=dot, stroke=bStroke}

    local function setVisual(on)
        if on then
            btn.BackgroundColor3 = Color3.fromRGB(15, 85, 15)
            btn.TextColor3       = Color3.fromRGB(160, 160, 165)
            bStroke.Color        = Color3.fromRGB(200, 200, 200)
            dot.BackgroundColor3 = Color3.fromRGB(90, 90, 95)
        else
            btn.BackgroundColor3 = Color3.fromRGB(35, 35, 40)
            btn.TextColor3       = Color3.fromRGB(210, 210, 215)
            bStroke.Color        = ThemeColors.Primary
            dot.BackgroundColor3 = Color3.fromRGB(200, 30, 30)
        end
    end

    -- Drag
    local dragging, dragStart, startPos = false, nil, nil
    btn.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
        or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = true; dragStart = inp.Position; startPos = container.Position
        end
    end)
    btn.InputEnded:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
        or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
    UserInputService.InputChanged:Connect(function(inp)
        if not dragging then return end
        if inp.UserInputType ~= Enum.UserInputType.MouseMovement
        and inp.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = inp.Position - dragStart
        container.Position = UDim2.new(
            startPos.X.Scale, startPos.X.Offset + delta.X,
            startPos.Y.Scale, startPos.Y.Offset + delta.Y
        )
    end)

    btn.Activated:Connect(function()
        _syncBombJump(not _bombJumpEnabled)
        setVisual(_bombJumpEnabled)
 -- [notif removed]
    end)

    -- Inicializar visual
    setVisual(_bombJumpEnabled)
    return sg
end

-- El boton BOMB se crea automaticamente desde bomb_jump.lua (script separado)

function SimpleBombJump()
    local c  = LocalPlayer.Character
    local h  = c and c:FindFirstChildOfClass("Humanoid")
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    if not h or not hrp then return end
    h.Jump = true
    task.spawn(function()
        task.wait()
        if hrp and hrp.Parent then
            local curVel = hrp.AssemblyLinearVelocity
            if curVel.Y < 30 then
                hrp.AssemblyLinearVelocity = Vector3.new(curVel.X, 55, curVel.Z)
            end
        end
    end)

end


function SetBombCornerRadius(frame, shapeType)
    local corner = frame:FindFirstChildOfClass("UICorner")
    if not corner then return end
    if shapeType == "Circle" then corner.CornerRadius = UDim.new(1, 0)  end
    if shapeType == "Square" then corner.CornerRadius = UDim.new(0, 0)  end
    if shapeType == "Rounded" then corner.CornerRadius = UDim.new(0, 8)  end
end

function CreateBombJumpButton()
    -- Destruir ScreenGui anterior completo + sweep orphans
    if BombJumpSystem.gui then
        pcall(function() BombJumpSystem.gui:Destroy() end)
        BombJumpSystem.gui = nil
    end
    BombJumpSystem.btnFrame = nil
    local function sweepBJ(p)
        if not p then return end
        for _, g in ipairs(p:GetChildren()) do
            if g.Name == "BombJumpBindable" then pcall(function() g:Destroy() end) end
        end
    end
    sweepBJ(game:GetService("CoreGui"))
    pcall(function() sweepBJ(LocalPlayer:FindFirstChild("PlayerGui")) end)
    if not BombJumpSystem.buttonVisible then return end

    BombJumpSystem.gui = Instance.new("ScreenGui")
    BombJumpSystem.gui.Name           = "BombJumpBindable"
    BombJumpSystem.gui.ResetOnSpawn   = false
    BombJumpSystem.gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    BombJumpSystem.gui.IgnoreGuiInset = true
    pcall(function() BombJumpSystem.gui.Parent = game:GetService("CoreGui") end)
    if not BombJumpSystem.gui.Parent then BombJumpSystem.gui.Parent = LocalPlayer.PlayerGui end

    local frame = MakeCapyBindableFrame(BombJumpSystem.gui, "BOMB JUMP", function()
        if not BombJumpSystem.enabled then
 CreateCustomNotification("BOMB JUMP", "Enable Double Jump first!", 2)
            return
        end
        SimpleBombJump()
    end, 200, 400)

    BombJumpSystem.btnFrame = frame
end

function SetupBombJumpKeybind()
    UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if _G._hubDisableKeybinds then return end
        if not gameProcessed and input.KeyCode == Enum.KeyCode.B and BombJumpSystem.keyEnabled and BombJumpSystem.enabled then
            SimpleBombJump()
        end
    end)
