function CreateInfoPanel()
    DestroyInfoPanel()

    local anyOn = false
    for _, v in pairs(Settings.infoPanel) do
        if v then anyOn = true break end
    end
    if not anyOn then return end

    local playerGui = LocalPlayer:WaitForChild("PlayerGui")

    InfoPanelSystem.gui = Instance.new("ScreenGui")
    InfoPanelSystem.gui.Name = "InformationPanel_re"
    InfoPanelSystem.gui.ResetOnSpawn = false
    InfoPanelSystem.gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    InfoPanelSystem.gui.DisplayOrder = 8000
    -- FIX MOBILE: no bloquear inputs del juego (joystick/controles)
    pcall(function() InfoPanelSystem.gui.PassThroughNonActiveDescendants = true end)
    InfoPanelSystem.gui.Parent = playerGui

    if MainSystem and MainSystem.state then
        MainSystem.state.infoGui = InfoPanelSystem.gui
    end

    -- Detectar m?vil para ajustar tama?o y posici?n del panel
    local _isMobileInfo = pcall(function() return game:GetService("UserInputService").TouchEnabled end)
        and game:GetService("UserInputService").TouchEnabled
    local _vp        = workspace.CurrentCamera.ViewportSize
    local _panelW    = _isMobileInfo and math.min(220, _vp.X - 16) or 380
    local _initPosX  = _isMobileInfo and math.max(0, _vp.X - _panelW - 8) or (_vp.X - _panelW - 20)
    local _initPosY  = _isMobileInfo and 60 or 20

    local mainPanel = Instance.new("Frame", InfoPanelSystem.gui)
    mainPanel.Name = "MainPanel"
    mainPanel.Size = UDim2.new(0, _panelW, 0, 50)
    mainPanel.Position = UDim2.fromOffset(_initPosX, _initPosY)
    mainPanel.BackgroundColor3 = ThemeColors.Background
    mainPanel.BackgroundTransparency = 0.85
    mainPanel.BorderSizePixel = 0
    mainPanel.ClipsDescendants = true
    mainPanel.Active = false  -- FIX MOBILE: no bloquear joystick ni controles t?ctiles
    Instance.new("UICorner", mainPanel).CornerRadius = UDim.new(0, 12)

    -- FIX SCROLL+DRAG: drag movido al header (ver abajo), no al mainPanel completo
    -- Asi el scroll del mouse sobre el contenido NO arrastra el panel
    local _dragStart2, _startPos2, _dragging2 = nil, nil, false
    local _UIS2 = game:GetService("UserInputService")

    local mainStroke = Instance.new("UIStroke", mainPanel)
    mainStroke.Color = ThemeColors.Primary
    mainStroke.Thickness = 2.5

    local strokeGrad = Instance.new("UIGradient", mainStroke)
    strokeGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,    ThemeColors.Primary),    -- Celeste
        ColorSequenceKeypoint.new(0.33, ThemeColors.Accent),     -- Arena
        ColorSequenceKeypoint.new(0.66, ThemeColors.Secondary),  -- Oceano
        ColorSequenceKeypoint.new(1,    ThemeColors.Primary)     -- Celeste
    })

    task.spawn(function()
        while strokeGrad and strokeGrad.Parent do
            for r = 0, 360, 6 do  -- OPT: step 3->6, mitad de iteraciones
                if not strokeGrad or not strokeGrad.Parent then break end
                strokeGrad.Rotation = r
                task.wait(0.04)  -- OPT: 0.02->0.04
            end
        end
    end)

    local header = Instance.new("Frame", mainPanel)
    header.Size = UDim2.new(1, 0, 0, 38)
    header.BackgroundColor3 = ThemeColors.BackgroundLight
    header.BackgroundTransparency = 0.9
    header.BorderSizePixel = 0
    header.Active = true  -- FIX MOBILE: solo el header captura touch para arrastrar

    local titleLbl = Instance.new("TextLabel", header)
    titleLbl.Size = UDim2.new(1, 0, 1, 0)
    titleLbl.Position = UDim2.new(0, 10, 0, 0)
    titleLbl.BackgroundTransparency = 1
 titleLbl.Text = convertirFuenteCursor(" INFORMATION PANEL")
    titleLbl.FontFace = Font.fromEnum(Enum.Font.GothamBold)
    titleLbl.TextSize = 15
    titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    titleLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    titleLbl.TextStrokeTransparency = 0.3
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left

    -- FIX SCROLL+DRAG: drag conectado al header (barra de titulo)
    do
        if not pcall(function()
            local dd = Instance.new("UIDragDetector", header)
            dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
            dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
            dd.Dragged:Connect(function()
                local vp = workspace.CurrentCamera.ViewportSize
                local pw = mainPanel.AbsoluteSize.X
                local ph = mainPanel.AbsoluteSize.Y
                mainPanel.Position = UDim2.fromOffset(
                    math.clamp(mainPanel.Position.X.Offset, 0, math.max(0, vp.X - pw)),
                    math.clamp(mainPanel.Position.Y.Offset, 0, math.max(0, vp.Y - ph)))
            end)
        end) then
            header.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                    _dragging2 = true
                    _dragStart2 = input.Position
                    _startPos2  = mainPanel.Position
                end
            end)
            header.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                    _dragging2 = false
                    _dragStart2 = nil
                end
            end)
            _UIS2.InputChanged:Connect(function(input)
                if not _dragging2 or not _dragStart2 then return end
                if input.UserInputType ~= Enum.UserInputType.MouseMovement
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
                local delta = input.Position - _dragStart2
                local vp    = workspace.CurrentCamera.ViewportSize
                local pw    = mainPanel.AbsoluteSize.X
                local ph    = mainPanel.AbsoluteSize.Y
                local newX  = math.clamp(_startPos2.X.Offset + delta.X, 0, vp.X - pw)
                local newY  = math.clamp(_startPos2.Y.Offset + delta.Y, 0, vp.Y - ph)
                mainPanel.Position = UDim2.fromOffset(newX, newY)
                -- En touch: actualizar la referencia en cada frame para evitar acumulaci?n de delta
                if input.UserInputType == Enum.UserInputType.Touch then
                    _dragStart2 = input.Position
                    _startPos2  = mainPanel.Position
                end
            end)
        end
    end

    local scroll = Instance.new("ScrollingFrame", mainPanel)
    scroll.Name = "InfoScroll"
    scroll.Size = UDim2.new(1, -16, 1, -44)
    scroll.Position = UDim2.new(0, 8, 0, 42)
    scroll.BackgroundTransparency = 1
    scroll.BorderSizePixel = 0
    scroll.ScrollBarThickness = 3
    scroll.ScrollBarImageColor3 = ThemeColors.Primary
    scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    -- FIX MOBILE: en m?vil el scroll no debe capturar toda el ?rea del panel
    if _isMobileInfo then scroll.Active = false end

    local scrollLayout = Instance.new("UIListLayout", scroll)
    scrollLayout.Padding = UDim.new(0, 2)
    scrollLayout.SortOrder = Enum.SortOrder.LayoutOrder
    scrollLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center

    local _lblTxtSz = _isMobileInfo and 10 or 11
    local _sepTxtSz = _isMobileInfo and 10 or 12
    local _lblH     = _isMobileInfo and 16 or 18
    local _sepH     = _isMobileInfo and 17 or 20

    function makeLabel(text, color)
        local lbl = Instance.new("TextLabel", scroll)
        lbl.Size = UDim2.new(1, -4, 0, _lblH)
        lbl.BackgroundTransparency = 1
        lbl.Text = convertirFuenteCursor(text)
        lbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
        lbl.TextSize = _lblTxtSz
        lbl.TextColor3 = color or ThemeColors.TextPrimary
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        lbl.TextWrapped = true
        lbl.TextScaled = false
        return lbl
    end

    function makeSep(text, color)
        local lbl = Instance.new("TextLabel", scroll)
        lbl.Size = UDim2.new(1, -4, 0, _sepH)
        lbl.BackgroundTransparency = 1
        lbl.Text = convertirFuenteCursor(text)
        lbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
        lbl.TextSize = _sepTxtSz
        lbl.TextColor3 = color or ThemeColors.TextPrimary
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        return lbl
    end

    InfoPanelSystem.active = true

    task.spawn(function()
        InfoPanelSystem.loopRunning = true
        while InfoPanelSystem.active and InfoPanelSystem.gui and InfoPanelSystem.gui.Parent do

            for _, c in pairs(scroll:GetChildren()) do
                if c:IsA("TextLabel") then c:Destroy() end
            end

            local lineCount = 0

            if Settings.infoPanel.murdererInfo then
                makeSep(" MURDERER ", Color3.fromRGB(255,   0,  40))
                local murderer = findMurderer()
                if murderer then
                    makeLabel("Name: " .. murderer.Name, ThemeColors.Accent)
                    makeLabel("Role: MURDERER ", Color3.fromRGB(58, 58, 58))
                    if murderer.Character and murderer.Character:FindFirstChild("HumanoidRootPart")
                    and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                        local _mIP  = murderer.Character:FindFirstChild("HumanoidRootPart")
                        local _myIP = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        local d = _mIP and _myIP and (_mIP.Position - _myIP.Position).Magnitude or 0
                        makeLabel("Distance: " .. math.floor(d) .. " studs", ThemeColors.Aurora4)
                    end
                    lineCount += 4
                else
                    makeLabel("Murderer: NOT FOUND", ThemeColors.TextSecondary)
                    lineCount += 2
                end
            end

            if Settings.infoPanel.sheriffInfo then
                makeSep(" SHERIFF ", ThemeColors.Primary)
                local sheriff = findSheriffPlayer()
                if sheriff then
                    makeLabel("Name: " .. sheriff.Name, ThemeColors.Aurora2)
                    makeLabel("Role: SHERIFF ", Color3.fromRGB(0, 255, 0))
                    if sheriff.Character and sheriff.Character:FindFirstChild("HumanoidRootPart")
                    and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                        local _sIP  = sheriff.Character:FindFirstChild("HumanoidRootPart")
                        local _myIP2 = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        local d = _sIP and _myIP2 and (_sIP.Position - _myIP2.Position).Magnitude or 0
                        makeLabel("Distance: " .. math.floor(d) .. " studs", ThemeColors.Aurora4)
                    end
                    lineCount += 4
                else
                    makeLabel("Sheriff: NOT FOUND", ThemeColors.TextSecondary)
                    lineCount += 2
                end
            end

            if Settings.infoPanel.playerStats then
                makeSep(" YOUR STATS ", ThemeColors.Primary)
                local myRole = GetPlayerRole(LocalPlayer)
                makeLabel("Name: " .. LocalPlayer.Name, ThemeColors.Aurora1)
                makeLabel("Role: " .. myRole, GetRoleColor(myRole))
                if LocalPlayer.Character then
                    local hum = LocalPlayer.Character:FindFirstChild("Humanoid")
                    if hum then
                        makeLabel("HP:   " .. math.floor(hum.Health) .. " / " .. math.floor(hum.MaxHealth), Color3.fromRGB(255, 50, 50))
                    end
                    local hrp = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local p = hrp.Position
                        makeLabel(string.format("Pos:  %.0f, %.0f, %.0f", p.X, p.Y, p.Z), ThemeColors.TextSecondary)
                    end
                end
                lineCount += 5
            end

            if Settings.infoPanel.mapInfo then
                makeSep(" MAP ", ThemeColors.Aurora3)
                local mapName, totalCoins = GetCurrentMap()
                makeLabel("Map:   " .. (mapName or "Lobby / Unknown"), ThemeColors.Aurora2)
                makeLabel("Coins: " .. tostring(totalCoins), ThemeColors.Primary)
                lineCount += 3
            end

            if Settings.infoPanel.roleInfo then
                makeSep(" ROLES ", ThemeColors.Aurora4)
                local inn, mur, she = 0, 0, 0
                for _, p in ipairs(_cachedPlayers) do
                    local r = GetPlayerRole(p)
                    if r == "Murderer" then mur += 1
                    elseif r == "Sheriff" then she += 1
                    else inn += 1 end
                end
                makeLabel("Innocents: " .. inn, Color3.fromRGB(255, 50, 50))
                makeLabel("Murderers: " .. mur, Color3.fromRGB(255,   0,  40))
                makeLabel("Sheriffs:  " .. she, Color3.fromRGB(0, 255, 0))
                lineCount += 4
            end

            if Settings.infoPanel.performanceInfo then
                makeSep(" PERFORMANCE ", ThemeColors.Aurora2)
                -- OPT: usar _lastDt global en vez de RenderStepped:Wait() bloqueante
                local fps = math.floor(1 / math.max(_lastDt or 1/60, 0.001))
                local fpsColor = fps >= 55 and Color3.fromRGB(130, 130, 135)
                             or fps >= 30 and Color3.fromRGB(255,200,50)
                             or Color3.fromRGB(255,80,80)
                makeLabel("FPS:  " .. tostring(fps), fpsColor)
                makeLabel("Ping: ~" .. tostring(CombatState.currentPing) .. " ms", ThemeColors.Aurora3)
                lineCount += 3
            end

            if Settings.infoPanel.gameInfo then
                makeSep(" GAME INFO ", ThemeColors.Primary)
                makeLabel("Game:    Murder Mystery 2", ThemeColors.Aurora1)
                makeLabel("Version: " .. tostring(game.PlaceVersion), ThemeColors.Aurora3)
                makeLabel("Creator: Nikilis", ThemeColors.TextSecondary)
                lineCount += 4
            end

            if Settings.infoPanel.coinInfo then
                makeSep(" COINS ", ThemeColors.Primary)
                local allCoins = GetAllCoins()
                makeLabel("On map: " .. tostring(#allCoins), ThemeColors.Aurora1)
                if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                    local nearCoin, dist = FindNearestCoin(allCoins)
                    if dist < math.huge and nearCoin then
                        makeLabel("Nearest: " .. math.floor(dist) .. " studs", ThemeColors.Aurora2)
                        makeLabel(string.format("CoinPos: %.0f, %.0f, %.0f", nearCoin.Position.X, nearCoin.Position.Y, nearCoin.Position.Z), Color3.fromRGB(255,215,0))
                    else
                        makeLabel("Nearest: No coins found", ThemeColors.TextSecondary)
                    end
                end
                lineCount += 4
            end

            if lineCount == 0 then
                DestroyInfoPanel()
                return
            end

            local _maxH  = _isMobileInfo and math.min(320, _vp.Y - _initPosY - 20) or 540
            local totalH = math.clamp(lineCount * 20 + 55, 60, _maxH)
            TweenService:Create(mainPanel, TweenInfo.new(0.25), {
                Size = UDim2.new(0, _panelW, 0, totalH)
            }):Play()

            task.wait(0.5)
        end
        InfoPanelSystem.loopRunning = false
    end)
end


