function CreateMainUI_InfoPanel()
 CreateSection(leftColumn, "", "INFORMATION PANEL", ThemeColors.Aurora1)

    local function CreateInfoToggleBtn(parent, label, key, color)
        CreateAuroraToggle(parent, label, function(on)
            Settings.infoPanel[key] = on
            if on then
                if not InfoPanelSystem.gui or not InfoPanelSystem.gui.Parent then
                    CreateInfoPanel()
                end
                CreateCustomNotification(LocalPlayer.Name .. " Says:", label:gsub("[^%32-%127]", "") .. " -- panel live", 2)
            else
                local anyOn = false
                for _, v in pairs(Settings.infoPanel) do if v then anyOn = true; break end end
                if not anyOn then DestroyInfoPanel() end
                CreateCustomNotification(LocalPlayer.Name .. " Says:", label:gsub("[^\32-\127]", "") .. " -- panel hidden", 2)
            end
        end, Settings.infoPanel[key] or false)
    end

    CreateInfoToggleBtn(leftColumn, " Murderer Information","murdererInfo",    ThemeColors.Accent)
    CreateInfoToggleBtn(leftColumn, " Sheriff Information", "sheriffInfo",     ThemeColors.Aurora2)
    CreateInfoToggleBtn(leftColumn, " Your Player Stats",   "playerStats",     ThemeColors.Primary)
    CreateInfoToggleBtn(leftColumn, " Map Information",     "mapInfo",         ThemeColors.Aurora3)
    CreateInfoToggleBtn(leftColumn, " Performance Stats",   "performanceInfo", ThemeColors.Aurora2)
    CreateInfoToggleBtn(leftColumn, " Game Information",    "gameInfo",        ThemeColors.Primary)
    CreateInfoToggleBtn(leftColumn, " Coin Information",    "coinInfo",        ThemeColors.Primary)

    CreateButton(leftColumn, " ENABLE ALL INFO", Color3.fromRGB(255, 50, 50), function()
        for k in pairs(Settings.infoPanel) do Settings.infoPanel[k] = true end
        CreateInfoPanel()
        CreateCustomNotification(LocalPlayer.Name .. " Says:", "Every info panel section is now broadcasting", 3)
    end)

    CreateButton(leftColumn, " DISABLE ALL INFO", ThemeColors.Primary, function()
        for k in pairs(Settings.infoPanel) do Settings.infoPanel[k] = false end
        DestroyInfoPanel()
        CreateCustomNotification(LocalPlayer.Name .. " Says:", "Info panels cleared -- running silent", 3)
    end)
end

