function CreateMainUI_Fly()
    local S = MainSystem.state

    -- ==================================================
    --  FLY
    -- ==================================================
    CreateSection(leftColumn, "", "FLY", ThemeColors.Aurora2)

    -- -- Variables internas de vuelo --
    local flyNoclipConn       = nil
    -- AUTO-SAFE: usar _G._flyEnabled para que el estado persista entre builds de tab.
    -- _readToggleFile lee el .txt individual; si dice "true" y el toggle no estaba
    -- en el JSON (_G._toggleStates), sincronizamos aqui antes de crear el toggle.
    do
        local _fState = _readToggleFile("Fly (WASD + Space/Ctrl + Shift boost)")
        if _fState == true then
            _G._toggleStates = _G._toggleStates or {}
            _G._toggleStates["Fly (WASD + Space/Ctrl + Shift boost)"] = true
        end
        if _G._flyEnabled == nil then _G._flyEnabled = false end
    end
    local flyNoclipEnabled    = (_G._toggleStates and _G._toggleStates["Fly (WASD + Space/Ctrl + Shift boost)"]) == true
    local flyNoclipSpeed      = 40
    local flyNoclipAccel      = 12
    local flyNoclipBoost      = 2.5
    local flyNoclipGravity    = false
    local flyNoclipInvisWalls = true
    local flyNoclipUpSpeed    = 40
    local flyNoclipDownSpeed  = 40
    local flyNoclipSmoothness = 8
    local flyNoclipMaxHeight  = 9999
    local flyCurrentVelocity  = Vector3.zero

    local function applyNoclip(char, on)
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") then p.CanCollide = not on end
        end
    end

    local _flySwimTracks = {}
    local function _playSwimAnim(h)
        pcall(function()
            for _, tr in ipairs(_flySwimTracks) do pcall(function() tr:Stop() end) end
            _flySwimTracks = {}
            local animator = h:FindFirstChildOfClass("Animator")
            if not animator then return end
            local IDS = {"507784897", "481825862", "10921264784"}
            for _, id in ipairs(IDS) do
                local ok, tr = pcall(function()
                    local a = Instance.new("Animation")
                    a.AnimationId = "rbxassetid://" .. id
                    local t = animator:LoadAnimation(a)
                    t.Priority = Enum.AnimationPriority.Action4
                    t.Looped = true; t:Play(0.15)
                    return t
                end)
                if ok and tr then table.insert(_flySwimTracks, tr) end
            end
        end)
    end
    local function _stopSwimAnim()
        for _, tr in ipairs(_flySwimTracks) do pcall(function() tr:Stop() end) end
        _flySwimTracks = {}
    end

    local _flyNoclipWallConn = nil

    local function startFlyNoclip()
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not hrp or not hum then return end
        if flyNoclipConn then flyNoclipConn:Disconnect(); flyNoclipConn = nil end
        if _flyNoclipWallConn then _flyNoclipWallConn:Disconnect(); _flyNoclipWallConn = nil end
        pcall(function() local v = hrp:FindFirstChild("FlyBV"); if v then v:Destroy() end end)
        pcall(function() local v = hrp:FindFirstChild("FlyBG"); if v then v:Destroy() end end)
        _playSwimAnim(hum)
        hum.PlatformStand = true
        local bv = Instance.new("BodyVelocity", hrp)
        bv.Name = "FlyBV"; bv.MaxForce = Vector3.new(1e5,1e5,1e5); bv.Velocity = Vector3.zero
        local bg = Instance.new("BodyGyro", hrp)
        bg.Name = "FlyBG"; bg.MaxTorque = Vector3.new(1e5,1e5,1e5); bg.P = 1e4; bg.D = 500
        if flyNoclipInvisWalls then applyNoclip(char, true) end
        -- MOBILE SUPPORT: detectar si el dispositivo es movil
        local _isMobile = (function()
            local ok, res = pcall(function() return UserInputService.TouchEnabled end)
            return ok and res
        end)()

        -- MOBILE: botones flotantes de subir/bajar para movil
        -- Variables en _G para que todos los sistemas de fly las compartan
        _G._flyUpHeld    = _G._flyUpHeld    or false
        _G._flyDownHeld  = _G._flyDownHeld  or false
        _G._flyBoostHeld = _G._flyBoostHeld or false
        local _flyMobileGui = nil
        local _flyUpHeld    = _G._flyUpHeld
        local _flyDownHeld  = _G._flyDownHeld
        local _flyBoostHeld = _G._flyBoostHeld

        if _isMobile then
            _flyMobileGui = Instance.new("ScreenGui")
            _flyMobileGui.Name = "FlyMobileControls_HUB"
            _flyMobileGui.ResetOnSpawn = false
            _flyMobileGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            _flyMobileGui.IgnoreGuiInset = true
            _flyMobileGui.DisplayOrder = 9995
            pcall(function() _flyMobileGui.Parent = game:GetService("CoreGui") end)
            if not _flyMobileGui.Parent then _flyMobileGui.Parent = LocalPlayer.PlayerGui end

            local vp = workspace.CurrentCamera.ViewportSize
            local btnSize = 70

            local function _makeFlyBtn(label, color, posX, posY, onDown, onUp)
                local btn = Instance.new("TextButton", _flyMobileGui)
                btn.Size = UDim2.fromOffset(btnSize, btnSize)
                btn.Position = UDim2.fromOffset(posX, posY)
                btn.BackgroundColor3 = color
                btn.BackgroundTransparency = 0.3
                btn.Text = label
                btn.TextColor3 = Color3.fromRGB(255, 255, 255)
                btn.FontFace = Font.fromEnum(Enum.Font.GothamBold)
                btn.TextSize = 14
                btn.BorderSizePixel = 0
                btn.AutoButtonColor = false
                btn.ZIndex = 300
                Instance.new("UICorner", btn).CornerRadius = UDim.new(1, 0)
                local stroke = Instance.new("UIStroke", btn)
                stroke.Color = Color3.fromRGB(255, 255, 255)
                stroke.Thickness = 1.5
                stroke.Transparency = 0.4
                btn.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.Touch
                    or inp.UserInputType == Enum.UserInputType.MouseButton1 then
                        onDown()
                        TweenService:Create(btn, TweenInfo.new(0.08), {BackgroundTransparency = 0.05}):Play()
                    end
                end)
                btn.InputEnded:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.Touch
                    or inp.UserInputType == Enum.UserInputType.MouseButton1 then
                        onUp()
                        TweenService:Create(btn, TweenInfo.new(0.08), {BackgroundTransparency = 0.3}):Play()
                    end
                end)
                return btn
            end

            -- Boton SUBIR (derecha, arriba)
            _makeFlyBtn("?\nSUBIR", Color3.fromRGB(60, 120, 220),
                vp.X - btnSize * 2 - 20, vp.Y - btnSize * 3 - 20,
                function() _flyUpHeld = true;    _G._flyUpHeld = true end,
                function() _flyUpHeld = false;   _G._flyUpHeld = false end)

            -- Boton BAJAR (derecha, centro)
            _makeFlyBtn("?\nBAJAR", Color3.fromRGB(220, 80, 60),
                vp.X - btnSize * 2 - 20, vp.Y - btnSize * 2 - 10,
                function() _flyDownHeld = true;  _G._flyDownHeld = true end,
                function() _flyDownHeld = false; _G._flyDownHeld = false end)

            -- Boton BOOST (derecha, abajo)
            _makeFlyBtn("?\nBOOST", Color3.fromRGB(200, 160, 20),
                vp.X - btnSize - 10, vp.Y - btnSize * 2 - 10,
                function() _flyBoostHeld = true;  _G._flyBoostHeld = true end,
                function() _flyBoostHeld = false; _G._flyBoostHeld = false end)
        end

        flyNoclipConn = _safeConnect(RunService.Heartbeat, function(dt)
            if not flyNoclipEnabled then
                flyNoclipConn:Disconnect(); flyNoclipConn = nil
                -- FIX DESYNC: frenar completamente antes de destruir BodyVelocity
                -- Si bv se destruye con velocidad != 0, el servidor no recibe la posicion
                -- correcta y los demas te siguen viendo en el lugar anterior.
                pcall(function() bv.Velocity = Vector3.zero end)
                pcall(function() bv.MaxForce = Vector3.zero end)
                -- Esperar 2 frames para que el motor de fisica propague el frenado al servidor
                task.wait(0.05)
                -- Guardar posicion actual ANTES de restaurar colisiones
                -- (al restaurar CanCollide el personaje puede saltar fisicamente)
                local _landPos = hrp and hrp.Position or nil
                pcall(function() bv:Destroy() end); pcall(function() bg:Destroy() end)
                _stopSwimAnim()
                -- Restaurar colisiones PRIMERO, luego PlatformStand
                -- Si se hace al rev?s el personaje cae con PlatformStand=false antes
                -- de tener colisiones, causando que atraviese el suelo del lado cliente
                applyNoclip(LocalPlayer.Character, false)
                task.wait(0.033)  -- 2 frames para que el motor registre las colisiones
                if hum and hum.Parent then
                    hum.PlatformStand = false
                    -- FIX DESYNC: forzar al servidor a aceptar la posicion actual
                    -- cambiando el estado a GettingUp (hace un network ownership assertion)
                    pcall(function()
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end)
                end
                -- Anclar momentaneamente el HRP para que el servidor registre la posicion exacta
                -- antes de que la gravedad lo mueva (evita que el servidor lo vea en otro lugar)
                if hrp and hrp.Parent and _landPos then
                    pcall(function()
                        local _oldAnchored = hrp.Anchored
                        hrp.Anchored = true
                        hrp.CFrame = CFrame.new(_landPos)
                        task.wait(0.05)
                        hrp.Anchored = _oldAnchored
                    end)
                end
                -- Limpiar GUI movil
                if _flyMobileGui then
                    pcall(function() _flyMobileGui:Destroy() end)
                    _flyMobileGui = nil
                end
                _flyUpHeld = false; _flyDownHeld = false; _flyBoostHeld = false
                return
            end
            local cam = _Camera
            local dir = Vector3.zero

            -- MOBILE: usar MoveDirection del Humanoid (thumbstick) para WASD
            -- PC: usar IsKeyDown normal
            local isBoosting = false
            if _isMobile then
                -- Thumbstick da la direccion de movimiento en el plano XZ
                local currentChar = LocalPlayer.Character
                local currentHum  = currentChar and currentChar:FindFirstChildOfClass("Humanoid")
                if currentHum then
                    local moveDir = currentHum.MoveDirection
                    if moveDir.Magnitude > 0.1 then
                        -- Convertir moveDir (world space) a camara-relativo
                        local flatMove = Vector3.new(moveDir.X, 0, moveDir.Z)
                        dir = flatMove
                    end
                end
                -- Botones moviles de subir/bajar/boost
                if _flyUpHeld   then dir = dir + Vector3.new(0, flyNoclipUpSpeed   / flyNoclipSpeed, 0) end
                if _flyDownHeld then dir = dir - Vector3.new(0, flyNoclipDownSpeed  / flyNoclipSpeed, 0) end
                isBoosting = _flyBoostHeld
            else
                isBoosting = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
                if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
                -- Subir/bajar con velocidades independientes
                if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                    dir = dir + Vector3.new(0, flyNoclipUpSpeed / flyNoclipSpeed, 0)
                end
                if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.Q) then
                    dir = dir - Vector3.new(0, flyNoclipDownSpeed / flyNoclipSpeed, 0)
                end
            end

            local spd = flyNoclipSpeed * (isBoosting and flyNoclipBoost or 1)
            -- Clamp altura maxima
            if hrp and hrp.Position.Y > flyNoclipMaxHeight and dir.Y > 0 then
                dir = Vector3.new(dir.X, 0, dir.Z)
            end
            local targetVel = dir.Magnitude > 0 and dir.Unit * spd or Vector3.zero
            -- Interpolacion suave con flyNoclipSmoothness
            local alpha = math.clamp(flyNoclipSmoothness * dt, 0, 1)
            flyCurrentVelocity = flyCurrentVelocity:Lerp(targetVel, alpha)
            bv.Velocity = flyCurrentVelocity
            bg.CFrame = cam.CFrame
        end)
    end

    -- Toggle principal de Fly
    -- AUTO-SAFE: initialValue lee _G._toggleStates (ya sincronizado con el .txt arriba).
    -- Al re-ejecutar el hub: _readToggleFile devuelve "true" -> _G._toggleStates = true
    -- -> initialValue = true -> CreateAuroraToggle dispara callback(true) via _autoRestoreOnReexec.
    -- Al cambiar de tab (rebuild): estado ya guardado en _G._toggleStates, toggle arranca en ON
    -- pero callback NO se re-dispara (isPhysical=true + _isTabRebuild=true).
    local _flyInitVal = (_G._toggleStates and _G._toggleStates["Fly (WASD + Space/Ctrl + Shift boost)"]) == true
    CreateToggle(leftColumn, "Fly (WASD + Space/Ctrl + Shift boost)", function(on)
        flyNoclipEnabled = on
        _G._flyEnabled   = on   -- sincronizar global para keybind y auto-safe
        if on then
            startFlyNoclip()
            -- [notif removed]
        else
            -- [notif removed]
        end
    end, _flyInitVal)

    -- AUTO-SAFE: si al construir el tab el toggle ya estaba ON (re-ejecucion real,
    -- el sistema _autoRestoreOnReexec aun no disparo el callback porque espera al tab),
    -- activar fly directamente aqui sin esperar la cola de restauracion.
    if _flyInitVal and not flyNoclipEnabled then
        flyNoclipEnabled = true
        _G._flyEnabled   = true
        task.defer(function()
            task.wait(0.15)  -- esperar un frame para que el personaje este listo
            pcall(startFlyNoclip)
        end)
    end

    -- Keybind para toggle de Fly
    do
        local _flyKeybind = Enum.KeyCode.G
        local _flyKeybindConn = nil
        local _flyKeybindActive = false

        -- Selector de tecla
        local _flyKeyRow = Instance.new("Frame", leftColumn)
        _flyKeyRow.Size = UDim2.new(1, -4, 0, 36)
        _flyKeyRow.BackgroundColor3 = Color3.fromRGB(90, 15, 25)
        _flyKeyRow.BackgroundTransparency = 0.75
        _flyKeyRow.BorderSizePixel = 0
        Instance.new("UICorner", _flyKeyRow).CornerRadius = UDim.new(0, 8)
        local _flyKeyStroke = Instance.new("UIStroke", _flyKeyRow)
        _flyKeyStroke.Color = ThemeColors.Aurora2; _flyKeyStroke.Thickness = 1.2

        local _flyKeyLbl = Instance.new("TextLabel", _flyKeyRow)
        _flyKeyLbl.Size = UDim2.new(0.6, 0, 1, 0); _flyKeyLbl.Position = UDim2.new(0, 8, 0, 0)
        _flyKeyLbl.BackgroundTransparency = 1; _flyKeyLbl.Text = "Keybind Fly"
        _flyKeyLbl.TextColor3 = ThemeColors.TextPrimary; _flyKeyLbl.TextSize = 12
        _flyKeyLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        _flyKeyLbl.TextXAlignment = Enum.TextXAlignment.Left; _flyKeyLbl.ZIndex = 2

        local _flyKeyBtn = Instance.new("TextButton", _flyKeyRow)
        _flyKeyBtn.Size = UDim2.new(0, 70, 0, 22); _flyKeyBtn.AnchorPoint = Vector2.new(1, 0.5)
        _flyKeyBtn.Position = UDim2.new(1, -6, 0.5, 0)
        _flyKeyBtn.BackgroundColor3 = ThemeColors.Aurora2; _flyKeyBtn.BackgroundTransparency = 0.35
        _flyKeyBtn.Text = "[ G ]"; _flyKeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
        _flyKeyBtn.TextSize = 11; _flyKeyBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        _flyKeyBtn.BorderSizePixel = 0; _flyKeyBtn.ZIndex = 3
        Instance.new("UICorner", _flyKeyBtn).CornerRadius = UDim.new(0, 6)

        local _flyListening = false
        _flyKeyBtn.Activated:Connect(function()
            if _flyListening then return end
            _flyListening = true
            _flyKeyBtn.Text = "[ ... ]"
            _flyKeyBtn.BackgroundTransparency = 0.1
            local conn; conn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp then return end
                if inp.UserInputType == Enum.UserInputType.Keyboard then
                    _flyKeybind = inp.KeyCode
                    _flyKeyBtn.Text = "[ " .. tostring(inp.KeyCode):gsub("Enum.KeyCode.", "") .. " ]"
                    _flyKeyBtn.BackgroundTransparency = 0.35
                    _flyListening = false
                    conn:Disconnect()
                end
            end)
        end)

        -- Escuchar keybind en tiempo real
        _flyKeybindConn = UserInputService.InputBegan:Connect(function(inp, gp)
            if gp then return end
            if _G._hubDisableKeybinds then return end
            if inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == _flyKeybind and not _flyListening then
                flyNoclipEnabled = not flyNoclipEnabled
                _G._flyEnabled   = flyNoclipEnabled  -- sincronizar global
                -- Guardar en .txt igual que el LocalScript de referencia
                pcall(_saveToggleFile, "Fly (WASD + Space/Ctrl + Shift boost)", flyNoclipEnabled)
                if flyNoclipEnabled then startFlyNoclip() end
                -- [notif removed]
            end
        end)
    end

    -- Bindable Fly
    local _flyBindGui = nil
    CreateToggle(leftColumn, "Show Bindable Button", function(on)
        if on then
            if _flyBindGui then pcall(function() _flyBindGui:Destroy() end) end
            local sg = Instance.new("ScreenGui")
            sg.Name = "FlyBind_HUB"; sg.ResetOnSpawn = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
            pcall(function() sg.Parent = CoreGui end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _flyBindGui = sg
            MakeCapyBindableFrame(sg, "FLY", function()
                flyNoclipEnabled = not flyNoclipEnabled
                _G._flyEnabled   = flyNoclipEnabled  -- sincronizar global
                pcall(_saveToggleFile, "Fly (WASD + Space/Ctrl + Shift boost)", flyNoclipEnabled)
                if flyNoclipEnabled then startFlyNoclip() end
                -- [notif removed]
            end, 20, 200)
        else
            if _flyBindGui then pcall(function() _flyBindGui:Destroy() end); _flyBindGui = nil end
            DestroyCapyBind("FLY")
        end
    end, false)

    -- -- Sliders de Fly --
    CreateSlider(leftColumn, "Horizontal Speed", 5, 500, flyNoclipSpeed, function(v) flyNoclipSpeed = v end)
    CreateSlider(leftColumn, "Ascend Speed (Space)", 5, 500, flyNoclipUpSpeed, function(v) flyNoclipUpSpeed = v end)
    CreateSlider(leftColumn, "Descend Speed (Ctrl/Q)", 5, 500, flyNoclipDownSpeed, function(v) flyNoclipDownSpeed = v end)
    CreateSlider(leftColumn, "Multiplicador Boost (Shift)", 1, 20, flyNoclipBoost, function(v) flyNoclipBoost = v end)
    CreateSlider(leftColumn, "Suavizado de movimiento", 1, 30, flyNoclipSmoothness, function(v) flyNoclipSmoothness = v end)
    CreateSlider(leftColumn, "Altura maxima (studs)", 50, 9999, flyNoclipMaxHeight, function(v) flyNoclipMaxHeight = v end)
    CreateSlider(leftColumn, "Gravedad al desactivar", 20, 196, 196, function(v) workspace.Gravity = v end)
end



function CreateMainUI_SwimFly()
 CreateSection(rightColumn, "", "BUG TRAMP", ThemeColors.Accent)

    local bugTrapMain = { enabled = false, conn = nil, escapeConn = nil }

    local function hookBugTrap(state)
        if state.conn then state.conn:Disconnect(); state.conn = nil end
        local ts = game.ReplicatedStorage:FindFirstChild("TrapSystem")
        local function doHook_wall(ts2)
            local hl = ts2:FindFirstChild("TrapHitLocal")
            if not hl then hl = ts2:WaitForChild("TrapHitLocal", 10) end
            if not hl then return end
            state.conn = hl.OnClientEvent:Connect(function(_, player)
                if player ~= LocalPlayer or not state.enabled then return end
                task.spawn(function()
                    local char = LocalPlayer.Character
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    for _ = 1, 80 do
                        if not state.enabled then break end
                        if hum and hum.Parent then hum.WalkSpeed = 16; hum.JumpPower = 50 end
                        task.wait(0.016)
                    end
                end)
            end)
        end
        if ts then doHook_wall(ts)
        else task.spawn(function()
            ts2 = game.ReplicatedStorage:WaitForChild("TrapSystem", 30)
            if ts2 and state.enabled then doHook_wall(ts2) end
        end) end
    end

 CreateToggle(rightColumn, "Bug Tramp (no te atrapa)", function(on)
        bugTrapMain.enabled = on
        if bugTrapMain.escapeConn then bugTrapMain.escapeConn:Disconnect(); bugTrapMain.escapeConn = nil end
        if on then
            hookBugTrap(bugTrapMain)
            -- task.spawn+wait en vez de Heartbeat: solo chequea WalkSpeed cada 0.15s
            bugTrapMain.escapeConn = task.spawn(function()
                while bugTrapMain.enabled do
                    task.wait(0.15)
                    if not bugTrapMain.enabled then break end
                    local char = LocalPlayer.Character
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    if hum and hum.WalkSpeed < 5 then hum.WalkSpeed = 16; hum.JumpPower = 50 end
                end
            end)
 -- [notif removed]
        else
            if bugTrapMain.conn then bugTrapMain.conn:Disconnect(); bugTrapMain.conn = nil end
 -- [notif removed]
        end
    end, false)
end


