                {Transparency = 0.7}):Play()
            task.wait(1.4)
            TweenService:Create(panelStroke, TweenInfo.new(1.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                {Transparency = 0.1}):Play()
            task.wait(1.4)
        end
    end)

    -- FIX: drag con UIDragDetector + fallback UserInputService (sin Draggable legacy)
    do
        local _dragging2, _dragStart2, _startPos2 = false, nil, nil
        if not pcall(function()
            local dd2 = Instance.new("UIDragDetector", panel)
            dd2.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
            dd2.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
            dd2.Dragged:Connect(function()
                local vp = workspace.CurrentCamera.ViewportSize
                panel.Position = UDim2.fromOffset(
                    math.clamp(panel.Position.X.Offset, 0, vp.X - panel.AbsoluteSize.X),
                    math.clamp(panel.Position.Y.Offset, 0, vp.Y - panel.AbsoluteSize.Y))
            end)
        end) then
            local UIS2 = game:GetService("UserInputService")
            panel.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _dragging2 = true; _dragStart2 = inp.Position; _startPos2 = panel.Position
                end
            end)
            panel.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then _dragging2 = false end
            end)
            UIS2.InputChanged:Connect(function(inp)
                if not _dragging2 then return end
                if inp.UserInputType ~= Enum.UserInputType.MouseMovement
                and inp.UserInputType ~= Enum.UserInputType.Touch then return end
                local delta = inp.Position - _dragStart2
                local vp = workspace.CurrentCamera.ViewportSize
                panel.Position = UDim2.fromOffset(
                    math.clamp(_startPos2.X.Offset + delta.X, 0, vp.X - panel.AbsoluteSize.X),
                    math.clamp(_startPos2.Y.Offset + delta.Y, 0, vp.Y - panel.AbsoluteSize.Y))
            end)
        end
    end

    header = Instance.new("Frame", panel)
    header.Size             = UDim2.new(1, 0, 0, 32)
    header.Position         = UDim2.new(0, 0, 0, 0)
    header.BackgroundColor3 = BOMB_COLOR
    header.BackgroundTransparency = 0.255
    header.BorderSizePixel  = 0
    header.ZIndex           = 121
    Instance.new("UICorner", header).CornerRadius = UDim.new(0, 16)

    headerLbl = Instance.new("TextLabel", header)
    headerLbl.Size               = UDim2.new(1, 0, 1, 0)
    headerLbl.BackgroundTransparency = 1
    headerLbl.Text               = " FAKE BOMB"
    headerLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    headerLbl.TextSize           = 13
    headerLbl.TextColor3         = Color3.fromRGB(255, 255, 255)
    headerLbl.ZIndex             = 122

    function MakeCircleBtn(parent, posX, color, icon, labelText, onClick)
        local posY = 38  -- debajo del header

        local btn = Instance.new("TextButton", parent)
        btn.Size                = UDim2.new(0, BTN_SIZE, 0, BTN_SIZE)
        btn.Position            = UDim2.new(0, posX, 0, posY)
        btn.BackgroundColor3    = color
        btn.BackgroundTransparency = 0.68
        btn.Text                = ""
        btn.AutoButtonColor     = false
        btn.BorderSizePixel     = 0
        btn.ZIndex              = 123
        Instance.new("UICorner", btn).CornerRadius = UDim.new(1, 0)  -- circular

        local btnStroke = Instance.new("UIStroke", btn)
        btnStroke.Color     = color
        btnStroke.Thickness = 2.5
        btnStroke.Transparency = 0.2

        local iconLbl = Instance.new("TextLabel", btn)
        iconLbl.Size               = UDim2.new(1, 0, 0, BTN_SIZE * 0.55)
        iconLbl.Position           = UDim2.new(0, 0, 0, 4)
        iconLbl.BackgroundTransparency = 1
        iconLbl.Text               = icon
        iconLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
        iconLbl.TextSize           = 22
        iconLbl.TextColor3         = Color3.fromRGB(255, 255, 255)
        iconLbl.ZIndex             = 124

        local subLbl = Instance.new("TextLabel", btn)
        subLbl.Size               = UDim2.new(1, -2, 0, 18)
        subLbl.Position           = UDim2.new(0, 1, 1, -20)
        subLbl.BackgroundTransparency = 1
        subLbl.Text               = labelText
        subLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
        subLbl.TextSize           = 9
        subLbl.TextColor3         = color
        subLbl.TextScaled         = false
        subLbl.ZIndex             = 124

        btn.MouseEnter:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.2),
                {BackgroundTransparency = 0.3, Size = UDim2.new(0, BTN_SIZE+6, 0, BTN_SIZE+6), Position = UDim2.new(0, posX-3, 0, posY-3)}):Play()
            TweenService:Create(btnStroke, TweenInfo.new(0.2), {Thickness = 3.5, Transparency = 0}):Play()
        end)
        btn.MouseLeave:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.2),
                {BackgroundTransparency = 0.25, Size = UDim2.new(0, BTN_SIZE, 0, BTN_SIZE), Position = UDim2.new(0, posX, 0, posY)}):Play()
            TweenService:Create(btnStroke, TweenInfo.new(0.2), {Thickness = 2.5, Transparency = 0.2}):Play()
        end)
        btn.Activated:Connect(function()

            TweenService:Create(btn, TweenInfo.new(0.08),
                {BackgroundTransparency = 0.1, BackgroundColor3 = Color3.fromRGB(255,255,255)}):Play()
            task.wait(0.12)
            TweenService:Create(btn, TweenInfo.new(0.2),
                {BackgroundTransparency = 0.25, BackgroundColor3 = color}):Play()
            if onClick then onClick() end
        end)

        return btn
    end

    gap    = 8
    startX = 8  -- padding left

    autoState = false
    autoConn  = nil
    b1 = MakeCircleBtn(panel, startX, BOMB_COLOR, "", "AUTO\nEQUIP", function()
        autoState = not autoState
        if autoConn then autoConn:Disconnect(); autoConn = nil end
        if autoState then
            -- task.spawn+wait: buscar murderer cada 0.3s en vez de 60fps
            autoConn = task.spawn(function()
                while autoState do
                    task.wait(0.3)
                    if not autoState then break end
                    local char = LocalPlayer.Character
                    if not char then continue end
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if not hrp then continue end
                    local murderer = findMurderer()
                    if not murderer or not murderer.Character then continue end
                    local mHRP = murderer.Character:FindFirstChild("HumanoidRootPart")
                    if not mHRP then continue end
                    if (hrp.Position - mHRP.Position).Magnitude <= 20 then
                        local fb = LocalPlayer.Backpack:FindFirstChild("FakeBomb") or char:FindFirstChild("FakeBomb")
                        if fb and fb:IsA("Tool") and not char:FindFirstChild("FakeBomb") then
                            local hum = char:FindFirstChildOfClass("Humanoid")
                            if hum then
                                hum:EquipTool(fb)
 CreateCustomNotification("BOMB AUTO EQUIP", "FakeBomb equipada automaticamente!", 2)
                            end
                        end
                    end
                end
            end)
 -- [notif removed]
        else
 -- [notif removed]
        end
        TweenService:Create(b1, TweenInfo.new(0.25),
            {BackgroundColor3 = autoState and BOMB_COLOR or Color3.fromRGB(60,60,60),
             BackgroundTransparency = autoState and 0.3 or 0.7}):Play()
    end)

    MakeCircleBtn(panel, startX + BTN_SIZE + gap, EQUIP_COLOR, "", "EQUIP", function()
        local char = LocalPlayer.Character
        if not char then return end
        fb = LocalPlayer.Backpack:FindFirstChild("FakeBomb") or char:FindFirstChild("FakeBomb")
        if fb and fb:IsA("Tool") then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(fb)
 CreateCustomNotification("AUTO EQUIP", "FakeBomb equipada!", 2)
            end
        else
 CreateCustomNotification("AUTO EQUIP", "No se encontro FakeBomb en el inventario", 3)
        end
    end)

    MakeCircleBtn(panel, startX + (BTN_SIZE + gap) * 2, LAUNCH_COLOR, "", "LAUNCH", function()
        local char = LocalPlayer.Character
        if not char then return end
        hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        fb = LocalPlayer.Backpack:FindFirstChild("FakeBomb") or char:FindFirstChild("FakeBomb")
        if not fb or not fb:IsA("Tool") then
 CreateCustomNotification("FAKE BOMB", "No se encontro FakeBomb en el inventario", 3)
            return
        end
        if not char:FindFirstChild("FakeBomb") then
            hum:EquipTool(fb)
            task.wait(0.12)
        end
        equipped = char:FindFirstChild("FakeBomb")
        if equipped and equipped:IsA("Tool") then
            pcall(function() equipped:Activate() end)
            pcall(function()
                local remote = equipped:FindFirstChildOfClass("RemoteEvent")
                    or equipped:FindFirstChild("Throw")
                    or equipped:FindFirstChild("Launch")
                if remote then remote:FireServer() end
            end)
 CreateCustomNotification("FAKE BOMB", "FakeBomb lanzada!", 2)
        else
 CreateCustomNotification("FAKE BOMB", "No se pudo equipar la FakeBomb", 3)
        end
    end)

    FakeBombBindlePanel.autoEquipConn = autoConn
end

function CreateMainUI_SwimFlyGithub()
    -- ==============================================================
    --  AUTO JUMP  VERSION MEJORADA CON MAS SLIDERS
    -- ==============================================================
    local sec = CreateSection(leftColumn, "", "AUTO JUMP", ThemeColors.Accent)

    if not _G._autoJumpState then
        _G._autoJumpState = {
            enabled       = false,
            jumpPower     = 50,
            jumpInterval  = 0.5,
            jumpHeight    = 7,
            walkSpeed     = 16,
            preDelay      = 0,
            gravity       = 196,
            repeatCount   = 1,   -- cuantas veces salta por ciclo
            conn          = nil,
            bindGui       = nil,
        }
    end
    local AJ = _G._autoJumpState

    -- Status bar
    local statusF = Instance.new("Frame", sec)
    statusF.Size = UDim2.new(1, -10, 0, 32)
    statusF.BackgroundColor3 = Color3.fromRGB(180, 55, 70)
    statusF.BackgroundTransparency = 0.75
    statusF.BorderSizePixel = 0
    Instance.new("UICorner", statusF).CornerRadius = UDim.new(0, 8)
    local ssStroke = Instance.new("UIStroke", statusF)
    ssStroke.Color = ThemeColors.Accent; ssStroke.Thickness = 1.5
    _sp(function()
        while ssStroke and ssStroke.Parent do
            TweenService:Create(ssStroke, TweenInfo.new(1.2, Enum.EasingStyle.Sine), {Transparency = 0.75}):Play()
            _w(1.2)
            TweenService:Create(ssStroke, TweenInfo.new(1.2, Enum.EasingStyle.Sine), {Transparency = 0}):Play()
            _w(1.2)
        end
    end)
    local statusL = Instance.new("TextLabel", statusF)
    statusL.Size = UDim2.new(1, -10, 1, 0)
    statusL.Position = UDim2.new(0, 8, 0, 0)
    statusL.BackgroundTransparency = 1
    statusL.Text = "Auto Jump: OFF"
    statusL.Font = Enum.Font.Montserrat; statusL.TextSize = 11
    statusL.TextColor3 = Color3.fromRGB(255, 200, 200)
    statusL.TextXAlignment = Enum.TextXAlignment.Left; statusL.ZIndex = 2

    local function stopAutoJump()
        AJ.enabled = false
        if AJ.conn then pcall(function() pcall(function() coroutine.close(AJ.conn) end) end); AJ.conn = nil end
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.JumpPower = 50; hum.UseJumpPower = true end
        statusL.Text = "Auto Jump: OFF"
        statusL.TextColor3 = Color3.fromRGB(255, 200, 200)
    end

    local function startAutoJump()
        AJ.enabled = true
        statusL.Text = "Auto Jump: ON  cada " .. string.format("%.1f", AJ.jumpInterval) .. "s"
        statusL.TextColor3 = Color3.fromRGB( 50, 255, 180)
        if AJ.conn then pcall(function() pcall(function() coroutine.close(AJ.conn) end) end); AJ.conn = nil end
        AJ.conn = _sp(function()
            while AJ.enabled do
                if AJ.preDelay > 0 then _w(AJ.preDelay) end
                if not AJ.enabled then break end
                local char = LocalPlayer.Character
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 then
                    hum.JumpPower = AJ.jumpPower
                    hum.UseJumpPower = true
                    for _ = 1, math.max(1, AJ.repeatCount) do
                        hum:ChangeState(Enum.HumanoidStateType.Jumping)
                        _w(0.05)
                    end
                end
                _w(AJ.jumpInterval)
            end
        end)
    end

    -- Toggle principal
    CreateAuroraToggle(sec, "Auto Jump", function(enabled)
        if enabled then
            startAutoJump()
            -- [notif removed]
        else
            stopAutoJump()
            -- [notif removed]
        end
    end, false)

    -- Keybind Auto Jump
    do
        local _ajKeybind = Enum.KeyCode.J
        local _ajListening = false

        local _ajKeyRow = Instance.new("Frame", sec)
        _ajKeyRow.Size = UDim2.new(1, -4, 0, 36)
        _ajKeyRow.BackgroundColor3 = Color3.fromRGB(90, 15, 25)
        _ajKeyRow.BackgroundTransparency = 0.75
        _ajKeyRow.BorderSizePixel = 0
        Instance.new("UICorner", _ajKeyRow).CornerRadius = UDim.new(0, 8)
        local _ajKeyStroke = Instance.new("UIStroke", _ajKeyRow)
        _ajKeyStroke.Color = ThemeColors.Accent; _ajKeyStroke.Thickness = 1.2

        local _ajKeyLbl = Instance.new("TextLabel", _ajKeyRow)
        _ajKeyLbl.Size = UDim2.new(0.6, 0, 1, 0); _ajKeyLbl.Position = UDim2.new(0, 8, 0, 0)
        _ajKeyLbl.BackgroundTransparency = 1; _ajKeyLbl.Text = "Keybind Auto Jump"
        _ajKeyLbl.TextColor3 = ThemeColors.TextPrimary; _ajKeyLbl.TextSize = 12
        _ajKeyLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        _ajKeyLbl.TextXAlignment = Enum.TextXAlignment.Left; _ajKeyLbl.ZIndex = 2

        local _ajKeyBtn = Instance.new("TextButton", _ajKeyRow)
        _ajKeyBtn.Size = UDim2.new(0, 70, 0, 22); _ajKeyBtn.AnchorPoint = Vector2.new(1, 0.5)
        _ajKeyBtn.Position = UDim2.new(1, -6, 0.5, 0)
        _ajKeyBtn.BackgroundColor3 = ThemeColors.Accent; _ajKeyBtn.BackgroundTransparency = 0.35
        _ajKeyBtn.Text = "[ J ]"; _ajKeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
        _ajKeyBtn.TextSize = 11; _ajKeyBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        _ajKeyBtn.BorderSizePixel = 0; _ajKeyBtn.ZIndex = 3
        Instance.new("UICorner", _ajKeyBtn).CornerRadius = UDim.new(0, 6)

        _ajKeyBtn.Activated:Connect(function()
            if _ajListening then return end
            _ajListening = true; _ajKeyBtn.Text = "[ ... ]"
            local conn; conn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp then return end
                if inp.UserInputType == Enum.UserInputType.Keyboard then
                    _ajKeybind = inp.KeyCode
                    _ajKeyBtn.Text = "[ " .. tostring(inp.KeyCode):gsub("Enum.KeyCode.", "") .. " ]"
                    _ajListening = false; conn:Disconnect()
                end
            end)
        end)

        UserInputService.InputBegan:Connect(function(inp, gp)
            if gp or _ajListening then return end
            if inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == _ajKeybind then
                if AJ.enabled then stopAutoJump()
                else startAutoJump() end
            end
        end)
    end

    -- Bindable flotante
    do
        local ajBindGui = nil
        CreateAuroraToggle(sec, "Bindable Auto Jump", function(enabled)
            if ajBindGui then pcall(function() ajBindGui:Destroy() end); ajBindGui = nil end
            AJ.bindGui = nil
            if not enabled then return end
            local sg = Instance.new("ScreenGui")
            sg.Name = "AutoJumpBind"; sg.ResetOnSpawn = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true; sg.DisplayOrder = 9950
            pcall(function() sg.Parent = CoreGui end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            ajBindGui = sg; AJ.bindGui = sg

            local BTN = 70
            local frame = Instance.new("Frame", sg)
            frame.Name = "AJBindFrame"; frame.Size = UDim2.new(0, BTN, 0, BTN)
            frame.Position = UDim2.new(0, 80, 0.5, -35)
            frame.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
            frame.BackgroundTransparency = 0.75; frame.BorderSizePixel = 0
            frame.Active = true; frame.ZIndex = 200
            -- FIX: Draggable legacy removido; UIDragDetector + fallback UIS se agrega abajo
            Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 14)
            local fStroke = Instance.new("UIStroke", frame)
            fStroke.Color = ThemeColors.Accent; fStroke.Thickness = 2.5; fStroke.Transparency = 0.1
            _sp(function()
                while fStroke and fStroke.Parent do
                    TweenService:Create(fStroke, TweenInfo.new(1, Enum.EasingStyle.Sine), {Transparency = 0.7}):Play()
                    _w(1)
                    TweenService:Create(fStroke, TweenInfo.new(1, Enum.EasingStyle.Sine), {Transparency = 0}):Play()
                    _w(1)
                end
            end)
            -- FIX: drag con UIDragDetector + fallback UserInputService (sin Draggable legacy)
            do
                local _dragAJ, _startAJ, _posAJ = false, nil, nil
                if not pcall(function()
                    local ddAJ = Instance.new("UIDragDetector", frame)
                    ddAJ.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                    ddAJ.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                    ddAJ.Dragged:Connect(function()
                        local vp = workspace.CurrentCamera.ViewportSize
                        frame.Position = UDim2.fromOffset(
                            math.clamp(frame.Position.X.Offset, 0, vp.X - frame.AbsoluteSize.X),
                            math.clamp(frame.Position.Y.Offset, 0, vp.Y - frame.AbsoluteSize.Y))
                    end)
                end) then
                    local UIS3 = game:GetService("UserInputService")
                    frame.InputBegan:Connect(function(inp)
                        if inp.UserInputType == Enum.UserInputType.MouseButton1
                        or inp.UserInputType == Enum.UserInputType.Touch then
                            _dragAJ = true; _startAJ = inp.Position; _posAJ = frame.Position
                        end
                    end)
                    frame.InputEnded:Connect(function(inp)
                        if inp.UserInputType == Enum.UserInputType.MouseButton1
                        or inp.UserInputType == Enum.UserInputType.Touch then _dragAJ = false end
                    end)
                    UIS3.InputChanged:Connect(function(inp)
                        if not _dragAJ then return end
                        if inp.UserInputType ~= Enum.UserInputType.MouseMovement
                        and inp.UserInputType ~= Enum.UserInputType.Touch then return end
                        local delta = inp.Position - _startAJ
                        local vp = workspace.CurrentCamera.ViewportSize
                        frame.Position = UDim2.fromOffset(
                            math.clamp(_posAJ.X.Offset + delta.X, 0, vp.X - frame.AbsoluteSize.X),
                            math.clamp(_posAJ.Y.Offset + delta.Y, 0, vp.Y - frame.AbsoluteSize.Y))
                    end)
                end
            end
            local icon = Instance.new("TextLabel", frame)
            icon.Size = UDim2.new(1, 0, 0.55, 0); icon.Position = UDim2.new(0, 0, 0, 6)
            icon.BackgroundTransparency = 1; icon.Text = "^"
            icon.TextSize = 26; icon.Font = Enum.Font.Montserrat
            icon.TextColor3 = ThemeColors.Accent; icon.ZIndex = 201
            local lbl = Instance.new("TextLabel", frame)
            lbl.Size = UDim2.new(1, 0, 0, 18); lbl.Position = UDim2.new(0, 0, 1, -22)
            lbl.BackgroundTransparency = 1; lbl.Text = "AUTO\nJUMP"
            lbl.TextSize = 9; lbl.Font = Enum.Font.Montserrat
            lbl.TextColor3 = Color3.fromRGB(210, 240, 255); lbl.TextWrapped = true; lbl.ZIndex = 201
            local dot = Instance.new("Frame", frame)
            dot.Size = UDim2.new(0, 8, 0, 8); dot.Position = UDim2.new(1, -12, 0, 4)
            dot.BackgroundColor3 = Color3.fromRGB(180, 180, 185); dot.BorderSizePixel = 0; dot.ZIndex = 202
            Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
            local function updateDot()
                dot.BackgroundColor3 = AJ.enabled and Color3.fromRGB( 50, 255, 180) or Color3.fromRGB(200, 60, 60)
            end
            updateDot()
            frame.InputBegan:Connect(function(inp)
                if inp.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                TweenService:Create(frame, TweenInfo.new(0.08), {BackgroundColor3 = Color3.fromRGB(55, 55, 130)}):Play()
                _w(0.1)
                TweenService:Create(frame, TweenInfo.new(0.18), {BackgroundColor3 = Color3.fromRGB(20, 35, 80), BackgroundTransparency = 0.75}):Play()
                if AJ.enabled then stopAutoJump()
                else startAutoJump() end
                updateDot()
            end)
            _sp(function()
                while dot and dot.Parent do _w(0.2); if dot.Parent then updateDot() end end
            end)
        end, false)
    end

    -- Sliders mejorados
    CreateSlider(sec, "Jump Power", 10, 500, AJ.jumpPower, function(v)
        AJ.jumpPower = v
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.JumpPower = v; hum.UseJumpPower = true end
    end)
    CreateSlider(sec, "Intervalo entre saltos (x0.1s)", 1, 50, math.floor(AJ.jumpInterval * 10), function(v)
        AJ.jumpInterval = v / 10
        if AJ.enabled then statusL.Text = "Auto Jump: ON  cada " .. string.format("%.1f", AJ.jumpInterval) .. "s" end
    end)
    CreateSlider(sec, "Saltos por ciclo", 1, 5, AJ.repeatCount, function(v)
        AJ.repeatCount = math.floor(v)
    end)
    CreateSlider(sec, "JumpHeight extra", 0, 200, AJ.jumpHeight, function(v)
        AJ.jumpHeight = v
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.UseJumpPower = false; hum.JumpHeight = v end
    end)
    CreateSlider(sec, "WalkSpeed al saltar", 8, 300, 16, function(v)
        AJ.walkSpeed = v
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.WalkSpeed = v end
    end)
    CreateSlider(sec, "Pre-Delay antes de saltar (ms)", 0, 100, 0, function(v)
        AJ.preDelay = v / 1000
    end)
    CreateSlider(sec, "Gravedad", 20, 300, 196, function(v)
        AJ.gravity = v
        workspace.Gravity = v
    end)

    -- ==============================================================
    --  JUMP BOOSTER  salto potenciado con keybind y sliders
    -- ==============================================================
    local jbSec = CreateSection(rightColumn, "", "JUMP BOOSTER", ThemeColors.Aurora1)

    local JB = {
        enabled        = false,
        power          = 120,   -- fuerza del salto
        upForce        = 80,    -- impulso adicional en Y
        duration       = 0.18,  -- duracion del impulso
        cooldown       = 0.5,   -- tiempo entre activaciones
        launchAngle    = 0,     -- angulo de lanzamiento (0 = vertical puro)
        horizontalMult = 1,     -- multiplicador horizontal
        lastUsed       = 0,
        keybind        = Enum.KeyCode.E,
        listening      = false,
        conn           = nil,
    }

    -- Status bar JB
    local jbStatusF = Instance.new("Frame", jbSec)
    jbStatusF.Size = UDim2.new(1, -10, 0, 32)
    jbStatusF.BackgroundColor3 = Color3.fromRGB(10, 22, 10)
    jbStatusF.BackgroundTransparency = 0.75
    jbStatusF.BorderSizePixel = 0
    Instance.new("UICorner", jbStatusF).CornerRadius = UDim.new(0, 8)
    local jbStroke = Instance.new("UIStroke", jbStatusF)
    jbStroke.Color = ThemeColors.Aurora1; jbStroke.Thickness = 1.5
    _sp(function()
        while jbStroke and jbStroke.Parent do
            TweenService:Create(jbStroke, TweenInfo.new(1, Enum.EasingStyle.Sine), {Transparency = 0.8}):Play()
            _w(1)
            TweenService:Create(jbStroke, TweenInfo.new(1, Enum.EasingStyle.Sine), {Transparency = 0}):Play()
            _w(1)
        end
    end)
    local jbStatusL = Instance.new("TextLabel", jbStatusF)
    jbStatusL.Size = UDim2.new(1, -10, 1, 0); jbStatusL.Position = UDim2.new(0, 8, 0, 0)
    jbStatusL.BackgroundTransparency = 1; jbStatusL.Text = "Jump Booster: OFF"
    jbStatusL.Font = Enum.Font.Montserrat; jbStatusL.TextSize = 11
    jbStatusL.TextColor3 = Color3.fromRGB(255, 200, 200)
    jbStatusL.TextXAlignment = Enum.TextXAlignment.Left; jbStatusL.ZIndex = 2

    -- Funcion de disparo del booster
    local function fireJumpBooster()
        local now = tick()
        if now - JB.lastUsed < JB.cooldown then
            local remaining = string.format("%.1f", JB.cooldown - (now - JB.lastUsed))
            CreateCustomNotification("JUMP BOOSTER", "Cooldown: " .. remaining .. "s", 1)
            return
        end
        JB.lastUsed = now
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not hrp or not hum or hum.Health <= 0 then return end

        -- Guardar JumpPower original
        local origJP = hum.JumpPower
        hum.JumpPower = JB.power
        hum.UseJumpPower = true
        hum:ChangeState(Enum.HumanoidStateType.Jumping)

        -- Impulso adicional con BodyVelocity
        local bv = Instance.new("BodyVelocity")
        bv.Name = "JumpBoosterBV"
        bv.MaxForce = Vector3.new(
            1e5 * JB.horizontalMult,
            1e5,
            1e5 * JB.horizontalMult
        )
        -- Calcular direccion: mezcla de camara + angulo
        local cam = _Camera
        local lookFlat = Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
        if lookFlat.Magnitude > 0 then lookFlat = lookFlat.Unit end
        local angleFactor = math.sin(math.rad(JB.launchAngle))
        bv.Velocity = Vector3.new(
            lookFlat.X * JB.upForce * angleFactor * JB.horizontalMult,
            JB.upForce,
            lookFlat.Z * JB.upForce * angleFactor * JB.horizontalMult
        )
        bv.Parent = hrp

        -- Efecto visual: particles si hay attachment
        pcall(function()
            local att = hrp:FindFirstChildOfClass("Attachment") or Instance.new("Attachment", hrp)
            local burst = Instance.new("ParticleEmitter", att)
            burst.Lifetime = NumberRange.new(0.2, 0.5)
            burst.Speed = NumberRange.new(10, 20)
            burst.Color = ColorSequence.new(Color3.fromRGB( 50, 255, 180))
            burst.Size = NumberSequence.new(0.3, 0)
            burst.Rate = 0; burst.Enabled = false
            burst:Emit(18)
            _dl(0.6, function() pcall(function() burst:Destroy() end) end)
        end)

        _dl(JB.duration, function()
            if bv and bv.Parent then bv:Destroy() end
            if hum and hum.Parent then hum.JumpPower = origJP end
        end)

        CreateCustomNotification("JUMP BOOSTER", "BOOST! Potencia: " .. JB.power, 1.5)
    end

    -- Toggle principal
    CreateAuroraToggle(jbSec, "Jump Booster (activa el sistema)", function(on)
        JB.enabled = on
        if JB.conn then pcall(function() JB.conn:Disconnect() end); JB.conn = nil end
        if on then
            -- Escuchar el keybind para disparar
            JB.conn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp or not JB.enabled or JB.listening then return end
                if inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == JB.keybind then
                    fireJumpBooster()
                end
            end)
            jbStatusL.Text = "Jump Booster: ON  tecla [" .. tostring(JB.keybind):gsub("Enum.KeyCode.", "") .. "]"
            jbStatusL.TextColor3 = Color3.fromRGB( 50, 255, 180)
            -- [notif removed]
        else
            jbStatusL.Text = "Jump Booster: OFF"
            jbStatusL.TextColor3 = Color3.fromRGB(255, 200, 200)
            -- [notif removed]
        end
    end, false)

    -- Keybind selector Jump Booster
    do
        local _jbKeyRow = Instance.new("Frame", jbSec)
        _jbKeyRow.Size = UDim2.new(1, -4, 0, 36)
        _jbKeyRow.BackgroundColor3 = Color3.fromRGB(90, 15, 25)
        _jbKeyRow.BackgroundTransparency = 0.75
        _jbKeyRow.BorderSizePixel = 0
        Instance.new("UICorner", _jbKeyRow).CornerRadius = UDim.new(0, 8)
        local _jbKeyStroke = Instance.new("UIStroke", _jbKeyRow)
        _jbKeyStroke.Color = ThemeColors.Aurora1; _jbKeyStroke.Thickness = 1.2

        local _jbKeyLbl = Instance.new("TextLabel", _jbKeyRow)
        _jbKeyLbl.Size = UDim2.new(0.6, 0, 1, 0); _jbKeyLbl.Position = UDim2.new(0, 8, 0, 0)
        _jbKeyLbl.BackgroundTransparency = 1; _jbKeyLbl.Text = "Keybind Booster"
        _jbKeyLbl.TextColor3 = ThemeColors.TextPrimary; _jbKeyLbl.TextSize = 12
        _jbKeyLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        _jbKeyLbl.TextXAlignment = Enum.TextXAlignment.Left; _jbKeyLbl.ZIndex = 2

        local _jbKeyBtn = Instance.new("TextButton", _jbKeyRow)
        _jbKeyBtn.Size = UDim2.new(0, 70, 0, 22); _jbKeyBtn.AnchorPoint = Vector2.new(1, 0.5)
        _jbKeyBtn.Position = UDim2.new(1, -6, 0.5, 0)
        _jbKeyBtn.BackgroundColor3 = ThemeColors.Aurora1; _jbKeyBtn.BackgroundTransparency = 0.35
        _jbKeyBtn.Text = "[ E ]"; _jbKeyBtn.TextColor3 = Color3.fromRGB(255,255,255)
        _jbKeyBtn.TextSize = 11; _jbKeyBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        _jbKeyBtn.BorderSizePixel = 0; _jbKeyBtn.ZIndex = 3
        Instance.new("UICorner", _jbKeyBtn).CornerRadius = UDim.new(0, 6)

        _jbKeyBtn.Activated:Connect(function()
            if JB.listening then return end
            JB.listening = true; _jbKeyBtn.Text = "[ ... ]"; _jbKeyBtn.BackgroundTransparency = 0.1
            local conn; conn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp then return end
                if inp.UserInputType == Enum.UserInputType.Keyboard then
                    JB.keybind = inp.KeyCode
                    local keyName = tostring(inp.KeyCode):gsub("Enum.KeyCode.", "")
                    _jbKeyBtn.Text = "[ " .. keyName .. " ]"
                    _jbKeyBtn.BackgroundTransparency = 0.35
                    JB.listening = false; conn:Disconnect()
                    jbStatusL.Text = "Jump Booster: " .. (JB.enabled and "ON" or "OFF") .. "  tecla [" .. keyName .. "]"
                    if not UserInputService.TouchEnabled then CreateCustomNotification("JUMP BOOSTER", "Tecla cambiada a [" .. keyName .. "]", 2) end
                end
            end)
        end)
    end

    -- Bindable flotante Jump Booster
    local _jbBindGui = nil
    CreateAuroraToggle(jbSec, "Bindable Boton Booster", function(on)
        if _jbBindGui then pcall(function() _jbBindGui:Destroy() end); _jbBindGui = nil end
        if not on then DestroyCapyBind("BOOST"); return end
        local sg = Instance.new("ScreenGui")
        sg.Name = "JBBoostBind"; sg.ResetOnSpawn = false
        sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
        pcall(function() sg.Parent = CoreGui end)
        if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
        _jbBindGui = sg
        MakeCapyBindableFrame(sg, "BOOST", function()
            fireJumpBooster()
        end, 20, 280)
        CreateCustomNotification("JUMP BOOSTER", "Bindable activo  presiona BOOST para saltar", 2)
    end, false)

    -- Sliders Jump Booster
    CreateSlider(jbSec, "Potencia de salto", 50, 1000, JB.power, function(v) JB.power = v end)
    CreateSlider(jbSec, "Impulso vertical (BodyVelocity)", 10, 500, JB.upForce, function(v) JB.upForce = v end)
    CreateSlider(jbSec, "Duracion del impulso (x0.01s)", 5, 100, math.floor(JB.duration * 100), function(v)
        JB.duration = v / 100
    end)
    CreateSlider(jbSec, "Cooldown entre boosts (x0.1s)", 1, 50, math.floor(JB.cooldown * 10), function(v)
        JB.cooldown = v / 10
    end)
    CreateSlider(jbSec, "Angulo de lanzamiento (grados)", 0, 80, JB.launchAngle, function(v)
        JB.launchAngle = v
    end)
    CreateSlider(jbSec, "Multiplicador horizontal", 1, 10, JB.horizontalMult, function(v)
        JB.horizontalMult = v
    end)

    -- ==============================================================
    --  INFORMATION MURDER / SHERIFF  mensaje flotante de roles
    -- ==============================================================
    local infoRolSec = CreateSection(rightColumn, "", "INFORMATION ROLES", ThemeColors.Primary)

    -- Estado global del sistema de info de roles
    local IR = {
        murderNotif  = false,
        sheriffNotif = false,
        autoLoop     = false,
        loopConn     = nil,
        loopInterval = 5,
        showHP       = true,
        showDist     = true,
    }

    local function _getRoleInfo(role)
        local player = (role == "murder") and (findMurderer and findMurderer()) or (findSheriffPlayer and findSheriffPlayer())
        if not player then return nil end
        local char = player.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        local hp   = hum and math.floor(hum.Health) or 0
        local maxHp = hum and math.floor(hum.MaxHealth) or 100
        local dist = 0
        pcall(function()
            local myChar = LocalPlayer.Character
            local myHrp  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local thHrp  = char and char:FindFirstChild("HumanoidRootPart")
            if myHrp and thHrp then
                dist = math.floor((myHrp.Position - thHrp.Position).Magnitude)
            end
        end)
        return { name = player.Name, hp = hp, maxHp = maxHp, dist = dist }
    end

    local function notifyMurder()
        local info = _getRoleInfo("murder")
        if not info then
            CreateCustomNotification("MURDER", "No detectado aun", 2)
            return
        end
        local msg = info.name
        if IR.showHP then msg = msg .. " | HP: " .. info.hp .. "/" .. info.maxHp end
        if IR.showDist then msg = msg .. " | Dist: " .. info.dist .. " studs" end
        CreateCustomNotification("MURDER DETECTADO", msg, 4)
    end

    local function notifySheriff()
        local info = _getRoleInfo("sheriff")
        if not info then
            CreateCustomNotification("SHERIFF", "No detectado aun", 2)
            return
        end
        local msg = info.name
        if IR.showHP then msg = msg .. " | HP: " .. info.hp .. "/" .. info.maxHp end
        if IR.showDist then msg = msg .. " | Dist: " .. info.dist .. " studs" end
        CreateCustomNotification("SHERIFF DETECTADO", msg, 4)
    end

    -- Boton: mostrar Murder ahora
    CreateButton(rightColumn, "Show who is the Murder", ThemeColors.Primary, function()
        notifyMurder()
    end)

    -- Boton: mostrar Sheriff ahora
    CreateButton(rightColumn, "Show who is the Sheriff", ThemeColors.Aurora2, function()
        notifySheriff()
    end)

    -- Boton: mostrar ambos
    CreateButton(rightColumn, "Show Murder and Sheriff", ThemeColors.Accent, function()
        notifyMurder()
        _w(0.3)
        notifySheriff()
    end)
end


