function CreateMainUI_Universal()
    -- =============================================
    -- FLOAT / LAY  (Universal) -- Swim Fly removido del main tab
    -- =============================================
    do
 CreateSection(leftColumn, "", "UNIVERSAL", ThemeColors.Primary)
        local S = MainSystem.state

        -- -- FLOAT ---------------------------------
        local _floatEnabled    = false
        local _floatBindGui    = game:GetService("CoreGui"):FindFirstChild("FloatBind_HUB")
        local _floatBindEnabled = false
        local _floatConn       = nil
        local _floatOffset     = 310  -- % offset

        local function _stopFloat()
            _floatEnabled = false
            if _floatConn then _floatConn:Disconnect(); _floatConn = nil end
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            -- Limpiar BodyPosition y BodyVelocity
            if hrp then
                local bp = hrp:FindFirstChild("FloatBP")
                if bp then bp:Destroy() end
                local bv = hrp:FindFirstChild("FloatBV")
                if bv then bv:Destroy() end
            end
            if hum then
                hum.PlatformStand = false
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end

        local function _startFloat()
            _stopFloat()
            _floatEnabled = true
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then return end

            -- Altura objetivo = posicion actual + offset
            local targetY = hrp.Position.Y + math.max(0.5, _floatOffset / 100)

            -- FIX FLOAT WALK: usar BodyVelocity SOLO en Y para no bloquear movimiento WASD
            -- BodyPosition bloqueaba el movimiento horizontal. BodyVelocity en Y = flota + camina.
            local bv = Instance.new("BodyVelocity")
            bv.Name     = "FloatBV"
            bv.MaxForce = Vector3.new(0, 1e5, 0)   -- fuerza solo en Y, X/Z libres para WASD
            bv.Velocity = Vector3.zero
            bv.Parent   = hrp

            -- BodyPosition para mantener la altura fija
            local bp = Instance.new("BodyPosition")
            bp.Name      = "FloatBP"
            bp.MaxForce  = Vector3.new(0, 4e4, 0)  -- fuerza Y moderada (no aplasta el salto)
            bp.D         = 300
            bp.P         = 6000
            bp.Position  = Vector3.new(hrp.Position.X, targetY, hrp.Position.Z)
            bp.Parent    = hrp

            -- FIX: NO setear PlatformStand -- eso bloqueaba el movimiento
            -- El jugador puede caminar con WASD normalmente mientras flota
            local savedJump = hum.JumpPower
            hum.JumpPower = 50  -- mantener salto habilitado

            local _floatTick = 0
            _floatConn = RunService.Heartbeat:Connect(function()
                _floatTick = _floatTick + 1
                if _floatTick < 3 then return end  -- ~20fps es suficiente para float
                _floatTick = 0
                if not _floatEnabled then return end
                local c = LocalPlayer.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                local h = c and c:FindFirstChildOfClass("Humanoid")
                if not r or not h then return end
                -- Actualizar Y segun posicion horizontal actual (permite caminar libremente)
                local bpInst = r:FindFirstChild("FloatBP")
                if bpInst then
                    -- Solo actualizar Y: X y Z los controla el Humanoid normal
                    bpInst.Position = Vector3.new(r.Position.X, targetY, r.Position.Z)
                end
                -- FIX: nunca bloquear el movimiento con PlatformStand
                if h.PlatformStand then h.PlatformStand = false end
            end)
        end

        local function _destroyFloatBind()
            local function sweep(p)
                if not p then return end
                for _, g in ipairs(p:GetChildren()) do
                    if g.Name == "FloatBind_HUB" then pcall(function() g:Destroy() end) end
                end
            end
            sweep(game:GetService("CoreGui"))
            pcall(function() sweep(LocalPlayer:FindFirstChild("PlayerGui")) end)
            _floatBindGui = nil
            DestroyCapyBind("FLOAT")
        end

        local function _createFloatBind()
            _destroyFloatBind()
            local sg = Instance.new("ScreenGui")
            sg.Name = "FloatBind_HUB"; sg.ResetOnSpawn = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
            pcall(function() sg.Parent = game:GetService("CoreGui") end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _floatBindGui = sg
            MakeCapyBindableFrame(sg, "FLOAT", function()
                _floatEnabled = not _floatEnabled
                if _floatEnabled then _startFloat() else _stopFloat() end
 -- [notif removed]
            end, 120, 160)
        end

 CreateToggle(leftColumn, "Float", function(on)
            if on then _startFloat() else _stopFloat() end
        end, false)

 CreateToggle(leftColumn, "Show Button", function(on)
            _floatBindEnabled = on
            if on then _createFloatBind() else _destroyFloatBind() end
        end, _floatBindGui ~= nil)

 CreateSlider(leftColumn, "Float Offset (%)", 0, 600, _floatOffset, function(v)
            _floatOffset = v
        end)

        -- -- LAY -----------------------------------
        _layEnabled    = false
        _layBindGui    = game:GetService("CoreGui"):FindFirstChild("LayBind_HUB")
        _layBindEnabled = false
        _laySavedSpeed = 16
        _layConn       = nil

        local function _stopLay()
            _layEnabled = false
            if _layConn then _layConn:Disconnect(); _layConn = nil end
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if hum then
                hum.PlatformStand = false
                hum.WalkSpeed     = _laySavedSpeed
                hum.AutoRotate    = true
            end
        end

        local function _startLay()
            _stopLay()
            _layEnabled = true
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
            _laySavedSpeed    = hum.WalkSpeed
            -- PlatformStand hace que el personaje se caiga al suelo
            hum.PlatformStand = true
            hum.AutoRotate    = false

            local UIS = game:GetService("UserInputService")
            local _jumpConn = nil

            -- Detectar cuando el jugador presiona Space para levantarse
            _jumpConn = UIS.InputBegan:Connect(function(inp, gpe)
                if gpe then return end
                if inp.KeyCode == Enum.KeyCode.Space or inp.KeyCode == Enum.KeyCode.ButtonA then
                    if _layEnabled then
                        _layEnabled = false
                        _jumpConn:Disconnect()
                        if _layConn then _layConn:Disconnect(); _layConn = nil end
                        local c = LocalPlayer.Character
                        local h = c and c:FindFirstChildOfClass("Humanoid")
                        if h then
                            h.PlatformStand = false
                            h.WalkSpeed     = _laySavedSpeed
                            h.AutoRotate    = true
                            h:ChangeState(Enum.HumanoidStateType.Jumping)
                        end
                        -- Actualizar UI toggle si existe
 -- [notif removed]
                    end
                end
            end)

            local _layTick = 0
            _layConn = RunService.Heartbeat:Connect(function()
                _layTick = _layTick + 1
                if _layTick < 3 then return end  -- OPT: ~20fps suficiente para mantener PlatformStand
                _layTick = 0
                if not _layEnabled then return end
                c = LocalPlayer.Character
                h = c and c:FindFirstChildOfClass("Humanoid")
                if not h then return end
                -- Mantener PlatformStand activo (el servidor puede resetearlo)
                if not h.PlatformStand then h.PlatformStand = true end
                -- No permitir movimiento horizontal
                h.WalkSpeed = 0
            end)
        end

        local function _destroyLayBind()
            local function sweep(p)
                if not p then return end
                for _, g in ipairs(p:GetChildren()) do
                    if g.Name == "LayBind_HUB" then pcall(function() g:Destroy() end) end
                end
            end
            sweep(game:GetService("CoreGui"))
            pcall(function() sweep(LocalPlayer:FindFirstChild("PlayerGui")) end)
            _layBindGui = nil
            DestroyCapyBind("LAY")
        end

        local function _createLayBind()
            _destroyLayBind()
            local sg = Instance.new("ScreenGui")
            sg.Name = "LayBind_HUB"; sg.ResetOnSpawn = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
            pcall(function() sg.Parent = game:GetService("CoreGui") end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _layBindGui = sg
            MakeCapyBindableFrame(sg, "LAY", function()
                _layEnabled = not _layEnabled
                if _layEnabled then _startLay() else _stopLay() end
 -- [notif removed]
            end, 220, 160)
        end

 CreateToggle(leftColumn, "Lay", function(on)
            if on then _startLay() else _stopLay() end
        end, false)

 CreateToggle(leftColumn, "Show Button", function(on)
            _layBindEnabled = on
            if on then _createLayBind() else _destroyLayBind() end
        end, _layBindGui ~= nil)
    end

    -- =============================================
    -- TRAP IMMUNE
    -- Hooks TrapHitLocal to instantly restore WalkSpeed and JumpPower
    -- ================================================================
    do
 CreateSection(leftColumn, "", "TRAP IMMUNE", ThemeColors.Aurora2)

        local _trapImmuneEnabled = false
        local _trapImmuneConn    = nil

        local function _connectTrapImmune()
            -- Hook TrapHitLocal: when the server fires it, we immediately restore stats
            local TrapSystem = game:GetService("ReplicatedStorage"):FindFirstChild("TrapSystem")
            if not TrapSystem then
 CreateCustomNotification("TRAP IMMUNE", "TrapSystem not found in ReplicatedStorage", 3)
                return false
            end
            local TrapHitLocal = TrapSystem:FindFirstChild("TrapHitLocal")
            if not TrapHitLocal then
 CreateCustomNotification("TRAP IMMUNE", "TrapHitLocal event not found", 3)
                return false
            end
            -- Connect BEFORE the game's own script so we restore stats first
            _trapImmuneConn = TrapHitLocal.OnClientEvent:Connect(function(trap, player)
                if not _trapImmuneEnabled then return end
                if player ~= LocalPlayer then return end
                local char = LocalPlayer.Character
                if not char then return end
                local hum = char:FindFirstChildOfClass("Humanoid")
                if not hum then return end
                -- Restore immediately and keep restoring for the trap duration (4s)
                -- The game script sets WalkSpeed=0.01 and JumpPower=1 then waits 4s
                local function _restore()
                    if not _trapImmuneEnabled then return end
                    if hum and hum.Parent then
                        hum.WalkSpeed = 16
                        hum.JumpPower = 50
                    end
                end
                -- Restore every 0.05s during the 4s trap window (80 iters = 4s exactos)
                task.spawn(function()
                    for _ = 1, 80 do  -- OPT: 100->80, cubre exactamente los 4s de trampa
                        if not _trapImmuneEnabled then break end
                        task.wait(0.016)
                        _restore()
                    end
                end)
            end)
            return true
        end

 CreateToggle(leftColumn, "Trap Immune", function(on)
            _trapImmuneEnabled = on
            if _trapImmuneConn then
                pcall(function() _trapImmuneConn:Disconnect() end)
                _trapImmuneConn = nil
            end
            if on then
                local ok = _connectTrapImmune()
                if ok then
 -- [notif removed]
                end
            else
 -- [notif removed]
            end
        end, false)
    
end -- closes do block
end -- closes CreateMainUI_Universal

function CreateMainUI_Other()
    local S = MainSystem.state

    -- [REMOVE BLACK SCREEN eliminado por usuario]


    -- =============================================
    -- AUTO ESQUIVAR AL MURDER (esquivar con TP instantaneo)
    -- =============================================
    do
 CreateSection(rightColumn, "", "AUTO ESQUIVAR AL MURDER", Color3.fromRGB(57, 57, 57))

        local _esquivarEnabled = false
        local _esquivarDist    = 4     -- distancia de activacion
        local _esquivarFar     = 20    -- distancia de escape
        local _lastEsquivar    = 0
        local _esquivarConn    = nil

        local function _doEsquivar()
            local now = tick()
            if now - _lastEsquivar < 0.8 then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then return end
            local murderer = findMurderer()
            if not murderer or not murderer.Character then return end
            local mHRP = murderer.Character:FindFirstChild("HumanoidRootPart")
            if not mHRP then return end
            local dist = (hrp.Position - mHRP.Position).Magnitude
            if dist <= _esquivarDist then
                _lastEsquivar = now
                -- Calcular direccion de escape
                local awayDir = (hrp.Position - mHRP.Position)
                if awayDir.Magnitude < 0.1 then
                    awayDir = Vector3.new(math.random(-1,1), 0, math.random(-1,1))
                end
                awayDir = awayDir.Unit
                -- Intentar varias direcciones para encontrar lugar seguro
                local escapePos = hrp.Position + awayDir * _esquivarFar
                local ray = workspace:Raycast(escapePos + Vector3.new(0,20,0), Vector3.new(0,-40,0))
                if ray then escapePos = ray.Position + Vector3.new(0,3,0) end
                pcall(function() hrp.CFrame = CFrame.new(escapePos) end)
 CreateCustomNotification(" ESQUIVAR", "Esquivaste al Murder! (" .. math.floor(dist) .. " studs)", 2)
            end
        end

        local function _startEsquivarLoop()
            if _esquivarConn then pcall(function() task.cancel(_esquivarConn) end) end
            _esquivarConn = task.spawn(function()
                while _esquivarEnabled do
                    task.wait(0.1)  -- OPT: 0.05->0.1, 10fps suficiente para deteccion de distancia
                    if _esquivarEnabled then _doEsquivar() end
                end
            end)
        end

 CreateToggle(rightColumn, " Auto Esquivar al Murder", function(enabled)
            _esquivarEnabled = enabled
            if enabled then
                _startEsquivarLoop()
 -- [notif removed]
            else
                if _esquivarConn then pcall(function() task.cancel(_esquivarConn) end); _esquivarConn = nil end
 -- [notif removed]
            end
        end, false)

        -- Bindable button para esquivar
 CreateToggle(rightColumn, "Show Bindable Dodge Button", function(on)
            local function sweep(p)
                if not p then return end
                for _, g in ipairs(p:GetChildren()) do
                    if g.Name == "EsquivarBind_HUB" then pcall(function() g:Destroy() end) end
                end
            end
            sweep(game:GetService("CoreGui"))
            pcall(function() sweep(LocalPlayer:FindFirstChild("PlayerGui")) end)
            DestroyCapyBind("ESQUIVAR")
            if on then
                local sg = Instance.new("ScreenGui")
                sg.Name = "EsquivarBind_HUB"; sg.ResetOnSpawn = false
                sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
                pcall(function() sg.Parent = game:GetService("CoreGui") end)
                if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
                MakeCapyBindableFrame(sg, "ESQUIVAR", function()
                    _esquivarEnabled = not _esquivarEnabled
                    if _esquivarEnabled then _startEsquivarLoop()
                    else if _esquivarConn then pcall(function() task.cancel(_esquivarConn) end); _esquivarConn = nil end end
 -- [notif removed]
                end, 320, 60)
            end
        end, false)

 CreateSlider(rightColumn, "Distancia Activacion (studs)", 1, 15, 4, function(v) _esquivarDist = v end)
 CreateSlider(rightColumn, "Distancia Escape (studs)", 5, 60, 20, function(v) _esquivarFar = v end)
    end

end

_FU_ImageCache = {}

function _fuFind(root, name, maxDepth)
    maxDepth = maxDepth or 8
    if maxDepth <= 0 or not root then return nil end
    local f = root:FindFirstChild(name)
    if f then return f end
    for _, c in ipairs(root:GetChildren()) do
        local r = _fuFind(c, name, maxDepth - 1)
        if r then return r end
    end
end

function _fuBestImage(frame)
    if not frame then return nil end
    local best, bestArea = nil, 0
    for _, c in ipairs(frame:GetDescendants()) do
        if c:IsA("ImageLabel") and c.Image and c.Image ~= ""
            and not c.Image:find("rbxasset://") then  -- excluir assets del engine
            local area = c.AbsoluteSize.X * c.AbsoluteSize.Y
            if area > bestArea then
                best, bestArea = c.Image, area
            end
        end
    end
    return best
end

function _fuScanWeapons()
    pcall(function()
        local pGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if not pGui then return end

        local function extractItemFrame(frame)
            if not frame then return end
            local itemId = frame:GetAttribute("ItemId")
                        or frame:GetAttribute("RewardedItemId")
                        or frame:GetAttribute("WeaponId")
                        or frame:GetAttribute("Id")
            if not itemId then
                for _, child in ipairs(frame:GetDescendants()) do
                    if child:IsA("TextLabel") and child.Text and child.Text ~= "" then
                        local txt = child.Text
                        if not txt:find(" ") or txt:find("_") then
                            itemId = txt
                        end
                    end
                end
            end
            local img = _fuBestImage(frame)
            if img and img ~= "" then
                if itemId and itemId ~= "" then
                    _FU_ImageCache[itemId] = img
                end
                if frame.Name and frame.Name ~= "" and frame.Name ~= "Frame"
                    and frame.Name ~= "ImageLabel" and frame.Name ~= "TextLabel" then
                    _FU_ImageCache[frame.Name] = img
                end
            end
        end

        crossPlat = pGui:FindFirstChild("CrossPlatform")
        if crossPlat then
            local shopRoot = crossPlat:FindFirstChild("Shop")
            if shopRoot then
                for _, sizeFrame in ipairs(shopRoot:GetChildren()) do   -- Large, Medium, Small
                    local main = sizeFrame:FindFirstChild("Main")
                    local container = main and main:FindFirstChild("Container")
                    local vc = container and container:FindFirstChild("ViewContents")
                    local items = vc and vc:FindFirstChild("Items")
                    local sf = items and items:FindFirstChild("ScrollFrame")
                    if sf then
                        for _, itemFrame in ipairs(sf:GetChildren()) do
                            extractItemFrame(itemFrame)  -- LargeBoxContentItem, etc.
                        end
                    end
                    local cont2 = sizeFrame:FindFirstChild("Container")
                    local vc2 = cont2 and cont2:FindFirstChild("ViewContents")
                    if vc2 then
                        for _, child in ipairs(vc2:GetChildren()) do
                            for _, d in ipairs(child:GetChildren()) do
                                extractItemFrame(d)
                            end
                        end
                    end
                end
            end

            local shopSvc = _fuFind(crossPlat, "ShopService", 5)
            if shopSvc then
                local bcif = shopSvc:FindFirstChild("BoxContentItemFrame")
                if bcif then
                    extractItemFrame(bcif)
                    for _, child in ipairs(bcif:GetChildren()) do
                        extractItemFrame(child)
                    end
                end
            end

            local ipf = crossPlat:FindFirstChild("ItemPackFrame")
            if ipf then
                local boxIcon = _fuFind(ipf, "BoxIcon", 8)
                if boxIcon and boxIcon:IsA("ImageLabel") and boxIcon.Image ~= "" then
                    if boxIcon.Parent then
                        _FU_ImageCache[boxIcon.Parent.Name] = boxIcon.Image
                    end
                end
            end
        end

        mainGUI = pGui:FindFirstChild("MainGUI")
        if mainGUI then
            local vbc = _fuFind(mainGUI, "ViewBoxContents", 8)
            if vbc then
                for _, section in ipairs(vbc:GetChildren()) do  -- BoxContentsLayout, NewBoxContents
                    for _, itemFrame in ipairs(section:GetChildren()) do
                        extractItemFrame(itemFrame)
                    end
                end
            end
            local inventory = _fuFind(mainGUI, "Inventory", 6)
            if inventory then
                local mainInv = _fuFind(inventory, "Main", 4)
                if mainInv then
                    for _, cat in ipairs(mainInv:GetChildren()) do  -- Weapons, Pets, etc.
                        for _, itemFrame in ipairs(cat:GetDescendants()) do
                            if (itemFrame:IsA("Frame") or itemFrame:IsA("ImageButton"))
                                and itemFrame.Name ~= "" and itemFrame.Name ~= "Frame" then
                                extractItemFrame(itemFrame)
                            end
                        end
                    end
                end
            end
        end

        for _, desc in ipairs(pGui:GetDescendants()) do
            if (desc:IsA("Frame") or desc:IsA("ImageButton")) then
                local n = desc.Name
                if n and n ~= "" and n ~= "Frame" and n ~= "ImageLabel"
                    and n ~= "TextLabel" and n ~= "ScrollingFrame"
                    and not _FU_ImageCache[n] then
                    local img = _fuBestImage(desc)
                    if img then _FU_ImageCache[n] = img end
                end
            end
        end
    end)
end

function _fuGetItemImage(itemId, boxImage)
    if _FU_ImageCache[itemId] then return _FU_ImageCache[itemId] end
    return boxImage or "rbxassetid://4618878928"
end

_fuScanDone = false
task.spawn(function()
    for _, waitTime in ipairs({2, 4, 8, 15, 30}) do
        task.wait(waitTime == 2 and 2 or waitTime - (({2,4,8,15,30})[math.max(1,1)]))
        _fuScanWeapons()
        local n = 0; for _ in pairs(_FU_ImageCache) do n += 1 end
        if n > 15 then _fuScanDone = true; break end
    end
end)

FU_RARITY_COLOR = {
    Common    = Color3.fromRGB(200,200,205),
    Uncommon  = Color3.fromRGB(230, 133, 30),
    Rare      = Color3.fromRGB(140, 140, 140),
    Legendary = Color3.fromRGB(255,200,30),
}
