_FU_RARITY_NORM = {
    common="Common", uncommon="Uncommon", rare="Rare", legendary="Legendary",
    Common="Common", Uncommon="Uncommon", Rare="Rare", Legendary="Legendary",
}
function _fuNormRarity(s)
    return s and (_FU_RARITY_NORM[s] or _FU_RARITY_NORM[s:lower()] or "Common")
end

FU_BOXES = {}   -- se llena en _fuBuildBoxList()
_fuBoxesReady = false
_fuBoxSelectorCallback = nil  -- callback para refrescar el selector de UI

function _fuBuildItemsFromModule(mod)
    local data = mod.ItemData or mod
    if not data then return nil, nil, nil end
    local imgVal = data.Image or ""
    local contents = data.Contents or data.contents or {}
    local rarityChances = data.RarityChances or data.rarityChances or {Common=70,Uncommon=15,Rare=10,Legendary=5}
    local nameVal = data.Name or mod.Name or "?"

    local total = (rarityChances.Common or 0)+(rarityChances.Uncommon or 0)
               +(rarityChances.Rare or 0)+(rarityChances.Legendary or 0)

    if #contents == 0 then return nil, nil, nil end

    local nItems = #contents
    local items = {}
    for i, itemId in ipairs(contents) do
        local frac = (i - 0.5) / nItems  -- posicion normalizada 0..1
        local rarity
        local cThresh = (rarityChances.Common or 0) / 100
        local uThresh = cThresh + (rarityChances.Uncommon or 0) / 100
        local rThresh = uThresh + (rarityChances.Rare or 0) / 100
        if frac < cThresh then rarity = "Common"
        elseif frac < uThresh then rarity = "Uncommon"
        elseif frac < rThresh then rarity = "Rare"
        else rarity = "Legendary" end
        table.insert(items, {id=itemId, rarity=rarity})
    end

    return nameVal, imgVal, items
end

function _fuLoadBoxFromModule(boxModule, keyName)
    local ok, data = pcall(require, boxModule)
    if not ok or type(data) ~= "table" then return nil end

    local nameVal, imgVal, items = _fuBuildItemsFromModule(data)
    if not nameVal or not items or #items == 0 then return nil end

    for _, item in ipairs(items) do
        if not _FU_ImageCache[item.id] then
            _FU_ImageCache[item.id] = imgVal  -- placeholder; se sobreescribe si el GUI tiene mejor
        end
    end

    return {
        name  = nameVal,
        key   = keyName or boxModule.Name,
        image = imgVal ~= "" and imgVal or "rbxassetid://4618878928",
        items = items,
        _live = true,  -- viene del juego en tiempo real
    }
end

function _fuBuildBoxList()
    local boxes = {}
    local seenKeys = {}

    local RS = game:GetService("ReplicatedStorage")
    local SS = RS:FindFirstChild("SharedServices")

    pcall(function()
        local eis = SS and SS:FindFirstChild("EventInfoService1")
        local el  = eis and eis:FindFirstChild("EventList")
        if not el then return end
        for _, eventFolder in ipairs(el:GetChildren()) do
            local mbMod = eventFolder:FindFirstChild("MysteryBox")
                       or eventFolder:FindFirstChild("MysteryBox1")
            if mbMod and mbMod:IsA("ModuleScript") then
                local boxEntry = _fuLoadBoxFromModule(mbMod, eventFolder.Name.."Box")
                if boxEntry and not seenKeys[boxEntry.key] then
                    seenKeys[boxEntry.key] = true
                    table.insert(boxes, boxEntry)
                end
            end
            for _, child in ipairs(eventFolder:GetChildren()) do
                if child:IsA("ModuleScript") and child.Name:find("Box") then
                    local boxEntry = _fuLoadBoxFromModule(child, child.Name)
                    if boxEntry and not seenKeys[boxEntry.key] then
                        seenKeys[boxEntry.key] = true
                        table.insert(boxes, boxEntry)
                    end
                end
            end
        end
    end)

    pcall(function()
        local mb = SS and SS:FindFirstChild("MysteryBoxes")
        if not mb then return end
        for _, boxMod in ipairs(mb:GetChildren()) do
            if boxMod:IsA("ModuleScript") then
                local boxEntry = _fuLoadBoxFromModule(boxMod, boxMod.Name)
                if boxEntry and not seenKeys[boxEntry.key] then
                    seenKeys[boxEntry.key] = true
                    table.insert(boxes, boxEntry)
                end
            end
        end
    end)

    pcall(function()
        pGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        cp = pGui and pGui:FindFirstChild("CrossPlatform")
        shop = cp and cp:FindFirstChild("Shop")
        if not shop then return end
        for _, sizeFrame in ipairs(shop:GetChildren()) do
            local main = sizeFrame:FindFirstChild("Main")
            local cont = main and main:FindFirstChild("Container")
            local itemsF = cont and cont:FindFirstChild("Items")
            local sf = itemsF and itemsF:FindFirstChild("ScrollFrame")
            if sf then
                for _, boxFrame in ipairs(sf:GetChildren()) do
                    local bkey = boxFrame.Name
                    if bkey ~= "" and bkey ~= "Frame" and not seenKeys[bkey] then
                        local boxImg = _fuBestImage(boxFrame) or "rbxassetid://4618878928"
                        local vc = cont and cont:FindFirstChild("ViewContents")
                        local itemsInside = vc and (vc:FindFirstChild("BoxContents")
                                         or vc:FindFirstChild("BoxFrame")
                                         or vc:FindFirstChild("Items"))
                        local parsedItems = {}
                        if itemsInside then
                            for _, iFrame in ipairs(itemsInside:GetChildren()) do
                                local iid = iFrame:GetAttribute("ItemId")
                                       or iFrame:GetAttribute("RewardedItemId")
                                       or iFrame.Name
                                local img2 = _fuBestImage(iFrame)
                                if img2 then _FU_ImageCache[iid] = img2 end
                                local rar = _fuNormRarity(iFrame:GetAttribute("Rarity") or "Common")
                                if iid and iid ~= "" and iid ~= "Frame" then
                                    table.insert(parsedItems, {id=iid, rarity=rar})
                                end
                            end
                        end
                        if #parsedItems > 0 then
                            seenKeys[bkey] = true
                            table.insert(boxes, {
                                name  = bkey:gsub("Box"," Box"):gsub("([%u])", " %1"):gsub("^%s+",""),
                                key   = bkey,
                                image = boxImg,
                                items = parsedItems,
                                _live = true,
                            })
                        end
                    end
                end
            end
        end
    end)

    for _, fb in ipairs(_FU_FALLBACK) do
        if not seenKeys[fb.key] then
            local itemsCopy = {}
            for _, it in ipairs(fb.items) do
                table.insert(itemsCopy, {id=it.id, rarity=it.r})
            end
            table.insert(boxes, {
                name  = fb.name,
                key   = fb.key,
                image = fb.image,
                items = itemsCopy,
                _live = false,
            })
        end
    end

    return boxes
end

do
    local itemsCopy = {}
    for _, fb in ipairs(_FU_FALLBACK) do
        local fc = {}
        for _, it in ipairs(fb.items) do table.insert(fc, {id=it.id, rarity=it.r}) end
        table.insert(FU_BOXES, {name=fb.name, key=fb.key, image=fb.image, items=fc, _live=false})
    end
end

task.spawn(function()
    for _, delay in ipairs({3, 6, 12}) do
        task.wait(delay == 3 and 3 or 3)
        local newBoxes = _fuBuildBoxList()
        if newBoxes and #newBoxes > 0 then
            local currentKey = FU_BOXES[_fuState and _fuState.boxIdx or 1] and
                               FU_BOXES[_fuState and _fuState.boxIdx or 1].key
            for i = #FU_BOXES, 1, -1 do FU_BOXES[i] = nil end
            for _, b in ipairs(newBoxes) do table.insert(FU_BOXES, b) end
            if currentKey then
                for i, b in ipairs(FU_BOXES) do
                    if b.key == currentKey then
                        if _fuState then _fuState.boxIdx = i end; break
                    end
                end
            end
            if _fuBoxSelectorCallback then pcall(_fuBoxSelectorCallback) end
            local live = 0
            for _, b in ipairs(FU_BOXES) do if b._live then live += 1 end end
            if live >= 3 then break end  -- suficientes cajas en vivo
        end
    end
    _fuBoxesReady = true
end)

FU_RARITY_WEIGHTS = {{rarity="Common",weight=70},{rarity="Uncommon",weight=15},{rarity="Rare",weight=10},{rarity="Legendary",weight=5}}
function fuPickRarity()
    local t=0; for _,w in ipairs(FU_RARITY_WEIGHTS) do t+=w.weight end
    local r=math.random(1,t); local c=0
    for _,w in ipairs(FU_RARITY_WEIGHTS) do c+=w.weight; if r<=c then return w.rarity end end
    return "Common"
end
function fuPickItem(box)
    local rarity=fuPickRarity(); local pool={}
    for _,item in ipairs(box.items) do if item.rarity==rarity then table.insert(pool,item) end end
    if #pool==0 then pool=box.items end
    return pool[math.random(1,#pool)]
end

_fuState = {boxIdx=1, isOpening=false, openBtnRef=nil}
_fuRouletteGui = nil

function _fuDestroyRoulette()
    if _fuRouletteGui then
        pcall(function() _fuRouletteGui:Destroy() end)
        _fuRouletteGui = nil
    end
    _fuState.isOpening = false
    pcall(function()
        if _fuState.openBtnRef and _fuState.openBtnRef.Parent then
            _fuState.openBtnRef.Text             = ">  ABRIR CAJA"
            _fuState.openBtnRef.BackgroundColor3 = ThemeColors.BackgroundLight
        end
    end)
end

