FU_N_LEFT=22; local FU_N_RIGHT=4

function _fuBuildCard(parent, item, boxImage, posX, isWinner)
    local card=Instance.new("Frame",parent)
    card.Size=UDim2.new(0,FU_CARD_W,1,-16); card.Position=UDim2.new(0,posX,0,8)
    card.BackgroundColor3=Color3.fromRGB(  3,   8,  18); card.BorderSizePixel=0; card.ZIndex=3
    Instance.new("UICorner",card).CornerRadius=UDim.new(0,10)
    local cs=Instance.new("UIStroke",card); cs.Color=fuRC(item.rarity)
    cs.Thickness=isWinner and 3 or 1.5; cs.Transparency=isWinner and 0 or 0.6

    local imgId=_fuGetItemImage(item.id,boxImage)
    local imgFrame=Instance.new("Frame",card)
    imgFrame.Size=UDim2.new(1,-14,0,95); imgFrame.Position=UDim2.new(0,7,0,7)
    imgFrame.BackgroundColor3=fuRC(item.rarity); imgFrame.BackgroundTransparency=0.9
    imgFrame.BorderSizePixel=0; imgFrame.ZIndex=4
    Instance.new("UICorner",imgFrame).CornerRadius=UDim.new(0,8)
    local imgLbl=Instance.new("ImageLabel",imgFrame)
    imgLbl.Size=UDim2.new(1,-6,1,-6); imgLbl.Position=UDim2.new(0,3,0,3)
    imgLbl.BackgroundTransparency=1; imgLbl.Image=imgId
    imgLbl.ScaleType=Enum.ScaleType.Fit; imgLbl.ZIndex=5; imgLbl.BorderSizePixel=0

    local cleanName=item.id:gsub("_K_20%d%d$",""):gsub("_G_20%d%d$",""):gsub("_20%d%d$",""):gsub("_K$",""):gsub("_G$",""):gsub("_"," ")
    local nameLbl=Instance.new("TextLabel",card)
    nameLbl.Size=UDim2.new(1,-6,0,28); nameLbl.Position=UDim2.new(0,3,0,104)
    nameLbl.BackgroundTransparency=1; nameLbl.Text=cleanName
    nameLbl.TextColor3=Color3.fromRGB(230,230,230); nameLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    nameLbl.TextSize=11; nameLbl.TextWrapped=true; nameLbl.ZIndex=4

    local badge=Instance.new("Frame",card)
    badge.Size=UDim2.new(1,-16,0,17); badge.Position=UDim2.new(0,8,1,-22)
    badge.BackgroundColor3=fuRC(item.rarity); badge.BackgroundTransparency=0.2
    badge.BorderSizePixel=0; badge.ZIndex=4
    Instance.new("UICorner",badge).CornerRadius=UDim.new(0,5)
    local bl=Instance.new("TextLabel",badge)
    bl.Size=UDim2.new(1,0,1,0); bl.BackgroundTransparency=1
    bl.Text=item.rarity:upper(); bl.TextColor3=Color3.fromRGB(255,255,255)
    bl.FontFace = Font.fromEnum(Enum.Font.Arimo); bl.TextSize=9; bl.ZIndex=5
end

function _fuPlayRoulette(box, wonItem)
    _fuDestroyRoulette()

    pcall(function()
        local bc = game:GetService("ReplicatedStorage")
            :WaitForChild("Remotes",3)
            :WaitForChild("Shop",3)
            :WaitForChild("BoxController",3)
        if bc and bc:IsA("BindableEvent") then
            bc:Fire({{MysteryBoxId = box.key, RewardedItemId = wonItem.id}})
        end
    end)

    VP_W=740
    _fuRouletteGui=Instance.new("ScreenGui")
    _fuRouletteGui.Name="FakeUnboxRoulette"; _fuRouletteGui.ResetOnSpawn=false
    _fuRouletteGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
    _fuRouletteGui.IgnoreGuiInset=true; _fuRouletteGui.DisplayOrder=9999
    pcall(function() _fuRouletteGui.Parent=game:GetService("CoreGui") end)
    if not _fuRouletteGui.Parent then _fuRouletteGui.Parent=LocalPlayer.PlayerGui end

    bg=Instance.new("Frame",_fuRouletteGui)
    bg.Size=UDim2.new(1,0,1,0); bg.BackgroundColor3=Color3.fromRGB(  3,   8,  18)
    bg.BackgroundTransparency=0.85; bg.BorderSizePixel=0; bg.ZIndex=1

    titleLbl=Instance.new("TextLabel",_fuRouletteGui)
    titleLbl.Size=UDim2.new(0,VP_W,0,46); titleLbl.Position=UDim2.new(0.5,-VP_W/2,0,55)
    titleLbl.BackgroundTransparency=1; titleLbl.Text=" "..box.name:upper().." "
    titleLbl.TextColor3=Color3.fromRGB(255, 210, 80); titleLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    titleLbl.TextSize=24; titleLbl.TextTransparency=1; titleLbl.ZIndex=10
    TweenService:Create(titleLbl,TweenInfo.new(0.4),{TextTransparency=0}):Play()

    boxImgFrame=Instance.new("Frame",_fuRouletteGui)
    boxImgFrame.Size=UDim2.new(0,90,0,90); boxImgFrame.Position=UDim2.new(0.5,-VP_W/2-110,0.5,-45)
    boxImgFrame.BackgroundColor3=Color3.fromRGB(  3,   8,  18); boxImgFrame.BorderSizePixel=0; boxImgFrame.ZIndex=10
    Instance.new("UICorner",boxImgFrame).CornerRadius=UDim.new(0,12)
    Instance.new("UIStroke",boxImgFrame).Color=ThemeColors.Primary
    boxImgLbl=Instance.new("ImageLabel",boxImgFrame)
    boxImgLbl.Size=UDim2.new(1,-8,1,-8); boxImgLbl.Position=UDim2.new(0,4,0,4)
    boxImgLbl.BackgroundTransparency=1; boxImgLbl.Image=box.image
    boxImgLbl.ScaleType=Enum.ScaleType.Fit; boxImgLbl.ZIndex=11

    rouletteBg=Instance.new("Frame",_fuRouletteGui)
    rouletteBg.Size=UDim2.new(0,VP_W,0,165); rouletteBg.Position=UDim2.new(0.5,-VP_W/2,0.5,-82)
    rouletteBg.BackgroundColor3=Color3.fromRGB(  3,   8,  18); rouletteBg.BorderSizePixel=0; rouletteBg.ZIndex=2
    Instance.new("UICorner",rouletteBg).CornerRadius=UDim.new(0,14)
    rbs=Instance.new("UIStroke",rouletteBg); rbs.Color=ThemeColors.Primary; rbs.Thickness=2.5

    centerLine=Instance.new("Frame",rouletteBg)
    centerLine.Size=UDim2.new(0,3,1,-10); centerLine.Position=UDim2.new(0.5,-1,0,5)
    centerLine.BackgroundColor3=Color3.fromRGB(255,60,60); centerLine.BorderSizePixel=0; centerLine.ZIndex=10

    triTop=Instance.new("ImageLabel",rouletteBg)
    triTop.Size=UDim2.new(0,18,0,12); triTop.Position=UDim2.new(0.5,-9,0,-1)
    triTop.BackgroundTransparency=1; triTop.Image="rbxassetid://4918357796"
    triTop.ImageColor3=Color3.fromRGB(255,60,60); triTop.ZIndex=10

    for _,side in ipairs({"Left","Right"}) do
        local f=Instance.new("Frame",rouletteBg)
        f.Size=UDim2.new(0,100,1,0)
        f.Position=side=="Left" and UDim2.new(0,0,0,0) or UDim2.new(1,-100,0,0)
        f.BackgroundColor3=Color3.fromRGB(  3,   8,  18); f.BorderSizePixel=0; f.ZIndex=9
        Instance.new("UICorner",f).CornerRadius=UDim.new(0,14)
        local g=Instance.new("UIGradient",f); g.Rotation=side=="Left" and 90 or 270
        g.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0),NumberSequenceKeypoint.new(1,1)})
    end

    scroll=Instance.new("ScrollingFrame",rouletteBg)
    scroll.Size=UDim2.new(1,0,1,0); scroll.BackgroundTransparency=1
    scroll.BorderSizePixel=0; scroll.ScrollBarThickness=0
    scroll.ScrollingEnabled=false; scroll.ClipsDescendants=true; scroll.ZIndex=3

    TOTAL=FU_N_LEFT+1+FU_N_RIGHT
    scroll.CanvasSize=UDim2.new(0,TOTAL*FU_STEP,0,0)
    wonIdx=FU_N_LEFT+1; local allItems={}
    for i=1,FU_N_LEFT do table.insert(allItems,box.items[math.random(1,#box.items)]) end
    table.insert(allItems,wonItem)
    for i=1,FU_N_RIGHT do table.insert(allItems,box.items[math.random(1,#box.items)]) end
    for i,item in ipairs(allItems) do _fuBuildCard(scroll,item,box.image,(i-1)*FU_STEP,i==wonIdx) end

    wonCardCenter=(wonIdx-1)*FU_STEP+FU_CARD_W/2
    targetOffset=wonCardCenter-VP_W/2
    scroll.CanvasPosition=Vector2.new(0,0)

    task.spawn(function()
        task.wait(0.5)
        SPIN_TIME=4.5; local elapsed=0
        local function easeOutQuart(t) return 1-(1-t)^4 end
        local conn
        conn=RunService.RenderStepped:Connect(function(dt)
            elapsed=math.min(elapsed+dt,SPIN_TIME)
            local te=easeOutQuart(elapsed/SPIN_TIME)
            scroll.CanvasPosition=Vector2.new(te*targetOffset,0)
            if elapsed>=SPIN_TIME then
                conn:Disconnect(); scroll.CanvasPosition=Vector2.new(targetOffset,0)
                task.wait(0.1)
                for _,c in ipairs(scroll:GetChildren()) do
                    if c:IsA("Frame") and math.abs(c.Position.X.Offset-(wonIdx-1)*FU_STEP)<2 then
                        local ws=c:FindFirstChildOfClass("UIStroke")
                        if ws then ws.Thickness=4
                            task.spawn(function()
                                while c and c.Parent do
                                    TweenService:Create(ws,TweenInfo.new(0.6,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut),{Transparency=0}):Play(); task.wait(0.6)
                                    TweenService:Create(ws,TweenInfo.new(0.6,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut),{Transparency=0.6}):Play(); task.wait(0.6)
                                end
                            end)
                        end; break
                    end
                end
                task.wait(0.2)
                cleanName=wonItem.id:gsub("_K_20%d%d$",""):gsub("_G_20%d%d$",""):gsub("_20%d%d$",""):gsub("_K$",""):gsub("_G$",""):gsub("_"," ")
                banner=Instance.new("Frame",_fuRouletteGui)
                banner.Size=UDim2.new(0,440,0,90); banner.Position=UDim2.new(0.5,-220,0.5,95)
                banner.BackgroundColor3=Color3.fromRGB(  3,   8,  18); banner.BackgroundTransparency=1
                banner.BorderSizePixel=0; banner.ZIndex=11
                Instance.new("UICorner",banner).CornerRadius=UDim.new(0,14)
                bs=Instance.new("UIStroke",banner); bs.Color=fuRC(wonItem.rarity); bs.Thickness=3
                gl=Instance.new("TextLabel",banner)
                gl.Size=UDim2.new(1,0,0,30); gl.Position=UDim2.new(0,0,0,8)
                gl.BackgroundTransparency=1; gl.Text="!OBTUVISTE!"; gl.TextColor3=Color3.fromRGB(172, 172, 172)
                gl.FontFace = Font.fromEnum(Enum.Font.Arimo); gl.TextSize=13; gl.ZIndex=12
                il=Instance.new("TextLabel",banner)
                il.Size=UDim2.new(1,-16,0,42); il.Position=UDim2.new(0,8,0,34)
                il.BackgroundTransparency=1; il.Text=cleanName; il.TextColor3=fuRC(wonItem.rarity)
                il.FontFace = Font.fromEnum(Enum.Font.Arimo); il.TextSize=26; il.ZIndex=12
                TweenService:Create(banner,TweenInfo.new(0.4,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{BackgroundTransparency=0}):Play()
                if wonItem.rarity=="Legendary" then
                    for _=1,8 do task.spawn(function()
                        task.wait(math.random()*0.5)
                        local p=Instance.new("Frame",_fuRouletteGui)
                        p.Size=UDim2.new(0,8,0,8); p.ZIndex=15; p.BackgroundColor3=fuRC("Legendary"); p.BorderSizePixel=0
                        Instance.new("UICorner",p).CornerRadius=UDim.new(1,0)
                        p.Position=UDim2.new(0.5,math.random(-200,200),0.5,math.random(-80,80))
                        TweenService:Create(p,TweenInfo.new(1.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{
                            Position=UDim2.new(p.Position.X.Scale,p.Position.X.Offset+math.random(-60,60),p.Position.Y.Scale,p.Position.Y.Offset-math.random(60,150)),
                            BackgroundTransparency=1,Size=UDim2.new(0,2,0,2)}):Play()
                        task.wait(1.2); pcall(function() p:Destroy() end)
                    end) end
                end
                task.wait(0.4)
                closeBtn=Instance.new("TextButton",_fuRouletteGui)
                closeBtn.Size=UDim2.new(0,150,0,42); closeBtn.Position=UDim2.new(0.5,-75,0.5,200)
                closeBtn.BackgroundColor3=Color3.fromRGB(  3,   8,  18); closeBtn.BorderSizePixel=0
                closeBtn.Text="CERRAR"; closeBtn.TextColor3=Color3.fromRGB(255, 210, 80)
                closeBtn.FontFace = Font.fromEnum(Enum.Font.Arimo); closeBtn.TextSize=18; closeBtn.ZIndex=12
                Instance.new("UICorner",closeBtn).CornerRadius=UDim.new(0,10)
                css=Instance.new("UIStroke",closeBtn); css.Color=ThemeColors.Primary; css.Thickness=2
                closeBtn.BackgroundTransparency=1
                TweenService:Create(closeBtn,TweenInfo.new(0.3,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{BackgroundTransparency=0}):Play()
                closeBtn.Activated:Connect(_fuDestroyRoulette)
                bgBtn=Instance.new("TextButton",bg)
                bgBtn.Size=UDim2.new(1,0,1,0); bgBtn.BackgroundTransparency=1; bgBtn.Text=""; bgBtn.ZIndex=0
                bgBtn.Activated:Connect(_fuDestroyRoulette)
            end
        end)
    end)


end

function CreateMainUI_Toys()
 CreateSection(leftColumn, "", "FAKE UNBOX", ThemeColors.Primary)

    local boxSelectorRow = Instance.new("Frame", leftColumn)
    boxSelectorRow.Name             = "FU_BoxRow"
    boxSelectorRow.Size             = UDim2.new(1, -10, 0, 38)
    boxSelectorRow.BackgroundTransparency = 1
