    local bns=Instance.new("UIStroke",boxNameLbl); bns.Color=ThemeColors.Primary; bns.Thickness=1.5; bns.Transparency=0.3

    local nextBtn = Instance.new("TextButton", boxSelectorRow)
    nextBtn.Size=UDim2.new(0,32,0,32); nextBtn.Position=UDim2.new(1,-32,0.5,-16)
    nextBtn.BackgroundColor3=Color3.fromRGB(53, 26, 8); nextBtn.BorderSizePixel=0
    nextBtn.Text=">"; nextBtn.TextColor3=ThemeColors.Primary
    nextBtn.FontFace = Font.fromEnum(Enum.Font.Arimo); nextBtn.TextSize=18; nextBtn.AutoButtonColor=false
    Instance.new("UICorner",nextBtn).CornerRadius=UDim.new(0,8)
    local ns=Instance.new("UIStroke",nextBtn); ns.Color=ThemeColors.Primary; ns.Thickness=1.5

    local boxCard = Instance.new("Frame", leftColumn)
    boxCard.Name                   = "FU_BoxCard"
    boxCard.Size                   = UDim2.new(1, -10, 0, 86)
    boxCard.BackgroundColor3       = Color3.fromRGB(  3,   8,  18)
    boxCard.BackgroundTransparency = 0.68
    boxCard.BorderSizePixel        = 0
    Instance.new("UICorner", boxCard).CornerRadius = UDim.new(0, 12)
    local cardStroke = Instance.new("UIStroke", boxCard)
    cardStroke.Color = ThemeColors.Primary; cardStroke.Thickness = 2; cardStroke.Transparency = 0.3

    local boxImg = Instance.new("ImageLabel", boxCard)
    boxImg.Size                   = UDim2.new(0, 76, 0, 76)
    boxImg.Position               = UDim2.new(0, 5, 0.5, -38)
    boxImg.BackgroundTransparency = 1
    boxImg.Image                  = FU_BOXES[1].image
    boxImg.ScaleType              = Enum.ScaleType.Fit
    boxImg.ZIndex                 = 2

    local openBtn = Instance.new("TextButton", boxCard)
    openBtn.Size             = UDim2.new(1, -90, 1, -16)
    openBtn.Position         = UDim2.new(0, 88, 0, 8)
    openBtn.BackgroundColor3 = ThemeColors.BackgroundLight
    openBtn.BorderSizePixel  = 0
    openBtn.Text             = ">  ABRIR\nCAJA"
    openBtn.TextColor3       = ThemeColors.Accent
    openBtn.FontFace = Font.fromEnum(Enum.Font.Arimo)
    openBtn.TextSize         = 17
    openBtn.AutoButtonColor  = false
    openBtn.ZIndex           = 3
    Instance.new("UICorner", openBtn).CornerRadius = UDim.new(0, 10)
    local openStroke = Instance.new("UIStroke", openBtn)
    openStroke.Color = ThemeColors.Primary; openStroke.Thickness = 2.5

    task.spawn(function()
        while openBtn and openBtn.Parent do
            TweenService:Create(openStroke,TweenInfo.new(1.2,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut),{Transparency=0.5}):Play()
            task.wait(1.2)
            TweenService:Create(openStroke,TweenInfo.new(1.2,Enum.EasingStyle.Sine,Enum.EasingDirection.InOut),{Transparency=0}):Play()
            task.wait(1.2)
        end
    end)

    probsData = {
        {n="Common",    p="70%", c=FU_RARITY_COLOR.Common},
        {n="Uncommon",  p="15%", c=FU_RARITY_COLOR.Uncommon},
        {n="Rare",      p="10%", c=FU_RARITY_COLOR.Rare},
        {n="Legendary", p="5%",  c=FU_RARITY_COLOR.Legendary},
    }
    probHeader = Instance.new("TextLabel", leftColumn)
    probHeader.Size=UDim2.new(1,-10,0,16); probHeader.BackgroundTransparency=1
    probHeader.Text="PROBABILIDADES:"; probHeader.TextColor3=Color3.fromRGB(142, 142, 142)
    probHeader.FontFace = Font.fromEnum(Enum.Font.Arimo); probHeader.TextSize=11
    probHeader.TextXAlignment=Enum.TextXAlignment.Left

    for _, r in ipairs(probsData) do
        local row=Instance.new("Frame",leftColumn)
        row.Size=UDim2.new(1,-10,0,18); row.BackgroundTransparency=1; row.BorderSizePixel=0
        local dot=Instance.new("Frame",row); dot.Size=UDim2.new(0,9,0,9); dot.Position=UDim2.new(0,2,0.5,-4)
        dot.BackgroundColor3=r.c; dot.BorderSizePixel=0; Instance.new("UICorner",dot).CornerRadius=UDim.new(1,0)
        local rl=Instance.new("TextLabel",row); rl.Size=UDim2.new(1,-16,1,0); rl.Position=UDim2.new(0,16,0,0)
        rl.BackgroundTransparency=1; rl.Text=r.n.." "..r.p; rl.TextColor3=r.c
        rl.FontFace = Font.fromEnum(Enum.Font.Arimo); rl.TextSize=12; rl.TextXAlignment=Enum.TextXAlignment.Left
    end

    local function refreshBox()
        local box = FU_BOXES[_fuState.boxIdx]
        if not box then return end
 boxNameLbl.Text = box.name
        boxImg.Image    = box.image
        boxNameLbl.TextColor3 = box._live
            and Color3.fromRGB(160, 160, 165)
            or  Color3.fromRGB(255,255,255)
        task.spawn(_fuScanWeapons)
    end

    _fuBoxSelectorCallback = function() pcall(refreshBox) end
    refreshBox()

    prevBtn.Activated:Connect(function()

        _fuState.boxIdx = _fuState.boxIdx > 1 and _fuState.boxIdx-1 or #FU_BOXES
        refreshBox()
    end)
    nextBtn.Activated:Connect(function()

        _fuState.boxIdx = _fuState.boxIdx < #FU_BOXES and _fuState.boxIdx+1 or 1
        refreshBox()
    end)

    openBtn.MouseEnter:Connect(function()
        if not _fuState.isOpening then
            TweenService:Create(openBtn,TweenInfo.new(0.12),{BackgroundColor3=Color3.fromRGB(59, 59, 59)}):Play()
        end
    end)
    openBtn.MouseLeave:Connect(function()
        if not _fuState.isOpening then
            TweenService:Create(openBtn,TweenInfo.new(0.12),{BackgroundColor3=ThemeColors.BackgroundLight}):Play()
        end
    end)

    openBtn.Activated:Connect(function()
        if _fuState.isOpening then return end
        _fuState.isOpening  = true
        _fuState.openBtnRef = openBtn


 openBtn.Text = "\nABRIENDO"
        TweenService:Create(openBtn,TweenInfo.new(0.1),{BackgroundColor3=Color3.fromRGB(85, 85, 85)}):Play()
        task.wait(0.12)
        TweenService:Create(openBtn,TweenInfo.new(0.15),{BackgroundColor3=ThemeColors.BackgroundLight}):Play()

        box     = FU_BOXES[_fuState.boxIdx]
        wonItem = fuPickItem(box)
        _fuPlayRoulette(box, wonItem)
    end)
end



