                BackgroundTransparency = 1
            }):Play()
            TweenService:Create(optStroke, TweenInfo.new(0.18), {
                Color = sel and ThemeColors.Aurora2 or ThemeColors.Secondary,
                Transparency = sel and 0.1 or 0.6
            }):Play()
            optTxt.TextColor3 = sel and Color3.fromRGB(255,255,255) or ThemeColors.TextPrimary
        end)

        optBtn.Activated:Connect(function()

            ApplyTheme(themeName)
 valueLabel.Text = themeName
            previewDot.BackgroundColor3 = ThemeColors.Primary
            previewDot2.BackgroundColor3 = ThemeColors.Aurora2
            sw1.BackgroundColor3 = ThemeColors.Primary
            sw2.BackgroundColor3 = ThemeColors.Aurora2
            sw3.BackgroundColor3 = ThemeColors.Aurora3
 swLabel.Text = " " .. themeName
            for _, child in ipairs(menu:GetChildren()) do
                if child:IsA("TextButton") then
                    local cStk = child:FindFirstChildOfClass("UIStroke")
                    local cTxt = child:FindFirstChild("TextLabel")
                    local cChk = child:FindFirstChildWhichIsA("TextLabel", true)
                    local isThis = (child == optBtn)
                    child.BackgroundColor3 = isThis and ThemeColors.Primary or ThemeColors.BackgroundLight
                    if cStk then
                        cStk.Color = isThis and ThemeColors.Aurora2 or ThemeColors.Secondary
                        cStk.Transparency = isThis and 0.1 or 0.6
                    end
                    for _, lbl in ipairs(child:GetChildren()) do
                        if lbl:IsA("TextLabel") then
 if lbl.Text == "" or lbl.Text == "" then
 lbl.Text = isThis and "" or ""
                            elseif lbl.Name ~= "" then
                                lbl.TextColor3 = isThis and Color3.fromRGB(255,255,255) or ThemeColors.TextPrimary
                            end
                        end
                    end
                end
            end
 menuOpen = false; arrow.Text = ""
            TweenService:Create(menu, TweenInfo.new(0.2,Enum.EasingStyle.Back,Enum.EasingDirection.In),{Size=UDim2.new(0,0,0,0)}):Play()
            task.wait(0.22); menu.Visible = false
 CreateCustomNotification(" THEME", themeName .. " ", 2)
        end)
    end

    selFrame.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end

        if menuOpen then
            local nOpts = #themeList
            local absPos = container.AbsolutePosition
            local absSize = container.AbsoluteSize
            menu.Size = UDim2.new(0, 0, 0, 0)
            menu.Position = UDim2.new(0, absPos.X + 4, 0, absPos.Y + absSize.Y + 4)
            menu.Visible = true
            TweenService:Create(menu, TweenInfo.new(0.25,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{
                Size = UDim2.new(0, absSize.X, 0, nOpts * 44 + 12)
            }):Play()
            TweenService:Create(arrow, TweenInfo.new(0.2), {Rotation = 180}):Play()
            arrow.TextColor3 = ThemeColors.Primary
        else
            TweenService:Create(menu, TweenInfo.new(0.2,Enum.EasingStyle.Back,Enum.EasingDirection.In),{Size=UDim2.new(0,0,0,0)}):Play()
            TweenService:Create(arrow, TweenInfo.new(0.2), {Rotation = 0}):Play()
            arrow.TextColor3 = Color3.fromRGB(255,255,255)
            task.wait(0.22); menu.Visible = false
        end
    end)
    selFrame.MouseEnter:Connect(function()
        TweenService:Create(selFrame, TweenInfo.new(0.2),{BackgroundTransparency=0.65}):Play()
        TweenService:Create(selStroke, TweenInfo.new(0.2),{Thickness=2.5}):Play()
        TweenService:Create(valueLabel, TweenInfo.new(0.2),{TextColor3=Color3.fromRGB(255,255,255)}):Play()
    end)
    selFrame.MouseLeave:Connect(function()
        TweenService:Create(selFrame, TweenInfo.new(0.2),{BackgroundTransparency=0.82}):Play()
        TweenService:Create(selStroke, TweenInfo.new(0.2),{Thickness=2}):Play()
        TweenService:Create(valueLabel, TweenInfo.new(0.2),{TextColor3=ThemeColors.Primary}):Play()
    end)
end

