function CreateMainUI_LogoSelector()

    -- == HAND FLUTTER ========================================================
    do
        local _hfConn    = nil
        local _hfOn      = false
        local _hfSpeed   = 20   -- grados/frame de oscilacion
        local _hfRange   = 40   -- rango total en grados
        local _hfBindGui = nil

 CreateSection(leftColumn, "", "HAND FLUTTER", ThemeColors.Aurora2)

 CreateSlider(leftColumn, "Oscillation Speed", 1, 60, 20, function(v) _hfSpeed = v end)
 CreateSlider(leftColumn, "Rango ( deg)", 5, 90, 40, function(v) _hfRange = v end)

        -- Animacion: ShakeAnimation del Bell2025 toy
        -- Ruta: LocalPlayer.Backpack.Toys.Bell2025.ShakeToyScript.ShakeAnimation
        local _hfTrack = nil  -- AnimationTrack activo para no acumular tracks
        local function _playShakeAnim()
            pcall(function()
                -- Buscar en Backpack Y en Character (puede estar equipado)
                local bell = nil
                for _, loc in ipairs({LocalPlayer.Backpack, LocalPlayer.Character}) do
                    if loc then
                        local toys = loc:FindFirstChild("Toys")
                        if toys then
                            bell = toys:FindFirstChild("Bell2025")
                            if bell then break end
                        end
                        -- Tambien buscar directo sin carpeta Toys
                        bell = loc:FindFirstChild("Bell2025")
                        if bell then break end
                    end
                end
                if not bell then
                    CreateCustomNotification("HAND FLUTTER", "Bell2025 no encontrado en Backpack", 2)
                    return
                end

                local shakeScript = bell:FindFirstChild("ShakeToyScript")
                local anim = shakeScript and shakeScript:FindFirstChild("ShakeAnimation")
                           or bell:FindFirstChild("ShakeAnimation")  -- fallback directo

                if not anim then
                    CreateCustomNotification("HAND FLUTTER", "ShakeAnimation no encontrado", 2)
                    return
                end

                local char = LocalPlayer.Character
                if not char then return end

                -- Usar Animator (mas correcto que Humanoid:LoadAnimation en R15)
                local hum      = char:FindFirstChildOfClass("Humanoid")
                local animator = hum and hum:FindFirstChildOfClass("Animator")
                if not animator then return end

                -- Parar track anterior si sigue corriendo
                if _hfTrack and _hfTrack.IsPlaying then
                    _hfTrack:Stop(0)
                end

                _hfTrack = animator:LoadAnimation(anim)
                _hfTrack:Play()

                -- Repetir mientras flutter esta ON
                _hfTrack.Stopped:Connect(function()
                    if _hfOn and _hfTrack then
                        _hfTrack:Play()
                    end
                end)
            end)
        end

        local _hfT = 0
        local function _hfLoop()
            if _hfConn then pcall(function() _hfConn:Disconnect() end); _hfConn = nil end
            _hfConn = RunService.Heartbeat:Connect(function()
                if not _hfOn then _hfConn:Disconnect(); _hfConn = nil; return end
                _hfT = _hfT + _hfSpeed * 0.016
                local char = LocalPlayer.Character
                -- Oscilar ambos brazos
                local parts = {"LeftUpperArm", "RightUpperArm", "LeftArm", "RightArm"}
                for _, pName in ipairs(parts) do
                    local part = char and char:FindFirstChild(pName)
                    if part and part:IsA("BasePart") then
                        local angle = math.sin(_hfT) * math.rad(_hfRange)
                        pcall(function()
                            part.CFrame = part.CFrame * CFrame.Angles(angle, 0, 0)
                        end)
                    end
                end
            end)
        end

 CreateToggle(leftColumn, "Hand Flutter", function(on)
            _hfOn = on
            if not on then
                if _hfConn then pcall(function() _hfConn:Disconnect() end); _hfConn = nil end
                return
            end
            _hfLoop()
            -- [notif removed]
        end, false)

        -- Bindable: reproduce ShakeAnimation
        local function _makeHFBtn()
            if _hfBindGui then pcall(function() _hfBindGui:Destroy() end) end
            for _, g in ipairs(game:GetService("CoreGui"):GetChildren()) do
                if g.Name == "HandFlutterBindable" then pcall(function() g:Destroy() end) end
            end
            _hfBindGui = Instance.new("ScreenGui")
            _hfBindGui.Name = "HandFlutterBindable"; _hfBindGui.ResetOnSpawn = false
            _hfBindGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling; _hfBindGui.IgnoreGuiInset = true
            pcall(function() _hfBindGui.Parent = game:GetService("CoreGui") end)
            if not _hfBindGui.Parent then _hfBindGui.Parent = LocalPlayer:WaitForChild("PlayerGui") end
            MakeCapyBindableFrame(_hfBindGui, "FLUTTER", function()
                -- Reproducir ShakeAnimation siempre al presionar
                _playShakeAnim()
            end, 80, 310)
        end
 CreateAuroraToggle(leftColumn, "Enable Hand Flutter Bindable", function(on)
            if on then _makeHFBtn()
            else
                if _hfBindGui then pcall(function() _hfBindGui:Destroy() end); _hfBindGui = nil end
                DestroyCapyBind("FLUTTER")
            end
        end, false)
    end
end

function CreateMainUI_BackgroundSelector()
    -- ==================================================================
    -- SECOND LIFE v2 -- FIX MM2: knife baja HP a 0 de un solo golpe.
    -- 1ra cuchillada -> HP a 0 -> interceptamos -> restauramos -> sobrevivis
    -- 2da cuchillada (o siguientes sin vidas) -> muerte normal
    -- ==================================================================
 CreateSection(leftColumn, "", "SECOND LIFE", ThemeColors.Aurora1)

    -- Conexiones activas del Second Life (para cleanup limpio)
    local _slHealthConn = nil
    local _slRefillConn = nil
    local _slCharConn   = nil

    local function _slStopRefill()
        if _slRefillConn then
            pcall(function() _slRefillConn:Disconnect() end)
            _slRefillConn = nil
        end
    end

    local function _slCleanup()
        _slStopRefill()
        if _slHealthConn then pcall(function() _slHealthConn:Disconnect() end); _slHealthConn = nil end
    end

    local function setupSecondLife(character)
        _slCleanup()
        if not character then return end
        if not Settings.secondLife.enabled then return end

        local humanoid = character:WaitForChild("Humanoid", 5)
        local hrp      = character:WaitForChild("HumanoidRootPart", 5)
        if not humanoid or not hrp then return end

        -- Resetear vidas al entrar al personaje
        Settings.secondLife.used = false
        local _protecting = false
        local _lastHit    = 0

        -- HealthChanged se dispara ANTES que .Died -- es el momento correcto
        -- MM2 knife: HP baja directo de 100 -> 0 en un solo evento
        _slHealthConn = humanoid.HealthChanged:Connect(function(hp)
            if not Settings.secondLife.enabled then return end
            if hp > 0.5 then return end          -- HP normal, ignorar
            if _protecting then return end        -- ya procesando este golpe
            if Settings.secondLife.used then      -- sin vidas -> muerte normal
                humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
                return
            end

            -- Debounce: evitar doble-disparo del evento en el mismo tick
            local now = tick()
            if now - _lastHit < 0.2 then return end
            _lastHit = now

            -- -- SOBREVIVIR PRIMER GOLPE ----------------------------------
            Settings.secondLife.used = true
            _protecting = true

            -- 1. Bloquear estado Dead ANTES de que Roblox lo procese
            pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end)
            -- 2. Restaurar HP en el MISMO frame (sin task.wait)
            pcall(function() humanoid.Health = humanoid.MaxHealth end)
            pcall(function() humanoid.PlatformStand = false end)

            -- 3. Mantener HP > 0 durante 200ms (cubre el tick de red del servidor)
            local _refillT = 0
            _slStopRefill()
            _slRefillConn = RunService.Heartbeat:Connect(function(dt)
                _refillT = _refillT + dt
                if not humanoid or not humanoid.Parent then
                    _slStopRefill(); _protecting = false; return
                end
                -- Bloquear repetidamente la muerte y restaurar HP
                if _refillT < 0.2 then
                    pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end)
                    if humanoid.Health < 1 then
                        pcall(function() humanoid.Health = humanoid.MaxHealth end)
                    end
                    if humanoid.PlatformStand then
                        pcall(function() humanoid.PlatformStand = false end)
                    end
                else
                    -- Pasados 200ms: re-habilitar muerte normal para el proximo golpe
                    _slStopRefill()
                    pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, true) end)
                    _protecting = false
                end
            end)

            -- Feedback visual: flash rojo
            pcall(function()
                local sg = Instance.new("ScreenGui"); sg.ResetOnSpawn = false
                sg.Name = "SLFlash"; sg.IgnoreGuiInset = true
                sg.Parent = LocalPlayer.PlayerGui
                local f = Instance.new("Frame", sg)
                f.Size = UDim2.new(1,0,1,0)
                f.BackgroundColor3 = Color3.fromRGB(255, 0, 0)
                f.BackgroundTransparency = 0.35
                f.BorderSizePixel = 0
                TweenService:Create(f, TweenInfo.new(0.6), {BackgroundTransparency = 1}):Play()
                Debris:AddItem(sg, 1.5)
            end)
            -- Sonido
            pcall(function()
                local snd = Instance.new("Sound")
                snd.SoundId = "rbxassetid://9116544314"
                snd.Volume = 0.8; snd.Parent = hrp; snd:Play()
                Debris:AddItem(snd, 2)
            end)

 CreateCustomNotification("<3 SECOND LIFE", "!Sobreviviste! Proximo golpe es FATAL", 3)
        end)
    end

 CreateAuroraToggle(leftColumn, "Second Life", function(enabled)
        Settings.secondLife.enabled = enabled
        Settings.secondLife.used    = false
        if not enabled then
            _slCleanup()
            if _slCharConn then pcall(function() _slCharConn:Disconnect() end); _slCharConn = nil end
 CreateCustomNotification("SECOND LIFE", "OFF", 1)
            return
        end
        -- Activar: hookear personaje actual y futuros respawns
        if LocalPlayer.Character then
            task.spawn(function() setupSecondLife(LocalPlayer.Character) end)
        end
        if _slCharConn then pcall(function() _slCharConn:Disconnect() end) end
        _slCharConn = LocalPlayer.CharacterAdded:Connect(function(character)
            task.wait(0.3)  -- esperar que cargue el Humanoid
            setupSecondLife(character)
        end)
 CreateCustomNotification("<3 SECOND LIFE", "ON -- sobrevivis el 1er golpe", 2)
    end, Settings.secondLife.enabled)

    -- -- Second Life (Secure) -- TP fuera del mapa 3 seg y vuelve ------
    -- ==================================================================
    -- TP LOW MAP -- Teleporta ABAJO del mapa al activarse o al recibir dano mortal
    -- Estado persistido en _G para sobrevivir ClearContent() entre tabs
    -- ==================================================================
 CreateSection(leftColumn, "", "TP LOW MAP", ThemeColors.Aurora3)
    do
        -- Persistir todo en _G para sobrevivir cambios de tab
        _G._tpLow = _G._tpLow or {
            enabled  = false,
            conn     = nil,
            charConn = nil,
            floatConn = nil,
        }
        local _st = _G._tpLow
        local LOW_Y = -500

        local function _tpLowCleanup()
            if _st.conn      then pcall(function() _st.conn:Disconnect()      end); _st.conn      = nil end
            if _st.floatConn then pcall(function() _st.floatConn:Disconnect() end); _st.floatConn = nil end
        end

        -- Teleportar inmediatamente abajo del mapa
        local function _doTP()
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then return end
            pcall(function()
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(hrp.Position.X, LOW_Y, hrp.Position.Z)
            end)
            -- Bloquear muerte
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end)
            hum.Health = math.max(hum.Health, 1)
            hum.PlatformStand = false
            CreateCustomNotification("TP LOW MAP", "v Teleportado bajo el mapa", 2)
        end

        local function _startFloat(character)
            if _st.floatConn then pcall(function() _st.floatConn:Disconnect() end); _st.floatConn = nil end
            local hrp = character and character:FindFirstChild("HumanoidRootPart")
            local hum = character and character:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then return end
            _st.floatConn = RunService.Heartbeat:Connect(function()
                if not _st.enabled then
                    pcall(function() _st.floatConn:Disconnect() end); _st.floatConn = nil
                    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true) end)
                    return
                end
                if not hrp.Parent then
                    pcall(function() _st.floatConn:Disconnect() end); _st.floatConn = nil; return
                end
                -- Mantener posicion bajo el mapa
                if hrp.Position.Y > LOW_Y + 3 then
                    pcall(function()
                        hrp.CFrame = CFrame.new(hrp.Position.X, LOW_Y, hrp.Position.Z)
                        hrp.AssemblyLinearVelocity = Vector3.zero
                    end)
                end
                if hum.Health < 1 then hum.Health = 1 end
                hum.PlatformStand = false
            end)
        end

        local function _tpLowSetup(character)
            _tpLowCleanup()
            if not character or not _st.enabled then return end
            local hum = character:WaitForChild("Humanoid", 5)
            local hrp = character:WaitForChild("HumanoidRootPart", 5)
            if not hum or not hrp then return end

            local _lastHit = 0
            _st.conn = hum.HealthChanged:Connect(function(hp)
                if not _st.enabled then return end
                if hp > 0 then return end
                local now = tick()
                if now - _lastHit < 0.2 then return end
                _lastHit = now
                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
                hum.Health = 1
                _doTP()
                _startFloat(character)
            end)
        end

        CreateAuroraToggle(leftColumn, "TP Low Map (teleportar bajo el mapa)", function(on)
            _st.enabled = on
            if on then
                -- TP INMEDIATO al activar
                _doTP()
                _startFloat(LocalPlayer.Character)
                _tpLowSetup(LocalPlayer.Character)
                if _st.charConn then pcall(function() _st.charConn:Disconnect() end) end
                _st.charConn = LocalPlayer.CharacterAdded:Connect(function(c)
                    task.wait(0.5)
                    if _st.enabled then
                        _doTP()
                        _startFloat(c)
                        _tpLowSetup(c)
                    end
                end)
                -- [notif removed]
            else
                _tpLowCleanup()
                if _st.charConn then pcall(function() _st.charConn:Disconnect() end); _st.charConn = nil end
                -- Volver al mapa si estamos abajo
                local char = LocalPlayer.Character
                local hrp2 = char and char:FindFirstChild("HumanoidRootPart")
                local hum2 = char and char:FindFirstChildOfClass("Humanoid")
                if hrp2 and hrp2.Position.Y < -100 then
                    if hum2 then
                        pcall(function() hum2:SetStateEnabled(Enum.HumanoidStateType.Dead, true) end)
                        hum2.PlatformStand = false
                    end
                    pcall(TeleportToMap)
                end
                -- [notif removed]
            end
        end, _st.enabled)  -- restaurar estado al re-crear la UI

        -- Bindable: boton flotante en pantalla para activar/desactivar
 CreateAuroraToggle(leftColumn, "TP Low Map Bindable", function(on)
            if _G._tpLowBindGui then
                pcall(function() _G._tpLowBindGui:Destroy() end); _G._tpLowBindGui = nil
            end
            for _, g in ipairs(game:GetService("CoreGui"):GetChildren()) do
                if g.Name == "TpLowMapBindable" then pcall(function() g:Destroy() end) end
            end
            DestroyCapyBind("TP LOW MAP")
            if on then
                local sg = Instance.new("ScreenGui")
                sg.Name = "TpLowMapBindable"; sg.ResetOnSpawn = false
                sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
                pcall(function() sg.Parent = game:GetService("CoreGui") end)
                if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
                _G._tpLowBindGui = sg
                MakeCapyBindableFrame(sg, "TP LOW MAP", function()
                    -- Toggle desde bindable
                    _tpLowEnabled = not _tpLowEnabled
                    if _tpLowEnabled then
                        _tpLowSetup(LocalPlayer.Character)
 -- [notif removed]
                    else
                        _tpLowCleanup()
                        local char2 = LocalPlayer.Character
                        local hrp3  = char2 and char2:FindFirstChild("HumanoidRootPart")
                        if hrp3 and hrp3.Position.Y < -100 then pcall(TeleportToMap) end
 -- [notif removed]
                    end
                end, 160, 430)
            end
        end, false)
    end

end


function CreateMainUI_InvisibleGhost()
    -- ==================================================================
    --  INVISIBILIDAD v7 -- Clone + Void (Fix Mapa + Inventario + Combate)
    --  Basado en el sistema de Gemini con fixes adicionales
    -- ==================================================================
    CreateSection(rightColumn, "", "INVISIBILIDAD", ThemeColors.Aurora3)

    local VOID_POS = Vector3.new(0, 50000, 0)
    local _inv = {
        enabled = false, realChar = nil, fakeChar = nil,
        platform = nil, mapSyncConn = nil, tempFolder = nil,
        charAddedConn = nil,
    }

    local function _invClean()
        if _inv.mapSyncConn then
            pcall(function() _inv.mapSyncConn:Disconnect() end)
            _inv.mapSyncConn = nil
        end
    end

    -- Restaurar inventario desde la carpeta temporal al backpack
    local function _restoreInventory(tf)
        if not tf then return end
        for _, t in pairs(tf:GetChildren()) do
            pcall(function() t.Parent = LocalPlayer.Backpack end)
        end
        pcall(function() tf:Destroy() end)
    end

    local function activar()
        local char = LocalPlayer.Character
        if not char or not char.Parent then
            CreateCustomNotification("INVIS", "Sin personaje", 2); return false
        end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then
            CreateCustomNotification("INVIS", "Sin HumanoidRootPart", 2); return false
        end

        _inv.realChar = char

        -- Carpeta temporal para el inventario en ReplicatedStorage
        local tf = Instance.new("Folder")
        tf.Name = "SafeInv_" .. LocalPlayer.Name
        tf.Parent = game:GetService("ReplicatedStorage")
        _inv.tempFolder = tf

        -- 1. Plataforma invisible en el void
        local plat = Instance.new("Part")
        plat.Size = Vector3.new(20, 1, 20)
        plat.CFrame = CFrame.new(VOID_POS - Vector3.new(0, 3, 0))
        plat.Anchored = true
        plat.Transparency = 1
        plat.CanCollide = true
        plat.Parent = workspace
        _inv.platform = plat

        -- 2. Guardar posicion actual (spawn del clon)
        local spawnCF = hrp.CFrame

        -- 3. Guardar herramientas al temp
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum:UnequipTools() end) end
        task.wait(0.1)
        for _, t in pairs(LocalPlayer.Backpack:GetChildren()) do
            pcall(function() t.Parent = tf end)
        end

        -- 4. Clonar personaje real
        char.Archivable = true
        local fake = char:Clone()
        fake.Name = LocalPlayer.Name .. "_Fake"
        fake.Parent = workspace
        _inv.fakeChar = fake

        -- 5. Mover personaje REAL al void con BodyVelocity
        pcall(function() hrp.CFrame = CFrame.new(VOID_POS) end)
        local bv = Instance.new("BodyVelocity")
        bv.Velocity = Vector3.zero
        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bv.Name = "InvisStayStill"
        bv.Parent = hrp

        -- 6. Asignar clon como personaje controlado
        LocalPlayer.Character = fake
        fake.HumanoidRootPart.CFrame = spawnCF
        workspace.CurrentCamera.CameraSubject = fake:FindFirstChild("Humanoid")

        -- 7. Restaurar inventario al backpack (para que el clon pueda usarlas)
        task.wait(0.016)
        for _, t in pairs(tf:GetChildren()) do
            pcall(function() t.Parent = LocalPlayer.Backpack end)
        end

        -- 8. TP de refuerzo del clon a posicion correcta
        task.spawn(function()
            task.wait(0)
            pcall(function() fake.HumanoidRootPart.CFrame = spawnCF end)
            task.wait(0.1)
            pcall(function() fake.HumanoidRootPart.CFrame = spawnCF end)
        end)

        -- 9. Re-activar animaciones del clon
        local anim = fake:FindFirstChild("Animate")
        if anim then
            anim.Disabled = true
            task.wait(0.016)
            anim.Disabled = false
        end

        -- 10. Sincronizacion de mapa
        _inv.mapSyncConn = hrp:GetPropertyChangedSignal("CFrame"):Connect(function()
            if not _inv.fakeChar or not _inv.realChar then return end
            local currentPos = hrp.Position
            if (currentPos - VOID_POS).Magnitude > 1000 then
                local newMapCF = hrp.CFrame
                pcall(function() _inv.fakeChar.HumanoidRootPart.CFrame = newMapCF end)
                task.wait(0.016)
                pcall(function() hrp.CFrame = CFrame.new(VOID_POS) end)
            end
        end)

        _inv.enabled = true
        CreateCustomNotification("INVIS ON", "Invisible -- clon activo en mapa", 3)
        return true
    end

    local function desactivar()
        _invClean()
        local real = _inv.realChar
        local fake = _inv.fakeChar
        if not real or not fake then
            _inv.enabled = false
            return
        end

        -- 1. Desconectar mapSyncConn para que no interfiera con el TP
        -- (ya hecho por _invClean arriba)

        -- 2. Obtener posicion final del clon ANTES de cualquier cambio
        local fakeHRP = fake:FindFirstChild("HumanoidRootPart")
        local finalCF = fakeHRP and fakeHRP.CFrame or CFrame.new(0, 5, 0)

        -- 3. Desquipar herramientas del clon
        local fHum = fake:FindFirstChildOfClass("Humanoid")
        if fHum then pcall(function() fHum:UnequipTools() end) end
        task.wait(0.016)

        -- 4. Guardar inventario del backpack (herramientas del clon) al temp
        local tf = _inv.tempFolder
        for _, t in pairs(LocalPlayer.Backpack:GetChildren()) do
            pcall(function() t.Parent = tf end)
        end

        -- 5. Destruir BodyVelocity del personaje REAL primero (para que pueda moverse)
        local hrp = real:FindFirstChild("HumanoidRootPart")
        if hrp then
            local bv = hrp:FindFirstChild("InvisStayStill")
            if bv then pcall(function() bv:Destroy() end) end
            -- Zerear velocidad para que no salga disparado del void
            pcall(function()
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end

        -- 6. Mover el personaje real a la posicion final ANTES de asignarlo
        -- Esto es critico: si asignamos primero y luego movemos, hay un frame donde cae del void
        if hrp then
            pcall(function() real:PivotTo(finalCF) end)
            pcall(function()
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end

        -- 7. Destruir plataforma del void
        if _inv.platform then
            pcall(function() _inv.platform:Destroy() end)
        end

        -- 8. Asignar el personaje real como controlable
        LocalPlayer.Character = real

        -- 9. TP de refuerzo triple para asegurar posicion (el Character= puede causar micro-lag)
        task.spawn(function()
            task.wait(0)
            if hrp and hrp.Parent then
                pcall(function() real:PivotTo(finalCF) end)
                pcall(function()
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            task.wait(0.016)
            if hrp and hrp.Parent then
                pcall(function() real:PivotTo(finalCF) end)
                pcall(function()
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            task.wait(0.1)
            if hrp and hrp.Parent then
                pcall(function() real:PivotTo(finalCF) end)
                pcall(function()
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end)
            end
        end)

        -- 10. Restaurar camara al personaje real
        workspace.CurrentCamera.CameraSubject = real:FindFirstChild("Humanoid")

        -- 11. Asegurar que el humanoid pueda caminar
        local rHum = real:FindFirstChildOfClass("Humanoid")
        if rHum then
            pcall(function()
                rHum.PlatformStand = false
                rHum:ChangeState(Enum.HumanoidStateType.Running)
            end)
        end

        -- 12. Restaurar inventario del temp al backpack del personaje real
        task.wait(0.1)
        _restoreInventory(tf)

        -- 13. Reiniciar scripts del cliente si existen
        if real:FindFirstChild("CharacterClient") then
            real.CharacterClient.Disabled = true
            task.wait(0.1)
            real.CharacterClient.Disabled = false
        end

        -- 14. Restaurar CoreGui
        pcall(function()
            game:GetService("StarterGui"):SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true)
        end)

        -- 15. Destruir clon
        task.wait(0.016)
        pcall(function() fake:Destroy() end)

        -- 16. Limpiar estado
        _inv.fakeChar   = nil
        _inv.realChar   = nil
        _inv.platform   = nil
        _inv.tempFolder = nil
        _inv.enabled    = false

        CreateCustomNotification("INVIS OFF", "Visible -- personaje real restaurado", 2)
    end

    -- Limpieza de seguridad si el personaje se resetea
    _inv.charAddedConn = LocalPlayer.CharacterAdded:Connect(function()
        _invClean()
        _inv.enabled   = false
        _inv.fakeChar  = nil
        _inv.realChar  = nil
        _inv.platform  = nil
        _inv.tempFolder = nil
    end)

    -- Toggle principal
    -- FIX: tabla para guardar las transparencias originales de cada parte
    local _invOrigTrans = {}

    -- FIX: funcion auxiliar para destruir TODAS las sillas invisibles (por si hay duplicadas)
    local function _destroyInvisChairs()
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "invischair" then pcall(function() obj:Destroy() end) end
        end
        -- busqueda profunda por si la silla quedo anidada en otro objeto
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj.Name == "invischair" then pcall(function() obj:Destroy() end) end
        end
    end

    CreateAuroraToggle(rightColumn, "Invisible", function(on)
        if on then
            -- Anti Fling inline
            local char = LocalPlayer.Character
            if not char then
                CreateCustomNotification("INVIS", "Sin personaje", 2)
                pcall(function() _G._toggleStates["Invisible"] = false end)
                return
            end
            local hum  = char:FindFirstChildOfClass("Humanoid")
            local hrp  = char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then
                CreateCustomNotification("INVIS", "Sin Humanoid/HRP", 2)
                pcall(function() _G._toggleStates["Invisible"] = false end)
                return
            end

            local savedpos = hrp.CFrame
            task.wait()
            pcall(function() char:MoveTo(Vector3.new(-25.95, 84, 3537.55)) end)
            task.wait(0.15)

            local Seat = Instance.new("Seat", workspace)
            Seat.Anchored = false
            Seat.CanCollide = false
            Seat.Name = "invischair"
            Seat.Transparency = 1
            Seat.Position = Vector3.new(-25.95, 84, 3537.55)
            local Weld = Instance.new("Weld", Seat)
            Weld.Part0 = Seat
            Weld.Part1 = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
            task.wait()
            pcall(function() Seat.CFrame = savedpos end)

            -- FIX: guardar transparencia original ANTES de modificar
            _invOrigTrans = {}
            for _, part in pairs(char:GetDescendants()) do
                if part:IsA("BasePart") or part:IsA("Decal") then
                    _invOrigTrans[part] = part.Transparency
                    pcall(function() part.Transparency = 0.5 end)
                end
            end

            CreateCustomNotification("INVIS ON", "Invisible activo", 3)
        else
            -- FIX: destruir TODAS las sillas invisibles (no solo la primera encontrada)
            _destroyInvisChairs()

            -- FIX: restaurar transparencia original guardada; si no hay registro usar 0
            local char = LocalPlayer.Character
            if char then
                for _, part in pairs(char:GetDescendants()) do
                    if part:IsA("BasePart") or part:IsA("Decal") then
                        local orig = _invOrigTrans[part]
                        pcall(function() part.Transparency = orig ~= nil and orig or 0 end)
                    end
                end
            end
            _invOrigTrans = {}

            CreateCustomNotification("INVIS OFF", "Visible", 2)
        end
    end, false)

    -- Bindable button para Invisible
    do
        local _invBind = _G._newInvisBind or { enabled = false, gui = nil }
        _G._newInvisBind = _invBind
        CreateAuroraToggle(rightColumn, "Invisible (Bindable)", function(on)
            _invBind.enabled = on
            if _invBind.gui then pcall(function() _invBind.gui:Destroy() end); _invBind.gui = nil end
            if on then
                local gui = Instance.new("ScreenGui")
                gui.Name = "NewInvisBind"; gui.ResetOnSpawn = false
                gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                gui.IgnoreGuiInset = true; gui.DisplayOrder = 9900
                pcall(function() gui.Parent = game:GetService("CoreGui") end)
                if not gui.Parent then gui.Parent = LocalPlayer.PlayerGui end
                _invBind.gui = gui
                MakeCapyBindableFrame(gui, "INVIS", function()
                    local cur = _G._toggleStates and _G._toggleStates["Invisible"]
                    local newVal = not cur
                    if _G._toggleStates then _G._toggleStates["Invisible"] = newVal end
                    -- Disparar el toggle manualmente
                    local char = LocalPlayer.Character
                    if newVal then
                        if char then
                            local hum = char:FindFirstChildOfClass("Humanoid")
                            local hrp = char:FindFirstChild("HumanoidRootPart")
                            if hum and hrp then
                                local savedpos = hrp.CFrame
                                task.wait()
                                pcall(function() char:MoveTo(Vector3.new(-25.95, 84, 3537.55)) end)
                                task.wait(0.15)
                                local Seat = Instance.new("Seat", workspace)
                                Seat.Anchored = false; Seat.CanCollide = false
                                Seat.Name = "invischair"; Seat.Transparency = 1
                                Seat.Position = Vector3.new(-25.95, 84, 3537.55)
                                local Weld = Instance.new("Weld", Seat)
                                Weld.Part0 = Seat
                                Weld.Part1 = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
                                task.wait()
                                pcall(function() Seat.CFrame = savedpos end)
                                -- FIX: guardar originales y aplicar transparencia
                                _invOrigTrans = {}
                                for _, part in pairs(char:GetDescendants()) do
                                    if part:IsA("BasePart") or part:IsA("Decal") then
                                        _invOrigTrans[part] = part.Transparency
                                        pcall(function() part.Transparency = 0.5 end)
                                    end
                                end
                                CreateCustomNotification("INVIS ON", "Invisible activo", 3)
                            end
                        end
                    else
                        -- FIX: destruir TODAS las sillas y restaurar originales
                        _destroyInvisChairs()
                        if char then
                            for _, part in pairs(char:GetDescendants()) do
                                if part:IsA("BasePart") or part:IsA("Decal") then
                                    local orig = _invOrigTrans[part]
                                    pcall(function() part.Transparency = orig ~= nil and orig or 0 end)
                                end
                            end
                        end
                        _invOrigTrans = {}
                        CreateCustomNotification("INVIS OFF", "Visible", 2)
                    end
                end, 20, 320)
                CreateCustomNotification("INVIS BIND", "Bindable activo", 2)
            else
                CreateCustomNotification("INVIS BIND", "Bindable removido", 2)
            end
        end, _invBind.enabled)
    end
end
_gameInfoState = {
    timerEnabled   = false,
    timerConn      = nil,
    timerGui       = nil,
    rolEnabled     = false,
    rolConn        = nil,
    rolGui         = nil,
    pctEnabled     = false,
    pctConn        = nil,
    pctGui         = nil,
}

-- Tabla de posiciones Y relativas por nombre de overlay (centrado en pantalla)
-- Layout vertical centrado:
--   Timer  -> 0.33 (arriba, un poco separado)
--   ROL    -> 0.50 (centro exacto, manejado por NotifyRol aparte)
--   Pct    -> 0.58 (justo debajo del ROL)
local _overlayYScale = {
    Timer = 0.33,
    Pct   = 0.58,
}

function _createOverlayLabel(name, posY, textSize, font)
    -- ==============================================================
    -- OVERLAY FLOTANTE ANIMADO v3 - CENTRADO EN PANTALLA
    -- Aparece desde arriba (slide-down) con fade-in suave.
    -- Pill semi-transparente centrada horizontalmente.
    -- posY ignorado: se usa _overlayYScale[name] para posicion relativa.
    -- ==============================================================
    local pg = LocalPlayer:WaitForChild("PlayerGui")
    local sg = Instance.new("ScreenGui")
    sg.Name            = "BYPAS_" .. name
    sg.ResetOnSpawn    = false
    sg.DisplayOrder    = 9900
    sg.IgnoreGuiInset  = true
    sg.ZIndexBehavior  = Enum.ZIndexBehavior.Global
    pcall(function() sg.Parent = game:GetService("CoreGui") end)
    if not sg.Parent then sg.Parent = pg end

    local yScale    = _overlayYScale[name] or 0.50
    local pillH     = textSize + 18
    local pillW     = name == "Timer" and 200 or 180

    -- Pill centrada horizontalmente, completamente sin fondo (solo texto flotante)
    local pill = Instance.new("Frame", sg)
    pill.Name                   = "Pill"
    pill.Size                   = UDim2.new(0, pillW, 0, pillH)
    pill.AnchorPoint            = Vector2.new(0.5, 0.5)
    pill.Position               = UDim2.new(0.5, 0, yScale, -30)  -- empieza 30px arriba
    pill.BackgroundTransparency = 1   -- sin fondo: completamente transparente
    pill.BorderSizePixel        = 0
    pill.ZIndex                 = 99
    Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 12)

    -- Sin borde: elemento completamente flotante
    local stroke = Instance.new("UIStroke", pill)
    stroke.Color           = Color3.fromRGB(0, 210, 255)
    stroke.Thickness       = 0
    stroke.Transparency    = 1.0   -- invisible siempre
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Label de texto centrado dentro del pill
    local lbl = Instance.new("TextLabel", pill)
    lbl.Name                   = "Display"
    lbl.Size                   = UDim2.new(1, 0, 1, 0)
    lbl.Position               = UDim2.new(0, 0, 0, 0)
    lbl.AnchorPoint            = Vector2.new(0, 0)
    lbl.BackgroundTransparency = 1
    lbl.Text                   = ""
    lbl.Font                   = font or Enum.Font.GothamBold
    lbl.TextSize               = textSize
    lbl.TextColor3             = Color3.fromRGB(255, 255, 255)
    lbl.TextTransparency       = 1   -- empieza invisible (fade-in)
    lbl.TextStrokeTransparency = 0.20
    lbl.TextStrokeColor3       = Color3.fromRGB(0, 0, 0)
    lbl.TextXAlignment         = Enum.TextXAlignment.Center
    lbl.TextYAlignment         = Enum.TextYAlignment.Center
    lbl.ZIndex                 = 100

    -- Animacion de entrada: slide-down desde arriba + fade-in (solo texto, sin fondo)
    local _ts = TweenService or game:GetService("TweenService")
    local targetPos = UDim2.new(0.5, 0, yScale, 0)

    task.spawn(function()
        task.wait(0.05)
        -- Slide-down del pill (sin cambiar transparencia de fondo: se mantiene en 1)
        _ts:Create(pill, TweenInfo.new(0.40, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
            Position = targetPos,
        }):Play()
        -- Fade-in del texto
        task.wait(0.12)
        _ts:Create(lbl, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            TextTransparency = 0,
        }):Play()
    end)

    return sg, lbl
end

function CreateMainUI_GameInfo()
    -- ================================================================
    -- PANEL CENTRAL: Timer Round / Mi Rol / Porcentaje
    -- Se muestra grande y centrado en el tab Main, responsive mobile
    -- ================================================================
    do
        local _isMobile = _G._isMobileHub or false

        -- Limpiar panel previo si existe (re-open tab)
        local _cpWrapper = contentContainer:FindFirstChild("TwoColumnWrapper") or contentContainer
        local _prevPanel = _cpWrapper:FindFirstChild("MainCenterPanel")
        if _prevPanel then _prevPanel:Destroy() end
        -- Limpiar ScreenGui flotante anterior
        pcall(function()
            local cg = game:GetService("CoreGui")
            local prev = cg:FindFirstChild("BYPAS_MainCenterPanel")
                      or LocalPlayer.PlayerGui:FindFirstChild("BYPAS_MainCenterPanel")
            if prev then prev:Destroy() end
        end)

        -- ScreenGui flotante: panel fijo en la parte SUPERIOR de la pantalla
        local _cpSg = Instance.new("ScreenGui")
        _cpSg.Name = "BYPAS_MainCenterPanel"
        _cpSg.ResetOnSpawn = false
        _cpSg.IgnoreGuiInset = true
        _cpSg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        _cpSg.DisplayOrder = 8500
        _cpSg.Enabled = false  -- Panel superior oculto; los toggles muestran overlays flotantes propios
        pcall(function() _cpSg.Parent = game:GetService("CoreGui") end)
        if not _cpSg.Parent then _cpSg.Parent = LocalPlayer.PlayerGui end

        local _cpanel = Instance.new("Frame", _cpSg)
        _cpanel.Name = "MainCenterPanel"
        -- Centrado horizontalmente, fijo 6px desde el borde superior de la pantalla
        _cpanel.AnchorPoint = Vector2.new(0.5, 0)
        _cpanel.Position = UDim2.new(0.5, 0, 0, 6)
        _cpanel.BackgroundColor3 = Color3.fromRGB(5, 14, 30)
        _cpanel.BackgroundTransparency = 1   -- sin fondo: flota sobre el juego
        _cpanel.BorderSizePixel = 0
        _cpanel.ZIndex = 60

        -- Destruir el ScreenGui cuando el tab cambie o el hub se cierre
        if contentContainer then
            contentContainer.AncestryChanged:Connect(function(_, newParent)
                if not newParent then
                    pcall(function() _cpSg:Destroy() end)
                end
            end)
        end
        Instance.new("UICorner", _cpanel).CornerRadius = UDim.new(0, 14)

        local _cpStroke = Instance.new("UIStroke", _cpanel)
        _cpStroke.Color = Color3.fromRGB(210, 85, 100)
        _cpStroke.Thickness = 0          -- sin borde
        _cpStroke.Transparency = 1.0     -- completamente invisible
        _cpStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        -- Sin gradiente: fondo limpio
        local _cpGrad = Instance.new("UIGradient", _cpanel)
        _cpGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
        })
        _cpGrad.Rotation = 90

        -- Layout: mobile = columna vertical, PC = fila horizontal
        if _isMobile then
            -- MOBILE: 3 filas apiladas, bien separadas
            _cpanel.Size = UDim2.new(0.92, 0, 0, 96)

            local _layout = Instance.new("UIListLayout", _cpanel)
            _layout.FillDirection = Enum.FillDirection.Vertical
            _layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
            _layout.VerticalAlignment = Enum.VerticalAlignment.Center
            _layout.Padding = UDim.new(0, 2)
            _layout.SortOrder = Enum.SortOrder.LayoutOrder

            local _pad = Instance.new("UIPadding", _cpanel)
            _pad.PaddingLeft   = UDim.new(0, 10)
            _pad.PaddingRight  = UDim.new(0, 10)
            _pad.PaddingTop    = UDim.new(0, 6)
            _pad.PaddingBottom = UDim.new(0, 6)

            -- Fila 1: Timer
            local _timerBlock = Instance.new("Frame", _cpanel)
            _timerBlock.Name = "TimerBlock"
            _timerBlock.Size = UDim2.new(1, 0, 0, 32)
            _timerBlock.BackgroundTransparency = 1
            _timerBlock.LayoutOrder = 1

            local _timerCaption = Instance.new("TextLabel", _timerBlock)
            _timerCaption.Size = UDim2.new(0.42, 0, 1, 0)
            _timerCaption.Position = UDim2.new(0, 0, 0, 0)
            _timerCaption.BackgroundTransparency = 1
            _timerCaption.Text = "TIMER"
            _timerCaption.Font = Enum.Font.GothamBold
            _timerCaption.TextSize = 11
            _timerCaption.TextColor3 = Color3.fromRGB(0, 180, 240)
            _timerCaption.TextXAlignment = Enum.TextXAlignment.Left
            _timerCaption.ZIndex = 61

            local _timerVal = Instance.new("TextLabel", _timerBlock)
            _timerVal.Name = "CPTimerVal"
            _timerVal.Size = UDim2.new(0.58, 0, 1, 0)
            _timerVal.Position = UDim2.new(0.42, 0, 0, 0)
            _timerVal.BackgroundTransparency = 1
            _timerVal.Text = "--:--"
            _timerVal.Font = Enum.Font.GothamBold
            _timerVal.TextSize = 22
            _timerVal.TextColor3 = Color3.fromRGB(255, 255, 255)
            _timerVal.TextXAlignment = Enum.TextXAlignment.Right
            _timerVal.ZIndex = 61

            -- Fila 2: Rol
            local _rolBlock = Instance.new("Frame", _cpanel)
            _rolBlock.Name = "RolBlock"
            _rolBlock.Size = UDim2.new(1, 0, 0, 32)
            _rolBlock.BackgroundTransparency = 1
            _rolBlock.LayoutOrder = 2

            local _rolCaption = Instance.new("TextLabel", _rolBlock)
            _rolCaption.Size = UDim2.new(0.42, 0, 1, 0)
            _rolCaption.Position = UDim2.new(0, 0, 0, 0)
            _rolCaption.BackgroundTransparency = 1
            _rolCaption.Text = "MI ROL"
            _rolCaption.Font = Enum.Font.GothamBold
            _rolCaption.TextSize = 11
            _rolCaption.TextColor3 = Color3.fromRGB(0, 180, 240)
            _rolCaption.TextXAlignment = Enum.TextXAlignment.Left
            _rolCaption.ZIndex = 61

            local _rolVal = Instance.new("TextLabel", _rolBlock)
            _rolVal.Name = "CPRolVal"
            _rolVal.Size = UDim2.new(0.58, 0, 1, 0)
            _rolVal.Position = UDim2.new(0.42, 0, 0, 0)
            _rolVal.BackgroundTransparency = 1
            _rolVal.Text = "..."
            _rolVal.Font = Enum.Font.GothamBold
            _rolVal.TextSize = 18
            _rolVal.TextColor3 = Color3.fromRGB(0, 255, 160)
            _rolVal.TextXAlignment = Enum.TextXAlignment.Right
            _rolVal.ZIndex = 61

            -- Fila 3: Porcentaje
            local _pctBlock = Instance.new("Frame", _cpanel)
            _pctBlock.Name = "PctBlock"
            _pctBlock.Size = UDim2.new(1, 0, 0, 32)
            _pctBlock.BackgroundTransparency = 1
            _pctBlock.LayoutOrder = 3

            local _pctCaption = Instance.new("TextLabel", _pctBlock)
            _pctCaption.Size = UDim2.new(0.5, 0, 1, 0)
            _pctCaption.Position = UDim2.new(0, 0, 0, 0)
            _pctCaption.BackgroundTransparency = 1
            _pctCaption.Text = "MURDER%"
            _pctCaption.Font = Enum.Font.GothamBold
            _pctCaption.TextSize = 11
            _pctCaption.TextColor3 = Color3.fromRGB(0, 180, 240)
            _pctCaption.TextXAlignment = Enum.TextXAlignment.Left
