            local _pctVal = Instance.new("TextLabel", _pctBlock)
            _pctVal.Name = "CPPctVal"
            _pctVal.Size = UDim2.new(0.5, 0, 1, 0)
            _pctVal.Position = UDim2.new(0.5, 0, 0, 0)
            _pctVal.BackgroundTransparency = 1
            _pctVal.Text = "...%"
            _pctVal.Font = Enum.Font.GothamBold
            _pctVal.TextSize = 18
            _pctVal.TextColor3 = Color3.fromRGB(255, 200, 60)
            _pctVal.TextXAlignment = Enum.TextXAlignment.Right
            _pctVal.ZIndex = 61

            -- Guardar referencias globales para actualizar desde los toggles
            _G._cpTimerVal = _timerVal
            _G._cpRolVal   = _rolVal
            _G._cpPctVal   = _pctVal

        else
            -- PC: 3 bloques en fila horizontal, bien centrados
            _cpanel.Size = UDim2.new(0.88, 0, 0, 58)

            local _layout = Instance.new("UIListLayout", _cpanel)
            _layout.FillDirection = Enum.FillDirection.Horizontal
            _layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
            _layout.VerticalAlignment = Enum.VerticalAlignment.Center
            _layout.Padding = UDim.new(0, 0)
            _layout.SortOrder = Enum.SortOrder.LayoutOrder

            local function _makeBlock(parent, caption, defaultVal, defaultColor, order)
                local blk = Instance.new("Frame", parent)
                blk.Name = caption .. "Block"
                blk.Size = UDim2.new(0.333, 0, 1, 0)
                blk.BackgroundTransparency = 1
                blk.LayoutOrder = order

                -- Separador vertical entre bloques (excepto el primero)
                if order > 1 then
                    local sep = Instance.new("Frame", blk)
                    sep.Size = UDim2.new(0, 1, 0.6, 0)
                    sep.Position = UDim2.new(0, 0, 0.2, 0)
                    sep.BackgroundColor3 = Color3.fromRGB(210, 85, 100)
                    sep.BackgroundTransparency = 0.7
                    sep.BorderSizePixel = 0
                    sep.ZIndex = 61
                end

                local cap = Instance.new("TextLabel", blk)
                cap.Size = UDim2.new(1, 0, 0, 20)
                cap.Position = UDim2.new(0, 0, 0, 4)
                cap.BackgroundTransparency = 1
                cap.Text = caption
                cap.Font = Enum.Font.GothamBold
                cap.TextSize = 10
                cap.TextColor3 = Color3.fromRGB(0, 180, 240)
                cap.TextXAlignment = Enum.TextXAlignment.Center
                cap.ZIndex = 61

                local val = Instance.new("TextLabel", blk)
                val.Name = "CP" .. caption .. "Val"
                val.Size = UDim2.new(1, 0, 0, 30)
                val.Position = UDim2.new(0, 0, 0, 18)
                val.BackgroundTransparency = 1
                val.Text = defaultVal
                val.Font = Enum.Font.GothamBold
                val.TextSize = 20
                val.TextColor3 = defaultColor
                val.TextXAlignment = Enum.TextXAlignment.Center
                val.ZIndex = 61
                -- Stroke de texto para legibilidad
                local vs = Instance.new("UIStroke", val)
                vs.Color = Color3.fromRGB(0, 0, 0)
                vs.Thickness = 1.2
                vs.Transparency = 0.5

                return val
            end

            local _timerVal = _makeBlock(_cpanel, "TIMER",   "--:--", Color3.fromRGB(255, 255, 255), 1)
            local _rolVal   = _makeBlock(_cpanel, "MI ROL",  "...",   Color3.fromRGB(0, 255, 160),   2)
            local _pctVal   = _makeBlock(_cpanel, "MURDER%", "...%",  Color3.fromRGB(255, 200, 60),  3)

            _G._cpTimerVal = _timerVal
            _G._cpRolVal   = _rolVal
            _G._cpPctVal   = _pctVal
        end

        -- Loop de actualizaci?n en tiempo real (lee del cache, no necesita toggles activos)
        local _cpConn = nil
        local _cpLastSecs = -1
        local _cpLastRole = ""
        local _cpLastPct  = ""
        local _cpTick = 0

        local _roleColors = {
            Murderer = Color3.fromRGB(255, 50,  50),
            Sheriff  = Color3.fromRGB(80,  160, 255),
            Hero     = Color3.fromRGB(255, 220,  0),
            Zombie   = Color3.fromRGB(40,  255,  40),
            Survivor = Color3.fromRGB(200, 200, 200),
            Freezer  = Color3.fromRGB(180, 220, 255),
            Runner   = Color3.fromRGB(255, 150,  60),
            Assassin = Color3.fromRGB(255, 140,   0),
            Innocent = Color3.fromRGB(0,   255, 160),
        }
        local function _timerColor(s)
            if s > 60 then return Color3.fromRGB(0, 230, 100)
            elseif s > 30 then return Color3.fromRGB(255, 220, 0)
            else return Color3.fromRGB(255, 60, 60) end
        end
        local function _fmt(s)
            return string.format("%d:%02d", math.floor(s/60), s%60)
        end

        _cpConn = RunService.Heartbeat:Connect(function()
            if not (_cpanel and _cpanel.Parent) then
                _cpConn:Disconnect(); return
            end
            -- Panel is hidden (Enabled=false); skip all work
            local _cpSgRef = _cpanel.Parent  -- _cpanel es hijo directo del ScreenGui
            if _cpSgRef and _cpSgRef:IsA("ScreenGui") and not _cpSgRef.Enabled then return end
            _cpTick = _cpTick + 1
            if _cpTick < 6 then return end  -- ~10Hz
            _cpTick = 0

            -- Timer: leer del estado global de gameInfo
            local tv = _G._cpTimerVal
            if tv and tv.Parent then
                local T = _gameInfoState and _gameInfoState._timerState
                local secs = 0
                local active = false
                if T and T.active and T.value then
                    secs = math.max(0, math.floor(T.value - (tick() - (T.syncTick or tick()))))
                    active = true
                end
                local newSecs = active and secs or -1
                if newSecs ~= _cpLastSecs then
                    _cpLastSecs = newSecs
                    if active and secs > 0 then
                        tv.Text = _fmt(secs)
                        tv.TextColor3 = _timerColor(secs)
                    else
                        -- Fallback: leer el display del overlay si existe
                        local ovGui = LocalPlayer.PlayerGui:FindFirstChild("BYPAS_Timer")
                                   or (game:GetService("CoreGui"):FindFirstChild("BYPAS_Timer"))
                        local ovLbl = ovGui and ovGui:FindFirstChild("Display")
                        if ovLbl and ovLbl.Text ~= "" and ovLbl.Text ~= "--:--" then
                            tv.Text = ovLbl.Text
                            tv.TextColor3 = ovLbl.TextColor3
                        else
                            tv.Text = "--:--"
                            tv.TextColor3 = Color3.fromRGB(130, 130, 130)
                        end
                    end
                end
            end

            -- Rol: leer del roleCache
            local rv = _G._cpRolVal
            if rv and rv.Parent then
                local role = (_roleCache and _roleCache.localRole) or "..."
                if role ~= _cpLastRole then
                    _cpLastRole = role
                    rv.Text = role:upper()
                    rv.TextColor3 = _roleColors[role] or Color3.fromRGB(200, 200, 200)
                end
            end

            -- Porcentaje: leer del overlay o del estado
            local pv = _G._cpPctVal
            if pv and pv.Parent then
                local pctOvGui = LocalPlayer.PlayerGui:FindFirstChild("BYPAS_Pct")
                              or (game:GetService("CoreGui"):FindFirstChild("BYPAS_Pct"))
                local pctLbl = pctOvGui and pctOvGui:FindFirstChild("Display")
                local rawPct = (pctLbl and pctLbl.Text) or (lastPct and ("MURDER% " .. lastPct .. "%")) or "...%"
                -- Extraer solo el n?mero/porcentaje
                local numStr = rawPct:match("(%d+%.?%d*)%%") or rawPct:match("(%d+%.?%d*)")
                local displayTxt = numStr and (numStr .. "%") or "...%"
                if displayTxt ~= _cpLastPct then
                    _cpLastPct = displayTxt
                    pv.Text = displayTxt
                    local n = tonumber(numStr)
                    if n then
                        if n >= 50 then pv.TextColor3 = Color3.fromRGB(255, 60, 60)
                        elseif n >= 25 then pv.TextColor3 = Color3.fromRGB(255, 200, 60)
                        else pv.TextColor3 = Color3.fromRGB(0, 220, 100) end
                    else
                        pv.TextColor3 = Color3.fromRGB(200, 200, 200)
                    end
                end
            end
        end)
    end

 CreateSection(leftColumn, "", "GAME INFO", Color3.fromRGB(129, 129, 129))

 CreateToggle(leftColumn, "TIMER (sincronizado con el juego)", function(on)
        _gameInfoState.timerEnabled = on

        if _gameInfoState.timerConn then
            _gameInfoState.timerConn:Disconnect()
            _gameInfoState.timerConn = nil
        end
        if _gameInfoState.timerGui then
            _gameInfoState.timerGui:Destroy()
            _gameInfoState.timerGui = nil
        end

        if not on then return end

        -- BUGFIX: Limpiar localRole stale -- NO tocar lastUpdate para no forzar
        -- un _refreshRoleCache que piisaria murderer/sheriff del RoundStart
        _roleCache.localRole = _roleCache.localRole or "Innocent"
        task.defer(function()
            if not _roleCache.localRole or _roleCache.localRole == "" then
                _roleCache.localRole = "Innocent"
            end
        end)

        local sg, lbl = _createOverlayLabel("Timer", 8, 26, Enum.Font.GothamBold)
        _gameInfoState.timerGui = sg

        -- -- Estado del timer: tabla local unica --------------------------
        local T = {
            value    = 0,      -- segundos recibidos del servidor
            syncTick = tick(), -- tick() cuando se recibio value
            active   = false,  -- hay un valor valido
            frozen   = false,  -- congelado (murder muerto / ronda termino)
            frozenAt = 0,      -- segundos al momento de congelar
            lastSecs = -1,     -- ultimo segundo mostrado (evita redibujar sin cambio)
        }
        _gameInfoState._timerState = T  -- exponer para panel central

        local function _fmt(s) return string.format("%d:%02d", math.floor(s/60), s % 60) end
        local function _color(s)
            if s > 120 then return Color3.fromRGB(236, 140, 32)
            elseif s > 60 then return Color3.fromRGB(255, 180, 30)
            else return Color3.fromRGB(255, 60, 60) end
        end

        -- -- Connections (limpieza al desactivar) -------------------------
        local _conns = {}
        local function _addConn(c) _conns[#_conns+1] = c end
        local function _disconnectAll()
            for _, c in ipairs(_conns) do pcall(function() c:Disconnect() end) end
            _conns = {}
        end

        -- -- Adjuntar al RoundTimerPart -----------------------------------
        local function _attachToTimerPart(tp)
            if not tp or not tp.Parent then return end

            -- Leer valor inicial sin esperar al primer evento
            local initV = tp:GetAttribute("Time")
            if type(initV) == "number" and initV > 0 and initV <= 600 then
                T.value = initV; T.syncTick = tick(); T.active = true
                -- Ocultar NotifyRol: el timer ya esta corriendo
                _G._roundTimerRunning = true
                pcall(function()
                    local cg = game:GetService("CoreGui")
                    local sg2 = cg:FindFirstChild("BYPAS_NotifyRol")
                             or LocalPlayer.PlayerGui:FindFirstChild("BYPAS_NotifyRol")
                    if sg2 then
                        local lbl2 = sg2:FindFirstChildOfClass("TextLabel")
                        if lbl2 then lbl2.Text = "" end
                    end
                end)
            end

            -- AttributeChanged: fuente primaria, 0 lag
            _addConn(tp.AttributeChanged:Connect(function(attr)
                if attr ~= "Time" then return end
                local v = tp:GetAttribute("Time")
                if type(v) == "number" then
                    if v > 0 and v <= 600 then
                        T.value    = v
                        T.syncTick = tick()
                        T.active   = true
                        T.frozen   = false  -- tick nuevo = ronda activa
                        -- Ocultar NotifyRol mientras el timer de ronda corre
                        if not _G._roundTimerRunning then
                            _G._roundTimerRunning = true
                            pcall(function()
                                local cg = game:GetService("CoreGui")
                                local sg2 = cg:FindFirstChild("BYPAS_NotifyRol")
                                         or LocalPlayer.PlayerGui:FindFirstChild("BYPAS_NotifyRol")
                                if sg2 then
                                    local lbl2 = sg2:FindFirstChildOfClass("TextLabel")
                                    if lbl2 then lbl2.Text = "" end
                                end
                            end)
                        end
                    elseif v <= 0 and T.active then
                        -- Llego 0 -> ronda termino
                        T.frozen   = true
                        T.frozenAt = 0
                        T.active   = false
                        lbl.Text       = "FIN"
                        lbl.TextColor3 = Color3.fromRGB(58, 58, 58)
                        -- Habilitar NotifyRol de nuevo (ronda terminada)
                        _G._roundTimerRunning = false
                        if _nrLastRole then _nrLastRole = "" end  -- forzar refresh en proxima deteccion
                        -- FIX SHERIFF VIEJO: limpiar roles al terminar el timer,
                        -- igual que hace el remote RoundEnd. Sin esto el StealGun
                        -- sigue viendo _roleCache.sheriff de la ronda anterior.
                        _G._visualRoundOver = true
                        _G._betweenRounds   = true
                        _G._sgRoundToken    = (_G._sgRoundToken or 0) + 1
                        _roleCache.murderer  = nil
                        _roleCache.sheriff   = nil
                        _roleCache.hero      = nil
                        -- FIX ROLES: limpiar roles secundarios
                        _roleCache.assassin  = nil
                        _roleCache.zombie    = nil
                        _roleCache.survivor  = nil
                        _roleCache.localRole = "Innocent"
                        _roleCache.lastUpdate = 0
                        if _G._deadRoles      then for k in next, _G._deadRoles      do _G._deadRoles[k]      = nil end end
                        if _G._deadSheriffIds then for k in next, _G._deadSheriffIds do _G._deadSheriffIds[k] = nil end end
                        _G._forceInstanceTick = true
                        -- Limpiar visuals
                        task.defer(function()
                            if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
                            _deadBodies = {}
                            -- Limpiar chams/outlines de todos los jugadores
                            for _, p in ipairs(_cachedPlayers) do
                                if p ~= LocalPlayer then
                                    pcall(removeCham,    p)
                                    pcall(removeOutline, p)
                                    pcall(removeBox,     p)
                                end
                            end
                        end)
                    end
                end
            end))

            -- SurfaceGui TextLabel: fallback si el atributo no funciona
            local sg2 = tp:FindFirstChild("SurfaceGui")
            local tl  = sg2 and sg2:FindFirstChild("Timer")
            if tl then
                _addConn(tl:GetPropertyChangedSignal("Text"):Connect(function()
                    if T.active then return end  -- atributo ya esta activo, ignorar
                    local m, s = tl.Text:match("^(%d+):(%d+)$")
                    if m then
                        local v2 = tonumber(m)*60 + tonumber(s)
                        if v2 > 0 and v2 <= 600 then
                            T.value = v2; T.syncTick = tick(); T.active = true
                        end
                    end
                end))
            end
        end

        -- Buscar RoundTimerPart ahora, o esperar a que aparezca
        local tp0 = workspace:FindFirstChild("RoundTimerPart")
        if tp0 then
            _attachToTimerPart(tp0)
        else
            _addConn(workspace.ChildAdded:Connect(function(child)
                if child.Name == "RoundTimerPart" then
                    _attachToTimerPart(child)
                end
            end))
        end

        -- -- Remotes Gameplay: RoundStart + RoundEnd ----------------------
        task.spawn(function()
            local RS = game:GetService("ReplicatedStorage")
            local ok, gameplay = pcall(function()
                return RS:WaitForChild("Remotes", 10):WaitForChild("Gameplay", 10)
            end)
            if not ok or not gameplay then return end

            local rsEv = gameplay:FindFirstChild("RoundStart")
            if rsEv then
                _addConn(rsEv.OnClientEvent:Connect(function()
                    -- Nueva ronda: descongelar y re-adjuntar
                    T.frozen = false; T.frozenAt = 0; T.active = false
                    -- Permitir NotifyRol durante asignacion de roles (timer aun no corre)
                    _G._roundTimerRunning = false
                    if _nrLastRole then _nrLastRole = "" end  -- forzar refresh del rol
                    task.wait(0.3)
                    local tp = workspace:FindFirstChild("RoundTimerPart")
                    if tp then _attachToTimerPart(tp) end
                    -- Re-hookear murderer (se asignan roles ~1s despues)
                    task.delay(1.2, function()
                        local murder = findMurderer()
                        if murder then _hookMurderer(murder) end
                    end)
                end))
            end

            local reEv = gameplay:FindFirstChild("RoundEnd")
            if reEv then
                _addConn(reEv.OnClientEvent:Connect(function()
                    T.frozen = true; T.frozenAt = 0; T.active = false
                    lbl.Text       = "FIN"
                    lbl.TextColor3 = Color3.fromRGB(58, 58, 58)
                    -- Habilitar NotifyRol de nuevo (RoundEnd recibido)
                    _G._roundTimerRunning = false
                    if _nrLastRole then _nrLastRole = "" end  -- forzar refresh en proxima deteccion
                    -- FIX: limpiar roles y visuals desde el timer local tambien
                    -- (el handler global de RoundEnd puede llegar con delay en lag)
                    _G._visualRoundOver = true
                    _G._betweenRounds   = true
                    _G._sgRoundToken    = (_G._sgRoundToken or 0) + 1
                    _roleCache.murderer  = nil
                    _roleCache.sheriff   = nil
                    _roleCache.hero      = nil
                    -- FIX ROLES: limpiar roles secundarios
                    _roleCache.assassin  = nil
                    _roleCache.zombie    = nil
                    _roleCache.survivor  = nil
                    _roleCache.localRole = "Innocent"
                    _roleCache.lastUpdate = 0
                    if _G._deadRoles      then for k in next, _G._deadRoles      do _G._deadRoles[k]      = nil end end
                    if _G._deadSheriffIds then for k in next, _G._deadSheriffIds do _G._deadSheriffIds[k] = nil end end
                    _G._forceInstanceTick = true
                    task.defer(function()
                        if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
                        _deadBodies = {}
                        for _, p in ipairs(_cachedPlayers) do
                            if p ~= LocalPlayer then
                                pcall(removeCham,    p)
                                pcall(removeOutline, p)
                                pcall(removeBox,     p)
                            end
                        end
                    end)
                end))
            end
        end)

        -- -- Murder death: hook Humanoid.Died directo (0 polling) ---------
        function _hookMurderer(murder)
            if not murder or not murder.Character then return end
            local mHum = murder.Character:FindFirstChildOfClass("Humanoid")
            if not mHum or mHum.Health <= 0 then return end
            _addConn(mHum.Died:Connect(function()
                if T.frozen then return end
                local elapsed = tick() - T.syncTick
                T.frozen   = true
                T.frozenAt = math.max(0, math.floor(T.value - elapsed))
                lbl.Text       = " " .. _fmt(T.frozenAt)
                lbl.TextColor3 = Color3.fromRGB(255, 171, 41)
                -- Murderer muerto: limpiar Dead Cham
                task.defer(function()
                    if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
                    _deadBodies = {}
                end)
            end))
        end
        task.spawn(function()
            task.wait(1)
            local murder = findMurderer()
            if murder then _hookMurderer(murder) end
        end)

        -- -- Display loop: Heartbeat, redibuja solo cuando cambia el segundo o el rol
        -- -- Display loop: Heartbeat, redibuja solo cuando cambia el segundo
        -- FIX: solo muestra el TIEMPO (sin rol) en el overlay principal
        local _hbTimerTick = 0
        local _hbConn = RunService.Heartbeat:Connect(function()
            if not lbl or not lbl.Parent then _hbConn:Disconnect(); return end
            -- Throttle: timer updates every second, no need to run 60fps
            _hbTimerTick = _hbTimerTick + 1
            if _hbTimerTick < 8 then return end  -- ~7Hz, fine for 1s countdown
            _hbTimerTick = 0
            if T.frozen then return end
            if not T.active then
                if lbl.Text ~= "--:--" then
                    lbl.Text       = "--:--"
                    lbl.TextColor3 = Color3.fromRGB(120, 120, 120)
                end
                return
            end
            local secs = math.max(0, math.floor(T.value - (tick() - T.syncTick)))
            if secs == T.lastSecs then return end
            T.lastSecs = secs
            lbl.Text       = secs > 0 and _fmt(secs) or "--:--"
            lbl.TextColor3 = _color(secs)
        end)
        _addConn(_hbConn)

        -- -- Desconectar todo al apagar el toggle -------------------------
        _gameInfoState.timerConn = { Disconnect = _disconnectAll }

    end, false)


    do
        local _notifyRolState = { enabled = false, lastRole = "", conn = nil, cbId = nil }
        local function _playMurderSound()
            local s = Instance.new("Sound")
            s.SoundId = "rbxassetid://9116544314" -- sonido de muerte/alerta
            s.Volume  = 0.9
            s.Parent  = workspace
            s:Play()
            game.Debris:AddItem(s, 3)
        end
        local function _playSheriffSound()
            local s = Instance.new("Sound")
            s.SoundId = "rbxassetid://9116544314" -- sonido de click/accion
            s.Volume  = 0.9
            s.Parent  = workspace
            s:Play()
            game.Debris:AddItem(s, 3)
        end
        local _roleColors = {
            Murderer = Color3.fromRGB(255,  0, 40),
            Sheriff  = ThemeColors.Primary,  -- Azul
            Hero     = Color3.fromRGB(255,210,  0),
            Zombie   = Color3.fromRGB( 40,255, 40),
            Survivor = Color3.fromRGB(255, 255, 255),
            Freezer  = Color3.fromRGB(200, 200, 200),
            Runner   = Color3.fromRGB(198, 100, 17),
            Assassin = Color3.fromRGB(255,140,  0),
            Innocent = Color3.fromRGB(  0, 255, 160),
        }
 CreateToggle(leftColumn, "Notify ROL My", function(on)
            _notifyRolState.enabled = on

            -- Limpiar callbacks y GUI anteriores
            if _notifyRolState.cbId then
                _roundStartRoleCallbacks[_notifyRolState.cbId] = nil
                _notifyRolState.cbId = nil
            end
            if _notifyRolState.conn then
                _notifyRolState.conn:Disconnect()
                _notifyRolState.conn = nil
            end
            if _notifyRolState.gui then
                pcall(function() _notifyRolState.gui:Destroy() end)
                _notifyRolState.gui = nil
            end

            if not on then return end

            -- -- NUEVO: Overlay persistente SIEMPRE visible (no depende de gun/knife) --
            -- Usa UNICAMENTE el cache de RoundStart (_roleCache.localRole)
            local function _showRolOnScreen(role)
                if not _notifyRolState.enabled then return end
                -- No mostrar mientras el timer de ronda este activo
                if _G._roundTimerRunning then return end
                if _notifyRolState.gui then
                    pcall(function() _notifyRolState.gui:Destroy() end)
                    _notifyRolState.gui = nil
                end
                local safeRole = (role and role ~= "") and role or "Innocent"
                local color = _roleColors[safeRole] or Color3.fromRGB(200, 200, 200)

                -- OVERLAY FLOTANTE ANIMADO: pill CENTRADO en pantalla, slide-down desde arriba
                -- Posicion: Y=0.50 (centro) entre Timer(0.33) y Pct(0.58)
                local sg = Instance.new("ScreenGui")
                sg.Name            = "BYPAS_NotifyRol"
                sg.ResetOnSpawn    = false
                sg.ZIndexBehavior  = Enum.ZIndexBehavior.Global
                sg.DisplayOrder    = 9990
                sg.IgnoreGuiInset  = true
                pcall(function() sg.Parent = game:GetService("CoreGui") end)
                if not sg.Parent then sg.Parent = LocalPlayer:WaitForChild("PlayerGui") end

                -- Pill centrada horizontalmente, sin fondo (solo texto flotante con color del rol)
                local pill = Instance.new("Frame", sg)
                pill.Name                   = "Pill"
                pill.Size                   = UDim2.new(0, 200, 0, 40)
                pill.AnchorPoint            = Vector2.new(0.5, 0.5)
                pill.Position               = UDim2.new(0.5, 0, 0.50, -30)  -- arriba inicialmente
                pill.BackgroundTransparency = 1   -- sin fondo: siempre transparente
                pill.BorderSizePixel        = 0
                pill.ZIndex                 = 99
                Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 12)

                local stroke = Instance.new("UIStroke", pill)
                stroke.Color           = color
                stroke.Thickness       = 0     -- sin borde
                stroke.Transparency    = 1.0
                stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

                local lbl = Instance.new("TextLabel", pill)
                lbl.Name                   = "Display"
                lbl.Size                   = UDim2.new(1, 0, 1, 0)
                lbl.Position               = UDim2.new(0, 0, 0, 0)
                lbl.BackgroundTransparency = 1
                lbl.Text                   = "ROL: " .. safeRole:upper()
                lbl.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
                lbl.TextSize               = 18
                lbl.TextColor3             = color
                lbl.TextTransparency       = 1   -- empieza invisible
                lbl.TextStrokeTransparency = 0.20
                lbl.TextStrokeColor3       = Color3.fromRGB(0, 0, 0)
                lbl.TextXAlignment         = Enum.TextXAlignment.Center
                lbl.TextYAlignment         = Enum.TextYAlignment.Center
                lbl.ZIndex                 = 100

                -- Animacion de entrada: slide-down + fade-in (solo texto, sin fondo)
                local _ts2 = TweenService or game:GetService("TweenService")
                task.spawn(function()
                    task.wait(0.05)
                    -- Slide-down al centro exacto (sin cambiar BackgroundTransparency)
                    _ts2:Create(pill, TweenInfo.new(0.40, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Position = UDim2.new(0.5, 0, 0.50, 0),
                    }):Play()
                    task.wait(0.12)
                    _ts2:Create(lbl, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        TextTransparency = 0,
                    }):Play()
                    -- Pulso del color del texto (en lugar del borde)
                    task.wait(0.55)
                    while lbl and lbl.Parent and _notifyRolState.enabled do
                        _ts2:Create(lbl, TweenInfo.new(1.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {TextTransparency = 0.30}):Play()
                        task.wait(1.4)
                        _ts2:Create(lbl, TweenInfo.new(1.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {TextTransparency = 0}):Play()
                        task.wait(1.4)
                    end
                end)

                _notifyRolState.gui = sg
            end

            -- FIX: Solo actualiza cuando el rol REALMENTE cambia. No resetea _nrLastRole
            -- durante la ronda (evita spam de Innocent/Murderer entre ticks).
            _nrLastRole = ""
            _hbTnr = 0
            _notifyRolState.conn = RunService.Heartbeat:Connect(function()
                if not _notifyRolState.enabled then return end
                _hbTnr = _hbTnr + 1
                if _hbTnr < 30 then return end  -- ~2Hz
                _hbTnr = 0

                -- Ocultar label mientras el timer de ronda este corriendo
                -- Solo actua UNA VEZ (cuando pasa de visible a oculto)
                if _G._roundTimerRunning then
                    if _nrLastRole ~= "__hidden__" then
                        pcall(function()
                            local cg = game:GetService("CoreGui")
                            local existingSgHide = cg:FindFirstChild("BYPAS_NotifyRol")
                                               or LocalPlayer.PlayerGui:FindFirstChild("BYPAS_NotifyRol")
                            if existingSgHide then
                                local pillHide = existingSgHide:FindFirstChild("Pill")
                                local lblHide  = pillHide and pillHide:FindFirstChild("Display")
                                              or existingSgHide:FindFirstChildOfClass("TextLabel")
                                if lblHide and lblHide.Text ~= "" then
                                    local _ts4 = TweenService or game:GetService("TweenService")
                                    if pillHide then
                                        _ts4:Create(pillHide, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                                            Position = UDim2.new(0.5, 0, 0.50, -30),
                                            BackgroundTransparency = 1,
                                        }):Play()
                                        _ts4:Create(lblHide, TweenInfo.new(0.15), {TextTransparency = 1}):Play()
                                        local stk = pillHide:FindFirstChildOfClass("UIStroke")
                                        if stk then _ts4:Create(stk, TweenInfo.new(0.20), {Transparency = 1.0}):Play() end
                                    end
                                    task.delay(0.30, function() if lblHide then lblHide.Text = "" end end)
                                end
                            end
                        end)
                        _nrLastRole = "__hidden__"  -- marca: ya oculto, no volver a animar
                    end
                    return
                end

                -- Fuera de ronda: si veniamos ocultos, limpiar la marca para permitir refresh
                if _nrLastRole == "__hidden__" then _nrLastRole = "" end

                -- Leer rol del cache (unico source-of-truth del servidor)
                local role = _roleCache.localRole
                if not role or role == "" or role == "Dead" then role = "Innocent" end

                -- Salir si el rol es identico al que ya se muestra (evita spam)
                if role == _nrLastRole then return end

                -- Cambio real: actualizar texto y color
                _nrLastRole = role
                local cg = game:GetService("CoreGui")
                local existingSg = cg:FindFirstChild("BYPAS_NotifyRol")
                                or LocalPlayer.PlayerGui:FindFirstChild("BYPAS_NotifyRol")
                if existingSg then
                    pcall(function()
                        local c2 = _roleColors[role] or Color3.fromRGB(200,200,200)
                        local pill2 = existingSg:FindFirstChild("Pill")
                        local lbl2 = pill2 and pill2:FindFirstChild("Display")
                                  or existingSg:FindFirstChildOfClass("TextLabel")
                        if lbl2 then
                            lbl2.Text       = "ROL: " .. role:upper()
                            lbl2.TextColor3 = c2
                        end
                        local _ts3 = TweenService or game:GetService("TweenService")
                        if pill2 then
                            local stroke2 = pill2:FindFirstChildOfClass("UIStroke")
                            if stroke2 then
                                _ts3:Create(stroke2, TweenInfo.new(0.3), {Color = c2}):Play()
                            end
                        end
                    end)
                else
                    _showRolOnScreen(role)
                end
            end)

            -- Registrar callback de RoundStart para notificacion + actualizar overlay
            cbId = tostring(tick())
            _notifyRolState.cbId = cbId
            _roundStartRoleCallbacks[cbId] = function(role)
                if not _notifyRolState.enabled then return end
                if not role or role == "" then role = "Innocent" end
                -- Actualizar _nrLastRole ANTES de mostrar para que el Heartbeat
                -- no detecte un "cambio" adicional en el proximo tick
                _nrLastRole = role
                _showRolOnScreen(role)
                if role == "Murderer" then
                    _playMurderSound()
 CreateCustomNotification("MI ROL: MURDERER", "!Sos el ASESINO!", 5)
                elseif role == "Sheriff" then
                    _playSheriffSound()
 CreateCustomNotification("MI ROL: SHERIFF", "!Sos el SHERIFF!", 5)
                elseif role == "Hero" then
                    _playSheriffSound()
 CreateCustomNotification("MI ROL: HERO", "!Sos el HEROE!", 5)
                elseif role == "Innocent" then
 CreateCustomNotification("MI ROL: INNOCENT", "Sos INOCENTE.", 4)
                else
 CreateCustomNotification("MI ROL: " .. role:upper(), "Rol detectado.", 4)
                end
            end

            -- Mostrar inmediatamente con el rol actual del cache (si ya hay uno valido)
            task.defer(function()
                -- Solo mostrar si el cache viene del RoundStart (no de fallback)
                local cached = _roleCache.localRole
                if not cached or cached == "" or cached == "Dead" then cached = "Innocent" end
                _showRolOnScreen(cached)
                _nrLastRole = cached
            end)
        end, false)
    end



 CreateToggle(leftColumn, "PORCENTAJE ROL", function(on)
        _gameInfoState.pctEnabled = on

        if _gameInfoState.pctConn then
            _gameInfoState.pctConn:Disconnect()
            _gameInfoState.pctConn = nil
        end
        if _gameInfoState.pctGui then
            _gameInfoState.pctGui:Destroy()
            _gameInfoState.pctGui = nil
        end

        if not on then return end

        sg, lbl = _createOverlayLabel("Pct", 68, 14, Enum.Font.GothamBold)
        -- Centrado en pantalla (posicion definida por _overlayYScale.Pct = 0.58)
        lbl.TextSize = 14
        _gameInfoState.pctGui = sg

        lastPct = "..."
 lbl.Text = "MURDER% " .. lastPct .. "%"

        pcall(function()
            _pctEventConn = game.ReplicatedStorage.Remotes.Gameplay.ShowRoleSelectNew.OnClientEvent:Connect(function(arg1)
                if not _gameInfoState.pctEnabled then return end
                if type(arg1) == "table" and arg1.Chance ~= nil then
                    lastPct = tostring(arg1.Chance)
                end
            end)
        end)

        -- Poll inicial + re-poll cada 3 s para mantener el valor fresco
        task.spawn(function()
            while _gameInfoState.pctEnabled do
                local ok, val = pcall(function()
                    return game.ReplicatedStorage.Remotes.Extras.GetChance:InvokeServer()
                end)
                if ok and val ~= nil then lastPct = tostring(val) end
                task.wait(3)
            end
        end)

        _hbTpctC = 0
        _gameInfoState.pctConn = RunService.Heartbeat:Connect(function()
            _hbTpctC=_hbTpctC+1; if _hbTpctC<4 then return end; _hbTpctC=0
            if not _gameInfoState.pctEnabled then return end
 lbl.Text = "MURDER% " .. lastPct .. "%"
            n = tonumber(lastPct)
            if n then
                if n >= 50 then
                    lbl.TextColor3 = Color3.fromRGB(58, 58, 58)
                elseif n >= 25 then
                    lbl.TextColor3 = Color3.fromRGB(60, 60, 60)
                else
                    lbl.TextColor3 = Color3.fromRGB(236, 140, 32)
                end
            else
                lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            end
        end)
        _origPctDisable = _gameInfoState.pctConn
        if _pctEventConn then
            -- Usar task.spawn+wait en vez de Heartbeat para cleanup de conn
            task.spawn(function()
                while _pctEventConn do
                    task.wait(0.5)
                    if not _gameInfoState.pctEnabled and _pctEventConn then
                        _pctEventConn:Disconnect()
                        _pctEventConn = nil
                    end
                end
            end)
        end

    end, false)
end


