-- ===================================================================
-- SECURE RESEARCH FACILITY -- TP a TestTube con sliders de offset
-- Ruta: workspace.ResearchFacility.Interactive.AccessibleTestTube.Tube
-- ===================================================================
_srfState = {
    enabled   = false,
    conn      = nil,
    offsetX   = 0,
    offsetY   = 0,
    offsetZ   = 0,
    interval  = 0.5,   -- segundos entre cada re-TP
    autoReTP  = true,  -- re-teleportar si te alejan
    lastPos   = nil,
}

function _srfGetTube()
    -- Navegar la ruta exacta: workspace -> ResearchFacility -> Interactive -> AccessibleTestTube -> Tube
    local ok, tube = pcall(function()
        return workspace
            :FindFirstChild("ResearchFacility")
            :FindFirstChild("Interactive")
            :FindFirstChild("AccessibleTestTube")
            :FindFirstChild("Tube")
    end)
    if ok and tube then return tube end
    -- Fallback: buscar "Tube" descendiente de cualquier "AccessibleTestTube"
    ok2, tube2 = pcall(function()
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj.Name == "AccessibleTestTube" then
                local t = obj:FindFirstChild("Tube")
                if t then return t end
            end
        end
        return nil
    end)
    return ok2 and tube2 or nil
end

function _srfDoTP()
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end

    local tube = _srfGetTube()
    if not tube then
 CreateCustomNotification("SECURE RF", "Tube no encontrado en este mapa", 2)
        return false
    end

    -- Posicion del Tube + offsets del usuario
    local tubeCF = tube:IsA("BasePart") and tube.CFrame
               or (tube:IsA("Model") and tube:GetModelCFrame())
               or (tube:FindFirstChildWhichIsA("BasePart") and tube:FindFirstChildWhichIsA("BasePart").CFrame)
    if not tubeCF then
 CreateCustomNotification("SECURE RF", "No se pudo obtener posicion del Tube", 2)
        return false
    end

    local targetPos = tubeCF.Position + Vector3.new(
        _srfState.offsetX,
        _srfState.offsetY,
        _srfState.offsetZ
    )

    pcall(function() hrp.CFrame = CFrame.new(targetPos) end)
    _srfState.lastPos = targetPos
    return true
end

function CreateMainUI_SecureResearchFacility()
 CreateSection(leftColumn, "", "SECURE RESEARCH FACILITY", Color3.fromRGB(220, 123, 26))

    -- Info label
    -- (info label removida)

    -- Toggle principal -- arranca conn siempre, intenta TP inmediato y periodico
 CreateToggle(leftColumn, "Secure TestTube (auto-TP)", function(on)
        _srfState.enabled = on

        if _srfState.conn then
            pcall(function() _srfState.conn:Disconnect() end)
            _srfState.conn = nil
        end

        if not on then
            _srfState.lastPos = nil
 CreateCustomNotification("SECURE RF", "Desactivado", 1.5)
            return
        end

        -- Intentar TP inmediato (puede fallar si el mapa aun no cargo)
        _srfDoTP()
 CreateCustomNotification("SECURE RF", "SECURE RF ON -- buscando Tube...", 2)

        -- Arrancar loop SIEMPRE (no depende del exito del TP inicial)
        local _rfTick = 0
        _srfState.conn = RunService.Heartbeat:Connect(function(dt)
            if not _srfState.enabled then return end
            _rfTick = _rfTick + dt
            if _rfTick < (_srfState.interval or 0.5) then return end
            _rfTick = 0

            local char2 = LocalPlayer.Character
            local hrp2  = char2 and char2:FindFirstChild("HumanoidRootPart")
            if not hrp2 then return end

            if not _srfState.autoReTP then return end

            if _srfState.lastPos then
                -- Ya tenemos posicion: re-TP si nos alejaron
                local drift = (hrp2.Position - _srfState.lastPos).Magnitude
                if drift > 3 then
                    pcall(function() hrp2.CFrame = CFrame.new(_srfState.lastPos) end)
                end
            else
                -- No tenemos posicion aun: intentar encontrar el Tube
                local ok = _srfDoTP()
                if ok then
 CreateCustomNotification("SECURE RF", "Tube encontrado! TP activo", 2)
                end
            end
        end)
    end, false)

    -- Boton de TP manual inmediato
 CreateButton(leftColumn, "TP al Tube ahora", ThemeColors.Aurora3, function()
        ok = _srfDoTP()
 CreateCustomNotification("SECURE RF", ok and "TP ejecutado!" or "Tube no encontrado", 2)
    end)

    -- Boton para SALIR del Tube (TP a posicion segura afuera)
 CreateButton(leftColumn, "Salir del Tube", ThemeColors.Aurora4, function()
        -- Desactivar auto-reTP para que no nos vuelva a meter
        wasEnabled = _srfState.enabled
        _srfState.lastPos = nil  -- limpiar posicion objetivo

        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then
 CreateCustomNotification("SECURE RF", "No se encontro el personaje", 2)
            return
        end

        -- Intentar TP al spawn o a un lugar seguro relativo
        -- Primero intentar encontrar SpawnLocation
        spawnPos = nil
        pcall(function()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("SpawnLocation") then
                    spawnPos = obj.Position + Vector3.new(0, 5, 0)
                    break
                end
            end
        end)

        if spawnPos then
            pcall(function() hrp.CFrame = CFrame.new(spawnPos) end)
 CreateCustomNotification("SECURE RF", "Saliste al spawn!", 2)
        else
            -- Fallback: TP 30 studs arriba del Tube
            local tube = _srfGetTube()
            if tube then
                local tubeCF = tube:IsA("BasePart") and tube.CFrame
                           or (tube:FindFirstChildWhichIsA("BasePart") and tube:FindFirstChildWhichIsA("BasePart").CFrame)
                if tubeCF then
                    pcall(function() hrp.CFrame = tubeCF + Vector3.new(0, 30, 20) end)
 CreateCustomNotification("SECURE RF", "Saliste del Tube!", 2)
                end
            else
                -- Ultimo fallback: subir 50 studs
                pcall(function() hrp.CFrame = hrp.CFrame + Vector3.new(0, 50, 0) end)
 CreateCustomNotification("SECURE RF", "Saliste (TP hacia arriba)", 2)
            end
        end
    end)

    -- -- TOGGLES DE INFORMACION --------------------------------------
    -- Cada toggle muestra el mensaje UNA SOLA VEZ hasta que cambie el dato

    -- 1. Information Murder -- una notif por cada nuevo murderer detectado
    CreateAuroraToggle(leftColumn, "Information Murder", function(on)
        _srfState.autoReTP = on
        if on then
            task.spawn(function()
                local _lastKey = ""
                while _srfState.autoReTP do
                    task.wait(1.5)
                    if not _srfState.autoReTP then break end
                    local murder = findMurderer and findMurderer()
                    if murder then
                        local char  = murder.Character
                        local hrp   = char and char:FindFirstChild("HumanoidRootPart")
                        local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        local dist  = (hrp and myHRP) and math.floor((hrp.Position - myHRP.Position).Magnitude) or "?"
                        local key   = murder.Name
                        if key ~= _lastKey then
                            _lastKey = key
                            CreateCustomNotification("Information Murder",
                                murder.Name .. " es el Murderer -- " .. tostring(dist) .. " studs", 6)
                        end
                    else
                        if _lastKey ~= "" then _lastKey = "" end
                    end
                end
            end)
            CreateCustomNotification("Information Murder", "Activo -- buscando Murderer", 2)
        else
            CreateCustomNotification("Information Murder", "Desactivado", 1.5)
        end
    end, false)

    -- 2. Information Sheriff -- una notif por cada nuevo sheriff detectado
    CreateAuroraToggle(leftColumn, "Information Sheriff", function(on)
        _srfState.infoSheriff = on
        if on then
            task.spawn(function()
                local _lastKey = ""
                while _srfState.infoSheriff do
                    task.wait(1.5)
                    if not _srfState.infoSheriff then break end
                    local sheriff = findSheriffPlayer and findSheriffPlayer()
                    if sheriff then
                        local char  = sheriff.Character
                        local hrp   = char and char:FindFirstChild("HumanoidRootPart")
                        local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        local dist  = (hrp and myHRP) and math.floor((hrp.Position - myHRP.Position).Magnitude) or "?"
                        local key   = sheriff.Name
                        if key ~= _lastKey then
                            _lastKey = key
                            CreateCustomNotification("Information Sheriff",
                                sheriff.Name .. " tiene la pistola -- " .. tostring(dist) .. " studs", 6)
                        end
                    else
                        if _lastKey ~= "" then _lastKey = "" end
                    end
                end
            end)
            CreateCustomNotification("Information Sheriff", "Activo -- buscando Sheriff", 2)
        else
            CreateCustomNotification("Information Sheriff", "Desactivado", 1.5)
        end
    end, false)

    -- 3. Information Personal -- notifica solo cuando cambia el rol o la HP cae >10
    CreateAuroraToggle(leftColumn, "Information Personal", function(on)
        _srfState.infoPersonal = on
        if on then
            task.spawn(function()
                local _lastKey = ""
                while _srfState.infoPersonal do
                    task.wait(1.5)
                    if not _srfState.infoPersonal then break end
                    local role = (_roleCache and _roleCache.localRole) or "Innocent"
                    if role == "" or role == "Dead" then role = "Innocent" end
                    local char = LocalPlayer.Character
                    local hum  = char and char:FindFirstChildOfClass("Humanoid")
                    local hp   = hum and math.floor(hum.Health / 10) * 10 or 0  -- bucket de 10 en 10
                    local ping = math.floor(LocalPlayer:GetNetworkPing() * 1000)
                    local key  = role .. tostring(hp)
                    if key ~= _lastKey then
                        _lastKey = key
                        CreateCustomNotification("Information Personal",
                            "Rol: " .. role .. " | HP: " .. tostring(hum and math.floor(hum.Health) or "?") .. " | Ping: " .. ping .. "ms", 6)
                    end
                end
            end)
            CreateCustomNotification("Information Personal", "Activo -- mostrando tus stats", 2)
        else
            CreateCustomNotification("Information Personal", "Desactivado", 1.5)
        end
    end, false)

    -- 4. Information Muertos -- una notif por cada muerte nueva de Murder o Sheriff
    CreateAuroraToggle(leftColumn, "Information Muertos (Murder+Sheriff)", function(on)
        _srfState.infoMuertos = on
        if on then
            task.spawn(function()
                local _notified = {}  -- tabla: key -> true, para no repetir
                while _srfState.infoMuertos do
                    task.wait(1.5)
                    if not _srfState.infoMuertos then break end
                    for _, p in pairs(_cachedPlayers) do
                        if p == LocalPlayer then continue end
                        local char = p.Character
                        local hum  = char and char:FindFirstChildOfClass("Humanoid")
                        local role = _roleCache and (_roleCache[p] or _roleCache.roles and _roleCache.roles[p.Name])
                        if hum and hum.Health <= 0 and role then
                            local roleStr = tostring(role)
                            if roleStr:lower():find("murder") or roleStr:lower():find("sheriff") then
                                local key = p.Name .. roleStr
                                if not _notified[key] then
                                    _notified[key] = true
                                    CreateCustomNotification("Information Muertos",
                                        p.Name .. " (" .. roleStr .. ") murio", 6)
                                end
                            end
                        end
                    end
                    -- Limpiar tabla al inicio de nueva ronda (cuando todos vuelven a estar vivos)
                    local anyDead = false
                    for _, p in pairs(_cachedPlayers) do
                        local char = p.Character
                        local hum  = char and char:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health <= 0 then anyDead = true; break end
                    end
                    if not anyDead then _notified = {} end
                end
            end)
            CreateCustomNotification("Information Muertos", "Activo -- vigilando Murder y Sheriff", 2)
        else
            CreateCustomNotification("Information Muertos", "Desactivado", 1.5)
        end
    end, false)
end

-- SECURE AUTOMATIC -- mata al murderer con knife + safe TP
-- Detecta al murderer, espera que este cerca y lo mata silenciosamente
-- ===================================================================
_secAuto = {
    enabled     = false,
    conn        = nil,
    radius      = 30,
    delay       = 0.05,
    mode        = "Knife",   -- "Knife" | "Gun"
    _gui        = nil,
    _lastKill   = 0,
    _cooldown   = 0.8,
}

function CreateMainUI_SecureAuto()
 CreateSection(leftColumn, "", "SECURE AUTOMATIC", Color3.fromRGB(58, 58, 58))

    -- Info label
    -- (info label removida)

    -- Modo de ataque: toggles simples
    do
        local modeFrame = Instance.new("Frame", leftColumn)
        modeFrame.Size = UDim2.new(1, -10, 0, 26)
        modeFrame.BackgroundTransparency = 1
        modeFrame.BorderSizePixel = 0
        local modeLbl = Instance.new("TextLabel", modeFrame)
        modeLbl.Size = UDim2.new(0.35, 0, 1, 0); modeLbl.BackgroundTransparency = 1
 modeLbl.Text = "Ataque:"; modeLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
        modeLbl.TextSize = 11; modeLbl.TextColor3 = Color3.fromRGB(200,200,200)
        modeLbl.TextXAlignment = Enum.TextXAlignment.Left
        local modeLayout = Instance.new("UIListLayout", modeFrame)
        modeLayout.FillDirection = Enum.FillDirection.Horizontal
        modeLayout.Padding = UDim.new(0, 4)
        local modes = {"Knife"}  -- Solo knife
        local selMode = _secAuto.mode or "Knife"
        local modeBtns = {}
        for _, m in ipairs(modes) do
            local mb = Instance.new("TextButton", modeFrame)
            mb.Size = UDim2.new(0, 72, 1, 0); mb.BackgroundColor3 = Color3.fromRGB(255,255,255)
            mb.BackgroundTransparency = m == selMode and 0.72 or 0.92
 mb.BorderSizePixel = 0; mb.Text = m; mb.AutoButtonColor = false
            mb.FontFace = Font.fromEnum(Enum.Font.Arimo); mb.TextSize = 10
            mb.TextColor3 = m == selMode and Color3.fromRGB(255,255,255) or Color3.fromRGB(180,180,180)
            Instance.new("UICorner", mb).CornerRadius = UDim.new(0, 8)
            local st = Instance.new("UIStroke", mb)
            st.Color = Color3.fromRGB(255,255,255); st.Thickness = 1
            st.Transparency = m == selMode and 0.5 or 0.85; mb.ZIndex = 13
            modeBtns[m] = {btn=mb, stroke=st}
            mb.Activated:Connect(function()
                selMode = m; _secAuto.mode = m
                for k, d in pairs(modeBtns) do
                    local isS = (k == m)
                    TweenService:Create(d.btn, TweenInfo.new(0.15), {
                        BackgroundTransparency = isS and 0.72 or 0.92,
                        TextColor3 = isS and Color3.fromRGB(255,255,255) or Color3.fromRGB(180,180,180),
                    }):Play()
                    TweenService:Create(d.stroke, TweenInfo.new(0.15), {Transparency = isS and 0.5 or 0.85}):Play()
                end
            end)
        end
    end

    -- Admin Fly reemplaza los sliders/toggles de Secure Automatic
    do
        local _adminFlyEnabled = false
        local _adminFlyConn = nil
        local _adminFlySpeed = 60
        local _adminFlyTracks = {}

        local function _adminFlyStop()
            _adminFlyEnabled = false
            if _adminFlyConn then _adminFlyConn:Disconnect(); _adminFlyConn = nil end
            pcall(function()
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if hrp then
                    pcall(function() local b = hrp:FindFirstChild("AdminFlyBV"); if b then b:Destroy() end end)
                    pcall(function() local b = hrp:FindFirstChild("AdminFlyBG"); if b then b:Destroy() end end)
                end
                if hum and hum.Parent then hum.PlatformStand = false end
                for _, tr in ipairs(_adminFlyTracks) do pcall(function() tr:Stop() end) end
                _adminFlyTracks = {}
                if char then
                    for _, p in ipairs(char:GetDescendants()) do
                        if p:IsA("BasePart") then pcall(function() p.CanCollide = true end) end
                    end
                end
            end)
        end

        local function _adminFlyStart()
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not hrp or not hum then return end

            _adminFlyEnabled = true
            if _adminFlyConn then _adminFlyConn:Disconnect() end

            -- Noclip
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then pcall(function() p.CanCollide = false end) end
            end

            -- Swim anims
            pcall(function()
                local animator = hum:FindFirstChildOfClass("Animator")
                if animator then
                    for _, id in ipairs({"507784897", "481825862", "10921264784"}) do
                        pcall(function()
                            local a = Instance.new("Animation")
                            a.AnimationId = "rbxassetid://" .. id
                            local t = animator:LoadAnimation(a)
                            t.Priority = Enum.AnimationPriority.Action4
                            t.Looped = true; t:Play(0.15)
                            table.insert(_adminFlyTracks, t)
                        end)
                    end
                end
            end)

            hum.PlatformStand = true
            pcall(function() local b = hrp:FindFirstChild("AdminFlyBV"); if b then b:Destroy() end end)
            pcall(function() local b = hrp:FindFirstChild("AdminFlyBG"); if b then b:Destroy() end end)

            local bv = Instance.new("BodyVelocity", hrp)
            bv.Name = "AdminFlyBV"; bv.MaxForce = Vector3.new(1e6,1e6,1e6); bv.Velocity = Vector3.zero
            local bg = Instance.new("BodyGyro", hrp)
            bg.Name = "AdminFlyBG"; bg.MaxTorque = Vector3.new(1e6,1e6,1e6); bg.P = 2e4; bg.D = 800

            local _afIsMobile = (function()
                local ok, res = pcall(function() return UserInputService.TouchEnabled end)
                return ok and res
            end)()
            _adminFlyConn = RunService.Heartbeat:Connect(function()
                if not _adminFlyEnabled then
                    pcall(function() bv:Destroy() end); pcall(function() bg:Destroy() end)
                    _adminFlyConn:Disconnect(); _adminFlyConn = nil
                    return
                end
                local cam = workspace.CurrentCamera
                local dir = Vector3.zero
                local isBst = false
                if _afIsMobile then
                    local _afc = LocalPlayer.Character
                    local _afh = _afc and _afc:FindFirstChildOfClass("Humanoid")
                    if _afh then
                        local md = _afh.MoveDirection
                        if md.Magnitude > 0.1 then dir = Vector3.new(md.X, 0, md.Z) end
                    end
                    if _G._flyUpHeld   then dir = dir + Vector3.yAxis end
                    if _G._flyDownHeld then dir = dir - Vector3.yAxis end
                    isBst = _G._flyBoostHeld
                else
                    isBst = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.yAxis end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then dir = dir - Vector3.yAxis end
                end
                local spd = _adminFlySpeed * (isBst and 3 or 1)
                bv.Velocity = dir.Magnitude > 0 and dir.Unit * spd or Vector3.zero
                bg.CFrame = cam.CFrame
            end)
        end



        LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if _adminFlyEnabled then _adminFlyStart() end
        end)
    end

    local function _secAutoFire()
        local now = os.clock()
        if now - _secAuto._lastKill < _secAuto._cooldown then return end
        _secAuto._lastKill = now

        local char = LocalPlayer.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end

        -- Detectar murderer dentro del radio
        local murderer = _roleCache.murderer
        if not murderer then
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("Knife") then
                    murderer = p; break
                end
            end
        end
        if not murderer or not murderer.Character then return end
        local mHRP = murderer.Character:FindFirstChild("HumanoidRootPart")
        local mHum = murderer.Character:FindFirstChildOfClass("Humanoid")
        if not mHRP or not mHum or mHum.Health <= 0 then return end
        if (hrp.Position - mHRP.Position).Magnitude > _secAuto.radius then return end

        task.delay(_secAuto.delay, function()
            if not _secAuto.enabled then return end

            -- -- STEP 1: TP dentro/debajo del murderer ------------------------
            -- Teleportamos nuestro HRP exactamente a la posicion del mHRP del murder
            -- (dentro de su hitbox) para que el KnifeStabbed/firetouchinterest sea 100% efectivo
            -- Este es el mismo comportamiento de "GoTo Feet" mostrado en la imagen
            pcall(function()
                -- Rotar 90 deg en X (lay under) + posicion exacta del murder
                local underCF = CFrame.new(mHRP.Position) * CFrame.Angles(math.rad(90), 0, 0)
                hrp.CFrame = underCF
                hrp.AssemblyLinearVelocity = Vector3.zero
            end)

            -- -- STEP 2: Esperar 1 frame para que el TP se aplique ------------
            task.wait()

            -- -- STEP 3: Disparar el kill con knife ---------------------------
            if _secAuto.mode == "Knife" or true then  -- siempre usar knife primero
                local knife = char:FindFirstChild("Knife")
                    or (function()
                        local k = LocalPlayer.Backpack:FindFirstChild("Knife")
                        if k then pcall(function() hum:EquipTool(k) end); task.wait(0.04) end
                        return char:FindFirstChild("Knife")
                    end)()
                if knife then
                    local ev = knife:FindFirstChild("Events")
                    local hd = knife:FindFirstChild("Handle")
                    -- Metodo 1: KnifeStabbed (directo, no causa TP del jugador)
                    local stab = ev and ev:FindFirstChild("KnifeStabbed")
                    if stab then pcall(function() stab:FireServer(mHRP) end) end
                    -- Metodo 2: firetouchinterest -- simula contacto fisico con el handle
                    if firetouchinterest and hd then
                        pcall(function()
                            firetouchinterest(hd, mHRP, 0)
                            task.wait(0.016)
                            firetouchinterest(hd, mHRP, 1)
                        end)
                    end
                    -- Metodo 3: KnifeThrown apuntando directamente al mHRP
                    thrown = ev and ev:FindFirstChild("KnifeThrown")
                    if thrown and hd then
                        local origin = hd.CFrame
                        local tgtCF  = CFrame.new(mHRP.Position)
                        pcall(function() thrown:FireServer(origin, tgtCF) end)
                    end
                end
            end

 CreateCustomNotification(" SECURE AUTO", "-> " .. murderer.Name, 1.5)
        end)
    end

    local function _secStart()
        if _secAuto.conn then _secAuto.conn:Disconnect(); _secAuto.conn = nil end
        local _hbT = 0
        _secAuto.conn = RunService.Heartbeat:Connect(function()
            _hbT = _hbT + 1; if _hbT < 3 then return end; _hbT = 0
            if not _secAuto.enabled then return end
            _secAutoFire()
        end)
    end

    local function _secStop()
        if _secAuto.conn then _secAuto.conn:Disconnect(); _secAuto.conn = nil end
    end

    -- -- BINDABLE LEGACY ------------------------------------------------
 CreateToggle(leftColumn, " Bindable Secure Auto (boton pantalla)", function(on)
        if _secAuto._gui then
            pcall(function() _secAuto._gui:Destroy() end)
            _secAuto._gui = nil
        end
        if not on then return end

        bGui = Instance.new("ScreenGui")
        bGui.Name = "BypasSecureAutoBindable"
        bGui.ResetOnSpawn = false
        bGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        bGui.IgnoreGuiInset = true
        bGui.DisplayOrder = 9850
        pcall(function() bGui.Parent = game:GetService("CoreGui") end)
        if not bGui.Parent then bGui.Parent = LocalPlayer:WaitForChild("PlayerGui") end
        _secAuto._gui = bGui

        frame = Instance.new("Frame", bGui)
        frame.Size = UDim2.new(0, 200, 0, 58)
        frame.Position = UDim2.new(0, 20, 0, 200)
        frame.BackgroundColor3 = Color3.fromRGB(  3,   8,  18)
        frame.BackgroundTransparency = 0.72
        frame.BorderSizePixel = 0
        frame.Active = true
        frame.ZIndex = 198
        Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 10)
        fStroke = Instance.new("UIStroke", frame)
        fStroke.Color = Color3.fromRGB(57, 57, 57)
        fStroke.Thickness = 2
        fStroke.Transparency = 0.1
        -- Pulso animado
        task.spawn(function()
            while frame and frame.Parent do
                TweenService:Create(fStroke, TweenInfo.new(0.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Transparency=0.6}):Play()
                task.wait(0.9)
                TweenService:Create(fStroke, TweenInfo.new(0.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Transparency=0.0}):Play()
                task.wait(0.9)
            end
        end)

        btn = Instance.new("TextButton", frame)
        btn.Size = UDim2.new(1, 0, 1, 0)
        btn.BackgroundTransparency = 1
        btn.FontFace = Font.fromEnum(Enum.Font.Arimo)
        btn.TextSize = 16
        btn.ZIndex = 200
        btn.AutoButtonColor = false

        local function _updateBtnText()
 btn.Text = _secAuto.enabled and " SECURE ON" or " SECURE OFF"
            btn.TextColor3 = _secAuto.enabled and Color3.fromRGB(255, 50, 50) or Color3.fromRGB(58, 58, 58)
        end
        _updateBtnText()

        -- Drag
        ds, fs, isDrag = nil, nil, false
        btn.InputBegan:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 then
                ds = inp.Position; fs = frame.Position; isDrag = false
            end
        end)
        UserInputService.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 then ds = nil; isDrag = false end
        end)
        UserInputService.InputChanged:Connect(function(inp)
            if not ds then return end
            if inp.UserInputType == Enum.UserInputType.MouseMovement then
                local d = inp.Position - ds
                if not isDrag and d.Magnitude > 5 then isDrag = true end
                if isDrag then frame.Position = UDim2.new(fs.X.Scale, fs.X.Offset + d.X, fs.Y.Scale, fs.Y.Offset + d.Y) end
            end
        end)
        btn.Activated:Connect(function()
            if isDrag then return end
            _secAuto.enabled = not _secAuto.enabled
            if _secAuto.enabled then _secStart() else _secStop() end
            _updateBtnText()

        end)
    end, false)
end

-- ===================================================================
-- RESEARCH FACILITY -- auto-TP + auto-click en tecla F (interacciones)
-- Detecta el mapa Research Facility y automates las interacciones
-- ===================================================================
_rfState = {
    enabled     = false,
    fConn       = nil,
    mapConn     = nil,
    detected    = false,
    autoClick   = false,
    clickConn   = nil,
    tpEnabled   = false,
    spots       = {},        -- se pueblan al detectar el mapa
    lastTP      = 0,
    tpCooldown  = 3,
}

-- Detectar si el mapa actual es Research Facility
function _rfDetectMap()
    for _, obj in pairs(workspace:GetDescendants()) do
        if obj:IsA("BasePart") or obj:IsA("Model") or obj:IsA("Folder") then
            local n = obj.Name:lower()
            if n:find("research") or n:find("facility") or n:find("lab") or n:find("laborat") then
                return true
            end
        end
    end
    -- fallback: checar nombre del map en Lighting o ReplicatedStorage
    local mapName = ""
    pcall(function()
        mapName = game:GetService("Lighting"):GetAttribute("MapName") or ""
    end)
    if mapName:lower():find("research") or mapName:lower():find("facility") then return true end
    return false
end

-- Encontrar objetos interactivos (ProximityPrompts relacionados a F)
function _rfGetInteractables()
    local spots = {}
    for _, obj in pairs(workspace:GetDescendants()) do
        if obj:IsA("ProximityPrompt") then
            local keyCode = obj.KeyboardKeyCode
            if keyCode == Enum.KeyCode.F or keyCode == Enum.KeyCode.E then
                local part = obj.Parent
                if part and part:IsA("BasePart") then
                    table.insert(spots, { pp = obj, part = part, pos = part.Position })
                end
            end
        end
    end
    return spots
end

-- Ejecutar ProximityPrompt (simula presionar F)
function _rfFirePP(pp)
    pcall(function()
        local VPS = game:GetService("VirtualInputManager") or game:GetService("Players")
        fireproximityprompt(pp)
    end)

    -- -- KNIFE DODGE (esquivar cuchillo lanzado) ----------------------
    do
        local _kDodgeEnabled = false
        local _kDodgeConn    = nil
        local _kDodgeCooldown = 0
        local _kDodgeLastTime = 0

        local function _doDodge(bladePart)
            local now = tick()
            if now - _kDodgeLastTime < 0.4 then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then return end

            -- FIX: verificar que la bladePart aun existe y se mueve hacia nosotros
            if not bladePart.Parent then return end
            local vel = bladePart.AssemblyLinearVelocity
            if vel.Magnitude > 1 then
                local toMe = (hrp.Position - bladePart.Position)
                if toMe:Dot(vel.Unit) <= 0 then return end  -- alejandose -> no esquivar
            end

            -- Direccion perpendicular a la trayectoria del cuchillo
            local knifeVel = bladePart.AssemblyLinearVelocity
            local knifeDir = knifeVel.Magnitude > 1 and knifeVel.Unit or
                             (bladePart.Position - hrp.Position).Unit
            -- Vector perpendicular al plano XZ
            local right = Vector3.new(-knifeDir.Z, 0, knifeDir.X).Unit
            local sideA = hrp.Position + right * 7
            local sideB = hrp.Position - right * 7

            -- Raycast hacia abajo para encontrar el suelo real en cada lado
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = {char}
            local hitA = workspace:Raycast(sideA + Vector3.new(0, 8, 0), Vector3.new(0, -20, 0), params)
            local hitB = workspace:Raycast(sideB + Vector3.new(0, 8, 0), Vector3.new(0, -20, 0), params)

            local dodgePos
            -- FIX: usar Y del suelo + 3.2 (altura HRP). Si no hay suelo, mantener Y actual
            if hitA and hitB then
                -- Ambos tienen suelo -> elegir el que tenga suelo mas alto (mas cerca del personaje)
                local yA = hitA.Position.Y + 3.2
                local yB = hitB.Position.Y + 3.2
                dodgePos = (math.abs(yA - hrp.Position.Y) <= math.abs(yB - hrp.Position.Y))
                    and Vector3.new(sideA.X, yA, sideA.Z)
                    or  Vector3.new(sideB.X, yB, sideB.Z)
            elseif hitA then
                dodgePos = Vector3.new(sideA.X, hitA.Position.Y + 3.2, sideA.Z)
            elseif hitB then
                dodgePos = Vector3.new(sideB.X, hitB.Position.Y + 3.2, sideB.Z)
            else
                -- Sin suelo en ningun lado -> mantener Y actual (no subir ni bajar)
                dodgePos = Vector3.new(sideA.X, hrp.Position.Y, sideA.Z)
            end

            _kDodgeLastTime = now
            pcall(function()
                local newCF = CFrame.new(dodgePos, dodgePos + hrp.CFrame.LookVector)
                hrp.CFrame = newCF
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end

        local function _startKnifeDodge()
            if _kDodgeConn then pcall(function() _kDodgeConn:Disconnect() end) end
            _kDodgeConn = workspace.DescendantAdded:Connect(function(obj)
                if not _kDodgeEnabled then return end
                if not obj:IsA("Model") then return end
                local n = obj.Name
                if not (n == "ThrowingKnife" or n:lower():find("throwingknife")) then return end
                if obj.Parent ~= workspace then return end
                -- Monitorear distancia del cuchillo a mi personaje
                task.spawn(function()
                    task.wait(0.016)
                    local blade = obj:FindFirstChild("BladePosition")
                        or obj:FindFirstChild("KnifeVisual")
                        or obj:FindFirstChildWhichIsA("BasePart")
                    if not blade then return end
                    local _t = 0
                    local monConn
                    monConn = RunService.Heartbeat:Connect(function()
                        _t = _t + 1; if _t < 2 then return end; _t = 0
                        if not _kDodgeEnabled or not obj.Parent or not blade.Parent then
                            monConn:Disconnect(); return
                        end
                        local char = LocalPlayer.Character
                        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                        if not hrp then return end

                        -- FIX: ignorar si el knife fue lanzado por el propio jugador local
                        -- (el modelo estara relacionado con el LocalPlayer)
                        if obj:IsDescendantOf(LocalPlayer) then
                            monConn:Disconnect(); return
                        end

                        -- FIX: solo esquivar si el knife viene HACIA nosotros (no alejandose)
                        local vel = blade.AssemblyLinearVelocity
                        if vel.Magnitude > 1 then
                            local toMe = (hrp.Position - blade.Position)
                            local dot  = toMe:Dot(vel.Unit)
                            if dot <= 0 then return end  -- alejandose -> ignorar
                        end

                        -- Activar esquive si el knife esta a menos de 10 studs
                        local dist = (blade.Position - hrp.Position).Magnitude
                        if dist <= 10 then
                            monConn:Disconnect()
                            _doDodge(blade)
                        end
                    end)
                end)
            end)
        end

 CreateAuroraToggle(leftColumn, "Knife Dodge (dodge thrown knife)", function(on)
            _kDodgeEnabled = on
            if on then
                _startKnifeDodge()
            else
                if _kDodgeConn then pcall(function() _kDodgeConn:Disconnect() end); _kDodgeConn = nil end
            end
        end, false)
    end
end

function CreateMainUI_ResearchFacility_DISABLED()
    CreateSection(rightColumn, "", "RESEARCH FACILITY AUTO", Color3.fromRGB(214, 116, 23))

    local rfInfoLbl = Instance.new("TextLabel", rightColumn)
    rfInfoLbl.Size = UDim2.new(1, -10, 0, 36)
    rfInfoLbl.BackgroundTransparency = 1
    rfInfoLbl.Text = "Detecta Research Facility y activa TP automatico + auto-click en objetos interactivos (F key)"
    rfInfoLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    rfInfoLbl.TextSize = 9
    rfInfoLbl.TextColor3 = Color3.fromRGB(255, 196, 66)
    rfInfoLbl.TextWrapped = true
    rfInfoLbl.TextXAlignment = Enum.TextXAlignment.Left
    rfInfoLbl.ZIndex = 11

    -- Status del mapa
    local mapStatusLbl = Instance.new("TextLabel", rightColumn)
    mapStatusLbl.Size = UDim2.new(1, -10, 0, 22)
    mapStatusLbl.BackgroundColor3 = Color3.fromRGB(  3,   8,  18)
    mapStatusLbl.BackgroundTransparency = 0.3
    mapStatusLbl.BorderSizePixel = 0
    mapStatusLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    mapStatusLbl.TextSize = 11
    mapStatusLbl.TextColor3 = Color3.fromRGB(180, 180, 200)
    mapStatusLbl.TextXAlignment = Enum.TextXAlignment.Center
    mapStatusLbl.Text = "Mapa: no detectado"
    mapStatusLbl.ZIndex = 12
    Instance.new("UICorner", mapStatusLbl).CornerRadius = UDim.new(0, 6)

    -- Actualizar status del mapa en tiempo real
    task.spawn(function()
        while mapStatusLbl and mapStatusLbl.Parent do
            local isRF = _rfDetectMap()
            mapStatusLbl.Text = isRF and " Research Facility detectado" or " Mapa: no es Research Facility"
            mapStatusLbl.TextColor3 = isRF and Color3.fromRGB(250, 155, 38) or Color3.fromRGB(63, 63, 63)
            task.wait(2)
        end
    end)

    -- Cooldown slider
    CreateSlider(rightColumn, "Cooldown TP entre spots (seg)", 1, 20, 3, function(v)
        _rfState.tpCooldown = v
    end)

    -- Toggle Auto TP a spots
    CreateAuroraToggle(rightColumn, "Auto TP a Spots (F)", function(on)
        _rfState.tpEnabled = on
        if _rfState.fConn then
            pcall(function() _rfState.fConn:Disconnect() end)
            _rfState.fConn = nil
        end
        if on then
            CreateCustomNotification("RF AUTO", "Auto TP ON", 2)
            local _rfTick2 = 0
            _rfState.fConn = RunService.Heartbeat:Connect(function(dt)
                if not _rfState.tpEnabled then return end
                _rfTick2 = _rfTick2 + dt
                if _rfTick2 < (_rfState.tpCooldown or 3) then return end
                _rfTick2 = 0
                if not _rfDetectMap() then return end
                local char = LocalPlayer.Character
                local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local spots = _rfGetInteractables()
                if #spots == 0 then return end
                -- TP al spot mas cercano no visitado recientemente
                local now = tick()
                local best, bestD = nil, math.huge
                for _, s in ipairs(spots) do
                    local d = (hrp.Position - s.pos).Magnitude
                    if d < bestD then bestD = d; best = s end
                end
                if best then
                    pcall(function()
                        hrp.CFrame = CFrame.new(best.pos + Vector3.new(0, 3, 0))
                    end)
                    task.wait(0.15)
                    pcall(function() _rfFirePP(best.pp) end)
                end
            end)
        else
            CreateCustomNotification("RF AUTO", "Auto TP OFF", 2)
        end
    end, _rfState.tpEnabled)

    -- Toggle Auto Click (fire all ProximityPrompts F/E sin TP)
    CreateAuroraToggle(rightColumn, "Auto Click Objetos (F/E)", function(on)
        _rfState.autoClick = on
        if _rfState.clickConn then
            pcall(function() _rfState.clickConn:Disconnect() end)
            _rfState.clickConn = nil
        end
        if on then
            CreateCustomNotification("RF CLICK", "Auto Click ON", 2)
            local _ckTick = 0
            _rfState.clickConn = RunService.Heartbeat:Connect(function(dt)
                if not _rfState.autoClick then return end
                _ckTick = _ckTick + dt
                if _ckTick < 1.5 then return end
                _ckTick = 0
                if not _rfDetectMap() then return end
                local char = LocalPlayer.Character
                local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                for _, s in ipairs(_rfGetInteractables()) do
                    if (hrp.Position - s.pos).Magnitude < 12 then
                        pcall(function() _rfFirePP(s.pp) end)
                    end
                end
            end)
        else
            CreateCustomNotification("RF CLICK", "Auto Click OFF", 2)
        end
    end, _rfState.autoClick)

    -- Boton manual: TP al spot mas cercano ahora
    CreateButton(rightColumn, "TP al Spot Mas Cercano", Color3.fromRGB(214, 116, 23), function()
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then CreateCustomNotification("RF", "Sin personaje", 2); return end
        if not _rfDetectMap() then CreateCustomNotification("RF", "No es Research Facility", 2); return end
        local spots = _rfGetInteractables()
        if #spots == 0 then CreateCustomNotification("RF", "No hay spots detectados", 2); return end
        local best, bestD = nil, math.huge
        for _, s in ipairs(spots) do
            local d = (hrp.Position - s.pos).Magnitude
            if d < bestD then bestD = d; best = s end
        end
        if best then
            pcall(function() hrp.CFrame = CFrame.new(best.pos + Vector3.new(0, 3, 0)) end)
            task.wait(0.2)
            pcall(function() _rfFirePP(best.pp) end)
            CreateCustomNotification("RF", "TP + click ejecutado", 2)
        end
    end)
end





