-- ==================================================================
-- KNIFE DODGE -- Esquiva automatico al knife lanzado
-- ==================================================================
function CreateMainUI_KnifeDodge()
    -- Guard: evita duplicar los toggles si la funcion se llama mas de una vez
    if _G._infoSectionCreated then return end
    _G._infoSectionCreated = true

    -- Reemplazado por panel de informacion MS/FPS
    CreateSection(leftColumn, "", "INFORMATION", ThemeColors.Accent)

    local _infoEnabled = false
    local _fpsEnabled  = false
    local _msEnabled   = false
    local _infoGui     = nil
    local _infoFrame   = nil
    local _infoFpsLbl  = nil
    local _infoMsLbl   = nil
    local _infoHbConn  = nil

    local function _ensureGui()
        if _infoGui and _infoGui.Parent then return _infoGui end
        _infoGui = game:GetService("CoreGui"):FindFirstChild("OD_InfoDisplay")
        if _infoGui then return _infoGui end
        _infoGui = Instance.new("ScreenGui")
        _infoGui.Name = "OD_InfoDisplay"; _infoGui.ResetOnSpawn = false
        _infoGui.DisplayOrder = 9997; _infoGui.IgnoreGuiInset = true
        pcall(function() _infoGui.Parent = game:GetService("CoreGui") end)
        if not _infoGui.Parent then _infoGui.Parent = LocalPlayer:WaitForChild("PlayerGui") end
        return _infoGui
    end

    local function _buildFrame()
        if _infoFrame and _infoFrame.Parent then return end
        local sg = _ensureGui()
        -- Limpiar cualquier InfoHUD residual de ejecuciones anteriores
        local oldHUD = sg:FindFirstChild("InfoHUD")
        if oldHUD then pcall(function() oldHUD:Destroy() end) end

        -- ==============================================================
        -- RECTANGULO PRINCIPAL -- estilo compacto con borde dorado
        -- Fondo oscuro semitransparente, bordes amarillo/dorado,
        -- esquinas levemente redondeadas, layout vertical, arrastrable
        -- ==============================================================
        _infoFrame = Instance.new("Frame", sg)
        _infoFrame.Name                  = "InfoHUD"
        _infoFrame.Size                  = UDim2.new(0, 90, 0, 40)
        _infoFrame.Position              = UDim2.new(0, 12, 0, 12)
        _infoFrame.AnchorPoint           = Vector2.new(0, 0)
        _infoFrame.BackgroundColor3      = Color3.fromRGB(  3,   8,  18)  -- negro hub
        _infoFrame.BackgroundTransparency = 0.15
        _infoFrame.BorderSizePixel       = 0
        _infoFrame.ZIndex                = 50
        _infoFrame.Active                = true
        Instance.new("UICorner", _infoFrame).CornerRadius = UDim.new(0, 6)

        -- Borde shimmer del hub
        local stroke = Instance.new("UIStroke", _infoFrame)
        stroke.Color            = ThemeColors and ThemeColors.Primary or Color3.fromRGB(200, 200, 200)
        stroke.Thickness        = 2
        stroke.ApplyStrokeMode  = Enum.ApplyStrokeMode.Border
        stroke.Transparency     = 0.05
        local _infoGrad = Instance.new("UIGradient", stroke)
        _infoGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,    Color3.fromRGB(220, 220, 220)),
            ColorSequenceKeypoint.new(0.33, Color3.fromRGB(255, 200, 120)),
            ColorSequenceKeypoint.new(0.66, Color3.fromRGB(  3,   8,  18)),
            ColorSequenceKeypoint.new(1,    Color3.fromRGB(220, 220, 220)),
        })
        RegisterShimmer(_infoGrad, 60, 0)

        -- Padding interno
        local pad = Instance.new("UIPadding", _infoFrame)
        pad.PaddingLeft   = UDim.new(0, 6)
        pad.PaddingRight  = UDim.new(0, 6)
        pad.PaddingTop    = UDim.new(0, 4)
        pad.PaddingBottom = UDim.new(0, 4)

        -- Layout vertical (FPS arriba, Ping abajo)
        local layout = Instance.new("UIListLayout", _infoFrame)
        layout.FillDirection        = Enum.FillDirection.Vertical
        layout.VerticalAlignment    = Enum.VerticalAlignment.Top
        layout.HorizontalAlignment  = Enum.HorizontalAlignment.Left
        layout.Padding              = UDim.new(0, 2)
        layout.SortOrder            = Enum.SortOrder.LayoutOrder

        -- Label FPS -- texto verde, bold
        _infoFpsLbl = Instance.new("TextLabel", _infoFrame)
        _infoFpsLbl.Name                 = "FPS"
        _infoFpsLbl.Size                 = UDim2.new(1, 0, 0, 14)
        _infoFpsLbl.LayoutOrder          = 1
        _infoFpsLbl.BackgroundTransparency = 1
        _infoFpsLbl.ZIndex               = 51
        _infoFpsLbl.FontFace             = Font.fromEnum(Enum.Font.GothamBold)
        _infoFpsLbl.TextSize             = 12
        _infoFpsLbl.TextColor3           = Color3.fromRGB(200, 200, 200)  -- blanco gris
        _infoFpsLbl.Text                 = "FPS: --"
        _infoFpsLbl.TextXAlignment       = Enum.TextXAlignment.Left
        _infoFpsLbl.TextYAlignment       = Enum.TextYAlignment.Center
        _infoFpsLbl.RichText             = false

        -- Label Ping -- texto blanco/gris claro
        _infoMsLbl = Instance.new("TextLabel", _infoFrame)
        _infoMsLbl.Name                  = "MS"
        _infoMsLbl.Size                  = UDim2.new(1, 0, 0, 14)
        _infoMsLbl.LayoutOrder           = 2
        _infoMsLbl.BackgroundTransparency = 1
        _infoMsLbl.ZIndex                = 51
        _infoMsLbl.FontFace              = Font.fromEnum(Enum.Font.GothamBold)
        _infoMsLbl.TextSize              = 12
        _infoMsLbl.TextColor3            = Color3.fromRGB(255, 200, 120) -- dorado hub
        _infoMsLbl.Text                  = "Ping: --ms"
        _infoMsLbl.TextXAlignment        = Enum.TextXAlignment.Left
        _infoMsLbl.TextYAlignment        = Enum.TextYAlignment.Center
        _infoMsLbl.RichText              = false

        -- -- DRAG: arrastrar con mouse/touch -------------------------
        local _dragging   = false
        local _dragStart  = nil
        local _frameStart = nil

        _infoFrame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                _dragging   = true
                _dragStart  = input.Position
                _frameStart = _infoFrame.Position
            end
        end)
        _infoFrame.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
                _dragging = false
            end
        end)
        game:GetService("UserInputService").InputChanged:Connect(function(input)
            if not _dragging then return end
            if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end
            if not _infoFrame or not _infoFrame.Parent then _dragging = false; return end
            local delta = input.Position - _dragStart
            local vp2   = workspace.CurrentCamera.ViewportSize
            local newX  = math.clamp(_frameStart.X.Offset + delta.X, 0, vp2.X - 90)
            local newY  = math.clamp(_frameStart.Y.Offset + delta.Y, 0, vp2.Y - 40)
            _infoFrame.Position = UDim2.new(
                _frameStart.X.Scale, newX,
                _frameStart.Y.Scale, newY
            )
        end)

        -- Loop actualizacion
        -- FIX: desconectar conexion previa si existe antes de crear una nueva
        if _infoHbConn then pcall(function() _infoHbConn:Disconnect() end); _infoHbConn = nil end
        local _hbT = 0
        local _lastDt = 1/60
        _infoHbConn = RunService.Heartbeat:Connect(function(dt)
            _lastDt = dt
            _hbT = _hbT + 1; if _hbT < 20 then return end; _hbT = 0  -- LAG FIX: 3Hz suficiente para display FPS/ping
            if not _infoFrame or not _infoFrame.Parent then return end
            local showFps = _infoEnabled or _fpsEnabled
            local showMs  = _infoEnabled or _msEnabled
            -- OPT: dt ya es el tiempo del ultimo frame -- sin Wait() bloqueante
            local fps = math.floor(1 / math.max(_lastDt, 0.001))
            local ms  = math.floor(LocalPlayer:GetNetworkPing() * 1000)
            if _infoFpsLbl then
                _infoFpsLbl.Text    = showFps and ("FPS: " .. fps) or ""
                _infoFpsLbl.Visible = showFps
            end
            if _infoMsLbl then
                _infoMsLbl.Text    = showMs and ("Ping: " .. ms .. "ms") or ""
                _infoMsLbl.Visible = showMs
                _infoMsLbl.TextColor3 = ms < 80 and Color3.fromRGB(247, 151, 36)
                    or ms < 150 and ThemeColors.Primary or Color3.fromRGB(255,80,80)
            end
        end)
    end

    local function _tryDestroy()
        if _infoEnabled or _fpsEnabled or _msEnabled then return end
        if _infoHbConn then pcall(function() _infoHbConn:Disconnect() end); _infoHbConn = nil end
        if _infoFrame and _infoFrame.Parent then
            TweenService:Create(_infoFrame, TweenInfo.new(0.4, Enum.EasingStyle.Sine, Enum.EasingDirection.In),
                {Size = UDim2.new(0,0,0,0), BackgroundTransparency=1}):Play()
            task.delay(0.45, function()
                pcall(function() if _infoFrame then _infoFrame:Destroy(); _infoFrame = nil end end)
            end)
        end
    end

    CreateAuroraToggle(leftColumn, "Information MS/FPS", function(on)
        _infoEnabled = on
        if on then _buildFrame(); CreateCustomNotification("INFO", "MS + FPS activos", 2)
        else _tryDestroy() end
    end, false)

    CreateAuroraToggle(leftColumn, "Solo FPS", function(on)
        _fpsEnabled = on
        if on then _buildFrame(); CreateCustomNotification("INFO", "FPS activo", 1.5)
        else _tryDestroy() end
    end, false)

    CreateAuroraToggle(leftColumn, "Solo MS (ping)", function(on)
        _msEnabled = on
        if on then _buildFrame(); CreateCustomNotification("INFO", "MS activo", 1.5)
        else _tryDestroy() end
    end, false)
end


function CreateMainUI_FakeAvatarMain()
    local S = MainSystem.state
 CreateSection(leftColumn, "", "FAKE AVATAR", ThemeColors.Aurora1)

    local function _doFakeHeadless(char, enable)
        if not char then return end
        local head = char:FindFirstChild("Head")
        if not head then return end
        if enable then
            S.fakeHeadless.originalTransparency = {}
            for _, obj in pairs(head:GetDescendants()) do
                if obj:IsA("BasePart") or obj:IsA("MeshPart") or obj:IsA("Decal") then
                    S.fakeHeadless.originalTransparency[obj] = obj.Transparency
                    obj.Transparency = 1
                end
            end
            head.Transparency = 1
        else
            for obj, trans in pairs(S.fakeHeadless.originalTransparency) do
                if obj and obj.Parent then obj.Transparency = trans end
            end
            S.fakeHeadless.originalTransparency = {}
            head.Transparency = 0
        end
    end

    local function _doFakeKorblox(char, enable)
        if not char then return end
        local parts = {
            char:FindFirstChild("LeftUpperLeg") or char:FindFirstChild("Left Leg"),
            char:FindFirstChild("LeftLowerLeg"),
            char:FindFirstChild("LeftFoot"),
        }
        if enable then
            S.fakeKorblox.originalTransparency = {}
            for _, part in pairs(parts) do
                if part then
                    S.fakeKorblox.originalTransparency[part] = part.Transparency
                    part.Transparency = 1
                end
            end
        else
            for part, trans in pairs(S.fakeKorblox.originalTransparency) do
                if part and part.Parent then part.Transparency = trans end
            end
            S.fakeKorblox.originalTransparency = {}
        end
    end

    -- Toggle Fake Headless
 CreateToggle(leftColumn, "Fake Headless", function(enabled)
        S.fakeHeadless.enabled = enabled
        _doFakeHeadless(LocalPlayer.Character, enabled)
 CreateCustomNotification("FAKE AVATAR",
            enabled and "Headless ON -- head invisible" or "Headless OFF", 3)
    end, S.fakeHeadless and S.fakeHeadless.enabled or false)

    -- Boton para aplicar de nuevo si el avatar recarga
 CreateButton(leftColumn, "Re-apply Headless", ThemeColors.Aurora1, function()
        PlaySound()
        _doFakeHeadless(LocalPlayer.Character, true)
 CreateCustomNotification("FAKE AVATAR", "Headless re-aplicado", 2)
    end)

    -- Toggle Fake Korblox
 CreateToggle(leftColumn, "Fake Korblox", function(enabled)
        S.fakeKorblox.enabled = enabled
        _doFakeKorblox(LocalPlayer.Character, enabled)
 CreateCustomNotification("FAKE AVATAR",
            enabled and "Korblox ON -- left leg invisible" or "Korblox OFF", 3)
    end, S.fakeKorblox and S.fakeKorblox.enabled or false)

    -- Boton para aplicar de nuevo
 CreateButton(leftColumn, "Re-apply Korblox", ThemeColors.Aurora1, function()
        PlaySound()
        _doFakeKorblox(LocalPlayer.Character, true)
 CreateCustomNotification("FAKE AVATAR", "Korblox re-aplicado", 2)
    end)

    -- Reconectar al respawnear
    if not _G._fakeAvatarMainCharConn then
        _G._fakeAvatarMainCharConn = LocalPlayer.CharacterAdded:Connect(function(char)
            task.wait(0.6)
            if S.fakeHeadless and S.fakeHeadless.enabled then _doFakeHeadless(char, true) end
            if S.fakeKorblox  and S.fakeKorblox.enabled  then _doFakeKorblox(char, true)  end
        end)
    end
end

-- FIX: CreateBorderedSection definida globalmente para que CreateMainTab y otras tabs puedan usarla
-- v2: aurora header animations -- shimmer text color + pulsing stroke glow + scan line sweep
function CreateBorderedSection(parent, title)
    local wrapper = Instance.new("Frame", parent)
    wrapper.Size = UDim2.new(1, -6, 0, 0)
    wrapper.BackgroundColor3 = ThemeColors.Background
    wrapper.BackgroundTransparency = 1  -- TRANSPARENCIA TOTAL: fondo del juego visible
    wrapper.BorderSizePixel = 0
    wrapper.AutomaticSize = Enum.AutomaticSize.Y
    wrapper.ZIndex = 11
    Instance.new("UICorner", wrapper).CornerRadius = UDim.new(0, 8)

    -- Animated border stroke -- UIGradient rotates via shimmer manager
    local wStroke = Instance.new("UIStroke", wrapper)
    wStroke.Thickness = 1.5
    wStroke.Transparency = 0.0
    wStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local wStrokeGrad = Instance.new("UIGradient", wStroke)
    -- Aurora palette: teal -> cyan -> purple -> teal
    local _AC1 = ThemeColors.Primary    -- celeste principal
    local _AC2 = ThemeColors.Accent    -- cyan brillante
    local _AC3 = ThemeColors.Secondary   -- morado aurora
    local _AC4 = ThemeColors.Primary   -- celeste medio
    wStrokeGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   _AC1),
        ColorSequenceKeypoint.new(0.25, _AC2),
        ColorSequenceKeypoint.new(0.5,  _AC3),
        ColorSequenceKeypoint.new(0.75, _AC4),
        ColorSequenceKeypoint.new(1,   _AC1),
    })
    -- Register into global shimmer loop (unique offset per section)
    RegisterShimmer(wStrokeGrad, 90, math.random(0, 359))

    if title and title ~= "" then
        local header = Instance.new("Frame", wrapper)
        header.Size = UDim2.new(1, 0, 0, 42)
        header.BackgroundColor3 = ThemeColors.Primary
        header.BackgroundTransparency = 0.82
        header.BorderSizePixel = 0
        header.ZIndex = 12
        header.ClipsDescendants = true
        Instance.new("UICorner", header).CornerRadius = UDim.new(0, 8)

        -- Bottom-half fill to square off the lower corners of the header bar
        local sq = Instance.new("Frame", header)
        sq.Size = UDim2.new(1, 0, 0.5, 0)
        sq.Position = UDim2.new(0, 0, 0.5, 0)
        sq.BackgroundColor3 = ThemeColors.Primary
        sq.BackgroundTransparency = 0.82
        sq.BorderSizePixel = 0
        sq.ZIndex = 12

        -- -- SCAN LINE: horizontal shimmer sweep across header background --
        local scanLine = Instance.new("Frame", header)
        scanLine.Size = UDim2.new(0, 60, 1, 0)
        scanLine.Position = UDim2.new(-0.4, 0, 0, 0)
        scanLine.BackgroundColor3 = ThemeColors.TextPrimary
        scanLine.BackgroundTransparency = 0.82
        scanLine.BorderSizePixel = 0
        scanLine.ZIndex = 13
        local scanGrad = Instance.new("UIGradient", scanLine)
        scanGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   Color3.fromRGB(0, 0, 0)),
            ColorSequenceKeypoint.new(0.3, ThemeColors.TextPrimary),
            ColorSequenceKeypoint.new(0.7, ThemeColors.TextPrimary),
            ColorSequenceKeypoint.new(1,   Color3.fromRGB(0, 0, 0)),
        })
        scanGrad.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0,   1),
            NumberSequenceKeypoint.new(0.3, 0.6),
            NumberSequenceKeypoint.new(0.7, 0.6),
            NumberSequenceKeypoint.new(1,   1),
        })
        -- Animate scan line: sweeps left-to-right every ~2.4s, pauses, repeats
        task.spawn(function()
            while header and header.Parent do
                TweenService:Create(scanLine, TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {
                    Position = UDim2.new(1.1, 0, 0, 0)
                }):Play()
                task.wait(2.4)
                scanLine.Position = UDim2.new(-0.4, 0, 0, 0)
                task.wait(0.3)
            end
        end)

        -- -- TITLE LABEL with animated text color (aurora cycle) --
        local titleLbl = Instance.new("TextLabel", header)
        titleLbl.Size = UDim2.new(1, 0, 1, 0)
        titleLbl.Position = UDim2.new(0, 0, 0, 0)
        titleLbl.BackgroundTransparency = 1
        titleLbl.Text = title
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.TextSize = 18
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        titleLbl.TextXAlignment = Enum.TextXAlignment.Center
        titleLbl.TextYAlignment = Enum.TextYAlignment.Center
        titleLbl.ZIndex = 14

        -- UIStroke on the text label: glows with aurora color, pulses opacity
        local txtStroke = Instance.new("UIStroke", titleLbl)
        txtStroke.Color = _AC2
        txtStroke.Thickness = 1.2
        txtStroke.Transparency = 0.3

        -- Color fijo del hub (sin loop RGB animado)
        titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        txtStroke.Color     = ThemeColors.Primary
        txtStroke.Transparency = 0.3
    end

    local section = Instance.new("Frame", wrapper)
    section.Size = UDim2.new(1, 0, 0, 0)
    section.BackgroundTransparency = 1
    section.BorderSizePixel = 0
    section.AutomaticSize = Enum.AutomaticSize.Y
    section.ZIndex = 12
    if title and title ~= "" then
        section.Position = UDim2.new(0, 0, 0, 44)
    end
    local padding = Instance.new("UIPadding", section)
    padding.PaddingTop = UDim.new(0, 2)
    padding.PaddingBottom = UDim.new(0, 2)
    padding.PaddingLeft = UDim.new(0, 2)
    padding.PaddingRight = UDim.new(0, 2)
    local layout = Instance.new("UIListLayout", section)
    layout.Padding = UDim.new(0, 0)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    local wPad = Instance.new("UIPadding", wrapper)
    wPad.PaddingBottom = UDim.new(0, 2)
    _currentMainSectionFrame = section
    return section
end

function CreateMainTab()
    ClearContent()
    -- OPT: limpiar conexiones del tab anterior para evitar duplicados al volver
    pcall(function()
        local _mp = _G._mainProt
        if _mp then
            if _mp.afConn     then _mp.afConn:Disconnect();     _mp.afConn     = nil end
            if _mp.avConn     then _mp.avConn:Disconnect();     _mp.avConn     = nil end
            if _mp.avSafeConn then _mp.avSafeConn:Disconnect(); _mp.avSafeConn = nil end
            if _mp.afkThread  then pcall(function() pcall(function() coroutine.close(_mp.afkThread) end) end); _mp.afkThread = nil end
        end
        local _sp = _G._swimProt
        if _sp then
            if _sp.swConn then _sp.swConn:Disconnect(); _sp.swConn = nil end
            if _sp.pjConn then _sp.pjConn:Disconnect(); _sp.pjConn = nil end
        end
        if _killAllConn     then _killAllConn:Disconnect();     _killAllConn     = nil end
        if _gFarmConn       then _gFarmConn:Disconnect();       _gFarmConn       = nil end
        if _killKnifeConn   then _killKnifeConn:Disconnect();   _killKnifeConn   = nil end
        if _afkXPLobbyConn  then _afkXPLobbyConn:Disconnect();  _afkXPLobbyConn  = nil end
    end)
    _currentMainSectionFrame = nil
    CreateMainColumns()

    local RunService    = RunService
    local UserInput     = UserInputService
    local Lighting      = Lighting

    -- ============================================
    -- BOTON RESET ALL TOGGLES
    -- ============================================
    do
        local _resetAllContainer = Instance.new("Frame", leftColumn)
        _resetAllContainer.Size = UDim2.new(1, -6, 0, 52)
        _resetAllContainer.BackgroundTransparency = 1
        _resetAllContainer.BorderSizePixel = 0
        _resetAllContainer.ZIndex = 12

        local _resetAllBtn = Instance.new("TextButton", _resetAllContainer)
        _resetAllBtn.Size = UDim2.new(1, -6, 1, -6)
        _resetAllBtn.Position = UDim2.new(0, 3, 0, 3)
        _resetAllBtn.BackgroundColor3 = Color3.fromRGB(4, 14, 28)
        _resetAllBtn.BackgroundTransparency = 0.18
        _resetAllBtn.BorderSizePixel = 0
        _resetAllBtn.AutoButtonColor = false
        _resetAllBtn.ZIndex = 13
        -- Estilo USE: rectangular glassmorphism
        Instance.new("UICorner", _resetAllBtn).CornerRadius = UDim.new(0, 6)

        -- Gradiente glassmorphism violeta/oscuro
        local _rabGrad = Instance.new("UIGradient", _resetAllBtn)
        _rabGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   Color3.fromRGB(20, 8, 40)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(10, 4, 24)),
            ColorSequenceKeypoint.new(1,   Color3.fromRGB(20, 8, 40)),
        })
        _rabGrad.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0,   0.30),
            NumberSequenceKeypoint.new(0.5, 0.20),
            NumberSequenceKeypoint.new(1,   0.30),
        })
        _rabGrad.Rotation = 90

        -- Borde neon cian brillante (estilo USE)
        local _rabStroke = Instance.new("UIStroke", _resetAllBtn)
        _rabStroke.Color = Color3.fromRGB(0, 210, 240)
        _rabStroke.Thickness = 1.8
        _rabStroke.Transparency = 0.10
        _rabStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        local _rabStrokeGrad = Instance.new("UIGradient", _rabStroke)
        _rabStrokeGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   Color3.fromRGB(180, 60, 255)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0,  220, 255)),
            ColorSequenceKeypoint.new(1,   Color3.fromRGB(180, 60, 255)),
        })
        _rabStrokeGrad.Rotation = 90

        -- Sin icono emoji (eliminado por solicitud)
        local _rabIcon = Instance.new("TextLabel", _resetAllBtn)
        _rabIcon.Size = UDim2.new(0, 0, 0, 0)
        _rabIcon.Position = UDim2.new(0, 0, 0, 0)
        _rabIcon.BackgroundTransparency = 1
        _rabIcon.Text = ""
        _rabIcon.TextColor3 = Color3.fromRGB(220, 180, 255)
        _rabIcon.Font = Enum.Font.GothamBold
        _rabIcon.TextSize = 1
        _rabIcon.TextXAlignment = Enum.TextXAlignment.Left
        _rabIcon.ZIndex = 15

        -- Texto principal centrado (sin icono)
        local _rabLbl = Instance.new("TextLabel", _resetAllBtn)
        _rabLbl.Size = UDim2.new(1, -16, 1, 0)
        _rabLbl.Position = UDim2.new(0, 8, 0, 0)
        _rabLbl.BackgroundTransparency = 1
        _rabLbl.Text = "RESET ALL TOGGLES"
        _rabLbl.TextColor3 = Color3.fromRGB(220, 200, 255)
        _rabLbl.Font = Enum.Font.GothamBold
        _rabLbl.TextSize = 13
        _rabLbl.TextXAlignment = Enum.TextXAlignment.Center
        _rabLbl.ZIndex = 14

        -- Glow sutil en el texto
        local _rabTxtStroke = Instance.new("UIStroke", _rabLbl)
        _rabTxtStroke.Color = Color3.fromRGB(0, 210, 255)
        _rabTxtStroke.Thickness = 1.0
        _rabTxtStroke.Transparency = 0.4

        -- Hover estilo USE
        _resetAllBtn.MouseEnter:Connect(function()
            TweenService:Create(_resetAllBtn, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(8, 20, 45), BackgroundTransparency = 0.05}):Play()
            TweenService:Create(_rabStroke, TweenInfo.new(0.15), {Color = Color3.fromRGB(0, 240, 255), Thickness = 2.5, Transparency = 0.0}):Play()
            TweenService:Create(_rabLbl, TweenInfo.new(0.15), {TextColor3 = Color3.fromRGB(255, 255, 255)}):Play()
        end)
        _resetAllBtn.MouseLeave:Connect(function()
            TweenService:Create(_resetAllBtn, TweenInfo.new(0.18), {BackgroundColor3 = Color3.fromRGB(4, 14, 28), BackgroundTransparency = 0.18}):Play()
            TweenService:Create(_rabStroke, TweenInfo.new(0.18), {Color = Color3.fromRGB(0, 210, 240), Thickness = 1.8, Transparency = 0.10}):Play()
            TweenService:Create(_rabLbl, TweenInfo.new(0.18), {TextColor3 = Color3.fromRGB(220, 200, 255)}):Play()
        end)

        -- Click: apagar todos los toggles y cortar sus conexiones
        _resetAllBtn.Activated:Connect(function()
            -- Flash visual: pulso cian brillante estilo USE
            TweenService:Create(_resetAllBtn, TweenInfo.new(0.06), {BackgroundColor3 = Color3.fromRGB(0, 160, 200), BackgroundTransparency = 0.05}):Play()
            TweenService:Create(_rabStroke, TweenInfo.new(0.06), {Color = Color3.fromRGB(255, 255, 255), Thickness = 3}):Play()
            task.wait(0.12)
            TweenService:Create(_resetAllBtn, TweenInfo.new(0.25), {BackgroundColor3 = Color3.fromRGB(4, 14, 28), BackgroundTransparency = 0.18}):Play()
            TweenService:Create(_rabStroke, TweenInfo.new(0.25), {Color = Color3.fromRGB(0, 210, 240), Thickness = 1.8}):Play()

            local _count = 0
            local _ts = _G._toggleStates or {}
            local _tc = _G._toggleCallbacks or {}

            -- 1) Apagar todos los toggles via callback
            for nombre, estado in pairs(_ts) do
                if estado == true then
                    _count = _count + 1
                    _G._toggleStates[nombre] = false
                    if _tc[nombre] then pcall(_tc[nombre], false) end
                end
            end

            -- 2) Cortar conexiones de combat
            if CombatState then
                pcall(function() if CombatState.autoShootConnection  then CombatState.autoShootConnection:Disconnect();  CombatState.autoShootConnection  = nil end end)
                pcall(function() if CombatState.autoReloadConnection then CombatState.autoReloadConnection:Disconnect(); CombatState.autoReloadConnection = nil end end)
                pcall(function() if CombatState.gunConnection        then CombatState.gunConnection:Disconnect();        CombatState.gunConnection        = nil end end)
                pcall(function() if CombatState.trackingConnection   then CombatState.trackingConnection:Disconnect();   CombatState.trackingConnection   = nil end end)
                CombatState.autoShootEnabled = false; CombatState.autoReloadEnabled = false
                CombatState.autoEquipEnabled = false; CombatState.knifeShootEnabled = false
            end
            if CombatTabState then
                pcall(function() if CombatTabState.shootPickConn then CombatTabState.shootPickConn:Disconnect(); CombatTabState.shootPickConn = nil end end)
                pcall(function() if CombatTabState.autoShootMurderConn then CombatTabState.autoShootMurderConn:Disconnect(); CombatTabState.autoShootMurderConn = nil end end)
                CombatTabState.shootPickEnabled = false; CombatTabState.autoShootMurderEnabled = false
                CombatTabState.silentAimEnabled = false; CombatTabState.knifeShootEnabled = false
            end
            if AimlockState then pcall(function() if AimlockState.conn then AimlockState.conn:Disconnect(); AimlockState.conn = nil end end); AimlockState.enabled = false end
            if KnifeSAState then pcall(_KnifeSA_deactivate); KnifeSAState.enabled = false end
            pcall(_TK_stopAll)
            pcall(StopFlying); pcall(DisableNoclip)
            pcall(StopAutoFarm); pcall(StopShootSheriff); pcall(StopShootMurder)
            pcall(StopKillAtKnife); pcall(StopFarmXPSheriff)
            pcall(StopAFKFarmLobby); pcall(StopAFKXPLobby)
            pcall(StopKillAllMurder); pcall(StopFlingSystem)
            if Settings and Settings.connections then
                pcall(function() if Settings.connections.fly then Settings.connections.fly:Disconnect(); Settings.connections.fly = nil end end)
                pcall(function() if Settings.connections.noclip then Settings.connections.noclip:Disconnect(); Settings.connections.noclip = nil end end)
            end

            -- 3) Actualizar visuals de knobs
            if _G._toggleApplyStates then
                for nombre, applyFn in pairs(_G._toggleApplyStates) do
                    if _G._toggleStates[nombre] == false then pcall(applyFn, false, false) end
                end
            end

            -- 4) Guardar estado limpio
            pcall(_saveConfig)
            _G._forceInstanceTick = true
            if _vcRefreshAll then task.defer(_vcRefreshAll) end

            local msg = _count > 0
                and ("? " .. _count .. " toggle" .. (_count == 1 and "" or "s") .. " desactivado" .. (_count == 1 and "" or "s"))
                or  "? Sin toggles activos"
            CreateCustomNotification("RESET", msg, 2.5)
        end)

        -- Animacion de pulso del borde estilo USE (cian/violeta)
        task.spawn(function()
            while _resetAllBtn and _resetAllBtn.Parent do
                TweenService:Create(_rabStroke, TweenInfo.new(1.0, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Transparency = 0.0, Thickness = 2.2}):Play()
                task.wait(1.0)
                TweenService:Create(_rabStroke, TweenInfo.new(1.0, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Transparency = 0.40, Thickness = 1.8}):Play()
                task.wait(1.0)
            end
        end)
    end

    -- ============================================
    -- PROTECTIONS
    -- ============================================
    do
        local _protSection = CreateBorderedSection(leftColumn, " PROTECTIONS")

        -- Persistir estado de protecciones en _G
        _G._mainProt = _G._mainProt or {
            afConn = nil, afProtecting = false,
            avConn = nil, avSafeConn = nil, avSafePos = nil,
            afkThread = nil,
        }
        local _mp = _G._mainProt

        -- -- Anti Fling --
        do
            local _afConnFling    = nil
            local _afConnVoid     = nil
            local _afConnPos      = nil
            local _afConnVel      = nil
            local _afLastSafePos  = nil
            local _afOrigSpeed    = nil

            -- Nombres de partes que pertenecen al cuerpo humanoide (nunca al mapa)
            local _CHAR_PARTS = {
                HumanoidRootPart=true, Head=true,
                UpperTorso=true, LowerTorso=true, Torso=true,
                LeftUpperArm=true, LeftLowerArm=true, LeftHand=true,
                RightUpperArm=true, RightLowerArm=true, RightHand=true,
                LeftUpperLeg=true, LeftLowerLeg=true, LeftFoot=true,
                RightUpperLeg=true, RightLowerLeg=true, RightFoot=true,
            }

            local function _enableAntiFling()
                -- OPT: throttle a ~10Hz (cada 6 frames) -- proteccion efectiva sin quemar CPU
                local _afTick = 0
                _afConnFling = _safeConnect(RunService.Stepped, function()
                    _afTick = _afTick + 1
                    if _afTick < 6 then return end
                    _afTick = 0
                    local localCharacter = LocalPlayer.Character
                    if not localCharacter then return end
                    for _, otherPlayer in ipairs(_cachedPlayers) do  -- OPT: cache global
                        if otherPlayer ~= LocalPlayer then
                            local char = otherPlayer.Character
                            if char and char:FindFirstChildOfClass("Humanoid") then
                                for _, part in ipairs(char:GetChildren()) do
                                    if part:IsA("BasePart") and _CHAR_PARTS[part.Name] then
                                        if part.CanCollide then  -- OPT: solo escribir si cambia
                                            pcall(function() part.CanCollide = false end)
                                        end
                                    end
                                end
                            end
                        end
                    end
                end)
            end

            local function _disableAntiFling()
                if _afConnFling then pcall(function() _afConnFling:Disconnect() end); _afConnFling = nil end
                if _afConnVoid  then pcall(function() _afConnVoid:Disconnect()  end); _afConnVoid  = nil end
                if _afConnPos   then pcall(function() _afConnPos:Disconnect()   end); _afConnPos   = nil end
                if _afConnVel   then pcall(function() _afConnVel:Disconnect()   end); _afConnVel   = nil end
            end

            CreateAuroraToggle(_protSection, "Anti Fling", function(on)
                if on then
                    _enableAntiFling()
                    -- [notif removed]
                else
                    _disableAntiFling()
                    -- [notif removed]
                end
            end, false)
        end

        -- -- Anti Void -- OPT: un solo Heartbeat en vez de dos
        CreateAuroraToggle(_protSection, "Anti Void", function(on)
            if _mp.avConn     then pcall(function() _mp.avConn:Disconnect()     end); _mp.avConn     = nil end
            if _mp.avSafeConn then pcall(function() _mp.avSafeConn:Disconnect() end); _mp.avSafeConn = nil end
            if not on then _mp.avSafePos = nil; return end
            -- OPT: un solo loop hace las dos cosas (guarda pos segura + detecta void)
            _mp.avConn = _safeConnect(RunService.Heartbeat, function()
                local char = LocalPlayer.Character; if not char then return end
                local hrp  = char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
                local y = hrp.Position.Y
                if y > -20 then
                    _mp.avSafePos = hrp.CFrame
                elseif y < -150 then
                    local dest = _mp.avSafePos or CFrame.new(hrp.Position.X, 5, hrp.Position.Z)
                    pcall(function() char:PivotTo(dest) end)
                    local bv = Instance.new("BodyVelocity")
                    bv.Name = "_AntiVoidBV"; bv.Velocity = Vector3.zero
                    bv.MaxForce = Vector3.new(1e6, 1e6, 1e6); bv.Parent = hrp
                    _dl(0.2, function() if bv and bv.Parent then bv:Destroy() end end)
                    CreateCustomNotification("ANTI VOID", "Caida detectada -- posicion restaurada", 2)
                end
            end)
        end, _mp.avConn ~= nil)

        -- -- Anti AFK --
        CreateAuroraToggle(_protSection, "Anti AFK", function(on)
            if _mp.afkThread then pcall(function() pcall(function() coroutine.close(_mp.afkThread) end) end); _mp.afkThread = nil end
            if not on then return end
            local vu = game:GetService("VirtualUser")
            _mp.afkThread = _sp(function()
                while _G._mainProt and _mp.afkThread do
                    pcall(function() vu:ClickButton2(Vector2.new(0,0)) end)
                    pcall(function()
                        local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                        if hum then hum:ChangeState(hum:GetState()) end
                    end)
                    _w(25)
                end
            end)
            -- [notif removed]
        end, _mp.afkThread ~= nil)
    end

    -- ============================================
    -- NOCLIP
    -- ============================================
    do
        local _ncSection = CreateBorderedSection(rightColumn, " NOCLIP")

        -- FIX: persistir en _G para sobrevivir cambios de tab
        _G._ncState = _G._ncState or {
            enabled = false, conn = nil,
            origWS  = 16,    origJP = 50,
            frame   = 0,     refresh = 2,  -- OPT: cada 2 frames (~30Hz) suficiente para noclip
            keybind = Enum.KeyCode.N,
            keybindActive = false, keybindConn = nil,
        }
        local _nc          = _G._ncState
        local _ncKeybind       = _nc.keybind
        local _ncKeybindActive = _nc.keybindActive
        local _ncKeybindConn   = _nc.keybindConn
        local _ncBtnSize       = 37
        local _ncBtnGui        = nil
        local _ncBtnRef        = nil   -- referencia al TextButton flotante

        local function _ncOff()
            _nc.enabled = false
            if _nc.conn then _nc.conn:Disconnect(); _nc.conn = nil end
            local c = LocalPlayer.Character; if not c then return end
            for _, p in ipairs(c:GetDescendants()) do
                if p:IsA("BasePart") then pcall(function() p.CanCollide = true end) end
            end
            local hum = c:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function() hum.WalkSpeed = _nc.origWS end)
                pcall(function() hum.JumpPower  = _nc.origJP  end)
            end
            -- Actualizar color del boton flotante si existe
            if _ncBtnRef and _ncBtnRef.Parent then
                _ncBtnRef.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
                _ncBtnRef.BackgroundTransparency = 0.75
                _ncBtnRef.Text = "NC"
            end
        end

        local function _ncOn()
            _ncOff()
            _nc.enabled = true
            local c = LocalPlayer.Character
            if c then
                local hum = c:FindFirstChildOfClass("Humanoid")
                if hum then _nc.origWS = hum.WalkSpeed; _nc.origJP = hum.JumpPower end
            end
            _nc.frame = 0
            local _cachedChar  = LocalPlayer.Character
            local _cachedParts = {}
            if _cachedChar then
                for _, p in ipairs(_cachedChar:GetDescendants()) do
                    if p:IsA("BasePart") then _cachedParts[#_cachedParts + 1] = p end
                end
            end
            -- Stepped es antes de la fisica -- ideal para noclip
            _nc.conn = RunService.Stepped:Connect(function()
                _nc.frame = _nc.frame + 1
                if _nc.frame < _nc.refresh then return end
                _nc.frame = 0
                if not _nc.enabled then return end
                local ch = LocalPlayer.Character; if not ch then return end
                -- Reconstruir cache si el personaje cambio (respawn)
                if ch ~= _cachedChar then
                    _cachedChar = ch; _cachedParts = {}
                    for _, p in ipairs(ch:GetDescendants()) do
                        if p:IsA("BasePart") then _cachedParts[#_cachedParts + 1] = p end
                    end
                end
                for i = 1, #_cachedParts do
                    local p = _cachedParts[i]
                    if p and p.Parent then p.CanCollide = false end
                end
            end)
            -- Actualizar color del boton flotante
            if _ncBtnRef and _ncBtnRef.Parent then
                _ncBtnRef.BackgroundColor3 = Color3.fromRGB( 50, 255, 180)
                _ncBtnRef.Text = "NC "
            end
        end

        -- Al respawn, re-aplicar si estaba activo
        LocalPlayer.CharacterAdded:Connect(function()
            if _nc.enabled then
                _w(0.5)
                _ncOn()
            end
        end)

        -- Toggle principal
        CreateAuroraToggle(_ncSection, "Noclip", function(on)
            if on then _ncOn() else _ncOff() end
        end, false)

        -- Keybind remap: al activar el toggle, espera la proxima tecla presionada y la asigna
        local _ncKeybindLabel = "Noclip (Keybind) [N]"
        local _ncKeybindWaiting = false
        local _ncKeybindListenConn = nil
        CreateAuroraToggle(_ncSection, _ncKeybindLabel, function(on)
            if not on then return end
            if _ncKeybindWaiting then return end
            _ncKeybindWaiting = true
            if not UserInputService.TouchEnabled then CreateCustomNotification("KEYBIND", "Presiona la tecla que queres usar para Noclip...", 3) end
            -- Escuchar la proxima tecla
            if _ncKeybindListenConn then pcall(function() _ncKeybindListenConn:Disconnect() end) end
            _ncKeybindListenConn = UserInput.InputBegan:Connect(function(input, gpe)
                if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
                -- Ignorar teclas de UI
                if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Return then
                    _ncKeybindWaiting = false
                    _sp(function() _G._toggleStates[_ncKeybindLabel] = false end)
                    pcall(function() _ncKeybindListenConn:Disconnect() end)
                    return
                end
                _ncKeybind = input.KeyCode
                _nc.keybind = input.KeyCode  -- FIX: persistir en _G._ncState
                _ncKeybindLabel = "Noclip (Keybind) [" .. tostring(input.KeyCode.Name) .. "]"
                _ncKeybindWaiting = false
                if not UserInputService.TouchEnabled then CreateCustomNotification("KEYBIND", "Noclip -> " .. tostring(input.KeyCode.Name), 2) end
                _sp(function() _G._toggleStates[_ncKeybindLabel] = false end)
                pcall(function() _ncKeybindListenConn:Disconnect() end)
            end)
        end, false)

        -- MOBILE: si es movil, mostrar aviso de que usar el boton bindable
        do
            local _ncIsMobile = (function()
                local ok, res = pcall(function() return UserInputService.TouchEnabled end)
                return ok and res
            end)()
            if _ncIsMobile then
                local _ncMobileTip = Instance.new("TextLabel", _ncSection)
                _ncMobileTip.Size = UDim2.new(1, -8, 0, 32)
                _ncMobileTip.BackgroundColor3 = Color3.fromRGB(80, 15, 25)
                _ncMobileTip.BackgroundTransparency = 0.5
                _ncMobileTip.BorderSizePixel = 0
                _ncMobileTip.Text = "?? Mobile: use the 'Noclip (Button)' below"
                _ncMobileTip.TextColor3 = Color3.fromRGB(255, 175, 188)
                _ncMobileTip.FontFace = Font.fromEnum(Enum.Font.Montserrat)
                _ncMobileTip.TextSize = 10
                _ncMobileTip.TextWrapped = true
                _ncMobileTip.ZIndex = 13
                Instance.new("UICorner", _ncMobileTip).CornerRadius = UDim.new(0, 6)
                local _ncTS = Instance.new("UIStroke", _ncMobileTip)
                _ncTS.Color = Color3.fromRGB(210, 85, 100); _ncTS.Thickness = 1; _ncTS.Transparency = 0.4
            end
        end

        -- Noclip (Keybind Active) -- escucha la tecla N para toggle
        CreateAuroraToggle(_ncSection, "Noclip (Keybind Active)", function(on)
            _ncKeybindActive = on
            _nc.keybindActive = on  -- FIX: persistir
            if _nc.keybindConn then pcall(function() _nc.keybindConn:Disconnect() end); _nc.keybindConn = nil end
            if on then
                _nc.keybindConn = UserInput.InputBegan:Connect(function(input, gpe)
                    if gpe then return end
                    if _G._hubDisableKeybinds then return end
                    if input.KeyCode == _ncKeybind then
                        _nc.enabled = not _nc.enabled
                        if _nc.enabled then
                            _ncOn()
                            _G._toggleStates["Noclip"] = true
                        else
                            _ncOff()
                            _G._toggleStates["Noclip"] = false
                        end
                    end
                end)
            end
        end, _nc.keybindActive)
        -- FIX: restaurar keybind connection si ya estaba activo
        if _nc.keybindActive then
            if _nc.keybindConn then pcall(function() _nc.keybindConn:Disconnect() end); _nc.keybindConn = nil end
            _nc.keybindConn = UserInput.InputBegan:Connect(function(input, gpe)
                if gpe then return end
                if _G._hubDisableKeybinds then return end
                if input.KeyCode == _ncKeybind then
                    _nc.enabled = not _nc.enabled
                    if _nc.enabled then _ncOn(); _G._toggleStates["Noclip"] = true
                    else _ncOff(); _G._toggleStates["Noclip"] = false end
                end
            end)
        end

        -- Noclip Button Size
        CreateSlider(_ncSection, "Noclip Button Size", 10, 100, _ncBtnSize, function(v)
            _ncBtnSize = v
        end)

        -- Noclip (Button) -- boton bindable que activa/desactiva noclip
        local _ncBindGui = nil
        local _ncBindFrame = nil
        CreateAuroraToggle(_ncSection, "Noclip (Button)", function(on)
            if _ncBindGui then pcall(function() _ncBindGui:Destroy() end); _ncBindGui = nil; _ncBindFrame = nil end
            if on then
                _ncBindGui = Instance.new("ScreenGui")
                _ncBindGui.Name           = "NoclipBindableHub"
                _ncBindGui.ResetOnSpawn   = false
                _ncBindGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                _ncBindGui.IgnoreGuiInset = true
                _ncBindGui.DisplayOrder   = 9900
                pcall(function() _ncBindGui.Parent = CoreGui end)
                if not _ncBindGui.Parent then _ncBindGui.Parent = LocalPlayer.PlayerGui end

                _ncBindFrame = MakeCapyBindableFrame(_ncBindGui, "NOCLIP", function()
                    _nc.enabled = not _nc.enabled
                    if _nc.enabled then
                        _ncOn()
                        _G._toggleStates["Noclip"] = true
                    else
                        _ncOff()
                        _G._toggleStates["Noclip"] = false
                    end
                end)
            end
        end, false)

        -- button Noclip Draggable

    end

    -- ============================================
    -- LOCAL CHARACTER
    -- ============================================
    do
        local _lcSection = CreateBorderedSection(leftColumn, " LOCAL CHARACTER")

        -- Reset Character -- mata al personaje para forzar respawn
        CreateButton(_lcSection, "Reset Character", ThemeColors.Aurora3, function()
            pcall(function()
                local char = LocalPlayer.Character
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.Health = 0
                    CreateCustomNotification("RESET", "Personaje reseteado", 1.5)
                end
            end)
        end)

        -- Reset Cam -- movido aqui (era parte de Local Character, ahora agrupado con caracter)
        CreateAuroraToggle(_lcSection, "Reset Cam", function(on)
            if on then
                pcall(function()
                    local cam  = _Camera
                    local char = LocalPlayer.Character
                    local hum  = char and char:FindFirstChildOfClass("Humanoid")
                    if cam then
                        cam.CameraType = Enum.CameraType.Custom
                        if hum then cam.CameraSubject = hum end
                        cam.FieldOfView = 70
                    end
                    CreateCustomNotification("RESET CAM", "Camara restaurada", 1.5)
                end)
                _sp(function() _G._toggleStates["Reset Cam"] = false end)
            end
        end, false)
    end

    -- ============================================
    -- CAMERA
    -- ============================================
    do
        local _camSection = CreateBorderedSection(rightColumn, " CAMERA")

        -- FIX: persistir estado de camara en _G para sobrevivir cambios de tab
        _G._mainCamState = _G._mainCamState or { fovValue=80, fovActive=false, fovConn=nil, ncCamMode=false, ncCamConn=nil, ncCamOffset=CFrame.new(0,2,8), briVal=1, briActive=false }
        local _cs = _G._mainCamState
        local _fovValue  = _cs.fovValue
        local _fovActive = _cs.fovActive
        -- Limpiar conn anterior si existia (tab switch)
        if _cs.fovConn then pcall(function() _cs.fovConn:Disconnect() end); _cs.fovConn = nil end
        if _cs.ncCamConn then pcall(function() _cs.ncCamConn:Disconnect() end); _cs.ncCamConn = nil end

        -- FOV slider
        CreateSlider(_camSection, "FOV", 1, 120, _fovValue, function(v)
            _fovValue = v; _cs.fovValue = v
            if _cs.fovActive then
                pcall(function() _Camera.FieldOfView = v end)
            end
        end)

        -- Activar FOV -- aplica el FOV y lo mantiene contra resets del juego
        CreateAuroraToggle(_camSection, "Enable FOV", function(on)
            _cs.fovActive = on
            if _cs.fovConn then pcall(function() _cs.fovConn:Disconnect() end); _cs.fovConn = nil end
            if on then
                pcall(function() _Camera.FieldOfView = _cs.fovValue end)
                _cs.fovConn = _safeConnect(RunService.RenderStepped, function()
                    local cam = _Camera
                    if cam and math.abs(cam.FieldOfView - _cs.fovValue) > 0.5 then
                        cam.FieldOfView = _cs.fovValue
                    end
                end)
            else
                pcall(function() _Camera.FieldOfView = 70 end)
            end
        end, _cs.fovActive)
        -- OPT: restaurar FOV -- el toggle ya inicializa el loop, no duplicar

        -- --- NOCLIP CAMERA (subgrupo dentro de Camera) ---------------------
        local _ncCamOffset = _cs.ncCamOffset
        CreateAuroraToggle(_camSection, "Noclip Camera", function(on)
            _cs.ncCamMode = on
            if _cs.ncCamConn then pcall(function() _cs.ncCamConn:Disconnect() end); _cs.ncCamConn = nil end
            local cam = _Camera
            if on then
                pcall(function() cam.CameraType = Enum.CameraType.Scriptable end)
                _cs.ncCamConn = _safeConnect(RunService.RenderStepped, function()
                    if not _cs.ncCamMode then return end
                    local char = LocalPlayer.Character
                    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    pcall(function()
                        local camCF = hrp.CFrame * _cs.ncCamOffset
                        cam.CFrame  = CFrame.lookAt(camCF.Position, hrp.Position + Vector3.new(0, 1, 0))
                    end)
                end)
                -- [notif removed]
            else
                pcall(function()
                    cam.CameraType = Enum.CameraType.Custom
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum then cam.CameraSubject = hum end
                end)
                -- [notif removed]
            end
        end, _cs.ncCamMode)
        -- OPT: restaurar Noclip Camera -- el toggle ya inicializa el loop, no duplicar

        -- Slider de distancia de la Noclip Camera
        CreateSlider(_camSection, "Noclip Cam Distance", 3, 30, 8, function(v)
            _cs.ncCamOffset = CFrame.new(0, v * 0.25, v)
            _ncCamOffset = _cs.ncCamOffset
        end)

        -- brightness (slider, 0-10)
        local _briVal    = _cs.briVal
        local _briActive = _cs.briActive
        CreateSlider(_camSection, "brightness", 0, 10, _briVal, function(v)
            _briVal = v; _cs.briVal = v
            if _cs.briActive then
                pcall(function() Lighting.Brightness = v end)
            end
        end)

        -- brightness (toggle -- aplica/restaura)
        CreateAuroraToggle(_camSection, "Apply Brightness", function(on)
            _cs.briActive = on
            if on then
                pcall(function() Lighting.Brightness = _cs.briVal end)
            else
                pcall(function() Lighting.Brightness = 1 end)
            end
        end, _cs.briActive)
        if _cs.briActive then pcall(function() Lighting.Brightness = _cs.briVal end) end
    end

    -- ============================================
    -- SPEED
    -- ============================================
    do
        local _spSection = CreateBorderedSection(leftColumn, " SPEED")

        -- FIX: persistir en _G para sobrevivir cambios de tab
        _G._mainSpeedState = _G._mainSpeedState or { swVal=16, swActive=false, swConn=nil, pjVal=50, pjActive=false, pjConn=nil, ijConn=nil }
        local _sp = _G._mainSpeedState
        local _swVal    = _sp.swVal
        local _swActive = _sp.swActive
        local _swConn   = _sp.swConn

        -- Aplica walkspeed al humanoid actual
        local function _applyWS(v)
            pcall(function()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 then hum.WalkSpeed = v end
            end)
        end
        local function _restoreWS()
            pcall(function()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum then hum.WalkSpeed = 16 end
            end)
        end

        -- Speed walk (slider)
        CreateSlider(_spSection, "Speed walk", 0, 500, _swVal, function(v)
            _swVal = v; _sp.swVal = v
            if _swActive then _applyWS(v) end
        end)

        -- Always speed -- mantiene el walkspeed incluso tras respawn o reseteos del juego
        CreateAuroraToggle(_spSection, "Always speed", function(on)
            _swActive = on; _sp.swActive = on
            if _sp.swConn then pcall(function() _sp.swConn:Disconnect() end); _sp.swConn = nil end
            if on then
                _applyWS(_swVal)
                _sp.swConn = _safeConnect(RunService.Heartbeat, function()
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 and math.abs(hum.WalkSpeed - _sp.swVal) > 0.5 then
                        pcall(function() hum.WalkSpeed = _sp.swVal end)
                    end
                end)
            else
                _restoreWS()
            end
        end, _sp.swActive)
        -- OPT: restaurar speed -- el toggle ya inicializa el loop, no duplicar

        local _pjVal    = _sp.pjVal
        local _pjActive = _sp.pjActive

        local function _applyJP(v)
            pcall(function()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 then hum.JumpPower = v end
            end)
        end
        local function _restoreJP()
            pcall(function()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum then hum.JumpPower = 50 end
            end)
        end

        -- Power Jump (slider)
        CreateSlider(_spSection, "Power Jump", 0, 1000, _pjVal, function(v)
            _pjVal = v; _sp.pjVal = v
