        end)

        -- Power Jump/Always -- mantiene el JumpPower contra reseteos
        CreateAuroraToggle(_spSection, "Power Jump/Always", function(on)
            _pjActive = on; _sp.pjActive = on
            if _sp.pjConn then pcall(function() _sp.pjConn:Disconnect() end); _sp.pjConn = nil end
            if on then
                _applyJP(_pjVal)
                _sp.pjConn = _safeConnect(RunService.Heartbeat, function()
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 and math.abs(hum.JumpPower - _sp.pjVal) > 0.5 then
                        pcall(function() hum.JumpPower = _sp.pjVal end)
                    end
                end)
            else
                _restoreJP()
            end
        end, _sp.pjActive)
        -- OPT: restaurar jump -- el toggle ya inicializa el loop, no duplicar

        -- Infinite Jump -- usa JumpRequest para saltar en el aire
        -- FIX: usar _sp.ijConn para no perder la referencia al cambiar de tab
        if _sp.ijConn then pcall(function() _sp.ijConn:Disconnect() end); _sp.ijConn = nil end
        CreateAuroraToggle(_spSection, "Infinite Jump", function(on)
            if _sp.ijConn then pcall(function() _sp.ijConn:Disconnect() end); _sp.ijConn = nil end
            if on then
                _sp.ijConn = UserInput.JumpRequest:Connect(function()
                    pcall(function()
                        local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health > 0 then
                            hum:ChangeState(Enum.HumanoidStateType.Jumping)
                        end
                    end)
