        end, _sp.ijConn ~= nil)
    end

    -- ============================================
    -- JUMP BOOST
    -- ============================================
    do
        local _jbSection = CreateBorderedSection(rightColumn, "^  JUMP BOOST")

        local _jbVal       = 80
        local _jbBtnSize   = 50
        local _jbDraggable = true
        local _jbBindGui   = nil
        local _jbBindFrame = nil

        -- Jump Boost (slider) -- potencia del dash
        CreateSlider(_jbSection, "Jump Boost", 0, 1000, _jbVal, function(v)
            _jbVal = v
        end)

        -- Jump Boost Button Size (slider)
        CreateSlider(_jbSection, "Jump Boost Button Size", 10, 200, _jbBtnSize, function(v)
            _jbBtnSize = v
        end)

        -- Funcion del dash: impulso fuerte hacia adelante + arriba
        local function _doJumpBoost()
            pcall(function()
                local char = LocalPlayer.Character; if not char then return end
                local hrp  = char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
                local hum  = char:FindFirstChildOfClass("Humanoid"); if not hum then return end
                if hum.Health <= 0 then return end

                -- Direccion: LookVector del personaje (adelante) + componente vertical
                local fwd    = hrp.CFrame.LookVector
                local power  = _jbVal * 0.6

                -- Impulso: 80% hacia adelante, 50% hacia arriba
                local impulse = Vector3.new(fwd.X * power, power * 0.5, fwd.Z * power)

                -- Cancelar velocidad actual primero para que el impulso sea limpio
                local bvCancel = Instance.new("BodyVelocity")
                bvCancel.Name     = "_JBCancel"
                bvCancel.Velocity = Vector3.zero
                bvCancel.MaxForce = Vector3.new(1e7, 1e7, 1e7)
                bvCancel.Parent   = hrp

                _w()  -- 1 frame para que la cancelacion aplique

                bvCancel:Destroy()

                -- Aplicar el impulso real
                local bv = Instance.new("BodyVelocity")
                bv.Name     = "_JumpBoostBV"
                bv.Velocity = impulse
                bv.MaxForce = Vector3.new(1e7, 1e7, 1e7)
                bv.Parent   = hrp

                hum:ChangeState(Enum.HumanoidStateType.Jumping)

                -- Mantener por 0.12s y soltar (deja que la fisica tome el control)
                _dl(0.12, function()
                    if bv and bv.Parent then bv:Destroy() end
                end)
            end)
        end

        local function _makeJBBindable()
            if _jbBindGui then pcall(function() _jbBindGui:Destroy() end); _jbBindGui = nil; _jbBindFrame = nil end
            _jbBindGui = Instance.new("ScreenGui")
            _jbBindGui.Name           = "JumpBoostBindableHub"
            _jbBindGui.ResetOnSpawn   = false
            _jbBindGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            _jbBindGui.IgnoreGuiInset = true
            _jbBindGui.DisplayOrder   = 9900
            pcall(function() _jbBindGui.Parent = CoreGui end)
            if not _jbBindGui.Parent then _jbBindGui.Parent = LocalPlayer.PlayerGui end

            _jbBindFrame = MakeCapyBindableFrame(_jbBindGui, "DASH", _doJumpBoost)
        end

        -- Jump Boost (Button) -- boton bindable
        CreateAuroraToggle(_jbSection, "Jump Boost (Button)", function(on)
            if on then
                _makeJBBindable()
            else
                if _jbBindGui then pcall(function() _jbBindGui:Destroy() end); _jbBindGui = nil; _jbBindFrame = nil end
            end
        end, false)

    end


