    -- -- AUTO PRESTIGE ----------------------------------------------------
    do
        local _apSec = CreateBorderedSection(rightColumn, "*  AUTO PRESTIGE")
        _G._apState = _G._apState or { enabled = false, conn = nil }
        local _ap = _G._apState

        local function _doPrestige()
            -- Buscar boton de Prestige en el juego
            pcall(function()
                for _, obj in ipairs(Players.LocalPlayer.PlayerGui:GetDescendants()) do
                    if obj:IsA("TextButton") or obj:IsA("ImageButton") then
                        local n = obj.Name:lower()
                        if n:find("prestige") or n:find("level up") then
                            obj:Activate()
                            CreateCustomNotification("PRESTIGE", "Prestige activado!", 2)
                            return
                        end
                    end
                end
                -- Fallback: buscar en workspace
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("ProximityPrompt") and obj.ActionText:lower():find("prestige") then
                        game:GetService("ProximityPromptService"):TriggerPrompt(obj)
                        CreateCustomNotification("PRESTIGE", "Prestige activado!", 2)
                        return
                    end
                end
                CreateCustomNotification("PRESTIGE", "Boton de Prestige no encontrado", 2)
            end)
        end

        -- Boton clickeable
        CreateButton(_apSec, "* Prestige Ahora", ThemeColors.Aurora1, function()
            _sp(_doPrestige)
        end)

        -- Toggle auto prestige -- OPT: throttle ~2Hz (prestige no requiere 60Hz)
        CreateAuroraToggle(_apSec, "Auto Prestige", function(on)
            _ap.enabled = on
            if _ap.conn then pcall(function() _ap.conn:Disconnect() end); _ap.conn = nil end
            if on then
                local _apTick = 0
                _ap.conn = RunService.Heartbeat:Connect(function()
                    if not _ap.enabled then return end
                    _apTick = _apTick + 1
                    if _apTick < 30 then return end  -- OPT: ~2Hz
                    _apTick = 0
                    for _, obj in ipairs(Players.LocalPlayer.PlayerGui:GetDescendants()) do
                        if (obj:IsA("TextButton") or obj:IsA("ImageButton")) then
                            local n = obj.Name:lower()
                            if n:find("prestige") and obj.Visible and obj.Active then
                                pcall(function() obj:Activate() end)
                                CreateCustomNotification("PRESTIGE", "Auto Prestige!", 2)
                                break
                            end
                        end
                    end
                end)
                CreateCustomNotification("PRESTIGE", "Auto Prestige ON", 2)
            else
                CreateCustomNotification("PRESTIGE", "Auto Prestige OFF", 2)
            end
        end, _ap.enabled)
        -- OPT: restaurar prestige -- el toggle ya inicializa el loop, no duplicar
    end
    CreateMainUI_BombJump()                 -- LEFT:  BOMB DOUBLE JUMP / Click Effect
    CreateMainUI_ResearchFacility_DISABLED()-- RIGHT: RESEARCH FACILITY AUTO
    CreateMainUI_Fly()                      -- LEFT:  FLY (+ auto-emote)
