    CreateMainUI_SecureAuto()               -- LEFT:  SECURE AUTOMATIC
    CreateMainUI_BackgroundSelector()       -- LEFT:  SECOND LIFE + TP LOW MAP
    CreateMainUI_LogoSelector()             -- LEFT:  HAND FLUTTER

    -- Grupo 5 -- Avatar y estetica
    CreateMainUI_FakeAvatarMain()           -- LEFT:  FAKE AVATAR (principal, multi-tab)




    -- == SONG PLAYER ==============================================
    do
        local _spSec = CreateBorderedSection(leftColumn, " MM2 / MMV")
        _G._songState = _G._songState or { autoPlay=false, currentId="1840776993", sound=nil }
        local _ss = _G._songState
        local function _playSound(id)
            if _ss.sound and _ss.sound.Parent then pcall(function() _ss.sound:Stop(); _ss.sound:Destroy() end) end
            local snd = Instance.new("Sound", workspace)
            snd.Name="rbxassetid://140622075233565Song"; snd.SoundId="rbxassetid://"..tostring(id):gsub("%D","")
            snd.Volume=1; snd.Looped=_ss.autoPlay; snd.RollOffMaxDistance=1e9
            pcall(function() snd:Play() end); _ss.sound=snd
        end
        local function _stopSound()
            if _ss.sound and _ss.sound.Parent then pcall(function() _ss.sound:Stop(); _ss.sound:Destroy() end); _ss.sound=nil end
        end
        local _lbl=Instance.new("TextLabel",_spSec)
        _lbl.Size=UDim2.new(1,-8,0,16); _lbl.BackgroundTransparency=1; _lbl.BorderSizePixel=0
        _lbl.Text=" Song ID to Play"; _lbl.TextColor3=ThemeColors.TextSecondary
        _lbl.Font=Enum.Font.Montserrat; _lbl.TextSize=11
        _lbl.TextXAlignment=Enum.TextXAlignment.Left; _lbl.ZIndex=13
        local _box=Instance.new("TextBox",_spSec)
        _box.Size=UDim2.new(1,-8,0,28); _box.BackgroundColor3=Color3.fromRGB(10,20,8)
        _box.BackgroundTransparency = 0.75; _box.BorderSizePixel=0; _box.Text=_ss.currentId
        _box.TextColor3=ThemeColors.Primary; _box.PlaceholderText="ID de la cancion..."
        _box.PlaceholderColor3=Color3.fromRGB(80,100,70); _box.Font=Enum.Font.Montserrat
        _box.TextSize=13; _box.ClearTextOnFocus=false; _box.ZIndex=13
        Instance.new("UICorner",_box).CornerRadius=UDim.new(0,6)
        local _bs=Instance.new("UIStroke",_box); _bs.Color=ThemeColors.Primary
        _bs.Thickness=1.2; _bs.Transparency=0.35; _bs.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
        _box:GetPropertyChangedSignal("Text"):Connect(function() _ss.currentId=_box.Text end)
        local _bw=Instance.new("Frame",_spSec); _bw.Size=UDim2.new(1,-8,0,32)
        _bw.BackgroundTransparency=1; _bw.BorderSizePixel=0; _bw.ZIndex=12
        local _btn=Instance.new("TextButton",_bw); _btn.Size=UDim2.new(1,0,1,0)
        _btn.BackgroundColor3=ThemeColors.Background; _btn.BackgroundTransparency=0.15
        _btn.Text=" Play Song"; _btn.TextColor3=ThemeColors.TextPrimary
        _btn.Font=Enum.Font.Montserrat; _btn.TextSize=13
        _btn.AutoButtonColor=false; _btn.BorderSizePixel=0; _btn.ZIndex=13
        Instance.new("UICorner",_btn).CornerRadius=UDim.new(0,6)
        local _bst=Instance.new("UIStroke",_btn); _bst.Thickness=1.5
        _bst.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
        local _bg=Instance.new("UIGradient",_bst)
        _bg.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,ThemeColors.Primary),ColorSequenceKeypoint.new(0.5,ThemeColors.Aurora2),ColorSequenceKeypoint.new(1,ThemeColors.Primary)})
        _btn.MouseEnter:Connect(function() TweenService:Create(_btn,TweenInfo.new(0.1),{BackgroundTransparency=0.05}):Play() end)
        _btn.MouseLeave:Connect(function() TweenService:Create(_btn,TweenInfo.new(0.1),{BackgroundTransparency=0.15}):Play() end)
        _btn.Activated:Connect(function()
            local id=tostring(_ss.currentId):gsub("%D","")
            if id=="" then CreateCustomNotification("SONG","Ingresa un ID valido",2); return end
            _playSound(id); CreateCustomNotification("SONG","> "..id,2)
        end)
        CreateAuroraToggle(_spSec,"Auto Play Song",function(on)
            _ss.autoPlay=on
            if _ss.sound and _ss.sound.Parent then _ss.sound.Looped=on end
            if not on then _stopSound() end
        end,_ss.autoPlay)
    end

    _sp(function()
        if not leftColumn  or not leftColumn.Parent  then return end
        if not rightColumn or not rightColumn.Parent then return end
        -- OPT: local en vez de global para no contaminar el entorno en cada apertura
        local function recalcCanvas(col)
            local layout = col:FindFirstChildOfClass("UIListLayout")
            if not layout then return end
            col.CanvasSize = UDim2.new(0, 0, 0, layout.AbsoluteContentSize.Y + 40)
        end
        _w(0.15)
        recalcCanvas(leftColumn)
        recalcCanvas(rightColumn)
        _w(0.3)
        recalcCanvas(leftColumn)
        recalcCanvas(rightColumn)
    end)
end

FarmSystem = {
    state = {
        on            = false,
        mode          = "Fly Mode",   -- "Fly Mode" | "TP Below Map" | "Instant TP"
        spd           = 100,
        dly           = 0,
        start         = 0,
        tgt           = 40,           -- coins antes de shoot
        shoot         = false,
        pos           = nil,
        shooting      = false,
        rst           = "None",
        lmt           = 40,
        useLmt        = false,
        conn          = nil,
        coinType      = "Coin",
        syncMode      = false,
        autoRejoin    = false,
        lastCoinTick  = 0,
        lastCoinObj   = nil,
        autoShootMurderer = false,
        autoShootConn     = nil,
        autoResetMurderer = false,
        autoResetSheriff  = false,
        autoResetInnocent = false,
        autoResetConn     = nil,
        autoReset         = false,
        resetCoins        = 40,
        monitorConn       = nil,
        coinsFarmed       = 0,
        grabbed           = {},
    },

    GetInventoryCoins = function()
        -- Try multiple paths for coin counter
        local ok, val = pcall(function()
            return LocalPlayer.PlayerGui
                :FindFirstChild("Scoreboard_Phone")
                :FindFirstChild("BonusModes")
                :FindFirstChild("Container")
                :FindFirstChild("LevelUp")
                :FindFirstChild("Coins")
                :FindFirstChild("CoinIcon")
                :FindFirstChild("TextLabel").Text
        end)
        if ok and tonumber(val) then return tonumber(val) end
        -- Fallback: buscar cualquier TextLabel con numero de monedas
        local ok2, val2 = pcall(function()
            local sb = LocalPlayer.PlayerGui:FindFirstChild("Scoreboard_Phone")
            if not sb then return nil end
            for _, desc in ipairs(sb:GetDescendants()) do
                if desc:IsA("TextLabel") then
                    local n = tonumber(desc.Text)
                    if n and n >= 0 and n <= 9999 then return n end
                end
            end
        end)
        return (ok2 and tonumber(val2)) or 0
    end,

    FindCoinContainer = function()
        -- Deteccion directa via RS.Coins.CoinObjects.Coin
        local ok, coinFolder = pcall(function()
            return game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
        end)
        if ok and coinFolder and coinFolder:IsA("Folder") and #coinFolder:GetChildren() > 0 then
            return coinFolder
        end
        -- Fallback: buscar CoinContainer en workspace
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("Model") or obj:IsA("Folder") then
                local cc = obj:FindFirstChild("CoinContainer")
                if cc and #cc:GetChildren() > 0 then
                    return cc
                end
            end
        end
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj.Name == "CoinContainer" and #obj:GetChildren() > 0 then
                return obj
            end
        end
        return nil
    end,

    _coinCache = {},
    _lastCoinRefresh = 0,
    _coinRefreshInterval = 3, -- Refresh cada 3 segundos
    -- FIX: tabla Y inicial para detectar coins que MM2 esta animando hacia arriba
    _coinBaseY = {},

    GetCoins = function()
        local F = FarmSystem.state
        local now = tick()

        if now - FarmSystem._lastCoinRefresh > FarmSystem._coinRefreshInterval then
            FarmSystem._coinCache = {}

            local cc = FarmSystem.FindCoinContainer()
            if cc then
                if FarmSystem._lastCoinContainer ~= cc then
                    FarmSystem._lastCoinContainer = cc
                    F.grabbed = {}
                    FarmSystem._coinBaseY = {}
                end

                for _, coin in ipairs(cc:GetChildren()) do
                    -- FIX: skip invisible/transparent coins
                    if coin:IsA("BasePart") and coin.Name == "Coin_Server"
                    and coin.Transparency < 0.9  -- FIX: no recoger coins invisibles
                    and coin.Parent then
                        -- FIX: registrar Y inicial cuando la coin entra al cache
                        if not FarmSystem._coinBaseY[coin] then
                            FarmSystem._coinBaseY[coin] = coin.Position.Y
                        end
                        table.insert(FarmSystem._coinCache, coin)
                    end
                end
            end

            if #FarmSystem._coinCache == 0 then
                -- Intentar desde RS.Coins.CoinObjects.Coin
                local rsOk, coinFolder = pcall(function()
                    return game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
                end)
                if rsOk and coinFolder then
                    for _, obj in ipairs(coinFolder:GetChildren()) do
                        if (obj:IsA("BasePart") or obj:IsA("MeshPart"))
                        and obj.Transparency < 0.9
                        and obj.Parent then
                            table.insert(FarmSystem._coinCache, obj)
                        end
                    end
                end
            end
            if #FarmSystem._coinCache == 0 then
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("BasePart") and obj.Name == "Coin_Server"
                    and obj.Transparency < 0.9 -- FIX: no recoger coins invisibles
                    and obj.Parent then
                        table.insert(FarmSystem._coinCache, obj)
                    end
                end
            end

            FarmSystem._lastCoinRefresh = now
        end

        local out = {}
        for _, coin in ipairs(FarmSystem._coinCache) do
            -- FIX: verificar que siga existiendo, no sea invisible, y no este en grabbed
            if coin and coin.Parent and not F.grabbed[coin] and coin.Transparency < 0.9 then
                local pos = coin.Position
                if pos then
                    -- FIX: si la coin subio mas de 3 studs desde su Y original,
                    -- MM2 la esta animando hacia arriba (recogida) -> ignorarla
                    local baseY = FarmSystem._coinBaseY[coin]
                    if baseY and pos.Y > baseY + 3 then
                        F.grabbed[coin] = true  -- marcarla como recogida
                        FarmSystem._coinBaseY[coin] = nil
                    else
                        table.insert(out, {obj=coin, pos=pos})
                    end
                end
            end
        end

        return out
    end,

    GetNearest = function()
        local F    = FarmSystem.state
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil, math.huge end
        local best, bestD, bestPos = nil, math.huge, nil
        for _, entry in ipairs(FarmSystem.GetCoins()) do
            local d = (hrp.Position - entry.pos).Magnitude
            if d < bestD then bestD = d; best = entry.obj; bestPos = entry.pos end
        end
        FarmSystem._nearestPos = bestPos
        return best, bestD
    end,

    Collect = function(coin)
        local F = FarmSystem.state
        if not coin or not coin.Parent then return end
        F.grabbed[coin] = true
        F.coinsFarmed   = (F.coinsFarmed or 0) + 1

        local grabbedCount = 0
        for _ in pairs(F.grabbed) do grabbedCount = grabbedCount + 1 end

        if grabbedCount > 100 then
            local newGrabbed = {}
            local kept = 0

            for c, _ in pairs(F.grabbed) do
                if c and c.Parent and kept < 50 then
                    newGrabbed[c] = true
                    kept = kept + 1
                end
            end

            F.grabbed = newGrabbed
            _logINFO("FarmSystem -- memoria limpiada: " .. grabbedCount .. " -> " .. kept .. " coins")
        end

        -- FIX: forzar refresh del cache en el proximo frame para que el personaje
        -- se mueva inmediatamente a la siguiente coin sin esperar los 3 segundos del intervalo
        FarmSystem._lastCoinRefresh = 0
    end,

    NC = function()
        local char = LocalPlayer.Character
        if not char then return end
        for _, p in pairs(char:GetDescendants()) do
            if p:IsA("BasePart") then p.CanCollide = false end
        end
    end,

    Clean = function()
        local F = FarmSystem.state
        for coin in pairs(F.grabbed) do
            if not coin or not coin.Parent then F.grabbed[coin] = nil end
        end
    end,

    StartMonitoring = function()
        local F = FarmSystem.state
        if F.monitorConn then F.monitorConn:Disconnect() end
        if not F.autoReset then return end
        local lastReset = 0
        local _monTick = 0
        F.monitorConn = _safeConnect(RunService.Heartbeat, function()
            _monTick = _monTick + 1; if _monTick < 30 then return end; _monTick = 0  -- OPT: 2Hz, no necesita verificar coins a 60Hz
            if tick() - lastReset < 3 then return end  -- cooldown 3s entre resets
            local coins = FarmSystem.GetInventoryCoins()
            if coins >= F.resetCoins then
                lastReset = tick()
 CreateCustomNotification("AUTO RESET", coins .. " coins! Reseteando...", 3)
                _sp(function()
                    _w(0.5)
                    local char = LocalPlayer.Character
                    local hum  = char and char:FindFirstChildOfClass("Humanoid")
                    if hum then hum.Health = 0 end
                end)
            end
        end)
    end,

    StopMonitoring = function()
        local F = FarmSystem.state
        if F.monitorConn then F.monitorConn:Disconnect(); F.monitorConn = nil end
    end,

    Start = function()
        local F = FarmSystem.state
        if F.conn then F.conn:Disconnect(); F.conn = nil end
        if not F.on then return end

        F.start        = tick()
        F.grabbed      = {}
        F.coinsFarmed  = 0
        F.lastCoinObj  = nil
        F.lastCoinTick = 0

        -- FIX: esperar a que aparezca la primera moneda antes de empezar
        _coinDetected = false
        _sp(function()
            maxWait = 15  -- maximo 15 segundos esperando monedas
            waited  = 0
            while F.on and not _coinDetected and waited < maxWait do
                local coins = FarmSystem.GetCoins()
                if #coins > 0 then
                    _coinDetected = true
 CreateCustomNotification("FARM", "Moneda detectada -- iniciando farm!", 2)
                else
                    _w(0.5)
                    waited = waited + 0.5
                end
            end
            if not _coinDetected then
 CreateCustomNotification("FARM", "No se detectaron monedas, farm en espera...", 3)
            end
        end)

        lastClean = tick()
        lastDelay = tick()

        F.conn = RunService.Heartbeat:Connect(function()
            if not F.on then
                F.conn:Disconnect(); F.conn = nil
                return
            end

            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            hum  = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then return end

            -- FIX: parar farm si el jugador esta muerto
            if hum.Health <= 0 then
                _coinDetected = false  -- resetear para la proxima vida
                return
            end

            -- FIX: no empezar hasta que se detecte la primera moneda
            if not _coinDetected then return end

            -- FIX: PlatformStand=true desactiva el motor fisico del Humanoid por completo.
            -- PlatformStand=false + ChangeState(Running) peleaba contra el CFrame cada frame
            -- y empujaba al personaje hacia arriba. Con true el HRP solo obedece physics externas.
            if hum.Health > 0 then
                hum.PlatformStand = true
            end
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero

            FarmSystem.NC()

            if tick() - lastClean >= 3 then
                lastClean = tick()
                FarmSystem.Clean()
            end

            if F.dly > 0 and tick() - lastDelay < F.dly then return end
            lastDelay = tick()

            coin, dist = FarmSystem.GetNearest()
            if not coin then
                F.grabbed = {}
                lastClean = tick()
                -- Sin coins: enderezar personaje y quedarse quieto
                if hrp and hum and hum.Health > 0 then
                    hum.PlatformStand = false
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                    hrp.CFrame = CFrame.new(hrp.Position) * CFrame.Angles(0, (hrp.CFrame - hrp.CFrame.Position).LookVector ~= Vector3.zero and select(2, hrp.CFrame:ToEulerAnglesYXZ()) or 0, 0)
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                    hum.WalkToPoint = hrp.Position
                end
                return
            end

            if F.syncMode then
                if F.lastCoinObj == coin then
                    if tick() - F.lastCoinTick > 5 then
                        F.grabbed[coin] = true
                        F.lastCoinObj   = nil
                        F.lastCoinTick  = tick()
                        return
                    end
                else
                    F.lastCoinObj  = coin
                    F.lastCoinTick = tick()
                end
            end

            coinPos = FarmSystem._nearestPos
                or (coin:IsA("BasePart") and coin.Position)
                or (coin:IsA("Model") and coin.PrimaryPart and coin.PrimaryPart.Position)
            if not coinPos then return end

            if F.mode == "Fly Mode" then
                -- FIX: usar BodyVelocity en lugar de CFrame para mover al personaje.
                -- CFrame + PlatformStand=false peleaba contra el motor fisico y subia al personaje.
                -- BodyVelocity + PlatformStand=true mueve sin conflicto y no genera subida.
                FarmSystem.Fly(true)  -- asegura que bv/bg esten activos

                local myPos  = hrp.Position
                local dir    = coinPos - myPos
                local dist   = dir.Magnitude

                if dist > 0.8 then
                    local spd = math.clamp(F.spd, 1, 200)
                    -- Mover directo hacia la coin en los 3 ejes con BodyVelocity
                    if F.bv and F.bv.Parent then
                        F.bv.Velocity = dir.Unit * spd
                    end
                    -- Orientar BodyGyro hacia la coin (solo en horizontal)
                    if F.bg and F.bg.Parent then
                        local flat = Vector3.new(dir.X, 0, dir.Z)
                        if flat.Magnitude > 0.1 then
                            F.bg.CFrame = CFrame.lookAt(myPos, myPos + flat)
                        end
                    end
                else
                    -- Ya esta en la coin: detener BodyVelocity y recolectar
                    if F.bv and F.bv.Parent then F.bv.Velocity = Vector3.zero end
                    if firetouchinterest and coin:IsA("BasePart") then
                        pcall(function() firetouchinterest(hrp, coin, 0) end)
                        pcall(function() firetouchinterest(hrp, coin, 1) end)
                    end
                    FarmSystem.Collect(coin)
                end

            elseif F.mode == "TP Below Map" then
                hrp.CFrame = CFrame.new(coinPos + Vector3.new(0, -80, 0))
                _sp(function()
                    if hrp and hrp.Parent then
                        hrp.CFrame = CFrame.new(coinPos)
                        FarmSystem.Collect(coin)
                    end
                end)

            else  -- Instant TP (TP Coin)
                hrp.CFrame = CFrame.new(coinPos)
                -- Aplicar delay de TP si esta configurado
                local _tpDelay = (_G._farmTPDelay or 0)
                if _tpDelay > 0 then
                    task.wait(_tpDelay)
                end
                FarmSystem.Collect(coin)
            end

            realCoins = FarmSystem.GetInventoryCoins()
            if F.shoot and not F.shooting and realCoins >= F.tgt then
                F.shooting = true
                F.on       = false

                _sp(function()
                    -- Pausar farm y restaurar personaje antes de disparar
                    local returnCF = hrp.CFrame
                    if hum and hum.Health > 0 then
                        hum.PlatformStand = false
                        pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                    end
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero

                    CreateCustomNotification("FARM", "40 coins -- disparando al Murder!", 2)
                    _w(0.2)

                    -- Usar exactamente StartShootMurder de Combat (TP detras + dispara)
                    if StartShootMurder then
                        StartShootMurder()
                        -- Esperar un ciclo de shoot (TP + disparo + retorno interno)
                        _w(2.5)
                        if StopShootMurder then StopShootMurder() end
                    end

                    -- Volver a la posicion del farm y reanudar
                    _w(0.3)
                    pcall(function() hrp.CFrame = returnCF end)
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero

                    CreateCustomNotification("FARM", "Disparado -- regresando al farm", 2)
                    _w(1)
                    F.grabbed  = {}
                    F.shooting = false
                    F.on       = true
                    FarmSystem.Start()
                end)
            end

            -- Auto Kill Everyone As Murderer: al llegar a 40 coins llama StartKillAllMurder de Combat
            if _G._farmAutoKillActive and not _G._farmAutoKillFired and realCoins >= 40 then
                local myRole = _roleCache and _roleCache.localRole
                if myRole == "Murderer" then
                    _G._farmAutoKillFired = true
                    CreateCustomNotification("AUTO KILL EVERYONE", "40 coins -- activando Kill All!", 2)
                    task.spawn(function()
                        if StartKillAllMurder then StartKillAllMurder() end
                    end)
                end
            end

            if F.autoResetMurderer or F.autoResetSheriff or F.autoResetInnocent then
                local role = GetPlayerRole(LocalPlayer)
                if (F.autoResetMurderer and role == "Murderer") or
                   (F.autoResetSheriff  and role == "Sheriff")  or
                   (F.autoResetInnocent and role == "Innocent") then
                    hum.Health = 0
                end
            end
        end)
    end,

    Stop = function()
        local F = FarmSystem.state
        F.on = false
        if F.conn then F.conn:Disconnect(); F.conn = nil end
        -- FIX: destruir BodyVelocity/BodyGyro creados por Fly Mode
        FarmSystem.Fly(false)
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hrp then
            pcall(function()
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end
        -- FIX: restaurar PlatformStand=false para que el personaje vuelva a moverse normal
        if hum then
            pcall(function()
                hum.PlatformStand = false
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end)
        end
    end,

    Fly = function(on)
        local F    = FarmSystem.state
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        if on then
            if not F.bv then
                local bv = Instance.new("BodyVelocity", hrp)
                bv.Velocity       = Vector3.zero
                bv.MaxForce       = Vector3.new(1e5,1e5,1e5)
                bv.P              = 1e4
                F.bv = bv
            end
            if not F.bg then
                local bg = Instance.new("BodyGyro", hrp)
                bg.MaxTorque = Vector3.new(1e5,1e5,1e5)
                bg.P         = 1e4
                bg.CFrame    = hrp.CFrame
                F.bg = bg
            end
        else
            if F.bv then F.bv:Destroy(); F.bv = nil end
            if F.bg then F.bg:Destroy(); F.bg = nil end
        end
    end,
}

FarmToggles = {
    resetInnocentActive = false,
    shootSheriffActive  = false,
    killAllMurderActive = false,
    autoFarmActive      = false,
    autoReset40Active   = false,
    autoReset40Conn     = nil,
    endRound40Active    = false,   -- End Round: fling al murder cuando moris
    endRound40Conn      = nil,
    _erCharConn         = nil,     -- CharacterAdded para re-hookear Died en respawn
    _erRemConn          = nil,     -- CharacterRemoving para detectar reset manual
    _erCoinConn         = nil,     -- CoinCollected: resetear al llegar a 40 monedas
    resetInnocentConn   = nil,
    shootSheriffConn    = nil,
    killAllMurderConn   = nil,
}

FarmStats = {
    coinsTotal      = 0,
    resets          = 0,
    sessionStart    = tick(),
    lastCoinCount   = 0,
    coinMonitorConn = nil,
}


_farmCoinSet   = {}   -- { [coin] = true }
_farmCoinCount = 0
_farmCCRef     = nil  -- referencia al CoinContainer activo
_farmAddedConn = nil
_farmRemovedConn = nil

_farmCoinTypeMap = {
    Coin       = {"MainCoin", "Coin"},
    Egg        = {"CurrencyEgg1", "Egg", "EggCoin", "Egg_Server"},
    BeachBall  = {"BeachBall", "BeachBall_Server", "Ball"},
    Candy      = {"Cyan", "Candy", "CandyCoin", "Candy_Server"},
    SnowCannon = {"SnowToken", "Snowflake", "Snow", "Snow_Server"},
}
_farmCoinTypeName = "Coin" -- default

-- Mapa de nombre UI -> clave de _farmCoinTypeMap (usado en el selector)
_coinTypeNameMap = {
    ["Coin"]       = "Coin",
    ["SnowCannon"] = "SnowCannon",
    ["Candy"]      = "Candy",
    ["Egg"]        = "Egg",
    ["BeachBall"]  = "BeachBall",
}

-- Rutas de ReplicatedStorage para cada tipo de moneda
_coinTypePaths = {
    Coin       = {"ReplicatedStorage", "Coins", "CoinObjects", "Coin"},
    SnowCannon = {"ReplicatedStorage", "Coins", "SnowTokenObjects", "SnowToken"},
    Candy      = {"ReplicatedStorage", "Coins", "CandyObjects", "Cyan"},
    Egg        = {"ReplicatedStorage", "Coins", "EggObjects", "Eggs", "CurrencyEgg1"},
    BeachBall  = {"ReplicatedStorage", "Coins", "BeachBallObjects", "BeachBall"},
}

-- Obtiene los objetos de moneda directamente de ReplicatedStorage (para deteccion)
function _getCoinsFromRS(coinTypeName)
    local path = _coinTypePaths[coinTypeName]
    if not path then return {} end
    local results = {}
    -- 1) Intentar encontrar clones en workspace que coincidan con nombres del tipo
    local names = _farmCoinTypeMap[coinTypeName] or {}
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("BasePart") then
            for _, n in ipairs(names) do
                if obj.Name:lower() == n:lower() then
                    table.insert(results, obj)
                    break
                end
            end
        end
    end
    return results
end

function GetCoinList(coinTypeName)
    local typeName = coinTypeName or _farmCoinTypeName
    -- Primero intentar desde el farmCoinSet activo
    local fromSet = {}
    local names = _farmCoinTypeMap[typeName] or _farmCoinTypeMap["Coin"]
    for coin in pairs(_farmCoinSet) do
        if coin and coin.Parent then
            for _, n in ipairs(names) do
                if coin.Name:lower() == n:lower() then
                    table.insert(fromSet, coin)
                    break
                end
            end
        end
    end
    if #fromSet > 0 then return fromSet end
    -- Fallback: buscar en workspace
    return _getCoinsFromRS(typeName)
end

function _farmCoinNameMatches(name)
    local lower = name:lower()
    local targets = _farmCoinTypeMap[_farmCoinTypeName] or _farmCoinTypeMap["Coin"]
    for _, t in ipairs(targets) do
        if lower == t:lower() then return true end
    end
    return false
end

function _farmOnAdded(obj)
    if obj:IsA("BasePart") and _farmCoinNameMatches(obj.Name) then
        if not _farmCoinSet[obj] then
            _farmCoinSet[obj]   = true
            _farmCoinCount = _farmCoinCount + 1
        end
    end
end

function _farmOnRemoved(obj)
    if _farmCoinSet[obj] then
        _farmCoinSet[obj]   = nil
        _farmCoinCount = _farmCoinCount - 1
        if _farmCoinCount < 0 then _farmCoinCount = 0 end
    end
end

-- Flag para saber si el container activo viene de RS (sus hijos son Models, no BaseParts directos)
_farmContainerIsRS = false

function FindActiveCoinContainer()
    -- Prioridad 0: workspace.Mansion2.CoinContainer (mapa Mansion2 activo)
    -- Debe ir ANTES que RS para que el _farmCoinSet use las coins del workspace real
    do
        local m2 = workspace:FindFirstChild("Mansion2")
        if m2 then
            local cc = m2:FindFirstChild("CoinContainer")
            if cc and #cc:GetChildren() > 0 then
                _farmContainerIsRS = false
                return cc, "Mansion2"
            end
        end
    end
    -- Prioridad 1: RS.Coins.CoinObjects.Coin (siempre cuando el tipo es Coin)
    if _farmCoinTypeName == "Coin" or _farmCoinTypeName == nil then
        local ok, coinFolder = pcall(function()
            return game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
        end)
        if ok and coinFolder and #coinFolder:GetChildren() > 0 then
            _farmContainerIsRS = true
            return coinFolder, "ReplicatedStorage.Coins.CoinObjects.Coin"
        end
    end
    _farmContainerIsRS = false
    -- Prioridad: workspace.Workplace.CoinContainer (estructura real del juego)
    local _wp = workspace:FindFirstChild("Workplace")
    if _wp then
        local _wcc = _wp:FindFirstChild("CoinContainer")
        if _wcc and #_wcc:GetChildren() > 0 then
            return _wcc, "Workplace"
        end
    end
    -- Fallback: CoinContainer en cualquier hijo de workspace
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") or obj:IsA("Folder") then
            local cc = obj:FindFirstChild("CoinContainer")
            if cc and #cc:GetChildren() > 0 then
                return cc, obj.Name
            end
        end
    end
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj.Name == "CoinContainer" then
            if #obj:GetChildren() > 0 then
                return obj, (obj.Parent and obj.Parent.Name or "?")
            end
        end
    end
    local coinCount = 0
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("BasePart") and obj.Name == "Coin_Server" then
            coinCount = coinCount + 1
            if coinCount >= 1 then
                local parent = obj.Parent
                if parent and parent ~= workspace then
                    return parent, parent.Name
                end
            end
        end
    end
    return nil, nil
end

function _farmAttachToContainer(cc)
    if _farmCCRef == cc then return end
    if _farmAddedConn   then _farmAddedConn:Disconnect();   _farmAddedConn   = nil end
    if _farmRemovedConn then _farmRemovedConn:Disconnect(); _farmRemovedConn = nil end
    _farmCoinSet   = {}
    _farmCoinCount = 0
    _farmCCRef     = cc
    if not cc then return end

    if _farmContainerIsRS then
        -- RS.Coins.CoinObjects.Coin: cada hijo puede ser Model > CoinVisual > MainCoin
        local function _rsExtractPart(child)
            if child:IsA("BasePart") and _farmCoinNameMatches(child.Name) then return child end
            local found = child:FindFirstChild("MainCoin", true)  -- recursivo atraviesa CoinVisual
            if found and found:IsA("BasePart") then return found end
            return child:FindFirstChildWhichIsA("BasePart")
        end

        for _, child in ipairs(cc:GetChildren()) do
            local part = _rsExtractPart(child)
            if part and part:IsA("BasePart") then
                _farmCoinSet[part] = true
                _farmCoinCount = _farmCoinCount + 1
            end
        end
        -- ChildAdded: cuando llega un nuevo Model al folder de RS
        _farmAddedConn = cc.ChildAdded:Connect(function(child)
            task.defer(function()
                if not child or not child.Parent then return end
                local part = _rsExtractPart(child)
                if part and part:IsA("BasePart") and not _farmCoinSet[part] then
                    _farmCoinSet[part] = true
                    _farmCoinCount = _farmCoinCount + 1
                end
            end)
        end)
        -- ChildRemoved: cuando se recoge una moneda y el Model desaparece
        _farmRemovedConn = cc.ChildRemoved:Connect(function(child)
            local part = child:IsA("BasePart") and child
                      or child:FindFirstChild("MainCoin", true)
                      or child:FindFirstChildWhichIsA("BasePart")
            if part and _farmCoinSet[part] then
                _farmCoinSet[part] = nil
                _farmCoinCount = _farmCoinCount - 1
                if _farmCoinCount < 0 then _farmCoinCount = 0 end
            end
        end)
    else
        -- Workspace CoinContainer: estructura real es Model > CoinVisual > MainCoin
        -- Usar FindFirstChild recursivo para atravesar cualquier nivel de nesting
        local function _extractCoinPart(child)
            if child:IsA("BasePart") and _farmCoinNameMatches(child.Name) then
                return child
            end
            -- Buscar MainCoin recursivo (atraviesa CoinVisual u otro intermediario)
            local found = child:FindFirstChild("MainCoin", true)
            if found and found:IsA("BasePart") then return found end
            -- Fallback: cualquier BasePart nombrada como coin
            for _, desc in ipairs(child:GetDescendants()) do
                if desc:IsA("BasePart") and _farmCoinNameMatches(desc.Name) then
                    return desc
                end
            end
            return nil
        end

        for _, child in ipairs(cc:GetChildren()) do
            local part = _extractCoinPart(child)
            if part then
                _farmCoinSet[part] = true
                _farmCoinCount = _farmCoinCount + 1
            end
        end

        _farmAddedConn = cc.ChildAdded:Connect(function(child)
            task.defer(function()  -- defer para que el Model termine de cargar sus hijos
                if not child or not child.Parent then return end
                local part = _extractCoinPart(child)
                if part and not _farmCoinSet[part] then
                    _farmCoinSet[part] = true
                    _farmCoinCount = _farmCoinCount + 1
                end
            end)
        end)
        _farmRemovedConn = cc.ChildRemoved:Connect(function(child)
            -- Buscar en el set cualquier part que perteneciera a este child
            local part = child:IsA("BasePart") and child
                      or child:FindFirstChild("MainCoin", true)
            if part and _farmCoinSet[part] then
                _farmCoinSet[part] = nil
                _farmCoinCount = _farmCoinCount - 1
                if _farmCoinCount < 0 then _farmCoinCount = 0 end
            else
                -- Fallback: barrer todo el set buscando parts huerfanas
                for p in pairs(_farmCoinSet) do
                    if not p or not p.Parent then
                        _farmCoinSet[p] = nil
                        _farmCoinCount = _farmCoinCount - 1
                        if _farmCoinCount < 0 then _farmCoinCount = 0 end
                    end
                end
            end
        end)
    end
end

_farmLastMapCheck = 0
function EnsureCoinContainerAttached()
    local now = tick()
    if now - _farmLastMapCheck < 0.5 then return end  -- FIX: 3s->0.5s para detectar coins rapido al arrancar
    _farmLastMapCheck = now
    local cc = FindActiveCoinContainer()
    if cc and cc ~= _farmCCRef then
        _farmAttachToContainer(cc)
    elseif not cc and _farmCCRef then
        _farmAttachToContainer(nil)
    end
end

_farmGrabbed   = {}
_farmCacheTime = 0

function _farmRefreshCoinType()
    _farmCCRef = nil  -- forzar re-attach
    _farmContainerIsRS = false  -- resetear flag RS para re-detectar
    _farmLastMapCheck = 0
    _farmGrabbed = {}
    _gFarmGrabbed = {}
    _gRebuildCoinCache()  -- reconstruir cache con el nuevo tipo de moneda
    EnsureCoinContainerAttached()
end

function GetNearestFarmCoin(hrp)
    local best, bestD = nil, math.huge
    local hrpPos = hrp.Position
    for coin in pairs(_farmCoinSet) do
        if coin and coin.Parent and not _farmGrabbed[coin] then
            if coin.Transparency >= 0.99 then
                _farmGrabbed[coin] = true
                break
            end
            local d = (hrpPos - coin.Position).Magnitude
            if d < bestD then bestD = d; best = coin end
        end
    end
    return best, bestD
end

function GetFarmCoinCount()
    local n = 0
    for coin in pairs(_farmCoinSet) do
        if coin and coin.Parent and not _farmGrabbed[coin] then n = n + 1 end
    end
    return n
end

