end

function StartShootSheriff()
    if _shootSheriffRunning then return end
    _shootSheriffRunning = true
    FarmToggles.shootSheriffActive = true

    _shootSheriffThread = _sp(function()
        while _shootSheriffRunning do
            if _inventoryCoins < 40 then
                _w(0.5)
                break
            end

            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not hrp or not hum or hum.Health <= 0 then
                _w(1)
                local char = LocalPlayer.Character
                local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                hum  = char and char:FindFirstChildOfClass("Humanoid")
                if not hrp then _w(1); break end
            end

            local savedPos = hrp.CFrame

            local gun = _findGun(char)

            if not gun then
                local gunDrop = nil
                local playerChars = {}
                for _, p in ipairs(_cachedPlayers) do
                    if p.Character then playerChars[p.Character] = true end
                end
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if (obj.Name == "GunDrop" or obj.Name == "Gun") and obj:IsA("Tool") then
                        if not playerChars[obj.Parent] then
                            local h = obj:FindFirstChild("Handle")
                            if h and h:IsA("BasePart") then
                                gunDrop = obj; break
                            end
                        end
                    end
                end
                if gunDrop then
                    local gPart = gunDrop:FindFirstChild("Handle") or gunDrop:FindFirstChildWhichIsA("BasePart")
                    if gPart then
                        -- La GUN viene al jugador  NO blink del HRP
                        local grabPos = hrp.Position + Vector3.new(0, -1, 0)
                        pcall(function()
                            gPart.CFrame = CFrame.new(grabPos)
                            gunDrop:PivotTo(CFrame.new(grabPos))
                        end)
                        _w(0)
                        pcall(function()
                            firetouchinterest(hrp, gPart, 0)
                            _w(0)
                            firetouchinterest(hrp, gPart, 1)
                        end)
                        _w(0.05)
                        if gunDrop and gunDrop.Parent ~= char and gunDrop.Parent ~= LocalPlayer.Backpack then
                            -- Segundo intento: mover a posicin exacta del HRP
                            pcall(function()
                                gPart.CFrame = CFrame.new(hrp.Position)
                                gunDrop:PivotTo(CFrame.new(hrp.Position))
                            end)
                            _w(0)
                            pcall(function()
                                firetouchinterest(hrp, gPart, 0)
                                _w(0)
                                firetouchinterest(hrp, gPart, 1)
                            end)
                            _w(0.05)
                            -- ltimo recurso: EquipTool
                            if gunDrop.Parent then
                                pcall(function() hum:EquipTool(gunDrop) end)
                            end
                        end
                    end
                    _w(0.15)
                    gun = _findGun(char)
                    if gun then
 CreateCustomNotification("AUTO GRAB GUN", " Gun agarrada (fluido)", 2)
                    end
                else
                    _w(0.5)
                end
            end

            if gun and not _findGunIn(char) then
                pcall(function() hum:EquipTool(gun) end)
                _w(0.2)
                gun = _findGunIn(char)
            end

            if gun and _findGunIn(char) then
                _w(3)
                local murder = findMurderer()
                if murder and murder.Character then
                    local mHRP = murder.Character:FindFirstChild("HumanoidRootPart")
                    if mHRP then
                        local mCF = mHRP.CFrame
                        hrp.CFrame = CFrame.new(mCF.Position - mCF.LookVector * 5, mHRP.Position)
                        _w(0.15)
                        local shootRem = gun:FindFirstChild("Shoot")
                        if not shootRem then
                            for _, v in ipairs(gun:GetDescendants()) do
                                if v:IsA("RemoteEvent") then shootRem = v; break end
                            end
                        end
                        if shootRem and shootRem:IsA("RemoteEvent") then
                            local oCF = hrp.CFrame
                            local _dir2 = (mHRP.Position - oCF.Position).Unit
                            local tCF = CFrame.new(mHRP.Position, mHRP.Position + _dir2)
                            pcall(function() shootRem:FireServer(oCF, tCF) end)
                            _w(0.05)
                            pcall(function() shootRem:FireServer(oCF, tCF) end)
                        else
                            -- FIX: sin redireccin de cmara
                            _fireGunMM2(gun)
                            _w(0.05)
                            _fireGunMM2(gun)
                        end
 CreateCustomNotification("SHOOT SHERIFF", "Disparado al murder!", 2)
                    end
                end
                hrp.CFrame = savedPos
            end

            _w(3)
        end
    end)
end

