function StartShootMurder()
    if _shootMurderEnabled then StopShootMurder() end
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        _shootMurderSavedCF = hrp.CFrame  -- guardar posicin al activar
    end
    _shootMurderEnabled = true

    _shootMurderThread = _sp(function()
        while _shootMurderEnabled do
            local c   = LocalPlayer.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            local hum = c and c:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then _w(1); break end

            local savedCF = hrp.CFrame

            local gun = _findGun(c)

            if not gun then
                local playerChars = {}
                for _, p in ipairs(_cachedPlayers) do
                    if p.Character then playerChars[p.Character] = true end
                end
                local gunDrop = nil
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if (obj.Name == "GunDrop" or obj.Name == "Gun")
                    and obj:IsA("Tool")
                    and not playerChars[obj.Parent] then
                        gunDrop = obj; break
                    end
                end

                if gunDrop then
                    local gPart = gunDrop:FindFirstChild("Handle") or gunDrop:FindFirstChildWhichIsA("BasePart")
                    if gPart then
                        -- La GUN viene al jugador  NO blink del HRP
                        local grabPos = hrp.Position + Vector3.new(0, -1, 0)
                        pcall(function()
                            gPart.CFrame = CFrame.new(grabPos)
                            gunDrop:PivotTo(CFrame.new(grabPos))
                        end)
                        _w(0)
                        pcall(function()
                            firetouchinterest(hrp, gPart, 0)
                            _w(0)
                            firetouchinterest(hrp, gPart, 1)
                        end)
                        _w(0.05)
                        if gunDrop and gunDrop.Parent ~= c and gunDrop.Parent ~= LocalPlayer.Backpack then
                            pcall(function()
                                gPart.CFrame = CFrame.new(hrp.Position)
                                gunDrop:PivotTo(CFrame.new(hrp.Position))
                            end)
                            _w(0)
                            pcall(function()
                                firetouchinterest(hrp, gPart, 0)
                                _w(0)
                                firetouchinterest(hrp, gPart, 1)
                            end)
                            _w(0.05)
                            if gunDrop.Parent then
                                pcall(function() hum:EquipTool(gunDrop) end)
                            end
                        end
                    end
                    _w(0.15)
                    gun = _findGun(c)
                end

                pcall(function() hrp.CFrame = savedCF end)
                _w(0.3)
            end

            if gun and not _findGunIn(c) then
                pcall(function() hum:EquipTool(gun) end)
                _w(0.2)
                gun = _findGunIn(c)
            end

            if not gun then
                _w(1)
                break
            end

            if not _shootMurderEnabled then break end

            murder = findMurderer()
            if murder and murder.Character then
                local mHRP = murder.Character:FindFirstChild("HumanoidRootPart")
                local mHum = murder.Character:FindFirstChildOfClass("Humanoid")
                if mHRP and mHum and mHum.Health > 0 then
                    -- FIX DESYNC LOBBY: no TP si la ronda no est activa o el murder
                    -- est en el lobby (Y > 70 = coordenada del lobby en MM2).
                    -- Sin este chequeo el toggle te mandaba al lobby durante la carga
                    -- de ronda porque _roleCache.murderer apuntaba al murder viejo.
                    if _G._betweenRounds or not _G._roundStartTime
                    or (os.clock() - (_G._roundStartTime or 0)) < 1.5 then  -- FIX #3
                        _w(0.5); break
                    end
                    if mHRP.Position.Y > 70 then
                        -- Murder est en el lobby  cache desactualizado, esperar
                        _w(0.5); break
                    end
                    local mCF = mHRP.CFrame
                    pcall(function()
                        hrp.CFrame = CFrame.new(mCF.Position - mCF.LookVector * 4, mHRP.Position)
                    end)
                    _w(0.15)

                    local shootRem = gun:FindFirstChild("Shoot")
                    if not shootRem then
                        for _, v in ipairs(gun:GetDescendants()) do
                            if v:IsA("RemoteEvent") then shootRem = v; break end
                        end
                    end

                    if shootRem and shootRem:IsA("RemoteEvent") then
                        local graNode = hrp:FindFirstChild("GunRaycastAttachment")
                        local graCF   = graNode and graNode.WorldCFrame or hrp.CFrame
                        local tCF     = CFrame.new(mHRP.Position, mHRP.Position + Vector3.new(0,1,0))
                        pcall(function() shootRem:FireServer(graCF, tCF) end)
                        _w(0.05)
                        pcall(function() shootRem:FireServer(graCF, tCF) end)
                    else
                        local cam = _Camera
                        local origCF = cam.CFrame
                        pcall(function() cam.CFrame = CFrame.lookAt(cam.CFrame.Position, mHRP.Position) end)
                        _fireGunMM2(gun)
                        _w(0.05)
                        _fireGunMM2(gun)
                        pcall(function() cam.CFrame = origCF end)
                    end

 CreateCustomNotification("SHOOT MURDER", "Disparado -> " .. murder.Name, 2)
                    _w(0.3)
                end
            end

            pcall(function() hrp.CFrame = savedCF end)
            _w(0.5)
        end
    end)
end

