function EquipKnife()
    local char = LocalPlayer.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum then return nil end

    -- Validador: mismo criterio que _isKnifeTool  nunca acepta guns ni bombas
    local function _isRealKnife(t)
        if not t or not t:IsA("Tool") then return false end
        local n = t.Name:lower()
        if n:find("gun") or n:find("sheriff") or n:find("revolver")
           or n:find("bomb") or n:find("snow") or t:FindFirstChild("GunClient") then
            return false
        end
        if not t:FindFirstChild("Handle") then return false end
        return t:FindFirstChild("KnifeClient") ~= nil
            or n:find("knife") or n:find("blade")
            or t.Name == "Knife" or t.Name == "VIPKnife"
            or t.Name == "DefaultKnife" or t.Name == "MurderKnife"
    end

    -- 1. Ya equipada en el personaje
    for _, t in ipairs(char:GetChildren()) do
        if _isRealKnife(t) then return t end
    end

    -- 2. Buscar en backpack y equipar
    local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if _isRealKnife(t) then
                pcall(function() hum:EquipTool(t) end)
                _w(0.15)
                for _, c in ipairs(char:GetChildren()) do
                    if _isRealKnife(c) then return c end
                end
            end
        end
    end

    return nil
end

function FireKnifeOnTarget(knife, targetHrp)
    if not knife or not targetHrp then return end
    local c   = LocalPlayer.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    -- Guardar posicin del jugador para que NO se mueva
    local savedCF  = hrp and hrp.CFrame
    local savedVel = hrp and hrp.AssemblyLinearVelocity

    pcall(function()
        local ev = knife:FindFirstChild("Events")
        if ev then
            local stab = ev:FindFirstChild("KnifeStabbed")
            if stab then pcall(function() stab:FireServer() end) end
            local thrown = ev:FindFirstChild("KnifeThrown")
            local handle = knife:FindFirstChild("Handle")
            if thrown and handle then
                pcall(function() thrown:FireServer(handle.CFrame, targetHrp.CFrame) end)
            end
        end
    end)
    pcall(function()
        for _, child in ipairs(knife:GetDescendants()) do
            if child:IsA("RemoteEvent") then
                pcall(function() child:FireServer(targetHrp) end)
            end
        end
    end)
    pcall(function()
        cam  = _Camera
        origCam = cam.CFrame
        if hrp then
            cam.CFrame = CFrame.lookAt(hrp.Position, targetHrp.Position)
        end
        knife:Activate()
        cam.CFrame = origCam
    end)
    -- Restaurar posicin inmediatamente para que el personaje NO se mueva
    if hrp and savedCF then
        _sp(function()
            pcall(function()
                hrp.CFrame = savedCF
                hrp.AssemblyLinearVelocity = savedVel or Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end)
    end
end

function StartKillAllMurder()
    if _killAllRunning then return end
    local knife = EquipKnife()
    if not knife then
        local _kaDict2 = (_LangStrings and _LangStrings[_G.HubLanguage or "[US] English"]) or _LangStrings["[US] English"]
 CreateCustomNotification("KILL ALL MURDER", _kaDict2.no_knife, 3)
        FarmToggles.killAllMurderActive = false
        return
    end
    _killAllRunning = true
    FarmToggles.killAllMurderActive = true
    local _kaDict = (_LangStrings and _LangStrings[_G.HubLanguage or "[US] English"]) or _LangStrings["[US] English"]
 CreateCustomNotification("KILL ALL MURDER", _kaDict.knife_aura, 2)

    local _hbTkillAll = 0
    _killAllConn = _safeConnect(RunService.Heartbeat, function()
        _hbTkillAll = _hbTkillAll + 1
        if _hbTkillAll < 3 then return end
        _hbTkillAll = 0
        if not _killAllRunning then return end
        if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda

        local char  = LocalPlayer.Character
        local myHRP = char and char:FindFirstChild("HumanoidRootPart")
        if not myHRP then return end

        -- Guardar posicin para que el personaje NO se mueva
        local savedCF  = myHRP.CFrame
        local savedVel = myHRP.AssemblyLinearVelocity

        -- Re-equipar knife si se perdi
        local currentKnife = char:FindFirstChild("Knife")
        if not currentKnife then
            currentKnife = EquipKnife()
            if not currentKnife then
                StopKillAllMurder()
                local _kaDict3 = (_LangStrings and _LangStrings[_G.HubLanguage or "[US] English"]) or _LangStrings["[US] English"]
 CreateCustomNotification("KILL ALL MURDER", _kaDict3.knife_lost, 3)
                return
            end
        end
        knife = currentKnife

        -- Knife Aura 10K  atacar a TODOS los jugadores en rango
        for _, target in ipairs(_cachedPlayers) do
            if target ~= LocalPlayer and target.Character then
                local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                local tHum = target.Character:FindFirstChildOfClass("Humanoid")
                if tHRP and tHum and tHum.Health > 0 then
                    local dist = (myHRP.Position - tHRP.Position).Magnitude
                    if dist <= 10000 then
                        -- WALL CHECK: no atacar a trav?s de paredes
                        local eyePos  = myHRP.Position + Vector3.new(0, 1.5, 0)
                        local bodyPos = tHRP.Position  + Vector3.new(0, 0.8, 0)
                        if wallCheckRaycast(eyePos, bodyPos) then
                            FireKnifeOnTarget(knife, tHRP)
                        end
                    end
                end
            end
        end

        -- Restaurar posicin del personaje local  NO se mueve
        _sp(function()
            pcall(function()
                myHRP.CFrame = savedCF
                myHRP.AssemblyLinearVelocity = savedVel or Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
            end)
        end)
    end)
end

