function FindMapBase()
    local _m2f = Workspace:FindFirstChild("Mansion2")
    if _m2f then
        local _bf = _m2f:FindFirstChild("Base")
        if _bf and _bf:IsA("BasePart") then return _bf end
    end
    local names = {"Base","Floor","Baseplate","Ground","Map","Terrain"}
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") or obj:IsA("Folder") then
            if obj:FindFirstChild("CoinContainer") then
                for _, n in ipairs(names) do
                    local b = obj:FindFirstChild(n)
                    if b and b:IsA("BasePart") then return b end
                end
                for _, child in ipairs(obj:GetChildren()) do
                    if child:IsA("BasePart") and child.Size.Y < 5 and child.Size.X > 50 then
                        return child
                    end
                end
            end
        end
    end
    for _, n in ipairs(names) do
        local b = workspace:FindFirstChild(n)
        if b and b:IsA("BasePart") then return b end
    end
    return nil
end

