-- FIX LAG: cachear monedas con eventos en vez de GetDescendants() cada frame
-- FIX local limit: gCoinCache helpers en do..end (5 locales liberados)
do
    local _gCoinCache = {}
    local _gCoinCacheConn1, _gCoinCacheConn2

    local function _gIsCoin(obj)
        if not obj:IsA("BasePart") then return false end
        local names = _farmCoinTypeMap[_farmCoinTypeName] or _farmCoinTypeMap["Coin"]
        local lower = obj.Name:lower()
        for _, n in ipairs(names) do
            if lower == n:lower() then return true end
        end
        return false
    end

    -- Extrae el BasePart real de una coin dado cualquier nivel de nesting
    -- Soporta: BasePart directo, Model>MainCoin, Model>CoinVisual>MainCoin
    local function _extractMainPart(child)
        if child:IsA("BasePart") and _gIsCoin(child) then return child end
        -- Busqueda recursiva: atraviesa CoinVisual u otro intermediario
        local found = child:FindFirstChild("MainCoin", true)
        if found and found:IsA("BasePart") then return found end
        -- Fallback: cualquier BasePart con nombre de coin
        for _, desc in ipairs(child:GetDescendants()) do
            if _gIsCoin(desc) then return desc end
        end
        return nil
    end

    local function _gRebuildCoinCache()
        _gCoinCache = {}
        -- Prioridad 1: workspace.Workplace.CoinContainer (ruta real del juego)
        pcall(function()
            local wp = workspace:FindFirstChild("Workplace")
            local cc = wp and wp:FindFirstChild("CoinContainer")
            if cc then
                for _, child in ipairs(cc:GetChildren()) do
                    local part = _extractMainPart(child)
                    if part then _gCoinCache[part] = true end
                end
            end
        end)
        -- Prioridad 2: cualquier CoinContainer en workspace (otros mapas)
        if not next(_gCoinCache) then
            for _, obj in ipairs(workspace:GetDescendants()) do
                if _gIsCoin(obj) then _gCoinCache[obj] = true end
            end
        end
        -- Prioridad 3: RS.Coins.CoinObjects.Coin (modelo de red)
        if not next(_gCoinCache) and (_farmCoinTypeName == "Coin" or _farmCoinTypeName == nil) then
            pcall(function()
                local coinFolder = game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
                for _, child in ipairs(coinFolder:GetChildren()) do
                    local part = _extractMainPart(child)
                    if part and part:IsA("BasePart") then
                        _gCoinCache[part] = true
                    end
                end
            end)
        end
    end

    local function _gStartCoinCache()
        _gRebuildCoinCache()
        if _gCoinCacheConn1 then _gCoinCacheConn1:Disconnect() end
        if _gCoinCacheConn2 then _gCoinCacheConn2:Disconnect() end
        -- DescendantAdded: usar task.defer para esperar que el Model termine de cargar hijos
        _gCoinCacheConn1 = workspace.DescendantAdded:Connect(function(obj)
            task.defer(function()
                if not obj or not obj.Parent then return end
                if _gIsCoin(obj) then
                    _gCoinCache[obj] = true
                elseif obj:IsA("Model") or obj:IsA("Folder") then
                    local part = _extractMainPart(obj)
                    if part then _gCoinCache[part] = true end
                end
            end)
        end)
        _gCoinCacheConn2 = workspace.DescendantRemoving:Connect(function(obj)
            _gCoinCache[obj] = nil
        end)
        -- Escuchar tambien RS.Coins.CoinObjects.Coin para detectar nuevas monedas
        if _farmCoinTypeName == "Coin" or _farmCoinTypeName == nil then
            pcall(function()
                local coinFolder = game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
                coinFolder.ChildAdded:Connect(function(child)
                    task.defer(function()
                        if not child or not child.Parent then return end
                        local part = _extractMainPart(child)
                        if part and part:IsA("BasePart") then
                            _gCoinCache[part] = true
                        end
                    end)
                end)
                coinFolder.ChildRemoved:Connect(function(child)
                    local part = child:IsA("BasePart") and child
                              or child:FindFirstChild("MainCoin", true)
                    if part then _gCoinCache[part] = nil end
                end)
            end)
        end
    end

    -- Expose as globals for functions defined outside this block
    function _gGetCoins()
        local list = {}
        for coin in pairs(_gCoinCache) do
            if coin.Parent and coin.Transparency < 0.99 then
                table.insert(list, coin)
            else
                _gCoinCache[coin] = nil
            end
        end
        return list
    end

    function _gStartCoinCachePublic()
        _gStartCoinCache()
    end
end

function _gGetNearest(pos)
    local coins = _gGetCoins()
    -- RANDOM COIN: si est activo el modo aleatorio, elegir moneda random
    if _G._farmRandomCoinActive and #coins > 0 then
        local available = {}
        for _, c in ipairs(coins) do
            if c and c.Parent and not _gFarmGrabbed[c] then
                table.insert(available, c)
            end
        end
        if #available > 0 then
            local chosen = available[math.random(1, #available)]
            return chosen, (pos - chosen.Position).Magnitude
        end
    end
    -- MODO NORMAL: moneda ms cercana
    local best, bestD = nil, math.huge
    for _, c in ipairs(coins) do
        if c and c.Parent and not _gFarmGrabbed[c] then
            local d = (pos - c.Position).Magnitude
            if d < bestD then bestD = d; best = c end
        end
    end
    return best, bestD
end

-- Fuente de verdad para saber si estamos en lobby.
-- Usa _betweenRounds y _roundStartTime como se?ales principales.
-- FIXED: workspace:FindFirstChild("Lobby") eliminado -- en MM2 el objeto Lobby
-- permanece en workspace durante toda la ronda, causando que _isInLobby()
-- devuelva true siempre y bloquee el vuelo hacia coins indefinidamente.
local function _isInLobby()
    if _G._betweenRounds then return true end
    if not _G._roundStartTime or _G._roundStartTime == 0 then
        -- Doble chequeo: si hay coins activas en el mapa, hay ronda en curso
        local hasCoins = false
        pcall(function()
            local wp = workspace:FindFirstChild("Workplace")
            local cc = wp and wp:FindFirstChild("CoinContainer")
            if cc and #cc:GetChildren() > 0 then hasCoins = true end
        end)
        pcall(function()
            if not hasCoins then
                local m2 = workspace:FindFirstChild("Mansion2")
                local cc = m2 and m2:FindFirstChild("CoinContainer")
                if cc and #cc:GetChildren() > 0 then hasCoins = true end
            end
        end)
        if hasCoins then return false end
        return true
    end
    return false
end

function _gDestroyPhysics()
    if _gFarmBV and _gFarmBV.Parent then pcall(function() _gFarmBV:Destroy() end) end
    if _gFarmBG and _gFarmBG.Parent then pcall(function() _gFarmBG:Destroy() end) end
    _gFarmBV = nil; _gFarmBG = nil
end

-- Profundidad bajo el mapa para el modo BelowMap (studs bajo el suelo)
-- Con rotacion 90deg el HRP esta acostado: necesita bajar ~2.5 studs bajo el piso
_belowMapDepth = -2.6  -- studs bajo el suelo (suficiente para quedar oculto acostado)

function _gGetGroundY(fromPos)
    local origin = fromPos or Vector3.new(0, 500, 0)
    local rp = RaycastParams.new()
    rp.FilterDescendantsInstances = {LocalPlayer.Character}
    rp.FilterType = Enum.RaycastFilterType.Exclude
    -- Siempre raycastear desde el cielo para evitar falsos positivos si el
    -- personaje esta dentro de un techo/piso (el ray golpearia esa geometria)
    local skyOrigin = Vector3.new(origin.X, 2000, origin.Z)
    local result = workspace:Raycast(skyOrigin, Vector3.new(0, -2500, 0), rp)
    if result then
        return result.Position.Y
    end
    -- Fallback: buscar base del mapa
    local base = FindMapBase()
    if base then return base.Position.Y + base.Size.Y / 2 end
    return 0
end

function _gMakePhysics(hrp, useTilt)
    _gDestroyPhysics()
    local bv = Instance.new("BodyVelocity")
    -- En modo BelowMap necesitamos control total en Y para clavar al personaje bajo el suelo.
    -- En modo Normal/Safe NO aplicamos fuerza en Y para que la gravedad funcione normal
    -- y el personaje no se pegue al techo.
    if _autoFarmMode == "BelowMap" then
        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    else
        bv.MaxForce = Vector3.new(math.huge, 0, math.huge)
    end
    bv.Velocity = Vector3.zero; bv.P = 1e6; bv.Parent = hrp
    _gFarmBV = bv
    -- BodyGyro removido: interferia con el movimiento y el contacto con monedas
end

_gFarmTouchConn = nil  -- firetouchinterest en monedas cercanas

function _gExpandFarmHitbox(hrp)
    if not hrp then return end
    -- Solo firetouchinterest, sin modificar el tama?o del personaje
    if _gFarmTouchConn then
        pcall(function() _gFarmTouchConn:Disconnect() end)
        _gFarmTouchConn = nil
    end
    local _touchTick = 0
    _gFarmTouchConn = game:GetService("RunService").Heartbeat:Connect(function()
        if not _gFarmRunning or _autoFarmMode ~= "BelowMap" then
            if _gFarmTouchConn then
                pcall(function() _gFarmTouchConn:Disconnect() end)
                _gFarmTouchConn = nil
            end
            return
        end
        _touchTick = _touchTick + 1
        if _touchTick < 3 then return end
        _touchTick = 0
        if not firetouchinterest then return end
        local c  = LocalPlayer.Character
        local rp = c and c:FindFirstChild("HumanoidRootPart")
        if not rp then return end
        local coins = _gGetCoins and _gGetCoins() or {}
        for _, coin in ipairs(coins) do
            if coin and coin.Parent then
                pcall(function()
                    firetouchinterest(rp, coin, 0)
                    firetouchinterest(rp, coin, 1)
                end)
            end
        end
    end)
end

function _gRestoreFarmHitbox()
    if _gFarmTouchConn then
        pcall(function() _gFarmTouchConn:Disconnect() end)
        _gFarmTouchConn = nil
    end
end

-- Tras respawn en BelowMap: reinicia el BV, el lock de Humanoid y el loop de movimiento.
function _restoreBelowMapPose(char)
    if _autoFarmMode ~= "BelowMap" then return end
    task.spawn(function()
        local hrp = char:WaitForChild("HumanoidRootPart", 5)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end
        task.wait(0.15)
        if not (char.Parent and hum.Health > 0) then return end

        -- Limpiar BV anterior y crear FarmAntiGravity fresco
        pcall(function()
            local old = hrp:FindFirstChild("FarmAntiGravity")
            if old then old:Destroy() end
        end)
        _gDestroyPhysics()
        local bv = Instance.new("BodyVelocity")
        bv.Name      = "FarmAntiGravity"
        bv.MaxForce  = Vector3.new(math.huge, math.huge, math.huge)
        bv.Velocity  = Vector3.zero
        bv.Parent    = hrp
        _gFarmBV = bv

        -- Reiniciar lock de Humanoid
        if _gBelowFloatConn then
            pcall(function() _gBelowFloatConn:Disconnect() end)
            _gBelowFloatConn = nil
        end
        local _gBelowTick = 0
        _gBelowFloatConn = RunService.Heartbeat:Connect(function(dt)
            if not _gFarmRunning or _autoFarmMode ~= "BelowMap" then
                if _gBelowFloatConn then _gBelowFloatConn:Disconnect(); _gBelowFloatConn = nil end
                return
            end
            -- 10Hz is plenty for platform stand enforcement
            _gBelowTick = _gBelowTick + dt
            if _gBelowTick < 0.10 then return end
            _gBelowTick = 0
            local c   = LocalPlayer.Character
            local h   = c and c:FindFirstChildOfClass("Humanoid")
            if h and h.Health > 0 then
                h.PlatformStand = true
                pcall(function() h:ChangeState(Enum.HumanoidStateType.Physics) end)
            end
        end)

        -- Relanzar el loop de movimiento
        _bmBlacklist = {}
        _gBelowMapLoop()
    end)
end

-- ==================================================================
-- AUTO FARM - Logica precisa con noclip, BV anti-gravedad y firetouchinterest
-- ==================================================================
_farmBlacklist        = {}
_farmNcConn           = nil
_farmStateConn        = nil
_autoFarmAlturaOffset = 0.60  -- studs bajo la moneda (fijo)

function _farmGetNearestCoin()
    local player = LocalPlayer
    if not player.Character or not player.Character:FindFirstChild("HumanoidRootPart") then return nil end
    local root = player.Character.HumanoidRootPart
    local nearest, minDist = nil, math.huge

    local function _tryPart(v)
        if v and v:IsA("BasePart") and v.Parent and not _farmBlacklist[v] and v.Transparency < 0.99 then
            local dist = (v.Position - root.Position).Magnitude
            if dist < minDist then minDist = dist; nearest = v end
        end
    end

    -- Helper: extrae la BasePart real de un hijo del CoinContainer
    local function _extractFromChild(child)
        if child:IsA("BasePart") then return child end
        local found = child:FindFirstChild("MainCoin", true)
        if found and found:IsA("BasePart") then return found end
        return child:FindFirstChildWhichIsA("BasePart")
    end

    -- Prioridad 0: workspace.Mansion2.CoinContainer -- buscar la mas cercana (FIX: eliminado hardcodeo de [6])
    pcall(function()
        local m2 = workspace:FindFirstChild("Mansion2")
        if not m2 then return end
        local cc = m2:FindFirstChild("CoinContainer")
        if not cc then return end
        for _, child in ipairs(cc:GetChildren()) do
            local part = _extractFromChild(child)
            _tryPart(part)
        end
    end)

    -- Prioridad 1: usar _farmCoinSet (cache principal, ya apunta a Mansion2.CoinContainer
    -- gracias al cambio en FindActiveCoinContainer)
    EnsureCoinContainerAttached()
    for coin in pairs(_farmCoinSet) do
        _tryPart(coin)
    end

    -- Prioridad 2: workspace.Mansion2.CoinContainer completo (todas las coins, no solo [6])
    if not nearest then
        pcall(function()
            local m2 = workspace:FindFirstChild("Mansion2")
            local cc = m2 and m2:FindFirstChild("CoinContainer")
            if cc then
                for _, child in ipairs(cc:GetChildren()) do
                    _tryPart(_extractFromChild(child))
                end
            end
        end)
    end

    -- Prioridad 3: workspace.Workplace.CoinContainer directo (otros mapas)
    if not nearest then
        pcall(function()
            local wp = workspace:FindFirstChild("Workplace")
            local cc = wp and wp:FindFirstChild("CoinContainer")
            if cc then
                for _, child in ipairs(cc:GetChildren()) do
                    local part = child:IsA("BasePart") and child
                              or child:FindFirstChild("MainCoin", true)
                    _tryPart(part)
                end
            end
        end)
    end

    -- Prioridad 4: cualquier CoinContainer en workspace (otros mapas)
    if not nearest then
        for _, obj in ipairs(workspace:GetChildren()) do
            local cc = obj:FindFirstChild("CoinContainer")
            if cc then
                for _, v in ipairs(cc:GetDescendants()) do
                    if v:IsA("BasePart") and v.Name == "MainCoin" then
                        _tryPart(v)
                    end
                end
            end
        end
    end

    -- Prioridad 5: RS.Coins.CoinObjects.Coin (modelo de red, ultimo recurso)
    if not nearest then
        pcall(function()
            local coinFolder = game:GetService("ReplicatedStorage").Coins.CoinObjects.Coin
            for _, child in ipairs(coinFolder:GetChildren()) do
                local part = child:IsA("BasePart") and child
                          or child:FindFirstChild("MainCoin", true)
                          or child:FindFirstChildWhichIsA("BasePart")
                _tryPart(part)
            end
        end)
    end

    return nearest
end

function StopAutoFarm()
    pcall(function() FarmSystem.Stop() end)
    _gFarmRunning = false
    FarmToggles.autoFarmActive = false
    FarmSystem.state.on = false
    _farmBlacklist = {}
    _gFarmGrabbed  = {}

    if _farmNcConn    then _farmNcConn:Disconnect();    _farmNcConn    = nil end
    if _farmStateConn then _farmStateConn:Disconnect(); _farmStateConn = nil end

    pcall(function()
        local player = LocalPlayer
        if not player.Character then return end
        local rootPart = player.Character:FindFirstChild("HumanoidRootPart")
        local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
        -- Limpiar todos los objetos fisicos del farm
        for _, name in ipairs({"FarmBV", "FarmBG", "FarmBP", "FarmAntiGravity"}) do
            local obj = rootPart and rootPart:FindFirstChild(name)
            if obj then pcall(function() obj:Destroy() end) end
        end
        if humanoid then
            humanoid.PlatformStand = false
            pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end)
        end
        if rootPart then
            rootPart.Anchored = false
            rootPart.AssemblyLinearVelocity  = Vector3.zero
            rootPart.AssemblyAngularVelocity = Vector3.zero
            rootPart.CFrame = CFrame.new(rootPart.Position)
        end
    end)
end

function StartAutoFarm()
    pcall(function() FarmSystem.Stop() end)
    StopAutoFarm()
    _gFarmRunning = true
    _gFarmGrabbed = {}
    _farmBlacklist = {}
    FarmToggles.autoFarmActive = true
    FarmSystem.state.on = true

    local player = LocalPlayer

    -- Loop principal: solo firetouchinterest, sin mover el personaje en absoluto
    local _farmNcTick = 0
    _farmNcConn = RunService.Heartbeat:Connect(function(dt)
        if not _gFarmRunning then return end
        -- Throttle: coin scan doesn't need 60fps
        _farmNcTick = _farmNcTick + dt
        if _farmNcTick < 0.10 then return end
        _farmNcTick = 0
        local character = player.Character
        if not character then return end
        local rootPart = character:FindFirstChild("HumanoidRootPart")
        if not rootPart then return end

        -- Buscar moneda mas cercana
        local best, bestD = nil, math.huge
        local mansion = workspace:FindFirstChild("Mansion2")
        if mansion and mansion:FindFirstChild("CoinContainer") then
            for _, v in pairs(mansion.CoinContainer:GetDescendants()) do
                if v.Name == "MainCoin" and v:IsA("BasePart") and not _farmBlacklist[v] then
                    local d = (v.Position - rootPart.Position).Magnitude
                    if d < bestD then bestD = d; best = v end
                end
            end
        end
        if not best then
            for _, v in pairs(workspace:GetDescendants()) do
                if v.Name == "MainCoin" and v:IsA("BasePart") and not _farmBlacklist[v] then
                    local d = (v.Position - rootPart.Position).Magnitude
                    if d < bestD then bestD = d; best = v end
                end
            end
        end

        if best and best.Parent then
            pcall(function() firetouchinterest(rootPart, best, 0) end)
            pcall(function() firetouchinterest(rootPart, best, 1) end)
        end
    end)
end


_killKnifeEnabled = false
_killKnifeConn    = nil

function StartKillAtKnife()
    if _killKnifeConn then _killKnifeConn:Disconnect(); _killKnifeConn = nil end
    _killKnifeEnabled = true
    local knife = EquipKnife and EquipKnife()
    if not knife then
 CreateCustomNotification("KILL AT KNIFE", "No hay knife en inventario!", 3)
        _killKnifeEnabled = false
        return
    end
 CreateCustomNotification("KILL AT KNIFE", "Knife Aura 10K activo como Murder!", 2)
    local _hbTkillKnife = 0
    local _killKnifeDt = 0
    _killKnifeConn = _safeConnect(RunService.Heartbeat, function(dt)
        _killKnifeDt = _killKnifeDt + dt; if _killKnifeDt < 0.4 then return end; _killKnifeDt = 0  -- OPT: 400ms
        if not _killKnifeEnabled then
            if _killKnifeConn then _killKnifeConn:Disconnect(); _killKnifeConn = nil end
            return
        end
        if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda
        local char = LocalPlayer.Character
        local myHRP = char and char:FindFirstChild("HumanoidRootPart")
        if not char or not myHRP then return end
        local currentKnife = char:FindFirstChild("Knife")
        if not currentKnife then
            currentKnife = EquipKnife and EquipKnife()
            if not currentKnife then return end
        end
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer and p.Character then
                local tHRP = p.Character:FindFirstChild("HumanoidRootPart")
                local tHum = p.Character:FindFirstChildOfClass("Humanoid")
                if tHRP and tHum and tHum.Health > 0 then
                    if (myHRP.Position - tHRP.Position).Magnitude <= 10000 then
                        pcall(function() FireKnifeOnTarget(currentKnife, tHRP) end)
                    end
                end
            end
        end
    end)
end

function StopKillAtKnife()
    _killKnifeEnabled = false
    if _killKnifeConn then _killKnifeConn:Disconnect(); _killKnifeConn = nil end
end

_farmXPSheriffEnabled = false
_farmXPSheriffThread  = nil
_farmXPSheriffSavedCF = nil

function StopFarmXPSheriff()
    _farmXPSheriffEnabled = false
    if _farmXPSheriffThread then
        pcall(function() pcall(function() coroutine.close(_farmXPSheriffThread) end) end)
        _farmXPSheriffThread = nil
    end
end

function StartFarmXPSheriff()
    if _farmXPSheriffEnabled then StopFarmXPSheriff() end
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then _farmXPSheriffSavedCF = hrp.CFrame end
    _farmXPSheriffEnabled = true

    _farmXPSheriffThread = _sp(function()
        while _farmXPSheriffEnabled do
            local c   = LocalPlayer.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            local hum = c and c:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then _w(1); break end

            local savedCF = _farmXPSheriffSavedCF or hrp.CFrame

            local gun = _findGun(c)
            if not gun then
                local playerChars = {}
                for _, p in ipairs(_cachedPlayers) do
                    if p.Character then playerChars[p.Character] = true end
                end
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if (obj.Name == "GunDrop" or obj.Name == "Gun")
                    and obj:IsA("Tool") and not playerChars[obj.Parent] then
                        local gPart = obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart")
                        if gPart then
                            -- Intento 1: firetouchinterest sin mover nada
                            pcall(function()
                                firetouchinterest(hrp, gPart, 0)
                                _w(0)
                                firetouchinterest(hrp, gPart, 1)
                            end)
                            _w(0.1)
                            gun = _findGun(c)
                            if gun then break end
                            -- Intento 2: la GUN viene al jugador (NO blink del HRP)
                            local grabPos18 = hrp.Position + Vector3.new(0, -1, 0)
                            pcall(function()
                                gPart.CFrame = CFrame.new(grabPos18)
                                obj:PivotTo(CFrame.new(grabPos18))
                            end)
                            _w(0)
                            pcall(function()
                                firetouchinterest(hrp, gPart, 0)
                                _w(0)
                                firetouchinterest(hrp, gPart, 1)
                            end)
                            _w(0.1)
                            gun = _findGun(c)
                            if gun then break end
                            -- ltimo recurso: EquipTool
                            if obj.Parent then
                                pcall(function() hum:EquipTool(obj) end)
                                _w(0.1)
                                gun = _findGun(c)
                                if gun then break end
                            end
                        end
                    end
                end
            end

            if not gun then _w(2); break end

            if not _findGunIn(c) then
                pcall(function() hum:EquipTool(gun) end)
                _w(0.2)
                gun = _findGunIn(c)
            end
            if not gun then _w(2); break end

            _w(3)
            if not _farmXPSheriffEnabled then break end

            murder = findMurderer()
            if not murder or not murder.Character then
                pcall(function() hrp.CFrame = savedCF end)
                _w(2); break
            end
            mHRP = murder.Character:FindFirstChild("HumanoidRootPart")
            mHum = murder.Character:FindFirstChildOfClass("Humanoid")
            if not mHRP or not mHum or mHum.Health <= 0 then
                pcall(function() hrp.CFrame = savedCF end)
                _w(2); break
            end

            mCF = mHRP.CFrame
            pcall(function()
                hrp.CFrame = CFrame.new(
                    mCF.Position - mCF.LookVector * 8,
                    mHRP.Position
                )
            end)
            _w(0.15)

            shootRem = gun:FindFirstChild("Shoot")
            if not shootRem then
                for _, v in ipairs(gun:GetDescendants()) do
                    if v:IsA("RemoteEvent") then shootRem = v; break end
                end
            end

            gra    = hrp:FindFirstChild("GunRaycastAttachment") or hrp:FindFirstChildWhichIsA("Attachment")
            graCF  = gra and gra.WorldCFrame or hrp.CFrame
            tPos   = mHRP.Position
            dir    = (tPos - graCF.Position).Unit
            tCF    = CFrame.new(tPos, tPos + dir)

            if shootRem and shootRem:IsA("RemoteEvent") then
                pcall(function() shootRem:FireServer(graCF, tCF) end)
                _w(0.05)
                pcall(function() shootRem:FireServer(graCF, tCF) end)
            else
                local cam = _Camera
                local oc  = cam.CFrame
                pcall(function() cam.CFrame = CFrame.lookAt(cam.CFrame.Position, tPos) end)
                _fireGunMM2(gun)
                _w(0.05)
                _fireGunMM2(gun)
                pcall(function() cam.CFrame = oc end)
            end

 CreateCustomNotification("FARM XP SHERIFF", "Disparado -> " .. murder.Name, 1)

            _w(0.3)
            pcall(function() hrp.CFrame = savedCF end)
            _w(0.5)
            _farmXPSheriffSavedCF = hrp and hrp.CFrame or savedCF
        end
    end)
end

_afkXPLobbyEnabled = false
_afkXPLobbyTPed    = false  -- ya hizo TP esta ronda
_afkXPLobbyConn    = nil

function StartAFKXPLobby()
    if _afkXPLobbyConn then _afkXPLobbyConn:Disconnect(); _afkXPLobbyConn = nil end
    _afkXPLobbyTPed = false
    _afkXPLobbyEnabled = true

    local _hbTafkXP = 0
    _afkXPLobbyConn = _safeConnect(RunService.Heartbeat, function()
        _hbTafkXP=_hbTafkXP+1; if _hbTafkXP<5 then return end; _hbTafkXP=0
        if not _afkXPLobbyEnabled or _afkXPLobbyTPed then return end
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer and p.Character then
                if p.Character:FindFirstChild("Knife") then
                    _afkXPLobbyTPed = true
 CreateCustomNotification("AFK XP LOBBY", "Knife detectado -> TP Lobby", 2)
                    _sp(function()
                        _w(0.2)
                        TeleportToLobby()
                    end)
                    return
                end
            end
        end
        murder = findMurderer()
        if murder and murder.Character then
            local g = _findGunIn(murder.Character)
            if g then
                _afkXPLobbyTPed = true
 CreateCustomNotification("AFK XP LOBBY", "Gun del Murder detectada -> TP Lobby", 2)
                _sp(function()
                    _w(0.2)
                    TeleportToLobby()
                end)
                return
            end
        end
    end)

    if not _G._afkXPLobbyRespawnHook then
        _G._afkXPLobbyRespawnHook = true
        LocalPlayer.CharacterAdded:Connect(function()
            _afkXPLobbyTPed = false
        end)
    end
end

function StopAFKXPLobby()
    _afkXPLobbyEnabled = false
    if _afkXPLobbyConn then _afkXPLobbyConn:Disconnect(); _afkXPLobbyConn = nil end
end


ESPSystem = {
    playerESP = {},
    coinESP   = {},
}

function getOrCreateESPGui()
    local pg = LocalPlayer:FindFirstChild("PlayerGui")
    if not pg then return nil end
    local g = pg:FindFirstChild("BypasESP_Persistent")
    if g then return g end
    g = Instance.new("ScreenGui")
    g.Name             = "BypasESP_Persistent"
    g.ResetOnSpawn     = false
    g.ZIndexBehavior   = Enum.ZIndexBehavior.Sibling
    g.DisplayOrder     = 8500
    g.IgnoreGuiInset   = true
    g.Parent           = pg
    return g
end

function removePlayerESP(player)
    local bb = ESPSystem.playerESP[player]
    if bb and bb.Parent then bb:Destroy() end
    ESPSystem.playerESP[player] = nil
end

function updatePlayerESP(player)
    if player == LocalPlayer then return end
    local char = player.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    local role  = GetPlayerRole(player)
    local color = GetRoleColor(role)
    local show  = Settings.esp.enabled.Everyone
        or (Settings.esp.enabled.MurdererOnly and role == "Murderer")
        or (Settings.esp.enabled.SheriffOnly  and role == "Sheriff")
    if not show or not hrp then
        removePlayerESP(player)
        return
    end
    local bb = ESPSystem.playerESP[player]
    if not bb or not bb.Parent then
        local espGui = getOrCreateESPGui()
        if not espGui then return end
        bb = Instance.new("BillboardGui")
        bb.Name           = "PESP_" .. player.Name
        bb.Size           = UDim2.new(0, 120, 0, 60)
        bb.StudsOffset    = Vector3.new(0, 3.2, 0)
        bb.AlwaysOnTop    = true
        bb.ResetOnSpawn   = false
        bb.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        bb.Parent         = espGui
        local nameL = Instance.new("TextLabel", bb)
        nameL.Name                   = "NameLabel"
        nameL.Size                   = UDim2.new(1, 0, 0.5, 0)
        nameL.BackgroundTransparency = 1
        nameL.FontFace = Font.fromEnum(Enum.Font.Arimo)
        nameL.TextSize               = 14
        nameL.TextStrokeTransparency = 0.4
        local roleL = Instance.new("TextLabel", bb)
        roleL.Name                   = "RoleLabel"
        roleL.Size                   = UDim2.new(1, 0, 0.5, 0)
        roleL.Position               = UDim2.new(0, 0, 0.5, 0)
        roleL.BackgroundTransparency = 1
        roleL.FontFace = Font.fromEnum(Enum.Font.Arimo)
        roleL.TextSize               = 12
        roleL.TextStrokeTransparency = 0.4
        ESPSystem.playerESP[player] = bb
    end
    bb.Adornee = hrp
    local nameL = bb:FindFirstChild("NameLabel")
    local roleL = bb:FindFirstChild("RoleLabel")
    if nameL then
        nameL.Text       = player.Name
        nameL.TextColor3 = color
    end
    if roleL then
        local distStr = ""
        if Settings.esp.enabled.DisplayDistance then
            local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if myHRP then
                distStr = " [" .. math.floor((myHRP.Position - hrp.Position).Magnitude) .. "m]"
            end
        end
        roleL.Text       = role .. distStr
        roleL.TextColor3 = color
    end
end

function attachPlayerESP(player)
    if player == LocalPlayer then return end
    player.CharacterAdded:Connect(function()
        -- BUG FIX: 0.6s -> 0.1s. 600ms mostraba al jugador en la posicion de muerte.
        -- El character tarda ~0.08s en tener HRP valido, 0.1s es suficiente margen.
        task.wait(0.1)
        updatePlayerESP(player)
    end)
    player.AncestryChanged:Connect(function()
        if not player.Parent then removePlayerESP(player) end
    end)
    updatePlayerESP(player)
end

playerESPConn = nil
function startPlayerESPLoop()
    if playerESPConn then playerESPConn:Disconnect() end
    local _hbTplayerESP = 0
    playerESPConn = RunService.Heartbeat:Connect(function()
        -- BUG FIX: de cada 10 frames -> cada 3 frames (~20Hz).
        -- A 10 frames (~6Hz) el billboard quedaba 167ms en la posicion de muerte.
        _hbTplayerESP=_hbTplayerESP+1; if _hbTplayerESP<72 then return end; _hbTplayerESP=0  -- OPT: 60?72 frames player ESP
        local anyEnabled = Settings.esp.enabled.Everyone
            or Settings.esp.enabled.MurdererOnly
            or Settings.esp.enabled.SheriffOnly
        if not anyEnabled then
            for p, bb in pairs(ESPSystem.playerESP) do
                if bb and bb.Parent then bb:Destroy() end
                ESPSystem.playerESP[p] = nil
            end
            return
        end
        for _, player in ipairs(_cachedPlayers) do
            pcall(updatePlayerESP, player)
        end
    end)
end

Players.PlayerAdded:Connect(function(player)
    attachPlayerESP(player)
    task.wait(0.5)
    updatePlayerESP(player)
end)
for _, player in ipairs(_cachedPlayers) do
    attachPlayerESP(player)
end
startPlayerESPLoop()

-- ================================================================
-- == STUCKNIFE ESP AUTO-HIDE: hides all ESP boards while StucKnife
--    is present in workspace (anti-detection measure).
--    ESP is automatically restored once StucKnife is removed.
-- ================================================================
do
    local _stucKnifeCount = 0  -- track how many StucKnife instances are present
    local _espWasHidden   = false

    local function _hideAllESP(hide)
        if hide == _espWasHidden then return end
        _espWasHidden = hide
        pcall(function()
            local gui = getESPGui and getESPGui()
            if gui then gui.Enabled = not hide end
        end)
        -- Also hide individual billboards directly
        pcall(function()
            for _, bb in pairs(espBoards) do
                if bb and bb.Parent then
                    bb.Enabled = not hide
                end
            end
        end)
    end

    workspace.DescendantAdded:Connect(function(obj)
        if obj.Name == "StucKnife" and obj:IsA("BasePart") then
            _stucKnifeCount = _stucKnifeCount + 1
            _hideAllESP(true)
        end
    end)

    workspace.DescendantRemoving:Connect(function(obj)
        if obj.Name == "StucKnife" and obj:IsA("BasePart") then
            _stucKnifeCount = math.max(0, _stucKnifeCount - 1)
            if _stucKnifeCount == 0 then
                _hideAllESP(false)
            end
        end
    end)

    -- Check for any StucKnife already in workspace at load time
    task.spawn(function()
        local count = 0
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj.Name == "StucKnife" and obj:IsA("BasePart") then
                count = count + 1
            end
        end
        _stucKnifeCount = count
        if count > 0 then _hideAllESP(true) end
    end)
end
-- ================================================================

coinESPTask = nil
-- Coin ESP -- usa _farmCoinSet para reutilizar el cache del sistema de farm
-- Cham dorado en cada moneda visible, sin BillboardGui (sin lag)
_coinHL        = nil
_coinHLConn    = nil
_coinESPConns  = {}   -- tabla de conns event-driven

function startCoinESPLoop()
    if coinESPTask then task.cancel(coinESPTask); coinESPTask = nil end
    -- Cleanup anterior
    for part, bb in pairs(ESPSystem.coinESP) do
        if bb and bb.Parent then bb:Destroy() end
        ESPSystem.coinESP[part] = nil
    end
    if _coinHL then pcall(function() _coinHL:Destroy() end); _coinHL = nil end
    for _, conn in ipairs(_coinESPConns) do pcall(function() conn:Disconnect() end) end
    _coinESPConns = {}

    if not Settings.esp.enabled.Coins then return end

    -- Aplica Highlight cham dorado a una moneda si es visible
    local function _applyHL(coin)
        if not coin or not coin.Parent then return end
        if ESPSystem.coinESP[coin] then return end
        -- Ignorar monedas invisibles (ya recolectadas o ocultas)
        if coin:IsA("BasePart") and coin.LocalTransparencyModifier >= 0.9 then return end
        if coin:IsA("BasePart") and coin.Transparency >= 0.9 then return end
        local hl = Instance.new("Highlight")
        hl.Name              = "CoinChams"
        hl.FillColor         = Color3.fromRGB(255, 215, 0)    -- dorado
        hl.OutlineColor      = Color3.fromRGB(255, 255, 80)
        hl.FillTransparency  = 0.35
        hl.OutlineTransparency = 0
        hl.DepthMode         = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Adornee           = coin
        hl.Parent            = coin
        ESPSystem.coinESP[coin] = hl
    end

    local function _isCoin(obj)
        if not obj:IsA("BasePart") then return false end
        local n = obj.Name:lower()
        return n == "coin_server" or n == "coin" or n:find("coin")
    end

    -- Usar _farmCoinSet primero (ya tiene todas las monedas del mapa cacheadas)
    if _farmCoinSet and next(_farmCoinSet) then
        for coin in pairs(_farmCoinSet) do
            pcall(_applyHL, coin)
        end
    else
        -- Fallback: escanear CoinContainer o workspace
        local cc = workspace:FindFirstChild("CoinContainer", true)
        if cc then
            local function _applyCoinHL(parent)
                if _coinHL and _coinHL.Parent then pcall(function() _coinHL:Destroy() end) end
                local hl = Instance.new("Highlight")
                hl.Name              = "CoinChams"
                hl.FillColor         = Color3.fromRGB(255, 215, 0)
                hl.OutlineColor      = Color3.fromRGB(255, 255, 80)
                hl.FillTransparency  = 0.35
                hl.OutlineTransparency = 0
                hl.DepthMode         = Enum.HighlightDepthMode.AlwaysOnTop
                hl.Adornee           = parent
                hl.Parent            = parent
                _coinHL = hl
            end
            _applyCoinHL(cc)
        else
            for _, obj in ipairs(workspace:GetDescendants()) do
                if _isCoin(obj) then pcall(_applyHL, obj) end
            end
        end
    end

    -- Event-driven: nuevas monedas y monedas del farmCoinSet
    coinESPTask = task.spawn(function()
        local addConn = workspace.DescendantAdded:Connect(function(obj)
            if not Settings.esp.enabled.Coins then return end
            if _isCoin(obj) then pcall(_applyHL, obj) end
        end)
        local remConn = workspace.DescendantRemoving:Connect(function(obj)
            local hl = ESPSystem.coinESP[obj]
            if hl then pcall(function() hl:Destroy() end); ESPSystem.coinESP[obj] = nil end
        end)
        table.insert(_coinESPConns, addConn)
        table.insert(_coinESPConns, remConn)
        while Settings.esp.enabled.Coins do task.wait(3) end
        addConn:Disconnect(); remConn:Disconnect()
    end)
end


