        task.spawn(_trackDeathOf, p, c)
    end)
end
Players.PlayerAdded:Connect(function(p)
    p.CharacterAdded:Connect(function(c)
        task.wait(0.1)
        task.spawn(_trackDeathOf, p, c)
    end)
end)

-- ===================================================================
-- CHAM FREEZE DEAD -- detecta modelos Raggy/muertos en workspace
-- MM2 crea un modelo "Raggy" (u otro nombre) cuando el jugador muere
-- Completamente independiente del sistema Character de Roblox
-- ===================================================================
ChamRaggyState = {
    enabled     = false,
    highlights  = {},   -- { [Model] = Highlight }
    fillColor   = Color3.fromRGB(255, 0,  40),       -- rojo vivo
    outlineColor = Color3.fromRGB(255,   0,  40),
    fillTransp  = 0.4,
    outTransp   = 0.0,
    conn        = nil,  -- workspace.DescendantAdded connection
    scanConn    = nil,  -- periodic scan connection
}

-- Nombres de modelos de ragdoll conocidos en MM2 y otros juegos
-- FIX local limit: funciones RAGGY en do..end para liberar 7 registros top-level
do
    local _RAGGY_NAMES = {
        raggy=true, ragdoll=true, deadbody=true, dead_body=true,
        corpse=true, body=true, deadmodel=true, deathmodel=true,
        playerdead=true, deadplayer=true,
    }

    local function _isRaggyModel(obj)
        if not obj:IsA("Model") then return false end
        local n = obj.Name:lower()
        if _RAGGY_NAMES[n] then return true end
        if n:find("raggy") or n:find("ragdoll") or n:find("dead") then return true end
        local hrp = obj:FindFirstChild("HumanoidRootPart")
        local hum = obj:FindFirstChildOfClass("Humanoid")
        if hrp and not hum then
            for _, p in ipairs(_cachedPlayers) do
                if p.Character == obj then return false end
            end
            return true
        end
        return false
    end

    local function _getModelColor(model)
        local modelName = model.Name:lower()
        for _, p in ipairs(_cachedPlayers) do
            if p ~= LocalPlayer then
                if model.Name == p.Name or modelName:find(p.Name:lower()) then
                    local role = GetPlayerRole(p)
                    if role == "Murderer" then
                        return Color3.fromRGB(255, 60, 60), Color3.fromRGB(255, 180, 180)
                    elseif role == "Sheriff" or role == "Hero" then
                        return Color3.fromRGB(80, 80, 85), Color3.fromRGB(80, 80, 85)
                    end
                end
            end
        end
        return ChamRaggyState.fillColor, ChamRaggyState.outlineColor
    end

    local function _applyRaggyHighlight(model)
        if not ChamRaggyState.enabled then return end
        if ChamRaggyState.highlights[model] then return end
        local fc, oc = _getModelColor(model)
        local hl = Instance.new("Highlight")
        hl.Name              = "ChamRaggyHL"
        hl.FillColor         = fc
        hl.FillTransparency  = ChamRaggyState.fillTransp
        hl.OutlineColor      = oc
        hl.OutlineTransparency = ChamRaggyState.outTransp
        hl.DepthMode         = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Adornee           = model
        hl.Parent            = model
        ChamRaggyState.highlights[model] = hl
        model.AncestryChanged:Connect(function()
            if not model.Parent then
                pcall(function() hl:Destroy() end)
                ChamRaggyState.highlights[model] = nil
            end
        end)
    end

    local function _removeAllRaggyHighlights()
        for model, hl in pairs(ChamRaggyState.highlights) do
            pcall(function() hl:Destroy() end)
        end
        ChamRaggyState.highlights = {}
    end

    local function _scanWorkspaceForRaggy()
        if not ChamRaggyState.enabled then return end
        for _, obj in ipairs(workspace:GetDescendants()) do
            if _isRaggyModel(obj) and not ChamRaggyState.highlights[obj] then
                _applyRaggyHighlight(obj)
            end
        end
    end

    -- ToggleChamRaggy es global para que la UI pueda llamarla
    function ToggleChamRaggy(enabled)
        ChamRaggyState.enabled = enabled
        if ChamRaggyState.conn then ChamRaggyState.conn:Disconnect(); ChamRaggyState.conn = nil end
        if ChamRaggyState.scanConn then ChamRaggyState.scanConn:Disconnect(); ChamRaggyState.scanConn = nil end
        if not enabled then _removeAllRaggyHighlights(); return end
        _scanWorkspaceForRaggy()
        ChamRaggyState.conn = workspace.DescendantAdded:Connect(function(obj)
            if not ChamRaggyState.enabled then return end
            task.defer(function()
                if _isRaggyModel(obj) then _applyRaggyHighlight(obj) end
                if obj:IsA("Model") and _isRaggyModel(obj) then _applyRaggyHighlight(obj) end
            end)
        end)
        _scanTick = 0
        -- OPT: un solo acumulador de dt en vez de doble throttle (_crTick + _scanTick)
        -- El scan de workspace cada 2s es suficiente; DescendantAdded cubre detecci?n inmediata
        ChamRaggyState.scanConn = RunService.Heartbeat:Connect(function(dt)
            if not ChamRaggyState.enabled then return end
            _scanTick = _scanTick + dt
            if _scanTick < 2 then return end
            _scanTick = 0
            _scanWorkspaceForRaggy()
        end)
    end

    -- _refreshRaggyColors tambien se expone global para uso en UI
    function _refreshRaggyColors()
        for model, hl in pairs(ChamRaggyState.highlights) do
            if hl and hl.Parent then
                local fc, oc = _getModelColor(model)
                hl.FillColor         = fc
                hl.FillTransparency  = ChamRaggyState.fillTransp
                hl.OutlineColor      = oc
                hl.OutlineTransparency = ChamRaggyState.outTransp
            end
        end
    end
end

-- roleOf: detecta el rol de un jugador usando SOLO el cache del RoundStart
-- FIX: NO llamar GetPlayerRole -- detecta knife/gun en Character y escribe en _roleCache,
-- contaminando el cache y aplicando chams de rol sin que el toggle lo pida.
function roleOf(player)
    if not player or not player.Character then return "Innocent" end
    if _G._visualRoundOver then return "Innocent" end
    -- FIX: revisar cache ANTES de Health -- si es murder/sheriff/hero nunca mostrar Dead
    -- aunque haya un frame de lag donde Health baje temporalmente.
    if _roleCache.murderer == player then return "Murderer" end
    if _roleCache.sheriff  == player then return "Sheriff"  end
    if _roleCache.hero     == player then return "Hero"     end
    -- Solo Dead si no tiene rol conocido Y realmente murio
    local hum = player.Character:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health <= 0 then return "Dead" end
    if _G._murdererDied then return "Grey" end
    return "Innocent"
end

-- knifeInHand: detecta si el jugador tiene el knife EQUIPADO (en mano, en Character)
-- NO detecta knife en Backpack -- en MM2 todos tienen knife en backpack
-- Solo util para ESP visual "knife in hand" flag, nunca para determinar rol
function knifeInHand(player)
    if not player or not player.Character then return false end
    local char = player.Character
    -- Buscar knife equipado (Tool directo en Character, NO en Backpack)
    -- FIX: solo Tool -- Model puede ser decorativo y da falso positivo
    for _, obj in ipairs(char:GetChildren()) do
        if obj:IsA("Tool") then
            local n = obj.Name:lower()
            if n:find("knife") or n:find("blade") or n == "knife" then
                return true
            end
        end
    end
    return false
end

function colorOf(role)
    -- FIX REPAINT: "Dead" siempre debe ser gris, sin importar si los roles son conocidos o no.
    -- Antes devolvia verde para Dead cuando rolesKnown=false, causando que jugadores
    -- muertos al inicio de ronda aparecieran con color de Inocente vivo.
    if role == "Dead" then return Color3.fromRGB(190, 190, 210) end
    -- FIX: verde hasta que murderer o sheriff sean detectados
    local rolesKnown = (_roleCache.murderer ~= nil) or (_roleCache.sheriff ~= nil)
    if not rolesKnown then
        return Color3.fromRGB(  0, 255, 160)  -- VERDE Innocent (todos innocents hasta detectar)
    end
    if role == "Murderer"  then return Color3.fromRGB(255,   0,  40)  end  -- rojo
    if role == "Sheriff"   then return Color3.fromRGB(  0, 140, 255)  end  -- Azul Sheriff
    if role == "Hero"      then return Color3.fromRGB(255, 230, 0)    end
    return Color3.fromRGB(  0, 255, 160)  -- Innocent / resto (verde)
end

-- vsShow: determina si el ESP/Cham debe mostrarse para este jugador
-- El rol viene de roleOf() -> GetPlayerRole() -> _roleCache (RoundStart)
-- flags.knife usa knifeInHand() que solo detecta knife equipado en Character
function vsShow(flags, role, player)
    if flags.everyone  then return true end
    if flags.murderer  and role == "Murderer" then return true end
    if flags.sheriff   and role == "Sheriff"  then return true end
    if flags.hero      and role == "Hero"     then return true end
    if flags.assassin  and role == "Assassin" then return true end
    if flags.dead      and role == "Dead"     then return true end
    -- FIX SURVIVOR: antes mapeaba a role=="Innocent", haciendo que TODOS los inocentes
    -- recibieran cham en plena partida cuando survivor estaba activo.
    -- Survivor es un rol especifico de fin de ronda, no equivale a Innocent durante la partida.
    if flags.survivor  and role == "Survivor"   then return true end
    if flags.zombie    and role == "Zombie"      then return true end
    -- GunHolder: solo si everyone esta activo (tiene arma pero no es Sheriff)
    if flags.everyone  and role == "GunHolder"   then return true end
    -- Grey: murder muerto mid-ronda -- visible solo si everyone activo
    if role == "Grey"  and flags.everyone        then return true end
    -- knife removido de vsShow: no determinar murder/visuals por knife en mano
    return false
end

function getESPGui()
    local pg = LocalPlayer:FindFirstChild("PlayerGui")
    if not pg then return nil end
    if ESPGui and ESPGui.Parent then return ESPGui end
    ESPGui = Instance.new("ScreenGui")
    ESPGui.Name           = "VisualsESP_Hub"
    ESPGui.ResetOnSpawn   = false
    ESPGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    ESPGui.DisplayOrder   = 8500
    ESPGui.IgnoreGuiInset = true
    ESPGui.Parent         = pg
    return ESPGui
end

function removeBoard(player)
    if espBoards[player] then
        pcall(function() espBoards[player]:Destroy() end)
        espBoards[player] = nil
    end
end

function updateBoard(player)
    if not player or not player.Parent then removeBoard(player); return end
    if _G._rolesCacheReady == false then return end
    local char = player.Character
    if not char or not char.Parent then return end
    local hrp  = char:FindFirstChild("HumanoidRootPart")
    local hum  = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then removeBoard(player); return end

    -- Murder muerto o ronda terminada -> respetar rol real de cada jugador
    local role
    if _G._murdererDied or _G._visualRoundOver then
        -- FIX REPAINT COLOR: respetar todos los roles reales, no colapsar a "Innocent".
        -- Antes el Murderer quedaba pintado como Innocent (verde) al morir porque
        -- no habia rama para el -- ahora se mantiene como "Murderer" (rojo) correctamente.
        if     _roleCache.murderer == player                                       then role = "Murderer"
        elseif _roleCache.sheriff  == player                                       then role = "Sheriff"
        elseif _roleCache.hero     == player                                       then role = "Hero"
        elseif player == LocalPlayer and (_roleCache.localRole == "Murderer")      then role = "Murderer"
        elseif player == LocalPlayer and (_roleCache.localRole == "Sheriff")       then role = "Sheriff"
        elseif player == LocalPlayer and (_roleCache.localRole == "Hero")          then role = "Hero"
        else role = "Innocent"
        end
    else
        -- Sin ronda activa -> sin board (con grace period para evitar flicker)
        local roundActive = (_roleCache.murderer ~= nil)
                         or (_roleCache.sheriff  ~= nil)
                         or (_roleCache.hero     ~= nil)
        if roundActive then
            _lastRoundActiveTs = tick()
        else
            -- Solo apagar si llevamos >2s sin roles (evita flicker al inicio de ronda)
            if (tick() - _lastRoundActiveTs) < _ROUND_ACTIVE_GRACE then
                roundActive = true  -- grace: mantener visible
            else
                removeBoard(player); return
            end
        end

        if _roleCache.murderer == player then role = "Murderer"
        elseif _roleCache.sheriff == player then role = "Sheriff"
        elseif _roleCache.hero    == player then role = "Hero"
        else
            -- OPT: roleOf() faz GetChildren() para detectar GunHolder, caro por jugador/tick.
            -- Usar GetPlayerRole() O(1) aqui; GunHolder se detecta solo si hay toggle activo.
            local _r = GetPlayerRole(player)
            if _r == "Dead" or _r == "Grey" then role = "Innocent"
            else role = (_r ~= "" and _r) or "Innocent" end
        end
    end

    local show = vsShow(VisualState.esp, role, player)
    -- En estado de fin de ronda, mostrar si hay algun toggle de equipo activo
    if not show and (_G._murdererDied or _G._visualRoundOver) then
        show = VisualState.esp.everyone or VisualState.esp.survivor
            or VisualState.esp.murderer or VisualState.esp.sheriff
    end

    if not show or not hrp then removeBoard(player); return end

    local gui = getESPGui()
    if not gui then return end

    -- OPT: crear board solo si no existe (evita garbage cada frame)
    local bb = espBoards[player]
    if not bb or not bb.Parent then
        bb = Instance.new("BillboardGui")
        bb.Name           = "ESP_" .. player.Name
        bb.Size           = UDim2.new(0, 140, 0, 68)
        bb.StudsOffset    = Vector3.new(0, 3.5, 0)
        bb.AlwaysOnTop    = true
        bb.ResetOnSpawn   = false
        bb.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        bb.Parent         = gui

        local n = Instance.new("TextLabel", bb)
        n.Name                   = "N"
        n.Size                   = UDim2.new(1, 0, 0.42, 0)
        n.BackgroundTransparency = 1
        n.FontFace = Font.fromEnum(Enum.Font.Arimo)
        n.TextSize               = 14
        n.TextStrokeTransparency = 0.2
        n.TextXAlignment         = Enum.TextXAlignment.Center

        local r = Instance.new("TextLabel", bb)
        r.Name                   = "R"
        r.Size                   = UDim2.new(1, 0, 0.35, 0)
        r.Position               = UDim2.new(0, 0, 0.42, 0)
        r.BackgroundTransparency = 1
        r.FontFace = Font.fromEnum(Enum.Font.Arimo)
        r.TextSize               = 11
        r.TextStrokeTransparency = 0.2
        r.TextXAlignment         = Enum.TextXAlignment.Center

        -- Health bar frame
        local hbBg = Instance.new("Frame", bb)
        hbBg.Name               = "HBBg"
        hbBg.Size               = UDim2.new(0.85, 0, 0.18, 0)
        hbBg.Position           = UDim2.new(0.075, 0, 0.80, 0)
        hbBg.BackgroundColor3   = Color3.fromRGB(  3,   8,  18)
        hbBg.BackgroundTransparency = 0.3
        hbBg.BorderSizePixel    = 0
        Instance.new("UICorner", hbBg).CornerRadius = UDim.new(1, 0)

        local hbFill = Instance.new("Frame", hbBg)
        hbFill.Name               = "HBFill"
        hbFill.Size               = UDim2.new(1, 0, 1, 0)
        hbFill.BackgroundColor3   = Color3.fromRGB(90, 90, 95)
        hbFill.BorderSizePixel    = 0
        Instance.new("UICorner", hbFill).CornerRadius = UDim.new(1, 0)

        espBoards[player] = bb
    end

    -- OPT: solo actualizar Adornee si cambio
    if bb.Adornee ~= hrp then bb.Adornee = hrp end

    local color = colorOf(role)
    local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    local distStr = ""
    if VisualState.esp.distance and myHRP then
        distStr = " [" .. math.floor((myHRP.Position - hrp.Position).Magnitude) .. "m]"
    end

    local nL = bb:FindFirstChild("N")
    local rL = bb:FindFirstChild("R")
    -- OPT: evitar asignar si el valor no cambio
    if nL then
        if nL.TextColor3 ~= color then nL.TextColor3 = color end
 if nL.Text ~= player.Name then nL.Text = player.Name end
    end
    if rL then
        local newText = role .. distStr
        if rL.TextColor3 ~= color then rL.TextColor3 = color end
 if rL.Text ~= newText then rL.Text = newText end
    end

    -- Health bar update
    local hbBg = bb:FindFirstChild("HBBg")
    if hbBg then
        local hum2 = char:FindFirstChildOfClass("Humanoid")
        local showHB = VisualState.esp.healthBar
        hbBg.Visible = showHB and hum2 ~= nil
        if showHB and hum2 then
            local pct = math.clamp(hum2.Health / math.max(hum2.MaxHealth, 1), 0, 1)
            local hbFill = hbBg:FindFirstChild("HBFill")
            if hbFill then
                -- OPT: solo actualizar si la salud cambio mas de 1%
                local prevPct = hbFill:GetAttribute("_pct") or -1
                if math.abs(pct - prevPct) > 0.01 then
                    hbFill:SetAttribute("_pct", pct)
                    hbFill.Size = UDim2.new(pct, 0, 1, 0)
                    local r2 = math.min(1, 2 * (1 - pct))
                    local g2 = math.min(1, 2 * pct)
                    hbFill.BackgroundColor3 = Color3.new(r2, g2, 0.1)
                end
            end
        end
    end
end

-- ==================================================================
-- OUTLINE -- BoxHandleAdornment (PieceOutline) por cada parte del cuerpo
-- Funciona igual que PieceCham pero con Transparency alta para efecto de borde
function _aplicarPieceOutline(char, color)
    local _now = tick()
    if not _outCacheTs[char] or (_now - _outCacheTs[char]) > 3 then
        _outPartList[char] = nil
        _outCacheTs[char]  = _now
    end
    if not _outPartList[char] then
        local parts = {}
        for _, part in ipairs(char:GetDescendants()) do
            -- FIX DISAPPEAR: mismo fix que _chamPartList, no filtrar por Transparency
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                parts[#parts+1] = part
            end
        end
        _outPartList[char] = parts
    end
    for _, part in ipairs(_outPartList[char]) do
        if not part.Parent then _outPartList[char] = nil; break end
        local prev = part:FindFirstChild("PieceOutline")
        if prev and prev:IsA("BoxHandleAdornment") then
            if _color3Equals(prev.Color3, color) then
                continue
            else
                pcall(function() prev:Destroy() end)
            end
        elseif prev then
            pcall(function() prev:Destroy() end)
        end
        pcall(function()
            local b = Instance.new("BoxHandleAdornment")
            b.Name         = "PieceOutline"
            b.Size         = part.Size + Vector3.new(0.02, 0.02, 0.02)
            b.AlwaysOnTop  = true
            b.ZIndex       = 4
            b.Adornee      = part
            b.Color3       = color
            b.Transparency = 0.35  -- cuerpo completo relleno semi-transparente
            b.CFrame       = CFrame.new(0, 0, 0)
            b.Parent       = part
        end)
    end
end

function _limpiarPieceOutline(char)
    if not char then return end
    _outPartList[char] = nil
    _outCacheTs[char]  = nil
    local toDestroy = {}
    for _, desc in ipairs(char:GetDescendants()) do
        if desc:IsA("BoxHandleAdornment") and desc.Name == "PieceOutline" then
            toDestroy[#toDestroy+1] = desc
        end
    end
    for _, desc in ipairs(toDestroy) do
        pcall(function() desc:Destroy() end)
    end
end

-- CHAM -- BoxHandleAdornment (PieceCham) con role cache
-- LOGICA:
--   Al activar / sin rol detectado -> GRIS (todos)
--   Murderer vivo  -> ROJO
--   Sheriff vivo   -> AZUL
--   Hero vivo      -> DORADO
--   Inocentes vivos (cuando hay rol detectado) -> VERDE
--   Muerto (Health<=0) -> GRIS siempre
-- ==================================================================
_CHAM_TRANSP = 0.5

-- FIX: comparar Color3 por componentes, no por referencia (== siempre false en Color3)
function _color3Equals(a, b)
    return math.abs(a.R - b.R) < 0.002
       and math.abs(a.G - b.G) < 0.002
       and math.abs(a.B - b.B) < 0.002
end

-- FIX REPINTADO: tabla de timestamps para invalidar el cache periodicamente.
-- Los accesorios de Roblox cargan 5-15s despues del spawn, asi que el cache
-- inicial no los incluye y esas partes nunca reciben PieceChams.
-- Invalidar cada 8s fuerza un rebuild que las incluye.
if not _chamCacheTs then _chamCacheTs = {} end

function _aplicarPieceChams(char, color)
    -- OPT: cachear lista de parts por char -- GetDescendants() es caro, solo reconstruir si char cambio
    -- FIX REPINTADO: invalidar el cache cada 8s para incluir accesorios que cargaron tarde
    local _now = tick()
    -- OPT: TTL 1.5s->3s -- instanceLoop invalida el cache al cambiar de rol v?a removeCham,
    -- por lo que 1.5s era demasiado agresivo. 3s cubre accesorios tard?os sin reconstruir cada tick.
    if not _chamCacheTs[char] or (_now - _chamCacheTs[char]) > 3 then
        _chamPartList[char] = nil
        _chamCacheTs[char]  = _now
    end
    if not _chamPartList[char] then
        local parts = {}
        for _, part in ipairs(char:GetDescendants()) do  -- OPT: pairs->ipairs (array ordenado, m?s r?pido)
            -- FIX DISAPPEAR: NO filtrar por Transparency -- una parte temp. en T=1
            -- (xray, bodyparts, spawn) quedaria fuera del cache y causaria desaparicion
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                parts[#parts+1] = part
            end
        end
        _chamPartList[char] = parts
    end
    for _, part in ipairs(_chamPartList[char]) do
        if not part.Parent then _chamPartList[char] = nil; break end  -- char cambio, invalidar
        local prev = part:FindFirstChild("PieceCham")
        -- FIX: solo recrear si no existe o el color cambio (evita flickering)
        if prev and prev:IsA("BoxHandleAdornment") then
            if _color3Equals(prev.Color3, color) then
                continue  -- color ya correcto, no tocar
            else
                pcall(function() prev:Destroy() end)
            end
        elseif prev then
            pcall(function() prev:Destroy() end)
        end
        local ok, _ = pcall(function()
            local b = Instance.new("BoxHandleAdornment")
            b.Name         = "PieceCham"
            b.Size         = part.Size + Vector3.new(0.18, 0.04, 0.18)  -- FIX: expand sides (X/Z) more than top/bottom (Y) for side glow effect
            b.AlwaysOnTop  = true
            b.ZIndex       = 5
            b.Adornee      = part
            b.Color3       = color
            b.Transparency = _CHAM_TRANSP
            b.CFrame       = CFrame.new(0, 0, 0)
            b.Parent       = part
        end)
        _ = ok
    end
end

function _limpiarPieceChams(char)
    if not char then return end
    -- Invalidar caches al limpiar
    _chamSamplePart[char] = nil
    _chamPartList[char]   = nil
    -- FIX REPINTADO: limpiar tambien el timestamp de cache periodico
    if _chamCacheTs then _chamCacheTs[char] = nil end
    local toDestroy = {}
    for _, desc in ipairs(char:GetDescendants()) do  -- OPT: pairs->ipairs (array, m?s r?pido)
        if desc:IsA("BoxHandleAdornment") and desc.Name == "PieceCham" then
            toDestroy[#toDestroy+1] = desc
        end
    end
    for _, desc in ipairs(toDestroy) do
        pcall(function() desc:Destroy() end)
    end
end

-- Devuelve true si _roleCache ya conoce al menos un Murderer o Sheriff
function _chamRolKnown()
    -- FIX: leer _roleCache directo en vez de GetPlayerRole() en loop
    -- GetPlayerRole llama _refreshRoleCache -> innecesario cada frame
    return (_roleCache.murderer ~= nil)
        or (_roleCache.sheriff  ~= nil)
        or (_roleCache.hero     ~= nil)
end

function removeCham(player)
    if player and player.Character then
        _limpiarPieceChams(player.Character)
    end
    -- FIX: limpiar tambien el char cacheado en chamHighlight si es distinto al actual
    -- (el jugador respawneo y chamHighlight apunta al char viejo)
    local ref = chamHighlight[player]
    if ref then
        if typeof(ref) == "Instance" then
            if ref:IsA("Highlight") then
                pcall(function() ref:Destroy() end)
            elseif ref:IsA("Model") and ref ~= (player and player.Character) then
                -- char viejo -- limpiar sus PieceChams tambien
                pcall(function() _limpiarPieceChams(ref) end)
            end
        end
        chamHighlight[player] = nil
    end
    -- FIX DISAPPEAR: restaurar LocalTransparencyModifier en caso de corrupcion
    if player and player.Character then
        local char = player.Character
        for _, part in ipairs(char:GetDescendants()) do
            if (part:IsA("BasePart") or part:IsA("MeshPart"))
            and part.LocalTransparencyModifier ~= 0 then
                pcall(function() part.LocalTransparencyModifier = 0 end)
            end
        end
    end
end

function updateCham(player)
    if not player or not player.Parent then removeCham(player); return end
    -- FIX RACE CONDITION: si el cache se esta repoblando, no tocar nada.
    -- Antes llamaba removeCham() aqui -> destruia chams validos del tick anterior.
    -- Mejor dejar los chams existentes hasta que el cache este listo.
    if _G._rolesCacheReady == false then return end
    if player == LocalPlayer then return end  -- nunca aplicar cham al propio jugador
    local char = player.Character
    if not char or not char.Parent then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local isDead = not hum or hum.Health <= 0
    -- FIX Dead Cham: si DeadOnly esta activo, NO remover -- aplicar color gris
    if isDead then
        local _vcd = VisualState and VisualState.cham
        local deadEnabled = _vcd and (_vcd.dead or (_vcd.enabled and _vcd.enabled.DeadOnly))
        if deadEnabled then
            -- Aplicar cham gris para muertos
            local DEAD_COL = Color3.fromRGB(155, 155, 155)
            pcall(function() _aplicarPieceChams(char, DEAD_COL) end)
            chamHighlight[player] = char
        else
            removeCham(player)
        end
        return
    end
    if not char:FindFirstChild("HumanoidRootPart") then return end

    -- FIX REPINTADO: si el jugador respawneo, limpiar chams del char viejo
    local cachedChar = chamHighlight[player]
    if cachedChar and typeof(cachedChar) == "Instance" and cachedChar ~= char then
        pcall(function() _limpiarPieceChams(cachedChar) end)
        chamHighlight[player] = nil
    end

    local GREEN = Color3.fromRGB(  0, 255, 160)  -- VERDE Innocent para Innocents

    -- FIX TRANSICION: si estamos entre rondas (mapa viejo destruido, RoundStart no llego),
    -- bloquear chams completamente para evitar que roles viejos del cache pinten a todos.
    if _G._betweenRounds then removeCham(player); return end

    -- FIX REPINTADO: la guardia rolesKnown causaba que si el instanceLoop corria
    -- en el intervalo entre "limpiar roleCache" y "repoblar roleCache" en RoundStart,
    -- todos los jugadores perdian el cham aunque el cache estaba a punto de estar listo.
    -- _rolesCacheReady=false ya bloquea el loop durante ese intervalo (ver arriba),
    -- asi que esta guardia adicional es redundante y solo causa delays.
    -- Solo bloquear en betweenRounds (ya manejado arriba) o sin everyone activo.
    if not (VisualState.cham and VisualState.cham.everyone) then
        local rolesKnown = (_roleCache.murderer ~= nil) or (_roleCache.sheriff ~= nil) or (_roleCache.hero ~= nil)
        if not rolesKnown and not _G._murdererDied and not _G._visualRoundOver then
            -- Aun no llegaron roles del servidor -- solo quitar si no hay everyone
            removeCham(player); return
        end
    end

    -- Helper: chequea si el cham actual esta vivo con el color correcto
    -- OPT: cachear la parte muestra por char -- evita GetChildren() cada tick por jugador
    if not _chamSamplePart[char] or not _chamSamplePart[char].Parent then
        _chamSamplePart[char] = nil
        for _, c in ipairs(char:GetChildren()) do
            if c:IsA("BasePart") and c.Name ~= "HumanoidRootPart" then
                _chamSamplePart[char] = c; break
            end
        end
    end
    local function _chamOk(col)
        if chamHighlight[player] ~= char then return false end
        local sp = _chamSamplePart[char]
        if not sp or not sp.Parent then return false end
        local ex = sp:FindFirstChild("PieceCham")
        return ex and ex:IsA("BoxHandleAdornment") and ex.Parent ~= nil and _color3Equals(ex.Color3, col)
    end

    -- Murder muerto o ronda terminada -> todos sin rol activo se pintan VERDE (inocente)
    if _G._murdererDied or _G._visualRoundOver then
        local endRole
        if     _roleCache.murderer == player                                  then endRole = "Murderer"
        elseif _roleCache.sheriff  == player                                  then endRole = "Sheriff"
        elseif _roleCache.hero     == player                                  then endRole = "Hero"
        elseif player == LocalPlayer and (_roleCache.localRole == "Murderer") then endRole = "Murderer"
        elseif player == LocalPlayer and (_roleCache.localRole == "Sheriff")  then endRole = "Sheriff"
        elseif player == LocalPlayer and (_roleCache.localRole == "Hero")     then endRole = "Hero"
        else                                                                       endRole = "Innocent"
        end

        local showEndCham = vsShow(VisualState.cham, endRole, player)
                         or VisualState.cham.everyone
                         or (VisualState.cham.survivor and endRole == "Innocent")
        if not showEndCham then removeCham(player); return end

        -- Muertos (rol limpiado) -> VERDE. Roles activos -> su color
        local endCol
        if     endRole == "Murderer" then endCol = Color3.fromRGB(255,   0,  40)
        elseif endRole == "Sheriff"  then endCol = Color3.fromRGB(  0, 140, 255)
        elseif endRole == "Hero"     then endCol = Color3.fromRGB(255, 230,   0)
        else                              endCol = GREEN  -- inocente o muerto = verde
        end

        _aplicarPieceChams(char, endCol)
        chamHighlight[player] = char
        return
    end

    -- Sin ronda activa y sin estado de fin -> solo quitar si no es Everyone
    local roundActive = (_roleCache.murderer ~= nil)
                     or (_roleCache.sheriff  ~= nil)
                     or (_roleCache.hero     ~= nil)
    -- FIX: si Everyone esta activo, mostrar cham independientemente del roundActive
    if not roundActive and not VisualState.cham.everyone then
        removeCham(player); return
    end

    -- Los jugadores muertos ya tienen su rol limpiado del roleCache -> caen en "Innocent" -> VERDE
    local role
    if     _roleCache.murderer == player then role = "Murderer"
    elseif _roleCache.sheriff  == player then role = "Sheriff"
    elseif _roleCache.hero     == player then role = "Hero"
    else role = "Innocent" end

    local show = vsShow(VisualState.cham, role, player)
    if not show then removeCham(player); return end

    local col
    if     role == "Murderer"  then col = Color3.fromRGB(255,   0,  40)
    elseif role == "Sheriff"   then col = Color3.fromRGB(  0, 140, 255)
    elseif role == "Hero"      then col = Color3.fromRGB(255, 230,   0)
    elseif role == "GunHolder" then col = Color3.fromRGB(255, 230,   0)
    else                            col = GREEN
    end

    local samplePart
    local ch = char:GetChildren()
    for i = 1, #ch do
        if ch[i]:IsA("BasePart") and ch[i].Name ~= "HumanoidRootPart" then
            samplePart = ch[i]; break
        end
    end

    -- Aplicar color. _aplicarPieceChams tiene check per-parte interno:
    -- si el color ya es correcto en esa parte -> continue (no recrear).
    -- Llamarla cada tick es seguro y no causa flickering.
    _aplicarPieceChams(char, col)
    chamHighlight[player] = char
end

function removeOutline(player)
    if outHighlight[player] then
        local char = outHighlight[player]
        if typeof(char) == "Instance" then
            pcall(function() _limpiarPieceOutline(char) end)
        end
        outHighlight[player] = nil
    end
    -- Tambien limpiar por char actual por si cambio
    if player and player.Character then
        pcall(function() _limpiarPieceOutline(player.Character) end)
    end
    -- FIX DISAPPEAR: restaurar LocalTransparencyModifier en caso de corrupcion
    if player and player.Character then
        local char = player.Character
        for _, part in ipairs(char:GetDescendants()) do
            if (part:IsA("BasePart") or part:IsA("MeshPart"))
            and part.LocalTransparencyModifier ~= 0 then
                pcall(function() part.LocalTransparencyModifier = 0 end)
            end
        end
    end
end

function updateOutline(player)
    if not player or not player.Parent then removeOutline(player); return end
    if player == LocalPlayer then return end
    if _G._betweenRounds then removeOutline(player); return end
    if _G._rolesCacheReady == false then removeOutline(player); return end
    local char = player.Character
    if not char or not char.Parent then removeOutline(player); return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then removeOutline(player); return end

    local GREEN = Color3.fromRGB(  0, 255, 160)

    -- Si el char cambio (respawn) -> limpiar outline del char viejo
    if outHighlight[player] and outHighlight[player] ~= char then
        pcall(function() _limpiarPieceOutline(outHighlight[player]) end)
        outHighlight[player] = nil
    end

    -- Murder muerto o ronda terminada
    if _G._murdererDied or _G._visualRoundOver then
        local endRole
        if     _roleCache.sheriff == player then endRole = "Sheriff"
        elseif _roleCache.hero    == player then endRole = "Hero"
        elseif player == LocalPlayer and (_roleCache.localRole == "Sheriff") then endRole = "Sheriff"
        elseif player == LocalPlayer and (_roleCache.localRole == "Hero")    then endRole = "Hero"
        else endRole = "Innocent"
        end
        local showEndOut = vsShow(VisualState.outline, endRole, player)
                        or VisualState.outline.everyone
                        or (VisualState.outline.survivor and endRole == "Innocent")
        if not showEndOut then removeOutline(player); return end
        local colEnd
        if     endRole == "Sheriff" then colEnd = Color3.fromRGB(  0, 140, 255)
        elseif endRole == "Hero"    then colEnd = Color3.fromRGB(255, 230,   0)
        else                             colEnd = GREEN
        end
        pcall(function() _aplicarPieceOutline(char, colEnd) end)
        outHighlight[player] = char
        return
    end

    -- Roles no conocidos aun
    local rolesKnown = (_roleCache.murderer ~= nil) or (_roleCache.sheriff ~= nil) or (_roleCache.hero ~= nil)
    if not rolesKnown then removeOutline(player); return end

    -- Sin ronda activa
    local roundActive = (_roleCache.murderer ~= nil) or (_roleCache.sheriff ~= nil) or (_roleCache.hero ~= nil)
    if not roundActive then
        if (tick() - _lastRoundActiveTs) >= _ROUND_ACTIVE_GRACE then
            removeOutline(player); return
        end
    end

    local role
    if     _roleCache.murderer == player then role = "Murderer"
    elseif _roleCache.sheriff  == player then role = "Sheriff"
    elseif _roleCache.hero     == player then role = "Hero"
    else role = "Innocent" end

    local show = vsShow(VisualState.outline, role, player)
    if not show then removeOutline(player); return end

    local col = colorOf(role)
    pcall(function() _aplicarPieceOutline(char, col) end)
    outHighlight[player] = char
end

-- =============================================================
-- HIGHLIGHT ESP -- Highlight de Roblox: solo BORDES del cuerpo
-- FillColor = color del rol, FillTransparency por rol, OutlineTransparency=0 (bordes visibles)
-- =============================================================
hlObjects = {}  -- [player] = Highlight instance

function removeHighlight(player)
    local hl = hlObjects[player]
    if hl then
        pcall(function() hl:Destroy() end)
        hlObjects[player] = nil
    end
    -- FIX DISAPPEAR: destruir un Highlight con AlwaysOnTop puede corromper
    -- LocalTransparencyModifier de las partes, dejando al jugador invisible.
    -- Restaurar a 0 en todas las partes del char al quitar el Highlight.
    if player and player.Character then
        local char = player.Character
        for _, part in ipairs(char:GetDescendants()) do
            if (part:IsA("BasePart") or part:IsA("MeshPart"))
            and part.LocalTransparencyModifier ~= 0 then
                pcall(function() part.LocalTransparencyModifier = 0 end)
            end
        end
    end
end

function updateHighlight(player)
    if not player or not player.Parent then removeHighlight(player); return end
    if player == LocalPlayer then return end
    if _G._betweenRounds then removeHighlight(player); return end
    local char = player.Character
    if not char or not char.Parent then removeHighlight(player); return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then removeHighlight(player); return end

    local vh = VisualState and VisualState.highlight
    if not vh then removeHighlight(player); return end

    -- Determinar rol
    local role
    if     _roleCache.murderer == player then role = "Murderer"
    elseif _roleCache.sheriff  == player then role = "Sheriff"
    elseif _roleCache.hero     == player then role = "Hero"
    else                                      role = "Innocent"
    end

    -- Ver si debe mostrarse
    local show = vh.everyone
              or (vh.murderer  and role == "Murderer")
              or (vh.sheriff   and (role == "Sheriff" or role == "Hero"))
              or (vh.hero      and role == "Hero")
              or (vh.assassin  and role == "Murderer")
              or (vh.innocent  and role == "Innocent")
              or (vh.survivor  and role == "Innocent")
    if not show then removeHighlight(player); return end

    -- Color por rol
    local col
    if     role == "Murderer" then col = Color3.fromRGB(255,   0,  40)
    elseif role == "Sheriff"  then col = Color3.fromRGB(  0, 140, 255)
    elseif role == "Hero"     then col = Color3.fromRGB(255, 200,   0)
    else                           col = Color3.fromRGB(  0, 255, 160)  -- verde Innocent
    end

    local hl = hlObjects[player]
    -- Si el char cambio, destruir el viejo
    if hl and hl.Parent and hl.Adornee ~= char then
        pcall(function() hl:Destroy() end)
        hl = nil; hlObjects[player] = nil
    elseif hl and not hl.Parent then
        hl = nil; hlObjects[player] = nil
    end

    -- Fill transparency por rol: Murder/Sheriff/Hero mas solido, Innocent sutil
    local fillTransp
    if     role == "Murderer" then fillTransp = 0.30
    elseif role == "Sheriff"  then fillTransp = 0.35
    elseif role == "Hero"     then fillTransp = 0.35
    else                           fillTransp = 0.55   -- Innocent: muy sutil
    end

    if not hl then
        hl = Instance.new("Highlight")
        hl.Name                = "PlayerHL"
        hl.FillColor           = col
        hl.FillTransparency    = fillTransp        -- relleno con color de rol
        hl.OutlineColor        = col
        hl.OutlineTransparency = 0                 -- bordes bien visibles
        hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Adornee             = char
        hl.Parent              = char
        hlObjects[player]      = hl
    else
        if not _color3Equals(hl.OutlineColor, col) then
            pcall(function() hl.OutlineColor = col; hl.FillColor = col end)
        end
        if hl.FillTransparency ~= fillTransp then
            pcall(function() hl.FillTransparency = fillTransp end)
        end
    end
end

function removeBox(player)
    if boxSelect[player] then
        pcall(function() boxSelect[player]:Destroy() end)
        boxSelect[player] = nil
    end
end

function updateBox(player)
    -- SelectionBox deshabilitado: el Box ESP usa BoxHandleAdornment (EspBox) gestionado por _startEspBoxLoop
    removeBox(player)
end

SKELETON_PAIRS = {
    {"Head","UpperTorso"},{"UpperTorso","LowerTorso"},
    {"UpperTorso","LeftUpperArm"},{"UpperTorso","RightUpperArm"},
    {"LeftUpperArm","LeftLowerArm"},{"RightUpperArm","RightLowerArm"},
    {"LeftLowerArm","LeftHand"},{"RightLowerArm","RightHand"},
    {"LowerTorso","LeftUpperLeg"},{"LowerTorso","RightUpperLeg"},
    {"LeftUpperLeg","LeftLowerLeg"},{"RightUpperLeg","RightLowerLeg"},
    {"LeftLowerLeg","LeftFoot"},{"RightLowerLeg","RightFoot"},
}

function removeSkeleton(player)
    if skelParts[player] then
        for _, obj in ipairs(skelParts[player]) do
            pcall(function()
                if typeof(obj) == "RBXScriptConnection" then
                    obj:Disconnect()
                elseif obj.Remove then
                    obj:Remove()
                elseif obj.Destroy then
                    obj:Destroy()
                end
            end)
        end
        skelParts[player] = nil
    end
end

function buildSkeleton(player)
    removeSkeleton(player)
    local char = player.Character
    if not char then return end
    if not char:FindFirstChild("HumanoidRootPart") then
        skelParts[player] = {}
        task.wait(1)
        char = player.Character
        if not char then skelParts[player] = nil; return end
    end
    local _pr = GetPlayerRole(player); local role = (_pr ~= "" and _pr ~= "Grey") and _pr or "Innocent"
    local show = vsShow(VisualState.skeleton, role, player)
    if not show then return end

    local color = colorOf(role)
    local objs  = {}
    local lines  = {}   -- Drawing.Line por cada hueso
    local camera = workspace.CurrentCamera

    for _, pair in ipairs(SKELETON_PAIRS) do
        local ln = Drawing.new("Line")
        ln.Thickness  = 1.5
        ln.Color      = color
        ln.Transparency = 1
        ln.Visible    = false
        ln.ZIndex     = 1
        table.insert(objs,  ln)
        table.insert(lines, { line = ln, b1 = pair[1], b2 = pair[2] })
    end
    local headDot = Drawing.new("Circle")
    headDot.Radius      = 5
    headDot.Color       = color
    headDot.Thickness   = 1.5
    headDot.Filled      = false
    headDot.Transparency = 1
    headDot.Visible     = false
    table.insert(objs, headDot)

    local _hbTlocalConn = 0
    local conn = RunService.Heartbeat:Connect(function()
        _hbTlocalConn=_hbTlocalConn+1; if _hbTlocalConn<10 then return end; _hbTlocalConn=0  -- OPT: 6->10 frames (~6Hz)
        local c = player.Character
        if not c or not c.Parent then
            for _, ln in ipairs(objs) do pcall(function() ln:Remove() end) end
            skelParts[player] = nil
            return
        end
        local cam = workspace.CurrentCamera
        -- OPT: GetPlayerRole O(1) en vez de roleOf con GetChildren() a 20Hz
        local _pr2 = GetPlayerRole(player)
        local r2 = (_pr2 ~= "" and _pr2 ~= "Grey") and _pr2 or "Innocent"
        local sh  = vsShow(VisualState.skeleton, r2, player)
        local col = colorOf(r2)

        if not sh then
            for _, ln in ipairs(objs) do ln.Visible = false end
            return
        end

        for _, entry in ipairs(lines) do
            local part1 = c:FindFirstChild(entry.b1)
            local part2 = c:FindFirstChild(entry.b2)
            if part1 and part2 then
                local sp1, on1 = cam:WorldToViewportPoint(part1.Position)
                local sp2, on2 = cam:WorldToViewportPoint(part2.Position)
                if on1 or on2 then
                    entry.line.From    = Vector2.new(sp1.X, sp1.Y)
                    entry.line.To      = Vector2.new(sp2.X, sp2.Y)
                    entry.line.Color   = col
                    entry.line.Visible = true
                else
                    entry.line.Visible = false
                end
            else
                entry.line.Visible = false
            end
        end

        local head = c:FindFirstChild("Head")
        if head then
            local sp, on = cam:WorldToViewportPoint(head.Position)
            if on then
                headDot.Position  = Vector2.new(sp.X, sp.Y)
                headDot.Radius    = math.clamp(300 / math.max(sp.Z, 1), 3, 10)
                headDot.Color     = col
                headDot.Visible   = true
            else
                headDot.Visible = false
            end
        end
    end)
    table.insert(objs, conn)

    skelParts[player] = objs
end

ESPBoards = { coin = {} }

-- Caches event-driven para evitar workspace:GetDescendants() en cada tick
_coinWorldCache  = {}   -- [obj] = true
_knifeWorldCache = {}   -- [obj] = true

workspace.DescendantAdded:Connect(function(obj)
    if not obj:IsA("BasePart") and not obj:IsA("Model") then return end
    local n = obj.Name
    if n == "Coin_Server" or n:lower():find("coin") then
        if obj:IsA("BasePart") then _coinWorldCache[obj] = true end
    end
    if n == "Knife" or n == "KnifeHandle" then
        if not obj:IsDescendantOf(Players) then _knifeWorldCache[obj] = true end
    end
end)

workspace.DescendantRemoving:Connect(function(obj)
    -- OPT: solo limpiar si el obj estaba en algun cache (mayoria de partes del mapa no estan)
    if _coinWorldCache[obj]  then _coinWorldCache[obj]  = nil end
    if _knifeWorldCache[obj] then _knifeWorldCache[obj] = nil end
end)

task.spawn(function()
    for _, obj in ipairs(workspace:GetDescendants()) do
        local n = obj.Name
        if obj:IsA("BasePart") then
            if n == "Coin_Server" or n:lower():find("coin") then
                _coinWorldCache[obj] = true
            end
        end
        if n == "Knife" or n == "KnifeHandle" then
            if not obj:IsDescendantOf(Players) then _knifeWorldCache[obj] = true end
        end
    end
end)

function clearCoinsESP()
    for obj, bb in pairs(ESPBoards.coin) do
        pcall(function() bb:Destroy() end)
        ESPBoards.coin[obj] = nil
    end
end

-- Detecta ThrowingKnife del murderer en workspace (knife lanzado)
-- y aplica multiples tipos de ESP segun los modos activos:
--   box     -> frame 2D sobre el knife
--   outline -> Highlight outline
--   cham    -> Highlight fill (chams)
--   text    -> BillboardGui con label + distancia
-- ===================================================================
-- === THROWN KNIFE ESP -- texto al lado del knife cuando el MURDER lo lanza ===
-- Solo ThrowingKnife (en vuelo), solo del murder, texto pequeno, fondo invisible
_thrownKnifeObjects = {}
_thrownKnifeConn    = nil
_thrownKnifeEnabled = true  -- siempre activo, no necesita toggle

function _isThrownKnifeByMurder(obj)
    if obj.Name ~= "ThrowingKnife" then return false end
    for _, p in ipairs(_cachedPlayers) do
        if p.Character and obj:IsDescendantOf(p.Character) then return false end
    end
    _refreshRoleCache()
    return _roleCache and _roleCache.murderer ~= nil
end

function _getKnifePart(obj)
    if obj:IsA("BasePart") or obj:IsA("MeshPart") then return obj end
    return obj:FindFirstChild("KnifeVisual")
        or obj:FindFirstChildWhichIsA("MeshPart")
        or obj:FindFirstChildWhichIsA("BasePart")
end

function _applyKnifeTextESP(obj)
    if _thrownKnifeObjects[obj] then return end
    local part = _getKnifePart(obj)
    if not part then
        task.wait(0.016)
        if not obj.Parent then return end
        part = _getKnifePart(obj)
        if not part then return end
    end

    -- BillboardGui: pequeno, al lado del knife, fondo invisible
    local bb = Instance.new("BillboardGui")
    bb.Name         = "_TKText"
    bb.Adornee      = part
    bb.Size         = UDim2.new(0, 60, 0, 18)
    bb.StudsOffset  = Vector3.new(2, 0.5, 0)  -- al lado derecho del knife
    bb.AlwaysOnTop  = true
    bb.MaxDistance  = 200
    bb.Parent       = part

    local lbl = Instance.new("TextLabel", bb)
    lbl.Size                   = UDim2.new(1, 0, 1, 0)
    lbl.BackgroundTransparency = 1   -- fondo invisible
    lbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    lbl.TextSize               = 11
    lbl.TextColor3             = Color3.fromRGB(255, 80, 60)
    lbl.TextStrokeTransparency = 0.2
    lbl.TextStrokeColor3       = Color3.fromRGB(0, 0, 0)
    lbl.Text                   = "knife"
    lbl.TextXAlignment         = Enum.TextXAlignment.Left

    _thrownKnifeObjects[obj] = bb

    -- Auto-destruir cuando el knife desaparece
    obj.AncestryChanged:Connect(function()
        if obj.Parent then return end
        pcall(function() if bb and bb.Parent then bb:Destroy() end end)
        _thrownKnifeObjects[obj] = nil
    end)
end

-- Listener: detecta ThrowingKnife del murder en workspace
_thrownKnifeConn = workspace.DescendantAdded:Connect(function(obj)
    if not _thrownKnifeEnabled then return end
    if _isThrownKnifeByMurder(obj) then
        task.spawn(function() pcall(_applyKnifeTextESP, obj) end)
    end
end)

-- Compat legacy
function startKnifeESP() _thrownKnifeEnabled = true  end
function stopKnifeESP()  _thrownKnifeEnabled = false
    for obj, bb in pairs(_thrownKnifeObjects) do
        pcall(function() if bb and bb.Parent then bb:Destroy() end end)
    end
    _thrownKnifeObjects = {}
end



