DeathPoseState = {
    enabled   = false,
    highlights = {},  -- [userId] = { hl=Highlight, bb=BillboardGui, char=Model }
}

-- -- Limpia TODOS los clones y ESPs del Dead Cham al fin de ronda -------------
function _clearAllDeadCham()
    -- 1. DeathPoseState.highlights -- adornments, highlights, billboards, clones
    pcall(function()
        for uid, entry in pairs(DeathPoseState.highlights) do
            pcall(function()
                for _, a in ipairs(entry.adornments or {}) do
                    if a and a.Parent then a:Destroy() end
                end
                if entry.hl    and entry.hl.Parent    then entry.hl:Destroy()    end
                if entry.bb    and entry.bb.Parent    then entry.bb:Destroy()    end
                if entry.clone and entry.clone.Parent then entry.clone:Destroy() end
            end)
        end
    end)
    DeathPoseState.highlights = {}

    -- 2. DeadBodyESP.highlights -- estatuas clonadas en workspace
    pcall(function()
        if DeadBodyESP and DeadBodyESP.highlights then
            for plr, data in pairs(DeadBodyESP.highlights) do
                pcall(function()
                    if data.clone and data.clone.Parent then data.clone:Destroy() end
                    if data.conn  then data.conn:Disconnect() end
                end)
            end
            DeadBodyESP.highlights = {}
        end
    end)

    -- 3. Sweep de seguridad en workspace: destruir cualquier estatua/clone huerfano
    pcall(function()
        for _, obj in ipairs(workspace:GetChildren()) do
            -- Estatuas del Dead Body ESP (nombre "Estatua_<jugador>")
            if obj:IsA("Model") and tostring(obj.Name):find("^Estatua_") then
                pcall(function() obj:Destroy() end)
            end
            -- Clones del DeathPose (nombre "DeathPose_<jugador>")
            if obj:IsA("Model") and tostring(obj.Name):find("^DeathPose_") then
                pcall(function() obj:Destroy() end)
            end
        end
        -- Carpeta de clones
        local folder = workspace:FindFirstChild(CLONE_FOLDER_NAME or "DeathPoseClones_Local")
        if folder then folder:Destroy() end
    end)

    -- 4. Highlights huerfanos con atributos _deadEsp / _deadCham
    pcall(function()
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("Highlight") and (
                obj.Name == "DeadESP" or obj.Name == "ChamRaggyHL" or
                obj:GetAttribute("_deadEsp") or obj:GetAttribute("_deadCham")
            ) then
                pcall(function() obj:Destroy() end)
            end
        end
    end)

    -- 5. Carpeta _DeathPoseESP -- vaciar TODOS los hijos sin destruir la carpeta
    -- (destruir la carpeta y recrearla causa un frame donde los clones nuevos
    --  no tienen padre valido; vaciarla es mas seguro y evita referencias huerfanas)
    pcall(function()
        local espFolder = workspace:FindFirstChild("_DeathPoseESP")
        if espFolder then
            for _, child in ipairs(espFolder:GetChildren()) do
                pcall(function() child:Destroy() end)
            end
            -- Sweep adicional: por si GetChildren() devolvio lista desactualizada
            -- (puede pasar si hubo inserciones concurrentes en el mismo frame)
            for _, child in ipairs(espFolder:GetChildren()) do
                pcall(function() child:Destroy() end)
            end
        end
    end)
end
_G._clearAllDeadCham = _clearAllDeadCham

CLONE_FOLDER_NAME = "DeathPoseClones_Local"  -- kept for compatibility
function getCloneFolder()
    local folder = workspace:FindFirstChild(CLONE_FOLDER_NAME)
    if not folder then
        folder = Instance.new("Folder")
        folder.Name = CLONE_FOLDER_NAME
        folder.Parent = workspace
    end
    return folder
end

-- -- Aplicar ESP Cham al cuerpo muerto ----------------------------------------
-- NO clonamos nada. El cuerpo muerto sigue en workspace con su pose exacta.
-- Solo le ponemos un Highlight encima.
function spawnDeathClone(player, _snapOverride)
    if not DeathPoseState.enabled then return end
    local uid = player.UserId

    -- Limpiar ESP anterior si existe
    local prev = DeathPoseState.highlights[uid]
    if prev then
        pcall(function() if prev.hl and prev.hl.Parent then prev.hl:Destroy() end end)
        pcall(function() if prev.bb and prev.bb.Parent then prev.bb:Destroy() end end)
        DeathPoseState.highlights[uid] = nil
    end

    -- El personaje muerto sigue en workspace -- usarlo directamente
    local deadChar = player.Character
    if not deadChar or not deadChar.Parent then return end

    -- Verificar que realmente esta muerto
    local hum = deadChar:FindFirstChildOfClass("Humanoid")
    -- Puede que Health ya sea 0, o que el Humanoid ya fue removido -- ambos casos OK

    -- -- Color segun rol -------------------------------------------------------
    local _espFill, _espOutline
    if _roleCache.murderer == player then
        _espFill    = Color3.fromRGB(255,  60,  60)
        _espOutline = Color3.fromRGB(255, 150, 150)
    elseif _roleCache.sheriff == player or _roleCache.hero == player then
        _espFill    = Color3.fromRGB( 80, 160, 255)  -- Azul (sheriff/hero)
        _espOutline = Color3.fromRGB(255, 200,  70)  -- Amarillo contorno
    else
        _espFill    = Color3.fromRGB( 60, 220, 100)
        _espOutline = Color3.fromRGB(120, 255, 150)
    end

    -- Aplicar color de paleta si el usuario eligio uno
    local _deathColorPalette = {
        nil,  -- indice 1 = por rol (no override)
        { fill = Color3.fromRGB(255, 60, 60), outline = Color3.fromRGB(255,150,150) },
        { fill = Color3.fromRGB( 80,160,255), outline = Color3.fromRGB(255, 200, 70) },
        { fill = Color3.fromRGB( 30,220, 80), outline = Color3.fromRGB(255, 181, 51) },
        { fill = Color3.fromRGB(220,220,255), outline = Color3.fromRGB(255,255,255) },
        { fill = Color3.fromRGB(255,140,  0), outline = Color3.fromRGB(255,200, 80) },
    }
    local pidx = (type(_DeathEspColorIdx) == "number" and _DeathEspColorIdx >= 2)
                 and _DeathEspColorIdx or nil
    if pidx and _deathColorPalette[pidx] then
        _espFill    = _deathColorPalette[pidx].fill
        _espOutline = _deathColorPalette[pidx].outline
    end

    -- -- Highlight directo sobre el cuerpo muerto -----------------------------
    local hl = Instance.new("Highlight")
    hl.FillColor           = _espFill
    hl.FillTransparency    = (type(_DeathEspFillTransp) == "number") and _DeathEspFillTransp or 0.35
    hl.OutlineColor        = _espOutline
    hl.OutlineTransparency = 0.0
    hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Adornee             = deadChar   -- apunta al model del personaje muerto
    hl.Parent              = deadChar   -- parented en el mismo char

    -- -- BillboardGui flotante -------------------------------------------------
    local hrp = deadChar:FindFirstChild("HumanoidRootPart")
             or deadChar:FindFirstChildWhichIsA("BasePart")
    local bb = nil
    if hrp then
        bb = Instance.new("BillboardGui")
        bb.Adornee     = hrp
        bb.Size        = UDim2.new(0, 200, 0, 58)
        bb.StudsOffset = Vector3.new(0, 3.2, 0)
        bb.AlwaysOnTop = true
        bb.MaxDistance = 300
        bb.Parent      = deadChar

        local nameL = Instance.new("TextLabel", bb)
        nameL.Size                   = UDim2.new(1, 0, 0.55, 0)
        nameL.BackgroundTransparency = 1
        nameL.Text                   = "! " .. player.Name
        nameL.FontFace = Font.fromEnum(Enum.Font.Arimo)
        nameL.TextSize               = 15
        nameL.TextColor3             = _espFill
        nameL.TextStrokeColor3       = Color3.fromRGB(0, 0, 0)
        nameL.TextStrokeTransparency = 0
        nameL.TextXAlignment         = Enum.TextXAlignment.Center

        local _rStr
        if     _roleCache.murderer == player then _rStr = "* MURDERER"
        elseif _roleCache.sheriff  == player
            or _roleCache.hero     == player then _rStr = "* SHERIFF"
        else                                      _rStr = "* INNOCENT" end

        local roleL = Instance.new("TextLabel", bb)
        roleL.Size                   = UDim2.new(1, 0, 0.45, 0)
        roleL.Position               = UDim2.new(0, 0, 0.55, 0)
        roleL.BackgroundTransparency = 1
        roleL.Text                   = _rStr
        roleL.FontFace = Font.fromEnum(Enum.Font.Arimo)
        roleL.TextSize               = 11
        roleL.TextColor3             = _espFill
        roleL.TextStrokeColor3       = Color3.fromRGB(0, 0, 0)
        roleL.TextStrokeTransparency = 0.2
        roleL.TextXAlignment         = Enum.TextXAlignment.Center
    end

    DeathPoseState.highlights[uid] = { hl = hl, bb = bb, char = deadChar }

    -- Auto-limpiar cuando el personaje sea removido de workspace
    -- (MM2 quita el cuerpo muerto despues de ~15 segundos)
    task.spawn(function()
        -- Esperar a que el personaje salga del workspace
        local t = 0
        while deadChar and deadChar.Parent and t < 30 do
            task.wait(0.5)
            t = t + 0.5
        end
        local entry = DeathPoseState.highlights[uid]
        if entry and entry.char == deadChar then
            pcall(function() if entry.hl and entry.hl.Parent then entry.hl:Destroy() end end)
            pcall(function() if entry.bb and entry.bb.Parent then entry.bb:Destroy() end end)
            DeathPoseState.highlights[uid] = nil
        end
    end)
end

function clearDeathPose(player)
    local uid = player.UserId
    local entry = DeathPoseState.highlights and DeathPoseState.highlights[uid]
    if entry then
        for _, a in ipairs(entry.adornments or {}) do
            pcall(function() if a and a.Parent then a:Destroy() end end)
        end
        pcall(function() if entry.hl and entry.hl.Parent then entry.hl:Destroy() end end)
        pcall(function() if entry.bb and entry.bb.Parent then entry.bb:Destroy() end end)
        DeathPoseState.highlights[uid] = nil
    end
end

-- ensureSnapTracking ya no necesita hacer nada (no clonamos),
-- pero la mantenemos para no romper llamadas existentes
_snapConn = nil
function ensureSnapTracking()
    -- No-op: ahora aplicamos ESP directo al cuerpo muerto, sin snapshot
end

-- -- BODY PARTS para BoxHandleAdornment ---------------------------------------
_DEATH_POSE_PARTS = {
    "Head", "UpperTorso", "LowerTorso", "Torso",
    "LeftUpperArm", "LeftLowerArm", "LeftHand",
    "RightUpperArm", "RightLowerArm", "RightHand",
    "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
    "RightUpperLeg", "RightLowerLeg", "RightFoot",
    "LeftArm", "RightArm", "LeftLeg", "RightLeg",
}

-- -- Obtener color de rol para el dead pose ------------------------------------
function _getDeathPoseColor(player)
    if _roleCache and _roleCache.murderer == player then
        return Color3.fromRGB(255,   0,  40)   -- rojo: murderer
    elseif _roleCache and (_roleCache.sheriff == player or _roleCache.hero == player) then
        return Color3.fromRGB(80, 80, 85)  -- morado: sheriff/hero
    else
        return Color3.fromRGB(224, 127, 27)   -- verde: innocent
    end
end

-- -- Aplicar BoxHandleAdornments al cuerpo muerto -----------------------------
-- No clona nada -- usa el cuerpo real que MM2 deja en workspace
function _applyDeathPoseAdornments(player, char)
    if not char or not char.Parent then return end
    local color = _getDeathPoseColor(player)
    local uid   = player.UserId

    -- Limpiar adornos anteriores del mismo jugador
    local prev = DeathPoseState.highlights[uid]
    if prev then
        for _, adorn in ipairs(prev.adornments or {}) do
            pcall(function() if adorn and adorn.Parent then adorn:Destroy() end end)
        end
        pcall(function() if prev.bb and prev.bb.Parent then prev.bb:Destroy() end end)
        DeathPoseState.highlights[uid] = nil
    end

    local adornments = {}

    -- Aplicar BoxHandleAdornment en cada parte del cuerpo
    for _, partName in ipairs(_DEATH_POSE_PARTS) do
        local part = char:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            local ok, adorn = pcall(function()
                local a = Instance.new("BoxHandleAdornment")
                a.Name        = "DeathPoseAdorn"
                a.Adornee     = part
                a.Parent      = part
                a.AlwaysOnTop = true   -- se ve a traves de paredes
                a.ZIndex      = 10
                a.Size        = (partName == "Head")
                                and Vector3.new(1.05, 1.05, 1.05)
                                or  part.Size + Vector3.new(0.08, 0.08, 0.08)
                a.Color3      = color
                a.Transparency = 0.45
                return a
            end)
            if ok and adorn then
                table.insert(adornments, adorn)
            end
        end
    end

    -- BillboardGui flotante con nombre + rol
    local hrp = char:FindFirstChild("HumanoidRootPart")
             or char:FindFirstChildWhichIsA("BasePart")
    local bb = nil
    if hrp then
        bb             = Instance.new("BillboardGui")
        bb.Adornee     = hrp
        bb.Size        = UDim2.new(0, 200, 0, 52)
        bb.StudsOffset = Vector3.new(0, 3.5, 0)
        bb.AlwaysOnTop = true
        bb.MaxDistance = 400
        bb.Parent      = char

        local nameL = Instance.new("TextLabel", bb)
        nameL.Size                   = UDim2.new(1, 0, 0.55, 0)
        nameL.BackgroundTransparency = 1
        nameL.Text                   = "! " .. player.Name
        nameL.FontFace               = Font.fromEnum(Enum.Font.Arimo)
        nameL.TextSize               = 15
        nameL.TextColor3             = color
        nameL.TextStrokeColor3       = Color3.new(0, 0, 0)
        nameL.TextStrokeTransparency = 0
        nameL.TextXAlignment         = Enum.TextXAlignment.Center

        local _rStr
        if     _roleCache and _roleCache.murderer == player then _rStr = "* MURDERER"
        elseif _roleCache and (_roleCache.sheriff == player
            or _roleCache.hero == player)             then _rStr = "* SHERIFF"
        else                                               _rStr = "* INNOCENT" end

        local roleL = Instance.new("TextLabel", bb)
        roleL.Size                   = UDim2.new(1, 0, 0.45, 0)
        roleL.Position               = UDim2.new(0, 0, 0.55, 0)
        roleL.BackgroundTransparency = 1
        roleL.Text                   = _rStr
        roleL.FontFace               = Font.fromEnum(Enum.Font.Arimo)
        roleL.TextSize               = 11
        roleL.TextColor3             = color
        roleL.TextStrokeColor3       = Color3.new(0, 0, 0)
        roleL.TextStrokeTransparency = 0.2
        roleL.TextXAlignment         = Enum.TextXAlignment.Center
    end

    DeathPoseState.highlights[uid] = { adornments = adornments, bb = bb, char = char }

    -- NO auto-limpiar: el cuerpo dura toda la ronda
    -- Se limpia solo cuando empieza nueva ronda (RoundStart -> clearDeathPose)
end

-- -- hookCharDeathPose -- GHOST ESP (3 pilares tecnicos) ----------------------
-- Pilar 1: RenderStepped snapshot cada frame (no Heartbeat) -- captura pose exacta
-- Pilar 2: Clone asincronico con Archivable=true + PivotTo() al ultimo snapshot
-- Pilar 3: BoxHandleAdornment AlwaysOnTop en todos los BaseParts del clon (wallhack)
-- Extra:   Vigila workspace.House2 y otros contenedores secundarios de MM2
function hookCharDeathPose(player, char)
    local hum = char:WaitForChild("Humanoid", 10)
    if not hum then return end

    -- -- PILAR 1: Snapshot en RenderStepped (cada frame, maxima fidelidad) ------
    local lastCF   = char:GetPivot()  -- CFrame completo del model
    local partSnap = {}               -- [part] = {CFrame, Size} para accesorios
    local trackerConn

    -- OPT: GetDescendants() en cada RenderStepped (60Hz) era muy costoso.
    -- Cambiamos a Heartbeat con throttle de 6 frames (~10Hz).
    -- La pose de muerte se captura con suficiente fidelidad a 10Hz.
    -- Adicionalmente: la lista de BaseParts se cachea en la primera captura
    -- y solo se reconstruye si el personaje cambia (DescendantAdded/Removed).
    local _snapPartList = nil   -- cache de partes: solo se reconstruye si cambia el char
    local _snapDirty    = true  -- true = reconstruir lista en el proximo tick
    char.DescendantAdded:Connect(function()   _snapDirty = true end)
    char.DescendantRemoving:Connect(function() _snapDirty = true end)

    local _dtSnapTick = 0
    local _tcTick=0
    trackerConn = game:GetService("RunService").Heartbeat:Connect(function()
        _tcTick=_tcTick+1; if _tcTick<6 then return end; _tcTick=0  -- OPT: 10Hz para tracker
        _dtSnapTick = _dtSnapTick + 1
        if _dtSnapTick < 6 then return end  -- OPT: ~10Hz (era RenderStepped=60Hz)
        _dtSnapTick = 0
        if not char or not char.Parent then
            if trackerConn then trackerConn:Disconnect(); trackerConn = nil end
            return
        end
        if hum.Health <= 0 then return end  -- congelado en el ultimo frame vivo

        pcall(function() lastCF = char:GetPivot() end)

        -- Reconstruir lista de partes solo cuando cambia el personaje
        if _snapDirty then
            _snapPartList = {}
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then
                    table.insert(_snapPartList, p)
                end
            end
            _snapDirty = false
        end

        if _snapPartList then
            for _, p in ipairs(_snapPartList) do
                if p and p.Parent then
                    partSnap[p] = { CFrame = p.CFrame, Size = p.Size, Name = p.Name }
                end
            end
        end
    end)

    -- -- Buscar ragdoll en TODO workspace (el mapa siempre cambia) ---------------
    -- MM2 mueve el modelo muerto a workspace.{NombreMapa}:GetChildren()[N]
    -- No podemos hardcodear el nombre del mapa -> escanear TODOS los hijos de workspace.
    local function _findRagdollAnywhere()
        -- 1. Buscar por nombre del jugador directo en hijos de workspace
        local direct = workspace:FindFirstChild(player.Name)
        if direct and direct:IsA("Model") then return direct end

        -- 2. Escanear TODOS los contenedores de workspace (mapas, carpetas, etc.)
        -- workspace.House2:GetChildren()[8] -> no sabemos el indice ni el mapa
        -- -> buscar en GetChildren() de cada hijo de workspace
        for _, container in ipairs(workspace:GetChildren()) do
            -- Saltar cosas que claramente no son contenedores de mapa
            if container:IsA("Model") or container:IsA("Folder") then
                -- Buscar el model del jugador por nombre
                local byName = container:FindFirstChild(player.Name)
                if byName and byName:IsA("Model") then
                    return byName
                end
                -- Buscar mas profundo (1 nivel) -- workspace.House2.Folder.PlayerModel
                for _, child in ipairs(container:GetChildren()) do
                    if child:IsA("Model") and child.Name == player.Name then
                        return child
                    end
                    -- Un nivel mas: workspace.House2.Something.PlayerName
                    if child:IsA("Model") or child:IsA("Folder") then
                        local deep = child:FindFirstChild(player.Name)
                        if deep and deep:IsA("Model") then
                            return deep
                        end
                    end
                end
            end
        end

        -- 3. Buscar por HumanoidRootPart con el userId en descendientes
        -- (algunos juegos renombran el model pero dejan el HRP intacto)
        for _, container in ipairs(workspace:GetChildren()) do
            if container:IsA("Model") or container:IsA("Folder") then
                for _, child in ipairs(container:GetDescendants()) do
                    if child:IsA("Model") then
                        local hrp = child:FindFirstChild("HumanoidRootPart")
                        local hum = child:FindFirstChildOfClass("Humanoid")
                        -- Identificar por presencia de HRP + sin Humanoid vivo = ragdoll
                        if hrp and (not hum or hum.Health <= 0) then
                            -- Verificar que las partes del body coincidan con el char original
                            local hasHead = child:FindFirstChild("Head")
                            if hasHead and child.Name == player.Name then
                                return child
                            end
                        end
                    end
                end
            end
        end

        return nil
    end

    local fired = false
    local function _onDeath()
        if fired then return end
        fired = true
        if trackerConn then trackerConn:Disconnect(); trackerConn = nil end
        if not DeathPoseState.enabled then return end

        local color = _getDeathPoseColor(player)
        local uid   = player.UserId

        -- Limpiar ESP anterior del mismo jugador
        local prev = DeathPoseState.highlights[uid]
        if prev then
            for _, a in ipairs(prev.adornments or {}) do
                pcall(function() if a and a.Parent then a:Destroy() end end)
            end
            pcall(function() if prev.bb  and prev.bb.Parent  then prev.bb:Destroy()  end end)
            pcall(function() if prev.clone and prev.clone.Parent then prev.clone:Destroy() end end)
            DeathPoseState.highlights[uid] = nil
        end

        -- Carpeta de destino
        local folder = workspace:FindFirstChild("_DeathPoseESP")
        if not folder then
            folder = Instance.new("Folder")
            folder.Name = "_DeathPoseESP"
            folder.Parent = workspace
        end

        -- -- PILAR 2: Clonacion asincronica --------------------------------------
        -- Forzar Archivable antes de clonar (requerido para modelos del servidor)
        local clone = nil
        pcall(function()
            char.Archivable = true
            clone = char:Clone()
        end)

        -- Si el char ya fue destruido, buscar en contenedores secundarios
        if not clone then
            -- Escanear todo workspace para el ragdoll (mapa variable)
            local ragdoll = _findRagdollAnywhere()
            if ragdoll then
                pcall(function()
                    ragdoll.Archivable = true
                    clone = ragdoll:Clone()
                end)
            end
            -- Si aun no encontramos, esperar 1 frame y reintentar
            -- (MM2 puede moverlo en el mismo frame de muerte)
            if not clone then
                task.wait()
                ragdoll = _findRagdollAnywhere()
                if ragdoll then
                    pcall(function()
                        ragdoll.Archivable = true
                        clone = ragdoll:Clone()
                    end)
                end
            end
        end

        if clone then
            -- Limpiar scripts y Humanoid del clon para que no ejecute logica
            for _, d in ipairs(clone:GetDescendants()) do
                if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ModuleScript") then
                    pcall(function() d:Destroy() end)
                end
            end
            pcall(function()
                local h = clone:FindFirstChildOfClass("Humanoid")
                if h then h:Destroy() end
                local anim = clone:FindFirstChild("Animate")
                if anim then anim:Destroy() end
            end)

            -- Anclar todas las partes
            for _, p in ipairs(clone:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Anchored     = true
                    p.CanCollide   = false
                    p.CanQuery     = false
                    p.CanTouch     = false
                    p.CastShadow   = false
                end
            end

            -- -- PivotTo: colocar el clon en la ultima pose snapshot ------------
            pcall(function() clone:PivotTo(lastCF) end)

            clone.Name   = "DeathPose_" .. player.Name
            clone.Parent = folder

            -- -- PILAR 3: BoxHandleAdornment en todos los BaseParts del clon -----
            local adornments = {}
            for _, p in ipairs(clone:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Transparency = 1  -- parte invisible, solo se ve el adorno

                    local a = Instance.new("BoxHandleAdornment")
                    a.Name         = "GhostAdorn"
                    a.Adornee      = p
                    a.AlwaysOnTop  = true   -- visible a traves de paredes (wallhack)
                    a.ZIndex       = 10
                    a.Size         = p.Size + Vector3.new(0.05, 0.05, 0.05)
                    a.Color3       = color
                    a.Transparency = 0.4
                    a.Parent       = p
                    table.insert(adornments, a)
                end
            end

            -- BillboardGui
            local hrpPart = clone:FindFirstChild("HumanoidRootPart")
                         or clone:FindFirstChildWhichIsA("BasePart")
            local bb = nil
            if hrpPart then
                bb             = Instance.new("BillboardGui")
                bb.Adornee     = hrpPart
                bb.Size        = UDim2.new(0, 200, 0, 52)
                bb.StudsOffset = Vector3.new(0, 3.5, 0)
                bb.AlwaysOnTop = true
                bb.MaxDistance = 400
                bb.Parent      = clone

                local nameL = Instance.new("TextLabel", bb)
                nameL.Size = UDim2.new(1,0,0.55,0); nameL.BackgroundTransparency = 1
                nameL.Text = "! " .. player.Name
                nameL.FontFace = Font.fromEnum(Enum.Font.Arimo)
                nameL.TextSize = 15; nameL.TextColor3 = color
                nameL.TextStrokeColor3 = Color3.new(0,0,0); nameL.TextStrokeTransparency = 0
                nameL.TextXAlignment = Enum.TextXAlignment.Center

                local _rStr
                if     _roleCache and _roleCache.murderer == player then _rStr = "* MURDERER"
                elseif _roleCache and (_roleCache.sheriff == player
                    or _roleCache.hero == player)             then _rStr = "* SHERIFF"
                else                                               _rStr = "* INNOCENT" end

                local roleL = Instance.new("TextLabel", bb)
                roleL.Size = UDim2.new(1,0,0.45,0); roleL.Position = UDim2.new(0,0,0.55,0)
                roleL.BackgroundTransparency = 1; roleL.Text = _rStr
                roleL.FontFace = Font.fromEnum(Enum.Font.Arimo); roleL.TextSize = 11
                roleL.TextColor3 = color
                roleL.TextStrokeColor3 = Color3.new(0,0,0); roleL.TextStrokeTransparency = 0.2
                roleL.TextXAlignment = Enum.TextXAlignment.Center
            end

            DeathPoseState.highlights[uid] = { adornments = adornments, bb = bb, clone = clone }

        else
            -- Fallback: sin clon (char destruido antes de poder clonarlo)
            -- Usar el snapshot de partes individuales guardado en RenderStepped
            if not next(partSnap) then return end

            local staticModel = Instance.new("Model")
            staticModel.Name  = "DeathPose_" .. player.Name
            local adornments  = {}

            for part, data in pairs(partSnap) do
                pcall(function()
                    local p = Instance.new("Part")
                    p.Name         = data.Name or "Part"
                    p.Size         = data.Size
                    p.CFrame       = data.CFrame
                    p.Anchored     = true
                    p.CanCollide   = false
                    p.CanQuery     = false
                    p.CastShadow   = false
                    p.Transparency = 1
                    p.Parent       = staticModel

                    local a = Instance.new("BoxHandleAdornment")
                    a.Name         = "GhostAdorn"
                    a.Adornee      = p
                    a.AlwaysOnTop  = true
                    a.ZIndex       = 10
                    a.Size         = p.Size + Vector3.new(0.05, 0.05, 0.05)
                    a.Color3       = color
                    a.Transparency = 0.4
                    a.Parent       = p
                    table.insert(adornments, a)
                end)
            end

            staticModel.Parent = folder
            DeathPoseState.highlights[uid] = { adornments = adornments, bb = nil, clone = staticModel }
        end
    end

    hum.HealthChanged:Connect(function(hp) if hp <= 0 then _onDeath() end end)
    hum.Died:Connect(_onDeath)

    -- -- Watcher de workspace: captura el modelo cuando MM2 lo mueve al mapa --
    -- workspace.DescendantAdded detecta modelos re-emparentados (House2, etc.)
    local _wsWatcher
    _wsWatcher = workspace.DescendantAdded:Connect(function(obj)
        if fired then
            pcall(function() _wsWatcher:Disconnect() end)
            return
        end
        -- Si aparece un model con el nombre del jugador -> es el ragdoll
        if obj:IsA("Model") and obj.Name == player.Name then
            if hum.Health <= 0 then
                pcall(function() _wsWatcher:Disconnect() end)
                task.spawn(_onDeath)
            end
        end
    end)
end

function hookDeathPose(player)
    if player == LocalPlayer then return end
    player.CharacterAdded:Connect(function(char)
        clearDeathPose(player)
        task.defer(function()
            hookCharDeathPose(player, char)
        end)
    end)
    if player.Character then
        hookCharDeathPose(player, player.Character)
    end
end

for _, p in ipairs(_cachedPlayers) do hookDeathPose(p) end
Players.PlayerAdded:Connect(hookDeathPose)
ensureSnapTracking()

DeadBodyESP = {
    enabled      = false,
    highlights   = {},
    TIEMPO_MUERTO = 15,  -- Igual que el codigo de referencia
}

-- Colores por rol (rojo=murder, azul=sheriff, verde=innocent)
_DB_COLOR_MURDER   = Color3.fromRGB(255,  60,  60)  -- Rojo
_DB_COLOR_SHERIFF  = Color3.fromRGB( 80, 160, 255)  -- Azul
_DB_COLOR_INNOCENT = Color3.fromRGB( 60, 220, 100)  -- Verde

function _getDeadRoleColor(player)
    if _roleCache.murderer == player then
        return _DB_COLOR_MURDER,   " MURDERER"
    end
    if _roleCache.sheriff == player or _roleCache.hero == player then
        return _DB_COLOR_SHERIFF,  " SHERIFF"
    end
    return _DB_COLOR_INNOCENT, " INNOCENT"
end

-- Aplica el highlight de VIVO al personaje (mientras camina)
-- Highlight = solo BORDES (FillTransparency=1, OutlineTransparency=0)
function _aplicarHighlightVivo(char, color)
    for _, old in ipairs(char:GetChildren()) do
        if old:IsA("Highlight") and old.Name == "ChamESP" then old:Destroy() end
    end
    local hl = Instance.new("Highlight")
    hl.Name = "ChamESP"
    hl.FillColor = color
    hl.FillTransparency = 1              -- sin relleno
    hl.OutlineColor = color
    hl.OutlineTransparency = 0           -- solo bordes visibles
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Parent = char
end

-- Crea la estatua de la pose de muerte -- recibe snapshot ya pre-capturado sincronicamente
function _crearEstatuaMuerte(personaje, espColor, roleLabel, player, preSnap)
    local partSnapshots = {}
    local apparelClones = {}

    if preSnap then
        -- Usar snapshot ya capturado sincronicamente en el evento Died (pose exacta garantizada)
        partSnapshots = preSnap.parts
        apparelClones = preSnap.apparel
    else
        -- Fallback: capturar ahora (puede no tener la pose exacta si hubo yields)
        pcall(function() personaje.Archivable = true end)
        for _, obj in pairs(personaje:GetChildren()) do
            if obj:IsA("BasePart") then
                partSnapshots[obj.Name] = {
                    cf           = obj.CFrame,
                    size         = obj.Size,
                    color        = obj.Color,
                    material     = obj.Material,
                    transparency = obj.Transparency,
                    mesh         = obj:FindFirstChildWhichIsA("SpecialMesh"),
                }
            elseif obj:IsA("Shirt") or obj:IsA("Pants") or obj:IsA("CharacterMesh")
                or obj:IsA("CharacterAppearance") or obj:IsA("BodyColors") then
                pcall(function() table.insert(apparelClones, obj:Clone()) end)
            end
        end
    end

    -- Construir la estatua con los snapshots
    local estatua = Instance.new("Model")
    estatua.Name = "Estatua_" .. personaje.Name

    for partName, snap in pairs(partSnapshots) do
        local part = Instance.new("Part")
        part.Name        = partName
        part.Size        = snap.size
        part.CFrame      = snap.cf       -- aplicar la pose capturada
        part.Color       = snap.color
        part.Material    = snap.material
        part.Transparency = snap.transparency
        part.Anchored    = true
        part.CanCollide  = false
        part.CastShadow  = false
        -- Copiar mesh especial si existia (para partes con forma custom)
        if snap.mesh then
            snap.mesh:Clone().Parent = part
        end
        part.Parent = estatua
    end

    -- Ropa y apariencia
    for _, app in ipairs(apparelClones) do
        app.Parent = estatua
    end

    -- Highlight por rol (rojo=murder, azul=sheriff, cian=innocent)
    local hl = Instance.new("Highlight")
    hl.Name              = "ChamESP"
    hl.FillColor         = espColor
    hl.OutlineColor      = Color3.new(1, 1, 1)
    hl.FillTransparency  = 0.45
    hl.OutlineTransparency = 0
    hl.DepthMode         = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Parent            = estatua

    -- Billboard con nombre y rol
    local rootPart = estatua:FindFirstChild("HumanoidRootPart") or estatua:FindFirstChildWhichIsA("Part")
    if rootPart then
        local bb = Instance.new("BillboardGui")
        bb.Adornee      = rootPart
        bb.Size         = UDim2.new(0, 170, 0, 52)
        bb.StudsOffset  = Vector3.new(0, 3.5, 0)
        bb.AlwaysOnTop  = true
        bb.MaxDistance  = 200
        bb.Parent       = estatua

        local nameL = Instance.new("TextLabel", bb)
        nameL.Size                  = UDim2.new(1, 0, 0.55, 0)
        nameL.BackgroundTransparency = 1
        nameL.Text                  = " " .. personaje.Name
        nameL.FontFace = Font.fromEnum(Enum.Font.Arimo)
        nameL.TextSize              = 14
        nameL.TextColor3            = espColor
        nameL.TextStrokeTransparency = 0
        nameL.TextStrokeColor3      = ThemeColors.Background
        nameL.TextXAlignment        = Enum.TextXAlignment.Center

        local roleL = Instance.new("TextLabel", bb)
        roleL.Size                  = UDim2.new(1, 0, 0.45, 0)
        roleL.Position              = UDim2.new(0, 0, 0.55, 0)
        roleL.BackgroundTransparency = 1
        roleL.Text                  = roleLabel
        roleL.FontFace = Font.fromEnum(Enum.Font.Arimo)
        roleL.TextSize              = 11
        roleL.TextColor3            = espColor
        roleL.TextStrokeTransparency = 0.2
        roleL.TextStrokeColor3      = ThemeColors.Background
        roleL.TextXAlignment        = Enum.TextXAlignment.Center
    end

    estatua.Parent = workspace
    DeadBodyESP.highlights[player] = { clone = estatua, conn = nil }

    task.delay(DeadBodyESP.TIEMPO_MUERTO, function()
        pcall(function() if estatua and estatua.Parent then estatua:Destroy() end end)
        if DeadBodyESP.highlights[player] and DeadBodyESP.highlights[player].clone == estatua then
            DeadBodyESP.highlights[player] = nil
        end
    end)
end

function _applyDeadBodyESP(player, preSnap)
    if not DeadBodyESP.enabled then return end
    if player == LocalPlayer then return end

    local char = player.Character
    if not char then return end
    local espColor, roleLabel = _getDeadRoleColor(player)

    -- Construir la estatua en task.spawn (solo la construccion, el snapshot ya fue capturado)
    task.spawn(function()
        _crearEstatuaMuerte(char, espColor, roleLabel, player, preSnap)
    end)
end

function _hookDeadBodyESP(player)
    if player == LocalPlayer then return end

    local function _hookChar(char)
        -- Limpiar ESP previo si respawnea
        if DeadBodyESP.highlights[player] then
            pcall(function()
                local old = DeadBodyESP.highlights[player]
                if old.clone and old.clone.Parent then old.clone:Destroy() end
                if old.conn then old.conn:Disconnect() end
            end)
            DeadBodyESP.highlights[player] = nil
        end

        local hum  = char:WaitForChild("Humanoid", 8)
        if not hum then return end
        local root = char:WaitForChild("HumanoidRootPart", 5)
        if not root then return end

        -- Capturar snapshot sincronicamente en Died -- ANTES de cualquier yield
        hum.Died:Connect(function()
            if not DeadBodyESP.enabled then return end
            -- Snapshot inmediato: Died dispara con el personaje todavia en workspace
            -- Capturamos AHORA, sincronicamente, antes de que Roblox lo limpie
            local snap = { parts = {}, apparel = {} }
            pcall(function()
                char.Archivable = true
                for _, obj in pairs(char:GetChildren()) do
                    if obj:IsA("BasePart") then
                        snap.parts[obj.Name] = {
                            cf           = obj.CFrame,
                            size         = obj.Size,
                            color        = obj.Color,
                            material     = obj.Material,
                            transparency = obj.Transparency,
                            mesh         = obj:FindFirstChildWhichIsA("SpecialMesh"),
                        }
                    elseif obj:IsA("Shirt") or obj:IsA("Pants") or obj:IsA("CharacterMesh")
                        or obj:IsA("CharacterAppearance") or obj:IsA("BodyColors") then
                        local ok, cl = pcall(function() return obj:Clone() end)
                        if ok and cl then table.insert(snap.apparel, cl) end
                    end
                end
            end)
            -- Pasar el snapshot pre-capturado -- la construccion puede hacerse async
            espColor, roleLabel = _getDeadRoleColor(player)
            task.spawn(function()
                pcall(function()
                    _crearEstatuaMuerte(char, espColor, roleLabel, player, snap)
                end)
            end)
        end)

        DeadBodyESP.highlights[player] = DeadBodyESP.highlights[player] or {}
    end

    player.CharacterAdded:Connect(_hookChar)

    -- Hook al personaje que ya existe al cargar el script
    if player.Character then
        task.spawn(function() _hookChar(player.Character) end)
    end
end

function ToggleDeadBodyESP(v)
    DeadBodyESP.enabled = v
    if not v then
        for plr, data in pairs(DeadBodyESP.highlights) do
            pcall(function()
                if data.clone and data.clone.Parent then data.clone:Destroy() end
                if data.conn then data.conn:Disconnect() end
            end)
        end
        DeadBodyESP.highlights = {}
    end
 CreateCustomNotification("DEAD BODY ESP", v and " Activado (Ghost Clone)" or " Desactivado", 2)
end

for _, p in ipairs(_cachedPlayers) do _hookDeadBodyESP(p) end
Players.PlayerAdded:Connect(_hookDeadBodyESP)

BodyPartState = {
    hideHead     = false,
    hideTorso    = false,
    hideArms     = false,
    hideLegs     = false,
    hideAccessories = false,
    connection   = nil,
}

BodyParts = {
    Head  = {"Head"},
    Torso = {"UpperTorso", "LowerTorso", "HumanoidRootPart"},
    Arms  = {"LeftUpperArm","LeftLowerArm","LeftHand","RightUpperArm","RightLowerArm","RightHand"},
    Legs  = {"LeftUpperLeg","LeftLowerLeg","LeftFoot","RightUpperLeg","RightLowerLeg","RightFoot"},
}

function isAccessory(part)
    local parent = part.Parent
    return parent and (parent:IsA("Accessory") or parent.Name == "HairAttachment"
        or parent.ClassName == "Accessory")
end

function applyBodyParts()
    -- FIX DISAPPEAR BUG: snapshot del char del LocalPlayer para que nunca sea tocado,
    -- aunque _cachedPlayers lo incluya o Character haya sido reasignado temporalmente
    -- (ej: sistema de invisibilidad asigna un clon como LocalPlayer.Character).
    local _safeLocalChar = LocalPlayer and LocalPlayer.Character
    for _, player in ipairs(_cachedPlayers) do
        if player ~= LocalPlayer then
            local char = player.Character
            -- FIX: doble guardia -- no tocar el char del LocalPlayer bajo ninguna condicion
            if char and char ~= _safeLocalChar then
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") or part:IsA("MeshPart") then
                        local hidden = false
                        if BodyPartState.hideHead and table.find(BodyParts.Head, part.Name) then hidden = true end
                        if BodyPartState.hideTorso and table.find(BodyParts.Torso, part.Name) then hidden = true end
                        if BodyPartState.hideArms and table.find(BodyParts.Arms, part.Name) then hidden = true end
                        if BodyPartState.hideLegs and table.find(BodyParts.Legs, part.Name) then hidden = true end
                        if BodyPartState.hideAccessories and isAccessory(part) then hidden = true end
                        part.LocalTransparencyModifier = hidden and 1 or 0
                    end
                end
            end
        end
    end
end

function startBodyPartLoop()
    if BodyPartState.connection then BodyPartState.connection:Disconnect() end
    local anyActive = BodyPartState.hideHead or BodyPartState.hideTorso
        or BodyPartState.hideArms or BodyPartState.hideLegs or BodyPartState.hideAccessories
    if not anyActive then
        for _, player in ipairs(_cachedPlayers) do
            if player ~= LocalPlayer then
                local char = player.Character
                if char then
                    for _, part in ipairs(char:GetDescendants()) do
                        if part:IsA("BasePart") or part:IsA("MeshPart") then
                            part.LocalTransparencyModifier = 0
                        end
                    end
                end
            end
        end
        BodyPartState.connection = nil
        return
    end
    local _bpTick=0
    BodyPartState.connection = RunService.Heartbeat:Connect(function()
        _bpTick=_bpTick+1; if _bpTick<6 then return end; _bpTick=0  -- OPT: 10Hz para body parts
        -- FIX: BodyPartState no tiene campo .enabled; verificar anyActive directamente
        local _anyActive = BodyPartState.hideHead or BodyPartState.hideTorso
            or BodyPartState.hideArms or BodyPartState.hideLegs or BodyPartState.hideAccessories
        if not _anyActive then
            -- FIX INVISIBILITY BUG: antes solo hacia 'return' y los jugadores
            -- quedaban con LocalTransparencyModifier=1 (invisibles) para siempre.
            -- Ahora: restaurar visibilidad de todos y detener el loop.
            if BodyPartState.connection then
                BodyPartState.connection:Disconnect()
                BodyPartState.connection = nil
            end
            for _, _rp in ipairs(_cachedPlayers) do
                if _rp ~= LocalPlayer then
                    local _rc = _rp.Character
                    if _rc then
                        for _, _rpart in ipairs(_rc:GetDescendants()) do
                            if _rpart:IsA("BasePart") or _rpart:IsA("MeshPart") then
                                pcall(function() _rpart.LocalTransparencyModifier = 0 end)
                            end
                        end
                    end
                end
            end
            return
        end
        pcall(applyBodyParts)
    end)
end

instanceLoop = nil --[[empty loop removed]]
-- hookPlayer se define en linea 18033; la llamada correcta esta en linea 18052

-- ==================================================================
-- _vcRefreshAll: fuerza repintado completo de chams/outline/box
-- Limpia la cache de chamHighlight/outHighlight/boxSelect para que
-- el instanceLoop re-aplique todo en el proximo tick (~0.08s)
-- ==================================================================
function _vcRefreshAll()
    -- Limpiar cache de chams
    for player, ref in pairs(chamHighlight or {}) do
        pcall(function()
            if player and player.Character then
                _limpiarPieceChams(player.Character)
            end
            if typeof(ref) == "Instance" and ref:IsA("Highlight") then
                ref:Destroy()
            end
        end)
        chamHighlight[player] = nil
    end
    -- Limpiar cache de outline
    -- FIX: outHighlight[player] guarda el char (Model), NO un Highlight instance.
    -- El outline real son BoxHandleAdornments ("PieceOutline") dentro de cada parte.
    -- Usar _limpiarPieceOutline en lugar de :Destroy() sobre el char.
    for player, char in pairs(outHighlight or {}) do
        pcall(function() if char and char.Parent then _limpiarPieceOutline(char) end end)
        outHighlight[player] = nil
    end
    -- Limpiar cache de box
    for player, sb in pairs(boxSelect or {}) do
        pcall(function() if sb and sb.Parent then sb:Destroy() end end)
        boxSelect[player] = nil
    end
    -- FIX: limpiar tambien ESP boards y highlights de todos los jugadores
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer then
            pcall(removeBoard,     player)
            pcall(removeHighlight, player)
        end
    end
    -- FIX DISAPPEAR BUG: tras limpiar todos los caches de visuals, asegurar que
    -- el LocalPlayer nunca quede con LocalTransparencyModifier=1 (invisible).
    -- Esto ocurria al desactivar cualquier toggle del tab MAIN despues de haber
    -- activado visuals: _vcRefreshAll() se llamaba via doToggle y el personaje
    -- del jugador podia quedar invisible indefinidamente.
    pcall(function()
        local _myChar = LocalPlayer and LocalPlayer.Character
        if _myChar then
            for _, part in ipairs(_myChar:GetDescendants()) do
                if part:IsA("BasePart") and part.LocalTransparencyModifier ~= 0 then
                    part.LocalTransparencyModifier = 0
                end
            end
        end
    end)
    -- Forzar tick inmediato del instanceLoop para re-aplicar
    _G._forceInstanceTick = true
end

do
    local ticker = 0
    -- OPT: Tabla de indices para round-robin de skeleton (no reconstruir cada frame)
    local _skelDirty = {}   -- [player] = true cuando necesita rebuild
    -- FIX VERDE ENTRE RONDAS: exponer _lastRole via _G para que RoundStart
    -- lo limpie al inicio de cada ronda. Sin esto el rol viejo persiste en cache
    -- y el jugador que era Murderer queda pintado de verde en la ronda siguiente.
    _G._lastRoleCache = _G._lastRoleCache or {}
    local _lastRole  = _G._lastRoleCache   -- [player] = role anterior para detectar cambio

    if instanceLoop then instanceLoop:Disconnect() end
    -- OPT: pre-alocar tablas fuera del callback para no crear basura cada tick
    local _tickRoles = {}
    local _tickHum   = {}
    -- FIX REPINTADO INMEDIATO: flag para que RoundStart fuerce el tick sin esperar el intervalo
    _G._forceInstanceTick = _G._forceInstanceTick or false
    instanceLoop = RunService.Heartbeat:Connect(function(dt)
        ticker = ticker + dt
        -- LAG FIX: si no hay ningun visual activo, correr a 2s para no consumir CPU
        local _vs = VisualState
        -- FIX: incluir hero/assassin/zombie/skeleton/tracer en el check de visuals activos
        local _anyVisual = _vs and (
            (_vs.esp    and (_vs.esp.everyone    or _vs.esp.murderer    or _vs.esp.sheriff
                          or _vs.esp.hero        or _vs.esp.assassin    or _vs.esp.zombie
                          or _vs.esp.survivor    or _vs.esp.dead        or _vs.esp.knife
                          or _vs.esp.gun         or _vs.esp.coins       or _vs.esp.distance)) or
            (_vs.cham   and (_vs.cham.everyone   or _vs.cham.murderer   or _vs.cham.sheriff
                          or _vs.cham.hero       or _vs.cham.assassin   or _vs.cham.zombie
                          or _vs.cham.survivor   or _vs.cham.dead       or _vs.cham.knife
                          or _vs.cham.coins)) or
            (_vs.outline and (_vs.outline.everyone or _vs.outline.murderer or _vs.outline.sheriff
                          or _vs.outline.hero    or _vs.outline.assassin or _vs.outline.zombie
                          or _vs.outline.survivor or _vs.outline.dead   or _vs.outline.knife)) or
            (_vs.box    and (_vs.box.everyone    or _vs.box.murderer    or _vs.box.sheriff
                          or _vs.box.hero        or _vs.box.assassin    or _vs.box.zombie
                          or _vs.box.survivor    or _vs.box.dead        or _vs.box.knife)) or
            (_vs.skeleton and (_vs.skeleton.everyone or _vs.skeleton.murderer or _vs.skeleton.sheriff
                          or _vs.skeleton.hero   or _vs.skeleton.assassin or _vs.skeleton.zombie)) or
            (_vs.tracer  and (_vs.tracer.everyone  or _vs.tracer.murderer  or _vs.tracer.sheriff
                          or _vs.tracer.hero     or _vs.tracer.assassin  or _vs.tracer.zombie
                          or _vs.tracer.knife    or _vs.tracer.gun       or _vs.tracer.droppedknife))
        )
        local _timeSinceRS   = os.clock() - (_G._roundStartTime or 0)  -- FIX #3
        local _isEarlyRound  = _timeSinceRS < 12
        -- FIX REPINTADO: intervalo adaptativo
        --   - Sin visuals activos: 2s (LAG FIX -- no hacer nada si no hay nada que pintar)
        --   - Entre rondas / murderer muerto: 1.2s (nada cambia)
        --   - Primeros 12s de ronda: 0.05s (20Hz) para pintar al instante
        --   - Resto de ronda: 0.12s (8Hz) -- balance CPU/reactividad
        local _roundInterval = (not _anyVisual) and 2.0
                            or (_G._visualRoundOver or _G._murdererDied) and 1.2
                            or (_isEarlyRound and 0.08 or 0.15)
        -- _forceInstanceTick: RoundStart pidio tick inmediato
        if _G._forceInstanceTick then
            _G._forceInstanceTick = false
            ticker = 999
        end
        if ticker < _roundInterval then return end
        ticker = 0

        -- limpiar caches del tick sin re-alocar tabla
        for k in next, _tickRoles do _tickRoles[k] = nil end
        for k in next, _tickHum   do _tickHum[k]   = nil end

        -- OPT: cachear roleOf y Humanoid por tick -- evita GetChildren() 4x por jugador por tick
        local function _cachedRoleOf(p)
            if not _tickRoles[p] then _tickRoles[p] = roleOf(p) end
            return _tickRoles[p]
        end
        local function _cachedHum(char)
            if not char then return nil end
            if _tickHum[char] == nil then
                _tickHum[char] = char:FindFirstChildOfClass("Humanoid") or false
            end
            return _tickHum[char] or nil
        end

        local activePlayers = {}
        for _, player in ipairs(_cachedPlayers) do
            if player ~= LocalPlayer then
                activePlayers[player] = true
                local c = player.Character
                if c and c.Parent then
                    -- OPT: detectar cambio de rol para forzar refresh de skeleton
                    -- FIX: NO usar roleOf/GetPlayerRole -- detectan cuchillo y escriben en _roleCache
                    -- causando que se aplique cham del rol en plena ronda sin que el toggle lo pida.
                    -- Usar SOLO el cache del servidor (RoundStart).
                    local curRole
                    if     _roleCache.murderer == player then curRole = "Murderer"
                    elseif _roleCache.sheriff  == player then curRole = "Sheriff"
                    elseif _roleCache.hero     == player then curRole = "Hero"
                    else                                      curRole = "Innocent"
                    end
                    if _lastRole[player] ~= curRole then
                        _lastRole[player] = curRole
                        _skelDirty[player] = true
                        -- FIX REPINTADO: destruir outline/cham viejos inmediatamente
                        pcall(removeOutline, player)
                        pcall(removeCham,    player)
                        -- FIX REPINTADO: limpiar ref al char viejo y re-habilitar deathHook
                        if chamHighlight then chamHighlight[player] = nil end
                        if _G._deathHookDone then _G._deathHookDone[player] = nil end
                    end
                    -- FIX Dead Cham: updateBoard siempre elimina muertos (sin nombre)
                    pcall(updateBoard,   player)
                    -- updateCham maneja DeadOnly internamente (pinta gris si muerto+DeadOnly)
                    pcall(updateCham,    player)
                    pcall(updateOutline, player)
                    pcall(updateHighlight, player)
                    pcall(updateBox,     player)
                    -- Hook Humanoid.Died para limpiar visuals instantaneamente (sin esperar el proximo tick)
                    if not _G._deathHookDone    then _G._deathHookDone    = {} end
                    if not _G._deathHookChar    then _G._deathHookChar    = {} end  -- FIX: rastrear char por player
                    -- FIX RONDA N+1: si el character cambio, invalidar el hook del personaje anterior
                    -- Sin esto: deathHook queda apuntando al Humanoid viejo -> nuevas muertes no se detectan
                    if _G._deathHookDone[player] and _G._deathHookChar[player] ~= c then
                        _G._deathHookDone[player] = nil
                        _G._deathHookChar[player] = nil
                    end
                    if not _G._deathHookDone[player] then
                        _G._deathHookDone[player] = true
                        _G._deathHookChar[player] = c  -- FIX: guardar char actual
                        local hum2 = c:FindFirstChildOfClass("Humanoid")
                        -- FIX RONDAS: token snapshot para ignorar Died de rondas anteriores
                        local _diedRoundToken = _G._sgRoundToken or 0
                        if hum2 then
                            hum2.Died:Connect(function()
                                -- FIX: si ya es otra ronda, no escribir roles viejos
                                if (_G._sgRoundToken or 0) ~= _diedRoundToken then return end
                                removeBox(player)
                                removeBoard(player)
                                removeOutline(player)
                                removeHighlight(player)

                                -- Limpiar el rol del jugador muerto del roleCache
                                if _roleCache.murderer == player then
                                    _roleCache.murderer = nil
                                    _roleCache.lastUpdate = 0
                                elseif _roleCache.sheriff == player then
                                    _roleCache.sheriff = nil
                                    _roleCache.lastUpdate = 0
                                elseif _roleCache.hero == player then
                                    _roleCache.hero = nil
                                    _roleCache.lastUpdate = 0
                                end

                                _G._deathHookDone[player] = nil
                                if _G._deathHookChar then _G._deathHookChar[player] = nil end

                                -- Pintar VERDE al morir (rol limpiado = inocente)
                                local _vcdDead = VisualState and VisualState.cham
                                local chamActive = _vcdDead and (
                                    _vcdDead.everyone or _vcdDead.murderer or _vcdDead.sheriff
                                    or _vcdDead.hero or _vcdDead.survivor or _vcdDead.dead
                                )
                                if chamActive then
                                    local dc = player.Character
                                    if dc then
                                        local GREEN_COL = Color3.fromRGB(  0, 255, 160)
                                        pcall(function() _aplicarPieceChams(dc, GREEN_COL) end)
                                        chamHighlight[player] = dc
                                    end
                                else
                                    removeCham(player)
                                end
                            end)
                        end
                    end
                    -- CAMBIO 2: hook instantaneo cuando un inocente agarra la gun (GunDrop).
                    -- ChildAdded en el Character detecta Tool nuevo -> si es gun y el
                    -- jugador no es Murderer -> promoverlo a nuevo Sheriff (azul) o Hero (amarillo).
                    if not _G._gunHookDone then _G._gunHookDone = {} end
                    if not _G._gunHookDone[player] then
                        _G._gunHookDone[player] = true
                        c.ChildAdded:Connect(function(tool)
                            if not tool:IsA("Tool") then return end
                            local n = tool.Name:lower()
                            local isGun = (_GUN_NAMES and _GUN_NAMES[tool.Name])
                                       or n:find("gun") or n:find("revolver")
                                       or n:find("pistol") or n:find("sheriff")
                                       or n:find("weapon")
                            if not isGun then return end
                            -- Ignorar si es el murderer
                            if _roleCache.murderer == player then return end
                            -- Si ya es sheriff o hero conocido, no reprocesar
                            if _roleCache.sheriff == player or _roleCache.hero == player then return end

                            -- Cualquier cham activo alcanza para pintar
                            local _vcdG = VisualState and VisualState.cham
                            local chamG = _vcdG and (
                                _vcdG.everyone or _vcdG.sheriff or _vcdG.hero
                                or _vcdG.survivor or _vcdG.assassin
                            )
                            if not chamG then return end

                            local pc = player.Character
                            if not pc then return end

                            -- Promover a nuevo Sheriff en roleCache y pintar AMARILLO
                            _roleCache.sheriff    = player
                            _roleCache.lastUpdate = 0
                            if player == LocalPlayer then
                                _roleCache.localRole = "Sheriff"
                            end

                            local YELLOW = Color3.fromRGB(255, 210, 0)
                            if _hl_remove then pcall(_hl_remove, pc) end
                            pcall(function() _aplicarPieceChams(pc, YELLOW) end)
                            chamHighlight[player] = pc

                            -- Hook muerte del nuevo sheriff via KnifeKill (ya est? en el listener global)
                            -- Actualizar SheriffDeadBlock para compatibilidad
                            if SheriffDeadBlock then
                                SheriffDeadBlock.isDeadSheriffID = player.UserId
                                SheriffDeadBlock.deadSheriffName = player.Name
                            end

                            -- Cuando suelte la gun, volver a verde (inocente)
                            tool.AncestryChanged:Connect(function()
                                if tool.Parent == player.Character then return end
                                local pc2 = player.Character
                                if not pc2 then return end
                                local ph = pc2:FindFirstChildOfClass("Humanoid")
                                if not ph or ph.Health <= 0 then return end
                                -- Solo limpiar si sigue siendo el sheriff que registramos
                                if _roleCache.sheriff ~= player then return end
                                _roleCache.sheriff    = nil
                                _roleCache.lastUpdate = 0
                                if player == LocalPlayer then
                                    _roleCache.localRole = "Innocent"
                                end
                                local _vcdG2 = VisualState and VisualState.cham
                                local chamG2 = _vcdG2 and (
                                    _vcdG2.everyone or _vcdG2.sheriff or _vcdG2.hero
                                    or _vcdG2.survivor or _vcdG2.assassin
                                )
                                if not chamG2 then return end
                                local GREEN2 = Color3.fromRGB(0, 255, 160)
                                if _hl_remove then pcall(_hl_remove, pc2) end
                                pcall(function() _aplicarPieceChams(pc2, GREEN2) end)
                                chamHighlight[player] = pc2
                            end)
                        end)
                        -- Limpiar el hook cuando el jugador respawnee
                        c.AncestryChanged:Connect(function()
                            if not c.Parent then
                                _G._gunHookDone[player] = nil
                            end
                        end)
                    end
                end
            end
        end

        -- Limpiar ESP de jugadores que salieron
        for player in pairs(espBoards)    do if not activePlayers[player] then removeBoard(player);    _lastRole[player] = nil end end
        for player in pairs(chamHighlight) do if not activePlayers[player] then removeCham(player)    end end
        for player in pairs(outHighlight)  do if not activePlayers[player] then removeOutline(player) end end
        for player in pairs(boxSelect)     do if not activePlayers[player] then removeBox(player)     end end
        for player in pairs(hlObjects)     do if not activePlayers[player] then removeHighlight(player)  end end
        for player in pairs(skelParts)     do if not activePlayers[player] then removeSkeleton(player); _lastRole[player] = nil end end

        for _, player in ipairs(_cachedPlayers) do
            if player ~= LocalPlayer then
                local anySkelly = vsShow(VisualState.skeleton, (GetPlayerRole and GetPlayerRole(player)) or roleOf(player) or "Innocent", player)
                if anySkelly and player.Character then
                    if not skelParts[player] then
                        -- No existe aun: construir
                        pcall(buildSkeleton, player)
                        _skelDirty[player] = false
                    elseif _skelDirty[player] then
                        -- Solo reconstruir si el rol cambio (dirty flag)
                        pcall(buildSkeleton, player)
                        _skelDirty[player] = false
                    end
                    -- Si ya existe y no dirty: NO hacer nada (beams se actualizan solos)
                elseif not anySkelly and skelParts[player] then
                    removeSkeleton(player)
                end
            end
        end

        if VisualState.coins.esp then
            for obj, bb in pairs(ESPBoards.coin) do
                if not obj or not obj.Parent then
                    pcall(function() bb:Destroy() end)
                    ESPBoards.coin[obj] = nil
                end
            end
            for obj in pairs(_coinWorldCache) do
                if obj.Parent and not ESPBoards.coin[obj] then
                    pcall(makeCoinBoard, obj)
                end
            end
        else
            clearCoinsESP()
        end

    end)
end

_hbTtracer = 0
_tracerViewCenter = Vector2.new(0, 0)  -- se actualiza al primer tick con ViewportSize real
_tracerViewTick = 30  -- forzar recalculo en el primer frame (Y=0 = arriba de pantalla)
_G._tracerFromHead = true  -- tracer siempre apunta a la cabeza
-- GUARD: desconectar conexion anterior si existe (evita duplicados al re-ejecutar)
if _G._tracerHBConn then pcall(function() _G._tracerHBConn:Disconnect() end) end
_G._tracerHBConn = RunService.Heartbeat:Connect(function()
    -- FIX LAG: guard ANTES del ticker ? si no hay tracers activos no incrementar ni entrar
    local vt = VisualState.tracer
    local anyTracer = vt.everyone or vt.murderer or vt.sheriff or vt.hero
        or vt.assassin or vt.dead or vt.survivor or vt.zombie
        or vt.knife or vt.droppedknife or vt.throwknife
    if not anyTracer then return end  -- sin resetLinePool: no hay lineas que limpiar si no hay tracers
    _hbTtracer=_hbTtracer+1; if _hbTtracer<36 then return end; _hbTtracer=0

    resetLinePool()

    local cam = workspace.CurrentCamera
    -- OPT: recalcular viewport center solo cada 30 ticks (~cada 4s) -- ViewportSize no cambia seguido
    _tracerViewTick = _tracerViewTick + 1
    if _tracerViewTick >= 30 then
        _tracerViewTick = 0
        -- TRACER ORIGIN: parte superior de la pantalla (Y = 0 = arriba del todo)
        _tracerViewCenter = Vector2.new(cam.ViewportSize.X / 2, 0)
    end
    local center = _tracerViewCenter

    for _, player in ipairs(_cachedPlayers) do
        if player ~= LocalPlayer and player.Character then
            local hrp = player.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                -- OPT: usar GetPlayerRole O(1) en lugar de roleOf con GetChildren()
                local _pr = GetPlayerRole(player)
                local role = (_pr ~= "" and _pr ~= "Grey") and _pr or "Innocent"
                if roleOf ~= nil and (VisualState.tracer.gunholder or false) then role = roleOf(player) end
                if vsShow(vt, role, player) then
                    local color = colorOf(role)
                    -- TRACER TARGET: siempre apunta a la Head del jugador (no al HRP)
                    -- _tracerFromHead ya no cambia el target; siempre es la cabeza
                    local _head = player.Character:FindFirstChild("Head")
                    local _tPart = _head or hrp
                    local sp, onScreen = cam:WorldToViewportPoint(_tPart.Position)
                    if onScreen then
                        local line = getLine()
                        line.From = center; line.To = Vector2.new(sp.X, sp.Y)
                        line.Color = color; line.Thickness = 2.5
                        line.Transparency = 1; line.Visible = true
                    end
                end
            end
        end
    end


    if vt.droppedknife then
        for obj in pairs(_knifeWorldCache) do
            if obj.Parent then
                local handle = obj:FindFirstChild("Handle")
                    or obj:FindFirstChildOfClass("BasePart")
                if handle then
                    local sp, onScreen = cam:WorldToViewportPoint(handle.Position)
                    if onScreen then
                        local line = getLine()
                        line.From = center; line.To = Vector2.new(sp.X, sp.Y)
                        line.Color = Color3.fromRGB(58, 58, 58)
                        line.Thickness = 2.2; line.Transparency = 1; line.Visible = true
                    end
                end
            end
        end
    end

    -- TRACER THROWINGKNIFE: draws a line to the flying ThrowingKnife in workspace
    if vt.throwknife then
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "ThrowingKnife" and obj:IsA("Model") then
                local kv = obj:FindFirstChild("KnifeVisual")
                local part = (kv and kv:IsA("BasePart") and kv.Transparency < 0.95 and kv)
                    or obj:FindFirstChildOfClass("BasePart")
                if part then
                    local sp, onScreen = cam:WorldToViewportPoint(part.Position)
                    if onScreen then
                        local line = getLine()
                        line.From = center; line.To = Vector2.new(sp.X, sp.Y)
                        line.Color = Color3.fromRGB(255, 60, 0)
                        line.Thickness = 2.5; line.Transparency = 1; line.Visible = true
                    end
                end
            end
        end
    end
end)

-- FIX PARTICULAS RESIDUALES: limpia todos los efectos visuales del char viejo
-- (PieceChams, ParticleEmitters, Trails, Beams, Highlights) al respawnear
local function _limpiarCharViejo(oldChar)
    if not oldChar then return end
    pcall(function()
        -- 1. PieceChams (BoxHandleAdornment)
        _limpiarPieceChams(oldChar)
        -- 2. Highlights propios del hub (ChamESP, OutlineHighlight, etc.)
        for _, obj in ipairs(oldChar:GetDescendants()) do
            if obj:IsA("Highlight") or obj:IsA("SelectionBox") then
                pcall(function() obj:Destroy() end)
            end
        end
        -- 3. Particulas/Trails/Beams residuales -- desactivarlos en vez de destruirlos
        -- (destruirlos puede causar errores si Roblox ya esta limpiando el char)
        for _, obj in ipairs(oldChar:GetDescendants()) do
            if obj:IsA("ParticleEmitter") or obj:IsA("Trail")
            or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
                pcall(function() obj.Enabled = false end)
            end
            if obj:IsA("Beam") then
                pcall(function() obj.Enabled = false end)
            end
        end
    end)
end

function hookPlayer(player)
    if player == LocalPlayer then return end
    player.CharacterAdded:Connect(function(char)
        -- FIX PARTICULAS RESIDUALES: capturar char viejo ANTES de que removeCham lo limpie
        -- para poder desactivar sus particulas/effects explicitamente
        local oldChar = chamHighlight and chamHighlight[player]
        if oldChar and typeof(oldChar) == "Instance" and oldChar:IsA("Model") and oldChar ~= char then
            task.defer(function() _limpiarCharViejo(oldChar) end)
        end
        -- Tambien limpiar el personaje actual de player.Character si es distinto al nuevo char
        if player.Character and player.Character ~= char then
            task.defer(function() _limpiarCharViejo(player.Character) end)
        end
        -- FIX: limpiar ESP viejo inmediatamente al respawn
        removeBoard(player); removeCham(player); removeOutline(player); removeBox(player)
        -- FIX: tambien limpiar PieceChams del char NUEVO que puedan haberse aplicado
        -- antes de que este listo (el instanceLoop corre cada 0.08s)
        _limpiarPieceChams(char)
        task.wait(0.9)  -- esperar que el personaje cargue completamente
        clearDeathPose(player)
        removeSkeleton(player)
        local anySkelly = vsShow(VisualState.skeleton, (GetPlayerRole and GetPlayerRole(player)) or roleOf(player) or "Innocent", player)
        if anySkelly then pcall(buildSkeleton, player) end
        -- instanceLoop se encarga de re-crear board/cham/outline/box en el proximo tick
    end)
    player.AncestryChanged:Connect(function()
        if not player.Parent then
            removeBoard(player); removeCham(player); removeOutline(player)
            removeBox(player);   removeSkeleton(player); clearDeathPose(player)
        end
    end)
end
for _, p in ipairs(_cachedPlayers) do hookPlayer(p) end
Players.PlayerAdded:Connect(hookPlayer)


function CreateVisualCard(parent, icon, title, accentColor)
    local card = Instance.new("Frame", parent)
    card.Name               = "Card_" .. title
    card.Size               = UDim2.new(1, -4, 0, 0)
    card.AutomaticSize      = Enum.AutomaticSize.Y
    card.BackgroundTransparency = 1
    card.BorderSizePixel    = 0

    local header = Instance.new("Frame", card)
    header.Name             = "Header"
    header.Size             = UDim2.new(1, 0, 0, 22)
    header.BackgroundTransparency = 1
    header.BorderSizePixel  = 0

    local titleLbl = Instance.new("TextLabel", header)
    titleLbl.Size              = UDim2.new(1,-10,1,0)
    titleLbl.Position          = UDim2.new(0,4,0,0)
    titleLbl.BackgroundTransparency = 1
    titleLbl.Text              = title
    titleLbl.TextSize          = 11
    titleLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    titleLbl.TextColor3        = ThemeColors.TextPrimary
    titleLbl.TextXAlignment    = Enum.TextXAlignment.Left

    local function AddSubLabel(parent, text)
        local lbl = Instance.new("TextLabel", parent)
        lbl.Size               = UDim2.new(1,-16,0,22)
        lbl.BackgroundTransparency = 1
        lbl.Text               = text
        lbl.TextSize           = 11
        lbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
        lbl.TextColor3         = accentColor
        lbl.TextXAlignment     = Enum.TextXAlignment.Left
        local pad = Instance.new("UIPadding", lbl)
        pad.PaddingLeft = UDim.new(0, 10)
    end

    local inner = Instance.new("Frame", card)
    inner.Name              = "Inner"
    inner.Size              = UDim2.new(1, 0, 0, 0)
    inner.AutomaticSize     = Enum.AutomaticSize.Y
    inner.Position          = UDim2.new(0, 0, 0, 22)
    inner.BackgroundTransparency = 1
    inner.BorderSizePixel   = 0
    local layout = Instance.new("UIListLayout", inner)
    layout.Padding      = UDim.new(0, 2)
    layout.SortOrder    = Enum.SortOrder.LayoutOrder
    local pad = Instance.new("UIPadding", inner)
    pad.PaddingBottom = UDim.new(0, 6)
    pad.PaddingLeft   = UDim.new(0, 4)
    pad.PaddingRight  = UDim.new(0, 4)

    return inner, AddSubLabel
end

function CreateVisualsTab()
    -- FIX: asegurar que contentContainer existe antes de construir el tab
    if not contentContainer or not contentContainer.Parent then
        warn("[dex] CreateVisualsTab: contentContainer no listo, reintentando...")
        _w(0.15)
        if not contentContainer or not contentContainer.Parent then return end
    end
    -- FIX MOBILE: resetear _currentMainSectionFrame para que CreateAuroraToggle
    -- use el parent correcto (inner del card) y no el frame del tab anterior.
    -- CreateSection/CreateNeonSection lo setean pero nunca lo limpian, causando
    -- que los toggles de Visuals se creen dentro de frames ocultos en movil.
    _currentMainSectionFrame = nil
    -- OPT: con cache de tabs, ClearContent() ya NO se llama aqui (el tab se construye una sola vez)
    -- Solo limpiar conexiones que el tab propio pudo haber creado en ejecuciones anteriores
    -- (trackerConn/_radarConn son conexiones del radar local, NO del instanceLoop global)
    _makeTwoColumns()
    -- FIX VISUALS SCROLL: forzar que el scroll este habilitado al entrar a Visuals
    if leftColumn then
        pcall(function()
            leftColumn.ScrollingEnabled = true
            leftColumn.AutomaticCanvasSize = Enum.AutomaticSize.Y
            leftColumn.CanvasSize = UDim2.new(0, 0, 0, 0)
            leftColumn.CanvasPosition = Vector2.new(0, 0)
        end)
    end

    _G.ESPState = _G.ESPState or {
        enabled = {},
        objects = {},
        connections = {}
    }
    local ESPState = _G.ESPState

    local function MiniHeader(parent, text, color)
        -- Separadores eliminados: opciones van juntas sin texto entre ellas
    end

    -- -- makeESPPlayerPin ------------------------------------------------
    -- Crea un selector de jugador para "pinear" un jugador especifico en un ESP.
    -- flags.pinPlayer = Player | nil  (nil = sin pin, aplica filtros normales)
    local function makeESPPlayerPin(parent, flags, accentColor)
        local PIN_COLOR = accentColor or Color3.fromRGB( 50, 255, 180)
        MiniHeader(parent, "PINEAR JUGADOR ESPECIFICO", PIN_COLOR)

        -- Contenedor del selector
        local pinRow = Instance.new("Frame", parent)
        pinRow.Name = "PinPlayerRow"
        pinRow.Size = UDim2.new(1, 0, 0, 32)
        pinRow.BackgroundTransparency = 1
        pinRow.BorderSizePixel = 0

        local layout = Instance.new("UIListLayout", pinRow)
        layout.FillDirection = Enum.FillDirection.Horizontal
        layout.Padding = UDim.new(0, 4)
        layout.VerticalAlignment = Enum.VerticalAlignment.Center

        -- Label con nombre del jugador pineado
        local pinLbl = Instance.new("TextLabel", pinRow)
        pinLbl.Size = UDim2.new(1, -70, 1, 0)
        pinLbl.BackgroundColor3 = Color3.fromRGB(20, 20, 26)
        pinLbl.BackgroundTransparency = 0.4
        pinLbl.BorderSizePixel = 0
        pinLbl.Text = "  Ninguno (todos)"
        pinLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        pinLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        pinLbl.TextSize = 11
        pinLbl.TextXAlignment = Enum.TextXAlignment.Left
        pinLbl.TextTruncate = Enum.TextTruncate.AtEnd
        pinLbl.ZIndex = 13
        Instance.new("UICorner", pinLbl).CornerRadius = UDim.new(0, 6)
        local pinStroke = Instance.new("UIStroke", pinLbl)
        pinStroke.Color = PIN_COLOR; pinStroke.Thickness = 1; pinStroke.Transparency = 0.6

        -- Boton X para quitar el pin
        local clearBtn = Instance.new("TextButton", pinRow)
        clearBtn.Size = UDim2.new(0, 30, 1, 0)
        clearBtn.BackgroundColor3 = Color3.fromRGB(180, 40, 40)
        clearBtn.BackgroundTransparency = 0.5
        clearBtn.BorderSizePixel = 0
        clearBtn.Text = "X"
        clearBtn.TextColor3 = Color3.fromRGB(255, 120, 120)
        clearBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        clearBtn.TextSize = 12
        clearBtn.AutoButtonColor = false
        clearBtn.ZIndex = 13
        Instance.new("UICorner", clearBtn).CornerRadius = UDim.new(0, 6)

        clearBtn.Activated:Connect(function()
            flags.pinPlayer = nil
            pinLbl.Text = "  Ninguno (todos)"
            pinLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            pinStroke.Transparency = 0.6
            if _vcRefreshAll then _vcRefreshAll() end
            CreateCustomNotification("ESP PIN", "Pin eliminado -- filtros normales", 2)
        end)

        -- Lista de jugadores expandible
        local listFrame = Instance.new("Frame", parent)
        listFrame.Name = "PinPlayerList"
        listFrame.Size = UDim2.new(1, 0, 0, 0)
        listFrame.BackgroundTransparency = 1
        listFrame.BorderSizePixel = 0
        listFrame.ClipsDescendants = true

        local listLayout = Instance.new("UIListLayout", listFrame)
        listLayout.Padding = UDim.new(0, 2)
        listLayout.SortOrder = Enum.SortOrder.LayoutOrder

        -- Boton abrir/cerrar lista
        local toggleListBtn = Instance.new("TextButton", parent)
        toggleListBtn.Size = UDim2.new(1, 0, 0, 26)
        toggleListBtn.BackgroundColor3 = PIN_COLOR
        toggleListBtn.BackgroundTransparency = 0.75
        toggleListBtn.BorderSizePixel = 0
        toggleListBtn.Text = "v  Seleccionar jugador"
        toggleListBtn.TextColor3 = PIN_COLOR
        toggleListBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        toggleListBtn.TextSize = 11
        toggleListBtn.AutoButtonColor = false
        toggleListBtn.ZIndex = 13
        Instance.new("UICorner", toggleListBtn).CornerRadius = UDim.new(0, 6)
        local tlStroke = Instance.new("UIStroke", toggleListBtn)
        tlStroke.Color = PIN_COLOR; tlStroke.Thickness = 1; tlStroke.Transparency = 0.4

        local listOpen = false
        local function _rebuildList()
            -- Limpiar lista anterior
            for _, ch in ipairs(listFrame:GetChildren()) do
                if ch:IsA("TextButton") then ch:Destroy() end
            end
            local plrs = {}
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer then table.insert(plrs, p) end
            end
            if #plrs == 0 then
                local empty = Instance.new("TextButton", listFrame)
                empty.Size = UDim2.new(1, 0, 0, 26)
                empty.BackgroundTransparency = 1
                empty.Text = "  (sin jugadores en el servidor)"
                empty.TextColor3 = Color3.fromRGB(140, 140, 140)
                empty.FontFace = Font.fromEnum(Enum.Font.Montserrat)
                empty.TextSize = 10
                empty.BorderSizePixel = 0
                empty.ZIndex = 14
            end
            for _, p in ipairs(plrs) do
                local btn = Instance.new("TextButton", listFrame)
                btn.Size = UDim2.new(1, 0, 0, 28)
                btn.BorderSizePixel = 0
                btn.Text = "  " .. p.Name
                btn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
                btn.TextSize = 11
                btn.TextXAlignment = Enum.TextXAlignment.Left
                btn.AutoButtonColor = false
                btn.ZIndex = 14
                Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)
                -- Color segun si es el pineado actual
                local isPinned = flags.pinPlayer == p
                btn.BackgroundColor3 = isPinned and PIN_COLOR or Color3.fromRGB(25, 25, 32)
                btn.BackgroundTransparency = isPinned and 0.3 or 0.5
                btn.TextColor3 = isPinned and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(210, 210, 210)
                local bStroke = Instance.new("UIStroke", btn)
                bStroke.Color = PIN_COLOR; bStroke.Thickness = 1
                bStroke.Transparency = isPinned and 0.0 or 0.7

                btn.Activated:Connect(function()
                    flags.pinPlayer = p
                    pinLbl.Text = "  * " .. p.Name
                    pinLbl.TextColor3 = PIN_COLOR
                    pinStroke.Transparency = 0.0
                    if _vcRefreshAll then _vcRefreshAll() end
                    CreateCustomNotification("ESP PIN", "Pineado: " .. p.Name, 3)
                    -- Cerrar lista y reconstruir para actualizar colores
                    listOpen = false
                    toggleListBtn.Text = "v  Seleccionar jugador"
                    TweenService:Create(listFrame, TweenInfo.new(0.15), {Size = UDim2.new(1, 0, 0, 0)}):Play()
                    _w(0.16)
                    _rebuildList()
                end)
            end
            -- Actualizar altura de la lista
            local totalH = listLayout.AbsoluteContentSize.Y
            if listOpen then
                TweenService:Create(listFrame, TweenInfo.new(0.15), {Size = UDim2.new(1, 0, 0, totalH)}):Play()
            end
        end

        toggleListBtn.Activated:Connect(function()
            listOpen = not listOpen
            if listOpen then
                _rebuildList()
                toggleListBtn.Text = "^  Cerrar lista"
                _w(0.01)
                local totalH = listLayout.AbsoluteContentSize.Y
                TweenService:Create(listFrame, TweenInfo.new(0.18), {Size = UDim2.new(1, 0, 0, totalH)}):Play()
            else
                toggleListBtn.Text = "v  Seleccionar jugador"
                TweenService:Create(listFrame, TweenInfo.new(0.15), {Size = UDim2.new(1, 0, 0, 0)}):Play()
            end
        end)

        -- Hover
        toggleListBtn.MouseEnter:Connect(function()
            TweenService:Create(toggleListBtn, TweenInfo.new(0.10), {BackgroundTransparency = 0.35}):Play()
        end)
        toggleListBtn.MouseLeave:Connect(function()
            TweenService:Create(toggleListBtn, TweenInfo.new(0.12), {BackgroundTransparency = 0.20}):Play()
        end)
    end


    do
        local inner = CreateVisualCard(leftColumn, "", "CHAM", ThemeColors.Aurora1)
        local vc = VisualState.cham
        MiniHeader(inner, "EVERYONE", Color3.fromRGB(255,255,255))
        CreateAuroraToggle(inner, "Cham Everyone", function(v) vc.everyone=v end, vc.everyone)
        MiniHeader(inner, "MURDERER", Color3.fromRGB(255,100,100))
        CreateAuroraToggle(inner, "Cham Murderer Only", function(v) vc.murderer=v end, vc.murderer)
        MiniHeader(inner, "SHERIFF", Color3.fromRGB(255, 181, 51))
        CreateAuroraToggle(inner, "Cham Sheriff Only", function(v) vc.sheriff=v end, vc.sheriff)
        MiniHeader(inner, "HERO", Color3.fromRGB(255, 181, 51))
        CreateAuroraToggle(inner, "Cham Hero Only", function(v) vc.hero=v end, vc.hero)
        MiniHeader(inner, "ASSASSIN", Color3.fromRGB(255, 210,   0))
        CreateAuroraToggle(inner, "Cham Assassin Only", function(v) vc.assassin=v end, vc.assassin)
        MiniHeader(inner, "DEAD", Color3.fromRGB(255,120,120))
 -- Cham Dead Only: muestra pose de muerte del jugador, dura TODA la ronda
 CreateAuroraToggle(inner, "Cham Dead Only", function(v)
            VisualState.cham.dead = v
            DeathPoseState.enabled = v  -- vincular dead pose al mismo toggle
            if v and _vcRefreshAll then _vcRefreshAll() end
            if v then
                -- Hookear todos los jugadores actuales
                for _, p in pairs(Players:GetPlayers()) do
                    if p ~= Players.LocalPlayer then
                        -- Si ya esta muerto, aplicar adornos ahora
                        if p.Character then
                            local hum = p.Character:FindFirstChildOfClass("Humanoid")
                            if hum and hum.Health <= 0 then
                                _sp(function()
                                    pcall(_applyDeathPoseAdornments, p, p.Character)
                                end)
                            end
                        end
                    end
                end
                CreateCustomNotification("VISUALS", "Cham Dead ON -- dura toda la ronda", 2)
            else
                -- Toggle OFF: limpiar TODO (ESP, clones, highlights, _DeathPoseESP)
                if type(_clearAllDeadCham) == "function" then pcall(_clearAllDeadCham) end
                _deadBodies = {}
                CreateCustomNotification("VISUALS", "Cham Dead OFF", 1)
            end
        end, VisualState.cham.dead or false)
        MiniHeader(inner, " SURVIVOR",        Color3.fromRGB(255,255,255))
 CreateAuroraToggle(inner, "Cham Survivor Only", function(v) vc.survivor=v end, vc.survivor)
        MiniHeader(inner, " COINS",           Color3.fromRGB(255, 215, 0))
 CreateAuroraToggle(inner, "Cham Coins", function(v)
            vc.coins = v
            _G._chamCoins = v
            -- Limpiar chams anteriores
            for _, obj in ipairs(workspace:GetDescendants()) do
                pcall(function()
                    local hl = obj:FindFirstChild("_ChamCoinHL")
                    if hl then hl:Destroy() end
                end)
            end
            if v then
                local function _addCoinCham(obj)
                    if not obj or not obj.Parent then return end
                    if obj:FindFirstChild("_ChamCoinHL") then return end
                    -- Usar _farmCoinNameMatches para los mismos nombres que usa el farm
                    if not obj:IsA("BasePart") then return end
                    if not (_farmCoinNameMatches and _farmCoinNameMatches(obj.Name)) then
                        local n = obj.Name:lower()
                        if not (n == "coin" or n == "maincoin" or n:find("coin")) then return end
                    end
                    if obj.Transparency >= 0.9 then return end
                    local hl = Instance.new("Highlight")
                    hl.Name = "_ChamCoinHL"
                    hl.FillColor = Color3.fromRGB(255, 215, 0)
                    hl.OutlineColor = Color3.fromRGB(255, 255, 80)
                    hl.OutlineTransparency = 0
                    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                    hl.Adornee = obj; hl.Parent = obj
                    hl.FillTransparency = 0.35
                    obj.AncestryChanged:Connect(function()
                        if not obj.Parent then pcall(function() hl:Destroy() end) end
                    end)
                end
                -- Prioridad: usar _farmCoinSet (cache ya llenado por el sistema de farm)
                if _farmCoinSet and next(_farmCoinSet) then
                    for coin in pairs(_farmCoinSet) do pcall(_addCoinCham, coin) end
                else
                    for _, obj in ipairs(workspace:GetDescendants()) do pcall(_addCoinCham, obj) end
                end
                if _G._chamCoinConn then pcall(function() _G._chamCoinConn:Disconnect() end) end
                _G._chamCoinConn = workspace.DescendantAdded:Connect(function(obj)
                    if _G._chamCoins then pcall(_addCoinCham, obj) end
                end)
            else
                if _G._chamCoinConn then _G._chamCoinConn:Disconnect(); _G._chamCoinConn = nil end
            end
        end, vc.coins)

        MiniHeader(inner, "GUN DROP", Color3.fromRGB(50, 60, 150))
        CreateAuroraToggle(inner, "Cham Gun (GunDrop)", function(v)
    _G._chamDropGun = v
    -- Limpiar chams anteriores al apagar
    if not v then
        for _, obj in ipairs(workspace:GetDescendants()) do
            pcall(function()
                local hl = obj:FindFirstChild("GunCham")
                if hl then hl:Destroy() end
            end)
        end
        if _G._chamDropGunConn then
            pcall(function() _G._chamDropGunConn:Disconnect() end)
            _G._chamDropGunConn = nil
        end
        if _G._chamDropGunRS then
            pcall(function() _G._chamDropGunRS:Disconnect() end)
            _G._chamDropGunRS = nil
        end
        return
    end

    local _GN = {GunDrop=true, DropGun=true, Gun=true, SheriffGun=true, HeroGun=true}

    -- FIX: Cham Gun usa BoxHandleAdornment (igual ruta que ESP Dropped Gun)
    -- en vez de Highlight -- mismo sistema que _applyESPGun pero es "cham" no "esp"
    local function _chamGunFn(obj)
        if not obj or not obj.Parent then return end
        -- Aceptar cualquier gun suelta (misma ruta que _applyESPGun)
        local n = obj.Name
        if not (n == "GunDrop" or n == "DropGun" or n == "Gun"
            or n == "SheriffGun" or n == "HeroGun"
            or (obj:IsA("Tool") and n:lower():find("gun"))) then return end
        -- No aplicar a guns equipadas
        if obj.Parent and obj.Parent:FindFirstChildOfClass("Humanoid") then return end
        if obj.Parent and obj.Parent:IsA("Backpack") then return end

        -- Highlight en la gun completa (BoxHandleAdornment no funciona en exploits)
        if not obj:FindFirstChild("GunCham") then
            pcall(function()
                local hl = Instance.new("Highlight")
                hl.Name                = "GunCham"
                hl.FillColor           = (_G._vsColors and _G._vsColors.cham) or Color3.fromRGB(90, 90, 95)
                hl.OutlineColor        = Color3.fromRGB(255, 255, 255)
                hl.OutlineTransparency = 0.2
                hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                hl.Adornee             = obj
                hl.Parent              = obj
                hl.FillTransparency    = 0.3
            end)
        end
        -- Apagar particulas y luces
        for _, d in ipairs(obj:GetDescendants()) do
            if d:IsA("ParticleEmitter") or d:IsA("PointLight") then
                pcall(function() d.Enabled = false end)
            end
        end

        -- Auto-limpiar cuando el arma desaparece
        local conn
        conn = obj.AncestryChanged:Connect(function()
            if not obj.Parent then
                pcall(function()
                    local hl = obj:FindFirstChild("GunCham")
                    if hl then hl:Destroy() end
                end)
                if conn then conn:Disconnect() end
            end
        end)
    end

    -- Aplicar a todas las armas existentes en el mapa
    for _, obj in ipairs(workspace:GetDescendants()) do
        pcall(_chamGunFn, obj)
    end

    -- Escuchar nuevas armas que aparezcan
    _G._chamDropGunConn = workspace.DescendantAdded:Connect(function(obj)
        if _G._chamDropGun then
            _sp(function() pcall(_chamGunFn, obj) end)
        end
    end)

    -- Respaldo por si el arma cambia de parent (ej: de mochila al suelo)
    local _cgdT = 0
    local _cdgTick=0
    _G._chamDropGunRS = RunService.Heartbeat:Connect(function(dt)
        _cdgTick=_cdgTick+1; if _cdgTick<3 then return end; _cdgTick=0  -- OPT: 20Hz para cham drop gun
        if not _G._chamDropGun then return end
        _cgdT = _cgdT + dt; if _cgdT < 0.2 then return end; _cgdT = 0
        if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda
        local gun = workspace:FindFirstChild("GunDrop",    true)
                 or workspace:FindFirstChild("DropGun",    true)
                 or workspace:FindFirstChild("SheriffGun", true)
        if gun then pcall(_chamGunFn, gun) end
    end)
end, _G._chamDropGun or false)

