            -- Aplica BoxHandleAdornment (UltraCham) + BillboardGui en la gun
            -- Busqueda recursiva con FindFirstChild(..., true) -- funciona en BioLab, Hotel, etc.
            -- Usa Highlight (igual que _applyHlGun) -- BoxHandleAdornment no funciona en exploits
            local function _applyESPGun(gun)
                if not gun or not gun.Parent then return end
                local n = gun.Name
                if not (n == "GunDrop" or n == "DropGun" or n == "Gun"
                    or n == "SheriffGun" or n == "HeroGun") then return end
                if gun.Parent and gun.Parent:FindFirstChildOfClass("Humanoid") then return end
                if gun.Parent and gun.Parent:IsA("Backpack") then return end

                -- Highlight con relleno semitransparente + contorno blanco (igual que _applyHlGun)
                if not gun:FindFirstChild("GunESPHL") then
                    pcall(function()
                        local hl = Instance.new("Highlight")
                        hl.Name                = "GunESPHL"
                        hl.FillColor           = (_G._vsColors and _G._vsColors.esp) or Color3.fromRGB(231, 135, 30)
                        hl.OutlineColor        = Color3.fromRGB(255, 255, 255)
                        hl.OutlineTransparency = 0
                        hl.DepthMode           = Enum.HighlightDepthMode.AlwaysOnTop
                        hl.Adornee             = gun
                        hl.Parent              = gun
                        hl.FillTransparency    = 0.5
                    end)
                end

                -- Apagar particulas y luces
                for _, d in ipairs(gun:GetDescendants()) do
                    if d:IsA("ParticleEmitter") or d:IsA("PointLight") then
                        pcall(function() d.Enabled = false end)
                    end
                end

                -- Billboard "[ GUN DROP ]" flotante
                if not gun:FindFirstChild("GunText") then
                    pcall(function()
                        local bGui = Instance.new("BillboardGui", gun)
                        bGui.Name        = "GunText"
                        bGui.Size        = UDim2.new(0, 200, 0, 50)
                        bGui.AlwaysOnTop = true
