        MiniHeader(inner, "BY OBJECT", Color3.fromRGB(255,220,100))
        CreateAuroraToggle(inner, "Highlight Dropped Gun", function(v)
            _G._hlGunEnabled = v
            -- Limpiar todos los GunHighlight existentes al apagar
            if not v then
                for _, obj in ipairs(workspace:GetDescendants()) do
                    pcall(function()
                        local hl = obj:FindFirstChild("GunHighlight")
                        if hl then hl:Destroy() end
                        local pt = obj:FindFirstChild("GunHighlight_Particle")
                        if pt then pt:Destroy() end
                    end)
                end
                if _G._hlGunConn then
                    pcall(function() _G._hlGunConn:Disconnect() end)
                    _G._hlGunConn = nil
                end
                return
            end

            -- Funcion que aplica el highlight a cualquier gun drop
            -- (igual que el codigo de referencia: azul electrico, AlwaysOnTop, apaga particulas)
            local function _applyHlGun(obj)
                if not obj or not obj.Parent then return end
                -- Aceptar cualquier nombre de gun suelta en todos los mapas
                local n = obj.Name
                local isGun = (n == "GunDrop" or n == "DropGun" or n == "Gun"
                    or n == "SheriffGun" or n == "HeroGun")
                if not isGun then return end
                -- No aplicar a guns equipadas por jugadores
                if obj.Parent and obj.Parent:FindFirstChildOfClass("Humanoid") then return end
                if obj.Parent and obj.Parent:IsA("Backpack") then return end

                -- Crear/actualizar Highlight (mismo config que el codigo de referencia)
                local hl = obj:FindFirstChild("GunHighlight")
                if not hl then
                    hl = Instance.new("Highlight")
                    hl.Name        = "GunHighlight"
                    hl.FillColor   = (_G._vsColors and _G._vsColors.esp) or Color3.fromRGB(90, 90, 95)
                    hl.OutlineColor = Color3.fromRGB(255, 255, 255)  -- Contorno blanco
                    hl.OutlineTransparency = 0
                    hl.DepthMode   = Enum.HighlightDepthMode.AlwaysOnTop  -- ver a traves de paredes
                    hl.Adornee     = obj
                    hl.Parent      = obj
                    hl.FillTransparency    = 0.5
                end

                -- Apagar particulas y luces (igual que el codigo de referencia)
                for _, d in ipairs(obj:GetDescendants()) do
                    if d:IsA("ParticleEmitter") or d:IsA("PointLight") then
                        pcall(function() d.Enabled = false end)
                    end
                end

                -- Auto-limpiar cuando la gun desaparece
                obj.AncestryChanged:Connect(function()
                    if not obj.Parent then
                        pcall(function()
                            local h2 = obj:FindFirstChild("GunHighlight")
                            if h2 then h2:Destroy() end
                        end)
                    end
                end)
            end

            -- Scan inicial recursivo en todos los mapas (BioLab, Hotel, House, Factory, etc.)
            for _, obj in ipairs(workspace:GetDescendants()) do
                pcall(_applyHlGun, obj)
            end

            -- Heartbeat: buscador recursivo constante con workspace:FindFirstChild(..., true)
            -- Exactamente igual al codigo de referencia -- detecta gun en cualquier carpeta
            local _hlGunTick = 0
            _G._hlGunConn = _safeConnect(RunService.Heartbeat, function()
                if not _G._hlGunEnabled then return end
                if _G._visualRoundOver then return end
                -- OPT: throttle a 5Hz -- FindFirstChild(true) escanea TODO workspace cada frame sin esto
                _hlGunTick = _hlGunTick + 1; if _hlGunTick < 12 then return end; _hlGunTick = 0
                local gun = workspace:FindFirstChild("GunDrop",    true)
                         or workspace:FindFirstChild("DropGun",    true)
                         or workspace:FindFirstChild("SheriffGun", true)
                         or workspace:FindFirstChild("HeroGun",    true)
                if gun then pcall(_applyHlGun, gun) end
            end)

            -- DescendantAdded: detecta nuevas guns cuando caen
            if _G._hlGunDescConn then
                pcall(function() _G._hlGunDescConn:Disconnect() end)
            end
            _G._hlGunDescConn = workspace.DescendantAdded:Connect(function(obj)
                if _G._hlGunEnabled then
                    _sp(function() pcall(_applyHlGun, obj) end)
                end
            end)
        end, _G._hlGunEnabled or false)
 CreateAuroraToggle(inner, "Highlight Throwing Knives", function(v)
            _G._tkHlEnabled=v
            if v then
                if not _G._tkHlConn then
                    _G._tkHlConn=workspace.DescendantAdded:Connect(function(obj)
                        if not _G._tkHlEnabled then return end
                        local nm=obj.Name:lower()
                        if not(nm:find("knife") or nm:find("blade")) then return end
                        if obj:IsDescendantOf(Players) then return end
                        pcall(function()
                            local hl=Instance.new("Highlight"); hl.Adornee=obj.Parent
                            hl.FillColor=Color3.fromRGB(255,60,30); hl.OutlineColor=Color3.fromRGB(255,150,100)
                            hl.OutlineTransparency=0
                            hl.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop; hl.Parent=obj.Parent
                            hl.FillTransparency=0.4
                            _dl(3,function() pcall(function() if hl and hl.Parent then hl:Destroy() end end) end)
                        end)
                    end)
                end
            else
                if _G._tkHlConn then _G._tkHlConn:Disconnect(); _G._tkHlConn=nil end
            end
        end, false)
        makeESPPlayerPin(inner, vh, ThemeColors.Aurora3)
