    do
        local TrapSystem_vt = ReplicatedStorage:FindFirstChild("TrapSystem")
        local _trapTracked       = {}
        local _trapEnabled       = false
        local _trapWSConn        = nil
        local _trapNotifyEnabled = false

        local function getOwnerName(part)
            local parent = part and part.Parent
            if not parent then return "?" end
            local pp = parent:FindFirstChild("PlacedPlayer")
            if pp and pp:IsA("ObjectValue") and pp.Value then return pp.Value.Name end
            local ps = parent:FindFirstChild("PlacedBy") or parent:FindFirstChild("Owner")
            if ps and ps.Value and ps.Value ~= "" then return tostring(ps.Value) end
            return "?"
        end

        local function getTrapName(part)
            local parent = part and part.Parent
            if not parent then return "Trampa" end
            local tn = parent:FindFirstChild("TrapName") or parent:FindFirstChild("ItemName")
            if tn and tn.Value and tn.Value ~= "" then return tostring(tn.Value) end
            local n = tostring(parent.Name):gsub("Clone", ""):gsub("%s+", ""):gsub("%d+$", "")
            if n ~= "" and n ~= "Workspace" and n ~= "workspace" then return n end
            return "Trampa"
        end

        local function removeBillboard(part)
            local data = _trapTracked[part]
            if not data then return end
            pcall(function() if data.conn then data.conn:Disconnect() end end)
            pcall(function() if data.bb then data.bb:Destroy() end end)
            _trapTracked[part] = nil
        end

        local function clearAll()
            for part in pairs(_trapTracked) do removeBillboard(part) end
            _trapTracked = {}
        end

        local function addBillboard(part)
            if not _trapEnabled then return end
            if _trapTracked[part] then return end
            if not part or not part.Parent then return end

            local owner    = getOwnerName(part)
            local trapName = getTrapName(part)
            local isActive = part.Transparency < 0.6

            local bb = Instance.new("BillboardGui")
            bb.Name        = "TrapESP_BB"
            bb.Size        = UDim2.new(0, 130, 0, 40)
            bb.StudsOffset = Vector3.new(0, 4.5, 0)
            bb.AlwaysOnTop = true
            bb.Parent      = part

            local lblName = Instance.new("TextLabel", bb)
            lblName.Size                   = UDim2.new(1, 0, 0.55, 0)
            lblName.BackgroundTransparency = 1
            lblName.FontFace = Font.fromEnum(Enum.Font.Montserrat)
            lblName.TextSize               = 13
            lblName.TextColor3             = isActive and Color3.fromRGB(58, 58, 58) or Color3.fromRGB(255, 200, 60)
            lblName.TextStrokeTransparency = 0
            lblName.TextStrokeColor3       = ThemeColors.Background
            lblName.Text                   = " " .. trapName

            local lblOwner = Instance.new("TextLabel", bb)
            lblOwner.Size                   = UDim2.new(1, 0, 0.45, 0)
            lblOwner.Position               = UDim2.new(0, 0, 0.55, 0)
            lblOwner.BackgroundTransparency = 1
            lblOwner.FontFace = Font.fromEnum(Enum.Font.Montserrat)
            lblOwner.TextSize               = 11
            lblOwner.TextColor3             = Color3.fromRGB(190, 190, 195)
            lblOwner.TextStrokeTransparency = 0
            lblOwner.TextStrokeColor3       = ThemeColors.Background
            lblOwner.Text                   = " " .. owner

            local conn = part.AncestryChanged:Connect(function()
                if not part or not part.Parent then
                    removeBillboard(part)
                end
            end)
            _trapTracked[part] = { bb = bb, conn = conn }
        end

        local function initialScan()
            for _, obj in ipairs(workspace:GetDescendants()) do  -- OPT: pairs->ipairs
                if obj:IsA("BasePart") and obj.Name == "TrapVisual" then
                    pcall(addBillboard, obj)
                end
            end
        end

        local inner = CreateVisualCard(leftColumn, "", "VIEW TRAP", Color3.fromRGB(255, 100, 60))

        MiniHeader(inner, " ESP DE TRAMPAS (visible + invisible)", Color3.fromRGB( 50, 255, 180))
 CreateAuroraToggle(inner, "View Trap ESP", function(v)
            _trapEnabled = v
            if _trapWSConn then _trapWSConn:Disconnect(); _trapWSConn = nil end
            if v then
                initialScan()
                _trapWSConn = workspace.DescendantAdded:Connect(function(obj)
                    if _trapEnabled and obj:IsA("BasePart") and obj.Name == "TrapVisual" then
                        _sp(function() pcall(addBillboard, obj) end)
                    end
                end)
 -- [notif removed]
            else
                clearAll()
 -- [notif removed]
            end
        end, false)

        MiniHeader(inner, " NOTIFICACIONES", Color3.fromRGB(255, 200, 60))
 CreateAuroraToggle(inner, "Notify Trap Hit", function(v) _trapNotifyEnabled = v end, false)

        if TrapSystem_vt then
            pcall(function()
                TrapSystem_vt.TrapHitLocal.OnClientEvent:Connect(function(trapObj, victim)
                    if _trapNotifyEnabled then
                        local name = victim and victim.Name or "Alguien"
 CreateCustomNotification(" ATRAPADO", name .. " fue atrapado!", 3)
                    end
                end)
                TrapSystem_vt.TrapHitVisual.OnClientEvent:Connect(function(trapObj, trapCF, victim)
                    if _trapNotifyEnabled and victim then
 CreateCustomNotification(" TRAP", victim.Name .. " cayo en trampa!", 3)
                    end
                end)
                TrapSystem_vt.PlaceTrapLocal.OnClientEvent:Connect(function(trapObj)
                    if _trapNotifyEnabled then
                        local pp = trapObj and trapObj:FindFirstChild("PlacedPlayer")
                        local owner = pp and pp.Value and pp.Value.Name or "?"
 CreateCustomNotification(" TRAMPA PUESTA", owner .. " coloco una trampa!", 3)
                    end
                end)
            end)
        end

        MiniHeader(inner, " SCAN MANUAL", Color3.fromRGB(195, 195, 200))
        local scanBtn = Instance.new("TextButton", inner)
        scanBtn.Size = UDim2.new(1, 0, 0, 36)
        scanBtn.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
        scanBtn.BackgroundTransparency = 0.75
        scanBtn.BorderSizePixel = 0
 scanBtn.Text = " Scan Todas las Trampas"
        scanBtn.TextColor3 = Color3.fromRGB(195, 195, 200)
        scanBtn.TextSize = 11
        scanBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        scanBtn.ZIndex = 13
        Instance.new("UICorner", scanBtn).CornerRadius = UDim.new(0, 8)
        local scanStroke = Instance.new("UIStroke", scanBtn)
        scanStroke.Color = Color3.fromRGB(195, 195, 200)
        scanStroke.Thickness = 2.5
        scanStroke.Transparency = 0.3
        scanBtn.Activated:Connect(function()

            local count = 0
            for _, obj in ipairs(workspace:GetDescendants()) do  -- OPT: pairs->ipairs
                if obj:IsA("BasePart") and obj.Name == "TrapVisual" then
                    count += 1
                    local owner = getOwnerName(obj)
                    local trapName = getTrapName(obj)
                    local estado = obj.Transparency < 0.6 and "ACTIVA" or "invisible"
 CreateCustomNotification(" " .. trapName, owner .. " -- " .. estado, 3)
                end
            end
            if count == 0 then
 CreateCustomNotification(" SCAN", "No se encontraron trampas", 2)
            end
        end)
    end


    do
        -- == TRACER -- BY TEAM + BY OBJECT + from Head ==============
