do
    local function _worldReapply()
        task.wait(0.35) -- esperar a que la camara y el personaje esten listos

        -- FIX: siempre restaurar zoom al revivir para evitar que la camara se pegue a la cabeza
        pcall(function()
            LocalPlayer.CameraMaxZoomDistance = 400
            LocalPlayer.CameraMinZoomDistance = 0.5
        end)

        if WorldSystem.effects.noBlur then
            pcall(function()
                for _, e in pairs(Lighting:GetChildren()) do
                    if e:IsA("BlurEffect") then e.Enabled = false end
                end
                for _, e in pairs(workspace.CurrentCamera:GetChildren()) do
                    if e:IsA("BlurEffect") then e.Enabled = false end
                end
            end)
        end
        if WorldSystem.effects.fullBright then
            pcall(function()
                Lighting.Brightness = 2
                Lighting.ClockTime  = 14
                Lighting.FogEnd     = 100000
                Lighting.GlobalShadows = false
                Lighting.OutdoorAmbient = Color3.fromRGB(128, 128, 128)
                Lighting.Ambient    = Color3.fromRGB(128, 128, 128)
            end)
        end
        if WorldSystem.effects.noFog then
            pcall(function() Lighting.FogEnd = 100000; Lighting.FogStart = 99999 end)
        end

        task.wait(0.5)

        -- FIX WORLD/BOOST #1: una sola declaracion de perf, sin shadowing
        local perf = WorldSystem.performance
        if perf then
            if perf.ultraMode then
                pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
            end
            if perf.disableShadows then
                pcall(function() Lighting.GlobalShadows = false end)
            end
            if perf.disablePostEffects then
                pcall(function()
                    for _, effect in pairs(Lighting:GetChildren()) do
                        if effect:IsA("PostEffect") then effect.Enabled = false end
                    end
                    for _, effect in pairs(workspace.CurrentCamera:GetChildren()) do
                        if effect:IsA("PostEffect") then effect.Enabled = false end
                    end
                end)
            end
            if perf.removeParticles then
                task.spawn(function()
                    task.wait(0.3)
                    for _, obj in pairs(workspace:GetDescendants()) do
                        if obj:IsA("ParticleEmitter") then pcall(function() obj.Enabled = false end) end
                    end
                end)
            end
            if perf.freezeDistant then
                -- FIX INVISIBILITY: el codigo original usaba LocalTransparencyModifier=1
                -- en jugadores lejanos, lo que los volvia completamente invisibles.
                -- Fix: solo pausar animaciones de jugadores lejanos, NUNCA tocar transparencia.
                task.spawn(function()
                    task.wait(1)
                    for _, p in pairs(_cachedPlayers) do
                        if p ~= LocalPlayer and p.Character then
                            pcall(function()
                                local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                                local tHRP = p.Character:FindFirstChild("HumanoidRootPart")
                                if myHRP and tHRP then
                                    local isFar = (myHRP.Position - tHRP.Position).Magnitude > 150
                                    -- FIX: solo pausar/reanudar el Animator, nunca ocultar partes
                                    local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                    local animator = hum and hum:FindFirstChildOfClass("Animator")
                                    if animator then
                                        pcall(function()
                                            if isFar then
                                                local firstTrack = animator:GetPlayingAnimationTracks()[1]
                                                if firstTrack then firstTrack:AdjustSpeed(0) end
                                            else
                                                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                                                    track:AdjustSpeed(1)
                                                end
                                            end
                                        end)
                                    end
                                    -- Asegurar que LocalTransparencyModifier sea 0 siempre
                                    for _, part in ipairs(p.Character:GetDescendants()) do
                                        if part:IsA("BasePart") and part.LocalTransparencyModifier ~= 0 then
                                            pcall(function() part.LocalTransparencyModifier = 0 end)
                                        end
                                    end
                                end
                            end)
                        end
                    end
                end)
            end
        end

        -- FIX WORLD/BOOST #2: Re-aplicar toggles del tab BOOST (BS.*) tras pantalla negra
        -- Sin esto, todas las optimizaciones del tab Boost se pierden al respawnear
        -- Re-aplicar Low Render Quality del tab Settings si estaba activo
        local _hsReapply = _G._hubSettings
        if _hsReapply and _hsReapply.lowRenderQuality then
            task.spawn(function()
                task.wait(0.4)
                pcall(function()
                    settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
                end)
            end)
        end
        local BS = _G.BS
        if BS then
            task.spawn(function()
                task.wait(0.4) -- pequeno delay extra para que el nuevo mapa cargue
                pcall(function()
                    if BS.ultraFPS then
                        settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
                    end
                    if BS.noShadows then
                        Lighting.GlobalShadows = false
                    end
                    if BS.shadowSoftOff then
                        Lighting.ShadowSoftness = 0
                    end
                    if BS.noPostFX then
                        for _, e in ipairs(Lighting:GetChildren()) do
                            if e:IsA("PostEffect") then e.Enabled = false end
                        end
                        for _, e in ipairs(workspace.CurrentCamera:GetChildren()) do
                            if e:IsA("PostEffect") then e.Enabled = false end
                        end
                    end
                    if BS.noBloom then
                        for _, e in ipairs(Lighting:GetChildren()) do
                            if e:IsA("BloomEffect") then e.Enabled = false end
                        end
                    end
                    if BS.noBlur then
                        for _, e in ipairs(Lighting:GetChildren()) do
                            if e:IsA("BlurEffect") then e.Enabled = false end
                        end
                        for _, e in ipairs(workspace.CurrentCamera:GetChildren()) do
                            if e:IsA("BlurEffect") then e.Enabled = false end
                        end
                    end
                    if BS.noCCFX then
                        for _, e in ipairs(Lighting:GetChildren()) do
                            if e:IsA("ColorCorrectionEffect") then e.Enabled = false end
                        end
                    end
                    if BS.noSunRays then
                        for _, e in ipairs(Lighting:GetChildren()) do
                            if e:IsA("SunRaysEffect") then e.Enabled = false end
                        end
                    end
                    if BS.noDOF then
                        for _, e in ipairs(Lighting:GetChildren()) do
                            if e:IsA("DepthOfFieldEffect") then e.Enabled = false end
                        end
                        for _, e in ipairs(workspace.CurrentCamera:GetChildren()) do
                            if e:IsA("DepthOfFieldEffect") then e.Enabled = false end
                        end
                    end
                    if BS.noParticles then
                        for _, d in ipairs(workspace:GetDescendants()) do
                            if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Smoke")
                            or d:IsA("Fire") or d:IsA("Sparkles") then
                                pcall(function() d.Enabled = false end)
                            end
                        end
                    end
                    if BS.noBeams then
                        for _, d in ipairs(workspace:GetDescendants()) do
                            if d:IsA("Beam") then pcall(function() d.Enabled = false end) end
                        end
                    end
                    -- FPS cap
                    if BS.maxFPS and setfpscap then
                        pcall(function() setfpscap(BS.maxFPS) end)
                    end
                end)
            end)
        end

        -- FIX WORLD/BOOST #3: Re-aplicar GunAura tras respawn usando el sistema event-driven
        -- El conn viejo usaba workspace:GetDescendants() cada 3 frames -> lag masivo
        -- Ahora simplemente re-activa el toggle para reconstruir el cache limpiamente
        local ga = WorldSystem.gunAura
        if ga and ga.enabled and (not ga.conn or not ga.conn.Connected) then
            -- Limpiar conn roto si existe
            if ga.conn then pcall(function() ga.conn:Disconnect() end); ga.conn = nil end
            if ga._auraAddConn then pcall(function() ga._auraAddConn:Disconnect() end); ga._auraAddConn = nil end
            if ga._auraRemConn then pcall(function() ga._auraRemConn:Disconnect() end); ga._auraRemConn = nil end
            -- Re-activar via el sistema event-driven (mismo que el toggle del tab)
            -- Construir cache inicial solo una vez al respawn, luego event-driven
            local _auraCache = {}
            local function _isFloorGun(obj)
                if not obj or not obj:IsA("Tool") then return false end
                if obj.Name ~= "GunDrop" and obj.Name ~= "DropGun" then return false end
                local par = obj.Parent; if not par then return false end
                if par:FindFirstChildOfClass("Humanoid") then return false end
                for _, p in ipairs(_cachedPlayers) do
                    if p.Backpack == par then return false end
                end
                return true
            end
            -- Scan inicial ligero (una sola vez, no en loop)
            pcall(function()
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if _isFloorGun(obj) then _auraCache[obj] = true end
                end
            end)
            ga._auraAddConn = workspace.DescendantAdded:Connect(function(obj)
                if obj:IsA("Tool") and (obj.Name == "GunDrop" or obj.Name == "DropGun") then
                    task.wait(0.016)
                    if _isFloorGun(obj) then _auraCache[obj] = true end
                end
            end)
            ga._auraRemConn = workspace.DescendantRemoving:Connect(function(obj)
                _auraCache[obj] = nil
            end)
            local _gaTimer = 0
            ga.conn = RunService.Heartbeat:Connect(function(dt)
                _gaTimer = _gaTimer + dt
                if _gaTimer < 0.08 then return end
                _gaTimer = 0
                if not ga.enabled then return end
                local char = LocalPlayer.Character; if not char then return end
                local root = char:FindFirstChild("HumanoidRootPart"); if not root then return end
                if _findGun and _findGun(char) then return end
                for obj in pairs(_auraCache) do
                    if not obj or not obj.Parent then _auraCache[obj] = nil; continue end
                    local handle = obj:FindFirstChild("Handle") or (obj:IsA("BasePart") and obj)
                    if handle and (root.Position - handle.Position).Magnitude <= ga.range then
                        pcall(function() firetouchinterest(root, handle, 0); firetouchinterest(root, handle, 1) end)
                        _auraCache[obj] = nil; break
                    end
                end
            end)
        end

        pcall(function()
            local hubGui = LocalPlayer.PlayerGui:FindFirstChild("f")
            if hubGui then
                for _, desc in pairs(hubGui:GetDescendants()) do
                    if desc:IsA("ScrollingFrame") then
                        desc.ScrollingEnabled = true
                    end
                end
            end
        end)
    end

    -- FIX: solo conectar UNA vez usando un guard global
    if not _G._worldReapplyConnected then
        _G._worldReapplyConnected = true
        Players.LocalPlayer.CharacterAdded:Connect(function()
            if WorldSystem then _worldReapply() end
        end)
    end
end
function GetCurrentMapInWorkspace()
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj:IsA("Model") and (
            obj:FindFirstChild("CoinContainer") or
            obj:FindFirstChild("Spawns") or
            obj.Name:find("Map") or
            obj.Name:find("House") or
            obj.Name:find("Mansion") or
            obj.Name:find("Station") or
            obj.Name:find("Hospital") or
            obj.Name:find("School") or
            obj.Name:find("Factory") or
            obj.Name:find("Office") or
            obj.Name:find("Workplace") or
            obj.Name:find("Milbase")
        ) then
            if obj.Name:lower() ~= "lobby" then
                return obj
            end
        end
    end
    return nil
end

_votePadState = {
    isRunning    = false,
    targetPart   = nil,   -- BasePart seleccionada por el usuario (click)
    times        = 5,     -- veces a resetear (slider)
    currentCycle = 0,
    delay        = 1.0,   -- delay entre ciclos (slider)
    activePad    = 0,     -- indice del votepad activo (1,2,3) o 0 si ninguno
}

_votePickConn = nil
_voteStatusLbl = nil  -- referencia al label de estado (se setea en UI)

function _startVotePick()
    if _votePickConn then _votePickConn:Disconnect(); _votePickConn = nil end
 if _voteStatusLbl then _voteStatusLbl.Text = " Click en el VotePad..." end
    local mouse = LocalPlayer:GetMouse()
    _votePickConn = mouse.Button1Down:Connect(function()
        local hit = mouse.Target
        if hit and hit:IsA("BasePart") then
            _votePadState.targetPart = hit
            if _voteStatusLbl then
 _voteStatusLbl.Text = " Part: " .. hit.Name .. " (" .. hit.Parent.Name .. ")"
            end
 CreateCustomNotification("TP VOTE", "Part seleccionada: " .. hit.Name, 2)
        end
        _votePickConn:Disconnect(); _votePickConn = nil
    end)
end

-- Calcula un CFrame encima de la plataforma del VotePad,
-- desplazado hacia adelante para no chocar contra la pared trasera.
local function _getPlatformCF(part)
    -- Subimos 4 studs y nos alejamos 3 studs hacia -Z local del part (frente de la plataforma)
    local base = part.CFrame
    return base * CFrame.new(0, 4, 3)
end

-- TP multipaso hacia la plataforma del votepad (3 intentos rapidos)
local function _tpToPlatform(hrpRef, part)
    if not (hrpRef and part and part.Parent) then return end
    local cf = _getPlatformCF(part)
    for _ = 1, 3 do
        pcall(function()
            local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if h then
                h.CFrame = cf
                h.AssemblyLinearVelocity = Vector3.zero
            end
        end)
        task.wait(0.016)
    end
end

function AutoVoteMap(times)
    if _votePadState.isRunning then
        CreateCustomNotification("VOTE", "Ya hay un voto en progreso!", 2)
        return
    end
    if not _votePadState.targetPart or not _votePadState.targetPart.Parent then
        CreateCustomNotification("VOTE", "Primero activa un TP VotePad (1/2/3)!", 3)
        return
    end

    _votePadState.isRunning   = true
    _votePadState.currentCycle = 0
    local targetPart = _votePadState.targetPart
    local delay      = _votePadState.delay or 1.0

    task.spawn(function()
        -- TP inicial a la plataforma antes de empezar ciclos
        local char0 = LocalPlayer.Character
        local hrp0  = char0 and char0:FindFirstChild("HumanoidRootPart")
        _tpToPlatform(hrp0, targetPart)
        task.wait(0.3)

        for i = 1, times do
            if not _votePadState.isRunning then break end
            _votePadState.currentCycle = i

            -- Esperar personaje vivo
            local char, hrp, hum
            local t = 0
            repeat
                task.wait(0.1); t = t + 0.1
                char = LocalPlayer.Character
                hrp  = char and char:FindFirstChild("HumanoidRootPart")
                hum  = char and char:FindFirstChildOfClass("Humanoid")
            until (hrp and hum and hum.Health > 0) or t > 10
            if not hrp then break end

            if not targetPart or not targetPart.Parent then
                CreateCustomNotification("VOTE ERROR", "El VotePad ya no existe!", 3)
                break
            end

            -- TP a plataforma (no contra la pared)
            _tpToPlatform(hrp, targetPart)
            task.wait(0.2)

            CreateCustomNotification(
                "AUTO VOTE " .. i .. "/" .. times,
                "Plataforma: " .. targetPart.Name .. " | delay: " .. delay .. "s", 1.2
            )

            -- Resetear
            local hum2 = char:FindFirstChildOfClass("Humanoid")
            if hum2 and hum2.Health > 0 then hum2.Health = 0 end
            task.wait(0.15)
            if LocalPlayer.Character == char then
                pcall(function() LocalPlayer:LoadCharacter() end)
            end

            -- Esperar nuevo char
            local oldChar = LocalPlayer.Character
            local timeout = 0
            repeat
                task.wait(0.1); timeout = timeout + 0.1
            until LocalPlayer.Character ~= oldChar or timeout > 8

            -- Esperar que cargue
            task.wait(0.3)
            local newChar = LocalPlayer.Character
            local newHRP  = newChar and newChar:FindFirstChild("HumanoidRootPart")
            local newHum  = newChar and newChar:FindFirstChildOfClass("Humanoid")
            local tWait = 0
            repeat
                task.wait(0.016); tWait = tWait + 0.05
                newChar = LocalPlayer.Character
                newHRP  = newChar and newChar:FindFirstChild("HumanoidRootPart")
                newHum  = newChar and newChar:FindFirstChildOfClass("Humanoid")
            until (newHRP and newHum and newHum.Health > 0) or tWait > 5

            -- TP a plataforma despues del respawn
            _tpToPlatform(newHRP, targetPart)

            -- Delay configurable entre ciclos
            if i < times then
                task.wait(math.max(0.15, delay - 0.3))
            end
        end

        _votePadState.isRunning    = false
        _votePadState.currentCycle = 0
        if _voteStatusLbl then
            _voteStatusLbl.Text = " Part: " .. (targetPart and targetPart.Name or "?")
        end
        CreateCustomNotification("VOTE COMPLETO", "Voto " .. times .. " veces", 3)
    end)
end

function CreateControllableDummy()
    local char = LocalPlayer.Character
    if not char then return nil end

    local dummy = char:Clone()
    dummy.Name = "FakeDummy_" .. LocalPlayer.Name

    for _, part in pairs(dummy:GetDescendants()) do
        if part:IsA("BasePart") or part:IsA("MeshPart") then
            part.Transparency = 0.65
            part.CanCollide = false
            part.Anchored = true  -- Anclado: no necesita fisica, solo posicion
            part.Massless = true
            if part.Name == "Head" then
                local face = part:FindFirstChild("face")
                if face then face.Transparency = 0.65 end
            end
        elseif part:IsA("Decal") then
            part.Transparency = 0.65
        elseif part:IsA("Script") or part:IsA("LocalScript") then
            part:Destroy()
        end
    end

    local highlight = Instance.new("Highlight")
    highlight.FillColor = ThemeColors.Primary
    highlight.FillTransparency = 0.6
    highlight.OutlineColor = ThemeColors.Aurora2
    highlight.OutlineTransparency = 0.2
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = dummy

    return dummy
end

function CreateAuroraToggle(parent, nombre, callback, initialValue)
    local actualParent = _currentMainSectionFrame or parent
    local _trackedCol = (actualParent == leftColumn or (actualParent and actualParent.Parent == leftColumn)) and leftColumn or rightColumn
    _colHeights[_trackedCol == leftColumn and "left" or "right"] = (_colHeights[_trackedCol == leftColumn and "left" or "right"] or 0) + 48

    _G._toggleStates = _G._toggleStates or {}
    local savedState = _G._toggleStates[nombre]
    local estado = (savedState ~= nil) and savedState or (initialValue or false)

    -- REGISTRO DE CALLBACKS: guardar el callback por nombre para poder
    -- restaurar toggles del World Tab (y otros) desde el auto-restore
    if callback then
        _G._toggleCallbacks = _G._toggleCallbacks or {}
        _G._toggleCallbacks[nombre] = callback
    end
    -- REGISTRO DE APPLYSTATE: guardar la funcion visual del knob para que
    -- el auto-restore del World Tab pueda actualizar el indicador a verde
    -- sin depender de la closure local (inaccesible desde fuera de la funcion).
    -- Se sobreescribe al re-crear el toggle (cambio de tab) con la nueva instancia.
    _G._toggleApplyStates = _G._toggleApplyStates or {}

    -- FIX: C_IND_ON/C_IND_OFF eliminadas (variables muertas de version anterior,
    -- nunca usadas; C_IND_OFF=rojo podia aplicarse por error en algunos paths).
    local TWEEN_T   = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

    -- Detectar m?vil para ajustar tama?os
    local _isMobileTog = pcall(function() return UserInputService.TouchEnabled end) and UserInputService.TouchEnabled
    local _toggleBgW   = 80
    local _toggleBgH   = 38
    local _knobSize    = 28
    local _knobOffR    = -(_knobSize + 5)
    local _knobOffL    = 4
    local _labelTxtSz  = 16
    local _labelWScale = 0.55
    local _rowH        = 48
    local _toggleRightOff = -6

    -- Marco principal: fila transparente para ver el juego detras
    local container = Instance.new("Frame", actualParent)
    container.Name                   = "AuroraToggleRow_" .. nombre
    container.Size                   = UDim2.new(1, 0, 0, _rowH)
    -- FIX ROJO AUTOSAVE: usar el color guardado si existe, sino el color por defecto azul oscuro
    local _ccc = _G._toggleColorCurrent
    container.BackgroundColor3       = (_ccc and _ccc.bg) or Color3.fromRGB(  5,  18,  50)
    container.BackgroundTransparency = (_ccc and _ccc.bgT) or 0.72
    container.BorderSizePixel        = 0
    container.ZIndex                 = 20

    -- Etiqueta de texto (mitad izquierda) - mas grande y visible
    local label = Instance.new("TextLabel", container)
    label.Size             = UDim2.new(_labelWScale, 0, 1, 0)
    label.Position         = UDim2.new(0, 8, 0, 0)
    label.BackgroundTransparency = 1
    label.Text             = nombre
    label.TextSize         = 16
    label.FontFace         = Font.fromEnum(Enum.Font.GothamBold)
    label.TextColor3       = Color3.fromRGB(230, 255, 245)  -- blanco azulado brillante
    label.TextXAlignment   = Enum.TextXAlignment.Left
    label.TextYAlignment   = Enum.TextYAlignment.Center
    label.TextTruncate     = Enum.TextTruncate.AtEnd
    label.ZIndex           = 22
    -- Sombra negra fuerte para que se lea bien sobre el fondo transparente
    label.TextStrokeColor3       = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0.0  -- sombra solida

    -- Registro de traduccion
    if _LangObjects then
        table.insert(_LangObjects, {obj=label, key=nombre, prefix="", suffix=""})
        if _G.HubLanguage and _LangStrings then
            local _d = _LangStrings[_G.HubLanguage]
            if _d and _d[nombre] then label.Text = _d[nombre] end
        end
    end

    -- Toggle estilo Combat (pill/switch): track con thumb deslizante y numero 1/0
    local _TRACK_W, _TRACK_H = 100, 44
    local _THUMB_W, _THUMB_H = 40, 34
    local _THUMB_PAD = 4
    local _C_TRACK_OFF  = Color3.fromRGB( 12,  25,  40)
    local _C_TRACK_ON   = Color3.fromRGB(  0, 200, 160)
    local _C_THUMB_ON   = Color3.fromRGB( 50, 255, 180)
    local _C_THUMB_OFF  = Color3.fromRGB(  3,   8,  18)
    local _POS_THUMB_ON  = UDim2.new(1, -(_THUMB_W + _THUMB_PAD), 0.5, -_THUMB_H/2)
    local _POS_THUMB_OFF = UDim2.new(0, _THUMB_PAD, 0.5, -_THUMB_H/2)
    local _POS_NUM_ON    = UDim2.new(0, _THUMB_PAD, 0, 0)
    local _POS_NUM_OFF   = UDim2.new(0.5, 0, 0, 0)

    local track = Instance.new("Frame", container)
    track.Name                   = "ToggleTrack"
    track.Size                   = UDim2.new(0, _TRACK_W, 0, _TRACK_H)
    track.AnchorPoint            = Vector2.new(1, 0.5)
    track.Position               = UDim2.new(1, _toggleRightOff, 0.5, 0)
    track.BackgroundColor3       = estado and _C_TRACK_ON or _C_TRACK_OFF
    track.BackgroundTransparency = 0
    track.BorderSizePixel        = 0
    track.ZIndex                 = 21
    track.ClipsDescendants       = false
    Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

    local thumb = Instance.new("Frame", track)
    thumb.Size                   = UDim2.new(0, _THUMB_W, 0, _THUMB_H)
    thumb.Position               = estado and _POS_THUMB_ON or _POS_THUMB_OFF
    thumb.BackgroundColor3       = estado and _C_THUMB_ON or _C_THUMB_OFF
    thumb.BackgroundTransparency = 0
    thumb.BorderSizePixel        = 0
    thumb.ZIndex                 = 24
    Instance.new("UICorner", thumb).CornerRadius = UDim.new(0, 8)

    -- Borde brillante del track para el efecto muelle
    local _trackStroke = Instance.new("UIStroke", track)
    _trackStroke.Name        = "TOGGLE_TRACK_STROKE"
    _trackStroke.Thickness   = 1.5
    _trackStroke.Color       = estado and Color3.fromRGB(50, 255, 180) or Color3.fromRGB(15, 40, 60)
    _trackStroke.Transparency = 0.2

    -- ANIMACION ARCOIRIS EN EL THUMB (cicla colores del muelle cuando esta ON)
    local _dokkRainbowConn = nil
    local _dokkHue = 0
    local _dokkPalette = {
        Color3.fromRGB(  0, 255, 180),
        Color3.fromRGB( 60, 255, 120),
        Color3.fromRGB(  0, 180, 255),
        Color3.fromRGB(140,  60, 255),
        Color3.fromRGB(  0, 230, 200),
        Color3.fromRGB( 80, 255, 150),
    }
    local function _dokkStartRainbow()
        if _dokkRainbowConn then return end
        _dokkRainbowConn = RunService.Heartbeat:Connect(function(dt)
            if not (thumb and thumb.Parent) then
                if _dokkRainbowConn then _dokkRainbowConn:Disconnect(); _dokkRainbowConn = nil end
                return
            end
            _dokkHue = (_dokkHue + dt * 0.45) % 1
            local n = #_dokkPalette
            local rawPos = _dokkHue * n
            local i1 = math.floor(rawPos) % n + 1
            local i2 = i1 % n + 1
            local t  = rawPos - math.floor(rawPos)
            local c1, c2 = _dokkPalette[i1], _dokkPalette[i2]
            local newC = Color3.new(
                c1.R + (c2.R - c1.R) * t,
                c1.G + (c2.G - c1.G) * t,
                c1.B + (c2.B - c1.B) * t
            )
            pcall(function() thumb.BackgroundColor3 = newC end)
            pcall(function() _trackStroke.Color = newC end)
            pcall(function()
                track.BackgroundColor3 = Color3.new(newC.R*0.28, newC.G*0.28, newC.B*0.28)
            end)
        end)
    end
    local function _dokkStopRainbow()
        if _dokkRainbowConn then _dokkRainbowConn:Disconnect(); _dokkRainbowConn = nil end
        pcall(function() thumb.BackgroundColor3 = _C_THUMB_OFF end)
        pcall(function() _trackStroke.Color = Color3.fromRGB(15, 40, 60) end)
        pcall(function() track.BackgroundColor3 = _C_TRACK_OFF end)
    end
    if estado then task.spawn(_dokkStartRainbow) end

    local numLabel = Instance.new("TextLabel", track)
    numLabel.Size                   = UDim2.new(0.5, 0, 1, 0)
    numLabel.Position               = estado and _POS_NUM_ON or _POS_NUM_OFF
    numLabel.BackgroundTransparency = 1
    numLabel.Text                   = estado and "ON" or "OFF"
    numLabel.Font                   = Enum.Font.GothamBold
    numLabel.TextSize               = 11
    numLabel.TextColor3             = Color3.fromRGB(200, 255, 235)
    numLabel.TextXAlignment         = Enum.TextXAlignment.Center
    numLabel.ZIndex                 = 23

    -- Boton invisible sobre todo el row
    local clickRow = Instance.new("TextButton", container)
    clickRow.Size                   = UDim2.new(1, 0, 1, 0)
    clickRow.BackgroundTransparency = 1
    clickRow.Text                   = ""
    clickRow.ZIndex                 = 25
    clickRow.AutoButtonColor        = false

    -- Funcion de actualizacion visual (con arcoiris muelle nocturno)
    local function ApplyState(on, animate)
        local _tiTrack = TweenInfo.new(animate and 0.20 or 0, Enum.EasingStyle.Quad)
        local _tiThumb = TweenInfo.new(animate and 0.22 or 0, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        if animate then
            if on then
                -- Flash blanco al activar -> luego inicia arcoiris
                _dokkStopRainbow()
                TweenService:Create(thumb, TweenInfo.new(0.07), {BackgroundColor3 = Color3.fromRGB(255, 255, 255)}):Play()
                TweenService:Create(track, _tiTrack, {BackgroundColor3 = _C_TRACK_ON}):Play()
                TweenService:Create(thumb, _tiThumb, {Position = _POS_THUMB_ON}):Play()
                TweenService:Create(numLabel, _tiTrack, {Position = _POS_NUM_ON}):Play()
                task.delay(0.09, function()
                    if thumb and thumb.Parent then _dokkStartRainbow() end
                end)
            else
                -- Detener arcoiris y volver a oscuro
                _dokkStopRainbow()
                TweenService:Create(track, _tiTrack, {BackgroundColor3 = _C_TRACK_OFF}):Play()
                TweenService:Create(thumb, _tiThumb, {Position = _POS_THUMB_OFF}):Play()
                TweenService:Create(thumb, TweenInfo.new(0.20), {BackgroundColor3 = _C_THUMB_OFF}):Play()
                TweenService:Create(numLabel, _tiTrack, {Position = _POS_NUM_OFF}):Play()
            end
        else
            track.BackgroundColor3 = on and _C_TRACK_ON or _C_TRACK_OFF
            thumb.Position         = on and _POS_THUMB_ON or _POS_THUMB_OFF
            thumb.BackgroundColor3 = on and _C_THUMB_ON or _C_THUMB_OFF
            numLabel.Position      = on and _POS_NUM_ON or _POS_NUM_OFF
            if on then task.spawn(_dokkStartRainbow) else _dokkStopRainbow() end
        end
        numLabel.Text = on and "ON" or "OFF"
    end
    -- FIX AUTO-RESTORE VISUAL: exponer ApplyState globalmente para que el
    -- bloque de restauracion del World Tab pueda actualizar el knob a ON/OFF
    -- sin necesitar acceso a esta closure. Se sobreescribe si el toggle se re-crea.
    _G._toggleApplyStates[nombre] = ApplyState
    ApplyState(estado, false)

    -- Hover: resaltar fondo del container
    local _hoverTi = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    clickRow.MouseEnter:Connect(function()
        TweenService:Create(container, _hoverTi, {BackgroundTransparency = 0.30}):Play()
    end)
    clickRow.MouseLeave:Connect(function()
        TweenService:Create(container, _hoverTi, {BackgroundTransparency = 0.55}):Play()
    end)
    -- Logica de toggle
    local _doToggleLastTime = 0  -- FIX DOBLE ACTIVACION: debounce guard
    local function doToggle()
        -- FIX DOBLE ACTIVACION: ignorar si se llama dos veces en menos de 0.25s
        local _now = tick()
        if (_now - _doToggleLastTime) < 0.25 then return end
        _doToggleLastTime = _now
        -- PASO 1: Invertir el booleano en la tabla de estado
        estado = not estado
        _G._toggleStates[nombre] = estado

        -- PASO 2: Actualizar la UI (colores/animacion del knob)
        ApplyState(estado, true)
        PlayToggleSound(estado)

        -- PASO 3: Auto-guardar (throttled: agrupa saves rapidos para no lagear)
        pcall(_saveConfigThrottled)

        -- AUTO-SAFE POR TOGGLE: guardar estado en archivo .txt propio
        -- Identico a la logica del LocalScript de referencia:
        -- activar -> escribe "true", desactivar -> escribe "false"
        -- Al re-unirse al juego, se lee este archivo y se auto-activa
        if not (_neverRestoreToggles and _neverRestoreToggles[nombre]) then
            pcall(_saveToggleFile, nombre, estado)
        end

        -- PASO 4: Ejecutar la accion real del toggle (callback del feature)
        -- FIX: suprimir notificaciones al activar/desactivar manualmente,
        -- EXCEPTO toggles de tipo "Information" (muestran paneles de informacion).
        if callback then
            local _isInfoToggle = nombre:lower():find("^information")
            if _isInfoToggle then
                callback(estado)
            else
                local _origNotif = CreateCustomNotification
                CreateCustomNotification = function() end
                pcall(callback, estado)
                CreateCustomNotification = _origNotif
            end
        end

        -- FIX: forzar tick inmediato del instanceLoop para que los visuals
        -- se apliquen o limpien en el proximo Heartbeat sin esperar el intervalo
        _G._forceInstanceTick = true
        -- FIX: al desactivar, forzar limpieza inmediata de todos los visuals.
        -- FIX DISAPPEAR OUTLINE: los toggles de Outline tienen su propio cleanup
        -- (_refreshOutlineOnly en el callback) que borra solo BoxHandleAdornments
        -- sin tocar los ESP/Cham Highlights de otros jugadores.
        -- Si se usara _vcRefreshAll aqui para toggles de Outline, removeHighlight()
        -- destruiria los highlights de ESP/Cham de TODOS los jugadores, haciendolos
        -- "desaparecer" hasta que el instanceLoop los re-cree (hasta 2s de delay).
        local _nombreLow = nombre:lower()
        local _isOutlineToggle = _nombreLow:find("^outline ") and not _nombreLow:find("outline throwingknife") and not _nombreLow:find("outline tk")
        if not estado and _vcRefreshAll and not _isOutlineToggle then
            task.defer(_vcRefreshAll)
        end
    end

    -- =====================================================================
    -- AUTO-SAFE POR TOGGLE (lectura del .txt individual)
    -- Si el archivo .txt de este toggle dice "true" Y el estado actual
    -- es false (el JSON no lo captur?, ej: salida sin guardar, re-join),
    -- forzar el estado a true para que el bloque de auto-activacion lo dispare.
    -- Exactamente igual que el LocalScript de referencia:
    --   success, data = pcall(readfile, fileName)
    --   if success and data == "true" then isEnabled = true end
    -- =====================================================================
    if not (_neverRestoreToggles and _neverRestoreToggles[nombre])
       and not (_G._isTabRebuild == true) then
        local _fileState = _readToggleFile(nombre)
        if _fileState == true and not estado then
            -- El archivo dice ON pero el JSON no lo tenia: sincronizar
            estado = true
            _G._toggleStates[nombre] = true
            -- Actualizar visual del knob a ON
            pcall(function() ApplyState(true, false) end)
        elseif _fileState == false and estado and savedState == nil then
            -- El archivo dice OFF explicitamente Y el JSON no tenia estado guardado:
            -- el usuario lo apago y el JSON no lo capturo (ej: autoguardado estaba OFF).
            -- FIX MAIN TAB ROJO: si el JSON SI tenia el estado (savedState ~= nil),
            -- el JSON gana sobre el .txt para evitar que toggles del main tab aparezcan
            -- en rojo al cargar aunque el JSON los tenga como true.
            estado = false
            _G._toggleStates[nombre] = false
            pcall(function() ApplyState(false, false) end)
        end
    end

    -- Auto-activar al cargar (misma logica que antes)
    local _isBoostNoAuto = _G._boostNoAutoThisSession and _G._boostNoAutoThisSession[nombre]
    -- _isNeverRestore: true solo si esta en _neverRestoreToggles Y NO esta en _autoRestoreOnReexec
    -- Los toggles en _autoRestoreOnReexec SIEMPRE se restauran en re-ejecucion real
    local _isNeverRestore = (_neverRestoreToggles and _neverRestoreToggles[nombre])
                            and not (_autoRestoreOnReexec and _autoRestoreOnReexec[nombre])
    -- _isAutoRestore: toggle que debe restaurarse en re-ejecucion (no en tab rebuild)
    local _isAutoRestore  = _autoRestoreOnReexec and _autoRestoreOnReexec[nombre]
    -- AUTORESTORE v2 + AUTO-RESTORE ON REEXEC:
    -- _wasUserSet    ? habia un estado guardado (en disco o en sesion)
    -- _isTabRebuild  ? es solo un cambio de pestana (UI se recrea, funcionalidad ya corre)
    -- Diferencia clave:
    --   Tab rebuild:   _G._isTabRebuild == true  ? NO llamar callback (ya esta corriendo)
    --   Re-ejecucion:  _G._isTabRebuild == false/nil ? SI llamar callback (hub nuevo, nada corre)
    -- Caso A: toggle sin estado previo con initialValue=true ? auto-activar (comportamiento original)
    -- Caso B: toggle con savedState=true y NO es tab rebuild ? restaurar desde disco
    -- Caso C (_autoRestoreOnReexec): savedState=true + NO tab rebuild ? restaurar Y disparar funcion
    local _wasUserSet   = (savedState ~= nil)
    local _isTabRebuild = (_G._isTabRebuild == true)
    -- Para _autoRestoreOnReexec: activar si el disco dice true Y no es tab rebuild
    -- FIX v21: _noAutoActivateWorld solo bloquea cuando se esta construyendo
    -- el World Tab (idx 2). Combat, Visuals y otros tabs NO se bloquean.
    local _worldBlockActive = _G._noAutoActivateWorld and (_G._currentBuildingTabIdx == 2)

    -- FIX DOBLE ACTIVACION v2: verificar _activatedToggles ANTES de calcular
    -- _shouldAutoActivate para cortar el path lo mas temprano posible.
    -- Tab rebuild (_isTabRebuild=true) SIEMPRE bloquea la auto-activacion:
    -- el callback ya esta corriendo y re-dispararlo duplica loops/efectos.
    local _alreadyFired = _G._activatedToggles and _G._activatedToggles[nombre]

    local _shouldAutoActivate = estado and callback
        and not _isBoostNoAuto
        and not _worldBlockActive
        and not _isNeverRestore
        and not _alreadyFired
        and not _isTabRebuild   -- nunca re-activar en tab rebuild (ya corre)
        and (not _wasUserSet or (savedState == true))
    if _shouldAutoActivate then
        -- Marcar como disparado para que futuras reconstrucciones del toggle
        -- (cambios de tab, reloads) no vuelvan a llamar el callback.
        if _G._activatedToggles then _G._activatedToggles[nombre] = true end
    end
    -- BLOQUEO PREMIUM: si el toggle es Premium y no tiene verificacion, forzar OFF
    -- aunque el archivo .txt o JSON diga true (puede haber quedado guardado de antes)
    if _shouldAutoActivate and nombre:find("%(Premium%)") and not _G._discordPremiumVerified then
        _shouldAutoActivate = nil
        estado = false
        _G._toggleStates[nombre] = false
        pcall(function() ApplyState(false, false) end)
        -- Borrar el archivo .txt para que no se reactive en el proximo join
        pcall(function() _saveToggleFile(nombre, false) end)
    end
    if _shouldAutoActivate then
        local lower = nombre:lower()

        -- FIX DOBLE ACTIVACION v2: _isTabRebuild ya esta bloqueado arriba,
        -- por lo que aqui solo llegamos en re-ejecucion real (hub nuevo).
        -- Todos los toggles fisicos esperan a que su tab este construido
        -- antes de disparar el callback para evitar upvalues nil.
        local lower = nombre:lower()
        local isPhysical = (
            lower:find("swim fly") or lower:find("fly %+") or lower:find("fly+")
            or (lower:find("fly") and not lower:find("firefly"))
            or lower:find("noclip") or lower:find("no%-clip")
            or lower:find("swim") or lower:find("float")
            or lower:find("spinbot") or lower:find("spin bot")
            or lower:find("^lay$") or lower:find(" lay$") or lower:find("^lay ")
            or lower:find("ragdoll") or lower:find("orbit")
            or lower:find("platform stand") or lower:find("bhop") or lower:find("bunny hop")
            or lower:find("fling self") or lower:find("auto fling")
            or lower:find("knife aura") or lower:find("auto click") or lower:find("kill all")
            or lower:find("touch fling") or lower:find("hitbox expander") or lower:find("hitbox")
            or lower:find("knife hitbox") or lower:find("kill except") or lower:find("auto kill")
            or lower:find("fling todos") or lower:find("fling sheriff") or lower:find("fling all")
            or lower:find("kill aura") or lower:find("aura auto")
            or lower:find("anti bang") or lower:find("bang murder") or lower:find("bang sheriff")
            or lower:find("bang random") or lower:find("bang innocent")
            or lower:find("goto murder") or lower:find("goto sheriff")
            or lower:find("goto innocent") or lower:find("goto selected")
            or lower:find("instant interact") or lower:find("interactions distance")
            or lower:find("tp to am") or lower:find("tp to void")
            or lower:find("tp to lobby") or lower:find("tp to vm")
            or lower:find("bindable button")
            or lower:find("expose murderer") or lower:find("expose roles")
            or lower:find("auto shoot") or lower:find("shoot murder")
            or lower:find("shoot pick") or lower:find("wall check")
            or lower:find("silent aim") or lower:find("aimlock")
            or lower:find("pierce bullet") or lower:find("shoot camuflado")
            or lower:find("shooper") or lower:find("shoot spam")
            or lower:find("strafe prediction") or lower:find("tianca prediction")
            or lower:find("throwing knife") or lower:find("bullet tracer")
            or lower:find("prediction tracer") or lower:find("velocity prediction")
            or lower:find("auto ping") or lower:find("ping boost")
            or lower:find("auto stab") or lower:find("auto slash")
            or lower:find("fast slash") or lower:find("auto throw")
            or lower:find("fast throw") or lower:find("instant throw")
            or lower:find("knife silent") or lower:find("speed glitch")
            or lower:find("enable walkspeed") or lower:find("always speed")
            or lower:find("power jump") or lower:find("infinite jump")
            or lower:find("infinity jump") or lower:find("auto jump")
            or lower:find("wall hop") or lower:find("spin")
            or lower:find("click tp") or lower:find("tp low map")
            or lower:find("auto tp") or lower:find("auto teleport")
            or lower:find("auto farm") or lower:find("auto prestige")
            or lower:find("auto grab gun") or lower:find("auto equip gun")
            or lower:find("auto remove")
            or lower:find("dual knife") or lower:find("dual gun")
            or lower:find("invisible") or lower:find("xray")
            or lower:find("second life") or lower:find("skip death")
            or lower:find("trap immune") or lower:find("bug tramp")
            or lower:find("auto esquivar") or lower:find("auto spectate")
            or lower:find("auto announce") or lower:find("auto reset")
            or lower:find("own ping") or lower:find("ping mode")
            or lower:find("spoof method") or lower:find("shoot condition")
            or lower:find("spoof") or lower:find("secure tp")
        )

        if isPhysical then
            -- Toggle fisico: esperar a que el tab que lo contiene este construido
            -- y el personaje este listo antes de disparar el callback.
            task.spawn(function()
                task.wait(0.3)
                if _G._tabBuilt then
                    local _waitTick = 0
                    local _lowerN = nombre:lower()
                    local _targetTabIdx = nil
                    if _lowerN:find("silent aim") or _lowerN:find("aimlock") or _lowerN:find("shoot")
                    or _lowerN:find("auto stab") or _lowerN:find("auto slash") or _lowerN:find("fast slash")
                    or _lowerN:find("auto throw") or _lowerN:find("fast throw") or _lowerN:find("instant throw")
                    or _lowerN:find("knife silent") or _lowerN:find("throwing knife") or _lowerN:find("bullet tracer")
                    or _lowerN:find("prediction tracer") or _lowerN:find("velocity prediction")
                    or _lowerN:find("strafe prediction") or _lowerN:find("tianca prediction")
                    or _lowerN:find("pierce bullet") or _lowerN:find("shooper") or _lowerN:find("bindable silent")
                    or _lowerN:find("shoot pick") or _lowerN:find("wall check") or _lowerN:find("auto ping")
                    or _lowerN:find("lead time") or _lowerN:find("jump prediction") or _lowerN:find("lag compensation")
                    or _lowerN:find("shoot studs") or _lowerN:find("shoot view") or _lowerN:find("trajectory")
                    or _lowerN:find("dual knife") or _lowerN:find("dual gun") or _lowerN:find("auto shoot") then
                        _targetTabIdx = 6
                    elseif _lowerN:find("fly") or _lowerN:find("noclip") or _lowerN:find("walkspeed")
                    or _lowerN:find("speed glitch") or _lowerN:find("power jump") or _lowerN:find("infinite jump")
                    or _lowerN:find("infinity jump") or _lowerN:find("auto jump") or _lowerN:find("wall hop")
                    or _lowerN:find("spin") or _lowerN:find("click tp") or _lowerN:find("tp low map")
                    or _lowerN:find("orbit") or _lowerN:find("invisible") or _lowerN:find("second life")
                    or _lowerN:find("trap immune") or _lowerN:find("bug tramp") or _lowerN:find("skip death")
                    or _lowerN:find("auto farm") or _lowerN:find("auto prestige") or _lowerN:find("auto grab")
                    or _lowerN:find("auto equip") or _lowerN:find("coin aura") or _lowerN:find("auto remove")
                    or _lowerN:find("auto esquivar") or _lowerN:find("auto spectate") or _lowerN:find("auto announce")
                    or _lowerN:find("auto reset") or _lowerN:find("ping boost") or _lowerN:find("own ping")
                    or _lowerN:find("secure auto") or _lowerN:find("booster") or _lowerN:find("bindable boton")
                    or _lowerN:find("show bindable") then
                        _targetTabIdx = 7
                    end
                    if _targetTabIdx then
                        local _waitStart = tick()
                        while not (_G._tabBuilt and _G._tabBuilt[_targetTabIdx]) and _waitTick < 150 do
                            task.wait(0.1)
                            _waitTick = _waitTick + 1
                            if _G._toggleCallbacks and _G._toggleCallbacks[nombre] then break end
                        end
                        task.wait(0.05)
                    end
                end
                -- FIX MULTI-FIRE INVISIBLE: guard para toggles que modifican transparencia
                -- del personaje (invisible, xray). Si ya hay una ejecucion corriendo,
                -- no disparar otra vez para evitar que el fondo/personaje quede opaco.
                local _lowerFire = nombre:lower()
                local _isInvisToggle = _lowerFire:find("invisible") or _lowerFire:find("xray")
                local _fireKey = "_autoFiring_" .. nombre:gsub("[^%w]", "_")
                if _isInvisToggle then
                    if _G[_fireKey] then
                        -- Ya hay una activacion en curso para este toggle: saltar
                        return
                    end
                    _G[_fireKey] = true
                end
                local _orig = CreateCustomNotification
                CreateCustomNotification = function() end
                pcall(callback, true)
                CreateCustomNotification = _orig
                pcall(function() ApplyState(true, true) end)
                -- Liberar guard despues de que el callback termino
                if _isInvisToggle then
                    task.defer(function() _G[_fireKey] = nil end)
                end
            end)
        else
            -- Toggle no fisico (visual, setting): disparar escalonado para no saturar un frame.
            _G._autoActivateCount = (_G._autoActivateCount or 0) + 1
            local _myDelay = (_G._autoActivateCount - 1) * 0.02
            task.delay(_myDelay, function()
                local _orig = CreateCustomNotification
                CreateCustomNotification = function() end
                pcall(callback, true)
                CreateCustomNotification = _orig
                pcall(function() ApplyState(true, false) end)
                local _ln = nombre:lower()
                local _isVisualToggle = _ln:find("^esp ") or _ln:find("^cham ") or _ln:find("^box esp")
                    or _ln:find("^outline ") or _ln:find("^skeleton ") or _ln:find("^tracer ")
                    or _ln:find("^highlight ") or _ln:find("^view trap") or _ln:find("esp display")
                    or _ln:find("esp dropped") or _ln:find("esp gun") or _ln:find("esp knife")
                    or _ln:find("coin.*esp") or _ln:find("esp.*coin")
                if _isVisualToggle then
                    _G._forceInstanceTick = true
                    task.defer(function()
                        task.wait(0.12)
                        if _vcRefreshAll then pcall(_vcRefreshAll) end
                    end)
                end
            end)
        end
    end

    -- FIX MOBILE: Activated responde a touch en celu; MouseButton1Click no siempre lo hace
    clickRow.Activated:Connect(doToggle)

    -- FIX SCROLL: TextButton absorbe MouseWheel y Touch, impide scroll en PC y mobile.
    clickRow.Selectable = false
    _attachScrollPassthrough(clickRow)

    -- FIX LEAK: desconectar _dokkRainbowConn cuando el container se destruye.
    -- Sin esto, cada cambio de pesta?a deja conexiones Heartbeat huerfanas
    -- corriendo a 60Hz (una por cada toggle ON). Con 185 toggles y N cambios
    -- de pestana el numero de conexiones crece indefinidamente.
    container.Destroying:Connect(function()
        if _dokkRainbowConn then
            pcall(function() _dokkRainbowConn:Disconnect() end)
            _dokkRainbowConn = nil
        end
    end)

    return container
end

function CreateWorldColumns()
    _currentMainSectionFrame = nil
    -- FIX COLUMNAS: resetear alturas antes de crear para que _autoCol
    -- siempre produzca el mismo resultado al entrar/salir del tab
    _colHeights = {left = 0, right = 0}
    _makeTwoColumns()
end






-- CreateWorldUI_Camera removida por el usuario


function CreateWorldUI_GoldBomb()
    CreateSection(leftColumn, "", "GOLD BOMB", ThemeColors.Primary)

    _G._goldBomb = _G._goldBomb or {
        enabled    = false,
        detectConn = nil,
        charConn   = nil,
    }
    local GB = _G._goldBomb

    local GOLD_MESH_ID    = "rbxassetid://104516854"
    local GOLD_TEXTURE_ID = "rbxassetid://111999858263148"

    -- Aplica la skin dorada a un item FakeBomb (busca Handle igual que el script)
    local function actualizarBomba(item)
        local handle = item:FindFirstChild("Handle")
        if not handle then return end
        local mesh      = handle:FindFirstChildOfClass("SpecialMesh")
        local isMeshPart = handle:IsA("MeshPart")

        if mesh then
            -- Guardar originales
            if not handle:FindFirstChild("_GBOrigMeshId") then
                local t = Instance.new("StringValue"); t.Name = "_GBOrigMeshId"; t.Value = mesh.MeshId; t.Parent = handle
            end
            if not handle:FindFirstChild("_GBOrigTexId") then
                local t = Instance.new("StringValue"); t.Name = "_GBOrigTexId"; t.Value = mesh.TextureId; t.Parent = handle
            end
            mesh.MeshId    = GOLD_MESH_ID
            mesh.TextureId = GOLD_TEXTURE_ID
        elseif isMeshPart then
            if not handle:FindFirstChild("_GBOrigMeshId") then
                local t = Instance.new("StringValue"); t.Name = "_GBOrigMeshId"; t.Value = handle.MeshId; t.Parent = handle
            end
            if not handle:FindFirstChild("_GBOrigTexId") then
                local t = Instance.new("StringValue"); t.Name = "_GBOrigTexId"; t.Value = handle.TextureId; t.Parent = handle
            end
            handle.MeshId    = GOLD_MESH_ID
            handle.TextureId = GOLD_TEXTURE_ID
        end
    end

    -- Restaura la skin original
    local function restaurarBomba(item)
        local handle = item:FindFirstChild("Handle")
        if not handle then return end
        local tMesh = handle:FindFirstChild("_GBOrigMeshId")
        local tTex  = handle:FindFirstChild("_GBOrigTexId")
        local mesh  = handle:FindFirstChildOfClass("SpecialMesh")
        if mesh then
            if tMesh then mesh.MeshId    = tMesh.Value end
            if tTex  then mesh.TextureId = tTex.Value  end
        elseif handle:IsA("MeshPart") then
            if tMesh then handle.MeshId    = tMesh.Value end
            if tTex  then handle.TextureId = tTex.Value  end
        end
        if tMesh then tMesh:Destroy() end
        if tTex  then tTex:Destroy()  end
    end

    -- Escanea los mismos lugares que el script original
    local function _scanAndApply()
        local lugares = {workspace, ReplicatedStorage, game:GetService("StarterPack")}
        for _, lugar in ipairs(lugares) do
            if lugar then
                for _, obj in ipairs(lugar:GetDescendants()) do
                    if obj.Name == "FakeBomb" then
                        pcall(actualizarBomba, obj)
                    end
                end
            end
        end
    end

    local function _scanAndRestore()
        local lugares = {workspace, ReplicatedStorage, game:GetService("StarterPack")}
        for _, lugar in ipairs(lugares) do
            if lugar then
                for _, obj in ipairs(lugar:GetDescendants()) do
                    if obj.Name == "FakeBomb" then
                        pcall(restaurarBomba, obj)
                    end
                end
            end
        end
    end

    local function _startDetect()
        if GB.detectConn then pcall(function() GB.detectConn:Disconnect() end); GB.detectConn = nil end
        if GB.charConn   then pcall(function() GB.charConn:Disconnect()   end); GB.charConn   = nil end

        _scanAndApply()

        -- Detectar nuevas FakeBomb que aparezcan en runtime
        GB.detectConn = workspace.DescendantAdded:Connect(function(obj)
            if not GB.enabled then return end
            if obj.Name == "FakeBomb" then
                task.defer(function()
                    if obj and obj.Parent then pcall(actualizarBomba, obj) end
                end)
            end
        end)

        GB.charConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if GB.enabled then _scanAndApply() end
        end)
    end

    local function _stopDetect()
        if GB.detectConn then pcall(function() GB.detectConn:Disconnect() end); GB.detectConn = nil end
        if GB.charConn   then pcall(function() GB.charConn:Disconnect()   end); GB.charConn   = nil end
        _scanAndRestore()
    end

    CreateAuroraToggle(leftColumn, "Gold Bomb", function(enabled)
        GB.enabled = enabled
        if enabled then
            _startDetect()
            CreateCustomNotification("GOLD BOMB", "Activado -- bomba dorada!", 2)
        else
            _stopDetect()
            CreateCustomNotification("GOLD BOMB", "Desactivado", 1.5)
        end
    end, GB.enabled)
end

function CreateWorldUI_FakeBombCustomization()
    CreateSection(leftColumn, "", "CUSTOMIZATION -- FAKEBOMB", ThemeColors.Primary)

    _G._fbCustom = _G._fbCustom or {
        enabled    = false,
        colorR     = 180,
        colorG     = 50,
        colorB     = 255,
        detectConn = nil,
        charConn   = nil,
    }
    local S = _G._fbCustom
    local TEXTURE_ID = "rbxassetid://92015258335205"

    -- La FakeBomb en MM2 es un Handle suelto (BasePart directo en workspace, no un Tool)
    -- _applyBombSkin recibe el Handle directamente
    local function _applyBombSkin(handle)
        if not handle or not handle.Parent then return end
        if not handle:IsA("BasePart") then return end
        pcall(function()
            local mesh = handle:FindFirstChildOfClass("SpecialMesh")
            if mesh then
                -- Guardar TextureId original SOLO si no fue guardado ya
                if not handle:FindFirstChild("_FBOriginalTexId") then
                    local tag = Instance.new("StringValue")
                    tag.Name  = "_FBOriginalTexId"
                    tag.Value = mesh.TextureId
                    tag.Parent = handle
                end
                -- Reemplazar completamente el TextureId
                mesh.TextureId = TEXTURE_ID
            end
            handle.Color = Color3.fromRGB(S.colorR, S.colorG, S.colorB)
        end)
    end

    -- Quita el skin y restaura el TextureId original del Handle suelto
    local function _removeBombSkin(handle)
        if not handle then return end
        if not handle:IsA("BasePart") then return end
        pcall(function()
            local mesh = handle:FindFirstChildOfClass("SpecialMesh")
            local tag  = handle:FindFirstChild("_FBOriginalTexId")
            if mesh and tag then
                mesh.TextureId = tag.Value
            end
            if tag then tag:Destroy() end
        end)
    end

    -- Referencia al Handle suelto activo de la bomba
    local _activeBombHandle = nil

    -- Helper: determina si un objeto es el Handle suelto de la FakeBomb
    -- La FakeBomb en MM2 es un BasePart llamado "Handle" suelto en workspace,
    -- NO un Tool. El Handle del Dual Gun/Knife esta dentro del Character, no en workspace directamente.
    local function _isBombHandle(obj)
        if not obj:IsA("BasePart") then return false end
        if obj.Name ~= "Handle" then return false end
        -- El Handle de la bomba aparece directo en workspace (sin Tool padre)
        -- El Handle del Dual Gun/Knife esta dentro de un Tool dentro del Character
        local parent = obj.Parent
        if not parent then return false end
        -- Si el padre es workspace directamente -> es la bomba
        if parent == workspace then return true end
        -- Si el padre es un Model suelto en workspace (algunos mapas) -> tambien valido
        if parent:IsA("Model") and parent.Parent == workspace and
           not parent:FindFirstChildOfClass("Humanoid") then return true end
        return false
    end

    -- Escanea workspace para aplicar si la bomba ya esta activa
    local function _scanWorkspace()
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "Handle" and obj:IsA("BasePart") and _isBombHandle(obj) then
                _activeBombHandle = obj
                _applyBombSkin(obj)
                break
            end
        end
    end

    local function _startDetect()
        if S.detectConn then pcall(function() S.detectConn:Disconnect() end); S.detectConn = nil end
        if S.charConn   then pcall(function() S.charConn:Disconnect()   end); S.charConn   = nil end

        _scanWorkspace()

        -- Detectar el Handle suelto de la bomba cuando aparece en workspace
        S.detectConn = workspace.ChildAdded:Connect(function(obj)
            if not S.enabled then return end
            if not _isBombHandle(obj) then return end
            _activeBombHandle = obj
            task.defer(function()
                if obj and obj.Parent then _applyBombSkin(obj) end
            end)
        end)

        -- Re-aplicar tras cada respawn
        S.charConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.5)
            if S.enabled then _scanWorkspace() end
        end)
    end

    local function _stopDetect()
        if S.detectConn then pcall(function() S.detectConn:Disconnect() end); S.detectConn = nil end
        if S.charConn   then pcall(function() S.charConn:Disconnect()   end); S.charConn   = nil end
        if _activeBombHandle then
            _removeBombSkin(_activeBombHandle)
            _activeBombHandle = nil
        end
        -- Por si quedo algun Handle suelto en workspace con el tag
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "Handle" and obj:IsA("BasePart") and obj:FindFirstChild("_FBOriginalTexId") then
                _removeBombSkin(obj)
            end
        end
    end

    -- -- Toggle principal ------------------------------------------
    CreateAuroraToggle(leftColumn, " FakeBomb Customization", function(enabled)
        S.enabled = enabled
        if enabled then
            _startDetect()
            CreateCustomNotification("FAKEBOMB", "Customization ON -- detectando bomba!", 2.5)
        else
            _stopDetect()
            CreateCustomNotification("FAKEBOMB", "Customization OFF", 1.5)
        end
    end, S.enabled)

    -- -- Preview de color ------------------------------------------
    local previewRow = Instance.new("Frame", leftColumn)
    previewRow.Size = UDim2.new(1, -8, 0, 30)
    previewRow.BackgroundTransparency = 1
    previewRow.BorderSizePixel = 0
    local previewBox = Instance.new("Frame", previewRow)
    previewBox.Size = UDim2.new(0, 24, 0, 24)
    previewBox.Position = UDim2.new(0, 8, 0, 3)
    previewBox.BackgroundColor3 = Color3.fromRGB(S.colorR, S.colorG, S.colorB)
    previewBox.BorderSizePixel = 0
    Instance.new("UICorner", previewBox).CornerRadius = UDim.new(0, 5)
    local _pvStroke = Instance.new("UIStroke", previewBox)
    _pvStroke.Color = ThemeColors.Primary
    _pvStroke.Thickness = 1.5
    local previewLbl = Instance.new("TextLabel", previewRow)
    previewLbl.Size = UDim2.new(1, -44, 1, 0)
    previewLbl.Position = UDim2.new(0, 40, 0, 0)
    previewLbl.BackgroundTransparency = 1
    previewLbl.Text = "Color de la bomba (RGB)"
    previewLbl.TextColor3 = Color3.fromRGB(200, 200, 210)
    previewLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
    previewLbl.TextSize = 13
    previewLbl.TextXAlignment = Enum.TextXAlignment.Left

    local function _refreshColor()
        previewBox.BackgroundColor3 = Color3.fromRGB(S.colorR, S.colorG, S.colorB)
        if S.enabled then
            local char = LocalPlayer.Character
            if char then
                local fb = char:FindFirstChild("FakeBomb")
                if fb then
                    local h = fb:FindFirstChild("Handle") or fb:FindFirstChildOfClass("BasePart")
                    if h then pcall(function() h.Color = Color3.fromRGB(S.colorR, S.colorG, S.colorB) end) end
                end
            end
        end
    end

    -- -- Slider 1 -- Color R ----------------------------------------
    CreateAuroraSlider(leftColumn, "Bomb Color R", 0, 255, S.colorR, 0, function(v)
        S.colorR = math.floor(v); _refreshColor()
    end)

    -- -- Slider 2 -- Color G ----------------------------------------
    CreateAuroraSlider(leftColumn, "Bomb Color G", 0, 255, S.colorG, 0, function(v)
        S.colorG = math.floor(v); _refreshColor()
    end)

    -- -- Slider 3 -- Color B ----------------------------------------
    CreateAuroraSlider(leftColumn, "Bomb Color B", 0, 255, S.colorB, 0, function(v)
        S.colorB = math.floor(v); _refreshColor()
    end)
end
-- CreateWorldUI_Tilt removida -- causaba bug de camara giratoria (CFrame acumulativo en RenderStepped)

local function _makeTPButton(label, callback, forcedParent)
    local actualParent = forcedParent or _currentMainSectionFrame or leftColumn

    local C_BG       = ThemeColors.Background
    local C_BG_TR    = 0.05   -- transparencia normal (casi solido, igual referencia)
    local C_BG_HOV   = 0.05   -- transparencia hover
    local C_BG_CLK   = 0.05   -- transparencia click
    local C_STROKE   = ThemeColors.Primary
    local C_STROKE_CLK = ThemeColors.Accent
    local C_TEXT     = ThemeColors.TextPrimary
    local TWEEN_T    = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local TWEEN_FAST = TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

    local container = Instance.new("Frame", actualParent)
    container.Name                   = "TPBtn_" .. label
    container.Size                   = UDim2.new(1, 0, 0, 56)
    container.BackgroundTransparency = 1
    container.BorderSizePixel        = 0
    container.ZIndex                 = 20

    local btn = Instance.new("TextButton", container)
    btn.Name                    = "TPBtnInner_" .. label
    btn.Size                    = UDim2.new(1, -16, 0, 38)
    btn.Position                = UDim2.new(0, 8, 0.5, -19)
    btn.BackgroundColor3        = C_BG
    btn.BackgroundTransparency  = C_BG_TR
    btn.BorderSizePixel         = 0
    btn.Text                    = label
    btn.TextColor3              = C_TEXT
    btn.FontFace                = Font.fromEnum(Enum.Font.GothamBold)
    btn.TextSize                = 14
    btn.TextXAlignment          = Enum.TextXAlignment.Center
    btn.TextYAlignment          = Enum.TextYAlignment.Center
    btn.AutoButtonColor         = false
    btn.ZIndex                  = 21
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)  -- esquinas ligeramente redondeadas como referencia

    local stroke = Instance.new("UIStroke", btn)
    stroke.Color           = C_STROKE
    stroke.Thickness       = 1.5
    stroke.Transparency    = 0.10
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

    -- Hover: fondo mas solido
    btn.MouseEnter:Connect(function()
        TweenService:Create(btn, TWEEN_T, {BackgroundColor3 = ThemeColors.Secondary, BackgroundTransparency = C_BG_HOV}):Play()
        TweenService:Create(stroke, TWEEN_T, {Transparency = 0, Thickness = 2}):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TWEEN_T, {BackgroundColor3 = C_BG, BackgroundTransparency = C_BG_TR}):Play()
        TweenService:Create(stroke, TWEEN_T, {Transparency = 0.10, Thickness = 1.5}):Play()
    end)

    -- Click: flash rapido
    btn.Activated:Connect(function()
        TweenService:Create(btn,    TWEEN_FAST, {BackgroundColor3 = ThemeColors.Accent, BackgroundTransparency = C_BG_CLK}):Play()
        TweenService:Create(stroke, TWEEN_FAST, {Color = C_STROKE_CLK, Thickness = 2.5}):Play()
        task.wait(0.12)
        TweenService:Create(btn,    TWEEN_T, {BackgroundColor3 = C_BG, BackgroundTransparency = C_BG_TR}):Play()
        TweenService:Create(stroke, TWEEN_T, {Color = C_STROKE, Thickness = 1.5}):Play()
        if callback then callback() end
    end)

    return container
end

function CreateWorldUI_Emotes()
    local EMOTES = {
        { name = "Sit",      key = "Z", keyCode = Enum.KeyCode.Z, id = "2431845940", emoji = "[SIT]",  accent = Color3.fromRGB( 80, 200, 255) },
        { name = "Ninja",    key = "X", keyCode = Enum.KeyCode.X, id = "2431864798", emoji = "[NJA]",  accent = Color3.fromRGB(180,  60, 255) },
        { name = "Dab",      key = "C", keyCode = Enum.KeyCode.C, id = "2445521505", emoji = "[DAB]",  accent = Color3.fromRGB( 50, 255, 150) },
        { name = "Floss",    key = "V", keyCode = Enum.KeyCode.V, id = "2452938820", emoji = "[FLS]",  accent = Color3.fromRGB(255, 200,  50) },
        { name = "Headless", key = "B", keyCode = Enum.KeyCode.B, id = "2513664073", emoji = "[HDL]",  accent = Color3.fromRGB(255,  60,  80) },
        { name = "Zombie",   key = "N", keyCode = Enum.KeyCode.N, id = "2513692312", emoji = "[ZMB]",  accent = Color3.fromRGB( 80, 255,  80) },
        { name = "Zen",      key = "M", keyCode = Enum.KeyCode.M, id = "2431812646", emoji = "[ZEN]",  accent = Color3.fromRGB(255, 150, 200) },
    }

    for _, emote in ipairs(EMOTES) do
        if not WorldSystem.emote.bindable[emote.name] then
            WorldSystem.emote.bindable[emote.name] = {
                frame    = nil,
                enabled  = false,
                textSize = 10,
                sizeX    = 38,
                sizeY    = 38,
            }
        end
    end

    local EmoteState = {
        keybindsOn  = WorldSystem.emote.keybindsOn,
        currentTrack = nil,
        keyConn      = nil,
        moveConn     = nil,
        bindable     = WorldSystem.emote.bindable,
    }

    -- FIX: bindableGui eliminado (memory leak -- nunca se usaba)
    -- FIX: funciones cambiadas a local para evitar colision si el tab se recarga
    local function CreateOnScreenButton(emoteName, sizeX, sizeY, textSize, posY, callback)
        pcall(function()
            local old = CoreGui:FindFirstChild("EmoteBtn_" .. emoteName)
            if old then old:Destroy() end
        end)
        -- Destruir cualquier ScreenGui anterior con el mismo nombre
        local guiName = "EmoteBtn_" .. emoteName
        local function sweepEmote(p)
            if not p then return end
            for _, g in ipairs(p:GetChildren()) do
                if g.Name == guiName then pcall(function() g:Destroy() end) end
            end
        end
        sweepEmote(CoreGui)
        pcall(function() sweepEmote(LocalPlayer:FindFirstChild("PlayerGui")) end)

        local gui2 = Instance.new("ScreenGui")
        gui2.Name           = guiName
        gui2.ResetOnSpawn   = false
        gui2.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui2.IgnoreGuiInset = true
        gui2.DisplayOrder   = 9800
        pcall(function() gui2.Parent = CoreGui end)
        if not gui2.Parent then gui2.Parent = LocalPlayer.PlayerGui end

        local frame = MakeCapyBindableFrame(gui2, emoteName, function()
            if callback then
                local ok, err = pcall(callback)
                if not ok then
 CreateCustomNotification("EMOTE", "Error: " .. tostring(err), 3)
                end
            end
        end, 600, posY)

        frame._gui = gui2
        return frame
    end

    local function StopEmote()
        if EmoteState.currentTrack then
            pcall(function() EmoteState.currentTrack:Stop() end)
            EmoteState.currentTrack = nil
        end
        if EmoteState.moveConn then
            EmoteState.moveConn:Disconnect()
            EmoteState.moveConn = nil
        end
        if EmoteState._jumpConn then
            pcall(function() EmoteState._jumpConn:Disconnect() end)
            EmoteState._jumpConn = nil
        end
    end

    local function PlayEmote(animId, emoteName)
        StopEmote()
        local char = LocalPlayer.Character
        if not char then
 CreateCustomNotification("EMOTE", "Sin personaje.", 2); return
        end
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if not humanoid then
 CreateCustomNotification("EMOTE", "Sin Humanoid.", 2); return
        end

        local animator = humanoid:FindFirstChildOfClass("Animator")
        if not animator then
            animator = Instance.new("Animator", humanoid)
        end

        local anim = Instance.new("Animation")
        anim.AnimationId = "rbxassetid://" .. animId

        local track
        local ok, err = pcall(function()
            track = humanoid:LoadAnimation(anim)
        end)
        if not ok or not track then
 CreateCustomNotification("EMOTE", "No se pudo cargar: " .. tostring(err), 3)
            return
        end

        track:Play()
        EmoteState.currentTrack = track

        -- Detener emote si el humanoid muere o cambia de personaje
        local _emoteJumpConn = humanoid.StateChanged:Connect(function(_, newState)
            if newState == Enum.HumanoidStateType.Jumping
            or newState == Enum.HumanoidStateType.Freefall
            or newState == Enum.HumanoidStateType.Dead then
                StopEmote()
            end
        end)
        -- Guardar conexion de salto para limpiarla junto con moveConn
        local _prevMoveConn = EmoteState.moveConn
        EmoteState._jumpConn = _emoteJumpConn

        local _hbEmote = 0
        EmoteState.moveConn = RunService.Heartbeat:Connect(function()
            _hbEmote = _hbEmote + 1; if _hbEmote < 3 then return end; _hbEmote = 0
            local c3 = LocalPlayer.Character
            if not c3 then StopEmote(); return end
            local hrp2 = c3:FindFirstChild("HumanoidRootPart")
            local hum3 = c3:FindFirstChildOfClass("Humanoid")
            if not hrp2 or not hum3 then StopEmote(); return end
            -- Parar si camina (velocidad horizontal > umbral)
            local vel = hrp2.AssemblyLinearVelocity
            if vel and (vel.X*vel.X + vel.Z*vel.Z) > 1.5 then
                StopEmote(); return
            end
            -- Parar si el humanoid esta moviendo (MoveDirection activo)
            if hum3.MoveDirection.Magnitude > 0.05 then
                StopEmote(); return
            end
            -- Parar si esta en el aire (salto o caida)
            if hum3.FloorMaterial == Enum.Material.Air then
                StopEmote(); return
            end
        end)

 CreateCustomNotification("EMOTE", " " .. emoteName, 2)
    end

    -- ================================================================
    -- HEADER PREMIUM: EMOTES con banner de gradiente animado
    -- ================================================================
    local _emotesSec = CreateSection(leftColumn, "", "EMOTES", Color3.fromRGB(56, 56, 56))

    -- Banner decorativo superior para la seccion de emotes
    local _emoteBanner = Instance.new("Frame", leftColumn)
    _emoteBanner.Name = "EmotesBanner"
    _emoteBanner.Size = UDim2.new(1, -4, 0, 52)
    _emoteBanner.BackgroundColor3 = Color3.fromRGB(8, 14, 40)
    _emoteBanner.BackgroundTransparency = 0.2
    _emoteBanner.BorderSizePixel = 0
    Instance.new("UICorner", _emoteBanner).CornerRadius = UDim.new(0, 12)
    -- Stroke animado con gradiente arcoiris
    local _bannerStroke = Instance.new("UIStroke", _emoteBanner)
    _bannerStroke.Thickness = 2
    _bannerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local _bannerGrad = Instance.new("UIGradient", _bannerStroke)
    _bannerGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB( 80, 200, 255)),
        ColorSequenceKeypoint.new(0.2, Color3.fromRGB(180,  60, 255)),
        ColorSequenceKeypoint.new(0.4, Color3.fromRGB( 50, 255, 150)),
        ColorSequenceKeypoint.new(0.6, Color3.fromRGB(255, 200,  50)),
        ColorSequenceKeypoint.new(0.8, Color3.fromRGB(255,  60,  80)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB( 80, 200, 255)),
    })
    RegisterShimmer(_bannerGrad, 70, math.random(0, 359))
    -- Gradiente de fondo del banner
    local _bannerBgGrad = Instance.new("UIGradient", _emoteBanner)
    _bannerBgGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(20,  8, 60)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB( 8, 20, 50)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(25,  5, 45)),
    })
    _bannerBgGrad.Rotation = 90
    -- Icono / titulo del banner
    local _bannerTitle = Instance.new("TextLabel", _emoteBanner)
    _bannerTitle.Size = UDim2.new(1, -12, 1, 0)
    _bannerTitle.Position = UDim2.new(0, 12, 0, 0)
    _bannerTitle.BackgroundTransparency = 1
    _bannerTitle.Text = "EMOTES  [Z] [X] [C] [V] [B] [N] [M]"
    _bannerTitle.FontFace = Font.fromEnum(Enum.Font.GothamBold)
    _bannerTitle.TextSize = 13
    _bannerTitle.TextColor3 = Color3.fromRGB(220, 240, 255)
    _bannerTitle.TextXAlignment = Enum.TextXAlignment.Left
    _bannerTitle.TextYAlignment = Enum.TextYAlignment.Center
    _bannerTitle.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    _bannerTitle.TextStrokeTransparency = 0.3
    _bannerTitle.ZIndex = 15
    -- Sub-label
    local _bannerSub = Instance.new("TextLabel", _emoteBanner)
    _bannerSub.Size = UDim2.new(1, -12, 0, 16)
    _bannerSub.Position = UDim2.new(0, 12, 1, -18)
    _bannerSub.BackgroundTransparency = 1
    _bannerSub.Text = "Pulsa PLAY o usa teclas para activar"
    _bannerSub.FontFace = Font.fromEnum(Enum.Font.Gotham)
    _bannerSub.TextSize = 10
    _bannerSub.TextColor3 = Color3.fromRGB(140, 180, 220)
    _bannerSub.TextXAlignment = Enum.TextXAlignment.Left
    _bannerSub.ZIndex = 15
    -- Linea separadora decorativa bajo el banner
    local _bannerLine = Instance.new("Frame", leftColumn)
    _bannerLine.Name = "EmotesBannerLine"
    _bannerLine.Size = UDim2.new(1, -8, 0, 2)
    _bannerLine.BackgroundColor3 = Color3.fromRGB(80, 200, 255)
    _bannerLine.BackgroundTransparency = 0.4
    _bannerLine.BorderSizePixel = 0
    Instance.new("UICorner", _bannerLine).CornerRadius = UDim.new(1, 0)
    local _lineGrad = Instance.new("UIGradient", _bannerLine)
    _lineGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 0, 0)),
        ColorSequenceKeypoint.new(0.2, Color3.fromRGB(80, 200, 255)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(180, 60, 255)),
        ColorSequenceKeypoint.new(0.8, Color3.fromRGB(80, 200, 255)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(0, 0, 0)),
    })
    RegisterShimmer(_lineGrad, 55, 40)

    CreateAuroraToggle(leftColumn, "Enable All Keybinds [Z / X / C / V / B / N]", function(enabled)
        EmoteState.keybindsOn = enabled
        WorldSystem.emote.keybindsOn = enabled
        if EmoteState.keyConn then
            EmoteState.keyConn:Disconnect()
            EmoteState.keyConn = nil
        end
        if enabled then
            EmoteState.keyConn = UserInputService.InputBegan:Connect(function(input, _gameProcessed)
                for _, emote in ipairs(EMOTES) do
                    if input.KeyCode == emote.keyCode then
                        PlayEmote(emote.id, emote.name)
                        break
                    end
                end
            end)
 if not UserInputService.TouchEnabled then CreateCustomNotification("KEYBINDS ON", "Z/X/C/V/B/N activos!", 3) end
        else
            StopEmote()
        end
    end, EmoteState.keybindsOn)

    local posBaseY = 160
    for i, emote in ipairs(EMOTES) do
        local bindData = EmoteState.bindable[emote.name]
        local capturedId   = emote.id
        local capturedName = emote.name
        local cardPosY = posBaseY + (i - 1) * 52

        -- Distribuir paneles entre columna izquierda y derecha automaticamente
        local targetCol = (i % 2 == 1) and leftColumn or rightColumn

        -- ==============================================================
        -- PANEL PREMIUM -- dise?o visual mejorado con gradiente, icono de color y animaciones
        -- ==============================================================
        local emoteAccent = emote.accent or ThemeColors.Primary
        local emoteEmoji  = emote.emoji  or "[--]"

        local panel = Instance.new("Frame", targetCol)
        panel.Name                   = "EmotePanel_" .. capturedName
        panel.Size                   = UDim2.new(1, -4, 0, 0)
        panel.BackgroundColor3       = Color3.fromRGB(6, 12, 38)
        panel.BackgroundTransparency = 0.55
        panel.BorderSizePixel        = 0
        panel.AutomaticSize          = Enum.AutomaticSize.Y
        Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 12)
        -- Gradiente de fondo del panel (de color del emote hacia oscuro)
        local panelBgGrad = Instance.new("UIGradient", panel)
