        -- Funcion cleanup del boton on-screen
        local function destroyEmoteBtn()
            if bindData.frame then
                if bindData.frame._gui then pcall(function() bindData.frame._gui:Destroy() end)
                else pcall(function() bindData.frame:Destroy() end) end
                bindData.frame = nil
            end
            local guiName = "EmoteBtn_" .. capturedName
            local function sweepE(p)
                if not p then return end
                for _, g in ipairs(p:GetChildren()) do
                    if g.Name == guiName then pcall(function() g:Destroy() end) end
                end
            end
            sweepE(CoreGui)
            pcall(function() sweepE(LocalPlayer:FindFirstChild("PlayerGui")) end)
        end

        -- Forzar panel como parent para CreateAuroraToggle y CreateSlider
        local _savedSection = _currentMainSectionFrame
        _currentMainSectionFrame = panel

        -- Toggle: Enable Bindable Button
        CreateAuroraToggle(panel, "Enable " .. capturedName .. " Emote Bindable Button", function(enabled)
            bindData.enabled = enabled
            if enabled then
                destroyEmoteBtn()
                bindData.frame = CreateOnScreenButton(capturedName, bindData.sizeX, bindData.sizeY, bindData.textSize, cardPosY, function() PlayEmote(capturedId, capturedName) end)
            else
                destroyEmoteBtn()
            end
        end, bindData.enabled)

        -- Sliders
        CreateSlider(panel, capturedName .. " Emote Bind Text Size", 6, 24, bindData.textSize, function(v)
            bindData.textSize = v
            if bindData.frame then
                local lbl = bindData.frame:FindFirstChildOfClass("TextLabel")
                if lbl then lbl.TextSize = v end
            end
        end)

        CreateSlider(panel, capturedName .. " Emote Bind Size X", 20, 200, bindData.sizeX, function(v)
            bindData.sizeX = v
            if bindData.frame then bindData.frame.Size = UDim2.new(0, v, 0, bindData.sizeY) end
        end)

        CreateSlider(panel, capturedName .. " Emote Bind Size Y", 16, 100, bindData.sizeY, function(v)
            bindData.sizeY = v
            if bindData.frame then bindData.frame.Size = UDim2.new(0, bindData.sizeX, 0, v) end
        end)

        -- Dropdown shape type
        if not bindData.shapeType then bindData.shapeType = "Circle" end
        CreateNebulaSelector(panel, capturedName .. " Emote Bindable Shape Type", {"Circle","Square","Rounded"}, bindData.shapeType, function(v)
            bindData.shapeType = v
            if bindData.frame then
                local corner = bindData.frame:FindFirstChildOfClass("UICorner")
                if not corner then corner = Instance.new("UICorner", bindData.frame) end
                if v == "Circle" then corner.CornerRadius = UDim.new(1, 0) end
                if v == "Square" then corner.CornerRadius = UDim.new(0, 0) end
                if v == "Rounded" then corner.CornerRadius = UDim.new(0, 8) end
            end
        end)

        _currentMainSectionFrame = _savedSection
    end

