    _gridFrame.BackgroundTransparency = 1
    _gridFrame.BorderSizePixel   = 0
    local _gridLayout = Instance.new("UIGridLayout", _gridFrame)
    _gridLayout.CellSize          = UDim2.new(0.5, -5, 0, 46)
    _gridLayout.CellPadding       = UDim2.new(0, 5, 0, 5)
    _gridLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    _gridLayout.SortOrder         = Enum.SortOrder.LayoutOrder
    local _gridPad = Instance.new("UIPadding", _gridFrame)
    _gridPad.PaddingLeft = UDim.new(0, 2); _gridPad.PaddingRight = UDim.new(0, 2)
    _gridPad.PaddingTop = UDim.new(0, 4); _gridPad.PaddingBottom = UDim.new(0, 4)

    local _currentCatIdx = 1
    local _tabBtns = {}
    local _activeAnimBtn = nil  -- boton actualmente seleccionado

    local function _showCategory(catIdx)
        _currentCatIdx = catIdx
        _activeAnimBtn = nil
        -- Limpiar grid
        for _, c in ipairs(_gridFrame:GetChildren()) do
            if c:IsA("TextButton") or c:IsA("Frame") then c:Destroy() end
        end
        local cat = ANIM_CATEGORIES[catIdx]
        -- Resaltar tab activo
        for ti, tb in ipairs(_tabBtns) do
            if ti == catIdx then
                tb.BackgroundTransparency = 0.05
                tb.TextColor3 = Color3.fromRGB(255, 255, 255)
                TweenService:Create(tb, TweenInfo.new(0.15), {BackgroundTransparency = 0.05, TextColor3 = Color3.fromRGB(255,255,255)}):Play()
            else
                TweenService:Create(tb, TweenInfo.new(0.15), {BackgroundTransparency = 0.72, TextColor3 = Color3.fromRGB(160, 160, 160)}):Play()
            end
        end

        -- Colores base derivados del color de la categoria
        local r, g, b = cat.color.R, cat.color.G, cat.color.B
        local darkBg  = Color3.new(r*0.08 + 0.04, g*0.08 + 0.02, b*0.12 + 0.06)
        local hoverBg = Color3.new(r*0.18 + 0.06, g*0.12 + 0.03, b*0.22 + 0.08)
        local activeBg= Color3.new(r*0.30 + 0.06, g*0.18 + 0.04, b*0.35 + 0.10)

        -- Crear botones de anims
        for order, anim in ipairs(cat.anims) do
            local captured = anim
            -- Contenedor del boton
            local btnWrap = Instance.new("Frame", _gridFrame)
            btnWrap.Name              = "AnimBtnWrap_" .. anim.name
            btnWrap.LayoutOrder       = order
            btnWrap.BackgroundColor3  = darkBg
            btnWrap.BackgroundTransparency = 0.15
            btnWrap.BorderSizePixel   = 0
            Instance.new("UICorner", btnWrap).CornerRadius = UDim.new(0, 8)

            -- Stroke de borde con color de categoria
            local btnStroke = Instance.new("UIStroke", btnWrap)
            btnStroke.Color = cat.color; btnStroke.Thickness = 1.2; btnStroke.Transparency = 0.5
            btnStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            -- Franja de color superior (acento visual)
            local topBar = Instance.new("Frame", btnWrap)
            topBar.Name = "TopBar"
            topBar.Size = UDim2.new(1, 0, 0, 3)
            topBar.Position = UDim2.new(0, 0, 0, 0)
            topBar.BackgroundColor3 = cat.color
            topBar.BackgroundTransparency = 0.3
            topBar.BorderSizePixel = 0
            local topBarCorner = Instance.new("UICorner", topBar)
            topBarCorner.CornerRadius = UDim.new(0, 8)

            -- Boton invisible encima (captura clicks)
            local btn = Instance.new("TextButton", btnWrap)
            btn.Name                   = "AnimBtn_" .. anim.name
            btn.Size                   = UDim2.new(1, 0, 1, 0)
            btn.BackgroundTransparency = 1
            btn.BorderSizePixel        = 0
            btn.Text                   = ""
            btn.AutoButtonColor        = false
            btn.ZIndex                 = 5

            -- Texto del nombre (ocupa todo el ancho)
            local nameLabel = Instance.new("TextLabel", btnWrap)
            nameLabel.Name = "AnimName"
            nameLabel.Size = UDim2.new(1, -8, 1, 0)
            nameLabel.Position = UDim2.new(0, 4, 0, 0)
            nameLabel.BackgroundTransparency = 1
            nameLabel.Text = anim.name
            nameLabel.TextSize = 12
            nameLabel.Font = Enum.Font.GothamBold
            nameLabel.TextColor3 = Color3.fromRGB(210, 210, 230)
            nameLabel.TextXAlignment = Enum.TextXAlignment.Center
            nameLabel.TextYAlignment = Enum.TextYAlignment.Center
            nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
            nameLabel.ZIndex = 4

            -- Hover
            btn.MouseEnter:Connect(function()
                TweenService:Create(btnWrap, TweenInfo.new(0.13), {BackgroundColor3 = hoverBg, BackgroundTransparency = 0.05}):Play()
                TweenService:Create(btnStroke, TweenInfo.new(0.13), {Transparency = 0.1, Thickness = 1.8}):Play()
                TweenService:Create(nameLabel, TweenInfo.new(0.13), {TextColor3 = Color3.fromRGB(255,255,255)}):Play()
            end)
            btn.MouseLeave:Connect(function()
                if _activeAnimBtn ~= btnWrap then
                    TweenService:Create(btnWrap, TweenInfo.new(0.13), {BackgroundColor3 = darkBg, BackgroundTransparency = 0.15}):Play()
                    TweenService:Create(btnStroke, TweenInfo.new(0.13), {Transparency = 0.5, Thickness = 1.2}):Play()
                    TweenService:Create(nameLabel, TweenInfo.new(0.13), {TextColor3 = Color3.fromRGB(210,210,230)}):Play()
                end
            end)

            -- Click: marcar como activo + aplicar
            btn.Activated:Connect(function()
                -- Desmarcar anterior
                if _activeAnimBtn and _activeAnimBtn ~= btnWrap and _activeAnimBtn.Parent then
                    TweenService:Create(_activeAnimBtn, TweenInfo.new(0.15), {BackgroundColor3 = darkBg, BackgroundTransparency = 0.15}):Play()
                    local prevStroke = _activeAnimBtn:FindFirstChildOfClass("UIStroke")
                    if prevStroke then TweenService:Create(prevStroke, TweenInfo.new(0.15), {Transparency = 0.5, Thickness = 1.2}):Play() end
                    local prevName = _activeAnimBtn:FindFirstChild("AnimName")
                    if prevName then TweenService:Create(prevName, TweenInfo.new(0.15), {TextColor3 = Color3.fromRGB(210,210,230)}):Play() end
                end
                -- Marcar este como activo
                _activeAnimBtn = btnWrap
                TweenService:Create(btnWrap, TweenInfo.new(0.1, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                    {BackgroundColor3 = activeBg, BackgroundTransparency = 0}):Play()
                TweenService:Create(btnStroke, TweenInfo.new(0.1), {Transparency = 0, Thickness = 2.0}):Play()
                TweenService:Create(nameLabel, TweenInfo.new(0.1), {TextColor3 = Color3.fromRGB(255,255,255)}):Play()
                -- Aplicar animacion
                _applyAnimation(captured)
            end)
        end
    end

    -- Crear tabs
    for i, cat in ipairs(ANIM_CATEGORIES) do
        local capturedIdx = i
        local tb = Instance.new("TextButton", _tabRow)
        tb.Name                   = "Tab_" .. cat.name
        tb.Size                   = UDim2.new(0, 72, 1, 0)
        tb.BackgroundColor3       = cat.color
        tb.BackgroundTransparency = 0.7
        tb.BorderSizePixel        = 0
        tb.Text                   = cat.name
        tb.TextColor3             = Color3.fromRGB(180, 180, 180)
        tb.TextSize               = 11
        tb.Font                   = Enum.Font.Montserrat
        tb.AutoButtonColor        = false
        Instance.new("UICorner", tb).CornerRadius = UDim.new(0, 6)
        tb.Activated:Connect(function() _showCategory(capturedIdx) end)
        _tabBtns[i] = tb
    end

    -- Mostrar primera categoria por defecto
    _showCategory(1)

end

-- =============================================
-- SHERIFF FLING ULTRA -- Sistema completo (reemplaza Steal Gun UI)
-- Flingea al sheriff. Si lo saca volando o pasan >7s -> TP a ultima pose.
-- No continua el fling una vez que lo saco.
-- =============================================
_G._sfuState = {
    enabled        = false,
    flingConn      = nil,
    lastSheriffPos = nil,
    flingStart     = 0,
    flingedOut     = false,
    lastMyPos      = nil,
    timeoutSec     = 7,
}

function _sfuFindSheriff()
    for _, p in ipairs(_cachedPlayers) do
        if p == LocalPlayer then continue end
        local c = p.Character
        if not c then continue end
        local hum = c:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then continue end
        local function hasGun(container)
            if not container then return false end
            for _, t in ipairs(container:GetChildren()) do
                if t:IsA("Tool") then
                    local n = t.Name:lower()
                    if n:find("gun") or n:find("revolver") or n:find("pistol") or n:find("sheriff") then
                        return true
                    end
                end
            end
            return false
        end
        if hasGun(c) or hasGun(p.Backpack) then return p end
    end
    return nil
end

function _sfuTP(hrp, pos)
    if not hrp or not hrp.Parent then return end
    pcall(function()
        hrp.CFrame = CFrame.new(pos)
        hrp.AssemblyLinearVelocity  = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)
end

function _sfuStop()
    _G._sfuState.enabled = false
    if _G._sfuState.flingConn then
        pcall(function() _G._sfuState.flingConn:Disconnect() end)
        _G._sfuState.flingConn = nil
    end
    pcall(function()
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if hum then hum.PlatformStand = false end
        if hrp then
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.AssemblyLinearVelocity  = Vector3.zero
        end
        if char then
            for _, v in ipairs(char:GetDescendants()) do
                if v:IsA("BasePart") then pcall(function() v.CanCollide = true end) end
            end
        end
    end)
end

function _sfuStart()
    _sfuStop()
    _G._sfuState.enabled     = true
    _G._sfuState.flingedOut  = false
    _G._sfuState.flingStart  = tick()
    _G._sfuState.lastMyPos   = nil
    _G._sfuState.lastSheriffPos = nil

    local SIZE      = 2.5
    local ROT_POWER = 400000
    local SPEED     = 0.025
    local index     = 1
    local lastTk    = 0
    local offsets   = {
        Vector3.new( SIZE, 0,  SIZE), Vector3.zero,
        Vector3.new( SIZE, 0, -SIZE), Vector3.zero,
        Vector3.new(-SIZE, 0, -SIZE), Vector3.zero,
        Vector3.new(-SIZE, 0,  SIZE), Vector3.zero,
    }

    _G._sfuState.flingConn = RunService.PostSimulation:Connect(function()
        if not _G._sfuState.enabled then _sfuStop(); return end

        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        -- Guardar ultima posicion propia ANTES de movernos
        _G._sfuState.lastMyPos = hrp.Position

        -- Si detectamos fling exitoso en frame anterior -> TP y parar
        if _G._sfuState.flingedOut then
            local savedPos = _G._sfuState.lastMyPos
            _sfuStop()
            if savedPos then _sfuTP(hrp, savedPos) end
            CreateCustomNotification("FLING SHERIFF", "Sacado -- TP a ultima pose", 2)
            return
        end

        local sheriff = _sfuFindSheriff()
        if not sheriff or not sheriff.Character then
            local savedPos = _G._sfuState.lastMyPos
            _sfuStop()
            if savedPos then _sfuTP(hrp, savedPos) end
            CreateCustomNotification("FLING SHERIFF", "Sheriff no encontrado -- TP", 2)
            return
        end

        local shChar = sheriff.Character
        local shHRP  = shChar:FindFirstChild("HumanoidRootPart")
        local shHum  = shChar:FindFirstChildOfClass("Humanoid")
        if not shHRP or not shHum or shHum.Health <= 0 then
            local savedPos = _G._sfuState.lastMyPos
            _sfuStop()
            if savedPos then _sfuTP(hrp, savedPos) end
            CreateCustomNotification("FLING SHERIFF", "Sheriff fuera -- TP", 2)
            return
        end

        local prevShPos = _G._sfuState.lastSheriffPos
        _G._sfuState.lastSheriffPos = shHRP.Position

        -- Detectar si ya lo saco volando
        local shVel        = shHRP.AssemblyLinearVelocity or Vector3.zero
        local flingedSpeed = shVel.Magnitude > 200
        local flingedDist  = prevShPos ~= nil and (prevShPos - shHRP.Position).Magnitude > 25
        local timedOut     = (tick() - _G._sfuState.flingStart) > (_G._sfuState.timeoutSec or 7)

        if flingedSpeed or flingedDist or timedOut then
            _G._sfuState.flingedOut = true
            return  -- proximo frame hace TP y para
        end

        -- Noclip mientras flingea
        for _, v in ipairs(char:GetDescendants()) do
            if v:IsA("BasePart") then pcall(function() v.CanCollide = false end) end
        end
        hum.PlatformStand = true

        if tick() - lastTk >= SPEED then
            index = index + 1
            if index > #offsets then index = 1 end
            lastTk = tick()
        end

        local prediction = shHRP.AssemblyLinearVelocity * 0.08
        hrp.CFrame = shHRP.CFrame * CFrame.new(offsets[index]) + prediction
        hrp.AssemblyAngularVelocity = Vector3.new(0, ROT_POWER, 0)
        hrp.AssemblyLinearVelocity  = (shHRP.Position - hrp.Position).Unit * 600 + Vector3.new(0, 50, 0)
    end)
end

-- =============================================
-- ORBIT PLAYER -- Orbitar a un jugador especifico
-- Toggle principal, bindable, sliders de configuracion
-- =============================================
function CreateWorldUI_OrbitPlayer()
    local _opSec = CreateSection(leftColumn, "", "ORBIT PLAYER", ThemeColors.Aurora2)

    -- Estado global persistente
    _G._worldOrbitPlayer = _G._worldOrbitPlayer or {
        active        = false,
        targetName    = nil,
        speed         = 5,
        distOffset    = 6,
        conn          = nil,
        noclipConn    = nil,
        bindTextSize  = 10,
        bindSizeX     = 38,
        bindSizeY     = 38,
    }
    local _op = _G._worldOrbitPlayer

    -- Helpers
    local function _stopOrbitPlayer()
        _op.active = false
        if _op.conn      then pcall(function() _op.conn:Disconnect()      end); _op.conn      = nil end
        if _op.noclipConn then pcall(function() _op.noclipConn:Disconnect() end); _op.noclipConn = nil end
    end

    local function _startOrbitPlayer()
        _stopOrbitPlayer()
        local tName = _op.targetName
        if not tName or tName == "N/A" then
            CreateCustomNotification("ORBIT PLAYER", "Selecciona un jugador primero", 3)
            return
        end
        local target = Players:FindFirstChild(tName)
        if not target then
            CreateCustomNotification("ORBIT PLAYER", "Jugador no encontrado: " .. tName, 3)
            return
        end
        _op.active = true

        -- Noclip del char local
        local _opNcTick = 0
        _op.noclipConn = RunService.Stepped:Connect(function()
            if not _op.active then return end
            _opNcTick = _opNcTick + 1; if _opNcTick < 6 then return end; _opNcTick = 0  -- OPT: throttle ~10Hz, noclip no necesita 60fps
            local char = LocalPlayer.Character
            if not char then return end
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then pcall(function() p.CanCollide = false end) end
            end
        end)

        local _angle = 0
        local _opHbTick = 0
        _op.conn = RunService.Heartbeat:Connect(function(dt)
            if not _op.active then return end
            _opHbTick = _opHbTick + 1; if _opHbTick < 2 then return end; _opHbTick = 0  -- OPT: throttle ~30Hz, suficiente para orbita suave
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local tChar = target.Character
            local tHRP  = tChar and tChar:FindFirstChild("HumanoidRootPart")
            if not tHRP then return end
            _angle = _angle + dt * _op.speed
            local r = _op.distOffset
            local offset = Vector3.new(math.cos(_angle) * r, 0, math.sin(_angle) * r)
            pcall(function()
                hrp.CFrame = CFrame.new(tHRP.Position + offset, tHRP.Position)
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end)
        CreateCustomNotification("ORBIT PLAYER", "Orbitando a " .. tName, 2)
    end

    -- -- Toggle principal ----------------------------------------------
    CreateAuroraToggle(_opSec, "Orbit Player", function(on)
        if on then _startOrbitPlayer() else _stopOrbitPlayer() end
    end, _op.active)

    -- -- Bindable toggle -----------------------------------------------
    do
        local _obBind = _G._obBind or { enabled = false, gui = nil }
        _G._obBind = _obBind

        CreateAuroraToggle(_opSec, "Enable OB Bindable Button", function(on)
            _obBind.enabled = on
            if _obBind.gui then
                pcall(function() _obBind.gui:Destroy() end); _obBind.gui = nil
                DestroyCapyBind("ORBIT PLYR")
            end
            if on then
                local sg = Instance.new("ScreenGui")
                sg.Name = "OrbitPlayerBind"; sg.ResetOnSpawn = false
                sg.IgnoreGuiInset = true; sg.DisplayOrder = 9850
                pcall(function() sg.Parent = CoreGui end)
                if not sg.Parent then sg.Parent = LocalPlayer:WaitForChild("PlayerGui") end
                _obBind.gui = sg
                MakeCapyBindableFrame(sg, "ORBIT PLYR", function()
                    _op.active = not _op.active
                    if _op.active then _startOrbitPlayer() else _stopOrbitPlayer() end
                    -- [notif removed]
                end, _op.bindSizeX, _op.bindSizeY)
                CreateCustomNotification("OB BIND", "Bindable ON", 2)
            else
                CreateCustomNotification("OB BIND", "Bindable OFF", 2)
            end
        end, _obBind.enabled)
    end

    -- -- Slider: Orbit Bind Text Size ---------------------------------
    CreateSlider(_opSec, "Orbit Player Bind Text Size", 6, 28, _op.bindTextSize, function(v)
        _op.bindTextSize = v
    end)

    -- -- Slider: Orbit Bind Size X -------------------------------------
    CreateSlider(_opSec, "Orbit Player Bind Size X", 20, 100, _op.bindSizeX, function(v)
        _op.bindSizeX = v
    end)

    -- -- Slider: Orbit Player Bind Size Y -----------------------------
    CreateSlider(_opSec, "Orbit Player Bind Size Y", 20, 100, _op.bindSizeY, function(v)
        _op.bindSizeY = v
    end)

    -- -- Select Player dropdown ----------------------------------------
    local _playerNames = {"N/A"}
    for _, p in ipairs(_cachedPlayers) do
        if p ~= LocalPlayer then table.insert(_playerNames, p.Name) end
    end

    CreateNebulaSelector(_opSec, "Select Player", _playerNames, _op.targetName or "N/A", function(name)
        _op.targetName = (name == "N/A") and nil or name
        -- Si orbit esta activo, reiniciarlo con el nuevo target
        if _op.active then _startOrbitPlayer() end
    end)

    -- -- Slider: Orbit Speed -------------------------------------------
    CreateSlider(_opSec, "Orbit Speed", 1, 20, _op.speed, function(v)
        _op.speed = v
    end)

    -- -- Slider: Orbit Distance Offset --------------------------------
    CreateSlider(_opSec, "Orbit Distance Offset", 1, 30, _op.distOffset, function(v)
        _op.distOffset = v
    end)
end

-- =============================================
-- FLING ORBIT SHERIFF -- AUTO-LOOP + STEAL GUN (una sola vez)
-- =============================================
function CreateWorldUI_FlingOrbit()


    local FOS = {
        active         = false,
        loopEnabled    = false,   -- toggle de loop continuo
        autoGrabGun    = true,
        savedPos       = nil,     -- posicion guardada al activar
        watchConn      = nil,
        dropConn       = nil,
        loopConn       = nil,
    }

    -- -- Helpers ------------------------------------------------------------
    local function _hasGun()
        -- FIX: busca TODOS los nombres de gun que usa MM2, no solo "Gun"
        local char = LocalPlayer.Character
        local bp   = LocalPlayer.Backpack
        local _gunNames = {Gun=true, SheriffGun=true, HeroGun=true, GunModel=true,
                           Revolver=true, Pistol=true, Sheriff=true}
        local function _check(container)
            if not container then return false end
            for _, t in ipairs(container:GetChildren()) do
                if t:IsA("Tool") then
                    if _gunNames[t.Name] or t.Name:lower():find("gun")
                    or t.Name:lower():find("revolver") or t.Name:lower():find("pistol") then
                        return true
                    end
                end
            end
            return false
        end
        return _check(char) or _check(bp)
    end

    local function _sheriffFlinged(hrp)
        if not hrp or not hrp.Parent then return true end
        -- FIX: bajar umbrales -- 150 studs/s es suficiente para considerar flingeado
        -- 800 era demasiado alto y a veces no detectaba
        return hrp.Position.Y < -60 or hrp.Position.Y > 1200
            or hrp.AssemblyLinearVelocity.Magnitude > 150
    end

    -- -- Grab gun invisible (blink, grab, volver) ---------------------------
    local function _grabGunInvisible(child)
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum or hum.Health <= 0 then return false end
        local handle = child:FindFirstChild("Handle") or child:FindFirstChildWhichIsA("BasePart")
        if not handle then return false end
        -- TP la gun al jugador en vez de mover al jugador
        pcall(function() handle.CFrame = CFrame.new(hrp.Position) end)
        pcall(function() child:PivotTo(CFrame.new(hrp.Position)) end)
        pcall(function()
            firetouchinterest(hrp, handle, 0); task.wait(0.016)
            firetouchinterest(hrp, handle, 1)
        end)
        task.wait(0.1)
        if not _hasGun() and handle.Parent then
            -- Re-TP y reintentar
            pcall(function() handle.CFrame = CFrame.new(hrp.Position) end)
            pcall(function() child:PivotTo(CFrame.new(hrp.Position)) end)
            task.wait(0.02)
            pcall(function()
                firetouchinterest(hrp, handle, 0); task.wait(0.02)
                firetouchinterest(hrp, handle, 1)
            end)
            task.wait(0.016)
        end
        local tries = 0
        while not _hasGun() and tries < 8 and handle and handle.Parent do
            tries = tries + 1; task.wait(0.08)
            pcall(function() handle.CFrame = CFrame.new(hrp.Position) end)
            pcall(function()
                firetouchinterest(hrp, handle, 0); task.wait(0.02)
                firetouchinterest(hrp, handle, 1)
            end)
        end
        return _hasGun()
    end

    -- -- Espera GunDrop con timeout ------------------------------------------
    local function _waitForGunDrop(timeoutSec, onFound)
        -- FIX: detectar la gun dropeada con TODOS los nombres posibles que usa MM2
        -- En MM2 la gun puede aparecer como: GunDrop, DropGun, Gun, SheriffGun, HeroGun,
        -- o como un Tool suelto en workspace (sin parent con Humanoid)
        local _dropNames = {GunDrop=true, DropGun=true, Gun=true, SheriffGun=true,
                            HeroGun=true, GunModel=true, Revolver=true, Pistol=true}
        local function _isGunDrop(obj)
            if not obj or not obj:IsA("Tool") then return false end
            local n = obj.Name
            if not (_dropNames[n] or n:lower():find("gun") or n:lower():find("revolver")) then return false end
            -- No debe estar equipada por alguien (no debe tener ancestro con Humanoid)
            local p = obj.Parent
            if p and p:IsA("Model") then
                if p:FindFirstChildOfClass("Humanoid") then return false end  -- equipada
            end
            -- Debe estar en workspace directamente o en un Model del workspace
            if obj:IsDescendantOf(workspace) then return true end
            return false
        end

        -- Comprobar si ya hay gun drop en workspace
        for _, obj in ipairs(workspace:GetDescendants()) do
            if _isGunDrop(obj) then
                onFound(obj); return
            end
        end
        local conn
        local done = false
        conn = workspace.DescendantAdded:Connect(function(child)
            if done then return end
            if _isGunDrop(child) then
                done = true
                if conn then conn:Disconnect(); conn = nil end
                task.spawn(function() task.wait(0.08); onFound(child) end)
            end
        end)
        task.delay(timeoutSec, function()
            if not done then
                done = true
                if conn then conn:Disconnect(); conn = nil end
                CreateCustomNotification("STEAL GUN", "Timeout -- gun no aparecio en " .. timeoutSec .. "s", 3)
            end
        end)
    end

    -- -- TP al mapa y tp de vuelta a saved pos ------------------------------
    local function _tpToMap()
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local ok = pcall(TeleportToMap)
        if not ok then
            -- fallback: buscar spawn en workspace
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("SpawnLocation") or (obj:IsA("BasePart") and obj.Name:lower():find("spawn")) then
                    hrp.CFrame = CFrame.new(obj.Position + Vector3.new(0, 5, 0))
                    return true
                end
            end
        end
        return true
    end

    -- -- Parar todo ---------------------------------------------------------
    local function _stopAll(tpBack)
        FOS.active = false; FOS.loopEnabled = false
        FlingSystem.flingSheriff = false; FlingSystem.flingAll = false
        FlingSystem.flingMurder = false; FlingSystem.flingInnocent = false
        _flingStopLoop()
        for _, k in ipairs({"watchConn","dropConn","loopConn"}) do
            if FOS[k] then pcall(function() FOS[k]:Disconnect() end); FOS[k] = nil end
        end
        if tpBack and FOS.savedPos then
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                task.spawn(function()
                    task.wait(0.1)
                    pcall(function() hrp.CFrame = FOS.savedPos end)
                end)
            end
        end
 CreateCustomNotification("FLING ORBIT", "Detenido" .. (tpBack and " -- TP a ultima posicion" or ""), 2)
    end

    -- -- Un ciclo de fling ---------------------------------------------------
    local function _doOneFlingCycle(onDone)
        local sheriff = findSheriffPlayer and findSheriffPlayer()
        if not sheriff or not sheriff.Character then
 CreateCustomNotification("FLING ORBIT", "Sheriff no encontrado", 3)
            onDone(false); return
        end
        local shHRP = sheriff.Character:FindFirstChild("HumanoidRootPart")
        if not shHRP then onDone(false); return end
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then onDone(false); return end

        -- TP cerca del sheriff y fling
        pcall(function() myHRP.CFrame = CFrame.new(shHRP.Position + Vector3.new(0, 2, 0)) end)
        task.wait(0.016)
        FlingSystem.flingSheriff = true; FlingSystem.flingAll = false
        FlingSystem.flingMurder = false; FlingSystem.flingInnocent = false
        _flingStartLoop()
 CreateCustomNotification("FLING ORBIT", "Flingeando a " .. sheriff.Name, 3)

        -- Esperar que salga volando (max 10s)
        local elapsed = 0
        local detected = false
        while elapsed < 10 and FOS.active do
            task.wait(0.25); elapsed = elapsed + 0.25
            local curSheriff = findSheriffPlayer and findSheriffPlayer()
            local curHRP = curSheriff and curSheriff.Character and curSheriff.Character:FindFirstChild("HumanoidRootPart")
            if _sheriffFlinged(curHRP) then
                detected = true; break
            end
        end

        FlingSystem.flingSheriff = false; _flingStopLoop()

        if not detected or not FOS.active then onDone(false); return end

        -- Esperar 3 segundos tras detectar el fling
 CreateCustomNotification("FLING ORBIT", "!Sheriff flingeado! Esperando 3s...", 3)
        task.wait(3)
        if not FOS.active then onDone(false); return end

        -- TP al mapa
        _tpToMap()
 CreateCustomNotification("FLING ORBIT", "TP al mapa ", 2)
        task.wait(0.5)
        onDone(true)
    end

    -- -- Iniciar fling (modo loop o single) ---------------------------------
    local function _startFlingOrbit(loop)
        if FOS.active then
 CreateCustomNotification("FLING ORBIT", "Ya esta activo", 2); return
        end
        -- Guardar posicion actual
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if myHRP then FOS.savedPos = myHRP.CFrame end

        FOS.active = true; FOS.loopEnabled = loop

        task.spawn(function()
            repeat
                local success = false
                local done = false
                _doOneFlingCycle(function(ok)
                    success = ok; done = true
                end)
                -- Wait for cycle to complete
                while not done do task.wait(0.1) end
                if not FOS.active then break end

                if success and FOS.loopEnabled then
                    -- Grab gun if wanted
                    if FOS.autoGrabGun and not _hasGun() then
 CreateCustomNotification("FLING ORBIT", "Esperando GunDrop...", 2)
                        local grabbed = false
                        _waitForGunDrop(8, function(drop)
                            task.spawn(function()
                                local ok2 = _grabGunInvisible(drop)
 CreateCustomNotification("FLING ORBIT", ok2 and " Gun agarrada!" or "Sin gun", 2)
                                grabbed = true
                            end)
                        end)
                        -- Wait up to 9s for grab
                        local tw = 0
                        while not grabbed and tw < 9 do task.wait(0.2); tw = tw + 0.2 end
                    end
                    if not FOS.active then break end
                    -- Esperar 2 segundos antes del proximo fling
 CreateCustomNotification("FLING ORBIT", "Siguiente fling en 2s...", 2)
                    task.wait(2)
                    if not FOS.active then break end
                end
            until not FOS.active or not FOS.loopEnabled or not success

            if FOS.active then
                -- Ciclo terminado (single o fallo)
                FOS.active = false
                FlingSystem.flingSheriff = false; _flingStopLoop()
            end
        end)
    end





end


-- QUICK FLING BUTTONS
-- FIX: _SG_DROP_NAMES/_SG_GUN_NAMES hoisted here (used at line 32088, defined originally at ~37476)
local _SG_GUN_NAMES  = {Gun=true, SheriffGun=true, HeroGun=true,
                        GunModel=true, Revolver=true, Pistol=true,
                        GunDrop=true, DropGun=true}
local _SG_DROP_NAMES = {GunDrop=true, DropGun=true, Gun=true,
                        SheriffGun=true, HeroGun=true}

function CreateWorldUI_QuickFlingButtons()
    local _qfSection = CreateSection(leftColumn, "", "QUICK FLING", ThemeColors.Aurora2)

    local _qfState = {
        flingAllActive    = false,
        flingMurderActive = false,
        stealGunActive    = false,
    }
    -- FIX v14: exponer al global para que _sgFlingPlayer pueda resetear stealGunActive
    _G._qfStateRef = _qfState

    local function _qfStopAll()
        -- Resetear todos los estados de UI
        _qfState.flingAllActive    = false
        _qfState.flingMurderActive = false
        _qfState.stealGunActive    = false
        -- Resetear todos los flags del sistema de fling
        FlingSystem.flingAll       = false
        FlingSystem.flingMurder    = false
        FlingSystem.flingSheriff   = false
        FlingSystem.flingInnocent  = false
        FlingSystem.specificTarget = nil
        -- Liberar guards para que los proximos flings arranquen limpios
        _flingActive    = false
        _flingReturning = false
        -- Parar el loop de fling automatico
        StopFlingSystem()
        -- Limpiar StealGun
        StealGunSystem.enabled = false
        if StealGunSystem._sgCacheConn then
            pcall(function() StealGunSystem._sgCacheConn:Disconnect() end)
            StealGunSystem._sgCacheConn = nil
        end
        if StealGunSystem._sgRemoveConn then
            pcall(function() StealGunSystem._sgRemoveConn:Disconnect() end)
            StealGunSystem._sgRemoveConn = nil
        end
    end

    -- BOTON: FLING A TODOS
    CreateButton(leftColumn, ">> FLING A TODOS", ThemeColors.Aurora2, function()
        if _qfState.flingAllActive then
            _qfState.flingAllActive = false
            FlingSystem.flingAll = false
            StopFlingSystem()
            CreateCustomNotification("FLING A TODOS", "Desactivado", 2)
        else
            _qfStopAll()
            _qfState.flingAllActive   = true
            FlingSystem.flingAll      = true
            FlingSystem.flingMurder   = false
            FlingSystem.flingSheriff  = false
            FlingSystem.flingInnocent = false
            FlingSystem.specificTarget = nil
            _flingStartLoop()
            CreateCustomNotification("FLING A TODOS", "Activo - lanzando a todos", 3)
        end
    end)

    -- BOTON: FLING MURDER
    CreateButton(leftColumn, ">> FLING MURDER", ThemeColors.Aurora3, function()
        if _qfState.flingMurderActive then
            -- Cancelar manualmente
            _qfState.flingMurderActive = false
            FlingSystem.flingMurder = false
            _flingActive    = false
            _flingReturning = false
            StopFlingSystem()
            CreateCustomNotification("FLING MURDER", "Desactivado", 2)
        else
            _refreshRoleCache()
            local murder = _roleCache and _roleCache.murderer
            if not murder then
                CreateCustomNotification("FLING MURDER", "Murderer no detectado - activa en ronda activa", 3)
                return
            end
            _qfStopAll()
            _flingActive    = false
            _flingReturning = false
            _qfState.flingMurderActive = true
            FlingSystem.flingMurder    = true
            FlingSystem.flingAll       = false
            FlingSystem.flingSheriff   = false
            FlingSystem.flingInnocent  = false
            FlingSystem.specificTarget = nil
            CreateCustomNotification("FLING MURDER", "Flingeando a " .. murder.Name .. " por 5s...", 3)
            task.spawn(function()
                -- Obtener HRP del murder al momento de ejecutar
                local tChar = murder.Character
                local tHRP  = tChar and tChar:FindFirstChild("HumanoidRootPart")
                if not tHRP then
                    _qfState.flingMurderActive = false
                    FlingSystem.flingMurder    = false
                    _flingActive               = false
                    CreateCustomNotification("FLING MURDER", "Murder sin character", 2)
                    return
                end

                -- == STICKY FLING por 5 segundos usando la misma logica que flingAll ==
                local myChar = LocalPlayer.Character
                local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
                if not myHRP or not myHum then
                    _qfState.flingMurderActive = false
                    FlingSystem.flingMurder    = false
                    return
                end

                -- Capturar posicion segura antes de empezar
                local _fmSafePos = nil
                local _ry = myHRP.Position.Y
                if _ry > 2 and _ry < 800 then
                    _fmSafePos = myHRP.CFrame
                    _G.OldPos  = _fmSafePos
                    _flingLastSafePos = _fmSafePos
                end

                -- == STICKY FLING por 5 segundos -- misma logica exacta que _stickyFlingOne ==
                -- Nos metemos en el cuerpo del murder y aplicamos velocidad en NUESTRO HRP
                local _RS = game:GetService("RunService")
                local _launched = false
                local _fmConn
                local _timeStart = tick()

                local function _fmZeroSelf()
                    for _p = 1, 3 do
                        pcall(function()
                            myHRP.AssemblyLinearVelocity  = Vector3.zero
                            myHRP.AssemblyAngularVelocity = Vector3.zero
                            myHRP.Velocity    = Vector3.zero
                            myHRP.RotVelocity = Vector3.zero
                        end)
                    end
                end

                pcall(function() myHum.PlatformStand = true end)

                _fmConn = _RS.Heartbeat:Connect(function()
                    if not tHRP or not tHRP.Parent then
                        _launched = true
                        _fmZeroSelf()
                        if _fmConn then _fmConn:Disconnect(); _fmConn = nil end
                        return
                    end
                    local tVel = tHRP.AssemblyLinearVelocity.Magnitude
                    if tVel > 120 or tick() - _timeStart >= 5 then
                        _launched = true
                        _fmZeroSelf()
                        pcall(function() myHum.PlatformStand = false end)
                        if _fmConn then _fmConn:Disconnect(); _fmConn = nil end
                        return
                    end
                    if not _qfState.flingMurderActive then
                        _launched = true
                        _fmZeroSelf()
                        if _fmConn then _fmConn:Disconnect(); _fmConn = nil end
                        return
                    end
                    -- Meterme en el cuerpo del murder y aplicar velocidad en MI HRP
                    pcall(function()
                        myHRP.CFrame = tHRP.CFrame
                        myChar:SetPrimaryPartCFrame(tHRP.CFrame)
                    end)
                    pcall(function()
                        myHRP.AssemblyLinearVelocity  = Vector3.new(0, 50000, 0)
                        myHRP.AssemblyAngularVelocity = Vector3.new(50000, 50000, 50000)
                    end)
                end)

                -- Esperar hasta que terminen los 5 segundos o el murder salga volando
                local _waited = 0
                repeat
                    task.wait(0.016)
                    _waited = _waited + 0.05
                until _launched or _waited > 6

                if _fmConn then _fmConn:Disconnect(); _fmConn = nil end
                -- Triple zereo post-loop igual que _stickyFlingOne
                pcall(function()
                    myHRP.AssemblyLinearVelocity  = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                    myHRP.Velocity    = Vector3.zero
                    myHRP.RotVelocity = Vector3.zero
                    myHum.PlatformStand = false
                end)
                task.wait(0.016)
                pcall(function()
                    myHRP.AssemblyLinearVelocity  = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                end)
                -- Limpiar estado
                _qfState.flingMurderActive = false
                FlingSystem.flingMurder    = false
                _flingActive               = false
                _flingReturning            = false

                -- TP al mapa usando la deteccion de World tab
                CreateCustomNotification("FLING MURDER", "Fling terminado - volviendo al mapa...", 2)
                task.wait(0.2)
                TeleportToMap()
            end)
        end
    end)

    -- BINDABLE: STEAL GUN
    do
        local _sgBind = { gui = nil, frame = nil }
        CreateToggle(leftColumn, "Steal Gun Bindable Button", false, function(on)
            if _sgBind.gui then pcall(function() _sgBind.gui:Destroy() end) _sgBind.gui = nil end
            _sgBind.frame = nil
            if on then
                local sg = Instance.new("ScreenGui")
                sg.Name = "StealGunBindable"; sg.ResetOnSpawn = false
                pcall(function() sg.Parent = game:GetService("CoreGui") end)
                if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
                _sgBind.gui = sg
                -- FIX: capturar frame para SetActiveState
                local _sgFrame = MakeCapyBindableFrame(sg, "STEAL\nGUN", function()
                    -- FIX BINDABLE: usar _G._qfStateRef en vez del _qfState local del closure
                    -- El closure captura el _qfState de la instancia de CreateWorldUI_QuickFlingButtons
                    -- que creo este toggle. Si el World tab se reconstruye, se crea un nuevo _qfState
                    -- local pero el bindable (en CoreGui) todavia referencia el viejo. Usar el ref
                    -- global garantiza que siempre apuntamos al _qfState activo.
                    local _qs = _G._qfStateRef or _qfState
                    if _qs.stealGunActive then
                        -- Desactivar
                        _qs.stealGunActive = false
                        StealGunSystem.enabled  = false
                        _flingActive = false; _flingReturning = false
                        if StealGunSystem._sgCacheConn  then pcall(function() StealGunSystem._sgCacheConn:Disconnect()  end) StealGunSystem._sgCacheConn  = nil end
                        if StealGunSystem._sgRemoveConn then pcall(function() StealGunSystem._sgRemoveConn:Disconnect() end) StealGunSystem._sgRemoveConn = nil end
                        -- FIX VISUAL: reflejar estado inactivo
                        pcall(function() if _sgBind.frame then _sgBind.frame:SetActiveState(false) end end)
                        CreateCustomNotification("STEAL GUN", "Desactivado", 2)
                    else
                        -- Detectar portador de gun
                        -- FIX: usar el _qfStopAll del ref global si el local ya no es valido
                        if _G._qfStateRef then
                            _G._qfStateRef.flingAllActive    = false
                            _G._qfStateRef.flingMurderActive = false
                            _G._qfStateRef.stealGunActive    = false
                            FlingSystem.flingAll       = false
                            FlingSystem.flingMurder    = false
                            FlingSystem.flingSheriff   = false
                            FlingSystem.flingInnocent  = false
                            FlingSystem.specificTarget = nil
                            _flingActive    = false
                            _flingReturning = false
                            if FlingSystem.active then
                                pcall(StopFlingSystem)
                                FlingSystem.active = false
                            end
                        else
                            _qfStopAll()
                        end
                        StealGunSystem.sheriffOriginalFound = nil
                        StealGunSystem.sheriffDeadDetected  = false
                        StealGunSystem.roleCheckDisabled    = false
                        StealGunSystem.gunInBackpackMode    = false
                        StealGunSystem._roundToken = (StealGunSystem._roundToken or 0) + 1
                        _roleCache.lastUpdate = 0
                        _refreshRoleCache()
                        local holder = nil
                        if _roleCache.sheriff and _roleCache.sheriff.Character then
                            local sh = _roleCache.sheriff.Character:FindFirstChildOfClass("Humanoid")
                            if sh and sh.Health > 0 then holder = _roleCache.sheriff end
                        end
                        if not holder and _roleCache.hero and _roleCache.hero.Character then
                            local hh = _roleCache.hero.Character:FindFirstChildOfClass("Humanoid")
                            if hh and hh.Health > 0 then holder = _roleCache.hero end
                        end
                        if not holder then
                            CreateCustomNotification("STEAL GUN", "No se detecto portador de gun", 4)
                            return
                        end
                        _flingActive = false; _flingReturning = false
                        _qs.stealGunActive                  = true
                        StealGunSystem.enabled              = true
                        StealGunSystem.sheriffOriginalFound = holder
                        -- FIX VISUAL: reflejar estado activo
                        pcall(function() if _sgBind.frame then _sgBind.frame:SetActiveState(true) end end)
                        CreateCustomNotification("STEAL GUN", "Flingeando a " .. holder.Name .. " por 5s...", 3)
                        task.spawn(StealGunLoop)
                    end
                end)
                _sgBind.frame = _sgFrame
                -- FIX: exponer al global para que StealGunLoop pueda resetear el visual
                _G._sgBindRef = _sgBind
            end
        end)
    end

    -- BOTON: STEAL GUN (fling al sheriff/portador de gun por 5s, luego TP al mapa)
    -- FIX TP INVOLUNTARIO: token de sesion para invalidar spawns acumulados de presses anteriores
    local _sgBtnToken = 0
    CreateButton(leftColumn, ">> STEAL GUN", ThemeColors.Aurora4, function()
        if _qfState.stealGunActive then
            -- Cancelar activo: incrementar token para invalidar el spawn en curso
            _sgBtnToken = _sgBtnToken + 1
            _qfState.stealGunActive    = false
            StealGunSystem.enabled     = false
            _flingActive               = false
            _flingReturning            = false
            if StealGunSystem._sgCacheConn then
                pcall(function() StealGunSystem._sgCacheConn:Disconnect() end)
                StealGunSystem._sgCacheConn = nil
            end
            if StealGunSystem._sgRemoveConn then
                pcall(function() StealGunSystem._sgRemoveConn:Disconnect() end)
                StealGunSystem._sgRemoveConn = nil
            end
            CreateCustomNotification("STEAL GUN", "Desactivado", 2)
            return
        end

        -- Parar cualquier fling previo y limpiar todos los guards
        _qfStopAll()

        -- Reset del sistema para deteccion limpia
        StealGunSystem.sheriffOriginalFound = nil
        StealGunSystem.sheriffDeadDetected  = false
        StealGunSystem.roleCheckDisabled    = false
        StealGunSystem.gunInBackpackMode    = false
        StealGunSystem._roundToken          = (StealGunSystem._roundToken or 0) + 1
        _roleCache.lastUpdate = 0
        _refreshRoleCache()

        -- Detectar portador de la gun: sheriff (cache) -> hero -> scan visual
        -- NOTA: se mantiene la deteccion del nuevo sheriff para no flingear siempre al viejo
        local currentGunHolder = nil
        -- Prioridad 1: sheriff del cache (evita flingear al sheriff muerto)
        if _roleCache.sheriff and _roleCache.sheriff.Character then
            local sHum = _roleCache.sheriff.Character:FindFirstChildOfClass("Humanoid")
            if sHum and sHum.Health > 0 then
                currentGunHolder = _roleCache.sheriff
            end
        end
        -- Prioridad 2: hero (quien recogi? la gun del sheriff muerto)
        if not currentGunHolder and _roleCache.hero and _roleCache.hero.Character then
            local hHum = _roleCache.hero.Character:FindFirstChildOfClass("Humanoid")
            if hHum and hHum.Health > 0 then
                currentGunHolder = _roleCache.hero
            end
        end
        -- Prioridad 3: scan visual por quien tiene la gun equipada/backpack
        if not currentGunHolder and _findGunIn then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    local pHum = p.Character:FindFirstChildOfClass("Humanoid")
                    -- Solo jugadores VIVOS para no flingear al sheriff muerto
                    if pHum and pHum.Health > 0 then
                        local hasGun = _findGunIn(p.Character)
                        if not hasGun then
                            local bp = p:FindFirstChildOfClass("Backpack")
                            hasGun = bp and _findGunIn(bp)
                        end
                        if hasGun then
                            currentGunHolder = p
                            break
                        end
                    end
                end
            end
        end

        if not currentGunHolder then
            CreateCustomNotification("STEAL GUN", "No se detecto portador de gun", 4)
            return
        end

        _flingActive    = false
        _flingReturning = false
        _qfState.stealGunActive             = true
        StealGunSystem.enabled              = true
        StealGunSystem.sheriffOriginalFound = currentGunHolder
        -- FIX TP INVOLUNTARIO: incrementar token en cada nueva activacion para invalidar spawns viejos
        _sgBtnToken = _sgBtnToken + 1
        local _myToken = _sgBtnToken
        CreateCustomNotification("STEAL GUN", "Flingeando a " .. currentGunHolder.Name .. " por 5s...", 3)

        task.spawn(function()
            local tChar = currentGunHolder.Character
            local tHRP  = tChar and tChar:FindFirstChild("HumanoidRootPart")
            if not tHRP then
                _qfState.stealGunActive = false
                StealGunSystem.enabled  = false
                CreateCustomNotification("STEAL GUN", "Target sin character", 2)
                return
            end

            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myHRP or not myHum or myHum.Health <= 0 then
                _qfState.stealGunActive = false
                StealGunSystem.enabled  = false
                return
            end

            -- Capturar posicion segura antes del fling
            local _sgSafePos = nil
            local _ry = myHRP.Position.Y
            if _ry > 2 and _ry < 800 then
                _sgSafePos = myHRP.CFrame
                _G.OldPos  = _sgSafePos
                _flingLastSafePos = _sgSafePos
            end

            -- Escuchar drop de gun ANTES del fling
            local _gunDropped = nil
            local _dropConn = workspace.DescendantAdded:Connect(function(obj)
                if not _qfState.stealGunActive then return end
                if not (obj:IsA("Tool") and _SG_DROP_NAMES[obj.Name]) then return end
                local p = obj.Parent
                if p and p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return end
                _gunDropped = _gunDropped or obj
            end)

            -- == STICKY FLING por 5 segundos -- misma logica exacta que _stickyFlingOne ==
            -- Nos metemos en el cuerpo del portador y aplicamos velocidad en NUESTRO HRP
            local _RS = game:GetService("RunService")
            local _launched = false
            local _sgFlingConn
            local _timeStart = tick()

            local function _sgZeroSelf()
                for _p = 1, 3 do
                    pcall(function()
                        myHRP.AssemblyLinearVelocity  = Vector3.zero
                        myHRP.AssemblyAngularVelocity = Vector3.zero
                        myHRP.Velocity    = Vector3.zero
                        myHRP.RotVelocity = Vector3.zero
                    end)
                end
            end

            pcall(function() myHum.PlatformStand = true end)

            _sgFlingConn = _RS.Heartbeat:Connect(function()
                if not tHRP or not tHRP.Parent then
                    _launched = true
                    _sgZeroSelf()
                    if _sgFlingConn then _sgFlingConn:Disconnect(); _sgFlingConn = nil end
                    return
                end
                local tVel = tHRP.AssemblyLinearVelocity.Magnitude
                if tVel > 120 or tick() - _timeStart >= 5 then
                    _launched = true
                    _sgZeroSelf()
                    pcall(function() myHum.PlatformStand = false end)
                    if _sgFlingConn then _sgFlingConn:Disconnect(); _sgFlingConn = nil end
                    return
                end
                if not _qfState.stealGunActive then
                    _launched = true
                    _sgZeroSelf()
                    if _sgFlingConn then _sgFlingConn:Disconnect(); _sgFlingConn = nil end
                    return
                end
                -- Meterme en el cuerpo del portador y aplicar velocidad en MI HRP
                pcall(function()
                    myHRP.CFrame = tHRP.CFrame
                    myChar:SetPrimaryPartCFrame(tHRP.CFrame)
                end)
                pcall(function()
                    myHRP.AssemblyLinearVelocity  = Vector3.new(0, 50000, 0)
                    myHRP.AssemblyAngularVelocity = Vector3.new(50000, 50000, 50000)
                end)
            end)

            -- Esperar hasta que terminen los 5 segundos o el portador salga volando
            local _waited = 0
            repeat
                task.wait(0.016)
                _waited = _waited + 0.05
            until _launched or _waited > 6

            if _sgFlingConn then _sgFlingConn:Disconnect(); _sgFlingConn = nil end
            pcall(function() _dropConn:Disconnect() end)
            -- Triple zereo post-loop igual que _stickyFlingOne
            pcall(function()
                myHRP.AssemblyLinearVelocity  = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
                myHRP.Velocity    = Vector3.zero
                myHRP.RotVelocity = Vector3.zero
                myHum.PlatformStand = false
            end)
            task.wait(0.016)
            pcall(function()
                myHRP.AssemblyLinearVelocity  = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
            end)
            -- Limpiar estado ANTES del TP para que nada bloquee
            StealGunSystem.enabled  = false
            _qfState.stealGunActive = false
            _flingActive            = false
            _flingReturning         = false

            -- TP al mapa inmediatamente (en spawn separado para que nunca quede bloqueado)
            -- FIX TP INVOLUNTARIO: solo ejecutar el TP si este spawn corresponde al ultimo press
            -- FIX CAIDA: zerear velocidad varias veces y reintentar TP para no caer bajo el mapa
            task.spawn(function()
                task.wait(0.15)
                if _myToken ~= _sgBtnToken then return end  -- press mas reciente lo invalida
                -- Zero extra antes del TP para asegurar que no haya velocidad residual del fling
                local _myC3 = LocalPlayer.Character
                local _myH3 = _myC3 and _myC3:FindFirstChild("HumanoidRootPart")
                local _myHum3 = _myC3 and _myC3:FindFirstChildOfClass("Humanoid")
                if _myH3 then
                    pcall(function()
                        _myH3.AssemblyLinearVelocity  = Vector3.zero
                        _myH3.AssemblyAngularVelocity = Vector3.zero
                        _myH3.Velocity    = Vector3.zero
                        _myH3.RotVelocity = Vector3.zero
                    end)
                end
                if _myHum3 then
                    pcall(function() _myHum3:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                end
                -- Primer TP al mapa
                local _tpOk = pcall(TeleportToMap)
                task.wait(0.2)
                -- Segundo zereo + segundo TP de confirmacion para evitar caer
                if _myToken ~= _sgBtnToken then return end
                local _myC4 = LocalPlayer.Character
                local _myH4 = _myC4 and _myC4:FindFirstChild("HumanoidRootPart")
                if _myH4 then
                    pcall(function()
                        _myH4.AssemblyLinearVelocity  = Vector3.zero
                        _myH4.AssemblyAngularVelocity = Vector3.zero
                    end)
                    -- Si el TP anterior fallo o el personaje esta muy abajo, reintentar
                    if not _tpOk or _myH4.Position.Y < 0 then
                        pcall(TeleportToMap)
                        task.wait(0.15)
                        local _myH5 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        if _myH5 then
                            pcall(function()
                                _myH5.AssemblyLinearVelocity  = Vector3.zero
                                _myH5.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end
                    end
                end
                CreateCustomNotification("STEAL GUN", "Fling terminado - volviendo al mapa...", 2)
            end)

            -- Intentar agarrar la gun en paralelo (no bloquea el TP)
            task.spawn(function()
                local grabbed = _sgLocalHasGun and _sgLocalHasGun()
                if not grabbed and _gunDropped then
                    local myC = LocalPlayer.Character
                    local myH = myC and myC:FindFirstChild("HumanoidRootPart")
                    local obj = _gunDropped
                    if obj and obj.Parent and myH then
                        local p = obj.Parent
                        if not (p and p:IsA("Model") and p:FindFirstChildOfClass("Humanoid")) then
                            local handle = obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart")
                            if handle then
                                pcall(function() handle.CFrame = CFrame.new(myH.Position) end)
                                pcall(function() obj:PivotTo(CFrame.new(myH.Position)) end)
                                task.wait(0.016)
                                pcall(function()
                                    firetouchinterest(myH, handle, 0)
                                    task.wait(0.03)
                                    firetouchinterest(myH, handle, 1)
                                end)
                                task.wait(0.016)
                                grabbed = _sgLocalHasGun()
                            end
                        end
                    end
                end
                if grabbed then
                    CreateCustomNotification("STEAL GUN", "Gun robada de " .. currentGunHolder.Name .. "!", 2.5)
                end
            end)
        end)
    end)
end
-- FIN QUICK FLING BUTTONS


function CreateWorldUI_RompGun() -- global to stay under 200-local limit
 local _ptSection = CreateSection(rightColumn, "", "PLAYER TOOLS", ThemeColors.Aurora3)

    if not WorldSystem.playerTools then
        WorldSystem.playerTools = { selectedPlayer = nil }
    end
    local PT = WorldSystem.playerTools

    -- Selector de jugadores (estilo Combat/Fling -- usa _cachedPlayers, sin boton refrescar)
    local _ptPlayerList = {"(sin jugadores)"}
    for _, p in ipairs(_cachedPlayers) do
        if p ~= LocalPlayer then table.insert(_ptPlayerList, p.Name) end
    end
    local _initDef = _ptPlayerList[1]
    local _ptSelector = CreateNebulaSelector(_ptSection, "Seleccionar Jugador", _ptPlayerList, _initDef, function(name)
        PT.selectedPlayer = name
    end)
    _G._ptSelectorRef = _ptSelector
    PT.selectedPlayer = _initDef

    coinResultFrame = Instance.new("Frame", rightColumn)
    coinResultFrame.Size = UDim2.new(1, -10, 0, 60)
    coinResultFrame.BackgroundColor3 = ThemeColors.Background
    coinResultFrame.BackgroundTransparency = 0.85
    coinResultFrame.BorderSizePixel = 0
    coinResultFrame.Visible = false
    Instance.new("UICorner", coinResultFrame).CornerRadius = UDim.new(0, 8)
    coinResStroke = Instance.new("UIStroke", coinResultFrame)
    coinResStroke.Color = ThemeColors.Primary
    coinResStroke.Thickness = 2.5
    coinResLbl = Instance.new("TextLabel", coinResultFrame)
    coinResLbl.Size = UDim2.new(1, -12, 1, 0)
    coinResLbl.Position = UDim2.new(0, 8, 0, 0)
    coinResLbl.BackgroundTransparency = 1
 coinResLbl.Text = ""
    coinResLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
    coinResLbl.TextSize = 12
    coinResLbl.TextColor3 = ThemeColors.Primary
    coinResLbl.TextXAlignment = Enum.TextXAlignment.Left
    coinResLbl.TextWrapped = true
    coinResLbl.ZIndex = 2

 CreateButton(rightColumn, " Check Player Coins", ThemeColors.Primary, function()
        local targetName = PT.selectedPlayer
        if not targetName or targetName == "(sin jugadores)" then
 CreateCustomNotification("COINS", "Selecciona un jugador primero!", 3)
            return
        end
        local target = Players:FindFirstChild(targetName)
        if not target then
 CreateCustomNotification("COINS", "Jugador no encontrado: " .. targetName, 3)
            return
        end

        local coins = nil
        local bagName = nil
        local isFull = false

        -- METODO 1: Leer CoinBags del PlayerGui (igual que el script CoinBagContainerScript del juego)
        -- Players.[Player].PlayerGui.MainGUI.Game.CoinBags.CoinBagContainerScript
        pcall(function()
            local pg = target.PlayerGui
            local mainGUI = pg and pg:FindFirstChild("MainGUI")
            local gameGui = mainGUI and mainGUI:FindFirstChild("Game")
            local coinBags = gameGui and gameGui:FindFirstChild("CoinBags")
            local container = coinBags and coinBags:FindFirstChild("Container")
            if container then
                for _, bagFrame in ipairs(container:GetChildren()) do
                    if bagFrame:IsA("Frame") and bagFrame.Visible then
                        -- Leer el texto del coin counter (CurrencyFrame.Icon.Coins)
                        local currFrame = bagFrame:FindFirstChild("CurrencyFrame")
                        local icon = currFrame and currFrame:FindFirstChild("Icon")
                        local coinsLabel = icon and icon:FindFirstChild("Coins")
                        if coinsLabel then
                            local n = tonumber(coinsLabel.Text)
                            if n then
                                coins = n
                                bagName = bagFrame:GetAttribute("BagName") or bagFrame.Name
                                -- Verificar si la bolsa esta llena
                                local fullIcon = bagFrame:FindFirstChild("FullBagIcon")
                                isFull = fullIcon and fullIcon.Visible or false
                            end
                        end
                    end
                end
            end
        end)

        -- METODO 2: Atributo directo en el Player (fallback)
        if not coins then
            pcall(function()
                local v = target:GetAttribute("Coins") or target:GetAttribute("coins") or target:GetAttribute("Gold")
                if type(v) == "number" then coins = v end
            end)
        end

        -- METODO 3: leaderstats (fallback)
        if not coins then
            pcall(function()
                local ls = target:FindFirstChild("leaderstats")
                if ls then
                    for _, v in ipairs(ls:GetChildren()) do
                        local n = v.Name:lower()
                        if n:find("coin") or n:find("gold") then
                            local num = tonumber(v.Value)
                            if num then coins = num; break end
                        end
                    end
                end
            end)
        end

        coinResultFrame.Visible = true
        if coins then
            local fullStr = isFull and " BOLSA LLENA!" or ""
            local bagStr  = bagName and (" [" .. bagName .. "]") or ""
            coinResLbl.Text = targetName .. "\n Coins: " .. tostring(coins) .. bagStr .. fullStr
            coinResLbl.TextColor3 = isFull and Color3.fromRGB(255, 200, 50) or ThemeColors.Primary
            local notifMsg = targetName .. " tiene " .. tostring(coins) .. " coins" .. bagStr .. fullStr
 CreateCustomNotification("COINS", notifMsg, 6)
        else
            coinResLbl.Text = targetName .. "\n Coins: No accesibles (MM2)"
            coinResLbl.TextColor3 = Color3.fromRGB(255, 120, 50)
 CreateCustomNotification("COINS", targetName .. " -- No accesibles (MM2)", 4)
        end
    end)

end
function CreateWorldUI_AutoGrabGun()
    CreateSection(rightColumn, "", "AUTO GRAB GUN", ThemeColors.Aurora4)

    -- Setup state
    GrabState = WorldSystem.grab or GrabState or {}
    if not GrabState._cachedDrop then GrabState._cachedDrop = nil end
    if not GrabState._hbConn     then GrabState._hbConn     = nil end
    if not GrabState._agConn     then GrabState._agConn     = nil end
    if not GrabState._agRoundConn then GrabState._agRoundConn = nil end
    if not GrabState._agBusy     then GrabState._agBusy     = false end
    if not GrabState.autoEnabled  then GrabState.autoEnabled  = false end

    task.defer(function()
        -- -- RESTAURAR btnFrame desde _G._grabBindGui si el GUI sigue vivo ------
        -- Cuando el tab se re-abre, GrabState.btnFrame queda nil porque es local al frame.
        -- Pero si el ScreenGui sigue en CoreGui, podemos recuperar el Frame interior
        -- para que los sliders de tamano/forma sigan funcionando.
        if _G._grabBindGui and _G._grabBindGui.Parent then
            WorldSystem.grab.gui = _G._grabBindGui
            grabGui = _G._grabBindGui
            -- El Frame/boton interior es hijo directo del ScreenGui
            local recovered = _G._grabBindGui:FindFirstChildWhichIsA("Frame")
                           or _G._grabBindGui:FindFirstChildWhichIsA("TextButton")
            if recovered then
                GrabState.btnFrame = recovered
            end
        end

        if GrabState.autoEnabled then
            GrabState._agBusy = false
            if not GrabState._agConn then
                task.spawn(_agTryGrab)
                GrabState._agConn = workspace.DescendantAdded:Connect(function(obj)
                    if not GrabState.autoEnabled then return end
                    -- Solo "GunDrop" exacto -- el nombre que MM2 usa para la gun suelta
                    if obj.Name == "GunDrop" and obj:IsA("Tool") then
                        GrabState._cachedDrop = obj.Parent and obj or nil
                        task.spawn(_agTryGrab)
                    end
                end)
            end
            if not GrabState._hbConn then
                local _hbTimer2 = 0
                local _hbTgrabHb = 0
                GrabState._hbConn = RunService.Heartbeat:Connect(function(dt)
                    _hbTgrabHb=_hbTgrabHb+1; if _hbTgrabHb<3 then return end; _hbTgrabHb=0
                    if not GrabState.autoEnabled then return end
                    if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda
                    _hbTimer2 = _hbTimer2 + dt
                    if _hbTimer2 < 0.25 then return end
                    _hbTimer2 = 0
                    local char = LocalPlayer.Character
                    if char and not (_findGun(char)) then
                        task.spawn(_agTryGrab)
                    end
                end)
            end
        end
    end)

    -- grabGui se gestiona solo a traves del toggle "Grab Gun Bindable Button".
    -- MakeGrabBindableBtn() hace sweep + crea ScreenGui + Frame correctamente.
    -- NO creamos un ScreenGui vacio aqui: eso era la causa del bug de desaparicion.

    function FindGunDrop()
        -- Solo buscar "GunDrop" exacto (nombre que MM2 usa para la gun suelta)
        local direct = workspace:FindFirstChild("GunDrop")
        if direct then return direct end

        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj.Name == "GunDrop" and obj:IsA("Tool") then return obj end
        end

        -- legacy fallback (code continues below)
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("Tool") and (obj.Name == "Gun" or obj.Name:lower():find("revolver") or obj.Name:lower():find("sheriff")) then
                local inPlayer = false
                for _, p in pairs(_cachedPlayers) do
                    local char = p.Character
                    local bp   = p.Backpack
                    if (char and obj:IsDescendantOf(char)) or (bp and obj:IsDescendantOf(bp)) then
                        inPlayer = true; break
                    end
                end
                if not inPlayer then return obj end
            end
        end
        return nil
    end

    function GetGunDropPos(gunDrop)
        if not gunDrop then return nil end
        if gunDrop:IsA("Tool") then
            local h = gunDrop:FindFirstChild("Handle")
            if h then return h.Position end
        end
        if gunDrop:IsA("BasePart") then return gunDrop.Position end
        if gunDrop:IsA("Model") then
            if gunDrop.PrimaryPart then return gunDrop.PrimaryPart.Position end
            local bp = gunDrop:FindFirstChildOfClass("BasePart")
            if bp then return bp.Position end
        end
        local bp = gunDrop:FindFirstChildOfClass("BasePart")
        if bp then return bp.Position end
        return nil
    end

    -- FIX: exponer como _G para que el closure del bindable siempre la encuentre
    function TryGrabGun()
        _G._TryGrabGun = TryGrabGun  -- sync
        local char = LocalPlayer.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end

        if GrabState.safeCheck then
            local myRole = _roleCache.localRole or "Innocent"
            if myRole ~= "Sheriff" and myRole ~= "Hero" then
 CreateCustomNotification("GRAB GUN", "No sos Sheriff/Hero. Safe Check activado.", 2)
                return
            end
        end

        _refreshRoleCache()

        local gunDrop = _agFindGunDrop and _agFindGunDrop() or FindGunDrop()
        if not gunDrop then
 CreateCustomNotification("GRAB GUN", "No se encontro ninguna arma en el mapa.", 2)
            return
        end

        local gPart = (_agGetPart and _agGetPart(gunDrop))
            or gunDrop:FindFirstChild("Handle")
            or gunDrop:FindFirstChildWhichIsA("BasePart")
        if not gPart then
 CreateCustomNotification("GRAB GUN", "No se pudo encontrar la parte del arma.", 2)
            return
        end

        task.spawn(function()
            pcall(function()
                -- METODO 1: EquipTool directo (instantaneo, 0 lag)
                if gunDrop:IsA("Tool") then
                    pcall(function() hum:EquipTool(gunDrop) end)
                    if _findGun(char) then
                        CreateCustomNotification("GRAB GUN", " Gun agarrada!", 2)
                        return
                    end
                end

                -- METODO 2: ProximityPrompt
                pcall(function()
                    local pp = gunDrop:FindFirstChildOfClass("ProximityPrompt")
                           or gPart:FindFirstChildOfClass("ProximityPrompt")
                    if pp then fireproximityprompt(pp) end
                end)
                if _findGun(char) then
                    CreateCustomNotification("GRAB GUN", " Gun agarrada!", 2)
                    return
                end

                -- METODO 3: LA GUN viene al jugador (NO blink del HRP ? 0 TP, 0 delay)
                local gOrigCF   = gPart.CFrame
                local gAnchored = gPart.Anchored
                local grabTarget = root.Position + Vector3.new(0, -1.2, 0)
                pcall(function()
                    gPart.Anchored = false
                    gPart.CFrame = CFrame.new(grabTarget)
                    if gunDrop:IsA("Tool") then gunDrop:PivotTo(CFrame.new(grabTarget)) end
                end)
                pcall(function()
                    firetouchinterest(root, gPart, 0)
                    firetouchinterest(root, gPart, 1)
                end)
                if _findGun(char) then
                    CreateCustomNotification("GRAB GUN", " Gun agarrada!", 2)
                    return
                end

                -- METODO 4: exactamente en HRP (sin yield)
                pcall(function()
                    gPart.CFrame = CFrame.new(root.Position)
                    if gunDrop:IsA("Tool") then gunDrop:PivotTo(CFrame.new(root.Position)) end
                end)
                pcall(function()
                    firetouchinterest(root, gPart, 0)
                    firetouchinterest(root, gPart, 1)
                end)
                if _findGun(char) then
                    CreateCustomNotification("GRAB GUN", " Gun agarrada!", 2)
                    return
                end

                -- METODO 5: EquipTool forzado final, restaurar si falla
                task.defer(function()
                    if _findGun(char) then return end
                    if gunDrop and gunDrop.Parent then
                        pcall(function() hum:EquipTool(gunDrop) end)
                    end
                    if _findGun(char) then
                        CreateCustomNotification("GRAB GUN", " Gun agarrada!", 2)
                        return
                    end
                    pcall(function()
                        gPart.CFrame   = gOrigCF
                        gPart.Anchored = gAnchored
                    end)
                    CreateCustomNotification("GRAB GUN", "Arma encontrada pero no se pudo agarrar.", 2)
                end)
            end)
        end)
    end

    function SetCornerRadius(frame, shapeType)
        local corner = frame:FindFirstChildOfClass("UICorner")
        if not corner then return end
        if shapeType == "Circle" then corner.CornerRadius = UDim.new(1, 0)  end
        if shapeType == "Square" then corner.CornerRadius = UDim.new(0, 0)  end
        if shapeType == "Rounded" then corner.CornerRadius = UDim.new(0, 8)  end
    end

    function MakeGrabBindableBtn()
        -- -- SWEEP COMPLETO: destruir cualquier instancia anterior via _G + por nombre --
        if _G._grabBindGui then
            pcall(function() _G._grabBindGui:Destroy() end)
            _G._grabBindGui = nil
        end
        if WorldSystem.grab.gui then
            pcall(function() WorldSystem.grab.gui:Destroy() end)
            WorldSystem.grab.gui = nil
        end
        local function sweepGrab(p)
            if not p then return end
            for _, g in ipairs(p:GetChildren()) do
                if g.Name == "GrabGunBindable" then pcall(function() g:Destroy() end) end
            end
        end
        sweepGrab(CoreGui)
        pcall(function() sweepGrab(LocalPlayer:FindFirstChild("PlayerGui")) end)
        GrabState.btnFrame = nil

        -- -- CREAR GUI FRESCO ----------------------------------------------
        local gg = Instance.new("ScreenGui")
        gg.Name = "GrabGunBindable"; gg.ResetOnSpawn = false
        gg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gg.IgnoreGuiInset = true; gg.DisplayOrder = 9900
        pcall(function() gg.Parent = CoreGui end)
        if not gg.Parent then gg.Parent = LocalPlayer.PlayerGui end

        -- Guardar referencia en _G Y en WorldSystem para que persista entre re-aperturas del tab
        _G._grabBindGui      = gg
        WorldSystem.grab.gui = gg
        grabGui              = gg

        -- FIX: usar rightColumn como guiParent para que AncestryChanged destruya el bind
        -- cuando el tab se cierra (antes usaba gg=ScreenGui que nunca pierde padre)
        local frame = MakeCapyBindableFrame(rightColumn or gg, "GRAB GUN", function()
            -- FIX: sync _G._TryGrabGun antes de llamar, por si el closure cambio
            if type(TryGrabGun) == "function" then _G._TryGrabGun = TryGrabGun end
            local fn = (type(TryGrabGun) == "function" and TryGrabGun)
                    or _G._TryGrabGun
            if fn then pcall(fn) end
        end, 200, 300)
        GrabState.btnFrame = frame

        -- Aplicar tamano/forma guardados (por si ya existian del slider)
        if frame then
            frame.Size = UDim2.new(0, GrabState.sizeX, 0, GrabState.sizeY)
            local lbl = frame:FindFirstChildOfClass("TextLabel")
            if lbl then lbl.TextSize = GrabState.textSize end
            local corner = frame:FindFirstChildOfClass("UICorner")
            if corner then
                if GrabState.shapeType == "Circle"  then corner.CornerRadius = UDim.new(1, 0) end
                if GrabState.shapeType == "Square"  then corner.CornerRadius = UDim.new(0, 0) end
                if GrabState.shapeType == "Rounded" then corner.CornerRadius = UDim.new(0, 8) end
            end
        end
    end

    local function _destroyGrabBind()
        if _G._grabBindGui then
            pcall(function() _G._grabBindGui:Destroy() end)
            _G._grabBindGui = nil
        end
        if WorldSystem.grab.gui then
            pcall(function() WorldSystem.grab.gui:Destroy() end)
            WorldSystem.grab.gui = nil
        end
        local function sweepGrab(p)
            if not p then return end
            for _, g in ipairs(p:GetChildren()) do
                if g.Name == "GrabGunBindable" then pcall(function() g:Destroy() end) end
            end
        end
        sweepGrab(CoreGui)
        pcall(function() sweepGrab(LocalPlayer:FindFirstChild("PlayerGui")) end)
        GrabState.btnFrame = nil
        grabGui = nil
        DestroyCapyBind("GRAB GUN")
    end


    -- ===============================================================
    -- CONTROLES: TOGGLES Y SLIDERS
    -- ===============================================================
    



    do
        local _prevSection = _currentMainSectionFrame
        _currentMainSectionFrame = nil
        CreateButton(rightColumn, "Grab Gun", ThemeColors.Aurora3, function()
            -- FIX: usar _G._TryGrabGun como fallback por si TryGrabGun no esta en scope
            -- (puede pasar si el tab se cerro y reabrio y la funcion no fue redefinida aun)
            local fn = (type(TryGrabGun) == "function" and TryGrabGun) or _G._TryGrabGun
            if fn then pcall(fn) end
        end)
        _currentMainSectionFrame = _prevSection
    end

    -- TOGGLE: Grab Gun Bindable Button
    -- FIX: sincronizar GrabState.bindable desde el estado guardado en disco antes de
    -- pasar initialValue al toggle, para que no se active si el usuario lo desactivo.
    -- WorldSystem.grab.bindable siempre arranca en false (recien inicializado), pero
    -- _G._toggleStates ya tiene el valor real cargado por _loadConfig().
    do
        local _savedBindable = _G._toggleStates and _G._toggleStates["Grab Gun Bindable Button"]
        if _savedBindable ~= nil then
            GrabState.bindable = _savedBindable
            WorldSystem.grab.bindable = _savedBindable
        end
    end
    CreateAuroraToggle(rightColumn, "Grab Gun Bindable Button", function(enabled)
        GrabState.bindable = enabled
        WorldSystem.grab.bindable = enabled
        if enabled then
            MakeGrabBindableBtn()
            CreateCustomNotification("GRAB GUN", "Boton bindable creado", 2)
        else
            _destroyGrabBind()
            CreateCustomNotification("GRAB GUN", "Boton bindable eliminado", 2)
        end
    end, GrabState.bindable)

    -- SLIDER: Tama?o X del boton
    CreateSlider(rightColumn, "Button Width (X)", 20, 200, GrabState.sizeX, function(val)
        GrabState.sizeX = val
        if GrabState.btnFrame then
            GrabState.btnFrame.Size = UDim2.new(0, GrabState.sizeX, 0, GrabState.sizeY)
        end
    end)

    -- SLIDER: Tama?o Y del boton
    CreateSlider(rightColumn, "Button Height (Y)", 20, 200, GrabState.sizeY, function(val)
        GrabState.sizeY = val
        if GrabState.btnFrame then
            GrabState.btnFrame.Size = UDim2.new(0, GrabState.sizeX, 0, GrabState.sizeY)
        end
    end)

    -- SLIDER: Tama?o de texto del boton
    CreateSlider(rightColumn, "Texto del Boton", 6, 32, GrabState.textSize, function(val)
        GrabState.textSize = val
        if GrabState.btnFrame then
            local lbl = GrabState.btnFrame:FindFirstChildOfClass("TextLabel")
            if lbl then lbl.TextSize = val end
        end
    end)



    if not GrabState._cachedDrop then GrabState._cachedDrop = nil end
    if not GrabState._hbConn    then GrabState._hbConn    = nil end

    -- -- Buscar gun suelta en workspace (solo hijos directos + cache) ------
    function _agFindGunDrop()
        -- 1. Cache valido: verificar que sigue suelto (no en ningun player)
        local cached = GrabState._cachedDrop
        if cached and cached.Parent then
            local inPlayer = false
            for _, p in pairs(_cachedPlayers) do
                local c = p.Character; local b = p.Backpack
                if (c and cached:IsDescendantOf(c)) or (b and cached:IsDescendantOf(b)) then
                    inPlayer = true; break
                end
            end
            if not inPlayer then return cached end
        end
        GrabState._cachedDrop = nil

        -- 2. Solo hijos directos de workspace -- SOLO GunDrop (nombre exacto)
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj.Name == "GunDrop" then
                GrabState._cachedDrop = obj; return obj
            end
            -- GunDrop dentro de un Model (un nivel)
            if obj:IsA("Model") then
                for _, child in ipairs(obj:GetChildren()) do
                    if child.Name == "GunDrop" then
                        GrabState._cachedDrop = child; return child
                    end
                end
            end
        end
        return nil
    end

    function _agGetPart(gunDrop)
        if not gunDrop then return nil end
        if gunDrop:IsA("BasePart") then return gunDrop end
        local h = gunDrop:FindFirstChild("Handle")
        if h and h:IsA("BasePart") then return h end
        return gunDrop:FindFirstChildWhichIsA("BasePart")
    end

    function _agGetPos(obj)
        if not obj then return nil end
        if obj:IsA("Tool") then
            local h = obj:FindFirstChild("Handle")
            if h then return h.Position end
        end
        if obj:IsA("BasePart") then return obj.Position end
        if obj:IsA("Model") then
            if obj.PrimaryPart then return obj.PrimaryPart.Position end
            local bp = obj:FindFirstChildOfClass("BasePart")
            if bp then return bp.Position end
        end
        local bp = obj:FindFirstChildOfClass("BasePart")
        return bp and bp.Position or nil
    end

    if GrabState._agConn == nil then GrabState._agConn = nil end
    if GrabState._agBusy == nil then GrabState._agBusy = false end

    function _agTryGrab()
        if GrabState._agBusy then return end
        GrabState._agBusy = true
        task.spawn(function()
            pcall(function()
                local char = LocalPlayer.Character
                local root = char and char:FindFirstChild("HumanoidRootPart")
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                if not root or not hum or hum.Health <= 0 then return end

                _refreshRoleCache()
                if (_roleCache.localRole or "") == "Murderer" then return end
                if _findGun(char) then return end

                local gunDrop = _agFindGunDrop()
                if not gunDrop then return end
                local gPart = _agGetPart(gunDrop)
                if not gPart then return end

                -- METODO 1: EquipTool directo (0 lag, 0 delay, sin mover nada)
                if gunDrop:IsA("Tool") then
                    pcall(function() hum:EquipTool(gunDrop) end)
                    if _findGun(char) then
                        GrabState._cachedDrop = nil
                        CreateCustomNotification("AUTO GRAB GUN", "Gun agarrada!", 2)
                        return
                    end
                end

                -- METODO 2: ProximityPrompt (algunos modos de MM2 lo usan)
                pcall(function()
                    local pp = gunDrop:FindFirstChildOfClass("ProximityPrompt")
                           or (gPart and gPart:FindFirstChildOfClass("ProximityPrompt"))
                    if pp then fireproximityprompt(pp) end
                end)
                if _findGun(char) then
                    GrabState._cachedDrop = nil
                    CreateCustomNotification("AUTO GRAB GUN", "Gun agarrada!", 2)
                    return
                end

                -- METODO 3: LA GUN viene al jugador (NO blink del HRP ? 0 TP de world)
                -- Guardamos CFrame original para restaurar si no se agarra
                local origGunCF  = gPart.CFrame
                local origAnch   = gPart.Anchored
                local grabTarget = root.Position + Vector3.new(0, -1.2, 0)
                pcall(function()
                    gPart.Anchored = false
                    gPart.CFrame   = CFrame.new(grabTarget)
                    if gunDrop:IsA("Tool") then gunDrop:PivotTo(CFrame.new(grabTarget)) end
                end)
                -- firetouchinterest en el mismo frame (sin yield)
                pcall(function()
                    firetouchinterest(root, gPart, 0)
                    firetouchinterest(root, gPart, 1)
                end)
                if _findGun(char) then
                    GrabState._cachedDrop = nil
                    CreateCustomNotification("AUTO GRAB GUN", "Gun agarrada!", 2)
                    return
                end

                -- METODO 4: segundo movimiento exactamente en HRP (sin yield)
                pcall(function()
                    gPart.CFrame = CFrame.new(root.Position)
                    if gunDrop:IsA("Tool") then gunDrop:PivotTo(CFrame.new(root.Position)) end
                end)
                pcall(function()
                    firetouchinterest(root, gPart, 0)
                    firetouchinterest(root, gPart, 1)
                end)
                if _findGun(char) then
                    GrabState._cachedDrop = nil
                    CreateCustomNotification("AUTO GRAB GUN", "Gun agarrada!", 2)
                    return
                end

                -- METODO 5 (?ltimo recurso): EquipTool forzado + restaurar posici?n si falla
                task.defer(function()
                    if _findGun(char) then return end
                    if gunDrop and gunDrop.Parent then
                        pcall(function() hum:EquipTool(gunDrop) end)
                    end
                    if _findGun(char) then
                        GrabState._cachedDrop = nil
                        CreateCustomNotification("AUTO GRAB GUN", "Gun agarrada!", 2)
                        return
                    end
                    -- Restaurar posici?n original si ning?n m?todo funcion?
                    pcall(function()
                        if gPart and gPart.Parent then
                            gPart.CFrame   = origGunCF
                            gPart.Anchored = origAnch
                        end
                    end)
                end)
            end)
            task.wait(0.02)
            GrabState._agBusy = false
        end)
    end

    if GrabState._agRoundConn == nil then GrabState._agRoundConn = nil end
    if GrabState._hbConn      == nil then GrabState._hbConn      = nil end


    -- TOGGLE: Auto Grab Gun
 CreateAuroraToggle(rightColumn, "Auto Grab Gun (cualquier rol)", function(enabled)
        GrabState.autoEnabled = enabled
        GrabState._cachedDrop = nil

        if enabled then
            GrabState._agBusy = false
            task.spawn(_agTryGrab)

            -- Event-driven: DescendantAdded en workspace
            -- FIX: detectar TODOS los nombres de gun que usa MM2 (no solo "GunDrop" exacto)
            if GrabState._agConn then GrabState._agConn:Disconnect() end
            GrabState._agConn = workspace.DescendantAdded:Connect(function(obj)
                if not GrabState.autoEnabled then return end
                if _findGun(LocalPlayer.Character) then return end
                -- FIX: aceptar cualquier nombre de gun en _GUN_NAMES o keyword "gun"/"sheriff"/"revolver"
                if not obj:IsA("Tool") then return end
                local nm = obj.Name:lower()
                local isGun = _GUN_NAMES[obj.Name]
                    or nm:find("gun") or nm:find("sheriff") or nm:find("revolver")
                if not isGun then return end
                local inPlayer = false
                for _, p in pairs(_cachedPlayers) do
                    local c = p.Character; local b = p.Backpack
                    if (c and obj:IsDescendantOf(c)) or (b and obj:IsDescendantOf(b)) then
                        inPlayer = true; break
                    end
                end
                if not inPlayer then
                    -- FIX: usar _fluidGrabGun -- mueve la GUN al player, no al reves
                    -- Sin blink del HRP -> sin lag visible para el jugador
                    task.spawn(function() pcall(_fluidGrabGun, obj) end)
                end
            end)

            -- Heartbeat fallback cada 0.5s
            -- FIX: no pausar por _visualRoundOver al inicio -- la gun puede spawnear justo
            -- cuando _visualRoundOver todavia es true (lag de red). Solo pausar si ya
            -- llevamos mas de 3s desde el fin de ronda sin RoundStart.
            if GrabState._hbConn then GrabState._hbConn:Disconnect() end
            local _hbT = 0
            GrabState._hbConn = RunService.Heartbeat:Connect(function(dt)
                if not GrabState.autoEnabled then return end
                -- FIX: permitir grab aunque _visualRoundOver sea true si hay drop visible
                -- Solo saltear si estamos en intermission larga (>3s sin RoundStart)
                if _G._visualRoundOver then
                    local timeSinceStart = _G._roundStartTime and (os.clock() - _G._roundStartTime) or 999  -- FIX #3
                    if timeSinceStart > 3 then return end
                end
                _hbT = _hbT + dt
                if _hbT < 0.5 then return end
                _hbT = 0
                local c = LocalPlayer.Character
                if c and not _findGun(c) then
                    local drop = _agFindGunDrop()
                    if drop then task.spawn(function() pcall(_fluidGrabGun, drop) end) end
                end
            end)

            -- RoundStart: burst de intentos en los primeros 4 segundos de ronda
            -- FIX: extender burst a 4s (40 intentos) porque la gun puede tardar en spawnear
            if GrabState._agRoundConn then pcall(function() GrabState._agRoundConn:Disconnect() end) end
            task.spawn(function()
                local ok, rem = pcall(function()
                    return ReplicatedStorage
                        :WaitForChild("Remotes", 5)
                        :WaitForChild("Gameplay", 5)
                        :WaitForChild("RoundStart", 5)
                end)
                if not ok or not rem then return end
                GrabState._agRoundConn = rem.OnClientEvent:Connect(function()
                    if not GrabState.autoEnabled then
                        GrabState._agRoundConn:Disconnect(); GrabState._agRoundConn = nil; return
                    end
                    GrabState._agBusy     = false
                    GrabState._cachedDrop = nil
                    -- FIX: burst de 40 intentos en 4s (gun puede tardar en spawnear en el mapa)
                    -- Ademas buscar en workspace:GetDescendants() por si la gun ya esta pero
                    -- el cache no la tiene todavia
                    task.spawn(function()
                        for _ = 1, 40 do
                            if not GrabState.autoEnabled then break end
                            if _findGun(LocalPlayer.Character) then break end
                            -- Intentar grab con agTryGrab (usa cache)
                            task.spawn(_agTryGrab)
                            -- FIX: ademas buscar directo en workspace sin cache
                            local char = LocalPlayer.Character
                            if char then
                                for _, obj in ipairs(workspace:GetDescendants()) do
                                    if obj:IsA("Tool") then
                                        local nm = obj.Name:lower()
                                        if _GUN_NAMES[obj.Name] or nm:find("gun") or nm:find("sheriff") then
                                            local inPlayer = false
                                            for _, p in pairs(_cachedPlayers) do
                                                local c2 = p.Character; local b2 = p.Backpack
                                                if (c2 and obj:IsDescendantOf(c2)) or (b2 and obj:IsDescendantOf(b2)) then
                                                    inPlayer = true; break
                                                end
                                            end
                                            if not inPlayer then
                                                pcall(_fluidGrabGun, obj)
                                                if _findGun(char) then break end
                                            end
                                        end
                                    end
                                end
                            end
                            task.wait(0.1)
                        end
                    end)
                end)
            end)
        else
            if GrabState._agConn      then GrabState._agConn:Disconnect();      GrabState._agConn      = nil end
            if GrabState._hbConn      then GrabState._hbConn:Disconnect();      GrabState._hbConn      = nil end
            if GrabState._agRoundConn then pcall(function() GrabState._agRoundConn:Disconnect() end); GrabState._agRoundConn = nil end
        end
    end, GrabState.autoEnabled)

    -- ==============================================================
    -- NOTIFICACIONES & INFO -- sincronizadas con GunDrop
    -- ==============================================================
    do
        -- Nombres validos de gun drop en MM2
        local _GUN_NAMES = {GunDrop=true, DropGun=true, Gun=true, SheriffGun=true, HeroGun=true}

        -- -- 1. Auto Notify on Dropped Gun ---------------------------------
        -- Detecta cuando aparece o desaparece un GunDrop en workspace
        -- y notifica al jugador con sonido + notificacion hub.
        local _notifDropConn = nil
        local _notifDropRemConn = nil

        WorldSystem.notif = WorldSystem.notif or {}

        CreateAuroraToggle(rightColumn, "Auto Notify on Dropped Gun", function(on)
            WorldSystem.notif.droppedGun = on
            -- Limpiar conexiones anteriores
            if _notifDropConn    then pcall(function() _notifDropConn:Disconnect()    end); _notifDropConn    = nil end
            if _notifDropRemConn then pcall(function() _notifDropRemConn:Disconnect() end); _notifDropRemConn = nil end
            WorldSystem.notif.droppedConn = nil

            if on then
                -- Helper: verifica si un objeto es hijo de un Character de jugador
                local function _isInPlayerChar(obj)
                    local par = obj.Parent
                    if not par then return false end
                    -- Tool directamente en un Character (par es el Model del personaje)
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p.Character and (par == p.Character or par.Parent == p.Character) then
                            return true
                        end
                    end
                    return false
                end

                -- Notificar cuando aparece la gun
                _notifDropConn = workspace.DescendantAdded:Connect(function(obj)
                    if not WorldSystem.notif.droppedGun then return end
                    if not _GUN_NAMES[obj.Name] then return end
                    -- Verificar que sea un Tool o BasePart (no un folder interno)
                    if not (obj:IsA("Tool") or obj:IsA("BasePart") or obj:IsA("Model")) then return end
                    -- FIX: ignorar si la gun esta dentro del personaje de un jugador
                    -- (Sheriff/Hero equipando su gun de rol al inicio de ronda)
                    if _isInPlayerChar(obj) then return end
                    -- Solo si el gun esta en workspace suelto (no en un personaje)
                    local par = obj.Parent
                    if par == workspace or (par and par.Parent == workspace) then
                        CreateCustomNotification(" GUN DROP", "!Aparecio una Gun en el mapa!", 4)
                        -- Sonido opcional
                        pcall(function()
                            local snd = Instance.new("Sound", workspace)
                            snd.SoundId = "rbxassetid://4612390796"
                            snd.Volume  = 0.6
                            snd:Play()
                            game:GetService("Debris"):AddItem(snd, 3)
                        end)
                    end
                end)
                WorldSystem.notif.droppedConn = _notifDropConn

                -- Notificar cuando desaparece (alguien la agarro)
                _notifDropRemConn = workspace.DescendantRemoving:Connect(function(obj)
                    if not WorldSystem.notif.droppedGun then return end
                    if not _GUN_NAMES[obj.Name] then return end
                    if not (obj:IsA("Tool") or obj:IsA("BasePart") or obj:IsA("Model")) then return end
                    -- FIX: ignorar si la gun viene de/va a un personaje (equip/unequip de rol)
                    if _isInPlayerChar(obj) then return end
                    local par = obj.Parent
                    if par == workspace or (par and par.Parent == workspace) then
                        CreateCustomNotification(" GUN DROP", "La Gun fue recogida", 2)
                    end
                end)

                CreateCustomNotification("AUTO NOTIFY", "Notificaciones de Gun Drop ON", 2)
            else
                CreateCustomNotification("AUTO NOTIFY", "Notificaciones de Gun Drop OFF", 2)
            end
        end, WorldSystem.notif.droppedGun)

        -- -- 2. Gun Pickup Notify --------------------------------------------
        -- Detecta cuando el LocalPlayer agarra la gun (Tool entra en su Character)
        -- y cuando la suelta, notificando en ambos casos.
        -- FIX: Solo notifica si el jugador NO es Sheriff/Hero con su gun de rol,
        -- o si la gun es un pickup real del suelo (GunDrop/DropGun).
        local _pickupConn = nil
        -- Guns de rol nativas: el Sheriff/Hero las recibe al inicio de ronda, NO son pickup
        local _ROLE_GUN_NAMES = {SheriffGun=true, HeroGun=true, Gun=true}
        -- Solo estas son pickup real del suelo
        local _DROP_GUN_NAMES = {GunDrop=true, DropGun=true}

        CreateAuroraToggle(rightColumn, "Gun Pickup Notify", function(on)
            WorldSystem.notif.gunPickupNotify = on
            if _pickupConn then pcall(function() _pickupConn:Disconnect() end); _pickupConn = nil end

            if on then
                local function _watchChar(char)
                    if not char then return end
                    -- Detectar cuando entra la gun al personaje
                    char.ChildAdded:Connect(function(obj)
                        if not WorldSystem.notif.gunPickupNotify then return end
                        if not (obj:IsA("Tool") and _GUN_NAMES[obj.Name]) then return end
                        -- FIX: ignorar si es la gun nativa del rol Sheriff/Hero
                        -- (SheriffGun, HeroGun, Gun asignada por el juego al inicio de ronda)
                        local localRole = _roleCache and _roleCache.localRole or ""
                        if _ROLE_GUN_NAMES[obj.Name] and
                           (localRole == "Sheriff" or localRole == "Hero") then
                            return  -- gun de rol, no es un pickup del suelo
                        end
                        CreateCustomNotification(" GUN", "!Agarraste la Gun!", 3)
                        pcall(function()
                            local snd = Instance.new("Sound", workspace)
                            snd.SoundId = "rbxassetid://9125402735"
                            snd.Volume  = 0.5
                            snd:Play()
                            game:GetService("Debris"):AddItem(snd, 2)
                        end)
                    end)
                    -- Detectar cuando la suelta
                    char.ChildRemoved:Connect(function(obj)
                        if not WorldSystem.notif.gunPickupNotify then return end
                        if not (obj:IsA("Tool") and _GUN_NAMES[obj.Name]) then return end
                        -- FIX: ignorar cuando el Sheriff/Hero desequipa su gun de rol
                        local localRole = _roleCache and _roleCache.localRole or ""
                        if _ROLE_GUN_NAMES[obj.Name] and
                           (localRole == "Sheriff" or localRole == "Hero") then
                            return  -- desequipar gun de rol no es "soltar" el arma
                        end
                        CreateCustomNotification(" GUN", "Soltaste la Gun", 2)
                    end)
                end

                -- Personaje actual
                _watchChar(LocalPlayer.Character)

                -- Futuros respawns
                _pickupConn = LocalPlayer.CharacterAdded:Connect(function(char)
                    if WorldSystem.notif.gunPickupNotify then
                        _watchChar(char)
                    end
                end)

                CreateCustomNotification("GUN PICKUP", "Notificacion de pickup ON", 2)
            else
                CreateCustomNotification("GUN PICKUP", "Notificacion de pickup OFF", 2)
            end
        end, WorldSystem.notif.gunPickupNotify)
    end

end


function CreateWorldUI_FreezeCharacter()
    local _sec = CreateSection(leftColumn, "", "  FREEZE CHARACTER", ThemeColors.Aurora2)

    _G._freezeCharState = _G._freezeCharState or {
        enabled      = false,
        frozenCFrame = nil,
        heartConn    = nil,
        savedTracks  = {},
        transparency = 0,
        invis        = false,
        invisConn    = nil,
    }
    local FS = _G._freezeCharState

    -- -- Helpers ----------------------------------------------------------

    local function _freezeGetChar()
        return LocalPlayer and LocalPlayer.Character
    end

    local function _freezeApplyTransparency(t)
        local char = _freezeGetChar()
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                pcall(function() part.Transparency = t end)
            end
        end
    end

    local function _freezeRestoreTransparency()
        local char = _freezeGetChar()
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                pcall(function() part.Transparency = 0 end)
            end
        end
    end

    local function _freezeStop()
        FS.enabled = false
        if FS.heartConn then
            pcall(function() FS.heartConn:Disconnect() end)
            FS.heartConn = nil
        end
        local char = _freezeGetChar()
        if char then
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") then
                    pcall(function()
                        part.Anchored                = false
                        part.AssemblyLinearVelocity  = Vector3.zero
                        part.AssemblyAngularVelocity = Vector3.zero
                    end)
                end
            end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function() hum.WalkSpeed  = 16 end)
                pcall(function() hum.JumpHeight = 7.2 end)
            end
        end
        if not FS.invis then _freezeRestoreTransparency() end
        FS.frozenCFrame = nil
    end

    local function _freezeStart()
        local char = _freezeGetChar()
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        if not root then return end

        FS.enabled      = true
        FS.frozenCFrame = root.CFrame

        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function() hum.WalkSpeed  = 0 end)
            pcall(function() hum.JumpHeight = 0 end)
        end

        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function()
                    part.AssemblyLinearVelocity  = Vector3.zero
                    part.AssemblyAngularVelocity = Vector3.zero
                    part.Anchored                = true
                end)
            end
        end

        _freezeApplyTransparency(FS.transparency)

        if FS.heartConn then pcall(function() FS.heartConn:Disconnect() end) end
        local _fsTick = 0
        FS.heartConn = RunService.Heartbeat:Connect(function(dt)
            if not FS.enabled then return end
            -- 20Hz is plenty for position lock (server reconciles anyway)
            _fsTick = _fsTick + dt
            if _fsTick < 0.05 then return end
            _fsTick = 0
            local c = _freezeGetChar()
            if not c then return end
            local r = c:FindFirstChild("HumanoidRootPart")
            if not r or not FS.frozenCFrame then return end
            pcall(function()
                r.CFrame = FS.frozenCFrame
                r.AssemblyLinearVelocity  = Vector3.zero
                r.AssemblyAngularVelocity = Vector3.zero
            end)
        end)
    end

    -- -- Toggle: Freeze Player --------------------------------------------
    CreateAuroraToggle(_sec, "Freeze Player", function(on)
        if on then
            _freezeStart()
            CreateCustomNotification(" FREEZE", "Te congelaste en tu posicion actual", 2)
        else
            _freezeStop()
            CreateCustomNotification(" FREEZE", "Descongelado", 1.5)
        end
    end, FS.enabled)

    -- -- Slider: Transparencia del personaje congelado ---------------------
    CreateSlider(_sec, "Transparencia (%)", 0, 100, math.floor(FS.transparency * 100), function(v)
        FS.transparency = v / 100
        if FS.enabled then
            _freezeApplyTransparency(FS.transparency)
        end
    end)

    -- -- Toggle: Invisible al congelarse ---------------------------------
    CreateAuroraToggle(_sec, "Invisible al congelarse", function(on)
        FS.invis = on
        if FS.invisConn then pcall(function() FS.invisConn:Disconnect() end); FS.invisConn = nil end
        if on then
            -- Volverte invisible ahora si ya estas congelado
            if FS.enabled then _freezeApplyTransparency(1) end
            -- Y en cada respawn futuro
            FS.invisConn = LocalPlayer.CharacterAdded:Connect(function()
                task.wait(0.3)
                if FS.invis and FS.enabled then _freezeApplyTransparency(1) end
            end)
            CreateCustomNotification(" FREEZE", "Invisible al congelar: ON", 2)
        else
            -- Restaurar transparencia del slider
            if FS.enabled then
                _freezeApplyTransparency(FS.transparency)
            else
                _freezeRestoreTransparency()
            end
            CreateCustomNotification(" FREEZE", "Invisible al congelar: OFF", 1.5)
        end
    end, false)

    -- -- Slider: Walk Speed (para cuando descongelas) ----------------------
    CreateSlider(_sec, "Walk Speed al descongelar", 0, 100, 16, function(v)
        _G._freezeRestoreWalkSpeed = v
        -- Si ya esta descongelado, aplicar directo
        if not FS.enabled then
            local char = _freezeGetChar()
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then pcall(function() hum.WalkSpeed = v end) end
        end
    end)

end
-- ========================================================================

function CreateWorldUI_InfinityJumpMovement()
 CreateSection(rightColumn, "", "INFINITY JUMP", ThemeColors.Aurora2)

        -- FIX: mover ijState a _G para que sobreviva entre cambios de tab
        _G._ijState = _G._ijState or { enabled = false, power = 50, conn = nil, stateConn = nil, charConn = nil, maxJumps = 0, jumpCount = 0 }
        local ijState = _G._ijState

        local function _ijConnectChar(char, hum)
            if ijState.conn      then ijState.conn:Disconnect();      ijState.conn = nil end
            if ijState.stateConn then ijState.stateConn:Disconnect(); ijState.stateConn = nil end
            if not char or not hum then return end
            ijState.jumpCount = 0
            ijState.conn = hum:GetPropertyChangedSignal("Jump"):Connect(function()
                if not ijState.enabled or not hum.Jump then return end
                if ijState.maxJumps ~= 0 and ijState.jumpCount >= ijState.maxJumps then return end
                ijState.jumpCount = ijState.jumpCount + 1
                local r = char:FindFirstChild("HumanoidRootPart")
                if r then
                    r.AssemblyLinearVelocity = Vector3.new(
                        r.AssemblyLinearVelocity.X, ijState.power, r.AssemblyLinearVelocity.Z)
                end
            end)
            -- FIX: StateChanged es mas confiable que hum.Jump==false para resetear en aterrizaje
            ijState.stateConn = hum.StateChanged:Connect(function(_, newState)
                if not ijState.enabled then return end
                if newState == Enum.HumanoidStateType.Landed
                or newState == Enum.HumanoidStateType.Running
                or newState == Enum.HumanoidStateType.RunningNoPhysics then
                    ijState.jumpCount = 0
                end
            end)
        end

 CreateAuroraToggle(rightColumn, "Infinity Jump", function(enabled)
            ijState.enabled = enabled
            if not enabled then
                if ijState.conn      then ijState.conn:Disconnect();      ijState.conn = nil end
                if ijState.stateConn then ijState.stateConn:Disconnect(); ijState.stateConn = nil end
            end
            if enabled then
                local char = LocalPlayer.Character
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                _ijConnectChar(char, hum)
                if ijState.charConn then ijState.charConn:Disconnect() end
                ijState.charConn = LocalPlayer.CharacterAdded:Connect(function(c)
                    if not ijState.enabled then return end
                    local h = c:WaitForChild("Humanoid")
                    _ijConnectChar(c, h)
                end)
 -- [notif removed]
            else
 -- [notif removed]
            end
        end, ijState.enabled)

 CreateSlider(rightColumn, "Infinity Jump Power", 10, 200, ijState.power, function(v)
            ijState.power = v
        end)

 CreateSlider(rightColumn, "Max Jumps (0 = infinito)", 0, 20, 0, function(v)
            ijState.maxJumps = v
        end)

 CreateSection(rightColumn, "", "CAMERA NOCLIP", ThemeColors.Primary)

 do
    -- -- CAMERA NOCLIP --------------------------------------------
    local _camNC_conn   = nil
    local _camNC_speed  = 32
    local _camNC_active = false

    local function _startCamNoclip()
        if _camNC_conn then pcall(function() _camNC_conn:Disconnect() end) end
        local cam = _Camera
        cam.CameraType = Enum.CameraType.Scriptable

        -- guardar CFrame inicial
        local cf = cam.CFrame

        _camNC_conn = RunService.RenderStepped:Connect(function(dt)
            if not _camNC_active then return end
            cam = _Camera
            local move = Vector3.new()
            if UserInputService:IsKeyDown(Enum.KeyCode.W) or UserInputService:IsKeyDown(Enum.KeyCode.Up)    then move = move + cam.CFrame.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) or UserInputService:IsKeyDown(Enum.KeyCode.Down)  then move = move - cam.CFrame.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.Left)  then move = move - cam.CFrame.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) or UserInputService:IsKeyDown(Enum.KeyCode.Right) then move = move + cam.CFrame.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.E) or UserInputService:IsKeyDown(Enum.KeyCode.Space) then move = move + Vector3.new(0,1,0) end
            if UserInputService:IsKeyDown(Enum.KeyCode.Q) or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then move = move - Vector3.new(0,1,0) end
            if move.Magnitude > 0.01 then
                cam.CFrame = cam.CFrame + move.Unit * _camNC_speed * dt
            end
        end)
    end

    local function _stopCamNoclip()
        _camNC_active = false
        if _camNC_conn then pcall(function() _camNC_conn:Disconnect() end); _camNC_conn = nil end
        pcall(function()
            local cam = _Camera
            cam.CameraType = Enum.CameraType.Custom
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            cam.CameraSubject = hum or (char and char:FindFirstChild("HumanoidRootPart"))
        end)
    end

    CreateToggle(rightColumn, "Camera Noclip", function(enabled)
        _camNC_active = enabled
        if enabled then
            _startCamNoclip()
            CreateCustomNotification("CAM NOCLIP", "Activo -- WASD/QE para mover", 2.5)
        else
            _stopCamNoclip()
            CreateCustomNotification("CAM NOCLIP", "Desactivado -- camara restaurada", 2)
        end
    end, false)

    -- Slider de velocidad
    CreateSlider(rightColumn, "Camera Speed", 5, 200, 32, function(v)
        _camNC_speed = v
    end)

    -- -- BOTON: Restablecer camara ---------------------------------
    local _sec = _currentMainSectionFrame or rightColumn
    local _resetCamContainer = Instance.new("Frame", _sec)
    _resetCamContainer.Name                   = "ResetCameraBtnContainer"
    _resetCamContainer.Size                   = UDim2.new(1, 0, 0, 84)
    _resetCamContainer.BackgroundTransparency = 1
    _resetCamContainer.BorderSizePixel        = 0
    _resetCamContainer.ZIndex                 = 20
    local resetBtn = Instance.new("TextButton", _resetCamContainer)
    resetBtn.Name                  = "ResetCameraBtn"
    resetBtn.Size                  = UDim2.new(1, -20, 0, 36)
    resetBtn.Position              = UDim2.new(0, 10, 0.5, -18)
    resetBtn.BackgroundColor3      = ThemeColors.Background
    resetBtn.BackgroundTransparency = 0.05
    resetBtn.BorderSizePixel       = 0
    resetBtn.Text                  = "  Restablecer Camara"
    resetBtn.TextColor3            = ThemeColors.TextPrimary
    resetBtn.FontFace              = Font.fromEnum(Enum.Font.GothamBold)
    resetBtn.TextSize              = 13
    resetBtn.AutoButtonColor       = false
    resetBtn.ZIndex                = 14
    Instance.new("UICorner", resetBtn).CornerRadius = UDim.new(0, 8)
    local _rbStroke = Instance.new("UIStroke", resetBtn)
    _rbStroke.Color     = ThemeColors.Primary
    _rbStroke.Thickness = 1.5
    _rbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local _rbPad = Instance.new("UIPadding", resetBtn)
    _rbPad.PaddingLeft = UDim.new(0, 8)

    -- Hover
    resetBtn.MouseEnter:Connect(function()
        TweenService:Create(resetBtn, TweenInfo.new(0.12), {BackgroundTransparency = 0.05}):Play()
    end)
    resetBtn.MouseLeave:Connect(function()
        TweenService:Create(resetBtn, TweenInfo.new(0.12), {BackgroundTransparency = 0.25}):Play()
    end)

    resetBtn.Activated:Connect(function()
        -- Forzar desactivacion del noclip si estaba activo
        if _camNC_active then
            _camNC_active = false
            if _camNC_conn then pcall(function() _camNC_conn:Disconnect() end); _camNC_conn = nil end
        end
        pcall(function()
            local cam = _Camera
            cam.CameraType = Enum.CameraType.Custom
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            cam.CameraSubject = hum or (char and char:FindFirstChild("HumanoidRootPart"))
        end)
        CreateCustomNotification("CAMARA", "Restablecida correctamente", 2)
    end)
 end
end

function CreateWorldUI_Spectate()
 local _specSec = CreateSection(rightColumn, "", "SPECTATE PLAYERS", ThemeColors.Aurora1)

        -- FIX: usar estado global para que las conexiones se puedan limpiar al reabrir el tab
        local specState = WorldSystem.spectate
        -- Limpiar conexiones viejas antes de reconstruir la UI
        local _wasSpectating = specState.enabled
        if specState.camConn then pcall(function() specState.camConn:Disconnect() end) specState.camConn = nil end
        if specState.conn    then pcall(function() specState.conn:Disconnect()    end) specState.conn    = nil end
        specState.enabled = false
        -- FIX: solo restaurar camara si realmente estaba spectando (no tocar la camara en el caso normal)
        if _wasSpectating then
            pcall(function()
                local cam = _Camera
                cam.CameraType = Enum.CameraType.Custom
                local myChar = LocalPlayer.Character
                if myChar then
                    local myHum = myChar:FindFirstChildOfClass("Humanoid")
                    cam.CameraSubject = myHum or myChar:FindFirstChild("HumanoidRootPart")
                end
            end)
        end

        local function GetAlivePlayers()
            local list = {}
            for _, p in pairs(_cachedPlayers) do
                if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                and p.Character:FindFirstChildOfClass("Humanoid")
                and p.Character:FindFirstChildOfClass("Humanoid").Health > 0 then
                    table.insert(list, p)
                end
            end
            return list
        end

        function StopSpectate()
            specState.enabled = false
            if specState.camConn then specState.camConn:Disconnect() specState.camConn = nil end
            local cam = _Camera
            cam.CameraType = Enum.CameraType.Custom
            local myChar = LocalPlayer.Character
            
            --  FIX: Verificar si Ghost esta activo
            local IG = MainSystem and MainSystem.state and MainSystem.state.invisibleGhost
            local isGhostActive = IG and IG.enabled
            
            if myChar then
                if not isGhostActive then
                    -- Normal: restaurar a humanoid real
                    local myHum = myChar:FindFirstChildOfClass("Humanoid")
                    cam.CameraSubject = myHum or myChar:FindFirstChild("HumanoidRootPart")
                else
                    -- Ghost activo: restaurar a clone
                    if IG.ghostClone and IG.ghostClone:FindFirstChildOfClass("Humanoid") then
                        cam.CameraSubject = IG.ghostClone:FindFirstChildOfClass("Humanoid")
                    end
                end
            end
 CreateCustomNotification("SPECTATE", " Spectate desactivado", 2)
        end

        function StartSpectate(target)
            if not target or not target.Character then
 CreateCustomNotification("SPECTATE", "El jugador no tiene personaje", 2)
                return
            end
            
            -- FIX: Desactivar Ghost si esta activo para que spectate funcione
            local IG = MainSystem and MainSystem.state and MainSystem.state.invisibleGhost
            local wasGhostActive = IG and IG.enabled
            if wasGhostActive then
                IG.enabled = false
 CreateCustomNotification("SPECTATE", "Ghost desactivado temporalmente para spectate", 2)
            end
            
            if specState.camConn then specState.camConn:Disconnect() specState.camConn = nil end
            specState.enabled = true
            local cam = _Camera
            cam.CameraType = Enum.CameraType.Custom
            local targetHum = target.Character:FindFirstChildOfClass("Humanoid")
            local targetHRP = target.Character:FindFirstChild("HumanoidRootPart")
            
            cam.CameraSubject = targetHum or targetHRP

            local _hbTspecCam = 0
            specState.camConn = RunService.Heartbeat:Connect(function()
                _hbTspecCam=_hbTspecCam+1; if _hbTspecCam<3 then return end; _hbTspecCam=0
                if not specState.enabled then
                    if specState.camConn then specState.camConn:Disconnect() specState.camConn = nil end
                    -- Reactivar ghost si estaba activo
                    if wasGhostActive and IG then
                        IG.enabled = true
 CreateCustomNotification("SPECTATE", "Ghost reactivado", 2)
                    end
                    return
                end
                if not target or not target.Parent then
                    StopSpectate()
                    return
                end
                local tChar = target.Character
                if not tChar then return end
                local tHum = tChar:FindFirstChildOfClass("Humanoid")
                local tHRP = tChar:FindFirstChild("HumanoidRootPart")
                
                if tHum and cam.CameraSubject ~= tHum then
                    cam.CameraSubject = tHum
                elseif tHRP and not tHum and cam.CameraSubject ~= tHRP then
                    cam.CameraSubject = tHRP
                end
            end)
 CreateCustomNotification("SPECTATE", " Spectando: " .. target.Name, 3)
        end

        specSelector = Instance.new("Frame", _specSec)
        specSelector.Size = UDim2.new(1, -10, 0, 50)
        specSelector.BackgroundColor3 = ThemeColors.BackgroundLight
        specSelector.BackgroundTransparency = 1
        specSelector.BorderSizePixel = 0
        Instance.new("UICorner", specSelector).CornerRadius = UDim.new(0, 8)
        selectorStroke = Instance.new("UIStroke", specSelector)
        selectorStroke.Color = ThemeColors.Aurora1
        selectorStroke.Thickness = 2.5

        specTargetLabel = Instance.new("TextLabel", specSelector)
        specTargetLabel.Size = UDim2.new(1, -10, 1, 0)
        specTargetLabel.Position = UDim2.new(0, 10, 0, 0)
        specTargetLabel.BackgroundTransparency = 1
 specTargetLabel.Text = "Target: ninguno seleccionado"
        specTargetLabel.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        specTargetLabel.TextSize = 11
        specTargetLabel.TextColor3 = ThemeColors.Aurora1
        specTargetLabel.TextXAlignment = Enum.TextXAlignment.Left
        specTargetLabel.ZIndex = 2

        _specSelectedPlayer = nil
        _specPlayerList = {}

        local function _refreshSpecList()
            _specPlayerList = {}
            for _, p in pairs(_cachedPlayers) do
                if p ~= LocalPlayer then
                    table.insert(_specPlayerList, p.Name)
                end
            end
            if #_specPlayerList == 0 then _specPlayerList = {"(sin jugadores)"} end
        end

        _refreshSpecList()
 CreateNebulaSelector(_specSec, "Seleccionar Jugador", _specPlayerList, _specPlayerList[1], function(name)
            _specSelectedPlayer = name
            t = Players:FindFirstChild(name)
            if t then
 specTargetLabel.Text = "Target: " .. name .. " [" .. GetPlayerRole(t) .. "]"
            else
 specTargetLabel.Text = "Target: " .. name
            end
        end)

        btnRow = Instance.new("Frame", _specSec)
        btnRow.Size = UDim2.new(1, -10, 0, 36)
        btnRow.BackgroundTransparency = 1
        rowLayout = Instance.new("UIListLayout", btnRow)
        rowLayout.FillDirection = Enum.FillDirection.Horizontal
        rowLayout.Padding = UDim.new(0, 6)

        function MakeSpecBtn(txt, color, cb)
            local b = Instance.new("TextButton", btnRow)
            b.Size = UDim2.new(0, 80, 1, 0)
            b.BackgroundColor3 = color
            b.BackgroundTransparency = 0.9
 b.Text = txt
            b.FontFace = Font.fromEnum(Enum.Font.Montserrat)
            b.TextSize = 11
            b.TextColor3 = Color3.fromRGB(255, 255, 255)
            b.BorderSizePixel = 0
            b.AutoButtonColor = false
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
            b.Activated:Connect(function()

                cb()
            end)
            return b
        end

        MakeSpecBtn(" Spectate", ThemeColors.Primary, function()
            if _specSelectedPlayer then
                local t = Players:FindFirstChild(_specSelectedPlayer)
                if t then
                    StartSpectate(t)
 specTargetLabel.Text = "Target: " .. _specSelectedPlayer .. " [" .. GetPlayerRole(t) .. "]"
                else
 CreateCustomNotification("SPECTATE", "Jugador no encontrado: " .. tostring(_specSelectedPlayer), 2)
                end
            else
 CreateCustomNotification("SPECTATE", "Selecciona un jugador primero", 2)
            end
        end)

        MakeSpecBtn(" Prev", ThemeColors.Aurora2, function()
            targets = GetAlivePlayers()
 if #targets == 0 then CreateCustomNotification("SPECTATE", "No hay jugadores vivos", 2) return end
            specState.currentIndex = specState.currentIndex - 1
            if specState.currentIndex < 1 then specState.currentIndex = #targets end
            t = targets[specState.currentIndex]
 specTargetLabel.Text = "Target: " .. t.Name .. " [" .. GetPlayerRole(t) .. "]"
            StartSpectate(t)
        end)

        MakeSpecBtn(" Next", ThemeColors.Aurora3, function()
            targets = GetAlivePlayers()
 if #targets == 0 then CreateCustomNotification("SPECTATE", "No hay jugadores vivos", 2) return end
            specState.currentIndex = specState.currentIndex + 1
            if specState.currentIndex > #targets then specState.currentIndex = 1 end
            t = targets[specState.currentIndex]
 specTargetLabel.Text = "Target: " .. t.Name .. " [" .. GetPlayerRole(t) .. "]"
            StartSpectate(t)
        end)

        MakeSpecBtn(" Stop", ThemeColors.Aurora1, function()
            StopSpectate()
 specTargetLabel.Text = "Target: ninguno seleccionado"
        end)

 CreateAuroraToggle(_specSec, " Auto Spectate Murder", function(enabled)
            specState.enabled = enabled
            if specState.conn then specState.conn:Disconnect() specState.conn = nil end
            if enabled then
                local _hbTspecConn = 0
                -- ROL CACHE: guardar el murder encontrado para no llamar findMurderer() cada frame.
                -- Solo se invalida si el murder muere, pierde el personaje, o cambia de ronda.
                local _cachedMurder   = nil   -- Player cacheado
                local _cachedHum      = nil   -- Humanoid cacheado
                local _cachedHrp      = nil   -- HumanoidRootPart cacheado
                local _cacheRoundTok  = nil   -- token de ronda al cachear
                local _cacheDeathConn = nil   -- conexion Died del murder cacheado

                local function _invalidateCache()
                    _cachedMurder = nil
                    _cachedHum    = nil
                    _cachedHrp    = nil
                    _cacheRoundTok = nil
                    if _cacheDeathConn then
                        pcall(function() _cacheDeathConn:Disconnect() end)
                        _cacheDeathConn = nil
                    end
                end

                local function _rebuildCache(murder)
                    _invalidateCache()
                    if not murder or not murder.Character then return end
                    _cachedMurder  = murder
                    _cachedHum     = murder.Character:FindFirstChildOfClass("Humanoid")
                    _cachedHrp     = murder.Character:FindFirstChild("HumanoidRootPart")
                    _cacheRoundTok = _G._sgRoundToken or 0
                    -- Invalidar cache si el murder muere
                    if _cachedHum then
                        _cacheDeathConn = _cachedHum.Died:Connect(_invalidateCache)
                    end
                end

                specState.conn = RunService.Heartbeat:Connect(function()
                    _hbTspecConn=_hbTspecConn+1; if _hbTspecConn<3 then return end; _hbTspecConn=0
                    if not specState.enabled then return end
                    if _G._visualRoundOver then _invalidateCache(); return end

                    -- Invalidar cache si cambio de ronda
                    local curTok = _G._sgRoundToken or 0
                    if _cacheRoundTok ~= curTok then _invalidateCache() end

                    -- Validar cache: si el murder cacheado ya no tiene personaje, invalidar
                    if _cachedMurder and (not _cachedMurder.Character or not _cachedMurder.Parent) then
                        _invalidateCache()
                    end

                    -- Si no hay cache valido, buscar el murder ahora
                    if not _cachedMurder then
                        local murder = findMurderer()
                        if murder and murder.Character then
                            _rebuildCache(murder)
                        end
                    end

                    -- Spectate usando el cache
                    if _cachedMurder and (_cachedHum or _cachedHrp) then
                        local cam = _Camera
                        cam.CameraType = Enum.CameraType.Custom
                        if _cachedHum then cam.CameraSubject = _cachedHum
                        else cam.CameraSubject = _cachedHrp end
                    end
                end)
 CreateCustomNotification("SPECTATE", " Auto-spectando al Murder", 3)
            else
                StopSpectate()
 specTargetLabel.Text = "Target: ninguno seleccionado"
            end
        end, false)
end


function CreateWorldUI_Performance()
    local sec = CreateSection(rightColumn, "", "! PERFORMANCE", ThemeColors.Aurora3)
    _currentMainSectionFrame = sec

    -- ================================================================
    -- FPS BOOST (TOGGLE PERSISTENTE - MEJORADO)
    -- Aplica optimizaciones al mapa al activar y restaura al desactivar.
    -- Ahora como toggle para que se re-aplique en cada respawn/ronda.
    -- ================================================================
    _G._fpsBState = _G._fpsBState or { enabled = false, conn = nil, origMat = {}, origRef = {}, origShadow = {} }
    local _fbs = _G._fpsBState

    local _fpsBSkipModels = {}
    local _fpsBSkipKw = {
        "knife","gun","ladder","stair","step","handle",
        "weapon","tool","ramp","gundrop","knifemodel",
        "spawn","spawnlocation","coin","bomb","sheriff",
        "murderer","trigger","zone","detector","sensor",
        "victory","round","event","checkpoint"
    }
    local function _fpsBShouldSkip(p)
        local par = p.Parent
        while par and par ~= workspace do
            if _fpsBSkipModels[par] then return true end
            if par:IsA("Tool") then return true end
            local pnl = par.Name:lower()
            for _, kw in ipairs(_fpsBSkipKw) do
                if pnl:find(kw) then return true end
            end
            par = par.Parent
        end
        return false
    end

    local function _applyFpsBoost()
        -- Reconstruir skip list de personajes
        _fpsBSkipModels = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr.Character then _fpsBSkipModels[plr.Character] = true end
            local bp = plr:FindFirstChildOfClass("Backpack")
            if bp then _fpsBSkipModels[bp] = true end
        end
        local n = 0
        for _, p in ipairs(workspace:GetDescendants()) do
            if (p:IsA("BasePart") or p:IsA("MeshPart")) and not _fpsBShouldSkip(p) then
                pcall(function()
                    -- Guardar originales solo la primera vez
                    if not _fbs.origMat[p] then
                        _fbs.origMat[p]    = p.Material
                        _fbs.origRef[p]    = p.Reflectance
                        _fbs.origShadow[p] = p.CastShadow
                    end
                    p.Material    = Enum.Material.SmoothPlastic
                    p.Reflectance = 0
                    p.CastShadow  = false
                end)
                n = n + 1
            end
        end
        -- Calidad de render minima
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        -- Desactivar sombras globales
        pcall(function() game:GetService("Lighting").GlobalShadows = false end)
        -- Apagar particulas del workspace
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
                pcall(function() obj.Enabled = false end)
            end
        end
        return n
    end

    local function _restoreFpsBoost()
        for p, mat in pairs(_fbs.origMat) do
            pcall(function()
                if p and p.Parent then
                    p.Material    = mat
                    p.Reflectance = _fbs.origRef[p] or 0
                    p.CastShadow  = _fbs.origShadow[p] ~= nil and _fbs.origShadow[p] or true
                end
            end)
        end
        _fbs.origMat = {}; _fbs.origRef = {}; _fbs.origShadow = {}
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic end)
        pcall(function() game:GetService("Lighting").GlobalShadows = true end)
    end

    CreateAuroraToggle(sec, "FPS Boost (Toggle)", function(on)
        _fbs.enabled = on
        if _fbs.conn then pcall(function() _fbs.conn:Disconnect() end); _fbs.conn = nil end
        if on then
            local n = _applyFpsBoost()
            -- Re-aplicar cuando se agregen nuevas partes (nueva ronda/mapa)
            _fbs.conn = workspace.DescendantAdded:Connect(function(obj)
                if not _fbs.enabled then return end
                if (obj:IsA("BasePart") or obj:IsA("MeshPart")) and not _fpsBShouldSkip(obj) then
                    pcall(function()
                        if not _fbs.origMat[obj] then
                            _fbs.origMat[obj]    = obj.Material
                            _fbs.origRef[obj]    = obj.Reflectance
                            _fbs.origShadow[obj] = obj.CastShadow
                        end
                        obj.Material    = Enum.Material.SmoothPlastic
                        obj.Reflectance = 0
                        obj.CastShadow  = false
                    end)
                end
            end)
            CreateCustomNotification("FPS BOOST", "ON ? " .. n .. " partes optimizadas", 3)
        else
            _restoreFpsBoost()
            CreateCustomNotification("FPS BOOST", "OFF ? graficos restaurados", 2)
        end
    end, _fbs.enabled)

    -- Boton one-shot (para aplicar rapido sin toggle)
    _makeTPButton("FPS Boost (One-Shot)", function()
        local n = _applyFpsBoost()
        CreateCustomNotification("FPS BOOST", "Aplicado ? " .. n .. " partes", 3)
    end, sec)

    -- ================================================================
    -- LESS LAG (sin cambios funcionales, preservado)
    -- ================================================================
    _makeTPButton("Less Lag", function()
        local n = 0
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("ParticleEmitter") or obj:IsA("Trail") or
               obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
                pcall(function() obj.Enabled = false end)
                n = n + 1
            end
        end
        CreateCustomNotification("LESS LAG", n .. " particulas/efectos desactivados", 3)
    end, sec)

    -- NO SHADOWS (seguro, sin cambios)
    CreateAuroraToggle(rightColumn, "No Shadows", function(on)
        pcall(function()
            game:GetService("Lighting").GlobalShadows = not on
            for _, p in ipairs(workspace:GetDescendants()) do
                if p:IsA("BasePart") or p:IsA("MeshPart") then
                    pcall(function() p.CastShadow = not on end)
                end
            end
        end)
        CreateCustomNotification("NO SHADOWS", on and "Sombras OFF" or "Sombras ON", 2)
    end, false)

    -- ================================================================
    -- REMOVE BARRIERS (TOGGLE PERSISTENTE - MEJORADO)
    -- Detecta barreras por: nombre con keyword, transparencia alta + colision,
    -- y partes invisibles sin nombre funcional. Persiste entre rondas.
    -- ================================================================
    _G._removeBarrState = _G._removeBarrState or { enabled = false, conn = nil, restored = {} }
    local _rbs = _G._removeBarrState

    -- Keywords que indican claramente que es una barrera invisible del mapa
    local _barrierKw = {
        "barrier","invis","invisible","bound","limit",
        "border","fence","clip","hitbox","noclip","nobuild"
    }
    -- Keywords que indican que es geometria funcional del mapa: NUNCA tocar
    local _safeKw = {
        "spawn","spawnlocation","coin","bomb","sheriff","murderer",
        "trigger","zone","detector","sensor","victory","round",
        "event","checkpoint","gun","knife","platform","floor",
        "ceiling","roof","door","ground","map","base","terrain",
        "stud","tile","grass","wood","stone","road","path","sand",
        "wall","block","collide","part","union","mesh","wedge",
        "ramp","step","stair","rail","pillar","column","beam"
    }

    local function _isBarrierPart(obj)
        if not (obj:IsA("BasePart") or obj:IsA("MeshPart")) then return false end
        if not obj.CanCollide then return false end
        local name = obj.Name:lower()

        -- Nunca tocar objetos con nombre funcional/geometria del mapa
        for _, kw in ipairs(_safeKw) do
            if name:find(kw) then return false end
        end

        -- Solo detectar como barrera si el NOMBRE lo indica explicitamente
        -- No usar transparencia: demasiado agresivo, rompe suelos/paredes/escaleras
        for _, kw in ipairs(_barrierKw) do
            if name:find(kw) then return true end
        end

        -- Parte completamente sin nombre ("Part", "BasePart") con transparencia = 1
        -- y sin padre reconocible: unico caso heuristico permitido
        if (name == "part" or name == "basepart" or name == "meshpart" or name == "unionoperation") then
            if obj.Transparency == 1 and obj.CanCollide then
                -- Verificar que no sea personaje ni tool
                local par = obj.Parent
                local isFunctional = false
                while par and par ~= workspace do
                    if par:IsA("Tool") or par:IsA("Hat") or par:IsA("Accessory")
                    or par:IsA("Model") then
                        isFunctional = true; break
                    end
                    par = par.Parent
                end
                if not isFunctional then return true end
            end
        end

        return false
    end

    local function _applyRemoveBarriers()
        local removed = 0
        for _, obj in ipairs(workspace:GetDescendants()) do
            if _isBarrierPart(obj) then
                pcall(function()
                    if not _rbs.restored[obj] then
                        _rbs.restored[obj] = obj.CanCollide
                    end
                    obj.CanCollide = false
                end)
                removed = removed + 1
            end
        end
        return removed
    end

    local function _restoreBarriers()
        for obj, orig in pairs(_rbs.restored) do
            if obj and obj.Parent then
                pcall(function() obj.CanCollide = orig end)
            end
        end
        _rbs.restored = {}
    end

    CreateAuroraToggle(sec, "Remove Barriers (Toggle)", function(on)
        _rbs.enabled = on
        if _rbs.conn then pcall(function() _rbs.conn:Disconnect() end); _rbs.conn = nil end
        if on then
            local removed = _applyRemoveBarriers()
            -- Re-aplicar en partes nuevas (nueva ronda/mapa)
            _rbs.conn = workspace.DescendantAdded:Connect(function(obj)
                if not _rbs.enabled then return end
                task.defer(function()
                    if _isBarrierPart(obj) then
                        pcall(function()
                            _rbs.restored[obj] = obj.CanCollide
                            obj.CanCollide = false
                        end)
                    end
                end)
            end)
            CreateCustomNotification("REMOVE BARRIERS", "ON ? " .. removed .. " barreras eliminadas", 3)
        else
            _restoreBarriers()
            CreateCustomNotification("REMOVE BARRIERS", "OFF ? colisiones restauradas", 2)
        end
    end, _rbs.enabled)

    -- Boton one-shot original (preservado)
    _makeTPButton("Remove Barriers (One-Shot)", function()
        local removed = _applyRemoveBarriers()
        CreateCustomNotification("REMOVE BARRIERS", removed .. " barriers eliminados", 3)
    end, sec)

    -- ================================================================
    -- GRAFICOS CARTON MEJORADOS (VISUAL ENHANCEMENT)
    -- Mejora la apariencia de los graficos de carton (SmoothPlastic)
    -- agregando colores ligeramente saturados, iluminacion limpia y
    -- efectos de post-procesado sutiles. SIN remover texturas.
    -- ================================================================
    _G._cartoonEnhState = _G._cartoonEnhState or {
        enabled      = false,
        conn         = nil,
        origColors   = {},
        origSmooth   = {},
        origSpecular = {},
        origBright   = nil,
        origClock    = nil,
        origFog      = nil,
        origBloom    = nil,
        bloomInst    = nil,
        corrInst     = nil,
    }
    local _ces = _G._cartoonEnhState

    -- Paleta de ajuste sutil de color: levemente mas saturada sin cambiar el tono
    local function _enhanceColor(c3)
        local h, s, v = Color3.toHSV(c3)
        -- Aumentar saturacion ligeramente (+15%), clampeado para no exagerar
        s = math.clamp(s * 1.15, 0, 1)
        -- Aumentar brillo muy poco (+5%) para que las partes oscuras no se vean apagadas
        v = math.clamp(v * 1.05, 0, 1)
        return Color3.fromHSV(h, s, v)
    end

    local function _cartoonEnhSkip(obj)
        local par = obj.Parent
        while par and par ~= workspace do
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Character == par then return true end
            end
            if par:IsA("Tool") or par:IsA("Hat") or par:IsA("Accessory") then return true end
            par = par.Parent
        end
        return false
    end

    local function _applyCartoonEnh()
        local L = game:GetService("Lighting")
        -- Guardar originales de lighting
        if not _ces.origBright then _ces.origBright = L.Brightness end
        if not _ces.origClock  then _ces.origClock  = L.ClockTime  end
        if not _ces.origFog    then _ces.origFog    = L.FogEnd      end

        -- Lighting limpio: mediod?a suave, sin niebla cercana
        pcall(function()
            L.Brightness  = math.min(L.Brightness + 0.5, 4)
            L.ClockTime   = 14   -- mediod?a (luz limpia y directa)
            L.FogEnd      = math.max(L.FogEnd, 100000)
        end)

        -- Agregar Bloom sutil si no existe
        if not _ces.bloomInst or not _ces.bloomInst.Parent then
            local existBloom = L:FindFirstChildOfClass("BloomEffect")
            if not existBloom then
                local bloom = Instance.new("BloomEffect", L)
                bloom.Intensity  = 0.4   -- sutil, no exagerado
                bloom.Size       = 16
                bloom.Threshold  = 0.9
                bloom.Enabled    = true
                _ces.bloomInst   = bloom
            else
                -- Guardar estado y ajustar el existente
                _ces.origBloom = { existBloom.Intensity, existBloom.Size, existBloom.Threshold, existBloom.Enabled }
                existBloom.Intensity = 0.4
                existBloom.Size      = 16
                existBloom.Threshold = 0.9
                existBloom.Enabled   = true
                _ces.bloomInst = existBloom
            end
        end

        -- ColorCorrection sutil para look mas vibrante
        if not _ces.corrInst or not _ces.corrInst.Parent then
            local existCorr = L:FindFirstChildOfClass("ColorCorrectionEffect")
            if not existCorr then
                local corr = Instance.new("ColorCorrectionEffect", L)
                corr.Saturation = 0.12   -- +12% saturacion global
                corr.Brightness = 0.02   -- poquito mas de brillo
                corr.Contrast   = 0.08   -- contraste ligeramente mayor
                corr.Enabled    = true
                _ces.corrInst   = corr
            else
                _ces.corrInst = existCorr
            end
        end

        -- Mejorar partes de tipo carton (SmoothPlastic / Neon existente)
        -- Solo ajustar color; NO cambiar Material ni remover texturas
        local n = 0
        for _, p in ipairs(workspace:GetDescendants()) do
            if (p:IsA("BasePart") or p:IsA("MeshPart")) and not _cartoonEnhSkip(p) then
                if p.Material == Enum.Material.SmoothPlastic
                or p.Material == Enum.Material.Plastic
                or p.Material == Enum.Material.Neon then
                    pcall(function()
                        if not _ces.origColors[p] then
                            _ces.origColors[p]   = p.Color
                            _ces.origSmooth[p]   = p.Material
                            _ces.origSpecular[p] = p.Reflectance
                        end
                        -- Mejorar color saturandolo levemente
                        p.Color       = _enhanceColor(p.Color)
                        -- Reducir reflejos plasticos que hacen que el carton se vea "barato"
                        p.Reflectance = math.max(p.Reflectance - 0.02, 0)
                        -- Asegurar material SmoothPlastic para sombras limpias
                        p.Material    = Enum.Material.SmoothPlastic
                    end)
                    n = n + 1
                end
            end
        end
        return n
    end

    local function _restoreCartoonEnh()
        local L = game:GetService("Lighting")
        -- Restaurar lighting
        pcall(function()
            if _ces.origBright then L.Brightness = _ces.origBright end
            if _ces.origClock  then L.ClockTime  = _ces.origClock  end
            if _ces.origFog    then L.FogEnd      = _ces.origFog    end
        end)
        _ces.origBright = nil; _ces.origClock = nil; _ces.origFog = nil
        -- Remover bloom y colorCorrection creados por nosotros
        if _ces.bloomInst and _ces.bloomInst.Parent then
            if _ces.origBloom then
                -- Era existente: restaurar valores
                pcall(function()
                    _ces.bloomInst.Intensity  = _ces.origBloom[1]
                    _ces.bloomInst.Size       = _ces.origBloom[2]
                    _ces.bloomInst.Threshold  = _ces.origBloom[3]
                    _ces.bloomInst.Enabled    = _ces.origBloom[4]
                end)
                _ces.origBloom = nil
            else
                -- Lo creamos nosotros: destruirlo
                pcall(function() _ces.bloomInst:Destroy() end)
            end
            _ces.bloomInst = nil
        end
        if _ces.corrInst and _ces.corrInst.Parent then
            pcall(function() _ces.corrInst:Destroy() end)
            _ces.corrInst = nil
        end
        -- Restaurar colores originales de partes
        for p, origColor in pairs(_ces.origColors) do
            if p and p.Parent then
                pcall(function()
                    p.Color       = origColor
                    p.Material    = _ces.origSmooth[p]   or Enum.Material.SmoothPlastic
                    p.Reflectance = _ces.origSpecular[p] or 0
                end)
            end
        end
        _ces.origColors = {}; _ces.origSmooth = {}; _ces.origSpecular = {}
    end

    CreateAuroraToggle(sec, "Cartoon Visual Enhance", function(on)
        _ces.enabled = on
        if _ces.conn then pcall(function() _ces.conn:Disconnect() end); _ces.conn = nil end
        if on then
            local n = _applyCartoonEnh()
            -- Re-aplicar en partes nuevas que aparezcan (nueva ronda)
            _ces.conn = workspace.DescendantAdded:Connect(function(obj)
                if not _ces.enabled then return end
                task.defer(function()
                    if (obj:IsA("BasePart") or obj:IsA("MeshPart")) and not _cartoonEnhSkip(obj) then
                        if obj.Material == Enum.Material.SmoothPlastic
                        or obj.Material == Enum.Material.Plastic
                        or obj.Material == Enum.Material.Neon then
                            pcall(function()
                                if not _ces.origColors[obj] then
                                    _ces.origColors[obj]   = obj.Color
                                    _ces.origSmooth[obj]   = obj.Material
                                    _ces.origSpecular[obj] = obj.Reflectance
                                end
                                obj.Color       = _enhanceColor(obj.Color)
                                obj.Reflectance = math.max(obj.Reflectance - 0.02, 0)
                                obj.Material    = Enum.Material.SmoothPlastic
                            end)
                        end
                    end
                end)
            end)
            CreateCustomNotification("CARTOON ENH", "ON ? " .. n .. " partes mejoradas visualmente", 3)
        else
            _restoreCartoonEnh()
            CreateCustomNotification("CARTOON ENH", "OFF ? apariencia original restaurada", 2)
        end
    end, _ces.enabled)

    -- ================================================================
    -- ANIMACIONES MEJORADAS: velocidad y fluidez de animaciones propias
    -- Ajusta el PlaybackSpeed del Animator del personaje local para que
    -- las animaciones se vean mas fluidas (sin tocar animaciones de NPCs).
    -- ================================================================
    _G._animEnhState = _G._animEnhState or { enabled = false, conn = nil, speed = 1.15 }
    local _aes = _G._animEnhState

    local function _applyAnimEnh(speed)
        local myChar = LocalPlayer and LocalPlayer.Character
        if not myChar then return end
        local hum = myChar:FindFirstChildOfClass("Humanoid")
        local animr = hum and hum:FindFirstChildOfClass("Animator")
        if animr then
            for _, track in ipairs(animr:GetPlayingAnimationTracks()) do
                -- Solo acelerar animaciones de movimiento/idle (no de muerte ni especiales)
                local name = track.Name and track.Name:lower() or ""
                if not name:find("death") and not name:find("emote") and not name:find("throw") then
                    pcall(function() track:AdjustSpeed(speed) end)
                end
            end
        end
    end

    local function _restoreAnimEnh()
        local myChar = LocalPlayer and LocalPlayer.Character
        if not myChar then return end
        local hum = myChar:FindFirstChildOfClass("Humanoid")
        local animr = hum and hum:FindFirstChildOfClass("Animator")
        if animr then
            for _, track in ipairs(animr:GetPlayingAnimationTracks()) do
                pcall(function() track:AdjustSpeed(1) end)
            end
        end
    end

    CreateAuroraToggle(sec, "Smooth Animations (+15%)", function(on)
        _aes.enabled = on
        if _aes.conn then pcall(function() _aes.conn:Disconnect() end); _aes.conn = nil end
        if on then
            _applyAnimEnh(1.15)
            -- Re-aplicar cuando el personaje reaparezca
            _aes.conn = LocalPlayer.CharacterAdded:Connect(function()
                task.wait(1)
                if _aes.enabled then _applyAnimEnh(1.15) end
            end)
            CreateCustomNotification("ANIM ENH", "Animaciones mas fluidas ON (+15% velocidad)", 2)
        else
            _restoreAnimEnh()
            CreateCustomNotification("ANIM ENH", "Animaciones restauradas a velocidad normal", 2)
        end
    end, _aes.enabled)
end



function CreateWorldUI_GotoPlayers()
    local _gotoSec = CreateSection(leftColumn, "", "GOTO PLAYERS", ThemeColors.Aurora3)

    _makeTPButton("Goto Murder", function()
        if not TeleportToMurderer() then
            CreateCustomNotification("GOTO", "No hay Murderer activo", 2)
        end
    end, _gotoSec)
    _makeTPButton("Goto Sheriff", function()
        if not TeleportToSheriff() then
            CreateCustomNotification("GOTO", "No hay Sheriff activo", 2)
        end
    end, _gotoSec)

    -- BOTON: TP Murder (one-shot)
    _makeTPButton("TP Murder", function()
        if not TeleportToMurderer() then
            CreateCustomNotification("TP MURDER", "No hay Murderer activo", 2)
        end
    end, leftColumn)

    -- BOTON: TP Sheriff (one-shot)
    _makeTPButton("TP Sheriff", function()
        if not TeleportToSheriff() then
            CreateCustomNotification("TP SHERIFF", "No hay Sheriff activo", 2)
        end
    end, leftColumn)

    -- BOTON: TP Random Player
    _makeTPButton("TP Random Player", function()
        TeleportToRandomPlayer()
    end, leftColumn)

    -- SELECTOR DE JUGADORES (usa CreateNebulaSelector del hub) + BOTON TP
    do
        local _selSec = CreateSection(leftColumn, "", "TP A JUGADOR", ThemeColors.Aurora3)

        local _playerNames  = {}
        local _playerMap    = {}  -- nombre -> Player
        local _selectorObj  = nil

        local function _rebuildOptions()
            _playerNames = {}
            _playerMap   = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then
                    table.insert(_playerNames, p.Name)
                    _playerMap[p.Name] = p
                end
            end
            if #_playerNames == 0 then
                _playerNames = {"(sin jugadores)"}
            end
            return _playerNames
        end

        _rebuildOptions()

        -- Selector nativo del hub
        _selectorObj = CreateNebulaSelector(
            _selSec,
            "Jugador",
            _playerNames,
            _playerNames[1],
            function(nombre)
                _G.GotoSelectedPlayer = _playerMap[nombre] or nil
            end
        )
        -- Inicializar seleccion
        _G.GotoSelectedPlayer = _playerMap[_playerNames[1]] or nil

        -- Boton refrescar lista (usar _makeTPButton del hub para estilo consistente)
        _makeTPButton("?  Actualizar jugadores", function()
            local nuevos = _rebuildOptions()
            local primero = nuevos[1]
            if _selectorObj then
                _selectorObj.SetOptions(nuevos, primero)
            end
            _G.GotoSelectedPlayer = _playerMap[primero] or nil
            CreateCustomNotification("SELECTOR", "Lista actualizada", 1)
        end, _selSec)

        -- Boton TP al jugador seleccionado (usar _makeTPButton del hub)
        _makeTPButton("TP ? Jugador Seleccionado", function()
            TeleportToSelectedPlayer()
        end, _selSec)
    end
end

function CreateWorldUI_SendToChat()
 CreateSection(leftColumn, "", "SEND TO CHAT", Color3.fromRGB(255, 180, 0))

    local function _getSheriff()
        return findSheriffPlayer()
    end

    local function _sayInChat(msg)
        if not msg or msg == "" then return end
        local sent = false

        -- Metodo 1: TextChatService (nuevo sistema MM2)
        if not sent then
            sent = pcall(function()
                local tcs = game:GetService("TextChatService")
                local gen = tcs:FindFirstChild("RBXGeneral", true)
                if not gen then
                    for _, ch in pairs(tcs:GetDescendants()) do
                        if ch:IsA("TextChannel") then
                            local nm = ch.Name:lower()
                            if nm:find("general") or nm:find("all") then
                                gen = ch; break
                            end
                        end
                    end
                end
                if not gen then gen = tcs:FindFirstChildOfClass("TextChannel") end
                if not gen then error("no channel") end
                -- SayMessage es el metodo correcto en cliente (SendAsync es solo server-side)
                gen:SayMessage(msg)
            end)
        end

        -- Metodo 2: BubbleChat / LegacyChat via SayMessageRequest
        if not sent then
            sent = pcall(function()
                local rs = ReplicatedStorage
                local ev = rs:FindFirstChild("DefaultChatSystemChatEvents", true)
                    or rs:FindFirstChild("ChatSystemEvents", true)
                if not ev then error("no events") end
                local sr = ev:FindFirstChild("SayMessageRequest") or ev:FindFirstChild("SendMessage")
                if not sr then error("no remote") end
                sr:FireServer(msg, "All")
            end)
        end

        -- Metodo 3: Chat via StarterGui
        if not sent then
            sent = pcall(function()
                StarterGui:SetCore("ChatMakeSystemMessage", {
                    Text = msg,
                    Color = Color3.new(1,1,1),
                    Font = Enum.Font.Montserrat,
                    TextSize = 18
                })
            end)
        end

        -- Metodo 4: LocalPlayer:Chat (legacy, algunas versiones)
        if not sent then
            pcall(function() LocalPlayer:Chat(msg) end)
        end

        -- Metodo 5: buscar remotes de chat del juego directamente
        if not sent then
            pcall(function()
                for _, v in ipairs(ReplicatedStorage:GetDescendants()) do
                    if v:IsA("RemoteEvent") then
                        local n = v.Name:lower()
                        if n:find("chat") or n:find("say") or n:find("message") then
                            v:FireServer(msg)
                            sent = true
                            break
                        end
                    end
                end
            end)
        end
    end

    chatMsgs = {
        { label="El murder es... (auto)",  fn=function()
            m=findMurderer()
            if m then _sayInChat("El murder es " .. m.Name .. "!!")
 else CreateCustomNotification("CHAT","No se detecto el murder",2) end
        end},
        { label="El sheriff es... (auto)", fn=function()
            s=_getSheriff()
            if s then _sayInChat("El sheriff es " .. s.Name)
 else CreateCustomNotification("CHAT","No se detecto el sheriff",2) end
        end},
        { label="XD", fn=function() _sayInChat("XD") end },
        { label="gg", fn=function() _sayInChat("gg") end },
        { label="nice", fn=function() _sayInChat("nice") end },
    }

    for _, btn in ipairs(chatMsgs) do
 CreateButton(leftColumn, btn.label, ThemeColors.Primary, function()
            btn.fn()
        end)
    end

    _customSlots = {"", "", ""}

 CreateSection(leftColumn, "", "MENSAJES PERSONALIZADOS", Color3.fromRGB(255, 200, 80))

    for slotI = 1, 3 do
        local rowFrame = Instance.new("Frame", leftColumn)
        rowFrame.Size = UDim2.new(1, -8, 0, 36)
        rowFrame.BackgroundTransparency = 1
        rowFrame.BorderSizePixel = 0

        local inp = Instance.new("TextBox", rowFrame)
        inp.Size = UDim2.new(1, -70, 1, 0)
        inp.Position = UDim2.new(0, 0, 0, 0)
        inp.BackgroundColor3 = ThemeColors.Background
        inp.BackgroundTransparency = 0.7
        inp.BorderSizePixel = 0
        inp.PlaceholderText = "Mensaje personalizado " .. slotI
 inp.Text = ""
        inp.TextSize = 12
        inp.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        inp.TextColor3 = Color3.fromRGB(255, 213, 83)
        inp.PlaceholderColor3 = Color3.fromRGB(134, 134, 134)
        inp.ClearTextOnFocus = false
        inp.ZIndex = 15
        Instance.new("UICorner", inp).CornerRadius = UDim.new(0, 8)
        local inpS = Instance.new("UIStroke", inp)
        inpS.Color = ThemeColors.Primary; inpS.Thickness = 2.5; inpS.Transparency = 0.4
        local inpP = Instance.new("UIPadding", inp)
        inpP.PaddingLeft = UDim.new(0, 8); inpP.PaddingRight = UDim.new(0, 8)
        local captSlot = slotI
        inp:GetPropertyChangedSignal("Text"):Connect(function() _customSlots[captSlot] = inp.Text end)

        local sendBtn = Instance.new("TextButton", rowFrame)
        sendBtn.Size = UDim2.new(0, 62, 1, 0)
        sendBtn.Position = UDim2.new(1, -62, 0, 0)
        sendBtn.BackgroundColor3 = ThemeColors.Background
        sendBtn.BackgroundTransparency = 0
        sendBtn.BorderSizePixel = 0
        sendBtn.AutoButtonColor = false
        sendBtn.Text = "Enviar"
        sendBtn.TextSize = 11
        sendBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        sendBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        sendBtn.ZIndex = 15
        Instance.new("UICorner", sendBtn).CornerRadius = UDim.new(0, 8)
        local _sendBtnStroke = Instance.new("UIStroke", sendBtn)
        _sendBtnStroke.Color = ThemeColors.Primary; _sendBtnStroke.Thickness = 1.5; _sendBtnStroke.Transparency = 0.3; _sendBtnStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        sendBtn.MouseEnter:Connect(function()
            TweenService:Create(sendBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Secondary}):Play()
            TweenService:Create(_sendBtnStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0, Thickness = 2}):Play()
        end)
        sendBtn.MouseLeave:Connect(function()
            TweenService:Create(sendBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
            TweenService:Create(_sendBtnStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0.3, Thickness = 1.5}):Play()
        end)
