            task.wait(0.12)
            TweenService:Create(sendBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
        end)
        local captSlot2 = slotI
        sendBtn.Activated:Connect(function()
            local txt = _customSlots[captSlot2]
            if txt and txt ~= "" then
                _sayInChat(txt)
 CreateCustomNotification("CHAT", "Enviado: " .. txt, 2)
            end
        end)
    end

    _autoSendEnabled = false
    _autoSendThread  = nil
    _autoSendInterval = 15
    _slotIdx = 1
    slotNames = {"Slot 1", "Slot 2", "Slot 3", "Murder (auto)", "Sheriff (auto)"}

 CreateSection(leftColumn, "", "AUTO SEND", Color3.fromRGB(220, 123, 26))

    slotRow = Instance.new("Frame", leftColumn)
    slotRow.Size = UDim2.new(1, -8, 0, 32)
    slotRow.BackgroundTransparency = 1; slotRow.BorderSizePixel = 0

    prevBtn = Instance.new("TextButton", slotRow)
    prevBtn.Size = UDim2.new(0, 28, 1, 0); prevBtn.Position = UDim2.new(0, 0, 0, 0)
    prevBtn.BackgroundColor3 = ThemeColors.Background; prevBtn.BackgroundTransparency = 0.05
    prevBtn.AutoButtonColor = false
    prevBtn.BorderSizePixel = 0; prevBtn.Text = "<"; prevBtn.TextSize = 14
    prevBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat); prevBtn.TextColor3 = Color3.fromRGB(255,255,255); prevBtn.ZIndex = 15
    Instance.new("UICorner", prevBtn).CornerRadius = UDim.new(0, 6)
    local _prevBtnStroke = Instance.new("UIStroke", prevBtn)
    _prevBtnStroke.Color = ThemeColors.Primary; _prevBtnStroke.Thickness = 1.5; _prevBtnStroke.Transparency = 0.3; _prevBtnStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    prevBtn.MouseEnter:Connect(function()
        TweenService:Create(prevBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Secondary}):Play()
        TweenService:Create(_prevBtnStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0, Thickness = 2}):Play()
