        TweenService:Create(_prevBtnStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0.3, Thickness = 1.5}):Play()
    end)
    prevBtn.Activated:Connect(function()
        TweenService:Create(prevBtn, TweenInfo.new(0.08), {BackgroundColor3 = ThemeColors.Accent}):Play()
        task.wait(0.12)
        TweenService:Create(prevBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
    end)

    slotLabel = Instance.new("TextLabel", slotRow)
    slotLabel.Size = UDim2.new(1, -64, 1, 0); slotLabel.Position = UDim2.new(0, 32, 0, 0)
 slotLabel.BackgroundTransparency = 1; slotLabel.Text = slotNames[1]
    slotLabel.TextSize = 12; slotLabel.FontFace = Font.fromEnum(Enum.Font.Montserrat)
    slotLabel.TextColor3 = Color3.fromRGB(169, 169, 169); slotLabel.ZIndex = 15

    nextBtnS = Instance.new("TextButton", slotRow)
    nextBtnS.Size = UDim2.new(0, 28, 1, 0); nextBtnS.Position = UDim2.new(1, -28, 0, 0)
    nextBtnS.BackgroundColor3 = ThemeColors.Background; nextBtnS.BackgroundTransparency = 0.05
    nextBtnS.AutoButtonColor = false
    nextBtnS.BorderSizePixel = 0; nextBtnS.Text = ">"; nextBtnS.TextSize = 14
    nextBtnS.FontFace = Font.fromEnum(Enum.Font.Montserrat); nextBtnS.TextColor3 = Color3.fromRGB(255,255,255); nextBtnS.ZIndex = 15
    Instance.new("UICorner", nextBtnS).CornerRadius = UDim.new(0, 6)
    local _nextBtnSStroke = Instance.new("UIStroke", nextBtnS)
    _nextBtnSStroke.Color = ThemeColors.Primary; _nextBtnSStroke.Thickness = 1.5; _nextBtnSStroke.Transparency = 0.3; _nextBtnSStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    nextBtnS.MouseEnter:Connect(function()
