 slotLabel.Text = slotNames[_slotIdx]
    end)
    nextBtnS.Activated:Connect(function()
        _slotIdx = _slotIdx % #slotNames + 1
 slotLabel.Text = slotNames[_slotIdx]
    end)

    local function _getAutoMsg()
        if _slotIdx == 4 then
            local m = findMurderer()
            return m and ("El murder es " .. m.Name .. "!!") or nil
        elseif _slotIdx == 5 then
            local s = findSheriffPlayer()
            return s and ("El sheriff es " .. s.Name) or nil
        else
            local txt = _customSlots[_slotIdx]
            return (txt and txt ~= "") and txt or nil
        end
    end

 CreateAuroraToggle(leftColumn, "Auto Send (repite mensaje)", function(on)
        _autoSendEnabled = on
        if _autoSendThread then task.cancel(_autoSendThread); _autoSendThread = nil end
        if on then
            _autoSendThread = task.spawn(function()
                while _autoSendEnabled do
                    local msg = _getAutoMsg()
                    if msg then
                        _sayInChat(msg)
 CreateCustomNotification("AUTO SEND", msg, 2)
