    end, false)

 CreateSlider(leftColumn, "Intervalo auto send (seg)", 3, 60, 15, function(v) _autoSendInterval = v end)

 CreateButton(leftColumn, " Enviar ahora", ThemeColors.Primary, function()
        msg = _getAutoMsg()
        if msg then
 _sayInChat(msg); CreateCustomNotification("CHAT", "Enviado: " .. msg, 2)
        else
 CreateCustomNotification("CHAT", "Slot vacio o sin murder/sheriff detectado", 2)
        end
    end)

    _G._autoAnnState = _G._autoAnnState or { enabled = false, conn = nil, interval = 15 }
    _autoAnnEnabled = _G._autoAnnState.enabled
    _autoAnnConn    = _G._autoAnnState.conn
    _autoAnnInterval = _G._autoAnnState.interval or 15
 CreateAuroraToggle(leftColumn, "Auto Announce Murder", function(on)
        _G._autoAnnState.enabled = on
        _autoAnnEnabled = on
        if _autoAnnConn then _autoAnnConn:Disconnect(); _autoAnnConn=nil end
        if on then
            _autoAnnConn = task.spawn(function()
                while _autoAnnEnabled do
                    local m=findMurderer()
                    if m then _sayInChat("MURDER: " .. m.Name .. " !!!") end
                    task.wait(_autoAnnInterval)
                end
            end)
 CreateCustomNotification("CHAT","Auto announce ON - cada "..tostring(_autoAnnInterval).."s",3)
        else
 CreateCustomNotification("CHAT","Auto announce OFF",2)
        end
    end, false)
 CreateSlider(leftColumn, "Intervalo announce (seg)", 5, 60, 15, function(v) _autoAnnInterval = v end)
end

function CreateWorldUI_FakeLag()
 local _flSec = CreateSection(rightColumn, "", "FAKE LAG", Color3.fromRGB(135, 135, 135))

    -- FIX LAG: usar _G para que CreateWorldTab pueda limpiar este loop entre visitas al tab
    if not _G._worldFl then
        _G._worldFl = {
            enabled    = false,
            conn       = nil,
            animConn   = nil,
            intensity  = 8,
            mode       = "Freeze",
            animDuring = true,
            _savedAnimTracks = {},
            _walkAnimTrack   = nil,
            _currentAnim     = "idle",
        }
    end
    local _fl = _G._worldFl

    -- Helper: capturar el AnimTrack que se esta reproduciendo y su velocidad/tiempo
    local function _captureCurrentAnim()
        local char = LocalPlayer.Character
        if not char then return nil end
        local hum  = char:FindFirstChildOfClass("Humanoid")
        local anim = hum and hum:FindFirstChildOfClass("Animator")
        if not anim then return nil end
        local tracks = anim:GetPlayingAnimationTracks()
        -- Priorizar animaciones de movimiento (walk/run/jump/swim) sobre idle
        local best = nil
        local bestPrio = -1
        for _, t in ipairs(tracks) do
            local n = t.Animation and t.Animation.AnimationId or ""
            local prio = 0
            if n:find("walk") or n:find("Walk") or n:find("run") or n:find("Run") then prio = 3
            elseif n:find("jump") or n:find("Jump") or n:find("fall") or n:find("Fall") then prio = 2
            elseif n:find("swim") or n:find("Swim") then prio = 4
            elseif t.IsPlaying then prio = 1 end
            if prio > bestPrio then bestPrio = prio; best = t end
        end
        return best
    end

    -- Helper: continuar reproduciendo la ultima animacion capturada incluso durante freeze
    local function _keepAnimAlive(animTrack)
        if not animTrack or not animTrack.IsPlaying then return end
        -- La animacion ya corre; solo aseguramos que no se detenga
        -- Si se detuvo (PlatformStand la frena), la relanzamos
        if not animTrack.IsPlaying then
            pcall(function() animTrack:Play(0) end)
        end
    end

 CreateNebulaSelector(_flSec, "Modo de Lag", {"Freeze","Stutter","Spike","Ghost"}, "Freeze", function(v)
        _fl.mode = v
    end)

 CreateSlider(_flSec, "Intensidad (frames)", 2, 30, 8, function(v)
        _fl.intensity = v
    end)

    -- Toggle: mantener animacion activa durante freeze

 -- -- Slider adicional 1: Stutter Pause (ms entre micro-congeladas) ----------
    if not _fl.stutterMs then _fl.stutterMs = 60 end
 CreateSlider(_flSec, "Stutter Pause (ms)", 10, 300, _fl.stutterMs, function(v)
        _fl.stutterMs = v
    end)

    -- -- Slider adicional 2: Spike Power (factor de velocidad en modo Spike) -----
    if not _fl.spikePower then _fl.spikePower = 1.5 end
 CreateSlider(_flSec, "Spike Power (factor)", 1, 10, _fl.spikePower, function(v)
        _fl.spikePower = v
    end)

    infoLbl = Instance.new("TextLabel", _flSec)
    infoLbl.Size=UDim2.new(1,0,0,52); infoLbl.BackgroundColor3=ThemeColors.Background
    infoLbl.BackgroundTransparency = 0.85; infoLbl.BorderSizePixel=0
    infoLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat); infoLbl.TextSize=9
    infoLbl.TextColor3=ThemeColors.TextSecondary; infoLbl.TextWrapped=true
    infoLbl.Text="FREEZE: congela N frames, mantiene animacion de caminata/salto/nado activa\nSTUTTER: jitter de posicion\nSPIKE: freeze largo periodico con animacion continua\nGHOST: freeze visual local sin afectar servidor"
    infoLbl.TextXAlignment=Enum.TextXAlignment.Left
    Instance.new("UICorner",infoLbl).CornerRadius=UDim.new(0,6)
    ip=Instance.new("UIPadding",infoLbl)
    ip.PaddingLeft=UDim.new(0,8); ip.PaddingRight=UDim.new(0,8)
    ip.PaddingTop=UDim.new(0,5); ip.PaddingBottom=UDim.new(0,5)
    Instance.new("UIStroke",infoLbl).Color=ThemeColors.Aurora4
end


function CreateWorldUI_StretchScreen()
    local _stretchSec = CreateSection(leftColumn, "", "[PC] STRETCH SCREEN", ThemeColors.Aurora4)

    _G._worldStretch = _G._worldStretch or {
        enabled = false, scaleX = 1.0, scaleY = 1.0, offsetX = 0, conn = nil,
    }
    local _stretch = _G._worldStretch
    local _stretchGui = nil

    local function _applyStretch()
        if not _stretchGui or not _stretchGui.Parent then
            _stretchGui = Instance.new("ScreenGui")
            _stretchGui.Name = "BYPAS_StretchScreen"
            _stretchGui.ResetOnSpawn = false
            _stretchGui.IgnoreGuiInset = true
            _stretchGui.DisplayOrder = 1
            pcall(function() _stretchGui.Parent = CoreGui end)
            if not _stretchGui.Parent then _stretchGui.Parent = LocalPlayer.PlayerGui end
        end
        for _, c in ipairs(_stretchGui:GetChildren()) do c:Destroy() end
        local sX = math.clamp(_stretch.scaleX, 0.3, 3.0)
        local sY = math.clamp(_stretch.scaleY, 0.3, 3.0)
        pcall(function()
            _Camera.FieldOfView = math.clamp(70 / sX, 10, 120)
        end)
        local cover = Instance.new("Frame", _stretchGui)
        cover.BackgroundTransparency = 1
        cover.BorderSizePixel = 0
        cover.AnchorPoint = Vector2.new(0.5, 0.5)
        cover.Size = UDim2.new(sX, _stretch.offsetX * 2, sY, 0)
        cover.Position = UDim2.new(0.5, _stretch.offsetX, 0.5, 0)
    end

    local function _removeStretch()
        pcall(function() _Camera.FieldOfView = 70 end)
        if _stretchGui then pcall(function() _stretchGui:Destroy() end); _stretchGui = nil end
    end

    CreateToggle(leftColumn, "Enable Stretch", function(en)
        _stretch.enabled = en
        if _stretch.conn then _stretch.conn:Disconnect(); _stretch.conn = nil end
        if en then
            _applyStretch()
            local _stretchTick = 0
            _stretch.conn = RunService.RenderStepped:Connect(function()
                if not _stretch.enabled then return end
                _stretchTick = _stretchTick + 1; if _stretchTick < 4 then return end; _stretchTick = 0  -- OPT: throttle ~15Hz, FOV no necesita 60fps
                pcall(function()
                    local t = math.clamp(70 / math.clamp(_stretch.scaleX, 0.3, 3.0), 10, 120)
                    if math.abs(_Camera.FieldOfView - t) > 0.5 then _Camera.FieldOfView = t end
                end)
            end)
            -- [notif removed]
        else
            _removeStretch()
            -- [notif removed]
        end
    end, false)

    CreateSlider(leftColumn, "Ancho (FOV stretch)", 30, 200, 100, function(v)
        _stretch.scaleX = v / 100
        if _stretch.enabled then _applyStretch() end
    end)
    CreateSlider(leftColumn, "Alto (zoom vertical)", 50, 200, 100, function(v)
        _stretch.scaleY = v / 100
        if _stretch.enabled then _applyStretch() end
    end)
    CreateSlider(leftColumn, "Offset Horizontal (px)", -300, 300, 0, function(v)
        _stretch.offsetX = v
        if _stretch.enabled then _applyStretch() end
    end)
    _makeTPButton("Reset pantalla normal", function()
        _stretch.scaleX = 1.0; _stretch.scaleY = 1.0; _stretch.offsetX = 0
        _removeStretch()
        CreateCustomNotification("STRETCH", "Reset a normal", 1.5)
    end, _stretchSec)
end


-- ===================================================================
-- WORLD: GAME UTILITIES con sistema de SLOTS (3 slots de auto-remove)
-- ===================================================================
-- ===================================================================
function CreateWorldUI_GameUtilities()
 CreateSection(leftColumn, "", "GAME UTILITIES", ThemeColors.Aurora1)

    -- ==========================================================
    -- SLOTS DE AUTO-REMOVE (Slot 1 / 2 / 3) con flechas < >
    -- ==========================================================
    local _slotCount = 3
    local _currentSlot = 1

    -- Estado por slot: { coins=bool, corpses=bool, sound=bool, bank=bool }
    local _slotStates = {}
    for i = 1, _slotCount do
        _slotStates[i] = { coins=false, corpses=false, sound=false, bank=false }
    end

    -- Conexiones activas por tipo (compartidas, solo 1 por tipo a la vez)
    local _arcConn, _corpseConn, _muteConn = nil, nil, nil
    local _bankDone = false

    local function _isCoinPart(obj)
        if not obj then return false end
        -- Detectar Part directa
        if obj:IsA("BasePart") then
            local n  = obj.Name:lower()
            local pn = obj.Parent and obj.Parent.Name:lower() or ""
            local gpn = obj.Parent and obj.Parent.Parent and obj.Parent.Parent.Name:lower() or ""
            if n == "coin" or n == "goldcoin" or n:find("coin") then return true end
            if pn == "coin" or pn == "coins" or pn:find("coin") then return true end
            if gpn == "coincontainer" or gpn:find("coin") then return true end
        end
        -- Detectar Model/Part dentro de CoinContainer
        if obj:IsA("Model") or obj:IsA("Part") then
            local par = obj.Parent
            while par do
                if par.Name == "CoinContainer" or par.Name:lower():find("coin") then return true end
                par = par.Parent
                if par == workspace then break end
            end
        end
        return false
    end

    -- Ocultar todas las monedas del CoinContainer (mismo metodo que Farm)
    local function _hideAllCoins()
        -- Una sola pasada: si encontramos CoinContainer, ocultamos sus hijos directamente
        local _visited = {}
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj.Name == "CoinContainer" and not _visited[obj] then
                _visited[obj] = true
                for _, v in ipairs(obj:GetDescendants()) do
                    if v:IsA("BasePart") then
                        pcall(function() v.LocalTransparencyModifier = 1 end)
                    end
                end
            elseif _isCoinPart(obj) and not _visited[obj] then
                _visited[obj] = true
                pcall(function() obj.LocalTransparencyModifier = 1 end)
            end
        end
    end

    local function _applySlot(slot)
        local st = _slotStates[slot]

        -- Auto Remove Coins
        if _arcConn then _arcConn:Disconnect(); _arcConn = nil end
        if st.coins then
            _hideAllCoins()
            _arcConn = workspace.DescendantAdded:Connect(function(obj)
                if _isCoinPart(obj) then pcall(function() obj.LocalTransparencyModifier = 1 end) end
            end)
        else
            -- Restaurar monedas ocultas al desactivar
            local _visited2 = {}
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj.Name == "CoinContainer" and not _visited2[obj] then
                    _visited2[obj] = true
                    for _, v in ipairs(obj:GetDescendants()) do
                        if v:IsA("BasePart") then
                            pcall(function() v.LocalTransparencyModifier = 0 end)
                        end
                    end
                elseif _isCoinPart(obj) and not _visited2[obj] then
                    _visited2[obj] = true
                    pcall(function() obj.LocalTransparencyModifier = 0 end)
                end
            end
        end

        -- Auto Remove Corpses
        if _corpseConn then _corpseConn:Disconnect(); _corpseConn = nil end
        if st.corpses then
            local _CORP = {raggy=true, deadbody=true, corpse=true, ragdoll=true}
            local function _kill(obj)
                if not obj or not obj.Parent then return end
                local n = obj.Name:lower()
                if _CORP[n] or n:find("dead") or n:find("rag") then pcall(function() obj:Destroy() end) end
            end
            for _, obj in ipairs(workspace:GetChildren()) do _kill(obj) end
            _corpseConn = workspace.ChildAdded:Connect(function(obj) task.defer(function() _kill(obj) end) end)
        end

        -- Mute Coin Sound
        if _muteConn then _muteConn:Disconnect(); _muteConn = nil end
        local function _muteS(obj)
            if not obj:IsA("Sound") then return end
            local n = obj.Name:lower()
            if n:find("coin") or n:find("pickup") or n:find("collect") or n:find("ding") then
                pcall(function()
                    if st.sound then
                        if not obj:GetAttribute("_pv") then obj:SetAttribute("_pv", obj.Volume) end
                        obj.Volume = 0
                    else
                        local pv = obj:GetAttribute("_pv"); obj.Volume = pv or 0.5
                    end
                end)
            end
        end
        for _, ch in ipairs(workspace:GetChildren()) do
            pcall(function() for _, s in ipairs(ch:GetDescendants()) do pcall(_muteS, s) end end)
        end
        if st.sound then
            _muteConn = workspace.DescendantAdded:Connect(function(obj) pcall(_muteS, obj) end)
        end
    end

    -- -- Selector de Slot con flechas ------------------------------
    local slotRow = Instance.new("Frame", leftColumn)
    slotRow.Size = UDim2.new(1, -8, 0, 34)
    slotRow.BackgroundColor3 = ThemeColors.Background
    slotRow.BackgroundTransparency = 0.85
    slotRow.BorderSizePixel = 0
    Instance.new("UICorner", slotRow).CornerRadius = UDim.new(0, 8)
    local slotStroke = Instance.new("UIStroke", slotRow)
    slotStroke.Color = ThemeColors.Primary; slotStroke.Thickness = 1.5; slotStroke.Transparency = 0.3

    local prevSlotBtn = Instance.new("TextButton", slotRow)
    prevSlotBtn.Size = UDim2.new(0, 28, 1, 0); prevSlotBtn.Position = UDim2.new(0, 0, 0, 0)
    prevSlotBtn.BackgroundColor3 = ThemeColors.Background; prevSlotBtn.BackgroundTransparency = 0.05; prevSlotBtn.BorderSizePixel = 0
    prevSlotBtn.AutoButtonColor = false
    Instance.new("UICorner", prevSlotBtn).CornerRadius = UDim.new(0, 6)
    local _prevSlotStroke = Instance.new("UIStroke", prevSlotBtn)
    _prevSlotStroke.Color = ThemeColors.Primary; _prevSlotStroke.Thickness = 1.5; _prevSlotStroke.Transparency = 0.3; _prevSlotStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    prevSlotBtn.Text = "<"; prevSlotBtn.TextSize = 16; prevSlotBtn.FontFace = Font.fromEnum(Enum.Font.Arimo)
    prevSlotBtn.TextColor3 = Color3.fromRGB(255, 255, 255); prevSlotBtn.ZIndex = 15
    prevSlotBtn.MouseEnter:Connect(function()
        TweenService:Create(prevSlotBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Secondary}):Play()
        TweenService:Create(_prevSlotStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0, Thickness = 2}):Play()
    end)
    prevSlotBtn.MouseLeave:Connect(function()
        TweenService:Create(prevSlotBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
        TweenService:Create(_prevSlotStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0.3, Thickness = 1.5}):Play()
    end)
    prevSlotBtn.Activated:Connect(function()
        TweenService:Create(prevSlotBtn, TweenInfo.new(0.08), {BackgroundColor3 = ThemeColors.Accent}):Play()
        task.wait(0.12)
        TweenService:Create(prevSlotBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
    end)

    local slotLbl = Instance.new("TextLabel", slotRow)
    slotLbl.Size = UDim2.new(1, -64, 1, 0); slotLbl.Position = UDim2.new(0, 32, 0, 0)
 slotLbl.BackgroundTransparency = 1; slotLbl.Text = "Slot 1"
    slotLbl.TextSize = 13; slotLbl.FontFace = Font.fromEnum(Enum.Font.Arimo)
    slotLbl.TextColor3 = Color3.fromRGB(220, 220, 225); slotLbl.ZIndex = 15

    local nextSlotBtn = Instance.new("TextButton", slotRow)
    nextSlotBtn.Size = UDim2.new(0, 28, 1, 0); nextSlotBtn.Position = UDim2.new(1, -28, 0, 0)
    nextSlotBtn.BackgroundColor3 = ThemeColors.Background; nextSlotBtn.BackgroundTransparency = 0.05; nextSlotBtn.BorderSizePixel = 0
    nextSlotBtn.AutoButtonColor = false
    Instance.new("UICorner", nextSlotBtn).CornerRadius = UDim.new(0, 6)
    local _nextSlotStroke = Instance.new("UIStroke", nextSlotBtn)
    _nextSlotStroke.Color = ThemeColors.Primary; _nextSlotStroke.Thickness = 1.5; _nextSlotStroke.Transparency = 0.3; _nextSlotStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    nextSlotBtn.Text = ">"; nextSlotBtn.TextSize = 16; nextSlotBtn.FontFace = Font.fromEnum(Enum.Font.Arimo)
    nextSlotBtn.TextColor3 = Color3.fromRGB(255, 255, 255); nextSlotBtn.ZIndex = 15
    nextSlotBtn.MouseEnter:Connect(function()
        TweenService:Create(nextSlotBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Secondary}):Play()
        TweenService:Create(_nextSlotStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0, Thickness = 2}):Play()
    end)
    nextSlotBtn.MouseLeave:Connect(function()
        TweenService:Create(nextSlotBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
        TweenService:Create(_nextSlotStroke, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 0.3, Thickness = 1.5}):Play()
    end)
    nextSlotBtn.Activated:Connect(function()
        TweenService:Create(nextSlotBtn, TweenInfo.new(0.08), {BackgroundColor3 = ThemeColors.Accent}):Play()
        task.wait(0.12)
        TweenService:Create(nextSlotBtn, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = ThemeColors.Background}):Play()
    end)

    -- Toggles del slot actual (se actualizan al cambiar slot)
    local _slotToggles = {}  -- { coins=toggle, corpses=toggle, sound=toggle, bank=toggle }

    local function _refreshSlotUI()
        local st = _slotStates[_currentSlot]
 slotLbl.Text = "Slot " .. _currentSlot
        -- Actualizar estado visual de los toggles
        for key, toggle in pairs(_slotToggles) do
            if toggle and toggle.SetState then
                pcall(function() toggle:SetState(st[key] or false) end)
            end
        end
    end

    prevSlotBtn.Activated:Connect(function()

        _currentSlot = (_currentSlot - 2) % _slotCount + 1
        _refreshSlotUI()
    end)
    nextSlotBtn.Activated:Connect(function()

        _currentSlot = _currentSlot % _slotCount + 1
        _refreshSlotUI()
    end)

    -- Toggles (aplican al slot actual)
 CreateAuroraToggle(leftColumn, "Auto Remove Coins", function(en)
        _slotStates[_currentSlot].coins = en
        _applySlot(_currentSlot)
 -- [notif removed]
    end, false)

 CreateAuroraToggle(leftColumn, "Auto Remove Corpses", function(en)
        _slotStates[_currentSlot].corpses = en
        _applySlot(_currentSlot)
 -- [notif removed]
    end, false)

    -- -- Auto Remove Pets -----------------------------------------------
    -- Oculta todos los pets en workspace volviendolos transparentes.
    -- Detecta Body parts del sistema de pets (Pet/Body) y NPC pets.
    -- Usa el mismo sistema de deteccion del script original de pets.
    do
        local _petRemConn   = nil
        local _petRemHbConn = nil
        local _petRemEnabled = false

        local function _hidePetBody(body)
            if not body or not body.Parent then return end
            pcall(function() body.LocalTransparencyModifier = 1 end)
            pcall(function() body.Transparency = 1 end)
            for _, desc in ipairs(body:GetDescendants()) do
                if desc:IsA("BasePart") then
                    pcall(function() desc.LocalTransparencyModifier = 1 end)
                    pcall(function() desc.Transparency = 1 end)
                end
                if desc:IsA("ParticleEmitter") or desc:IsA("Fire") or desc:IsA("Trail") or desc:IsA("Beam") then
                    pcall(function() desc.Enabled = false end)
                end
                if desc:IsA("BillboardGui") then
                    pcall(function() desc.Enabled = false end)
                end
            end
        end

        local function _removeAllPets()
            -- Recorrer todos los personajes en workspace
            for _, char in ipairs(workspace:GetChildren()) do
                local pet = char:FindFirstChild("Pet")
                if pet then
                    local body = pet:FindFirstChild("Body")
                    if body then _hidePetBody(body) end
                end
                -- Tambien buscar pets que sean hijos directos del char con StringValue "Pet"
                for _, child in ipairs(char:GetChildren()) do
                    if child.Name == "Pet" and child:IsA("StringValue") then
                        local body2 = child:FindFirstChild("Body")
                        if body2 then _hidePetBody(body2) end
                    end
                end
            end
            -- Buscar pets globales en workspace (pets sueltos como NPC)
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj.Name == "Body" and obj.Parent and obj.Parent.Name == "Pet" then
                    _hidePetBody(obj)
                end
            end
        end

        local function _restoreAllPets()
            for _, char in ipairs(workspace:GetChildren()) do
                local pet = char:FindFirstChild("Pet")
                if pet then
                    local body = pet:FindFirstChild("Body")
                    if body then
                        pcall(function() body.LocalTransparencyModifier = 0 end)
                        pcall(function() body.Transparency = 0 end)
                        for _, desc in ipairs(body:GetDescendants()) do
                            if desc:IsA("BasePart") then
                                pcall(function() desc.LocalTransparencyModifier = 0 end)
                                pcall(function() desc.Transparency = 0 end)
                            end
                            if desc:IsA("ParticleEmitter") or desc:IsA("Fire") or desc:IsA("Trail") or desc:IsA("Beam") then
                                pcall(function() desc.Enabled = true end)
                            end
                            if desc:IsA("BillboardGui") then
                                pcall(function() desc.Enabled = true end)
                            end
                        end
                    end
                end
                for _, child in ipairs(char:GetChildren()) do
                    if child.Name == "Pet" and child:IsA("StringValue") then
                        local body2 = child:FindFirstChild("Body")
                        if body2 then
                            pcall(function() body2.LocalTransparencyModifier = 0 end)
                            pcall(function() body2.Transparency = 0 end)
                            for _, desc in ipairs(body2:GetDescendants()) do
                                if desc:IsA("BasePart") then
                                    pcall(function() desc.LocalTransparencyModifier = 0 end)
                                    pcall(function() desc.Transparency = 0 end)
                                end
                                if desc:IsA("ParticleEmitter") or desc:IsA("Fire") or desc:IsA("Trail") or desc:IsA("Beam") then
                                    pcall(function() desc.Enabled = true end)
                                end
                                if desc:IsA("BillboardGui") then
                                    pcall(function() desc.Enabled = true end)
                                end
                            end
                        end
                    end
                end
            end
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj.Name == "Body" and obj.Parent and obj.Parent.Name == "Pet" then
                    pcall(function() obj.LocalTransparencyModifier = 0 end)
                    pcall(function() obj.Transparency = 0 end)
                    for _, desc in ipairs(obj:GetDescendants()) do
                        if desc:IsA("BasePart") then
                            pcall(function() desc.LocalTransparencyModifier = 0 end)
                            pcall(function() desc.Transparency = 0 end)
                        end
                        if desc:IsA("ParticleEmitter") or desc:IsA("Fire") or desc:IsA("Trail") or desc:IsA("Beam") then
                            pcall(function() desc.Enabled = true end)
                        end
                        if desc:IsA("BillboardGui") then
                            pcall(function() desc.Enabled = true end)
                        end
                    end
                end
            end
        end

        CreateAuroraToggle(leftColumn, "Auto Remove Pets", function(en)
            _petRemEnabled = en
            if _petRemConn    then pcall(function() _petRemConn:Disconnect()    end); _petRemConn    = nil end
            if _petRemHbConn  then pcall(function() _petRemHbConn:Disconnect()  end); _petRemHbConn  = nil end

            if en then
                -- Ocultar inmediatamente
                _removeAllPets()
                -- Solo DescendantAdded: sin Heartbeat para evitar lag
                _petRemConn = workspace.DescendantAdded:Connect(function(obj)
                    if not _petRemEnabled then return end
                    if obj.Name == "Body" and obj.Parent and obj.Parent.Name == "Pet" then
                        task.defer(function() _hidePetBody(obj) end)
                    end
                    -- Cubrir pets que llegan como Model completo
                    if obj.Name == "Pet" and obj:IsA("Model") then
                        task.defer(function()
                            local body = obj:FindFirstChild("Body")
                            if body then _hidePetBody(body) end
                        end)
                    end
                end)
 CreateCustomNotification("AUTO REMOVE", "Pets ocultos", 2)
            else
                _restoreAllPets()
 CreateCustomNotification("AUTO REMOVE", "Pets visibles de nuevo", 2)
            end
        end, false)
    end

    -- -- Auto Remove Traps ----------------------------------------------
    -- Destruye visualmente las trampas del jugador local y oculta las de otros.
    -- Basado en el TrapScriptClient: TrapVisual es la parte visible de la trampa.
    -- Tambien intercepta TrapHitLocal para evitar que la trampa nos frene.
    do
        local _trapRemEnabled = false
        local _trapRemConn    = nil
        local _trapHbConn     = nil

        local function _hideTrap(trapModel)
            if not trapModel or not trapModel.Parent then return end
            local tv = trapModel:FindFirstChild("TrapVisual")
            if tv then
                pcall(function() tv.Transparency = 1 end)
                pcall(function() tv.LocalTransparencyModifier = 1 end)
                pcall(function() tv.CanCollide = false end)
            end
            -- Ocultar todos los billboards de trampas
            for _, desc in ipairs(trapModel:GetDescendants()) do
                if desc:IsA("BillboardGui") then
                    pcall(function() desc.Enabled = false end)
                end
                if desc:IsA("BasePart") then
                    pcall(function() desc.LocalTransparencyModifier = 1 end)
                    pcall(function() desc.CanCollide = false end)
                end
            end
        end

        local function _removeAllTraps()
            -- Las trampas viven en workspace con un hijo "TrapVisual" y "PlacedPlayer"
            for _, obj in ipairs(workspace:GetChildren()) do
                if obj:FindFirstChild("TrapVisual") and obj:FindFirstChild("PlacedPlayer") then
                    _hideTrap(obj)
                end
            end
            -- Tambien buscar en ReplicatedStorage/TrapSystem por traps instanciadas
            pcall(function()
                local ts = game:GetService("ReplicatedStorage"):FindFirstChild("TrapSystem")
                if ts then
                    for _, trap in ipairs(workspace:GetDescendants()) do
                        if trap.Name == "TrapVisual" then
                            pcall(function() trap.Transparency = 1; trap.CanCollide = false end)
                        end
                    end
                end
            end)
        end

        local function _restoreAllTraps()
            for _, obj in ipairs(workspace:GetChildren()) do
                if obj:FindFirstChild("TrapVisual") and obj:FindFirstChild("PlacedPlayer") then
                    local tv = obj:FindFirstChild("TrapVisual")
                    if tv then
                        pcall(function() tv.Transparency = 0 end)
                        pcall(function() tv.LocalTransparencyModifier = 0 end)
                        pcall(function() tv.CanCollide = true end)
                    end
                    for _, desc in ipairs(obj:GetDescendants()) do
                        if desc:IsA("BillboardGui") then
                            pcall(function() desc.Enabled = true end)
                        end
                        if desc:IsA("BasePart") then
                            pcall(function() desc.LocalTransparencyModifier = 0 end)
                            pcall(function() desc.CanCollide = true end)
                        end
                    end
                end
            end
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj.Name == "TrapVisual" and obj:IsA("BasePart") then
                    pcall(function()
                        obj.LocalTransparencyModifier = 0
                        obj.Transparency = 0
                        obj.CanCollide = true
                    end)
                end
            end
        end

        CreateAuroraToggle(leftColumn, "Auto Remove Traps", function(en)
            _trapRemEnabled = en
            if _trapRemConn then pcall(function() _trapRemConn:Disconnect() end); _trapRemConn = nil end
            if _trapHbConn  then pcall(function() _trapHbConn:Disconnect()  end); _trapHbConn  = nil end

            if en then
                _removeAllTraps()
                -- Cubrir trampas nuevas que se coloquen (PlaceTrapLocal las hace visibles)
                _trapRemConn = workspace.ChildAdded:Connect(function(obj)
                    if not _trapRemEnabled then return end
                    task.defer(function()
                        if obj:FindFirstChild("TrapVisual") or obj:FindFirstChild("PlacedPlayer") then
                            _hideTrap(obj)
                        end
                    end)
                end)
                -- DescendantAdded en vez de Heartbeat para cubrir TrapHitLocal
                -- (la trampa re-aparece como descendant nuevo al ser golpeada)
                _trapHbConn = workspace.DescendantAdded:Connect(function(obj)
                    if not _trapRemEnabled then return end
                    if obj.Name == "TrapVisual" and obj:IsA("BasePart") then
                        task.defer(function()
                            pcall(function()
                                obj.LocalTransparencyModifier = 1
                                obj.CanCollide = false
                            end)
                        end)
                    end
                end)
 CreateCustomNotification("AUTO REMOVE", "Trampas ocultas", 2)
            else
                _restoreAllTraps()
 CreateCustomNotification("AUTO REMOVE", "Trampas visibles de nuevo", 2)
            end
        end, false)
    end

    -- -- Auto Remove Chroma ---------------------------------------------
    -- Detiene el efecto chroma (loop de tweens de color) en los displays de armas.
    -- Busca ChromaScript en KnifeDisplay/GunDisplay y deshabilita el loop.
    -- Tambien congela el color del Part padre en un color neutro.
    do
        local _chromaRemEnabled = false
        local _chromaConns      = {}

        local function _stopChromaOn(part)
            if not part or not part.Parent then return end
            -- Deshabilitar el ChromaScript si existe
            local cs = part:FindFirstChild("ChromaScript")
            if cs and cs:IsA("LocalScript") then
                pcall(function() cs.Disabled = true end)
            end
            -- Congelar el color del part en blanco neutro para que no quede en un color feo
            if part:IsA("BasePart") then
                pcall(function() part.Color = Color3.fromRGB(255, 255, 255) end)
            end
            -- Tambien buscar en hijos (ChromaScript puede estar dentro del Model)
            for _, desc in ipairs(part:GetDescendants()) do
                local dcs = desc:FindFirstChild("ChromaScript")
                if dcs and dcs:IsA("LocalScript") then
                    pcall(function() dcs.Disabled = true end)
                end
                if desc.Name == "ChromaScript" and desc:IsA("LocalScript") then
                    pcall(function() desc.Disabled = true end)
                end
            end
        end

        local function _resumeChromaOn(part)
            if not part or not part.Parent then return end
            local cs = part:FindFirstChild("ChromaScript")
            if cs and cs:IsA("LocalScript") then
                pcall(function() cs.Disabled = false end)
            end
            for _, desc in ipairs(part:GetDescendants()) do
                if desc.Name == "ChromaScript" and desc:IsA("LocalScript") then
                    pcall(function() desc.Disabled = false end)
                end
            end
        end

        local function _removeAllChroma()
            -- WeaponDisplays en workspace
            local wd = workspace:FindFirstChild("WeaponDisplays")
            if wd then
                for _, display in ipairs(wd:GetDescendants()) do
                    if display.Name == "Chroma" then
                        _stopChromaOn(display)
                    end
                    if display.Name == "ChromaScript" and display:IsA("LocalScript") then
                        pcall(function() display.Disabled = true end)
                    end
                end
            end
            -- Cubrir cualquier Chroma en workspace global
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj.Name == "Chroma" then _stopChromaOn(obj) end
                if obj.Name == "ChromaScript" and obj:IsA("LocalScript") then
                    pcall(function() obj.Disabled = true end)
                end
            end
        end

        local function _restoreAllChroma()
            local wd = workspace:FindFirstChild("WeaponDisplays")
            if wd then
                for _, display in ipairs(wd:GetDescendants()) do
                    if display.Name == "Chroma" then _resumeChromaOn(display) end
                end
            end
        end

        CreateAuroraToggle(leftColumn, "Auto Remove Chroma", function(en)
            _chromaRemEnabled = en
            -- Limpiar conexiones anteriores
            for _, c in ipairs(_chromaConns) do pcall(function() c:Disconnect() end) end
            _chromaConns = {}

            if en then
                _removeAllChroma()
                -- Cubrir nuevas instancias de Chroma
                table.insert(_chromaConns, workspace.DescendantAdded:Connect(function(obj)
                    if not _chromaRemEnabled then return end
                    if obj.Name == "Chroma" then
                        task.defer(function() _stopChromaOn(obj) end)
                    end
                    if obj.Name == "ChromaScript" and obj:IsA("LocalScript") then
                        task.defer(function() pcall(function() obj.Disabled = true end) end)
                    end
                end))
 CreateCustomNotification("AUTO REMOVE", "Chroma desactivado", 2)
            else
                _restoreAllChroma()
 CreateCustomNotification("AUTO REMOVE", "Chroma restaurado", 2)
            end
        end, false)
    end

 CreateAuroraToggle(leftColumn, "Skip Death Animation", function(en)
        if en then
            local _sdaTick=0
            _G._skipDeathAnimConn = RunService.Heartbeat:Connect(function()
                _sdaTick=_sdaTick+1; if _sdaTick<6 then return end; _sdaTick=0  -- OPT: 10Hz
                pcall(function()
                    local char = LocalPlayer.Character
                    if not char then return end
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if not hum then return end
                    -- Cuando el murder nos mata, saltar la animacion de muerte
                    if hum.Health <= 0 or hum:GetState() == Enum.HumanoidStateType.Dead then
                        -- Ocultar el personaje para no ver la animacion
                        for _, part in ipairs(char:GetDescendants()) do
                            if part:IsA("BasePart") then
                                part.LocalTransparencyModifier = 1
                            end
                        end
                        -- Desactivar la animacion de muerte del Animate script
                        local animate = char:FindFirstChild("Animate")
                        if animate then
                            pcall(function() animate.Disabled = true end)
                        end
                        -- Forzar estado GettingUp para cancelar la pose de muerte
                        pcall(function()
                            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        end)
                    end
                end)
            end)
        else
            if _G._skipDeathAnimConn then
                pcall(function() _G._skipDeathAnimConn:Disconnect() end)
                _G._skipDeathAnimConn = nil
            end
            -- Restaurar visibilidad del personaje
            pcall(function()
                local char = LocalPlayer.Character
                if char then
                    for _, part in ipairs(char:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.LocalTransparencyModifier = 0
                        end
                    end
                    local animate = char:FindFirstChild("Animate")
                    if animate then animate.Disabled = false end
                end
            end)
        end
 CreateCustomNotification("WORLD", en and "Skip Death Anim: ON" or "Skip Death Anim: OFF", 2)
    end, false)

 CreateAuroraToggle(leftColumn, "Mute Coin Sound", function(en)
        _slotStates[_currentSlot].sound = en
        _applySlot(_currentSlot)
 -- [notif removed]
    end, false)

    -- -- DISABLE BANK SCANNER --------------------------------------
 CreateAuroraToggle(leftColumn, "Disable Bank Scanner", function(en)
        if not en then return end
        task.spawn(function()
            local bank = workspace:FindFirstChild("Bank2") or workspace:FindFirstChild("Bank")
            if not bank then
                for _, obj in ipairs(workspace:GetChildren()) do
                    if obj.Name:lower():find("bank") then bank = obj; break end
                end
            end
 if not bank then CreateCustomNotification("WORLD", " Bank no encontrado", 3); return end
            local n = 0
            for _, obj in ipairs(bank:GetDescendants()) do
                pcall(function()
                    if obj:IsA("Script") or obj:IsA("LocalScript") then obj.Disabled = true; n = n + 1 end
                    if obj:IsA("BasePart") then
                        local nm = obj.Name:lower()
                        if nm:find("sensor") or nm:find("detect") or nm:find("trigger") then
                            obj.CanTouch = false; obj.Transparency = 1
                        end
                    end
                    if obj:IsA("Sound") then obj.Volume = 0 end
                end)
            end
 CreateCustomNotification("WORLD", "Bank Scanner OFF -- " .. n .. " scripts off", 2)
        end)
    end, false)

    -- -- LOOP INTERACTIVE ------------------------------------------
    local _liRunning = false
    local _liConn    = nil
 CreateAuroraToggle(leftColumn, "Loop Interactive", function(en)
        _liRunning = en
        if _liConn then _liConn:Disconnect(); _liConn = nil end
 if not en then CreateCustomNotification("WORLD", "Loop Interactive: OFF", 1); return end
        local _cached = {}
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("ProximityPrompt") or obj:IsA("ClickDetector") then
                table.insert(_cached, obj)
            end
        end
        _liConn = workspace.DescendantAdded:Connect(function(obj)
            if obj:IsA("ProximityPrompt") or obj:IsA("ClickDetector") then
                table.insert(_cached, obj)
            end
        end)
        task.spawn(function()
            while _liRunning do
                for i = #_cached, 1, -1 do
                    local obj = _cached[i]
                    if not obj or not obj.Parent then table.remove(_cached, i)
                    else
                        pcall(function()
                            if obj:IsA("ProximityPrompt") and obj.Enabled then fireproximityprompt(obj)
                            elseif obj:IsA("ClickDetector") then fireclickdetector(obj) end
                        end)
                    end
                end
                task.wait(0.8)
            end
        end)
 CreateCustomNotification("WORLD", "Loop Interactive: ON", 2)
    end, false)

    -- -- PREDICT CRATE ---------------------------------------------
    local _crateHooked = false
    local _crateConn   = nil
 CreateAuroraToggle(leftColumn, "Predict Crate", function(en)
        if _crateConn then _crateConn:Disconnect(); _crateConn = nil end
 if not en then CreateCustomNotification("WORLD", "Predict Crate: OFF", 1); return end
 if _crateHooked then CreateCustomNotification("WORLD", "Predict Crate: ya activo", 1); return end
        _crateHooked = true
