-- SPIN UNIVERSAL
-- ==============================================================
-- ==============================================================
-- AUTO CLICK / AUTO TOUCH (UNIVERSAL)
-- Funciona en PC (MouseButton1) y Mobile (TouchTap).
-- Slider de delay compartido entre ambos modos.
-- ==============================================================
function CreateWorldUI_AutoClickTouch()
    local sec = CreateSection(rightColumn, "", "AUTO CLICK / AUTO TOUCH", ThemeColors.Aurora2)
    _currentMainSectionFrame = sec

    local subLbl = Instance.new("TextLabel", sec)
    subLbl.Size = UDim2.new(1,-12,0,14)
    subLbl.BackgroundTransparency = 1
    subLbl.Text = "UNIVERSAL (PC + MOBILE)"
    subLbl.Font = Enum.Font.Montserrat
    subLbl.TextSize = 10
    subLbl.TextColor3 = Color3.fromRGB(0, 255, 160)
    subLbl.TextXAlignment = Enum.TextXAlignment.Left
    subLbl.ZIndex = 13

    -- Estado persistente
    if not _G._autoClickTouchState then
        _G._autoClickTouchState = {
            clickEnabled  = false,
            touchEnabled  = false,
            delay         = 0.05,
            clickLoop     = nil,
            touchLoop     = nil,
        }
    end
    local ACT = _G._autoClickTouchState

    -- ---- SLIDER DE DELAY ----------------------------------------
    -- Label de valor actual
    local delayValLbl = Instance.new("TextLabel", sec)
    delayValLbl.Size                = UDim2.new(1,-12,0,18)
    delayValLbl.BackgroundTransparency = 1
    delayValLbl.Text                = string.format("Delay: %.2f s", ACT.delay)
    delayValLbl.Font                = Enum.Font.Montserrat
    delayValLbl.TextSize            = 11
    delayValLbl.TextColor3          = Color3.fromRGB(200, 200, 255)
    delayValLbl.TextXAlignment      = Enum.TextXAlignment.Left
    delayValLbl.ZIndex              = 13

    -- Frame del slider
    local sliderTrack = Instance.new("Frame", sec)
    sliderTrack.Size                = UDim2.new(1,-12,0,14)
    sliderTrack.BackgroundColor3    = Color3.fromRGB(40, 40, 60)
    sliderTrack.BackgroundTransparency = 0.3
    sliderTrack.BorderSizePixel     = 0
    sliderTrack.ZIndex              = 13
    Instance.new("UICorner", sliderTrack).CornerRadius = UDim.new(0, 7)

    local sliderFill = Instance.new("Frame", sliderTrack)
    sliderFill.Size                 = UDim2.new(ACT.delay / 1.0, 0, 1, 0)  -- 0..1 seg
    sliderFill.BackgroundColor3     = Color3.fromRGB(180, 255, 230)
    sliderFill.BorderSizePixel      = 0
    sliderFill.ZIndex               = 14
    Instance.new("UICorner", sliderFill).CornerRadius = UDim.new(0, 7)

    local sliderKnob = Instance.new("Frame", sliderTrack)
    sliderKnob.Size                 = UDim2.new(0, 14, 0, 14)
    sliderKnob.AnchorPoint          = Vector2.new(0.5, 0)
    sliderKnob.Position             = UDim2.new(ACT.delay / 1.0, 0, 0, 0)
    sliderKnob.BackgroundColor3     = Color3.fromRGB(200, 200, 255)
    sliderKnob.BorderSizePixel      = 0
    sliderKnob.ZIndex               = 15
    Instance.new("UICorner", sliderKnob).CornerRadius = UDim.new(1, 0)

    -- Logica de arrastre del slider (PC: MouseButton1 + drag; Mobile: TouchStarted + drag)
    local _sliderDragging = false
    local function _updateSlider(absX)
        local trackAbsPos  = sliderTrack.AbsolutePosition.X
        local trackAbsSize = sliderTrack.AbsoluteSize.X
        local ratio = math.clamp((absX - trackAbsPos) / trackAbsSize, 0, 1)
        ACT.delay = math.max(0.01, ratio * 1.0)   -- rango 0.01 .. 1.00 seg
        sliderFill.Size     = UDim2.new(ratio, 0, 1, 0)
        sliderKnob.Position = UDim2.new(ratio, 0, 0, 0)
        delayValLbl.Text    = string.format("Delay: %.2f s", ACT.delay)
    end

    -- PC drag
    sliderTrack.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
        or inp.UserInputType == Enum.UserInputType.Touch then
            _sliderDragging = true
            _updateSlider(inp.Position.X)
        end
    end)
    sliderTrack.InputEnded:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
        or inp.UserInputType == Enum.UserInputType.Touch then
            _sliderDragging = false
        end
    end)
    UserInputService.InputChanged:Connect(function(inp)
        if not _sliderDragging then return end
        if inp.UserInputType == Enum.UserInputType.MouseMovement
        or inp.UserInputType == Enum.UserInputType.Touch then
            _updateSlider(inp.Position.X)
        end
    end)

    -- ---- Helpers internos ----------------------------------------
    local VirtualInputManager = pcall(function()
        return game:GetService("VirtualInputManager")
    end) and game:GetService("VirtualInputManager") or nil

    local function _doClick()
        -- PC: simular MouseButton1 click
        pcall(function()
            mouse1click()
        end)
        pcall(function()
            if VirtualInputManager then
                VirtualInputManager:SendMouseButtonEvent(0,0,0,true,game,0)
                VirtualInputManager:SendMouseButtonEvent(0,0,0,false,game,0)
            end
        end)
    end

    local function _doTouch()
        -- Mobile: simular tap en el centro de la pantalla
        pcall(function()
            local vp = workspace.CurrentCamera.ViewportSize
            local cx, cy = math.floor(vp.X/2), math.floor(vp.Y/2)
            if VirtualInputManager then
                VirtualInputManager:SendTouchEvent(0, cx, cy, true,  game)
                task.wait(0.02)
                VirtualInputManager:SendTouchEvent(0, cx, cy, false, game)
            end
        end)
        -- Fallback: mouse1click en centro
        pcall(function()
            local vp = workspace.CurrentCamera.ViewportSize
            mouse1click()
        end)
    end

    -- ---- Funciones start/stop ------------------------------------
    local function _startClickLoop()
        if ACT.clickLoop then return end
        ACT.clickLoop = task.spawn(function()
            while ACT.clickEnabled do
                pcall(_doClick)
                task.wait(ACT.delay)
            end
            ACT.clickLoop = nil
        end)
    end
    local function _stopClickLoop()
        ACT.clickEnabled = false
        ACT.clickLoop = nil
    end

    local function _startTouchLoop()
        if ACT.touchLoop then return end
        ACT.touchLoop = task.spawn(function()
            while ACT.touchEnabled do
                pcall(_doTouch)
                task.wait(ACT.delay)
            end
            ACT.touchLoop = nil
        end)
    end
    local function _stopTouchLoop()
        ACT.touchEnabled = false
        ACT.touchLoop = nil
    end

    -- ---- Toggles -------------------------------------------------
    CreateAuroraToggle(sec, "Auto Click (PC + Mobile)", function(on)
        ACT.clickEnabled = on
        if on then
            _startClickLoop()
            CreateCustomNotification("AUTO CLICK", "Auto Click ON  |  Delay: " .. string.format("%.2f",ACT.delay) .. "s", 1.5)
        else
            _stopClickLoop()
            CreateCustomNotification("AUTO CLICK", "Auto Click OFF", 1.5)
        end
    end, false)

    CreateAuroraToggle(sec, "Auto Touch (Mobile)", function(on)
        ACT.touchEnabled = on
        if on then
            _startTouchLoop()
            CreateCustomNotification("AUTO TOUCH", "Auto Touch ON  |  Delay: " .. string.format("%.2f",ACT.delay) .. "s", 1.5)
        else
            _stopTouchLoop()
            CreateCustomNotification("AUTO TOUCH", "Auto Touch OFF", 1.5)
        end
    end, false)
end

function CreateWorldUI_SpinSection()
    local sec = CreateSection(rightColumn, "", "SPIN", ThemeColors.Primary)
    _currentMainSectionFrame = sec

    local subLbl = Instance.new("TextLabel", sec)
    subLbl.Size = UDim2.new(1,-12,0,14)
    subLbl.BackgroundTransparency = 1
    subLbl.Text = "UNIVERSAL"
    subLbl.Font = Enum.Font.Montserrat
    subLbl.TextSize = 10
    subLbl.TextColor3 = Color3.fromRGB( 50, 255, 180)
    subLbl.TextXAlignment = Enum.TextXAlignment.Left

    -- FIX AUTO-ACTIVAR: resetear enabled/bindEnabled al abrir el tab para que
    -- el spin no se reactive solo. Los conns fisicos se limpian siempre.
    -- Solo preservar fontSize y sizeX (preferencias de UI, no estado funcional).
    local _prevFontSize = _G._spinState and _G._spinState.fontSize or 10
    local _prevSizeX    = _G._spinState and _G._spinState.sizeX    or 38
    -- Desconectar loops anteriores y destruir bindable anterior antes de recrear la UI
    if _G._spinState then
        if _G._spinState.conn then pcall(function() _G._spinState.conn:Disconnect() end) end
    end
    -- Destruir boton bindable previo si qued? flotando
    pcall(function() DestroyCapyBind("SPIN") end)
    _G._spinState = { enabled=false, bindEnabled=false, conn=nil, fontSize=_prevFontSize, sizeX=_prevSizeX }
    local SS = _G._spinState

    local spinConn = nil

    -- Helper local: inicia el loop de spin
    local function _startSpin()
        if spinConn then spinConn:Disconnect() spinConn = nil end
        local RS = RunService
        local _spinHB = 0
        spinConn = RS.Heartbeat:Connect(function()
            _spinHB = _spinHB + 1; if _spinHB < 3 then return end; _spinHB = 0
            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if hrp then hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(24), 0) end
        end)
    end

    -- Helper local: detiene el loop de spin
    local function _stopSpin()
        if spinConn then spinConn:Disconnect() spinConn = nil end
    end

    -- FIX: pasar initialValue=false explicito para que CreateToggle nunca restaure
    -- un estado guardado de "Spin" como true (el toggle se limpia al abrir el tab)
    CreateAuroraToggle(sec, "Spin", function(on)
        SS.enabled = on
        if on then _startSpin() else _stopSpin() end
    end, false)  -- false = nunca auto-activar

    CreateAuroraToggle(sec, "Enable Spin Bindable Button", function(on)
        SS.bindEnabled = on
        -- Limpiar keybind anterior
        if SS.conn then pcall(function() SS.conn:Disconnect() end) SS.conn = nil end
        if on then
            -- Crear ScreenGui para el boton bindable
            local _spinBindSg = Instance.new("ScreenGui")
            _spinBindSg.Name            = "CapyBindSg_SPIN_holder"
            _spinBindSg.ResetOnSpawn    = false
            _spinBindSg.DisplayOrder    = 9997
            _spinBindSg.ZIndexBehavior  = Enum.ZIndexBehavior.Sibling
            _spinBindSg.IgnoreGuiInset  = true
            pcall(function() _spinBindSg.Parent = game:GetService("CoreGui") end)
            if not _spinBindSg.Parent then
                _spinBindSg.Parent = LocalPlayer:WaitForChild("PlayerGui")
            end
            SS._spinBindSg = _spinBindSg

            -- Crear el boton visual en pantalla
            MakeCapyBindableFrame(_spinBindSg, "SPIN", function()
                SS.enabled = not SS.enabled
                if SS.enabled then
                    _startSpin()
                else
                    _stopSpin()
                end
            end)

            -- Tambien mantener keybind por tecla R (complementario al boton)
            SS.conn = UserInputService.InputBegan:Connect(function(inp, gpe)
                if gpe then return end
                if inp.KeyCode == Enum.KeyCode.R then
                    SS.enabled = not SS.enabled
                    if SS.enabled then _startSpin() else _stopSpin() end
                end
            end)
        else
            -- Destruir el boton bindable visual
            pcall(function() DestroyCapyBind("SPIN") end)
            if SS._spinBindSg then
                pcall(function() SS._spinBindSg:Destroy() end)
                SS._spinBindSg = nil
            end
            -- Asegurarse que el spin se detiene si estaba activo por el bind
            _stopSpin()
            SS.enabled = false
        end
    end, false)  -- false = nunca auto-activar

    CreateSlider(sec, "Spin Bind Text Size", 6, 24, SS.fontSize, function(v) SS.fontSize = v end)
    CreateSlider(sec, "Spin Bind Size X",    20, 120, SS.sizeX,   function(v) SS.sizeX   = v end)
end

-- ==============================================================
-- FIREFLIES / FAKE BOMB CLUTCH
-- ==============================================================
function CreateWorldUI_ClutchSection()
    local sec = CreateSection(leftColumn, "", "CLUTCH", ThemeColors.Accent)
    _currentMainSectionFrame = sec

    _G._clutchState = _G._clutchState or {
        fireflies = false,
        fakeBomb  = false,
        showBtn   = false,
        autoTP    = false,
        autoJump  = false,
    }
    local CS = _G._clutchState

    -- FIREFLIES CLUTCH: si el Murderer se acerca a menos de 30 studs, TP al jugador mas lejano (escape)
    if not _G._firefliesClutchConn then _G._firefliesClutchConn = nil end
    CreateToggle(sec, "Fireflies Clutch", CS.fireflies, function(on)
        CS.fireflies = on
        if _G._firefliesClutchConn then
            pcall(function() _G._firefliesClutchConn:Disconnect() end)
            _G._firefliesClutchConn = nil
        end
        if on then
            local _ffLastTP = 0
            _G._firefliesClutchConn = RunService.Heartbeat:Connect(function()
                if not CS.fireflies then return end
                local now = tick()
                if now - _ffLastTP < 4 then return end  -- cooldown 4s
                local myChar = LocalPlayer.Character
                local myHrp  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myHrp then return end
                -- Detectar murderer
                local murd = findMurderer and findMurderer()
                if not murd or not murd.Character then return end
                local mHrp = murd.Character:FindFirstChild("HumanoidRootPart")
                if not mHrp then return end
                local dist = (mHrp.Position - myHrp.Position).Magnitude
                if dist > 30 then return end  -- solo actuar si el murder esta cerca
                _ffLastTP = now
                -- Buscar el jugador mas lejano al murderer (escape optimo)
                local bestPlayer, bestDist = nil, 0
                for _, p in ipairs(_cachedPlayers) do
                    if p ~= LocalPlayer and p ~= murd and p.Character then
                        local pH = p.Character:FindFirstChild("HumanoidRootPart")
                        if pH then
                            local d = (pH.Position - mHrp.Position).Magnitude
                            if d > bestDist then bestDist = d; bestPlayer = p end
                        end
                    end
                end
                if bestPlayer and bestPlayer.Character then
                    local tHrp = bestPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if tHrp then
                        pcall(function()
                            myHrp.CFrame = tHrp.CFrame * CFrame.new(0, 0, 3)
                        end)
                        CreateCustomNotification("FIREFLIES CLUTCH", "Escape -> " .. bestPlayer.Name, 2)
                    end
                else
                    -- Fallback: TP lejos del murder en linea recta
                    pcall(function()
                        local dir = (myHrp.Position - mHrp.Position).Unit
                        myHrp.CFrame = CFrame.new(myHrp.Position + dir * 80)
                    end)
                    CreateCustomNotification("FIREFLIES CLUTCH", "Escape rapido del murder!", 2)
                end
            end)
            -- [notif removed]
        else
            -- [notif removed]
        end
    end)

    -- FAKE BOMB CLUTCH: equipa y lanza la FakeBomb automaticamente si el murder esta a menos de 20 studs
    if not _G._fakeBombClutchConn then _G._fakeBombClutchConn = nil end
    CreateToggle(sec, "Fake Bomb Clutch", CS.fakeBomb, function(on)
        CS.fakeBomb = on
        if _G._fakeBombClutchConn then
            pcall(function() _G._fakeBombClutchConn:Disconnect() end)
            _G._fakeBombClutchConn = nil
        end
        if on then
            local _fbLastLaunch = 0
            _G._fakeBombClutchConn = RunService.Heartbeat:Connect(function()
                if not CS.fakeBomb then return end
                local now = tick()
                if now - _fbLastLaunch < 5 then return end  -- cooldown 5s
                local myChar = LocalPlayer.Character
                local myHrp  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local hum    = myChar and myChar:FindFirstChildOfClass("Humanoid")
                if not myHrp or not hum or hum.Health <= 0 then return end
                -- Detectar murderer
                local murd = findMurderer and findMurderer()
                if not murd or not murd.Character then return end
                local mHrp = murd.Character:FindFirstChild("HumanoidRootPart")
                if not mHrp then return end
                local dist = (mHrp.Position - myHrp.Position).Magnitude
                if dist > 20 then return end  -- solo si el murder esta muy cerca
                _fbLastLaunch = now
                -- Buscar FakeBomb en backpack o en mano
                local fb = LocalPlayer.Backpack:FindFirstChild("FakeBomb")
                       or myChar:FindFirstChild("FakeBomb")
                if not fb or not fb:IsA("Tool") then
                    CreateCustomNotification("FAKE BOMB CLUTCH", "No se encontro FakeBomb en inventario", 2)
                    return
                end
                -- Equipar si no esta en mano
                if not myChar:FindFirstChild("FakeBomb") then
                    pcall(function() hum:EquipTool(fb) end)
                    task.wait(0.12)
                end
                local equipped = myChar:FindFirstChild("FakeBomb")
                if equipped and equipped:IsA("Tool") then
                    pcall(function() equipped:Activate() end)
                    pcall(function()
                        local remote = equipped:FindFirstChildOfClass("RemoteEvent")
                                    or equipped:FindFirstChild("Throw")
                                    or equipped:FindFirstChild("Launch")
                        if remote then remote:FireServer() end
                    end)
                    CreateCustomNotification("FAKE BOMB CLUTCH", "FakeBomb lanzada al murder!", 2)
                end
            end)
            -- [notif removed]
        else
            -- [notif removed]
        end
    end)

end

