function CreateWorldUI_TeleportAboveMap()
    local sec = CreateSection(rightColumn, "", "Teleport To Above Map", ThemeColors.Primary)
    _currentMainSectionFrame = sec

    _G._tpAboveMap = _G._tpAboveMap or { enabled=false, conn=nil, fontSize=10, sizeX=38, sizeY=38 }
    local S = _G._tpAboveMap

    local function doTPAbove()
        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        hrp.CFrame = CFrame.new(hrp.Position.X, 5000, hrp.Position.Z)
        CreateCustomNotification("TP ABOVE MAP", "Teleportado arriba del mapa!", 2)
    end

    _makeTPButton("Teleport To Above Map", doTPAbove, sec)

    CreateToggle(sec, "Enable TP To AM Bindable Button", false, function(on)
        S.enabled = on
        if S.conn then pcall(function() S.conn:Disconnect() end) S.conn = nil end
        -- Destruir GUI bindable anterior
        local _oldGui = _G._BindableGuiRegistry and _G._BindableGuiRegistry["TP AM_CapyBtn"]
        if _oldGui then pcall(function() _oldGui:Destroy() end) end
        _destroyNamedBindableGui("TP AM_CapyBtn")
        if on then
            -- Crear boton flotante bindable
            local _sg = Instance.new("ScreenGui")
            _sg.Name = "TpAMBindable"; _sg.ResetOnSpawn = false
            _sg.Parent = LocalPlayer.PlayerGui
            local _bf = MakeCapyBindableFrame(_sg, "TP AM", function()
                doTPAbove()
            end)
            -- Aplicar tamanos configurados por sliders
            if _bf then
                pcall(function()
                    _bf.Size = UDim2.new(0, S.sizeX, 0, S.sizeY)
                    local lbl = _bf:FindFirstChildOfClass("TextLabel")
                    if lbl then lbl.TextSize = S.fontSize end
                end)
            end
            S.conn = UserInputService.InputBegan:Connect(function(inp, gpe)
                if gpe or _G._hubDisableKeybinds then return end
                if inp.KeyCode == Enum.KeyCode.H then doTPAbove() end
            end)
        end
    end)

    CreateSlider(sec, "Teleport To Above Map Bind Text Size", 6, 24, S.fontSize, function(v) S.fontSize = v end)
    CreateSlider(sec, "Teleport To Above Map Bind Size X",    20, 120, S.sizeX,   function(v) S.sizeX   = v end)
    CreateSlider(sec, "Teleport To Above Map Bind Size Y",    20, 120, S.sizeY,   function(v) S.sizeY   = v end)
end

-- ==============================================================
-- VOID TELEPORT (MM2/MMV)
-- ==============================================================
function CreateWorldUI_VoidTeleport()
    local sec = CreateSection(leftColumn, "", "VOID", ThemeColors.Primary)
    _currentMainSectionFrame = sec

    local subLbl = Instance.new("TextLabel", sec)
    subLbl.Size = UDim2.new(1,-12,0,14)
    subLbl.BackgroundTransparency = 1
    subLbl.Text = "MM2 / MMV"
    subLbl.Font = Enum.Font.Montserrat
    subLbl.TextSize = 10
    subLbl.TextColor3 = Color3.fromRGB( 50, 255, 180)
    subLbl.TextXAlignment = Enum.TextXAlignment.Left

    _G._tpVoid = _G._tpVoid or {
        enabled  = false,
        conn     = nil,
        fontSize = 10,
        sizeX    = 38,
        sizeY    = 38,
        platform = nil,
    }
    _G._tpVoid.enabled = false
    local V = _G._tpVoid

    -- Destruir plataforma anterior si existe
    local function _destroyVoidPlat()
        if V.platform and V.platform.Parent then
            pcall(function() V.platform:Destroy() end)
        end
        V.platform = nil
    end

    -- Crear plataforma en Y=50000 y TP al jugador encima (igual que Under Map Farm)
    local function doTPVoid()
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end

        _destroyVoidPlat()

        local plat = Instance.new("Part")
        plat.Name       = "UnderMapPlatform"
        plat.Size       = Vector3.new(50, 5, 50)
        plat.Position   = Vector3.new(0, 50000, 0)
        plat.Anchored   = true
        plat.CanCollide = true
        plat.BrickColor = BrickColor.new("Really black")
        plat.Material   = Enum.Material.ForceField
        plat.Parent     = workspace
        V.platform      = plat

        pcall(function() hrp.CFrame = plat.CFrame * CFrame.new(0, 5, 0) end)
        task.wait(0.1)
        pcall(function()
            local c2  = LocalPlayer.Character
            local h2  = c2 and c2:FindFirstChild("HumanoidRootPart")
            if h2 then h2.CFrame = plat.CFrame * CFrame.new(0, 5, 0) end
        end)
        CreateCustomNotification("TP VOID", "Plataforma creada en el void!", 2)
    end

    -- Boton principal
    _currentMainSectionFrame = sec
    _makeTPButton("Teleport To Void (Platform)", doTPVoid, sec)

    -- Boton para destruir la plataforma y volver al mapa
    _makeTPButton("Destruir Plataforma", function()
        _destroyVoidPlat()
        CreateCustomNotification("TP VOID", "Plataforma destruida", 2)
    end, sec)

    CreateToggle(sec, "Enable TP To Void Bindable Button", false, function(on)
        V.enabled = on
        if V.conn then pcall(function() V.conn:Disconnect() end) V.conn = nil end
        -- Destruir GUI bindable anterior
        local _oldGui = _G._BindableGuiRegistry and _G._BindableGuiRegistry["TP VOID_CapyBtn"]
        if _oldGui then pcall(function() _oldGui:Destroy() end) end
        _destroyNamedBindableGui("TP VOID_CapyBtn")
        if on then
            -- Crear boton flotante bindable
            local _sg = Instance.new("ScreenGui")
            _sg.Name = "TpVoidBindable"; _sg.ResetOnSpawn = false
            _sg.Parent = LocalPlayer.PlayerGui
            local _bf = MakeCapyBindableFrame(_sg, "TP VOID", function()
                doTPVoid()
            end)
            if _bf then
                pcall(function()
                    _bf.Size = UDim2.new(0, V.sizeX, 0, V.sizeY)
                    local lbl = _bf:FindFirstChildOfClass("TextLabel")
                    if lbl then lbl.TextSize = V.fontSize end
                end)
            end
            V.conn = UserInputService.InputBegan:Connect(function(inp, gpe)
                if gpe then return end
                if inp.KeyCode == Enum.KeyCode.J then doTPVoid() end
            end)
        end
    end)

    CreateSlider(sec, "Teleport To Void Bind Text Size", 6, 24, V.fontSize, function(v) V.fontSize = v end)
    CreateSlider(sec, "Teleport To Void Bind Size X",    20, 120, V.sizeX,   function(v) V.sizeX   = v end)
    CreateSlider(sec, "Teleport To Void Bind Size Y",    20, 120, V.sizeY,   function(v) V.sizeY   = v end)
end

-- ==============================================================
-- EXPOSE ROLES
-- ==============================================================
function CreateWorldUI_ExposeRoles()
    local sec = CreateSection(rightColumn, "", "EXPOSE ROLES", ThemeColors.Accent)
    _currentMainSectionFrame = sec
    _G._autoExposeEnabled = false
    _G._autoExposeRoles   = false

    local subLbl = Instance.new("TextLabel", sec)
    subLbl.Size = UDim2.new(1,-12,0,14); subLbl.BackgroundTransparency = 1
    subLbl.Text = "UNIVERSAL"; subLbl.Font = Enum.Font.Montserrat; subLbl.TextSize = 10
    subLbl.TextColor3 = Color3.fromRGB( 50, 255, 180); subLbl.TextXAlignment = Enum.TextXAlignment.Left

    -- Usa _roleCache (mas confiable) con fallback a busqueda por herramienta
    local function getRoles()
        local murder  = (_roleCache and _roleCache.murderer) or nil
        local sheriff = (_roleCache and _roleCache.sheriff)  or nil
        -- fallback: buscar por herramienta si roleCache no tiene datos
        if not murder or not sheriff then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    for _, c in ipairs(p.Character:GetChildren()) do
                        if not murder and (c.Name:lower():find("murder") or (c:IsA("Tool") and c.Name:lower():find("knife"))) then
                            murder = p
                        end
                        if not sheriff and c.Name:lower():find("sheriff") then
                            sheriff = p
                        end
                    end
                end
            end
        end
        return murder, sheriff
    end

    local function _sayInChat(msg)
        if not msg or msg == "" then return end

        -- Metodo 1: TextChatService -- buscar RBXGeneral especificamente
        local ok1 = pcall(function()
            local tcs = game:GetService("TextChatService")
            -- MM2 usa RBXGeneral como canal principal
            local ch = tcs:FindFirstChild("TextChannels")
            if ch then
                local gen = ch:FindFirstChild("RBXGeneral")
                        or ch:FindFirstChildOfClass("TextChannel")
                if gen then
                    gen:SendAsync(msg)
                    return
                end
            end
            -- Fallback: buscar cualquier TextChannel
            for _, v in ipairs(tcs:GetDescendants()) do
                if v:IsA("TextChannel") then
                    v:SendAsync(msg)
                    return
                end
            end
            error("no channel")
        end)
        if ok1 then return end

        -- Metodo 2: SayMessageRequest legacy
        local ok2 = pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            -- Buscar en toda la jerarquia
            local function findRemote(parent, name)
                for _, v in ipairs(parent:GetDescendants()) do
                    if v.Name == name and (v:IsA("RemoteEvent") or v:IsA("RemoteFunction")) then
                        return v
                    end
                end
            end
            local sr = findRemote(rs, "SayMessageRequest")
                    or findRemote(rs, "SendChatMessage")
                    or findRemote(rs, "SayMessage")
            if sr then
                if sr:IsA("RemoteEvent") then
                    sr:FireServer(msg, "All")
                else
                    sr:InvokeServer(msg, "All")
                end
                return
            end
            error("no remote")
        end)
        if ok2 then return end

        -- Metodo 3: LocalPlayer:Chat (fallback universal, visible solo localmente)
        pcall(function() LocalPlayer:Chat(msg) end)
    end

    -- -- Auto Expose Murderer ---------------------------------------------
    CreateToggle(sec, "Auto Expose Murderer's Perk", false, function(on)
        _G._autoExposeEnabled = on
        if on then
            task.spawn(function()
                while _G._autoExposeEnabled do
                    task.wait(3)
                    local m = getRoles()
                    if m then
                        local msg = "El murder es " .. m.Name .. "!!"
                        _sayInChat(msg)
                        CreateCustomNotification("EXPOSE", msg, 3)
                    end
                end
            end)
        end
    end)

    -- -- Auto Expose Roles (murder + sheriff) ----------------------------
    CreateToggle(sec, "Auto Expose Roles", false, function(on)
        _G._autoExposeRoles = on
        if on then
            task.spawn(function()
                while _G._autoExposeRoles do
                    task.wait(3)
                    local m, s = getRoles()
                    if m then
                        local msg = "El murder es " .. m.Name .. "!!"
                        _sayInChat(msg)
                        CreateCustomNotification("EXPOSE", msg, 3)
                    end
                    if s then
                        task.wait(0.8)  -- pequena pausa entre mensajes para no spamear
                        local msg = "El sheriff es " .. s.Name
                        _sayInChat(msg)
                        CreateCustomNotification("EXPOSE", msg, 3)
                    end
                end
            end)
        end
    end)

    -- -- Botones manuales ------------------------------------------------
    _makeTPButton("Expose Roles (chat)", function()
        local m, s = getRoles()
        local parts = {}
        if m then table.insert(parts, "Murder: " .. m.Name) end
        if s then table.insert(parts, "Sheriff: " .. s.Name) end
        if #parts > 0 then
            local msg = table.concat(parts, " | ")
            _sayInChat(msg)
            CreateCustomNotification("ROLES", msg, 4)
        else
            CreateCustomNotification("ROLES", "No se detectaron roles", 2)
        end
    end, sec)

    _makeTPButton("Expose Murderer (chat)", function()
        local m = getRoles()
        if m then
            local msg = "El murder es " .. m.Name .. "!!"
            _sayInChat(msg)
            CreateCustomNotification("MURDER", msg, 3)
        else
            CreateCustomNotification("MURDER", "No se detecto el murder", 2)
        end
    end, sec)

    _makeTPButton("Expose Sheriff (chat)", function()
        local _, s = getRoles()
        if s then
            local msg = "El sheriff es " .. s.Name
            _sayInChat(msg)
            CreateCustomNotification("SHERIFF", msg, 3)
        else
            CreateCustomNotification("SHERIFF", "No se detecto el sheriff", 2)
        end
    end, sec)

    _makeTPButton("Expose Murderer's Perk", function()
        local m = getRoles()
        if m and m.Character then
            local perk = "Desconocido"
            for _, c in ipairs(m.Character:GetChildren()) do
                if c.Name:lower():find("perk") or c.Name:lower():find("ability") then perk = c.Name end
            end
            local msg = "Perk de " .. m.Name .. ": " .. perk
            _sayInChat(msg)
            CreateCustomNotification("PERK", msg, 3)
        else
            CreateCustomNotification("PERK", "No hay murder detectado", 2)
        end
    end, sec)
end

-- ==============================================================
-- TELEPORT TO LOBBY
-- ==============================================================
function CreateWorldUI_TeleportLobby()
    local sec = CreateSection(leftColumn, "", "LOBBY", ThemeColors.Primary)
    _currentMainSectionFrame = sec

    local subLbl = Instance.new("TextLabel", sec)
    subLbl.Size = UDim2.new(1,-12,0,14); subLbl.BackgroundTransparency = 1
    subLbl.Text = "MM2 / MMV"; subLbl.Font = Enum.Font.Montserrat; subLbl.TextSize = 10
    subLbl.TextColor3 = Color3.fromRGB( 50, 255, 180); subLbl.TextXAlignment = Enum.TextXAlignment.Left

    _G._tpLobby = _G._tpLobby or { enabled=false, conn=nil, fontSize=10, sizeX=38 }
    _G._tpLobby.enabled = false
    local L = _G._tpLobby

    _makeTPButton("Teleport To Lobby", function()
        pcall(TeleportToLobby)
    end, sec)
    CreateToggle(sec, "Enable TP To Lobby Bindable Button", false, function(on)
        L.enabled = on
        if L.conn then pcall(function() L.conn:Disconnect() end) L.conn = nil end
        -- Destruir boton flotante anterior (ScreenGui helper + CapyBind)
        if L._sg then pcall(function() L._sg:Destroy() end) L._sg = nil end
        pcall(function() DestroyCapyBind("TP LOBBY") end)
        -- Barrer cualquier remanente por nombre en PlayerGui
        pcall(function()
            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            if pg then
                for _, g in ipairs(pg:GetChildren()) do
                    if g.Name == "TpLobbyBindable" then g:Destroy() end
                end
            end
        end)
        if on then
            -- Crear boton flotante bindable
            local _sg = Instance.new("ScreenGui")
            _sg.Name = "TpLobbyBindable"; _sg.ResetOnSpawn = false
            _sg.Parent = LocalPlayer.PlayerGui
            L._sg = _sg  -- guardar referencia para destruir al desactivar
            local _bf = MakeCapyBindableFrame(_sg, "TP LOBBY", function()
                pcall(TeleportToLobby)
            end)
            if _bf then
                pcall(function()
                    _bf.Size = UDim2.new(0, L.sizeX, 0, L.sizeX) -- sizeY = sizeX (Lobby solo tiene sizeX)
                    local lbl = _bf:FindFirstChildOfClass("TextLabel")
                    if lbl then lbl.TextSize = L.fontSize end
                end)
            end
            L.conn = UserInputService.InputBegan:Connect(function(inp, gpe)
                if gpe then return end
                if inp.KeyCode == Enum.KeyCode.K then pcall(TeleportToLobby) end
            end)
        end
    end)
    CreateSlider(sec, "Teleport To Lobby Bind Text Size", 6, 24, L.fontSize, function(v)
        L.fontSize = v
        local sg = _G._capyBindRegistry and _G._capyBindRegistry["TP LOBBY"]
        if sg then
            local bf = sg:FindFirstChild("CapyBindBtn")
            if bf then
                local lbl = bf:FindFirstChildOfClass("TextLabel")
                if lbl then lbl.TextSize = v end
            end
        end
    end)
    CreateSlider(sec, "Teleport To Lobby Bind Size X",    20, 120, L.sizeX,   function(v)
        L.sizeX = v
        local sg = _G._capyBindRegistry and _G._capyBindRegistry["TP LOBBY"]
        if sg then
            local bf = sg:FindFirstChild("CapyBindBtn")
            if bf then bf.Size = UDim2.fromOffset(v, v) end
        end
    end)
end

