-- WORLD TAB ? BOMB DOUBLE JUMP
-- Movido desde MAIN. Incluye toggles base + nuevos de imagen:
-- ------------------------------------------------------------------------
--   Auto Teleport On Throw, Auto Jump When Teleported
-- ------------------------------------------------------------------------
function CreateWorldUI_BombJump()
    local section = CreateSection(leftColumn, "", "BOMB DOUBLE JUMP", ThemeColors.Primary)

    local clutchSection = CreateSection(leftColumn, "", "CLUTCH & AUTO", ThemeColors.Accent)
    _currentMainSectionFrame = clutchSection

    -- Show Fake Bomb Button ? bot?n rectangular peque?o que auto-equipa y lanza la FakeBomb
    do
        local _fbBtnGui = nil
        local _fbAutoConn = nil

        local function _destroyFBBtn()
            if _fbAutoConn then pcall(function() _fbAutoConn:Disconnect() end); _fbAutoConn = nil end
            if _fbBtnGui then pcall(function() _fbBtnGui:Destroy() end); _fbBtnGui = nil end
        end

        local function _equipAndThrowFakeBomb()
            local char    = LocalPlayer.Character
            local hum     = char and char:FindFirstChildOfClass("Humanoid")
            if not hum or hum.Health <= 0 then return end

            -- Buscar FakeBomb en Backpack o Character
            local fb = LocalPlayer.Backpack:FindFirstChild("FakeBomb")
                    or (char and char:FindFirstChild("FakeBomb"))

            -- Tambi?n intentar por la ruta exacta del juego
            if not fb then
                pcall(function()
                    fb = game:GetService("Players")[LocalPlayer.Name].Backpack:FindFirstChild("FakeBomb")
                end)
            end

            if not fb then
                CreateCustomNotification("FAKE BOMB", "No hay FakeBomb en el inventario", 2)
                return
            end

            -- Equipar
            pcall(function() hum:EquipTool(fb) end)

            -- Esperar un frame y disparar (simular click)
            task.wait(0.08)
            pcall(function()
                local tool = char and char:FindFirstChild("FakeBomb")
                if tool then
                    local remote = tool:FindFirstChildOfClass("RemoteEvent")
                             or tool:FindFirstChild("Activate")
                    if remote then
                        remote:FireServer()
                    else
                        -- Activar v?a evento de herramienta
                        tool:Activate()
                    end
                end
            end)
        end

        local function _createFBBtn()
            _destroyFBBtn()
            local W, H = 90, 34  -- rectangular peque?o

            local sg = Instance.new("ScreenGui")
            sg.Name           = "FakeBombSmallBtn"
            sg.ResetOnSpawn   = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true
            sg.DisplayOrder   = 9998
            pcall(function() sg.Parent = game:GetService("CoreGui") end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _fbBtnGui = sg

            local frame = Instance.new("Frame", sg)
            frame.Name                   = "FBSmallFrame"
            frame.Size                   = UDim2.fromOffset(W, H)
            frame.Position               = UDim2.fromOffset(200, 500)
            frame.BackgroundColor3       = Color3.fromRGB(  3,   8,  18)
            frame.BackgroundTransparency = 0.2
            frame.BorderSizePixel        = 0
            frame.Active                 = true
            frame.ZIndex                 = 200
            Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 8)

            local stroke = Instance.new("UIStroke", frame)
            stroke.Color        = Color3.fromRGB(255,   0,  40)
            stroke.Thickness    = 2
            stroke.Transparency = 0.1

            -- Pulso del borde
            task.spawn(function()
                while stroke and stroke.Parent do
                    TweenService:Create(stroke, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Transparency=0.7}):Play()
                    task.wait(1.2)
                    if not (stroke and stroke.Parent) then break end
                    TweenService:Create(stroke, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Transparency=0.0}):Play()
                    task.wait(1.2)
                end
            end)

            local lbl = Instance.new("TextLabel", frame)
            lbl.Size                 = UDim2.new(1, 0, 1, 0)
            lbl.BackgroundTransparency = 1
            lbl.Text                 = "?? FAKE BOMB"
            lbl.FontFace             = Font.fromEnum(Enum.Font.GothamBold)
            lbl.TextSize             = 11
            lbl.TextColor3           = Color3.fromRGB(255, 180, 180)
            lbl.TextXAlignment       = Enum.TextXAlignment.Center
            lbl.ZIndex               = 201

            -- Drag
            local _dragging, _dragStart, _startPos = false, nil, nil
            local _moved = false
            frame.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _dragging  = true
                    _moved     = false
                    _dragStart = inp.Position
                    _startPos  = frame.Position
                end
            end)
            UserInputService.InputChanged:Connect(function(inp)
                if not _dragging then return end
                if inp.UserInputType ~= Enum.UserInputType.MouseMovement
                and inp.UserInputType ~= Enum.UserInputType.Touch then return end
                local d = inp.Position - _dragStart
                if d.Magnitude > 4 then _moved = true end
                local vp = workspace.CurrentCamera.ViewportSize
                frame.Position = UDim2.fromOffset(
                    math.clamp(_startPos.X.Offset + d.X, 0, vp.X - W),
                    math.clamp(_startPos.Y.Offset + d.Y, 0, vp.Y - H)
                )
            end)
            frame.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _dragging = false
                    if not _moved then
                        -- Click: flash + acci?n
                        TweenService:Create(frame, TweenInfo.new(0.07), {BackgroundColor3=Color3.fromRGB(180,40,40), BackgroundTransparency=0.1}):Play()
                        task.wait(0.1)
                        TweenService:Create(frame, TweenInfo.new(0.2), {BackgroundColor3=Color3.fromRGB(  3,   8,  18), BackgroundTransparency=0.2}):Play()
                        task.spawn(_equipAndThrowFakeBomb)
                    end
                    task.defer(function() _moved = false end)
                end
            end)

            -- Animaci?n de entrada
            local sc = Instance.new("UIScale", frame); sc.Scale = 0
            TweenService:Create(sc, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
        end

        CreateToggle(clutchSection, " Show Fake Bomb Button", function(enabled)
            if enabled then
                _createFBBtn()
                CreateCustomNotification("FAKE BOMB BTN", "Bot?n visible ? click para equipar y lanzar", 2)
            else
                -- Animaci?n de salida antes de destruir
                if _fbBtnGui then
                    local sc = _fbBtnGui:FindFirstChild("FBSmallFrame") and _fbBtnGui.FBSmallFrame:FindFirstChildOfClass("UIScale")
                    if sc then
                        TweenService:Create(sc, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale=0}):Play()
                        task.delay(0.42, _destroyFBBtn)
                    else
                        _destroyFBBtn()
                    end
                end
                CreateCustomNotification("FAKE BOMB BTN", "Bot?n oculto", 1)
            end
        end, false)
    end

    -- Auto Teleport On Throw ? cuando el LocalPlayer lanza la FakeBomb,
    -- se teletransporta autom?ticamente a donde cae el Handle.
    -- FIX: usa los mismos filtros del sistema principal (timestamp < 0.35s,
    -- distancia < 8 studs, bomba m?s cercana a m? que a cualquier otro jugador).
    CreateToggle(clutchSection, " Auto Teleport On Throw", function(enabled)
        _G._autoTeleportOnThrow = enabled
        -- [notif removed]
        if _G._autoTPThrowConn then
            pcall(function() _G._autoTPThrowConn:Disconnect() end)
            _G._autoTPThrowConn = nil
        end
        if enabled then
            local _atLastClick = 0
            local _atCooldown  = 0
            -- Registrar clicks del LocalPlayer (igual que el sistema principal)
            if _G._autoTPClickConn then
                pcall(function() _G._autoTPClickConn:Disconnect() end)
            end
            _G._autoTPClickConn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp then return end
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _atLastClick = tick()
                end
            end)
            _G._autoTPThrowConn = workspace.ChildAdded:Connect(function(child)
                if not _G._autoTeleportOnThrow then return end
                -- Solo handles (bomba lanzada)
                if child.Name ~= "Handle" or not child:IsA("BasePart") then return end
                local now = tick()
                -- Cooldown entre TPs (evitar spam)
                if now - _atCooldown < DJ_COOLDOWN then return end
                -- El click debe ser reciente (< 0.35s), igual que el filtro principal
                if now - _atLastClick > 0.35 then return end
                local c   = LocalPlayer.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                local hum = c and c:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum or hum.Health <= 0 then return end
                -- Bomba debe estar cerca de m? (< 8 studs)
                local myDist = (child.Position - hrp.Position).Magnitude
                if myDist > 8 then return end
                -- Bomba debe ser m?s cercana a m? que a cualquier otro jugador
                for _, p in ipairs(_cachedPlayers) do
                    if p ~= LocalPlayer and p.Character then
                        local oHRP = p.Character:FindFirstChild("HumanoidRootPart")
                        if oHRP then
                            local oDist = (child.Position - oHRP.Position).Magnitude
                            if oDist < myDist then return end
                        end
                    end
                end
                _atCooldown = now
                -- Esperar que el Handle tenga velocidad estable (igual que _doBombJumpV3)
                task.spawn(function()
                    task.wait(0.08)
                    if not child or not child.Parent then return end
                    local c2   = LocalPlayer.Character
                    local hrp2 = c2 and c2:FindFirstChild("HumanoidRootPart")
                    local hum2 = c2 and c2:FindFirstChildOfClass("Humanoid")
                    if not hrp2 or not hum2 or hum2.Health <= 0 then return end
                    local bombPos = child.Position
                    local tpPos   = Vector3.new(bombPos.X, bombPos.Y + DJ_TP_OFFSET_Y, bombPos.Z)
                    pcall(function()
                        hrp2.CFrame = CFrame.new(tpPos)
                        hrp2.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    end)
                    -- [notif removed]
                end)
            end)
        else
            if _G._autoTPClickConn then
                pcall(function() _G._autoTPClickConn:Disconnect() end)
                _G._autoTPClickConn = nil
            end
        end
    end, false)

    -- Auto Jump When Teleported ? cuando el toggle est? activo, cada vez que el
    -- personaje sea teleportado encima de la bomba (por Auto Teleport On Throw O
    -- por el sistema principal de BombJump), ejecuta un salto normal autom?tico.
    -- Funciona de forma independiente: NO requiere que Auto Teleport On Throw
    -- ni BombJumpSystem est?n activos. Detecta el Handle igual que esos sistemas
    -- y hace el salto con Humanoid:ChangeState(Jumping) tras el TP (0.12s delay).
    CreateToggle(clutchSection, " Auto Jump When Teleported", function(enabled)
        _G._autoJumpAfterTP = enabled
        -- [notif removed]
        if _G._autoJumpTPConn then
            pcall(function() _G._autoJumpTPConn:Disconnect() end)
            _G._autoJumpTPConn = nil
        end
        if _G._autoJumpClickConn then
            pcall(function() _G._autoJumpClickConn:Disconnect() end)
            _G._autoJumpClickConn = nil
        end
        if enabled then
            local _ajCooldown  = 0
            local _ajLastClick = 0

            -- Registrar clicks del LocalPlayer para detectar lanzamiento propio
            _G._autoJumpClickConn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp then return end
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _ajLastClick = tick()
                end
            end)

            _G._autoJumpTPConn = workspace.ChildAdded:Connect(function(child)
                if not _G._autoJumpAfterTP then return end
                -- Solo Handles (bomba lanzada al workspace)
                if child.Name ~= "Handle" or not child:IsA("BasePart") then return end
                local now = tick()
                -- Cooldown para evitar spam
                if now - _ajCooldown < DJ_COOLDOWN then return end
                -- El click/lanzamiento debe ser reciente (< 0.35s)
                if now - _ajLastClick > 0.35 then return end
                local c   = LocalPlayer.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                local hum = c and c:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum or hum.Health <= 0 then return end
                -- La bomba debe estar cerca del jugador (< 8 studs)
                local myDist = (child.Position - hrp.Position).Magnitude
                if myDist > 8 then return end
                -- La bomba debe ser m?s cercana a m? que a cualquier otro jugador
                for _, p in ipairs(_cachedPlayers) do
                    if p ~= LocalPlayer and p.Character then
                        local oHRP = p.Character:FindFirstChild("HumanoidRootPart")
                        if oHRP then
                            local oDist = (child.Position - oHRP.Position).Magnitude
                            if oDist < myDist then return end
                        end
                    end
                end
                _ajCooldown = now
                -- Esperar a que el TP haya ocurrido (Auto TP On Throw tarda ~0.08s,
                -- BombJumpSystem tarda ~0.1-0.15s) y luego ejecutar salto normal
                task.delay(0.18, function()
                    if not _G._autoJumpAfterTP then return end
                    local c2   = LocalPlayer.Character
                    local hum2 = c2 and c2:FindFirstChildOfClass("Humanoid")
                    if not hum2 or hum2.Health <= 0 then return end
                    -- Salto normal de Humanoid (igual que presionar Space)
                    pcall(function()
                        hum2:ChangeState(Enum.HumanoidStateType.Jumping)
                    end)
                end)
            end)
        end
    end, false)

    -- -- Click Effect --
    CreateToggle(clutchSection, " Click Effect", function(on)
        _clickEffectEnabled = on
    end, _clickEffectEnabled)
end


-- =====================================================================
-- VOTE MAP SLOTS (TP por slot + Auto Vote c?clico)
-- =====================================================================

-- Estado de auto-vote por slot
_G._voteSlotState = _G._voteSlotState or {
    [1] = { autoEnabled = false, conn = nil, times = 5, delay = 1.0 },
    [2] = { autoEnabled = false, conn = nil, times = 5, delay = 1.0 },
    [3] = { autoEnabled = false, conn = nil, times = 5, delay = 1.0 },
}

-- Busca el VotePad correspondiente al slot (1, 2 o 3) en el workspace
local function _findVoteSlotPart(slotIndex)
    -- Ruta directa: workspace.Lobby.VotePads:GetChildren()[slotIndex]
    local ok, result = pcall(function()
        local votePads = workspace.Lobby.VotePads
        local children = votePads:GetChildren()
        local slot = children[slotIndex]
        if not slot then return nil end
        -- Si el slot es directamente una BasePart, devolverlo
        if slot:IsA("BasePart") then return slot end
        -- Si es un Model/Folder, buscar la primera BasePart dentro
        local part = slot:FindFirstChildOfClass("BasePart")
        return part
    end)
    if ok and result then return result end
    return nil
end

-- TP inmediato al slot elegido
local function _tpToVoteSlot(slotIndex)
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then
        CreateCustomNotification("VOTE MAP", "Personaje no encontrado", 2)
        return
    end
    local part = _findVoteSlotPart(slotIndex)
    if not part then
        CreateCustomNotification("VOTE MAP #" .. slotIndex, "VotePad #" .. slotIndex .. " no encontrado (estas en lobby?)", 3)
        return
    end
    -- Usar posicion directa encima del pad, igual que TeleportToVotepad
    local targetCF = CFrame.new(part.Position + Vector3.new(0, 5, 0))
    task.spawn(function()
        for _ = 1, 5 do
            pcall(function()
                local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if h then
                    h.CFrame = targetCF
                    h.AssemblyLinearVelocity = Vector3.zero
                    h.AssemblyAngularVelocity = Vector3.zero
                end
            end)
            task.wait(0.06)
        end
    end)
    CreateCustomNotification("VOTE MAP #" .. slotIndex, "TP a VotePad #" .. slotIndex, 1.5)
end

-- Auto vote c?clico para un slot: TP + reset + respawn N veces
local function _startAutoVoteSlot(slotIndex, times, delay)
    local S = _G._voteSlotState[slotIndex]
    if not S or S.autoEnabled then return end
    S.autoEnabled = true

    task.spawn(function()
        local part = _findVoteSlotPart(slotIndex)
        if not part then
            CreateCustomNotification("VOTE MAP #" .. slotIndex, "VotePad #" .. slotIndex .. " no encontrado!", 3)
            S.autoEnabled = false
            return
        end

        local cf = CFrame.new(part.Position + Vector3.new(0, 5, 0))
        -- TP inicial
        for _ = 1, 5 do
            pcall(function()
                local h = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if h then h.CFrame = cf; h.AssemblyLinearVelocity = Vector3.zero; h.AssemblyAngularVelocity = Vector3.zero end
            end)
            task.wait(0.06)
        end
        task.wait(0.3)

        for i = 1, times do
            if not S.autoEnabled then break end

            -- Esperar char vivo
            local t = 0
            repeat
                task.wait(0.1); t = t + 0.1
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChild("HumanoidRootPart")
                local hu = c and c:FindFirstChildOfClass("Humanoid")
                if h and hu and hu.Health > 0 then break end
            until t > 10

            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then break end

            -- TP al slot
            if not (part and part.Parent) then
                CreateCustomNotification("VOTE ERROR", "VotePad #" .. slotIndex .. " desaparecio!", 3)
                break
            end
            cf = CFrame.new(part.Position + Vector3.new(0, 5, 0))
            for _ = 1, 5 do
                pcall(function()
                    local h2 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if h2 then h2.CFrame = cf; h2.AssemblyLinearVelocity = Vector3.zero; h2.AssemblyAngularVelocity = Vector3.zero end
                end)
                task.wait(0.06)
            end

            CreateCustomNotification(
                "AUTO VOTE #" .. slotIndex .. " " .. i .. "/" .. times,
                "VotePad #" .. slotIndex, 1.2
            )

            -- Kill + respawn
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 then hum.Health = 0 end
            task.wait(0.15)
            if LocalPlayer.Character == char then
                pcall(function() LocalPlayer:LoadCharacter() end)
            end

            -- Esperar nuevo char
            local oldChar = LocalPlayer.Character
            local tw = 0
            repeat task.wait(0.1); tw = tw + 0.1
            until LocalPlayer.Character ~= oldChar or tw > 8
            task.wait(0.3)

            -- Esperar que cargue bien
            local tw2 = 0
            repeat
                task.wait(0.016); tw2 = tw2 + 0.05
                local nc = LocalPlayer.Character
                local nh = nc and nc:FindFirstChild("HumanoidRootPart")
                local nhu = nc and nc:FindFirstChildOfClass("Humanoid")
                if nh and nhu and nhu.Health > 0 then break end
            until tw2 > 5

            -- TP post-respawn
            for _ = 1, 5 do
                pcall(function()
                    local h3 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if h3 then h3.CFrame = cf; h3.AssemblyLinearVelocity = Vector3.zero; h3.AssemblyAngularVelocity = Vector3.zero end
                end)
                task.wait(0.06)
            end

            if i < times then task.wait(math.max(0.15, delay - 0.3)) end
        end

        S.autoEnabled = false
        CreateCustomNotification("VOTE COMPLETO #" .. slotIndex, "Voto " .. times .. " veces en slot #" .. slotIndex, 3)
    end)
end

local function _stopAutoVoteSlot(slotIndex)
    local S = _G._voteSlotState[slotIndex]
    if S then S.autoEnabled = false end
end

function CreateWorldUI_AutoVote()
    _G._voteSlotState = _G._voteSlotState or {
        [1] = { autoEnabled = false, conn = nil, times = 5, delay = 1.0 },
        [2] = { autoEnabled = false, conn = nil, times = 5, delay = 1.0 },
        [3] = { autoEnabled = false, conn = nil, times = 5, delay = 1.0 },
    }

    local sec = CreateSection(leftColumn, "", "VOTE MAP SLOTS", ThemeColors.Aurora1)
    _currentMainSectionFrame = sec

    for slotIndex = 1, 3 do
        local S = _G._voteSlotState[slotIndex]

        -- Boton TP al slot
        _makeTPButton("Vote Map Slot #" .. slotIndex, function()
            _tpToVoteSlot(slotIndex)
        end, sec)

        -- Toggle auto vote para este slot
        local _timesVal = S.times or 5
        local _delayVal = S.delay or 1.0

        CreateAuroraToggle(sec, "Auto Vote Map Slot #" .. slotIndex, function(on)
            if on then
                _startAutoVoteSlot(slotIndex, _timesVal, _delayVal)
            else
                _stopAutoVoteSlot(slotIndex)
            end
        end, false)
    end
end

