function CreateWorldTab()
    if not contentContainer or not contentContainer.Parent then
        task.wait(0.15)
        if not contentContainer or not contentContainer.Parent then return end
    end
    -- FIX AUTO-ACTIVAR: bloquear auto-activacion de toggles durante la carga del World tab
    -- Los toggles solo muestran su estado visual (ON/OFF) pero no ejecutan su callback al crearse.
    _G._noAutoActivateWorld = true
    -- FIX SPIN: limpiar el estado guardado de toggles que no deben persistir entre sesiones
    if _G._toggleStates then
        _G._toggleStates["Spin"] = false
        _G._toggleStates["Enable Spin Bindable Button"] = false
        _G._toggleStates["Auto Click (PC + Mobile)"] = false
        _G._toggleStates["Auto Touch (Mobile)"]      = false
    end
    -- FIX MAIN TAB ROJO: capturar snapshot de los callbacks YA registrados antes de
    -- que el World Tab agregue los suyos. El bloque de auto-restore al final usara esto
    -- para distinguir toggles de otros tabs (Main, Combat, etc.) y no aplicarles
    -- ApplyState(false), lo que los pintaria de rojo incorrectamente.
    local _worldTabCallbackSnapshot = {}
    if _G._toggleCallbacks then
        for _k in pairs(_G._toggleCallbacks) do
            _worldTabCallbackSnapshot[_k] = true
        end
    end

    ClearContent()
    _makeTwoColumns()  -- FIX: llamar ANTES de las funciones CreateWorldUI_

    -- ======================================================================
    -- FIX LAG WORLD TAB: limpiar TODOS los loops del tab anterior
    -- Cada vez que se entra al World tab se re-crean los toggles/UI, pero
    -- los loops de la instancia anterior quedan corriendo acumulando lag.
    -- Este bloque los desconecta todos antes de re-crear la UI.
    -- ======================================================================
    pcall(function()
        -- FakeLag loop
        if _G._worldFl then
            if _G._worldFl.conn    then _G._worldFl.conn:Disconnect();    _G._worldFl.conn    = nil end
            if _G._worldFl.animConn then _G._worldFl.animConn:Disconnect(); _G._worldFl.animConn = nil end
            _G._worldFl.enabled = false
        end
        -- StretchScreen loop
        if _G._worldStretch then
            if _G._worldStretch.conn then _G._worldStretch.conn:Disconnect(); _G._worldStretch.conn = nil end
            _G._worldStretch.enabled = false
        end
        -- OrbitFling loops
        if _G._worldOrbitFling then
            if _G._worldOrbitFling.conn   then _G._worldOrbitFling.conn:Disconnect();   _G._worldOrbitFling.conn   = nil end
            if _G._worldOrbitFling.noclip then _G._worldOrbitFling.noclip:Disconnect(); _G._worldOrbitFling.noclip = nil end
            _G._worldOrbitFling.active = false
        end
        -- OrbitPlayer loops (Heartbeat + Stepped) -- FIX: faltaba en el cleanup
        if _G._worldOrbitPlayer then
            if _G._worldOrbitPlayer.conn      then pcall(function() _G._worldOrbitPlayer.conn:Disconnect()      end); _G._worldOrbitPlayer.conn      = nil end
            if _G._worldOrbitPlayer.noclipConn then pcall(function() _G._worldOrbitPlayer.noclipConn:Disconnect() end); _G._worldOrbitPlayer.noclipConn = nil end
            _G._worldOrbitPlayer.active = false
        end
        -- GunAura loops (WorldSystem.gunAura)
        local ga = WorldSystem and WorldSystem.gunAura
        if ga then
            if ga.conn        then ga.conn:Disconnect();        ga.conn        = nil end
            if ga._auraAddConn then ga._auraAddConn:Disconnect(); ga._auraAddConn = nil end
            if ga._auraRemConn then ga._auraRemConn:Disconnect(); ga._auraRemConn = nil end
        end
        -- Spectate loops (WorldSystem.spectate)
        local sp = WorldSystem and WorldSystem.spectate
        if sp then
            if sp.conn    then sp.conn:Disconnect();    sp.conn    = nil end
            if sp.camConn then sp.camConn:Disconnect(); sp.camConn = nil end
            sp.enabled = false
        end
        -- KillAll loop (_killAllWorldState)
        if _killAllWorldState and _killAllWorldState.conn then
            _killAllWorldState.conn:Disconnect()
            _killAllWorldState.conn = nil
        end
        -- InfinityJump conns (_G._ijState) -- FIX: limpiar stateConn y charConn tambien
        if _G._ijState then
            if _G._ijState.conn      then pcall(function() _G._ijState.conn:Disconnect()      end) _G._ijState.conn      = nil end
            if _G._ijState.stateConn then pcall(function() _G._ijState.stateConn:Disconnect() end) _G._ijState.stateConn = nil end
            if _G._ijState.charConn  then pcall(function() _G._ijState.charConn:Disconnect()  end) _G._ijState.charConn  = nil end
        end
        -- Auto Respawn conn
        if _G._autoRespawnConn then
            pcall(function() _G._autoRespawnConn:Disconnect() end)
            _G._autoRespawnConn = nil
        end
        -- SFU fling conn
        if _G._sfuState and _G._sfuState.flingConn then
            pcall(function() _G._sfuState.flingConn:Disconnect() end)
            _G._sfuState.flingConn = nil
            _G._sfuState.enabled = false
        end
        -- Notifications droppedConn
        local wn = WorldSystem and WorldSystem.notif
        if wn and wn.droppedConn then
            pcall(function() wn.droppedConn:Disconnect() end)
            wn.droppedConn = nil
        end
        -- _bypasMiraConn (GrabGun aim dot)
        if _G._bypasMiraConn then
            pcall(function() _G._bypasMiraConn:Disconnect() end)
            _G._bypasMiraConn = nil
        end
        -- _chamCoinConn
        if _G._chamCoinConn then
            pcall(function() _G._chamCoinConn:Disconnect() end)
            _G._chamCoinConn = nil
        end
        -- Auto Jump When Teleported click conn
        if _G._autoJumpClickConn then
            pcall(function() _G._autoJumpClickConn:Disconnect() end)
            _G._autoJumpClickConn = nil
        end
        -- Auto Teleport On Throw conns
        if _G._autoTPThrowConn then
            pcall(function() _G._autoTPThrowConn:Disconnect() end)
            _G._autoTPThrowConn = nil
        end
        if _G._autoTPClickConn then
            pcall(function() _G._autoTPClickConn:Disconnect() end)
            _G._autoTPClickConn = nil
        end
        -- Freeze Character conn
        if _G._freezeCharState and _G._freezeCharState.heartConn then
            pcall(function() _G._freezeCharState.heartConn:Disconnect() end)
            _G._freezeCharState.heartConn = nil
        end
        -- AutoClickTouch cleanup
        if _G._autoClickTouchState then
            _G._autoClickTouchState.clickEnabled = false
            _G._autoClickTouchState.touchEnabled = false
            _G._autoClickTouchState.clickLoop    = nil
            _G._autoClickTouchState.touchLoop    = nil
        end
        -- TP Bindable conns -- desconectar y resetear enabled
        if _G._tpAboveMap then
            if _G._tpAboveMap.conn then pcall(function() _G._tpAboveMap.conn:Disconnect() end) _G._tpAboveMap.conn = nil end
            _G._tpAboveMap.enabled = false
        end
        if _G._tpVoid then
            if _G._tpVoid.conn then pcall(function() _G._tpVoid.conn:Disconnect() end) _G._tpVoid.conn = nil end
            _G._tpVoid.enabled = false
        end
        if _G._tpLobby then
            if _G._tpLobby.conn then pcall(function() _G._tpLobby.conn:Disconnect() end) _G._tpLobby.conn = nil end
            if _G._tpLobby._sg then pcall(function() _G._tpLobby._sg:Destroy() end) _G._tpLobby._sg = nil end
            pcall(function() DestroyCapyBind("TP LOBBY") end)
            _G._tpLobby.enabled = false
        end
        if _G._tpToMap then
            if _G._tpToMap.conn then pcall(function() _G._tpToMap.conn:Disconnect() end) _G._tpToMap.conn = nil end
            if _G._tpToMap._sg then pcall(function() _G._tpToMap._sg:Destroy() end) _G._tpToMap._sg = nil end
            pcall(function() DestroyCapyBind("TP MAP") end)
            _G._tpToMap.enabled = false
        end
        -- ProximityPrompts -- resetear al estado default SOLO si los toggles estan apagados
        pcall(function()
            local _ps = _G._proxState
            -- Si instant o noLimit siguen activos, NO resetear (el usuario los quiere activos)
            if not (_ps and (_ps.instant or _ps.noLimit)) then
                for _, v in ipairs(workspace:GetDescendants()) do
                    if v:IsA("ProximityPrompt") then
                        v.HoldDuration = 1
                        v.MaxActivationDistance = 10
                    end
                end
            end
        end)
        -- Error log conn: NO desconectar (es global y debe persistir entre tabs)
        -- Solo se reconecta si fue destruido externamente
    end)

    CreateWorldColumns()

    -- FIX: restaurar zoom de camara al valor correcto al entrar al tab
    pcall(function()
        LocalPlayer.CameraMaxZoomDistance = 400
        LocalPlayer.CameraMinZoomDistance = 0.5
    end)

    local function _safeCall(fn, name)
        local ok, err = pcall(fn)
        if not ok then
            warn("[WORLD TAB] Error en " .. tostring(name) .. ": " .. tostring(err))
        end
    end

    -- LAG FIX: task.wait() entre grupos de safeCall cede el hilo al renderer
    -- evitando el freeze visible al cargar el hub por primera vez.
    _safeCall(CreateWorldUI_GameUtilities,             "GameUtilities")
    _safeCall(CreateWorldUI_BombJump, "BombJump")
    _safeCall(CreateWorldUI_GoldBomb, "GoldBomb")
    -- FakeBombCustomization e InfinityJump eliminados del World tab
    _safeCall(CreateWorldUI_Emotes, "Emotes")
    _safeCall(CreateWorldUI_GotoPlayers, "GotoPlayers")
    _safeCall(CreateWorldUI_Spectate, "Spectate")
    _safeCall(CreateWorldUI_FakeLag, "FakeLag")
    _safeCall(CreateWorldUI_OrbitPlayer, "OrbitPlayer")
    _safeCall(CreateWorldUI_FlingOrbit, "FlingOrbit")
    _safeCall(CreateWorldUI_QuickFlingButtons, "QuickFlingButtons")

    -- FreezeCharacter eliminado del World tab
    _safeCall(CreateWorldUI_AutoVote, "AutoVote")
    -- CreateWorldUI_TeleportUniversal: funcion no implementada (eliminada)
    _safeCall(CreateWorldUI_ProximityPromptSection, "ProximityPromptSection")
    _safeCall(CreateWorldUI_SpinSection, "SpinSection")
    _safeCall(CreateWorldUI_AutoClickTouch, "AutoClickTouch")
    -- ClutchSection y TeleportAboveMap eliminados del World tab
    _safeCall(CreateWorldUI_VoidTeleport, "VoidTeleport")
    _safeCall(CreateWorldUI_ExposeRoles, "ExposeRoles")
    _safeCall(CreateWorldUI_TeleportLobby, "TeleportLobby")
    _safeCall(CreateWorldUI_TeleportToMap, "TeleportToMap")
    _safeCall(CreateWorldUI_StretchScreen, "StretchScreen")
    _safeCall(CreateWorldUI_AutoGrabGun, "AutoGrabGun")
    _safeCall(CreateWorldUI_Performance, "Performance")
    CreateWorldUI_InformationBindables()
    _safeCall(CreateWorldUI_RompGun,                   "RompGun")
    _safeCall(CreateWorldUI_FlingPlayer,               "FlingPlayer")
    _safeCall(CreateWorldUI_AutoPrestige,              "AutoPrestige")
    _safeCall(CreateWorldUI_Teleports,                 "Teleports")
    _safeCall(CreateWorldUI_TeleportToVoid,            "TeleportToVoid")
    _safeCall(CreateWorldUI_TeleportSheriffBindable,   "TeleportSheriffBindable")
    _safeCall(CreateWorldUI_TeleportMurdererBindable,  "TeleportMurdererBindable")



    -- AUTO-RESTORE WORLD TAB: restaurar toggles guardados en disco
    -- Se corre DESPUES de que todos los toggles del tab se registraron en _toggleCallbacks.
    -- Solo activa los que tienen savedState=true y no estan en la blacklist.
    -- FIX BACKGROUND BUILD: capturar el tabFrame aqui para no depender de contentContainer
    -- (que ya fue restaurado al frame real cuando _buildTabCached termina).
    local _worldTabFrame = _G._tabCache and _G._tabCache[2]
    task.defer(function()
        task.defer(function()
            _G._noAutoActivateWorld = false
            if not _G._toggleStates or not _G._toggleCallbacks then return end

            -- FIX AUTO-RESTORE CALLBACKS: ejecutar el callback de cada toggle guardado
            -- sin depender de que su frame este en el arbol de la GUI.
            -- Razon: al construir tabs en background (_buildTabCached), el tabFrame
            -- existe pero puede no estar visible/parentado aun cuando llega este defer.
            -- La solucion es llamar el callback directamente si el toggle esta registrado,
            -- en vez de buscar su frame en la GUI (que puede fallar silenciosamente).
            for nombre, state in pairs(_G._toggleStates) do
                if state == true
                and not (_neverRestoreToggles and _neverRestoreToggles[nombre])
                and _G._toggleCallbacks[nombre] then
                    -- FIX AUTO-SAFE: antes de restaurar, verificar el .txt individual.
                    -- Si el usuario desactivo el toggle manualmente, el .txt dice "false".
                    -- En ese caso NO activar el toggle aunque _G._toggleStates diga true
                    -- (puede haber quedado desincronizado si el JSON se guardo antes de
                    -- que el usuario lo apagara, o si el hub se cerro sin guardar el false).
                    local _txtState = _readToggleFile(nombre)
                    if _txtState == false then
                        -- El archivo .txt dice OFF: el usuario lo apago, respetar esa decision.
                        -- Sincronizar _G._toggleStates para que el knob quede en OFF tambien.
                        _G._toggleStates[nombre] = false
                        -- FIX MAIN TAB ROJO: NO llamar ApplyState(false) para toggles de otros tabs.
                        -- Este bloque itera sobre TODOS los toggles; si un toggle del Main Tab
                        -- (Anti Fling, Anti Void, Anti AFK, etc.) tiene su .txt en false, llamar
                        -- ApplyState(false) lo pinta de rojo aunque ya este visualmente correcto.
                        -- Solo aplicar el visual si el toggle fue registrado en ESTE build del World Tab.
                        if _worldTabCallbackSnapshot and not _worldTabCallbackSnapshot[nombre] then
                            if _G._toggleApplyStates and _G._toggleApplyStates[nombre] then
                                pcall(_G._toggleApplyStates[nombre], false, false)
                            end
                        end
                    else
                        -- _txtState == true o nil (archivo no existe): activar normalmente.
                        -- Silenciar notificaciones durante el restore
                        local _origNotif = CreateCustomNotification
                        CreateCustomNotification = function() end
                        -- FIX: llamar callback directamente sin buscar el frame en GUI.
                        -- El callback ya actualiza el estado interno (ej: GB.enabled = true
                        -- y llama _startDetect() en Gold Bomb) sin necesitar el frame visual.
                        pcall(_G._toggleCallbacks[nombre], true)
                        CreateCustomNotification = _origNotif
                        -- FIX VISUAL KNOB: actualizar el indicador a verde para que el toggle
                        -- muestre ON visualmente, no solo en la logica interna.
                        -- ApplyState es una closure local, pero la exponemos en _toggleApplyStates
                        -- al crear cada toggle para poder llamarla desde aqui.
                        if _G._toggleApplyStates and _G._toggleApplyStates[nombre] then
                            pcall(_G._toggleApplyStates[nombre], true, false)
                        end
                    end
                end
            end

            -- FIX BINDABLES WORLD TAB: despues de restaurar los toggles, re-crear
            -- los botones bindables en pantalla para los toggles que los usan
            -- (ej: TP Sheriff Bindable, TP Murderer Bindable, Shift Lock Bindable, etc.)
            -- updateBindables() recrea solo los botones cuyo Settings.X.bindable == true.
            pcall(updateBindables)
        end)
    end)
end



-- =====================================================================
-- STEAL GUN SYSTEM -- deteccion de sheriff + loop de robo de gun
-- =====================================================================

StealGunSystem = {
    enabled              = false,
    sheriffOriginalFound = nil,
    sheriffDeadDetected  = false,
    roleCheckDisabled    = false,
    gunInBackpackMode    = false,
    _roundToken          = 0,
    _sgCacheConn         = nil,
    _sgRemoveConn        = nil,
}

SheriffDeadBlock = {
    isDeadSheriffID = nil,
    deadSheriffName = nil,
}

-- OPT: lookup tables compartidas ? se crean UNA sola vez para todo el sistema

-- == STEAL GUN v15 ? usa la misma logica de fling que Fling Murder (_doStealFling) ==
-- Flingea al sheriff para forzar el drop de la gun, luego la agarra del suelo.
local function _sgFlingPlayer(TargetPlayer)
    -- FIX DETECCION: forzar refresh sin throttle para obtener sheriff actualizado
    _roleCache.lastUpdate = 0
    _refreshRoleCache()
    local currentSheriff = _roleCache and _roleCache.sheriff

    -- FIX FALLBACK VISUAL: si GetPlayerData no devolvio sheriff, buscar visualmente
    if not currentSheriff and _findGunIn then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then
                local hasGun = _findGunIn(p.Character)
                if not hasGun then
                    local bp = p:FindFirstChildOfClass("Backpack")
                    hasGun = bp and _findGunIn(bp)
                end
                if hasGun then
                    currentSheriff = p
                    _roleCache.sheriff = p
                    break
                end
            end
        end
    end

    -- FIX HERO FLING: solo redirigir al sheriff del cache si el TargetPlayer NO tiene la gun.
    -- Si TargetPlayer ya tiene la gun (es el heroe/nuevo portador), el debe ser el objetivo.
    -- Antes, cuando se llamaba _sgFlingPlayer(newSheriff) con el heroe como target,
    -- currentSheriff podia apuntar al sheriff viejo o a otro jugador, causando que
    -- el heroe nunca fuera flingeado.
    local targetAlreadyHasGun = _findGunIn and (
        (_findGunIn(TargetPlayer.Character) ~= nil) or
        (TargetPlayer:FindFirstChildOfClass("Backpack") and _findGunIn(TargetPlayer:FindFirstChildOfClass("Backpack")) ~= nil)
    )
    if not targetAlreadyHasGun and currentSheriff and currentSheriff ~= TargetPlayer and currentSheriff.Character then
        CreateCustomNotification("STEAL GUN", "Sheriff cambiado -> " .. currentSheriff.Name, 2.5)
        TargetPlayer = currentSheriff
        StealGunSystem.sheriffOriginalFound = currentSheriff
    end

    local tChar = TargetPlayer and TargetPlayer.Character
    local tHRP  = tChar and tChar:FindFirstChild("HumanoidRootPart")
    if not tHRP then return end

    local myChar = LocalPlayer.Character
    local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
    local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
    if not myHRP or not myHum or myHum.Health <= 0 then return end

    -- Si ya tenemos la gun, no hacer nada
    if _sgLocalHasGun() then
        StealGunSystem.enabled = false
        if _G._qfStateRef then _G._qfStateRef.stealGunActive = false end; pcall(function() if _G._sgBindRef and _G._sgBindRef.frame then _G._sgBindRef.frame:SetActiveState(false) end end)
        return
    end

    -- Marcar modo backpack para que el loop sepa que se intento
    StealGunSystem.gunInBackpackMode = true

    -- CAPTURAR POSICION SEGURA ANTES DEL FLING
    -- Se guarda aqui (antes de cualquier TP de agarre) para que el return
    -- siempre vuelva al lugar real donde estaba el jugador, no donde cayo la gun.
    local _sgSafePosBefore = nil
    do
        local _ry = myHRP.Position.Y
        if _ry > 2 and _ry < 800 then
            _sgSafePosBefore = myHRP.CFrame
        elseif _flingLastSafePos then
            local _sy = _flingLastSafePos.Position.Y
            if _sy > 2 and _sy < 800 then
                _sgSafePosBefore = _flingLastSafePos
            end
        end
        -- Actualizar OldPos con esta posicion para que _doStealFling tambien la use
        if _sgSafePosBefore then
            _G.OldPos = _sgSafePosBefore
            _flingLastSafePos = _sgSafePosBefore
        end
    end

    CreateCustomNotification("STEAL GUN", "Flingeando a " .. TargetPlayer.Name .. " para forzar drop...", 2.5)

    -- == FASE 1: FLING igual que Fling Murder ==
    -- Escuchar el drop de la gun ANTES de iniciar el fling (para no perdernos el evento)
    local _gunDropped = nil
    local _dropListener = workspace.DescendantAdded:Connect(function(obj)
        if not StealGunSystem.enabled then return end
        if not (obj:IsA("Tool") and _SG_DROP_NAMES[obj.Name]) then return end
        -- Ignorar si la gun sigue equipada por algun jugador
        local p = obj.Parent
        if p and p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return end
        _gunDropped = obj
    end)

    -- Ejecutar el sticky-force fling (misma funcion que Fling Murder)
    -- _doStealFling bloquea ~10s hasta que el target es lanzado o timeout
    pcall(_doStealFling, tHRP, true)  -- skipReturn=true, hacemos el return nosotros abajo

    -- Desconectar listener de drop
    pcall(function() _dropListener:Disconnect() end)

    -- == FASE 2: intentar agarrar la gun ==
    -- Primero verificar si ya la tenemos (el fling pudo haberla empujado a nuestro hitbox)
    local grabbed = _sgLocalHasGun()

    if not grabbed then
        -- Intentar agarrar la gun dropeada del suelo
        local function _grabObj(obj)
            if not obj or not obj.Parent then return false end
            -- Ignorar si ya fue recogida por alguien
            local p = obj.Parent
            if p and p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return false end
            local handle = obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart")
            if not handle then return false end
            -- FIX TP: mover el handle hacia el jugador (NO TP del jugador al handle)
            -- Antes hac?a myHRP.CFrame = handle.CFrame ? se teleportaba DENTRO del sheriff
            -- Ahora movemos la gun al jugador para agarrarla sin teleportarnos
            pcall(function() handle.CFrame = CFrame.new(myHRP.Position) end)
            pcall(function() obj:PivotTo(CFrame.new(myHRP.Position)) end)
            task.wait(0.016)
            pcall(function()
                firetouchinterest(myHRP, handle, 0)
                task.wait(0.03)
                firetouchinterest(myHRP, handle, 1)
            end)
            task.wait(0.08)
            -- Tambien todas las partes del cuerpo
            for _, part in ipairs(myChar:GetChildren()) do
                if part:IsA("BasePart") and part ~= myHRP then
                    pcall(function()
                        firetouchinterest(part, handle, 0)
                        task.wait(0.02)
                        firetouchinterest(part, handle, 1)
                    end)
                end
            end
            return _sgLocalHasGun()
        end

        -- Intentar con la gun detectada por el listener
        if _gunDropped then
            grabbed = _grabObj(_gunDropped)
        end

        -- Si no, escanear workspace completo (por si el drop ya estaba antes del listener)
        if not grabbed then
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("Tool") and _SG_DROP_NAMES[obj.Name] then
                    local p = obj.Parent
                    if not (p and p:IsA("Model") and p:FindFirstChildOfClass("Humanoid")) then
                        grabbed = _grabObj(obj)
                        if grabbed then break end
                    end
                end
                if _sgLocalHasGun() then grabbed = true; break end
            end
        end

        -- Esperar hasta 5s por un drop tardio (el server puede tardar en soltar la gun)
        if not grabbed then
            CreateCustomNotification("STEAL GUN", "Esperando drop de gun...", 2)
            local _waited = 0
            repeat
                task.wait(0.15)
                _waited = _waited + 0.15
                if _gunDropped and _gunDropped.Parent then
                    grabbed = _grabObj(_gunDropped)
                end
                if not grabbed then grabbed = _sgLocalHasGun() end
                -- Tambien re-escanear workspace cada 0.5s
                if not grabbed and _waited % 0.5 < 0.15 then
                    for _, obj in ipairs(workspace:GetDescendants()) do
                        if obj:IsA("Tool") and _SG_DROP_NAMES[obj.Name] then
                            local p = obj.Parent
                            if not (p and p:IsA("Model") and p:FindFirstChildOfClass("Humanoid")) then
                                grabbed = _grabObj(obj)
                                if grabbed then break end
                            end
                        end
                    end
                end
            until grabbed or _waited >= 5 or not StealGunSystem.enabled
        end
    end

    -- FASE 3: no hace falta TP de retorno extra.
    -- _doStealFling (ATOMIC GHOST FLING v5) ya restaura RootPart.CFrame
    -- a safePos al final de cada frame y al salir del loop.
    -- El jugador queda en su lugar original sin TPs adicionales.

    if grabbed then
        CreateCustomNotification("STEAL GUN", "Gun robada de " .. TargetPlayer.Name .. "!", 2.5)
        StealGunSystem.enabled = false
        if _G._qfStateRef then _G._qfStateRef.stealGunActive = false end; pcall(function() if _G._sgBindRef and _G._sgBindRef.frame then _G._sgBindRef.frame:SetActiveState(false) end end)
    else
        CreateCustomNotification("STEAL GUN", "No se pudo robar, esperando drop...", 2)
    end
end

-- OPT: helper compartido ? no se recrea en cada StealGunLoop
local function _sgHasGunIn(container)
    if not container then return false end
    for _, t in ipairs(container:GetChildren()) do
        if t:IsA("Tool") and _SG_GUN_NAMES[t.Name] then return true end
    end
    return false
end

local function _sgLocalHasGun()
    -- FIX v14: usar _findGunIn (que incluye keyword search) en vez de _sgHasGunIn
    -- que solo miraba _SG_GUN_NAMES y fallaba con SheriffRevolver, Revolver, etc.
    if _findGunIn then
        local char = LocalPlayer.Character
        local bp   = LocalPlayer:FindFirstChildOfClass("Backpack")
        return (_findGunIn(char) ~= nil) or (_findGunIn(bp) ~= nil)
    end
    -- fallback si _findGunIn todavia no esta definido
    return _sgHasGunIn(LocalPlayer.Character) or _sgHasGunIn(LocalPlayer.Backpack)
end

-- Encuentra al sheriff: primero por cache, si falla busca por gun en mano
function FindOriginalSheriff()
    if not StealGunSystem.enabled then return end
    -- Forzar refresh sin throttle
    _roleCache.lastUpdate = 0
    _refreshRoleCache()
    local cached = _roleCache and _roleCache.sheriff
    if cached and cached.Character then
        StealGunSystem.sheriffOriginalFound = cached
        return
    end
    -- Fallback: buscar visualmente quien tiene la gun (para cuando el cache aun no llego)
    if _findGunIn then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then
                local hasGun = _findGunIn(p.Character)
                if not hasGun then
                    local bp = p:FindFirstChildOfClass("Backpack")
                    hasGun = bp and _findGunIn(bp)
                end
                if hasGun then
                    StealGunSystem.sheriffOriginalFound = p
                    _roleCache.sheriff = p
                    return
                end
            end
        end
    end
end

-- Loop principal de StealGun: flingea al sheriff y espera la gun
function StealGunLoop()
    if not StealGunSystem.enabled then return end
    local _loopToken = StealGunSystem._roundToken

    -- FIX TP: arrancar tracker de posicion segura DESDE EL INICIO del loop
    -- para que _doStealFling siempre tenga un OldPos valido al hacer el return
    if _startFlingPosTracking then
        _startFlingPosTracking()
    end
    -- Capturar posicion inicial ahora mismo
    do
        local _mc = LocalPlayer.Character
        local _mh = _mc and _mc:FindFirstChild("HumanoidRootPart")
        if _mh then
            local ry = _mh.Position.Y
            if ry > 2 and ry < 800 then
                _flingLastSafePos = _mh.CFrame
                _G.OldPos  = _mh.CFrame
            end
        end
    end

    local _dropConn = nil

    local function _tryGrabDrop(obj)
        if not (obj:IsA("Tool") and _SG_DROP_NAMES[obj.Name]) then return end
        -- FIX: ignorar si la gun est? equipada por otro jugador (parent es Model con Humanoid)
        local objParent = obj.Parent
        if objParent and objParent:IsA("Model") and objParent:FindFirstChildOfClass("Humanoid") then return end
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not (myHRP and myHum and myHum.Health > 0) then return end
        local handle = obj:FindFirstChild("Handle") or obj:FindFirstChildWhichIsA("BasePart")
        if not handle then return end
        -- FIX: loop de reintentos (hasta 8 intentos) igual que _grabGunInvisible
        pcall(function() handle.CFrame = CFrame.new(myHRP.Position) end)
        pcall(function() obj:PivotTo(CFrame.new(myHRP.Position)) end)
        pcall(function()
            firetouchinterest(myHRP, handle, 0)
            task.wait(0.02)
            firetouchinterest(myHRP, handle, 1)
        end)
        task.wait(0.1)
        local tries = 0
        while not _sgLocalHasGun() and tries < 8 and handle and handle.Parent do
            tries = tries + 1
            task.wait(0.08)
            pcall(function() handle.CFrame = CFrame.new(myHRP.Position) end)
            pcall(function() obj:PivotTo(CFrame.new(myHRP.Position)) end)
            pcall(function()
                firetouchinterest(myHRP, handle, 0)
                task.wait(0.02)
                firetouchinterest(myHRP, handle, 1)
            end)
        end
        if _sgLocalHasGun() then
            CreateCustomNotification("STEAL GUN", "Gun agarrada del suelo!", 2)
            StealGunSystem.enabled = false
            -- FIX v14: resetear boton Quick Fling
            if _G._qfStateRef then _G._qfStateRef.stealGunActive = false end; pcall(function() if _G._sgBindRef and _G._sgBindRef.frame then _G._sgBindRef.frame:SetActiveState(false) end end)
            if _dropConn then pcall(function() _dropConn:Disconnect() end); _dropConn = nil end
        end
    end

    task.spawn(function()
        local _lastFlingTime   = 0    -- timestamp del ultimo fling lanzado
        local _lastFlingTarget = nil  -- jugador al que se flingeo por ultima vez
        local _flingCount      = 0    -- cuantas veces se flingeo al mismo target
        local _backpackModeStart = 0  -- FIX: variable declarada localmente (antes era global sin declarar)
        -- FIX: cooldown duro por UserId ? impide re-flingear al mismo jugador
        -- independientemente del estado de gunInBackpackMode
        local _flingCooldowns  = {}   -- { [userId] = timestamp }
        local FLING_COOLDOWN   = 6    -- segundos minimos entre flings al mismo sheriff

        while StealGunSystem.enabled and StealGunSystem._roundToken == _loopToken do
            if _sgLocalHasGun() then
                CreateCustomNotification("STEAL GUN", "Gun obtenida!", 2)
                StealGunSystem.enabled = false
                -- FIX v14: resetear boton Quick Fling
                if _G._qfStateRef then _G._qfStateRef.stealGunActive = false end; pcall(function() if _G._sgBindRef and _G._sgBindRef.frame then _G._sgBindRef.frame:SetActiveState(false) end end)
                break
            end

            -- Esperar a que el fling Y el return terminen antes de cualquier decision
            if _flingActive or _flingReturning then
                task.wait(0.2)
                continue
            end

            -- Refrescar cache en cada iteracion para detectar cambios de sheriff
            _refreshRoleCache()
            local target = _roleCache and _roleCache.sheriff
            -- FIX: si no hay sheriff en cache pero hay hero con la gun, promoverlo
            if not target and _roleCache and _roleCache.hero then
                local heroPlayer = _roleCache.hero
                local hHum = heroPlayer.Character and heroPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hHum and hHum.Health > 0 then
                    target = heroPlayer
                    _roleCache.sheriff = heroPlayer
                    _roleCache.hero    = nil
                end
            end
            StealGunSystem.sheriffOriginalFound = target

            if target and target.Character and target.Parent then
                local sHum = target.Character:FindFirstChildOfClass("Humanoid")
                local sHRP = target.Character:FindFirstChild("HumanoidRootPart")

                -- FIX: bloquear re-fling al mismo sheriff por FLING_COOLDOWN segundos
                -- Este guard cubre TODOS los branches (gunInBackpackMode o no)
                local _tuid = target.UserId
                local _lastT = _flingCooldowns[_tuid] or 0
                if tick() - _lastT < FLING_COOLDOWN then
                    -- Dentro del cooldown: solo escuchar drops, nunca re-flingear
                    if StealGunSystem.gunInBackpackMode then
                        if not _dropConn then
                            -- FIX: DescendantAdded en lugar de ChildAdded para capturar
                            -- guns dropeadas dentro de Models anidados en workspace
                            _dropConn = workspace.DescendantAdded:Connect(function(obj)
                                if StealGunSystem.enabled
                                and StealGunSystem._roundToken == _loopToken then
                                    task.spawn(function() _tryGrabDrop(obj) end)
                                else
                                    pcall(function() _dropConn:Disconnect() end)
                                    _dropConn = nil
                                end
                            end)
                            -- FIX: GetDescendants para buscar en toda la jerarqu?a de workspace
                            for _, obj in ipairs(workspace:GetDescendants()) do
                                _tryGrabDrop(obj)
                                if not StealGunSystem.enabled then break end
                            end
                        end
                    end
                    task.wait(0.3)
                    continue
                end

                if sHum and sHum.Health > 0 and sHRP then
                    -- Sheriff vivo y fuera de cooldown
                    if StealGunSystem.gunInBackpackMode then
                        -- Ya flingeamos pero el sheriff sobrevivio (cooldown expirado sin drop)
                        CreateCustomNotification("STEAL GUN", "Sheriff sobrevivio al fling, reintentando...", 2)
                        StealGunSystem.gunInBackpackMode = false
                        if _dropConn then
                            pcall(function() _dropConn:Disconnect() end)
                            _dropConn = nil
                        end
                    else
                        -- Lanzar fling ? registrar cooldown ANTES para que el loop no entre de nuevo
                        _flingCooldowns[_tuid] = tick()
                        _lastFlingTime = tick()
                        _lastFlingTarget = target
                        _flingCount = _flingCount + 1
                        pcall(_sgFlingPlayer, target)
                        -- Esperar a que el fling Y el TP de retorno terminen
                        local waited = 0
                        while (_flingActive or _flingReturning) and waited < 8 do
                            task.wait(0.1)
                            waited = waited + 0.1
                        end
                        -- Refrescar el cooldown al terminar para asegurar 6s desde que volvimos
                        _flingCooldowns[_tuid] = tick()
                    end
                else
                    -- Sheriff muerto o invalido: limpiar estado y buscar nuevo sheriff
                    CreateCustomNotification("STEAL GUN", target.Name .. " murio, buscando nuevo sheriff...", 3)
                    local deadUserId = target.UserId
                    -- Limpiar estado del sheriff muerto ? incluyendo cualquier referencia
                    -- al jugador muerto que pudiera haber quedado en hero
                    _roleCache.sheriff    = nil
                    if _roleCache.hero and _roleCache.hero.UserId == deadUserId then
                        _roleCache.hero = nil
                    end
                    _roleCache.lastUpdate = 0  -- forzar refresh inmediato en siguiente llamada
                    StealGunSystem.sheriffOriginalFound = nil
                    StealGunSystem.sheriffDeadDetected  = false
                    StealGunSystem.gunInBackpackMode    = false
                    StealGunSystem.roleCheckDisabled    = false
                    _backpackModeStart = 0
                    _lastFlingTarget = nil
                    _flingCount = 0
                    -- Limpiar flingCooldown del muerto para no bloquear al nuevo
                    _flingCooldowns[deadUserId] = nil
                    -- Limpiar dropConn del sheriff anterior
                    if _dropConn then
                        pcall(function() _dropConn:Disconnect() end)
                        _dropConn = nil
                    end

                    -- Esperar hasta que aparezca un nuevo sheriff vivo
                    -- Bypassear throttle del cache para detectar al nuevo lo antes posible
                    local waited = 0
                    repeat
                        task.wait(0.3)
                        waited = waited + 0.3

                        -- Forzar refresh inmediato sin throttle
                        _roleCache.lastUpdate = 0
                        _refreshRoleCache()

                        -- Limpiar cualquier referencia residual al sheriff muerto
                        if _roleCache.sheriff and _roleCache.sheriff.UserId == deadUserId then
                            _roleCache.sheriff = nil
                        end
                        if _roleCache.hero and _roleCache.hero.UserId == deadUserId then
                            _roleCache.hero = nil
                        end

                        local newSheriff = _roleCache.sheriff

                        -- Prioridad: hero (quien recogi? la gun del sheriff muerto).
                        -- FIX: limpiar _roleCache.hero una vez que lo promovemos a sheriff,
                        -- para que el loop principal no siga evaluando la rama equivocada.
                        if (not newSheriff or newSheriff.UserId == deadUserId) and _roleCache.hero then
                            local heroPlayer = _roleCache.hero
                            local hHum = heroPlayer.Character and heroPlayer.Character:FindFirstChildOfClass("Humanoid")
                            if hHum and hHum.Health > 0 and heroPlayer.UserId ~= deadUserId then
                                newSheriff = heroPlayer
                                _roleCache.sheriff = heroPlayer  -- promover hero a sheriff
                                _roleCache.hero    = nil         -- limpiar rol hero para evitar confusion
                            end
                        end

                        -- Fallback visual: buscar manualmente quien tiene la gun en mano
                        if (not newSheriff or newSheriff.UserId == deadUserId) and _findGunIn then
                            for _, p in ipairs(Players:GetPlayers()) do
                                if p ~= LocalPlayer and p.UserId ~= deadUserId and p.Character then
                                    local hasGun = _findGunIn(p.Character)
                                    if not hasGun then
                                        local bp = p:FindFirstChildOfClass("Backpack")
                                        hasGun = bp and _findGunIn(bp)
                                    end
                                    if hasGun then
                                        newSheriff = p
                                        _roleCache.sheriff    = p
                                        _roleCache.hero       = nil  -- limpiar hero si era este jugador
                                        _roleCache.lastUpdate = 0
                                        break
                                    end
                                end
                            end
                        end

                        if newSheriff and newSheriff.UserId ~= deadUserId
                        and newSheriff.Character
                        and newSheriff.Character:FindFirstChildOfClass("Humanoid")
                        and newSheriff.Character:FindFirstChildOfClass("Humanoid").Health > 0 then
                            StealGunSystem.sheriffOriginalFound = newSheriff
                            StealGunSystem.sheriffDeadDetected  = false
                            StealGunSystem.gunInBackpackMode    = false
                            -- Re-hookear muerte del nuevo sheriff
                            task.defer(function() pcall(_hookSheriffDeath, newSheriff) end)
                            CreateCustomNotification("STEAL GUN", "Nuevo portador: " .. newSheriff.Name .. " flingeando!", 2.5)
                            -- Flingear inmediatamente sin esperar la proxima iteracion del loop
                            _flingActive    = false
                            _flingReturning = false
                            task.spawn(function()
                                pcall(_sgFlingPlayer, newSheriff)
                                if StealGunSystem._roundToken == _loopToken then
                                    _flingCooldowns[newSheriff.UserId] = tick()
                                end
                            end)
                            break
                        elseif newSheriff and newSheriff.UserId == deadUserId then
                            _roleCache.sheriff = nil
                        end
                    until not StealGunSystem.enabled
                        or StealGunSystem._roundToken ~= _loopToken
                        or waited > 25
                        or _sgLocalHasGun()

                    if _sgLocalHasGun() then
                        CreateCustomNotification("STEAL GUN", "Gun obtenida!", 2)
                        StealGunSystem.enabled = false
                        break
                    end
                    if waited > 25 then
                        CreateCustomNotification("STEAL GUN", "Sin nuevo sheriff en 25s. Parando.", 3)
                        StealGunSystem.enabled = false
                        break
                    end
                end
            else
                -- Sin sheriff en cache aun: seguir esperando
                -- FIX: limpiar estado si el sheriff desapareci? del cache inesperadamente
                if StealGunSystem.gunInBackpackMode then
                    StealGunSystem.gunInBackpackMode = false
                    _backpackModeStart = 0
                    if _dropConn then
                        pcall(function() _dropConn:Disconnect() end)
                        _dropConn = nil
                    end
                end
                task.wait(0.5)
            end

            task.wait(0.8)
        end
        if _dropConn then pcall(function() _dropConn:Disconnect() end); _dropConn = nil end
    end)
end

function EnableStealGun()
    if StealGunSystem.enabled then return end
    StealGunSystem.enabled = true
    StealGunSystem.sheriffDeadDetected = false
    StealGunSystem.gunInBackpackMode   = false
    StealGunSystem.roleCheckDisabled   = false
    FindOriginalSheriff()
    StealGunLoop()
end

function DisableStealGun()
    if not StealGunSystem.enabled then return end
    StealGunSystem.enabled = false
    StealGunSystem.sheriffOriginalFound = nil
    StealGunSystem.sheriffDeadDetected  = false
    StealGunSystem.gunInBackpackMode    = false
    StealGunSystem.roleCheckDisabled    = false
end

function CanFlingTarget(target)
    if not target or not target.Character then return false end
    
    -- Verificar que este vivo
    local hum = target.Character:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    
    -- Si es el sheriff muerto bloqueado, NO
    if SheriffDeadBlock.isDeadSheriffID and target.UserId == SheriffDeadBlock.isDeadSheriffID then
        return false
    end
    
    return true
end








