    -- ==================================================================
    -- ==================================================================
    -- BREAK TRADE -- Boton clickeable: dispara el glitch una vez
    -- Tecnica: AcceptTrade + CancelAccept en el mismo frame a 0.01s
    -- durante 1 segundo (100 disparos), luego para solo.
    -- ==================================================================
    CreateSection(leftColumn, "", "BREAK TRADE", ThemeColors.Primary)

    if not Settings.premium then Settings.premium = {} end
    if not Settings.premium.breakTrade then
        Settings.premium.breakTrade = { running = false }
    end

    -- BOTON: Glitch Cooldown (un click -> corre 1s y para solo)
    CreateButton(leftColumn, "Glitch Cooldown (Bucle de Desincronizacion)", ThemeColors.Primary, function()
        if Settings.premium.breakTrade.running then
            CreateCustomNotification("BREAK TRADE", "Ya esta corriendo...", 2)
            return
        end
        Settings.premium.breakTrade.running = true
        CreateCustomNotification("BREAK TRADE", "Glitch activo -- desincronizando servidor...", 2)
        task.spawn(function()
            -- Dispara AcceptTrade + CancelAccept a 0.01s durante 1 segundo
            -- (~100 disparos) para romper la logica del cooldown del servidor
            local _endTime = tick() + 1
            while tick() < _endTime do
                pcall(function()
                    local Trade = ReplicatedStorage:FindFirstChild("Trade")
                    if Trade then
                        local acceptRemote = Trade:FindFirstChild("AcceptTrade")
                        local cancelRemote = Trade:FindFirstChild("CancelAccept")
                        if acceptRemote then acceptRemote:FireServer(game.PlaceId * 3) end
                        if cancelRemote then cancelRemote:FireServer() end
                    end
                end)
                task.wait(0.016)
            end
            Settings.premium.breakTrade.running = false
            CreateCustomNotification("BREAK TRADE", "Glitch completado", 2)
        end)
    end)

    -- ==================================================================
    -- TRADE TOOLS -- Loop Reset Automatico
    -- Al activar: hookea UpdateTrade.OnClientEvent (se dispara cada vez
    -- que el servidor manda un update del trade) y resetea el cooldown
    -- automaticamente sin que el usuario haga nada.
    -- Tambien corre en Heartbeat cada 0.3s como respaldo.
    -- ==================================================================
    if not Settings.premium.tradeCooldown then
        Settings.premium.tradeCooldown = {
            loopEnabled   = false,
            cooldownValue = 6,
            _heartConn    = nil,
            _hookConn     = nil,
        }
    end

    CreateSection(leftColumn, "", "TRADE TOOLS", ThemeColors.Aurora2)

    -- Helper: dispara el reset del cooldown via AcceptTrade + CancelAccept
    local function _tcFireReset()
        pcall(function()
            local Trade = ReplicatedStorage:FindFirstChild("Trade")
            if not Trade then return end
            local Key = game.PlaceId * 3
            local acceptRemote = Trade:FindFirstChild("AcceptTrade")
            local cancelRemote = Trade:FindFirstChild("CancelAccept")
            if acceptRemote then acceptRemote:FireServer(Key) end
            if cancelRemote then cancelRemote:FireServer() end
        end)
    end

    -- Helper: desconectar todo
    local function _tcStopAll()
        Settings.premium.tradeCooldown.loopEnabled = false
        if Settings.premium.tradeCooldown._heartConn then
            Settings.premium.tradeCooldown._heartConn:Disconnect()
            Settings.premium.tradeCooldown._heartConn = nil
        end
        if Settings.premium.tradeCooldown._hookConn then
            Settings.premium.tradeCooldown._hookConn:Disconnect()
            Settings.premium.tradeCooldown._hookConn = nil
        end
    end

    -- Toggle: Loop Reset Trade Cooldown (AUTOMATICO)
    CreateAuroraToggle(leftColumn, "Loop Reset Trade Cooldown", function(on)
        _tcStopAll()
        Settings.premium.tradeCooldown.loopEnabled = on

        if on then
            -- Hook 1: UpdateTrade.OnClientEvent
            -- Cada vez que el servidor manda un update del trade (alguien agrega/quita
            -- un item), el TradeModule llama ResetCooldown(false) -> reinicia a 6s.
            -- Interceptamos ese evento y disparamos el reset antes de que cuente.
            pcall(function()
                local tradeFolder = ReplicatedStorage:FindFirstChild("Trade")
                if tradeFolder then
                    local updateEv = tradeFolder:FindFirstChild("UpdateTrade")
                    if updateEv then
                        Settings.premium.tradeCooldown._hookConn = updateEv.OnClientEvent:Connect(function()
                            if Settings.premium.tradeCooldown.loopEnabled then
                                task.defer(_tcFireReset)
                            end
                        end)
                    end
                end
            end)

            -- Hook 2: Heartbeat cada ~0.3s como respaldo continuo
            local _hbTick = 0
            Settings.premium.tradeCooldown._heartConn = RunService.Heartbeat:Connect(function()
                if not Settings.premium.tradeCooldown.loopEnabled then return end
                _hbTick = _hbTick + 1
                if _hbTick < 18 then return end
                _hbTick = 0
                _tcFireReset()
            end)

            CreateCustomNotification("TRADE COOLDOWN", "Loop automatico activo -- se resetea solo", 3)
        else
            CreateCustomNotification("TRADE COOLDOWN", "Loop desactivado", 2)
        end
    end, false)

    -- Slider: Ajustar Tiempo de Reset (1-20 segundos)
    CreateSlider(leftColumn, "Ajustar Tiempo de Reset (seg)", 1, 20, Settings.premium.tradeCooldown.cooldownValue, function(v)
        Settings.premium.tradeCooldown.cooldownValue = v
    end)

    -- Boton: Reset Trade Cooldown (un solo disparo + para el loop)
    CreateButton(leftColumn, "Reset Trade Cooldown", ThemeColors.Aurora2, function()
        local ok = false
        pcall(function()
            local Trade = ReplicatedStorage:FindFirstChild("Trade")
            if Trade then
                local Key = game.PlaceId * 3
                local acceptRemote = Trade:FindFirstChild("AcceptTrade")
                local cancelRemote = Trade:FindFirstChild("CancelAccept")
                if acceptRemote then acceptRemote:FireServer(Key); ok = true end
                if cancelRemote then cancelRemote:FireServer(); ok = true end
            end
        end)
        Settings.premium.tradeCooldown.loopEnabled = false
        if ok then
            CreateCustomNotification("TRADE COOLDOWN", "Reset ejecutado y loop detenido", 3)
        else
            CreateCustomNotification("TRADE COOLDOWN", "Trade remote no encontrado", 2)
        end
    end)

 CreateSection(leftColumn, "", "SPEED GLITCH", ThemeColors.Aurora2)
    if not Settings.premium.speedGlitch then
        Settings.premium.speedGlitch = { enabled = false, multiplier = 3, originalSpeed = 16 }
    end

    local _sgConn       = nil  -- OPT: local
    local _sgWasJumping = false

    local function _sgStop()  -- OPT: local
        Settings.premium.speedGlitch.enabled = false
        if _sgConn then _sgConn:Disconnect(); _sgConn = nil end
        local char = LocalPlayer.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = 16 end
        end
    end

    -- _sgStart: inicia el Heartbeat loop del speed glitch.
    -- Extraida del callback del toggle para que el boton bindable
    -- tambien pueda arrancar el loop (antes solo seteaba el flag sin crear _sgConn).
    local function _sgStart()
        if _sgConn then _sgConn:Disconnect(); _sgConn = nil end
        Settings.premium.speedGlitch.enabled = true

        local char0 = LocalPlayer.Character
        if char0 then
            local hum0 = char0:FindFirstChildOfClass("Humanoid")
            if hum0 then Settings.premium.speedGlitch.originalSpeed = hum0.WalkSpeed end
        end

        -- MOBILE: detectar tap en boton de salto nativo de Roblox
        if UserInputService.TouchEnabled then
            local function _findJumpBtn(parent, depth)
                if not parent or depth > 8 then return nil end
                for _, c in ipairs(parent:GetChildren()) do
                    if (c.Name == "JumpButton" or c.Name == "Jump" or c.Name == "JumpBtn")
                        and (c:IsA("TextButton") or c:IsA("ImageButton") or c:IsA("GuiButton")) then
                        return c
                    end
                    local found = _findJumpBtn(c, depth + 1)
                    if found then return found end
                end
                return nil
            end
            task.spawn(function()
                local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
                    or LocalPlayer:WaitForChild("PlayerGui", 10)
                if not pg then return end
                local jBtn = _findJumpBtn(pg, 0)
                if jBtn then
                    jBtn.Activated:Connect(function()
                        if not Settings.premium.speedGlitch.enabled then return end
                        local char = LocalPlayer.Character
                        local hum  = char and char:FindFirstChildOfClass("Humanoid")
                        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                        if not hum or not hrp then return end
                        -- Forzar salto si no esta en el aire
                        if hum.FloorMaterial ~= Enum.Material.Air then
                            hum.Jump = true
                        end
                    end)
                end
            end)
        end

        local _hbTsgConn = 0  -- OPT: local
        local _isTouchDevice = UserInputService.TouchEnabled
        _sgConn = RunService.Heartbeat:Connect(function()
            _hbTsgConn=_hbTsgConn+1; if _hbTsgConn<2 then return end; _hbTsgConn=0
            if not Settings.premium.speedGlitch.enabled then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end

            local inAir = hum.FloorMaterial == Enum.Material.Air
            local baseSpeed = Settings.premium.speedGlitch.originalSpeed
            local mult      = Settings.premium.speedGlitch.multiplier

            if hum.WalkSpeed ~= baseSpeed then
                hum.WalkSpeed = baseSpeed
            end

            -- MoveDirection funciona en mobile (joystick) Y PC (teclado)
            local moveDir = hum.MoveDirection
            local moving  = moveDir.Magnitude > 0.1

            -- Fallback de teclado para PC si MoveDirection falla
            if not moving and not _isTouchDevice then
                local holdW = UserInputService:IsKeyDown(Enum.KeyCode.W)
                local holdA = UserInputService:IsKeyDown(Enum.KeyCode.A)
                local holdS = UserInputService:IsKeyDown(Enum.KeyCode.S)
                local holdD = UserInputService:IsKeyDown(Enum.KeyCode.D)
                if holdW or holdA or holdS or holdD then
                    moving = true
                    local cam = _Camera
                    local dir = Vector3.zero
                    if holdW then dir = dir + Vector3.new(cam.CFrame.LookVector.X,  0, cam.CFrame.LookVector.Z) end
                    if holdS then dir = dir - Vector3.new(cam.CFrame.LookVector.X,  0, cam.CFrame.LookVector.Z) end
                    if holdA then dir = dir - Vector3.new(cam.CFrame.RightVector.X, 0, cam.CFrame.RightVector.Z) end
                    if holdD then dir = dir + Vector3.new(cam.CFrame.RightVector.X, 0, cam.CFrame.RightVector.Z) end
                    if dir.Magnitude > 0 then moveDir = dir.Unit end
                end
            end

            if inAir and moving then
                local dir = Vector3.new(moveDir.X, 0, moveDir.Z)
                if dir.Magnitude > 0.01 then
                    dir = dir.Unit
                    local boosted = baseSpeed * mult
                    hrp.AssemblyLinearVelocity = Vector3.new(
                        dir.X * boosted,
                        hrp.AssemblyLinearVelocity.Y,
                        dir.Z * boosted
                    )
                end
                _sgWasJumping = true
            elseif not inAir and _sgWasJumping then
                _sgWasJumping = false
                hrp.AssemblyLinearVelocity = Vector3.new(0, hrp.AssemblyLinearVelocity.Y, 0)
            elseif not inAir then
                _sgWasJumping = false
            end
        end)
    end

 CreateToggle(leftColumn, "Enable Speed Glitch", function(enabled)
        if not enabled then
            _sgStop()
 CreateCustomNotification("SPEED GLITCH", "Desactivado -- velocidad normal restaurada", 2)
            return
        end
        _sgStart()
 CreateCustomNotification("SPEED GLITCH", "Activado -- saltar + joystick para boost de velocidad", 3)
    end, Settings.premium.speedGlitch.enabled)

 CreateSlider(leftColumn, "Speed Multiplier (Salto+W)", 2, 20, Settings.premium.speedGlitch.multiplier, function(value)
        Settings.premium.speedGlitch.multiplier = value
    end)

    -- BINDABLE: boton flotante para activar/desactivar Speed Glitch desde pantalla (pestana USE)
    do
        local _sgBindGui = CoreGui:FindFirstChild("SpeedGlitchBind_HUB")
        local function _destroySGBind()
            local function sweep(p)
                if not p then return end
                for _, g in ipairs(p:GetChildren()) do
                    if g.Name == "SpeedGlitchBind_HUB" then pcall(function() g:Destroy() end) end
                end
            end
            sweep(CoreGui)
            pcall(function() sweep(LocalPlayer:FindFirstChild("PlayerGui")) end)
            _sgBindGui = nil
            DestroyCapyBind("SPEED")
        end
        local function _createSGBind()
            _destroySGBind()
            local sg = Instance.new("ScreenGui")
            sg.Name = "SpeedGlitchBind_HUB"; sg.ResetOnSpawn = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
            pcall(function() sg.Parent = CoreGui end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _sgBindGui = sg
            MakeCapyBindableFrame(sg, "SPEED", function()
                local newState = not Settings.premium.speedGlitch.enabled
                if newState then
                    _sgStart()
                else
                    _sgStop()
                end
            end, 200, 200)
        end
        CreateToggle(leftColumn, "Show Bindable Button (Speed Glitch)", function(on)
            if on then _createSGBind() else _destroySGBind() end
        end, _sgBindGui ~= nil)
    end

    -- FAKE DIED
    CreateSection(rightColumn, "", "FAKE DIED", ThemeColors.Aurora2)
    do
        local _fdTrack   = nil
        local _fdMoveConn = nil

        local function _stopFdTrack()
            if _fdMoveConn then _fdMoveConn:Disconnect(); _fdMoveConn = nil end
            if _fdTrack then pcall(function() _fdTrack:Stop() end); _fdTrack = nil end
        end

        CreateToggle(rightColumn, "Fake Died", function(en)
            _stopFdTrack()
            if en then
                task.spawn(function()
                    local char = LocalPlayer.Character
                    if not char then return end
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if not hum then return end
                    local animator = hum:FindFirstChildOfClass("Animator")
                    if not animator then
                        animator = Instance.new("Animator", hum)
                    end
                    local anim = Instance.new("Animation")
                    anim.AnimationId = "rbxassetid://84112287597268"
                    local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
                    if ok and track then
                        _fdTrack = track
                        track.Priority = Enum.AnimationPriority.Action4
                        track:Play()
                        -- OPT: throttle 5 frames y Magnitude^2 evita sqrt
                        local _hbFd = 0
                        _fdMoveConn = RunService.Heartbeat:Connect(function()
                            _hbFd = _hbFd + 1; if _hbFd < 5 then return end; _hbFd = 0
                            local hrp = char:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                local vel = hrp.AssemblyLinearVelocity
                                if vel and vel.X*vel.X + vel.Z*vel.Z > 2.25 then  -- OPT: 1.5^2, sin sqrt
                                    _stopFdTrack()
                                end
                            end
                        end)
                        CreateCustomNotification("FAKE DIED", "Animacion reproduciendo", 3)
                    else
                        CreateCustomNotification("FAKE DIED", "Error al cargar animacion", 2)
                    end
                end)
            else
                CreateCustomNotification("FAKE DIED", "Desactivado", 2)
            end
        end, false)

        -- -- Toggle manual: Fake Died Bindable (sincronizado con el toggle de arriba) --
        -- El bindable NO se crea automaticamente al entrar a la pestana.
        -- Solo aparece cuando el usuario activa este toggle.
        local _fdBindGui = nil
        _G._fdBind = _G._fdBind or { enabled = false, gui = nil }

        -- Limpiar cualquier bindable huerfano de sesiones anteriores
        DestroyCapyBind("FAKE DIED")
        if _G._fdBind.gui then
            pcall(function() _G._fdBind.gui:Destroy() end)
            _G._fdBind.gui = nil
        end

        -- Funcion compartida de animacion (usada por el toggle principal y el bindable)
        local function _playFakeDied()
            if _fdTrack then pcall(function() _fdTrack:Stop() end); _fdTrack = nil end
            task.spawn(function()
                local char = LocalPlayer.Character
                if not char then return end
                local hum = char:FindFirstChildOfClass("Humanoid")
                if not hum then return end
                local animator = hum:FindFirstChildOfClass("Animator")
                if not animator then animator = Instance.new("Animator", hum) end
                local anim = Instance.new("Animation")
                anim.AnimationId = "rbxassetid://84112287597268"
                local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
                if ok and track then
                    _fdTrack = track
                    track.Priority = Enum.AnimationPriority.Action4
                    track:Play()
                    CreateCustomNotification("FAKE DIED", "Animacion reproduciendo", 3)
                else
                    CreateCustomNotification("FAKE DIED", "Error al cargar animacion", 2)
                end
            end)
        end

        local function _stopFakeDied()
            if _fdTrack then pcall(function() _fdTrack:Stop() end); _fdTrack = nil end
            CreateCustomNotification("FAKE DIED", "Desactivado", 2)
        end

        CreateAuroraToggle(rightColumn, "Fake Died Bindable", function(on)
            _G._fdBind.enabled = on
            -- Destruir bindable anterior siempre
            DestroyCapyBind("FAKE DIED")
            if _G._fdBind.gui then
                pcall(function() _G._fdBind.gui:Destroy() end)
                _G._fdBind.gui = nil
            end
            if on then
                local sg = Instance.new("ScreenGui")
                sg.Name = "FakeDiedBindSg"
                sg.ResetOnSpawn = false
                sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                sg.IgnoreGuiInset = true
                sg.DisplayOrder = 9900
                pcall(function() sg.Parent = CoreGui end)
                if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
                _G._fdBind.gui = sg
                _fdBindGui = sg

                -- El boton del bindable activa/desactiva sincronizado con _fdTrack
                MakeCapyBindableFrame(sg, "FAKE DIED", function()
                    if _fdTrack and _fdTrack.IsPlaying then
                        _stopFakeDied()
                    else
                        _playFakeDied()
                    end
                end, 200, 200)

                CreateCustomNotification("FAKE DIED", "Bindable ON -- boton flotante activo", 2)
            else
                CreateCustomNotification("FAKE DIED", "Bindable OFF", 2)
            end
        end, _G._fdBind.enabled)
    end



