        local function _scGetSkin()
            local list = (_skinState.mode == "gun") and _SC_GUN_SKINS or _SC_KNIFE_SKINS
            return list[_skinState.skinIdx] or list[1]
        end

        -- Deteccion de arma real usando logica del hub (Shoot remote = gun, Slash/Stab = knife)
        local function _scEsGun(tool)
            if not tool or not tool:IsA("Tool") then return false end
            if tool:FindFirstChild("Shoot", true)     then return true end
            if tool:FindFirstChild("GunClient", true) then return true end
            local n = tool.Name:lower()
            return n == "gun" or n:find("gun") or n:find("sheriff") or n:find("revolver")
        end
        local function _scEsKnife(tool)
            if not tool or not tool:IsA("Tool") then return false end
            if tool:FindFirstChild("Slash", true) then return true end
            if tool:FindFirstChild("Stab",  true) then return true end
            local n = tool.Name:lower()
            return n == "knife" or n:find("knife")
        end

        local function _scResetAll()
            for tool, data in pairs(_skinState.origData) do
                if tool and tool.Parent then
                    pcall(function() tool.Grip = data.Grip end)
                    for obj, eData in pairs(data.Elements) do
                        if obj and obj.Parent then
                            pcall(function()
                                if obj:IsA("SpecialMesh") then
                                    obj.MeshId    = eData.Mesh
                                    obj.TextureId = eData.Texture
                                    obj.Scale     = eData.Scale
                                elseif obj:IsA("MeshPart") then
                                    -- Restaurar MeshId y TextureID originales
                                    if eData.Mesh then
                                        obj.MeshId = eData.Mesh
                                    end
                                    obj.TextureID = eData.Texture
                                    -- Destruir cualquier SpecialMesh inyectado que cause invisibilidad
                                    local _sm = obj:FindFirstChildOfClass("SpecialMesh")
                                    if _sm then pcall(function() _sm:Destroy() end) end
                                end
                            end)
                        end
                    end
                end
            end
            table.clear(_skinState.origData)
            -- FIX MOBILE v2: desconectar listeners de Equipped al resetear
            if _skinState._equippedConns then
                for _, conn in pairs(_skinState._equippedConns) do
                    pcall(function() conn:Disconnect() end)
                end
                _skinState._equippedConns = {}
            end
        end

        -- LOGICA DIRECTA SOBRE EL HANDLE (como el Rayfield skin changer)
        -- Aplica para TODOS los tipos de knife sin importar si el Handle es MeshPart o BasePart:
        --   1. Handle MeshPart  -> escribir MeshId y TextureID directamente (executor lo permite)
        --                          NUNCA inyectar SpecialMesh: un SM dentro de MeshPart vuelve
        --                          el part completamente invisible en Roblox.
        --   2. Handle BasePart con SpecialMesh hijo  -> pisar MeshId/TextureId/Scale del SM
        --   3. Handle BasePart sin SpecialMesh (legacy)  -> pisar MeshId/TextureID directo
        local function _applyToAnyHandle(handle, skin, tool)
            if not handle or not skin then return end
            -- Forzar visibilidad siempre para evitar que sistemas externos dejen el knife invisible
            pcall(function() handle.Transparency = 0; handle.LocalTransparencyModifier = 0 end)
            if handle:IsA("MeshPart") then
                -- MeshPart: si la skin tiene scale, crear un FakePart con SpecialMesh encima
                -- ya que MeshPart.Size es de solo lectura en el cliente.
                if not _skinState.origData[tool].Elements[handle] then
                    _skinState.origData[tool].Elements[handle] = {
                        Mesh    = handle.MeshId,
                        Texture = handle.TextureID,
                    }
                end
                local _existingSM = handle:FindFirstChildOfClass("SpecialMesh")
                if _existingSM then pcall(function() _existingSM:Destroy() end) end
                -- Destruir FakePart previo si existe
                local _oldFake = handle:FindFirstChild("_SkinFakePart")
                if _oldFake then pcall(function() _oldFake:Destroy() end) end
                pcall(function()
                    handle.MeshId    = skin.meshId
                    handle.TextureID = skin.texId
                    handle.Transparency = 1  -- ocultar MeshPart original
                    -- Crear Part nueva con SpecialMesh para controlar scale libremente
                    local fakePart = Instance.new("Part")
                    fakePart.Name         = "_SkinFakePart"
                    fakePart.Anchored     = false
                    fakePart.CanCollide   = false
                    fakePart.Massless     = true
                    fakePart.Transparency = 0
                    fakePart.Size         = Vector3.new(0.1, 0.1, 0.1)
                    fakePart.Color        = handle.Color
                    fakePart.Material     = Enum.Material.SmoothPlastic
                    fakePart.CastShadow   = false
                    local sm = Instance.new("SpecialMesh", fakePart)
                    sm.MeshType  = Enum.MeshType.FileMesh
                    sm.MeshId    = skin.meshId
                    sm.TextureId = skin.texId
                    sm.Scale     = skin.scale or Vector3.new(0.056, 0.056, 0.056)
                    fakePart.Parent = handle
                    -- Soldar el FakePart al handle para que se mueva junto
                    -- FIX ADELANTADO: si la skin define weldOffset, usarlo para
                    -- alinear el mesh al pu?o (evita que katanas largas aparezcan adelantadas)
                    local weld = Instance.new("Weld", fakePart)
                    weld.Part0 = handle
                    weld.Part1 = fakePart
                    weld.C0    = skin.weldOffset or CFrame.new()
                    weld.C1    = CFrame.new()
                    -- Guardar referencia para limpiar al restaurar
                    _skinState.origData[tool].Elements[handle].FakePart = fakePart
                end)
            else
                -- BasePart: primero buscar SpecialMesh hijo
                local specialMesh = handle:FindFirstChildOfClass("SpecialMesh")
                if specialMesh then
                    if not _skinState.origData[tool].Elements[specialMesh] then
                        _skinState.origData[tool].Elements[specialMesh] = {
                            Mesh    = specialMesh.MeshId,
                            Texture = specialMesh.TextureId,
                            Scale   = specialMesh.Scale,
                        }
                    end
                    pcall(function()
                        specialMesh.MeshId    = skin.meshId
                        specialMesh.TextureId = skin.texId
                        specialMesh.Scale     = skin.scale
                    end)
                else
                    -- Fallback legacy: Handle con MeshId directo
                    if not _skinState.origData[tool].Elements[handle] then
                        _skinState.origData[tool].Elements[handle] = {
                            Mesh    = handle.MeshId,
                            Texture = handle.TextureID,
                        }
                    end
                    pcall(function()
                        handle.MeshId    = skin.meshId
                        handle.TextureID = skin.texId
                    end)
                end
            end
        end

        -- Helper: aplicar skin a todos los handles de un Tool o Model
        local function _applyToClone(container, skin)
            if not container or not skin then return end
            -- El DK_Clone ES el handle clonado directamente (no un Tool con Handle hijo)
            -- Tratar el container como el handle mismo
            local function _applyMeshToObj(obj)
                -- Forzar visibilidad siempre en cualquier BasePart
                if obj:IsA("BasePart") then
                    pcall(function() obj.Transparency = 0; obj.LocalTransparencyModifier = 0 end)
                end
                if obj:IsA("MeshPart") or (obj:IsA("BasePart") and skin.specialMesh) then
                    -- FIX: MeshPart en clone -> usar FakePart con SpecialMesh para controlar scale.
                    local _smOld = obj:FindFirstChildOfClass("SpecialMesh")
                    if _smOld then pcall(function() _smOld:Destroy() end) end
                    local _fakeOld = obj:FindFirstChild("_SkinFakePart")
                    if _fakeOld then pcall(function() _fakeOld:Destroy() end) end
                    pcall(function()
                        obj.MeshId      = skin.meshId
                        obj.TextureID   = skin.texId
                        obj.Transparency = 1
                        local fakePart = Instance.new("Part")
                        fakePart.Name         = "_SkinFakePart"
                        fakePart.Anchored     = false
                        fakePart.CanCollide   = false
                        fakePart.Massless     = true
                        fakePart.Transparency = 0
                        fakePart.Size         = Vector3.new(0.1, 0.1, 0.1)
                        fakePart.CastShadow   = false
                        local sm = Instance.new("SpecialMesh", fakePart)
                        sm.MeshType  = Enum.MeshType.FileMesh
                        sm.MeshId    = skin.meshId
                        sm.TextureId = skin.texId
                        sm.Scale     = skin.scale or Vector3.new(0.056, 0.056, 0.056)
                        fakePart.Parent = obj
                        local weld = Instance.new("Weld", fakePart)
                        weld.Part0 = obj
                        weld.Part1 = fakePart
                        -- FIX ADELANTADO: respetar weldOffset de la skin (ej. Purple Katana)
                        weld.C0    = skin.weldOffset or CFrame.new()
                        weld.C1    = CFrame.new()
                    end)
                elseif obj:IsA("SpecialMesh") then
                    -- SM propio del BasePart (no inyectado): actualizar normalmente
                    pcall(function()
                        obj.MeshId    = skin.meshId
                        obj.TextureId = skin.texId
                        obj.Scale     = skin.scale
                    end)
                end
            end
            -- Aplicar al container mismo (es el handle clonado)
            _applyMeshToObj(container)
            -- Y a todos sus descendants
            for _, obj in pairs(container:GetDescendants()) do
                _applyMeshToObj(obj)
            end
        end

        local function _scApplyInner(tool, skin)
            -- Guardar origData si es la primera vez
            if not _skinState.origData[tool] then
                _skinState.origData[tool] = { Grip = tool.Grip, Elements = {} }
            end

            -- GRIP: NO sobreescribir cuando Dual Knife esta activo.
            -- El DK usa el RightGrip real del tool para calcular el weld espejo;
            -- _KNIFE_GRIP_STD ya usa rotacion PARADO; no pisar el grip cuando Dual Knife esta activo.
            local _isDualKnifeActive = _G._dualKnifeEnabled == true
            if not _isDualKnifeActive then
                pcall(function() tool.Grip = skin.grip end)
            end

            -- Re-aplicar grip en Equipped (mobile puede pisarlo al animar)
            -- Solo cuando Dual Knife NO esta activo, por la misma razon.
            if not _skinState._equippedConns then _skinState._equippedConns = {} end
            if not _skinState._equippedConns[tool] then
                _skinState._equippedConns[tool] = tool.Equipped:Connect(function()
                    task.wait(0.016)
                    -- FIX BUG #1 PREMIUM GUN ORIENTATION:
                    -- Guard against BOTH Dual Knife AND Dual Gun being active.
                    -- When Dual Gun is active the MirrorWeld copies grip.C0/C1 from the
                    -- live RightGrip. The delayed re-apply below would fire AFTER the weld
                    -- is created and stomp the orientation, making the clone face backward.
                    local _isDualActive = (_G._dualKnifeEnabled == true)
                        or (_G._dualGunState and _G._dualGunState.enabled == true)
                    if _skinState.enabled and _skinState._equippedConns[tool] then
                        if not _isDualActive then
                            pcall(function() tool.Grip = skin.grip end)
                            task.wait(0.1)
                            if not (_G._dualKnifeEnabled == true or (_G._dualGunState and _G._dualGunState.enabled)) then
                                pcall(function() tool.Grip = skin.grip end)
                            end
                            task.wait(0.3)
                            if _skinState.enabled
                                and not (_G._dualKnifeEnabled == true or (_G._dualGunState and _G._dualGunState.enabled)) then
                                pcall(function() tool.Grip = skin.grip end)
                            end
                        end
                    end
                end)
            end

            -- MESH + TEXTURE: aplicar directo sobre el Handle (logica Rayfield)
            local handle = tool:FindFirstChild("Handle")
            if handle then
                _applyToAnyHandle(handle, skin, tool)
            end

            -- Recorrer el resto de descendants por partes decorativas adicionales
            for _, obj in pairs(tool:GetDescendants()) do
                if obj.Name ~= "Handle" then
                    -- Forzar visibilidad en todos los BasePart del tool siempre
                    if obj:IsA("BasePart") then
                        pcall(function() obj.Transparency = 0; obj.LocalTransparencyModifier = 0 end)
                    end
                    if obj:IsA("SpecialMesh") then
                        -- SM propio de un BasePart: actualizar normalmente
                        if not _skinState.origData[tool].Elements[obj] then
                            _skinState.origData[tool].Elements[obj] = {
                                Mesh = obj.MeshId, Texture = obj.TextureId, Scale = obj.Scale
                            }
                        end
                        pcall(function()
                            obj.MeshId    = skin.meshId
                            obj.TextureId = skin.texId
                            obj.Scale     = skin.scale
                        end)
                    elseif obj:IsA("MeshPart") then
                        -- FIX INVISIBLE: escribir MeshId+TextureID directo en MeshPart.
                        -- Nunca inyectar SpecialMesh en MeshPart: lo vuelve invisible.
                        if not _skinState.origData[tool].Elements[obj] then
                            _skinState.origData[tool].Elements[obj] = {
                                Mesh    = obj.MeshId,
                                Texture = obj.TextureID,
                            }
                        end
                        -- Destruir SM inyectados previos si existen
                        local _existSM = obj:FindFirstChildOfClass("SpecialMesh")
                        if _existSM then pcall(function() _existSM:Destroy() end) end
                        pcall(function()
                            obj.MeshId    = skin.meshId
                            obj.TextureID = skin.texId
                        end)
                    end
                end
            end

            -- HOOK DK_Clone: sincronizar skin al clon dual activo (gun o knife)
            local _char2 = LocalPlayer.Character
            local _dkClone = _char2 and _char2:FindFirstChild("DK_Clone")
            if _dkClone then
                _applyToClone(_dkClone, skin)
            end
        end

        local function _scApply(tool, skin, bypass)
            if not tool or not skin then return end
            if not bypass then
                if _skinState.mode == "gun"   and not _scEsGun(tool)   then return end
                if _skinState.mode == "knife" and not _scEsKnife(tool) then return end
            end
            -- FIX MOBILE SKIN: si el tool no tiene SpecialMesh/MeshPart todavia
            -- (pasa en mobile donde los descendants llegan con delay),
            -- esperar hasta 2s a que aparezca al menos uno antes de aplicar.
            local _hasMesh = false
            for _, obj in pairs(tool:GetDescendants()) do
                if obj:IsA("SpecialMesh") or obj:IsA("MeshPart") then
                    _hasMesh = true; break
                end
            end
            if not _hasMesh then
                -- FIX MOBILE v3: timeout extendido a 4s y re-intento cada 0.1s
                task.spawn(function()
                    local _t = 0
                    repeat
                        task.wait(0.1); _t = _t + 0.1
                        for _, obj in pairs(tool:GetDescendants()) do
                            if obj:IsA("SpecialMesh") or obj:IsA("MeshPart") then
                                _hasMesh = true; break
                            end
                        end
                    until _hasMesh or _t >= 4 or not tool.Parent
                    if tool.Parent and _skinState.enabled then
                        _scApplyInner(tool, skin)
                        -- Re-aplicar 0.5s despues por si el grip se pisa en mobile
                        -- FIX BUG #1: guard against BOTH Dual Knife AND Dual Gun
                        task.delay(0.5, function()
                            local _dualActive = (_G._dualKnifeEnabled == true)
                                or (_G._dualGunState and _G._dualGunState.enabled == true)
                            if tool.Parent and _skinState.enabled and not _dualActive then
                                pcall(function() tool.Grip = skin.grip end)
                            end
                        end)
                    end
                end)
                return
            end
            _scApplyInner(tool, skin)
        end

        -- Oyente automatico
        -- FIX: en MM2 la Gun vive en workspace.NombreJugador.Gun (no como Tool hijo directo del char raiz)
        -- Se usa _findGun() que ya maneja la busqueda correcta, y se escucha ChildAdded en el char de workspace
        -- FIX MOBILE REBUILD: limpiar conexiones viejas siempre que el tab se reconstruya,
        -- para que el listener se vuelva a registrar correctamente (evita que el guard
        -- "if not _charConn" bloquee el re-registro tras destruir y recrear el tab Premium).
        do
            if _skinState._charConn then
                pcall(function() _skinState._charConn:Disconnect() end)
                _skinState._charConn = nil
            end
            if _skinState._wsConn then
                pcall(function() _skinState._wsConn:Disconnect() end)
                _skinState._wsConn = nil
            end
            if _skinState._charPickupConn then
                pcall(function() _skinState._charPickupConn:Disconnect() end)
                _skinState._charPickupConn = nil
            end

            -- FIX MOBILE: en celu la gun llega via DescendantAdded del workspace,
            -- no necesariamente como ChildAdded del char. Usamos DescendantAdded
            -- para capturar cualquier Tool que aparezca (gun en char o en workspace).
            local function _scTryApplyGun()
                if not _skinState.enabled then return end
                -- FIX: no aplicar skin de gun si el modo actual es knife
                if _skinState.mode ~= "gun" then return end
                task.wait(0.15)
                -- FIX MOBILE: buscar tambien en workspace[playerName] ademas de char/backpack
                local gun = _findGun and _findGun()
                if not gun then
                    local wsChar = workspace:FindFirstChild(LocalPlayer.Name)
                    if wsChar then gun = _findGunIn and _findGunIn(wsChar) end
                end
                if gun then _scApply(gun, _scGetSkin(), true) end
            end

            local function _scSetupListener(char)
                -- Listener en el char (PC y mobile - tool equipada directamente)
                if _skinState._charPickupConn then
                    pcall(function() _skinState._charPickupConn:Disconnect() end)
                end
                _skinState._charPickupConn = char.ChildAdded:Connect(function(child)
                    -- FIX: solo intentar aplicar skin de gun si el modo actual es gun
                    if child:IsA("Tool") and _skinState.mode == "gun" then
                        task.spawn(_scTryApplyGun)
                    end
                end)
                -- Listener en DescendantAdded del workspace (mobile / MM2 gun model)
                -- Solo re-aplicar si es una Tool que puede ser la gun.
                -- FIX: guardamos la conexion para poder limpiarla al reconstruir el tab.
                if _skinState._wsConn then
                    pcall(function() _skinState._wsConn:Disconnect() end)
                end
                _skinState._wsConn = workspace.DescendantAdded:Connect(function(obj)
                    if not _skinState.enabled then return end
                    -- FIX: no aplicar skin de gun si el modo es knife
                    if _skinState.mode ~= "gun" then return end
                    if obj:IsA("Tool") then
                        local n = obj.Name:lower()
                        if n:find("gun") or n == "gun" or n:find("sheriff") or n:find("revolver") then
                            task.spawn(_scTryApplyGun)
                        end
                    end
                end)
                -- Re-check extra con delay por si la gun tarda en cargarse en mobile
                -- FIX MOBILE v4: m?s delays cubre executors lentos (Delta, Arceus X)
                task.delay(0.5,  _scTryApplyGun)
                task.delay(1.2,  _scTryApplyGun)
                task.delay(2.5,  _scTryApplyGun)
                task.delay(4.0,  _scTryApplyGun)
            end

            local _scChar = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
            _scSetupListener(_scChar)
            _skinState._charConn = LocalPlayer.CharacterAdded:Connect(function(newChar)
                -- Re-aplicar al respawnear (importante en mobile donde el char se recarga lento)
                _skinState.origData = {}  -- limpiar origData del char anterior
                -- FIX MOBILE v2: limpiar Equipped listeners del char anterior
                if _skinState._equippedConns then
                    for _, conn in pairs(_skinState._equippedConns) do
                        pcall(function() conn:Disconnect() end)
                    end
                    _skinState._equippedConns = {}
                end
                _scSetupListener(newChar)
            end)
        end

        -- Selector skin Gun
        local _gunNames = {}
        for _, s in ipairs(_SC_GUN_SKINS) do _gunNames[#_gunNames+1] = s.name end
        CreateNebulaSelector(rightColumn, "Skin -- Gun", _gunNames, _gunNames[1], function(sel)
            -- Auto-setear modo gun al usar este selector
            if _skinState.mode ~= "gun" then
                if _skinState.enabled then _scResetAll(); _skinState.enabled = false end
                _skinState.mode = "gun"
                _skinState.skinIdx = 1
            end
            local selectedSkin = nil
            for i, s in ipairs(_SC_GUN_SKINS) do
                if s.name == sel then
                    _skinState.skinIdx = i
                    selectedSkin = s
                    break
                end
            end
            -- FIX SKIN SWAP: si ya habia una skin aplicada, resetear origData del tool
            -- actual para que la nueva skin se aplique desde los valores originales
            -- y no queden capas acumuladas (bug visible en mobile: skin no cambiaba).
            local _toolActual = _findGun and _findGun()
            if _toolActual and _skinState.origData[_toolActual] then
                -- Restaurar valores originales de ese tool antes de aplicar la nueva skin
                local _data = _skinState.origData[_toolActual]
                pcall(function() _toolActual.Grip = _data.Grip end)
                for obj, eData in pairs(_data.Elements) do
                    if obj and obj.Parent then
                        pcall(function()
                            if obj:IsA("SpecialMesh") then
                                obj.MeshId    = eData.Mesh
                                obj.TextureId = eData.Texture
                                obj.Scale     = eData.Scale
                            elseif obj:IsA("MeshPart") then
                                -- FIX INVISIBLE: restaurar MeshId + TextureID, destruir SM si hay
                                if eData.Mesh then obj.MeshId = eData.Mesh end
                                obj.TextureID = eData.Texture
                                -- Restaurar Size si fue modificado por meshSize
                                if eData.Size then pcall(function() obj.Size = eData.Size end) end
                                -- Destruir FakePart si fue creado por la skin
                                if eData.FakePart then pcall(function() eData.FakePart:Destroy() end) end
                                -- Restaurar visibilidad del handle original
                                pcall(function() obj.Transparency = 0 end)
                                local _sm = obj:FindFirstChildOfClass("SpecialMesh")
                                if _sm then pcall(function() _sm:Destroy() end) end
                            end
                        end)
                    end
                end
                _skinState.origData[_toolActual] = nil  -- limpiar cache para re-capturar originales
            end
            -- FIX MOBILE: activar siempre, incluso si no hay gun ahora mismo.
            -- El listener de DescendantAdded/ChildAdded va a aplicar la skin
            -- cuando la gun aparezca (sea en PC o mobile).
            _skinState.enabled = true
            -- FIX: buscar gun en char, backpack Y en workspace[playerName] (mobile MM2)
            local function _findGunMobile()
                local gun = _findGun and _findGun()
                if gun then return gun end
                -- En mobile MM2 la gun a veces vive en workspace bajo el nombre del jugador
                local wsChar = workspace:FindFirstChild(LocalPlayer.Name)
                if wsChar then
                    gun = _findGunIn and _findGunIn(wsChar)
                    if gun then return gun end
                end
                return nil
            end
            local tool = _findGunMobile()
            if tool then
                _scApply(tool, _scGetSkin(), true)
            end
            -- Intentar de nuevo con delays por si la gun tarda en cargarse (mobile)
            -- FIX MOBILE v4: extendido hasta 5s para executors lentos
            task.delay(0.3, function()
                if not _skinState.enabled then return end
                local gun2 = _findGunMobile()
                if gun2 then _scApply(gun2, _scGetSkin(), true) end
            end)
            task.delay(0.8, function()
                if not _skinState.enabled then return end
                local gun3 = _findGunMobile()
                if gun3 then _scApply(gun3, _scGetSkin(), true) end
            end)
            task.delay(1.5, function()
                if not _skinState.enabled then return end
                local gun4 = _findGunMobile()
                if gun4 then _scApply(gun4, _scGetSkin(), true) end
            end)
            task.delay(3.0, function()
                if not _skinState.enabled then return end
                local gun5 = _findGunMobile()
                if gun5 then _scApply(gun5, _scGetSkin(), true) end
            end)
            task.delay(5.0, function()
                if not _skinState.enabled then return end
                local gun6 = _findGunMobile()
                if gun6 then _scApply(gun6, _scGetSkin(), true) end
            end)

        end)

        -- ==============================================================
        -- HOOK GUNSHOT SOUND -- Shotgun & Harvester
        -- Hookea __namecall para interceptar FireServer del remote de
        -- disparo en el CLIENTE (cuando vos dispara, no cuando otros).
        -- Reproduces el sonido personalizado localmente al instante.
        -- Shotgun  -> rbxassetid://7441077838
        -- Harvester -> rbxassetid://7808472682
        -- ==============================================================
        do
            -- Limpiar hook anterior si existia (re-ejecucion del script)
            if _G._scGunSoundHookActive and _G._scGunSoundOldNamecall and _G._scGunSoundMt then
                pcall(function()
                    setreadonly(_G._scGunSoundMt, false)
                    _G._scGunSoundMt.__namecall = _G._scGunSoundOldNamecall
                    setreadonly(_G._scGunSoundMt, true)
                end)
                _G._scGunSoundHookActive   = false
                _G._scGunSoundOldNamecall  = nil
                _G._scGunSoundMt           = nil
            end

            -- Helper: reproducir sonido localmente
            local function _playCustomGunSound(soundId)
                local s = Instance.new("Sound")
                s.SoundId = soundId
                s.Volume = 1
                s.RollOffMaxDistance = 60
                s.Parent = workspace
                s:Play()
                game:GetService("Debris"):AddItem(s, 4)
            end

            -- Solo instalar si el executor soporta hookmetamethod
            if hookmetamethod and getrawmetatable and setreadonly and newcclosure and getnamecallmethod then
                local mt = getrawmetatable(game)
                -- Guardar el namecall REAL solo la primera vez (evitar cadena rota en re-ejecucion)
                if not _G._scGunSoundRealNamecall then
                    _G._scGunSoundRealNamecall = mt.__namecall
                end
                local _origNC = _G._scGunSoundRealNamecall

                setreadonly(mt, false)
                mt.__namecall = newcclosure(function(self, ...)
                    local method
                    pcall(function() method = getnamecallmethod() end)

                    -- Solo interceptar FireServer
                    if method ~= "FireServer" then
                        return _origNC(self, ...)
                    end

                    -- Verificar que es un RemoteEvent de gun (por nombre)
                    -- FIX #6: removidos gunkill y fakeshoot (eventos de gameplay, no de disparo)
                    local selfName = ""
                    pcall(function() selfName = self.Name:lower() end)
                    local isGunRemote = selfName == "shoot" or selfName == "gunshoot"
                        or selfName == "bulletfire" or selfName == "gunfire"
                        or selfName == "shootremote" or selfName == "gunshot"

                    -- Sonido GunShot: reproducir siempre que el remote sea "gunshot",
                    -- sin importar si el skin changer esta activo o no
                    if selfName == "gunshot" then
                        _playCustomGunSound("rbxassetid://7441077838")
                    elseif isGunRemote and _skinState.enabled and _skinState.mode == "gun" then
                        local currentSkin = _scGetSkin()
                        if currentSkin then
                            if currentSkin.name == "Shotgun" then
                                _playCustomGunSound("rbxassetid://7441077838")
                            elseif currentSkin.name == "Harvester" then
                                _playCustomGunSound("rbxassetid://7808472682")
                            end
                        end
                    end

                    return _origNC(self, ...)
                end)
                setreadonly(mt, true)

                _G._scGunSoundHookActive  = true
                _G._scGunSoundOldNamecall = _origNC
                _G._scGunSoundMt          = mt
            end
        end
        -- == FIN HOOK GUNSHOT SOUND ==========================================

        -- -- SELECTOR KNIFE SKINS (funcional, mismo patron que Gun) -----------
        do
            local _knifeNames = {}
            for _, s in ipairs(_SC_KNIFE_SKINS) do _knifeNames[#_knifeNames+1] = s.name end

            -- Helper: buscar el knife equipado en char o backpack
            local function _findKnife()
                local char = LocalPlayer.Character
                local bp   = LocalPlayer.Backpack
                if char then
                    for _, child in ipairs(char:GetChildren()) do
                        if child:IsA("Tool") and _scEsKnife(child) then return child end
                    end
                end
                if bp then
                    for _, child in ipairs(bp:GetChildren()) do
                        if child:IsA("Tool") and _scEsKnife(child) then return child end
                    end
                end
                -- Fallback: buscar en workspace bajo el nombre del jugador
                local wsChar = workspace:FindFirstChild(LocalPlayer.Name)
                if wsChar then
                    for _, child in ipairs(wsChar:GetChildren()) do
                        if child:IsA("Tool") and _scEsKnife(child) then return child end
                    end
                end
                return nil
            end

            -- Conexiones de escucha knife (limpiadas al re-construir el tab)
            if _skinState._knifeCharConn then
                pcall(function() _skinState._knifeCharConn:Disconnect() end)
                _skinState._knifeCharConn = nil
            end
            if _skinState._knifePickupConn then
                pcall(function() _skinState._knifePickupConn:Disconnect() end)
                _skinState._knifePickupConn = nil
            end
            if _skinState._knifeWsConn then
                pcall(function() _skinState._knifeWsConn:Disconnect() end)
                _skinState._knifeWsConn = nil
            end

            -- Funcion que intenta aplicar la skin al knife actual
            local function _scTryApplyKnife()
                if not _skinState.enabled or _skinState.mode ~= "knife" then return end
                -- FIX DUAL KNIFE: no pisar el grip mientras dual knife esta activo
                if _G._dualKnifeEnabled then return end
                task.wait(0.15)
                if _G._dualKnifeEnabled then return end
                local knife = _findKnife()
                if knife then _scApply(knife, _scGetSkin(), true) end
            end

            -- Listener en el personaje para detectar cuando el knife aparece
            local function _scSetupKnifeListener(char)
                if _skinState._knifePickupConn then
                    pcall(function() _skinState._knifePickupConn:Disconnect() end)
                end
                _skinState._knifePickupConn = char.ChildAdded:Connect(function(child)
                    if child:IsA("Tool") and _scEsKnife(child) then
                        -- FIX DUAL KNIFE: no pisar el grip mientras dual knife esta activo
                        if _G._dualKnifeEnabled then return end
                        task.spawn(_scTryApplyKnife)
                    end
                end)
                -- Listener en workspace para mobile (knife puede llegar via DescendantAdded)
                if _skinState._knifeWsConn then
                    pcall(function() _skinState._knifeWsConn:Disconnect() end)
                end
                _skinState._knifeWsConn = workspace.DescendantAdded:Connect(function(obj)
                    if not _skinState.enabled or _skinState.mode ~= "knife" then return end
                    -- FIX DUAL KNIFE: no pisar el grip mientras dual knife esta activo
                    if _G._dualKnifeEnabled then return end
                    if obj:IsA("Tool") and _scEsKnife(obj) then
                        task.spawn(_scTryApplyKnife)
                    end
                end)
            end

            CreateNebulaSelector(rightColumn, "Skin -- Knife ??", _knifeNames, _knifeNames[1], function(sel)
                -- Auto-setear modo knife al usar este selector
                if _skinState.mode ~= "knife" then
                    if _skinState.enabled then _scResetAll(); _skinState.enabled = false end
                    _skinState.mode = "knife"
                    _skinState.skinIdx = 1
                end

                -- Encontrar el indice de la skin seleccionada
                local selectedSkin = nil
                for i, s in ipairs(_SC_KNIFE_SKINS) do
                    if s.name == sel then
                        _skinState.skinIdx = i
                        selectedSkin = s
                        break
                    end
                end

                if not selectedSkin then return end

                -- FIX SKIN SWAP: si ya habia una skin aplicada, restaurar origData antes de aplicar la nueva
                local _knifeActual = _findKnife()
                if _knifeActual and _skinState.origData[_knifeActual] then
                    local _data = _skinState.origData[_knifeActual]
                    pcall(function() _knifeActual.Grip = _data.Grip end)
                    for obj, eData in pairs(_data.Elements) do
                        if obj and obj.Parent then
                            pcall(function()
                                if obj:IsA("SpecialMesh") then
                                    obj.MeshId    = eData.Mesh
                                    obj.TextureId = eData.Texture
                                    obj.Scale     = eData.Scale
                                elseif obj:IsA("MeshPart") then
                                    -- FIX INVISIBLE: restaurar MeshId + TextureID, destruir SM si hay
                                    if eData.Mesh then obj.MeshId = eData.Mesh end
                                    obj.TextureID = eData.Texture
                                    -- Restaurar Size si fue modificado por meshSize
                                    if eData.Size then pcall(function() obj.Size = eData.Size end) end
                                    -- Destruir FakePart si fue creado por la skin
                                    if eData.FakePart then pcall(function() eData.FakePart:Destroy() end) end
                                    -- Restaurar visibilidad del handle original
                                    pcall(function() obj.Transparency = 0 end)
                                    local _sm = obj:FindFirstChildOfClass("SpecialMesh")
                                    if _sm then pcall(function() _sm:Destroy() end) end
                                end
                            end)
                        end
                    end
                    _skinState.origData[_knifeActual] = nil
                end

                -- Activar skin y aplicar al knife actual
                _skinState.enabled = true
                local knife = _findKnife()
                if knife then
                    _scApply(knife, _scGetSkin(), true)
                end

                -- Aplicar con delays (mobile / executor lento)
                task.delay(0.3, function()
                    if not _skinState.enabled or _skinState.mode ~= "knife" then return end
                    if _G._dualKnifeEnabled then return end
                    local k = _findKnife(); if k then _scApply(k, _scGetSkin(), true) end
                end)
                task.delay(0.8, function()
                    if not _skinState.enabled or _skinState.mode ~= "knife" then return end
                    if _G._dualKnifeEnabled then return end
                    local k = _findKnife(); if k then _scApply(k, _scGetSkin(), true) end
                end)
                task.delay(1.5, function()
                    if not _skinState.enabled or _skinState.mode ~= "knife" then return end
                    if _G._dualKnifeEnabled then return end
                    local k = _findKnife(); if k then _scApply(k, _scGetSkin(), true) end
                end)
                task.delay(3.0, function()
                    if not _skinState.enabled or _skinState.mode ~= "knife" then return end
                    if _G._dualKnifeEnabled then return end
                    local k = _findKnife(); if k then _scApply(k, _scGetSkin(), true) end
                end)

                -- Registrar listener del personaje para re-aplicar si el jugador muere/respawnea
                local char2 = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
                _scSetupKnifeListener(char2)
                if _skinState._knifeCharConn then
                    pcall(function() _skinState._knifeCharConn:Disconnect() end)
                end
                _skinState._knifeCharConn = LocalPlayer.CharacterAdded:Connect(function(newChar)
                    _skinState.origData = {}
                    if _skinState._equippedConns then
                        for _, conn in pairs(_skinState._equippedConns) do
                            pcall(function() conn:Disconnect() end)
                        end
                        _skinState._equippedConns = {}
                    end
                    -- FIX DUAL KNIFE: no re-aplicar el skin listener si dual knife esta activo
                    if not _G._dualKnifeEnabled then
                        _scSetupKnifeListener(newChar)
                    end
                end)

                -- HOOK DUAL KNIFE: aplicar skin al DK_Clone si dual knife esta activo
                -- Usar _applyToClone que respeta meshPartOnly y forceVisible
                task.spawn(function()
                    task.wait(0.2)
                    local char3 = LocalPlayer.Character
                    if not char3 then return end
                    local dkClone = char3:FindFirstChild("DK_Clone")
                    if dkClone then
                        _applyToClone(dkClone, selectedSkin)
                    end
                end)

                CreateCustomNotification("?? KNIFE SKIN", sel .. " aplicada!", 3)
            end)
        end  -- cierra do knife selector
        end  -- cierra do skin changer
    -- -- FIN SKIN CHANGER ------------------------------------------


    -- --------------------------------------------------------------------
    -- ?? CUSTOM MIRAS (CROSSHAIRS) - PREMIUM
    -- --------------------------------------------------------------------
    do
        local ccInner = CreateVisualCard(rightColumn, "", "CUSTOM CROSSHAIR", ThemeColors.Aurora1)

        CreateAuroraToggle(ccInner, "Custom Crosshair", function(enabled)
            Settings.cursor.enabled = enabled
            UpdateCustomCursor()
        end, Settings.cursor.enabled)

        -- Selector de miras
        CreateNebulaSelector(ccInner, "Select The Crosshair", scopeNames or {
            "CRUZ HOLOGRAFICA","FUEGO ARDIENTE","DIAMANTE DUAL","RAYO ELECTRICO",
            "LUNA OSCURA","PUNTO ROJO","VORTICE MORTAL","OJO VIGILANTE",
            "OBJETIVO PRECISO","EXPLOSION TACTICA","ESTRELLA NEON","DIAMANTE AZUL","PRISMA LETAL",
        }, (scopeNames and scopeNames[Settings.cursor.currentScopeIndex or 1]) or "CRUZ HOLOGRAFICA", function(selectedName)
            local names = scopeNames or {}
            for i, name in ipairs(names) do
                if name == selectedName then
                    Settings.cursor.currentScopeIndex = i
                    Settings.cursor.customMiraId = ""
                    if Settings.cursor.enabled then UpdateCustomCursor() end
                    break
                end
            end
        end)

        CreateSlider(ccInner, "Speed Crosshair Rotation", 1, 20, Settings.cursor.rotation.speed or 2, function(value)
            Settings.cursor.rotation.speed = value
        end)

        CreateSlider(ccInner, "Crosshair Size", 10, 200, Settings.cursor.size and Settings.cursor.size.x or 50, function(value)
            Settings.cursor.size = Settings.cursor.size or {x=50, y=50}
            Settings.cursor.size.x = value
            Settings.cursor.size.y = value
            if Settings.cursor.image then
                Settings.cursor.image.Size = UDim2.new(0, value, 0, value)
            end
        end)

        CreateAuroraToggle(ccInner, "Rotate Crosshair", function(enabled)
            Settings.cursor.rotation.enabled = enabled
            -- FIX: activar rotacion directamente sin depender de que el cursor este enabled
            if Settings.cursor.enabled then
                UpdateCustomCursor()
            elseif enabled then
                -- Si el cursor no esta activo, activarlo automaticamente para que la rotacion tenga efecto
                Settings.cursor.enabled = true
                -- Actualizar el toggle visual de Custom Crosshair
                if _G._toggleStates then _G._toggleStates["Custom Crosshair"] = true end
                if _G._toggleApplyStates and _G._toggleApplyStates["Custom Crosshair"] then
                    pcall(_G._toggleApplyStates["Custom Crosshair"], true, true)
                end
                UpdateCustomCursor()
            end
        end, Settings.cursor.rotation and Settings.cursor.rotation.enabled or false)
        -- ADD CUSTOM CROSSHAIR SECTION
        do
            local _addCCFrame = Instance.new("Frame", ccInner)
            _addCCFrame.Name = "AddCustomCrosshairFrame"
            _addCCFrame.Size = UDim2.new(1, -12, 0, 80)
            _addCCFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 30)
            _addCCFrame.BackgroundTransparency = 0.3
            _addCCFrame.BorderSizePixel = 0
            _addCCFrame.ZIndex = 20
            Instance.new("UICorner", _addCCFrame).CornerRadius = UDim.new(0, 8)
            local _addCCStroke = Instance.new("UIStroke", _addCCFrame)
            _addCCStroke.Color = ThemeColors and ThemeColors.Aurora1 or Color3.fromRGB(90, 120, 255)
            _addCCStroke.Thickness = 1.5
            _addCCStroke.Transparency = 0.4
            local _addCCPad = Instance.new("UIPadding", _addCCFrame)
            _addCCPad.PaddingLeft = UDim.new(0, 8)
            _addCCPad.PaddingRight = UDim.new(0, 8)
            _addCCPad.PaddingTop = UDim.new(0, 6)
            _addCCPad.PaddingBottom = UDim.new(0, 6)
            -- Titulo
            local _addCCTitle = Instance.new("TextLabel", _addCCFrame)
            _addCCTitle.Size = UDim2.new(1, 0, 0, 16)
            _addCCTitle.Position = UDim2.new(0, 0, 0, 0)
            _addCCTitle.BackgroundTransparency = 1
            _addCCTitle.Text = "Add Custom Crosshair"
            _addCCTitle.Font = Enum.Font.GothamBold
            _addCCTitle.TextSize = 11
            _addCCTitle.TextColor3 = ThemeColors and ThemeColors.Aurora1 or Color3.fromRGB(160, 180, 255)
            _addCCTitle.TextXAlignment = Enum.TextXAlignment.Left
            _addCCTitle.ZIndex = 21
            -- Input + boton en fila
            local _addCCRow = Instance.new("Frame", _addCCFrame)
            _addCCRow.Size = UDim2.new(1, 0, 0, 32)
            _addCCRow.Position = UDim2.new(0, 0, 0, 20)
            _addCCRow.BackgroundTransparency = 1
            _addCCRow.ZIndex = 21
            -- TextBox para el ID
            local _addCCBox = Instance.new("TextBox", _addCCRow)
            _addCCBox.Name = "CustomCrosshairIDBox"
            _addCCBox.Size = UDim2.new(1, -74, 1, 0)
            _addCCBox.Position = UDim2.new(0, 0, 0, 0)
            _addCCBox.BackgroundColor3 = Color3.fromRGB(30, 30, 42)
            _addCCBox.BackgroundTransparency = 0.1
            _addCCBox.BorderSizePixel = 0
            _addCCBox.PlaceholderText = "Crosshair ID..."
            _addCCBox.PlaceholderColor3 = Color3.fromRGB(120, 120, 140)
            _addCCBox.Text = Settings.cursor.customMiraId or ""
            _addCCBox.TextColor3 = Color3.fromRGB(230, 230, 255)
            _addCCBox.Font = Enum.Font.Gotham
            _addCCBox.TextSize = 12
            _addCCBox.ClearTextOnFocus = false
            _addCCBox.ZIndex = 22
            _addCCBox.ClipsDescendants = true
            Instance.new("UICorner", _addCCBox).CornerRadius = UDim.new(0, 6)
            local _boxStroke = Instance.new("UIStroke", _addCCBox)
            _boxStroke.Color = Color3.fromRGB(80, 100, 200)
            _boxStroke.Thickness = 1
            _boxStroke.Transparency = 0.5
            local _boxPad = Instance.new("UIPadding", _addCCBox)
            _boxPad.PaddingLeft = UDim.new(0, 6)
            -- Boton Add
            local _addCCBtn = Instance.new("TextButton", _addCCRow)
            _addCCBtn.Name = "AddCrosshairBtn"
            _addCCBtn.Size = UDim2.new(0, 68, 1, 0)
            _addCCBtn.Position = UDim2.new(1, -68, 0, 0)
            _addCCBtn.BackgroundColor3 = ThemeColors and ThemeColors.Aurora1 or Color3.fromRGB(90, 120, 255)
            _addCCBtn.BackgroundTransparency = 0.1
            _addCCBtn.BorderSizePixel = 0
            _addCCBtn.Text = "Add"
            _addCCBtn.Font = Enum.Font.GothamBold
            _addCCBtn.TextSize = 13
            _addCCBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
            _addCCBtn.AutoButtonColor = false
            _addCCBtn.ZIndex = 22
            Instance.new("UICorner", _addCCBtn).CornerRadius = UDim.new(0, 6)
            local _btnStroke = Instance.new("UIStroke", _addCCBtn)
            _btnStroke.Color = Color3.fromRGB(150, 170, 255)
            _btnStroke.Thickness = 1
            _btnStroke.Transparency = 0.4
            -- Hover
            _addCCBtn.MouseEnter:Connect(function()
                TweenService:Create(_addCCBtn, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(110, 140, 255), BackgroundTransparency = 0}):Play()
            end)
            _addCCBtn.MouseLeave:Connect(function()
                TweenService:Create(_addCCBtn, TweenInfo.new(0.15), {BackgroundColor3 = ThemeColors and ThemeColors.Aurora1 or Color3.fromRGB(90, 120, 255), BackgroundTransparency = 0.1}):Play()
            end)
            -- Logica del boton Add
            _addCCBtn.Activated:Connect(function()
                local _rawId = _addCCBox.Text or ""
                local _cleanId = _rawId:match("%d+")
                if not _cleanId or _cleanId == "" then
                    CreateCustomNotification("CROSSHAIR", "Ingresa un ID valido (solo numeros)", 2)
                    return
                end
                Settings.cursor.customMiraId = _cleanId
                if not Settings.cursor.enabled then
                    Settings.cursor.enabled = true
                    if _G._toggleStates then _G._toggleStates["Custom Crosshair"] = true end
                    if _G._toggleApplyStates and _G._toggleApplyStates["Custom Crosshair"] then
                        pcall(_G._toggleApplyStates["Custom Crosshair"], true, true)
                    end
                end
                UpdateCustomCursor()
                CreateCustomNotification("CROSSHAIR", "Mira personalizada aplicada! ID: " .. _cleanId, 3)
                -- Feedback visual en el boton
                local _origText = _addCCBtn.Text
                _addCCBtn.Text = "Added!"
                _addCCBtn.BackgroundColor3 = Color3.fromRGB(50, 200, 80)
                task.delay(1.2, function()
                    pcall(function()
                        _addCCBtn.Text = _origText
                        _addCCBtn.BackgroundColor3 = ThemeColors and ThemeColors.Aurora1 or Color3.fromRGB(90, 120, 255)
                    end)
                end)
            end)
        end
    -- -- FIN CUSTOM MIRAS ------------------------------------------
    end  -- cierra do CUSTOM MIRAS

end  -- cierra CreatePremiumTab


function CreateExclusiveTab()
    ClearContent()
    _makeTwoColumns()

    -- FIX SETTINGS SCROLL: forzar columna unica para que todas las secciones
    -- (izquierda y derecha) vayan al mismo ScrollingFrame y sean visibles
    rightColumn = leftColumn
    -- Asegurar que el scroll este habilitado al entrar a Settings
    if leftColumn then
        pcall(function()
            leftColumn.ScrollingEnabled = true
            leftColumn.ScrollingDirection = Enum.ScrollingDirection.Y
            leftColumn.ElasticBehavior = Enum.ElasticBehavior.Never
            leftColumn.AutomaticCanvasSize = Enum.AutomaticSize.Y
            leftColumn.CanvasSize = UDim2.new(0, 0, 0, 0)
            leftColumn.CanvasPosition = Vector2.new(0, 0)
        end)
    end

    -- ==============================================================
    --  SETTINGS - estado persistente
    -- ==============================================================
    _G._hubSettings = _G._hubSettings or {
        disableClickSound  = false,
        disableKeybinds    = false,
        undraggableButtons = false,
        noTabAnimations    = false,
        noMinMaxAnimations = false,
        allowHubDrag       = true,
        hubOpacity         = 15,   -- 0-95 (porcentaje de opacidad del fondo)
        hubScale           = 70,   -- 70-130 (escala del hub en %)
        hubLayoutMode      = 1,    -- 1=SidebarIzq 2=BarraTop 3=SidebarDer 4=BarraBot 5=MiniIzq
        notifDuration      = 3,    -- segundos default de notificaciones
        notifMuted         = false, -- silenciar todas las notificaciones
        notifShape         = "Rounded",  -- forma de las notificaciones: Rounded, Sharp, Pill, Banner, Minimal
        fpsLimit           = 0,    -- 0 = sin limite
        crosshairHidden    = false,
        hudHidden          = false,
        chatHidden         = false,
        lowRenderQuality   = false,
        disableShadows     = false,
        fullbright         = false,
        doubleColumn       = false, -- doble columna en la vista de Settings
    }
    local HS = _G._hubSettings
    local function _hs() return _G._hubSettings end

    -- FIX ESCALA: usar siempre _getTargetScale() como fuente de verdad,
    -- NO el Scale actual del frame (que puede estar en modo fullscreen o animandose).
    local _frozenScale = (_getTargetScale and _getTargetScale()) or 0.70
    -- FIX BUG TAMANIO: se elimino el task.defer que pisaba la escala al construir Settings.
    -- El fullscreen de Settings maneja su propia escala al entrar/salir correctamente.

    -- SETTINGS





    -- ============================================================
    -- SECCI?N: DISCORD
    -- ============================================================
    do
        local discordSec = CreateBorderedSectionGlobal(leftColumn, "??  DISCORD")

        local discordDesc = Instance.new("TextLabel", discordSec)
        discordDesc.Size = UDim2.new(1, -12, 0, 20)
        discordDesc.BackgroundTransparency = 1
        discordDesc.Text = "?nete a la comunidad de Zerqon Hub"
        discordDesc.TextColor3 = Color3.fromRGB(140, 180, 255)
        discordDesc.FontFace = Font.fromEnum(Enum.Font.Gotham)
        discordDesc.TextSize = 11
        discordDesc.TextWrapped = true
        discordDesc.TextXAlignment = Enum.TextXAlignment.Left
        discordDesc.ZIndex = 13
        local _ddPad = Instance.new("UIPadding", discordDesc)
        _ddPad.PaddingLeft = UDim.new(0, 6)

        -- Bot?n de Discord
        local discordBtn = Instance.new("TextButton", discordSec)
        discordBtn.Name = "DiscordJoinBtn"
        discordBtn.Size = UDim2.new(1, -12, 0, 44)
        discordBtn.BackgroundColor3 = Color3.fromRGB(88, 101, 242)   -- color Discord
        discordBtn.BackgroundTransparency = 0.05
        discordBtn.BorderSizePixel = 0
        discordBtn.Text = "  Join the Discord  ?  discord.gg/Prsa5w5VVA"
        discordBtn.FontFace = Font.fromEnum(Enum.Font.GothamBold)
        discordBtn.TextSize = 13
        discordBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        discordBtn.AutoButtonColor = false
        discordBtn.ZIndex = 13
        Instance.new("UICorner", discordBtn).CornerRadius = UDim.new(0, 10)
        local _dbStroke = Instance.new("UIStroke", discordBtn)
        _dbStroke.Color = Color3.fromRGB(150, 160, 255)
        _dbStroke.Thickness = 1.5
        _dbStroke.Transparency = 0.3
        _dbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        -- Hover
        discordBtn.MouseEnter:Connect(function()
            TweenService:Create(discordBtn, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(110, 120, 255), BackgroundTransparency = 0}):Play()
            TweenService:Create(_dbStroke, TweenInfo.new(0.12), {Transparency = 0}):Play()
        end)
        discordBtn.MouseLeave:Connect(function()
            TweenService:Create(discordBtn, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(88, 101, 242), BackgroundTransparency = 0.05}):Play()
            TweenService:Create(_dbStroke, TweenInfo.new(0.15), {Transparency = 0.3}):Play()
        end)

        -- Click: copiar link al portapapeles y notificaci?n
        discordBtn.Activated:Connect(function()
            pcall(function() setclipboard("https://discord.gg/Prsa5w5VVA") end)
            CreateCustomNotification("DISCORD", "Link copiado!  discord.gg/Prsa5w5VVA", 3)
            -- Feedback visual moment?neo
            discordBtn.Text = "  ?  Link copiado al portapapeles!"
            discordBtn.BackgroundColor3 = Color3.fromRGB(59, 165, 93)
            task.delay(2, function()
                pcall(function()
                    discordBtn.Text = "  Join the Discord  ?  discord.gg/Prsa5w5VVA"
                    TweenService:Create(discordBtn, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(88, 101, 242)}):Play()
                end)
            end)
        end)

        -- Label de link debajo
        local linkLbl = Instance.new("TextLabel", discordSec)
        linkLbl.Size = UDim2.new(1, -12, 0, 16)
        linkLbl.BackgroundTransparency = 1
        linkLbl.Text = "discord.gg/Prsa5w5VVA  ?  click para copiar el link"
        linkLbl.FontFace = Font.fromEnum(Enum.Font.Gotham)
        linkLbl.TextSize = 10
        linkLbl.TextColor3 = Color3.fromRGB(100, 120, 200)
        linkLbl.TextXAlignment = Enum.TextXAlignment.Left
        linkLbl.ZIndex = 13
        local _llPad = Instance.new("UIPadding", linkLbl)
        _llPad.PaddingLeft = UDim.new(0, 6)

        -- -- Tarjeta de perfil Discord (dentro de la secci?n DISCORD) --
        -- Solo visible si el usuario tiene premium verificado.
        -- La imagen se carga via proxy del propio servidor para evitar
        -- el bloqueo de URLs externas del CDN de Discord en el executor.
        if _G._discordPremiumVerified then
            local _BURL  = "https://zerqonhub.onrender.com"
            local _rId   = tostring(game:GetService("Players").LocalPlayer.UserId)
            local _HttpS = game:GetService("HttpService")

            local profileCard = Instance.new("Frame", discordSec)
            profileCard.Name  = "DiscordProfileCard"
            profileCard.Size  = UDim2.new(1, -12, 0, 54)
            profileCard.BackgroundColor3 = Color3.fromRGB(14, 16, 30)
            profileCard.BackgroundTransparency = 0.15
            profileCard.BorderSizePixel = 0
            profileCard.ZIndex = 13
            Instance.new("UICorner", profileCard).CornerRadius = UDim.new(0, 10)
            local _pcS = Instance.new("UIStroke", profileCard)
            _pcS.Color = Color3.fromRGB(88, 101, 242)
            _pcS.Thickness = 1.5
            _pcS.Transparency = 0.35
            _pcS.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            -- Avatar circular
            local avFrame = Instance.new("Frame", profileCard)
            avFrame.Size = UDim2.new(0, 38, 0, 38)
            avFrame.Position = UDim2.new(0, 8, 0.5, 0)
            avFrame.AnchorPoint = Vector2.new(0, 0.5)
            avFrame.BackgroundColor3 = Color3.fromRGB(88, 101, 242)
            avFrame.BackgroundTransparency = 0.6
            avFrame.BorderSizePixel = 0
            avFrame.ZIndex = 14
            Instance.new("UICorner", avFrame).CornerRadius = UDim.new(1, 0)
            local _avS = Instance.new("UIStroke", avFrame)
            _avS.Color = Color3.fromRGB(150, 160, 255)
            _avS.Thickness = 1.5
            _avS.Transparency = 0.2

            local avImg = Instance.new("ImageLabel", avFrame)
            avImg.Name = "DiscordAvatarImg"
            avImg.Size = UDim2.new(1, -4, 1, -4)
            avImg.Position = UDim2.new(0, 2, 0, 2)
            avImg.BackgroundTransparency = 1
            avImg.Image = ""
            avImg.ScaleType = Enum.ScaleType.Crop
            avImg.ZIndex = 15
            Instance.new("UICorner", avImg).CornerRadius = UDim.new(1, 0)

            -- Emoji fallback mientras carga
            local avEmoji = Instance.new("TextLabel", avFrame)
            avEmoji.Size = UDim2.new(1, 0, 1, 0)
            avEmoji.BackgroundTransparency = 1
            avEmoji.Text = "??"
            avEmoji.TextSize = 18
            avEmoji.Font = Enum.Font.GothamBold
            avEmoji.TextXAlignment = Enum.TextXAlignment.Center
            avEmoji.TextYAlignment = Enum.TextYAlignment.Center
            avEmoji.ZIndex = 14

            -- Nombre de usuario
            local nameLbl = Instance.new("TextLabel", profileCard)
            nameLbl.Name = "DiscordNameLbl"
            nameLbl.Size = UDim2.new(1, -60, 0, 20)
            nameLbl.Position = UDim2.new(0, 54, 0, 8)
            nameLbl.BackgroundTransparency = 1
            nameLbl.Text = _G._discordUsername or "Cargando..."
            nameLbl.TextSize = 12
            nameLbl.Font = Enum.Font.GothamBold
            nameLbl.TextXAlignment = Enum.TextXAlignment.Left
            nameLbl.TextColor3 = Color3.fromRGB(230, 230, 255)
            nameLbl.ZIndex = 14

            -- Badge VIP
            local badgeLbl = Instance.new("TextLabel", profileCard)
            badgeLbl.Size = UDim2.new(0, 80, 0, 15)
            badgeLbl.Position = UDim2.new(0, 54, 0, 31)
            badgeLbl.BackgroundColor3 = Color3.fromRGB(10, 30, 18)
            badgeLbl.BackgroundTransparency = 0
            badgeLbl.BorderSizePixel = 0
            badgeLbl.Text = "?? VIP ACTIVO"
            badgeLbl.TextSize = 9
            badgeLbl.Font = Enum.Font.GothamBold
            badgeLbl.TextColor3 = Color3.fromRGB(87, 242, 135)
            badgeLbl.TextXAlignment = Enum.TextXAlignment.Center
            badgeLbl.ZIndex = 14
            Instance.new("UICorner", badgeLbl).CornerRadius = UDim.new(0, 4)
            local _bdS = Instance.new("UIStroke", badgeLbl)
            _bdS.Color = Color3.fromRGB(87, 242, 135)
            _bdS.Thickness = 1
            _bdS.Transparency = 0.5

            -- Cargar avatar via proxy y nombre via get-avatar
            task.spawn(function()
                -- -- NOMBRE: pedir al backend si no est? en global --------------
                if not (_G._discordUsername and _G._discordUsername ~= "") then
                    local _ok, _res = pcall(function()
                        return request({ Url = _BURL .. "/api/get-avatar?roblox_id=" .. _rId, Method = "GET" })
                    end)
                    if _ok and _res and _res.Body then
                        local _dok, _d = pcall(function() return _HttpS:JSONDecode(_res.Body) end)
                        if _dok and _d and _d.username and _d.username ~= "" then
                            _G._discordUsername  = _d.username
                            _G._discordAvatarUrl = _d.avatarUrl or ""
                            pcall(function() nameLbl.Text = _d.username end)
                        end
                    end
                end

                -- -- IMAGEN: descargar bytes desde el proxy y mostrar -----------
                -- Los executors bloquean cdn.discordapp.com pero permiten nuestro
                -- dominio propio. Descargamos los bytes con request() y los cargamos
                -- como Content usando EditableImage (Synapse/Wave/Fluxus lo soportan).
                local _avatarLoaded = false

                -- Intento 1: Content.fromUri (executors modernos)
                pcall(function()
                    local _avatarUrl = _BURL .. "/api/discord-avatar?roblox_id=" .. _rId
                    -- Algunos executors soportan http directamente en Image si el dominio
                    -- est? en la whitelist del executor (no de Roblox)
                    avImg.Image = _avatarUrl
                    -- Esperar 1.5s para ver si carg? (el executor hace el request async)
                    task.wait(1.5)
                    -- Si Image sigue siendo la URL (no fue remplazada por rbxasset://), asumimos que carg?
                    if avImg.Image ~= "" and not avImg.Image:find("rbxasset") then
                        avEmoji.Visible = false
                        _avatarLoaded = true
                    end
                end)

                -- Intento 2: request() + EditableImage (fallback para executors con whitelist)
                if not _avatarLoaded then
                    pcall(function()
                        local _ok2, _res2 = pcall(function()
                            return request({
                                Url    = _BURL .. "/api/discord-avatar?roblox_id=" .. _rId,
                                Method = "GET",
                            })
                        end)
                        if _ok2 and _res2 and _res2.Body and #_res2.Body > 100 then
                            -- Crear EditableImage y cargar los bytes
                            local ei = Instance.new("EditableImage")
                            ei.Size = Vector2.new(128, 128)
                            -- Algunos executors exponen writePixels desde body raw
                            -- M?todo m?s compatible: usar ImageData si est? disponible
                            avImg.Image = ""
                            -- Intentar Content.fromObject si est? disponible (Roblox 2024+)
                            local ok3 = pcall(function()
                                ei:WritePixelsBuffer(0, 0, ei.Size, _res2.Body)
                                avImg.ImageContent = Content.fromObject(ei)
                            end)
                            if ok3 then
                                avEmoji.Visible = false
                                _avatarLoaded = true
                            end
                        end
                    end)
                end

                -- Si ning?n m?todo funcion?, mostrar inicial del nombre como fallback
                if not _avatarLoaded then
                    local _uname = _G._discordUsername or "?"
                    local _initial = _uname:sub(1, 1):upper()
                    avEmoji.Text = _initial ~= "" and _initial or "??"
                    avEmoji.TextSize = 20
                    avEmoji.Visible = true
                end
            end)
        end
    end

