    -- ============================================================

    -- ================================================================
    -- HUB LAYOUT (5 modos de distribucion de pesta?as)
    -- ================================================================
    do
        local layoutSec = CreateBorderedSectionGlobal(rightColumn, " HUB LAYOUT")

        local layoutDesc = Instance.new("TextLabel", layoutSec)
        layoutDesc.Size = UDim2.new(1, -12, 0, 22)
        layoutDesc.BackgroundTransparency = 1
        layoutDesc.Text = "Choose how the hub tabs are organized"
        layoutDesc.TextColor3 = Color3.fromRGB(140, 180, 255)
        layoutDesc.FontFace = Font.fromEnum(Enum.Font.Gotham)
        layoutDesc.TextSize = 11
        layoutDesc.TextWrapped = true
        layoutDesc.TextXAlignment = Enum.TextXAlignment.Left
        layoutDesc.ZIndex = 13

        _G._hubSettings = _G._hubSettings or {}
        local _curLayoutMode = _G._hubSettings.hubLayoutMode or 1

        -- ============================================================
        -- Funcion que aplica el layout seleccionado al hub
        -- ============================================================
        local function _applyHubLayout(mode)
            pcall(function()
                local dock = mainFrame:FindFirstChild("TabDock")
                if not dock then return end
                local dockList = dock:FindFirstChild("DockList")
                if not dockList then return end
                local dockLayout = dockList:FindFirstChildOfClass("UIListLayout")
                local dockPad    = dockList:FindFirstChildOfClass("UIPadding")

                _G._hubSettings.hubLayoutMode = mode
                _curLayoutMode = mode

                local ti = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

                -- Todos los modos usan el layout de referencia: panel derecho con botones grandes
                do
                    dock.Position = UDim2.new(0.65, 0, 0.14, 0)
                    dock.Size = UDim2.new(0.35, 0, 0.86, 0)
                    contentContainer.Position = UDim2.new(0, 0, 0, 36)
                    contentContainer.Size = UDim2.new(0.65, 0, 1, -36)
                    if dockLayout then
                        dockLayout.FillDirection       = Enum.FillDirection.Vertical
                        dockLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
                        dockLayout.VerticalAlignment   = Enum.VerticalAlignment.Top
                        -- FIX TAMA?O PESTA?AS: usar padding fijo en px igual al valor de creacion
                        -- (antes usaba UDim.new(0.02, 0) relativo -> tama?o cambiaba al reabrir)
                        dockLayout.Padding             = UDim.new(0, 4)
                    end
                    if dockPad then
                        dockPad.PaddingTop    = UDim.new(0, 4)
                        dockPad.PaddingBottom = UDim.new(0, 4)
                        dockPad.PaddingLeft   = UDim.new(0, 4)
                        dockPad.PaddingRight  = UDim.new(0, 4)
                    end
                    -- FIX TAMA?O PESTA?AS: usar altura fija en px igual al valor de creacion
                    -- (antes usaba UDim2.new(1,0,0.10,0) relativo -> tama?o cambiaba al reabrir)
                    local _isMobileLayout2 = pcall(function() return game:GetService("UserInputService").TouchEnabled end)
                                            and game:GetService("UserInputService").TouchEnabled
                    local _fixedRowH = _isMobileLayout2 and 52 or 60
                    for _, btn in ipairs(dockList:GetChildren()) do
                        if btn:IsA("TextButton") and btn:FindFirstChild("TAB_BTN_PROTECTED") then
                            btn.Size = UDim2.new(1, -8, 0, _fixedRowH)
                            local lbl = btn:FindFirstChild("TabLabel")
                            if lbl then
                                lbl.TextScaled   = false
                                local fullName = btn.Name:gsub("SideBtn$", "")
                                lbl.Text = fullName
                            end
                        end
                    end
                end
                if false then  -- bloque legacy desactivado

                elseif mode == 2 then
                    -- LAYOUT 2: Barra superior horizontal (44px de alto)
                    TweenService:Create(dock, ti, {
                        Position = UDim2.new(0, 0, 0, 36),
                        Size     = UDim2.new(1, 0, 0, 44)
                    }):Play()
                    TweenService:Create(contentContainer, ti, {
                        Position = UDim2.new(0, 0, 0, 82),
                        Size     = UDim2.new(1, 0, 1, -82)
                    }):Play()
                    if dockLayout then
                        dockLayout.FillDirection       = Enum.FillDirection.Horizontal
                        dockLayout.VerticalAlignment   = Enum.VerticalAlignment.Center
                        dockLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
                        dockLayout.Padding             = UDim.new(0, 3)
                    end
                    if dockList then
                        dockList.ScrollingDirection  = Enum.ScrollingDirection.X
                        dockList.AutomaticCanvasSize = Enum.AutomaticSize.X
                        dockList.CanvasSize          = UDim2.new(0, 0, 0, 0)
                    end
                    if dockPad then
                        dockPad.PaddingTop    = UDim.new(0, 2)
                        dockPad.PaddingBottom = UDim.new(0, 2)
                        dockPad.PaddingLeft   = UDim.new(0, 4)
                        dockPad.PaddingRight  = UDim.new(0, 4)
                    end
                    for _, btn in ipairs(dockList:GetChildren()) do
                        if btn:IsA("TextButton") then
                            btn.Size = UDim2.new(0, 88, 1, -6)
                            local lbl = btn:FindFirstChild("TabLabel")
                            if lbl then
                                lbl.TextSize     = 11
                                lbl.TextTruncate = Enum.TextTruncate.AtEnd
                                local fullName = btn.Name:gsub("SideBtn$", "")
                                lbl.Text = fullName
                            end
                        end
                    end

                elseif mode == 3 then
                    -- LAYOUT 3: Sidebar derecha (200px, vertical)
                    TweenService:Create(dock, ti, {
                        Position = UDim2.new(1, -200, 0, 36),
                        Size     = UDim2.new(0, 200, 1, -36)
                    }):Play()
                    TweenService:Create(contentContainer, ti, {
                        Position = UDim2.new(0, 0, 0, 36),
                        Size     = UDim2.new(1, -200, 1, -36)
                    }):Play()
                    if dockLayout then
                        dockLayout.FillDirection       = Enum.FillDirection.Vertical
                        dockLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
                        dockLayout.VerticalAlignment   = Enum.VerticalAlignment.Top
                        dockLayout.Padding             = UDim.new(0, 2)
                    end
                    if dockList then
                        dockList.ScrollingDirection   = Enum.ScrollingDirection.Y
                        dockList.AutomaticCanvasSize  = Enum.AutomaticSize.Y
                        dockList.CanvasSize           = UDim2.new(0, 0, 0, 0)
                    end
                    if dockPad then
                        dockPad.PaddingTop    = UDim.new(0, 6)
                        dockPad.PaddingBottom = UDim.new(0, 0)
                        dockPad.PaddingLeft   = UDim.new(0, 4)
                        dockPad.PaddingRight  = UDim.new(0, 4)
                    end
                    for _, btn in ipairs(dockList:GetChildren()) do
                        if btn:IsA("TextButton") then
                            btn.Size = UDim2.new(1, -8, 0, 52)
                            local lbl = btn:FindFirstChild("TabLabel")
                            if lbl then
                                lbl.TextSize     = 15
                                lbl.TextTruncate = Enum.TextTruncate.AtEnd
                                local fullName = btn.Name:gsub("SideBtn$", "")
                                lbl.Text = fullName
                            end
                        end
                    end

                elseif mode == 4 then
                    -- LAYOUT 4: Barra inferior horizontal (48px de alto)
                    TweenService:Create(dock, ti, {
                        Position = UDim2.new(0, 0, 1, -48),
                        Size     = UDim2.new(1, 0, 0, 48)
                    }):Play()
                    TweenService:Create(contentContainer, ti, {
                        Position = UDim2.new(0, 0, 0, 36),
                        Size     = UDim2.new(1, 0, 1, -84)
                    }):Play()
                    if dockLayout then
                        dockLayout.FillDirection       = Enum.FillDirection.Horizontal
                        dockLayout.VerticalAlignment   = Enum.VerticalAlignment.Center
                        dockLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
                        dockLayout.Padding             = UDim.new(0, 3)
                    end
                    if dockList then
                        dockList.ScrollingDirection  = Enum.ScrollingDirection.X
                        dockList.AutomaticCanvasSize = Enum.AutomaticSize.X
                        dockList.CanvasSize          = UDim2.new(0, 0, 0, 0)
                    end
                    if dockPad then
                        dockPad.PaddingTop    = UDim.new(0, 2)
                        dockPad.PaddingBottom = UDim.new(0, 2)
                        dockPad.PaddingLeft   = UDim.new(0, 4)
                        dockPad.PaddingRight  = UDim.new(0, 4)
                    end
                    for _, btn in ipairs(dockList:GetChildren()) do
                        if btn:IsA("TextButton") then
                            btn.Size = UDim2.new(0, 88, 1, -8)
                            local lbl = btn:FindFirstChild("TabLabel")
                            if lbl then
                                lbl.TextSize     = 11
                                lbl.TextTruncate = Enum.TextTruncate.AtEnd
                                local fullName = btn.Name:gsub("SideBtn$", "")
                                lbl.Text = fullName
                            end
                        end
                    end

                end  -- fin if false (modos legacy desactivados)
            end)
            local _layoutNames = {"Sidebar Izq", "Barra Top", "Sidebar Der", "Barra Bot", "Mini Izq"}
            CreateCustomNotification("LAYOUT", "Layout: " .. (_layoutNames[mode] or "?") .. " aplicado", 2)
        end

        -- ============================================================
        -- Funcion helper: dibuja un diagrama miniatura del layout
        -- ============================================================
        local function _makeDiagram(parent, mode, accentColor)
            local diag = Instance.new("Frame", parent)
            diag.Size     = UDim2.new(1, -10, 0, 42)
            diag.Position = UDim2.new(0, 5, 0, 14)
            diag.BackgroundColor3 = Color3.fromRGB(12, 12, 22)
            diag.BackgroundTransparency = 0.2
            diag.BorderSizePixel = 0
            diag.ZIndex = 16
            Instance.new("UICorner", diag).CornerRadius = UDim.new(0, 5)

            local function _blk(xS, yS, wS, hS, col, alpha)
                local b = Instance.new("Frame", diag)
                b.Position             = UDim2.new(xS, 0, yS, 0)
                b.Size                 = UDim2.new(wS, 0, hS, 0)
                b.BackgroundColor3     = col
                b.BackgroundTransparency = alpha or 0
                b.BorderSizePixel      = 0
                b.ZIndex               = 17
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 2)
            end

            local acc  = accentColor
            local grey = Color3.fromRGB(70, 80, 100)

            if mode == 1 then
                _blk(0,    0,    0.26, 1,    acc,  0.05)
                _blk(0.29, 0.06, 0.69, 0.88, grey, 0.45)
            elseif mode == 2 then
                _blk(0,    0,    1,    0.26, acc,  0.05)
                _blk(0.03, 0.30, 0.94, 0.66, grey, 0.45)
            elseif mode == 3 then
                _blk(0.02, 0.06, 0.69, 0.88, grey, 0.45)
                _blk(0.74, 0,    0.26, 1,    acc,  0.05)
            elseif mode == 4 then
                _blk(0.03, 0.04, 0.94, 0.66, grey, 0.45)
                _blk(0,    0.74, 1,    0.26, acc,  0.05)
            elseif mode == 5 then
                _blk(0,    0,    0.13, 1,    acc,  0.05)
                _blk(0.16, 0.06, 0.82, 0.88, grey, 0.45)
            end
        end

        -- ============================================================
        -- Definicion de los 5 layouts
        -- ============================================================
        local _layouts = {
            { label="SIDEBAR IZQ", desc="Tabs verticales izquierda",  color=Color3.fromRGB(20, 35, 80),  accent=Color3.fromRGB(255, 80, 180), mode=1 },
            { label="BARRA TOP",   desc="Tabs horizontales arriba",   color=Color3.fromRGB(18,  95,  65),  accent=Color3.fromRGB(55, 210, 135), mode=2 },
            { label="SIDEBAR DER", desc="Tabs verticales derecha",    color=Color3.fromRGB(95,  25, 135),  accent=Color3.fromRGB(175,  75, 255), mode=3 },
            { label="BARRA BOT",   desc="Tabs horizontales abajo",    color=Color3.fromRGB(135,  60, 15),  accent=Color3.fromRGB(255, 155,  55), mode=4 },
            { label="MINI IZQ",    desc="Sidebar mini (iconos only)", color=Color3.fromRGB(15,  95, 105),  accent=Color3.fromRGB(55, 215, 225), mode=5 },
        }
        local _layoutBtnRefs = {}

        local function _refreshLayoutBtns()
            for _, ref in ipairs(_layoutBtnRefs) do
                local isActive = (ref.mode == _curLayoutMode)
                pcall(function()
                    TweenService:Create(ref.btn, TweenInfo.new(0.18), {
                        BackgroundTransparency = isActive and 0.08 or 0.68
                    }):Play()
                    TweenService:Create(ref.stroke, TweenInfo.new(0.18), {
                        Transparency = isActive and 0 or 0.6
                    }):Play()
                    ref.badge.Visible = isActive
                end)
            end
        end

        -- Fila 1 (layouts 1-2-3) y Fila 2 (layouts 4-5)
        local function _makeRow(parent, height)
            local row = Instance.new("Frame", parent)
            row.Size = UDim2.new(1, -8, 0, height)
            row.BackgroundTransparency = 1
            row.BorderSizePixel = 0
            row.ZIndex = 13
            local rl = Instance.new("UIListLayout", row)
            rl.FillDirection       = Enum.FillDirection.Horizontal
            rl.Padding             = UDim.new(0, 5)
            rl.VerticalAlignment   = Enum.VerticalAlignment.Center
            rl.HorizontalAlignment = Enum.HorizontalAlignment.Center
            return row
        end

        local row1 = _makeRow(layoutSec, 106)
        local row2 = _makeRow(layoutSec, 106)

        for i, layout in ipairs(_layouts) do
            local parentRow = (i <= 3) and row1 or row2

            local card = Instance.new("TextButton", parentRow)
            card.Name = "LayoutCard_" .. tostring(layout.mode)
            card.Size = UDim2.new(0, 76, 1, -6)
            card.BackgroundColor3 = layout.color
            card.BackgroundTransparency = (layout.mode == _curLayoutMode) and 0.08 or 0.68
            card.BorderSizePixel = 0
            card.Text = ""
            card.AutoButtonColor = false
            card.ZIndex = 13
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 10)

            local cardStroke = Instance.new("UIStroke", card)
            cardStroke.Color = layout.accent
            cardStroke.Thickness = 1.8
            cardStroke.Transparency = (layout.mode == _curLayoutMode) and 0 or 0.6
            cardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            -- Badge ACTIVO
            local badge = Instance.new("Frame", card)
            badge.Name = "ActiveBadge"
            badge.Size = UDim2.new(1, 0, 0, 15)
            badge.Position = UDim2.new(0, 0, 0, 0)
            badge.BackgroundColor3 = layout.accent
            badge.BackgroundTransparency = 0.12
            badge.BorderSizePixel = 0
            badge.ZIndex = 15
            badge.Visible = (layout.mode == _curLayoutMode)
            Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 6)
            local badgeLbl = Instance.new("TextLabel", badge)
            badgeLbl.Size = UDim2.new(1, 0, 1, 0)
            badgeLbl.BackgroundTransparency = 1
            badgeLbl.Text = "? ACTIVE"
            badgeLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            badgeLbl.FontFace = Font.fromEnum(Enum.Font.GothamBold)
            badgeLbl.TextSize = 7
            badgeLbl.ZIndex = 16

            -- Diagrama visual miniatura
            _makeDiagram(card, layout.mode, layout.accent)

            -- Nombre del layout
            local nameLbl = Instance.new("TextLabel", card)
            nameLbl.Size = UDim2.new(1, -4, 0, 15)
            nameLbl.Position = UDim2.new(0, 2, 1, -32)
            nameLbl.BackgroundTransparency = 1
            nameLbl.Text = layout.label
            nameLbl.TextColor3 = Color3.fromRGB(235, 240, 255)
            nameLbl.FontFace = Font.fromEnum(Enum.Font.GothamBold)
            nameLbl.TextSize = 8
            nameLbl.TextWrapped = false
            nameLbl.ZIndex = 14

            -- Descripcion del layout
            local descLbl = Instance.new("TextLabel", card)
            descLbl.Size = UDim2.new(1, -4, 0, 16)
            descLbl.Position = UDim2.new(0, 2, 1, -17)
            descLbl.BackgroundTransparency = 1
            descLbl.Text = layout.desc
            descLbl.TextColor3 = Color3.fromRGB(140, 180, 255)
            descLbl.FontFace = Font.fromEnum(Enum.Font.Gotham)
            descLbl.TextSize = 7
            descLbl.TextWrapped = true
            descLbl.ZIndex = 14

            table.insert(_layoutBtnRefs, {
                btn    = card,
                stroke = cardStroke,
                badge  = badge,
                mode   = layout.mode
            })

            local _cardMode = layout.mode
            card.MouseEnter:Connect(function()
                if _cardMode ~= _curLayoutMode then
                    TweenService:Create(card, TweenInfo.new(0.1), {BackgroundTransparency = 0.28}):Play()
                end
            end)
            card.MouseLeave:Connect(function()
                if _cardMode ~= _curLayoutMode then
                    TweenService:Create(card, TweenInfo.new(0.12), {BackgroundTransparency = 0.68}):Play()
                end
            end)
            card.Activated:Connect(function()
                PlayTabSound()
                _applyHubLayout(_cardMode)
                _curLayoutMode = _cardMode
                _refreshLayoutBtns()
            end)
        end

        -- SIEMPRE aplicar layout 1 (Sidebar izquierda) al iniciar, ignorar valor guardado
        _G._hubSettings.hubLayoutMode = 1
        _curLayoutMode = 1
        task.defer(function()
            _applyHubLayout(1)
            -- FIX SETTINGS SCROLL: re-habilitar scroll tras aplicar layout
            if leftColumn then
                pcall(function()
                    leftColumn.ScrollingEnabled = true
                    leftColumn.AutomaticCanvasSize = Enum.AutomaticSize.Y
                end)
            end
        end)
    end

    -- -- OPACIDAD Y VISUAL DEL HUB --------------------------------
    local visualSec = CreateBorderedSectionGlobal(rightColumn, " HUB VISUAL")

    -- Opacidad del fondo del hub (slider 0-95)
    CreateSlider(visualSec, "Opacidad Hub (0=invisible, 95=solido)", 0, 95, HS.hubOpacity, function(v)
        _hs().hubOpacity = v
        -- v=0 -> totalmente transparente (1.0), v=95 -> casi opaco (0.05)
        local transparency = 1 - (v / 100)
        pcall(function()
            if contentContainer and contentContainer.Parent then
                contentContainer.BackgroundTransparency = transparency
            end
            -- Aplicar tambien a mainFrame por si contentContainer no tiene fondo
            if mainFrame and mainFrame.Parent then
                mainFrame.BackgroundTransparency = transparency
            end
        end)
    end)

    -- Centrar hub en pantalla
    local centerBtn = Instance.new("TextButton", visualSec)
    centerBtn.Size = UDim2.new(1, -8, 0, 30); centerBtn.BackgroundColor3 = ThemeColors.Primary
    centerBtn.BackgroundTransparency = 0.3; centerBtn.BorderSizePixel = 0
    centerBtn.Text = " Centrar Hub en pantalla"; centerBtn.TextColor3 = Color3.fromRGB(255,255,255)
    centerBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat); centerBtn.TextSize = 11
    centerBtn.AutoButtonColor = false; centerBtn.ZIndex = 13
    Instance.new("UICorner", centerBtn).CornerRadius = UDim.new(0, 8)
    Instance.new("UIStroke", centerBtn).Color = ThemeColors.Primary
    centerBtn.Activated:Connect(function()
        pcall(function()
            mainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
            mainFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
        end)
        CreateCustomNotification("SETTINGS", "Hub centrado", 1.5)
    end)

    -- Escala del hub (slider 70-130%)
    do
        -- FIX ESCALA: el slider llama al callback en el init (applyValue en CreateSlider).
        -- Ese primer disparo pisaba el uiScale correcto ya aplicado al arrancar el hub.
        -- Con _scaleSliderReady lo ignoramos en el init y solo aplicamos en drags reales.
        local _scaleSliderReady = false
        CreateSlider(visualSec, "Escala Hub (%)", 70, 130, _hs().hubScale or 70, function(v)
            if not _scaleSliderReady then _scaleSliderReady = true; return end
            _hs().hubScale = v
            pcall(function()
                local sc = mainFrame:FindFirstChildOfClass("UIScale")
                if not sc then sc = Instance.new("UIScale", mainFrame) end
                -- FIX ESCALA DOBLE: v ya es el porcentaje (ej: 130), solo dividir por 100.
                sc.Scale = v / 100
                -- Mantener el tama?o base correcto segun dispositivo
                do
                    local _ns = (_getHubSize and _getHubSize()) or UDim2.new(0, 900, 0, 480)
                    if _G._setHubFrameSize then _G._setHubFrameSize(_ns) else mainFrame.Size = _ns end
                end
            end)
        end)
    end

    -- ============================================================
    --  FONT SELECTOR (Hub Labels)
    --  Permite cambiar la fuente de las etiquetas de los botones
    --  de la sidebar entre Normal (Gotham) y Arcade (PressStart2P).
    -- ============================================================
    do
        local _FONTS = {
            {
                label    = "Normal",
                fontFace = Font.fromEnum(Enum.Font.GothamMedium),
                textSize = 15,
            },
            {
                label    = "Arcade",
                fontFace = Font.new(
                    "rbxasset://fonts/families/PressStart2P.json",
                    Enum.FontWeight.Bold,
                    Enum.FontStyle.Normal
                ),
                textSize = 9,
            },
        }

        -- Guardar estado en _hubSettings para persistencia
        _G._hubSettings.fontMode = _G._hubSettings.fontMode or 1  -- 1=Normal, 2=Arcade

        local function _applyHubFont(modeIdx)
            _G._hubSettings.fontMode = modeIdx
            local fd = _FONTS[modeIdx]
            if not fd then return end
            -- Guardar la fuente activa globalmente para tabs reci?n cargados
            _G._hubActiveFontFace = fd.fontFace
            _G._hubActiveFontSize = fd.textSize
            -- Aplicar a todos los TabLabel de la sidebar
            pcall(function()
                if not tabDockList then return end
                for _, btn in ipairs(tabDockList:GetChildren()) do
                    if btn:IsA("TextButton") then
                        local lbl = btn:FindFirstChild("TabLabel")
                        if lbl then
                            lbl.FontFace = fd.fontFace
                            lbl.TextSize = fd.textSize
                        end
                    end
                end
            end)
            -- Aplicar a TODOS los TextLabel, TextButton y TextBox del hub completo
            -- incluyendo tabs cacheados que a?n no est?n visibles
            local function _applyFontToFrame(frame)
                if not frame then return end
                for _, obj in ipairs(frame:GetDescendants()) do
                    if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                        pcall(function()
                            obj.FontFace = fd.fontFace
                            -- FIX: NO reducir TextSize en modo Arcade para que Settings
                            -- y otros elementos no se achiquen. Solo cambia la fuente visual.
                        end)
                    end
                end
            end
            pcall(function()
                -- Aplicar al mainFrame completo (incluye tabs ya visibles)
                _applyFontToFrame(mainFrame)
                -- Aplicar tambi?n a cada tab cacheado por separado (aunque ya est?n en mainFrame,
                -- esto garantiza que tabs cargados luego tambi?n reciban la fuente)
                if _G._tabCache then
                    for _, tabFrame in pairs(_G._tabCache) do
                        if tabFrame and tabFrame.Parent then
                            _applyFontToFrame(tabFrame)
                        end
                    end
                end
            end)
        end

        local fontSec = CreateBorderedSectionGlobal(rightColumn, " FONT SELECTOR")

        -- Preview label
        local previewLbl = Instance.new("TextLabel", fontSec)
        previewLbl.Size                 = UDim2.new(1, -8, 0, 28)
        previewLbl.BackgroundColor3     = Color3.fromRGB(10, 15, 40)
        previewLbl.BackgroundTransparency = 0.4
        previewLbl.BorderSizePixel      = 0
        previewLbl.Text                 = "PREVIEW"
        previewLbl.TextColor3           = Color3.fromRGB(180, 220, 255)
        previewLbl.TextSize             = 13
        previewLbl.FontFace             = Font.fromEnum(Enum.Font.GothamMedium)
        previewLbl.TextXAlignment       = Enum.TextXAlignment.Center
        previewLbl.ZIndex               = 14
        Instance.new("UICorner", previewLbl).CornerRadius = UDim.new(0, 8)
        Instance.new("UIStroke", previewLbl).Color = Color3.fromRGB( 50, 255, 180)

        local function _refreshPreview(modeIdx)
            local fd = _FONTS[modeIdx]
            if not fd then return end
            previewLbl.FontFace = fd.fontFace
            previewLbl.TextSize = fd.textSize + 2  -- un poco mas grande en preview
        end
        _refreshPreview(_G._hubSettings.fontMode)

        -- Botones de seleccion lado a lado
        local btnRow = Instance.new("Frame", fontSec)
        btnRow.Size                 = UDim2.new(1, -8, 0, 34)
        btnRow.BackgroundTransparency = 1
        btnRow.BorderSizePixel      = 0
        local btnRowLayout = Instance.new("UIListLayout", btnRow)
        btnRowLayout.FillDirection  = Enum.FillDirection.Horizontal
        btnRowLayout.Padding        = UDim.new(0, 6)
        btnRowLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        btnRowLayout.VerticalAlignment   = Enum.VerticalAlignment.Center

        local _fontBtns = {}
        local _tiFont   = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

        local function _refreshFontBtns(activeIdx)
            for i, btn in ipairs(_fontBtns) do
                local isActive = (i == activeIdx)
                TweenService:Create(btn, _tiFont, {
                    BackgroundColor3     = isActive and Color3.fromRGB( 50, 255, 180) or Color3.fromRGB(20, 30, 70),
                    BackgroundTransparency = isActive and 0.15 or 0.55,
                }):Play()
                local st = btn:FindFirstChildOfClass("UIStroke")
                if st then
                    st.Transparency = isActive and 0 or 0.5
                end
            end
        end

        for i, fd in ipairs(_FONTS) do
            local btn = Instance.new("TextButton", btnRow)
            btn.Size                   = UDim2.new(0, 88, 1, 0)
            btn.BackgroundColor3       = Color3.fromRGB(20, 30, 70)
            btn.BackgroundTransparency = 0.55
            btn.BorderSizePixel        = 0
            btn.Text                   = fd.label
            btn.TextColor3             = Color3.fromRGB(210, 235, 255)
            btn.FontFace               = Font.fromEnum(Enum.Font.GothamBold)
            btn.TextSize               = 11
            btn.AutoButtonColor        = false
            btn.ZIndex                 = 14
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)
            local st = Instance.new("UIStroke", btn)
            st.Color       = Color3.fromRGB( 50, 255, 180)
            st.Thickness   = 1.5
            st.Transparency = 0.5
            st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            local _i = i
            btn.Activated:Connect(function()
                _applyHubFont(_i)
                _refreshPreview(_i)
                _refreshFontBtns(_i)
                CreateCustomNotification(
                    "FONT SELECTOR",
                    "Fuente: " .. fd.label,
                    1.5
                )
            end)
            _fontBtns[i] = btn
        end

        -- Marcar el activo al construir el tab
        _refreshFontBtns(_G._hubSettings.fontMode)
        -- Aplicar fuente guardada al construir (por si se reabre el hub)
        task.defer(function()
            _applyHubFont(_G._hubSettings.fontMode)
        end)
    end

    -- ============================================================
    --  TOGGLE COLOR SELECTOR  v2  (NebulaSelector ? dropdown)
    --  Selector de color FONDO del toggle (row) + PILL (switch)
    --  Se cierra automaticamente al seleccionar. Animacion lenta.
    -- ============================================================
    do
        -- Paleta compartida: fondo del row + pill del switch
        local _TC_BG = {
            { label = "?? Azul",     bg = Color3.fromRGB(20,  40, 120), bgT = 0.72, stroke = Color3.fromRGB(40,  60,  180) },
            { label = "?? Verde",    bg = Color3.fromRGB(80,  200, 120), bgT = 0.78, stroke = Color3.fromRGB(20,  140, 60)  },
            { label = "?? Rojo",     bg = Color3.fromRGB(220, 80,  80),  bgT = 0.80, stroke = Color3.fromRGB(180, 30,  30)  },
            { label = "?? Morado",   bg = Color3.fromRGB(160, 80,  220), bgT = 0.78, stroke = Color3.fromRGB(110, 30,  180) },
            { label = "?? Naranja",  bg = Color3.fromRGB(255, 160, 50),  bgT = 0.80, stroke = Color3.fromRGB(200, 100, 10)  },
            { label = "?? Rosa",     bg = Color3.fromRGB(255, 120, 180), bgT = 0.78, stroke = Color3.fromRGB(200, 60,  130) },
            { label = "?? Cyan",     bg = Color3.fromRGB(0,   220, 220), bgT = 0.80, stroke = Color3.fromRGB(0,   160, 180) },
            { label = "? Blanco",   bg = Color3.fromRGB(240, 240, 255), bgT = 0.82, stroke = Color3.fromRGB(160, 170, 210) },
            { label = "? Negro",    bg = Color3.fromRGB(20,  20,  30),  bgT = 0.55, stroke = Color3.fromRGB(80,  80,  120) },
            { label = "?? Indigo",   bg = Color3.fromRGB(60,  40,  180), bgT = 0.72, stroke = Color3.fromRGB(100, 60,  220) },
        }
        local _TC_PILL = {
            { label = "?? Azul Rey",  pill = Color3.fromRGB(60,  80,  190), stroke = Color3.fromRGB(40,  60,  180) },
            { label = "?? Verde",     pill = Color3.fromRGB(30,  130, 70),  stroke = Color3.fromRGB(20,  140, 60)  },
            { label = "?? Rojo",      pill = Color3.fromRGB(160, 40,  40),  stroke = Color3.fromRGB(180, 30,  30)  },
            { label = "?? Morado",    pill = Color3.fromRGB(100, 40,  170), stroke = Color3.fromRGB(110, 30,  180) },
            { label = "?? Naranja",   pill = Color3.fromRGB(190, 100, 20),  stroke = Color3.fromRGB(200, 100, 10)  },
            { label = "?? Rosa",      pill = Color3.fromRGB(190, 60,  130), stroke = Color3.fromRGB(200, 60,  130) },
            { label = "?? Cyan",      pill = Color3.fromRGB(0,   150, 170), stroke = Color3.fromRGB(0,   160, 180) },
            { label = "? Plata",     pill = Color3.fromRGB(140, 150, 200), stroke = Color3.fromRGB(160, 170, 210) },
            { label = "? Oscuro",    pill = Color3.fromRGB(30,  30,  50),  stroke = Color3.fromRGB(80,  80,  120) },
            { label = "?? Violeta",   pill = Color3.fromRGB(80,  40,  200), stroke = Color3.fromRGB(100, 60,  220) },
        }

        _G._hubSettings.toggleColorIdx     = _G._hubSettings.toggleColorIdx     or 1
        _G._hubSettings.togglePillColorIdx = _G._hubSettings.togglePillColorIdx or 1

        -- Aplicar color de fondo del row
        local function _applyBgColor(idx)
            _G._hubSettings.toggleColorIdx = idx
            local c = _TC_BG[idx]; if not c then return end
            _G._toggleColorCurrent = _G._toggleColorCurrent or {}
            _G._toggleColorCurrent.bg     = c.bg
            _G._toggleColorCurrent.bgT    = c.bgT
            _G._toggleColorCurrent.stroke = c.stroke
            pcall(function()
                if not mainFrame then return end
                for _, obj in ipairs(mainFrame:GetDescendants()) do
                    if obj:IsA("Frame") and obj.Name and obj.Name:sub(1, 16) == "AuroraToggleRow_" then
                        pcall(function()
                            obj.BackgroundColor3       = c.bg
                            obj.BackgroundTransparency = c.bgT
                            local st = obj:FindFirstChildOfClass("UIStroke")
                            if st then st.Color = c.stroke end
                        end)
                    end
                end
            end)
        end

        -- Aplicar color del pill (ToggleBackground)
        local function _applyPillColor(idx)
            _G._hubSettings.togglePillColorIdx = idx
            local c = _TC_PILL[idx]; if not c then return end
            _G._toggleColorCurrent = _G._toggleColorCurrent or {}
            _G._toggleColorCurrent.pill = c.pill
            pcall(function()
                if not mainFrame then return end
                for _, obj in ipairs(mainFrame:GetDescendants()) do
                    if obj:IsA("Frame") and obj.Name and obj.Name:sub(1, 16) == "AuroraToggleRow_" then
                        pcall(function()
                            local tb = obj:FindFirstChild("ToggleBackground")
                            if tb then
                                tb.BackgroundColor3       = c.pill
                                tb.BackgroundTransparency = 0.3
                                local tbSt = tb:FindFirstChildOfClass("UIStroke")
                                if tbSt then tbSt.Color = c.stroke end
                            end
                        end)
                    end
                end
            end)
        end

        local colorSec = CreateBorderedSectionGlobal(rightColumn, " COLOR TOGGLES")

        -- === Preview mini-toggle ===
        local prevRow = Instance.new("Frame", colorSec)
        prevRow.Name                   = "ToggleColorPreview"
        prevRow.Size                   = UDim2.new(1, -8, 0, 46)
        prevRow.BackgroundColor3       = _TC_BG[_G._hubSettings.toggleColorIdx].bg
        prevRow.BackgroundTransparency = _TC_BG[_G._hubSettings.toggleColorIdx].bgT
        prevRow.BorderSizePixel        = 0; prevRow.ZIndex = 13
        Instance.new("UICorner", prevRow).CornerRadius = UDim.new(0, 8)
        local prevStroke = Instance.new("UIStroke", prevRow)
        prevStroke.Color = _TC_BG[_G._hubSettings.toggleColorIdx].stroke
        prevStroke.Thickness = 2; prevStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local prevLabel = Instance.new("TextLabel", prevRow)
        prevLabel.Size = UDim2.new(0.6, 0, 1, 0); prevLabel.Position = UDim2.new(0, 8, 0, 0)
        prevLabel.BackgroundTransparency = 1; prevLabel.Text = "? Preview toggle"
        prevLabel.TextColor3 = Color3.fromRGB(255, 255, 255); prevLabel.TextSize = 11
        prevLabel.FontFace = Font.fromEnum(Enum.Font.GothamBold)
        prevLabel.TextXAlignment = Enum.TextXAlignment.Left; prevLabel.ZIndex = 14

        local prevPill = Instance.new("Frame", prevRow)
        prevPill.Size = UDim2.new(0, 52, 0, 26); prevPill.AnchorPoint = Vector2.new(1, 0.5)
        prevPill.Position = UDim2.new(1, -8, 0.5, 0)
        prevPill.BackgroundColor3 = _TC_PILL[_G._hubSettings.togglePillColorIdx].pill
        prevPill.BackgroundTransparency = 0.3; prevPill.BorderSizePixel = 0; prevPill.ZIndex = 14
        Instance.new("UICorner", prevPill).CornerRadius = UDim.new(0, 7)
        local prevPillStroke = Instance.new("UIStroke", prevPill)
        prevPillStroke.Color = _TC_PILL[_G._hubSettings.togglePillColorIdx].stroke
        prevPillStroke.Thickness = 1.5; prevPillStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local prevKnob = Instance.new("Frame", prevPill)
        prevKnob.Size = UDim2.new(0, 18, 0, 18); prevKnob.AnchorPoint = Vector2.new(0, 0.5)
        prevKnob.Position = UDim2.new(0, 4, 0.5, 0)
        prevKnob.BackgroundColor3 = Color3.fromRGB(255, 80, 80)
        prevKnob.BorderSizePixel = 0; prevKnob.ZIndex = 15
        Instance.new("UICorner", prevKnob).CornerRadius = UDim.new(0, 5)

        local function _refreshPreview()
            local bg  = _TC_BG[_G._hubSettings.toggleColorIdx]
            local pil = _TC_PILL[_G._hubSettings.togglePillColorIdx]
            if bg then
                TweenService:Create(prevRow,    TweenInfo.new(0.35), {BackgroundColor3 = bg.bg, BackgroundTransparency = bg.bgT}):Play()
                TweenService:Create(prevStroke, TweenInfo.new(0.35), {Color = bg.stroke}):Play()
            end
            if pil then
                TweenService:Create(prevPill,       TweenInfo.new(0.35), {BackgroundColor3 = pil.pill}):Play()
                TweenService:Create(prevPillStroke, TweenInfo.new(0.35), {Color = pil.stroke}):Play()
            end
        end

        -- === Selector Fondo del Row ===
        local _bgNames = {}
        for _, c in ipairs(_TC_BG) do _bgNames[#_bgNames+1] = c.label end

        CreateNebulaSelector(colorSec, "Fondo del Toggle", _bgNames,
            _TC_BG[_G._hubSettings.toggleColorIdx].label,
            function(sel)
                for i, c in ipairs(_TC_BG) do
                    if c.label == sel then
                        _applyBgColor(i)
                        _refreshPreview()
                        CreateCustomNotification("COLOR TOGGLES", "Fondo: " .. c.label, 1.5)
                        break
                    end
                end
            end
        )

        -- === Selector Pill (ToggleBackground) ===
        local _pillNames = {}
        for _, c in ipairs(_TC_PILL) do _pillNames[#_pillNames+1] = c.label end

        CreateNebulaSelector(colorSec, "Pill del Toggle (switch)", _pillNames,
            _TC_PILL[_G._hubSettings.togglePillColorIdx].label,
            function(sel)
                for i, c in ipairs(_TC_PILL) do
                    if c.label == sel then
                        _applyPillColor(i)
                        _refreshPreview()
                        CreateCustomNotification("COLOR TOGGLES", "Pill: " .. c.label, 1.5)
                        break
                    end
                end
            end
        )

        -- Aplicar colores guardados al construir el tab
        task.defer(function()
            _applyBgColor(_G._hubSettings.toggleColorIdx)
            _applyPillColor(_G._hubSettings.togglePillColorIdx)
        end)
    end


    -- -- NOTIFICACIONES -------------------------------------------
    local notifSec = CreateBorderedSectionGlobal(rightColumn, " NOTIFICACIONES")

    CreateAuroraToggle(notifSec, "Silenciar Notificaciones", function(on)
        _hs().notifMuted = on
        -- Hook: override CreateCustomNotification cuando esta muted
        if on then
            _G._notifMutedOrig = _G._notifMutedOrig or CreateCustomNotification
            CreateCustomNotification = function() end  -- noop
        else
            if _G._notifMutedOrig then
                CreateCustomNotification = _G._notifMutedOrig
                _G._notifMutedOrig = nil
            end
        end
        if not on then CreateCustomNotification("SETTINGS", "Notificaciones activadas", 1.5) end
    end, HS.notifMuted)

    CreateSlider(notifSec, "Duracion notif (seg)", 1, 10, HS.notifDuration, function(v)
        _hs().notifDuration = v
        -- Parchear la duracion default globalmente
        _G._notifDefaultDuration = v
    end)

    -- Selector de forma de notificaciones
    local _notifShapes = {"Rounded", "Sharp", "Pill", "Banner", "Minimal"}
    local _notifShapeDesc = {
        ["Rounded"]  = "Clasica con esquinas redondeadas",
        ["Sharp"]    = "Bordes rectos sin redondeo",
        ["Pill"]     = "Completamente circular (capsula)",
        ["Banner"]   = "Barra horizontal compacta con acento lateral",
        ["Minimal"]  = "Sin icono, solo texto semitransparente",
    }
    local _curShape = HS.notifShape or "Rounded"

    -- Label de descripcion de la forma actual
    local _shapeDescLbl = Instance.new("TextLabel", notifSec)
    _shapeDescLbl.Size = UDim2.new(1, -8, 0, 22)
    _shapeDescLbl.BackgroundTransparency = 1
    _shapeDescLbl.Text = "  " .. (_notifShapeDesc[_curShape] or "")
    _shapeDescLbl.TextColor3 = Color3.fromRGB(180, 180, 200)
    _shapeDescLbl.FontFace = Font.fromEnum(Enum.Font.Gotham)
    _shapeDescLbl.TextSize = 10
    _shapeDescLbl.TextXAlignment = Enum.TextXAlignment.Left
    _shapeDescLbl.ZIndex = 13

    CreateNebulaSelector(notifSec, "Forma de Notificaciones", _notifShapes, _curShape, function(sel)
        _hs().notifShape = sel
        _shapeDescLbl.Text = "  " .. (_notifShapeDesc[sel] or "")
        CreateCustomNotification("PREVIEW", "Asi se ve la forma: " .. sel, 2.5)
    end)

    -- Limpiar notificaciones activas
    local clearNotifBtn = Instance.new("TextButton", notifSec)
    clearNotifBtn.Size = UDim2.new(1, -8, 0, 28); clearNotifBtn.BackgroundColor3 = Color3.fromRGB(80,20,20)
    clearNotifBtn.BackgroundTransparency = 0.3; clearNotifBtn.BorderSizePixel = 0
    clearNotifBtn.Text = " Limpiar notificaciones activas"; clearNotifBtn.TextColor3 = Color3.fromRGB(255,120,120)
    clearNotifBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat); clearNotifBtn.TextSize = 11
    clearNotifBtn.AutoButtonColor = false; clearNotifBtn.ZIndex = 13
    Instance.new("UICorner", clearNotifBtn).CornerRadius = UDim.new(0, 8)
    clearNotifBtn.Activated:Connect(function()
        pcall(function()
            local cg = game:GetService("CoreGui")
            for _, g in ipairs(cg:GetChildren()) do
                if g.Name:find("OverdriveNotif_") then pcall(function() g:Destroy() end) end
            end
            _notifQueue = {}
            _notifRunning = false
            _notifOffset = 0
        end)
    end)

    -- -- HUD & CROSSHAIR ------------------------------------------
    local hudSec = CreateBorderedSectionGlobal(rightColumn, " HUD & CROSSHAIR")

    CreateAuroraToggle(hudSec, "Ocultar Crosshair Roblox", function(on)
        _hs().crosshairHidden = on
        -- FIX MOBILE: NO usar CoreGuiType.All - destruye el TouchGui (boton salto + joystick) en celular
        -- Solo ocultar el crosshair especifico; si el executor no lo soporta, no tocar nada mas
        pcall(function()
            local sg = game:GetService("StarterGui")
            local _ok = pcall(function()
                sg:SetCoreGuiEnabled(Enum.CoreGuiType.Crosshair, not on)
            end)
            -- Fallback para executors viejos que no tienen CoreGuiType.Crosshair:
            -- NO llamar .All porque rompe el joystick y el boton de salto en mobile
        end)
        -- Ocultar cursor del mouse en PC
        pcall(function()
            game:GetService("UserInputService").MouseIconEnabled = not on
        end)
        CreateCustomNotification("SETTINGS", on and "Crosshair oculto" or "Crosshair visible", 1.5)
    end, HS.crosshairHidden)

    CreateAuroraToggle(hudSec, "Ocultar HUD (Backpack/Health)", function(on)
        _hs().hudHidden = on
        pcall(function()
            local sg = game:GetService("StarterGui")
            sg:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, not on)
            sg:SetCoreGuiEnabled(Enum.CoreGuiType.Health, not on)
        end)
        CreateCustomNotification("SETTINGS", on and "HUD oculto" or "HUD visible", 1.5)
    end, HS.hudHidden)

    CreateAuroraToggle(hudSec, "Ocultar Chat", function(on)
        _hs().chatHidden = on
        pcall(function()
            local sg = game:GetService("StarterGui")
            sg:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, not on)
        end)
        CreateCustomNotification("SETTINGS", on and "Chat oculto" or "Chat visible", 1.5)
    end, HS.chatHidden or false)

    -- -- PERFORMANCE -----------------------------------------------
    local perfSec = CreateBorderedSectionGlobal(rightColumn, " PERFORMANCE")

    CreateAuroraToggle(perfSec, "Low Render Quality (reduce lag)", function(on)
        _hs().lowRenderQuality = on
        pcall(function()
            settings().Rendering.QualityLevel = on and Enum.QualityLevel.Level01 or Enum.QualityLevel.Automatic
        end)
        CreateCustomNotification("SETTINGS", on and "Calidad minima (menos lag)" or "Calidad automatica", 2)
    end, HS.lowRenderQuality or false)

    CreateAuroraToggle(perfSec, "Disable Shadows (FPS boost)", function(on)
        _hs().disableShadows = on
        pcall(function()
            game:GetService("Lighting").GlobalShadows = not on
        end)
        CreateCustomNotification("SETTINGS", on and "Sombras OFF" or "Sombras ON", 1.5)
    end, HS.disableShadows or false)

    CreateAuroraToggle(perfSec, "Fullbright (max Brightness)", function(on)
        _hs().fullbright = on
        pcall(function()
            local L = game:GetService("Lighting")
            if on then
                -- Guardar estado original antes de pisar (solo la primera vez)
                if not _G._lightingOriginals then
                    _G._lightingOriginals = {
                        brightness    = L.Brightness,
                        clockTime     = L.ClockTime,
                        fogEnd        = L.FogEnd,
                        globalShadows = L.GlobalShadows,
                    }
                end
                L.Brightness = 10
                L.ClockTime = 14
                L.FogEnd = 100000
                L.GlobalShadows = false
                for _, e in ipairs(L:GetChildren()) do
                    if e:IsA("BlurEffect") or e:IsA("ColorCorrectionEffect") or e:IsA("SunRaysEffect") then
                        e.Enabled = false
                    end
                end
            else
                -- Restaurar originales
                if _G._lightingOriginals then
                    L.Brightness    = _G._lightingOriginals.brightness
                    L.ClockTime     = _G._lightingOriginals.clockTime
                    L.FogEnd        = _G._lightingOriginals.fogEnd
                    L.GlobalShadows = _G._lightingOriginals.globalShadows
                end
                for name, enabled in pairs(_G._postFXOriginalStates or {}) do
                    pcall(function()
                        if name:sub(1,2) == "L_" then
                            local eff = L:FindFirstChild(name:sub(3))
                            if eff then eff.Enabled = enabled end
                        end
                    end)
                end
            end
        end)
        CreateCustomNotification("SETTINGS", on and "Fullbright ON" or "Fullbright OFF", 1.5)
    end, HS.fullbright or false)

    CreateSlider(perfSec, "FPS Cap (0 = sin limite)", 0, 60, 0, function(v)
        _hs().fpsLimit = v
        if v > 0 then
            _G._fpsCap = v
            -- Iniciar loop de FPS cap si no existe ya
            if not _G._fpsCapConn then
                -- OPT LAG FIX: task.wait() dentro de Heartbeat causa stutters porque bloquea
                -- el hilo. La forma correcta de cap de FPS es simplemente NO HACER nada en los
                -- frames extra (early return) -- el motor ya avanza al siguiente frame por su cuenta.
                local _lastFrameTime = tick()
                _G._fpsCapConn = RunService.Heartbeat:Connect(function()
                    if not _G._fpsCap or _G._fpsCap <= 0 then
                        if _G._fpsCapConn then
                            _G._fpsCapConn:Disconnect()
                            _G._fpsCapConn = nil
                        end
                        return
                    end
                    local targetDelta = 1 / _G._fpsCap
                    local now = tick()
                    local elapsed = now - _lastFrameTime
                    -- OPT: skip frame si no paso suficiente tiempo (NO task.wait, eso stutter)
                    if elapsed < targetDelta then return end
                    _lastFrameTime = now
                end)
            end
        else
            _G._fpsCap = nil
            if _G._fpsCapConn then
                _G._fpsCapConn:Disconnect()
                _G._fpsCapConn = nil
            end
        end
        CreateCustomNotification("SETTINGS", v > 0 and ("FPS cap: " .. v) or "FPS cap OFF", 1.5)
    end)


    -- ================================================================
    -- CREDITOS / AGRADECIMIENTOS
    -- ================================================================
    do
        local creditsSec = CreateBorderedSectionGlobal(leftColumn, "")

        local credFrame = Instance.new("Frame", creditsSec)
