        credFrame.AutomaticSize = Enum.AutomaticSize.Y
        credFrame.BackgroundTransparency = 1
        credFrame.BorderSizePixel = 0

        -- Barra de color lateral (igual que en la imagen)
        local bar = Instance.new("Frame", credFrame)
