function CreateCombatTab()
    if not contentContainer or not contentContainer.Parent then
        _w(0.15)
        if not contentContainer or not contentContainer.Parent then return end
    end
    ClearContent()
    -- OPT: limpiar conexiones del tab anterior
    pcall(function()
        local cs = CombatTabState
        if cs then
            if cs.autoShootConnection    then cs.autoShootConnection:Disconnect();    cs.autoShootConnection    = nil end
            if cs.autoReloadConnection   then cs.autoReloadConnection:Disconnect();   cs.autoReloadConnection   = nil end
            if cs.autoEquipConnection    then cs.autoEquipConnection:Disconnect();    cs.autoEquipConnection    = nil end
            if cs.autoEquipMurderConn    then cs.autoEquipMurderConn:Disconnect();    cs.autoEquipMurderConn    = nil end
            if cs.saAutoHideConn         then cs.saAutoHideConn:Disconnect();         cs.saAutoHideConn         = nil end
            if cs.shootPickConn          then cs.shootPickConn:Disconnect();          cs.shootPickConn          = nil end
            if cs.autoShootMurderConn    then cs.autoShootMurderConn:Disconnect();    cs.autoShootMurderConn    = nil end
        end
        if _G._wcsState and _G._wcsState.conn then _G._wcsState.conn:Disconnect(); _G._wcsState.conn = nil end
        if _G._asmState and _G._asmState.conn then _G._asmState.conn:Disconnect(); _G._asmState.conn = nil end
    end)

    -- Helper: ocultar BackpackGui para evitar flash de hotbar cuando se mueven tools al personaje
    local _sg = StarterGui
    local function _hideBackpackUI()
        pcall(function() _sg:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false) end)
    end
