        pcall(function() _sg:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true) end)
    end

    -- ---------------------------------------------------------------------

    -- ESTADO COMBAT (usa tabla global persistente)
    local CombatState = CombatTabState

    _makeTwoColumns()

    -- CREAR SECCIN CON BORDE
 local function CreateBorderedSection(parent, title)
        -- Wrapper externo con fondo totalmente transparente
