    end
    
    -- CreateBorderedToggle: ahora definida globalmente antes de CreateCombatTab()
    -- Ver definicin en lnea ~36355 (fuera de esta funcin)

    -- =============================================
    -- HEADER VISUAL: GUN
    -- =============================================
    do
        local _gunHeader = Instance.new("Frame", leftColumn)
        _gunHeader.Size = UDim2.new(1, -10, 0, 36)
        _gunHeader.BackgroundColor3 = ThemeColors.Primary
        _gunHeader.BackgroundTransparency = 0.72
        _gunHeader.BorderSizePixel = 0
        _gunHeader.ZIndex = 12
        Instance.new("UICorner", _gunHeader).CornerRadius = UDim.new(0, 8)
        local _ghStroke = Instance.new("UIStroke", _gunHeader)
        _ghStroke.Color = ThemeColors.Primary
        _ghStroke.Thickness = 2
        _ghStroke.Transparency = 0.1
        local _ghLbl = Instance.new("TextLabel", _gunHeader)
        _ghLbl.Size = UDim2.new(1, -16, 1, 0)
        _ghLbl.Position = UDim2.new(0, 8, 0, 0)
        _ghLbl.BackgroundTransparency = 1
        _ghLbl.Text = " GUN"
        _ghLbl.TextColor3 = ThemeColors.Primary
        _ghLbl.Font = Enum.Font.Montserrat
        _ghLbl.TextSize = 16
        _ghLbl.TextXAlignment = Enum.TextXAlignment.Left
        _ghLbl.ZIndex = 13
    end

    -- =============================================
 local silentAimSection = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, "[*] SILENT AIM") or Instance.new("Frame")

    -- _saGunModeApply: compatibilidad (selector eliminado)
    _G._saGunModeApply = _G._saGunModeApply or function(shootFn) pcall(shootFn) end

    -- Estado SA (guardado en CombatTabState para persistir entre pestaas)
    CombatTabState.silentAimEnabled  = CombatTabState.silentAimEnabled  or false
    CombatTabState.saTargetPart      = CombatTabState.saTargetPart      or "Head"
    -- Todos los toggles de prediccin OFF por defecto para no interferir con el disparo
    CombatTabState.saUsePrediction   = CombatTabState.saUsePrediction   ~= nil and CombatTabState.saUsePrediction or false
    CombatTabState.saPredJump        = CombatTabState.saPredJump        ~= nil and CombatTabState.saPredJump or false
    CombatTabState.saPredAccel       = CombatTabState.saPredAccel       ~= nil and CombatTabState.saPredAccel or false
    CombatTabState.saPredTrend       = CombatTabState.saPredTrend       ~= nil and CombatTabState.saPredTrend or false
    CombatTabState.saPredLag         = CombatTabState.saPredLag         ~= nil and CombatTabState.saPredLag or false
    CombatTabState.saPredStrafe      = CombatTabState.saPredStrafe      ~= nil and CombatTabState.saPredStrafe or false
    CombatTabState.gunPredMode       = CombatTabState.gunPredMode       or "Default"

    -- FIX: sincronizar _tiancaPredStrength con el estado guardado de Tianca al reabrir pestaa
    -- Evita que quede un valor viejo si el toggle fue apagado en otra sesin
    do
        local _tpSaved = CombatTabState.tiancaPred
        if _tpSaved and _tpSaved.enabled then
            _G._tiancaPredStrength = (_tpSaved.strength or 65) / 100
        else
            _G._tiancaPredStrength = 0
        end
    end

    -- Alias local para este tab
    CombatState = CombatTabState

    -- -- Funcin que calcula el targetCFrame al objetivo -------------------
    -- ==========================================================================
    -- SNAPSHOT SYSTEM  Anti-MovedPlayer v2
    -- Problema: entre MouseButton1Down (click) y FireServer hay 1-3 frames (~16-50ms).
    -- En ese tiempo el target se desplaz y el disparo falla.
    --
    -- Solucin en 2 capas:
    --   1. InputBegan congela un snapshot {pos, vel, t} en el frame exacto del click.
    --   2. En el __namecall, dead-reckoning: pos_real ~ snapPos + snapVel * (now - snapT).
    --      Si el snap tiene > 100ms de edad -> usar posicin live directa.
    -- ==========================================================================
    -- FIX Bugs 3 y 4: _saClickSnap y _saInputConn en _G, NO como local.
    -- Problema anterior: cada recarga del tab de Combat creaba una nueva closure
    -- con su propio _saClickSnap local (nil). El __namecall hook de la closure VIEJA
    -- segua vivo y apuntaba al snap viejo -> siempre nil -> fallback live sin dead-reckoning.
    -- Adems _saHookInput haca 'if _saInputConn then return' pero _saInputConn era
    -- una nueva local nil -> siempre creaba otra conexin InputBegan -> 2+ listeners
    -- pisndose mutuamente y sobrescribiendo el snap con datos incorrectos.
    -- Solucin: compartir tanto snap como conn en _G para que persistan entre recargas.
    if _G._saClickSnap == nil then _G._saClickSnap = nil end  -- inicializar solo 1 vez
    local _SA_SNAP_TTL = 0.18 -- segundos; si el snap es ms viejo -> ignorar

    -- Hook InputBegan para capturar el snap en el frame del click
    -- Limpiar conexin previa si existe (evitar listeners duplicados)
    if _G._saInputConn then
        pcall(function() _G._saInputConn:Disconnect() end)
        _G._saInputConn = nil
    end
    local function _saHookInput()
        if _G._saInputConn then return end
        _G._saInputConn = UserInputService.InputBegan:Connect(function(input, gp)
            if gp then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
               and input.UserInputType ~= Enum.UserInputType.Touch
               and input.KeyCode ~= Enum.KeyCode.ButtonR2 then return end
            if not CombatTabState.silentAimEnabled then return end

            -- Capturar estado exacto del target en este frame
            local tgt = findMurderer()
            if not tgt or not tgt.Character then return end
            local tHRP = tgt.Character:FindFirstChild("HumanoidRootPart")
            if not tHRP then return end
            local partName = CombatState.saTargetPart or CombatTabState.saTargetPart or "Head"
            local tPart = tgt.Character:FindFirstChild(partName)
                       or tgt.Character:FindFirstChild("Head") or tHRP
            local vel  = tHRP.AssemblyLinearVelocity or Vector3.zero
            local uid2 = tgt.UserId or 0
            local h2   = _getHist and _getHist(uid2)
            local pVel = (h2 and h2.emaVelXZ)
                and Vector3.new(h2.emaVelXZ.X, (h2.emaVelY and h2.emaVelY.Y or 0), h2.emaVelXZ.Z)
                or vel
            _G._saClickSnap = {
                pos     = tPart.Position,
                hrpPos  = tHRP.Position,
                vel     = vel,
                prevVel = pVel,
                t       = os.clock(),
                target  = tgt,
                tPart   = tPart,
                tHRP    = tHRP,
            }
        end)
    end
    _saHookInput()

    -- Helper: construir CFrames robustos desde origen -> targetPos
    -- _buildSACFrames: replica exacta del GunClient 2
    -- graCF = GunRaycastAttachment.WorldCFrame con LookVector apuntando al target
    -- targetCF = CFrame en targetPos mirando de vuelta al origen (como WeaponService:GetMouseTargetCFrame)
    local function _buildSACFrames(origin, targetPos, graWorldCF)
        local dir = targetPos - origin
        if dir.Magnitude < 0.01 then return nil, nil end
        local dirU = dir.Unit
        local upV  = math.abs(dirU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis

        -- graCF: si tenemos el WorldCFrame real del attachment, reorientarlo hacia el target
        -- Esto replica exactamente: GunRaycastAttachment.WorldCFrame siendo la base
        -- con el LookVector corregido para apuntar al target
        local graCF
        if graWorldCF then
            -- Mantener la posicin exacta del attachment, solo reorientar LookVector
            graCF = CFrame.new(graWorldCF.Position) * CFrame.lookAt(Vector3.zero, dirU, upV)
        else
            graCF = CFrame.lookAt(origin, targetPos, upV)
        end

        -- targetCF: CFrame en la posicin del impacto, LookVector apunta al origen
        -- Replica WeaponService:GetMouseTargetCFrame() que el GunClient 2 usa
        local backDir = (origin - targetPos)
        local backU   = backDir.Magnitude > 0.01 and backDir.Unit or -dirU
        local bkUp    = math.abs(backU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
        local targetCF = CFrame.lookAt(targetPos, targetPos + backU, bkUp)

        return graCF, targetCF
    end

    -- -- _saGetTargetCF: retorna graCF y targetCF correctos para MM2 ---------
    -- MM2 GunClient usa esta firma: Shoot:FireServer(graCF, targetCF)
    --   graCF    = CFrame del punto de disparo (GunRaycastAttachment), LookVector apunta HACIA el target
    --   targetCF = CFrame en la posicin del impacto, LookVector apunta DE VUELTA al shooter
    -- Ambos CFrames deben apuntar exactamente a targetPos para que el servidor
    -- pueda validar la trayectoria sin inconsistencias.
    local function _saGetTargetCF()
        -- -- Encontrar target -------------------------------------------------
        local target = nil

        -- Custom Target: usar los mismos campos que el toggle "Use Custom Target"
        -- (saUseCustomTarget/saCustomTargetName eran campos separados que nunca se sincronizaban)
        local _ctEnabled = CombatTabState.useCustomTarget
                        or CombatTabState.saUseCustomTarget
        local _ctPlayer  = CombatTabState.customTargetPlayer

        if _ctEnabled and _ctPlayer and _ctPlayer.Parent then
            -- Target directo por referencia (mas fiable que buscar por nombre)
            target = _ctPlayer
        elseif _ctEnabled and CombatTabState.saCustomTargetName and CombatTabState.saCustomTargetName ~= "" then
            -- Fallback: buscar por nombre (compatibilidad con saCustomTargetName)
            for _, p in ipairs(_cachedPlayers) do
                if p.Name == CombatTabState.saCustomTargetName and p ~= LocalPlayer then
                    target = p; break
                end
            end
        end

        -- Si no hay custom target activo, usar murderer normal
        if not target then
            target = findMurderer()
        end
        -- FIX SHOOT ROTO: el fallback de knife agarraba cualquier jugador con Knife
        -- (en MM2 todos tienen knife), redirigiendo disparos a inocentes cuando
        -- no habia murderer en cache. Eliminado: si no hay murderer real, no hay target.
        if not target or not target.Character then return nil, nil end

        local tChar = target.Character
        local tHum  = tChar:FindFirstChildOfClass("Humanoid")
        if not tHum or tHum.Health <= 0 then return nil, nil end

        local tHRP = tChar:FindFirstChild("HumanoidRootPart")
        if not tHRP then return nil, nil end

        -- -- Parte objetivo ---------------------------------------------------
        local partName = CombatState.saTargetPart or CombatTabState.saTargetPart or "Head"
        local tPart    = tChar:FindFirstChild(partName)
                      or tChar:FindFirstChild("Head")
                      or tHRP

        -- -- Origen del disparo -----------------------------------------------
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return nil, nil end

        local gun = nil
        for _, t in ipairs(myChar:GetChildren()) do
            if t:IsA("Tool") and (_GUN_NAMES and _GUN_NAMES[t.Name] or t.Name:lower():find("gun")) then
                gun = t; break
            end
        end
        local gra        = getGunAttachment(gun, myHRP)
        local graWorldCF = gra and gra.WorldCFrame  -- CFrame completo para _buildSACFrames
        local origin     = graWorldCF and graWorldCF.Position
                        or (myHRP.Position + Vector3.new(0, 1.5, 0))

        -- -- Prediccin con snapshot dead-reckoning ----------------------------
        -- Capa 1: Si hay un snapshot fresco del click, extrapolar con dead-reckoning.
        --         snapPos + snapVel * dt da la posicin real al frame del FireServer.
        -- Capa 2: Si el snap es viejo o no existe, usar solver unificado live.
        -- Capa 3: Sin prediccin -> lead mnimo de ping.
        local targetPos
        local vel   = tHRP.AssemblyLinearVelocity or Vector3.new(0,0,0)
        local speed = vel.Magnitude
        local now   = os.clock()

        local _usePred = CombatTabState.saUsePrediction or false

        -- Invalidar cach compartida si el target del SA cambi respecto al del cach
        -- (evita usar prediccin de un target anterior cuando el murderer cambia)
        if _predCache.target and _predCache.target ~= target then
            _predCache.pos = nil; _predCache.ts = 0
        end

        -- -- Intentar dead-reckoning desde snapshot del click -----------------
        local _snapUsed = false
        if _G._saClickSnap
           and _G._saClickSnap.target == target
           and (now - _G._saClickSnap.t) < _SA_SNAP_TTL then
            local snap = _G._saClickSnap
            local dt   = now - snap.t
            -- Dead-reckoning: posicin_real ~ pos_en_click + vel_en_click * Dt
            -- Esto compensa exactamente los frames perdidos entre click y namecall.
            -- Dead-reckoning con aceleracin (pos + vel*dt + 0.5*accel*dt)
            local snapAccel = Vector3.zero
            if snap.prevVel then
                local aRaw = (snap.vel - snap.prevVel) / math.max(dt, 0.016)
                if aRaw.Magnitude < 400 then snapAccel = aRaw end
            end
            local drPos = snap.pos + snap.vel * dt + snapAccel * (0.5 * dt * dt)
            -- Clamp de seguridad dinmico segn ping:
            -- ping bajo (<60ms): 3 studs, alto (>150ms): 7 studs
            -- (evita extrapolacin errnea en cambio de direccin brusco)
            local _drClamp
            do
                local _pm = 60
                pcall(function() _pm = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
                _drClamp = math.clamp(_pm / 1000 * 32 * 1.5, 2.5, 7.0)  -- WalkSpeed32 * tof * 1.5
            end
            local drift = (drPos - snap.pos)
            if drift.Magnitude > _drClamp then
                drPos = snap.pos + drift.Unit * _drClamp
            end
            -- Clamp vertical respecto al HRP live (el jugador no puede estar muy lejos del suelo)
            drPos = Vector3.new(
                drPos.X,
                math.clamp(drPos.Y, tHRP.Position.Y - 2.5, tHRP.Position.Y + 5),
                drPos.Z
            )

            if _usePred then
                -- Leer flags reales del selector  antes estaban TODOS hardcodeados a true
                local _tHumJump = tChar:FindFirstChildOfClass("Humanoid")
                local _tStateJump = _tHumJump and _tHumJump:GetState()
                local _tInAir = not _isGrounded(tHRP)
                             or _tStateJump == Enum.HumanoidStateType.Jumping
                             or _tStateJump == Enum.HumanoidStateType.Freefall
                local flags = {
                    usePrediction = CombatTabState.saUsePrediction and true or false,
                    predictJump   = CombatTabState.saUsePrediction and CombatTabState.saPredJump   and _tInAir or false,
                    predictAccel  = CombatTabState.saUsePrediction and CombatTabState.saPredAccel  or false,
                    predictTrend  = CombatTabState.saUsePrediction and CombatTabState.saPredTrend  or false,
                    predictLag    = CombatTabState.saUsePrediction and CombatTabState.saPredLag    or false,
                    predictStrafe = CombatTabState.saUsePrediction and CombatTabState.saPredStrafe or false,
                }
                local predicted, _, _ = _unifiedBalisticSolver(tPart, tHRP, flags, target)
                if predicted and predicted == predicted
                   and (predicted - tHRP.Position).Magnitude < 120 then
                    -- Blend: 75% solver v3 (latencia red + historial) + 25% dead-reckoning (latencia frame)
                    -- El solver ya incluye posHistory -> el DR aporta poco pero corrige frames perdidos
                    local _snapAge  = now - snap.t
                    local _drW = math.clamp(1 - (_snapAge / 0.060), 0.10, 0.30)
                    targetPos = predicted:Lerp(drPos, _drW)
                else
                    targetPos = drPos
                end
            else
                -- Sin prediccin: usar dead-reckoning puro + lead de ping mnimo
                local _pingMs = 60
                pcall(function() _pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
                -- Prioritize Your Ping: usar exclusivamente nuestro ping sin estimar el del target
                -- Ping Sensitivity: escala el lead por el slider
                local _pSens = (_G._saPingSensitivity or 1.0)
                local _pSec = _pingMs / 1000 * _pSens
                -- Lead de ping sobre la velocidad del snapshot (ms precisa que vel live)
                local lead = Vector3.new(snap.vel.X * _pSec, 0, snap.vel.Z * _pSec)
                targetPos = drPos + lead
            end
            _snapUsed = true
        end

        -- -- Fallback: sin snapshot vlido -> solver live -----------------------
        if not _snapUsed then
            -- FIX: garantizar targetPos siempre vlido antes del solver
            if not targetPos then targetPos = tPart and tPart.Position or tHRP.Position end
            if _usePred then
                local _tHumJump = tChar:FindFirstChildOfClass("Humanoid")
                local _tStateJump = _tHumJump and _tHumJump:GetState()
                local _tInAir = not _isGrounded(tHRP)
                             or _tStateJump == Enum.HumanoidStateType.Jumping
                             or _tStateJump == Enum.HumanoidStateType.Freefall
                -- Leer flags reales del selector  antes estaban TODOS hardcodeados a true
                local flags = {
                    usePrediction = CombatTabState.saUsePrediction and true or false,
                    predictJump   = CombatTabState.saUsePrediction and CombatTabState.saPredJump   and _tInAir or false,
                    predictAccel  = CombatTabState.saUsePrediction and CombatTabState.saPredAccel  or false,
                    predictTrend  = CombatTabState.saUsePrediction and CombatTabState.saPredTrend  or false,
                    predictLag    = CombatTabState.saUsePrediction and CombatTabState.saPredLag    or false,
                    predictStrafe = CombatTabState.saUsePrediction and CombatTabState.saPredStrafe or false,
                }
                local predicted, _, _ = _unifiedBalisticSolver(tPart, tHRP, flags, target)
                if predicted and predicted == predicted
                   and (predicted - tHRP.Position).Magnitude < 120 then
                    targetPos = predicted
                else
                    targetPos = tPart.Position
                end
            elseif speed > 0.3 then
                -- Lead mnimo: ping one-way + server tick (16.6ms)
                local _pingMs = 60
                pcall(function() _pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 500) end)
                -- Ping Sensitivity: escala el lead de ping seg?n el slider
                local _pSens = (_G._saPingSensitivity or 1.0)
                local _pSec = (_pingMs + 16.6) / 1000 * _pSens
                targetPos = tPart.Position + Vector3.new(vel.X * _pSec, 0, vel.Z * _pSec)
            else
                targetPos = tPart.Position
            end
        end

        -- FIX: garantizar que targetPos nunca sea nil antes de los guards
        if not targetPos or targetPos ~= targetPos then
            targetPos = (tPart and tPart.Position) or tHRP.Position
        end

        -- Floor/Ceiling guard: solo clampear si la prediccin es claramente invlida.
        -- En salto, el solver ya calcula la trayectoria correcta -> no interferir.
        local _tHumG = tChar:FindFirstChildOfClass("Humanoid")
        local _tIsAir = not _isGrounded(tHRP)
            or (_tHumG and (_tHumG:GetState() == Enum.HumanoidStateType.Jumping
                         or _tHumG:GetState() == Enum.HumanoidStateType.Freefall))
        -- Floor: nunca apuntar debajo del suelo del mapa (salvo en cada libre profunda)
        local _floorMin = _tIsAir and (tHRP.Position.Y - 12) or (tHRP.Position.Y - 3)
        if targetPos.Y < _floorMin then
            targetPos = Vector3.new(targetPos.X, tHRP.Position.Y + (_tIsAir and 0.5 or 0), targetPos.Z)
        end
        -- Ceiling: solo clampear si la prediccin se fue a ms de 16 studs sobre el HRP
        -- (el solver puede predecir hasta ~12 studs arriba en salto alto -> margen generoso)
        local _ceilingMax = tHRP.Position.Y + (_tIsAir and 16 or 6)
        if targetPos.Y > _ceilingMax then
            targetPos = Vector3.new(targetPos.X, tPart.Position.Y, targetPos.Z)
        end

        -- -- Wall check -------------------------------------------------------
        if CombatState.saWallCheck then
            if not wallCheckRaycast(origin, targetPos) then return nil, nil end
        end

        -- Invalidar snapshot tras usarlo (un solo disparo por click)
        _G._saClickSnap = nil

        if _usePred then -- SOLO aplicar mults cuando prediction esta activa
        -- -- Aplicar multiplicadores de prediccin avanzada (sliders del hub) -
        do
            local _hM  = CombatState.gunHorizAimMult  or 1.0
            local _vM  = CombatState.gunVertAimMult   or 1.0
            local _dHn = CombatState.gunPredDivHMin   or 0
            local _dHx = CombatState.gunPredDivHMax   or 0
            local _mPD = CombatState.gunMaxPredDist   or 999
            local _vPM = CombatState.gunVertPredMult  or 1.0
            local _lC  = CombatState.gunLatencyComp   or 1.0
            local _sS  = CombatState.gunStrafeScale   or 1.0
            local _aB  = CombatState.gunAccelBias     or 0
            local _jL  = CombatState.gunJumpLead      or 1.0

            -- Calcular offset desde HRP del target
            local baseOffset = targetPos - tHRP.Position
            local dist = (targetPos - origin).Magnitude

            -- Clamp de distancia mxima de prediccin
            local _distScale = 1.0
            if _mPD > 0 and dist > _mPD then
                _distScale = _mPD / dist
            end

            -- Horizontal multiplier sobre el offset XZ
            local horiz = Vector3.new(baseOffset.X * _hM, 0, baseOffset.Z * _hM)

            -- Vertical multiplier (jump lead + vert prediction)
            local _tHumJG = tChar:FindFirstChildOfClass("Humanoid")
            local _tIsAirG = not _isGrounded(tHRP)
                or (_tHumJG and (_tHumJG:GetState() == Enum.HumanoidStateType.Jumping
                             or _tHumJG:GetState() == Enum.HumanoidStateType.Freefall))
            local vertBase = baseOffset.Y * _vM * _vPM
            if _tIsAirG then vertBase = vertBase * _jL end

            -- Divisor horizontal aleatorio entre Min y Max (si ambos > 0)
            if _dHn > 0 and _dHx > 0 then
                local _divPct = _dHn + math.random() * math.abs(_dHx - _dHn)
                local _scale  = _divPct / 100
                horiz = Vector3.new(
                    tHRP.Position.X + (targetPos.X - tHRP.Position.X) * _scale,
                    0,
                    tHRP.Position.Z + (targetPos.Z - tHRP.Position.Z) * _scale
                ) - Vector3.new(tHRP.Position.X, 0, tHRP.Position.Z)
                -- Reaplica mult horizontal encima del divisor
                horiz = horiz * _hM
            end

            -- Latency compensation: escalar el offset completo segn ping
            local _pingMs = 60
            pcall(function() _pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 500) end)
            local _lcScale = 1.0 + (_pingMs / 1000) * (_lC - 1.0)

            -- Strafe scale: escalar componente perpendicular al look del target
            local _tLook = tHRP.CFrame.LookVector
            local _perpH = Vector3.new(-_tLook.Z, 0, _tLook.X)
            local _strafeComp = horiz:Dot(_perpH)
            horiz = horiz + _perpH * (_strafeComp * (_sS - 1.0))

            -- Accel bias: adicionar offset extra segn aceleracin del target
            local _tVel = tHRP.AssemblyLinearVelocity or Vector3.new(0,0,0)
            local _accelBiasOff = Vector3.new(_tVel.X * _aB * 0.016, 0, _tVel.Z * _aB * 0.016)

            -- Ensamblar targetPos final
            targetPos = tHRP.Position
                + (horiz + _accelBiasOff) * _lcScale * _distScale
                + Vector3.new(0, vertBase, 0)

            -- Re-aplicar floor/ceiling guard tras multiplicadores
            local _floorMinG = _tIsAirG and (tHRP.Position.Y - 12) or (tHRP.Position.Y - 3)
            local _ceilMaxG  = tHRP.Position.Y + (_tIsAirG and 16 or 6)
            targetPos = Vector3.new(
                targetPos.X,
                math.clamp(targetPos.Y, _floorMinG, _ceilMaxG),
                targetPos.Z
            )
        end
        end -- fin if _usePred (multiplicadores)
        -- -- FIN multiplicadores ----------------------------------------------

        -- -- Construir CFrames con helper robusto -----------------------------
        return _buildSACFrames(origin, targetPos, graWorldCF)
    end

    -- -- Hook __namecall para interceptar Shoot:FireServer -----------------
    -- Cuando el juego llama Parent_upvr.Shoot:FireServer(graCF, targetCF)
    -- reemplazamos el segundo argumento (targetCF) con nuestro _saGetTargetCF()
    -- BUGFIX double-hook: persistir estado en CombatTabState para no resetear al cambiar tab
    if CombatTabState._saHookActive == nil then CombatTabState._saHookActive = false end
    if CombatTabState._saOldNamecall == nil then CombatTabState._saOldNamecall = nil end
    if CombatTabState._saMt == nil then CombatTabState._saMt = nil end
    _saHookActive    = false  -- local shadow (solo para lectura inicial)
    _saOldNamecall   = CombatTabState._saOldNamecall
    _saMt            = CombatTabState._saMt

    local function _saApplyHook()
        -- FIX Bug 3: si _saHookActive es true pero _saOldNamecall es nil,
        -- significa que el estado qued inconsistente (ej: tab recargado sin cleanup).
        -- Resetear el flag para permitir re-hookear limpiamente.
        if CombatTabState._saHookActive and not CombatTabState._saOldNamecall then
            CombatTabState._saHookActive = false
        end
        if CombatTabState._saHookActive then return end  -- ya hookeado correctamente
        if not (hookmetamethod and getrawmetatable and setreadonly and newcclosure and getnamecallmethod) then
 CreateCustomNotification("SILENT AIM", " Executor sin hookmetamethod", 3)
            return false
        end
        local mt = getrawmetatable(game)
        -- FIX re-ejecuci?n: guardar el namecall REAL solo una vez en _G.
        -- Si el script se re-ejecuta sin que _saRemoveHook corriera,
        -- mt.__namecall ya es nuestro hook anterior -> capturarlo como "original"
        -- romper?a la cadena (el disparo nunca llegar?a al juego).
        -- _G._saRealNamecall guarda el namecall verdadero del juego desde la primera vez.
        if not _G._saRealNamecall then
            _G._saRealNamecall = mt.__namecall
        end
        local _saOldNamecall_local = _G._saRealNamecall
        setreadonly(mt, false)
        mt.__namecall = newcclosure(function(self, ...)
            -- Solo interceptar FireServer cuando SA est activo
            -- Para TODO lo dems: pasar ... SIN TOCAR (no convertir a tabla)
            local _orig = _saOldNamecall_local

            if not CombatTabState.silentAimEnabled or CombatTabState._saBypassHook then
                return _orig(self, ...)
            end

            local method
            pcall(function() method = getnamecallmethod() end)
            if method ~= "FireServer" then
                return _orig(self, ...)
            end

            -- Solo a partir de aqu guardamos args en tabla (solo para FireServer)
            local _args = {...}

            local selfOk  = false
            local selfName = ""
            pcall(function()
                selfName = self.Name
                local _ = self.Parent
                selfOk = self:IsA("RemoteEvent")
            end)
            if not selfOk then
                return _orig(self, ...)
            end

            -- FIX desync: check rapido SOLO por nombre del remote (sin loops)
            -- No usar IsDescendantOf ni GetChildren porque corre en CADA __namecall (cientos/seg)
            -- FIX #6: removidos GunKill y FakeShoot - son eventos de resultado gameplay (server->client),
            -- NO remotes de disparo. Interceptarlos corrompia su payload y rompia death detection.
            local _SHOOT_REMOTES = {
                shoot       = true,
                gunshoot    = true,
                playershot  = true,
                bulletfire  = true,
                gunfire     = true,
                shootremote = true,
            }
            local isGunRemote = _SHOOT_REMOTES[selfName:lower()] == true

            -- KNIFE SA MOBILE: interceptar Events/Throw (el remote que dispara el lanzamiento en mobile)
            -- Cuando el juego llama Throw:FireServer(), lo suprimimos y en su lugar
            -- llamamos KnifeThrown:FireServer(handleCF, targetCF) con direccion SA.
            if selfName == "Throw" and KnifeSAState and KnifeSAState.enabled then
                -- FIX: si _saBypassHook esta activo significa que _ksaFireKnife ya envio
                -- KnifeThrown directamente (VIA 1). Dejar pasar Throw:FireServer() al servidor
                -- sin volver a disparar KnifeThrown (evita doble disparo).
                if CombatTabState and CombatTabState._saBypassHook then
                    return _orig(self, ...)
                end
                local _intercepted = false
                pcall(function()
                    local myChar = LocalPlayer.Character
                    if not myChar then return end
                    local knife = myChar:FindFirstChild("Knife")
                    if not knife then return end
                    -- Verificar que self es el Events/Throw del knife del local player
                    if not self:IsDescendantOf(knife) then return end
                    local events = knife:FindFirstChild("Events") or knife
                    local knifeThrown = events:FindFirstChild("KnifeThrown")
                    if not knifeThrown then return end
                    local myHRP = myChar:FindFirstChild("HumanoidRootPart")
                    if not myHRP then return end
                    local target = _KnifeSA_getBestTarget and _KnifeSA_getBestTarget()
                    local handleCF, targetCF
                    if target and target.Character then
                        local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                        local tHum = target.Character:FindFirstChildOfClass("Humanoid")
                        if tHRP and tHum and tHum.Health > 0 then
                            local predictedPos = _KnifeSA_getPredictedPos and _KnifeSA_getPredictedPos(tHRP, target.Character) or tHRP.Position
                            local orig = myHRP.Position + Vector3.new(0, 1.5, 0)
                            local aimVec = predictedPos - orig
                            if aimVec.Magnitude < 0.01 then aimVec = myHRP.CFrame.LookVector end
                            handleCF = CFrame.new(orig, orig + aimVec.Unit)
                            local back = orig - predictedPos
                            targetCF = back.Magnitude > 0.1 and CFrame.new(predictedPos, predictedPos + back.Unit) or CFrame.new(predictedPos)
                        end
                    end
                    if not targetCF then
                        -- Sin target: dejar pasar el Throw original sin modificar
                        return
                    end
                    -- Suprimir el Throw original y disparar KnifeThrown con SA
                    pcall(function() knifeThrown:FireServer(handleCF, targetCF) end)
                    _intercepted = true
                end)
                if _intercepted then
                    -- Throw suprimido: KnifeThrown ya fue enviado con SA, no llamar _orig
                    return
                end
                -- Sin target SA o error: dejar pasar el Throw original intacto
                return _orig(self, ...)
            end

            if not isGunRemote then
                return _orig(self, ...)
            end

            -- Es un remote de gun: aplicar Silent Aim
            -- FIX CRITICO: Spoof Method esta FUERA del pcall para que su
            -- "return _orig" salga del namecall, no del pcall interno.
            -- Antes estaba dentro del pcall -> el return era ignorado y
            -- _orig se llamaba dos veces (doble disparo) o nunca (gun rota).

            if CombatTabState.saUseSpoofMethod then
                -- Intentar obtener target; si no hay, disparar normal sin tocar
                local ok, newGraCF, newTargetCF = pcall(_saGetTargetCF)
                if ok and newGraCF and newTargetCF then
                    local originPos    = newGraCF.Position
                    local newTargetPos = newTargetCF.Position
                    -- Enviar FireServer spoof apuntando al target real
                    local spoofOCF, spoofTCF = _buildSACFrames(originPos, newTargetPos)
                    if spoofOCF and spoofTCF then
                        CombatTabState._saBypassHook = true
                        pcall(_orig, self, spoofOCF, spoofTCF)
                        CombatTabState._saBypassHook = false
                    end
                    -- Ammo fix
                    pcall(function()
                        local myChar2 = LocalPlayer.Character
                        if not myChar2 then return end
                        for _, g2 in ipairs(myChar2:GetChildren()) do
                            if g2:IsA("Tool") then
                                local ammo2 = g2:FindFirstChild("Ammo")
                                if ammo2 and ammo2.Value <= 0 then
                                    local mx = g2:FindFirstChild("MaxAmmo")
                                    ammo2.Value = mx and mx.Value or 8
                                end
                            end
                        end
                    end)
                    CombatTabState.totalShots = (CombatTabState.totalShots or 0) + 1
                    if _G._bulletTracerDraw and originPos and newTargetPos then
                        _sp(function() pcall(_G._bulletTracerDraw, originPos, newTargetPos) end)
                    end
                end
                -- Siempre dejar pasar el disparo original del cliente (con args sin tocar)
                -- Esto mantiene animacion, sonido y cooldown funcionando normalmente.
                return _orig(self, table.unpack(_args))
            end

            -- Modo hook normal (no Spoof): modificar args en pcall y disparar una sola vez
            -- FIX v11: trabajar sobre copia de _args para evitar modificaci?n parcial
            -- si _buildSACFrames falla a mitad ? el disparo original nunca queda roto
            local _argsCopy = {table.unpack(_args)}
            local _saApplied = false
            pcall(function()
                local newGraCF, newTargetCF = _saGetTargetCF()
                if not (newTargetCF and newGraCF) then return end
                local newTargetPos = newTargetCF.Position
                local originPos    = newGraCF.Position
                local cfIdx = {}
                for i, v in ipairs(_argsCopy) do
                    if typeof(v) == "CFrame" then cfIdx[#cfIdx+1] = i end
                end
                if #cfIdx >= 2 then
                    local graCF_live, targetCF_live = _buildSACFrames(originPos, newTargetPos)
                    -- FIX v11: solo aplicar si AMBOS CFrames son v?lidos
                    if graCF_live and targetCF_live then
                        _argsCopy[cfIdx[1]] = graCF_live
                        _argsCopy[cfIdx[2]] = targetCF_live
                        _saApplied = true
                    end
                elseif #cfIdx == 1 then
                    local graCF_live = _buildSACFrames(originPos, newTargetPos)
                    if graCF_live then
                        _argsCopy[cfIdx[1]] = graCF_live
                        _saApplied = true
                    end
                end
                if _saApplied then
                    local myChar2 = LocalPlayer.Character
                    if not myChar2 then return end
                    for _, g2 in ipairs(myChar2:GetChildren()) do
                        if g2:IsA("Tool") then
                            local ammo2 = g2:FindFirstChild("Ammo")
                            if ammo2 and ammo2.Value <= 0 then
                                local mx = g2:FindFirstChild("MaxAmmo")
                                ammo2.Value = mx and mx.Value or 8
                            end
                        end
                    end
                    CombatTabState.totalShots = (CombatTabState.totalShots or 0) + 1
                    if _G._bulletTracerDraw and originPos and newTargetPos then
                        _sp(function() pcall(_G._bulletTracerDraw, originPos, newTargetPos) end)
                    end
                end
            end)

            -- FIX v11: si el SA no pudo aplicarse (sin target, sin murderer, error interno),
            -- disparar con los args ORIGINALES intactos para no romper el disparo normal.
            -- Si el SA s? se aplic?, disparar con los args modificados (apuntando al murderer).
            return _orig(self, table.unpack(_saApplied and _argsCopy or _args))
        end)
        setreadonly(mt, true)
        CombatTabState._saHookActive = true
        CombatTabState._saOldNamecall = _saOldNamecall_local
        CombatTabState._saMt = mt
        return true
    end

    local function _saRemoveHook()
        local _oldNC = CombatTabState._saOldNamecall
        local _mt    = CombatTabState._saMt
        if not CombatTabState._saHookActive or not _mt or not _oldNC then return end
        pcall(function()
            setreadonly(_mt, false)
            _mt.__namecall = _oldNC
            setreadonly(_mt, true)
        end)
        CombatTabState._saHookActive   = false
        CombatTabState._saOldNamecall  = nil
        CombatTabState._saMt           = nil
        -- Limpiar snapshot y conexin de input al desactivar
        _G._saClickSnap = nil
        if _G._saInputConn then
            pcall(function() _G._saInputConn:Disconnect() end)
            _G._saInputConn = nil
        end
    end

    -- Restaurar hook si ya estaba activo al reabrir la pestaa
    if CombatTabState.silentAimEnabled and not CombatTabState._saHookActive then
        _saApplyHook()
    end

    -- -- MTODO DE SILENT AIM ---------------------------------------------
    -- Inicializar estados si no existen
    CombatTabState.saUseHookMethod    = CombatTabState.saUseHookMethod    ~= nil and CombatTabState.saUseHookMethod    or false
    CombatTabState.saUseSpoofMethod   = CombatTabState.saUseSpoofMethod   ~= nil and CombatTabState.saUseSpoofMethod   or false
    CombatTabState.saUseCustomTarget  = CombatTabState.saUseCustomTarget  ~= nil and CombatTabState.saUseCustomTarget  or false
    CombatTabState.saCustomTargetName = CombatTabState.saCustomTargetName or ""

    do
        -- -- Fila informativa de mtodo ------------------------------------
        local function _makeMethodInfoRow(parent, icon, title, desc, color)
            local row = Instance.new("Frame", parent)
            row.Size = UDim2.new(1, -8, 0, 0)
            row.AutomaticSize = Enum.AutomaticSize.Y
            row.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
            row.BackgroundTransparency = 0.5
            row.BorderSizePixel = 0
            row.ZIndex = 13
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)
            local rs = Instance.new("UIStroke", row)
            rs.Color = color or ThemeColors.Primary
            rs.Thickness = 1
            rs.Transparency = 0.6
            local rpad = Instance.new("UIPadding", row)
            rpad.PaddingLeft = UDim.new(0, 8)
            rpad.PaddingRight = UDim.new(0, 8)
            rpad.PaddingTop = UDim.new(0, 5)
            rpad.PaddingBottom = UDim.new(0, 5)

            local titleLbl = Instance.new("TextLabel", row)
            titleLbl.Size = UDim2.new(1, 0, 0, 16)
            titleLbl.BackgroundTransparency = 1
            titleLbl.Text = icon .. "  " .. title
            titleLbl.TextColor3 = color or ThemeColors.Accent
            titleLbl.Font = Enum.Font.GothamBold
            titleLbl.TextSize = 12
            titleLbl.TextXAlignment = Enum.TextXAlignment.Left
            titleLbl.ZIndex = 14

            local descLbl = Instance.new("TextLabel", row)
            descLbl.Size = UDim2.new(1, 0, 0, 0)
            descLbl.Position = UDim2.new(0, 0, 0, 18)
            descLbl.AutomaticSize = Enum.AutomaticSize.Y
            descLbl.BackgroundTransparency = 1
            descLbl.Text = desc
            descLbl.TextColor3 = Color3.fromRGB(255, 200, 200)
            descLbl.Font = Enum.Font.Montserrat
            descLbl.TextSize = 10
            descLbl.TextXAlignment = Enum.TextXAlignment.Left
            descLbl.TextWrapped = true
            descLbl.ZIndex = 14
            return row
        end

    end

    -- -- Spoof Method toggle -----------------------------------------------
    -- Cuando est? activo, en lugar de redirigir el FireServer original,
    -- se env?a un FireServer paralelo (spoof) apuntando al target real y
    -- el disparo original pasa sin modificar. M?s dif?cil de detectar
    -- server-side porque el argumento visible del cliente no cambia.
    -- =====================================================================

    CreatePremiumToggle(silentAimSection, "Spoof Method", function(enabled)
        CombatTabState.saUseSpoofMethod = enabled
        if enabled then
            CreateCustomNotification("SILENT AIM", "Spoof Method ON ? Fake FireServer to target", 3)
        else
            CreateCustomNotification("SILENT AIM", "Spoof Method OFF ? modo hook normal", 2)
        end
    end, CombatTabState.saUseSpoofMethod)


    -- =====================================================================
    -- NUEVO TOGGLE: SILENT AIM (bot?n Shoot Murderer)
    -- Al activar: crea el bot?n "Shoot Murderer" en pantalla.
    -- Al presionar el bot?n: redirige la bala al murder usando Silent Aim.
    -- =====================================================================
    do
        local _saSMState = { enabled = false, gui = nil, dragging = false }

        local function _destroySASMGui()
            if _saSMState.gui then
                pcall(function() _saSMState.gui:Destroy() end)
                _saSMState.gui = nil
            end
            pcall(function()
                for _, g in ipairs(CoreGui:GetChildren()) do
                    if g.Name == "SilentAimShootMurderGui" then g:Destroy() end
                end
            end)
            pcall(function()
                for _, g in ipairs(LocalPlayer.PlayerGui:GetChildren()) do
                    if g.Name == "SilentAimShootMurderGui" then g:Destroy() end
                end
            end)
        end

        local function _doSilentAimShoot()
            task.spawn(function()
                local myChar = LocalPlayer.Character
                if not myChar then return end
                local myHum = myChar:FindFirstChildOfClass("Humanoid")
                if not myHum or myHum.Health <= 0 then return end
                local myHRP = myChar:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end

                -- Encontrar el murderer (target)
                local target = findMurderer and findMurderer()
                if not target or not target.Character then
                    CreateCustomNotification("SILENT AIM", "No hay Murder detectado", 1.5)
                    return
                end
                local tChar = target.Character
                local tHum  = tChar:FindFirstChildOfClass("Humanoid")
                if not tHum or tHum.Health <= 0 then
                    CreateCustomNotification("SILENT AIM", "Murder sin vida", 1.5)
                    return
                end
                local tHRP = tChar:FindFirstChild("HumanoidRootPart")
                if not tHRP then return end

                -- Buscar gun en mano o backpack
                local gun = _findGunIn and _findGunIn(myChar)
                local _wasInBackpack = false
                if not gun then
                    local gunBP = _findGunIn and _findGunIn(LocalPlayer.Backpack)
                    if gunBP then
                        _wasInBackpack = true
                        pcall(function() myHum:EquipTool(gunBP) end)
                        task.wait(0.06)
                        gun = _findGunIn and _findGunIn(myChar)
                    end
                end
                if not gun then
                    CreateCustomNotification("SILENT AIM", "No hay Gun disponible", 1.5)
                    return
                end

                -- Calcular posici?n objetivo usando la l?gica del Silent Aim existente
                local partName = (CombatTabState and CombatTabState.saTargetPart) or "Head"
                local tPart    = tChar:FindFirstChild(partName) or tChar:FindFirstChild("Head") or tHRP

                -- Determinar targetPos con predicci?n si est? activa
                local targetPos
                if CombatTabState and CombatTabState.saUsePrediction and _getCachedPrediction then
                    local predPos = _getCachedPrediction(target)
                    targetPos = predPos or tPart.Position
                else
                    targetPos = tPart.Position
                end

                -- Obtener origen del disparo (GunRaycastAttachment o HRP)
                local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP)
                local graWorldCF = barrelAtt and barrelAtt.WorldCFrame
                local originPos = (barrelAtt and barrelAtt.WorldPosition)
                    or (myHRP.Position + Vector3.new(0, 1.5, 0))

                -- Construir los CFrames de disparo
                local function _buildCF(orig, tgtPos, graWCF)
                    local dir = tgtPos - orig
                    if dir.Magnitude < 0.01 then return nil, nil end
                    local dirU = dir.Unit
                    local upV  = math.abs(dirU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
                    local graCF_new
                    if graWCF then
                        graCF_new = CFrame.new(graWCF.Position) * CFrame.lookAt(Vector3.zero, dirU, upV)
                    else
                        graCF_new = CFrame.lookAt(orig, tgtPos, upV)
                    end
                    local backDir = (orig - tgtPos)
                    local backU   = backDir.Magnitude > 0.01 and backDir.Unit or -dirU
                    local bkUp    = math.abs(backU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
                    local tgtCF   = CFrame.lookAt(tgtPos, tgtPos + backU, bkUp)
                    return graCF_new, tgtCF
                end

                local oCF, tCF = _buildCF(originPos, targetPos, graWorldCF)

                if oCF and tCF then
                    -- Intentar disparo via remote "Shoot" (m?todo principal MM2)
                    local shootRem = gun:FindFirstChild("Shoot")
                    if not shootRem then
                        for _, v in ipairs(gun:GetDescendants()) do
                            if v:IsA("RemoteEvent") then shootRem = v; break end
                        end
                    end
                    if not shootRem and getShootRemote then
                        shootRem = getShootRemote(gun)
                    end

                    if shootRem and shootRem:IsA("RemoteEvent") then
                        -- FIX: bypass el __namecall hook del SA para evitar doble
                        -- intercepcion y rotura del GunFired. El boton ya calculo
                        -- los CFrames correctos, no necesita ser redirigido de nuevo.
                        if CombatTabState then CombatTabState._saBypassHook = true end
                        pcall(function() shootRem:FireServer(oCF, tCF) end)
                        if CombatTabState then CombatTabState._saBypassHook = false end
                    else
                        -- Fallback: _fireGunMM2
                        if _fireGunMM2 then
                            if CombatTabState then CombatTabState._saBypassHook = true end
                            _fireGunMM2(gun, tCF)
                            if CombatTabState then CombatTabState._saBypassHook = false end
                        end
                    end
                    -- Desequipar si vino del backpack
                    if _wasInBackpack and myHum and myHum.Parent then
                        task.delay(0.17, function()
                            pcall(function() myHum:UnequipTools() end)
                        end)
                    end
                    CreateCustomNotification("SILENT AIM", "Bala redirigida -> " .. target.Name, 1.5)
                else
                    -- Fallback sin CFrame v?lido
                    if _fireGunMM2 then _fireGunMM2(gun) end
                end
            end)
        end

        local function _createSASMButton()
            _destroySASMGui()

            -- BOT?N PERSONALIZADO: transparente con borde oscuro y esquinas redondeadas
            local BTN_W, BTN_H = 130, 70
            local vp = workspace.CurrentCamera.ViewportSize
            local posX = math.clamp(vp.X * 0.5 - BTN_W / 2, 4, vp.X - BTN_W - 4)
            local posY = math.clamp(vp.Y * 0.5 - BTN_H / 2, 4, vp.Y - BTN_H - 4)

            local sg = Instance.new("ScreenGui")
            sg.Name           = "SilentAimShootMurderGui"
            sg.ResetOnSpawn   = false
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            sg.IgnoreGuiInset = true
            sg.DisplayOrder   = 9997
            pcall(function() sg.Parent = CoreGui end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _saSMState.gui = sg

            -- Contenedor raiz
            local btnRoot = Instance.new("Frame", sg)
            btnRoot.Name                   = "ShootMurderBtn"
            btnRoot.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            btnRoot.Position               = UDim2.fromOffset(posX, posY)
            btnRoot.AnchorPoint            = Vector2.new(0, 0)
            btnRoot.BackgroundTransparency = 1
            btnRoot.BorderSizePixel        = 0
            btnRoot.ZIndex                 = 200
            btnRoot.Active                 = true

            -- UIScale para animacion de entrada
            local sc = Instance.new("UIScale", btnRoot)
            sc.Scale = 0

            -- Bot?n principal: fondo degradado oscuro azul del hub + borde neon cian
            local clickBtn = Instance.new("TextButton", btnRoot)
            clickBtn.Name                   = "ShootButton"
            clickBtn.Size                   = UDim2.new(1, 0, 1, 0)
            clickBtn.Position               = UDim2.new(0, 0, 0, 0)
            clickBtn.AnchorPoint            = Vector2.new(0.5, 0.5)
            clickBtn.BackgroundColor3       = Color3.fromRGB(4, 10, 28)
            clickBtn.BackgroundTransparency = 0.15
            clickBtn.Text                   = "Shoot"
            clickBtn.TextColor3             = Color3.fromRGB(0, 210, 240)
            clickBtn.TextSize               = 15
            clickBtn.Font                   = Enum.Font.GothamMedium
            clickBtn.AutoButtonColor        = false
            clickBtn.ZIndex                 = 210

            -- Gradiente interno glassmorphism (igual que los botones del hub)
            local _btnGrad = Instance.new("UIGradient", clickBtn)
            _btnGrad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0,   Color3.fromRGB( 5, 20, 60)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB( 2, 10, 35)),
                ColorSequenceKeypoint.new(1,   Color3.fromRGB( 5, 20, 60)),
            })
            _btnGrad.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0,   0.30),
                NumberSequenceKeypoint.new(0.5, 0.18),
                NumberSequenceKeypoint.new(1,   0.30),
            })
            _btnGrad.Rotation = 90

            -- Glow en el texto
            local _txtStroke = Instance.new("UIStroke", clickBtn)
            _txtStroke.Color       = Color3.fromRGB(0, 210, 240)
            _txtStroke.Thickness   = 0.9
            _txtStroke.Transparency = 0.50
            _txtStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual

            local uiCorner = Instance.new("UICorner", clickBtn)
            uiCorner.CornerRadius = UDim.new(0, 20)

            -- Borde neon cian (igual que el hub)
            local uiStroke = Instance.new("UIStroke", clickBtn)
            uiStroke.Color           = Color3.fromRGB(0, 200, 240)
            uiStroke.Thickness       = 2.5
            uiStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            uiStroke.Transparency    = 0.10
            local _strokeGrad = Instance.new("UIGradient", uiStroke)
            _strokeGrad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0,   Color3.fromRGB(0, 220, 255)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(60, 100, 255)),
                ColorSequenceKeypoint.new(1,   Color3.fromRGB(0, 220, 255)),
            })
            _strokeGrad.Rotation = 90

            -- Linea de brillo superior (highlight glassmorphism)
            local _topLine = Instance.new("Frame", clickBtn)
            _topLine.Size = UDim2.new(0.55, 0, 0, 1)
            _topLine.Position = UDim2.new(0.225, 0, 0, 3)
            _topLine.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            _topLine.BackgroundTransparency = 0.60
            _topLine.BorderSizePixel = 0
            _topLine.ZIndex = 215
            Instance.new("UICorner", _topLine).CornerRadius = UDim.new(1, 0)

            -- Animacion de entrada (escala desde 0)
            task.spawn(function()
                task.wait(0.016)
                TweenService:Create(sc, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
            end)

            -- Drag
            local _moved = false
            local _dragging = false
            local _dragStart, _startPos = nil, nil

            if pcall(function()
                local dd = Instance.new("UIDragDetector", btnRoot)
                dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                dd.Dragged:Connect(function()
                    _moved = true
                    local vpN = workspace.CurrentCamera.ViewportSize
                    btnRoot.Position = UDim2.fromOffset(
                        math.clamp(btnRoot.Position.X.Offset, 0, vpN.X - BTN_W),
                        math.clamp(btnRoot.Position.Y.Offset, 0, vpN.Y - BTN_H))
                end)
                dd.DragEnd:Connect(function() task.defer(function() _moved = false end) end)
            end) then
                -- UIDragDetector OK
            else
                clickBtn.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1
                    or inp.UserInputType == Enum.UserInputType.Touch then
                        _dragging = true; _moved = false
                        -- FIX MOVIL: guardar solo X/Y
                        _dragStart = Vector3.new(inp.Position.X, inp.Position.Y, 0)
                        _startPos = btnRoot.Position
                    end
                end)
                UserInputService.InputChanged:Connect(function(inp)
                    if not _dragging then return end
                    if inp.UserInputType ~= Enum.UserInputType.MouseMovement
                    and inp.UserInputType ~= Enum.UserInputType.Touch then return end
                    -- FIX MOVIL: delta incremental para evitar salto a esquina en touch
                    local curX = inp.Position.X
                    local curY = inp.Position.Y
                    local dX = curX - _dragStart.X
                    local dY = curY - _dragStart.Y
                    if math.abs(dX) > 4 or math.abs(dY) > 4 then _moved = true end
                    _dragStart = Vector3.new(curX, curY, 0)
                    local vpN = workspace.CurrentCamera.ViewportSize
                    btnRoot.Position = UDim2.fromOffset(
                        math.clamp(btnRoot.Position.X.Offset + dX, 0, vpN.X - BTN_W),
                        math.clamp(btnRoot.Position.Y.Offset + dY, 0, vpN.Y - BTN_H))
                end)
                clickBtn.InputEnded:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1
                    or inp.UserInputType == Enum.UserInputType.Touch then
                        _dragging = false
                        task.defer(function() _moved = false end)
                    end
                end)
            end

            -- Hover
            clickBtn.MouseEnter:Connect(function()
                TweenService:Create(uiStroke, TweenInfo.new(0.12), {Color = Color3.fromRGB(120, 240, 255), Thickness = 3.0, Transparency = 0}):Play()
                TweenService:Create(clickBtn, TweenInfo.new(0.12), {BackgroundTransparency = 0.05}):Play()
                TweenService:Create(clickBtn, TweenInfo.new(0.12), {TextColor3 = Color3.fromRGB(180, 255, 255)}):Play()
            end)
            clickBtn.MouseLeave:Connect(function()
                TweenService:Create(uiStroke, TweenInfo.new(0.15), {Color = Color3.fromRGB(0, 200, 240), Thickness = 2.5, Transparency = 0.10}):Play()
                TweenService:Create(clickBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.15}):Play()
                TweenService:Create(clickBtn, TweenInfo.new(0.15), {TextColor3 = Color3.fromRGB(0, 210, 240)}):Play()
            end)

            -- Press / Release
            local _lastClick = 0
            clickBtn.MouseButton1Down:Connect(function()
                if _moved then return end
                TweenService:Create(sc, TweenInfo.new(0.07), {Scale=0.94}):Play()
                TweenService:Create(uiStroke, TweenInfo.new(0.07), {Thickness=1.5, Color=Color3.fromRGB(0,255,255)}):Play()
                TweenService:Create(clickBtn, TweenInfo.new(0.07), {BackgroundColor3=Color3.fromRGB(0,30,60)}):Play()
            end)
            clickBtn.MouseButton1Up:Connect(function()
                if _moved then return end
                TweenService:Create(sc, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
                TweenService:Create(uiStroke, TweenInfo.new(0.18), {Thickness=2.5, Color=Color3.fromRGB(0,200,240)}):Play()
                TweenService:Create(clickBtn, TweenInfo.new(0.18), {BackgroundColor3=Color3.fromRGB(4,10,28)}):Play()
            end)
            clickBtn.Activated:Connect(function()
                if _moved then return end
                local now = tick()
                if now - _lastClick < 0.25 then return end
                _lastClick = now
                if not _saSMState.enabled then return end
                _doSilentAimShoot()
            end)
        end

        -- Toggle principal: SILENT AIM (Shoot Murderer)
        CreateBorderedToggle(silentAimSection, "Silent Aim (Shoot Murderer Btn)", function(enabled)
            _saSMState.enabled = enabled
            -- FIX v8: sincronizar silentAimEnabled para que el __namecall hook
            -- y el resto del sistema SA reconozcan el estado del boton
            CombatTabState.silentAimEnabled = enabled
            if enabled then
                -- Activar el hook __namecall para que las llamadas FireServer
                -- que vengan del cliente normal tambien queden redirigidas
                if _saApplyHook then pcall(_saApplyHook) end
                _createSASMButton()
                CreateCustomNotification("SILENT AIM", "Bot?n 'Shoot Murderer' activado ? presionalo para disparar al murder", 3)
            else
                -- Desactivar hook si no hay otros sistemas SA activos
                if _saRemoveHook then pcall(_saRemoveHook) end
                -- Animaci?n de salida antes de destruir
                if _saSMState.gui then
                    local root = _saSMState.gui:FindFirstChild("ShootMurderBtn")
                    local sc = root and root:FindFirstChildOfClass("UIScale")
                    if sc then
                        TweenService:Create(sc, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0}):Play()
                        task.delay(0.32, _destroySASMGui)
                    else
                        _destroySASMGui()
                    end
                end
                CreateCustomNotification("SILENT AIM", "Bot?n 'Shoot Murderer' desactivado", 1.5)
            end
        end, false)
    end
    -- =====================================================================
    -- FIN NUEVO TOGGLE SILENT AIM
    -- =====================================================================

    -- -- BINDABLE SILENT AIM  botn flotante arrastrable para disparar con SA --
    do
        local _bsaState = { enabled = false, gui = nil }
        local function _destroyBSA()
            if _bsaState.gui then
                pcall(function()
                    local bg = _bsaState.gui:FindFirstChild("CapyBindBtn", true)
                    local sc = bg and bg:FindFirstChildOfClass("UIScale")
                    if sc then
                        TweenService:Create(sc, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale=0}):Play()
                        task.delay(0.32, function() pcall(function() _bsaState.gui:Destroy() end) end)
                    else
                        _bsaState.gui:Destroy()
                    end
                end)
                _bsaState.gui = nil
            end
            pcall(function()
                for _, g in ipairs(CoreGui:GetChildren()) do
                    if g.Name == "BypasBSA" then g:Destroy() end
                end
            end)
            pcall(function()
                for _, g in ipairs(LocalPlayer.PlayerGui:GetChildren()) do
                    if g.Name == "BypasBSA" then g:Destroy() end
                end
            end)
        end

        -- Helper: saca la gun, dispara con SA, y la oculta r?pido
        local function _bsaGunFlashAndShoot(onShootDone)
            local myChar = LocalPlayer.Character
            if not myChar then return end
            local myHum = myChar:FindFirstChildOfClass("Humanoid")
            if not myHum or myHum.Health <= 0 then return end
            local myHRP = myChar:FindFirstChild("HumanoidRootPart")
            if not myHRP then return end

            -- Buscar gun
            local gun = _findGunIn and _findGunIn(myChar)
            local wasInBackpack = false
            if not gun then
                local gunBP = _findGunIn and _findGunIn(LocalPlayer.Backpack)
                if gunBP then
                    wasInBackpack = true
                    pcall(function() myHum:EquipTool(gunBP) end)
                    _w(0.06)
                    gun = _findGunIn and _findGunIn(myChar)
                end
            end
            if not gun then
                CreateCustomNotification("BINDABLE SA", "Sin gun", 1.5)
                return
            end

            -- Target: murder detectado
            local target = findMurderer and findMurderer()
            if not target or not target.Character then
                CreateCustomNotification("BINDABLE SA", "Sin target (murder)", 1)
                return
            end
            local tHRP2 = target.Character:FindFirstChild("HumanoidRootPart")
            if not tHRP2 then
                return
            end

            -- Posici?n con predicci?n
            local tPos
            if CombatTabState.saUsePrediction then
                local predPos = _getCachedPrediction(target)
                tPos = predPos or (tHRP2.Position + Vector3.new(0, 0.5, 0))
            else
                local tHead = target.Character and target.Character:FindFirstChild("Head")
                tPos = (tHead and tHead.Position or tHRP2.Position) + Vector3.new(0, 0.2, 0)
            end

            local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP)
            local graWorldCF = barrelAtt and barrelAtt.WorldCFrame
            local cam = _Camera
            local originPos = (barrelAtt and barrelAtt.WorldPosition)
                or (cam and cam.CFrame.Position)
                or (myHRP.Position + Vector3.new(0, 1.5, 0))
            local shootR = getShootRemote and getShootRemote(gun)
            local oCF, tCF = buildShootCFrames(originPos, tPos, graWorldCF)

            if oCF and tCF then
                local gSD = gun:FindFirstChild("Shoot")
                if gSD and gSD:IsA("RemoteEvent") then
                    pcall(function() gSD:FireServer(oCF, tCF) end)
                elseif shootR then
                    pcall(function() shootR:FireServer(oCF, tCF) end)
                else
                    _fireGunMM2(gun)
                end
            else
                _fireGunMM2(gun)
            end

            -- Si estaba en backpack, volver a guardar
            if wasInBackpack and myHum and myHum.Parent then
                task.delay(0.17, function()
                    pcall(function() myHum:UnequipTools() end)
                end)
            end

            if onShootDone then onShootDone() end
        end

        CreateBorderedToggle(silentAimSection, "Bindable Silent Aim", function(enabled)
            _bsaState.enabled = enabled
            _destroyBSA()
            if not enabled then
                CreateCustomNotification("BINDABLE SA", "Desactivado", 2)
                return
            end

            -- Crear bot?n estilo bindable del hub (sin fondo, borde Aurora1)
            local bsaGui = Instance.new("ScreenGui")
            bsaGui.Name           = "BypasBSA"
            bsaGui.ResetOnSpawn   = false
            bsaGui.DisplayOrder   = 9998
            bsaGui.IgnoreGuiInset = true
            bsaGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            pcall(function() bsaGui.Parent = CoreGui end)
            if not bsaGui.Parent then bsaGui.Parent = LocalPlayer.PlayerGui end
            _bsaState.gui = bsaGui

            local BTN_W, BTN_H = 60, 60
            local mySlot = _assignSlot("BSA_SilentAim")
            local posX, posY = _getBindablePosition(mySlot)

            -- Contenedor ra?z
            local bsaRoot = Instance.new("Frame", bsaGui)
            bsaRoot.Name                   = "CapyBindBtn"
            bsaRoot.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            bsaRoot.Position               = UDim2.fromOffset(posX, posY)
            bsaRoot.BackgroundTransparency = 1
            bsaRoot.BorderSizePixel        = 0
            bsaRoot.ZIndex                 = 200
            bsaRoot.Active                 = true

            local bsaScale = Instance.new("UIScale", bsaRoot)
            bsaScale.Scale = 0

            -- Fondo transparente (sin fondo)
            local bsaPillBg = Instance.new("Frame", bsaRoot)
            bsaPillBg.Name                   = "PillBg"
            bsaPillBg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            bsaPillBg.AnchorPoint            = Vector2.new(0.5, 0.5)
            bsaPillBg.Position               = UDim2.fromScale(0.5, 0.5)
            bsaPillBg.BackgroundColor3       = ThemeColors.Aurora1
            bsaPillBg.BackgroundTransparency = 1
            bsaPillBg.BorderSizePixel        = 0
            bsaPillBg.ZIndex                 = 200
            Instance.new("UICorner", bsaPillBg).CornerRadius = UDim.new(0, 10)

            -- Borde del color del hub
            local bsaBorderFrame = Instance.new("Frame", bsaRoot)
            bsaBorderFrame.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            bsaBorderFrame.AnchorPoint            = Vector2.new(0.5, 0.5)
            bsaBorderFrame.Position               = UDim2.fromScale(0.5, 0.5)
            bsaBorderFrame.BackgroundTransparency = 1
            bsaBorderFrame.BorderSizePixel        = 0
            bsaBorderFrame.ZIndex                 = 201
            Instance.new("UICorner", bsaBorderFrame).CornerRadius = UDim.new(0, 10)

            local bsaStroke = Instance.new("UIStroke", bsaBorderFrame)
            bsaStroke.Color           = ThemeColors.Aurora1
            bsaStroke.Thickness       = 0
            bsaStroke.Transparency    = 1
            bsaStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            -- Texto centrado
            local bsaLabel = Instance.new("ImageLabel", bsaRoot)
            bsaLabel.Name                   = "StarIcon"
            bsaLabel.Size                   = UDim2.fromOffset(40, 40)
            bsaLabel.AnchorPoint            = Vector2.new(0.5, 0.5)
            bsaLabel.Position               = UDim2.fromScale(0.5, 0.5)
            bsaLabel.BackgroundTransparency = 1
            bsaLabel.Image                  = "rbxassetid://45428892"
            bsaLabel.ImageColor3            = Color3.fromRGB(255, 255, 255)
            bsaLabel.ScaleType              = Enum.ScaleType.Fit
            bsaLabel.TextXAlignment         = Enum.TextXAlignment.Center
            bsaLabel.TextYAlignment         = Enum.TextYAlignment.Center
            bsaLabel.TextWrapped            = true
            bsaLabel.ZIndex                 = 204

            -- Bot?n clickeable encima
            local bsaFill = Instance.new("TextButton", bsaRoot)
            bsaFill.Name                   = "Fill"
            bsaFill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            bsaFill.AnchorPoint            = Vector2.new(0.5, 0.5)
            bsaFill.Position               = UDim2.fromScale(0.5, 0.5)
            bsaFill.BackgroundTransparency = 1
            bsaFill.BorderSizePixel        = 0
            bsaFill.Text                   = ""
            bsaFill.AutoButtonColor        = false
            bsaFill.ZIndex                 = 210
            Instance.new("UICorner", bsaFill).CornerRadius = UDim.new(0, 10)

            -- Animaci?n entrada
            task.spawn(function()
                task.wait(0.016)
                TweenService:Create(bsaScale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
            end)

            -- Drag
            local _bMoved = false
            local _bDragStart, _bRootStart, _bDragging = nil, nil, false
            if pcall(function()
                local dd = Instance.new("UIDragDetector", bsaRoot)
                dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                dd.Dragged:Connect(function()
                    _bMoved = true
                    local vpN = workspace.CurrentCamera.ViewportSize
                    bsaRoot.Position = UDim2.fromOffset(
                        math.clamp(bsaRoot.Position.X.Offset, 0, vpN.X - BTN_W),
                        math.clamp(bsaRoot.Position.Y.Offset, 0, vpN.Y - BTN_H))
                end)
                dd.DragEnd:Connect(function() task.defer(function() _bMoved = false end) end)
            end) then
                -- UIDragDetector OK
            else
                bsaFill.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1
                    or inp.UserInputType == Enum.UserInputType.Touch then
                        -- FIX MOVIL: guardar solo X/Y
                        _bDragStart = Vector3.new(inp.Position.X, inp.Position.Y, 0)
                        _bRootStart = bsaRoot.Position; _bDragging = false; _bMoved = false
                    end
                end)
                RegisterTabConn(UserInputService.InputChanged:Connect(function(inp)
                    if not _bDragStart then return end
                    if inp.UserInputType ~= Enum.UserInputType.MouseMovement
                    and inp.UserInputType ~= Enum.UserInputType.Touch then return end
                    -- FIX MOVIL: delta incremental para evitar salto a esquina en touch
                    local curX = inp.Position.X
                    local curY = inp.Position.Y
                    local dX = curX - _bDragStart.X
                    local dY = curY - _bDragStart.Y
                    if math.abs(dX) > 6 or math.abs(dY) > 6 then _bDragging = true; _bMoved = true end
                    _bDragStart = Vector3.new(curX, curY, 0)
                    if _bDragging then
                        local vp = workspace.CurrentCamera.ViewportSize
                        bsaRoot.Position = UDim2.fromOffset(
                            math.clamp(bsaRoot.Position.X.Offset + dX, 0, vp.X - BTN_W),
                            math.clamp(bsaRoot.Position.Y.Offset + dY, 0, vp.Y - BTN_H))
                    end
                end))
                RegisterTabConn(UserInputService.InputEnded:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1
                    or inp.UserInputType == Enum.UserInputType.Touch then
                        _bDragStart = nil; _bDragging = false
                        task.defer(function() _bMoved = false end)
                    end
                end))
            end

            -- Hover
            bsaFill.MouseEnter:Connect(function()
                TweenService:Create(bsaPillBg, TweenInfo.new(0.12), {BackgroundTransparency=0.75}):Play()
-- [border removed]
            end)
            bsaFill.MouseLeave:Connect(function()
                TweenService:Create(bsaPillBg, TweenInfo.new(0.15), {BackgroundTransparency=1}):Play()
-- [border removed]
            end)

            -- Press / Release
            bsaFill.MouseButton1Down:Connect(function()
                if _bMoved then return end
                TweenService:Create(bsaPillBg, TweenInfo.new(0.07), {BackgroundTransparency=0.40}):Play()
-- [border removed]
                TweenService:Create(bsaScale,  TweenInfo.new(0.07), {Scale=0.92}):Play()
            end)
            bsaFill.MouseButton1Up:Connect(function()
                if _bMoved then return end
                TweenService:Create(bsaPillBg, TweenInfo.new(0.18), {BackgroundTransparency=1}):Play()
-- [border removed]
                TweenService:Create(bsaScale,  TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale=1}):Play()
            end)

            -- Click: disparar
            local _bsaLastShot = 0
            bsaFill.Activated:Connect(function()
                if _bMoved or _bDragging then return end
                if not _bsaState.enabled then return end
                local now = tick()
                if now - _bsaLastShot < 0.22 then return end
                _bsaLastShot = now
                -- Flash borde al disparar
                TweenService:Create(bsaStroke, TweenInfo.new(0.07), {Thickness=2}):Play()
                task.delay(0.15, function()
-- [border removed]
                end)
                _sp(_bsaGunFlashAndShoot)
            end)

            -- Liberar slot al destruirse
            bsaGui.AncestryChanged:Connect(function()
                if not bsaGui.Parent then
                    pcall(function() _releaseSlot("BSA_SilentAim") end)
                end
            end)

            CreateCustomNotification("BINDABLE SA", "Activado", 2)
        end, false)
    end
    CombatState.saButtonSize = CombatState.saButtonSize or 240
    do
        local sizeSec = Instance.new("Frame", silentAimSection)
        sizeSec.Size = UDim2.new(1, 0, 0, 50)
        sizeSec.BackgroundColor3 = Color3.fromRGB(55, 55, 60)
        sizeSec.BackgroundTransparency = 0.75
        sizeSec.BorderSizePixel = 0
        Instance.new("UICorner", sizeSec).CornerRadius = UDim.new(0, 8)
        local ssStroke = Instance.new("UIStroke", sizeSec)
        ssStroke.Color = ThemeColors.Primary; ssStroke.Thickness = 1.5; ssStroke.Transparency = 0.4

        local ssLbl = Instance.new("TextLabel", sizeSec)
        ssLbl.Size = UDim2.new(1, -80, 0, 20); ssLbl.Position = UDim2.new(0, 10, 0, 5)
        ssLbl.BackgroundTransparency = 1; ssLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat); ssLbl.TextSize = 11
        ssLbl.TextColor3 = ThemeColors.TextPrimary; ssLbl.TextXAlignment = Enum.TextXAlignment.Left
 ssLbl.Text = "Tama?o Bot?n SA: " .. CombatState.saButtonSize

        local ssBg = Instance.new("Frame", sizeSec)
        ssBg.Size = UDim2.new(1, -20, 0, 6); ssBg.Position = UDim2.new(0, 10, 0, 34)
        ssBg.BackgroundColor3 = Color3.fromRGB(40, 40, 55); ssBg.BorderSizePixel = 0
        ssBg.BackgroundTransparency = 0.75
        Instance.new("UICorner", ssBg).CornerRadius = UDim.new(1, 0)

        local initPct = (CombatState.saButtonSize - 100) / (400 - 100)
        local ssFill = Instance.new("Frame", ssBg)
        ssFill.Size = UDim2.new(initPct, 0, 1, 0)
        ssFill.BackgroundColor3 = ThemeColors.Primary; ssFill.BorderSizePixel = 0
        Instance.new("UICorner", ssFill).CornerRadius = UDim.new(1, 0)

        local ssKnob = Instance.new("Frame", ssBg)
        ssKnob.Size = UDim2.new(0, 14, 0, 14); ssKnob.Position = UDim2.new(initPct, 0, 0.5, 0)
        ssKnob.AnchorPoint = Vector2.new(0.5, 0.5); ssKnob.BackgroundColor3 = Color3.fromRGB(255,255,255)
        ssKnob.BorderSizePixel = 0; Instance.new("UICorner", ssKnob).CornerRadius = UDim.new(1, 0)

        local ssDragging = false
        ssKnob.InputBegan:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then ssDragging = true end
        end)
        ssKnob.InputEnded:Connect(function(inp)
            if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then ssDragging = false end
        end)
        RegisterTabConn(UserInputService.InputChanged:Connect(function(inp)
            if ssDragging and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
                local rel = UserInputService:GetMouseLocation().X - ssBg.AbsolutePosition.X
                local pct = math.clamp(rel / ssBg.AbsoluteSize.X, 0, 1)
                local val = math.floor(100 + pct * (400 - 100))
                ssFill.Size = UDim2.new(pct, 0, 1, 0)
                ssKnob.Position = UDim2.new(pct, 0, 0.5, 0)
 ssLbl.Text = "Tama?o Bot?n SA: " .. val
                CombatState.saButtonSize = val
                -- Actualizar tamao del botn existente
                if CombatState.silentAimGui then
                    pcall(function()
                        local btnRoot = CombatState.silentAimGui:FindFirstChildOfClass("Frame")
                        if btnRoot then
                            btnRoot.Size = UDim2.new(0, val, 0, math.floor(val * 0.31))
                        end
                    end)
                end
            end
        end))
    end

    -- -- Auto ocultar botn si sos Asesino ------------------------------------
    CombatState.saAutoHideMurderer = CombatState.saAutoHideMurderer or false
    CombatState.saAutoHideConn     = CombatState.saAutoHideConn     or nil
    CreateBorderedToggle(silentAimSection, "Auto ocultar botn si sos Asesino", function(enabled)
        CombatState.saAutoHideMurderer = enabled
        if CombatState.saAutoHideConn then
            CombatState.saAutoHideConn:Disconnect()
            CombatState.saAutoHideConn = nil
        end
        if enabled then
            local _lastHideState = nil  -- nil = sin estado previo

            -- OPT: cachear descendientes del ShootButton UNA sola vez en vez de
            -- llamar GetDescendants() en cada tick del Heartbeat
            local function _getShootBtnRoot()
                return CombatState.silentAimGui and
                       CombatState.silentAimGui:FindFirstChild("ShootButton")
            end
            local _cachedBtnChildren = nil
            local function _rebuildBtnCache()
                local root = _getShootBtnRoot()
                if not root then _cachedBtnChildren = nil; return end
                _cachedBtnChildren = root:GetDescendants()
            end

            local function _applyHideState(isMurderer, btnRoot)
                if _lastHideState == isMurderer then return end
                _lastHideState = isMurderer
                if not _cachedBtnChildren then _rebuildBtnCache() end
                local ti = TweenInfo.new(0.3)
                if isMurderer then
                    TweenService:Create(btnRoot, ti, {BackgroundTransparency = 1}):Play()
                    for _, child in ipairs(_cachedBtnChildren or {}) do
                        if child:IsA("TextLabel") or child:IsA("TextButton") then
                            pcall(function() TweenService:Create(child, ti, {BackgroundTransparency=1, TextTransparency=1}):Play() end)
                        elseif child:IsA("Frame") or child:IsA("ImageLabel") then
                            pcall(function() TweenService:Create(child, ti, {BackgroundTransparency=1}):Play() end)
                        elseif child:IsA("UIStroke") then
                            pcall(function() TweenService:Create(child, ti, {Transparency=1}):Play() end)
                        end
                    end
                    _dl(0.32, function()
                        if _lastHideState == true and btnRoot and btnRoot.Parent then
                            btnRoot.Visible = false
                        end
                    end)
                    btnRoot.Active = false
                else
                    btnRoot.Visible = true
                    btnRoot.Active  = false
                    TweenService:Create(btnRoot, ti, {BackgroundTransparency = 1}):Play()
                    for _, child in ipairs(_cachedBtnChildren or {}) do
                        if child:IsA("TextLabel") or child:IsA("TextButton") then
                            pcall(function() TweenService:Create(child, ti, {BackgroundTransparency=1, TextTransparency=0}):Play() end)
                        elseif child:IsA("Frame") or child:IsA("ImageLabel") then
                            pcall(function() TweenService:Create(child, ti, {BackgroundTransparency=0}):Play() end)
                        elseif child:IsA("UIStroke") then
                            pcall(function() TweenService:Create(child, ti, {Transparency=0}):Play() end)
                        end
                    end
                end
            end

            -- OPT LAG FIX: unificamos los 2 Heartbeat loops anteriores en uno solo a 2Hz.
            -- La logica reactiva (_lastHideState ~= isMurderer) ya evita tweens redundantes.
            local _hbAH = 0
            CombatState.saAutoHideConn = _safeConnect(RunService.Heartbeat, function()
                _hbAH = _hbAH + 1; if _hbAH < 30 then return end; _hbAH = 0  -- 2Hz
                if not CombatState.saAutoHideMurderer then return end
                local btnRoot = _getShootBtnRoot()
                if not btnRoot then return end
                local isMurderer = _roleCache and _roleCache.localRole == "Murderer"
                -- Solo aplicar si el estado cambio (evita tweens innecesarios)
                if _lastHideState ~= isMurderer then
                    _applyHideState(isMurderer, btnRoot)
                end
            end)
            -- [notif removed]
        else
            if CombatState.silentAimGui then
                pcall(function()
                    local btnRoot = CombatState.silentAimGui:FindFirstChild("ShootButton")
                    if btnRoot then
                        btnRoot.Visible = true
                        btnRoot.Active  = false  -- FIX
                        for _, child in ipairs(btnRoot:GetDescendants()) do
                            if child:IsA("TextLabel") or child:IsA("TextButton") then
                                pcall(function()
                                    TweenService:Create(child, TweenInfo.new(0.3), {TextTransparency = 0}):Play()
                                end)
                            elseif child:IsA("UIStroke") then
                                pcall(function()
                                    TweenService:Create(child, TweenInfo.new(0.3), {Transparency = 0}):Play()
                                end)
                            end
                        end
                    end
                end)
            end
            -- [notif removed]
        end
    end, CombatState.saAutoHideMurderer)

    -- Wall Check SIEMPRE activo en Silent Aim (integrado)
    CombatState.saWallCheck = true

    -- (Tianca Prediction movido a seccin propia: PREDICCIN  TIANCA)

    -- -- Body Part selector (CreateNebulaSelector nativo del hub) ---------------
    do
        local bodyParts = {"Head", "HumanoidRootPart", "UpperTorso", "LowerTorso",
            "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg"}
        CreateNebulaSelector(silentAimSection, "Parte del cuerpo", bodyParts,
            CombatState.saTargetPart or "Head",
            function(selected)
                CombatState.saTargetPart    = selected
                CombatTabState.saTargetPart = selected
                if Settings and Settings.combatSettings then
                    Settings.combatSettings.targetBodyPart = selected
                end
            end
        )
    end

    -- =========================================================
    -- PREDICTION TOGGLES ? sistema de predicci?n de combate
    -- Cada toggle activa un componente distinto del solver.
    -- saUsePrediction se recalcula en cada cambio para reflejar
    -- el estado real de todos los flags activos.
    -- =========================================================
    do
        -- Helper interno: recalcula saUsePrediction seg?n todos los flags activos
        local function _recalcUsePrediction()
            CombatTabState.saUsePrediction =
                (CombatTabState.saPredAccel   or false)
                or (CombatTabState.saPredTrend  or false)
                or (CombatTabState.saPredLag    or false)
                or (CombatTabState.saPredStrafe or false)
                or (CombatTabState.saPredJump   or false)
        end

        -- Inicializar estados con defaults seguros
        -- FIX AUTO-RESTORE: los toggles de prediccion ahora tienen initialValue=false y estan en
        -- _autoRestoreOnReexec, por lo que el callback los activa al restaurar. Pero CombatTabState
        -- puede tener valores residuales de la sesion anterior (tab rebuild). Para no crear
        -- inconsistencias, sincronizamos desde _G._toggleStates (la fuente de verdad del disco).
        local _ts = _G._toggleStates or {}
        CombatTabState.prioritizeYourPing = _ts["Own Ping Mode"]          == true or false
        CombatTabState.predictJumpToggle  = _ts["Jump Prediction"]        == true or false
        CombatTabState.lagPrediction      = _ts["Lag Compensation"]       == true or false
        CombatTabState.seeNormalPred      = _ts["Velocity Prediction"]    == true or false
        CombatTabState.seeLeadTimePred    = _ts["Lead Time Prediction"]   == true or false
        CombatTabState.seePingPred        = _ts["Ping Boost"]             == true or false
        CombatTabState.seeLagPred         = _ts["Lag Compensation"]       == true or false
        CombatTabState.seeXZOffset        = _ts["Strafe Prediction"]      == true or false
        CombatTabState.showPredTracer     = _ts["Prediction Tracer"]      == true or false
        CombatTabState.pingSensitivity    = CombatTabState.pingSensitivity or 1.0

        -- Sincronizar flags globales con el estado restaurado del config
        _G._saPrioritizeOwnPing  = CombatTabState.prioritizeYourPing
        _G._saPingPredEnabled    = CombatTabState.seePingPred
        _G._saPingSensitivity    = CombatTabState.pingSensitivity
        _G._showPredictionTracer = CombatTabState.showPredTracer
        _recalcUsePrediction()

        -- -- VELOCITY PREDICTION ------------------------------------------
        -- Predice la posici?n futura usando la velocidad EMA (promedio m?vil
        -- exponencial) del HumanoidRootPart. Es el componente base del solver.
        -- Recomendado siempre activar cuando el target se mueve.
        CreateBorderedToggle(silentAimSection, "Velocity Prediction", function(en)
            CombatTabState.seeNormalPred  = en
            CombatTabState.saPredAccel    = en
            _recalcUsePrediction()
            CreateCustomNotification("PRED", en and "? Velocity Pred ON ? compensa velocidad del target" or "Velocity Pred OFF", 2)
        end, CombatTabState.seeNormalPred)

        -- -- LEAD TIME PREDICTION -----------------------------------------
        -- Analiza el historial de posiciones del target (?ltimos 6 frames) para
        -- detectar la tendencia de movimiento y "adelantarse" a su trayectoria.
        -- Muy efectivo contra targets que corren en l?nea recta.
        CreateBorderedToggle(silentAimSection, "Lead Time Prediction", function(en)
            CombatTabState.seeLeadTimePred = en
            CombatTabState.saPredTrend     = en
            _recalcUsePrediction()
            CreateCustomNotification("PRED", en and "?? Lead Time ON ? anticipa trayectoria del target" or "Lead Time Pred OFF", 2)
        end, false)

        -- -- STRAFE PREDICTION --------------------------------------------
        -- Compensa el desplazamiento horizontal (X/Z) cuando el target hace
        -- strafe (movi?ndose lateralmente). Detecta cambios de direcci?n en
        -- el plano horizontal usando el blend de EMA + historial.
        CreateBorderedToggle(silentAimSection, "Strafe Prediction", function(en)
            CombatTabState.seeXZOffset    = en
            CombatTabState.saPredStrafe   = en
            _recalcUsePrediction()
            CreateCustomNotification("PRED", en and "? Strafe Pred ON ? compensa movimiento lateral" or "Strafe Pred OFF", 2)
        end, CombatTabState.seeXZOffset)

        -- -- JUMP PREDICTION ----------------------------------------------
        -- Activa compensaci?n de arco de salto: calcula la posici?n futura en Y
        -- usando la gravedad efectiva del juego (workspace.Gravity) cuando el
        -- target est? en el aire. Solo se aplica si el target NO est? en el suelo.
        CreateBorderedToggle(silentAimSection, "Jump Prediction", function(en)
            CombatTabState.predictJumpToggle = en
            CombatTabState.saPredJump        = en
            _recalcUsePrediction()
            CreateCustomNotification("PRED", en and "? Jump Pred ON ? compensa arco de salto/caida" or "Jump Pred OFF", 2)
        end, false)

        -- -- LAG COMPENSATION ---------------------------------------------
        -- Compensa el lag de red del target: estima cu?nto se ha movido el
        -- target durante el tiempo de vuelo del proyectil usando el ping EMA
        -- (exponential moving average, alpha=0.20). Desactiva si "Own Ping Mode"
        -- est? ON (en ese caso ya se usa tu propio ping como fuente de verdad).
        CreateBorderedToggle(silentAimSection, "Lag Compensation", function(en)
            CombatTabState.lagPrediction   = en
            CombatTabState.seeLagPred      = en
            CombatTabState.saPredLag       = en
            -- Si Own Ping Mode est? activo, lag comp del target no aplica
            if en and _G._saPrioritizeOwnPing then
                CombatTabState.saPredLag = false
                CreateCustomNotification("PRED", "? Desactiva 'Own Ping Mode' para usar Lag Comp", 2.5)
            else
                _recalcUsePrediction()
                CreateCustomNotification("PRED", en and "?? Lag Comp ON ? compensa ping de red del target" or "Lag Comp OFF", 2)
            end
        end, false)

        -- -- OWN PING MODE ------------------------------------------------
        -- Usa TU propio ping (LocalPlayer:GetNetworkPing()) como base del TOF
        -- en lugar del ping estimado del target. ?til cuando tienes ping alto
        -- y el lag comp est?ndar sobre-predice. Desactiva Lag Compensation.
        CreateBorderedToggle(silentAimSection, "Own Ping Mode", function(en)
            CombatTabState.prioritizeYourPing = en
            _G._saPrioritizeOwnPing = en
            -- Desactivar lag comp del target porque son mutuamente excluyentes
            if en then
                CombatTabState.saPredLag     = false
                CombatTabState.lagPrediction = false
                CombatTabState.seeLagPred    = false
            end
            _recalcUsePrediction()
            CreateCustomNotification("PRED", en and "?? Own Ping Mode ON ? usa tu ping como referencia" or "Own Ping Mode OFF", 2)
        end, CombatTabState.prioritizeYourPing)

        -- -- PING BOOST ---------------------------------------------------
        -- Agrega el valor de tu ping como componente extra en el c?lculo del TOF
        -- (time of flight). Potencia la predicci?n base multiplic?ndola por el
        -- factor de sensibilidad configurado en "Ping Sensitivity".
        -- Combinar con Velocity Pred para mejores resultados.
        CreateBorderedToggle(silentAimSection, "Ping Boost", function(en)
            CombatTabState.seePingPred    = en
            _G._saPingPredEnabled         = en
            CreateCustomNotification("PRED", en and "?? Ping Boost ON ? a?ade tu ping al TOF del solver" or "Ping Boost OFF", 2)
        end, CombatTabState.seePingPred)

        -- -- PREDICTION TRACER --------------------------------------------
        -- Dibuja una l?nea visual en pantalla desde el origen del disparo hasta
        -- el punto predicho por el solver. ?til para calibrar los multiplicadores
        -- y verificar que la predicci?n apunta donde debe.
        CreateBorderedToggle(silentAimSection, "Prediction Tracer", function(en)
            CombatTabState.showPredTracer = en
            _G._showPredictionTracer      = en
            if not en then
                pcall(function()
                    local cg = game:GetService("CoreGui")
                    local tg = cg:FindFirstChild("PredTracerGui")
                    if tg then tg:Destroy() end
                end)
            end
            CreateCustomNotification("PRED", en and "?? Tracer ON ? muestra el punto predicho en pantalla" or "Prediction Tracer OFF", 2)
        end, CombatTabState.showPredTracer)

        -- -- PING SENSITIVITY ---------------------------------------------
        -- Multiplica el componente de ping del solver. 1.0 = comportamiento
        -- est?ndar. Subir si el aim queda corto con Ping Boost activo.
        -- Bajar si el aim se pasa (over-prediction). Rango recomendado: 0.5?1.5.
        CreateSlider(silentAimSection, "Ping Sensitivity", 0.1, 3.0, CombatTabState.pingSensitivity, function(v)
            CombatTabState.pingSensitivity = v
            _G._saPingSensitivity          = v
        end)
    end

    -- =========================================================
    -- MOUSE SHOOT
    -- =========================================================
    do
        local _msState = {
            enabled      = false,
            conn         = nil,   -- Heartbeat connection
            cursorGui    = nil,   -- ScreenGui del circulito
            fovPred      = false, -- FOV Prediction activado
            circleSize   = 22,    -- Tama?o del c?rculo (px)
        }

        -- Crea el circulito encima del cursor
        local function _createCursorCircle()
            _msState.cursorGui = Instance.new("ScreenGui")
            _msState.cursorGui.Name            = "MouseShootCursor"
            _msState.cursorGui.ResetOnSpawn    = false
            _msState.cursorGui.DisplayOrder    = 9999
            _msState.cursorGui.IgnoreGuiInset  = true
            _msState.cursorGui.ZIndexBehavior  = Enum.ZIndexBehavior.Sibling

            -- Intentar poner en CoreGui primero, fallback a PlayerGui
            local ok = pcall(function()
                _msState.cursorGui.Parent = game:GetService("CoreGui")
            end)
            if not ok then
                _msState.cursorGui.Parent = LocalPlayer.PlayerGui
            end

            local SIZE = _msState.circleSize
            local circle = Instance.new("Frame", _msState.cursorGui)
            circle.Name                  = "MSCircle"
            circle.Size                  = UDim2.new(0, SIZE, 0, SIZE)
            circle.AnchorPoint           = Vector2.new(0.5, 0.5)
            circle.Position              = UDim2.new(0, 0, 0, 0)
            circle.BackgroundColor3      = Color3.fromRGB(255, 255, 255)
            circle.BackgroundTransparency = 0.25
            circle.BorderSizePixel       = 0
            circle.ZIndex                = 9999
            Instance.new("UICorner", circle).CornerRadius = UDim.new(1, 0)

            -- Borde de color del hub
            local stroke = Instance.new("UIStroke", circle)
            stroke.Color        = ThemeColors.Primary
            stroke.Thickness    = 2.2
            stroke.Transparency = 0

            -- Punto central
            local dot = Instance.new("Frame", circle)
            dot.Name                   = "Dot"
            dot.Size                   = UDim2.new(0, 5, 0, 5)
            dot.AnchorPoint            = Vector2.new(0.5, 0.5)
            dot.Position               = UDim2.new(0.5, 0, 0.5, 0)
            dot.BackgroundColor3       = ThemeColors.Primary
            dot.BackgroundTransparency = 0
            dot.BorderSizePixel        = 0
            dot.ZIndex                 = 10000
            Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)

            return circle
        end

        local function _destroyMouseShoot()
            if _msState.conn then
                pcall(function() _msState.conn:Disconnect() end)
                _msState.conn = nil
            end
            if _msState.cursorGui then
                pcall(function() _msState.cursorGui:Destroy() end)
                _msState.cursorGui = nil
            end
        end

        -- Helper: obtiene la gun equipada
        local function _msGetGun()
            local char = LocalPlayer.Character
            if not char then return nil end
            return _findGunIn and _findGunIn(char) or nil
        end

        -- OPT LAG FIX: cachear partes del murderer y RaycastParams para no llamar
        -- GetDescendants() + new RaycastParams() en CADA frame del Heartbeat (60Hz).
        -- Solo se recalcula cuando el character del murderer cambia.
        local _msCachedChar    = nil
        local _msCachedParams  = nil
        local function _msRebuildCache(ch)
            local parts = {}
            for _, p in ipairs(ch:GetDescendants()) do
                if p:IsA("BasePart") then parts[#parts+1] = p end
            end
            if #parts == 0 then _msCachedParams = nil; return end
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Include
            rp.FilterDescendantsInstances = parts
            _msCachedParams = rp
            _msCachedChar   = ch
        end

        -- Helper: detecta si el cursor est? encima del murderer
        local function _msMouseOverMurderer()
            local murderer = findMurderer and findMurderer()
            if not murderer or not murderer.Character then return false end
            local ch  = murderer.Character
            local hum = ch:FindFirstChildOfClass("Humanoid")
            if not hum or hum.Health <= 0 then return false end

            local cam = workspace.CurrentCamera
            if not cam then return false end

            -- Reconstruir cache solo si el character cambio
            if ch ~= _msCachedChar then _msRebuildCache(ch) end
            if not _msCachedParams then return false end

            local mousePos = UserInputService:GetMouseLocation()
            local ray = cam:ScreenPointToRay(mousePos.X, mousePos.Y)
            local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, _msCachedParams)
            return result ~= nil
        end

        local _msLastShot    = 0
        local _msCooldown    = 0.35  -- segundos entre disparos autom?ticos
        local _msCircleFrame = nil
        local _msBright      = false

        CreateBorderedToggle(silentAimSection, "Mouse Shoot", function(enabled)
            _msState.enabled = enabled
            _destroyMouseShoot()
            if not enabled then
                CreateCustomNotification("MOUSE SHOOT", "Desactivado", 2)
                return
            end

            -- Crear el circulito del cursor
            _msCircleFrame = _createCursorCircle()
            CreateCustomNotification("MOUSE SHOOT", "Activado ? apunt? al Murder y dispara!", 3)

            -- Loop principal: mover el circulo + detectar hover sobre murder
            local _msLoopTick = 0
            _msState.conn = RunService.Heartbeat:Connect(function()
                if not _msState.enabled then return end
                if not _msCircleFrame or not _msCircleFrame.Parent then return end

                -- Mover el circulito al cursor (siempre, visual smooth)
                -- FIX: IgnoreGuiInset=true -> coordenadas absolutas de pantalla
                -- GetMouseLocation() ya devuelve coordenadas sin inset, compensacion exacta via GuiService
                local mPos = UserInputService:GetMouseLocation()
                local _guiInset = Vector2.new(0, 0)
                pcall(function()
                    local gs = game:GetService("GuiService")
                    local inset = gs:GetGuiInset()
                    _guiInset = Vector2.new(inset.X, inset.Y)
                end)
                _msCircleFrame.Position = UDim2.new(0, mPos.X, 0, mPos.Y - _guiInset.Y)

                -- OPT LAG FIX: raycast hover check cada 2 frames (30Hz es suficiente para detectar hover)
                _msLoopTick = _msLoopTick + 1; if _msLoopTick < 2 then return end; _msLoopTick = 0

                local onMurderer = _msMouseOverMurderer()

                -- FIX FOV PREDICTION: si fovPred esta activo, tambien disparar cuando
                -- el murderer este dentro del FOV de camara (sin necesitar cursor encima).
                -- Antes: fovPred se seteaba pero nunca se leia -> el toggle no hacia nada.
                local inFov = false
                if _msState.fovPred and not onMurderer then
                    local murderer = findMurderer and findMurderer()
                    if murderer and murderer.Character then
                        local tHRP = murderer.Character:FindFirstChild("HumanoidRootPart")
                        local tHum = murderer.Character:FindFirstChildOfClass("Humanoid")
                        if tHRP and tHum and tHum.Health > 0 then
                            local cam = workspace.CurrentCamera
                            local vp  = cam.ViewportSize
                            local screenPos, onScreen = cam:WorldToViewportPoint(tHRP.Position)
                            if onScreen then
                                -- Calcular distancia al centro de pantalla en pixeles
                                local cx = vp.X / 2
                                local cy = vp.Y / 2
                                local dx = screenPos.X - cx
                                local dy = screenPos.Y - cy
                                local pixelDist = math.sqrt(dx*dx + dy*dy)
                                -- FOV Prediction dispara si esta dentro de un radio de 200px del centro
                                inFov = pixelDist <= (_msState.circleSize * 6 or 120)
                            end
                        end
                    end
                end

                -- Feedback visual: el circulo se pone del color del hub cuando apunta al murder
                local shouldFire = onMurderer or inFov
                if shouldFire ~= _msBright then
                    _msBright = shouldFire
                    local targetColor = shouldFire
                        and Color3.fromRGB(50, 255, 120)   -- verde = apuntando al murder
                        or  Color3.fromRGB(255, 255, 255)  -- blanco = sin target
                    local targetAlpha = shouldFire and 0.0 or 0.25
                    TweenService:Create(_msCircleFrame, TweenInfo.new(0.08), {
                        BackgroundColor3      = targetColor,
                        BackgroundTransparency = targetAlpha,
                    }):Play()
                    local str = _msCircleFrame:FindFirstChildOfClass("UIStroke")
                    if str then
                        TweenService:Create(str, TweenInfo.new(0.08), {
                            Color = shouldFire and Color3.fromRGB(50, 255, 120) or ThemeColors.Primary
                        }):Play()
                    end
                end

                -- Disparar automaticamente apenas el cursor pise el murder (o FOV Prediction activo)
                if not shouldFire then return end
                local now = tick()
                if now - _msLastShot < _msCooldown then return end

                local gun = _msGetGun()
                if not gun then return end

                -- Usar el mismo sistema de Silent Aim principal (_saGetTargetCF)
                -- para garantizar prediccion y CFrames identicos al SA normal
                local graCF, targetCF
                pcall(function()
                    graCF, targetCF = _saGetTargetCF()
                end)
                if not graCF or not targetCF then return end

                local shootR = getShootRemote(gun)
                if shootR and shootR:IsA("RemoteEvent") then
                    pcall(function() shootR:FireServer(graCF, targetCF) end)
                    _msLastShot = now
                end
            end)
        end, false)

        -- Toggle: FOV Prediction
        CreateBorderedToggle(silentAimSection, "FOV Prediction", function(enabled)
            _msState.fovPred = enabled
            CreateCustomNotification("MOUSE SHOOT", enabled and "FOV Prediction ON" or "FOV Prediction OFF", 1.5)
        end, false)

        -- -- SHOOT SPAM JUMPER ----------------------------------------------------
        -- Detecta 4 saltos seguidos del murder dentro del FOV y dispara autom?ticamente
        -- con wall check integrado.
        do
            local _ssjState = {
                enabled      = false,
                myRange      = 80,   -- distancia m?xima desde m? (studs)
                targetRange  = 80,   -- distancia m?xima del target (studs) ? si > rango, no dispara
                conn         = nil,
                -- Tracking de saltos
                jumpCount    = 0,
                lastY        = nil,
                wasAirborne  = false,
                lastJumpTime = 0,
                jumpResetTimeout = 2.5,  -- segundos sin salto para resetear contador
                jumpThreshold    = 4,    -- saltos necesarios para disparar
                lastShot         = 0,
                shotCooldown     = 0.25,
            }

            -- Chequeo de visibilidad: el target est? en el FOV de pantalla
            local function _ssjInFOV(tHRP)
                local cam = workspace.CurrentCamera
                if not cam then return false end
                local screenPos, onScreen = cam:WorldToViewportPoint(tHRP.Position)
                if not onScreen then return false end
                local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
                local dist2D = Vector2.new(screenPos.X, screenPos.Y) - center
                -- FOV de 200px de radio en pantalla (ajustable)
                return dist2D.Magnitude <= 200
            end

            -- Chequeo de rango 3D: mi distancia al target (myRange)
            -- y tambi?n que el target no est? m?s lejos de targetRange desde su propio HRP
            local function _ssjInRange(myHRP, tHRP)
                local d = (tHRP.Position - myHRP.Position).Magnitude
                -- myRange: distancia m?xima YO?target para activar
                if d > _ssjState.myRange then return false end
                -- targetRange: si el target est? m?s lejos que targetRange de m?, no disparar
                -- (permite limitar tiros a distancias donde el SA es confiable)
                if d > _ssjState.targetRange then return false end
                return true
            end

            -- Disparo con SA + wall check
            local function _ssjShoot()
                local now = tick()
                if now - _ssjState.lastShot < _ssjState.shotCooldown then return end

                local myChar = LocalPlayer.Character
                local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myHRP then return end

                -- Buscar gun equipada
                local gun = nil
                if _msGetGun then
                    gun = _msGetGun()
                else
                    for _, t in ipairs(myChar:GetChildren()) do
                        if t:IsA("Tool") and (_GUN_NAMES and _GUN_NAMES[t.Name] or t.Name:lower():find("gun")) then
                            gun = t; break
                        end
                    end
                end
                if not gun then return end

                -- Obtener CFrames del Silent Aim si est? disponible
                local graCF, targetCF
                if _saGetTargetCF then
                    pcall(function() graCF, targetCF = _saGetTargetCF() end)
                end

                -- Fallback: apuntar al murderer directamente
                if not graCF or not targetCF then
                    local murderer = findMurderer and findMurderer()
                    if not murderer or not murderer.Character then return end
                    local tHRP = murderer.Character:FindFirstChild("HumanoidRootPart")
                    if not tHRP then return end
                    local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP)
                    local originPos = (barrelAtt and barrelAtt.WorldPosition)
                        or (_Camera and _Camera.CFrame.Position)
                        or (myHRP.Position + Vector3.new(0, 1.5, 0))
                    local graWorldCF = barrelAtt and barrelAtt.WorldCFrame
                    graCF, targetCF = buildShootCFrames(originPos, tHRP.Position, graWorldCF)
                end
                if not graCF or not targetCF then return end

                -- Wall check: l?nea desde mi HRP hasta el punto objetivo
                local targetPos = targetCF.Position
                if not wallCheckRaycast(myHRP.Position, targetPos) then return end  -- hay pared

                local shootR = getShootRemote(gun)
                if shootR and shootR:IsA("RemoteEvent") then
                    if CombatTabState then CombatTabState._saBypassHook = true end
                    pcall(function() shootR:FireServer(graCF, targetCF) end)
                    if CombatTabState then CombatTabState._saBypassHook = false end
                    _ssjState.lastShot = now
                    CreateCustomNotification("SPAM JUMPER", "?? Disparo autom?tico ? " .. _ssjState.jumpCount .. " saltos", 1.5)
                end
            end

            local function _ssjStop()
                if _ssjState.conn then
                    pcall(function() _ssjState.conn:Disconnect() end)
                    _ssjState.conn = nil
                end
                _ssjState.jumpCount    = 0
                _ssjState.lastY        = nil
                _ssjState.wasAirborne  = false
            end

            local function _ssjStart()
                _ssjStop()
                local _ssjTick = 0
                _ssjState.conn = RunService.Heartbeat:Connect(function()
                    if not _ssjState.enabled then return end
                    -- OPT LAG FIX: 30Hz es suficiente para detectar aterrizaje (dura ~200ms+)
                    _ssjTick = _ssjTick + 1; if _ssjTick < 2 then return end; _ssjTick = 0

                    local murderer = findMurderer and findMurderer()
                    if not murderer or not murderer.Character then
                        _ssjState.jumpCount = 0; _ssjState.lastY = nil; _ssjState.wasAirborne = false
                        return
                    end

                    local tChar = murderer.Character
                    local tHRP  = tChar:FindFirstChild("HumanoidRootPart")
                    local tHum  = tChar:FindFirstChildOfClass("Humanoid")
                    if not tHRP or not tHum or tHum.Health <= 0 then return end

                    local myChar = LocalPlayer.Character
                    local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if not myHRP then return end

                    -- Rango y FOV check
                    if not _ssjInRange(myHRP, tHRP) then
                        _ssjState.jumpCount = 0; _ssjState.lastY = nil; _ssjState.wasAirborne = false
                        return
                    end
                    if not _ssjInFOV(tHRP) then return end

                    -- Reset de contador si pas? mucho tiempo sin saltar
                    local now = tick()
                    if now - _ssjState.lastJumpTime > _ssjState.jumpResetTimeout and _ssjState.jumpCount > 0 then
                        _ssjState.jumpCount = 0
                        _ssjState.lastY     = nil
                        _ssjState.wasAirborne = false
                    end

                    -- Detecci?n de salto: transici?n airborne ? grounded
                    local curY    = tHRP.Position.Y
                    local airborne = tHum.FloorMaterial == Enum.Material.Air

                    if _ssjState.lastY ~= nil then
                        -- Detectar el momento en que toca el suelo despu?s de estar en el aire
                        if _ssjState.wasAirborne and not airborne then
                            _ssjState.jumpCount    = _ssjState.jumpCount + 1
                            _ssjState.lastJumpTime = now

                            if _ssjState.jumpCount >= _ssjState.jumpThreshold then
                                -- ?4+ saltos detectados! disparar
                                _ssjShoot()
                                _ssjState.jumpCount   = 0
                                _ssjState.lastY       = nil
                                _ssjState.wasAirborne = false
                                return
                            end
                        end
                    end

                    _ssjState.lastY       = curY
                    _ssjState.wasAirborne = airborne
                end)
            end

            -- FIX BUG-1: Toggle para activar/desactivar Shoot Spam Jumper en la UI
            CreateBorderedToggle(silentAimSection, "Shoot Spam Jumper (4 saltos)", function(enabled)
                _ssjState.enabled = enabled
                if enabled then
                    _ssjStart()
                    CreateCustomNotification("SPAM JUMPER", "Activo ? detecta 4 saltos del Murder y dispara", 3)
                else
                    _ssjStop()
                    CreateCustomNotification("SPAM JUMPER", "Desactivado", 2)
                end
            end, false)

        -- -- FIN SHOOT SPAM JUMPER ------------------------------------------------

    end  -- cierre bloque silentAimSection

    -- =========================================================
    -- CUSTOM TARGET SYSTEM (Use Custom Target + Select Target)
    -- =========================================================
    do
        -- Estado persistente del custom target
        -- FIX AUTO-RESTORE: sincronizar desde _G._toggleStates (disco) para que el estado
        -- del knob sea correcto aunque initialValue sea false (el auto-restore lo dispara via _autoRestoreOnReexec)
        do
            local _savedCT = _G._toggleStates and _G._toggleStates["Use Custom Target"]
            CombatTabState.useCustomTarget = (_savedCT == true) and true or (CombatTabState.useCustomTarget or false)
        end
        CombatTabState.customTargetPlayer = CombatTabState.customTargetPlayer or nil

        -- Funci?n helper: obtiene el target activo (custom o murderer)
        _G._getEffectiveTarget = function()
            if CombatTabState.useCustomTarget and CombatTabState.customTargetPlayer
               and CombatTabState.customTargetPlayer.Parent then
                return CombatTabState.customTargetPlayer
            end
            return findMurderer and findMurderer()
        end

        -- Secci?n con borde
        local ctSection = CreateBorderedSection(leftColumn, " CUSTOM TARGET")

        -- Toggle: Use Custom Target
        local _ctToggleRef = CreateBorderedToggle(ctSection, "Use Custom Target", function(enabled)
            CombatTabState.useCustomTarget   = enabled
            CombatTabState.saUseCustomTarget = enabled   -- sincronizar campo legacy
            if enabled then
                if CombatTabState.customTargetPlayer and CombatTabState.customTargetPlayer.Parent then
                    CreateCustomNotification("CUSTOM TARGET", "ON ? " .. CombatTabState.customTargetPlayer.Name, 2)
                else
                    -- [notif removed]
                end
            else
                -- [notif removed]
            end
        end, false)

        -- Bot?n: Select Target ? abre selector de jugadores
        local _selBtn = Instance.new("TextButton", ctSection)
        _selBtn.Size = UDim2.new(1, -8, 0, 34)
        _selBtn.AutomaticSize = Enum.AutomaticSize.None
        _selBtn.BackgroundColor3 = ThemeColors.Background
        _selBtn.BackgroundTransparency = 0.35
        _selBtn.BorderSizePixel = 0
        _selBtn.Text = "  Select Target"
        _selBtn.TextColor3 = ThemeColors.TextPrimary
        _selBtn.Font = Enum.Font.GothamBold
        _selBtn.TextSize = 13
        _selBtn.ZIndex = 14
        _selBtn.Active = true
        _selBtn.AutoButtonColor = false
        local _selBtnPad = Instance.new("UIPadding", _selBtn)
        _selBtnPad.PaddingLeft = UDim.new(0, 10)
        local _selCorner = Instance.new("UICorner", _selBtn)
        _selCorner.CornerRadius = UDim.new(0, 8)
        local _selStroke = Instance.new("UIStroke", _selBtn)
        _selStroke.Color = ThemeColors.Primary
        _selStroke.Thickness = 1.5
        _selStroke.Transparency = 0.1
        -- Hover feedback
        _selBtn.MouseEnter:Connect(function()
            TweenService:Create(_selBtn, TweenInfo.new(0.1), {BackgroundTransparency = 0.15}):Play()
        end)
        _selBtn.MouseLeave:Connect(function()
            TweenService:Create(_selBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.35}):Play()
        end)

        -- Label del target seleccionado
        local _ctLabel = Instance.new("TextLabel", ctSection)
        _ctLabel.Size = UDim2.new(1, -8, 0, 18)
        _ctLabel.BackgroundTransparency = 1
        _ctLabel.Text = "Target: " .. (CombatTabState.customTargetPlayer and CombatTabState.customTargetPlayer.Name or "ninguno")
        _ctLabel.TextColor3 = Color3.fromRGB(140, 200, 255)
        _ctLabel.Font = Enum.Font.Montserrat
        _ctLabel.TextSize = 10
        _ctLabel.TextXAlignment = Enum.TextXAlignment.Left
        _ctLabel.ZIndex = 14
        local _ctlPad = Instance.new("UIPadding", _ctLabel)
        _ctlPad.PaddingLeft = UDim.new(0, 8)
        _ctlPad.PaddingBottom = UDim.new(0, 4)

        -- GUI del selector de jugadores
        local _selectorGui = nil
        local function _closeSelector()
            if _selectorGui and _selectorGui.Parent then
                pcall(function() _selectorGui:Destroy() end)
            end
            _selectorGui = nil
        end

        _selBtn.Activated:Connect(function()
            -- Cerrar si ya est? abierto
            if _selectorGui and _selectorGui.Parent then _closeSelector(); return end

            local sg = Instance.new("ScreenGui")
            sg.Name = "CustomTargetSelector"
            sg.ResetOnSpawn = false
            sg.IgnoreGuiInset = true
            sg.ZIndexBehavior = Enum.ZIndexBehavior.Global
            sg.DisplayOrder = 10100
            pcall(function() sg.Parent = game:GetService("CoreGui") end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _selectorGui = sg

            -- Fondo oscuro semitransparente
            local bg = Instance.new("Frame", sg)
            bg.Size = UDim2.new(1, 0, 1, 0)
            bg.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            bg.BackgroundTransparency = 0.5
            bg.BorderSizePixel = 0
            bg.ZIndex = 1

            -- Panel central
            local panel = Instance.new("Frame", sg)
            panel.Size = UDim2.new(0, 260, 0, 0)
            panel.AutomaticSize = Enum.AutomaticSize.Y
            panel.AnchorPoint = Vector2.new(0.5, 0.5)
            panel.Position = UDim2.new(0.5, 0, 0.5, 0)
            panel.BackgroundColor3 = Color3.fromRGB(10, 50, 44)
            panel.BackgroundTransparency = 0.08
            panel.BorderSizePixel = 0
            panel.ZIndex = 2
            Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 10)
            local pStroke = Instance.new("UIStroke", panel)
            pStroke.Color = Color3.fromRGB(200, 200, 200); pStroke.Thickness = 1.5; pStroke.Transparency = 0.1
            local pPad = Instance.new("UIPadding", panel)
            pPad.PaddingTop = UDim.new(0, 8); pPad.PaddingBottom = UDim.new(0, 8)
            pPad.PaddingLeft = UDim.new(0, 8); pPad.PaddingRight = UDim.new(0, 8)
            local pList = Instance.new("UIListLayout", panel)
            pList.SortOrder = Enum.SortOrder.LayoutOrder; pList.Padding = UDim.new(0, 4)

            -- T?tulo
            local titleRow = Instance.new("TextLabel", panel)
            titleRow.Size = UDim2.new(1, 0, 0, 22)
            titleRow.BackgroundTransparency = 1
            titleRow.Text = " Seleccionar Target del Silent Aim"
            titleRow.TextColor3 = Color3.fromRGB(0, 220, 190)
            titleRow.Font = Enum.Font.GothamBold
            titleRow.TextSize = 12
            titleRow.TextXAlignment = Enum.TextXAlignment.Left
            titleRow.ZIndex = 3
            titleRow.LayoutOrder = 0

            -- Bot?n para quitar custom target
            local clearBtn = Instance.new("TextButton", panel)
            clearBtn.Size = UDim2.new(1, 0, 0, 28)
            clearBtn.BackgroundColor3 = Color3.fromRGB(60, 20, 20)
            clearBtn.BackgroundTransparency = 0.3
            clearBtn.BorderSizePixel = 0
            clearBtn.Text = "  Usar Murder (sin custom)"
            clearBtn.TextColor3 = Color3.fromRGB(255, 180, 180)
            clearBtn.Font = Enum.Font.GothamSemibold
            clearBtn.TextSize = 11
            clearBtn.ZIndex = 3
            clearBtn.LayoutOrder = 1
            Instance.new("UICorner", clearBtn).CornerRadius = UDim.new(0, 6)
            clearBtn.Activated:Connect(function()
                CombatTabState.customTargetPlayer = nil
                CombatTabState.saCustomTargetName = ""
                CombatTabState.saUseCustomTarget  = false   -- sincronizar campo legacy
                _ctLabel.Text = "Target: ninguno"
                _closeSelector()
                CreateCustomNotification("CUSTOM TARGET", "Target limpiado ? usar? Murder", 2)
            end)

            -- Botones por cada jugador (excepto local)
            local allPlayers = game:GetService("Players"):GetPlayers()
            for i, plr in ipairs(allPlayers) do
                if plr ~= LocalPlayer then
                    local plrBtn = Instance.new("TextButton", panel)
                    plrBtn.Size = UDim2.new(1, 0, 0, 28)
                    plrBtn.BackgroundColor3 = (CombatTabState.customTargetPlayer == plr)
                        and Color3.fromRGB(0, 140, 120) or Color3.fromRGB(15, 40, 55)
                    plrBtn.BackgroundTransparency = 0.3
                    plrBtn.BorderSizePixel = 0
                    plrBtn.Text = "  " .. plr.Name
                    plrBtn.TextColor3 = Color3.fromRGB(210, 240, 255)
                    plrBtn.Font = Enum.Font.GothamSemibold
                    plrBtn.TextSize = 11
                    plrBtn.ZIndex = 3
                    plrBtn.LayoutOrder = i + 1
                    Instance.new("UICorner", plrBtn).CornerRadius = UDim.new(0, 6)
                    plrBtn.Activated:Connect(function()
                        CombatTabState.customTargetPlayer = plr
                        CombatTabState.saCustomTargetName = plr.Name
                        CombatTabState.saUseCustomTarget  = CombatTabState.useCustomTarget   -- sincronizar campo legacy
                        _ctLabel.Text = "Target: " .. plr.Name
                        _closeSelector()
                        CreateCustomNotification("CUSTOM TARGET", "Seleccionado: " .. plr.Name, 2)
                    end)
                end
            end

            -- Cerrar al hacer clic/toque en el fondo
            bg.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _closeSelector()
                end
            end)
        end)

        -- Descripci?n
        local _ctDesc = Instance.new("TextLabel", ctSection)
        _ctDesc.Size = UDim2.new(1, -8, 0, 0)
        _ctDesc.AutomaticSize = Enum.AutomaticSize.Y
        _ctDesc.BackgroundTransparency = 1
        _ctDesc.Text = "Usa Custom Target para apuntar a otro jugador en vez del Murder. Select Target abre el selector. Use Custom Target activa el sistema."
        _ctDesc.TextColor3 = Color3.fromRGB(130, 170, 220)
        _ctDesc.Font = Enum.Font.Montserrat
        _ctDesc.TextSize = 10
        _ctDesc.TextWrapped = true
        _ctDesc.TextXAlignment = Enum.TextXAlignment.Left
        _ctDesc.ZIndex = 13
        local _ctdPad = Instance.new("UIPadding", _ctDesc)
        _ctdPad.PaddingLeft = UDim.new(0, 6); _ctdPad.PaddingRight = UDim.new(0, 6)
        _ctdPad.PaddingTop = UDim.new(0, 2); _ctdPad.PaddingBottom = UDim.new(0, 4)
    end

    -- =========================================================
    -- SHOOT PICK + AUTO SHOOT MURDER
    -- =========================================================
    do
        local spSection = CreateBorderedSection(leftColumn, " AUTO SHOOT")

        -- Estado persistente
        CombatTabState.shootPickEnabled     = CombatTabState.shootPickEnabled     or false
        CombatTabState.shootPickConn        = CombatTabState.shootPickConn        or nil
        CombatTabState.autoShootMurderEnabled = CombatTabState.autoShootMurderEnabled or false
        CombatTabState.autoShootMurderConn  = CombatTabState.autoShootMurderConn  or nil
        CombatTabState.autoShootMurderWC    = (CombatTabState.autoShootMurderWC ~= nil) and CombatTabState.autoShootMurderWC or true

        -- Helper: dispara a un jugador con wall check opcional
        local function _shootAtPlayer(targetPlayer, wallCheckEnabled)
            if not targetPlayer or not targetPlayer.Character then return false end
            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHRP then return false end
            local tHRP  = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
            local tHead = targetPlayer.Character:FindFirstChild("Head") or tHRP
            if not tHRP then return false end
            local tHum  = targetPlayer.Character:FindFirstChildOfClass("Humanoid")
            if not tHum or tHum.Health <= 0 then return false end

            local aimPos = tHead and tHead.Position or tHRP.Position

            -- Wall check
            if wallCheckEnabled then
                if not wallCheckRaycast(myHRP.Position, aimPos, targetPlayer.Character) then
                    return false
                end
            end

            -- Obtener gun equipada (solo gun real, NO cuchillo ni otras tools)
            local gun = _findGunIn and _findGunIn(myChar)
            if not gun then return false end
            local shootRemote = getShootRemote and getShootRemote(gun)
            if not shootRemote then return false end

            pcall(function()
                local myChar2 = LocalPlayer.Character
                local myHRP2  = myChar2 and myChar2:FindFirstChild("HumanoidRootPart")
                local cam = workspace.CurrentCamera
                local originPos = (myHRP2 and myHRP2.Position + Vector3.new(0, 1.5, 0))
                              or (cam and cam.CFrame.Position)
                              or aimPos
                local oCF, tCF = buildShootCFrames(originPos, aimPos)
                if oCF and tCF then
                    shootRemote:FireServer(oCF, tCF)
                end
                -- FIX: eliminar fallback de 1 solo CFrame (firma incorrecta para MM2)
            end)
            return true
        end

        -- Toggle: Shoot Pick (dispara al murder cuando agarra el GunDrop)
        CombatTabState.shootPickEnabled = false
        CreateBorderedToggle(spSection, "Shoot Pick", function(enabled)
            CombatTabState.shootPickEnabled = enabled
            if CombatTabState.shootPickConn then
                pcall(function() CombatTabState.shootPickConn:Disconnect() end)
                CombatTabState.shootPickConn = nil
            end

            if enabled then
                local _dropNames = {GunDrop=true, DropGun=true, SheriffGun=true, HeroGun=true, Gun=true}

                local function _onGunPickedUp(obj)
                    obj.AncestryChanged:Connect(function()
                        if not CombatTabState.shootPickEnabled then return end
                        local p = obj.Parent
                        if not p then return end
                        local murder = findMurderer and findMurderer()
                        if murder and murder.Character == p then
                            task.wait(0.016)
                            local myChar = LocalPlayer.Character
                            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                            local tHRP   = murder.Character:FindFirstChild("HumanoidRootPart")
                            local tHead  = murder.Character:FindFirstChild("Head") or tHRP
                            if not myHRP or not tHead then return end

                            if not wallCheckRaycast(myHRP.Position, tHead.Position, murder.Character) then
                                CreateCustomNotification("SHOOT PICK", "Murder agarr? la gun (bloqueado por pared)", 1.5)
                                return
                            end

                            local gun = _findGunIn and _findGunIn(myChar)
                            if not gun then
                                CreateCustomNotification("SHOOT PICK", "Sin gun equipada", 2)
                                return
                            end
                            local shootRemote = getShootRemote and getShootRemote(gun)
                            if shootRemote then
                                pcall(function()
                                    local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP)
                                    local _cam = workspace.CurrentCamera
                                    local originPos = (barrelAtt and barrelAtt.WorldPosition)
                                                   or (_cam and _cam.CFrame.Position)
                                                   or (myHRP.Position + Vector3.new(0, 1.5, 0))
                                    local targetPos = tHead.Position
                                    local oCF, tCF = buildShootCFrames(originPos, targetPos)
                                    if oCF and tCF then
                                        shootRemote:FireServer(oCF, tCF)
                                    end
                                end)
                                CreateCustomNotification("SHOOT PICK", " Murder agarr? GunDrop ? disparado!", 2)
                            end
                        end
                    end)
                end

                CombatTabState.shootPickConn = workspace.DescendantAdded:Connect(function(obj)
                    if not CombatTabState.shootPickEnabled then return end
                    if obj:IsA("Tool") and _dropNames[obj.Name] then
                        _onGunPickedUp(obj)
                    end
                end)

                for _, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("Tool") and _dropNames[obj.Name] then
                        _onGunPickedUp(obj)
                    end
                end

                -- [notif removed]
            else
                -- [notif removed]
            end
        end, false)

        -- Toggle Wall Check del Shoot Pick
        local _spWallCheckEnabled = false
        CreateBorderedToggle(spSection, "Shoot Pick Wall Check", function(en)
            _spWallCheckEnabled = en
        end, false)

        -- ================================================================
        -- BOT?N: SHOOT MURDER
        -- Al presionar: TP detras del murder ? dispara ? TP de vuelta
        -- Tambi?n expone un BindableEvent en _G._ShootMurderBindable
        -- ================================================================

        -- BindableEvent para poder llamar la accion desde scripts externos:
        --   _G._ShootMurderBindable:Fire()
        if not _G._ShootMurderBindable then
            local _smBind = Instance.new("BindableEvent")
            _smBind.Name = "ShootMurderBindable"
            _G._ShootMurderBindable = _smBind
        end

        -- ================================================================
        -- SHOOT MURDER v2 (CORREGIDO)
        -- Logica:
        --   1. Verificar que sos Sheriff (tenes la gun equipada o en backpack)
        --   2. TP detras del murder (bien posicionado mirando al murder)
        --   3. Disparar via Silent Aim (FireServer con CFrames correctos)
        --   4. Iniciar listener: cuando una bala/proyectil del murder se
        --      acerque a tu HRP (<= 20 studs), TP de vuelta a savedCF
        --   5. Si no detecta bala en 3s, TP de vuelta igualmente
        -- ================================================================
        local _smCooldown = 0
        local _smBulletConn = nil  -- conexion del listener de bala

        -- Helper: detectar si somos Sheriff (tenemos gun equipada o en backpack)
        local function _isSheriff()
            local myChar = LocalPlayer.Character
            local myBP   = LocalPlayer.Backpack
            -- Verificar rol en cache del hub
            if _roleCache and (_roleCache.localRole == "Sheriff" or _roleCache.localRole == "Hero") then
                return true
            end
            -- Verificar por presencia de gun
            if myChar then
                local g = _findGunIn and _findGunIn(myChar)
                if g then return true end
            end
            if myBP then
                local g = _findGunIn and _findGunIn(myBP)
                if g then return true end
            end
            return false
        end

        -- Helper: construir CFrames de disparo correctos para MM2
        local function _buildShootCF(originPos, targetPos)
            local dir = targetPos - originPos
            if dir.Magnitude < 0.01 then return nil, nil end
            local dirU = dir.Unit
            local upV  = math.abs(dirU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
            local oCF  = CFrame.lookAt(originPos, targetPos, upV)
            local bkDir = (originPos - targetPos)
            local bkU   = bkDir.Magnitude > 0.01 and bkDir.Unit or -dirU
            local bkUp  = math.abs(bkU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
            local tCF   = CFrame.lookAt(targetPos, targetPos + bkU, bkUp)
            return oCF, tCF
        end

        -- Helper: TP seguro que tambien anula la velocidad
        local function _safeTeleport(hrp, cf)
            pcall(function()
                hrp.CFrame = cf
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end

        -- Detener listener de bala activo
        local function _stopBulletListener()
            if _smBulletConn then
                pcall(function() _smBulletConn:Disconnect() end)
                _smBulletConn = nil
            end
        end

        -- Funcion central de un solo disparo
        local function _doShootMurderOnce()
            local now = tick()
            if now - _smCooldown < 0.8 then return end
            _smCooldown = now

            -- Detener listener anterior si quedo activo
            _stopBulletListener()

            -- === 1. VERIFICAR ROL SHERIFF ===
            if not _isSheriff() then
                CreateCustomNotification("SHOOT MURDER", "No eres Sheriff (sin gun).", 2)
                return
            end

            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myHRP or not myHum or myHum.Health <= 0 then
                CreateCustomNotification("SHOOT MURDER", "Sin personaje.", 2); return
            end

            -- === 2. ENCONTRAR MURDER ===
            local murder = findMurderer and findMurderer()
            if not murder or not murder.Character then
                CreateCustomNotification("SHOOT MURDER", "Murder no encontrado.", 2); return
            end

            local mHRP = murder.Character:FindFirstChild("HumanoidRootPart")
            local mHum = murder.Character:FindFirstChildOfClass("Humanoid")
            if not mHRP or not mHum or mHum.Health <= 0 then
                CreateCustomNotification("SHOOT MURDER", "Murder muerto.", 2); return
            end

            -- Validar ronda activa
            if _G._betweenRounds or not _G._roundStartTime
            or (os.clock() - (_G._roundStartTime or 0)) < 1.5  -- FIX #3
            or mHRP.Position.Y > 70 then
                CreateCustomNotification("SHOOT MURDER", "Ronda no activa.", 2); return
            end

            -- === 3. OBTENER GUN (equipar si esta en backpack) ===
            local gun = _findGunIn and _findGunIn(myChar)
            if not gun then
                -- Intentar equipar desde backpack
                local gunBP = _findGunIn and _findGunIn(LocalPlayer.Backpack)
                if gunBP then
                    pcall(function() myHum:EquipTool(gunBP) end)
                    task.wait(0.08)
                    gun = _findGunIn and _findGunIn(myChar)
                end
            end
            if not gun then
                CreateCustomNotification("SHOOT MURDER", "No tienes gun disponible.", 2); return
            end

            -- === 4. GUARDAR POSICION ORIGINAL ===
            local savedCF = myHRP.CFrame

            -- === 5. TP DETRAS DEL MURDER ===
            -- Posicionarse 4 studs atras del murder, mirando hacia el murder
            local mCF      = mHRP.CFrame
            local behindPos = mCF.Position + mCF.LookVector * 4  -- detras segun donde mira el murder
            -- Asegurarse de quedar a la misma altura del HRP del murder
            behindPos = Vector3.new(behindPos.X, mHRP.Position.Y, behindPos.Z)
            -- CFrame mirando al murder
            local tpCF = CFrame.lookAt(behindPos, mHRP.Position)
            _safeTeleport(myHRP, tpCF)
            task.wait(0.10)

            -- Re-obtener referencias por si el murder se movio
            mHRP = murder.Character and murder.Character:FindFirstChild("HumanoidRootPart")
            if not mHRP then
                _safeTeleport(myHRP, savedCF)
                CreateCustomNotification("SHOOT MURDER", "Murder desaparecio.", 1.5); return
            end

            -- === 6. DISPARAR CON SILENT AIM ===
            local mHead = murder.Character:FindFirstChild("Head") or mHRP
            local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP)
            local _cam = workspace.CurrentCamera
            local originPos = (barrelAtt and barrelAtt.WorldPosition)
                           or (_cam and _cam.CFrame.Position)
                           or (myHRP.Position + Vector3.new(0, 1.5, 0))

            -- Usar prediccion de posicion si esta activa (similar a _saGetTargetCF)
            local aimPos = mHead.Position
            if CombatTabState and CombatTabState.saUsePrediction and _unifiedBalisticSolver then
                local tPart = mHead
                local flags = {
                    usePrediction = true,
                    predictJump   = CombatTabState.saPredJump   or false,
                    predictAccel  = CombatTabState.saPredAccel  or true,
                    predictTrend  = CombatTabState.saPredTrend  or false,
                    predictLag    = CombatTabState.saPredLag    or false,
                    predictStrafe = CombatTabState.saPredStrafe or false,
                }
                local predicted = pcall(function()
                    return _unifiedBalisticSolver(tPart, mHRP, flags, murder)
                end)
                if predicted and typeof(predicted) == "Vector3"
                    and (predicted - mHRP.Position).Magnitude < 60 then
                    aimPos = predicted
                end
            end

            local oCF, tCF = _buildShootCF(originPos, aimPos)
            local shootRem = getShootRemote and getShootRemote(gun)

            if oCF and tCF and shootRem and shootRem:IsA("RemoteEvent") then
                -- Disparar (doble disparo para mayor seguridad)
                pcall(function() shootRem:FireServer(oCF, tCF) end)
                task.wait(0.04)
                -- Re-calcular por si se movio un poco
                originPos = (barrelAtt and barrelAtt.WorldPosition)
                         or (myHRP.Position + Vector3.new(0, 1.5, 0))
                local mHead2 = murder.Character and murder.Character:FindFirstChild("Head")
                if mHead2 then
                    local oCF2, tCF2 = _buildShootCF(originPos, mHead2.Position)
                    if oCF2 and tCF2 then
                        pcall(function() shootRem:FireServer(oCF2, tCF2) end)
                    end
                end
            elseif _fireGunMM2 then
                -- Fallback via camara
                local cam = _Camera
                local origCamCF = cam and cam.CFrame
                pcall(function()
                    if cam then cam.CFrame = CFrame.lookAt(cam.CFrame.Position, mHead.Position) end
                end)
                _fireGunMM2(gun)
                task.wait(0.04)
                _fireGunMM2(gun)
                pcall(function()
                    if cam and origCamCF then cam.CFrame = origCamCF end
                end)
            end

            CreateCustomNotification("SHOOT MURDER", "Bala redirigida -> " .. murder.Name, 2)

            -- === 7. LISTENER: TP VUELTA CUANDO SE DETECTA BALA DEL MURDER ===
            -- Monitorea proyectiles/bala que vengan hacia mi HRP.
            -- Si alguna parte con nombre de bala/proyectil se acerca <= 15 studs, TP vuelta.
            -- Fallback automatico a los 2.5 segundos.
            local _listenStart = tick()
            local _myHRPRef    = myHRP  -- captura por closure
            local _savedCFRef  = savedCF

            -- Callback que ejecuta el TP de vuelta (una sola vez)
            local _tpBackDone = false
            local function _doTpBack(reason)
                if _tpBackDone then return end
                _tpBackDone = true
                _stopBulletListener()
                _safeTeleport(_myHRPRef, _savedCFRef)
                -- Pequena notificacion solo en modo debug (opcional)
                -- CreateCustomNotification("SHOOT MURDER", "Vuelta: " .. (reason or ""), 1)
            end

            -- Bullet names tipicos de MM2 (proyectiles del servidor)
            local _bulletKeywords = {
                "bullet", "projectile", "proj", "shot", "pellet",
                "Bullet", "Projectile", "Shot",
            }
            local function _isBulletPart(part)
                if not part:IsA("BasePart") then return false end
                local n = part.Name:lower()
                for _, kw in ipairs(_bulletKeywords) do
                    if n:find(kw:lower()) then return true end
                end
                return false
            end

            -- OPT LAG FIX: en lugar de GetDescendants() cada 3 frames (caro con mapa grande),
            -- usamos DescendantAdded para registrar balas en una tabla liviana.
            -- El Heartbeat solo itera esa tabla pequena (~0-5 objetos) en vez de todo el workspace.
            local _activeBullets = {}
            local _bulletAddConn = workspace.DescendantAdded:Connect(function(obj)
                if _isBulletPart(obj) then
                    _activeBullets[obj] = true
                    -- Auto-limpiar cuando la bala desaparece
                    obj.AncestryChanged:Connect(function()
                        if not obj.Parent then _activeBullets[obj] = nil end
                    end)
                end
            end)
            local _bulletRemConn = workspace.DescendantRemoving:Connect(function(obj)
                _activeBullets[obj] = nil
            end)

            local _hbCount = 0
            _smBulletConn = RunService.Heartbeat:Connect(function()
                _hbCount = _hbCount + 1

                -- Fallback timeout: 2.5 segundos
                if tick() - _listenStart > 2.5 then
                    pcall(function() _bulletAddConn:Disconnect() end)
                    pcall(function() _bulletRemConn:Disconnect() end)
                    _doTpBack("timeout")
                    return
                end

                -- Solo chequear cada 3 frames (aprox 18Hz)
                if _hbCount % 3 ~= 0 then return end

                if not _myHRPRef or not _myHRPRef.Parent then
                    pcall(function() _bulletAddConn:Disconnect() end)
                    pcall(function() _bulletRemConn:Disconnect() end)
                    _doTpBack("hrp_lost")
                    return
                end

                local myPos = _myHRPRef.Position

                -- OPT: iterar solo la tabla de balas activas (O(n) balas, no O(workspace))
                for obj in pairs(_activeBullets) do
                    if obj and obj.Parent then
                        local dist = (obj.Position - myPos).Magnitude
                        if dist <= 20 then
                            pcall(function() _bulletAddConn:Disconnect() end)
                            pcall(function() _bulletRemConn:Disconnect() end)
                            _doTpBack("bullet_detected")
                            return
                        end
                    else
                        _activeBullets[obj] = nil  -- limpiar referencias muertas
                    end
                end

                -- Chequear si el murder esta muy cerca (<8 studs)
                if murder and murder.Character then
                    local mHRP2 = murder.Character:FindFirstChild("HumanoidRootPart")
                    if mHRP2 then
                        local dist2 = (myPos - mHRP2.Position).Magnitude
                        if dist2 < 8 then
                            pcall(function() _bulletAddConn:Disconnect() end)
                            pcall(function() _bulletRemConn:Disconnect() end)
                            _doTpBack("too_close")
                            return
                        end
                    end
                end
            end)
        end

        -- Conectar BindableEvent a la misma funcion
        _G._ShootMurderBindable.Event:Connect(_doShootMurderOnce)

        -- ================================================================
        -- BOT?N: KILL SHERIFF
        -- ================================================================
        if not _G._KillSheriffBindable then
            local _ksBind = Instance.new("BindableEvent")
            _ksBind.Name = "KillSheriffBindable"
            _G._KillSheriffBindable = _ksBind
        end

        local _ksCooldown = 0
        local function _doKillSheriff()
            local now = tick()
            if now - _ksCooldown < 0.5 then return end
            _ksCooldown = now

            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myHRP or not myHum or myHum.Health <= 0 then
                CreateCustomNotification("KILL SHERIFF", "Sin personaje.", 2); return
            end

            local knife = myChar:FindFirstChild("Knife")
            if not knife then knife = EquipKnife() end
            if not knife then
                CreateCustomNotification("KILL SHERIFF", "No tienes knife.", 2); return
            end

            local sheriff = findSheriffPlayer and findSheriffPlayer()
            if not sheriff or not sheriff.Character then
                CreateCustomNotification("KILL SHERIFF", "Sheriff no encontrado.", 2); return
            end

            local sHRP = sheriff.Character:FindFirstChild("HumanoidRootPart")
            local sHum = sheriff.Character:FindFirstChildOfClass("Humanoid")
            if not sHRP or not sHum or sHum.Health <= 0 then
                CreateCustomNotification("KILL SHERIFF", "Sheriff ya muerto.", 2); return
            end

            local savedCF  = myHRP.CFrame
            local savedVel = myHRP.AssemblyLinearVelocity

            FireKnifeOnTarget(knife, sHRP)
            task.wait(0.05)
            FireKnifeOnTarget(knife, sHRP)

            _sp(function()
                pcall(function()
                    myHRP.CFrame = savedCF
                    myHRP.AssemblyLinearVelocity = savedVel or Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                end)
            end)

            CreateCustomNotification("KILL SHERIFF", "Cuchillo lanzado -> " .. sheriff.Name, 2)
        end

        _G._KillSheriffBindable.Event:Connect(_doKillSheriff)

        -- ================================================================
        -- BOTONES CLICKEABLES DEL HUB (dentro del panel)
        -- ================================================================
        CreateButton(spSection, "SHOOT MURDER", ThemeColors.Primary, function()
            task.spawn(_doShootMurderOnce)
        end)
        CreateButton(spSection, "KILL SHERIFF", ThemeColors.Primary, function()
            task.spawn(_doKillSheriff)
        end)

        -- Descripcion en el panel
        local _spDesc = Instance.new("TextLabel", spSection)
        _spDesc.Size = UDim2.new(1, -8, 0, 0)
        _spDesc.AutomaticSize = Enum.AutomaticSize.Y
        _spDesc.BackgroundTransparency = 1
        _spDesc.Text = "Shoot Pick: dispara al Murder cuando agarra el GunDrop. SHOOT MURDER: TP detras del murder y dispara. KILL SHERIFF: lanza el cuchillo al sheriff. Bindables: _G._ShootMurderBindable:Fire() / _G._KillSheriffBindable:Fire()"
        _spDesc.TextColor3 = Color3.fromRGB(130, 170, 220)
        _spDesc.Font = Enum.Font.Montserrat
        _spDesc.TextSize = 10
        _spDesc.TextWrapped = true
        _spDesc.TextXAlignment = Enum.TextXAlignment.Left
        _spDesc.ZIndex = 13
        local _spDescPad = Instance.new("UIPadding", _spDesc)
        _spDescPad.PaddingLeft = UDim.new(0, 6); _spDescPad.PaddingRight = UDim.new(0, 6)
        _spDescPad.PaddingTop = UDim.new(0, 2); _spDescPad.PaddingBottom = UDim.new(0, 4)
    end

    -- [Silent Aim Basic RMB eliminado por usuario]
    CombatTabState.shootOnRMB = false
    CombatTabState._rmbConn   = nil

    -- -- Prediction Mode selector ----------------------------------------------
    -- None       -> GunClient original sin modificar (WeaponService:GetMouseTargetCFrame)
    -- Ping Lead  -> GunClient modificado con ShootStart:FireServer + prediccin de ping
    -- Dynamic    -> Solver dinmico del hub (GunClient deshabilitado, hub toma control)
    -- Advanced   -> Solver avanzado completo (GunClient deshabilitado, hub toma control)
    -- Migrar modos viejos a "Default"
    do
        local _gpm = CombatTabState.gunPredMode
        local _validModes = { ["Default"]=true, ["Advanced GunClient"]=true, ["Ghost Take"]=true, ["Tianca Half"]=true }
        if not _validModes[_gpm] then
            CombatTabState.gunPredMode = "Default"
        end
    end
    CombatTabState.gunPredMode = CombatTabState.gunPredMode or "Default"

    -- Hook de ShootStart:FireServer para el modo "Ping Lead"
    -- El GunClient modificado usa ShootStart en vez de Shoot para disparar
    -- Interceptamos ese FireServer y reemplazamos la posicin con prediccin de ping
    local _gcPingHooked   = false
    local _gcPingLastFire = -999
    local _gcPingHookConn = nil

    local function _gcInstallPingHook(gun)
        if _gcPingHooked then return end
        local gs = gun and gun:FindFirstChild("GunServer")
        local shootStart = gs and gs:FindFirstChild("ShootStart")
        if not shootStart then
            -- Fallback: buscar Shoot directo
            shootStart = gun and (gun:FindFirstChild("Shoot") or getShootRemote and getShootRemote(gun))
        end
        if not shootStart then return end

        if hookfunction and newcclosure then
            local _origFS = shootStart.FireServer
            hookfunction(_origFS, newcclosure(function(self, ...)
                if CombatTabState.gunPredMode ~= "Ping Lead" then
                    return _origFS(self, ...)
                end
                if os.clock() - _gcPingLastFire < 0.05 then return end
                _gcPingLastFire = os.clock()

                -- Calcular posicin predicha con ping
                local myChar = LocalPlayer.Character
                local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local target = findMurderer and findMurderer()
                if not target then
                    -- Buscar cualquier enemigo cercano
                    if myHRP then
                        local best, bestD = nil, math.huge
                        for _, p in ipairs(_cachedPlayers) do
                            if p ~= LocalPlayer and p.Character then
                                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                if hrp and hum and hum.Health > 0 then
                                    local d = (hrp.Position - myHRP.Position).Magnitude
                                    if d < bestD then bestD = d; best = p end
                                end
                            end
                        end
                        target = best
                    end
                end

                if target and target.Character and myHRP then
                    local tHRP  = target.Character:FindFirstChild("HumanoidRootPart")
                    local tPart = target.Character:FindFirstChild(CombatTabState.saTargetPart or "Head") or tHRP
                    local tHum  = target.Character:FindFirstChildOfClass("Humanoid")
                    if tHRP and tHum and tHum.Health > 0 and tPart then
                        -- Prediccin simple: posicin + velocidad * ping
                        local pingMs = 60
                        pcall(function() pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
                        local pSec = pingMs / 1000
                        local vel  = tHRP.AssemblyLinearVelocity or Vector3.new()
                        local predicted = tPart.Position + Vector3.new(vel.X * pSec, 0, vel.Z * pSec)
                        -- Usar firma de ShootStart del GunClient2: FireServer(1, position)
                        return _origFS(self, 1, predicted)
                    end
                end
                -- Sin target: dejar pasar original
                return _origFS(self, ...)
            end))
            _gcPingHooked = true
        end
    end

    local function _gcRemovePingHook()
        _gcPingHooked = false
    end

    -- ==========================================================================
    -- SISTEMA DE PREDICCIN POR HOOK  nunca toca GunClient.Disabled ni .Source
    -- Hookea el FireServer del remote de disparo y reemplaza el targetCF/pos
    -- con la prediccin correspondiente segn el modo activo.
    -- None siempre pasa sin tocar nada.
    -- ==========================================================================

    -- Estado del hook principal de disparo
    local _predHooked    = false
    local _predLastFire  = -999
    local _predHookedRemote = nil  -- remote que fue hookeado

    -- Funcin auxiliar: encontrar el mejor target (custom target o murderer)
    local function _predGetTarget()
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return nil end
        -- Respetar custom target si est? activo
        local target = (_G._getEffectiveTarget and _G._getEffectiveTarget())
                    or (findMurderer and findMurderer())
        return target, myHRP
    end

    -- Calcular posicin predicha segn el modo
    -- Devuelve Vector3 o nil (nil = dejar pasar sin modificar)
    local function _predCalcPos(mode)
        local target, myHRP = _predGetTarget()
        if not target or not myHRP then return nil end
        local ch   = target.Character
        local tHRP = ch and ch:FindFirstChild("HumanoidRootPart")
        local tPart = ch and ch:FindFirstChild(CombatTabState.saTargetPart or "Head") or tHRP
        local tHum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not tHRP or not tHum or tHum.Health <= 0 or not tPart then return nil end

        local vel    = tHRP.AssemblyLinearVelocity or Vector3.new()
        local pingMs = 60
        pcall(function() pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
        local pSec   = pingMs / 1000

        local function _applyTiancai(pos)
            local offset = CombatTabState.gunTiancaiOffset or 250
            if offset == 0 then return pos end
            return pos + vel * (offset / 1000)
        end

        if mode == "Level" then
            -- Level: GunClient 1 (Shoot:FireServer graCF+targetCF) - ping lead basico
            -- graCF = GunRaycastAttachment.WorldCFrame reorientado al target
            -- targetCF = CFrame en predictedPos mirando de vuelta al origen
            local myChar2 = LocalPlayer.Character
            if not myChar2 then return nil end
            local myHRP2 = myChar2:FindFirstChild("HumanoidRootPart")
            if not myHRP2 then return nil end
            local gra = myHRP2:FindFirstChild("GunRaycastAttachment")
            if not gra then
                gra = Instance.new("Attachment")
                gra.Name = "GunRaycastAttachment"
                gra.Position = Vector3.new(0, 1.35, -1)
                gra.Parent = myHRP2
            end
            local predictedPos1 = _applyTiancai(tPart.Position + Vector3.new(vel.X * pSec, 0, vel.Z * pSec))
            local origin1 = gra.WorldCFrame.Position
            local dir1 = predictedPos1 - origin1
            if dir1.Magnitude < 0.01 then return nil end
            local dirU1 = dir1.Unit
            local upV1  = math.abs(dirU1.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
            local graCF_gc1 = CFrame.new(origin1) * CFrame.lookAt(Vector3.zero, dirU1, upV1)
            local backDir1 = (origin1 - predictedPos1)
            local backU1   = backDir1.Magnitude > 0.01 and backDir1.Unit or -dirU1
            local bkUp1    = math.abs(backU1.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
            local targetCF_gc1 = CFrame.lookAt(predictedPos1, predictedPos1 + backU1, bkUp1)
            CombatTabState._gc1_graCF    = graCF_gc1
            CombatTabState._gc1_targetCF = targetCF_gc1
            return predictedPos1

        elseif mode == "Full" then
            -- Full: GunClient 2 (ShootStart:FireServer Vector3) - jump+accel+lag
            -- Usa el solver balstico con jump+accel+lag para la posicin
            local ok2, solved2 = pcall(function()
                return _unifiedBalisticSolver and _unifiedBalisticSolver(tPart, tHRP, {
                    usePrediction = true,
                    predictJump   = true,
                    predictAccel  = true,
                    predictTrend  = true,
                    predictLag    = true,
                    predictStrafe = false,
                }, target)
            end)
            if ok2 and solved2 then return _applyTiancai(solved2) end
            return _applyTiancai(tPart.Position + Vector3.new(vel.X * pSec, 0, vel.Z * pSec))

        elseif mode == "Advanced" then
            local ok, solved = pcall(function()
                return _unifiedBalisticSolver and _unifiedBalisticSolver(tPart, tHRP, {
                    usePrediction = true,
                    predictJump   = true,
                    predictAccel  = true,
                    predictTrend  = true,
                    predictLag    = true,
                    predictStrafe = true,
                }, target)
            end)
            if ok and solved then return _applyTiancai(solved) end
            return _applyTiancai(tPart.Position + Vector3.new(vel.X * pSec, 0, vel.Z * pSec))
        end

        return nil
    end

    CombatTabState._predCalcPos = _predCalcPos

    -- Instalar el hook en el remote de disparo (Shoot o ShootStart)
    local function _predInstallHook()
        if _predHooked then return end
        if not (hookfunction and newcclosure) then return end

        local gun = LocalPlayer.Character and _findGunIn and _findGunIn(LocalPlayer.Character)
                 or LocalPlayer.Backpack   and _findGunIn and _findGunIn(LocalPlayer.Backpack)
        if not gun then return end

        -- Buscar remote: primero Shoot directo, luego GunServer/ShootStart
        local remote = gun:FindFirstChild("Shoot")
        if not remote or not remote:IsA("RemoteEvent") then
            local gs = gun:FindFirstChild("GunServer")
            remote = gs and (gs:FindFirstChild("ShootStart") or gs:FindFirstChild("Shoot"))
        end
        if not remote or not remote:IsA("RemoteEvent") then
            remote = getShootRemote and getShootRemote(gun)
        end
        if not remote then return end

        _predHookedRemote = remote
        local _origFS = remote.FireServer

        hookfunction(_origFS, newcclosure(function(self, ...)
            local pm = CombatTabState.gunPredMode
            -- None: pasar siempre sin tocar
            if pm == "Default" then
                return _origFS(self, ...)
            end
            -- Rate limit: dejar pasar el disparo original incluso si hay cooldown
            if os.clock() - _predLastFire < 0.05 then return _origFS(self, ...) end
            _predLastFire = os.clock()

            local predictedPos = _predCalcPos(pm)
            if not predictedPos then
                return _origFS(self, ...)
            end

            -- Detectar firma del remote y reemplazar el argumento de posicin/CFrame
            local args = {...}
            local replaced = false

            -- Firma 1: FireServer(originCF, targetCF)  -> args[1]=CFrame, args[2]=CFrame
            if typeof(args[1]) == "CFrame" and (typeof(args[2]) == "CFrame" or args[2] == nil) then
                -- GunClient 1: usar graCF y targetCF precalculados si estn disponibles
                local _gc1gra = CombatTabState._gc1_graCF
                local _gc1tgt = CombatTabState._gc1_targetCF
                if pm == "Level" and _gc1gra and _gc1tgt then
                    args[1] = _gc1gra
                    args[2] = _gc1tgt
                else
                    local dir = (predictedPos - args[1].Position).Unit
                    args[2] = CFrame.new(predictedPos, predictedPos + dir)
                end
                replaced = true
            -- Firma 2: FireServer(1, Vector3)  -> args[1]=number, args[2]=Vector3
            elseif typeof(args[1]) == "number" and typeof(args[2]) == "Vector3" then
                args[2] = predictedPos
                replaced = true
            -- Firma 3: FireServer(Vector3)  -> args[1]=Vector3
            elseif typeof(args[1]) == "Vector3" then
                args[1] = predictedPos
                replaced = true
            -- Firma 4: FireServer(CFrame) sola -> args[1]=CFrame target
            elseif typeof(args[1]) == "CFrame" and #args == 1 then
                local dir = Vector3.new(0, 0, -1)
                args[1] = CFrame.new(predictedPos, predictedPos + dir)
                replaced = true
            end

            if replaced then
                return _origFS(self, table.unpack(args))
            else
                return _origFS(self, ...)
            end
        end))

        _predHooked = true
    end

    local function _predRemoveHook()
        -- hookfunction no se puede desinstalar; el hook ya chequea pm == "Default" y pasa sin tocar nada
        _predHooked = false
        _predHookedRemote = nil
        _gcPingHooked = false
        -- FIX: forzar modo Default en CombatTabState para que el hook lo bypasee correctamente
        if CombatTabState then CombatTabState.gunPredMode = "Default" end
    end
    -- Hook directo sobre el GunClient LocalScript de MM2
    -- Modifica la funcion de disparo inyectando la posicion del target del Silent Aim
    local _gcHooked       = false
    local _gcHookedGun    = nil
    local _gcOrigActivate = nil
    local _gcOrigTouch    = nil

    local function _gcGetTarget()
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return nil end
        -- Respetar custom target si est? activo, luego murderer como fallback
        local target = (_G._getEffectiveTarget and _G._getEffectiveTarget())
                    or (CombatTabState.saTarget and Players:FindFirstChild(CombatTabState.saTarget))
                    or (findMurderer and findMurderer())
        return target
    end

    local function _gcGetTargetCFrame(mode)
        local target = _gcGetTarget()
        if not target or not target.Character then return nil end
        local ch   = target.Character
        local tHRP = ch:FindFirstChild("HumanoidRootPart")
        local part = ch:FindFirstChild(CombatTabState.saTargetPart or "Head") or tHRP
        local hum  = ch:FindFirstChildOfClass("Humanoid")
        if not part or not tHRP or not hum or hum.Health <= 0 then return nil end

        local vel    = tHRP.AssemblyLinearVelocity or Vector3.zero
        local pingMs = 60
        pcall(function() pingMs = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
        local pSec   = pingMs / 1000

        local predictedPos

        if mode == "Advanced GunClient" then
            -- Advanced GunClient: firma Shoot:FireServer(graCF, targetCF)
            -- Igual al GunClient 1 y 2 originales pero con prediccion de ping + strafe
            local strafeScale = CombatTabState.gunStrafeScale or 1.0
            local horizVel    = Vector3.new(vel.X, 0, vel.Z)
            predictedPos = part.Position
                         + horizVel * pSec * strafeScale
                         + Vector3.new(0, (vel.Y > 0 and vel.Y * pSec * 0.5 or 0), 0)

        elseif mode == "Ghost Take" then
            -- Ghost Take: firma Shoot:FireServer(graCF, targetCF)
            -- Prediccion suave: solo compensacion horizontal de ping, sin salto
            predictedPos = part.Position + Vector3.new(vel.X * pSec, 0, vel.Z * pSec)

        elseif mode == "Tianca Half" then
            -- Tianca Half: firma ShootStart:FireServer(Vector3)
            -- Media prediccion: mitad del offset de velocidad (menos agresivo)
            local offset = (CombatTabState.gunTiancaiOffset or 250) / 1000
            predictedPos = part.Position + vel * offset
        end

        if not predictedPos then return nil end

        -- Construir CFrame apuntando desde GunRaycastAttachment al target
        local myChar2 = LocalPlayer.Character
        local myHRP2  = myChar2 and myChar2:FindFirstChild("HumanoidRootPart")
        local gra     = myHRP2 and myHRP2:FindFirstChild("GunRaycastAttachment")
        if not gra then
            if myHRP2 then
                gra = Instance.new("Attachment")
                gra.Name = "GunRaycastAttachment"
                gra.Position = Vector3.new(0, 1.35, -1)
                gra.Parent = myHRP2
            else
                return nil
            end
        end

        local origin = gra.WorldCFrame.Position
        local dir    = (predictedPos - origin)
        if dir.Magnitude < 0.01 then return nil end
        local dirU   = dir.Unit
        local upV    = math.abs(dirU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
        local graCF  = CFrame.new(origin) * CFrame.lookAt(Vector3.zero, dirU, upV)
        local backDir = (origin - predictedPos)
        local backU   = backDir.Magnitude > 0.01 and backDir.Unit or -dirU
        local bkUp    = math.abs(backU.Y) > 0.98 and Vector3.xAxis or Vector3.yAxis
        local tgtCF   = CFrame.lookAt(predictedPos, predictedPos + backU, bkUp)

        return graCF, tgtCF, predictedPos
    end

    local function _gcInstallGunClientHook(gun, mode)
        if not gun then return end
        if not (hookfunction and newcclosure) then return end
        if _gcHooked and _gcHookedGun == gun then return end

        _gcHooked   = false
        _gcHookedGun = gun

        if mode == "Tianca Half" then
            -- Bacon GunClient: hookear ShootStart:FireServer(Vector3)
            local gs = gun:FindFirstChild("GunServer")
            local shootStart = gs and gs:FindFirstChild("ShootStart")
            if not shootStart then return end
            local _origFS = shootStart.FireServer
            hookfunction(_origFS, newcclosure(function(self, ...)
                local pm = CombatTabState.gunPredMode
                if pm ~= "Tianca Half" then return _origFS(self, ...) end
                local _, _, predictedPos = _gcGetTargetCFrame(pm)
                if predictedPos then
                    return _origFS(self, predictedPos)
                end
                return _origFS(self, ...)
            end))
            _gcHooked = true

        else
            -- GunClient 1/2: hookear Shoot:FireServer(graCF, targetCF)
            local shootRemote = gun:FindFirstChild("Shoot")
            if not shootRemote or not shootRemote:IsA("RemoteEvent") then
                local gs = gun:FindFirstChild("GunServer")
                shootRemote = gs and (gs:FindFirstChild("Shoot") or gs:FindFirstChild("ShootStart"))
            end
            if not shootRemote then
                shootRemote = getShootRemote and getShootRemote(gun)
            end
            if not shootRemote then return end
            local _origFS = shootRemote.FireServer
            hookfunction(_origFS, newcclosure(function(self, ...)
                local pm = CombatTabState.gunPredMode
                if pm == "Default" then return _origFS(self, ...) end
                local graCF, tgtCF, predictedPos = _gcGetTargetCFrame(pm)
                if not graCF or not tgtCF then return _origFS(self, ...) end
                local args = {...}
                -- Detectar firma y reemplazar
                if typeof(args[1]) == "CFrame" then
                    args[1] = graCF
                    if typeof(args[2]) == "CFrame" or args[2] == nil then
                        args[2] = tgtCF
                    end
                    return _origFS(self, table.unpack(args))
                elseif typeof(args[1]) == "Vector3" then
                    args[1] = predictedPos
                    return _origFS(self, table.unpack(args))
                end
                return _origFS(self, ...)
            end))
            _gcHooked = true
        end
    end

    local function _gcRemoveHook()
        _gcHooked    = false
        _gcHookedGun = nil
    end

    local function _applyGunPredMode(mode)
        CombatTabState.gunPredMode = mode

        if mode == "Default" then
            _predRemoveHook()
            _gcRemoveHook()

        elseif mode == "Advanced GunClient" or mode == "Ghost Take" or mode == "Tianca Half" then
            _predRemoveHook()
            -- Instalar hook sobre el GunClient real
            local gun = LocalPlayer.Character and _findGunIn and _findGunIn(LocalPlayer.Character)
                     or LocalPlayer.Backpack   and _findGunIn and _findGunIn(LocalPlayer.Backpack)
            _gcInstallGunClientHook(gun, mode)
        end

        CreateCustomNotification("SA GUN", mode, 1.5)
    end

    -- Heartbeat: re-instalar hook si la gun cambio (equip/respawn)
    local _predHookTick = 0
    RegisterTabConn(RunService.Heartbeat:Connect(function()
        _predHookTick = _predHookTick + 1; if _predHookTick < 30 then return end; _predHookTick = 0
        local pm = CombatTabState.gunPredMode
        if pm == "Default" then return end
        -- GunClient hook
        local gun = LocalPlayer.Character and _findGunIn and _findGunIn(LocalPlayer.Character)
                 or LocalPlayer.Backpack   and _findGunIn and _findGunIn(LocalPlayer.Backpack)
        if gun and (not _gcHooked or _gcHookedGun ~= gun) then
            _gcInstallGunClientHook(gun, pm)
        end
    end))

    -- Aplicar el modo guardado (o None por defecto)
    _applyGunPredMode(CombatTabState.gunPredMode or "Default")


    -- ==============================================================
    -- Variables de prediccin avanzada para gun SA
    CombatTabState.gunHorizAimMult    = CombatTabState.gunHorizAimMult    or 1.10
    CombatTabState.gunVertAimMult     = CombatTabState.gunVertAimMult     or 1.15
    CombatTabState.gunPredDivHMin     = CombatTabState.gunPredDivHMin     or 32.72
    CombatTabState.gunPredDivHMax     = CombatTabState.gunPredDivHMax     or 53.58
    CombatTabState.gunMaxPredDist     = CombatTabState.gunMaxPredDist     or 250.0
    CombatTabState.gunVertPredMult    = CombatTabState.gunVertPredMult    or 1.0
    CombatTabState.gunLatencyComp     = CombatTabState.gunLatencyComp     or 1.0
    CombatTabState.gunStrafeScale     = CombatTabState.gunStrafeScale     or 1.0
    CombatTabState.gunAccelBias       = CombatTabState.gunAccelBias       or 0.5
    CombatTabState.gunJumpLead        = CombatTabState.gunJumpLead        or 1.0
    -- Prediccin gun: horizontal/vertical min/max (misma lgica que knife)
    CombatTabState.gunPredHMin        = CombatTabState.gunPredHMin        or 20
    CombatTabState.gunPredHMax        = CombatTabState.gunPredHMax        or 55
    CombatTabState.gunPredVMin        = CombatTabState.gunPredVMin        or 18
    CombatTabState.gunPredVMax        = CombatTabState.gunPredVMax        or 40

    -- == COPY CONFIG GUN  sistema de diagnstico igual al Knife ==============
    -- Tabla de setters para mover los sliders programticamente desde el analyzer
    local _gpSliderSet = {}

    -- Funcin para crear un slider de prediccin gun con setter programtico
    -- (misma lgica que CreateKnifePredSlider pero para la seccin silentAimSection)
    local function CreateGunPredSlider(parent, title, minVal, maxVal, defaultVal, callback)
        -- ==============================================================
        --  GUN PRED SLIDER  misma apariencia que CreateSlider
        --  Panel cristal con gradiente diagonal  borde aurora shimmer
        --  Caja de valor separada  track teal  thumb blanco circular
        -- ==============================================================
        local C_STROKE   = ThemeColors.Primary
        local C_TEXT     = ThemeColors.TextPrimary
        local C_SUBTEXT  = ThemeColors.TextSecondary
        local C_TRACK_BG = ThemeColors.Aurora2
        local C_TRACK_FG = ThemeColors.Primary
        local C_THUMB    = ThemeColors.Accent

        local CONTAINER_H = 44   -- igual que CreateSlider
        local STEP = 0.01

        -- -- CONTENEDOR PRINCIPAL  sin fondo, solo track y label flotando --
        local container = Instance.new("Frame", parent)
        container.Name                   = "GunSliderWrapper_" .. title
        container.Size                   = UDim2.new(1, -4, 0, CONTAINER_H)
        container.BackgroundTransparency = 1
        container.BorderSizePixel        = 0
        container.ClipsDescendants       = false

        -- -- TTULO (izquierda, arriba) ------------------------------
        local titleLabel = Instance.new("TextLabel", container)
        titleLabel.Name                   = "TitleLabel"
        titleLabel.Size                   = UDim2.new(1, -90, 0, 18)
        titleLabel.Position               = UDim2.new(0, 10, 0, 6)
        titleLabel.BackgroundTransparency = 1
        titleLabel.Text                   = title
        titleLabel.TextXAlignment         = Enum.TextXAlignment.Left
        titleLabel.TextYAlignment         = Enum.TextYAlignment.Center
        titleLabel.TextColor3             = C_TEXT
        titleLabel.FontFace               = Font.fromEnum(Enum.Font.Montserrat)
        titleLabel.TextSize               = 13
        titleLabel.TextTruncate           = Enum.TextTruncate.AtEnd
        titleLabel.ZIndex                 = 12

        -- -- CAJA DE VALOR --------------------------------------------
        local valBox = Instance.new("Frame", container)
        valBox.Size                   = UDim2.new(0, 58, 0, 20)
        valBox.Position               = UDim2.new(0, 10, 0, 28)
        valBox.BackgroundColor3       = ThemeColors.BackgroundLight
        valBox.BackgroundTransparency = 0.10
        valBox.BorderSizePixel        = 0
        valBox.ZIndex                 = 12
        Instance.new("UICorner", valBox).CornerRadius = UDim.new(0, 5)
        local _vbStroke2 = Instance.new("UIStroke", valBox)
        _vbStroke2.Color           = ThemeColors.Primary
        _vbStroke2.Thickness       = 1
        _vbStroke2.Transparency    = 0.4
        _vbStroke2.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local valueLabel = Instance.new("TextLabel", valBox)
        valueLabel.Name                   = "ValueLabel"
        valueLabel.Size                   = UDim2.new(1, 0, 1, 0)
        valueLabel.BackgroundTransparency = 1
        valueLabel.Text                   = string.format("%.2f", defaultVal)
        valueLabel.TextXAlignment         = Enum.TextXAlignment.Center
        valueLabel.TextYAlignment         = Enum.TextYAlignment.Center
        valueLabel.TextColor3             = C_TEXT
        valueLabel.FontFace               = Font.fromEnum(Enum.Font.Montserrat)
        valueLabel.TextSize               = 12
        valueLabel.ZIndex                 = 13

        -- -- SUBTTULO RANGO ------------------------------------------
        local subtitleLabel = Instance.new("TextLabel", container)
        subtitleLabel.Name                   = "SubtitleLabel"
        subtitleLabel.Size                   = UDim2.new(0, 80, 0, 12)
        subtitleLabel.Position               = UDim2.new(0, 10, 1, -14)
        subtitleLabel.BackgroundTransparency = 1
        subtitleLabel.Text                   = tostring(minVal) .. "  " .. tostring(maxVal)
        subtitleLabel.TextXAlignment         = Enum.TextXAlignment.Left
        subtitleLabel.TextYAlignment         = Enum.TextYAlignment.Center
        subtitleLabel.TextColor3             = C_SUBTEXT
        subtitleLabel.FontFace               = Font.fromEnum(Enum.Font.Montserrat)
        subtitleLabel.TextSize               = 10
        subtitleLabel.ZIndex                 = 12

        -- -- TRACK ----------------------------------------------------
        local sliderTrack = Instance.new("Frame", container)
        sliderTrack.Name                   = "SliderTrack"
        sliderTrack.Size                   = UDim2.new(1, -20, 0, 2)
        sliderTrack.Position               = UDim2.new(0, 10, 0, 36)
        sliderTrack.BackgroundColor3       = C_TRACK_BG
        sliderTrack.BackgroundTransparency = 0.40
        sliderTrack.BorderSizePixel        = 0
        sliderTrack.ClipsDescendants       = false
        sliderTrack.ZIndex                 = 12
        Instance.new("UICorner", sliderTrack).CornerRadius = UDim.new(1, 0)






        -- Fill bar teal brillante
        local initPct = math.clamp((defaultVal - minVal) / math.max(0.001, maxVal - minVal), 0, 1)
        local sliderFill = Instance.new("Frame", sliderTrack)
        sliderFill.Name                   = "FillBar"
        sliderFill.Size                   = UDim2.new(initPct, 0, 1, 0)
        sliderFill.BackgroundColor3       = C_TRACK_FG
        sliderFill.BackgroundTransparency = 0.0
        sliderFill.BorderSizePixel        = 0
        sliderFill.ZIndex                 = 13
        Instance.new("UICorner", sliderFill).CornerRadius = UDim.new(1, 0)

        -- -- THUMB ----------------------------------------------------
        local sliderThumb = Instance.new("ImageButton", sliderTrack)
        sliderThumb.Name                   = "SliderThumb"
        sliderThumb.Size                   = UDim2.new(0, 8, 0, 8)
        sliderThumb.AnchorPoint            = Vector2.new(0.5, 0.5)
        sliderThumb.Position               = UDim2.new(initPct, 0, 0.5, 0)
        sliderThumb.BackgroundColor3       = C_THUMB
        sliderThumb.BackgroundTransparency = 0.35
        sliderThumb.BorderSizePixel        = 0
        sliderThumb.ZIndex                 = 15
        Instance.new("UICorner", sliderThumb).CornerRadius = UDim.new(1, 0)
        local _thumbStroke2 = Instance.new("UIStroke", sliderThumb)
        _thumbStroke2.Color           = ThemeColors.Primary
        _thumbStroke2.Thickness       = 0.8
        _thumbStroke2.Transparency    = 0.10
        _thumbStroke2.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        -- -- LGICA ----------------------------------------------------
        local currentValue = defaultVal
        local draggingKS   = false

        local function round(v)
            return math.clamp(math.floor(v / STEP + 0.5) * STEP, minVal, maxVal)
        end

        local function applyValue(v)
            v = math.clamp(round(v), minVal, maxVal)
            currentValue = v
            local ratio = math.clamp((v - minVal) / math.max(maxVal - minVal, 0.001), 0, 1)
            sliderThumb.Position = UDim2.new(ratio, 0, 0.5, 0)
            sliderFill.Size      = UDim2.new(ratio, 0, 1, 0)
            valueLabel.Text      = string.format("%.2f", v)
            if callback then callback(v) end
        end

        applyValue(defaultVal)

        local function updateFromInput(inp)
            local mx = inp and inp.UserInputType == Enum.UserInputType.Touch and inp.Position.X or UserInputService:GetMouseLocation().X
            local tp = sliderTrack.AbsolutePosition.X
            local ts = sliderTrack.AbsoluteSize.X
            applyValue(minVal + math.clamp((mx - tp) / math.max(ts, 1), 0, 1) * (maxVal - minVal))
        end
        local function updateFromMouse() updateFromInput(nil) end

        sliderThumb.MouseEnter:Connect(function()
            TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 22, 0, 22)}):Play()
        end)
        sliderThumb.MouseLeave:Connect(function()
            if not draggingKS then
                TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 18, 0, 18)}):Play()
            end
        end)
        sliderThumb.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingKS = true; _G._sliderDragging = true
                TweenService:Create(sliderThumb, TweenInfo.new(0.08), {Size = UDim2.new(0, 22, 0, 22)}):Play()
            end
        end)
        sliderTrack.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingKS = true; _G._sliderDragging = true; updateFromInput(i)
            end
        end)
        RegisterTabConn(UserInputService.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingKS = false; _G._sliderDragging = false
                TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 18, 0, 18)}):Play()
            end
        end))
        RegisterTabConn(UserInputService.InputChanged:Connect(function(i)
            if draggingKS and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
                updateFromInput(i)
            end
        end))

        local function setValue(v)
            applyValue(v)
        end

        _attachScrollPassthrough(container, sliderTrack, sliderThumb)
        return container, setValue
    end

    -- Sliders de prediction gun eliminados

    -- -- BOTN + GUI DIAGNOSTICADOR (estilo idntico al Knife Analyzer) --------
    do
        local _copyGunGui  = nil
        local _copyGunConn = nil

        local function _destroyCopyGunGui()
            if _copyGunGui then
                pcall(function() _copyGunGui:Destroy() end)
                _copyGunGui = nil
            end
            if _copyGunConn then
                pcall(function() _copyGunConn:Disconnect() end)
                _copyGunConn = nil
            end
        end

        local function _showGunConfigAnalysis()
            _destroyCopyGunGui()

            -- ScreenGui overlay
            local sg = Instance.new("ScreenGui")
            sg.Name           = "GunConfigAnalysis"
            sg.ResetOnSpawn   = false
            sg.IgnoreGuiInset = true
            sg.DisplayOrder   = 9999
            pcall(function() sg.Parent = CoreGui end)
            if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
            _copyGunGui = sg

            -- Fondo semi-transparente
            local bg = Instance.new("Frame", sg)
            bg.Size                   = UDim2.fromScale(1, 1)
            bg.BackgroundColor3       = Color3.fromRGB(255, 255, 255)
            bg.BackgroundTransparency = 0.4
            bg.BorderSizePixel        = 0
            bg.ZIndex                 = 10

            -- Panel central
            local panel = Instance.new("Frame", bg)
            panel.Size          = UDim2.fromOffset(380, 340)
            panel.Position      = UDim2.fromScale(0.5, 0.5)
            panel.AnchorPoint   = Vector2.new(0.5, 0.5)
            panel.BackgroundColor3 = Color3.fromRGB(12, 12, 22)
