            panel.ZIndex          = 11
            Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 14)
            local panStroke = Instance.new("UIStroke", panel)
            panStroke.Color     = ThemeColors.Primary
            panStroke.Thickness = 2

            -- Ttulo
            local title = Instance.new("TextLabel", panel)
            title.Size                = UDim2.new(1, 0, 0, 38)
            title.BackgroundTransparency = 1
            title.Text                = " GUN CONFIG ANALYZER"
            title.TextColor3          = ThemeColors.Primary
            title.Font                = Enum.Font.Montserrat
            title.TextSize            = 15
            title.ZIndex              = 12

            -- Spinner giratorio
            local spinnerFrame = Instance.new("Frame", panel)
            spinnerFrame.Size            = UDim2.fromOffset(60, 60)
            spinnerFrame.Position        = UDim2.new(0.5, 0, 0, 46)
            spinnerFrame.AnchorPoint     = Vector2.new(0.5, 0)
            spinnerFrame.BackgroundTransparency = 1
            spinnerFrame.ZIndex          = 12

            local spinLbl = Instance.new("TextLabel", spinnerFrame)
            spinLbl.Size                 = UDim2.fromScale(1, 1)
            spinLbl.BackgroundTransparency = 1
            spinLbl.Text                 = ""
            spinLbl.TextColor3           = ThemeColors.Primary
            spinLbl.Font                 = Enum.Font.Montserrat
            spinLbl.TextSize             = 48
            spinLbl.ZIndex               = 12

            -- Label de diagnstico en tiempo real
            local infoLbl = Instance.new("TextLabel", panel)
            infoLbl.Size                 = UDim2.new(1, -20, 0, 90)
            infoLbl.Position             = UDim2.fromOffset(10, 116)
            infoLbl.BackgroundTransparency = 1
            infoLbl.Text                 = "Analizando sistema..."
            infoLbl.TextColor3           = Color3.fromRGB(210, 240, 255)
            infoLbl.Font                 = Enum.Font.Montserrat
            infoLbl.TextSize             = 12
            infoLbl.TextWrapped          = true
            infoLbl.ZIndex               = 12

            -- Label config recomendada
            local recLbl = Instance.new("TextLabel", panel)
            recLbl.Size                  = UDim2.new(1, -20, 0, 110)
            recLbl.Position              = UDim2.fromOffset(10, 210)
            recLbl.BackgroundTransparency = 1
            recLbl.Text                  = ""
            recLbl.TextColor3            = Color3.fromRGB(255, 230, 80)
            recLbl.Font                  = Enum.Font.Montserrat
            recLbl.TextSize              = 11
            recLbl.TextWrapped           = true
            recLbl.ZIndex                = 12

            -- Botn cerrar
            local closeBtn = Instance.new("TextButton", panel)
            closeBtn.Size             = UDim2.fromOffset(28, 28)
            closeBtn.Position         = UDim2.new(1, -32, 0, 4)
            closeBtn.BackgroundColor3 = Color3.fromRGB(180, 40, 40)
            closeBtn.BackgroundTransparency = 0.2
            closeBtn.Text             = ""
            closeBtn.TextColor3       = Color3.fromRGB(255, 255, 255)
            closeBtn.Font             = Enum.Font.Montserrat
            closeBtn.TextSize         = 13
            closeBtn.BorderSizePixel  = 0
            closeBtn.ZIndex           = 13
            Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0, 6)
            closeBtn.Activated:Connect(_destroyCopyGunGui)

            -- Variables para anlisis
            local _fpsHistory   = {}
            local _pingHistory  = {}
            local _analysisDone = false
            local _spinAngle    = 0
            local _sampleCount  = 0
            local _maxSamples   = 60  -- ~3 seg de muestras a 20Hz (Heartbeat)

            local _cgT = 0
            _copyGunConn = _safeConnect(RunService.Heartbeat, function(dt)
                if not sg.Parent then _destroyCopyGunGui(); return end
                _cgT = _cgT + dt; if _cgT < 0.033 then return end; _cgT = 0
                _spinAngle = (_spinAngle + 8) % 360
                spinLbl.Rotation = _spinAngle

                if _analysisDone then return end

                -- Recolectar FPS y Ping
                _sampleCount = _sampleCount + 1
                local okF, fps  = pcall(function() return math.floor(1 / dt) end)
                local okP, ping = pcall(function() return math.floor(LocalPlayer:GetNetworkPing() * 1000) end)
                if okF then table.insert(_fpsHistory,  fps)  end
                if okP then table.insert(_pingHistory, ping) end

                -- Info en tiempo real
                local curFps  = okF and fps  or 0
                local curPing = okP and ping or 0
                local lag     = curPing > 120 and "ALTO" or curPing > 60 and "MEDIO" or "BAJO"
                infoLbl.Text = string.format(
 " Ping actual: %d ms  |  Lag: %s\n FPS actual: %d\n Muestras: %d/%d",
                    curPing, lag, curFps, _sampleCount, _maxSamples
                )

                -- Al tener suficientes muestras -> calcular y aplicar config
                if _sampleCount >= _maxSamples then
                    _analysisDone = true

                    local avgPing, avgFps = 0, 0
                    for _, v in ipairs(_pingHistory) do avgPing = avgPing + v end
                    for _, v in ipairs(_fpsHistory)  do avgFps  = avgFps  + v  end
                    avgPing = math.floor(avgPing / math.max(1, #_pingHistory))
                    avgFps  = math.floor(avgFps  / math.max(1, #_fpsHistory))

                    -- -- Algoritmo de recomendacin para Gun SA ----------------
                    -- Ping bajo  -> multiplicadores bajos (poco lead), divisores pequeos
                    -- Ping alto  -> ms lead horizontal/vertical, divisores ms altos
                    -- FPS bajo   -> latency comp ms alta, strafe ms agresivo

                    local hM, vM, dMin, dMax, mDist, vPM, lC, sS, aB, jL, tO

                    if avgPing <= 40 then
                        -- Excelente: mnima prediccin
                        hM=1.02; vM=1.02; dMin=10; dMax=18;  mDist=120; vPM=0.9;  lC=0.8;  sS=0.7;  aB=0.1; jL=0.8; tO=80
                    elseif avgPing <= 80 then
                        -- Buena: prediccin estndar
                        hM=1.10; vM=1.15; dMin=22; dMax=38;  mDist=200; vPM=1.0;  lC=1.0;  sS=1.0;  aB=0.3; jL=1.0; tO=180
                    elseif avgPing <= 130 then
                        -- Media: valores de imagen (32.72 / 53.58)
                        hM=1.18; vM=1.22; dMin=32; dMax=54;  mDist=250; vPM=1.15; lC=1.2;  sS=1.2;  aB=0.5; jL=1.1; tO=280
                    elseif avgPing <= 200 then
                        -- Alta: ms agresivo
                        hM=1.35; vM=1.40; dMin=45; dMax=70;  mDist=320; vPM=1.35; lC=1.5;  sS=1.5;  aB=0.8; jL=1.3; tO=380
                    else
                        -- Muy alta: prediccin mxima
                        hM=1.60; vM=1.70; dMin=58; dMax=85;  mDist=400; vPM=1.60; lC=1.9;  sS=1.8;  aB=1.2; jL=1.6; tO=460
                    end

                    -- Ajuste por FPS bajo -> ms latency comp y strafe
                    if avgFps < 30 then
                        lC = lC + 0.3; sS = sS + 0.2; dMin = dMin + 4; dMax = dMax + 4
                    elseif avgFps < 60 then
                        lC = lC + 0.1; dMin = dMin + 2; dMax = dMax + 2
                    end

                    -- Clampear valores a rangos de sliders
                    hM    = math.clamp(hM,    0.5,  3.0)
                    vM    = math.clamp(vM,    0.5,  3.0)
                    dMin  = math.clamp(dMin,  0,    100)
                    dMax  = math.clamp(dMax,  0,    100)
                    mDist = math.clamp(mDist, 10,   500)
                    vPM   = math.clamp(vPM,   0.1,  3.0)
                    lC    = math.clamp(lC,    0.1,  3.0)
                    sS    = math.clamp(sS,    0.0,  3.0)
                    aB    = math.clamp(aB,    0.0,  2.0)
                    jL    = math.clamp(jL,    0.0,  3.0)
                    tO    = math.clamp(tO,    0,    500)

                    -- FIX: sliders eliminados; aplicar directo a CombatTabState
                    CombatTabState.gunHorizAimMult  = hM
                    CombatTabState.gunVertAimMult   = vM
                    CombatTabState.gunPredDivHMin   = dMin
                    CombatTabState.gunPredDivHMax   = dMax
                    CombatTabState.gunMaxPredDist   = mDist
                    CombatTabState.gunVertPredMult  = vPM
                    CombatTabState.gunLatencyComp   = lC
                    CombatTabState.gunStrafeScale   = sS
                    CombatTabState.gunAccelBias     = aB
                    CombatTabState.gunJumpLead      = jL
                    CombatTabState.gunTiancaiOffset = tO
                    if CombatState then
                        CombatState.gunHorizAimMult  = hM
                        CombatState.gunVertAimMult   = vM
                        CombatState.gunPredDivHMin   = dMin
                        CombatState.gunPredDivHMax   = dMax
                        CombatState.gunMaxPredDist   = mDist
                        CombatState.gunVertPredMult  = vPM
                        CombatState.gunLatencyComp   = lC
                        CombatState.gunStrafeScale   = sS
                        CombatState.gunAccelBias     = aB
                        CombatState.gunJumpLead      = jL
                        CombatState.gunTiancaiOffset = tO
                    end
                    -- nil-safe: mover sliders si existen
                    if _gpSliderSet.horizMult then _gpSliderSet.horizMult(hM)  end
                    if _gpSliderSet.vertMult  then _gpSliderSet.vertMult(vM)   end
                    if _gpSliderSet.divMin    then _gpSliderSet.divMin(dMin)   end
                    if _gpSliderSet.divMax    then _gpSliderSet.divMax(dMax)   end
                    if _gpSliderSet.maxDist   then _gpSliderSet.maxDist(mDist) end
                    if _gpSliderSet.vertPred  then _gpSliderSet.vertPred(vPM)  end
                    if _gpSliderSet.latComp   then _gpSliderSet.latComp(lC)    end
                    if _gpSliderSet.strafe    then _gpSliderSet.strafe(sS)     end
                    if _gpSliderSet.accel     then _gpSliderSet.accel(aB)      end
                    if _gpSliderSet.jump      then _gpSliderSet.jump(jL)       end
                    if _gpSliderSet.tiancai   then _gpSliderSet.tiancai(tO)    end

                    recLbl.Text = string.format(
 " Config aplicada para %dms / %dfps:\nH Mult=%.2f  V Mult=%.2f\nDiv Min=%.1f  Div Max=%.1f\nMaxDist=%.0f  LatComp=%.2f\nStrafe=%.2f  Accel=%.2f  Jump=%.2f\nTiancai=%.0f",
                        avgPing, avgFps, hM, vM, dMin, dMax, mDist, lC, sS, aB, jL, tO
                    )
                    spinLbl.Text       = ""
                    spinLbl.TextColor3 = Color3.fromRGB(130, 130, 135)
                    spinLbl.Rotation   = 0

                    CreateCustomNotification("GUN CONFIG", "Config ptima aplicada  Ping: " .. avgPing .. "ms FPS: " .. avgFps, 4)
                end
            end)
        end

        -- Boton Copy Gun Config (estilo nativo hub)
        CreateButton(silentAimSection, "Copy Config Gun", ThemeColors.Primary, function()
            _showGunConfigAnalysis()
            CreateCustomNotification("GUN CONFIG", "Analizando ping, FPS y lag... ", 2)
        end)
    end
