        })
        _khTextGrad.Rotation = 0
        RegisterShimmer(_khTextGrad, 55, 5)

        -- Badge "SILENT AIM" a la derecha
        local _khBadge = Instance.new("Frame", _knifeHeader)
        _khBadge.Size                   = UDim2.new(0, 82, 0, 22)
        _khBadge.AnchorPoint            = Vector2.new(1, 0.5)
