        Instance.new("UICorner", _khBadge).CornerRadius = UDim.new(0, 6)
        local _khBadgeStroke = Instance.new("UIStroke", _khBadge)
        _khBadgeStroke.Thickness    = 1.2
        _khBadgeStroke.Transparency = 0.2
        _khBadgeStroke.Color        = ThemeColors.Aurora2
        local _khBadgeLbl = Instance.new("TextLabel", _khBadge)
        _khBadgeLbl.Size                   = UDim2.new(1, 0, 1, 0)
        _khBadgeLbl.BackgroundTransparency = 1
