        _khDiv.Position               = UDim2.new(0.075, 0, 1, -1)
        _khDiv.BackgroundColor3       = ThemeColors.Aurora1
        _khDiv.BackgroundTransparency = 0.4
        _khDiv.BorderSizePixel        = 0
        _khDiv.ZIndex                 = 14
        local _khDivGrad = Instance.new("UIGradient", _khDiv)
        _khDivGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   Color3.fromRGB(0,0,0)),
            ColorSequenceKeypoint.new(0.2, ThemeColors.Aurora1),
            ColorSequenceKeypoint.new(0.8, ThemeColors.Primary),
            ColorSequenceKeypoint.new(1,   Color3.fromRGB(0,0,0)),
        })
    end
    -- =============================================
    -- KNIFE SILENT AIM (nuevo sistema ? c?mara libre, sin shift lock)
    -- =============================================
 knifeSASection = CreateBorderedSection(leftColumn, " KNIFE SILENT AIM")

    -- -- SELECTOR DE MODO KNIFE SILENT AIM -----------------------------
    do
        CombatTabState.knifeSAMode = CombatTabState.knifeSAMode or "Normal"

        -- FIX: _saKnifeCamLockOn eliminado ? no redirigir c?mara en ning?n modo SA

        -- -- _saKnifeModeApply ? Electro > Lag > Phantom, sin redirigir c?mara --
        _G._saKnifeModeApply = function(throwFn)
            local mode = CombatTabState.knifeSAMode or "Normal"
            if mode == "Normal" then
                -- Normal: throw puro sin modificaci?n
                pcall(throwFn)

            elseif mode == "Electro" then
                -- -- ELECTRO: doble throw desincronizado --
                -- Lanza el knife dos veces con 50ms de diferencia.
                -- El server procesa ambos como trayectorias distintas ? mayor cobertura.
                -- Mejor que Normal: cubre el margen de error de posici?n del target.
                task.spawn(function()
                    pcall(throwFn)
                    task.wait(0.016)
                    pcall(throwFn)
                end)

            elseif mode == "Phantom" then
                -- -- PHANTOM: TP silencioso + throw m?ltiple con spread vertical --
                -- Se teletransporta a 2 studs del target (distancia de stab),
                -- lanza el knife 3 veces con offsets Y distintos para garantizar
                -- que al menos uno impacte aunque el target est? saltando.
                -- Mejor que Lag: elimina la distancia + cubre variaci?n vertical.
                local target = findMurderer()
                if not target then
                    for _, p in ipairs(_cachedPlayers) do
                        if p ~= LocalPlayer and p.Character then
                            if p.Character:FindFirstChild("Knife") then target = p; break end
                        end
                    end
                end
                local char   = LocalPlayer.Character
                local hrp    = char and char:FindFirstChild("HumanoidRootPart")
                local tChar  = target and target.Character
                local tHRP   = tChar and tChar:FindFirstChild("HumanoidRootPart")

                if hrp and tHRP then
                    local origCF = hrp.CFrame
                    local toTarget = tHRP.Position - hrp.Position
                    local dist = toTarget.Magnitude
                    if dist > 4 then
                        -- TP a 2 studs del target mirando hacia ?l
                        local tpPos = tHRP.Position - toTarget.Unit * 2
                        pcall(function()
                            hrp.CFrame = CFrame.new(tpPos, tHRP.Position)
                            hrp.AssemblyLinearVelocity = Vector3.zero
                        end)
                        task.wait(0.016)  -- 1 frame para que el server registre la posici?n
                    end
                    -- 3 throws con offset vertical: centro, +0.5, -0.5 (cubre salto y agachado)
                    local yOffsets = {0, 0.5, -0.5}
                    for i, yo in ipairs(yOffsets) do
                        if yo ~= 0 and hrp.Parent then
                            pcall(function() hrp.CFrame = hrp.CFrame + Vector3.new(0, yo, 0) end)
                        end
                        pcall(throwFn)
                        if i < 3 then task.wait(0.016) end
                    end
                    -- Volver a posici?n original en la pr?xima ventana del server
                    task.delay(0.05, function()
                        pcall(function()
                            hrp.CFrame = origCF
                            hrp.AssemblyLinearVelocity = Vector3.zero
                        end)
                    end)
                else
                    -- Fallback: doble throw
                    pcall(throwFn)
                    task.delay(0.016, function() pcall(throwFn) end)
                end
            end
        end
    end

    -- Toggle principal
    -- NOTA: Knife Silent Aim es INCOMPATIBLE con:
    --  Silent Knife Kill (ambos hookean KnifeThrown = double-fire)
    --  Simulate Knife Throw (ambos hookean RMB InputBegan = double-trigger)
    do
    local _ksaToggleRef = CreateBorderedToggle(knifeSASection, "Knife Silent Aim", function(enabled)
        KnifeSAState.enabled = enabled
        if enabled then
            -- -- Auto-desactivar todo lo que compite con Knife SA -------------

            -- 1. Silent Knife Kill (hookea KnifeThrown = double-fire)
            if CombatTabState._sk and CombatTabState._sk.enabled then
                CombatTabState._sk.enabled = false
                if CombatTabState._skStop then pcall(CombatTabState._skStop) end
 CreateCustomNotification("CONFLICT", "Silent Knife Kill desactivado (conflicto con Knife SA)", 3)
            end

            -- 2. Simulate Knife Throw (hookea RMB = double-trigger)
            if CombatTabState._sim and CombatTabState._sim.enabled then
                CombatTabState._sim.enabled = false
                if CombatTabState._sim.conn then CombatTabState._sim.conn:Disconnect(); CombatTabState._sim.conn = nil end
 CreateCustomNotification("CONFLICT", "Simulate Knife Throw desactivado (conflicto con Knife SA)", 3)
            end

            -- 3. Instant Kill Aura (hookea RMB + workspace.ChildAdded = double-fire)
            if _ika and _ika.enabled then
                _ika.enabled = false
                pcall(_ikaStop)
 CreateCustomNotification("CONFLICT", "Instant Kill Aura desactivado (conflicto con Knife SA)", 3)
            end

            -- 4. Knife Aura / Auto Click (disparan KnifeThrown en loop = colisi?n)
            if Settings.premium.knifeAura.enabled then
                Settings.premium.knifeAura.enabled = false
                if Settings.premium.knifeAura.connection then
                    Settings.premium.knifeAura.connection:Disconnect()
                    Settings.premium.knifeAura.connection = nil
                end
 CreateCustomNotification("CONFLICT", "Knife Aura desactivado (conflicto con Knife SA)", 3)
            end
            if Settings.premium.knifeAura.autoClick then
                Settings.premium.knifeAura.autoClick = false
                if Settings.premium.knifeAura.autoClickConn then
                    Settings.premium.knifeAura.autoClickConn:Disconnect()
                    Settings.premium.knifeAura.autoClickConn = nil
                end
            end

            -- 5. Quit Throw Animation (bloquea las anims que Knife SA ejecuta)
            if QA and QA.enabled then
                QA.enabled = false
                pcall(stopQA)
 CreateCustomNotification("CONFLICT", "Quit Throw Animation desactivado (conflicto con Knife SA)", 3)
            end

            _KnifeSA_activate()
            -- FIX: al activar SA, limpiar IKS para que no interfiera
            if InvisibleKnifeSystem.enabled then
                cleanupInvisibleKnife()
                _IKS_startMonitor()
            end

            -- -- HOOK AL BOTÓN THROW NATIVO DE MM2 (solo mobile/tablet) ---------
            local _isMobileKSA = UserInputService.TouchEnabled
            if _isMobileKSA then
                -- Limpiar conexiones anteriores si existen
                if KnifeSAState._mobileConns then
                    for _, c in ipairs(KnifeSAState._mobileConns) do
                        pcall(function() c:Disconnect() end)
                    end
                end
                KnifeSAState._mobileConns = {}
                -- ================================================================
                -- MOBILE THROW SYSTEM v10
                --
                -- USA LAS FUNCIONES YA EXISTENTES DE KnifeSAState para animaciones:
                --   KnifeSAState._playThrowAnim()        -> ThrowCharge (o ThrowCharge 2)
                --   KnifeSAState._playThrowHoldAnim()    -> ThrowHold en loop
                --   KnifeSAState._releaseThrowHoldAnim() -> para el hold
                --   KnifeSAState._playThrowKnifeAnim()   -> ThrowKnife
                --   KnifeSAState._getThrowTrack()        -> track actual de charge
                --
                -- Estas funciones ya tienen el knife correcto via closure del
                -- _KnifeSA_setupKnife que se ejecuto ANTES de entrar aqui.
                -- No se necesita ningun loader propio.
                --
                -- Flujo (ciclo infinito mientras KnifeSA activo):
                --   1) ThrowCharge: play -> esperar fin de track
                --   2) ThrowHold:   loop -> esperar touch del jugador
                --   3) Al touch: stop hold -> ThrowKnife -> FireServer -> reiniciar
                -- ================================================================
                if not _G._mobileKSALastThrow then _G._mobileKSALastThrow = -999 end

                local _mobileSeqRunning   = false
                local _mobileWaitingTouch = false
                local _mobileTouchFired   = false
                local THROW_CD            = 1.5

                -- Calcula bladeCF y targetCF con Silent Aim o fallback al frente
                local function _calcCFrames()
                    local char  = LocalPlayer.Character
                    local myHRP = char and char:FindFirstChild("HumanoidRootPart")
                    if not myHRP then return nil, nil end
                    local origin    = myHRP.Position + Vector3.new(0, 1.5, 0)
                    local targetPos = nil
                    if KnifeSAState.enabled then
                        local target = _KnifeSA_getBestTarget and _KnifeSA_getBestTarget()
                        if target and target.Character then
                            local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                            local tHum = target.Character:FindFirstChildOfClass("Humanoid")
                            if tHRP and tHum and tHum.Health > 0 then
                                local ok = true
                                if KnifeSAState.wallCheck then
                                    local tHead = target.Character:FindFirstChild("Head")
                                    local los  = wallCheckRaycast(myHRP.Position, tHRP.Position, target.Character)
                                    local losH = not los and tHead and wallCheckRaycast(origin, tHead.Position, target.Character)
                                    ok = los or losH
                                end
                                if ok then
                                    targetPos = _KnifeSA_getPredictedPos
                                        and _KnifeSA_getPredictedPos(tHRP, target.Character)
                                        or  tHRP.Position
                                    local minY = math.max(0.3, tHRP.Position.Y - 1.5)
                                    if targetPos.Y < minY then
                                        targetPos = Vector3.new(targetPos.X, tHRP.Position.Y + 0.5, targetPos.Z)
                                    end
                                end
                            end
                        end
                    end
                    if not targetPos then
                        targetPos = origin + myHRP.CFrame.LookVector * 30
                    end
                    local dir  = targetPos - origin
                    if dir.Magnitude < 0.01 then dir = myHRP.CFrame.LookVector end
                    local dirU = dir.Unit
                    local bladeCF  = CFrame.new(origin, origin + dirU)
                    local backDir  = origin - targetPos
                    local targetCF = backDir.Magnitude > 0.1
                        and CFrame.new(targetPos, targetPos + backDir.Unit)
                        or  CFrame.new(targetPos)
                    return bladeCF, targetCF
                end

                -- Lanza el knife via knife.Events.KnifeThrown:FireServer
                local function _fireKnifeServer(bladeCF, targetCF)
                    local char  = LocalPlayer.Character
                    local knife = char and char:FindFirstChild("Knife")
                    if not knife then
                        local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
                        knife = bp and bp:FindFirstChild("Knife")
                    end
                    if not knife then return end
                    local ev = knife:FindFirstChild("Events")
                    local kt = ev and ev:FindFirstChild("KnifeThrown")
                    if not kt then return end
                    local fired = false
                    pcall(function() kt:FireServer(bladeCF, targetCF); fired = true end)
                    if not fired then pcall(function() kt:FireServer(targetCF, bladeCF); fired = true end) end
                    if not fired then pcall(function() kt:FireServer(targetCF);          fired = true end) end
                    if not fired then pcall(function() kt:FireServer(bladeCF)                       end) end
                end

                -- ----------------------------------------------------------------
                -- ================================================================
                -- MOBILE THROW SYSTEM v16 - FLUJO NATIVO
                --
                -- ESTRATEGIA: No luchar contra el KnifeClient.
                -- El KnifeClient nativo maneja todo el FireServer correctamente.
                -- Nosotros solo:
                --   1) Detectamos el tap en el boton Throw (primer tap -> inicia secuencia)
                --   2) Esperamos a que ThrowCharge termine y ThrowHold empiece (u67=true en el KC nativo)
                --   3) En fase HOLDING: detectamos cualquier touch en pantalla (ignorando gp)
                --   4) Calculamos el target SA y disparamos TouchTapInWorld sintetico
                --      OR inyectamos directamente WeaponService:GetTargetPosition con SA
                --
                -- El KnifeClient queda HABILITADO para que el servidor procese todo.
                -- KnifeSAState._setupKnife lo deshabilita solo para Desktop (RMB).
                -- En mobile lo dejamos habilitado.
                -- ================================================================

                -- Habilitar KnifeClient en mobile (no debe estar disabled)
                do
                    local function _enableKC(parent)
                        if not parent then return end
                        local knife = parent:FindFirstChild("Knife")
                        local kc = knife and knife:FindFirstChild("KnifeClient")
                        if kc then pcall(function() kc.Disabled = false end) end
                    end
                    local c0 = LocalPlayer.Character
                    if c0 then _enableKC(c0) end
                    _enableKC(LocalPlayer.Backpack)
                end

                -- Estado de la secuencia
                -- 0=IDLE  1=CHARGING  2=HOLDING  3=THROWING
                local _throwState       = 0
                local _mobileSeqActive  = false

                -- Cache de tracks locales (independiente de KnifeSAState)
                local _msaCache = {}

                local function _msaGetAnimator()
                    local c = LocalPlayer.Character
                    local h = c and c:FindFirstChildOfClass("Humanoid")
                    return h and h:FindFirstChildOfClass("Animator")
                end

                local function _msaPlay(knife, name, looped)
                    local anim = _msaGetAnimator()
                    if not anim then return nil end
                    local kc  = knife and knife:FindFirstChild("KnifeClient")
                    local obj = kc and kc:FindFirstChild(name)
                    if not obj then return nil end
                    local t = _msaCache[name]
                    if t then
                        local ok = pcall(function() return t.IsPlaying end)
                        if not ok then t = nil; _msaCache[name] = nil end
                    end
                    if not t then
                        local ok, tr = pcall(function() return anim:LoadAnimation(obj) end)
                        if not ok or not tr then return nil end
                        tr.Priority = Enum.AnimationPriority.Action
                        _msaCache[name] = tr
                        t = tr
                    end
                    t.Looped = looped or false
                    if t.IsPlaying then pcall(function() t:Stop(0) end); task.wait(0.016) end
                    pcall(function() t:Play(0.05) end)
                    return t
                end

                local function _msaStop(name)
                    local t = _msaCache[name]
                    if t then pcall(function() t.Looped = false; t:Stop(0.05) end) end
                end

                local function _msaWait(track, fallback)
                    if not track then task.wait(fallback or 0.5); return end
                    local t0 = os.clock()
                    repeat task.wait(0.016) until track.IsPlaying or (os.clock()-t0) > 0.4
                    local len = (track.Length and track.Length > 0.05) and track.Length or (fallback or 0.5)
                    local t1 = os.clock()
                    repeat task.wait(0.016) until (not track.IsPlaying) or (os.clock()-t1) >= len + 0.05
                end

                -- Calcula targetCF con Silent Aim o fallback al frente del personaje
                local function _calcTarget()
                    local c    = LocalPlayer.Character
                    local myHRP = c and c:FindFirstChild("HumanoidRootPart")
                    if not myHRP then return nil end
                    local origin = myHRP.Position + Vector3.new(0, 1.5, 0)
                    local targetPos = nil
                    -- Intentar SA
                    if KnifeSAState and KnifeSAState.enabled
                    and type(_KnifeSA_getBestTarget) == "function" then
                        local tgt = _KnifeSA_getBestTarget()
                        if tgt and tgt.Character then
                            local tHRP = tgt.Character:FindFirstChild("HumanoidRootPart")
                            local tHum = tgt.Character:FindFirstChildOfClass("Humanoid")
                            if tHRP and tHum and tHum.Health > 0 then
                                local pred = nil
                                if type(_KnifeSA_getPredictedPos) == "function" then
                                    pcall(function()
                                        pred = _KnifeSA_getPredictedPos(tHRP, tgt.Character)
                                    end)
                                end
                                targetPos = pred or tHRP.Position
                                local minY = math.max(0.3, tHRP.Position.Y - 1.5)
                                if targetPos.Y < minY then
                                    targetPos = Vector3.new(targetPos.X, tHRP.Position.Y + 0.5, targetPos.Z)
                                end
                            end
                        end
                    end
                    -- Fallback: frente del personaje
                    if not targetPos then
                        targetPos = origin + myHRP.CFrame.LookVector * 30
                    end
                    local aimVec = (targetPos - origin)
                    if aimVec.Magnitude < 0.01 then aimVec = myHRP.CFrame.LookVector end
                    local aimDir = aimVec.Unit
                    local handleCF  = CFrame.new(origin, origin + aimDir)
                    local backDir   = origin - targetPos
                    local targetCF  = backDir.Magnitude > 0.1
                        and CFrame.new(targetPos, targetPos + backDir.Unit)
                        or  CFrame.new(targetPos)
                    return handleCF, targetCF
                end

                -- Ejecuta el FireServer con el KnifeClient habilitado
                local function _doFireServer(knife, targetCF)
                    if not knife or not targetCF then return end
                    local kc     = knife:FindFirstChild("KnifeClient")
                    local ev     = knife:FindFirstChild("Events")
                    local kt     = ev and ev:FindFirstChild("KnifeThrown")
                    local handle = knife:FindFirstChild("Handle")
                    if not kt then return end
                    -- Habilitar KnifeClient para que el servidor procese el throw
                    if kc then pcall(function() kc.Disabled = false end) end
                    -- Usar Handle.CFrame real como el KnifeClient nativo
                    local bladeCF = handle and handle.CFrame or CFrame.new()
                    local ok = false
                    pcall(function() kt:FireServer(bladeCF, targetCF); ok = true end)
                    if not ok then pcall(function() kt:FireServer(targetCF, bladeCF); ok = true end) end
                    if not ok then pcall(function() kt:FireServer(targetCF) end) end
                    -- Mantener KnifeClient habilitado (mobile necesita que este activo)
                end

                -- Secuencia principal
                local function _runSequence()
                    if _mobileSeqActive then return end
                    _mobileSeqActive = true
                    _throwState      = 0

                    task.spawn(function()
                        local function _cleanup()
                            _mobileSeqActive = false
                            _throwState      = 0
                            _G._mobileThrowState = "IDLE"
                        end

                        local c     = LocalPlayer.Character
                        local knife = c and c:FindFirstChild("Knife")
                        local hum   = c and c:FindFirstChildOfClass("Humanoid")
                        if not knife or not hum or hum.Health <= 0 then
                            _cleanup(); return
                        end

                        -- Asegurar KnifeClient habilitado
                        local kc = knife:FindFirstChild("KnifeClient")
                        if kc then pcall(function() kc.Disabled = false end) end

                        -- === ESTADO 1: CHARGING ===
                        _throwState = 1
                        _G._mobileThrowState = "CHARGING"
                        task.wait(0.05)

                        local chargeTrack = _msaPlay(knife, "ThrowCharge", false)
                        _msaWait(chargeTrack, 0.6)
                        task.wait(0.08)

                        if not _mobileSeqActive then _cleanup(); return end

                        -- === ESTADO 2: HOLDING ===
                        _throwState = 2
                        _G._mobileThrowState = "HOLDING"
                        _msaPlay(knife, "ThrowHold", true)
                        task.wait(0.08)  -- minimo antes de aceptar touch

                        -- Esperar touch (maximo 30s)
                        -- _throwState cambia a 3 cuando el touch handler lo confirma
                        local wt = os.clock()
                        repeat task.wait(0.016)
                        until _throwState == 3
                           or not _mobileSeqActive
                           or (os.clock()-wt) > 30

                        _msaStop("ThrowHold")
                        _msaStop("ThrowCharge")

                        if _throwState ~= 3 or not _mobileSeqActive then
                            _cleanup(); return
                        end

                        -- Cooldown global
                        local now = os.clock()
                        if now - (_G._mobileKSALastThrow or -999) < 1.5 then
                            _cleanup(); return
                        end
                        _G._mobileKSALastThrow            = now
                        KnifeSAState._lastMobileThrowTime = now

                        -- Calcular target SA antes de animar ThrowKnife
                        local handleCF, targetCF = _calcTarget()

                        -- === ESTADO 3: THROWING ===
                        _G._mobileThrowState = "THROWING"
                        task.wait(0.05)

                        local throwTrack = _msaPlay(knife, "ThrowKnife", false)
                        task.wait(0.10)  -- dejar que la animacion arranque

                        -- FireServer con KnifeClient habilitado y Handle.CFrame real
                        if targetCF then
                            _doFireServer(knife, targetCF)
                        end

                        _msaWait(throwTrack, 0.5)
                        _cleanup()
                    end)
                end

                -- ----------------------------------------------------------------
                -- HOOK AL BOTON THROW
                -- Primer tap  -> inicia secuencia (IDLE)
                -- Segundo tap en HOLDING -> confirma lanzamiento (HOLDING -> THROWING)
                -- ----------------------------------------------------------------
                task.spawn(function()
                    local pg2  = LocalPlayer:WaitForChild("PlayerGui", 20)
                    if not pg2 then return end
                    local gcui = pg2:WaitForChild("GameplayControlsUI", 20)
                    if not gcui then return end
                    local tc   = gcui:WaitForChild("TouchControls", 20)
                    if not tc then return end
                    local rb   = tc:WaitForChild("RightBar", 20)
                    if not rb then return end
                    local throwBtn = rb:WaitForChild("Throw", 20)
                    if not throwBtn then return end

                    -- Usar Activated (funciona con TouchBinding.UIButton del juego nativo)
                    -- Si no dispara, fallback a InputBegan con hit-test
                    local function _onThrowTap()
                        if not KnifeSAState.enabled then return end
                        local c2 = LocalPlayer.Character
                        if not (c2 and c2:FindFirstChild("Knife")) then return end
                        if _throwState == 2 then
                            -- Segundo tap: confirmar lanzamiento
                            _throwState = 3
                        elseif _throwState == 0 and not _mobileSeqActive then
                            -- Primer tap: iniciar secuencia
                            _runSequence()
                        end
                        -- En CHARGING (1) o THROWING (3): ignorar
                    end

                    -- Metodo 1: Activated (el mas confiable si el UIButton esta conectado)
                    local conn1 = throwBtn.Activated:Connect(_onThrowTap)
                    table.insert(KnifeSAState._mobileConns, conn1)

                    -- Metodo 2: InputBegan hit-test como respaldo
                    local conn2 = UserInputService.InputBegan:Connect(function(inp, gp)
                        -- En HOLDING aceptamos aunque gp=true (el dedo puede estar sobre GUI)
                        if _throwState ~= 2 and gp then return end
                        if inp.UserInputType ~= Enum.UserInputType.Touch
                        and inp.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                        if not KnifeSAState.enabled then return end
                        -- Hit-test: verificar que el touch cayo en el boton Throw
                        local pos  = inp.Position
                        local objs = pg2:GetGuiObjectsAtPosition(pos.X, pos.Y)
                        for _, obj in ipairs(objs) do
                            if obj == throwBtn or obj:IsDescendantOf(throwBtn) then
                                _onThrowTap()
                                return
                            end
                        end
                    end)
                    table.insert(KnifeSAState._mobileConns, conn2)

                    LocalPlayer.CharacterAdded:Connect(function(newChar)
                        _msaCache        = {}
                        _mobileSeqActive = false
                        _throwState      = 0
                        _G._mobileThrowState = "IDLE"
                        -- Re-habilitar KnifeClient en personaje nuevo
                        newChar.ChildAdded:Connect(function(ch)
                            if ch:IsA("Tool") and ch.Name == "Knife" then
                                _msaCache = {}
                                local kc2 = ch:FindFirstChild("KnifeClient")
                                if kc2 then pcall(function() kc2.Disabled = false end) end
                            end
                        end)
                    end)
                end)

                -- ----------------------------------------------------------------
                -- TOUCH EN PANTALLA (cualquier zona) -> confirma lanzamiento en HOLDING
                -- Acepta gp=true porque el dedo puede tocar sobre controles del juego
                -- ----------------------------------------------------------------
                local _touchConfirmConn = UserInputService.InputBegan:Connect(function(inp, gp)
                    -- No filtrar por gp en HOLDING: el dedo puede caer sobre GUI del juego
                    if inp.UserInputType ~= Enum.UserInputType.Touch then return end
                    if not KnifeSAState.enabled then return end
                    if _throwState ~= 2 or not _mobileSeqActive then return end
                    local c = LocalPlayer.Character
                    if not (c and c:FindFirstChild("Knife")) then return end
                    _throwState = 3
                end)
                table.insert(KnifeSAState._mobileConns, _touchConfirmConn)

                -- Limpieza al desactivar SA
                table.insert(KnifeSAState._mobileConns, {
                    Disconnect = function()
                        _mobileSeqActive = false
                        _throwState      = 0
                        _G._mobileThrowState = "IDLE"
                        _msaCache        = {}
                    end
                })
            end
 CreateCustomNotification("KNIFE SA", _isMobileKSA and "✅ Activo • toca la pantalla cuando el knife este en pose para lanzar" or "✅ Activo • equipa knife, lanza con RMB", 3)
        else
            _KnifeSA_deactivate()
            -- Restaurar cualquier knife que IKS hubiera ocultado
            for model, _ in pairs(InvisibleKnifeSystem.activeKnives) do
                pcall(_IKS_show, model)
            end
            -- Desconectar hooks al bot?n Throw nativo (mobile)
            if KnifeSAState._mobileConns then
                for _, c in ipairs(KnifeSAState._mobileConns) do
                    pcall(function() c:Disconnect() end)
                end
                KnifeSAState._mobileConns = {}
            end
            -- FIX MOBILE: asegurarse de que KnifeClient quede habilitado
            -- porque el bot?n mobile puede haber dejado el knife en estado SA
            do
                local char = LocalPlayer.Character
                local function _reEnableKnifeClient(parent)
                    if not parent then return end
                    local knife = parent:FindFirstChild("Knife")
                    if not knife then return end
                    local kc = knife:FindFirstChild("KnifeClient")
                    if kc then kc.Disabled = false end
                end
                if char then _reEnableKnifeClient(char) end
                _reEnableKnifeClient(LocalPlayer.Backpack)
            end
            -- FIX RESTORE: resetear todos los estados del SA que puedan haber quedado activos
            KnifeSAState.wallCheck      = false
            KnifeSAState.fastSlash      = false
            KnifeSAState.fastSlashSpeed = 20
            KnifeSAState.prediction     = "Dynamic"
            KnifeSAState.target         = "Closest"
            KnifeSAState._lastTargetId  = nil
            KnifeSAState._origCanCollide = {}
            -- Limpiar historial de predicci?n para evitar datos sucios en pr?xima activaci?n
            _knifeSA_posHistory = table.create(90)
            _ksa_head = 1
            _ksa_count = 0
            _knifeSA_lastHistoryTime = 0
            -- Resetear toggle de Wall Check en UI si est? activo
            if _G._toggleStates then
                _G._toggleStates["Knife Silent Aim Wall Check"] = false
            end
 CreateCustomNotification("KNIFE SA", "Desactivado ? todo restaurado", 2)
        end
    end, KnifeSAState.enabled)
    -- Wire _toggleFn so the bindable button uses the FULL toggle logic (with restore)
    KnifeSAState._toggleFn = function()
        local newState = not KnifeSAState.enabled
        if _ksaToggleRef and _ksaToggleRef.SetState then
            _ksaToggleRef:SetState(newState)
        else
            -- Fallback: replicate full on/off logic inline
            KnifeSAState.enabled = newState
            _G._toggleStates = _G._toggleStates or {}
            _G._toggleStates["Knife Silent Aim"] = newState
            if newState then
                pcall(_KnifeSA_activate)
                CreateCustomNotification("KNIFE SA", "Activado", 1.5)
            else
                pcall(_KnifeSA_deactivate)
                -- Restore knife fully (same as main toggle off branch)
                local char = LocalPlayer.Character
                if char then
                    local function _restoreK(knife)
                        if not knife then return end
                        local kc = knife:FindFirstChild("KnifeClient")
                        if kc then kc.Disabled = false end
                        local origCC = KnifeSAState._origCanCollide or {}
                        for _, part in ipairs(knife:GetDescendants()) do
                            if part:IsA("BasePart") then
                                pcall(function() part.CanCollide = (origCC[part] ~= nil) and origCC[part] or true end)
                            end
                        end
                        local kHandle = knife:FindFirstChild("Handle")
                        if kHandle then pcall(function() kHandle.CanCollide = (origCC[kHandle] ~= nil) and origCC[kHandle] or true end) end
                        -- Stop SA animations
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        local animr = hum and hum:FindFirstChildOfClass("Animator")
                        if animr then
                            for _, track in ipairs(animr:GetPlayingAnimationTracks()) do
                                local id = track.Animation and track.Animation.AnimationId or ""
                                if id:find("knife") or id:find("Knife") or id:find("1108307876") then
                                    pcall(function() track:Stop(0.1) end)
                                end
                            end
                        end
                        -- Re-enable KnifeClient via defer so it retakes control
                        task.defer(function()
                            if not char or not char.Parent then return end
                            local k2 = char:FindFirstChild("Knife")
                            local kc2 = k2 and k2:FindFirstChild("KnifeClient")
                            if kc2 then kc2.Disabled = false end
                        end)
                    end
                    _restoreK(char:FindFirstChild("Knife"))
                    local bp = LocalPlayer.Backpack
                    if bp then _restoreK(bp:FindFirstChild("Knife")) end
                end
                -- Reset sub-states
                KnifeSAState.wallCheck = false
                KnifeSAState.fastSlash = false
                KnifeSAState._origCanCollide = {}
                _knifeSA_posHistory = table.create(90); _ksa_head = 1; _ksa_count = 0
                if _G._toggleStates then _G._toggleStates["Knife Silent Aim Wall Check"] = false end
                CreateCustomNotification("KNIFE SA", "Desactivado ? knife restaurado", 2)
