                            if knife then pcall(function() FireKnifeOnTarget(knife, hrp) end) end
                        end
                    end
                    task.wait(0.1)
                end
                _kaRunning = false
                CreateCustomNotification("KILL ALL", "Terminado", 1.5)
            end)
