        -- -------------------------------------------------------------------
    -- THROWING KNIFE ? Silent Aim via __namecall hook (MainEvent spoof)
    -- -------------------------------------------------------------------
    do
 local tkSilentSection = CreateBorderedSection(leftColumn, " THROWING KNIFE ? SILENT AIM")



        -- State
        CombatTabState.tkSA = CombatTabState.tkSA or {
            enabled = false,
            range   = 30,
            hookActive = false,
            oldNamecall = nil,
            mt = nil,
            lastKilledUserId = 0,
            lastThrowTime    = 0,
        }
        local tkSA = CombatTabState.tkSA

        -- Helper: find closest living player within range
        local function _tkGetClosest(myHRP, range)
            local best, bestDist = nil, math.huge
            for _, p in ipairs(_cachedPlayers) do
                if p == LocalPlayer then continue end
                local ch = p.Character
                if not ch then continue end
                local pHRP = ch:FindFirstChild("HumanoidRootPart")
                local pHum = ch:FindFirstChildOfClass("Humanoid")
                if not pHRP or not pHum or pHum.Health <= 0 then continue end
                local d = (myHRP.Position - pHRP.Position).Magnitude
                if d < range and d < bestDist then
                    bestDist = d
                    best = pHRP
                end
            end
            return best
        end

        -- Apply / remove namecall hook
        local function _tkApplyHook()
            if tkSA.hookActive then return end
            if not (hookmetamethod and getrawmetatable and setreadonly and newcclosure and getnamecallmethod) then
 CreateCustomNotification("TK SILENT AIM", " Executor sin hookmetamethod", 3)
                return false
            end
            local mt = getrawmetatable(game)
            local oldNC = mt.__namecall
            tkSA.oldNamecall = oldNC
            tkSA.mt = mt
            setreadonly(mt, false)
            mt.__namecall = newcclosure(function(self, ...)
                local method = getnamecallmethod()
                if method == "FireServer" and tkSA.enabled then
                    -- Check if this is the knife throw remote
                    local ok, selfName = pcall(function() return self.Name end)
                    if ok and selfName then
                        local args = {...}
                        local lname = selfName:lower()
                        -- MM2 uses RemoteEvent named "MainEvent" or "KnifeThrown" event
                        -- The first arg is "KnifeThrown" and second is target position/CFrame
                        local isKnifeThrow = false
                        if lname:find("main") or lname:find("knife") or lname:find("throw") then
                            if typeof(args[1]) == "string" and args[1] == "KnifeThrown" then
                                isKnifeThrow = true
                            elseif typeof(args[1]) == "CFrame" or typeof(args[1]) == "Vector3" then
                                -- Direct KnifeThrown FireServer(handleCF, targetCF)
                                isKnifeThrow = lname:find("throw") ~= nil
                            end
                        end
                        -- Also intercept direct KnifeThrown remote
                        if selfName == "KnifeThrown" or selfName == "KnifeThrow" then
                            isKnifeThrow = true
                        end

                        if isKnifeThrow then
                            -- FIX: si Knife Silent Aim est? activo, NO interceptar ?
                            -- el SA ya mand? el FireServer con la predicci?n correcta
                            if KnifeSAState and KnifeSAState.enabled then
                                return oldNC(self, ...)
                            end
                            local myChar = LocalPlayer.Character
                            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                            if myHRP then
                                local closestHRP = _tkGetClosest(myHRP, tkSA.range)
                                -- 1 kill por lanzamiento: si el mas cercano fue el ultimo kill (<2s), usar el segundo
                                if closestHRP then
                                    local nowT = tick()
                                    local ownerCh = closestHRP.Parent
                                    local ownerPl = ownerCh and game:GetService("Players"):GetPlayerFromCharacter(ownerCh)
                                    local ownerId = ownerPl and ownerPl.UserId or 0
                                    if ownerId ~= 0 and ownerId == tkSA.lastKilledUserId
                                       and (nowT - tkSA.lastThrowTime) < 2.0 then
                                        local best2, best2Dist = nil, math.huge
                                        for _, p in ipairs(_cachedPlayers) do
                                            if p == LocalPlayer or p.UserId == ownerId then continue end
                                            local ch2 = p.Character
                                            local hrp2 = ch2 and ch2:FindFirstChild("HumanoidRootPart")
                                            local hum2 = ch2 and ch2:FindFirstChildOfClass("Humanoid")
                                            if hrp2 and hum2 and hum2.Health > 0 then
                                                local d2 = (myHRP.Position - hrp2.Position).Magnitude
                                                if d2 < tkSA.range and d2 < best2Dist then
                                                    best2 = hrp2; best2Dist = d2
                                                end
                                            end
                                        end
                                        if best2 then closestHRP = best2 end
                                    end
                                    local finalCh = closestHRP.Parent
                                    local finalPl = finalCh and game:GetService("Players"):GetPlayerFromCharacter(finalCh)
                                    tkSA.lastKilledUserId = finalPl and finalPl.UserId or 0
                                    tkSA.lastThrowTime    = nowT
                                end
                                if closestHRP then
                                    local targetPos = closestHRP.Position + Vector3.new(0, 0.5, 0)
                                    -- Find and replace Vector3/CFrame args with target position
                                    for i, v in ipairs(args) do
                                        if typeof(v) == "Vector3" then
                                            args[i] = targetPos
                                        elseif typeof(v) == "CFrame" then
                                            -- If it looks like a target CFrame (not origin)
                                            local dist = (v.Position - myHRP.Position).Magnitude
                                            if dist > 2 then  -- not the handle origin
                                                args[i] = CFrame.new(targetPos)
                                            end
                                        end
                                    end
                                end
                            end
                            return oldNC(self, table.unpack(args))
                        end
                    end
                end
                return oldNC(self, ...)
            end)
            setreadonly(mt, true)
            tkSA.hookActive = true
            return true
        end

        local function _tkRemoveHook()
            if not tkSA.hookActive or not tkSA.mt or not tkSA.oldNamecall then return end
            pcall(function()
                setreadonly(tkSA.mt, false)
                tkSA.mt.__namecall = tkSA.oldNamecall
                setreadonly(tkSA.mt, true)
            end)
            tkSA.hookActive = false
            tkSA.oldNamecall = nil
            tkSA.mt = nil
        end

        -- Restore if was active
        if tkSA.enabled and not tkSA.hookActive then _tkApplyHook() end

        -- -- KNIFE HITBOX EXPANDER ? reemplaza Silent Aim ------------------
        -- Expande KnifeVisual mientras vuela + fire remotes (KnifeThrown,
        -- HandleTouched, KnifeStabbed, Handle.Kill) a jugadores en rango.
        local _KHB_enabled  = false
        local _KHB_mainConn = nil
        local _KHB_conns    = {}

        local function _KHB_getKnife()
            local char = LocalPlayer.Character
            local bp   = LocalPlayer:FindFirstChild("Backpack")
            return (char and char:FindFirstChild("Knife"))
                or (bp  and bp:FindFirstChild("Knife"))
        end

        local function _KHB_fireAll(kPos, tHRP)
            local myChar = LocalPlayer.Character
            if myChar and tHRP:IsDescendantOf(myChar) then return end
            local knife  = _KHB_getKnife()
            if not knife then return end
            local ev     = knife:FindFirstChild("Events")
            local handle = knife:FindFirstChild("Handle")
            if not ev then return end
            local tPos = tHRP.Position
            local dir  = tPos - kPos  -- vector del knife al target

            -- bladeCF: origen del knife, LookVector apunta HACIA el target
            local bladeCF = dir.Magnitude > 0.01
                and CFrame.new(kPos, tPos)
                or  CFrame.new(kPos)

            -- FIX: targetCF debe apuntar DE VUELTA al origen (igual que gun SA)
            -- El servidor valida que targetCF.LookVector apunte hacia el shooter.
            -- Antes apuntaba en la misma direcci?n que bladeCF ? rechazo del servidor.
            local backDir = kPos - tPos  -- inverso: del target de vuelta al knife
            local targetCF = backDir.Magnitude > 0.01
                and CFrame.new(tPos, tPos + backDir.Unit)
                or  CFrame.new(tPos)

            local thrown  = ev:FindFirstChild("KnifeThrown")
            local touched = ev:FindFirstChild("HandleTouched")
            local stabbed = ev:FindFirstChild("KnifeStabbed")

            -- Probar firma principal y firma invertida como fallback
            if thrown then
                local fired = false
                pcall(function() thrown:FireServer(bladeCF, targetCF); fired = true end)
                if not fired then
                    pcall(function() thrown:FireServer(targetCF, bladeCF) end)
                end
            end
            if touched then pcall(function() touched:FireServer(tHRP) end) end
            if stabbed then pcall(function() stabbed:FireServer() end) end
            if handle  then
                local kill = handle:FindFirstChild("Kill")
                if kill then
                    pcall(function() kill:FireServer(tHRP) end)
                    pcall(function() kill:FireServer(tHRP.Parent) end)
                    pcall(function() kill:FireServer() end)
                end
                for _, re in ipairs(handle:GetChildren()) do
                    if re:IsA("RemoteEvent") and re.Name ~= "Kill" then
                        pcall(function() re:FireServer(tHRP) end)
                    end
                end
            end
        end

        local function _KHB_expandPart(part)
            if not part or not part:IsA("BasePart") then return end
            pcall(function()
                part.Size = Vector3.new(tkSA.range * 2, tkSA.range * 2, tkSA.range * 2)
                part.Transparency = 0.93
                part.CanCollide   = false
            end)
        end

        local function _KHB_monitor(obj)
            if not _KHB_enabled then return end
            local isStuck = (obj.Name == "StucKnife")
            -- Referencia de posici?n
            local posRef
            if obj:IsA("Model") then
                posRef = obj:FindFirstChild("KnifeVisual")
                      or obj:FindFirstChildWhichIsA("MeshPart")
                      or obj:FindFirstChildWhichIsA("BasePart")
            elseif obj:IsA("BasePart") then posRef = obj
            else posRef = obj:FindFirstChildWhichIsA("BasePart") end
            if not posRef then return end

            -- Expandir inmediatamente
            _KHB_expandPart(posRef)

            -- Escalar progresivamente mientras vuela (rango crece de 0 a tkSA.range en 0.5s)
            if not isStuck then
                task.spawn(function()
                    local t = 0
                    local maxRange = tkSA.range
                    while obj and obj.Parent and _KHB_enabled do
                        t = t + 0.033
                        -- Crece de 1 stud hasta el rango completo en ~0.5s
                        local base = math.min(maxRange * 2, 2 + t * maxRange * 4)
                        pcall(function()
                            posRef.Size = Vector3.new(base, base, base)
                            posRef.CanCollide = false
                        end)
                        task.wait(0.033)
                    end
                end)
            end

            -- StucKnife: expansi?n masiva + fire inmediato (solo 1 jugador ? el m?s cercano)
            if isStuck then
                task.spawn(function()
                    local kPos = posRef.Position
                    local range = tkSA.range
                    _G._TK_RANGE = range
                    pcall(function()
                        posRef.Size = Vector3.new(range * 4, range * 4, range * 4)
                        posRef.Transparency = 0.96; posRef.CanCollide = false
                    end)
                    local bestP, bestHRP, bestDist = nil, nil, math.huge
                    for _, p in ipairs(_cachedPlayers) do
                        if p == LocalPlayer then continue end
                        local pc = p.Character
                        if not pc then continue end
                        local phrp = pc:FindFirstChild("HumanoidRootPart")
                        if not phrp then continue end
                        local phum = pc:FindFirstChildOfClass("Humanoid")
                        if not phum or phum.Health <= 0 then continue end
                        local d = (kPos - phrp.Position).Magnitude
                        -- OPT: sin wall check ? knives atraviesan paredes en MM2
                        if d <= range and d < bestDist then
                            bestDist = d; bestP = p; bestHRP = phrp
                        end
                    end
                    if bestP and bestHRP then
                        -- FIX: verificar vivo antes de disparar
                        local _stHum = bestP.Character and bestP.Character:FindFirstChildOfClass("Humanoid")
                        if _stHum and _stHum.Health > 0 and bestHRP.Parent then
                            _KHB_fireAll(kPos, bestHRP)
                            CreateCustomNotification("KNIFE STUCK ?",
                                bestP.Name .. " @ " .. math.floor(bestDist) .. " studs", 2)
                        end
                    end
                end)
            end

        -- Heartbeat 20Hz ? mata al jugador m?s cercano en rango (1 kill por lanzamiento)
            local _kHBKilled = false
            local hbT = 0
            local conn
            conn = RunService.Heartbeat:Connect(function()
                if not _KHB_enabled then pcall(function() conn:Disconnect() end); return end
                if _kHBKilled         then pcall(function() conn:Disconnect() end); return end
                hbT = hbT + 1; if hbT < 3 then return end; hbT = 0  -- OPT: 30?20Hz

                -- Guard: el knife o la parte de referencia ya no existen
                if not obj or not obj.Parent or not posRef or not posRef.Parent then
                    pcall(function() conn:Disconnect() end); return
                end

                local kPos  = posRef.Position
                local range = _G._TK_RANGE or tkSA.range  -- siempre leer el valor m?s fresco
                _G._TK_RANGE = tkSA.range  -- mantener sync

                local bestP, bestHRP, bestDist = nil, nil, math.huge
                for _, p in ipairs(_cachedPlayers) do
                    if p == LocalPlayer then continue end
                    local pc   = p.Character
                    if not pc or not pc.Parent then continue end
                    local phrp = pc:FindFirstChild("HumanoidRootPart")
                    if not phrp or not phrp.Parent then continue end
                    local phum = pc:FindFirstChildOfClass("Humanoid")
                    -- FIX: verificar vivo Y que el personaje sea v?lido en este frame
                    if not phum or phum.Health <= 0 then continue end
                    local d = (kPos - phrp.Position).Magnitude
                    if d <= range and d < bestDist then
                        bestDist = d; bestP = p; bestHRP = phrp
                    end
                end

                if bestP and bestHRP then
                    -- FIX: verificar que el target siga vivo justo antes de disparar
                    local tHum = bestP.Character and bestP.Character:FindFirstChildOfClass("Humanoid")
                    if tHum and tHum.Health > 0 and bestHRP.Parent then
                        _kHBKilled = true
                        _KHB_fireAll(kPos, bestHRP)
                        CreateCustomNotification("KNIFE HIT ?",
                            bestP.Name .. " @ " .. math.floor(bestDist) .. " studs", 2)
                    end
                    pcall(function() conn:Disconnect() end)
                end
            end)
            table.insert(_KHB_conns, conn)
            if #_KHB_conns > 20 then
                for i=1,5 do pcall(function() table.remove(_KHB_conns,1):Disconnect() end) end
            end
        end

        local function _KHB_start()
            _KHB_enabled = true
            -- Scan existentes
            for _, obj in ipairs(workspace:GetChildren()) do
                if obj.Name == "ThrowingKnife" or obj.Name == "StucKnife" then
                    _KHB_monitor(obj)
                end
            end
            -- ChildAdded
            _KHB_mainConn = workspace.ChildAdded:Connect(function(obj)
                if not _KHB_enabled then return end
                local n = obj.Name
                if n == "ThrowingKnife" and obj:IsA("Model") then
                    task.wait(0.02); _KHB_monitor(obj)
                elseif n == "StucKnife" then
                    _KHB_monitor(obj)
                end
            end)
            -- DescendantAdded (StucKnife dentro de Model)
            local dc = workspace.DescendantAdded:Connect(function(obj)
                if not _KHB_enabled then return end
                if obj.Name == "StucKnife" and obj:IsA("BasePart") then
                    if not obj:GetAttribute("_khb_done") then
                        obj:SetAttribute("_khb_done", true)
                        _KHB_monitor(obj)
                    end
                end
            end)
            table.insert(_KHB_conns, dc)
        end

        local function _KHB_stop()
            _KHB_enabled = false
            if _KHB_mainConn then pcall(function() _KHB_mainConn:Disconnect() end); _KHB_mainConn = nil end
            for _, c in ipairs(_KHB_conns) do pcall(function() c:Disconnect() end) end
            _KHB_conns = {}
        end

        CreateBorderedToggle(tkSilentSection, "Throwing Knife Silent Aim", function(en)
            if en then
                _KHB_start()
                -- [notif removed]
            else
                _KHB_stop()
                -- [notif removed]
            end
        end, false)

        -- Range slider ? controla cu?ntos studs mata y el tama?o del expand
 CreateSlider(tkSilentSection, "Max Range (studs)", 0, 100, tkSA.range, function(v)
            tkSA.range    = v
            _G._TK_RANGE  = v  -- sincronizar con sistema TK global
        end)

        -- ------------------------------------------------------------------
        -- INSTANT THROW ? lanza el knife autom?ticamente al jugador m?s
        -- cercano en campo de visi?n (con wall check). Usa KnifeThrown
        -- directo igual que _TK_fire pero en loop de Heartbeat.
        -- ------------------------------------------------------------------
        do
            CombatTabState.instantThrow = CombatTabState.instantThrow or {
                enabled  = false,
                conn     = nil,
                lastFire = -999,
                cooldown = 0.08,  -- segundos entre lanzamientos (lo m?s r?pido posible)
            }
            local _it = CombatTabState.instantThrow

            -- Helper: obtener el knife (equipado o en backpack)
            local function _itGetKnife()
                local char = LocalPlayer.Character
                local bp   = LocalPlayer:FindFirstChild("Backpack")
                if char then
                    local k = char:FindFirstChild("Knife")
                    if k then return k end
                end
                if bp then
                    local k = bp:FindFirstChild("Knife")
                    if k then return k end
                end
                return nil
            end

            -- Helper: jugador m?s cercano visible (wall check + FOV de c?mara)
            local function _itGetTarget(myHRP, range)
                local cam   = workspace.CurrentCamera
                local best, bestDist = nil, math.huge
                for _, p in ipairs(_cachedPlayers) do
                    if p == LocalPlayer then continue end
                    local ch  = p.Character
                    if not ch then continue end
                    local pHRP = ch:FindFirstChild("HumanoidRootPart")
                    local pHum = ch:FindFirstChildOfClass("Humanoid")
                    if not pHRP or not pHum or pHum.Health <= 0 then continue end

                    local d = (myHRP.Position - pHRP.Position).Magnitude
                    if d > range then continue end

                    -- Wall check: ojo del local player ? cuerpo del target
                    local eyePos  = myHRP.Position + Vector3.new(0, 1.5, 0)
                    local bodyPos = pHRP.Position  + Vector3.new(0, 0.8, 0)
                    local visible = wallCheckRaycast(eyePos, bodyPos)
                    if not visible then continue end

                    -- FOV check: el jugador debe estar en el campo de visi?n de la c?mara
                    local screenPos, onScreen = cam:WorldToViewportPoint(pHRP.Position)
                    if not onScreen then continue end

                    if d < bestDist then
                        bestDist = d
                        best = pHRP
                    end
                end
                return best, bestDist
            end

            -- Disparar KnifeThrown hacia el target
            local function _itFire(knife, myHRP, tHRP)
                local ev = knife:FindFirstChild("Events")
                if not ev then return end

                local kPos     = myHRP.Position + Vector3.new(0, 1, 0)
                local tPos     = tHRP.Position  + Vector3.new(0, 0.5, 0)
                local dir      = tPos - kPos
                if dir.Magnitude < 0.01 then return end

                local bladeCF  = CFrame.new(kPos, tPos)
                -- FIX: targetCF debe apuntar DE VUELTA al origen (como en gun SA y _KHB_fireAll)
                local backDir  = kPos - tPos
                local targetCF = backDir.Magnitude > 0.01
                    and CFrame.new(tPos, tPos + backDir.Unit)
                    or  CFrame.new(tPos)

                -- 1. KnifeThrown (firma principal)
                local thrown = ev:FindFirstChild("KnifeThrown")
                if thrown then
                    pcall(function() thrown:FireServer(bladeCF, targetCF) end)
                end

                -- 2. HandleTouched ? simula colisi?n
                local touched = ev:FindFirstChild("HandleTouched")
                if touched then
                    pcall(function() touched:FireServer(tHRP) end)
                end

                -- 3. KnifeStabbed
                local stabbed = ev:FindFirstChild("KnifeStabbed")
                if stabbed then pcall(function() stabbed:FireServer() end) end

                -- 4. Handle.Kill
                local handle = knife:FindFirstChild("Handle")
                if handle then
                    local kill = handle:FindFirstChild("Kill")
                    if kill then
                        pcall(function() kill:FireServer(tHRP) end)
                        pcall(function() kill:FireServer(tHRP.Parent) end)
                        pcall(function() kill:FireServer() end)
                    end
                    for _, re in ipairs(handle:GetChildren()) do
                        if re:IsA("RemoteEvent") and re.Name ~= "Kill" then
                            pcall(function() re:FireServer(tHRP) end)
                        end
                    end
                end
            end

            local function _itStart()
                if _it.conn then pcall(function() _it.conn:Disconnect() end) end
                local _hb = 0
                _it.conn = RunService.Heartbeat:Connect(function()
                    _hb = _hb + 1; if _hb < 2 then return end; _hb = 0  -- ~30Hz
                    if not _it.enabled then return end
                    if _G._visualRoundOver then return end

                    local now  = tick()
                    if now - _it.lastFire < _it.cooldown then return end

                    local char  = LocalPlayer.Character
                    local myHRP = char and char:FindFirstChild("HumanoidRootPart")
                    local myHum = char and char:FindFirstChildOfClass("Humanoid")
                    if not myHRP or not myHum or myHum.Health <= 0 then return end

                    local knife = _itGetKnife()
                    if not knife then return end

                    local range = tkSA.range > 0 and tkSA.range or 50
                    local tHRP, dist = _itGetTarget(myHRP, range)
                    if not tHRP then return end

                    -- No suicidarse
                    if tHRP:IsDescendantOf(char) then return end

                    _it.lastFire = now
                    _itFire(knife, myHRP, tHRP)
                end)
            end

            local function _itStop()
                if _it.conn then pcall(function() _it.conn:Disconnect() end); _it.conn = nil end
            end

            -- Restaurar si estaba activo
            if _it.enabled then _itStart() end

            CreateBorderedToggle(tkSilentSection, "Instant Throw", function(en)
                _it.enabled = en
                if en then
                    _itStart()
                    -- [notif removed]
                else
                    _itStop()
                    -- [notif removed]
                end
            end, false)

            -- Slider de cooldown entre lanzamientos
            CreateSlider(tkSilentSection, "Instant Throw Cooldown (s)", 0, 1, _it.cooldown, function(v)
                _it.cooldown = v
            end)
        end
    end

    -- -- KNIFE SILENT AIM BUTTON ? sistema bindable unificado -----------------
    knifeBindState = knifeBindState or { enabled = false, _gui = nil, draggable = false }

    -- -- SLIDERS DE PREDICCI?N DEL KNIFE -------------------------------------
 knifePredSection = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, " PREDICCIN  TIANCA") or Instance.new("Frame")

    -- Funcin helper (mantenida por compatibilidad interna, no genera UI)
    -- CreateKnifePredSlider  devuelve {frame, setValue}
    -- setValue(v) mueve el knob y actualiza el label visualmente sin drag
    function CreateKnifePredSlider(parent, title, minVal, maxVal, defaultVal, callback)
        -- ==============================================================
        --  KNIFE PRED SLIDER  misma apariencia que CreateSlider
        --  Panel cristal con gradiente diagonal  borde aurora shimmer
        --  Caja de valor separada  track teal  thumb blanco circular
        -- ==============================================================
        local C_STROKE   = ThemeColors.Primary
        local C_TEXT     = ThemeColors.TextPrimary
        local C_SUBTEXT  = ThemeColors.TextSecondary
        local C_TRACK_BG = ThemeColors.Aurora2
        local C_TRACK_FG = ThemeColors.Primary
        local C_THUMB    = ThemeColors.Accent

        local STEP = 0.01
        local CONTAINER_H = 44   -- igual que CreateSlider

        -- -- CONTENEDOR PRINCIPAL  glassmorphism idntico a CreateSlider --
        local container = Instance.new("Frame", parent)
        container.Name                   = "KnifeSliderWrapper_" .. title
        container.Size                   = UDim2.new(1, -4, 0, CONTAINER_H)

        container.BackgroundTransparency = 1
        container.BorderSizePixel        = 0
        container.ClipsDescendants       = false























        -- -- TTULO (izquierda, arriba) ------------------------------
        local titleLabel = Instance.new("TextLabel", container)
        titleLabel.Name                   = "TitleLabel"
        titleLabel.Size                   = UDim2.new(1, -90, 0, 18)
        titleLabel.Position               = UDim2.new(0, 10, 0, 6)
        titleLabel.BackgroundTransparency = 1
        titleLabel.Text                   = title
        titleLabel.TextXAlignment         = Enum.TextXAlignment.Left
        titleLabel.TextYAlignment         = Enum.TextYAlignment.Center
        titleLabel.TextColor3             = C_TEXT
        titleLabel.FontFace               = Font.fromEnum(Enum.Font.Montserrat)
        titleLabel.TextSize               = 13
        titleLabel.TextTruncate           = Enum.TextTruncate.AtEnd
        titleLabel.ZIndex                 = 12

        -- -- CAJA DE VALOR --------------------------------------------
        local valBox = Instance.new("Frame", container)
        valBox.Size                   = UDim2.new(0, 58, 0, 20)
        valBox.Position               = UDim2.new(0, 10, 0, 28)
        valBox.BackgroundColor3       = ThemeColors.BackgroundLight
        valBox.BackgroundTransparency = 0.10
        valBox.BorderSizePixel        = 0
        valBox.ZIndex                 = 12
        Instance.new("UICorner", valBox).CornerRadius = UDim.new(0, 5)
        local vbStroke = Instance.new("UIStroke", valBox)
        vbStroke.Color           = ThemeColors.Primary
        vbStroke.Thickness       = 1
        vbStroke.Transparency    = 0.4
        vbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local valueLabel = Instance.new("TextLabel", valBox)
        valueLabel.Size                   = UDim2.new(1, 0, 1, 0)
        valueLabel.BackgroundTransparency = 1
        valueLabel.Text                   = string.format("%.2f", defaultVal)
        valueLabel.TextXAlignment         = Enum.TextXAlignment.Center
        valueLabel.TextYAlignment         = Enum.TextYAlignment.Center
        valueLabel.TextColor3             = C_TEXT
        valueLabel.FontFace               = Font.fromEnum(Enum.Font.Montserrat)
        valueLabel.TextSize               = 12
        valueLabel.ZIndex                 = 13

        -- -- SUBTTULO RANGO ------------------------------------------
        local subtitleLabel = Instance.new("TextLabel", container)
        subtitleLabel.Name                   = "SubtitleLabel"
        subtitleLabel.Size                   = UDim2.new(0, 80, 0, 12)
        subtitleLabel.Position               = UDim2.new(0, 10, 1, -14)
        subtitleLabel.BackgroundTransparency = 1
        subtitleLabel.Text                   = tostring(minVal) .. "  " .. tostring(maxVal)
        subtitleLabel.TextXAlignment         = Enum.TextXAlignment.Left
        subtitleLabel.TextYAlignment         = Enum.TextYAlignment.Center
        subtitleLabel.TextColor3             = C_SUBTEXT
        subtitleLabel.FontFace               = Font.fromEnum(Enum.Font.Montserrat)
        subtitleLabel.TextSize               = 10
        subtitleLabel.ZIndex                 = 12

        -- -- TRACK ----------------------------------------------------
        local sliderTrack = Instance.new("Frame", container)
        sliderTrack.Name                   = "SliderTrack"
        sliderTrack.Size                   = UDim2.new(1, -20, 0, 2)
        sliderTrack.Position               = UDim2.new(0, 10, 0, 36)
        sliderTrack.BackgroundColor3       = C_TRACK_BG
        sliderTrack.BackgroundTransparency = 0.40
        sliderTrack.BorderSizePixel        = 0
        sliderTrack.ClipsDescendants       = false
        sliderTrack.ZIndex                 = 12
        Instance.new("UICorner", sliderTrack).CornerRadius = UDim.new(1, 0)






        -- Fill bar teal brillante
        local initPct = math.clamp((defaultVal - minVal) / math.max(0.001, maxVal - minVal), 0, 1)
        local sliderFill = Instance.new("Frame", sliderTrack)
        sliderFill.Name                   = "FillBar"
        sliderFill.Size                   = UDim2.new(initPct, 0, 1, 0)
        sliderFill.BackgroundColor3       = C_TRACK_FG
        sliderFill.BackgroundTransparency = 0.0
        sliderFill.BorderSizePixel        = 0
        sliderFill.ZIndex                 = 13
        Instance.new("UICorner", sliderFill).CornerRadius = UDim.new(1, 0)

        -- -- THUMB ----------------------------------------------------
        local sliderThumb = Instance.new("ImageButton", sliderTrack)
        sliderThumb.Name                   = "SliderThumb"
        sliderThumb.Size                   = UDim2.new(0, 8, 0, 8)
        sliderThumb.AnchorPoint            = Vector2.new(0.5, 0.5)
        sliderThumb.Position               = UDim2.new(initPct, 0, 0.5, 0)
        sliderThumb.BackgroundColor3       = C_THUMB
        sliderThumb.BackgroundTransparency = 0.35
        sliderThumb.BorderSizePixel        = 0
        sliderThumb.ZIndex                 = 15
        Instance.new("UICorner", sliderThumb).CornerRadius = UDim.new(1, 0)
        local _thumbStroke3 = Instance.new("UIStroke", sliderThumb)
        _thumbStroke3.Color           = ThemeColors.Primary
        _thumbStroke3.Thickness       = 0.8
        _thumbStroke3.Transparency    = 0.10
        _thumbStroke3.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        -- -- LGICA ----------------------------------------------------
        local draggingKS = false
        local function applyValue(v)
            v = math.clamp(math.floor(v / STEP + 0.5) * STEP, minVal, maxVal)
            local ratio = math.clamp((v - minVal) / math.max(maxVal - minVal, 0.001), 0, 1)
            sliderThumb.Position = UDim2.new(ratio, 0, 0.5, 0)
            sliderFill.Size      = UDim2.new(ratio, 0, 1, 0)
            valueLabel.Text      = string.format("%.2f", v)
            if callback then callback(v) end
        end
        local function updateFromInput(inp)
            local mx = inp and inp.UserInputType == Enum.UserInputType.Touch and inp.Position.X or UserInputService:GetMouseLocation().X
            local tp = sliderTrack.AbsolutePosition.X; local ts = sliderTrack.AbsoluteSize.X
            applyValue(minVal + math.clamp((mx - tp) / math.max(ts, 1), 0, 1) * (maxVal - minVal))
        end
        local function updateFromMouse() updateFromInput(nil) end
        sliderThumb.MouseEnter:Connect(function()
            TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 22, 0, 22)}):Play()
        end)
        sliderThumb.MouseLeave:Connect(function()
            if not draggingKS then TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 18, 0, 18)}):Play() end
        end)
        sliderThumb.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingKS = true; _G._sliderDragging = true
                TweenService:Create(sliderThumb, TweenInfo.new(0.08), {Size = UDim2.new(0, 22, 0, 22)}):Play()
            end
        end)
        sliderTrack.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then draggingKS = true; _G._sliderDragging = true; updateFromInput(i) end
        end)
        RegisterTabConn(UserInputService.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingKS = false; _G._sliderDragging = false
                TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 18, 0, 18)}):Play()
            end
        end))
        RegisterTabConn(UserInputService.InputChanged:Connect(function(i)
            if draggingKS and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then updateFromInput(i) end
        end))
        applyValue(defaultVal)
        local function setValue(v) applyValue(v) end
        _attachScrollPassthrough(container, sliderTrack, sliderThumb)
        return container, setValue
    end

        -- Info solver removida

    -- == SLIDERS DE PREDICCIN KNIFE (Horizontal / Vertical / Divisor) ========
    -- Valores por defecto exactos de la imagen
    KnifeSAState.predHMin    = KnifeSAState.predHMin    or 16.5
