            -- Label de info en tiempo real (ping/fps/lag)
            local infoLbl = Instance.new("TextLabel", panel)
            infoLbl.Size = UDim2.new(1, -20, 0, 80)
            infoLbl.Position = UDim2.fromOffset(10, 118)
            infoLbl.BackgroundTransparency = 1
            infoLbl.Text = "Analizando sistema..."
            infoLbl.TextColor3 = Color3.fromRGB(210, 240, 255)
            infoLbl.Font = Enum.Font.Montserrat
            infoLbl.TextSize = 12
            infoLbl.TextWrapped = true
            infoLbl.ZIndex = 12

            -- Label de configuracin recomendada
            local recLbl = Instance.new("TextLabel", panel)
            recLbl.Size = UDim2.new(1, -20, 0, 100)
            recLbl.Position = UDim2.fromOffset(10, 200)
            recLbl.BackgroundTransparency = 1
            recLbl.Text = ""
            recLbl.TextColor3 = Color3.fromRGB(255, 230, 100)
            recLbl.Font = Enum.Font.Montserrat
            recLbl.TextSize = 11
            recLbl.TextWrapped = true
            recLbl.ZIndex = 12

            -- Botn cerrar
            local closeBtn = Instance.new("TextButton", panel)
            closeBtn.Size = UDim2.fromOffset(28, 28)
            closeBtn.Position = UDim2.new(1, -32, 0, 4)
            closeBtn.BackgroundColor3 = Color3.fromRGB(180, 40, 40)
            closeBtn.BackgroundTransparency = 0.2
            closeBtn.Text = ""
            closeBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
            closeBtn.Font = Enum.Font.Montserrat
            closeBtn.TextSize = 13
            closeBtn.BorderSizePixel = 0
            closeBtn.ZIndex = 13
            Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0, 6)
            closeBtn.Activated:Connect(_destroyCopyKnifeGui)

            -- Variables para anlisis
            local _fpsHistory   = {}
            local _pingHistory  = {}
            local _analysisDone = false
            local _spinAngle    = 0
            local _sampleCount  = 0
            local _maxSamples   = 60   -- ~3 segundos de muestras a 20Hz

            local _ckT = 0
            _copyKnifeConn = _safeConnect(RunService.Heartbeat, function(dt)
                if not sg.Parent then _destroyCopyKnifeGui(); return end
                _ckT = _ckT + dt; if _ckT < 0.066 then return end; _ckT = 0  -- OPT: 15fps UI
                _spinAngle = (_spinAngle + 8) % 360
                spinLbl.Rotation = _spinAngle

                if _analysisDone then return end

                -- Recolectar datos
                _sampleCount = _sampleCount + 1
                local ok, fps  = pcall(function() return math.floor(1 / dt) end)
                local ok2, ping = pcall(function() return math.floor(LocalPlayer:GetNetworkPing() * 1000) end)
                if ok  then table.insert(_fpsHistory,  fps)  end
                if ok2 then table.insert(_pingHistory, ping) end

                -- Actualizar label de info en tiempo real
                local curFps  = ok  and fps  or 0
                local curPing = ok2 and ping or 0
                local lag     = curPing > 120 and "ALTO" or curPing > 60 and "MEDIO" or "BAJO"
                infoLbl.Text = string.format(
 " Ping actual: %d ms  |  Lag: %s\n FPS actual: %d\n Muestras: %d/%d",
                    curPing, lag, curFps, _sampleCount, _maxSamples
                )

                -- Cuando tengamos suficientes muestras, calcular config recomendada
                if _sampleCount >= _maxSamples then
                    _analysisDone = true

                    -- Promedios
                    local avgPing, avgFps = 0, 0
                    for _, v in ipairs(_pingHistory) do avgPing = avgPing + v end
                    for _, v in ipairs(_fpsHistory)  do avgFps  = avgFps  + v  end
                    avgPing = math.floor(avgPing / math.max(1, #_pingHistory))
                    avgFps  = math.floor(avgFps  / math.max(1, #_fpsHistory))

                    -- --- Algoritmo de recomendacin ---------------------------
                    -- Basado en ping + fps -> ajustar prediccin horizontal/vertical
                    -- Ping alto = ms prediccin necesaria
                    -- FPS bajo  = ms suavizado necesario (divisor ms alto)

                    local hMin, hMax, dHMin, dHMax, vMin, vMax

                    if avgPing <= 40 then
                        -- Conexin excelente: poca prediccin
                        hMin=8;  hMax=25; dHMin=15; dHMax=20; vMin=12; vMax=22
                    elseif avgPing <= 80 then
                        -- Conexin buena: prediccin estndar
                        hMin=14; hMax=40; dHMin=18; dHMax=24; vMin=18; vMax=32
                    elseif avgPing <= 130 then
                        -- Conexin media: prediccin moderada (valores de imagen)
                        hMin=16.5; hMax=51; dHMin=20; dHMax=26; vMin=23.5; vMax=39
                    elseif avgPing <= 200 then
                        -- Conexin alta: ms prediccin
                        hMin=22; hMax=65; dHMin=24; dHMax=32; vMin=28; vMax=50
                    else
                        -- Conexin muy alta: prediccin agresiva
                        hMin=30; hMax=80; dHMin=28; dHMax=40; vMin=35; vMax=60
                    end

                    -- Ajuste por FPS bajo
                    if avgFps < 30 then
                        dHMin = dHMin + 5; dHMax = dHMax + 5
                    end

                    -- Aplicar config recomendada  actualiza valores Y mueve los sliders visualmente
                    -- Mover sliders si existen (pueden estar eliminados)
                    if _kpSliderSet.hMin  then _kpSliderSet.hMin(hMin)   end
                    if _kpSliderSet.hMax  then _kpSliderSet.hMax(hMax)   end
                    if _kpSliderSet.dHMin then _kpSliderSet.dHMin(dHMin) end
                    if _kpSliderSet.dHMax then _kpSliderSet.dHMax(dHMax) end
                    if _kpSliderSet.vMin  then _kpSliderSet.vMin(vMin)   end
                    if _kpSliderSet.vMax  then _kpSliderSet.vMax(vMax)   end
                    -- Aplicar directamente a KnifeSAState como fallback
                    KnifeSAState.predHMin    = hMin
                    KnifeSAState.predHMax    = hMax
                    KnifeSAState.predDivHMin = dHMin
                    KnifeSAState.predDivHMax = dHMax
                    KnifeSAState.predVMin    = vMin
                    KnifeSAState.predVMax    = vMax

                    recLbl.Text = string.format(
 " Config aplicada para %dms / %dfps:\nH Min=%.1f  H Max=%.1f\nDiv H Min=%.1f  Div H Max=%.1f\nV Min=%.1f  V Max=%.1f",
                        avgPing, avgFps, hMin, hMax, dHMin, dHMax, vMin, vMax
                    )
                    spinLbl.Text = ""
                    spinLbl.TextColor3 = Color3.fromRGB(130, 130, 135)
                    spinLbl.Rotation = 0

                    CreateCustomNotification("KNIFE CONFIG", "Config ptima aplicada  Ping: " .. avgPing .. "ms FPS: " .. avgFps, 4)
                end
            end)
        end

    end
 knifeKillSection = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, "KNIFE AURA") or Instance.new("Frame")

    if not Settings.premium.knifeAura.autoClick then
        Settings.premium.knifeAura.autoClick    = false
        Settings.premium.knifeAura.autoClickConn = nil
    end

    function _FireKnifeCombat(targetHrp)
        local char = LocalPlayer.Character; if not char then return end
        -- Buscar knife en personaje o backpack
        local knife = char:FindFirstChildWhichIsA("Tool")
        if not knife or not knife.Name:lower():find("knife") then
            knife = nil
            for _, t in pairs(LocalPlayer.Backpack:GetChildren()) do
                if t:IsA("Tool") and t.Name:lower():find("knife") then knife=t; break end
            end
            if knife then
                pcall(function()
                    local hum2 = char:FindFirstChildOfClass("Humanoid")
                    if hum2 then hum2:EquipTool(knife)
                    else knife.Parent = char end
                end)
                _w(0.05)
                knife = char:FindFirstChildWhichIsA("Tool")
                _showBackpackUI()
            end
        end
        if not knife then return end
        -- Metodo 1: KnifeStabbed / KnifeThrown del tool (el mas efectivo en MM2)
        pcall(function()
            local ev = knife:FindFirstChild("Events")
            if ev then
                local stab = ev:FindFirstChild("KnifeStabbed")
                if stab then stab:FireServer() end
                local thrown = ev:FindFirstChild("KnifeThrown")
                local handle = knife:FindFirstChild("Handle")
                if thrown and handle then thrown:FireServer(handle.CFrame, targetHrp.CFrame) end
            end
        end)
        -- Metodo 2: RemoteEvents dentro del tool
        pcall(function()
            for _, child in pairs(knife:GetDescendants()) do
                if child:IsA("RemoteEvent") then pcall(function() child:FireServer(targetHrp) end) end
            end
        end)
        -- Metodo 3: Activar el tool directamente
        pcall(function()
            local hum = char:FindFirstChildOfClass("Humanoid")  -- FIX: variable local, no global
            if hum then hum:EquipTool(knife) end
            knife:Activate()
        end)
    end

    -- OPT: cache de HumanoidRootParts por player ? se actualiza solo cuando
    -- un personaje cambia (CharacterAdded/CharacterRemoving), no en cada tick.
    -- Compartido entre KnifeAura y AutoClick para no duplicar el overhead.
    -- OPT: cache compartido de HRP + Humanoid para todos los loops de combat
    -- (KnifeAura, AutoClick, AutoStab) ? se actualiza por eventos, no por polling
    local _kaHRPCache = {}  -- [Player] = HumanoidRootPart | false
    local _kaHumCache = {}  -- [Player] = Humanoid | false

    local function _kaRebuildHRP(p)
        if not p or p == LocalPlayer then return end
        local char = p.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        _kaHRPCache[p] = hrp or false
        _kaHumCache[p] = hum or false
    end
    local function _kaFlushPlayer(p)
        _kaHRPCache[p] = nil
        _kaHumCache[p] = nil
    end

    local function _kaInitCache()
        _kaHRPCache = {}
        _kaHumCache = {}
        for _, p in ipairs(_cachedPlayers) do
            _kaRebuildHRP(p)
        end
    end
    _kaInitCache()

    _safeConnect(Players.PlayerAdded, function(p)
        _safeConnect(p.CharacterAdded,    function() task.defer(function() _kaRebuildHRP(p) end) end)
        _safeConnect(p.CharacterRemoving, function() _kaHRPCache[p] = false; _kaHumCache[p] = false end)
    end)
    _safeConnect(Players.PlayerRemoving, function(p) _kaFlushPlayer(p) end)
    for _, p in ipairs(_cachedPlayers) do
        if p ~= LocalPlayer then
            _safeConnect(p.CharacterAdded,    function() task.defer(function() _kaRebuildHRP(p) end) end)
            _safeConnect(p.CharacterRemoving, function() _kaHRPCache[p] = false; _kaHumCache[p] = false end)
        end
    end

    function _InitKnifeAuraCombat()
        if Settings.premium.knifeAura.connection then
            Settings.premium.knifeAura.connection:Disconnect()
            Settings.premium.knifeAura.connection = nil
        end
        local _hbTknifeAura = 0
        local _kaOnCooldown = false  -- FIX: flag para evitar bloquear el Heartbeat con task.wait
        Settings.premium.knifeAura.connection = RunService.Heartbeat:Connect(function()
            _hbTknifeAura = _hbTknifeAura + 1; if _hbTknifeAura < 3 then return end; _hbTknifeAura = 0  -- OPT: ~50ms
            if not Settings.premium.knifeAura.enabled then return end
            if _kaOnCooldown then return end  -- FIX: cooldown sin bloquear el heartbeat
            if _G._visualRoundOver then return end
            if _G._betweenRounds    then return end
            local char = LocalPlayer.Character; if not char then return end
            local hrp  = char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
            local savedCF  = hrp.CFrame
            local savedVel = hrp.AssemblyLinearVelocity
            local radius   = Settings.premium.knifeAura.radius
            local myPos    = hrp.Position
            -- OPT: usar cache de HRP - sin FindFirstChild en cada player cada tick
            for p, tHRP in pairs(_kaHRPCache) do
                if tHRP and tHRP.Parent then
                    local d = (myPos - tHRP.Position).Magnitude
                    if d <= radius then
                        -- WALL CHECK: wallCheckRaycast devuelve true = linea de vision libre (sin pared)
                        local eyePos  = myPos + Vector3.new(0, 1.5, 0)
                        local bodyPos = tHRP.Position + Vector3.new(0, 0.8, 0)
                        if not wallCheckRaycast(eyePos, bodyPos) then continue end
                        -- FIX: disparar en task.spawn para no bloquear el Heartbeat
                        _kaOnCooldown = true
                        local _tHRP = tHRP
                        local _savedCF = savedCF
                        local _savedVel = savedVel
                        _sp(function()
                            pcall(function() _FireKnifeCombat(_tHRP) end)
                            pcall(function()
                                hrp.CFrame = _savedCF
                                hrp.AssemblyLinearVelocity = _savedVel or Vector3.zero
                                hrp.AssemblyAngularVelocity = Vector3.zero
                            end)
                            _w(Settings.premium.knifeAura.cooldown or 0.3)
                            _kaOnCooldown = false
                        end)
                        break
                    end
                end
            end
        end)
    end

    function _InitAutoClickCombat()
        if Settings.premium.knifeAura.autoClickConn then
            Settings.premium.knifeAura.autoClickConn:Disconnect()
            Settings.premium.knifeAura.autoClickConn = nil
        end
        if not Settings.premium.knifeAura.autoClick then return end
        local _hbTknifeAC = 0
        Settings.premium.knifeAura.autoClickConn = _safeConnect(RunService.Heartbeat, function()
            _hbTknifeAC = _hbTknifeAC + 1; if _hbTknifeAC < 6 then return end; _hbTknifeAC = 0  -- OPT: 100ms
            if not Settings.premium.knifeAura.autoClick then return end
            if _G._visualRoundOver then return end
            if _G._betweenRounds    then return end
            local char = LocalPlayer.Character; if not char then return end
            local hrp  = char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
            local best, bd = nil, math.huge
            local radius = Settings.premium.knifeAura.radius
            local myPos  = hrp.Position
            -- OPT: usar cache de HRP ? sin FindFirstChild en cada player cada tick
            for p, tHRP in pairs(_kaHRPCache) do
                if tHRP and tHRP.Parent and tHRP.Position.Y <= 70 then
                    local d = (myPos - tHRP.Position).Magnitude
                    if d <= radius and d < bd then
                        -- WALL CHECK: solo seleccionar targets con l?nea de visi?n
                        local eyePos  = myPos + Vector3.new(0, 1.5, 0)
                        local bodyPos = tHRP.Position + Vector3.new(0, 0.8, 0)
                        if wallCheckRaycast(eyePos, bodyPos) then
                            bd = d; best = tHRP
                        end
                    end
                end
            end
            if best then _FireKnifeCombat(best); _w(Settings.premium.knifeAura.cooldown or 0.3) end
        end)
    end

    CreateBorderedToggle(knifeKillSection, "Enable Knife Aura", function(en)
        -- CONFLICT: Knife Aura dispara KnifeThrown en loop desde Heartbeat
        -- Knife SA tambin maneja KnifeThrown -> doble-fire -> TP o target equivocado
        if en and KnifeSAState and KnifeSAState.enabled then
 CreateCustomNotification("CONFLICT", "Desactiv Knife Silent Aim primero  Knife Aura y Knife SA disparan KnifeThrown al mismo tiempo.", 4)
            return
        end
        Settings.premium.knifeAura.enabled = en
        if en then
            _InitKnifeAuraCombat()
 CreateCustomNotification("KNIFE AURA", "Activo - golpea desde " .. Settings.premium.knifeAura.radius .. " studs", 3)
        else
            if Settings.premium.knifeAura.connection then
                Settings.premium.knifeAura.connection:Disconnect()
                Settings.premium.knifeAura.connection = nil
            end
 CreateCustomNotification("KNIFE AURA", "Desactivado", 2)
        end
    end, Settings.premium.knifeAura.enabled)

    -- [Sliders Aura Studs y Aura Cooldown eliminados por usuario]
    Settings.premium.knifeAura.radius   = Settings.premium.knifeAura.radius or 10
    Settings.premium.knifeAura.cooldown = Settings.premium.knifeAura.cooldown or 0.5

    -- Slider: rango del Knife Aura (mximo 60 studs)
    CreateSlider(knifeKillSection, "Knife Aura Rango (studs)", 1, 60,
        Settings.premium.knifeAura.radius or 10,
        function(v)
            Settings.premium.knifeAura.radius = v
            -- Si el aura est activa, reiniciarla con el nuevo rango
            if Settings.premium.knifeAura.enabled then
                if Settings.premium.knifeAura.connection then
                    Settings.premium.knifeAura.connection:Disconnect()
                    Settings.premium.knifeAura.connection = nil
                end
                _InitKnifeAuraCombat()
            end
        end
    )
    -- =============================================
    -- =============================================
    -- KNIFE HITBOX / REACH
    -- =============================================
    do
        local _reachEnabled = false
        local _reachSize    = 0          -- studs (sincronizado con el slider)
        local _reachConn    = nil
        local _KNIFE_DEFAULT_SIZE = Vector3.new(0.2, 0.3, 2.1)

        -- OPT: cache reactivo del knife ? se actualiza por eventos, no por polling
        local _cachedKnife = nil
        local _reachCharConns = {}

        -- -- SelectionBox hitbox visual por jugador --------------------------
        -- Tabla: [player] = SelectionBox instance
        local _hbBoxes    = {}
        local _hbBoxConns = {}  -- [player] = CharacterAdded conn

        local _HB_LINE_COLOR = Color3.fromRGB(255, 0, 0)   -- borde rojo igual a la imagen
        local _HB_LINE_THICK = 0.08                         -- grosor del borde
        local _HB_SURF_TRANSP = 1.0                         -- interior transparente (controlado por slider)

        local function _createBoxForPlayer(player)
            if player == LocalPlayer then return end
            -- Limpiar caja anterior si existe
            if _hbBoxes[player] then
                pcall(function() _hbBoxes[player]:Destroy() end)
                _hbBoxes[player] = nil
            end
            local char = player.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local sb = Instance.new("SelectionBox")
            sb.Name              = "HitboxESP"
            sb.Color3            = _HB_LINE_COLOR
            sb.LineThickness     = _HB_LINE_THICK
            sb.SurfaceTransparency = _HB_SURF_TRANSP
            sb.SurfaceColor3     = Color3.fromRGB(255, 50, 50)
            sb.Adornee           = hrp
            sb.Parent            = workspace
            _hbBoxes[player]     = sb
        end

        local function _removeBoxForPlayer(player)
            if _hbBoxes[player] then
                pcall(function() _hbBoxes[player]:Destroy() end)
                _hbBoxes[player] = nil
            end
        end

        local function _clearAllBoxes()
            for p, sb in pairs(_hbBoxes) do
                pcall(function() sb:Destroy() end)
                _hbBoxes[p] = nil
            end
        end

        local _hbPlayerAddedConn   = nil
        local _hbPlayerRemovingConn = nil

        local function _startHitboxVisuals()
            -- Crear cajas para todos los jugadores actuales
            for _, p in ipairs(_cachedPlayers) do
                _createBoxForPlayer(p)
                -- Hook CharacterAdded para recrear la caja al respawn
                if _hbBoxConns[p] then
                    pcall(function() _hbBoxConns[p]:Disconnect() end)
                end
                _hbBoxConns[p] = p.CharacterAdded:Connect(function()
                    task.wait(0.15)  -- esperar que el char cargue
                    if _reachEnabled then _createBoxForPlayer(p) end
                end)
            end
            -- Hook PlayerAdded para nuevos jugadores
            if not _hbPlayerAddedConn then
                _hbPlayerAddedConn = Players.PlayerAdded:Connect(function(p)
                    if not _reachEnabled then return end
                    _createBoxForPlayer(p)
                    _hbBoxConns[p] = p.CharacterAdded:Connect(function()
                        task.wait(0.15)
                        if _reachEnabled then _createBoxForPlayer(p) end
                    end)
                end)
            end
            -- Hook PlayerRemoving para limpiar
            if not _hbPlayerRemovingConn then
                _hbPlayerRemovingConn = Players.PlayerRemoving:Connect(function(p)
                    _removeBoxForPlayer(p)
                    if _hbBoxConns[p] then
                        pcall(function() _hbBoxConns[p]:Disconnect() end)
                        _hbBoxConns[p] = nil
                    end
                end)
            end
        end

        local function _stopHitboxVisuals()
            _clearAllBoxes()
            for p, c in pairs(_hbBoxConns) do
                pcall(function() c:Disconnect() end)
                _hbBoxConns[p] = nil
            end
            if _hbPlayerAddedConn   then pcall(function() _hbPlayerAddedConn:Disconnect()   end); _hbPlayerAddedConn   = nil end
            if _hbPlayerRemovingConn then pcall(function() _hbPlayerRemovingConn:Disconnect() end); _hbPlayerRemovingConn = nil end
        end
        -- -- fin SelectionBox system -----------------------------------------

        local function _isKnifeTool(t)
            return t:IsA("Tool") and t.Name:lower():find("knife")
        end

        local function _rebuildKnifeCache()
            _cachedKnife = nil
            local char = LocalPlayer.Character
            if char then
                for _, t in ipairs(char:GetChildren()) do
                    if _isKnifeTool(t) then _cachedKnife = t; return end
                end
            end
            for _, t in ipairs(LocalPlayer.Backpack:GetChildren()) do
                if _isKnifeTool(t) then _cachedKnife = t; return end
            end
        end

        local function _hookCharForKnife(char)
            for _, c in ipairs(_reachCharConns) do pcall(function() c:Disconnect() end) end
            _reachCharConns = {}
            if not char then return end
            table.insert(_reachCharConns, char.ChildAdded:Connect(function(t)
                if _isKnifeTool(t) then _cachedKnife = t end
            end))
            table.insert(_reachCharConns, char.ChildRemoved:Connect(function(t)
                if t == _cachedKnife then _rebuildKnifeCache() end
            end))
            table.insert(_reachCharConns, LocalPlayer.Backpack.ChildAdded:Connect(function(t)
                if _isKnifeTool(t) then _cachedKnife = t end
            end))
            table.insert(_reachCharConns, LocalPlayer.Backpack.ChildRemoved:Connect(function(t)
                if t == _cachedKnife then _rebuildKnifeCache() end
            end))
        end

        _rebuildKnifeCache()
        _hookCharForKnife(LocalPlayer.Character)
        _safeConnect(LocalPlayer.CharacterAdded, function(char)
            _cachedKnife = nil
            task.defer(function()
                _rebuildKnifeCache()
                _hookCharForKnife(char)
            end)
        end)

        -- Funci?n para obtener el knife (ahora solo lee el cache)
        local function _getKnife()
            if _cachedKnife and _cachedKnife.Parent then return _cachedKnife end
            _rebuildKnifeCache()  -- fallback si el cache qued? stale
            return _cachedKnife
        end

        -- Funci?n aplicar reach al handle del knife
        local function _applyReach(knife)
            local handle = knife and knife:FindFirstChild("Handle")
            if not handle then return end
            handle.Size         = Vector3.new(_reachSize, _reachSize, _reachSize)
            handle.Massless     = true
            handle.CanCollide   = false
            handle.Transparency = _G._dualKnifeEnabled and 0 or 1
            if not handle:FindFirstChildOfClass("TouchTransmitter") then
                Instance.new("TouchTransmitter", handle)
            end
        end

        -- Funci?n restaurar knife
        local function _resetKnife()
            local knife = _getKnife()
            local handle = knife and knife:FindFirstChild("Handle")
            if handle then
                handle.Size         = _KNIFE_DEFAULT_SIZE
                handle.Transparency = 0
                handle.Massless     = false
                handle.CanCollide   = true
            end
        end

        local _hbOriginalSizes = {}   -- [player] = Vector3 tama?o original
        -- Loop de mantenimiento del reach (el juego resetea el handle cada frame)
        local function _startReachLoop()
            if _reachConn then pcall(function() _reachConn:Disconnect() end) end
            local _reachT  = 0
            local _hrpT    = 0   -- contador separado para el chequeo de HRPs (~2Hz)
            _reachConn = _safeConnect(RunService.Heartbeat, function()
                _reachT = _reachT + 1; if _reachT < 4 then return end; _reachT = 0  -- ~15Hz (reducido de 30Hz para evitar lag con todos los toggles activos)
                if not _reachEnabled then return end
                if _G._visualRoundOver then return end
                -- Mantener knife reach
                local knife = _cachedKnife
                if knife and knife.Parent then
                    pcall(_applyReach, knife)
                end
                -- ~2Hz: verificar que todos los jugadores siguen expandidos
                -- Cubre casos donde el servidor restablece el HRP sin CharacterAdded
                _hrpT = _hrpT + 1
                if _hrpT < 15 then return end
                _hrpT = 0
                for _, p in ipairs(_cachedPlayers) do
                    if p ~= LocalPlayer then
                        local char = p.Character
                        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            local curSize = hrp.Size
                            -- Si el HRP volvi? a su tama?o original (o no fue expandido a?n), re-expandir
                            local orig = _hbOriginalSizes[p]
                            local targetSize = _reachSize
                            if not orig or curSize.X < targetSize - 0.5 then
                                pcall(_saveAndExpandHRP, p)
                            end
                        end
                    end
                end
            end)
        end

        local function _stopReachLoop()
            if _reachConn then pcall(function() _reachConn:Disconnect() end); _reachConn = nil end
        end

        -- -- AUTO-RESTORE: restaurar HRP original en pantalla negra o reset ---
        -- Guarda el tama?o original del HRP de cada jugador antes de expandirlo

        local function _saveAndExpandHRP(player)
            if player == LocalPlayer then return end
            local char = player.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            -- Guardar solo si aun no tenemos el original
            if not _hbOriginalSizes[player] then
                _hbOriginalSizes[player] = hrp.Size
            end
            if _reachEnabled and _reachSize > 0 then
                pcall(function()
                    hrp.Size = Vector3.new(_reachSize, _reachSize, _reachSize)
                    hrp.Transparency = 1
                    hrp.CanCollide = false
                end)
            end
        end

        local function _restoreHRP(player)
            local char = player and player.Character
            if not char then
                _hbOriginalSizes[player] = nil
                return
            end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp and _hbOriginalSizes[player] then
                pcall(function()
                    hrp.Size = _hbOriginalSizes[player]
                    hrp.Transparency = 0
                    hrp.CanCollide = true
                end)
            end
            _hbOriginalSizes[player] = nil
        end

        local function _restoreAllHRPs()
            for _, p in ipairs(_cachedPlayers) do
                _restoreHRP(p)
            end
        end

        -- -- AUTO-RESTORE: pantalla negra + reset de personaje ---------------
        -- Usa RoundEnd / RoundStart de RS en lugar de Lighting.Brightness
        -- (MM2 no siempre baja Brightness al negro; usa ColorCorrection/BlurEffect)
        local _blackScreenConn  = nil
        local _roundStartConn   = nil
        local _hbPlayerAddedConn2 = nil  -- para capturar jugadores que entren mid-round

        local function _reexpandAll()
            -- Re-expandir todos los jugadores activos cuando la ronda reanuda
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then
                    _hbOriginalSizes[p] = nil  -- forzar re-guardado del tama?o fresco
                    _saveAndExpandHRP(p)
                    if _reachEnabled then _createBoxForPlayer(p) end
                end
            end
        end

        local function _startBlackScreenDetector()
            -- Desconectar conns anteriores
            if _blackScreenConn then pcall(function() _blackScreenConn:Disconnect() end); _blackScreenConn = nil end
            if _roundStartConn  then pcall(function() _roundStartConn:Disconnect()  end); _roundStartConn  = nil end

            -- RoundEnd -> pantalla negra: restaurar todos los HRPs inmediatamente
            task.spawn(function()
                local ok, reEv = pcall(function()
                    return game:GetService("ReplicatedStorage")
                        :WaitForChild("Remotes", 10)
                        :WaitForChild("Gameplay", 10)
                        :WaitForChild("RoundEnd", 10)
                end)
                if not ok or not reEv then return end
                _blackScreenConn = reEv.OnClientEvent:Connect(function()
                    if not _reachEnabled then return end
                    _restoreAllHRPs()
                end)
            end)

            -- RoundStart -> pantalla vuelve: re-expandir todos
            task.spawn(function()
                local ok2, rsEv = pcall(function()
                    return game:GetService("ReplicatedStorage")
                        :WaitForChild("Remotes", 10)
                        :WaitForChild("Gameplay", 10)
                        :WaitForChild("RoundStart", 10)
                end)
                if not ok2 or not rsEv then return end
                _roundStartConn = rsEv.OnClientEvent:Connect(function()
                    if not _reachEnabled then return end
                    -- Dar un frame para que los personajes est?n listos
                    task.wait(0.3)
                    if _reachEnabled then _reexpandAll() end
                end)
            end)

            -- Jugadores que entren DESPU?S de activar el hitbox tambi?n reciben expansi?n
            if not _hbPlayerAddedConn2 then
                _hbPlayerAddedConn2 = Players.PlayerAdded:Connect(function(p)
                    if not _reachEnabled then return end
                    p.CharacterAdded:Connect(function()
                        task.wait(0.25)
                        if _reachEnabled then
                            _hbOriginalSizes[p] = nil
                            _saveAndExpandHRP(p)
                            _createBoxForPlayer(p)
                        end
                    end)
                end)
            end
        end

        -- Hook CharacterAdded de cada jugador para restaurar y re-expandir tras reset
        local _hbResetConns = {}
        local function _hookPlayerReset(player)
            if _hbResetConns[player] then
                pcall(function() _hbResetConns[player]:Disconnect() end)
            end
            _hbResetConns[player] = player.CharacterAdded:Connect(function()
                -- El jugador se reseteo: limpiar tama?o cacheado y re-expandir
                _hbOriginalSizes[player] = nil
                task.wait(0.25)
                if _reachEnabled then
                    _saveAndExpandHRP(player)
                    task.spawn(function()
                        task.wait(0.1)
                        if _reachEnabled then _createBoxForPlayer(player) end
                    end)
                end
            end)
        end

        local function _startResetDetectors()
            -- Hookear CharacterAdded de todos los jugadores actuales
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then _hookPlayerReset(p) end
            end
            -- Hookear jugadores que entren despu?s
            _startBlackScreenDetector()
        end

        local function _stopResetDetectors()
            for p, c in pairs(_hbResetConns) do
                pcall(function() c:Disconnect() end)
                _hbResetConns[p] = nil
            end
            if _blackScreenConn then pcall(function() _blackScreenConn:Disconnect() end); _blackScreenConn = nil end
            if _roundStartConn  then pcall(function() _roundStartConn:Disconnect()  end); _roundStartConn  = nil end
            if _hbPlayerAddedConn2 then pcall(function() _hbPlayerAddedConn2:Disconnect() end); _hbPlayerAddedConn2 = nil end
        end
        -- -- fin AUTO-RESTORE ------------------------------------------------

        -- -- UI ---------------------------------------------------------------
        _killSheriffSection = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, " KNIFE HITBOX") or Instance.new("Frame")

        -- -- Hitbox Expander toggle ------------------------------------------
        CreateBorderedToggle(_killSheriffSection, "Hitbox Expander", function(en)
            _reachEnabled = en
            if en then
                -- 0. Restaurar HRPs residuales de ejecuciones anteriores antes de re-expandir
                -- (evita jugadores deformados si el hub se re-ejecuto sin apagar el toggle)
                _restoreAllHRPs()
                -- 1. Aplicar reach al knife
                local knife = _getKnife()
                if knife then _applyReach(knife) end
                _startReachLoop()
                -- 2. Expandir HRP de todos los jugadores actuales (usando _cachedPlayers)
                for _, p in ipairs(_cachedPlayers) do
                    if p ~= LocalPlayer then _saveAndExpandHRP(p) end
                end
                -- 3. Mostrar SelectionBox en todos los jugadores
                _startHitboxVisuals()
                -- 4. Activar detectores de pantalla negra y reset
                _startResetDetectors()
                CreateCustomNotification("HITBOX", "Hitbox Expander ON (" .. _reachSize .. " studs)", 2)
            else
                -- 1. Detener reach
                _stopReachLoop()
                _resetKnife()
                -- 2. Restaurar HRP original de todos los jugadores
                _restoreAllHRPs()
                -- 3. Quitar SelectionBoxes y detectores
                _stopHitboxVisuals()
                _stopResetDetectors()
                CreateCustomNotification("HITBOX", "Hitbox Expander OFF", 2)
            end
        end, false)

