            _hbSizeFill.BackgroundColor3 = ThemeColors.Primary
            _hbSizeFill.BorderSizePixel = 0
            _hbSizeFill.ZIndex = 13
            Instance.new("UICorner", _hbSizeFill).CornerRadius = UDim.new(1, 0)

            local _hbSizeThumb = Instance.new("Frame", _hbSizeTrack)
            _hbSizeThumb.Size = UDim2.new(0, 14, 0, 14)
            _hbSizeThumb.AnchorPoint = Vector2.new(0.5, 0.5)
            _hbSizeThumb.Position = UDim2.new(0, 0, 0.5, 0)
            _hbSizeThumb.BackgroundColor3 = ThemeColors.Accent
            _hbSizeThumb.BorderSizePixel = 0
            _hbSizeThumb.ZIndex = 14
            Instance.new("UICorner", _hbSizeThumb).CornerRadius = UDim.new(1, 0)

            local _hbSizeDragging = false
            local function _hbSizeSetVal(v)
                v = math.clamp(math.floor(v * 10 + 0.5) / 10, 0, 15)
                _reachSize = v
                _G._sliderVals[_hbSizeKey] = v
                _hbSizeValLbl.Text = string.format("%.2f", v)
                local pct = v / 15
                _hbSizeFill.Size = UDim2.new(pct, 0, 1, 0)
                _hbSizeThumb.Position = UDim2.new(pct, 0, 0.5, 0)
                -- Actualizar tama?o del HRP en todos los jugadores y el reach del knife
                if _reachEnabled then
                    local knife = _getKnife()
                    if knife then pcall(_applyReach, knife) end
                    for _, p in ipairs(_cachedPlayers) do
                        if p ~= LocalPlayer and p.Character then
                            local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                            if hrp then
                                pcall(function()
                                    hrp.Size = Vector3.new(v, v, v)
                                    hrp.Transparency = 1
                                    hrp.CanCollide = false
                                end)
                            end
                        end
                    end
                end
            end

            _hbSizeTrack.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _hbSizeDragging = true
                    local absPos  = _hbSizeTrack.AbsolutePosition.X
                    local absSize = _hbSizeTrack.AbsoluteSize.X
                    local pct = math.clamp((inp.Position.X - absPos) / absSize, 0, 1)
                    _hbSizeSetVal(pct * 15)
                end
            end)
            _hbSizeTrack.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _hbSizeDragging = false
                end
            end)
            UserInputService.InputChanged:Connect(function(inp)
                if not _hbSizeDragging then return end
                if inp.UserInputType ~= Enum.UserInputType.MouseMovement
                and inp.UserInputType ~= Enum.UserInputType.Touch then return end
                local absPos  = _hbSizeTrack.AbsolutePosition.X
                local absSize = _hbSizeTrack.AbsoluteSize.X
                local pct = math.clamp((inp.Position.X - absPos) / absSize, 0, 1)
                _hbSizeSetVal(pct * 15)
            end)
            -- FIX: restaurar posicion visual del thumb al reconstruir el tab
            task.defer(function() _hbSizeSetVal(_reachSize) end)
        end

