                local absSize = _hbSurfTrack.AbsoluteSize.X
                local pct = math.clamp((inp.Position.X - absPos) / absSize, 0, 1)
                _hbSurfSetVal(pct)
            end)
            -- FIX: restaurar posicion visual del thumb al reconstruir el tab
            task.defer(function() _hbSurfSetVal(_hbSurfVal) end)
        end

        -- Botn Reparar Cuchillo
        local repairBtn = Instance.new("TextButton", _killSheriffSection)
        repairBtn.Size = UDim2.new(1, -10, 0, 32)
        repairBtn.BackgroundColor3 = ThemeColors.Background
        repairBtn.BackgroundTransparency = 0.15
        repairBtn.BorderSizePixel = 0
        repairBtn.Text = " Reparar Cuchillo    si no hace dao"
        repairBtn.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        repairBtn.TextSize = 12
        repairBtn.TextColor3 = ThemeColors.TextPrimary
        repairBtn.AutoButtonColor = false
        repairBtn.ZIndex = 13
        Instance.new("UICorner", repairBtn).CornerRadius = UDim.new(0, 8)
        local repStroke = Instance.new("UIStroke", repairBtn)
        repStroke.Color = ThemeColors.Primary
        repStroke.Thickness = 1.5
        local repBgGrad = Instance.new("UIGradient", repairBtn)
        repBgGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,   ThemeColors.Aurora1),
            ColorSequenceKeypoint.new(0.5, ThemeColors.Background),
            ColorSequenceKeypoint.new(1,   ThemeColors.Aurora1),
        })
        repBgGrad.Rotation = 0

        repairBtn.Activated:Connect(function()
            pcall(function()
                local knife = _getKnife()
                local handle = knife and knife:FindFirstChild("Handle")
                if handle then
                    handle.Size = _KNIFE_DEFAULT_SIZE
                    _w(0.1)
                    if _reachEnabled then
                        handle.Size = Vector3.new(_reachSize, _reachSize, _reachSize)
                    end
                end
            end)
            CreateCustomNotification("KNIFE HITBOX", "Cuchillo reparado", 1.5)
        end)

    end
    -- ======================================================================
    -- SECCIN: DUAL WEAPON  Dual Knife y Dual Gun
    -- ======================================================================
    do
        local _dualSection = (CreateBorderedSection and rightColumn) and CreateBorderedSection(rightColumn, "  DUAL WEAPON") or Instance.new("Frame")

        -- -- NOMBRES EXACTOS de tools en MM2 (fix: antes usaba string.find parcial
        -- que clonaba cualquier handle de cualquier tool con nombre similar) --------
        local _dualKnifeNames = { Knife=true, VIPKnife=true, GodKnife=true }
        local _dualGunNames   = { Gun=true, SheriffGun=true, HeroGun=true, GunDrop=true }

        -- _dualKnifeKeywords/_dualGunKeywords se reusan como identificadores de modo
        local _dualKnifeKeywords = _dualKnifeNames
        local _dualGunKeywords   = _dualGunNames

        local function _dualMatchKeywords(tool, nameSet)
            if not tool then return false end
            -- Comparacion de nombre EXACTO ? no matchea nada con string.find parcial
            return nameSet[tool.Name] == true
        end

        -- -- ESTADO GLOBAL DUAL --------------------------------------------
        -- FIX: limpiar conexiones viejas del estado anterior antes de reusar el objeto.
        -- Si el tab se reconstruye y el estado ya existe, las conexiones apuntan a closures
        -- muertos que nunca disparan -> el toggle no funciona hasta re-activarlo manualmente.
        local function _dualCleanState(st)
            if not st then return end
            if st.steppedConn then pcall(function() st.steppedConn:Disconnect() end); st.steppedConn = nil end
            if st.renderConn  then pcall(function() st.renderConn:Disconnect()  end); st.renderConn  = nil end
            if st.inputConn   then pcall(function() st.inputConn:Disconnect()   end); st.inputConn   = nil end
        end
        if _G._dualKnifeState then _dualCleanState(_G._dualKnifeState) end
        if _G._dualGunState   then _dualCleanState(_G._dualGunState)   end
        _G._dualKnifeState = _G._dualKnifeState or {}
        _G._dualGunState   = _G._dualGunState   or {}
        -- Asegurar campos requeridos sin pisar enabled (puede venir de sesi?n anterior)
        local function _dualEnsureFields(st)
            if st.isNextSlash  == nil then st.isNextSlash  = true  end
            if st.isAttacking  == nil then st.isAttacking  = false end
            if st._lastStab    == nil then st._lastStab    = -999  end
            if st._lastThrow   == nil then st._lastThrow   = -999  end
        end
        _dualEnsureFields(_G._dualKnifeState)
        _dualEnsureFields(_G._dualGunState)

        -- FIX AUTO SAFE: sincronizar .enabled desde _toggleStates guardado en disco.
        -- Sin esto, aunque _toggleStates["Dual Knife"] sea true tras cargar config,
        -- el task.defer de reconstrucci?n no re-activa porque ks.enabled sigue nil.
        do
            local _ts = _G._toggleStates or {}
            if _ts["Dual Knife"] == true then
                _G._dualKnifeState.enabled = true
                _G._dualKnifeEnabled       = true
            end
            if _ts["Dual Gun"] == true then
                _G._dualGunState.enabled = true
            end
        end

        -- -- LGICA COMPARTIDA: pose brazo + clon handle -------------------
        local function _dualStartArm(state, keywordList)
            -- FIX: desconectar conexiones viejas antes de crear nuevas.
            -- Si _dualStartArm se llama sin haber pasado por _dualStopArm primero
            -- (ej. re-init tras respawn), se acumulaban conexiones zombie.
            if state.steppedConn then pcall(function() state.steppedConn:Disconnect() end); state.steppedConn = nil end
            if state.renderConn  then pcall(function() state.renderConn:Disconnect()  end); state.renderConn  = nil end
            if state.inputConn   then pcall(function() state.inputConn:Disconnect()   end); state.inputConn   = nil end
            -- Stepped: levanta el brazo izquierdo
            state.steppedConn = _safeConnect(RunService.Stepped, function()
                if not state.enabled then return end
                local char = LocalPlayer.Character
                if not char then return end
                -- FIX: buscar la tool que matchea los keywords del modo activo
                local tool = nil
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA("Tool") and _dualMatchKeywords(t, keywordList) then
                        tool = t; break
                    end
                end
                if not tool then return end
                local lUA       = char:FindFirstChild("LeftUpperArm")
                local lShoulder = lUA and lUA:FindFirstChild("LeftShoulder")
                local lLA       = char:FindFirstChild("LeftLowerArm")
                local lElbow    = lLA and lLA:FindFirstChild("LeftElbow")
                local lHandPart = char:FindFirstChild("LeftHand")
                local lWrist    = lHandPart and lHandPart:FindFirstChild("LeftWrist")
                if lShoulder then
                    lShoulder.Transform = CFrame.Angles(math.rad(90), 0, 0)
                    if lElbow then lElbow.Transform = CFrame.new() end
                    if lWrist then lWrist.Transform = CFrame.new() end
                    return
                end
                local torso   = char:FindFirstChild("Torso")
                local lJointR6 = torso and torso:FindFirstChild("Left Shoulder")
                if lJointR6 then lJointR6.Transform = CFrame.Angles(math.rad(90), 0, 0) end
            end)

            -- RenderStepped: clona handle y lo weldea a la mano izquierda
            local _dualRST = 0
            state.renderConn = _safeConnect(RunService.RenderStepped, function(dt)
                _dualRST = _dualRST + dt; if _dualRST < 0.033 then return end; _dualRST = 0
                local char = LocalPlayer.Character
                if not char then return end
                -- FIX: buscar la tool que matchea los keywords del modo activo,
                -- NO la primera tool gen?rica (evita clonar la Gun cuando Dual Knife est? activo)
                local tool = nil
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA("Tool") and _dualMatchKeywords(t, keywordList) then
                        tool = t; break
                    end
                end
                if not state.enabled or not tool then
                    for _, obj in pairs(char:GetChildren()) do
                        if obj.Name == "DK_Clone" then obj:Destroy() end
                    end
                    return
                end
                -- Buscar el handle real: SOLO "Handle" exacto (BasePart)
                -- FIX: eliminar fallback a BasePart generico que clonaba cualquier parte
                local handle = nil
                do
                    local h = tool:FindFirstChild("Handle")
                    if h and h:IsA("BasePart") then
                        handle = h
                    end
                    -- Si no hay "Handle" nombrado exactamente, no clonar nada.
                    -- Evita clonar partes de modelos, scripts u otros objetos del tool.
                end
                local rHand  = char:FindFirstChild("RightHand") or char:FindFirstChild("Right Arm")
                local lHand  = char:FindFirstChild("LeftHand")  or char:FindFirstChild("Left Arm")
                local grip   = rHand and rHand:FindFirstChild("RightGrip")
                if not (handle and grip and lHand) then return end
                -- Verificar que el handle pertenece a la tool correcta (no a otra tool del char)
                if handle.Parent ~= tool then return end
                local existing = char:FindFirstChild("DK_Clone")
                if existing then
                    local w = existing:FindFirstChild("MirrorWeld")
                    if w then
                        -- FIX VISUAL: usar el mismo CFrame que la gun original para que el clon
                        -- tenga apariencia identica (sin espejo roto que la parte a la mitad)
                        w.C0 = grip.C0
                        w.C1 = grip.C1
                    end
                    -- FIX DUAL INVISIBLE: mantener el clon visible aunque el handle cambie de transparencia
                    pcall(function() existing.Transparency = 0; existing.LocalTransparencyModifier = 0 end)
                    for _, desc in ipairs(existing:GetDescendants()) do
                        if desc:IsA("BasePart") then
                            pcall(function() desc.Transparency = 0; desc.LocalTransparencyModifier = 0 end)
                        end
                    end
                    return
                end
                handle.Archivable = true
                for _, d in ipairs(handle:GetDescendants()) do
                    pcall(function() d.Archivable = true end)
                end
                local clon = handle:Clone()
                clon.Name       = "DK_Clone"
                clon.CanCollide = false
                clon.Massless   = true
                clon.Anchored   = false
                -- FIX DUAL INVISIBLE: forzar visibilidad del clon sin importar la
                -- transparencia del handle original (puede estar en 1 por SA flash u otros sistemas)
                clon.Transparency = 0
                pcall(function() clon.LocalTransparencyModifier = 0 end)
                -- Limpiar hijos que no sean visuales (solo mantener mesh y partes)
                for _, child in pairs(clon:GetChildren()) do
                    if not child:IsA("BasePart") and not child:IsA("SpecialMesh") and not child:IsA("MeshPart") then
                        child:Destroy()
                    end
                end
                -- Asegurar que sub-partes del clon tambien sean visibles
                for _, desc in ipairs(clon:GetDescendants()) do
                    if desc:IsA("BasePart") then
                        pcall(function() desc.Transparency = 0; desc.LocalTransparencyModifier = 0 end)
                    end
                end
                clon.Parent = char
                local weld = Instance.new("Weld", clon)
                weld.Name  = "MirrorWeld"
                weld.Part0 = lHand
                weld.Part1 = clon
                -- FIX VISUAL: usar el mismo CFrame que la gun original para que el clon
                -- tenga apariencia identica (sin espejo roto que la parte a la mitad)
                weld.C0 = grip.C0
                weld.C1 = grip.C1

                -- HOOK PREMIUM SKIN: solo aplicar skin al clon si es Dual Gun (no Dual Knife)
                -- FIX: antes aplicaba siempre la skin de gun incluso al clon del knife
                local isDualGun = (keywordList == _dualGunKeywords)
                if isDualGun then
                    pcall(function()
                        local sc = _G._skinChangerState
                        if sc and sc.enabled and sc.mode == "gun" then
                            local _skinList = _G._SC_GUN_SKINS or {}
                            local _cSkin = _skinList[sc.skinIdx] or _skinList[1]
                            for _, obj in pairs(clon:GetDescendants()) do
                                if obj:IsA("SpecialMesh") then
                                    pcall(function()
                                        obj.MeshId    = _cSkin.meshId
                                        obj.TextureId = _cSkin.texId
                                        obj.Scale     = _cSkin.scale
                                    end)
                                elseif obj:IsA("MeshPart") then
                                    pcall(function() obj.TextureID = _cSkin.texId end)
                                end
                            end
                        end
                    end)
                end
            end)

            -- InputBegan: sistema completo de inputs para Dual Knife/Gun
            -- Independiente de Knife SA  funciona siempre que el toggle est ON
            state.inputConn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
                if gameProcessed then return end
                if not state.enabled then return end
                local char = LocalPlayer.Character
                if not char then return end
                -- FIX: buscar la tool que matchea los keywords del modo activo
                local tool = nil
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA("Tool") and _dualMatchKeywords(t, keywordList) then
                        tool = t; break
                    end
                end
                if not tool then return end

                local isDualKnife = (keywordList == _dualKnifeKeywords)
                local events = tool:FindFirstChild("Events")
                local knifeThrown  = events and events:FindFirstChild("KnifeThrown")
                local knifeStabbed = events and events:FindFirstChild("KnifeStabbed")

                -- -- LMB/Touch = SLASH cuando SA est OFF (SA lo maneja si est ON) --
                -- FIX BUG #2/#3 MOBILE: Touch is mapped ONLY to the slash/stab path.
                -- The RMB/DualStab path below must NOT claim Touch, or a single mobile
                -- tap would fall into both branches causing SA throw instead of slash.
                local _isTouchInput = (input.UserInputType == Enum.UserInputType.Touch)
                if isDualKnife and (input.UserInputType == Enum.UserInputType.MouseButton1 or _isTouchInput)
                    and not (KnifeSAState and KnifeSAState.enabled) then
                    if state.isAttacking then return end
                    local now = os.clock()
                    if now - (state._lastStab or -999) < 0.85 then return end
                    state.isAttacking = true
                    state._lastStab = now
                    _G._dualSlashToggle = not _G._dualSlashToggle
                    -- Usar _dkPlaySlot (definida despues del toggle, accesible via upvalue del closure externo)
                    _sp(function()
                        if _dkPlaySlot then
                            _dkPlaySlot(_G._dualSlashToggle and "slotA" or "slotB", 1.0)
                        end
                    end)
                    local ev = tool:FindFirstChild("Events")
                    local ks = ev and ev:FindFirstChild("KnifeStabbed")
                    if ks then pcall(function() ks:FireServer() end) end
                    _dl(0.85, function() state.isAttacking = false end)

                -- -- RMB only = DUALSTAB ANIMATION (Dual Knife ON) --
                -- FIX BUG #3: Touch is intentionally excluded here to prevent mobile
                -- tap from triggering DualStab instead of the slash path above.
                elseif isDualKnife and input.UserInputType == Enum.UserInputType.MouseButton2 then
                    local now = os.clock()
                    if now - (state._lastThrow or -999) < 0.8 then return end
                    state._lastThrow = now
                    -- Reproducir animacion DualStab
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    local animator = hum and hum:FindFirstChildOfClass("Animator")
                    if animator then
                        local animObj = Instance.new("Animation")
                        animObj.AnimationId = "rbxassetid://2470501967"
                        local ok, track = pcall(function() return animator:LoadAnimation(animObj) end)
                        if ok and track then
                            pcall(function() track:Play(0.05) end)
                        end
                    end
                    -- Activar stab en el servidor
                    local ev = tool:FindFirstChild("Events")
                    local ks = ev and ev:FindFirstChild("KnifeStabbed")
                    if ks then pcall(function() ks:FireServer() end) end
                    _dl(0.8, function() state.isAttacking = false end)

                -- -- LMB/Touch = THROW (Dual Gun mode, no Dual Knife) ----------
                -- FIX BUG #3: Touch here is safe because this branch only runs when
                -- isDualKnife==false (Dual Gun mode). The slash/stab branch above only
                -- runs when isDualKnife==true, so there is no overlap.
                elseif not isDualKnife and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
                    -- Dual Gun: LMB lanza
                    -- (solo si Knife SA no est activo  si SA est ON, l maneja el LMB)
                    if KnifeSAState and KnifeSAState.enabled then return end
                    if not knifeThrown then return end
                    local now = os.clock()
                    if now - (state._lastThrow or -999) < 1.0 then return end
                    state._lastThrow = now
                    local myHRP = char:FindFirstChild("HumanoidRootPart")
                    local cam = workspace.CurrentCamera
                    local targetCF = myHRP and CFrame.new(myHRP.Position, myHRP.Position + cam.CFrame.LookVector * 100)
                        or cam.CFrame
                    pcall(function() knifeThrown:FireServer(targetCF, targetCF) end)
                end
            end)
        end

        local function _dualStopArm(state)
            state.enabled = false
            if state.steppedConn then pcall(function() state.steppedConn:Disconnect() end); state.steppedConn = nil end
            if state.renderConn  then pcall(function() state.renderConn:Disconnect()  end); state.renderConn  = nil end
            if state.inputConn   then pcall(function() state.inputConn:Disconnect()   end); state.inputConn   = nil end
            -- Limpiar clon si existe
            local char = LocalPlayer.Character
            if char then
                for _, obj in pairs(char:GetChildren()) do
                    if obj.Name == "DK_Clone" then pcall(function() obj:Destroy() end) end
                end
            end
        end

        -- ==============================================================
        -- SISTEMA DE ANIMACIONES NATIVAS  Dual Knife
        -- Carga las anims directamente del knife equipado (sin IDs externos
        -- que pueden ser eliminados). Mata la slash nativa en el mismo frame
        -- del input para que el override tome efecto.
        -- ==============================================================
        local _dkAnimTracks  = {}   -- { slotA = track, slotB = track }
        local _dkToggle      = false

        local function _dkGetAnimator()
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            return hum and hum:FindFirstChildOfClass("Animator")
        end

        -- IDs de animaciones de slash/stab conocidos (fallback cuando el tool no tiene anims propias)
        local _DK_FALLBACK_IDS = {
            "10921264784",  -- Slash R15 MM2
            "3457535532",   -- Stab alternativo
            "507768375",    -- Slash Roblox default
            "522635514",    -- Slash alternativo
        }

        local function _dkLoadAnimFromId(animator, id)
            local ok, t = pcall(function()
                local a = Instance.new("Animation")
                a.AnimationId = "rbxassetid://" .. id
                local tr = animator:LoadAnimation(a)
                tr.Priority = Enum.AnimationPriority.Action4
                return tr
            end)
            return ok and t or nil
        end

        local function _dkPreloadTracks()
            local char = LocalPlayer.Character
            if not char then return end
            local tool = nil
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") and _dualMatchKeywords(t, _dualKnifeKeywords) then
                    tool = t; break
                end
            end
            if not tool then return end
            local animator = _dkGetAnimator()
            if not animator then return end

            _dkAnimTracks = {}

            -- 1. Recopilar todas las anims del knife
            local allAnims = {}
            for _, v in ipairs(tool:GetDescendants()) do
                if v:IsA("Animation") then table.insert(allAnims, v) end
            end

            -- 2. Filtrar las de slash/stab
            local slashAnims = {}
            for _, a in ipairs(allAnims) do
                local n = a.Name:lower()
                if n:find("slash") or n:find("stab") or n:find("hit") or n:find("animation1") then
                    table.insert(slashAnims, a)
                end
            end
            if #slashAnims == 0 then slashAnims = allAnims end

            -- 3. Intentar cargar desde el tool
            if slashAnims[1] then
                local ok, t = pcall(function() return animator:LoadAnimation(slashAnims[1]) end)
                if ok and t then t.Priority = Enum.AnimationPriority.Action4; _dkAnimTracks.slotA = t end
            end
            local animB = slashAnims[2] or slashAnims[1]
            if animB then
                local ok, t = pcall(function() return animator:LoadAnimation(animB) end)
                if ok and t then t.Priority = Enum.AnimationPriority.Action4; _dkAnimTracks.slotB = t end
            end

            -- 4. FALLBACK: si el tool no tiene animaciones propias, usar IDs conocidos
            if not _dkAnimTracks.slotA then
                for i, id in ipairs(_DK_FALLBACK_IDS) do
                    local t = _dkLoadAnimFromId(animator, id)
                    if t then
                        if not _dkAnimTracks.slotA then
                            _dkAnimTracks.slotA = t
                        elseif not _dkAnimTracks.slotB then
                            _dkAnimTracks.slotB = t
                            break
                        end
                    end
                end
            end
            -- Si solo se cargo slotA, slotB es el mismo (alterna la misma anim)
            if _dkAnimTracks.slotA and not _dkAnimTracks.slotB then
                _dkAnimTracks.slotB = _dkAnimTracks.slotA
            end
        end

        -- Mata las anims nativas de slash que el juego reproduce (sin tocar las nuestras)
        local function _dkKillNativeSlash()
            local animator = _dkGetAnimator()
            if not animator then return end
            local ok, playing = pcall(function() return animator:GetPlayingAnimationTracks() end)
            if not ok or not playing then return end
            for _, t in ipairs(playing) do
                if t.Priority ~= Enum.AnimationPriority.Action4 then
                    local n = (t.Name or ""):lower()
                    if n:find("slash") or n:find("stab") or n:find("hit") or n:find("animation1") or n:find("attack") then
                        pcall(function() t:Stop(0) end)
                    end
                end
            end
        end

        local function _dkIsTrackValid(t)
            if not t then return false end
            local ok, _ = pcall(function() return t.IsPlaying end)
            return ok
        end

        local function _dkPlaySlot(slot, speed)
            speed = speed or 1.0
            -- FIX: matar nativa en el mismo frame del input (sin yield)
            _dkKillNativeSlash()

            local track = _dkAnimTracks[slot]
            -- Si el track no existe o ya no es v?lido (tras respawn), recargar
            if not _dkIsTrackValid(track) then
                _dkAnimTracks = {}
                _dkPreloadTracks()
                track = _dkAnimTracks[slot]
                if not _dkIsTrackValid(track) then return end
            end

            if track.IsPlaying then
                pcall(function() track:Stop(0) end)
                -- FIX: eliminado _w() ? introduc?a un yield que dejaba pasar la animaci?n nativa
                -- del servidor antes del Play. Stop(0) es instant?neo; no necesita espera.
            end
            -- Segunda pasada sin yield (atrapa lo que el servidor pudo disparar en este frame)
            _dkKillNativeSlash()

            pcall(function() track:Play(0.05); track:AdjustSpeed(speed) end)
        end

        local function _dkStopAll()
            for _, t in pairs(_dkAnimTracks) do
                pcall(function() if t.IsPlaying then t:Stop(0.08) end end)
            end
        end


        -- Helper: re-armar solo las conexiones de Dual Knife tras pick-up o respawn.
        -- FIX BUG 2: los BpConn/CharPickupConn llamaban _dualStartArm y luego dejaban
        -- inputConn=nil sin recrear el conn correcto (el que usa _dkPlaySlot/_dkToggle).
        -- Esta funcion centraliza el re-arm completo: pose+clon+inputConn+tracks.
        local function _dkRearm(st)
            if st.steppedConn then pcall(function() st.steppedConn:Disconnect() end); st.steppedConn = nil end
            if st.renderConn  then pcall(function() st.renderConn:Disconnect()  end); st.renderConn  = nil end
            if st.inputConn   then pcall(function() st.inputConn:Disconnect()   end); st.inputConn   = nil end
            _dkAnimTracks = {}
            _dualStartArm(st, _dualKnifeKeywords)
            -- Reemplazar el inputConn de _dualStartArm (logica vieja) por el correcto
            if st.inputConn then pcall(function() st.inputConn:Disconnect() end); st.inputConn = nil end
            _sp(_dkPreloadTracks)
            st.inputConn = UserInputService.InputBegan:Connect(function(input, gp)
                if gp then return end
                if not st.enabled then return end
                local char = LocalPlayer.Character
                if not char then return end
                local tool = nil
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA("Tool") and _dualMatchKeywords(t, _dualKnifeKeywords) then tool = t; break end
                end
                if not tool then return end
                local events       = tool:FindFirstChild("Events")
                local knifeStabbed = events and events:FindFirstChild("KnifeStabbed")
                local knifeThrown  = events and events:FindFirstChild("KnifeThrown")
                if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch)
                    and not (KnifeSAState and KnifeSAState.enabled) then
                    if st.isAttacking then return end
                    local now = os.clock()
                    if now - (st._lastStab or -999) < 0.85 then return end
                    st.isAttacking = true
                    st._lastStab   = now
                    _dkToggle = not _dkToggle
                    _dkPlaySlot(_dkToggle and "slotA" or "slotB", 1.0)
                    if knifeStabbed then pcall(function() knifeStabbed:FireServer() end) end
                    _dl(0.85, function() st.isAttacking = false end)
                elseif input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.Touch then
                    if not knifeThrown then return end
                    local now = os.clock()
                    if now - (st._lastThrow or -999) < 1.0 then return end
                    st._lastThrow = now
                    _dkStopAll()
                    local myHRP = char:FindFirstChild("HumanoidRootPart")
                    local cam   = workspace.CurrentCamera
                    local targetCF = myHRP
                        and CFrame.new(myHRP.Position, myHRP.Position + cam.CFrame.LookVector * 100)
                        or cam.CFrame
                    pcall(function() knifeThrown:FireServer(targetCF, targetCF) end)
                end
            end)
        end

        -- -- TOGGLE: DUAL KNIFE --------------------------------------------
        CreatePremiumToggle(_dualSection, "Dual Knife", function(en)
            local state = _G._dualKnifeState
            if en then
                -- Desactivar Dual Gun si estaba activo (solo uno a la vez)
                if _G._dualGunState.enabled then
                    _dualStopArm(_G._dualGunState)
                    -- FIX: limpiar tambien los hooks de Dual Gun para que no re-activen el gun
                    if _G._dualGunBpConn then
                        pcall(function() _G._dualGunBpConn:Disconnect() end)
                        _G._dualGunBpConn = nil
                    end
                    if _G._dualGunCharPickupConn then
                        pcall(function() _G._dualGunCharPickupConn:Disconnect() end)
                        _G._dualGunCharPickupConn = nil
                    end
                    -- FIX: limpiar DK_Clone que pudo quedar del Dual Gun
                    local _chG = LocalPlayer.Character
                    if _chG then
                        for _, obj in pairs(_chG:GetChildren()) do
                            if obj.Name == "DK_Clone" then pcall(function() obj:Destroy() end) end
                        end
                    end
                end
                state.enabled        = true
                state.isAttacking    = false
                state._lastStab      = -999
                state._lastThrow     = -999
                _G._dualKnifeEnabled = true
                _dkToggle            = false
                _dkAnimTracks        = {}

                -- Pose del brazo + clon handle (igual que antes)
                _dualStartArm(state, _dualKnifeKeywords)

                -- Reemplazar el inputConn de _dualStartArm por el nuevo
                -- que usa animaciones nativas + killNativeSlash
                if state.inputConn then
                    pcall(function() state.inputConn:Disconnect() end)
                    state.inputConn = nil
                end

                _sp(_dkPreloadTracks)

                state.inputConn = UserInputService.InputBegan:Connect(function(input, gp)
                    if gp then return end
                    if not state.enabled then return end
                    local char = LocalPlayer.Character
                    if not char then return end
                    local tool = nil
                    for _, t in ipairs(char:GetChildren()) do
                        if t:IsA("Tool") and _dualMatchKeywords(t, _dualKnifeKeywords) then
                            tool = t; break
                        end
                    end
                    if not tool then return end

                    local events       = tool:FindFirstChild("Events")
                    local knifeStabbed = events and events:FindFirstChild("KnifeStabbed")
                    local knifeThrown  = events and events:FindFirstChild("KnifeThrown")

                    -- LMB/Touch -> slash alternado (solo si Knife SA est OFF)
                    if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch)
                        and not (KnifeSAState and KnifeSAState.enabled) then
                        if state.isAttacking then return end
                        local now = os.clock()
                        if now - (state._lastStab or -999) < 0.85 then return end
                        state.isAttacking = true
                        state._lastStab   = now
                        _dkToggle = not _dkToggle
                        -- Reproducir en este hilo (sin task.spawn) para que
                        -- _dkKillNativeSlash acte en el mismo frame del input
                        _dkPlaySlot(_dkToggle and "slotA" or "slotB", 1.0)
                        if knifeStabbed then pcall(function() knifeStabbed:FireServer() end) end
                        _dl(0.85, function() state.isAttacking = false end)

                    -- RMB/Touch -> throw
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.Touch then
                        if not knifeThrown then return end
                        local now = os.clock()
                        if now - (state._lastThrow or -999) < 1.0 then return end
                        state._lastThrow = now
                        _dkStopAll()
                        local myHRP = char:FindFirstChild("HumanoidRootPart")
                        local cam   = workspace.CurrentCamera
                        local targetCF = myHRP
                            and CFrame.new(myHRP.Position, myHRP.Position + cam.CFrame.LookVector * 100)
                            or cam.CFrame
                        pcall(function() knifeThrown:FireServer(targetCF, targetCF) end)
                    end
                end)

                -- FIX NUEVA RONDA DUAL KNIFE: hookear Backpack.ChildAdded para cuando el knife
                -- llega al inventario (pick-up desde suelo o inicio de ronda como Murderer).
                if _G._dualKnifeBpConn then
                    pcall(function() _G._dualKnifeBpConn:Disconnect() end)
                    _G._dualKnifeBpConn = nil
                end
                _G._dualKnifeBpConn = LocalPlayer.Backpack.ChildAdded:Connect(function(tool)
                    if not (state and state.enabled) then return end
                    if not tool:IsA("Tool") then return end
                    if _dualMatchKeywords(tool, _dualKnifeKeywords) then
                        task.wait(0.1)
                        -- FIX BUG 2: usar _dkRearm para recrear pose+clon+inputConn correcto
                        _dkRearm(state)
                    end
                end)

                -- FIX NUEVA RONDA DUAL KNIFE: hookear Character.ChildAdded para detectar cuando
                -- el jugador EQUIPA el knife (Backpack->Character). Ese evento NO dispara
                -- Backpack.ChildAdded, por eso el clon no aparecia al equipar el knife en rondas
                -- siguientes sin desactivar y reactivar el toggle manualmente.
                if _G._dualKnifeCharPickupConn then
                    pcall(function() _G._dualKnifeCharPickupConn:Disconnect() end)
                    _G._dualKnifeCharPickupConn = nil
                end
                local _dkChar = LocalPlayer.Character
                if _dkChar then
                    _G._dualKnifeCharPickupConn = _dkChar.ChildAdded:Connect(function(tool)
                        if not (state and state.enabled) then return end
                        if not tool:IsA("Tool") then return end
                        if _dualMatchKeywords(tool, _dualKnifeKeywords) then
                            task.wait(0.1)
                            -- FIX BUG 2: usar _dkRearm para recrear pose+clon+inputConn correcto
                            _dkRearm(state)
                        end
                    end)
                end

                CreateCustomNotification("DUAL KNIFE", "OK Activado  LMB: slash  |  RMB: throw", 3)
            else
                _G._dualKnifeEnabled = false
                _dkStopAll()
                _dualStopArm(state)
                -- Limpiar los hooks de deteccion de equip
                if _G._dualKnifeBpConn then
                    pcall(function() _G._dualKnifeBpConn:Disconnect() end)
                    _G._dualKnifeBpConn = nil
                end
                if _G._dualKnifeCharPickupConn then
                    pcall(function() _G._dualKnifeCharPickupConn:Disconnect() end)
                    _G._dualKnifeCharPickupConn = nil
                end
                -- FIX: limpiar tambien el DK_Clone del char si quedo colgado
                local _ch = LocalPlayer.Character
                if _ch then
                    for _, obj in pairs(_ch:GetChildren()) do
                        if obj.Name == "DK_Clone" then pcall(function() obj:Destroy() end) end
                    end
                end
                CreateCustomNotification("DUAL KNIFE", "X Desactivado", 2)
            end
        end, false)

        -- -- TOGGLE: DUAL GUN ----------------------------------------------
        CreatePremiumToggle(_dualSection, "Dual Gun", function(en)
            local state = _G._dualGunState
            if en then
                -- Desactivar Dual Knife si estaba activo (solo uno a la vez)
                if _G._dualKnifeState.enabled then
                    _G._dualKnifeEnabled = false  -- FIX: limpiar flag global que _dualStopArm no toca
                    _dkStopAll()
                    _dualStopArm(_G._dualKnifeState)
                    -- FIX: limpiar hooks de Dual Knife para que no re-activen el knife
                    if _G._dualKnifeBpConn then
                        pcall(function() _G._dualKnifeBpConn:Disconnect() end)
                        _G._dualKnifeBpConn = nil
                    end
                    if _G._dualKnifeCharPickupConn then
                        pcall(function() _G._dualKnifeCharPickupConn:Disconnect() end)
                        _G._dualKnifeCharPickupConn = nil
                    end
                    -- FIX: limpiar DK_Clone que pudo quedar del Dual Knife
                    local _chK = LocalPlayer.Character
                    if _chK then
                        for _, obj in pairs(_chK:GetChildren()) do
                            if obj.Name == "DK_Clone" then pcall(function() obj:Destroy() end) end
                        end
                    end
                end
                state.enabled = true
                _dualStartArm(state, _dualGunKeywords)

                -- FIX: si el jugador no tiene la gun todavia (es Murderer u Observer),
                -- escuchar el Backpack para re-armar cuando la gun llegue en esta vida.
                if _G._dualGunBpConn then
                    pcall(function() _G._dualGunBpConn:Disconnect() end)
                    _G._dualGunBpConn = nil
                end
                _G._dualGunBpConn = LocalPlayer.Backpack.ChildAdded:Connect(function(tool)
                    if not (state and state.enabled) then return end
                    if not tool:IsA("Tool") then return end
                    if _dualGunKeywords[tool.Name] then
                        task.wait(0.1)
                        if state.steppedConn then pcall(function() state.steppedConn:Disconnect() end); state.steppedConn = nil end
                        if state.renderConn  then pcall(function() state.renderConn:Disconnect()  end); state.renderConn  = nil end
                        if state.inputConn   then pcall(function() state.inputConn:Disconnect()   end); state.inputConn   = nil end
                        _dualStartArm(state, _dualGunKeywords)
                    end
                end)

                -- FIX: tambien escuchar Character.ChildAdded por si la gun llega
                -- directamente equipada al char (no pasa por Backpack en MM2).
                if _G._dualGunCharPickupConn then
                    pcall(function() _G._dualGunCharPickupConn:Disconnect() end)
                    _G._dualGunCharPickupConn = nil
                end
                local _dgChar = LocalPlayer.Character
                if _dgChar then
                    _G._dualGunCharPickupConn = _dgChar.ChildAdded:Connect(function(tool)
                        if not (state and state.enabled) then return end
                        if not tool:IsA("Tool") then return end
                        if _dualGunKeywords[tool.Name] then
                            task.wait(0.1)
                            if state.steppedConn then pcall(function() state.steppedConn:Disconnect() end); state.steppedConn = nil end
                            if state.renderConn  then pcall(function() state.renderConn:Disconnect()  end); state.renderConn  = nil end
                            if state.inputConn   then pcall(function() state.inputConn:Disconnect()   end); state.inputConn   = nil end
                            _dualStartArm(state, _dualGunKeywords)
                        end
                    end)
                end

                CreateCustomNotification("DUAL GUN", "OK Activado  Click Derecho para atacar", 3)
            else
                _dualStopArm(state)
                if _G._dualGunBpConn then
                    pcall(function() _G._dualGunBpConn:Disconnect() end)
                    _G._dualGunBpConn = nil
                end
                if _G._dualGunCharPickupConn then
                    pcall(function() _G._dualGunCharPickupConn:Disconnect() end)
                    _G._dualGunCharPickupConn = nil
                end
                -- FIX: limpiar tambien el DK_Clone del char si quedo colgado
                local _ch = LocalPlayer.Character
                if _ch then
                    for _, obj in pairs(_ch:GetChildren()) do
                        if obj.Name == "DK_Clone" then pcall(function() obj:Destroy() end) end
                    end
                end
                CreateCustomNotification("DUAL GUN", "X Desactivado", 2)
            end
        end, false)

        -- FIX TAB REBUILD: si los duales estaban activos cuando el tab se reconstruye,
        -- re-iniciar las conexiones ahora mismo (sin esperar que el usuario los toque).
        -- Todas las funciones locales ya est?n declaradas en este punto.
        task.defer(function()
            local ks = _G._dualKnifeState
            local gs = _G._dualGunState
            if ks and ks.enabled then
                _dualCleanState(ks)
                local char = LocalPlayer.Character
                if char then
                    -- FIX BUG 2: usar _dkRearm para incluir el inputConn correcto
                    _dkRearm(ks)
                end
            end
            if gs and gs.enabled then
                _dualCleanState(gs)
                local char = LocalPlayer.Character
                if char then
                    _dualStartArm(gs, _dualGunKeywords)
                end
            end
        end)

        -- -- AUTO RE-INIT TRAS PANTALLA NEGRA -----------------------------
        -- Cuando hay transicin de mapa, el Character se destruye y recrea.
        -- El DK_Clone y los brazos quedan invlidos -> re-arrancar automticamente.
        if _G._dualCharConn then pcall(function() _G._dualCharConn:Disconnect() end) end
        _G._dualCharConn = LocalPlayer.CharacterAdded:Connect(function(newChar)
            _w(0.6)  -- esperar que el char y sus joints estn listos
            -- Re-iniciar Dual Knife si estaba activo
            local ks = _G._dualKnifeState
            if ks and ks.enabled then
                -- Desconectar conns viejas (el char anterior ya no existe)
                if ks.steppedConn then pcall(function() ks.steppedConn:Disconnect() end); ks.steppedConn = nil end
                if ks.renderConn  then pcall(function() ks.renderConn:Disconnect()  end); ks.renderConn  = nil end
                if ks.inputConn   then pcall(function() ks.inputConn:Disconnect()   end); ks.inputConn   = nil end

                -- Esperar hasta 8s a que el knife este en char o backpack
                task.spawn(function()
                    local function _knifeReady()
                        local char = LocalPlayer.Character
                        local bp   = LocalPlayer.Backpack
                        if char then
                            for _, t in ipairs(char:GetChildren()) do
                                if t:IsA("Tool") and _dualMatchKeywords(t, _dualKnifeKeywords) then return true end
                            end
                        end
                        if bp then
                            for _, t in ipairs(bp:GetChildren()) do
                                if t:IsA("Tool") and _dualMatchKeywords(t, _dualKnifeKeywords) then return true end
                            end
                        end
                        return false
                    end
                    local _kWaited = 0
                    while not _knifeReady() and _kWaited < 8 do
                        task.wait(0.25); _kWaited = _kWaited + 0.25
                    end
                    if not (ks and ks.enabled) then return end

                    -- Hook backpack: si el knife llega despues (pick-up desde el suelo), re-armar
                    if _G._dualKnifeBpConn then pcall(function() _G._dualKnifeBpConn:Disconnect() end) end
                    _G._dualKnifeBpConn = LocalPlayer.Backpack.ChildAdded:Connect(function(tool)
                        if not (ks and ks.enabled) then return end
                        if not tool:IsA("Tool") or not _dualMatchKeywords(tool, _dualKnifeKeywords) then return end
                        task.wait(0.1)
                        -- FIX BUG 2: _dkRearm recrea pose+clon+inputConn correcto
                        _dkRearm(ks)
                    end)
                    -- FIX NUEVA RONDA: hookear Character.ChildAdded para detectar cuando el
                    -- jugador EQUIPA el knife (Backpack->Character). Ese evento NO dispara
                    -- Backpack.ChildAdded, por eso el dual no se activaba en rondas siguientes.
                    if _G._dualKnifeCharPickupConn then pcall(function() _G._dualKnifeCharPickupConn:Disconnect() end) end
                    local _curChar = newChar or LocalPlayer.Character
                    if _curChar then
                        _G._dualKnifeCharPickupConn = _curChar.ChildAdded:Connect(function(tool)
                            if not (ks and ks.enabled) then return end
                            if not tool:IsA("Tool") or not _dualMatchKeywords(tool, _dualKnifeKeywords) then return end
                            task.wait(0.1)
                            -- FIX BUG 2: _dkRearm recrea pose+clon+inputConn correcto
                            _dkRearm(ks)
                        end)
                    end

                    -- FIX BUG 2: _dkRearm centraliza el re-arm completo (pose+clon+inputConn+tracks)
                    -- Elimina el inputConn inline duplicado que habia aqui
                    _dkRearm(ks)
                end)
            end
            -- Re-iniciar Dual Gun si estaba activo
            local gs = _G._dualGunState
            if gs and gs.enabled then
                if gs.steppedConn then pcall(function() gs.steppedConn:Disconnect() end); gs.steppedConn = nil end
                if gs.renderConn  then pcall(function() gs.renderConn:Disconnect()  end); gs.renderConn  = nil end
                if gs.inputConn   then pcall(function() gs.inputConn:Disconnect()   end); gs.inputConn   = nil end

                task.spawn(function()
                    local function _gunReady()
                        local char = LocalPlayer.Character
                        local bp   = LocalPlayer.Backpack
                        if char then
                            for _, t in ipairs(char:GetChildren()) do
                                if t:IsA("Tool") and _dualGunKeywords[t.Name] then return true end
                            end
                        end
                        if bp then
                            for _, t in ipairs(bp:GetChildren()) do
                                if t:IsA("Tool") and _dualGunKeywords[t.Name] then return true end
                            end
                        end
                        return false
                    end

                    -- Esperar hasta 8s a que aparezca la gun
                    local waited = 0
                    while not _gunReady() and waited < 8 do
                        task.wait(0.25)
                        waited = waited + 0.25
                    end

                    if not (gs and gs.enabled) then return end
                    -- Limpiar conns que pudieran haberse creado mientras esperabamos
                    if gs.steppedConn then pcall(function() gs.steppedConn:Disconnect() end); gs.steppedConn = nil end
                    if gs.renderConn  then pcall(function() gs.renderConn:Disconnect()  end); gs.renderConn  = nil end
                    if gs.inputConn   then pcall(function() gs.inputConn:Disconnect()   end); gs.inputConn   = nil end
                    _dualStartArm(gs, _dualGunKeywords)

                    -- Tambien hookear el backpack: si la gun aparece mas tarde (pick-up), re-armar
                    if _G._dualGunBpConn then pcall(function() _G._dualGunBpConn:Disconnect() end) end
                    _G._dualGunBpConn = LocalPlayer.Backpack.ChildAdded:Connect(function(tool)
                        if not (gs and gs.enabled) then return end
                        if not tool:IsA("Tool") then return end
                        if _dualGunKeywords[tool.Name] then
                            task.wait(0.1)
                            if gs.steppedConn then pcall(function() gs.steppedConn:Disconnect() end); gs.steppedConn = nil end
                            if gs.renderConn  then pcall(function() gs.renderConn:Disconnect()  end); gs.renderConn  = nil end
                            if gs.inputConn   then pcall(function() gs.inputConn:Disconnect()   end); gs.inputConn   = nil end
                            _dualStartArm(gs, _dualGunKeywords)
                        end
                    end)
                end)
            end
        end)
    end
    -- GINGERSCOPE ARM POSE UI: eliminado por usuario

    -- ======================================================================
    -- SECCIN: COMBAT PREMIUM  Instant Throw  Auto Slash  Fast Slash  Fast Throw
    -- ======================================================================
    do
        local _cpSection = (CreateBorderedSection and rightColumn) and CreateBorderedSection(rightColumn, "!  COMBAT PREMIUM") or Instance.new("Frame")

        -- -- INSTANT THROW ----------------------------------------------------
        -- Guardar el AnimationId original de ThrowCharge para poder restaurarlo
        local _origThrowChargeId = nil

        local function _getThrowChargeAnim()
            local char  = LocalPlayer.Character
            local knife = char and (char:FindFirstChild("Knife") or
                (LocalPlayer.Backpack and LocalPlayer.Backpack:FindFirstChild("Knife")))
            if not knife then return nil end
            local kc = knife:FindFirstChild("KnifeClient")
            if not kc then return nil end
            -- ThrowCharge est dentro de KnifeClient como Animation object
            local tc = kc:FindFirstChild("ThrowCharge", true)
                or knife:FindFirstChild("ThrowCharge", true)
            return tc
        end

        local _itWsConn = nil  -- hook workspace.ChildAdded para instant throw

        local function _itKillAnims()
            local char = LocalPlayer.Character
            if not char then return end
            local hum  = char:FindFirstChildOfClass("Humanoid")
            local anim = hum and hum:FindFirstChildOfClass("Animator")
            if not anim then return end
            for _, t in ipairs(anim:GetPlayingAnimationTracks()) do
                local n = (t.Name or ""):lower()
                if n:find("throw") or n:find("charge") or n:find("hold")
                or n:find("throwingknife") or n:find("throwknife") or n:find("animation2") then
                    pcall(function() t:Stop(0) end)
                end
            end
        end

        -- Cuando aparece un ThrowingKnife en workspace: empujar velocidad maxima inmediatamente
        -- y matar la animacion del personaje al mismo tiempo
        local function _itOnTKAppear(obj)
            if not KnifeSAState.instantThrow then return end
            if obj.Name ~= "ThrowingKnife" then return end
            -- Matar animacion de carga en el mismo frame
            _itKillAnims()

            -- FIX: capturar direccion de lanzamiento ANTES de entrar al loop,
            -- desde la camara, no desde AssemblyLinearVelocity (que puede apuntar
            -- al jugador en el frame de spawn y mandarlo a volar).
            local _throwDir = nil
            pcall(function()
                local cam = workspace.CurrentCamera
                _throwDir = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
            end)

            -- Cache del personaje del LocalPlayer para no aplicar velocidad a sus partes
            local _myChar = LocalPlayer and LocalPlayer.Character

            -- Disparar el knife al maximo desde el primer frame
            task.spawn(function()
                for _ = 1, 8 do  -- 8 frames de empuje para velocidad maxima garantizada
                    if not obj or not obj.Parent then break end
                    if obj:IsA("Model") then
                        for _, part in ipairs(obj:GetDescendants()) do
                            -- FIX: nunca tocar partes que pertenecen al personaje del jugador
                            if _myChar and part:IsDescendantOf(_myChar) then continue end
                            if part:IsA("BasePart") or part:IsA("MeshPart") then
                                -- FIX: usar direccion de camara capturada, no vel del part
                                -- (vel puede ser ~0 o apuntar hacia atras en el primer frame)
                                local vel = part.AssemblyLinearVelocity
                                local dir = (vel.Magnitude > 2) and vel.Unit
                                         or _throwDir
                                         or part.CFrame.LookVector
                                pcall(function()
                                    part.AssemblyLinearVelocity = dir * 800
                                    part.CanCollide = false
                                end)
                            end
                        end
                    elseif obj:IsA("BasePart") or obj:IsA("MeshPart") then
                        -- FIX: nunca tocar el HRP u otras partes del jugador
                        if _myChar and obj:IsDescendantOf(_myChar) then
                            RunService.Heartbeat:Wait()
                            continue
                        end
                        local vel = obj.AssemblyLinearVelocity
                        local dir = (vel.Magnitude > 2) and vel.Unit
                                 or _throwDir
                                 or obj.CFrame.LookVector
                        pcall(function()
                            obj.AssemblyLinearVelocity = dir * 800
                            obj.CanCollide = false
                        end)
                    end
                    RunService.Heartbeat:Wait()
                end
            end)
        end

        CreatePremiumToggle(_cpSection, "Instant Throw (Premium)", function(en)
            KnifeSAState.instantThrow = en
            if en then
                KnifeSAState.instantThrowCooldown = 0
                -- FIX: NO nullear ThrowCharge ni matar animaciones ?
                -- eso romp?a el lanzamiento manual del ThrowingKnife.
                -- Solo empujamos la velocidad del knife cuando aparece en workspace.
                if _itWsConn then pcall(function() _itWsConn:Disconnect() end) end
                _itWsConn = workspace.ChildAdded:Connect(function(obj)
                    if not KnifeSAState.instantThrow then return end
                    _itOnTKAppear(obj)
                end)
                -- Forzar cualquier ThrowingKnife ya en workspace
                for _, obj in ipairs(workspace:GetChildren()) do
                    _itOnTKAppear(obj)
                end
                -- [notif removed]
            else
                -- Matar hook de workspace
                if _itWsConn then
                    pcall(function() _itWsConn:Disconnect() end)
                    _itWsConn = nil
                end
                -- Matar heartbeat killer si qued? activo de una ejecuci?n anterior
                if _G._itKillerConn then
                    pcall(function() _G._itKillerConn:Disconnect() end)
                    _G._itKillerConn = nil
                end
                -- Restaurar ThrowCharge si fue nulleado por ejecuciones anteriores
                if _origThrowChargeId then
                    local tc = _getThrowChargeAnim()
                    if tc and tc:IsA("Animation") then
                        pcall(function() tc.AnimationId = _origThrowChargeId end)
                    end
                    _origThrowChargeId = nil
                end
                -- [notif removed]
            end
        end, KnifeSAState.instantThrow)

        do
            local _itDesc = Instance.new("TextLabel", _cpSection)
            _itDesc.Size = UDim2.new(1, -8, 0, 0)
            _itDesc.AutomaticSize = Enum.AutomaticSize.Y
            _itDesc.BackgroundTransparency = 1
            _itDesc.Text = "Elimina la animacin de carga. El cuchillo sale en el mismo frame del input."
            _itDesc.TextColor3 = Color3.fromRGB(60, 190, 240)
            _itDesc.Font = Enum.Font.Montserrat
            _itDesc.TextSize = 10
            _itDesc.TextWrapped = true
            _itDesc.TextXAlignment = Enum.TextXAlignment.Left
            _itDesc.ZIndex = 13
            local _p = Instance.new("UIPadding", _itDesc)
            _p.PaddingLeft = UDim.new(0,6); _p.PaddingRight = UDim.new(0,6)
            _p.PaddingTop  = UDim.new(0,2); _p.PaddingBottom = UDim.new(0,6)
        end


        -- -- AUTO SLASH --------------------------------------------------------
        -- Cuando tenes el knife equipado y hay un jugador cerca (wall check),
        -- hace la animacion de navajazo automaticamente y dispara KnifeStabbed.
        do
            CombatTabState.autoSlashState = CombatTabState.autoSlashState or {
                enabled  = false,
                range    = 5,      -- studs maximos para auto-slash
                conn     = nil,
                lastStab = -999,
                cooldown = 0.85,   -- sincronizado con el stab normal
            }
            local _as = CombatTabState.autoSlashState

            local function _asGetKnife()
                local char = LocalPlayer.Character
                -- FIX: solo retornar el knife si esta equipado en el Character.
                -- Si esta en el Backpack (no equipado), no se ejecuta el slash.
                -- Esto evita que Auto Slash mate cuando el jugador no tiene el knife en mano.
                if char then
                    local k = char:FindFirstChild("Knife"); if k and k:IsA("Tool") then return k, true end
                end
                return nil, false
            end

            local function _asPlaySlash(knife)
                local char = LocalPlayer.Character
                if not char then return end
                local hum = char:FindFirstChildOfClass("Humanoid")
                if not hum then return end
                local animator = hum:FindFirstChildOfClass("Animator")
                if not animator then return end
                local slashNames = {"SlashKnife", "Slash", "Stab", "Hit", "Animation1"}
                for _, animName in ipairs(slashNames) do
                    local animObj = knife:FindFirstChild(animName, true)
                    if animObj and animObj:IsA("Animation") then
                        local ok, track = pcall(function()
                            return animator:LoadAnimation(animObj)
                        end)
                        if ok and track then
                            pcall(function() track:Play(0.1, 1, 1) end)
                            return
                        end
                    end
                end
            end

            local function _asFireStab(knife, tHRP)
                local ev = knife:FindFirstChild("Events")
                if not ev then return end
                local stabbed = ev:FindFirstChild("KnifeStabbed")
                if stabbed then pcall(function() stabbed:FireServer() end) end
                local touched = ev:FindFirstChild("HandleTouched")
                if touched and tHRP then
                    pcall(function() touched:FireServer(tHRP) end)
                end
                -- Handle.Kill -- necesario para que el kill registre
                local handle = knife:FindFirstChild("Handle")
                if handle then
                    local kill = handle:FindFirstChild("Kill")
                    if kill then
                        pcall(function() kill:FireServer(tHRP) end)
                        pcall(function() kill:FireServer(tHRP and tHRP.Parent) end)
                        pcall(function() kill:FireServer() end)
                    end
                end
            end

            local function _asStart()
                if _as.conn then pcall(function() _as.conn:Disconnect() end) end
                local _hb = 0
                _as.conn = RunService.Heartbeat:Connect(function()
                    _hb = _hb + 1; if _hb < 3 then return end; _hb = 0  -- ~20Hz
                    if not _as.enabled then return end
                    if _G._visualRoundOver then return end

                    local now = os.clock()
                    local cd = _as.cooldown
                    if KnifeSAState.fastSlash then
                        -- FIX: slider 1-10, dividir por 10 en vez de 100
                        local pct = math.max(0.05, (KnifeSAState.fastSlashSpeed or 5) / 10)
                        cd = 0.85 * pct
                    end
                    if now - _as.lastStab < cd then return end

                    local knife, equipped = _asGetKnife()
                    if not knife or not equipped then return end

                    local char  = LocalPlayer.Character
                    local myHRP = char and char:FindFirstChild("HumanoidRootPart")
                    local myHum = char and char:FindFirstChildOfClass("Humanoid")
                    if not myHRP or not myHum or myHum.Health <= 0 then return end

                    local bestHRP, bestDist = nil, math.huge
                    local myPos   = myHRP.Position
                    local eyePos  = myPos + Vector3.new(0, 1.5, 0)
                    local asRange = _as.range
                    -- OPT: usar cache de HRP+Hum ? sin FindFirstChild por player cada tick
                    for p, pHRP in pairs(_kaHRPCache) do
                        if not pHRP or not pHRP.Parent then continue end
                        local pHum = _kaHumCache[p]
                        if not pHum or pHum.Health <= 0 then continue end
                        local d = (myPos - pHRP.Position).Magnitude
                        if d > asRange then continue end
                        local bodyPos = pHRP.Position + Vector3.new(0, 0.8, 0)
                        if not wallCheckRaycast(eyePos, bodyPos) then continue end
                        if d < bestDist then bestDist = d; bestHRP = pHRP end
                    end

                    if not bestHRP then return end

                    _as.lastStab = now
                    task.spawn(function()
                        _asPlaySlash(knife)
                        _asFireStab(knife, bestHRP)
                    end)
                end)
            end

            local function _asStop()
                if _as.conn then pcall(function() _as.conn:Disconnect() end); _as.conn = nil end
            end

            if _as.enabled then _asStart() end

            CreatePremiumToggle(_cpSection, "Auto Slash (Premium)", function(en)
                _as.enabled = en
                if en then
                    _asStart()
                    -- [notif removed]
                else
                    _asStop()
                    -- [notif removed]
                end
            end, false)

            do
