    -- =============================================
    -- SHOOPER SHOT
    do
        local ssSection = (CreateBorderedSection and rightColumn) and CreateBorderedSection(rightColumn, "  SHOOPER SHOT") or Instance.new("Frame")
        local _ssEnabled = false; local _hookedGun = nil; local _origConns = {}; local _ourConn = nil
        local _ssLmbConn = nil; local _ssLast = 0; local _ssCD = 0.12

        local function _ssGetR(gun)
            local d=gun:FindFirstChild("Shoot"); if d and d:IsA("RemoteEvent") then return d end
            for _,v in ipairs(gun:GetDescendants()) do if v:IsA("RemoteEvent") then local n=v.Name:lower(); if n=="shoot" or n:find("shoot") or n:find("fire") then return v end end end
        end
        local function _ssCF(o,a)
            local dir=a-o; if dir.Magnitude<0.001 then return nil,nil end
            local u=dir.Unit; local up=math.abs(u.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            local g=CFrame.lookAt(o,a,up); local bu=-u; local bup=math.abs(bu.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            return g, CFrame.lookAt(a,a+bu,bup)
        end
        local function _ssGetTgt()
            local m=findMurderer and findMurderer(); if m and m.Character then return m end
            local myH=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart"); if not myH then return nil end
            local best,bestD=nil,math.huge
            for _,p in ipairs(Players:GetPlayers()) do
                if p~=LocalPlayer and p.Character then local h=p.Character:FindFirstChild("HumanoidRootPart"); local hm=p.Character:FindFirstChildOfClass("Humanoid")
                    if h and hm and hm.Health>0 then local d=(h.Position-myH.Position).Magnitude; if d<bestD then bestD=d; best=p end end
                end
            end
            return best
        end
        local function _ssFire(gun)
            local char=LocalPlayer.Character; if not char then return end
            local myH=char:FindFirstChild("HumanoidRootPart"); if not myH then return end
            local shootR=_ssGetR(gun); if not shootR then return end
            local tgt=_ssGetTgt(); if not tgt or not tgt.Character then return end
            local hp=tgt.Character:FindFirstChild("HumanoidRootPart"); if not hp then return end
            local gra=myH:FindFirstChild("GunRaycastAttachment") or myH:FindFirstChildWhichIsA("Attachment")
            local origin=gra and gra.WorldCFrame.Position or (myH.Position+Vector3.new(0,1.5,0))
            -- Prediccion simple de movimiento
            local vel = hp.AssemblyLinearVelocity
            local dist = (hp.Position - origin).Magnitude
            local tof = dist / 500  -- velocidad estimada de bala
            local aim = hp.Position + vel * tof + Vector3.new(0,0.3,0)
            local gA,tA=_ssCF(origin,aim)
            if gA then
                if CombatTabState then CombatTabState._saBypassHook=true end
                pcall(function() shootR:FireServer(gA,tA) end)
                _w(0.008)
                local oB=aim+Vector3.new(0,0.05,0); local gB,tB=_ssCF(oB,aim)
                if gB then pcall(function() shootR:FireServer(gB,tB) end) end
                if CombatTabState then CombatTabState._saBypassHook=false end
            end
        end
        local function _ssGetEquippedGun()
            local char=LocalPlayer.Character; if not char then return nil end
            for _,t in ipairs(char:GetChildren()) do if t:IsA("Tool") and (t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot") or _ssGetR(t)) then return t end end
        end
        local function _ssApplyDisable()
            pcall(function() local conns=getconnections(_hookedGun and _hookedGun.Activated); for _,c in ipairs(conns) do
                local already=false; for _,oc in ipairs(_origConns) do if oc==c then already=true; break end end
                if not already then c:Disable(); table.insert(_origConns,c) end
            end end)
        end
        local function _ssRestoreOrig()
            pcall(function() for _,c in ipairs(_origConns) do c:Enable() end end)
            _origConns = {}
        end
        local function _ssHook(gun)
            if _hookedGun==gun then
                -- Gun ya hookeada: sincronizar estado de conexiones originales
                if _ssEnabled then _ssApplyDisable() else _ssRestoreOrig() end
                return
            end
            -- Restaurar conexiones de la gun anterior antes de cambiar
            _ssRestoreOrig()
            if _ourConn then pcall(function() _ourConn:Disconnect() end); _ourConn=nil end
            _hookedGun=gun
            -- Solo deshabilitar conexiones originales si Shooper Shot est? activo
            if _ssEnabled then _ssApplyDisable() end
            _ourConn=gun.Activated:Connect(function()
                if _ssEnabled then
                    -- En mobile, Activated se dispara con touch; ejecutar inmediatamente
                    local now = tick()
                    if now - _ssLast >= _ssCD then
                        _ssLast = now
                        _sp(function() _ssFire(gun) end)
                    end
                end
                -- Si _ssEnabled=false: no hacer nada, las conexiones originales
                -- siguen habilitadas y manejan el disparo normalmente
            end)
            -- MOBILE EXTRA: hookear TouchTap directo en la gun como fallback
            -- (en algunos devices Activated no se dispara si el juego consume el touch)
            if UserInputService.TouchEnabled then
                pcall(function()
                    local _touchConn = gun.InputBegan:Connect(function(inp)
                        if not _ssEnabled then return end
                        if inp.UserInputType == Enum.UserInputType.Touch then
                            local now = tick()
                            if now - _ssLast >= _ssCD then
                                _ssLast = now
                                _sp(function() _ssFire(gun) end)
                            end
                        end
                    end)
                    -- Desconectar si la gun cambia
                    gun.AncestryChanged:Connect(function()
                        if not gun.Parent then pcall(function() _touchConn:Disconnect() end) end
                    end)
                end)
            end
        end
        local function _ssTryHook()
            local char=LocalPlayer.Character; if not char then return end
            for _,t in ipairs(char:GetChildren()) do if t:IsA("Tool") and (t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot")) then _ssHook(t); return end end
        end
        local function _ssOnChar(c) _w(0.5); _ssTryHook(); c.ChildAdded:Connect(function(ch) if ch:IsA("Tool") and (ch:FindFirstChild("GunClient") or ch:FindFirstChild("Shoot")) then _w(0.1); _ssHook(ch) end end) end
        LocalPlayer.CharacterAdded:Connect(_ssOnChar); if LocalPlayer.Character then _ssOnChar(LocalPlayer.Character) end

        CreateAuroraToggle(ssSection,"Shooper Shot",function(on)
            _ssEnabled=on
            -- Limpiar conexion anterior
            if _ssLmbConn then pcall(function() _ssLmbConn:Disconnect() end); _ssLmbConn=nil end
            if on then
                -- Hookear la gun al activar
                _ssTryHook()
                if _hookedGun then _ssApplyDisable() end

                -- FIX TOUCH SINGLE TAP: UN solo toque en pantalla dispara inmediatamente.
                -- En mobile usamos TouchTap (tap completo) para que NO requiera dos toques.
                -- En PC seguimos con MouseButton1.
                local _isMobileShoop = UserInputService.TouchEnabled

                if _isMobileShoop then
                    -- MOBILE: TouchTap = un solo tap completo -> dispara inmediatamente
                    _ssLmbConn = UserInputService.TouchTap:Connect(function(positions, gp)
                        if not _ssEnabled then return end
                        if gp then return end
                        local char = LocalPlayer.Character
                        if not char then return end
                        local equippedGun = nil
                        for _, t in ipairs(char:GetChildren()) do
                            if t:IsA("Tool") and (t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot") or _ssGetR(t)) then
                                equippedGun = t; break
                            end
                        end
                        if not equippedGun then return end
                        local now = tick()
                        if now - _ssLast < _ssCD then return end
                        _ssLast = now
                        _sp(function() _ssFire(equippedGun) end)
                    end)
                else
                    -- PC: MouseButton1
                    _ssLmbConn = UserInputService.InputBegan:Connect(function(i, gp)
                        if not _ssEnabled then return end
                        if i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                        if gp then return end
                        local char = LocalPlayer.Character
                        if not char then return end
                        local equippedGun = nil
                        for _, t in ipairs(char:GetChildren()) do
                            if t:IsA("Tool") and (t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot") or _ssGetR(t)) then
                                equippedGun = t; break
                            end
                        end
                        if not equippedGun then return end
                        local now = tick()
                        if now - _ssLast < _ssCD then return end
                        _ssLast = now
                        _sp(function() _ssFire(equippedGun) end)
                    end)
                end

                local modeText = _isMobileShoop and "ON -- 1 toque dispara al murder" or "ON -- LMB redirige al murder"
                CreateCustomNotification("SHOOPER SHOT", modeText, 2)
            else
                -- Restaurar conexiones originales
                _ssRestoreOrig()
                -- [notif removed]
            end
        end, false)

        -- Info
        do
            local _ssInfo = Instance.new("TextLabel", ssSection)
            _ssInfo.Size = UDim2.new(1,-8,0,0); _ssInfo.AutomaticSize = Enum.AutomaticSize.Y
            _ssInfo.BackgroundTransparency = 1
            _ssInfo.Text = UserInputService.TouchEnabled
                and "MOBILE: un solo toque en pantalla dispara al Murder automaticamente."
                or  "PC: cada LMB se redirige al Murder/target mas cercano automaticamente."
            _ssInfo.TextColor3 = Color3.fromRGB(140,200,255); _ssInfo.Font = Enum.Font.Montserrat
            _ssInfo.TextSize = 10; _ssInfo.TextWrapped = true; _ssInfo.TextXAlignment = Enum.TextXAlignment.Left; _ssInfo.ZIndex = 13
            local _p=Instance.new("UIPadding",_ssInfo); _p.PaddingLeft=UDim.new(0,6); _p.PaddingRight=UDim.new(0,6); _p.PaddingTop=UDim.new(0,2); _p.PaddingBottom=UDim.new(0,4)
        end
    end


    -- PIERCE BULLET  cdigo v2 (documento)
    do
        local pierceSec = (CreateBorderedSection and rightColumn) and CreateBorderedSection(rightColumn, "  PIERCE BULLET") or Instance.new("Frame")

        local _pEnabled     = false
        local _pTargetMode  = "murder"
        local _pPens        = 3
        local _pCooldown    = 0.25
        local _pLastShot    = 0
        local _pCachedR     = nil

        local function _pGetGun()
            local char = LocalPlayer.Character; if not char then return nil end
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") and (t.Name:lower():find("gun") or t.Name:lower():find("sheriff")
                or t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot")) then return t end
            end
        end

        local function _pGetRemote(gun)
            if _pCachedR and _pCachedR.Parent and _pCachedR:IsDescendantOf(gun) then return _pCachedR end
            _pCachedR = nil; if not gun then return nil end
            local d = gun:FindFirstChild("Shoot"); if d and d:IsA("RemoteEvent") then _pCachedR=d; return d end
            for _, v in ipairs(gun:GetDescendants()) do
                if v:IsA("RemoteEvent") then local n=v.Name:lower()
                    if n=="shoot" or n:find("shoot") or n:find("fire") then _pCachedR=v; return v end
                end
            end
        end

        local function _pGetOrigin(myHRP)
            local gra = myHRP:FindFirstChild("GunRaycastAttachment") or myHRP:FindFirstChildWhichIsA("Attachment")
            return gra and gra.WorldCFrame.Position or (myHRP.Position + Vector3.new(0,1.5,0))
        end

        local function _pBuildCF(originPos, aimPos)
            local dir = aimPos - originPos; if dir.Magnitude < 0.01 then return nil,nil end
            local dirU = dir.Unit; local upV = math.abs(dirU.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            local graCF = CFrame.lookAt(originPos, aimPos, upV)
            local backU = -dirU; local upB = math.abs(backU.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            return graCF, CFrame.lookAt(aimPos, aimPos+backU, upB)
        end

        local function _pFindTarget()
            if _pTargetMode == "murder" then
                local m = findMurderer and findMurderer()
                if m and m.Character then return m end
                -- fallback: nearest
            end
            local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not myHRP then return nil end
            local best, bestD = nil, math.huge
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    local h = p.Character:FindFirstChild("HumanoidRootPart")
                    local hm = p.Character:FindFirstChildOfClass("Humanoid")
                    if h and hm and hm.Health > 0 then
                        local d = (h.Position - myHRP.Position).Magnitude
                        if d < bestD then bestD=d; best=p end
                    end
                end
            end
            return best
        end

        local function _doPierce(forced)
            if not forced and not _pEnabled then return end
            local char = LocalPlayer.Character; if not char then return end
            local myHRP = char:FindFirstChild("HumanoidRootPart"); if not myHRP then return end
            local gun = _pGetGun(); if not gun then return end
            local shootR = _pGetRemote(gun); if not shootR then return end
            local target = _pFindTarget()
            if not target or not target.Character then return end
            local tChar = target.Character
            local tHRP  = tChar:FindFirstChild("HumanoidRootPart")
            local tHead = tChar:FindFirstChild("Head")
            local tTors = tChar:FindFirstChild("UpperTorso") or tChar:FindFirstChild("Torso")
            if not tHRP then return end
            local hitParts = {tHRP, tHead or tHRP, tTors or tHRP}

            -- PIERCE v4 WALL-BYPASS: teletransportarse junto al murder para que el servidor
            -- no rechace el disparo por pared/distancia. La bala conecta desde cualquier
            -- distancia atravesando TODAS las paredes del mapa. Volvemos instantaneamente.
            local originalCF    = myHRP.CFrame
            local savedAnchored = myHRP.Anchored
            local tPos = tHRP.Position
            local offset = (originalCF.Position - tPos)
            local offsetMag = offset.Magnitude
            local nearPos
            if offsetMag < 0.01 then
                nearPos = tPos + Vector3.new(0, 0, 1.5)
            else
                nearPos = tPos + (offset.Unit * 1.5)
            end
            -- Teletransportar junto al target silenciosamente
            pcall(function()
                myHRP.Anchored = true
                myHRP.CFrame = CFrame.new(nearPos, tPos)
            end)
            -- Disparar desde ahi: el servidor ve HRP al lado del target -> sin wall check
            local baseOrigin = nearPos + Vector3.new(0, 1.5, 0)
            if CombatTabState then CombatTabState._saBypassHook = true end
            for i = 1, _pPens do
                local hp = hitParts[(i-1) % #hitParts + 1]
                if hp then
                    local aimPos    = hp.Position
                    local originPos = baseOrigin
                    local graCF, targetCF = _pBuildCF(originPos, aimPos)
                    if graCF then pcall(function() shootR:FireServer(graCF, targetCF) end) end
                end
                if i < _pPens then _w(0.016) end
            end
            if CombatTabState then CombatTabState._saBypassHook = false end
            -- Volver instantaneamente a la posicion original
            pcall(function()
                myHRP.CFrame    = originalCF
                myHRP.Anchored  = savedAnchored
            end)
        end

        -- Boton SHOOT flotante -- misma estructura y animaciones que createBindableButton
        local _pGui = nil
        local function _pCreateBtn()
            if _G._pGuiRef and _G._pGuiRef.Parent then pcall(function() _G._pGuiRef:Destroy() end) end

            local BTN_W = 76
            local BTN_H = 76
            local vp    = workspace.CurrentCamera.ViewportSize

            local gui = Instance.new("ScreenGui")
            gui.Name           = "PierceBulletGui"
            gui.ResetOnSpawn   = false
            gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            gui.DisplayOrder   = 9900
            gui.IgnoreGuiInset = true
            pcall(function() gui.Parent = game:GetService("CoreGui") end)
            if not gui.Parent then gui.Parent = LocalPlayer.PlayerGui end
            _G._pGuiRef = gui

            -- Contenedor raiz (invisible, solo para drag) ? igual que bindable
            local bg = Instance.new("Frame", gui)
            bg.Name                   = "CapyBindBtn"
            bg.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            bg.Position               = UDim2.fromOffset(
                math.clamp(vp.X/2 - BTN_W/2, 4, vp.X - BTN_W - 4),
                math.clamp(vp.Y - 200, 4, vp.Y - BTN_H - 4))
            bg.BackgroundTransparency = 1
            bg.BorderSizePixel        = 0
            bg.ZIndex                 = 200
            bg.Active                 = true

            -- UIScale: empieza en 0, anima a 1 con Back bounce
            local _bgScale = Instance.new("UIScale", bg)
            _bgScale.Scale = 0

            -- Fondo transparente (aparece en hover/press) ? igual que bindable
            local pill = Instance.new("Frame", bg)
            pill.Name                   = "Pill"
            pill.AnchorPoint            = Vector2.new(0.5, 0.5)
            pill.Position               = UDim2.fromScale(0.5, 0.5)
            pill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            pill.BackgroundColor3       = ThemeColors.Aurora1
            pill.BackgroundTransparency = 1
            pill.BorderSizePixel        = 0
            pill.ZIndex                 = 201
            Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 10)

            -- Borde exterior del color del hub ? igual que bindable
            local outerRing = Instance.new("Frame", bg)
            outerRing.Name                   = "OuterRing"
            outerRing.AnchorPoint            = Vector2.new(0.5, 0.5)
            outerRing.Position               = UDim2.fromScale(0.5, 0.5)
            outerRing.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            outerRing.BackgroundTransparency = 1
            outerRing.BorderSizePixel        = 0
            outerRing.ZIndex                 = 202
            Instance.new("UICorner", outerRing).CornerRadius = UDim.new(0, 10)

            local outerStroke = Instance.new("UIStroke", outerRing)
            outerStroke.Color           = ThemeColors.Aurora1
            outerStroke.Thickness       = 0
            outerStroke.Transparency    = 1
            outerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            -- Label centrado con contorno negro ? igual que bindable
            local lbl = Instance.new("ImageLabel", bg)
            lbl.Name                   = "StarIcon"
            lbl.AnchorPoint            = Vector2.new(0.5, 0.5)
            lbl.Position               = UDim2.fromScale(0.5, 0.5)
            lbl.Size                   = UDim2.fromOffset(40, 40)
            lbl.BackgroundTransparency = 1
            lbl.Image                  = "rbxassetid://45428892"
            lbl.ImageColor3            = Color3.fromRGB(255, 255, 255)
            lbl.ScaleType              = Enum.ScaleType.Fit
            lbl.ZIndex                 = 205


            -- Boton invisible encima para capturar clicks ? igual que bindable
            local fill = Instance.new("TextButton", bg)
            fill.Name                   = "Fill"
            fill.AnchorPoint            = Vector2.new(0.5, 0.5)
            fill.Position               = UDim2.fromScale(0.5, 0.5)
            fill.Size                   = UDim2.fromOffset(BTN_W, BTN_H)
            fill.BackgroundTransparency = 1
            fill.Text                   = ""
            fill.AutoButtonColor        = false
            fill.ZIndex                 = 210
            Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 10)

            -- Glow de fondo ? igual que bindable
            local glow = Instance.new("ImageLabel", bg)
            glow.AnchorPoint            = Vector2.new(0.5, 0.5)
            glow.Position               = UDim2.fromScale(0.5, 0.5)
            glow.Size                   = UDim2.fromOffset(BTN_W * 1.3, BTN_H * 1.8)
            glow.BackgroundTransparency = 1
            glow.Image                  = "rbxassetid://118930676204472"
            glow.ScaleType              = Enum.ScaleType.Fit
            glow.ImageColor3            = ThemeColors.Aurora1
            glow.ImageTransparency      = 0.82
            glow.ZIndex                 = 199

            -- _moved declarado ANTES del bloque de drag (igual que bindable, evita el bug)
            local _moved = false

            -- -- ANIMACION DE ENTRADA: scale 0?1 con Back bounce --------------
            task.spawn(function()
                task.wait(0.016)
                TweenService:Create(_bgScale, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
            end)

            -- -- HOVER ---------------------------------------------------------
            fill.MouseEnter:Connect(function()
                TweenService:Create(pill,        TweenInfo.new(0.12), {BackgroundTransparency = 0.75}):Play()
                TweenService:Create(outerStroke, TweenInfo.new(0.12), {Transparency = 1, Thickness = 3.5}):Play()
            end)
            fill.MouseLeave:Connect(function()
                TweenService:Create(pill,        TweenInfo.new(0.15), {BackgroundTransparency = 1}):Play()
                TweenService:Create(outerStroke, TweenInfo.new(0.15), {Transparency = 1, Thickness = 3}):Play()
            end)

            -- -- PRESS / RELEASE: hundido + glow intenso -----------------------
            fill.MouseButton1Down:Connect(function()
                if _moved then return end
                TweenService:Create(pill,        TweenInfo.new(0.07), {BackgroundTransparency = 0.40}):Play()
                TweenService:Create(outerStroke, TweenInfo.new(0.07), {Transparency = 1, Thickness = 2}):Play()
                TweenService:Create(_bgScale,    TweenInfo.new(0.07), {Scale = 0.92}):Play()
                TweenService:Create(glow,        TweenInfo.new(0.07), {ImageTransparency = 0.55}):Play()
            end)
            fill.MouseButton1Up:Connect(function()
                if _moved then return end
                TweenService:Create(pill,        TweenInfo.new(0.18), {BackgroundTransparency = 1}):Play()
                TweenService:Create(outerStroke, TweenInfo.new(0.18), {Transparency = 1, Thickness = 3}):Play()
                TweenService:Create(_bgScale,    TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
                TweenService:Create(glow,        TweenInfo.new(0.25), {ImageTransparency = 0.82}):Play()
            end)

            -- -- ACTIVATED: flash glow + disparo pierce ------------------------
            fill.Activated:Connect(function()
                if _moved then return end
                if not _pEnabled then return end
                local now = tick()
                if now - _pLastShot < _pCooldown then return end
                _pLastShot = now
                TweenService:Create(glow, TweenInfo.new(0.08), {ImageTransparency = 0.42}):Play()
                task.delay(0.12, function()
                    TweenService:Create(glow, TweenInfo.new(0.25), {ImageTransparency = 0.82}):Play()
                end)
                _sp(function() _doPierce(true) end)
            end)

            -- -- DRAG: UIDragDetector con fallback manual ----------------------
            if pcall(function()
                local dd = Instance.new("UIDragDetector", bg)
                dd.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                dd.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                dd.Dragged:Connect(function()
                    _moved = true
                    local vpN = workspace.CurrentCamera.ViewportSize
                    bg.Position = UDim2.fromOffset(
                        math.clamp(bg.Position.X.Offset, 0, vpN.X - BTN_W),
                        math.clamp(bg.Position.Y.Offset, 0, vpN.Y - BTN_H))
                end)
                dd.DragEnd:Connect(function() task.defer(function() _moved = false end) end)
            end) then
                -- UIDragDetector OK
            else
                -- Fallback manual (executors sin soporte UIDragDetector)
                local _dragging  = false
                local _dragStart = nil
                local _startPos  = nil
                fill.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                        _dragging  = true
                        _moved     = false
                        _dragStart = input.Position
                        _startPos  = bg.Position
                    end
                end)
                UserInputService.InputChanged:Connect(function(input)
                    if not _dragging then return end
                    if input.UserInputType ~= Enum.UserInputType.MouseMovement
                    and input.UserInputType ~= Enum.UserInputType.Touch then return end
                    local delta = input.Position - _dragStart
                    if delta.Magnitude > 4 then _moved = true end
                    local vpN = workspace.CurrentCamera.ViewportSize
                    bg.Position = UDim2.fromOffset(
                        math.clamp(_startPos.X.Offset + delta.X, 0, vpN.X - BTN_W),
                        math.clamp(_startPos.Y.Offset + delta.Y, 0, vpN.Y - BTN_H))
                end)
                fill.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch then
                        _dragging = false
                        task.defer(function() _moved = false end)
                    end
                end)
            end
        end

        -- Helper: agrega badge PREMIUM a un AuroraToggleRow + overlay de bloqueo si no hay premium
        local function _addPremiumBadgeToAurora(parent, rowName)
            task.defer(function()
                local row = parent:FindFirstChild("AuroraToggleRow_" .. rowName)
                if not row then return end
                if row:FindFirstChild("PremiumBadge") then return end
                -- Badge: fondo dorado, texto negro = maximo contraste
                -- Al costado del texto, entre label y track (track: 76px desde derecha con offset -6)
                local badge = Instance.new("TextLabel", row)
                badge.Name = "PremiumBadge"
                badge.Size = UDim2.new(0, 82, 0, 15)
                badge.AnchorPoint = Vector2.new(1, 0.5)
                badge.Position = UDim2.new(1, -(76 + 6 + 6), 0.5, 0)
                badge.BackgroundColor3 = Color3.fromRGB(212, 160, 0)
                badge.BackgroundTransparency = 0
                badge.BorderSizePixel = 0
                badge.Text = "? PREMIUM"
                badge.TextColor3 = Color3.fromRGB(20, 12, 0)
                badge.TextSize = 9
                badge.Font = Enum.Font.GothamBold
                badge.TextXAlignment = Enum.TextXAlignment.Center
                badge.TextYAlignment = Enum.TextYAlignment.Center
                badge.ZIndex = 25
                Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 4)
                local st = Instance.new("UIStroke", badge)
                st.Color = Color3.fromRGB(255, 230, 80)
                st.Thickness = 1.5
                st.Transparency = 0
                -- BLOQUEO REAL: overlay que intercepta clicks si no hay premium
                if not _G._discordPremiumVerified then
                    local overlay = Instance.new("TextButton", row)
                    overlay.Name = "PremiumLockOverlay"
                    overlay.Size = UDim2.new(1, 0, 1, 0)
                    overlay.Position = UDim2.new(0, 0, 0, 0)
                    overlay.BackgroundTransparency = 1
                    overlay.Text = ""
                    overlay.ZIndex = 30
                    overlay.Activated:Connect(function()
                        CreateCustomNotification("VIP PREMIUM", "Requiere Premium. Verificate en el tab VIP.", 3)
                    end)
                    -- Auto-destruir al verificar premium
                    task.spawn(function()
                        while overlay and overlay.Parent do
                            task.wait(1)
                            if _G._discordPremiumVerified then
                                pcall(function() overlay:Destroy() end)
                                break
                            end
                        end
                    end)
                end
            end)
        end

