                task.defer(function()
                    local _tKey = "Shoot Camuflado (Premium)"
                    if _G._toggleStates then _G._toggleStates[_tKey] = false end
                    pcall(function()
                        local pg = game:GetService("CoreGui"):FindFirstChild("f") or LocalPlayer.PlayerGui:FindFirstChild("f")
                        if not pg then return end
                        for _, desc in ipairs(pg:GetDescendants()) do
                            if desc.Name == "AuroraToggleRow_Shoot Camuflado (Premium)" then
                                local bg = desc:FindFirstChild("ToggleBackground")
                                local knob = bg and bg:FindFirstChild("Knob")
                                if knob then knob.BackgroundColor3 = Color3.fromRGB(255,0,0) end
                            end
                        end
                    end)
                end)
                _scEnabled = false
                return
            end
            _scEnabled = on
            if _scConn then pcall(function() _scConn:Disconnect() end); _scConn = nil end

            if not on then
                -- [notif removed]
                return
            end

            _scConn = UserInputService.InputBegan:Connect(function(inp, gp)
                if gp or not _scEnabled then return end
                if inp.UserInputType ~= Enum.UserInputType.MouseButton1
                   and inp.UserInputType ~= Enum.UserInputType.Touch then return end

                -- Solo actuar si NO tiene gun equipada
                local char = LocalPlayer.Character
                if not char then return end
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA("Tool") then
                        local n = t.Name:lower()
                        if n:find("gun") or n:find("sheriff") or n:find("pistol") or n:find("revolver")
                           or t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot") then
                            return  -- gun equipada -> dejar que el juego dispare normal
                        end
                    end
                end

                -- Buscar gun en backpack sin equiparla
                local bp = LocalPlayer:FindFirstChild("Backpack")
                if not bp then return end
                local gun = nil
                for _, t in ipairs(bp:GetChildren()) do
                    if t:IsA("Tool") then
                        local n = t.Name:lower()
                        if n:find("gun") or n:find("sheriff") or n:find("pistol") or n:find("revolver")
                           or t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot") then
                            gun = t; break
                        end
                    end
                end
                if not gun then return end

                local now = tick()
                if now - _scLastShot < _scCooldown then return end
                _scLastShot = now

                _sp(function()
                    local myHRP = char:FindFirstChild("HumanoidRootPart")
                    if not myHRP then return end
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if not hum or hum.Health <= 0 then return end

                    -- FIX: equipar la gun antes de disparar (el servidor valida que est? en el char)
                    local alreadyEquipped = gun.Parent == char
                    if not alreadyEquipped then
                        _hideBackpackUI()
                        pcall(function() hum:EquipTool(gun) end)
                        task.wait(0.016)  -- esperar 1 frame para que el equip se registre en el servidor
                        -- Re-leer la gun desde el char (puede haber cambiado de referencia)
                        gun = char:FindFirstChild(gun.Name) or gun
                    end

                    local shootR = _pGetRemote(gun)
                    if not shootR then
                        if not alreadyEquipped then
                            pcall(function() hum:UnequipTools() end)
                            task.defer(_showBackpackUI)
                        end
                        return
                    end

                    local target = _pFindTarget()
                    if not target or not target.Character then
                        if not alreadyEquipped then
                            pcall(function() hum:UnequipTools() end)
                            task.defer(_showBackpackUI)
                        end
                        return
                    end
                    local tChar = target.Character
                    local tHRP  = tChar:FindFirstChild("HumanoidRootPart")
                    local tHead = tChar:FindFirstChild("Head")
                    local tTors = tChar:FindFirstChild("UpperTorso") or tChar:FindFirstChild("Torso")
                    if not tHRP then
                        if not alreadyEquipped then
                            pcall(function() hum:UnequipTools() end)
                            task.defer(_showBackpackUI)
                        end
                        return
                    end

                    local hitParts = {tHead or tHRP, tHRP, tTors or tHRP}
                    if CombatTabState then CombatTabState._saBypassHook = true end
                    for i = 1, _pPens do
                        local hp = hitParts[(i-1) % #hitParts + 1]
                        if hp then
                            local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP)
                            local aimPos    = hp.Position
                            local originPos = (barrelAtt and barrelAtt.WorldPosition)
                                          or (myHRP.Position + Vector3.new(0, 1.5, 0))
                            local graCF, targetCF = _pBuildCF(originPos, aimPos)
                            if graCF then pcall(function() shootR:FireServer(graCF, targetCF) end) end
                        end
                        if i < _pPens then _w(0.016) end
                    end
                    if CombatTabState then CombatTabState._saBypassHook = false end

                    -- Desequipar solo si la gun NO estaba en mano originalmente
                    if not alreadyEquipped then
                        task.delay(0.08, function()
                            pcall(function() hum:UnequipTools() end)
                            _showBackpackUI()
                        end)
                    end
                end)
            end)

            -- [notif removed]
        end, false)

        -- Badges PREMIUM en amarillo para los toggles Aurora de esta seccion
        _addPremiumBadgeToAurora(pierceSec, "Pierce Bullet (Premium)")
        _addPremiumBadgeToAurora(pierceSec, "Shoot Camuflado (Premium)")

    end
    -- -----------------------------------------------------------------
    -- AUTO PING COMPENSATION  ajusta sliders segn tu ping en tiempo real
    -- -----------------------------------------------------------------
    do
        local apcSec = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, "  AUTO PING COMP") or Instance.new("Frame")
        local _apcEnabled = false
        local _apcConn    = nil
        local _apcLastPing = 0

        -- Referencias a los sliders que vamos a auto-ajustar
        -- Gun: CombatTabState.gunLatencyComp (0.5-3.0)
        -- Knife: KnifeSAState.pingComp (ms adicionales, 0-200)

        -- Labels para mostrar valor actual
        local _apcGunLabel   = nil
        local _apcKnifeLabel = nil

        -- Info ping en tiempo real
        do
            local plb = Instance.new("TextLabel", apcSec)
            plb.Size = UDim2.new(1,-8,0,24)
            plb.BackgroundColor3 = Color3.fromRGB(11,16,42)
            plb.BackgroundTransparency = 0.4
            plb.BorderSizePixel = 0; plb.ZIndex = 13
            plb.Text = "Ping: -- ms"
            plb.TextColor3 = Color3.fromRGB( 50, 255, 180)
            plb.FontFace = Font.fromEnum(Enum.Font.GothamBold)
            plb.TextSize = 13; plb.TextXAlignment = Enum.TextXAlignment.Center
            Instance.new("UICorner", plb).CornerRadius = UDim.new(0,6)

            local statsService = game:GetService("Stats")
            _sp(function()
                while plb and plb.Parent do
                    _w(0.5)
                    pcall(function()
                        local ping = math.floor(statsService.Network.ServerStatsItem["Data Ping"]:GetValue())
                        _apcLastPing = ping
                        local color = ping < 80 and Color3.fromRGB( 50, 255, 180)
                                   or ping < 150 and Color3.fromRGB(255,200,0)
                                   or Color3.fromRGB(255,60,60)
                        plb.TextColor3 = color
                        plb.Text = " Ping: " .. ping .. " ms"
                    end)
                end
            end)
            _apcGunLabel = Instance.new("TextLabel", apcSec)
            _apcGunLabel.Size = UDim2.new(1,-8,0,18)
            _apcGunLabel.BackgroundTransparency = 1; _apcGunLabel.ZIndex = 13
            _apcGunLabel.Text = "Gun comp: --"
            _apcGunLabel.TextColor3 = Color3.fromRGB(140,200,255)
            _apcGunLabel.FontFace = Font.fromEnum(Enum.Font.Code)
            _apcGunLabel.TextSize = 11; _apcGunLabel.TextXAlignment = Enum.TextXAlignment.Left

            _apcKnifeLabel = Instance.new("TextLabel", apcSec)
            _apcKnifeLabel.Size = UDim2.new(1,-8,0,18)
            _apcKnifeLabel.BackgroundTransparency = 1; _apcKnifeLabel.ZIndex = 13
            _apcKnifeLabel.Text = "Knife comp: --"
            _apcKnifeLabel.TextColor3 = Color3.fromRGB(255,200,140)
            _apcKnifeLabel.FontFace = Font.fromEnum(Enum.Font.Code)
            _apcKnifeLabel.TextSize = 11; _apcKnifeLabel.TextXAlignment = Enum.TextXAlignment.Left
        end

        local function _apcApply(ping)
            -- -- GUN: ajustar gunLatencyComp --
            -- Frmula: ping bajo (<80ms) = comp ~1.0, ping alto (>200ms) = comp ~2.5
            local gunComp = math.clamp(1.0 + (ping / 100) * 0.6, 0.8, 3.0)
            CombatTabState.gunLatencyComp = gunComp

            -- -- KNIFE: ajustar pingComp (ms adicionales) --
            -- Frmula: aade ms extra proporcional al ping para compensar el vuelo del knife
            local knifeComp = math.clamp(ping * 0.4 - 10, 0, 200)
            KnifeSAState.pingComp = knifeComp

            -- -- Tianca Prediction: ajustar strength --
            if _G._tiancaPredStrength and _G._tiancaPredStrength > 0 then
                -- Solo ajustar si Tianca est activa
                local tiancaStrength = math.clamp(0.5 + (ping / 200) * 0.5, 0.5, 1.2)
                _G._tiancaPredStrength = tiancaStrength
            end

            -- Actualizar labels
            if _apcGunLabel and _apcGunLabel.Parent then
                _apcGunLabel.Text = string.format("Gun latency: %.2fx", gunComp)
            end
            if _apcKnifeLabel and _apcKnifeLabel.Parent then
                _apcKnifeLabel.Text = string.format("Knife pingComp: %.0fms", knifeComp)
            end
        end

        CreateAuroraToggle(apcSec, "Auto Ping Compensation", function(on)
            _apcEnabled = on
            if _apcConn then pcall(function() _apcConn:Disconnect() end); _apcConn = nil end
            if on then
                -- Aplicar inmediatamente con ping actual
                _apcApply(_apcLastPing > 0 and _apcLastPing or 80)
                -- Loop cada 1s para actualizar al cambiar el ping
                local _apcTick = 0
                _apcConn = _safeConnect(RunService.Heartbeat, function()
                    _apcTick = _apcTick + 1; if _apcTick < 60 then return end; _apcTick = 0  -- OPT: 1Hz, este loop solo verifica el flag
                    if not _apcEnabled then return end
                end)
                -- Actualizacin real cada 1s (Stats es ms lento)
                _sp(function()
                    local statsService = game:GetService("Stats")
                    while _apcEnabled do
                        _w(1)
                        pcall(function()
                            local ping = math.floor(statsService.Network.ServerStatsItem["Data Ping"]:GetValue())
                            _apcLastPing = ping
                            _apcApply(ping)
                        end)
                    end
                end)
                -- [notif removed]
            else
                -- [notif removed]
            end
        end, false)

        -- Info de qu ajusta
        do
            local infoLbl = Instance.new("TextLabel", apcSec)
            infoLbl.Size = UDim2.new(1,-8,0,0); infoLbl.AutomaticSize = Enum.AutomaticSize.Y
            infoLbl.BackgroundTransparency = 1; infoLbl.ZIndex = 13
            infoLbl.Text = "Ajusta automticamente:\n Gun: Latency Comp\n Knife: Ping Comp\n Tianca Pred (si est activa)"
            infoLbl.TextColor3 = Color3.fromRGB(130,150,180)
            infoLbl.FontFace = Font.fromEnum(Enum.Font.Code)
            infoLbl.TextSize = 10; infoLbl.TextWrapped = true
            infoLbl.TextXAlignment = Enum.TextXAlignment.Left
        end
    end

        -- -----------------------------------------------------------------
    -- SHOOT KEYBIND  dispara SA con una tecla
    -- -----------------------------------------------------------------
    do
        local skbSection   = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, "  SHOOT KEYBIND") or Instance.new("Frame")
        local _skbEnabled  = false
        local _skbKey      = Enum.KeyCode.Q  -- tecla default
        local _skbConn     = nil
        local _skbLastShot = 0
        local _skbCooldown = 0.25

        local function _skbFire()
            local now = tick()
            if now - _skbLastShot < _skbCooldown then return end
            local char = LocalPlayer.Character; if not char then return end
            local myHRP = char:FindFirstChild("HumanoidRootPart"); if not myHRP then return end
            -- Buscar gun
            local gun = nil
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") and (t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot")) then
                    gun = t; break
                end
            end
            if not gun then return end
            local shootR = getShootRemote and getShootRemote(gun)
            if not shootR then return end
            -- Target via SA
            local murder = findMurderer and findMurderer()
            if not murder or not murder.Character then return end
            local tHRP = murder.Character:FindFirstChild("HumanoidRootPart"); if not tHRP then return end
            local gra = myHRP:FindFirstChild("GunRaycastAttachment") or myHRP:FindFirstChildWhichIsA("Attachment")
            local origin = gra and gra.WorldCFrame.Position or (myHRP.Position + Vector3.new(0,1.5,0))
            local aim = tHRP.Position + Vector3.new(0,0.3,0)
            local dir = aim - origin; if dir.Magnitude < 0.01 then return end
            local u = dir.Unit; local up = math.abs(u.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            local graA = CFrame.lookAt(origin, aim, up)
            local bu = -u; local bup = math.abs(bu.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            local tgtA = CFrame.lookAt(aim, aim+bu, bup)
            _skbLastShot = now
            if CombatTabState then CombatTabState._saBypassHook = true end
            pcall(function() shootR:FireServer(graA, tgtA) end)
            if CombatTabState then CombatTabState._saBypassHook = false end
        end

        CreateAuroraToggle(skbSection, "Shoot Keybind", function(on)
            _skbEnabled = on
            if _skbConn then pcall(function() _skbConn:Disconnect() end); _skbConn = nil end
            if on then
                _skbConn = UserInputService.InputBegan:Connect(function(inp, gp)
                    if gp or not _skbEnabled then return end
                    if inp.KeyCode == _skbKey then _sp(_skbFire) end
                end)
                -- [notif removed]
            else
                -- [notif removed]
            end
        end, false)

        -- Botn de configuracin de tecla
        do
            local keyFrame = Instance.new("Frame", skbSection)
            keyFrame.Size = UDim2.new(1, -8, 0, 40)
            keyFrame.BackgroundColor3 = Color3.fromRGB(11, 16, 42)
            keyFrame.BackgroundTransparency = 0.3
            keyFrame.BorderSizePixel = 0
            keyFrame.ZIndex = 13
            Instance.new("UICorner", keyFrame).CornerRadius = UDim.new(0, 8)
            local kfStroke = Instance.new("UIStroke", keyFrame)
            kfStroke.Color = Color3.fromRGB(55, 70, 105)
            kfStroke.Thickness = 1.5
            kfStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            local kfLabel = Instance.new("TextLabel", keyFrame)
            kfLabel.Size = UDim2.new(0.45, 0, 1, 0)
            kfLabel.Position = UDim2.new(0, 8, 0, 0)
            kfLabel.BackgroundTransparency = 1
            kfLabel.Text = "Tecla:"
            kfLabel.TextColor3 = Color3.fromRGB(160, 175, 200)
            kfLabel.FontFace = Font.fromEnum(Enum.Font.GothamBold)
            kfLabel.TextSize = 12
            kfLabel.TextXAlignment = Enum.TextXAlignment.Left
            kfLabel.ZIndex = 14

            local kfBtn = Instance.new("TextButton", keyFrame)
            kfBtn.Size = UDim2.new(0, 60, 0, 26)
            kfBtn.Position = UDim2.new(1, -68, 0.5, -13)
            kfBtn.BackgroundColor3 = Color3.fromRGB(160, 20, 35)
            kfBtn.BackgroundTransparency = 0.3
            kfBtn.BorderSizePixel = 0
            kfBtn.Text = "Q"
            kfBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
            kfBtn.FontFace = Font.fromEnum(Enum.Font.Arcade)
            kfBtn.TextSize = 14
            kfBtn.AutoButtonColor = false
            kfBtn.ZIndex = 14
            Instance.new("UICorner", kfBtn).CornerRadius = UDim.new(0, 6)
            local kbStroke = Instance.new("UIStroke", kfBtn)
            kbStroke.Color = Color3.fromRGB( 50, 255, 180)
            kbStroke.Thickness = 1.5
            kbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

            local _listening = false
            local _listenConn = nil

            kfBtn.Activated:Connect(function()
                if _listening then return end
                _listening = true
                kfBtn.Text = "..."
                kfBtn.BackgroundColor3 = Color3.fromRGB(255, 150, 0)
                kbStroke.Color = Color3.fromRGB(255, 210,   0)
                if not UserInputService.TouchEnabled then CreateCustomNotification("SHOOT KEYBIND", "Presion la tecla que quers usar", 2) end

                if _listenConn then pcall(function() _listenConn:Disconnect() end) end
                _listenConn = UserInputService.InputBegan:Connect(function(inp, gp)
                    if gp then return end
                    if inp.UserInputType == Enum.UserInputType.Keyboard then
                        local keyName = tostring(inp.KeyCode):gsub("Enum.KeyCode.", "")
                        -- Ignorar teclas de sistema
                        if keyName == "Escape" or keyName == "Return" or keyName == "Tab" then
                            _listening = false
                            kfBtn.Text = tostring(_skbKey):gsub("Enum.KeyCode.", "")
                            kfBtn.BackgroundColor3 = Color3.fromRGB(160, 20, 35)
                            kbStroke.Color = Color3.fromRGB( 50, 255, 180)
                            pcall(function() _listenConn:Disconnect() end)
                            return
                        end
                        _skbKey = inp.KeyCode
                        kfBtn.Text = keyName
                        kfBtn.BackgroundColor3 = Color3.fromRGB(160, 20, 35)
                        kbStroke.Color = Color3.fromRGB( 50, 255, 180)
                        _listening = false
                        pcall(function() _listenConn:Disconnect() end)
                        if not UserInputService.TouchEnabled then CreateCustomNotification("SHOOT KEYBIND", "Tecla -> " .. keyName, 2) end
                    end
                end)
            end)

            kfBtn.MouseEnter:Connect(function()
                if not _listening then
                    TweenService:Create(kfBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.1}):Play()
                end
            end)
            kfBtn.MouseLeave:Connect(function()
                if not _listening then
                    TweenService:Create(kfBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.3}):Play()
                end
            end)
        end
    end

    -- -----------------------------------------------------------------
    -- SHOOT CONDITION  dispara SA automticamente segn condicin
    -- -----------------------------------------------------------------
    do
        local scSection    = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, "  SHOOT CONDITION") or Instance.new("Frame")
        local _scEnabled   = false
        local _scCondition = "Shoot Wall Check"  -- condicin activa
        local _scConn      = nil
        local _scLastShot  = 0
        local _scCooldown  = 0.3

        local function _scFireSA()
            local now = tick()
            if now - _scLastShot < _scCooldown then return end
            local char = LocalPlayer.Character; if not char then return end
            local myHRP = char:FindFirstChild("HumanoidRootPart"); if not myHRP then return end
            local gun = nil
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") and (t:FindFirstChild("GunClient") or t:FindFirstChild("Shoot")) then
                    gun = t; break
                end
            end
            if not gun then return end
            local shootR = getShootRemote and getShootRemote(gun); if not shootR then return end
            local murder = findMurderer and findMurderer()
            if not murder or not murder.Character then return end
            local tHRP = murder.Character:FindFirstChild("HumanoidRootPart"); if not tHRP then return end
            local gra = myHRP:FindFirstChild("GunRaycastAttachment") or myHRP:FindFirstChildWhichIsA("Attachment")
            local origin = gra and gra.WorldCFrame.Position or (myHRP.Position + Vector3.new(0,1.5,0))
            local aim = tHRP.Position + Vector3.new(0,0.3,0)
            local dir = aim - origin; if dir.Magnitude < 0.01 then return end
            local u = dir.Unit; local up = math.abs(u.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            local graA = CFrame.lookAt(origin, aim, up)
            local bu = -u; local bup = math.abs(bu.Y)>0.98 and Vector3.new(0,0,1) or Vector3.new(0,1,0)
            local tgtA = CFrame.lookAt(aim, aim+bu, bup)
            _scLastShot = now
            if CombatTabState then CombatTabState._saBypassHook = true end
            pcall(function() shootR:FireServer(graA, tgtA) end)
            if CombatTabState then CombatTabState._saBypassHook = false end
        end

        -- -- WALL CHECK -----------------------------------------------
        -- Throttle: solo hace raycast cada 0.08s para no lagguear
        local _lastWallState = true
        local _wallThrottle  = 0
        local function _checkWallCondition(murder, myHRP)
            local now = tick()
            if now - _wallThrottle < 0.08 then return end
            _wallThrottle = now
            local tHRP = murder.Character and murder.Character:FindFirstChild("HumanoidRootPart")
            if not tHRP then return end
            local params = RaycastParams.new()
            params.FilterDescendantsInstances = {LocalPlayer.Character, murder.Character}
            params.FilterType = Enum.RaycastFilterType.Exclude
            local dir = tHRP.Position - myHRP.Position
            local hit = workspace:Raycast(myHRP.Position, dir, params)
            -- behind wall = raycast hit something before reaching murder
            local behindWall = hit ~= nil and hit.Instance ~= nil
            if _lastWallState and not behindWall then
                -- murder acaba de salir de la pared -> disparar
                _sp(_scFireSA)
                CreateCustomNotification("SHOOT CONDITION", "Wall clear  disparando!", 1.5)
            end
            _lastWallState = behindWall
        end

        -- -- KNIFE CONDITION ------------------------------------------
        -- Usar ChildAdded del murder.Character es ms preciso que Heartbeat
        local _lastKnifeState  = false
        local _knifeWatchConn  = nil
        local function _startKnifeWatch()
            if _knifeWatchConn then pcall(function() _knifeWatchConn:Disconnect() end); _knifeWatchConn = nil end
            local murder = findMurderer and findMurderer()
            if not murder then return end
            local function _watchChar(char)
                if not char then return end
                -- Estado inicial
                _lastKnifeState = false
                for _, t in ipairs(char:GetChildren()) do
                    if t:IsA("Tool") and (t:FindFirstChild("KnifeClient") or t.Name:lower():find("knife")) then
                        _lastKnifeState = true; break
                    end
                end
                -- Hook ChildAdded: knife equipado
                local c1 = char.ChildAdded:Connect(function(child)
                    if not _scEnabled or _scCondition ~= "View Knife Shoot" then return end
                    if child:IsA("Tool") and (child:FindFirstChild("KnifeClient") or child.Name:lower():find("knife")) then
                        if not _lastKnifeState then
                            _lastKnifeState = true
                            _w(0.05)  -- esperar un frame para que el server registre
                            _sp(_scFireSA)
                            CreateCustomNotification("SHOOT CONDITION", "Murder equip knife  disparando!", 1.5)
                        end
                    end
                end)
                -- Hook ChildRemoved: knife desequipado
                local c2 = char.ChildRemoved:Connect(function(child)
                    if child:IsA("Tool") and (child:FindFirstChild("KnifeClient") or child.Name:lower():find("knife")) then
                        _lastKnifeState = false
                    end
                end)
                _knifeWatchConn = {c1, c2}
            end
            _watchChar(murder.Character)
            murder.CharacterAdded:Connect(function(char)
                if _scEnabled and _scCondition == "View Knife Shoot" then
                    _w(0.2); _watchChar(char)
                end
            end)
        end

        -- -- GUN PICK CONDITION ---------------------------------------
        -- Hook ChildAdded en el propio Character para detectar cuando agarra la gun
        local _gunPickConn = nil
        local function _startGunPickWatch()
            if _gunPickConn then pcall(function() _gunPickConn:Disconnect() end); _gunPickConn = nil end
            local char = LocalPlayer.Character; if not char then return end
            _gunPickConn = char.ChildAdded:Connect(function(child)
                if not _scEnabled or _scCondition ~= "Pick Gun Shoot" then return end
                if child:IsA("Tool") and (child:FindFirstChild("GunClient") or child:FindFirstChild("Shoot")) then
                    CreateCustomNotification("SHOOT CONDITION", "Gun agarrada  disparando!", 1.5)
                    _w(0.1)  -- pequeo delay para que la gun quede equipada
                    _sp(_scFireSA)
                end
            end)
            -- Tambin re-hookear al respawnear
            LocalPlayer.CharacterAdded:Connect(function(c)
                if _scEnabled and _scCondition == "Pick Gun Shoot" then
                    _w(0.3)
                    if _gunPickConn then pcall(function() _gunPickConn:Disconnect() end) end
                    _gunPickConn = c.ChildAdded:Connect(function(child)
                        if not _scEnabled or _scCondition ~= "Pick Gun Shoot" then return end
                        if child:IsA("Tool") and (child:FindFirstChild("GunClient") or child:FindFirstChild("Shoot")) then
                            _w(0.1); _sp(_scFireSA)
                        end
                    end)
                end
            end)
        end

        local function _stopAllWatchers()
            if _scConn then pcall(function() _scConn:Disconnect() end); _scConn = nil end
            if _knifeWatchConn then
                if type(_knifeWatchConn) == "table" then
                    for _, c in ipairs(_knifeWatchConn) do pcall(function() c:Disconnect() end) end
                end
                _knifeWatchConn = nil
            end
            if _gunPickConn then pcall(function() _gunPickConn:Disconnect() end); _gunPickConn = nil end
        end

        local function _startConditionLoop()
            _stopAllWatchers()
            _lastWallState = true; _lastKnifeState = false; _wallThrottle = 0

            if _scCondition == "Shoot Wall Check" then
                -- Wall check usa Heartbeat con throttle
                local _scTick = 0
                _scConn = _safeConnect(RunService.Heartbeat, function()
                    _scTick = _scTick + 1; if _scTick < 6 then return end; _scTick = 0  -- OPT: 10Hz para wall check
                    if not _scEnabled then return end
                    local char = LocalPlayer.Character; if not char then return end
                    local myHRP = char:FindFirstChild("HumanoidRootPart"); if not myHRP then return end
                    local murder = findMurderer and findMurderer()
                    if murder and murder.Character then
                        _checkWallCondition(murder, myHRP)
                    end
                end)
            elseif _scCondition == "View Knife Shoot" then
                -- Knife watch usa ChildAdded del char del murder
                _startKnifeWatch()
            elseif _scCondition == "Pick Gun Shoot" then
                -- Gun pick usa ChildAdded del propio char
                _startGunPickWatch()
            end
        end

        CreateAuroraToggle(scSection, "Shoot Condition", function(on)
            _scEnabled = on
            if on then
                _startConditionLoop()
                -- [notif removed]
            else
                _stopAllWatchers()
                -- [notif removed]
            end
        end, false)

        -- Selector: al cambiar condicin, reiniciar watchers si est activo
        CreateNebulaSelector(scSection, "Shoot Condition", {
            "Shoot Wall Check",
            "View Knife Shoot",
            "Pick Gun Shoot"
        }, "Shoot Wall Check", function(sel)
            _scCondition = sel
            if _scEnabled then
                _startConditionLoop()
            end
            CreateCustomNotification("SHOOT CONDITION", "Condicin -> " .. sel, 2)
        end)

        -- Descripcin de cada condicin
        do
            local descBox = Instance.new("Frame", scSection)
            descBox.Size = UDim2.new(1,-8,0,0); descBox.AutomaticSize = Enum.AutomaticSize.Y
            descBox.BackgroundColor3 = Color3.fromRGB(11,16,42); descBox.BackgroundTransparency = 0.4
            descBox.BorderSizePixel = 0; descBox.ZIndex = 13
            Instance.new("UICorner", descBox).CornerRadius = UDim.new(0,8)
            local pad = Instance.new("UIPadding", descBox)
            pad.PaddingLeft = UDim.new(0,8); pad.PaddingRight = UDim.new(0,8)
            pad.PaddingTop = UDim.new(0,5); pad.PaddingBottom = UDim.new(0,5)
            local dTxt = Instance.new("TextLabel", descBox)
            dTxt.Size = UDim2.new(1,0,0,0); dTxt.AutomaticSize = Enum.AutomaticSize.Y
            dTxt.BackgroundTransparency = 1; dTxt.ZIndex = 14
            dTxt.Text = "Wall Check: dispara cuando el murder sale de cobertura\nKnife Shoot: dispara cuando equipa el knife\nGun Pick: dispara cuando agarras el GunDrop"
            dTxt.TextColor3 = Color3.fromRGB(160,180,210); dTxt.FontFace = Font.fromEnum(Enum.Font.Code)
            dTxt.TextSize = 10; dTxt.TextWrapped = true; dTxt.TextXAlignment = Enum.TextXAlignment.Left
        end
    end




        -- SECCIN AIMLOCK  rightColumn
    -- =============================================
    do
        local _aimlockSection = (CreateBorderedSection and rightColumn) and CreateBorderedSection(rightColumn, " AIMLOCK") or Instance.new("Frame")

        -- Estado global persistente
        _G._aimlockState = _G._aimlockState or {
            aimlock        = false,
            aimlockGun     = false,
            aimlockFov     = false,
            fovConn        = nil,
            fovGui         = nil,
            fovCircle      = nil,
        }
        local ALS = _G._aimlockState

        -- Helper: obtener Murder o target vlido (con wall check y skip si yo soy Murder)
        local function _getAimlockTarget()
            -- No apuntar si el jugador local es el Murder
            local myRole = _roleCache and _roleCache.localRole or "Innocent"
            if myRole == "Murder" or myRole == "Murderer" then return nil end

            local m = findMurderer and findMurderer()
            if m and m.Character then
                local head = m.Character:FindFirstChild("Head")
                local hrp  = m.Character:FindFirstChild("HumanoidRootPart")
                local target = head or hrp
                if not target then return nil end
                -- Wall Check: no apuntar si hay pared de por medio
                local myChar = LocalPlayer.Character
                local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if myHRP and not (ALS.noWallCheck) then
                    -- Solo verificar wall check si NO est activo el No Wall Check
                    local hasLOS = wallCheckRaycast and wallCheckRaycast(myHRP.Position, target.Position)
                    if not hasLOS then return nil end
                end
                return target
            end
            return nil
        end

        -- Helper: detectar si el jugador tiene gun equipada (Tool con "Gun" o "Pistol" en nombre)
        local function _hasGunEquipped()
            local char = LocalPlayer.Character
            if not char then return false end
            for _, tool in ipairs(char:GetChildren()) do
                if tool:IsA("Tool") then
                    local n = tool.Name:lower()
                    if n:find("gun") or n:find("pistol") or n:find("revolver") then
                        return true
                    end
                end
            end
            return false
        end

        -- -- TOGGLE 1: Aimlock --------------------------------------------
        -- Mientras Shift Lock est activo, redirige la cmara al Murder
        CreateBorderedToggle(_aimlockSection, "Aimlock", function(enabled)
            ALS.aimlock = enabled
            if ALS._conn1 then
                pcall(function() ALS._conn1:Disconnect() end)
                ALS._conn1 = nil
            end
            if not enabled then return end
            local _als1T = 0
            ALS._conn1 = RunService.RenderStepped:Connect(function(dt)
                _als1T = _als1T + dt; if _als1T < 0.016 then return end; _als1T = 0
                if not ALS.aimlock then return end
                local isShiftLock = pcall(function()
                    return UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter
                end) and UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter
                if not isShiftLock then return end
                local target = _getAimlockTarget()
                if not target or not target.Parent then return end
                pcall(function()
                    local cam = workspace.CurrentCamera
                    local targetPos = target.Position
                    local camPos    = cam.CFrame.Position
                    cam.CFrame = CFrame.new(camPos, targetPos)
                end)
            end)
        end, false)

        -- -- TOGGLE 2: Aimlock Gun ----------------------------------------
        -- Igual que Aimlock pero SOLO cuando el jugador tenga gun equipada
        CreateBorderedToggle(_aimlockSection, "Aimlock Gun", function(enabled)
            ALS.aimlockGun = enabled
            if ALS._conn2 then
                pcall(function() ALS._conn2:Disconnect() end)
                ALS._conn2 = nil
            end
            if not enabled then return end
            local _als2T = 0
            ALS._conn2 = RunService.RenderStepped:Connect(function(dt)
                _als2T = _als2T + dt; if _als2T < 0.016 then return end; _als2T = 0
                if not ALS.aimlockGun then return end
                local isShiftLock = UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter
                if not isShiftLock then return end
                if not _hasGunEquipped() then return end
                local target = _getAimlockTarget()
                if not target or not target.Parent then return end
                pcall(function()
                    local cam = workspace.CurrentCamera
                    cam.CFrame = CFrame.new(cam.CFrame.Position, target.Position)
                end)
            end)
        end, false)

        -- -- TOGGLE 3: Aimlock No Wall Check ------------------------------
        -- El aimlock sigue al target aunque est detrs de paredes
        CreateBorderedToggle(_aimlockSection, "Aimlock No Wall Check", function(enabled)
            ALS.noWallCheck = enabled
            CreateCustomNotification("AIMLOCK", enabled and "No Wall Check ON  sigue detrs de paredes" or "No Wall Check OFF", 2)
        end, ALS.noWallCheck or false)

