    -- Funcin helper slider de prediccin
    function CreatePredSlider(parent, title, minVal, maxVal, defaultVal, callback)
        -- ==============================================================
        --  PRED SLIDER  misma apariencia que CreateSlider
        --  Panel cristal con gradiente diagonal  borde aurora shimmer
        -- ==============================================================
        local C_STROKE   = ThemeColors.Primary
        local C_TEXT     = ThemeColors.TextPrimary
        local C_SUBTEXT  = ThemeColors.TextSecondary
        local C_TRACK_BG = ThemeColors.Aurora2
        local C_TRACK_FG = ThemeColors.Primary
        local C_THUMB    = ThemeColors.Accent

        local STEP = 0.01
        local CONTAINER_H = 44   -- igual que CreateSlider

        -- -- CONTENEDOR PRINCIPAL  glassmorphism idntico a CreateSlider --
        local container = Instance.new("Frame", parent)
        container.Name                   = "PredSliderWrapper_" .. title
        container.Size                   = UDim2.new(1, -4, 0, CONTAINER_H)

        container.BackgroundTransparency = 1
        container.BorderSizePixel        = 0
        container.ClipsDescendants       = false
        container.ZIndex                 = 10























        local titleLabel = Instance.new("TextLabel", container)
        titleLabel.Size = UDim2.new(1, -90, 0, 18); titleLabel.Position = UDim2.new(0, 10, 0, 6)
        titleLabel.BackgroundTransparency = 1; titleLabel.Text = title
        titleLabel.TextXAlignment = Enum.TextXAlignment.Left; titleLabel.TextYAlignment = Enum.TextYAlignment.Center
        titleLabel.TextColor3 = C_TEXT; titleLabel.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        titleLabel.TextSize = 13; titleLabel.TextTruncate = Enum.TextTruncate.AtEnd; titleLabel.ZIndex = 12

        local valBox = Instance.new("Frame", container)
        valBox.Size = UDim2.new(0, 58, 0, 20); valBox.Position = UDim2.new(0, 10, 0, 28)
        valBox.BackgroundColor3 = ThemeColors.BackgroundLight; valBox.BackgroundTransparency = 0.10
        valBox.BorderSizePixel = 0; valBox.ZIndex = 12
        Instance.new("UICorner", valBox).CornerRadius = UDim.new(0, 5)
        local vbStroke = Instance.new("UIStroke", valBox)
        vbStroke.Color = ThemeColors.Primary; vbStroke.Thickness = 1
        vbStroke.Transparency = 0.4; vbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local valueLabel = Instance.new("TextLabel", valBox)
        valueLabel.Size = UDim2.new(1, 0, 1, 0); valueLabel.BackgroundTransparency = 1
        valueLabel.Text = string.format("%.2f", defaultVal)
        valueLabel.TextXAlignment = Enum.TextXAlignment.Center; valueLabel.TextYAlignment = Enum.TextYAlignment.Center
        valueLabel.TextColor3 = C_TEXT; valueLabel.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        valueLabel.TextSize = 12; valueLabel.ZIndex = 13

        local subtitleLabel = Instance.new("TextLabel", container)
        subtitleLabel.Name = "SubtitleLabel"
        subtitleLabel.Size = UDim2.new(0, 80, 0, 12); subtitleLabel.Position = UDim2.new(0, 10, 1, -14)
        subtitleLabel.BackgroundTransparency = 1; subtitleLabel.Text = tostring(minVal) .. "  " .. tostring(maxVal)
        subtitleLabel.TextXAlignment = Enum.TextXAlignment.Left; subtitleLabel.TextYAlignment = Enum.TextYAlignment.Center
        subtitleLabel.TextColor3 = C_SUBTEXT; subtitleLabel.FontFace = Font.fromEnum(Enum.Font.Montserrat)
        subtitleLabel.TextSize = 10; subtitleLabel.ZIndex = 12

        local sliderTrack = Instance.new("Frame", container)
        sliderTrack.Name = "SliderTrack"
        sliderTrack.Size = UDim2.new(1, -20, 0, 2); sliderTrack.Position = UDim2.new(0, 10, 0, 36)
        sliderTrack.BackgroundColor3 = C_TRACK_BG; sliderTrack.BackgroundTransparency = 0.40
        sliderTrack.BorderSizePixel = 0; sliderTrack.ClipsDescendants = false; sliderTrack.ZIndex = 12
        Instance.new("UICorner", sliderTrack).CornerRadius = UDim.new(1, 0)




        local initPct = math.clamp((defaultVal - minVal) / math.max(0.001, maxVal - minVal), 0, 1)
        local sliderFill = Instance.new("Frame", sliderTrack)
        sliderFill.Name = "FillBar"
        sliderFill.Size = UDim2.new(initPct, 0, 1, 0); sliderFill.BackgroundColor3 = C_TRACK_FG
        sliderFill.BackgroundTransparency = 0.0; sliderFill.BorderSizePixel = 0; sliderFill.ZIndex = 13
        Instance.new("UICorner", sliderFill).CornerRadius = UDim.new(1, 0)

        local sliderThumb = Instance.new("ImageButton", sliderTrack)
        sliderThumb.Size = UDim2.new(0, 8, 0, 8); sliderThumb.AnchorPoint = Vector2.new(0.5, 0.5)
        sliderThumb.Position = UDim2.new(initPct, 0, 0.5, 0); sliderThumb.BackgroundColor3 = C_THUMB
        sliderThumb.BackgroundTransparency = 0.35; sliderThumb.BorderSizePixel = 0; sliderThumb.ZIndex = 15
        Instance.new("UICorner", sliderThumb).CornerRadius = UDim.new(1, 0)
        local thumbStroke = Instance.new("UIStroke", sliderThumb)
        thumbStroke.Color = ThemeColors.Primary; thumbStroke.Thickness = 0.8
        thumbStroke.Transparency = 0.10; thumbStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        local draggingS = false
        local function applyValue(v)
            v = math.clamp(math.floor(v / STEP + 0.5) * STEP, minVal, maxVal)
            local ratio = math.clamp((v - minVal) / math.max(maxVal - minVal, 0.001), 0, 1)
            sliderThumb.Position = UDim2.new(ratio, 0, 0.5, 0); sliderFill.Size = UDim2.new(ratio, 0, 1, 0)
            valueLabel.Text = string.format("%.2f", v); if callback then callback(v) end
        end
        local function updateFromInput(inp)
            local mx = inp and inp.UserInputType == Enum.UserInputType.Touch and inp.Position.X or UserInputService:GetMouseLocation().X
            local tp = sliderTrack.AbsolutePosition.X; local ts = sliderTrack.AbsoluteSize.X
            applyValue(minVal + math.clamp((mx - tp) / math.max(ts, 1), 0, 1) * (maxVal - minVal))
        end
        local function updateFromMouse() updateFromInput(nil) end
        sliderThumb.MouseEnter:Connect(function() TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 22, 0, 22)}):Play() end)
        sliderThumb.MouseLeave:Connect(function() if not draggingS then TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 18, 0, 18)}):Play() end end)
        sliderThumb.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingS = true; _G._sliderDragging = true; TweenService:Create(sliderThumb, TweenInfo.new(0.08), {Size = UDim2.new(0, 22, 0, 22)}):Play()
            end
        end)
        sliderTrack.InputBegan:Connect(function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then draggingS = true; _G._sliderDragging = true; updateFromInput(i) end end)
        RegisterTabConn(UserInputService.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                draggingS = false; _G._sliderDragging = false; TweenService:Create(sliderThumb, TweenInfo.new(0.10), {Size = UDim2.new(0, 18, 0, 18)}):Play()
            end
        end))
        RegisterTabConn(UserInputService.InputChanged:Connect(function(i)
            if draggingS and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then updateFromInput(i) end
        end))
        applyValue(defaultVal)
        _attachScrollPassthrough(container, sliderTrack, sliderThumb)
        return container
    end

