    -- ======================================================================
    -- SHOW LEAD TIME TRACER  lnea roja desde el arma al punto de impacto
    -- ======================================================================
    do
        _G._leadTracer = _G._leadTracer or {
            enabled = false,
            line    = nil,
            conn    = nil,
        }
        local LT = _G._leadTracer

        local function _ltGetOrigin()
            local char = LocalPlayer.Character
            if not char then return nil end
            -- Intentar barrel del arma primero
            local gun = _findGunIn and _findGunIn(char)
            if gun then
                local barrel = gun:FindFirstChild("Barrel")
                           or gun:FindFirstChildWhichIsA("Attachment")
                if barrel then
                    return barrel.WorldPosition
                end
                local handle = gun:FindFirstChild("Handle")
                if handle then return handle.Position end
            end
            -- Fallback: cmara
            local cam = _Camera
            if cam then return cam.CFrame.Position end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            return hrp and (hrp.Position + Vector3.new(0, 1.5, 0))
        end

        local function _ltGetPredictedPos()
            -- Usar el solver completo para mayor precisin
            local target = nil
            if CombatTabState and CombatTabState.silentAimEnabled then
                target = findMurderer and findMurderer()
            end
            if not target then
                -- Buscar cualquier target enemigo cercano
                local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if myHRP then
                    local best, bestDist = nil, math.huge
                    for _, p in ipairs(_cachedPlayers) do
                        if p ~= LocalPlayer and p.Character then
                            local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                            local hum = p.Character:FindFirstChildOfClass("Humanoid")
                            if hrp and hum and hum.Health > 0 then
                                local d = (hrp.Position - myHRP.Position).Magnitude
                                if d < bestDist then bestDist = d; best = p end
                            end
                        end
                    end
                    target = best
                end
            end
            if not target or not target.Character then return nil end
            local hrp = target.Character:FindFirstChild("HumanoidRootPart")
            local part = target.Character:FindFirstChild(
                (CombatTabState and CombatTabState.saTargetPart) or "Head"
            ) or hrp
            if not hrp or not part then return nil end
            -- Calcular posicin predicha con ping + velocidad
            local rawVel = hrp.AssemblyLinearVelocity or Vector3.new()
            local _pms = 60
            pcall(function() _pms = math.clamp(LocalPlayer:GetNetworkPing() * 1000, 5, 400) end)
            local ema = _G._pingEMA or _pms
            local tof = math.max(ema / 1000 + 1/60, 0.016)
            -- Lead bsico: pos + vel * tof (ms estable visualmente que el solver full)
            local hrpToTarget = part.Position - hrp.Position
            local predicted = Vector3.new(
                hrp.Position.X + rawVel.X * tof,
                hrp.Position.Y + rawVel.Y * tof,
                hrp.Position.Z + rawVel.Z * tof
            ) + hrpToTarget
            return predicted
        end

        local function _ltWorldToScreen(pos)
            local cam = _Camera
            if not cam then return nil, false end
            local ok, sv, onScreen = pcall(function()
                return cam:WorldToViewportPoint(pos)
            end)
            if ok and onScreen then
                return Vector2.new(sv.X, sv.Y), true
            end
            return nil, false
        end

        local function _ltStop()
            if LT.conn then LT.conn:Disconnect(); LT.conn = nil end
            if LT.line then
                pcall(function() LT.line.Visible = false end)
            end
        end

        local function _ltStart()
            if LT.conn then return end
            -- Crear lnea Drawing (roja)
            if not LT.line then
                local ln = Drawing.new("Line")
                ln.Thickness = 2
                ln.Color     = Color3.fromRGB(255, 50, 50)
                ln.Transparency = 0.15
                ln.Visible   = false
                LT.line = ln
            end
            local _ltHbT = 0
            LT.conn = RunService.Heartbeat:Connect(function()
                _ltHbT = _ltHbT + 1; if _ltHbT < 4 then return end; _ltHbT = 0
                if not LT.enabled then _ltStop(); return end
                -- FIX: no correr el tracer durante el frame del disparo
                if _saLastShot and (os.clock() - _saLastShot) < 0.15 then return end
                if _G._visualRoundOver then LT.line.Visible = false; return end

                local originW = _ltGetOrigin()
                local targetW = _ltGetPredictedPos()

                if not originW or not targetW then
                    LT.line.Visible = false
                    return
                end

                local originS, onO = _ltWorldToScreen(originW)
                local targetS, onT = _ltWorldToScreen(targetW)

                if originS and targetS then
                    LT.line.From    = originS
                    LT.line.To      = targetS
                    LT.line.Visible = true
                else
                    LT.line.Visible = false
                end
            end)
        end


        -- Limpiar al destruir la seccin
        predSection.AncestryChanged:Connect(function()
            if not predSection.Parent then
                _ltStop()
                if LT.line then
                    pcall(function() LT.line:Remove() end)
                    LT.line = nil
                end
            end
        end)
    end

    -- =============================================
    -- SHOOT DISTANCE -- rightColumn
    -- Auto-dispara al Murder cuando entra en rango de distancia
    -- =============================================
    do
        local _sdSection = (CreateBorderedSection and rightColumn)
            and CreateBorderedSection(rightColumn, "  SHOOT DISTANCE")
            or Instance.new("Frame")

        _G._sdState = _G._sdState or {
            enabled  = false,
            distance = 30,
            rsConn   = nil,
            lastShot = 0,
        }
        local SD = _G._sdState

        local function _sdStop()
            if SD.rsConn then
                pcall(function() SD.rsConn:Disconnect() end)
                SD.rsConn = nil
            end
        end

        local function _sdStart()
            _sdStop()
            SD.rsConn = RunService.Heartbeat:Connect(function()
                if not SD.enabled then return end
                local now = tick()
                if now - SD.lastShot < 0.35 then return end

                local myChar = LocalPlayer.Character
                local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
                if not myHRP or not myHum or myHum.Health <= 0 then return end

                local murderer = findMurderer and findMurderer()
                if not murderer or not murderer.Character then return end

                local mHRP  = murderer.Character:FindFirstChild("HumanoidRootPart")
                local mHead = murderer.Character:FindFirstChild("Head")
                if not mHRP then return end

                local dist = (myHRP.Position - mHRP.Position).Magnitude
                if dist > SD.distance then return end

                -- Encontrar gun
                local gun = _findGun and _findGun(myChar)
                if not gun then return end

                SD.lastShot = now

                -- Calcular posicion predicha con Silent Aim (mismo sistema que el SA principal)
                local tPart = mHead or mHRP
                local targetPos = nil
                if _unifiedBalisticSolver then
                    local predicted = _unifiedBalisticSolver(tPart, mHRP, {
                        usePrediction = true,
                        predictJump   = true,
                        predictAccel  = true,
                        predictTrend  = true,
                        predictLag    = true,
                        predictStrafe = true,
                    }, murderer)
                    if predicted and predicted == predicted
                    and (predicted - mHRP.Position).Magnitude < 120 then
                        targetPos = predicted
                    end
                end
                targetPos = targetPos or tPart.Position

                -- Origen del disparo (barrel attachment via global getGunAttachment)
                local barrelAtt = getGunAttachment and getGunAttachment(gun, myHRP) or nil
                local cam = _Camera
                local originPos = (barrelAtt and barrelAtt.WorldPosition)
                    or (cam and cam.CFrame.Position)
                    or (myHRP.Position + Vector3.new(0, 1.5, 0))
                local graWorldCF = barrelAtt and barrelAtt.WorldCFrame

                -- Construir CFrames con buildShootCFrames (igual que Silent Aim)
                local oCF, tCF = buildShootCFrames(originPos, targetPos, graWorldCF)
                if not oCF or not tCF then return end

                -- Buscar RemoteEvent Shoot con la funci?n global (m?s robusta)
                local shootRem = getShootRemote and getShootRemote(gun)
                if not shootRem then
                    shootRem = gun:FindFirstChild("Shoot")
                    if not shootRem then
                        for _, v in ipairs(gun:GetDescendants()) do
                            if v:IsA("RemoteEvent") then shootRem = v; break end
                        end
                    end
                end

                if shootRem and shootRem:IsA("RemoteEvent") then
                    local graAtt  = getGunAttachment and getGunAttachment(gun, myHRP)
                    local graCF   = (graAtt and graAtt.WorldCFrame) or oCF
                    if CombatTabState then CombatTabState._saBypassHook = true end
                    pcall(function() shootRem:FireServer(graCF, tCF) end)
                    if CombatTabState then CombatTabState._saBypassHook = false end
                elseif _fireGunMM2 then
                    local origCamCF = cam and cam.CFrame
                    pcall(function() cam.CFrame = CFrame.lookAt(cam.CFrame.Position, targetPos) end)
                    _fireGunMM2(gun)
                    pcall(function() cam.CFrame = origCamCF end)
                end
            end)
        end

        -- Toggle principal
        CreateBorderedToggle(_sdSection, "Shoot Distance", function(enabled)
            SD.enabled = enabled
            if enabled then
                _sdStart()
                -- [notif removed]
            else
                _sdStop()
                -- [notif removed]
            end
        end, false)

        -- Slider de distancia
        CreateSlider(_sdSection, "Shoot distance (studs)", 5, 500, SD.distance or 100, function(v)
            SD.distance = v
        end)

        -- Limpiar al cambiar de pesta?a
        _sdSection.AncestryChanged:Connect(function()
            if not _sdSection.Parent then
                _sdStop()
            end
        end)
    end
    -- =============================================

    -- =============================================
    -- HEADER VISUAL: GUN (columna derecha)
    -- =============================================
    do
        local _gunHeaderR = Instance.new("Frame", rightColumn)
        _gunHeaderR.Size = UDim2.new(1, -10, 0, 36)
        _gunHeaderR.BackgroundColor3 = ThemeColors.Primary
        _gunHeaderR.BackgroundTransparency = 0.72
        _gunHeaderR.BorderSizePixel = 0
        _gunHeaderR.ZIndex = 12
        Instance.new("UICorner", _gunHeaderR).CornerRadius = UDim.new(0, 8)
        local _ghrStroke = Instance.new("UIStroke", _gunHeaderR)
        _ghrStroke.Color = ThemeColors.Primary
        _ghrStroke.Thickness = 2
        _ghrStroke.Transparency = 0.1
        local _ghrLbl = Instance.new("TextLabel", _gunHeaderR)
        _ghrLbl.Size = UDim2.new(1, -16, 1, 0)
        _ghrLbl.Position = UDim2.new(0, 8, 0, 0)
        _ghrLbl.BackgroundTransparency = 1
        _ghrLbl.Text = " GUN"
        _ghrLbl.TextColor3 = ThemeColors.Primary
        _ghrLbl.Font = Enum.Font.Montserrat
        _ghrLbl.TextSize = 16
        _ghrLbl.TextXAlignment = Enum.TextXAlignment.Left
        _ghrLbl.ZIndex = 13
    end

    end  -- close TK SILENT AIM do

    -- ======================================================================
    -- SECCI?N: GUN UTILITIES ? Bullet Tracer, Trajectory Info, Auto-Equip Smart
    -- ======================================================================
    do
        _currentMainSectionFrame = nil
        local _guCol = rightColumn or leftColumn or contentContainer
        local _gunUtilSection = CreateBorderedSection(_guCol, " GUN UTILITIES")

        -- Estado persistente
        CombatTabState._gunUtil = CombatTabState._gunUtil or {
            _btLiveEnabled   = false,
            _btLiveLine      = nil,
            _btLiveConn      = nil,
            trajEnabled      = false,
            _trajConn        = nil,
            _trajLine        = nil,
            _trajLabel       = nil,
            autoEquipRange   = false,
            equippingRange   = 80,
            _autoEquipConn   = nil,
            _onlyEquipRange  = 30,
        }
        local GU = CombatTabState._gunUtil
        -- FIX AUTO-RESTORE: sincronizar campos enabled desde _G._toggleStates (disco)
        do
            local _tsGU = _G._toggleStates or {}
            GU._btLiveEnabled = _tsGU["Bullet Tracer"]                 == true or false
            GU.trajEnabled    = _tsGU["Trajectory Info"]               == true or false
            GU.autoEquipRange = _tsGU["Auto Equip Gun (Murder en rango)"] == true or false
        end

        -- =====================================================================
        -- BULLET TRACER ? l?nea roja en tiempo real desde Gun ? Murder
        -- =====================================================================
        do
            local function _btStop()
                if GU._btLiveConn then
                    pcall(function() GU._btLiveConn:Disconnect() end)
                    GU._btLiveConn = nil
                end
                if GU._btLiveLine then
                    pcall(function() GU._btLiveLine.Visible = false end)
                end
            end

            local function _btStart()
                _btStop()
                if not GU._btLiveLine then
                    local ln = Drawing.new("Line")
                    ln.Visible      = false
                    ln.Color        = Color3.fromRGB(255, 40, 40)
                    ln.Thickness    = 2
                    ln.Transparency = 0.15
                    ln.ZIndex       = 5
                    GU._btLiveLine = ln
                end
                local line = GU._btLiveLine
                local _hbt = 0
                GU._btLiveConn = RunService.Heartbeat:Connect(function()
                    _hbt = _hbt + 1; if _hbt < 3 then return end; _hbt = 0
                    if not GU._btLiveEnabled then line.Visible = false; return end
                    if _G._visualRoundOver then line.Visible = false; return end

                    local char = LocalPlayer.Character
                    local cam  = workspace.CurrentCamera
                    if not char or not cam then line.Visible = false; return end

                    -- Solo activo si el jugador tiene la Gun equipada en mano
                    local gunTool = _findGunIn and _findGunIn(char)
                    if not gunTool then line.Visible = false; return end
                    local gunHandle = gunTool:FindFirstChild("Handle")
                    if not gunHandle then line.Visible = false; return end

                    local target = (_G._getEffectiveTarget and _G._getEffectiveTarget())
                               or (findMurderer and findMurderer())
                    if not target then line.Visible = false; return end
                    local tChar = target.Character
                    local tHRP  = tChar and (tChar:FindFirstChild("HumanoidRootPart") or tChar:FindFirstChild("Torso"))
                    if not tHRP then line.Visible = false; return end

                    local fromSc, ok1 = cam:WorldToViewportPoint(gunHandle.Position)
                    local toSc,   ok2 = cam:WorldToViewportPoint(tHRP.Position)
                    if not ok1 and not ok2 then line.Visible = false; return end

                    line.Visible = true
                    line.From    = Vector2.new(fromSc.X, fromSc.Y)
                    line.To      = Vector2.new(toSc.X,   toSc.Y)
                end)
            end

            CreateBorderedToggle(_gunUtilSection, "Bullet Tracer", function(enabled)
                GU._btLiveEnabled = enabled
                if enabled then
                    _btStart()
                    CreateCustomNotification("BULLET TRACER", " L?nea roja Gun ? Murder activada", 2)
                else
                    _btStop()
                    CreateCustomNotification("BULLET TRACER", " Tracer desactivado", 1.5)
                end
            end, false)

            do
                local d = Instance.new("TextLabel", _gunUtilSection)
                d.Size = UDim2.new(1, -8, 0, 0); d.AutomaticSize = Enum.AutomaticSize.Y
                d.BackgroundTransparency = 1
                d.Text = "Draws a red line in real time from your weapon to the Murder. Always visible while you have the gun equipped."
                d.TextColor3 = Color3.fromRGB(255, 100, 100)
                d.Font = Enum.Font.Montserrat; d.TextSize = 10
                d.TextWrapped = true; d.TextXAlignment = Enum.TextXAlignment.Left; d.ZIndex = 13
                local p = Instance.new("UIPadding", d)
                p.PaddingLeft = UDim.new(0,6); p.PaddingRight = UDim.new(0,6)
                p.PaddingTop  = UDim.new(0,2); p.PaddingBottom = UDim.new(0,4)
            end
        end

        -- =====================================================================
        -- TRAJECTORY INFO ? panel con distancia, velocidad y tiempo de vuelo
        -- =====================================================================
        do
            local function _tjStop()
                if GU._trajConn  then pcall(function() GU._trajConn:Disconnect() end);  GU._trajConn  = nil end
                if GU._trajLabel then pcall(function() GU._trajLabel:Destroy() end);     GU._trajLabel = nil end
                if GU._trajLine  then pcall(function() GU._trajLine:Destroy() end);      GU._trajLine  = nil end
            end

            local function _tjStart()
                _tjStop()

                -- ScreenGui
                local sg = Instance.new("ScreenGui")
                sg.Name           = "TrajectoryInfoGui"
                sg.ResetOnSpawn   = false
                sg.IgnoreGuiInset = true
                sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                sg.DisplayOrder   = 9800
                pcall(function() sg.Parent = CoreGui end)
                if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end

                -- Frame contenedor
                local fr = Instance.new("Frame", sg)
                fr.AnchorPoint         = Vector2.new(0.5, 0)
                fr.Position            = UDim2.new(0.5, 0, 0.08, 0)
                fr.Size                = UDim2.new(0, 260, 0, 0)
                fr.AutomaticSize       = Enum.AutomaticSize.Y
                fr.BackgroundColor3    = Color3.fromRGB(10, 10, 18)
                fr.BackgroundTransparency = 0.12
                fr.BorderSizePixel     = 0
                fr.ZIndex              = 9801
                Instance.new("UICorner", fr).CornerRadius = UDim.new(0, 10)
                -- FIX: usar ThemeColors.Primary para que el borde cambie con el tema del hub
                local frs = Instance.new("UIStroke", fr)
                frs.Color = ThemeColors.Primary; frs.Thickness = 1.5; frs.Transparency = 0.2
                local frl = Instance.new("UIListLayout", fr)
                frl.Padding = UDim.new(0, 2); frl.FillDirection = Enum.FillDirection.Vertical
                local frp = Instance.new("UIPadding", fr)
                frp.PaddingTop = UDim.new(0,6); frp.PaddingBottom = UDim.new(0,6)
                frp.PaddingLeft = UDim.new(0,8); frp.PaddingRight = UDim.new(0,8)

                -- FIX DRAG: hacer el panel arrastrable igual que el Information Panel
                do
                    local _tjDragging = false
                    local _tjDragStart = nil
                    local _tjFrameStart = nil
                    local _tjUIS = game:GetService("UserInputService")
                    -- Intentar UIDragDetector primero (ejecutores modernos)
                    local _tjDDOk = pcall(function()
                        local _tjDD = Instance.new("UIDragDetector", fr)
                        _tjDD.DragStyle     = Enum.UIDragDetectorDragStyle.TranslatePlane
                        _tjDD.ResponseStyle = Enum.UIDragDetectorResponseStyle.CustomWithFallback
                        _tjDD.Dragged:Connect(function()
                            local vp = workspace.CurrentCamera.ViewportSize
                            fr.Position = UDim2.fromOffset(
                                math.clamp(fr.Position.X.Offset, 0, vp.X - fr.AbsoluteSize.X),
                                math.clamp(fr.Position.Y.Offset, 0, vp.Y - fr.AbsoluteSize.Y))
                        end)
                    end)
                    if not _tjDDOk then
                        -- Fallback manual (ejecutores sin UIDragDetector)
                        fr.InputBegan:Connect(function(input)
                            if input.UserInputType == Enum.UserInputType.MouseButton1
                            or input.UserInputType == Enum.UserInputType.Touch then
                                _tjDragging   = true
                                _tjDragStart  = input.Position
                                _tjFrameStart = Vector2.new(fr.Position.X.Offset, fr.Position.Y.Offset)
                            end
                        end)
                        fr.InputEnded:Connect(function(input)
                            if input.UserInputType == Enum.UserInputType.MouseButton1
                            or input.UserInputType == Enum.UserInputType.Touch then
                                _tjDragging = false
                            end
                        end)
                        _tjUIS.InputChanged:Connect(function(input)
                            if not _tjDragging then return end
                            if input.UserInputType ~= Enum.UserInputType.MouseMovement
                            and input.UserInputType ~= Enum.UserInputType.Touch then return end
                            local delta = input.Position - _tjDragStart
                            local vp    = workspace.CurrentCamera.ViewportSize
                            fr.Position = UDim2.fromOffset(
                                math.clamp(_tjFrameStart.X + delta.X, 0, vp.X - fr.AbsoluteSize.X),
                                math.clamp(_tjFrameStart.Y + delta.Y, 0, vp.Y - fr.AbsoluteSize.Y))
                        end)
                    end
                end

                -- T?tulo
                local title = Instance.new("TextLabel", fr)
                title.Size = UDim2.new(1, 0, 0, 22); title.BackgroundTransparency = 1
                -- FIX: usar ThemeColors.Primary para que el t?tulo respete el tema del hub
                title.Text = " ? TRAJECTORY INFO"; title.TextColor3 = ThemeColors.Primary
                title.Font = Enum.Font.Montserrat; title.TextSize = 13
                title.TextXAlignment = Enum.TextXAlignment.Left; title.ZIndex = 9802

                -- Etiqueta de stats
                local lbl = Instance.new("TextLabel", fr)
                lbl.Size = UDim2.new(1, 0, 0, 0); lbl.AutomaticSize = Enum.AutomaticSize.Y
                lbl.BackgroundTransparency = 1
                lbl.Text = "Calculando..."
                lbl.TextColor3 = Color3.fromRGB(200, 230, 255)
                lbl.Font = Enum.Font.Montserrat; lbl.TextSize = 11
                lbl.TextWrapped = true; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.ZIndex = 9802
                GU._trajLabel = lbl

                -- Loop de actualizaci?n
                local _tjHb = 0
                GU._trajConn = RunService.Heartbeat:Connect(function()
                    _tjHb = _tjHb + 1; if _tjHb < 6 then return end; _tjHb = 0
                    if not GU.trajEnabled or not sg.Parent then
                        pcall(function() sg:Destroy() end); return
                    end
                    local char = LocalPlayer.Character
                    if not char then lbl.Text = "Sin personaje"; return end
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if not hrp then lbl.Text = "Sin HRP"; return end

                    local target = (_G._getEffectiveTarget and _G._getEffectiveTarget())
                               or (findMurderer and findMurderer())
                    if not target then lbl.Text = "Sin target"; return end
                    local tChar = target.Character
                    local tHRP  = tChar and (tChar:FindFirstChild("HumanoidRootPart") or tChar:FindFirstChild("Torso"))
                    if not tHRP then lbl.Text = "Sin HRP target"; return end

                    local dist   = (hrp.Position - tHRP.Position).Magnitude
                    local vel    = tHRP.AssemblyLinearVelocity
                    local speed  = math.round(vel.Magnitude * 10) / 10
                    local tFly   = math.round((dist / math.max(speed, 1)) * 100) / 100
                    local camDir = workspace.CurrentCamera and workspace.CurrentCamera.CFrame.LookVector or Vector3.new(0,0,-1)
                    local toTgt  = (tHRP.Position - hrp.Position).Unit
                    local angle  = math.round(math.deg(math.acos(math.clamp(camDir:Dot(toTgt), -1, 1))))

                    lbl.Text = string.format(
                        "?? Distancia:  %.1f st\n?? Velocidad target:  %.1f st/s\n? Tiempo vuelo est.:  %.2f s\n?? ?ngulo cam?target:  %d?",
                        dist, speed, tFly, angle
                    )
                end)
            end

            CreateBorderedToggle(_gunUtilSection, "Trajectory Info", function(enabled)
                GU.trajEnabled = enabled
                if enabled then
                    _tjStart()
                    CreateCustomNotification("TRAJECTORY INFO", " Panel de trayectoria activado", 3)
                else
                    _tjStop()
                    CreateCustomNotification("TRAJECTORY INFO", " Info de trayectoria desactivada", 2)
                end
            end, false)

            do
                local d = Instance.new("TextLabel", _gunUtilSection)
                d.Size = UDim2.new(1, -8, 0, 0); d.AutomaticSize = Enum.AutomaticSize.Y
                d.BackgroundTransparency = 1
                d.Text = "Displays on screen: distance, target speed, estimated flight time and camera?target angle."
                d.TextColor3 = Color3.fromRGB(130, 170, 220)
                d.Font = Enum.Font.Montserrat; d.TextSize = 10
                d.TextWrapped = true; d.TextXAlignment = Enum.TextXAlignment.Left; d.ZIndex = 13
                local p = Instance.new("UIPadding", d)
                p.PaddingLeft = UDim.new(0,6); p.PaddingRight = UDim.new(0,6)
                p.PaddingTop  = UDim.new(0,2); p.PaddingBottom = UDim.new(0,4)
            end
        end

        -- =====================================================================
        -- AUTO EQUIP GUN ? equipa la gun autom?ticamente bajo condiciones
        -- =====================================================================
        do
            GU._onlyEquipRange  = GU._onlyEquipRange  or 30
            GU.autoEquipRange   = GU.autoEquipRange   or false
            GU.equippingRange   = GU.equippingRange   or 80
            GU._autoEquipConn   = GU._autoEquipConn   or nil

            local function _hasGun()
                local char = LocalPlayer.Character
                if not char then return false end
                for _, tool in ipairs(char:GetChildren()) do
                    if tool:IsA("Tool") and (tool:FindFirstChild("Handle") or tool:FindFirstChildOfClass("Part")) then
                        return true
                    end
                end
                for _, tool in ipairs(LocalPlayer.Backpack:GetChildren()) do
                    if tool:IsA("Tool") and (tool:FindFirstChild("Handle") or tool:FindFirstChildOfClass("Part")) then
                        return false  -- est? en backpack, no equipada
                    end
                end
                return false
            end

            local function _findGunInBag()
                for _, tool in ipairs(LocalPlayer.Backpack:GetChildren()) do
                    if tool:IsA("Tool") and (tool:FindFirstChild("Handle") or tool:FindFirstChildOfClass("Part")) then
                        return tool
                    end
                end
                return nil
            end

            local function _equipGun(gun)
                pcall(function()
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum then hum:EquipTool(gun) end
                end)
            end

            local function _aeStop()
                if GU._autoEquipConn then
                    pcall(function() GU._autoEquipConn:Disconnect() end)
                    GU._autoEquipConn = nil
                end
            end

            local function _aeStart()
                _aeStop()
                local _aeHb = 0
                GU._autoEquipConn = RunService.Heartbeat:Connect(function()
                    _aeHb = _aeHb + 1; if _aeHb < 20 then return end; _aeHb = 0
                    if not GU.autoEquipRange then return end
                    local char = LocalPlayer.Character
                    if not char then return end
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    local target = (_G._getEffectiveTarget and _G._getEffectiveTarget())
                               or (findMurderer and findMurderer())
                    if not target or not target.Character then return end
                    local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                    if not tHRP then return end
                    local dist = (hrp.Position - tHRP.Position).Magnitude
                    if dist <= (GU._onlyEquipRange or 30) and not _hasGun() then
                        local gun = _findGunInBag()
                        if gun then _equipGun(gun) end
                    end
                end)
            end

            CreateBorderedToggle(_gunUtilSection, "Auto Equip Gun (Murder en rango)", function(enabled)
                GU.autoEquipRange = enabled
                if enabled then
                    _aeStart()
                    CreateCustomNotification("AUTO EQUIP", " Se equipar? la gun cuando el Murder est? en rango", 2.5)
                else
                    _aeStop()
                    CreateCustomNotification("AUTO EQUIP", " Auto Equip desactivado", 1.5)
                end
            end, false)

            CreateSlider(_gunUtilSection, "Rango de equip (studs)", 5, 100, GU._onlyEquipRange or 30, function(v)
                GU._onlyEquipRange = v
            end)

            do
                local d = Instance.new("TextLabel", _gunUtilSection)
                d.Size = UDim2.new(1, -8, 0, 0); d.AutomaticSize = Enum.AutomaticSize.Y
                d.BackgroundTransparency = 1
                d.Text = "Automatically equips the gun when the Murder enters the configured range. Requires gun in backpack."
                d.TextColor3 = Color3.fromRGB(130, 170, 220)
                d.Font = Enum.Font.Montserrat; d.TextSize = 10
                d.TextWrapped = true; d.TextXAlignment = Enum.TextXAlignment.Left; d.ZIndex = 13
                local p = Instance.new("UIPadding", d)
                p.PaddingLeft = UDim.new(0,6); p.PaddingRight = UDim.new(0,6)
                p.PaddingTop  = UDim.new(0,2); p.PaddingBottom = UDim.new(0,4)
            end
        end

        _currentMainSectionFrame = nil
    end  -- close GUN UTILITIES do

    -- ======================================================================
    -- SECCIN: CONDITION SHOOT
    -- Dispara el Silent Aim automticamente segn condiciones en tiempo real
    -- ======================================================================
    do
        _currentMainSectionFrame = nil
        local _csSection = CreateBorderedSection(leftColumn, " CONDITION SHOOT")

        -- Estado persistente
        _G._cshootState = _G._cshootState or {
            studsEnabled  = false,  -- toggle 1: dispara cuando murder est a X studs
            studsRange    = 15,     -- studs default
            wallEnabled   = false,  -- toggle 2: dispara cuando murder sale de detrs de pared
            knifeEnabled  = false,  -- toggle 3: dispara cuando murder equipa knife
            studsConn     = nil,
            wallConn      = nil,
            knifeConn     = nil,
            _wallWasHidden = false, -- track de si el murder ESTABA detrs de pared
            _knifeLastShot = 0,
            _studsLastShot = 0,
            _wallLastShot  = 0,
        }
        local CS = _G._cshootState
        -- FIX AUTO-RESTORE: sincronizar campos enabled desde _G._toggleStates (disco)
        -- porque los toggles usan initialValue=false y el callback los activa via _autoRestoreOnReexec
        do
            local _tsCS = _G._toggleStates or {}
            CS.studsEnabled = _tsCS["Shoot Studs"]      == true or false
            CS.wallEnabled  = _tsCS["Wall Check Shoot"] == true or false
            CS.knifeEnabled = _tsCS["Shoot View Knife"] == true or false
        end

        -- -- Helper: disparar usando el SA existente -----------------------------
        -- Prioridad: silentAimShootFn (botn SA creado) -> FireServer directo
        local function _csDoShoot()
            -- Verificar que SA est activo
            if not CombatTabState.silentAimEnabled then
                CreateCustomNotification(" COND SHOOT", "Activ Silent Aim primero!", 2.5)
                return false
            end
            -- Usar la funcin del botn SA si existe
            local fn = CombatTabState and CombatTabState.silentAimShootFn
            if fn then
                pcall(fn)
                return true
            end
            -- Fallback: intentar _predCalcPos + FireServer directo
            local target = findMurderer and findMurderer()
            if not target or not target.Character then return false end
            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHRP then return false end
            local gun = _findGunIn(myChar) or (LocalPlayer.Backpack and _findGunIn(LocalPlayer.Backpack))
            if not gun then return false end
            local hum = myChar:FindFirstChildOfClass("Humanoid")
            if hum and gun.Parent ~= myChar then
                pcall(function() hum:EquipTool(gun) end)
                gun = _findGunIn(myChar)
                if not gun then return false end
            end
            -- Ammo check
            pcall(function()
                local ammo = gun:FindFirstChild("Ammo")
                if ammo and ammo.Value <= 0 then
                    local mx = gun:FindFirstChild("MaxAmmo")
                    ammo.Value = mx and mx.Value or 8
                end
            end)
            local shootRemote = getShootRemote and getShootRemote(gun)
            if not shootRemote then return false end
            -- Calcular CFrames con el solver SA
            local graCF, targetCF = _saGetTargetCF and _saGetTargetCF()
            if not graCF or not targetCF then return false end
            _sp(function()
                CombatTabState._saBypassHook = true
                pcall(function() shootRemote:FireServer(graCF, targetCF) end)
                CombatTabState._saBypassHook = nil
            end)
            return true
        end

        -- Helper: distancia al murderer
        local function _csMurdererDist()
            local murd = findMurderer and findMurderer()
            if not murd or not murd.Character then return math.huge end
            local mHRP = murd.Character:FindFirstChild("HumanoidRootPart")
            local char = LocalPlayer.Character
            local myHRP = char and char:FindFirstChild("HumanoidRootPart")
            if not mHRP or not myHRP then return math.huge end
            return (myHRP.Position - mHRP.Position).Magnitude
        end

        -- Helper: chequear si el murderer tiene LOS (no hay pared)
        local function _csMurdererHasLOS()
            local murd = findMurderer and findMurderer()
            if not murd or not murd.Character then return false end
            local mHRP  = murd.Character:FindFirstChild("HumanoidRootPart")
            local mHead = murd.Character:FindFirstChild("Head")
            local char  = LocalPlayer.Character
            local myHRP = char and char:FindFirstChild("HumanoidRootPart")
            if not mHRP or not myHRP then return false end
            -- Raycast desde los ojos del local player hacia cabeza y HRP del murder
            local eyePos = myHRP.Position + Vector3.new(0, 1.5, 0)
            local losHRP  = wallCheckRaycast(eyePos, mHRP.Position, murd.Character)
            local losHead = mHead and wallCheckRaycast(eyePos, mHead.Position, murd.Character)
            return losHRP or (losHead == true)
        end

        -- Helper: murderer tiene knife en mano
        local function _csMurdererKnifeEquipped()
            local murd = findMurderer and findMurderer()
            if not murd or not murd.Character then return false end
            for _, tool in ipairs(murd.Character:GetChildren()) do
                if tool:IsA("Tool") then
                    local n = tool.Name:lower()
                    if n:find("knife") or n == "knife" or n:find("cuchillo") then
                        return true
                    end
                end
            end
            return false
        end

        -- ------------------------------------------------------------------------
        -- TOGGLE 1: Shoot Studs  dispara cuando murder est a <= studsRange studs
        -- ------------------------------------------------------------------------
        local function _csStartStuds()
            if CS.studsConn then pcall(function() CS.studsConn:Disconnect() end) end
            local _hb = 0
            CS.studsConn = _safeConnect(RunService.Heartbeat, function()
                if not CS.studsEnabled then return end
                _hb = _hb + 1; if _hb < 6 then return end; _hb = 0  -- ~10Hz

                local now = os.clock()
                if now - CS._studsLastShot < 0.65 then return end  -- cooldown

                local dist = _csMurdererDist()
                if dist > CS.studsRange then return end

                CS._studsLastShot = now
                local ok = _csDoShoot()
                if ok then
                    CreateCustomNotification(" COND SHOOT", "Disparo! Murder a " .. math.floor(dist) .. " studs", 1.2)
                end
            end)
        end

        local function _csStopStuds()
            if CS.studsConn then
                pcall(function() CS.studsConn:Disconnect() end)
                CS.studsConn = nil
            end
        end

        CreateBorderedToggle(_csSection, "Shoot Studs", function(enabled)
            CS.studsEnabled = enabled
            if enabled then
                _csStartStuds()
                CreateCustomNotification(" COND SHOOT", "Shoot Studs ON  rango: " .. CS.studsRange .. " studs", 2)
            else
                _csStopStuds()
                CreateCustomNotification(" COND SHOOT", "Shoot Studs OFF", 1.5)
            end
        end, false)

        -- Slider de rango de studs (1100, default 15)
        do
            local _ssSliderH = 44
            local _ssMin, _ssMax = 1, 100
            local _ssVal = CS.studsRange

            local _ssCont = Instance.new("Frame", _csSection)
            _ssCont.Name = "StudsRangeSlider"
            _ssCont.Size = UDim2.new(1, -4, 0, _ssSliderH)
            _ssCont.BackgroundColor3 = Color3.fromRGB(30, 36, 105)
            _ssCont.BackgroundTransparency = 0.75
            _ssCont.BorderSizePixel = 0
            _ssCont.ZIndex = 12
            Instance.new("UICorner", _ssCont).CornerRadius = UDim.new(0, 8)
            local _ssStroke = Instance.new("UIStroke", _ssCont)
            _ssStroke.Color = ThemeColors.Aurora3
            _ssStroke.Thickness = 1.2
            _ssStroke.Transparency = 0.45

            local _ssLabel = Instance.new("TextLabel", _ssCont)
            _ssLabel.Size = UDim2.new(0.65, 0, 0, 16)
            _ssLabel.Position = UDim2.new(0, 8, 0, 4)
            _ssLabel.BackgroundTransparency = 1
            _ssLabel.Text = " Rango Studs (studs)"
            _ssLabel.TextColor3 = Color3.fromRGB(210, 240, 255)
            _ssLabel.Font = Enum.Font.Montserrat
            _ssLabel.TextSize = 11
            _ssLabel.TextXAlignment = Enum.TextXAlignment.Left
            _ssLabel.ZIndex = 13

            local _ssValBox = Instance.new("TextLabel", _ssCont)
            _ssValBox.Size = UDim2.new(0, 46, 0, 18)
            _ssValBox.Position = UDim2.new(1, -52, 0, 2)
            _ssValBox.BackgroundColor3 = Color3.fromRGB(10, 40, 28)
            _ssValBox.BackgroundTransparency = 0.75
            _ssValBox.BorderSizePixel = 0
            _ssValBox.Text = tostring(_ssVal)
            _ssValBox.TextColor3 = ThemeColors.Primary
            _ssValBox.Font = Enum.Font.GothamBold
            _ssValBox.TextSize = 11
            _ssValBox.ZIndex = 14
            Instance.new("UICorner", _ssValBox).CornerRadius = UDim.new(0, 4)

            local _ssTrack = Instance.new("Frame", _ssCont)
            _ssTrack.Size = UDim2.new(1, -16, 0, 7)
            _ssTrack.Position = UDim2.new(0, 8, 0, 30)
            _ssTrack.BackgroundColor3 = ThemeColors.Aurora2
            _ssTrack.BackgroundTransparency = 0.75
            _ssTrack.BorderSizePixel = 0
            _ssTrack.ZIndex = 13
            Instance.new("UICorner", _ssTrack).CornerRadius = UDim.new(1, 0)

            local _ssFill = Instance.new("Frame", _ssTrack)
            _ssFill.BackgroundColor3 = ThemeColors.Primary
            _ssFill.BackgroundTransparency = 0.1
            _ssFill.BorderSizePixel = 0
            _ssFill.ZIndex = 14
            Instance.new("UICorner", _ssFill).CornerRadius = UDim.new(1, 0)

            local _ssThumb = Instance.new("Frame", _ssTrack)
            _ssThumb.Size = UDim2.new(0, 14, 0, 14)
            _ssThumb.AnchorPoint = Vector2.new(0.5, 0.5)
            _ssThumb.BackgroundColor3 = ThemeColors.Accent
            _ssThumb.BorderSizePixel = 0
            _ssThumb.ZIndex = 16
            Instance.new("UICorner", _ssThumb).CornerRadius = UDim.new(1, 0)

            local _ssDrag = Instance.new("TextButton", _ssTrack)
            _ssDrag.Size = UDim2.new(1, 0, 0, 22)
            _ssDrag.Position = UDim2.new(0, 0, 0.5, -11)
            _ssDrag.BackgroundTransparency = 1
            _ssDrag.Text = ""
            _ssDrag.ZIndex = 17

            local _ssDragging = false

            local function _ssUpdate(pct)
                pct = math.clamp(pct, 0, 1)
                _ssVal = math.max(1, math.floor(_ssMin + (_ssMax - _ssMin) * pct + 0.5))
                _ssValBox.Text = tostring(_ssVal)
                _ssFill.Size = UDim2.new(pct, 0, 1, 0)
                _ssThumb.Position = UDim2.new(pct, 0, 0.5, 0)
                CS.studsRange = _ssVal
            end

            local function _ssPct(x)
                local abs = _ssTrack.AbsolutePosition
                local siz = _ssTrack.AbsoluteSize
                return (x - abs.X) / math.max(siz.X, 1)
            end

            -- FIX MOBILE v4: InputBegan cubre mouse y touch para drag start/stop
            _ssDrag.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                or inp.UserInputType == Enum.UserInputType.Touch then
                    _ssDragging = true
                end
            end)
            UserInputService.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then _ssDragging = false end
            end)
            UserInputService.InputChanged:Connect(function(inp)
                if _ssDragging and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
                    _ssUpdate(_ssPct(inp.Position.X))
                end
            end)
            _ssDrag.Activated:Connect(function()
                _ssUpdate(_ssPct(UserInputService:GetMouseLocation().X))
            end)
            -- Init
            _ssUpdate((_ssVal - _ssMin) / (_ssMax - _ssMin))
        end

        -- ------------------------------------------------------------------------
        -- TOGGLE 2: Wall Check Shoot  dispara cuando el murder sale de atrs de pared
        -- Detecta transicin: estaba sin LOS -> ahora tiene LOS
        -- ------------------------------------------------------------------------
        local function _csStartWall()
            if CS.wallConn then pcall(function() CS.wallConn:Disconnect() end) end
            CS._wallWasHidden = not _csMurdererHasLOS()  -- estado inicial

            local _hb = 0
            CS.wallConn = _safeConnect(RunService.Heartbeat, function()
                if not CS.wallEnabled then return end
                _hb = _hb + 1; if _hb < 4 then return end; _hb = 0  -- ~15Hz para reaccin rpida

                local now = os.clock()
                if now - CS._wallLastShot < 0.55 then return end

                local hasLOS = _csMurdererHasLOS()

                -- Transicin: murder estaba escondido (sin LOS) y ahora aparece (con LOS)
                if CS._wallWasHidden and hasLOS then
                    CS._wallWasHidden = false
                    CS._wallLastShot  = now
                    local ok = _csDoShoot()
                    if ok then
                        CreateCustomNotification(" COND SHOOT", "Murder sali de pared  Disparo!", 1.5)
                    end
                elseif not hasLOS then
                    -- Actualizar estado: murder sigue detrs de pared
                    CS._wallWasHidden = true
                end
                -- Si tiene LOS pero no era transicin -> no disparar (evitar spam)
            end)
        end

        local function _csStopWall()
            if CS.wallConn then
                pcall(function() CS.wallConn:Disconnect() end)
                CS.wallConn = nil
            end
            CS._wallWasHidden = false
        end

        CreateBorderedToggle(_csSection, "Wall Check Shoot", function(enabled)
            CS.wallEnabled = enabled
            if enabled then
                _csStartWall()
                CreateCustomNotification(" COND SHOOT", "Wall Check Shoot ON  Esperando que murder salga", 2.5)
            else
                _csStopWall()
                CreateCustomNotification(" COND SHOOT", "Wall Check Shoot OFF", 1.5)
            end
        end, false)

        -- ------------------------------------------------------------------------
        -- TOGGLE 3: Shoot View Knife  dispara cuando el murder equipa el knife
        -- Detecta ChildAdded en el character del murderer
        -- ------------------------------------------------------------------------
        local function _csWatchCharKnife(char, player)
            if not char then return end
            char.ChildAdded:Connect(function(tool)
                if not CS.knifeEnabled then return end
                local murd = findMurderer and findMurderer()
                if not murd or player ~= murd then return end
                if not tool:IsA("Tool") then return end
                local n = tool.Name:lower()
                if not (n:find("knife") or n == "knife" or n:find("cuchillo")) then return end

                -- Pequeo delay para que el equip se procese completamente
                _sp(function()
                    if not CS.knifeEnabled then return end
                    local now = os.clock()
                    if now - CS._knifeLastShot < 0.6 then return end
                    CS._knifeLastShot = now
                    local ok = _csDoShoot()
                    if ok then
                        CreateCustomNotification(" COND SHOOT", "Murder equip knife  Disparo!", 1.5)
                    end
                end)
            end)
        end

        local function _csStartKnife()
            if CS.knifeConn then pcall(function() CS.knifeConn:Disconnect() end) end

            -- Registrar todos los players actuales
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer then
                    _csWatchCharKnife(p.Character, p)
                    p.CharacterAdded:Connect(function(char)
                        _csWatchCharKnife(char, p)
                    end)
                end
            end

            -- Nuevos players
            CS.knifeConn = Players.PlayerAdded:Connect(function(p)
                p.CharacterAdded:Connect(function(char)
                    _csWatchCharKnife(char, p)
                end)
            end)

            -- Chequeo inmediato: si murder ya tiene knife en mano
            _sp(function()
                if not CS.knifeEnabled then return end
                if _csMurdererKnifeEquipped() then
                    local now = os.clock()
                    if now - CS._knifeLastShot < 0.6 then return end
                    CS._knifeLastShot = now
                    local ok = _csDoShoot()
                    if ok then
                        CreateCustomNotification(" COND SHOOT", "Murder tiene knife  Disparo!", 1.5)
                    end
                end
            end)
        end

        local function _csStopKnife()
            if CS.knifeConn then
                pcall(function() CS.knifeConn:Disconnect() end)
                CS.knifeConn = nil
            end
        end

        CreateBorderedToggle(_csSection, "Shoot View Knife", function(enabled)
            CS.knifeEnabled = enabled
            if enabled then
                _csStartKnife()
                CreateCustomNotification(" COND SHOOT", "Shoot View Knife ON", 2)
            else
                _csStopKnife()
                CreateCustomNotification(" COND SHOOT", "Shoot View Knife OFF", 1.5)
            end
        end, false)

        -- Restaurar conexiones activas al reabrir la pesta?a (solo en tab rebuild)
        -- En re-ejecuci?n real, _autoRestoreOnReexec dispara el callback que inicia los loops.
        -- En tab rebuild, el callback se bloquea (isPhysical), as? que aqu? se reconectan manualmente.
        if _G._isTabRebuild then
            if CS.studsEnabled then _csStartStuds() end
            if CS.wallEnabled  then _csStartWall()  end
            if CS.knifeEnabled then _csStartKnife() end
        end
    end

    -- =======================================================================
    -- SHOOT KEYBIND  dispara el Silent Aim con una tecla configurable
    -- =======================================================================
    do
        local _skSection = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, " SHOOT KEYBIND") or Instance.new("Frame")

        -- Estado persistente
        _G._skState = _G._skState or {
            keybind       = Enum.KeyCode.E,   -- tecla default
            listening     = false,            -- esperando nueva tecla
            conn          = nil,              -- conexin UIS activa
        }
        local SK = _G._skState

        -- -- Funcin de disparo (usa el mismo _csDoShoot / SA) --------------
        local function _skShoot()
            if not CombatTabState.silentAimEnabled then
                if not UserInputService.TouchEnabled then CreateCustomNotification(" SHOOT KEYBIND", "Activ Silent Aim primero!", 2.5) end
                return
            end
            local fn = CombatTabState and CombatTabState.silentAimShootFn
            if fn then
                pcall(fn)
                return
            end
            -- Fallback directo
            local target = findMurderer and findMurderer()
            if not target or not target.Character then return end
            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHRP then return end
            local gun = _findGunIn(myChar) or (LocalPlayer.Backpack and _findGunIn(LocalPlayer.Backpack))
            if not gun then return end
            local hum = myChar:FindFirstChildOfClass("Humanoid")
            if hum and gun.Parent ~= myChar then
                pcall(function() hum:EquipTool(gun) end)
                gun = _findGunIn(myChar)
                if not gun then return end
            end
            local shootRemote = getShootRemote and getShootRemote(gun)
            if not shootRemote then return end
            local graCF, targetCF = _saGetTargetCF and _saGetTargetCF()
            if not graCF or not targetCF then return end
            _sp(function()
                CombatTabState._saBypassHook = true
                pcall(function() shootRemote:FireServer(graCF, targetCF) end)
                CombatTabState._saBypassHook = nil
            end)
        end

        -- -- Panel visual del keybind ---------------------------------------
        local _skPanel = Instance.new("Frame", _skSection)
        _skPanel.Size = UDim2.new(1, -8, 0, 38)
        _skPanel.BackgroundColor3 = Color3.fromRGB(8, 30, 22)
        _skPanel.BackgroundTransparency = 0.5
        _skPanel.BorderSizePixel = 0
        Instance.new("UICorner", _skPanel).CornerRadius = UDim.new(0, 8)
        local _skStroke = Instance.new("UIStroke", _skPanel)
        _skStroke.Color = Color3.fromRGB( 50, 255, 180)
        _skStroke.Thickness = 1.5
        _skStroke.Transparency = 0.3

        local _skTitle = Instance.new("TextLabel", _skPanel)
        _skTitle.Size = UDim2.new(0.55, 0, 1, 0)
        _skTitle.Position = UDim2.new(0, 10, 0, 0)
        _skTitle.BackgroundTransparency = 1
        _skTitle.Text = " Tecla de disparo SA"
        _skTitle.TextColor3 = Color3.fromRGB(210, 240, 255)
        _skTitle.Font = Enum.Font.Montserrat
        _skTitle.TextSize = 12
        _skTitle.TextXAlignment = Enum.TextXAlignment.Left
        _skTitle.ZIndex = 14

        local _skKeyBtn = Instance.new("TextButton", _skPanel)
        _skKeyBtn.Size = UDim2.new(0, 72, 0, 26)
        _skKeyBtn.Position = UDim2.new(1, -80, 0.5, -13)
        _skKeyBtn.BackgroundColor3 = ThemeColors.Background
        _skKeyBtn.BackgroundTransparency = 0.3
        _skKeyBtn.BorderSizePixel = 0
        _skKeyBtn.Text = SK.keybind.Name
        _skKeyBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        _skKeyBtn.Font = Enum.Font.GothamBold
        _skKeyBtn.TextSize = 12
        _skKeyBtn.ZIndex = 15
        Instance.new("UICorner", _skKeyBtn).CornerRadius = UDim.new(0, 6)
        local _skKeyStroke = Instance.new("UIStroke", _skKeyBtn)
        _skKeyStroke.Color = ThemeColors.Primary
        _skKeyStroke.Thickness = 1.2
        _skKeyStroke.Transparency = 0.2

        -- Listener principal del keybind
        if SK.conn then pcall(function() SK.conn:Disconnect() end) end
        SK.conn = UserInputService.InputBegan:Connect(function(inp, gp)
            if gp then return end
            -- Modo escucha: capturar nueva tecla
            if SK.listening then
                if inp.UserInputType == Enum.UserInputType.Keyboard then
                    SK.keybind = inp.KeyCode
                    SK.listening = false
                    _skKeyBtn.Text = inp.KeyCode.Name
                    _skKeyBtn.BackgroundColor3 = ThemeColors.Background
                    _skKeyStroke.Color = ThemeColors.Primary
                    if not UserInputService.TouchEnabled then CreateCustomNotification(" SHOOT KEYBIND", "Tecla asignada: " .. inp.KeyCode.Name, 2) end
                end
                return
            end
            -- Disparo normal
            if inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == SK.keybind then
                _skShoot()
            elseif inp.UserInputType == Enum.UserInputType.Touch and not SK.listening then
                _skShoot()
            end
        end)

        -- Click en el botn: entrar en modo escucha
        _skKeyBtn.Activated:Connect(function()
            if SK.listening then
                SK.listening = false
                _skKeyBtn.Text = SK.keybind.Name
                _skKeyBtn.BackgroundColor3 = ThemeColors.Background
                _skKeyStroke.Color = ThemeColors.Primary
            else
                SK.listening = true
                _skKeyBtn.Text = "..."
                _skKeyBtn.BackgroundColor3 = Color3.fromRGB(90, 35, 10)
                _skKeyStroke.Color = Color3.fromRGB(255, 160, 60)
                if not UserInputService.TouchEnabled then CreateCustomNotification(" SHOOT KEYBIND", "Presion una tecla para asignar", 2) end
            end
        end)

        -- Info label
        local _skInfo = Instance.new("TextLabel", _skSection)
        _skInfo.Size = UDim2.new(1, -8, 0, 0)
        _skInfo.AutomaticSize = Enum.AutomaticSize.Y
        _skInfo.BackgroundTransparency = 1
        _skInfo.Text = "Presion la tecla asignada para disparar el Silent Aim manualmente."
        _skInfo.TextColor3 = Color3.fromRGB(171, 15, 11)
        _skInfo.Font = Enum.Font.Montserrat
        _skInfo.TextSize = 10
        _skInfo.TextWrapped = true
        _skInfo.TextXAlignment = Enum.TextXAlignment.Left
        _skInfo.ZIndex = 13
        local _skPad = Instance.new("UIPadding", _skInfo)
        _skPad.PaddingLeft = UDim.new(0, 6); _skPad.PaddingRight = UDim.new(0, 6)
        _skPad.PaddingTop  = UDim.new(0, 2); _skPad.PaddingBottom = UDim.new(0, 4)
    end

    -- =======================================================================
    -- SHOOT CONDITION  selector unificado de condicin de disparo automtico
    -- Opciones: Shoot Wall Check | View Knife Shoot | Pick Gun Shoot
    -- =======================================================================
    do
        local _scSection = (CreateBorderedSection and leftColumn) and CreateBorderedSection(leftColumn, " SHOOT CONDITION") or Instance.new("Frame")

        -- Estado persistente
        _G._scondState = _G._scondState or {
            activeCondition = nil,   -- nil = desactivado, o nombre de condicin
            conn            = nil,   -- conexin activa
            _wallWasHidden  = false,
            _lastShot       = 0,
            _gunDropConn    = nil,
            _knifeConns     = {},
        }
        local SC = _G._scondState

        -- -- Helper: funcin de disparo reutilizable ------------------------
        local function _scDoShoot()
            if not CombatTabState.silentAimEnabled then
                CreateCustomNotification(" SHOOT CONDITION", "Activ Silent Aim primero!", 2.5)
                return false
            end
            local fn = CombatTabState and CombatTabState.silentAimShootFn
            if fn then pcall(fn); return true end
            local target = findMurderer and findMurderer()
            if not target or not target.Character then return false end
            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHRP then return false end
            local gun = _findGunIn(myChar) or (LocalPlayer.Backpack and _findGunIn(LocalPlayer.Backpack))
            if not gun then return false end
            local hum = myChar:FindFirstChildOfClass("Humanoid")
            if hum and gun.Parent ~= myChar then
                pcall(function() hum:EquipTool(gun) end)
                gun = _findGunIn(myChar)
                if not gun then return false end
            end
            local shootRemote = getShootRemote and getShootRemote(gun)
            if not shootRemote then return false end
            local graCF, tCF = _saGetTargetCF and _saGetTargetCF()
            if not graCF or not tCF then return false end
            _sp(function()
                CombatTabState._saBypassHook = true
                pcall(function() shootRemote:FireServer(graCF, tCF) end)
                CombatTabState._saBypassHook = nil
            end)
            return true
        end

        -- -- Helper: LOS hacia el murderer ----------------------------------
        local function _scHasLOS()
            local murd = findMurderer and findMurderer()
            if not murd or not murd.Character then return false end
            local mHRP  = murd.Character:FindFirstChild("HumanoidRootPart")
            local mHead = murd.Character:FindFirstChild("Head")
            local myChar = LocalPlayer.Character
            local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not mHRP or not myHRP then return false end
            local eye = myHRP.Position + Vector3.new(0, 1.5, 0)
            local losHRP  = wallCheckRaycast(eye, mHRP.Position, murd.Character)
            local losHead = mHead and wallCheckRaycast(eye, mHead.Position, murd.Character)
            return losHRP or (losHead == true)
        end

        -- -- Detener todas las condiciones activas --------------------------
        local function _scStopAll()
            if SC.conn then pcall(function() SC.conn:Disconnect() end); SC.conn = nil end
            if SC._gunDropConn then pcall(function() SC._gunDropConn:Disconnect() end); SC._gunDropConn = nil end
            for _, c in ipairs(SC._knifeConns) do pcall(function() c:Disconnect() end) end
            SC._knifeConns = {}
            SC._wallWasHidden = false
            SC._lastShot = 0
            SC.activeCondition = nil
        end

        -- -- CONDICIN 1: Shoot Wall Check ----------------------------------
        -- Dispara automticamente cuando el murderer deja de estar detrs de la pared
        local function _scStartWallCheck()
            _scStopAll()
            SC.activeCondition = "Shoot Wall Check"
            SC._wallWasHidden = not _scHasLOS()

            local _hb = 0
            SC.conn = RunService.Heartbeat:Connect(function()
                if SC.activeCondition ~= "Shoot Wall Check" then return end
                _hb = _hb + 1; if _hb < 4 then return end; _hb = 0  -- ~15Hz

                local now = os.clock()
                if now - SC._lastShot < 0.55 then return end

                local hasLOS = _scHasLOS()
                if SC._wallWasHidden and hasLOS then
                    -- Transicin: estaba escondido -> ahora visible -> disparar
                    SC._wallWasHidden = false
                    SC._lastShot = now
                    local ok = _scDoShoot()
                    if ok then
                        CreateCustomNotification(" SHOOT CONDITION", " Murder sali de la pared  Disparo!", 1.5)
                    end
                elseif not hasLOS then
                    SC._wallWasHidden = true
                end
            end)
        end

        -- -- CONDICIN 2: View Knife Shoot ----------------------------------
        -- Dispara cuando el murderer equipa el knife (lo tiene en la mano)
        local function _scWatchKnifeChar(char, player)
            if not char then return end
            local conn = char.ChildAdded:Connect(function(tool)
                if SC.activeCondition ~= "View Knife Shoot" then return end
                local murd = findMurderer and findMurderer()
                if not murd or player ~= murd then return end
                if not tool:IsA("Tool") then return end
                local n = tool.Name:lower()
                if not (n:find("knife") or n == "knife" or n:find("cuchillo")) then return end
                _sp(function()
                    if SC.activeCondition ~= "View Knife Shoot" then return end
                    local now = os.clock()
                    if now - SC._lastShot < 0.6 then return end
                    SC._lastShot = now
                    local ok = _scDoShoot()
                    if ok then
                        CreateCustomNotification(" SHOOT CONDITION", " Murder equip knife  Disparo!", 1.5)
                    end
                end)
            end)
            table.insert(SC._knifeConns, conn)
        end

        local function _scStartViewKnife()
            _scStopAll()
            SC.activeCondition = "View Knife Shoot"
            -- Registrar todos los jugadores actuales
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer then
                    _scWatchKnifeChar(p.Character, p)
                    local c = p.CharacterAdded:Connect(function(char)
                        _scWatchKnifeChar(char, p)
                    end)
                    table.insert(SC._knifeConns, c)
                end
            end
            SC.conn = Players.PlayerAdded:Connect(function(p)
                local c = p.CharacterAdded:Connect(function(char)
                    _scWatchKnifeChar(char, p)
                end)
                table.insert(SC._knifeConns, c)
            end)
            -- Chequeo inmediato: si murder ya tiene knife equipado
            _sp(function()
                if SC.activeCondition ~= "View Knife Shoot" then return end
                local murd = findMurderer and findMurderer()
                if murd and murd.Character then
                    for _, tool in ipairs(murd.Character:GetChildren()) do
                        if tool:IsA("Tool") then
                            local n = tool.Name:lower()
                            if n:find("knife") or n == "knife" or n:find("cuchillo") then
                                local now = os.clock()
                                if now - SC._lastShot < 0.6 then return end
                                SC._lastShot = now
                                local ok = _scDoShoot()
                                if ok then
                                    CreateCustomNotification(" SHOOT CONDITION", " Murder ya tiene knife  Disparo!", 1.5)
                                end
                                break
                            end
                        end
                    end
                end
            end)
        end

        -- -- CONDICIN 3: Pick Gun Shoot ------------------------------------
        -- Dispara con SA en el momento que el local player recoge el GunDrop
        local function _scStartPickGun()
            _scStopAll()
            SC.activeCondition = "Pick Gun Shoot"

            -- Detectar cuando el local player equipa la gun (GunDrop -> Character)
            local char = LocalPlayer.Character
            local function _watchChar(c)
                if not c then return end
                local cc = c.ChildAdded:Connect(function(tool)
                    if SC.activeCondition ~= "Pick Gun Shoot" then return end
                    if not tool:IsA("Tool") then return end
                    -- Verificar si es una gun (nombres tpicos de MM2)
                    local n = tool.Name:lower()
                    local isGun = n:find("gun") or n:find("pistol") or n:find("sheriff")
                        or n:find("revolver") or n == "gundrop" or n:find("weapon")
                    if not isGun then return end
                    -- Gun recogida: disparar SA inmediatamente
                    _sp(function()
                        if SC.activeCondition ~= "Pick Gun Shoot" then return end
                        local now = os.clock()
                        if now - SC._lastShot < 0.6 then return end
                        SC._lastShot = now
                        -- Pequeo delay para que el equip se procese
                        _w(0.08)
                        local ok = _scDoShoot()
                        if ok then
                            CreateCustomNotification(" SHOOT CONDITION", " Recogiste la Gun  Disparo SA!", 1.8)
                        end
                    end)
                end)
                table.insert(SC._knifeConns, cc)
            end

            _watchChar(char)
            -- Tambin monitorear si el personaje respawnea
            SC.conn = LocalPlayer.CharacterAdded:Connect(function(newChar)
                if SC.activeCondition ~= "Pick Gun Shoot" then return end
                _watchChar(newChar)
            end)

            CreateCustomNotification(" SHOOT CONDITION", " Pick Gun Shoot ON  Esperando GunDrop", 2.5)
        end

        -- -- Selector de condicin (NebulaSelector) -------------------------
        local _scOptions = {"Desactivado", "Shoot Wall Check", "View Knife Shoot", "Pick Gun Shoot"}
        local _scSavedOpt = (_G._toggleStates and _G._toggleStates["__scCondition__"]) or "Desactivado"
        if type(_scSavedOpt) ~= "string" then _scSavedOpt = "Desactivado" end

        -- ndice inicial
        local _scIndex = 1
        for i, v in ipairs(_scOptions) do
            if v == _scSavedOpt then _scIndex = i; break end
        end

        local _scDescTexts = {
            ["Desactivado"]      = "Sin condicin activa.",
            ["Shoot Wall Check"] = "Cuando el murder salga de detrs de la pared, dispara automticamente con SA.",
            ["View Knife Shoot"] = "Cuando el murder equipe el knife en la mano, dispara automticamente con SA.",
            ["Pick Gun Shoot"]   = "Cuando agarres el GunDrop, dispara automticamente con SA.",
        }

        -- -- Header --------------------------------------------------------
        local _scHdr = Instance.new("TextLabel", _scSection)
        _scHdr.Size = UDim2.new(1, -8, 0, 16)
        _scHdr.BackgroundTransparency = 1
        _scHdr.Text = " SHOOT CONDITION"
        _scHdr.TextColor3 = Color3.fromRGB( 50, 255, 180)
        _scHdr.Font = Enum.Font.GothamBold
        _scHdr.TextSize = 10
        _scHdr.TextXAlignment = Enum.TextXAlignment.Left
        _scHdr.ZIndex = 13
        local _scHdrPad = Instance.new("UIPadding", _scHdr)
        _scHdrPad.PaddingLeft = UDim.new(0, 8)

        -- -- Row prev/next -------------------------------------------------
        local _scRow = Instance.new("Frame", _scSection)
        _scRow.Size = UDim2.new(1, -8, 0, 34)
        _scRow.BackgroundColor3 = Color3.fromRGB(8, 28, 20)
        _scRow.BackgroundTransparency = 0.5
        _scRow.BorderSizePixel = 0
        _scRow.ZIndex = 13
        Instance.new("UICorner", _scRow).CornerRadius = UDim.new(0, 8)
        local _scRowStroke = Instance.new("UIStroke", _scRow)
        _scRowStroke.Color = Color3.fromRGB( 50, 255, 180)
        _scRowStroke.Thickness = 1.2
        _scRowStroke.Transparency = 0.4

        local _scPrev = Instance.new("TextButton", _scRow)
        _scPrev.Size = UDim2.new(0, 28, 0, 28)
        _scPrev.Position = UDim2.new(0, 3, 0.5, -14)
        _scPrev.BackgroundColor3 = ThemeColors.Background
        _scPrev.BackgroundTransparency = 0.4
        _scPrev.BorderSizePixel = 0
        _scPrev.Text = ""
        _scPrev.TextColor3 = Color3.fromRGB( 50, 255, 180)
        _scPrev.Font = Enum.Font.GothamBold
        _scPrev.TextSize = 18
        _scPrev.ZIndex = 14
        _scPrev.AutoButtonColor = false
        Instance.new("UICorner", _scPrev).CornerRadius = UDim.new(0, 6)

        local _scNext = Instance.new("TextButton", _scRow)
        _scNext.Size = UDim2.new(0, 28, 0, 28)
        _scNext.Position = UDim2.new(1, -31, 0.5, -14)
        _scNext.BackgroundColor3 = ThemeColors.Background
        _scNext.BackgroundTransparency = 0.4
        _scNext.BorderSizePixel = 0
        _scNext.Text = ""
        _scNext.TextColor3 = Color3.fromRGB( 50, 255, 180)
        _scNext.Font = Enum.Font.GothamBold
        _scNext.TextSize = 18
        _scNext.ZIndex = 14
        _scNext.AutoButtonColor = false
        Instance.new("UICorner", _scNext).CornerRadius = UDim.new(0, 6)

        local _scLbl = Instance.new("TextLabel", _scRow)
        _scLbl.Size = UDim2.new(1, -70, 1, 0)
        _scLbl.Position = UDim2.new(0, 35, 0, 0)
        _scLbl.BackgroundTransparency = 1
        _scLbl.Text = _scOptions[_scIndex]
        _scLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        _scLbl.Font = Enum.Font.Montserrat
        _scLbl.TextSize = 11
        _scLbl.TextXAlignment = Enum.TextXAlignment.Center
        _scLbl.TextTruncate = Enum.TextTruncate.AtEnd
        _scLbl.ZIndex = 14

        -- -- Descripcin dinmica ------------------------------------------
        local _scDescLabel = Instance.new("TextLabel", _scSection)
        _scDescLabel.Size = UDim2.new(1, -8, 0, 0)
        _scDescLabel.AutomaticSize = Enum.AutomaticSize.Y
        _scDescLabel.BackgroundColor3 = Color3.fromRGB(8, 30, 22)
        _scDescLabel.BackgroundTransparency = 0.5
        _scDescLabel.BorderSizePixel = 0
        _scDescLabel.ZIndex = 13
        _scDescLabel.TextWrapped = true
        _scDescLabel.TextXAlignment = Enum.TextXAlignment.Left
        _scDescLabel.Font = Enum.Font.Montserrat
        _scDescLabel.TextSize = 10
        Instance.new("UICorner", _scDescLabel).CornerRadius = UDim.new(0, 6)
        local _scDescStroke = Instance.new("UIStroke", _scDescLabel)
        _scDescStroke.Color = Color3.fromRGB( 50, 255, 180)
        _scDescStroke.Thickness = 1
        _scDescStroke.Transparency = 0.5
        local _scDescPad = Instance.new("UIPadding", _scDescLabel)
        _scDescPad.PaddingLeft = UDim.new(0, 8); _scDescPad.PaddingRight = UDim.new(0, 8)
        _scDescPad.PaddingTop = UDim.new(0, 5); _scDescPad.PaddingBottom = UDim.new(0, 5)

        local function _scApply(opt)
            _scLbl.Text = opt
            _scDescLabel.Text = _scDescTexts[opt] or ""
            _scDescLabel.TextColor3 = (opt == "Desactivado")
                and Color3.fromRGB(160, 160, 160)
                or Color3.fromRGB(210, 240, 255)
            if _G._toggleStates then _G._toggleStates["__scCondition__"] = opt end
            if opt == "Desactivado" then
                _scStopAll()
            elseif opt == "Shoot Wall Check" then
                _scStartWallCheck()
                CreateCustomNotification(" SHOOT CONDITION", " Wall Check ON", 2)
            elseif opt == "View Knife Shoot" then
                _scStartViewKnife()
                CreateCustomNotification(" SHOOT CONDITION", " View Knife ON", 2)
            elseif opt == "Pick Gun Shoot" then
                _scStartPickGun()
            end
        end

        -- Init visual
        _scDescLabel.Text = _scDescTexts[_scSavedOpt] or ""
        _scDescLabel.TextColor3 = (_scSavedOpt == "Desactivado") and Color3.fromRGB(160,160,160) or Color3.fromRGB(210, 20, 15)

        -- FIX MOBILE: Activated funciona en touch y PC
        _scPrev.Activated:Connect(function()
            _scIndex = _scIndex > 1 and _scIndex - 1 or #_scOptions
            _scApply(_scOptions[_scIndex])
        end)
        _scNext.Activated:Connect(function()
            _scIndex = _scIndex < #_scOptions and _scIndex + 1 or 1
            _scApply(_scOptions[_scIndex])
        end)

        -- Restaurar condicin guardada al reabrir la pestaa
        _sp(function()
            if _scSavedOpt == "Shoot Wall Check" then
                _scStartWallCheck()
            elseif _scSavedOpt == "View Knife Shoot" then
                _scStartViewKnife()
            elseif _scSavedOpt == "Pick Gun Shoot" then
                _scStartPickGun()
            end
        end)
    end

    -- ================================================================
    -- BOTONES FLOTANTES MOBILE DESACTIVADOS

    -- ================================================================
    -- AUTO-RESTORE COMBAT TAB v21: restaurar toggles de cuchillo/gun guardados en disco.
    -- Se corre DESPUES de que todos los toggles se registraron en _toggleCallbacks.
    -- Solo activa los que estan en _autoRestoreOnReexec (Instant Throw, Fast Slash,
    -- Fast Throw, Shooper Shot, Auto Shoot, Shoot Pick, etc.) y tienen savedState=true.
    -- FIX: usa task.defer doble (igual que World tab) para garantizar que todos los
    -- callbacks ya esten registrados antes de intentar llamarlos.
    -- NO se ejecuta en tab rebuild (_G._isTabRebuild=true) porque los loops ya corren.
    -- ================================================================
    if not _G._isTabRebuild then
        task.defer(function()
            task.defer(function()
                if not _G._toggleStates or not _G._toggleCallbacks then return end
                for nombre, state in pairs(_G._toggleStates) do
                    if state == true
                    and _autoRestoreOnReexec and _autoRestoreOnReexec[nombre]
                    and not (_neverRestoreToggles and _neverRestoreToggles[nombre])
                    and _G._toggleCallbacks[nombre] then
                        -- BLOQUEO PREMIUM: si el toggle requiere Premium y no esta verificado,
                        -- forzar a false y limpiar el archivo para que no se reactive.
                        if nombre:find("%(Premium%)") and not _G._discordPremiumVerified then
                            _G._toggleStates[nombre] = false
                            if _G._toggleApplyStates and _G._toggleApplyStates[nombre] then
                                pcall(_G._toggleApplyStates[nombre], false, false)
                            end
                            pcall(function() _saveToggleFile(nombre, false) end)
                        else
                        -- FIX AUTO-SAFE: verificar el .txt antes de activar.
                        -- Si el usuario lo apago manualmente, el .txt dice "false":
                        -- no activar aunque _G._toggleStates diga true.
                        local _txtState = _readToggleFile(nombre)
                        if _txtState == false then
                            _G._toggleStates[nombre] = false
                            if _G._toggleApplyStates and _G._toggleApplyStates[nombre] then
                                pcall(_G._toggleApplyStates[nombre], false, false)
                            end
                        else
                            local _origNotif = CreateCustomNotification
                            CreateCustomNotification = function() end
                            pcall(_G._toggleCallbacks[nombre], true)
                            CreateCustomNotification = _origNotif
                        end
                        end  -- fin bloqueo premium
                    end
                end
            end)
        end)
    end

end  -- close CreateCombatTab


