--[[ PLAYER CARD ELIMINADO
do
    local DA = _G._discordAuth or { loggedIn = false, hasPremium = false, username = nil }
    local tierName  = DA.hasPremium and "Premium" or "Free User"
    local tierColor = DA.hasPremium
        and Color3.fromRGB( 50, 255, 180)
        or  Color3.fromRGB(80, 255, 140)

    -- Card principal  debajo del serverInfoBox, ancho completo del serverPanel
    local pCard = Instance.new("Frame", serverPanel)
    pCard.Name = "PlayerCard"
    pCard.Size = UDim2.new(0, 68, 0, 90)
    pCard.Position = UDim2.new(0, 0, 0, 82)
    pCard.BackgroundColor3 = Color3.fromRGB(28, 32, 95)
    pCard.BackgroundTransparency = 0.35
    pCard.BorderSizePixel = 0
    pCard.ZIndex = 22
    Instance.new("UICorner", pCard).CornerRadius = UDim.new(0, 12)
    local pcStroke = Instance.new("UIStroke", pCard)
    pcStroke.Color = tierColor
    pcStroke.Thickness = 1.5
    pcStroke.Transparency = 0.2

    -- Gradiente de fondo sutil
    local pcGrad = Instance.new("UIGradient", pCard)
    pcGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(10, 22, 60)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(5,  12, 30)),
    })
    pcGrad.Rotation = 45

    -- Avatar circular del jugador Roblox
    local avatarOuter = Instance.new("Frame", pCard)
    avatarOuter.Size = UDim2.new(0, 44, 0, 44)
    avatarOuter.Position = UDim2.new(0.5, -22, 0, 4)
    avatarOuter.BackgroundColor3 = tierColor
    avatarOuter.BackgroundTransparency = 0.6
    avatarOuter.BorderSizePixel = 0
    avatarOuter.ZIndex = 23
    Instance.new("UICorner", avatarOuter).CornerRadius = UDim.new(1, 0)
    local aoStroke = Instance.new("UIStroke", avatarOuter)
    aoStroke.Color = tierColor
    aoStroke.Thickness = 2
    aoStroke.Transparency = 0

    local avatarImg = Instance.new("ImageLabel", avatarOuter)
    avatarImg.Name = "PlayerAvatar"
    avatarImg.Size = UDim2.new(1, -4, 1, -4)
    avatarImg.Position = UDim2.new(0, 2, 0, 2)
    avatarImg.BackgroundTransparency = 1
    avatarImg.Image = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=60&h=60"
    avatarImg.ScaleType = Enum.ScaleType.Fit
    avatarImg.ZIndex = 24
    Instance.new("UICorner", avatarImg).CornerRadius = UDim.new(1, 0)

    -- Nombre de display (arriba)
    local displayNameLbl = Instance.new("TextLabel", pCard)
    displayNameLbl.Size = UDim2.new(1, -4, 0, 16)
    displayNameLbl.Position = UDim2.new(0, 2, 0, 52)
    displayNameLbl.BackgroundTransparency = 1
    displayNameLbl.Text = LocalPlayer.DisplayName or LocalPlayer.Name
    displayNameLbl.FontFace = Font.fromEnum(Enum.Font.GothamBold)
    displayNameLbl.TextSize = 9
    displayNameLbl.TextColor3 = Color3.fromRGB(230, 235, 255)
    displayNameLbl.TextXAlignment = Enum.TextXAlignment.Left
    displayNameLbl.TextTruncate = Enum.TextTruncate.AtEnd
    displayNameLbl.ZIndex = 23

    -- Username (@name)
    local usernameLbl = Instance.new("TextLabel", pCard)
    usernameLbl.Size = UDim2.new(1, -4, 0, 12)
    usernameLbl.Position = UDim2.new(0, 2, 0, 67)
    usernameLbl.BackgroundTransparency = 1
    usernameLbl.Text = "@" .. LocalPlayer.Name
    usernameLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat)
    usernameLbl.TextSize = 8
    usernameLbl.TextColor3 = Color3.fromRGB(140, 155, 200)
    usernameLbl.TextXAlignment = Enum.TextXAlignment.Left
    usernameLbl.TextTruncate = Enum.TextTruncate.AtEnd
    usernameLbl.ZIndex = 23

    -- Badge de tier (abajo del username)
    local tierBadge = Instance.new("TextLabel", pCard)
    tierBadge.Size = UDim2.new(1, -8, 0, 14)
    tierBadge.Position = UDim2.new(0, 4, 1, -16)
    tierBadge.BackgroundColor3 = tierColor
    tierBadge.BackgroundTransparency = 0.75
    tierBadge.BorderSizePixel = 0
    tierBadge.Text = "* " .. tierName
    tierBadge.FontFace = Font.fromEnum(Enum.Font.GothamBold)
    tierBadge.TextSize = 8
    tierBadge.TextColor3 = tierColor
    tierBadge.TextXAlignment = Enum.TextXAlignment.Center
    tierBadge.ZIndex = 23
    Instance.new("UICorner", tierBadge).CornerRadius = UDim.new(0, 4)
    local tbStroke = Instance.new("UIStroke", tierBadge)
    tbStroke.Color = tierColor
    tbStroke.Thickness = 1
    tbStroke.Transparency = 0.3

    -- Actualizar tier cuando el Discord Auth cambie
    _G._playerCardTierUpdate = function()
        local da2 = _G._discordAuth or {}
        local isPrem = da2.hasPremium
        local isExcl = da2.isExclusive
        local newTier, newColor
        if isExcl then
            newTier  = "* Exclusive"
            newColor = Color3.fromRGB(255, 210,   0)
        elseif isPrem then
            newTier  = "* Premium"
            newColor = Color3.fromRGB( 50, 255, 180)
        else
            newTier  = "* Free User"
            newColor = Color3.fromRGB(80, 255, 140)
        end
        pcall(function()
            tierBadge.Text = newTier
            tierBadge.TextColor3 = newColor
            tierBadge.BackgroundColor3 = newColor
            tbStroke.Color = newColor
            pcStroke.Color = newColor
            aoStroke.Color = newColor
            avatarOuter.BackgroundColor3 = newColor
        end)
    end
    -- Llamar ahora por si ya hay datos de Discord
    if DA.loggedIn then
        _sp(_G._playerCardTierUpdate)
    end
end
]]

