    Instance.new("UICorner", wlTrack).CornerRadius = UDim.new(1, 0)

    -- Fill de la barra
    local wlFill = Instance.new("Frame", wlTrack)
    wlFill.Name = "WLFill"
    wlFill.Size = UDim2.new(1, 0, 1, 0)
    wlFill.BackgroundColor3 = Color3.fromRGB(80, 255, 140)
    wlFill.BackgroundTransparency = 0
    wlFill.BorderSizePixel = 0
    wlFill.ZIndex = 24
    Instance.new("UICorner", wlFill).CornerRadius = UDim.new(1, 0)
    local wlFillGrad = Instance.new("UIGradient", wlFill)
    wlFillGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(80, 100, 240)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(80, 255, 140)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB( 50, 255, 180)),
    })

    -- Actualizar la barra y el tiempo
    local _wlTotal = _G._sessionTotalSeconds or (6 * 3600)  -- 6h por defecto
    local function _updateWL()
        local rem = _G._sessionRemainingSeconds or 0
        local total = math.max(_wlTotal, rem, 1)
        local pct = math.clamp(rem / total, 0, 1)
        -- Tiempo formateado
        local d = math.floor(rem / 86400)
        local h = math.floor((rem % 86400) / 3600)
        local m = math.floor((rem % 3600) / 60)
        local s = rem % 60
        local txt
        if d > 0 then
            txt = string.format("%d:%02d:%02d:%02d", d, h, m, s)
        elseif h > 0 then
            txt = string.format("%d:%02d:%02d", h, m, s)
        else
            txt = string.format("0:%02d:%02d", m, s)
        end
        pcall(function()
            wlTimeLbl.Text = txt
            TweenService:Create(wlFill, TweenInfo.new(0.5, Enum.EasingStyle.Quad), {
                Size = UDim2.new(pct, 0, 1, 0)
            }):Play()
            -- Color de la barra: verde si >50%, amarillo si >20%, rojo si <20%
            local barColor
            if pct > 0.5 then
                barColor = Color3.fromRGB(80, 255, 140)
            elseif pct > 0.2 then
                barColor = Color3.fromRGB(255, 200, 60)
            else
                barColor = Color3.fromRGB(255,   0,  40)
            end
            wlFill.BackgroundColor3 = barColor
            wlTimeLbl.TextColor3 = barColor
        end)
    end

    -- Exponer para que el watchdog lo actualice
    _G._wlFrameUpdate = _updateWL
    _updateWL()

    -- Loop de actualizacin cada segundo
    _sp(function()
        while wlFrame and wlFrame.Parent do
            _w(1)
            if _G._sessionRemainingSeconds and _G._sessionRemainingSeconds > 0 then
                _G._sessionRemainingSeconds = _G._sessionRemainingSeconds - 1
            end
            _updateWL()
        end
    end)
end

