fpsConn = nil

function StartFPSLoop()
    if fpsConn then fpsConn:Disconnect() fpsConn = nil end
    local lastFrameTime = tick()
    local frameCount = 0
    local fpsUpdateAcc = 0
    fpsConn = _safeConnect(RunService.RenderStepped, function(dt)
        frameCount = frameCount + 1
        fpsUpdateAcc = fpsUpdateAcc + dt
        if fpsUpdateAcc >= 1.0 then
            local fps = math.round(frameCount / fpsUpdateAcc)
            frameCount = 0
            fpsUpdateAcc = 0

            local fpsColor
            if fps >= 55 then
                fpsColor = Color3.fromRGB(228, 131, 29)
            elseif fps >= 30 then
                fpsColor = Color3.fromRGB(205, 205, 210)
            else
                fpsColor = Color3.fromRGB(57, 57, 57)
            end
 fpsLabel.Text = ""
            fpsIcon.ImageColor3 = fpsColor

            local ping = 0
            pcall(function()
                ping = math.round(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue())
            end)
            if ping == 0 then
                pcall(function()
                    ping = math.round(game:GetService("Stats").Network.ServerStatsItem["Data Ping"].Value)
                end)
            end
            CombatState.currentPing = ping

            local pingColor
            if ping < 80 then
                pingColor = Color3.fromRGB(228, 131, 29)
            elseif ping < 150 then
                pingColor = Color3.fromRGB(205, 205, 210)
            else
                pingColor = Color3.fromRGB(57, 57, 57)
            end
 pingLabel.Text = ""
            pingIcon.ImageColor3 = pingColor
        end
    end)
end

