VisualDangerSystem = {
    enabled = false,
    activeWarnings = {},
    knifeHitboxes = {},
    trajectories = {},
}

DANGER_COLOR = ThemeColors.Primary
HITBOX_COLOR = Color3.fromRGB(63, 63, 63)

function createKnifeHitbox(knife)
    if not knife or not knife:FindFirstChild("Handle") then return end
    local handle = knife.Handle
    if VisualDangerSystem.knifeHitboxes[knife] then return end

    local hitbox = Instance.new("Part")
    hitbox.Name = "KnifeHitbox"
    hitbox.Size = handle.Size * 1.5
    hitbox.CFrame = handle.CFrame
    hitbox.CanCollide = false
    hitbox.Anchored = false
    hitbox.Transparency = 0.7
    hitbox.Color = HITBOX_COLOR
    hitbox.Material = Enum.Material.Neon
    hitbox.Parent = workspace

    local weld = Instance.new("WeldConstraint")
    weld.Part0 = handle
    weld.Part1 = hitbox
    weld.Parent = hitbox

    local outline = Instance.new("SelectionBox")
    outline.Adornee = hitbox
    outline.Color3 = DANGER_COLOR
    outline.LineThickness = 0.05
    outline.Transparency = 0.5
    outline.Parent = hitbox

    VisualDangerSystem.knifeHitboxes[knife] = hitbox

    knife.AncestryChanged:Connect(function()
        if not knife.Parent then
            if hitbox and hitbox.Parent then hitbox:Destroy() end
            VisualDangerSystem.knifeHitboxes[knife] = nil
        end
    end)
end

function createDangerWarning(knifeHandle, targetPosition)
    local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if not myHRP then return end

    local origin = knifeHandle.Position
    local direction = (targetPosition - origin).Unit
    local distance = (targetPosition - origin).Magnitude

    local att0 = Instance.new("Attachment")
    att0.Position = Vector3.new(0, 0, 0)
    att0.Parent = knifeHandle

    local att1 = Instance.new("Attachment")
    att1.WorldPosition = targetPosition
    att1.Parent = workspace.Terrain

    local beam = Instance.new("Beam")
    beam.Attachment0 = att0
    beam.Attachment1 = att1
    beam.Color = ColorSequence.new(DANGER_COLOR)
    beam.Width0 = 0.3
    beam.Width1 = 0.3
    beam.FaceCamera = true
    beam.Transparency = NumberSequence.new(0.3)
    beam.Parent = knifeHandle

    local dangerGui = Instance.new("BillboardGui")
    dangerGui.Name = "DangerWarning"
    dangerGui.Size = UDim2.new(0, 200, 0, 60)
    dangerGui.StudsOffset = Vector3.new(0, 2, 0)
    dangerGui.AlwaysOnTop = true
    dangerGui.MaxDistance = 100
    dangerGui.Parent = knifeHandle

    local dangerText = Instance.new("TextLabel", dangerGui)
    dangerText.Size = UDim2.new(1, 0, 1, 0)
    dangerText.BackgroundTransparency = 1
 dangerText.Text = " DANGER "
    dangerText.FontFace = Font.fromEnum(Enum.Font.Arimo)
    dangerText.TextSize = 24
    dangerText.TextColor3 = DANGER_COLOR
    dangerText.TextStrokeTransparency = 0
    dangerText.TextStrokeColor3 = ThemeColors.Background

    task.spawn(function()
        while dangerGui.Parent do
            dangerText.TextSize = 24 + math.sin(tick() * 10) * 4
            task.wait(0.016)
        end
    end)

    for i = 1, math.floor(distance / 5) do
        local point = origin + direction * (i * 5)
        local warningPart = Instance.new("Part")
        warningPart.Name = "DangerPoint"
        warningPart.Size = Vector3.new(1, 1, 1)
        warningPart.Position = point
        warningPart.Anchored = true
        warningPart.CanCollide = false
        warningPart.Transparency = 0.5
        warningPart.Color = DANGER_COLOR
        warningPart.Material = Enum.Material.Neon
        warningPart.Shape = Enum.PartType.Ball
        warningPart.Parent = workspace
        table.insert(VisualDangerSystem.activeWarnings, warningPart)
        task.delay(3, function()
            if warningPart and warningPart.Parent then warningPart:Destroy() end
        end)
    end

    table.insert(VisualDangerSystem.trajectories, {beam = beam, gui = dangerGui, att0 = att0, att1 = att1})

    task.delay(5, function()
        pcall(function()
            beam:Destroy()
            dangerGui:Destroy()
            att0:Destroy()
            att1:Destroy()
        end)
    end)
end

function monitorKnifeThrows()
    local function checkKnife(obj)
        if not obj:IsA("Tool") or obj.Name ~= "Knife" then return end

        local owner = obj.Parent
        if owner and owner:IsA("Model") then
            local player = Players:GetPlayerFromCharacter(owner)

            if player == LocalPlayer then
                if VisualDangerSystem.enabled then
                    createKnifeHitbox(obj)
                end
            else
                if VisualDangerSystem.enabled then
                    createKnifeHitbox(obj)
                end

                local handle = obj:FindFirstChild("Handle")
                if handle then
                    local lastPos = handle.Position
                    local lastTime = tick()

                    local conn
                    local _hbThandleTrk = 0
                    local _hbHandleDt = 0
                    conn = RunService.Heartbeat:Connect(function(dt)
                        _hbHandleDt = _hbHandleDt + dt; if _hbHandleDt < 0.05 then return end; _hbHandleDt = 0
                        if not handle or not handle.Parent then
                            conn:Disconnect()
                            return
                        end

                        local currentPos = handle.Position
                        local deltaTime = tick() - lastTime

                        if deltaTime > 0 then
                            local velocity = (currentPos - lastPos) / deltaTime

                            if velocity.Magnitude > 50 then
                                local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                                if myHRP then
                                    local directionToMe = (myHRP.Position - currentPos).Unit
                                    local dotProduct = velocity.Unit:Dot(directionToMe)

                                    if dotProduct > 0.5 and VisualDangerSystem.enabled then
                                        local targetPos = currentPos + velocity.Unit * 100
                                        createDangerWarning(handle, targetPos)
                                    end
                                end

                                conn:Disconnect()
                            end
                        end

                        lastPos = currentPos
                        lastTime = tick()
                    end)
                end
            end
        end
    end

    workspace.DescendantAdded:Connect(checkKnife)
    for _, obj in ipairs(workspace:GetDescendants()) do
        checkKnife(obj)
    end
end

function cleanupVisualDanger()
    for knife, hitbox in pairs(VisualDangerSystem.knifeHitboxes) do
        if hitbox and hitbox.Parent then hitbox:Destroy() end
    end
    VisualDangerSystem.knifeHitboxes = {}

    for _, warning in ipairs(VisualDangerSystem.activeWarnings) do
        if warning and warning.Parent then warning:Destroy() end
    end
    VisualDangerSystem.activeWarnings = {}

    for _, traj in ipairs(VisualDangerSystem.trajectories) do
        pcall(function()
            traj.beam:Destroy()
            traj.gui:Destroy()
            traj.att0:Destroy()
            traj.att1:Destroy()
        end)
    end
    VisualDangerSystem.trajectories = {}
end

function ToggleVisualDangerKnife(enabled)
    VisualDangerSystem.enabled = enabled
    if enabled then
        monitorKnifeThrows()
 CreateCustomNotification("Visual Danger", " Sistema activado", 2)
    else
        cleanupVisualDanger()
 CreateCustomNotification("Visual Danger", " Sistema desactivado", 2)
    end
end


InvisibleKnifeSystem = {
    enabled    = false,
    activeKnives = {},  -- [model/tool] = true
    connections  = {},  -- conexiones a desconectar al cleanup
    justThrew    = false,  -- flag: el local player acaba de tirar el knife
    lastThrowTime = 0,
}

function _IKS_hide(model)
    if not model or InvisibleKnifeSystem.activeKnives[model] then return end
    InvisibleKnifeSystem.activeKnives[model] = {}
    for _, obj in ipairs(model:GetDescendants()) do
        if obj:IsA("BasePart") or obj:IsA("MeshPart") then
            InvisibleKnifeSystem.activeKnives[model][obj] = obj.Transparency
            pcall(function() obj.Transparency = 1 end)
        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            InvisibleKnifeSystem.activeKnives[model][obj] = obj.Transparency
            pcall(function() obj.Transparency = 1 end)
        elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then
            InvisibleKnifeSystem.activeKnives[model][obj] = obj.Enabled
            pcall(function() obj.Enabled = false end)
        end
    end
    local addedConn = model.DescendantAdded:Connect(function(obj)
        if not InvisibleKnifeSystem.activeKnives[model] then return end
        if obj:IsA("BasePart") or obj:IsA("MeshPart") then
            pcall(function() obj.Transparency = 1 end)
        elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then
            pcall(function() obj.Enabled = false end)
        end
    end)
    table.insert(InvisibleKnifeSystem.connections, addedConn)
end

function _IKS_show(model)
    local saved = InvisibleKnifeSystem.activeKnives[model]
    if not saved then return end
    for obj, val in pairs(saved) do
        if obj and obj.Parent then
            pcall(function()
                if obj:IsA("BasePart") or obj:IsA("MeshPart")
                   or obj:IsA("Decal") or obj:IsA("Texture") then
                    obj.Transparency = val
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then
                    obj.Enabled = val
                end
            end)
        end
    end
    InvisibleKnifeSystem.activeKnives[model] = nil
end

function _IKS_monitorLife(model)
    task.delay(6, function()
        if InvisibleKnifeSystem.activeKnives[model] then
            _IKS_show(model)
        end
    end)

    local rmConn
    rmConn = model.AncestryChanged:Connect(function()
        if not model.Parent then
            _IKS_show(model)
            pcall(function() rmConn:Disconnect() end)
        end
    end)
    table.insert(InvisibleKnifeSystem.connections, rmConn)

    local function _hookTouchOnPart(part)
        if not part or not part:IsA("BasePart") then return end
        local touchConn
        touchConn = part.Touched:Connect(function(hit)
            if not hit then return end
            local hitChar = hit.Parent
            if not hitChar then return end
            local hum = hitChar:FindFirstChildOfClass("Humanoid")
                     or hitChar.Parent and hitChar.Parent:FindFirstChildOfClass("Humanoid")
            if hum and hum ~= LocalPlayer.Character:FindFirstChildOfClass("Humanoid") then
                task.spawn(function()
                    task.wait(0.016)  -- pequeno delay para que el hit se registre
                    _IKS_show(model)
                end)
                pcall(function() touchConn:Disconnect() end)
            end
        end)
        table.insert(InvisibleKnifeSystem.connections, touchConn)
    end

    if model:IsA("BasePart") then
        _hookTouchOnPart(model)
    else
        for _, obj in ipairs(model:GetDescendants()) do
            if obj:IsA("BasePart") then
                _hookTouchOnPart(obj)
            end
        end
        model.DescendantAdded:Connect(function(obj)
            if obj:IsA("BasePart") then
                _hookTouchOnPart(obj)
            end
        end)
    end
end

function _IKS_startMonitor()
    local char = LocalPlayer.Character
    if not char then return end

    local wspConn = workspace.DescendantAdded:Connect(function(obj)
        if not InvisibleKnifeSystem.enabled then return end
        if obj.Name ~= "ThrowingKnife" then return end
        if not (obj:IsA("Model") or obj:IsA("BasePart")) then return end

        -- Si Knife SA esta activo, no tocar nada
        if KnifeSAState and KnifeSAState.enabled then return end

        -- Si el sistema Throwing Knife esta activo, el ThrowingKnife que aparece
        -- en workspace ES del jugador local (vos sos el murderer que lo lanzo)
        -- No ocultarlo nunca en ese caso
        if _TK_ENABLED then return end

        -- Identificar si es del propio jugador por posicion
        local isOwn = false
        pcall(function()
            local creator = obj:FindFirstChild("creator") or obj:FindFirstChildWhichIsA("ObjectValue")
            if creator and creator.Value == LocalPlayer then isOwn = true; return end
            local myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if myHRP then
                local kv = obj:FindFirstChild("KnifeVisual") or obj:FindFirstChildWhichIsA("MeshPart")
                local part = kv or (obj:IsA("BasePart") and obj)
                if part and (part.Position - myHRP.Position).Magnitude < 15 then isOwn = true; return end
            end
            local dt = tick() - InvisibleKnifeSystem.lastThrowTime
            if dt < 2.0 then isOwn = true end
        end)
        if isOwn then return end

        task.wait(0.016)
        local dt2 = tick() - InvisibleKnifeSystem.lastThrowTime
        if dt2 < 2.0 then return end

        _IKS_hide(obj)
        _IKS_monitorLife(obj)
    end)
    table.insert(InvisibleKnifeSystem.connections, wspConn)

    local function _hookToolEvents(tool)
        if not tool:IsA("Tool") or tool.Name ~= "Knife" then return end
        local ev = tool:FindFirstChild("Events")
        if not ev then
            tool.ChildAdded:Connect(function(c)
                if c.Name == "Events" then ev = c end
            end)
        end
        local function _tryHook()
            if not ev then return end
            local kt = ev:FindFirstChild("KnifeThrown")
            if kt then
                local kc = kt.OnClientEvent:Connect(function()
                    InvisibleKnifeSystem.lastThrowTime = tick()
                    InvisibleKnifeSystem.justThrew = true
                    task.delay(1.5, function() InvisibleKnifeSystem.justThrew = false end)
                end)
                table.insert(InvisibleKnifeSystem.connections, kc)
            end
        end
        _tryHook()
        if ev then
            ev.ChildAdded:Connect(function(c)
                if c.Name == "KnifeThrown" then _tryHook() end
            end)
        end
    end

    local function _hookCharKnife(tool)
        if not tool:IsA("Tool") or tool.Name ~= "Knife" then return end
        _hookToolEvents(tool)
        local anc = tool.AncestryChanged:Connect(function()
            if not InvisibleKnifeSystem.enabled then return end
            if KnifeSAState and KnifeSAState.enabled then return end
            -- NUNCA ocultar el Tool "Knife" cuando se lanza
            -- Del debug: el Tool va a workspace>Model(jugador) cuando se lanza -- es el knife PROPIO
            -- El IKS solo debe ocultar ThrowingKnife que venga de OTROS jugadores
            -- Solo actualizar el timestamp para que wspConn lo identifique como propio
            if tool.Parent and tool.Parent ~= char and tool.Parent ~= LocalPlayer.Backpack then
                InvisibleKnifeSystem.lastThrowTime = tick()
            end
        end)
        table.insert(InvisibleKnifeSystem.connections, anc)
    end

    for _, c in ipairs(char:GetChildren()) do _hookCharKnife(c) end
    local cadConn = char.ChildAdded:Connect(function(c) _hookCharKnife(c) end)
    table.insert(InvisibleKnifeSystem.connections, cadConn)

    local inputConn = UserInputService.InputBegan:Connect(function(inp, gp)
        if gp then return end
        if not InvisibleKnifeSystem.enabled then return end
        -- FIX: no activar IKS si Knife SA esta manejando el tiro
        if KnifeSAState and KnifeSAState.enabled then return end
        local char2 = LocalPlayer.Character
        if not char2 then return end
        if not char2:FindFirstChild("Knife") then return end
        if inp.UserInputType == Enum.UserInputType.MouseButton2
        or inp.KeyCode == Enum.KeyCode.Q then
            InvisibleKnifeSystem.lastThrowTime = tick()
        end
    end)
    table.insert(InvisibleKnifeSystem.connections, inputConn)
end

function cleanupInvisibleKnife()
    for model, _ in pairs(InvisibleKnifeSystem.activeKnives) do
        pcall(_IKS_show, model)
    end
    for _, conn in ipairs(InvisibleKnifeSystem.connections) do
        pcall(function() conn:Disconnect() end)
    end
    InvisibleKnifeSystem.activeKnives  = {}
    InvisibleKnifeSystem.connections   = {}
    InvisibleKnifeSystem.justThrew     = false
    InvisibleKnifeSystem.lastThrowTime = 0
end

function ToggleInvisibleKnife(enabled)
    InvisibleKnifeSystem.enabled = enabled
    if enabled then
        cleanupInvisibleKnife()
        _IKS_startMonitor()
        LocalPlayer.CharacterAdded:Connect(function()
            if InvisibleKnifeSystem.enabled then
                task.wait(1)
                _IKS_startMonitor()
            end
        end)
 CreateCustomNotification("Invisible Knife", " Activado -- detecta ThrowingKnife + Tool", 2)
    else
        cleanupInvisibleKnife()
 CreateCustomNotification("Invisible Knife", " Desactivado", 2)
    end
end

_logOK("Nuevos sistemas cargados: Visual Danger Knife + Invisible Knife")
function abrirHub()
    -- ================================================================
    -- == GUARD DE DOBLE EJECUCION
    -- Si el hub ya se esta construyendo, ignorar la llamada extra.
    -- ================================================================
    if _G._hubRunning then
        _log("abrirHub() ya en ejecucion, ignorando llamada duplicada.")
        return
    end
    _G._hubRunning = true
    -- Safety net: liberar el lock si algo falla y el hub nunca termina
    task.delay(20, function()
        if not _G._hubReady then _G._hubRunning = false end
    end)
    -- ================================================================
    print("3: abrirHub() INICIADO")

    -- ================================================================
    -- == SPLASH SCREEN - Pantalla de bienvenida con imagen y boton
    -- Solo se muestra la primera vez; al reabrir el hub se saltea.
    -- ================================================================
    -- ================================================================
    -- == FIN SPLASH SCREEN
    -- ================================================================

    -- FIX LAG: limpiar entradas hu?rfanas del shimmerRegistry de ejecuciones anteriores
    if _shimmerRegistry then
        for i = #_shimmerRegistry, 1, -1 do
            local e = _shimmerRegistry[i]
            local ok, p = pcall(function() return e and e.grad and e.grad.Parent end)
            if not ok or not p then
                _shimmerRegistry[i] = _shimmerRegistry[#_shimmerRegistry]
                _shimmerRegistry[#_shimmerRegistry] = nil
            end
        end
    end
    -- FIX CRTICO: inicializar _tabConns ANTES de cualquier RegisterTabConn
    -- Si _tabConns es nil cuando RegisterTabConn intenta table.insert -> crash
    _G._tabConns     = {}   -- reiniciar conexiones de tab
    _G._sliderResets = {}   -- reiniciar resets de sliders
    -- FIX OPTIMIZACIN: si el hub ya existe y est oculto, solo mostrarlo
    local playerGui = LocalPlayer:WaitForChild("PlayerGui")
    local existingHub = playerGui:FindFirstChild("f") or game:GetService("CoreGui"):FindFirstChild("f")
    if existingHub and _G._hubHidden then
        -- FIX Z-LOGO: destruir cualquier reopener GUI que haya quedado flotando
        for _, child in ipairs(playerGui:GetChildren()) do
            if child:IsA("ScreenGui") and (
                child.Name == "reReopener" or
                child.Name:find("Reopener") or
                child.Name == "rbxassetid://140622075233565Reopener"
            ) then
                pcall(function() child:Destroy() end)
            end
        end
        -- FIX TAMA?O REOPEN MOBILE: ajustar tama?o y escala ANTES de Enabled=true
        -- para que el hub nunca aparezca ni un frame al tama?o incorrecto.
        local _targetSc = (_getTargetScale and _getTargetScale() or 0.70)
        if mainFrame then
            local _ns = (_getHubSize and _getHubSize()) or UDim2.new(0, 820, 0, 460)
            if _G._setHubFrameSize then _G._setHubFrameSize(_ns) else mainFrame.Size = _ns end
            mainFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
            mainFrame.BackgroundTransparency = 1
            pcall(function() local bg = mainFrame:FindFirstChild("HubBackground"); if bg then bg.ImageTransparency = 0 end end)
            local _uiSc = mainFrame:FindFirstChildOfClass("UIScale")
            if _uiSc then
                _uiSc.Scale = _targetSc * 0.7  -- empezar un poco mas chico para la animacion
            end
        end
        existingHub.Enabled = true
        _G._hubHidden = false
        -- Animacion de entrada suave desde escala casi correcta
        local _uiSc2 = mainFrame and mainFrame:FindFirstChildOfClass("UIScale")
        if _uiSc2 then
            TweenService:Create(_uiSc2, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = _targetSc}):Play()
        end
        -- FIX BINDABLES: restaurar con delay para no chocar con la animacion de entrada
        task.spawn(function()
            task.wait(0.45)
            pcall(function() if _G._setAllBindablesVisible then _G._setAllBindablesVisible(true) end end)
        end)
        -- FIX: recargar el tab activo para restaurar bindables y botones
        task.defer(function()
            if _G._reloadActiveTab then
                pcall(_G._reloadActiveTab)
            end
        end)
        return
    end
    _G._hubReady   = false  -- resetear al (re)abrir
    _G._activatedToggles = {}  -- FIX: resetear al abrir hub de nuevo
    _G._hubRunning = true   -- bloquear nuevas llamadas mientras se construye este hub
    -- FIX LAG: resetear el flag del loop homePanel para que el nuevo hub pueda iniciarlo
    _G._homePanelLoopActive = false

    -- FIX Z-LOGO: destruir reopener GUIs antes de abrir el hub
    -- (si no se destruyen, quedan flotando visibles mientras el hub esta abierto)
    for _, child in ipairs(playerGui:GetChildren()) do
        if child:IsA("ScreenGui") and (
            child.Name == "reReopener" or
            child.Name:find("Reopener") or
            child.Name == "rbxassetid://140622075233565Reopener"
        ) then
            pcall(function() child:Destroy() end)
        end
    end

    -- Destruir hub GUI previo si existe (safety net por si el cleanup no lo atrap)
    local oldHub = playerGui:FindFirstChild("f") or game:GetService("CoreGui"):FindFirstChild("f")
    if oldHub then oldHub:Destroy() end
    local oldDock = playerGui:FindFirstChild("BypasTabDock") or game:GetService("CoreGui"):FindFirstChild("BypasTabDock")
    if oldDock then oldDock:Destroy() end
    -- Destruir ScreenGuis hurfanos del hub que puedan haber quedado
    for _, child in ipairs(playerGui:GetChildren()) do
        if child:IsA("ScreenGui") and (child.Name:find("Bypas") or child.Name:find("rbxassetid://140622075233565")) then
            if child ~= oldHub and child ~= oldDock then
                pcall(function() child:Destroy() end)
            end
        end
    end

    -- -- WAITING REMOVIDO - NO CAUSA PANTALLA NEGRA --------------------------------




    _RegisterToggleRestore("Enable WalkSpeed", function()
        local c = LocalPlayer.Character
        if c then local h = c:FindFirstChildOfClass("Humanoid"); if h then h.WalkSpeed = 16 end end
    end)
    _RegisterToggleRestore("Enable Speed Glitch", function()
        local c = LocalPlayer.Character
        if c then local h = c:FindFirstChildOfClass("Humanoid"); if h then h.WalkSpeed = 16 end end
    end)
    _RegisterToggleRestore("Noclip", function()
        local c = LocalPlayer.Character
        if c then for _, p in pairs(c:GetDescendants()) do if p:IsA("BasePart") then pcall(function() p.CanCollide = true end) end end end
    end)
    _RegisterToggleRestore("Fly+Noclip", function()
        local c = LocalPlayer.Character
        if c then
            local h = c:FindFirstChildOfClass("Humanoid")
            if h then h.WalkSpeed = 16; h.JumpPower = 50; h.AutoRotate = true end
        end
    end)
    _RegisterToggleRestore("Timer Round", function() end)  -- limpia su propia GUI

    -- Limpiar GUIs viejas antes de abrir el hub
    pcall(function()
        local _pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if _pg then
            local _old = _pg:FindFirstChild("InterfazVacia")
            if _old then _old:Destroy() end
            local _old2 = _pg:FindFirstChild("ScreenGui")
            if _old2 then _old2:Destroy() end
        end
    end)

    local hubGui = Instance.new("ScreenGui")
    hubGui.Name = "f"
    hubGui.ResetOnSpawn = false
    hubGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    hubGui.DisplayOrder = 999
    hubGui.Enabled = true
    hubGui.IgnoreGuiInset = true
    -- FIX EXECUTOR: usar gethui() es el mtodo ms compatible
    local _guiParent = playerGui
    if gethui then
        _guiParent = gethui()
    else
        pcall(function() _guiParent = game:GetService("CoreGui") end)
    end
    pcall(function() hubGui.Parent = _guiParent end)
    if not hubGui.Parent then hubGui.Parent = playerGui end
    print("3: hubGui parent =", tostring(hubGui.Parent))
    print("3: ScreenGui creado y parenteado")

mainFrame = Instance.new("Frame", hubGui)
print("3: mainFrame creado")
-- Layout relativo: hub 900x480, UIScale 80%, centrado en pantalla
mainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
mainFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
-- mainFrame con fondo transparente para ver el juego detras
mainFrame.BackgroundColor3 = Color3.fromRGB(  5,  15,  40)  -- azul vibrante
mainFrame.BackgroundTransparency = 0.30
mainFrame.BorderSizePixel = 0
mainFrame.ClipsDescendants = true
-- FIX MOBILE CRITICO: Active=false hace que el frame NO absorba los toques del juego
-- Sin esto, el frame bloquea el joystick y el boton de salto en Delta/mobile
mainFrame.Active = false
Instance.new("UICorner", mainFrame).CornerRadius = UDim.new(0, 8)

-- ================================================================
-- == FONDO HUB v3 ? Aurora Liquida + Particulas + Color Cycle
-- Capas:
--   1. Imagen de fondo original (dock nocturno) con transparencia leve
--   2. Aurora: 3 franjas de color que rotan y cambian de tono en ciclo
--   3. Particulas: puntos de luz que suben y se desvanecen
--   4. Vi?eta perimetral con pulso suave
--   5. Shimmer diagonal que barre cada 8s
-- ================================================================
do
    mainFrame.BackgroundTransparency = 1

    -- -- CAPA 1: imagen de fondo con transparencia leve --------------
    local hubBgImage = Instance.new("ImageLabel", mainFrame)
    hubBgImage.Name            = "HubBackground"
    hubBgImage.Size            = UDim2.new(1, 0, 1, 0)
    hubBgImage.Position        = UDim2.new(0, 0, 0, 0)
    hubBgImage.ZIndex          = 1
    hubBgImage.Image           = "rbxassetid://96937964432645"
    hubBgImage.ImageTransparency = 0.30   -- discreta: los orbs pulsantes dan la profundidad visual
    hubBgImage.BackgroundTransparency = 1
    hubBgImage.ScaleType       = Enum.ScaleType.Stretch
    hubBgImage.ImageRectSize   = Vector2.new(900, 480)
    hubBgImage.ImageRectOffset = Vector2.new(0, 0)
    Instance.new("UICorner", hubBgImage).CornerRadius = UDim.new(0, 8)
    _G._hubBgMainImageRef = hubBgImage

    local _bgAnimRunning = false   -- MODIFICADO: animaciones del fondo desactivadas
    _G._hubBgAnimStop = function() _bgAnimRunning = false end

    -- ================================================================
    -- ANIMACION DE FONDO v5 - NEBULA CINEMATICA CON ORBS PULSANTES
    -- Capas de animacion:
    --   Loop A: parallax suave con zoom cinematico (keyframes)
    --   Loop B: micro-deriva organica frame-a-frame
    --   Loop C: orbs de luz pulsantes que flotan (glassmorphism)
    --   Loop D: aurora de 4 franjas con ciclo de color vivo
    --   Loop E: particulas triple con fade-in/out suave
    -- ================================================================

    -- Estado compartido entre loops A y B
    local _bgOx, _bgOy = 0, 0
    local _bgSx, _bgSy = 900, 480

    -- LOOP A: Tween de keyframes (parallax cinematico)
    task.spawn(function()
        local _kf = {
            {ox =   0, oy =   0, sx = 900, sy = 480, t =  0, e = Enum.EasingStyle.Sine},
            {ox =  15, oy =   8, sx = 855, sy = 456, t = 12, e = Enum.EasingStyle.Cubic},
            {ox =  45, oy =  20, sx = 815, sy = 435, t = 10, e = Enum.EasingStyle.Sine},
            {ox =  85, oy =  35, sx = 788, sy = 420, t =  9, e = Enum.EasingStyle.Quad},
            {ox = 105, oy =  55, sx = 778, sy = 415, t =  8, e = Enum.EasingStyle.Sine},
            {ox =  72, oy =  42, sx = 808, sy = 430, t = 10, e = Enum.EasingStyle.Cubic},
            {ox =  32, oy =  18, sx = 848, sy = 452, t = 11, e = Enum.EasingStyle.Sine},
            {ox =   4, oy =   4, sx = 888, sy = 475, t = 12, e = Enum.EasingStyle.Quart},
        }
        local _idx = 1
        while _bgAnimRunning and hubBgImage and hubBgImage.Parent do
            local _nxt = (_idx % (#_kf - 1)) + 2
            if _idx == 1 then _nxt = 2 end
            local _to = _kf[_nxt]
            _bgOx = _to.ox; _bgOy = _to.oy
            _bgSx = _to.sx; _bgSy = _to.sy
            local _ti = TweenInfo.new(_to.t, _to.e, Enum.EasingDirection.InOut)
            TweenService:Create(hubBgImage, _ti, {
                ImageRectOffset = Vector2.new(_to.ox, _to.oy),
                ImageRectSize   = Vector2.new(_to.sx, _to.sy),
            }):Play()
            -- El fondo respira con el movimiento (transparencia fija, sin pulso)
            task.wait(_to.t)
            _idx = _nxt
            if _nxt == #_kf then _idx = 1 end
        end
    end)

    -- LOOP B: Micro-deriva organica con doble seno
    task.spawn(function()
        local _t = 0
        local _SPEED_X = 0.22
        local _SPEED_Y = 0.17
        local _AMP_X   = 5
        local _AMP_Y   = 3.5
        while _bgAnimRunning and hubBgImage and hubBgImage.Parent do
            task.wait(0.05)
            _t = _t + 0.05
            local _driftX = math.sin(_t * _SPEED_X * math.pi * 2) * _AMP_X
                          + math.sin(_t * _SPEED_X * 1.618 * math.pi * 2) * (_AMP_X * 0.35)
            local _driftY = math.cos(_t * _SPEED_Y * math.pi * 2) * _AMP_Y
                          + math.cos(_t * _SPEED_Y * 1.414 * math.pi * 2) * (_AMP_Y * 0.30)
            local _newOx = math.clamp(_bgOx + _driftX, 0, 120)
            local _newOy = math.clamp(_bgOy + _driftY, 0, 60)
            pcall(function()
                hubBgImage.ImageRectOffset = Vector2.new(_newOx, _newOy)
                -- Tinte HSV muy sutil (no cambia el color principal, solo tono calido/frio)
                local _hue = (_t * 0.012) % 1
                hubBgImage.ImageColor3 = Color3.fromHSV(_hue, 0.12, 0.96)
            end)
        end
    end)

    -- ================================================================
    -- LOOP C: ORBS DE LUZ PULSANTES (glassmorphism flotante)
    -- 5 esferas de luz difusa que flotan, escalan y cambian de color
    -- dando el efecto "nebula/space" que no se nota el fondo solido
    -- ================================================================
    local _orbDefs = {
        -- {xPos, yPos, size, colorHue, speed, phaseOffset}
        {x=0.08, y=0.15, sz=200, hue=0.68, spd=0.07,  ph=0.0 },  -- violeta esquina TL
        {x=0.75, y=0.05, sz=170, hue=0.58, spd=0.055, ph=1.2 },  -- azul esquina TR
        {x=0.50, y=0.55, sz=230, hue=0.72, spd=0.045, ph=2.5 },  -- purpura centro
        {x=0.20, y=0.75, sz=150, hue=0.62, spd=0.065, ph=0.8 },  -- cian BL
        {x=0.85, y=0.65, sz=180, hue=0.80, spd=0.05,  ph=3.1 },  -- magenta BR
    }
    local _orbFrames = {}
    for _, od in ipairs(_orbDefs) do
        local orbF = Instance.new("Frame", mainFrame)
        orbF.AnchorPoint  = Vector2.new(0.5, 0.5)
        orbF.Position     = UDim2.new(od.x, 0, od.y, 0)
        orbF.Size         = UDim2.new(0, od.sz, 0, od.sz)
        orbF.BorderSizePixel = 0
        orbF.ZIndex       = 2
        orbF.BackgroundColor3 = Color3.fromHSV(od.hue, 0.9, 0.8)
        orbF.BackgroundTransparency = 0.72
        Instance.new("UICorner", orbF).CornerRadius = UDim.new(1, 0)
        -- Gradiente radial simulado: UIGradient de 0% a 100% transparente
        local og = Instance.new("UIGradient", orbF)
        og.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0,   0.30),
            NumberSequenceKeypoint.new(0.55, 0.68),
            NumberSequenceKeypoint.new(1,   1.0),
        })
        table.insert(_orbFrames, {frame=orbF, grad=og, def=od, t=od.ph})
    end

    task.spawn(function()
        local _ot = 0
        while _bgAnimRunning do
            task.wait(0.05)
            _ot = _ot + 0.05
            for _, orb in ipairs(_orbFrames) do
                orb.t = orb.t + 0.05
                local od = orb.def
                -- Flotacion: posicion oscila suavemente
                local floatX = od.x + math.sin(orb.t * od.spd * math.pi * 2) * 0.06
                local floatY = od.y + math.cos(orb.t * od.spd * 0.7 * math.pi * 2) * 0.055
                -- Pulso de escala: el orb "respira" (90%-115%)
                local pulse = 1.0 + math.sin(orb.t * od.spd * 1.3 * math.pi * 2) * 0.13
                local newSz = math.floor(od.sz * pulse)
                -- Ciclo de color HSV lento
                local newHue = (od.hue + orb.t * 0.004) % 1
                -- Transparencia pulsante (mas visible en pico, casi invisible en valle)
                local transPulse = 0.72 - math.sin(orb.t * od.spd * 2 * math.pi * 2) * 0.18
                pcall(function()
                    orb.frame.Position = UDim2.new(floatX, 0, floatY, 0)
                    orb.frame.Size = UDim2.new(0, newSz, 0, newSz)
                    orb.frame.BackgroundColor3 = Color3.fromHSV(newHue, 0.88, 0.82)
                    orb.frame.BackgroundTransparency = math.clamp(transPulse, 0.55, 0.90)
                end)
            end
        end
    end)

    -- -- CAPA 2: AURORA - 4 franjas de luz mas vivas y amplias --
    local _auroraPalette = {
        { Color3.fromRGB(40,  0, 110), Color3.fromRGB(100,  0, 200), Color3.fromRGB(  0, 80, 230), Color3.fromRGB(20, 0, 140) },
        { Color3.fromRGB( 0, 30, 140), Color3.fromRGB(  0,100, 240), Color3.fromRGB( 30,  0, 180), Color3.fromRGB( 0, 60, 200) },
        { Color3.fromRGB( 0,100, 190), Color3.fromRGB(  0,200, 240), Color3.fromRGB( 30, 80, 220), Color3.fromRGB( 0,140, 210) },
        { Color3.fromRGB(80,  0, 190), Color3.fromRGB(160,  0, 255), Color3.fromRGB(100,  0, 220), Color3.fromRGB(50,  0, 170) },
        { Color3.fromRGB(10,  0, 100), Color3.fromRGB( 80, 30, 200), Color3.fromRGB(  0, 50, 180), Color3.fromRGB(30, 10, 150) },
        { Color3.fromRGB( 0, 60, 170), Color3.fromRGB( 30,160, 255), Color3.fromRGB( 70,  0, 220), Color3.fromRGB( 0, 80, 190) },
    }
    local _auroraPaletteIdx = 1

    local function _makeAuroraStrip(yScale, heightScale, zidx, initRot)
        local f = Instance.new("Frame", mainFrame)
        f.Size = UDim2.new(1.4, 0, heightScale, 0)
        f.Position = UDim2.new(-0.20, 0, yScale, 0)
        f.BackgroundTransparency = 1
        f.BorderSizePixel = 0
        f.ZIndex = zidx
        f.ClipsDescendants = false
        Instance.new("UICorner", f).CornerRadius = UDim.new(0.5, 0)
        local g = Instance.new("UIGradient", f)
        g.Rotation = initRot or 0
        return f, g
    end

    local _auroraA, _gradA = _makeAuroraStrip(0.02, 0.60, 2,  10)
    local _auroraB, _gradB = _makeAuroraStrip(0.28, 0.55, 2, -10)
    local _auroraC, _gradC = _makeAuroraStrip(0.52, 0.50, 2,  16)
    local _auroraD, _gradD = _makeAuroraStrip(0.72, 0.40, 2,  -5)

    local function _applyAuroraPalette(pal)
        local c0, c1, c2, c3 = pal[1], pal[2], pal[3], pal[4]
        local function makeGrad(cA, cB)
            return ColorSequence.new({
                ColorSequenceKeypoint.new(0,    Color3.fromRGB(0,0,0)),
                ColorSequenceKeypoint.new(0.18, cA),
                ColorSequenceKeypoint.new(0.50, cB),
                ColorSequenceKeypoint.new(0.82, cA),
                ColorSequenceKeypoint.new(1,    Color3.fromRGB(0,0,0)),
            })
        end
        local makeTr = NumberSequence.new({
            NumberSequenceKeypoint.new(0,    1),
            NumberSequenceKeypoint.new(0.18, 0.50),
            NumberSequenceKeypoint.new(0.50, 0.28),
            NumberSequenceKeypoint.new(0.82, 0.50),
            NumberSequenceKeypoint.new(1,    1),
        })
        _gradA.Color = makeGrad(c0, c1); _gradA.Transparency = makeTr
        _gradB.Color = makeGrad(c1, c2); _gradB.Transparency = makeTr
        _gradC.Color = makeGrad(c2, c3); _gradC.Transparency = makeTr
        _gradD.Color = makeGrad(c3, c0); _gradD.Transparency = makeTr
    end
    _applyAuroraPalette(_auroraPalette[1])

    task.spawn(function()
        local _tA, _tB, _tC, _tD = 0, 0.6, 1.3, 2.1
        local _rotA, _rotB, _rotC, _rotD = 10, -10, 16, -5
        local _palTimer = 0
        local _PAL_DUR  = 10
        while _bgAnimRunning and _auroraA and _auroraA.Parent do
            local dt = 0.05
            task.wait(dt)
            _tA = _tA+dt; _tB = _tB+dt; _tC = _tC+dt; _tD = _tD+dt

            local yA = 0.02 + math.sin(_tA * 0.16) * 0.10
            local yB = 0.28 + math.sin(_tB * 0.11) * 0.12
            local yC = 0.52 + math.sin(_tC * 0.14) * 0.09
            local yD = 0.72 + math.sin(_tD * 0.18) * 0.07

            _rotA = 10  + math.sin(_tA * 0.08) * 24
            _rotB = -10 + math.sin(_tB * 0.10) * 20
            _rotC = 16  + math.sin(_tC * 0.07) * 26
            _rotD = -5  + math.sin(_tD * 0.12) * 18

            pcall(function()
                _auroraA.Position = UDim2.new(-0.20, 0, yA, 0)
                _auroraB.Position = UDim2.new(-0.20, 0, yB, 0)
                _auroraC.Position = UDim2.new(-0.20, 0, yC, 0)
                _auroraD.Position = UDim2.new(-0.20, 0, yD, 0)
                _gradA.Rotation = _rotA
                _gradB.Rotation = _rotB
                _gradC.Rotation = _rotC
                _gradD.Rotation = _rotD
            end)

            _palTimer = _palTimer + dt
            if _palTimer >= _PAL_DUR then
                _palTimer = 0
                _auroraPaletteIdx = (_auroraPaletteIdx % #_auroraPalette) + 1
                pcall(function() _applyAuroraPalette(_auroraPalette[_auroraPaletteIdx]) end)
            end
        end
    end)

    -- -- CAPA 3: PARTICULAS mejoradas (30 puntos, 3 tamanos, mas visibles) --
    local _PARTICLE_COUNT = 30
    local _particles = {}

    local function _makeParticle()
        local p = Instance.new("Frame", mainFrame)
        -- 3 tamanios: pequeno, medio, grande (estrella)
        local tier = math.random(1, 3)
        local sz = tier == 1 and math.random(1, 3) or tier == 2 and math.random(3, 6) or math.random(6, 10)
        p.Size = UDim2.new(0, sz, 0, sz)
        p.BackgroundTransparency = 1
        p.BorderSizePixel = 0
        p.ZIndex = 3
        Instance.new("UICorner", p).CornerRadius = UDim.new(1, 0)
        local palIdx = math.random(1, #_auroraPalette)
        local cIdx   = math.random(1, 4)
        p.BackgroundColor3 = _auroraPalette[palIdx][cIdx]
        return p, tier
    end

    local function _resetParticle(entry)
        local p = entry.frame
        local startX = math.random(1, 99) / 100
        local startY = math.random(72, 100) / 100
        p.Position = UDim2.new(startX, 0, startY, 0)
        p.BackgroundTransparency = 1
        local palIdx = math.random(1, #_auroraPalette)
        local cIdx   = math.random(1, 4)
        pcall(function() p.BackgroundColor3 = _auroraPalette[palIdx][cIdx] end)
        entry.x       = startX
        entry.y       = startY
        -- Particulas grandes suben mas lento pero brillan mas
        entry.speed   = entry.tier == 3 and math.random(2, 5)/100 or math.random(4, 14)/100
        entry.drift   = (math.random(-20, 20)) / 1000
        entry.life    = 0
        entry.maxLife = entry.tier == 3 and math.random(60, 130) or math.random(35, 90)
        entry.phase   = math.random(0, 62) / 10
        -- Particulas grandes brillan mas (menor transparencia en pico)
        entry.maxAlpha = entry.tier == 3 and 0.95 or entry.tier == 2 and 0.85 or 0.70
    end

    for i = 1, _PARTICLE_COUNT do
        local p, tier = _makeParticle()
        local entry = { frame=p, tier=tier, x=0, y=0, speed=0, drift=0, life=0, maxLife=60, phase=0, maxAlpha=0.80 }
        _resetParticle(entry)
        entry.y = math.random(0, 100) / 100
        p.Position = UDim2.new(entry.x, 0, entry.y, 0)
        entry.life = math.random(0, entry.maxLife)
        _particles[i] = entry
    end

    task.spawn(function()
        while _bgAnimRunning do
            task.wait(0.05)
            for _, e in ipairs(_particles) do
                if not (e.frame and e.frame.Parent) then continue end
                e.life = e.life + 1
                e.y = e.y - e.speed * 0.01
                e.x = e.x + e.drift + math.sin(e.life * 0.12 + e.phase) * 0.0018
                local lifeRatio = e.life / e.maxLife
                local alpha
                if lifeRatio < 0.18 then
                    alpha = lifeRatio / 0.18
                elseif lifeRatio > 0.72 then
                    alpha = 1 - (lifeRatio - 0.72) / 0.28
                else
                    alpha = 1
                end
                pcall(function()
                    e.frame.BackgroundTransparency = 1 - (alpha * e.maxAlpha)
                    e.frame.Position = UDim2.new(e.x, 0, e.y, 0)
                end)
                if e.life >= e.maxLife or e.y < -0.06 then
                    _resetParticle(e)
                end
            end
        end
    end)

    -- -- CAPA 4: VI?ETA perimetral con pulso de color suave -----------
    local _vigFrame = Instance.new("Frame", mainFrame)
    _vigFrame.Name = "HubVignette"
    _vigFrame.Size = UDim2.new(1, 0, 1, 0)
    _vigFrame.Position = UDim2.new(0, 0, 0, 0)
    _vigFrame.BackgroundTransparency = 1
    _vigFrame.BorderSizePixel = 0
    _vigFrame.ZIndex = 4
    Instance.new("UICorner", _vigFrame).CornerRadius = UDim.new(0, 8)
    local _vigGrad = Instance.new("UIGradient", _vigFrame)
    _vigGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(0,  0, 20)),
        ColorSequenceKeypoint.new(0.28, Color3.fromRGB(2,  2, 10)),
        ColorSequenceKeypoint.new(0.72, Color3.fromRGB(2,  2, 10)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(10, 0, 30)),
    })
    _vigGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,    0.38),
        NumberSequenceKeypoint.new(0.28, 0.97),
        NumberSequenceKeypoint.new(0.72, 0.97),
        NumberSequenceKeypoint.new(1,    0.34),
    })

    -- Pulso: la vigneta rota su gradiente suavemente para efecto de "latido"
    task.spawn(function()
        local _vRot = 0
        while _bgAnimRunning and _vigFrame and _vigFrame.Parent do
            task.wait(0.08)
            _vRot = (_vRot + 0.4) % 360
            pcall(function() _vigGrad.Rotation = _vRot end)
        end
    end)

    -- -- CAPA 5: SHIMMER diagonal ? barre cada 8s ---------------------
    local _shimFrame = Instance.new("Frame", mainFrame)
    _shimFrame.Name = "HubShimmer"
    _shimFrame.Size = UDim2.new(0.32, 0, 1.4, 0)
    _shimFrame.Position = UDim2.new(-0.40, 0, -0.20, 0)
    _shimFrame.BackgroundTransparency = 1
    _shimFrame.BorderSizePixel = 0
    _shimFrame.ZIndex = 5
    _shimFrame.ClipsDescendants = false
    local _shimGrad = Instance.new("UIGradient", _shimFrame)
    _shimGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,    Color3.fromRGB(0,   0,   0)),
        ColorSequenceKeypoint.new(0.30, Color3.fromRGB(100, 180, 255)),
        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(200, 240, 255)),
        ColorSequenceKeypoint.new(0.70, Color3.fromRGB(100, 180, 255)),
        ColorSequenceKeypoint.new(1,    Color3.fromRGB(0,   0,   0)),
    })
    _shimGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0,    1),
        NumberSequenceKeypoint.new(0.30, 0.84),
        NumberSequenceKeypoint.new(0.50, 0.72),
        NumberSequenceKeypoint.new(0.70, 0.84),
        NumberSequenceKeypoint.new(1,    1),
    })
    _shimGrad.Rotation = 22

    task.spawn(function()
        task.wait(2.5)
        while _bgAnimRunning and _shimFrame and _shimFrame.Parent do
            _shimFrame.Position = UDim2.new(-0.40, 0, -0.20, 0)
            TweenService:Create(_shimFrame,
                TweenInfo.new(2.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                { Position = UDim2.new(1.15, 0, -0.20, 0) }
            ):Play()
            task.wait(2.2 + 6.5)
        end
    end)
end

-- HubHeaderBar eliminado: el TopBar ya contiene el header completo estilo Capybara.
-- _G._hubHeaderBarRef se asigna al TopBar que se crea mas abajo.

-- ================================================================
-- == DETECCION DE DISPOSITIVO: PC vs CELULAR
-- El frame base es SIEMPRE 750x420 (el contenido interno esta disenado
-- para ese tama?o). En celular, UIScale lo reduce para que entre en
-- pantalla. En PC, UIScale lo maneja el slider de settings.
-- ================================================================
local _vp           = workspace.CurrentCamera.ViewportSize
local _isMobileHub  = false
pcall(function()
    local _uis = game:GetService("UserInputService")
    -- Detectar mobile por TouchEnabled sin importar el tama?o del viewport,
    -- ya que en tablets y celulares grandes _vp.X puede superar 850px.
    _isMobileHub = _uis.TouchEnabled and not _uis.KeyboardEnabled
end)
_G._isMobileHub = _isMobileHub

-- Tama?o base fijo: UIScale se encarga de ajustar segun dispositivo
mainFrame.Size = UDim2.new(0, 900, 0, 480)

-- ================================================================
-- == GUARDIAN DE FORMA DEL HUB v1
-- Detecta si cualquier script externo (ej: CapybaraScripts_MM2)
-- modifica el Size, Position o AnchorPoint de mainFrame y lo
-- restaura de inmediato al valor correcto.
-- Esto evita que un Panel.Size = UDim2.new(0,660,0,N) de otro
-- script pise el frame del hub.
-- ================================================================
do
    local _guardSize   = UDim2.new(0, 900, 0, 480)
    local _guardPos    = UDim2.new(0.5, 0, 0.5, 0)
    local _guardAnchor = Vector2.new(0.5, 0.5)
    local _guardBusy   = false   -- re-entrancy lock

    -- HUB MOVIBLE: allowDragMove permite que el drag actualice _guardPos
    _G._hubAllowDragMove = true
    _G._hubDragging = false

    mainFrame:GetPropertyChangedSignal("Size"):Connect(function()
        if _guardBusy then return end
        if mainFrame.Size == _guardSize then return end
        _guardBusy = true
        mainFrame.Size = _guardSize
        _guardBusy = false
    end)

    mainFrame:GetPropertyChangedSignal("Position"):Connect(function()
        if _guardBusy then return end
        -- HUB FIJO: el drag esta desactivado, nunca actualizar _guardPos por drag
        if mainFrame.Position == _guardPos then return end
        _guardBusy = true
        mainFrame.Position = _guardPos
        _guardBusy = false
    end)

    mainFrame:GetPropertyChangedSignal("AnchorPoint"):Connect(function()
        if _guardBusy then return end
        if mainFrame.AnchorPoint == _guardAnchor then return end
        _guardBusy = true
        mainFrame.AnchorPoint = _guardAnchor
        _guardBusy = false
    end)

    _G._setHubFrameSize = function(newSize)
        _guardSize = newSize
        _guardBusy = true
        mainFrame.Size = newSize
        _guardBusy = false
    end
    _G._setHubFramePos = function(newPos)
        _guardPos = newPos
        _guardBusy = true
        mainFrame.Position = newPos
        _guardBusy = false
    end
end

-- ================================================================
-- == HUB FIJO: drag desactivado (hub no movible)
-- ================================================================
-- (El hub permanece fijo en pantalla, no se puede arrastrar)
-- ================================================================
-- == FIN HUB FIJO
-- ================================================================

-- ================================================================
-- == EFECTO PARPADEO / PESTANEAR DEL FONDO (3 segundos despues de abrir)
-- Usa rbxassetid://124196125990159 (animacion de ojos que cierran y abren)
-- Se muestra como overlay encima del fondo del hub cada cierto tiempo.
-- ================================================================
do
    local BLINK_ASSET    = "rbxassetid://124196125990159"
    local BLINK_DELAY    = 3     -- segundos antes del primer parpadeo
    local BLINK_CLOSED   = 0.18  -- tiempo con los ojos cerrados
    local BLINK_OPEN_T   = 0.12  -- duracion del fade al abrir
    local BLINK_INTERVAL = 5     -- segundos entre parpadeos

    -- Overlay de imagen que cubre todo el fondo del hub
    local blinkOverlay = Instance.new("ImageLabel", mainFrame)
    blinkOverlay.Name                   = "BlinkOverlay"
    blinkOverlay.Size                   = UDim2.new(1, 0, 1, 0)         -- igual al fondo principal
    blinkOverlay.Position               = UDim2.new(0, 0, 0, 0)         -- igual al fondo principal
    blinkOverlay.AnchorPoint            = Vector2.new(0, 0)              -- igual al fondo principal
    blinkOverlay.Image                  = BLINK_ASSET
    blinkOverlay.BackgroundTransparency = 1
    blinkOverlay.ImageTransparency      = 1                              -- empieza invisible
    blinkOverlay.ScaleType              = Enum.ScaleType.Stretch         -- igual al fondo principal
    blinkOverlay.ImageRectSize          = Vector2.new(900, 480)          -- igual al fondo principal
    blinkOverlay.ImageRectOffset        = Vector2.new(0, 0)              -- igual al fondo principal
    blinkOverlay.ZIndex                 = 3
    blinkOverlay.Active                 = false
    Instance.new("UICorner", blinkOverlay).CornerRadius = UDim.new(0, 8)

    local function _doBlink()
        if not (blinkOverlay and blinkOverlay.Parent) then return end
        -- Cerrar ojos: fade in rapido
        TweenService:Create(blinkOverlay,
            TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {ImageTransparency = 0}):Play()
        task.wait(BLINK_CLOSED)
        -- Abrir ojos: fade out suave
        TweenService:Create(blinkOverlay,
            TweenInfo.new(BLINK_OPEN_T, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            {ImageTransparency = 1}):Play()
        task.wait(BLINK_OPEN_T)
    end

    task.spawn(function()
        task.wait(BLINK_DELAY)
        while mainFrame and mainFrame.Parent do
            pcall(_doBlink)
            task.wait(BLINK_INTERVAL)
        end
    end)
end
-- ================================================================
-- == FIN EFECTO PARPADEO
-- ================================================================
-- ================================================================
-- == FIN GUARDIAN DE FORMA DEL HUB
-- ================================================================

-- Fondo: referencia guardada en el bloque do de arriba; aplicar ID si se provee uno
_G._applyHubBackground = function(id)
    local ref = _G._hubBgMainImageRef
    if not ref or not ref.Parent then
        ref = mainFrame and mainFrame:FindFirstChild("HubBackground")
        _G._hubBgMainImageRef = ref
    end
    if ref then
        if id and id ~= "" then
            ref.Image = id
            ref.ImageTransparency = 0
        else
            -- Imagen predeterminada: mirada en el muelle nocturno
            ref.Image = "rbxassetid://96937964432645"
            ref.ImageTransparency = 0
        end
    end
end
_G._hubWaveContainer = nil

-- Borde del mainFrame activado (dise?o arco?ris rapido)
glowBorder = Instance.new("UIStroke", mainFrame)
glowBorder.Color = Color3.fromRGB(0, 200, 160)
glowBorder.Thickness = 2.5
glowBorder.Transparency = 0
glowBorder.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

-- ANIMACION DE BORDE RAPIDA: arcoiris ciclico con gradiente giratorio
do
    local _borderGrad = Instance.new("UIGradient", glowBorder)
    _borderGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,    Color3.fromRGB(  0, 220, 170)),
        ColorSequenceKeypoint.new(0.16, Color3.fromRGB( 80, 160, 255)),
        ColorSequenceKeypoint.new(0.33, Color3.fromRGB(180,  60, 255)),
        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(255,  60, 120)),
        ColorSequenceKeypoint.new(0.66, Color3.fromRGB(255, 180,   0)),
        ColorSequenceKeypoint.new(0.83, Color3.fromRGB( 60, 255, 120)),
        ColorSequenceKeypoint.new(1,    Color3.fromRGB(  0, 220, 170)),
    })
    _borderGrad.Rotation = 0
    _G._hubBorderGrad = _borderGrad

    -- Animacion rapida: gira 360? en ~1.8 segundos (muy rapida y vistosa)
    local _borderHue = 0
    local _borderRotation = 0
    local _borderAnimRunning = false   -- MODIFICADO: animacion del borde desactivada
    _G._hubBorderAnimStop = function() _borderAnimRunning = false end

    -- Paleta de colores arcoiris para ciclar el gradiente completo
    local _rainbowPalette = {
        Color3.fromRGB(  0, 220, 170),  -- teal
        Color3.fromRGB( 80, 160, 255),  -- azul
        Color3.fromRGB(180,  60, 255),  -- purpura
        Color3.fromRGB(255,  60, 120),  -- rosa
        Color3.fromRGB(255, 180,   0),  -- dorado
        Color3.fromRGB( 60, 255, 120),  -- verde
    }

    local function _lerpColor(c1, c2, t)
        return Color3.new(
            c1.R + (c2.R - c1.R) * t,
            c1.G + (c2.G - c1.G) * t,
            c1.B + (c2.B - c1.B) * t
        )
    end

    -- Loop de animacion: rota el gradiente muy rapido y cicla colores
    task.spawn(function()
        local _hbAnim = 0
        local _conn = game:GetService("RunService").Heartbeat:Connect(function(dt)
            if not _borderAnimRunning or not (glowBorder and glowBorder.Parent) then return end
            -- Rotar rapido: 200 grados por segundo (vuelta completa en ~1.8s)
            _borderRotation = (_borderRotation + dt * 200) % 360
            pcall(function() _borderGrad.Rotation = _borderRotation end)

            -- Ciclar colores del hub stroke con arcoiris suave
            _borderHue = (_borderHue + dt * 0.6) % 1
            local n = #_rainbowPalette
            local rawPos = _borderHue * n
            local i1 = math.floor(rawPos) % n + 1
            local i2 = i1 % n + 1
            local t_ = rawPos - math.floor(rawPos)
            local newC = _lerpColor(_rainbowPalette[i1], _rainbowPalette[i2], t_)
            pcall(function()
                glowBorder.Color = newC
            end)
        end)
        -- Limpiar cuando el hub se destruya
        task.spawn(function()
            while _borderAnimRunning and mainFrame and mainFrame.Parent do
                task.wait(2)
            end
            pcall(function() _conn:Disconnect() end)
        end)
    end)
end

-- Helper global: siempre 750x420 (UIScale se encarga de la escala)
_getHubSize = function()
    return UDim2.new(0, 900, 0, 480)
end

uiScale = Instance.new("UIScale", mainFrame)
uiScale.Scale = 0.80  -- escala PC 80%

-- ================================================================
-- == ESCALA AUTOMATICA POR DISPOSITIVO
-- Celular: calcula la escala para que 750px quepan en el ancho
--          disponible con un margen de 4px a cada lado (ancho ligeramente mayor).
--          Luego aplica hubScale (default 130%) sobre esa escala base.
-- PC:      usa el slider hubScale (70-130%, default 70%).
-- ================================================================
_getTargetScale = function()
    local _vpNow = workspace.CurrentCamera.ViewportSize
    local _isMobileNow = false
    pcall(function()
        local _uis = game:GetService("UserInputService")
        _isMobileNow = _uis.TouchEnabled and not _uis.KeyboardEnabled
    end)
    -- DEBUG: imprimir valores reales para diagnosticar
    _log("SCALE DEBUG VP=", tostring(_vpNow.X), "x", tostring(_vpNow.Y), "isMobile=", tostring(_isMobileNow))
    if _isMobileNow then
        -- Calcular escala exacta para que el frame 900x480 entre en pantalla con margen
        local _scaleByW = (_vpNow.X - 24) / 900
        local _scaleByH = (_vpNow.Y - 24) / 480
        local _final = math.clamp(math.min(_scaleByW, _scaleByH), 0.30, 0.55)
        _log("SCALE DEBUG mobile -> final=", tostring(_final))
        return _final
    else
        -- PC: 70%
        return 0.80
    end
end
do
    -- FIX: aplicar escala correcta inmediatamente (no diferida) para que PC siempre inicie en 0.70
    uiScale.Scale = _getTargetScale()
    -- Proteger contra sobreescrituras en el mismo frame
    _G._hubScaleApplied = true
end
mainFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
mainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
