        workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
            task.defer(function()
                if uiScale and uiScale.Parent then
                    uiScale.Scale = _getTargetScale()
                end
            end)
        end)
    end)
end
_log("Layout relativo 80%x82% aplicado")
