--[[ task.spawn(function()
    task.wait(0.5)

    local RS  = game:GetService("RunService")
    local _GLOW_ID = "rbxassetid://118930676204472"

    local _TRAIL_COLORS = {
        Color3.fromRGB(0,   255, 100),   -- verde neon
        Color3.fromRGB(0,   210, 180),   -- teal
        Color3.fromRGB(0,   230, 255),   -- cyan
        Color3.fromRGB(40,  120, 255),   -- azul aurora
        Color3.fromRGB(100,  50, 220),   -- morado
        Color3.fromRGB(0,   200,  80),   -- verde oscuro
        Color3.fromRGB(50,  180, 255),   -- azul cielo
        Color3.fromRGB(100, 200, 255),   -- celeste pastel
        Color3.fromRGB(0,   180, 210),   -- cyan-teal
        Color3.fromRGB(180,  80, 255),   -- violeta
    }

    local _trailSG = Instance.new("Frame", hubGui)
    _trailSG.Name                   = "EstelaContainer"
    _trailSG.Size                   = mainFrame.Size
    _trailSG.Position               = mainFrame.Position
    _trailSG.AnchorPoint            = mainFrame.AnchorPoint
    _trailSG.BackgroundTransparency = 1
    _trailSG.BorderSizePixel        = 0
    _trailSG.ZIndex                 = 300
    _trailSG.ClipsDescendants       = false

    -- Lerp helper
    local function lerp(a, b, t) return a + (b - a) * t end

    -- Ease in-out
    local function ease(t) return t * t * (3 - 2 * t) end

    local _NUM_TRAILS = 6
    local _activeTrails = {}

    local function _makeTrailData()
        local col = _TRAIL_COLORS[math.random(1, #_TRAIL_COLORS)]
        local goH = math.random() > 0.5
        local sX, sY, eX, eY
        if goH then
            sX = -0.12; sY = math.random(8, 92)/100
            eX =  1.12; eY = math.random(8, 92)/100
        else
            sX = math.random(8, 92)/100; sY = -0.12
            eX = math.random(8, 92)/100; eY =  1.12
        end
        local dur = 2.5 + math.random() * 2.0
        return {col=col, sX=sX, sY=sY, eX=eX, eY=eY, dur=dur, t=0, nextFlash=math.random(20,60)/100}
    end

    local function _makeImages(d)
        local col = d.col
        local imgs = {}
        -- 8 cola rastros
        local _TAIL = 8
        imgs.tails = {}
        for i = 1, _TAIL do
            local tr = Instance.new("ImageLabel", _trailSG)
            local sz = math.max(0.03, 0.15 - i * 0.014)
            tr.Size                   = UDim2.new(sz, 0, sz, 0)
            tr.AnchorPoint            = Vector2.new(0.5, 0.5)
            tr.Position               = UDim2.new(d.sX, 0, d.sY, 0)
            tr.BackgroundTransparency = 1
            tr.Image                  = _GLOW_ID
            tr.ImageColor3            = col
            tr.ImageTransparency      = math.min(0.97, 0.25 + i * 0.09)
            tr.BorderSizePixel        = 0
            tr.ZIndex                 = 300 + i
            imgs.tails[i] = {img=tr, lag=i * 0.07}
        end
        -- halo
        local halo = Instance.new("ImageLabel", _trailSG)
        halo.Size                   = UDim2.new(0.42, 0, 0.42, 0)
        halo.AnchorPoint            = Vector2.new(0.5, 0.5)
        halo.Position               = UDim2.new(d.sX, 0, d.sY, 0)
        halo.BackgroundTransparency = 1
        halo.Image                  = _GLOW_ID
        halo.ImageColor3            = col
        halo.ImageTransparency      = 0.45
        halo.BorderSizePixel        = 0
        halo.ZIndex                 = 309
        imgs.halo = halo
        -- nucleo
        local core = Instance.new("ImageLabel", _trailSG)
        core.Size                   = UDim2.new(0.18, 0, 0.18, 0)
        core.AnchorPoint            = Vector2.new(0.5, 0.5)
        core.Position               = UDim2.new(d.sX, 0, d.sY, 0)
        core.BackgroundTransparency = 1
        core.Image                  = _GLOW_ID
        core.ImageColor3            = col
        core.ImageTransparency      = 0.0
        core.BorderSizePixel        = 0
        core.ZIndex                 = 311
        imgs.core = core
        -- anillo exterior
        local outer = Instance.new("ImageLabel", _trailSG)
        outer.Size                   = UDim2.new(0.60, 0, 0.60, 0)
        outer.AnchorPoint            = Vector2.new(0.5, 0.5)
        outer.Position               = UDim2.new(d.sX, 0, d.sY, 0)
        outer.BackgroundTransparency = 1
        outer.Image                  = _GLOW_ID
        outer.ImageColor3            = col
        outer.ImageTransparency      = 0.70
        outer.BorderSizePixel        = 0
        outer.ZIndex                 = 307
        imgs.outer = outer
        return imgs
    end

    local function _destroyImgs(imgs)
        pcall(function() for _, td in ipairs(imgs.tails) do td.img:Destroy() end end)
        pcall(function() imgs.halo:Destroy() end)
        pcall(function() imgs.core:Destroy() end)
        pcall(function() imgs.outer:Destroy() end)
    end

    -- Spawn destellos aurora desde posicion actual
    local _flashQueue = {}
    local function _spawnFlash(cx, cy, col)
        if not (_trailSG and _trailSG.Parent) then return end
        local fx = Instance.new("ImageLabel", _trailSG)
        fx.Size                   = UDim2.new(0.28, 0, 0.28, 0)
        fx.AnchorPoint            = Vector2.new(0.5, 0.5)
        fx.Position               = UDim2.new(cx + math.random(-6,6)/100, 0, cy + math.random(-6,6)/100, 0)
        fx.BackgroundTransparency = 1
        fx.Image                  = _GLOW_ID
        fx.ImageColor3            = Color3.fromRGB(
            math.random(80,200), 255, math.random(100,200))
        fx.ImageTransparency      = 0.15
        fx.BorderSizePixel        = 0
        fx.ZIndex                 = 316
        table.insert(_flashQueue, {img=fx, life=0, maxLife=0.22})
    end

    -- Inicializar trails con offset de tiempo
    local trails = {}
    for i = 1, _NUM_TRAILS do
        local d = _makeTrailData()
        d.t = -(i - 1) * (d.dur / _NUM_TRAILS)  -- escalonar inicio
        if d.t < 0 then
            -- pre-iniciar: t negativo = todavia esperando
            local imgs = _makeImages(d)
            -- ocultar hasta que empiece
            imgs.core.ImageTransparency = 1
            imgs.halo.ImageTransparency = 1
            imgs.outer.ImageTransparency = 1
            for _, td in ipairs(imgs.tails) do td.img.ImageTransparency = 1 end
            table.insert(trails, {d=d, imgs=imgs})
        else
            table.insert(trails, {d=d, imgs=_makeImages(d)})
        end
    end

    -- Loop principal en Heartbeat
    RS.Heartbeat:Connect(function(dt)
        if not (_trailSG and _trailSG.Parent) then return end

        -- Actualizar flashes
        local fi = 1
        while fi <= #_flashQueue do
            local fl = _flashQueue[fi]
            fl.life = fl.life + dt
            local prog = fl.life / fl.maxLife
            if prog >= 1 then
                pcall(function() fl.img:Destroy() end)
                table.remove(_flashQueue, fi)
            else
                local alpha = math.sin(prog * math.pi)  -- campana: sube y baja
                local sc = 0.28 + alpha * 0.18
                pcall(function()
                    fl.img.ImageTransparency = 1 - alpha * 0.9
                    fl.img.Size = UDim2.new(sc, 0, sc, 0)
                end)
                fi = fi + 1
            end
        end

        -- Actualizar cada trail
        for idx, tr in ipairs(trails) do
            local d = tr.d
            d.t = d.t + dt

            if d.t < 0 then
                -- aun esperando, no hacer nada
            elseif d.t >= d.dur then
                -- termino: destruir y crear nuevo
                _destroyImgs(tr.imgs)
                local nd = _makeTrailData()
                nd.t = 0
                trails[idx] = {d=nd, imgs=_makeImages(nd)}
            else
                local prog = ease(d.t / d.dur)
                local cx = lerp(d.sX, d.eX, prog)
                local cy = lerp(d.sY, d.eY, prog)

                -- pulso de brillo
                local pulse = math.abs(math.sin(d.t * math.pi * 1.8)) * 0.20

                local imgs = tr.imgs
                pcall(function()
                    imgs.core.Position        = UDim2.new(cx, 0, cy, 0)
                    imgs.core.ImageTransparency = pulse
                    imgs.halo.Position        = UDim2.new(cx, 0, cy, 0)
                    imgs.halo.ImageTransparency = 0.40 + pulse * 0.4
                    imgs.outer.Position       = UDim2.new(cx, 0, cy, 0)
                    imgs.outer.ImageTransparency = 0.62 + pulse * 0.25
                end)

                -- colas con lag
                for _, td in ipairs(imgs.tails) do
                    local lagT = math.max(0, d.t - td.lag)
                    local lagProg = ease(lagT / d.dur)
                    local lx = lerp(d.sX, d.eX, lagProg)
                    local ly = lerp(d.sY, d.eY, lagProg)
                    pcall(function() td.img.Position = UDim2.new(lx, 0, ly, 0) end)
                end

                -- destellos aurora
                if d.t > d.nextFlash then
                    d.nextFlash = d.t + math.random(15, 55) / 100
                    _spawnFlash(cx, cy, d.col)
                end
            end
        end
    end)
end) --]]

