-- [ESTELAS MARINAS ELIMINADAS]
--[[ task.spawn(function()
    repeat task.wait(0.1) until _G._hubReady
    local RS = game:GetService("RunService")

    -- Colores del mar: solo azul y celeste puro, sin verde
    local _SEA_COLORS = {
        Color3.fromRGB(30,  160, 220),  -- celeste
        Color3.fromRGB(60,  190, 240),  -- celeste claro
        Color3.fromRGB(20,  120, 200),  -- azul mar
        Color3.fromRGB(80,  210, 240),  -- celeste brillante
        Color3.fromRGB(40,  170, 230),  -- celeste medio
        Color3.fromRGB(100, 220, 255),  -- celeste muy claro
        Color3.fromRGB(15,   90, 170),  -- azul profundo
        Color3.fromRGB(10,  140, 210),  -- azul oceano
        Color3.fromRGB(50,  180, 255),  -- azul cielo
        Color3.fromRGB(120, 200, 255),  -- celeste pastel
    }

    -- Formas de olas/espuma: circulos, elipses y arcos simulados con frames
    local _SHAPES = {"circle", "oval", "circle", "oval", "circle"}

    local _waveContainer = Instance.new("Frame", mainFrame)
    _waveContainer.Name                   = "WaveContainer"
    _waveContainer.Size                   = UDim2.new(1, 0, 1, 0)
    _waveContainer.Position               = UDim2.new(0, 0, 0, 0)
    _waveContainer.BackgroundTransparency = 1
    _waveContainer.BorderSizePixel        = 0
    _waveContainer.ZIndex                 = 4
    _waveContainer.ClipsDescendants       = true

    local _NUM_WAVES = 14
    local _waves     = {}

    local function _makeWave()
        local col   = _SEA_COLORS[math.random(1, #_SEA_COLORS)]
        local shape = _SHAPES[math.random(1, #_SHAPES)]
        -- Posicion inicial aleatoria en la mitad inferior (zona del mar)
        local x0    = math.random(2, 96) / 100
        local y0    = math.random(40, 95) / 100
        -- Movimiento: deriva horizontal lenta + oscilacion vertical suave
        local driftX = (math.random(0, 1) == 0 and 1 or -1) * (math.random(2, 8) / 1000)
        local phase  = math.random(0, 628) / 100  -- fase inicial aleatoria
        local period = math.random(180, 400) / 100  -- periodo de ola (segundos)
        local ampY   = math.random(8, 25) / 1000    -- amplitud vertical
        -- Tamano de la forma (pequena)
        local baseW  = math.random(18, 55) / 1000
        local baseH  = (shape == "oval") and (baseW * (math.random(30, 60) / 100)) or baseW
        local alpha  = math.random(5, 30) / 100   -- transparencia base (mas visibles)

        local f = Instance.new("Frame", _waveContainer)
        f.BackgroundColor3       = col
        f.BackgroundTransparency = alpha
        f.BorderSizePixel        = 0
        f.Size                   = UDim2.new(baseW, 0, baseH, 0)
        f.AnchorPoint            = Vector2.new(0.5, 0.5)
        f.Position               = UDim2.new(x0, 0, y0, 0)
        f.ZIndex                 = 5
        Instance.new("UICorner", f).CornerRadius = UDim.new(1, 0)  -- circulo perfecto

        -- Brillo interior
        local inner = Instance.new("Frame", f)
        inner.Size                   = UDim2.new(0.5, 0, 0.5, 0)
        inner.AnchorPoint            = Vector2.new(0.5, 0.5)
        inner.Position               = UDim2.new(0.35, 0, 0.35, 0)
        inner.BackgroundColor3       = Color3.fromRGB(180, 230, 255)
        inner.BackgroundTransparency = 0.55
        inner.BorderSizePixel        = 0
        inner.ZIndex                 = 6
        Instance.new("UICorner", inner).CornerRadius = UDim.new(1, 0)

        return {
            frame  = f,
            x      = x0,
            y      = y0,
            driftX = driftX,
            phase  = phase,
            period = period,
            ampY   = ampY,
            alpha  = alpha,
            life   = 0,
            maxLife = math.random(120, 280) / 10,  -- 12-28 segundos de vida
        }
    end

    -- Inicializar olas en posiciones distribuidas
    for i = 1, _NUM_WAVES do
        local w = _makeWave()
        w.life = math.random(0, math.floor(w.maxLife * 10)) / 10  -- desfase inicial
        table.insert(_waves, w)
    end

    local _dt = 0
    local _lastT = tick()

    RS.Heartbeat:Connect(function()
        if not (mainFrame and mainFrame.Parent) then return end
        local now = tick()
        local dt  = math.min(now - _lastT, 0.05)
        _lastT    = now
        _dt       = _dt + dt

        for i = #_waves, 1, -1 do
            local w = _waves[i]
            w.life = w.life + dt

            -- Reciclar ola muerta
            if w.life >= w.maxLife then
                pcall(function() w.frame:Destroy() end)
                _waves[i] = _makeWave()
                continue
            end

            local lifeRatio = w.life / w.maxLife
            -- Fade in primero 15%, fade out ultimo 20%
            local fadeMul
            if lifeRatio < 0.15 then
                fadeMul = lifeRatio / 0.15
            elseif lifeRatio > 0.80 then
                fadeMul = (1 - lifeRatio) / 0.20
            else
                fadeMul = 1
            end

            -- Movimiento
            w.x = w.x + w.driftX * dt
            -- Rebotar en los bordes
            if w.x < 0.02 or w.x > 0.98 then
                w.driftX = -w.driftX
                w.x = math.max(0.02, math.min(0.98, w.x))
            end
            local waveY = w.y + math.sin(_dt / w.period * math.pi * 2 + w.phase) * w.ampY

            pcall(function()
                w.frame.Position               = UDim2.new(w.x, 0, waveY, 0)
                w.frame.BackgroundTransparency = w.alpha + (1 - fadeMul) * (1 - w.alpha) * 0.98
            end)
        end
    end)
end) --]]

