        _tabIndicator.Size                   = UDim2.new(0, 3, 0.7, 0)
        _tabIndicator.AnchorPoint            = Vector2.new(1, 0.5)
        _tabIndicator.Position               = UDim2.new(1, -1, 0.5, 0)
        _tabIndicator.BackgroundColor3       = _accentColor
