    local serverPanel, restoreBtn = CreateServerPanel(mainFrame)

    local tabsVisible = true

    function ShowServerPanel()
        tabsVisible = false
        TweenService:Create(arrowLabel, TweenInfo.new(0.25), {ImageTransparency = 0.5}):Play()
        TweenService:Create(arrowToggleBtn, TweenInfo.new(0.25), {BackgroundColor3 = Color3.fromRGB(255, 180, 0), BackgroundTransparency = 0.5}):Play()
        -- Ocultar dock de tabs al mostrar server panel
        if _G._hubSettings and _G._hubSettings.noMinMaxAnimations then
            if tabDockFrame then tabDockFrame.BackgroundTransparency = 0.30 end  -- TRANSPARENCIA restaurada
        else
            if tabDockFrame then TweenService:Create(tabDockFrame, TweenInfo.new(0.25), {BackgroundTransparency = 0.15}):Play() end
            TweenService:Create(contentContainer, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Position = UDim2.new(0, 0, 1.5, 0)}):Play()
            task.wait(0.32)
            serverPanel.Visible = true
            serverPanel.Position = UDim2.new(0, 20, 1.5, 0)
            TweenService:Create(serverPanel, TweenInfo.new(0.45, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = UDim2.new(0, 20, 0, 60)}):Play()
        end
        RefreshRoles()
    end

    local fpsConn
    function ShowTabs()
        tabsVisible = true
        TweenService:Create(arrowLabel, TweenInfo.new(0.25), {ImageTransparency = 0}):Play()
        TweenService:Create(arrowToggleBtn, TweenInfo.new(0.25), {BackgroundColor3 = ThemeColors.Primary, BackgroundTransparency = 0.25}):Play()
        if _G._hubSettings and _G._hubSettings.noMinMaxAnimations then
            serverPanel.Visible = false
            if fpsConn then fpsConn:Disconnect(); fpsConn = nil end
            if tabDockFrame then tabDockFrame.BackgroundTransparency = 0.30 end  -- TRANSPARENCIA restaurada
        else
            TweenService:Create(serverPanel, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Position = UDim2.new(0, 20, 1.5, 0)}):Play()
            task.wait(0.32)
            serverPanel.Visible = false
            if fpsConn then fpsConn:Disconnect(); fpsConn = nil end
            -- Restaurar dock de tabs
            if tabDockFrame then TweenService:Create(tabDockFrame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {BackgroundTransparency = 0.55}):Play() end
            if contentContainer.Visible then
                TweenService:Create(contentContainer, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Position = UDim2.new(0, 0, 0, 36)}):Play()
            end
        end
    end

    _G._tabContentActive = false

    -- Funcion para volver al estado vacio (deseleccionar tabs pero mantener area visible)
    local function _goBackToEmpty()
        _G._tabContentActive = false
        -- NO ocultar contentContainer: el area izquierda siempre rellena el hub
        for _, btn in ipairs(sideButtons) do
            pcall(function() _applyBtnState(_, false) end)
        end
    end
    _G._goBackToEmpty = _goBackToEmpty  -- exponer para minimizeBtn (scope externo)

    -- FIX BINDABLES: funci?n para ocultar/mostrar todos los ScreenGuis flotantes (bindables, botones m?vil, etc.)
    local function _setAllBindablesVisible(visible)
        -- 1. capyBindRegistry: todos los MakeCapyBindableFrame (FLY, BOOST, BOMB JUMP, etc.)
        pcall(function()
            local reg = _G._capyBindRegistry
            if type(reg) == "table" then
                for _, sg in pairs(reg) do
                    pcall(function() if sg and sg.Parent then sg.Enabled = visible end end)
                end
            end
        end)
        -- 2. _BindableGuiRegistry: TP AM, TP VOID, SILENT AIM, etc.
        pcall(function()
            local reg = _G._BindableGuiRegistry
            if type(reg) == "table" then
                for _, sg in pairs(reg) do
                    pcall(function() if sg and sg.Parent then sg.Enabled = visible end end)
                end
            end
        end)
        -- 3. Buscar por nombre en PlayerGui y CoreGui todos los ScreenGuis conocidos del hub
        local _knownNames = {
            "FlyBind_HUB", "FlyMobileControls_HUB", "SwimFlyMobile_HUB",
            "AutoJumpBind", "JBBoostBind", "FloatBind_HUB", "LayBind_HUB",
            "EsquivarBind_HUB", "StealGunBindable", "GrabGunBindable",
            "SpeedGlitchBind_HUB", "TpAMBindable", "TpVoidBindable",
            "TpLobbyBindable", "TpMapBindable", "OrbitPlayerBind",
            "NewInvisBind", "HandFlutterBindable", "TpLowMapBindable",
            "PierceBulletGui", "SilentAimBind_HUB", "FakeUnboxRoulette",
            "OD_InfoDisplay", "BombJumpBindable_HUB",
            -- nombres adicionales que no matcheaban los patrones generales
            "BypasBSA", "BypasSecureAutoBindable",
            "NoclipBindableHub", "JumpBoostBindableHub",
            "BombJumpBindable", "FakeBombBindles", "FakeDiedBindSg",
        }
        local _parents = {}
        pcall(function() table.insert(_parents, LocalPlayer:FindFirstChildOfClass("PlayerGui")) end)
        pcall(function() table.insert(_parents, game:GetService("CoreGui")) end)
        pcall(function() if gethui then table.insert(_parents, gethui()) end end)
        for _, parent in ipairs(_parents) do
            if parent then
                for _, name in ipairs(_knownNames) do
                    pcall(function()
                        local sg = parent:FindFirstChild(name)
                        if sg then sg.Enabled = visible end
                    end)
                end
                -- Scan general: cubre cualquier ScreenGui del hub por patr?n de nombre
                for _, child in ipairs(parent:GetChildren()) do
                    pcall(function()
                        if child:IsA("ScreenGui") then
                            local n = child.Name
                            if n:find("_CapyBtn")  or n:find("_HUB")      or
                               n:find("Bindable")  or n:find("Bind_")     or
                               n:find("CapyBindSg") or n:find("Bypas")    or
                               n:find("BindableHub") then
                                child.Enabled = visible
                            end
                        end
                    end)
                end
            end
        end
    end
    _G._setAllBindablesVisible = _setAllBindablesVisible  -- exponer globalmente

    -- FIX MOBILE: en ejecutores moviles MouseButton1Click puede no disparar con touch.
    -- Usamos InputBegan como respaldo para garantizar que el boton funcione.
    local _arrowBtnDebounce = false
    local function _arrowBtnFire()
        if _arrowBtnDebounce then return end
        _arrowBtnDebounce = true
        task.delay(0.5, function() _arrowBtnDebounce = false end)
        -- disparar el handler de cierre/minimizar
        local _hubGuiRef    = hubGui
        local _mainFrameRef = mainFrame
        pcall(CloseExpandPanel)
        pcall(function() if _G._stopWeapon then _G._stopWeapon() end end)
        pcall(function() if _G._stopKnife  then _G._stopKnife()  end end)
        -- BINDABLES: se mantienen visibles al cerrar el hub (son ScreenGuis independientes)
        if _G._hubSettings and _G._hubSettings.noMinMaxAnimations then
            if _mainFrameRef then _mainFrameRef.BackgroundTransparency = 1 end
            if tabDockFrame  then tabDockFrame.BackgroundTransparency  = 1 end
        else
            pcall(function()
                local uiScaleClose = _mainFrameRef:FindFirstChildOfClass("UIScale")
                if uiScaleClose then
                    TweenService:Create(uiScaleClose, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0}):Play()
                end
                TweenService:Create(_mainFrameRef, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
                if tabDockFrame then
                    TweenService:Create(tabDockFrame, TweenInfo.new(0.3), {BackgroundTransparency = 0.15}):Play()
                end
            end)
        end
        _G._hubHidden = true
        pcall(_flushConfig)
        task.delay(0.36, function()
            pcall(function() if _hubGuiRef then _hubGuiRef.Enabled = false end end)
            pcall(function()
                for _, parent in ipairs({ LocalPlayer:FindFirstChildOfClass("PlayerGui"), game:GetService("CoreGui") }) do
                    if parent then local _h = parent:FindFirstChild("f"); if _h then _h.Enabled = false end end
                end
                if gethui then local _gh = gethui():FindFirstChild("f"); if _gh then _gh.Enabled = false end end
            end)
            if tabDockGui then pcall(function() tabDockGui.Enabled = false end) end
        end)
        -- Skull reopener
        local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if pg then
            -- Destruir reopeners anteriores
            for _, ch in ipairs(pg:GetChildren()) do
                if ch:IsA("ScreenGui") and (ch.Name == "reReopener" or ch.Name:find("Reopener")) then
                    pcall(function() ch:Destroy() end)
                end
            end
            local rGui2 = Instance.new("ScreenGui")
            rGui2.Name = "reReopener"
            rGui2.ResetOnSpawn = false
            rGui2.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            rGui2.DisplayOrder = 9998
            rGui2.Parent = pg
            local SKULL_SIZE2 = 70
            local skullMF2 = Instance.new("Frame", rGui2)
            skullMF2.BackgroundTransparency = 1
            skullMF2.AnchorPoint = Vector2.new(0.5, 0)
            skullMF2.Size = UDim2.new(0, SKULL_SIZE2, 0, SKULL_SIZE2)
            skullMF2.Position = UDim2.new(0.5, 0, 0, 10)
            local rBtn2 = Instance.new("TextButton", skullMF2)
            rBtn2.AnchorPoint = Vector2.new(0.5, 0.5)
            rBtn2.Position = UDim2.new(0.5, 0, 0.5, 0)
            rBtn2.Size = UDim2.new(0, 0, 0, 0)
            rBtn2.BackgroundColor3 = Color3.fromRGB( 50, 255, 180)
            rBtn2.BackgroundTransparency = 0.3
            rBtn2.BorderSizePixel = 0
            rBtn2.Text = "zerqon"
            rBtn2.TextColor3 = Color3.fromRGB(255, 255, 255)
            rBtn2.TextScaled = true
            rBtn2.FontFace = Font.fromEnum(Enum.Font.Montserrat)
            rBtn2.ZIndex = 100
            rBtn2.Active = true
            rBtn2.AutoButtonColor = false
            Instance.new("UICorner", rBtn2).CornerRadius = UDim.new(0, 12)
            local _rBtn2Stroke = Instance.new("UIStroke", rBtn2)
            _rBtn2Stroke.Color = Color3.fromRGB( 50, 255, 180)
            _rBtn2Stroke.Thickness = 1.5
            _rBtn2Stroke.Transparency = 0.1
            _rBtn2Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            local _rBtn2Grad = Instance.new("UIGradient", rBtn2)
            _rBtn2Grad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(200, 35, 130)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 80, 170)),
            })
            _rBtn2Grad.Rotation = 135
            TweenService:Create(rBtn2, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                Size = UDim2.new(0, SKULL_SIZE2 * 0.9, 0, SKULL_SIZE2 * 0.9)
            }):Play()
            local _rBtn2Clicked = false
            local function _reopenHub()
                if _rBtn2Clicked then return end
                _rBtn2Clicked = true
                task.delay(0.1, function()
                    pcall(function() rGui2:Destroy() end)
                    -- FIX: buscar hub en PlayerGui, CoreGui Y gethui() para no llamar abrirHub() innecesariamente
                    local existingHub = LocalPlayer.PlayerGui:FindFirstChild("f")
                                     or game:GetService("CoreGui"):FindFirstChild("f")
                                     or (gethui and gethui():FindFirstChild("f"))
                    if existingHub and _G._hubHidden then
                        -- FIX TAMA?O REOPEN MOBILE: escala correcta ANTES de Enabled=true
                        local _tgtSc = (_getTargetScale and _getTargetScale() or 0.70)
                        local uiScaleR = mainFrame and mainFrame:FindFirstChildOfClass("UIScale")
                        if uiScaleR then uiScaleR.Scale = _tgtSc * 0.75 end
                        if mainFrame and mainFrame.Parent then
                            mainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
                            mainFrame.Position    = UDim2.new(0.5, 0, 0.5, 0)
                        end
                        existingHub.Enabled = true
                        _G._hubHidden = false
                        -- FIX BINDABLES: restaurar todos los botones/bindables flotantes al reabrir
                        pcall(function() if _G._setAllBindablesVisible then _G._setAllBindablesVisible(true) end end)
                        if uiScaleR then
                            TweenService:Create(uiScaleR, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = _tgtSc}):Play()
                        end
                    else
                        task.spawn(abrirHub)
                    end
                end)
            end
            rBtn2.Activated:Connect(_reopenHub)
            rBtn2.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.Touch then _reopenHub() end
            end)
        end
    end
    -- Conectar tanto MouseButton1Click como InputBegan (touch) para compatibilidad movil
    arrowToggleBtn.Activated:Connect(_arrowBtnFire)  -- FIX MOBILE: reemplaza MouseButton1Click
    arrowToggleBtn.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.Touch then _arrowBtnFire() end
    end)

    restoreBtn.Activated:Connect(function()
        _goBackToEmpty()
    end)

    -- -- HOME PANEL  visible cuando no hay tab abierta --------------------------
    local homePanel = Instance.new("Frame", mainFrame)
    homePanel.Name = "HomePanel"
    homePanel.Size = UDim2.new(1, 0, 1, -36)
    homePanel.Position = UDim2.new(0, 0, 0, 36)
    homePanel.BackgroundTransparency = 1
    homePanel.BorderSizePixel = 0
    homePanel.ZIndex = 5
    homePanel.ClipsDescendants = false

    -- HOME PANEL: avatar del jugador grande + info del hub abajo
    local hpCard = Instance.new("Frame", homePanel)  -- dummy para compatibilidad
    hpCard.Name = "HomeUserCard"
    hpCard.Size = UDim2.new(0, 0, 0, 0)
    hpCard.BackgroundTransparency = 1
    hpCard.BorderSizePixel = 0
    hpCard.ZIndex = 1
    local hpStroke = Instance.new("UIStroke", hpCard)
    local hpPremiumBadge = Instance.new("Frame", hpCard)
    hpPremiumBadge.Size = UDim2.new(0,0,0,0)
    hpPremiumBadge.BackgroundTransparency = 1
    local hpPremiumLbl = Instance.new("TextLabel", hpPremiumBadge)
    hpPremiumLbl.Text = ""
    hpPremiumLbl.BackgroundTransparency = 1
    local function _updateHomePremiumStatus() end
    _updateHomePremiumStatus()

    -- === PANEL AVATAR (cuadro grande, imagen 3) ===
    -- (barras de info eliminadas)

    -- Mostrar/ocultar homePanel segun si hay tab activa
    -- FIX LAG: solo un loop activo a la vez. Cada vez que abrirHub() reconstruye
    -- el hub se spawneaba un loop nuevo sin matar el anterior, acumulando N loops
    -- corriendo en paralelo (uno por cada vez que se abrio el hub).
    if not _G._homePanelLoopActive then
        _G._homePanelLoopActive = true
        task.spawn(function()
            while homePanel and homePanel.Parent do
                homePanel.Visible = not _G._tabContentActive
                task.wait(0.1)
            end
            _G._homePanelLoopActive = false
        end)
    end

    -- Hub inicia sin cargar ningn tab (contentContainer.Visible = false)
    -- El tab se carga solo cuando el usuario clickea un botn

    -- FIX CARGA: garantizar que el hub siempre sea visible aunque la animacion falle
    -- Se pone un fallback de 15s que muestra el hub de todas formas
    mainFrame.Visible = false
    mainFrame.BackgroundTransparency = 1
    task.delay(15, function()
        if not _G._hubReady then
            warn("[HUB] Animacion de carga tardo demasiado, forzando inicio")
            pcall(function()
                mainFrame.Visible = true
                mainFrame.BackgroundTransparency = 1
                local _uiSF = mainFrame:FindFirstChildOfClass("UIScale")
                if _uiSF then _uiSF.Scale = (_getTargetScale and _getTargetScale() or 0.70) end
                if header then header.Position = UDim2.new(0, 0, 0, 0) end
            end)
            _G._hubReady = true
            _G._hubAlreadyBuilt = true
            _G._hubRunning = false  -- liberar lock: hub listo
            pcall(ApplyTheme, "Neon Green")
            task.defer(function()
                _G._tabContentActive = false
                -- FIX: hub inicia SIN pestana abierta; el usuario elige al clickear
            -- FIX FONDO: restaurar el fondo seleccionado si habia uno activo
            task.delay(1.5, function()
                local _savedBg = _G._hubBackgrounds and _G._hubBackgrounds.current or 0
                -- FIX COLORES REABRIR: si _restoreBackground ya existe, usarlo.
                -- Si no existe (tab Use aun no buildeado), aplicar tema guardado directamente.
                -- OPT: delay aumentado a 1.5s para que el tab 1 termine de renderizar
                if _savedBg > 0 and _G._restoreBackground then
                    pcall(_G._restoreBackground, _savedBg)
                else
                    pcall(ApplyTheme, "Neon Green")
                end
            end)
            end)
        end
    end)

    -- ================================================================
    -- ANIMACION DE APERTURA DEL HUB (sin pantalla de carga vieja)
    -- La animacion de carga es el checklist de la key screen.
    -- El hub aparece directamente con fade-in y opciones cayendo.
    -- ================================================================
    task.spawn(function()
        local _animOk, _animErr = pcall(function()
        if _G._hubAlreadyBuilt then
            -- Reapertura sin animacion: pop-in suave
            local _tgtSc2 = (_getTargetScale and _getTargetScale() or 0.70)
            local _uiSR = mainFrame:FindFirstChildOfClass("UIScale")
            if _uiSR then _uiSR.Scale = _tgtSc2 * 0.75 end
            mainFrame.Visible = true
            mainFrame.BackgroundTransparency = 1
            if _uiSR then
                TweenService:Create(_uiSR, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = _tgtSc2}):Play()
            end
            header.Position = UDim2.new(0, 0, 0, 0)
            TweenService:Create(glowBorder, TweenInfo.new(0.25, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {Thickness = 0, Transparency = 1.0}):Play()
            _G._hubReady = true
            mainFrame.BackgroundTransparency = 1
            task.defer(function()
                _G._tabContentActive = false
                contentContainer.Visible = true
                contentContainer.Size     = UDim2.new(0.78, 0, 1, -36)
                contentContainer.Position = UDim2.new(0, 0, 0, 36)
                tabDockFrame.Size         = UDim2.new(0.22, 0, 1, -36)
                tabDockFrame.Position     = UDim2.new(0.78, 0, 0, 36)
                pcall(function() SetActiveTab(1) end)
                task.delay(1.5, function()
                    local _savedBg = _G._hubBackgrounds and _G._hubBackgrounds.current or 0
                    if _savedBg > 0 and _G._restoreBackground then
                        pcall(_G._restoreBackground, _savedBg)
                    else
                        pcall(ApplyTheme, "Neon Green")
                    end
                end)
            end)
            task.delay(5.5, function() pcall(function() _buildTabCached(5) end) end)
            task.delay(2.5, function() pcall(function() _buildTabCached(2) end) end)
            task.delay(4.0, function() pcall(function() _buildTabCached(3) end) end)
            task.delay(7.0, function() pcall(function() _buildTabCached(6) end) end)
            task.delay(9.0, function() pcall(function() _buildTabCached(7) end) end)
            task.delay(11.0, function() pcall(function() _buildTabCached(8) end) end)
            task.delay(13.0, function() pcall(function() _buildTabCached(9) end) end)
            return
        end

        -- ================================================================
        -- PRIMERA APERTURA: el hub aparece con fade-in y opciones cayendo
        -- SIN pantalla de carga vieja (oval / barra de progreso eliminada)
        -- ================================================================

        -- Escala correcta antes de hacer visible
        local _tgtSc = (_getTargetScale and _getTargetScale() or 0.70)
        local _uiSc  = mainFrame:FindFirstChildOfClass("UIScale")
        if _uiSc then _uiSc.Scale = _tgtSc end

        -- Empezar invisible y desde ligeramente arriba
        mainFrame.BackgroundTransparency = 1
        mainFrame.Visible = true
        local _origPos = mainFrame.Position
        mainFrame.Position = UDim2.new(
            _origPos.X.Scale, _origPos.X.Offset,
            _origPos.Y.Scale - 0.06, _origPos.Y.Offset
        )

        -- Fade-in del frame principal con ca?da suave
        TweenService:Create(mainFrame,
            TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {Position = _origPos, BackgroundTransparency = 0}
        ):Play()

        -- Hijos caen con efecto cascada (cada uno con delay creciente)
        task.spawn(function()
            task.wait(0.1)
            local _children = mainFrame:GetChildren()
            for i, _child in ipairs(_children) do
                if _child:IsA("Frame") or _child:IsA("TextLabel")
                or _child:IsA("TextButton") or _child:IsA("ImageLabel")
                or _child:IsA("ScrollingFrame") then
                    local _cp = _child.Position
                    local _origTrans = _child.BackgroundTransparency
                    _child.Position = UDim2.new(_cp.X.Scale, _cp.X.Offset, _cp.Y.Scale - 0.04, _cp.Y.Offset)
                    local _delay = (i - 1) * 0.04
                    task.delay(_delay, function()
                        if _child and _child.Parent then
                            TweenService:Create(_child,
                                TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                                {Position = _cp}
                            ):Play()
                        end
                    end)
                end
            end
        end)

        -- Glow border fade out suave
        TweenService:Create(glowBorder, TweenInfo.new(0.35, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
            Thickness = 0,
            Transparency = 1.0
        }):Play()

        task.wait(0.6)

        -- Hub listo
        _G._hubReady = true
        _G._hubAlreadyBuilt = true
        _G._hubRunning = false
        pcall(ApplyTheme, "Neon Green")

        task.defer(function()
            _G._tabContentActive = false
            contentContainer.Visible = true
            contentContainer.Size     = UDim2.new(0.78, 0, 1, -36)
            contentContainer.Position = UDim2.new(0, 0, 0, 36)
            tabDockFrame.Size         = UDim2.new(0.22, 0, 1, -36)
            tabDockFrame.Position     = UDim2.new(0.78, 0, 0, 36)
            pcall(function() SetActiveTab(1) end)
            task.delay(0.5, function()
                local _savedBg = _G._hubBackgrounds and _G._hubBackgrounds.current or 0
                if _savedBg > 0 and _G._restoreBackground then
                    pcall(_G._restoreBackground, _savedBg)
                else
                    pcall(ApplyTheme, "Neon Green")
                end
            end)
        end)
        task.delay(5.5, function() pcall(function() _buildTabCached(5) end) end)
        task.delay(2.5, function() pcall(function() _buildTabCached(2) end) end)
        task.delay(4.0, function() pcall(function() _buildTabCached(3) end) end)
        task.delay(7.0, function() pcall(function() _buildTabCached(6) end) end)
        task.delay(9.0, function() pcall(function() _buildTabCached(7) end) end)
        task.delay(11.0, function() pcall(function() _buildTabCached(8) end) end)
        task.delay(13.0, function() pcall(function() _buildTabCached(9) end) end)
        end)  -- cierre pcall animacion
        if not _animOk then
            warn("[HUB] Error en apertura: " .. tostring(_animErr))
            pcall(function()
                mainFrame.Visible = true
                mainFrame.BackgroundTransparency = 0
                local _uiS = mainFrame:FindFirstChildOfClass("UIScale")
                if _uiS then _uiS.Scale = (_getTargetScale and _getTargetScale() or 0.70) end
                if header then header.Position = UDim2.new(0, 0, 0, 0) end
            end)
            _G._hubReady = true
            _G._hubAlreadyBuilt = true
            _G._hubRunning = false
            pcall(ApplyTheme, "Neon Green")
            task.defer(function()
                _G._tabContentActive = false
                contentContainer.Visible = true
                contentContainer.Position = UDim2.new(0, 0, 0, 36)
                pcall(function() SetActiveTab(1) end)
            end)
        end
    end)

LocalPlayer.CharacterAdded:Connect(function(newChar)
    task.wait(0.3)
    local IG = MainSystem and MainSystem.state and MainSystem.state.invisibleGhost
    if not IG then return end
    if IG.enabled then
        IG.enabled = false
        local conns = {"floatConn","dummyHBConn","dummySyncConn","dummyJumpConn","controlConn"}
        for _, k in ipairs(conns) do
            if IG[k] then pcall(function() IG[k]:Disconnect() end); IG[k] = nil end
        end
        for _, c in ipairs(IG.animConns or {}) do pcall(function() c:Disconnect() end) end
        IG.animConns = {}
        if IG.dummyModel then
            pcall(function() IG.dummyModel:Destroy() end)
            IG.dummyModel = nil
            IG.dummyHRP   = nil
            IG.dummyHum   = nil
        end
        task.wait(0.3)
        for _, part in ipairs(newChar:GetDescendants()) do
            if part:IsA("BasePart") or part:IsA("MeshPart") then
                part.LocalTransparencyModifier = 0
            end
        end
        local hum = newChar:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed  = 16
            hum.JumpPower  = 50
            hum.AutoRotate = true
        end
    end
end)

WallHopState = WallHopState or {
    enabled      = false,
    touchingWall = false,
    wallNormal   = Vector3.zero,
    canWallJump  = true,
    jumpHeight   = 60,
    detectDist   = 2.5,
    forwardBoost = 1.2,
    cooldown     = 0.08,
    hbConn       = nil,
    inputConn    = nil,
    jumpConn     = nil,
    lastWallHop  = 0,
    wallHopCount = 0,
    -- Wall Stick: mantener pegado a la pared con BodyPosition
    stickEnabled = true,    -- mientras toca la pared, queda pegado (sin caerse)
    stickBody    = nil,     -- BodyPosition para pegarse
    stickGyro    = nil,     -- BodyGyro para orientarse
    climbSpeed   = 18,      -- velocidad de movimiento en la pared (WASD)
}

function WallHop_Stop()
    for _, k in ipairs({"hbConn","inputConn","jumpConn"}) do
        if WallHopState[k] then WallHopState[k]:Disconnect(); WallHopState[k]=nil end
    end
    -- Limpiar stick bodies
    if WallHopState.stickBody then pcall(function() WallHopState.stickBody:Destroy() end); WallHopState.stickBody = nil end
    if WallHopState.stickGyro then pcall(function() WallHopState.stickGyro:Destroy() end); WallHopState.stickGyro = nil end
    -- Restaurar fsica
    pcall(function()
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.PlatformStand = false end
        workspace.Gravity = 196.2
    end)
    WallHopState.touchingWall = false
    WallHopState.canWallJump  = true
    WallHopState.wallNormal   = Vector3.zero
    WallHopState.wallHopCount = 0
end

function WallHop_Start()
    WallHop_Stop()

    -- Deteccin de pared: cada frame para mxima responsividad
    -- OPT: cachear params fuera del loop (antes se creaba RaycastParams.new() cada frame)
    local _whParams = RaycastParams.new()
    _whParams.FilterType = Enum.RaycastFilterType.Exclude
    local _whLastChar = nil

    WallHopState.hbConn = _safeConnect(RunService.Heartbeat, function()
        local char = LocalPlayer.Character
        if not char then WallHopState.touchingWall = false; return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then WallHopState.touchingWall = false; return end

        local hs = hum:GetState()
        local isGrounded = (hs == Enum.HumanoidStateType.Running
            or hs == Enum.HumanoidStateType.RunningNoPhysics
            or hs == Enum.HumanoidStateType.Landed)

        -- Si est en el suelo, resetear y no detectar pared
        if isGrounded then
            WallHopState.canWallJump  = true
            WallHopState.wallHopCount = 0
            WallHopState.touchingWall = false
            return
        end

        -- Solo detectar pared cuando est en el aire (Jumping / Freefall)
        -- OPT: solo reconstruir ignore list si el char cambi
        if char ~= _whLastChar then
            local ignore = {char}
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer and p.Character then table.insert(ignore, p.Character) end
            end
            _whParams.FilterDescendantsInstances = ignore
            _whLastChar = char
        end
        local params = _whParams

        local d = WallHopState.detectDist
        local fwd = hrp.CFrame.LookVector
        local rgt = hrp.CFrame.RightVector
        local dirs = {
            fwd, -fwd, rgt, -rgt,
            (fwd + rgt).Unit, (fwd - rgt).Unit,
            (-fwd + rgt).Unit, (-fwd - rgt).Unit,
        }
        local origins = {
            hrp.Position,
            hrp.Position + Vector3.new(0,  1.5, 0),
            hrp.Position + Vector3.new(0, -1.0, 0),
        }

        local hitNormal = nil
        for _, origin in ipairs(origins) do
            for _, dir in ipairs(dirs) do
                local res = workspace:Raycast(origin, dir * d, params)
                if res and res.Instance
                and res.Instance.CanCollide
                and res.Instance.Transparency < 0.85 then
                    local normFlat = Vector3.new(res.Normal.X, 0, res.Normal.Z)
                    if normFlat.Magnitude > 0.4 then
                        hitNormal = res.Normal
                        break
                    end
                end
            end
            if hitNormal then break end
        end

        WallHopState.touchingWall = hitNormal ~= nil
        WallHopState.wallNormal   = hitNormal or Vector3.zero

        -- -- WALL STICK: pegarse a la pared mientras la toca ------------
        if hitNormal and WallHopState.stickEnabled then
            -- Crear BodyPosition para quedar pegado si no existe
            if not WallHopState.stickBody or not WallHopState.stickBody.Parent then
                local bp = Instance.new("BodyPosition")
                bp.Name     = "WallStickBP"
                bp.MaxForce = Vector3.new(5e4, 5e4, 5e4)
                bp.P = 8000; bp.D = 800
                bp.Parent = hrp
                WallHopState.stickBody = bp
            end
            -- Mantener pegado a la superficie
            local stickPos = hrp.Position
            WallHopState.stickBody.Position = stickPos

            -- BodyGyro para orientarse hacia la pared
            if not WallHopState.stickGyro or not WallHopState.stickGyro.Parent then
                local bg = Instance.new("BodyGyro")
                bg.Name     = "WallStickBG"
                bg.MaxTorque = Vector3.new(1e4, 1e4, 1e4)
                bg.P = 5000; bg.D = 500
                bg.Parent = hrp
                WallHopState.stickGyro = bg
            end
            -- Orientar el personaje con los pies hacia la pared
            local upVec = hitNormal
            local look  = workspace.CurrentCamera.CFrame.LookVector
            local proj  = (look - upVec * look:Dot(upVec))
            if proj.Magnitude > 0.01 then proj = proj.Unit end
            WallHopState.stickGyro.CFrame = CFrame.fromMatrix(hrp.Position, proj:Cross(upVec), upVec)

            hum.PlatformStand = true  -- deshabilitar fsica normal
            workspace.Gravity = 0     -- sin gravedad mientras pegado

            -- WASD para moverse por la pared
            local cam   = workspace.CurrentCamera
            local right = (cam.CFrame.RightVector - upVec * cam.CFrame.RightVector:Dot(upVec))
            local fwd   = (cam.CFrame.LookVector  - upVec * cam.CFrame.LookVector:Dot(upVec))
            if right.Magnitude > 0.01 then right = right.Unit end
            if fwd.Magnitude   > 0.01 then fwd   = fwd.Unit   end
            local moveDir = Vector3.zero
            local UIS = game:GetService("UserInputService")
            if UIS:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + fwd end
            if UIS:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - fwd end
            if UIS:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - right end
            if UIS:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + right end
            if moveDir.Magnitude > 0.01 then
                WallHopState.stickBody.Position = WallHopState.stickBody.Position
                    + moveDir.Unit * WallHopState.climbSpeed * 0.016
            end

        elseif not hitNormal then
            -- Sali de la pared: restaurar fsica normal
            if WallHopState.stickBody then
                pcall(function() WallHopState.stickBody:Destroy() end)
                WallHopState.stickBody = nil
            end
            if WallHopState.stickGyro then
                pcall(function() WallHopState.stickGyro:Destroy() end)
                WallHopState.stickGyro = nil
            end
            if hum then hum.PlatformStand = false end
            workspace.Gravity = 196.2
        end
    end)

    -- Saltar desde la pared al presionar Space
    WallHopState.inputConn = UserInputService.InputBegan:Connect(function(input, gp)
        if gp then return end
        if input.KeyCode ~= Enum.KeyCode.Space then return end
        if not WallHopState.touchingWall then return end

        local now = tick()
        if now - WallHopState.lastWallHop < WallHopState.cooldown then return end

        local char = LocalPlayer.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        WallHopState.lastWallHop = now

        -- Destruir el stick para soltar la pared
        if WallHopState.stickBody then
            pcall(function() WallHopState.stickBody:Destroy() end)
            WallHopState.stickBody = nil
        end
        if WallHopState.stickGyro then
            pcall(function() WallHopState.stickGyro:Destroy() end)
            WallHopState.stickGyro = nil
        end
        hum.PlatformStand = false
        workspace.Gravity = 196.2

        -- Impulso de salto perpendicular a la pared
        local normal  = WallHopState.wallNormal
        local normH   = Vector3.new(normal.X, 0, normal.Z)
        if normH.Magnitude < 0.01 then normH = Vector3.new(0, 0, 1) end
        normH = normH.Unit
        local newVel = Vector3.new(
            normH.X * WallHopState.jumpHeight * WallHopState.forwardBoost,
            WallHopState.jumpHeight,
            normH.Z * WallHopState.jumpHeight * WallHopState.forwardBoost
        )
        pcall(function() hrp.AssemblyLinearVelocity = newVel end)
        task.delay(WallHopState.cooldown, function()
            WallHopState.canWallJump = true
        end)
    end)

end

LocalPlayer.CharacterAdded:Connect(function()
    if WallHopState and WallHopState.enabled then
        task.wait(0.4)
        WallHop_Start()
    end
end)




