function CreateUseTab()
    -- Guard: verificar contentContainer sin usar task.wait (el wait romperia la redireccion
    -- de contentContainer que hace _buildTabCached, dejando la pestana en blanco)
    -- FIX PESTANA USE EN BLANCO: el guard de .Parent fue eliminado porque _buildTabCached
    -- redirige contentContainer a un tabFrame que puede no tener parent aun en build
    -- background, causando que el tab quedara completamente vacio.
    if not contentContainer then return end
    -- Resetear frame de secci?n residual ANTES de construir columnas
    _currentMainSectionFrame = nil
    _makeTwoColumns()
    -- FIX RACE CONDITION: capturar leftColumn/rightColumn como locales INMEDIATAMENTE
    -- despues de _makeTwoColumns(), antes de cualquier yield/spawn. Las variables globales
    -- leftColumn y rightColumn pueden ser pisadas por el pre-build de otros tabs en background
    -- (task.delay 1.9s = USE, 2.2s = EMOTES se solapan), causando que el contenido del USE
    -- tab se construya dentro del frame equivocado (tab de Emotes) y quede en blanco.
    local leftColumn  = leftColumn   -- shadow del global: protege contra pisadas concurrentes
    local rightColumn = rightColumn  -- idem
    local col = leftColumn

    local bangSec = CreateBorderedSectionGlobal(col, " BANG")

    local _bang = {
        animSpeed      = 1.0,
        animTrack      = nil,
        conns          = { random=nil, murder=nil, sheriff=nil, innocent=nil },
        enabled        = { random=false, murder=false, sheriff=false, innocent=false },
        specificTarget = nil,
    }

    local BANG_ANIM_ID = "rbxassetid://5918726674"

    local function _bangPlayAnim()
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        local animr = hum and hum:FindFirstChildOfClass("Animator")
        if not animr then return end

        if _bang.animTrack and _bang.animTrack.IsPlaying then return end

        local a = Instance.new("Animation")
        a.AnimationId = BANG_ANIM_ID
        local ok, track = pcall(function() return animr:LoadAnimation(a) end)
        if ok and track then
            track:AdjustSpeed(_bang.animSpeed)
            track:Play()
            _bang.animTrack = track
            track.Stopped:Connect(function() _bang.animTrack = nil end)
        end
    end

    local function _bangGoto(target)
        if not target or not target.Character then return end
        local tHRP  = target.Character:FindFirstChild("HumanoidRootPart")
        if not tHRP then return end
        local myChar = LocalPlayer.Character
        local myHRP  = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return end

        -- FIX BANG ESPALDA: Z positivo = detras del personaje (espalda)
        -- En Roblox el LookVector apunta hacia "adelante" del model,
        -- entonces +Z va hacia la espalda del personaje objetivo
        local dist = _bang._behindDist or 2.5
        local offY = _bang._offsetY or 0
        local behindCF = tHRP.CFrame * CFrame.new(0, offY, dist)

        pcall(function()
            myHRP.CFrame = CFrame.new(behindCF.Position, tHRP.Position)
            myHRP.AssemblyLinearVelocity = Vector3.zero
        end)
    end

    local function _bangGetTarget(role)
        if role == "specific" then return _bang.specificTarget end
        _refreshRoleCache()
        if role == "random" then
            local list = {}
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer and p.Character then
                    local h = p.Character:FindFirstChildOfClass("Humanoid")
                    if h and h.Health > 0 then table.insert(list, p) end
                end
            end
            return #list > 0 and list[math.random(1,#list)] or nil
        elseif role == "murder" then return _roleCache.murderer
        elseif role == "sheriff" then return _roleCache.sheriff
        elseif role == "innocent" then
            for _, p in ipairs(_cachedPlayers) do
                if p ~= LocalPlayer and p ~= _roleCache.murderer and p ~= _roleCache.sheriff then
                    if p.Character then
                        local h = p.Character:FindFirstChildOfClass("Humanoid")
                        if h and h.Health > 0 then return p end
                    end
                end
            end
        end
        return nil
    end

    local _bangLastTP = 0
    local function _bangStart(role)
        if _bang.conns[role] then pcall(function() _bang.conns[role]:Disconnect() end) end
        local _hbTbangConns = 0
        _bang.conns[role] = RunService.Heartbeat:Connect(function()
            _hbTbangConns=_hbTbangConns+1; if _hbTbangConns<3 then return end; _hbTbangConns=0
            if not _bang.enabled[role] then return end
            if _G._visualRoundOver then return end  -- OPT: pausar al fin de ronda
            local now = tick()
            if now - _bangLastTP < (_bang._interval or 0.05) then return end
            _bangLastTP = now
            local t = _bangGetTarget(role)
            if not t then return end
            _bangGoto(t)
            _bangPlayAnim()
        end)
    end
    local function _bangStop(role)
        _bang.enabled[role] = false
        if _bang.conns[role] then pcall(function() _bang.conns[role]:Disconnect() end); _bang.conns[role] = nil end
        if _bang.animTrack  then pcall(function() _bang.animTrack:Stop(0.15)       end); _bang.animTrack  = nil end
    end

 CreateSlider(bangSec, "Animation Speed (x10)", 1, 30, 10, function(v)
        _bang.animSpeed = v / 10
        if _bang.animTrack and _bang.animTrack.IsPlaying then
            pcall(function() _bang.animTrack:AdjustSpeed(_bang.animSpeed) end)
        end
    end)

    local _bangToggleDefs = {
 { label = "Bang Random Player", role = "random" },
 { label = "Bang Murder", role = "murder" },
 { label = "Bang Sheriff", role = "sheriff" },
 { label = "Bang Innocent", role = "innocent" },
    }
    for _, def in ipairs(_bangToggleDefs) do
        local capturedRole = def.role
        local capturedLabel = def.label
 CreateAuroraToggle(bangSec, capturedLabel, function(on)
            _bang.enabled[capturedRole] = on
 if on then _bangStart(capturedRole); CreateCustomNotification("BANG", capturedLabel.." ON", 2)
 else _bangStop(capturedRole); CreateCustomNotification("BANG", capturedLabel.." OFF",2) end
        end, false)

        -- Bindable button para cada tipo de bang
 CreateAuroraToggle(bangSec, " Bindable: " .. capturedLabel, function(on)
            local guiName = "BangBind_" .. capturedRole
            local function sweep(p)
                if not p then return end
                for _, g in ipairs(p:GetChildren()) do
                    if g.Name == guiName then pcall(function() g:Destroy() end) end
                end
            end
            sweep(CoreGui)
            pcall(function() sweep(LocalPlayer:FindFirstChild("PlayerGui")) end)
            if on then
                local sg = Instance.new("ScreenGui")
                sg.Name = guiName; sg.ResetOnSpawn = false
                sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                sg.IgnoreGuiInset = true; sg.DisplayOrder = 9900
                pcall(function() sg.Parent = CoreGui end)
                if not sg.Parent then sg.Parent = LocalPlayer.PlayerGui end
                MakeCapyBindableFrame(sg, capturedLabel:upper():sub(1,8), function()
                    _bang.enabled[capturedRole] = not _bang.enabled[capturedRole]
                    if _bang.enabled[capturedRole] then
                        _bangStart(capturedRole)
 CreateCustomNotification("BANG", capturedLabel .. " ON", 1.5)
                    else
                        _bangStop(capturedRole)
 CreateCustomNotification("BANG", capturedLabel .. " OFF", 1.5)
                    end
                end, 200, 50)
            end
        end, false)
    end

    -- Sliders adicionales para Bang
 CreateSlider(bangSec, "Intervalo Bang (seg x100)", 1, 50, 5, function(v)
        -- intervalo entre bangs en centesimas de segundo
        _bang._interval = v / 100
    end)
 CreateSlider(bangSec, "Distancia Detras (studs x10)", 5, 80, 25, function(v)
        _bang._behindDist = v / 10
    end)
 CreateSlider(bangSec, "Offset Altura (Y)", -5, 10, 0, function(v)
        _bang._offsetY = v
    end)

    LocalPlayer.CharacterAdded:Connect(function()
        _bang.animTrack = nil
    end)

    -- == WALL HOP V2 ==
    local whSec = CreateBorderedSectionGlobal(rightColumn, " WALL HOP V2")

    local _whActive      = false
    local _whJumpEnabled = true
    local _whInputConn   = nil

    local _whRcParams = RaycastParams.new()
    _whRcParams.FilterType = Enum.RaycastFilterType.Exclude

    local function _wh_GetWallRaycast()
        local char = Players.LocalPlayer.Character
        if not char then return nil end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        _whRcParams.FilterDescendantsInstances = {char}
        local dirs = {
            hrp.CFrame.LookVector,
            -hrp.CFrame.LookVector,
            hrp.CFrame.RightVector,
            -hrp.CFrame.RightVector,
        }
        local detDist = 2
        local closest = nil
        local minDist = detDist + 1
        for _, dir in ipairs(dirs) do
            local ray = Workspace:Raycast(hrp.Position, dir * detDist, _whRcParams)
            if ray and ray.Instance and ray.Distance < minDist then
                minDist = ray.Distance
                closest = ray
            end
        end
        return closest
    end

    local function _wh_Stop()
        if _whInputConn then _whInputConn:Disconnect(); _whInputConn = nil end
        _whActive      = false
        _whJumpEnabled = true
    end

    local function _wh_Start()
        _wh_Stop()
        _whActive      = true
        _whJumpEnabled = true

        _whInputConn = UserInputService.JumpRequest:Connect(function()
            if not _whActive or not _whJumpEnabled then return end

            local char     = Players.LocalPlayer.Character
            local humanoid = char and char:FindFirstChildOfClass("Humanoid")
            local rootPart = char and char:FindFirstChild("HumanoidRootPart")
            local camera   = _Camera
            if not (humanoid and rootPart and camera) then return end

            local wallHit = _wh_GetWallRaycast()
            if not wallHit then return end

            _whJumpEnabled = false

            local wallNormal = wallHit.Normal
            local normH      = Vector3.new(wallNormal.X, 0, wallNormal.Z)
            local baseDir    = normH.Magnitude > 0.1 and normH.Unit
                               or (rootPart.CFrame.LookVector * Vector3.new(1,0,1)).Unit
            if baseDir.Magnitude < 0.1 then baseDir = Vector3.new(0,0,-1) end

            local camLook = camera.CFrame.LookVector
            local camH    = Vector3.new(camLook.X, 0, camLook.Z)
            local camDir  = camH.Magnitude > 0.1 and camH.Unit or baseDir

            local maxAngle     = math.rad(40)
            local dot          = math.clamp(baseDir:Dot(camDir), -1, 1)
            local angle        = math.acos(dot)
            local cross        = baseDir:Cross(camDir)
            local sign         = math.sign(cross.Y)
            if sign == 0 then angle = 0 end
            local clampedAngle = math.min(angle, maxAngle)
            local rot          = CFrame.Angles(0, clampedAngle * sign, 0)
            local targetDir    = rot * baseDir

            rootPart.CFrame = CFrame.lookAt(rootPart.Position, rootPart.Position + targetDir)
            RunService.Heartbeat:Wait()

            if humanoid and humanoid:GetState() ~= Enum.HumanoidStateType.Dead then
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                rootPart.CFrame = CFrame.lookAt(rootPart.Position, rootPart.Position + (-baseDir))
            end

            _w(0.15)
            _whJumpEnabled = true
        end)
    end

    CreateAuroraToggle(whSec, "Wall Hop V2", function(on)
        if on then
            _wh_Start()
            -- [notif removed]
        else
            _wh_Stop()
            -- [notif removed]
        end
    end, false)

