 sheriffNameLbl.BackgroundTransparency = 1; sheriffNameLbl.Text = " SHERIFF: ?"
    sheriffNameLbl.FontFace = Font.fromEnum(Enum.Font.Montserrat); sheriffNameLbl.TextSize = 9
    sheriffNameLbl.TextColor3 = Color3.fromRGB(141, 141, 141)
    sheriffNameLbl.TextXAlignment = Enum.TextXAlignment.Center; sheriffNameLbl.TextTruncate = Enum.TextTruncate.AtEnd; sheriffNameLbl.ZIndex = 14

    local allPlayersFrame = Instance.new("ScrollingFrame", infoRolesSec)
    allPlayersFrame.Size = UDim2.new(1,0,0,140)
    allPlayersFrame.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
