    allPlayersFrame.CanvasSize = UDim2.new(0,0,0,0)
    allPlayersFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
    Instance.new("UICorner", allPlayersFrame).CornerRadius = UDim.new(0,8)
    local apLayout = Instance.new("UIListLayout", allPlayersFrame)
    apLayout.Padding = UDim.new(0,3)
    apLayout.SortOrder = Enum.SortOrder.LayoutOrder
    local apPad = Instance.new("UIPadding", allPlayersFrame)
    apPad.PaddingLeft = UDim.new(0,5); apPad.PaddingTop = UDim.new(0,4); apPad.PaddingRight = UDim.new(0,5)

    local _playerRows = {}
    local function _rebuildPlayerRows()
        for _, r in pairs(_playerRows) do pcall(function() r:Destroy() end) end
        _playerRows = {}
        for _, p in ipairs(_cachedPlayers) do
            local row = Instance.new("Frame", allPlayersFrame)
            row.Size = UDim2.new(1,0,0,38)
            row.BackgroundColor3 = Color3.fromRGB(20, 35, 80)
            row.BackgroundTransparency = 0.75
            row.BorderSizePixel = 0
            Instance.new("UICorner", row).CornerRadius = UDim.new(0,6)

            local av = Instance.new("ImageLabel", row)
            av.Size = UDim2.new(0,30,0,30); av.Position = UDim2.new(0,4,0.5,-15)
            av.BackgroundTransparency = 1
            av.Image = "rbxassetid://0"

            local nm = Instance.new("TextLabel", row)
            nm.Size = UDim2.new(0.55,0,0,18); nm.Position = UDim2.new(0,40,0,2)
 nm.BackgroundTransparency = 1; nm.Text = p.DisplayName
