        applyBtn.Activated:Connect(function()
            local selColor = colorSwatch.BackgroundColor3
            local r = math.floor(selColor.R * 255)
            local g = math.floor(selColor.G * 255)
            local b = math.floor(selColor.B * 255)

            local function darken(c, f)
                return Color3.fromRGB(
                    math.clamp(math.floor(c.R*255*f), 0, 255),
                    math.clamp(math.floor(c.G*255*f), 0, 255),
                    math.clamp(math.floor(c.B*255*f), 0, 255))
            end
            local function lighten(c, f)
                return Color3.fromRGB(
                    math.clamp(math.floor(c.R*255 + (255 - c.R*255)*f), 0, 255),
                    math.clamp(math.floor(c.G*255 + (255 - c.G*255)*f), 0, 255),
                    math.clamp(math.floor(c.B*255 + (255 - c.B*255)*f), 0, 255))
            end

            local base   = Color3.fromRGB(r, g, b)
            local dark1  = darken(base, 0.45)
            local dark2  = darken(base, 0.60)
            local bright = lighten(base, 0.25)
            local pale   = lighten(base, 0.65)
            local pale2  = lighten(base, 0.40)
            local mid    = darken(base, 0.75)

            local CUSTOM_NAME = "__CustomHTMLColor__"
            Themes[CUSTOM_NAME] = {
                Primary         = base,
                Secondary       = mid,
                Accent          = bright,
                Background      = dark1,
                BackgroundLight = dark2,
                TextPrimary     = pale,
                TextSecondary   = pale2,
                Aurora1         = base,
                Aurora2         = bright,
                Aurora3         = pale2,
                Aurora4         = mid,
            }

            pcall(function() ApplyTheme(CUSTOM_NAME) end)

            pcall(function()
                local bg = _G._hubBgMainImageRef
                    or (mainFrame and mainFrame:FindFirstChild("HubBackground"))
                if bg then
                    TweenService:Create(bg, TweenInfo.new(0.4, Enum.EasingStyle.Sine), {
                        ImageColor3 = dark1
                    }):Play()
                end
                if glowBorder then
                    TweenService:Create(glowBorder, TweenInfo.new(0.3), {Color = base}):Play()
                end
            end)

            applyBtn.BackgroundColor3 = dark1
            applyBtn.TextColor3       = pale
            applyStroke.Color         = bright
            task.delay(0.6, function()
                if applyBtn and applyBtn.Parent then
                    TweenService:Create(applyBtn, TweenInfo.new(0.3), {
                        BackgroundColor3 = dark1
                    }):Play()
                end
            end)

            local hex  = string.format("#%02X%02X%02X", r, g, b)
            local name = colorInfoName.Text or "Color"
            CreateCustomNotification("HUB RECOLOREADO", name .. " " .. hex, 3)
        end)

        -- Boton secundario: restaurar tema original
        local resetBtn = Instance.new("TextButton", colorSec)
        resetBtn.Name                   = "ResetColorBtn"
        resetBtn.Size                   = UDim2.new(1, -8, 0, 22)
        resetBtn.Position               = UDim2.new(0, 4, 0, 0)
        resetBtn.BackgroundColor3       = Color3.fromRGB(  4,  12,  22)
        resetBtn.BackgroundTransparency = 0.5
        resetBtn.BorderSizePixel        = 0
        resetBtn.Text                   = "Restaurar tema original"
        resetBtn.TextSize               = 11
        resetBtn.FontFace               = Font.fromEnum(Enum.Font.Gotham)
        resetBtn.TextColor3             = Color3.fromRGB(180, 80, 100)
        resetBtn.AutoButtonColor        = false
        resetBtn.ZIndex                 = 23
        Instance.new("UICorner", resetBtn).CornerRadius = UDim.new(0, 5)
        local resetStroke = Instance.new("UIStroke", resetBtn)
        resetStroke.Color           = Color3.fromRGB( 50, 255, 180)
        resetStroke.Thickness       = 1
        resetStroke.Transparency    = 0.4
        resetStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border

        resetBtn.MouseEnter:Connect(function()
            TweenService:Create(resetBtn, TweenInfo.new(0.10), {BackgroundTransparency = 0.2}):Play()
        end)
        resetBtn.MouseLeave:Connect(function()
            TweenService:Create(resetBtn, TweenInfo.new(0.12), {BackgroundTransparency = 0.5}):Play()
        end)
        resetBtn.Activated:Connect(function()
            pcall(function() ApplyTheme("Neon Green") end)
            pcall(function()
                local bg = _G._hubBgMainImageRef
                    or (mainFrame and mainFrame:FindFirstChild("HubBackground"))
                if bg then
                    TweenService:Create(bg, TweenInfo.new(0.4), {
                        ImageColor3 = Color3.new(1, 1, 1)
                    }):Play()
                end
                if glowBorder then
                    TweenService:Create(glowBorder, TweenInfo.new(0.3), {
                        Color = Color3.fromRGB(210, 85, 100)
                    }):Play()
                end
            end)
            CreateCustomNotification("RESTAURADO", "Tema original del hub", 2)
        end)
    end

end -- cierra CreateUseTab

_ItemsFakeState = _G._ItemsFakeState or {
    activeKnifeSkin = nil,
    activeGunSkin   = nil,
    fakeKnife       = nil,
    fakeGun         = nil,
}
_G._ItemsFakeState = _ItemsFakeState

end -- cierra abrirHub



-- ================================================================
-- == PANTALLA DE CARGA ZERQON HUB (v2 - FACHERA EDITION)
-- == Mas grande, colores del hub, delays de 3s, animaciones epicas
-- ================================================================
local function _ZerqonLoadingScreen(onComplete)
    local TweenService = game:GetService("TweenService")
    local Players      = game:GetService("Players")
    local lp           = Players.LocalPlayer

    -- Colores del hub (teal/cyan oscuro igual que la UI principal)
    local C_BG_DARK   = Color3.fromRGB( 10,  20,  60)   -- fondo oscuro del hub
    local C_BG_MID    = Color3.fromRGB( 15,  35, 100)   -- azul medio hub
    local C_ACCENT    = Color3.fromRGB(  0, 200, 255)   -- cyan/teal del hub
    local C_CHECK     = Color3.fromRGB( 57, 255, 154)   -- verde check
    local C_WHITE     = Color3.fromRGB(255, 255, 255)
    local C_DIM       = Color3.fromRGB(130, 190, 220)   -- texto apagado
    local C_GLOW      = Color3.fromRGB(  0, 255, 220)   -- brillo teal

    -- ScreenGui
    local sg = Instance.new("ScreenGui")
    sg.Name           = "ZerqonLoadScreen"
    sg.ResetOnSpawn   = false
    sg.DisplayOrder   = 99999
    sg.IgnoreGuiInset = true
    pcall(function()
        if gethui then sg.Parent = gethui()
        else            sg.Parent = game:GetService("CoreGui") end
    end)
    if not sg.Parent then sg.Parent = lp.PlayerGui end

    -- Fondo oscuro semitransparente (backdrop)
    local backdrop = Instance.new("Frame", sg)
    backdrop.Name                 = "Backdrop"
    backdrop.Size                 = UDim2.new(1, 0, 1, 0)
    backdrop.Position             = UDim2.new(0, 0, 0, 0)
    backdrop.BackgroundColor3     = Color3.fromRGB(0, 0, 0)
    backdrop.BackgroundTransparency = 1  -- empieza invisible, fade in
    backdrop.BorderSizePixel      = 0
    backdrop.ZIndex               = 8

    -- Contenedor principal (MAS GRANDE: 420x220)
    local rect = Instance.new("Frame", sg)
    rect.Name                 = "LoadRect"
    rect.Size                 = UDim2.new(0, 420, 0, 220)
    rect.Position             = UDim2.new(0.5, -210, 0.5, -110)
    rect.BackgroundColor3     = C_BG_DARK
    rect.BackgroundTransparency = 1  -- empieza invisible para animacion de entrada
    rect.BorderSizePixel      = 0
    rect.ZIndex               = 10

    -- Esquinas redondeadas
    local corner = Instance.new("UICorner", rect)
    corner.CornerRadius = UDim.new(0, 12)

    -- ClipsDescendants: evita que el HubBackground y el BlinkOverlay se salgan del rect
    rect.ClipsDescendants = true

    -- Borde brillante (stroke teal)
    local stroke = Instance.new("UIStroke", rect)
    stroke.Color       = C_ACCENT
    stroke.Thickness   = 2
    stroke.Transparency = 1  -- empieza invisible

    -- Fondo del hub (imagen principal, igual que en el hub abierto)
    local loadHubBg = Instance.new("ImageLabel", rect)
    loadHubBg.Name                   = "LoadHubBackground"
    loadHubBg.Size                   = UDim2.new(1, 0, 1, 0)
    loadHubBg.Position               = UDim2.new(0, 0, 0, 0)
    loadHubBg.BackgroundTransparency = 1
    loadHubBg.Image                  = "rbxassetid://96937964432645"
    loadHubBg.ImageTransparency      = 0.30
    loadHubBg.ScaleType              = Enum.ScaleType.Stretch
    loadHubBg.ImageRectSize          = Vector2.new(900, 480)
    loadHubBg.ImageRectOffset        = Vector2.new(0, 0)
    loadHubBg.ZIndex                 = 10  -- debajo del contenido pero sobre el fondo solido

    -- Overlay de parpadeo (mismo asset que el hub principal)
    local loadBlinkOverlay = Instance.new("ImageLabel", rect)
    loadBlinkOverlay.Name                   = "LoadBlinkOverlay"
    loadBlinkOverlay.Size                   = UDim2.new(1, 0, 1, 0)
    loadBlinkOverlay.Position               = UDim2.new(0, 0, 0, 0)
    loadBlinkOverlay.BackgroundTransparency = 1
    loadBlinkOverlay.Image                  = "rbxassetid://124196125990159"
    loadBlinkOverlay.ImageTransparency      = 1   -- empieza invisible
    loadBlinkOverlay.ScaleType              = Enum.ScaleType.Stretch
    loadBlinkOverlay.ImageRectSize          = Vector2.new(900, 480)
    loadBlinkOverlay.ImageRectOffset        = Vector2.new(0, 0)
    loadBlinkOverlay.ZIndex                 = 11  -- encima del HubBackground, debajo del contenido
    loadBlinkOverlay.Active                 = false

    -- Gradiente de fondo del rect (encima del hubBg para que el contenido sea legible)
    local grad = Instance.new("UIGradient", rect)
    grad.Color    = ColorSequence.new({
        ColorSequenceKeypoint.new(0, C_BG_DARK),
        ColorSequenceKeypoint.new(1, C_BG_MID),
    })
    grad.Rotation = 135

    -- Header: nombre del hub con icono
    local headerLbl = Instance.new("TextLabel", rect)
    headerLbl.Name               = "Header"
    headerLbl.Size               = UDim2.new(1, -20, 0, 36)
    headerLbl.Position           = UDim2.new(0, 10, 0, 10)
    headerLbl.BackgroundTransparency = 1
    headerLbl.Text               = "? ZERQON HUB"
    headerLbl.TextColor3         = C_ACCENT
    headerLbl.Font               = Enum.Font.GothamBold
    headerLbl.TextSize           = 22
    headerLbl.TextXAlignment     = Enum.TextXAlignment.Left
    headerLbl.TextTransparency   = 1
    headerLbl.ZIndex             = 13

    -- Linea separadora debajo del header
    local divider = Instance.new("Frame", rect)
    divider.Name                 = "Divider"
    divider.Size                 = UDim2.new(1, -20, 0, 1)
    divider.Position             = UDim2.new(0, 10, 0, 50)
    divider.BackgroundColor3     = C_ACCENT
    divider.BackgroundTransparency = 0.5
    divider.BorderSizePixel      = 0
    divider.ZIndex               = 12

    -- Textos de carga (loading) y OK para cada paso
    local loadingTexts = {
        "Conectando...",
        "Autenticando...",
        "Cargando hub...",
    }
    local okTexts = {
        "Connected to Server",
        "No Key  -  Free Script  xD",
        "Ready",
    }

    local rows = {}
    for i = 1, 3 do
        local row = Instance.new("Frame", rect)
        row.Name                 = "Row" .. i
        row.Size                 = UDim2.new(1, -24, 0, 36)
        row.Position             = UDim2.new(0, 12, 0, 58 + (i-1) * 44)
        row.BackgroundTransparency = 1
        row.BorderSizePixel      = 0
        row.ZIndex               = 11

        -- Bolita indicadora izquierda
        local dot = Instance.new("Frame", row)
        dot.Name                 = "Dot"
        dot.Size                 = UDim2.new(0, 10, 0, 10)
        dot.Position             = UDim2.new(0, 2, 0.5, -5)
        dot.BackgroundColor3     = C_DIM
        dot.BorderSizePixel      = 0
        dot.ZIndex               = 13
        local dotCorner = Instance.new("UICorner", dot)
        dotCorner.CornerRadius = UDim.new(1, 0)

        -- Check mark (inicialmente invisible)
        local check = Instance.new("TextLabel", row)
        check.Name               = "Check"
        check.Size               = UDim2.new(0, 28, 1, 0)
        check.Position           = UDim2.new(0, 18, 0, 0)
        check.BackgroundTransparency = 1
        check.Text               = "?"
        check.TextColor3         = C_CHECK
        check.Font               = Enum.Font.GothamBold
        check.TextSize           = 20
        check.TextXAlignment     = Enum.TextXAlignment.Center
        check.TextTransparency   = 1
        check.ZIndex             = 12

        -- Texto del estado (MAS GRANDE: 16px)
        local txt = Instance.new("TextLabel", row)
        txt.Name                 = "Txt"
        txt.Size                 = UDim2.new(1, -52, 1, 0)
        txt.Position             = UDim2.new(0, 50, 0, 0)
        txt.BackgroundTransparency = 1
        txt.Text                 = loadingTexts[i]
        txt.TextColor3           = C_DIM
        txt.Font                 = Enum.Font.GothamBold
        txt.TextSize             = 16
        txt.TextXAlignment       = Enum.TextXAlignment.Left
        txt.TextTransparency     = 1  -- empieza invisible, fade in con la carta
        txt.ZIndex               = 12

        -- Spinner animado solo para "Cargando hub..." (fila 3)
        local spinner = nil
        if i == 3 then
            spinner = Instance.new("TextLabel", row)
            spinner.Name               = "Spinner"
            spinner.Size               = UDim2.new(0, 28, 1, 0)
            spinner.Position           = UDim2.new(1, -30, 0, 0)
            spinner.BackgroundTransparency = 1
            spinner.Text               = "?"
            spinner.TextColor3         = C_ACCENT
            spinner.Font               = Enum.Font.GothamBold
            spinner.TextSize           = 18
            spinner.TextXAlignment     = Enum.TextXAlignment.Center
            spinner.TextTransparency   = 1
            spinner.ZIndex             = 13
        end

        rows[i] = {check=check, txt=txt, dot=dot, spinner=spinner}
    end

    -- Barra de progreso inferior
    local progressBg = Instance.new("Frame", rect)
    progressBg.Name              = "ProgressBg"
    progressBg.Size              = UDim2.new(1, -24, 0, 6)
    progressBg.Position          = UDim2.new(0, 12, 1, -22)
    progressBg.BackgroundColor3  = C_BG_MID
    progressBg.BorderSizePixel   = 0
    progressBg.ZIndex            = 11
    local pbCorner = Instance.new("UICorner", progressBg)
    pbCorner.CornerRadius = UDim.new(1, 0)

    local progressBar = Instance.new("Frame", progressBg)
    progressBar.Name             = "ProgressFill"
    progressBar.Size             = UDim2.new(0, 0, 1, 0)
    progressBar.Position         = UDim2.new(0, 0, 0, 0)
    progressBar.BackgroundColor3 = C_ACCENT
    progressBar.BorderSizePixel  = 0
    progressBar.ZIndex           = 12
    local pfCorner = Instance.new("UICorner", progressBar)
    pfCorner.CornerRadius = UDim.new(1, 0)

    -- Texto "Copy Whitelist" debajo
    local copyLbl = Instance.new("TextLabel", rect)
    copyLbl.Size               = UDim2.new(1, 0, 0, 18)
    copyLbl.Position           = UDim2.new(0, 0, 1, -40)
    copyLbl.BackgroundTransparency = 1
    copyLbl.Text               = "?  Copy Whitelist  ?"
    copyLbl.TextColor3         = C_GLOW
    copyLbl.Font               = Enum.Font.Gotham
    copyLbl.TextSize           = 13
    copyLbl.TextXAlignment     = Enum.TextXAlignment.Center
    copyLbl.TextTransparency   = 1
    copyLbl.ZIndex             = 12

    -- ============================================================
    -- ANIMACION DE ENTRADA FACHERA: escala + fade in + slide up
    -- ============================================================
    rect.Position = UDim2.new(0.5, -210, 0.5, -90)  -- empieza un poco mas abajo
    local uiScale = Instance.new("UIScale", rect)
    uiScale.Scale = 0.7  -- empieza peque?o

    -- Loop de parpadeo del overlay (dentro del rect, confinado por ClipsDescendants)
    local _loadBlinkActive = true
    task.spawn(function()
        task.wait(3)  -- primer parpadeo a los 3s (igual que en el hub principal)
        while _loadBlinkActive and loadBlinkOverlay and loadBlinkOverlay.Parent do
            -- Cerrar: fade in rapido
            TweenService:Create(loadBlinkOverlay,
                TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                {ImageTransparency = 0}):Play()
            task.wait(0.18)
            -- Abrir: fade out suave
            TweenService:Create(loadBlinkOverlay,
                TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
                {ImageTransparency = 1}):Play()
            task.wait(0.12)
            task.wait(5)  -- intervalo entre parpadeos
        end
    end)

    task.spawn(function()
        -- Fade in del backdrop
        TweenService:Create(backdrop, TweenInfo.new(0.4, Enum.EasingStyle.Sine), {BackgroundTransparency = 0.55}):Play()
        task.wait(0.15)

        -- El rect aparece con: escala 0.7->1, posicion slide up, fade in, borde brilla
        TweenService:Create(uiScale, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
        TweenService:Create(rect, TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
            BackgroundTransparency = 0.08,
            Position = UDim2.new(0.5, -210, 0.5, -110),
        }):Play()
        TweenService:Create(stroke, TweenInfo.new(0.5, Enum.EasingStyle.Sine), {Transparency = 0.3}):Play()

        -- Header y texto aparecen en cascada
        task.wait(0.25)
        TweenService:Create(headerLbl, TweenInfo.new(0.35, Enum.EasingStyle.Sine), {TextTransparency = 0}):Play()
        task.wait(0.1)
        TweenService:Create(copyLbl, TweenInfo.new(0.3, Enum.EasingStyle.Sine), {TextTransparency = 0.3}):Play()

        -- Los textos de filas aparecen en cascada
        for i = 1, 3 do
            task.wait(0.08)
            TweenService:Create(rows[i].txt, TweenInfo.new(0.3, Enum.EasingStyle.Sine), {TextTransparency = 0}):Play()
        end

        task.wait(0.3)

        -- ============================================================
        -- SECUENCIA DE CHECKS con delay de 3 segundos cada uno
        -- ============================================================

        -- Paso 1: Conectando (3s delay)
        task.wait(3)
        local r1 = rows[1]
        r1.dot.BackgroundColor3 = C_CHECK
        TweenService:Create(r1.check, TweenInfo.new(0.15), {TextTransparency = 0}):Play()
        r1.txt.Text       = okTexts[1]
        r1.txt.TextColor3 = C_CHECK
        task.spawn(function()
            TweenService:Create(r1.check, TweenInfo.new(0.1), {TextColor3 = C_WHITE}):Play()
            task.wait(0.1)
            TweenService:Create(r1.check, TweenInfo.new(0.25), {TextColor3 = C_CHECK}):Play()
        end)
        TweenService:Create(progressBar, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Size = UDim2.new(0.33, 0, 1, 0)}):Play()

        -- Paso 2: Autenticando (3s delay)
        task.wait(0.5)
        rows[2].txt.Text = "Verificando licencia..."
        task.wait(3)
        local r2 = rows[2]
        r2.dot.BackgroundColor3 = C_CHECK
        TweenService:Create(r2.check, TweenInfo.new(0.15), {TextTransparency = 0}):Play()
        r2.txt.Text       = okTexts[2]
        r2.txt.TextColor3 = C_CHECK
        task.spawn(function()
            TweenService:Create(r2.check, TweenInfo.new(0.1), {TextColor3 = C_WHITE}):Play()
            task.wait(0.1)
            TweenService:Create(r2.check, TweenInfo.new(0.25), {TextColor3 = C_CHECK}):Play()
        end)
        TweenService:Create(progressBar, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Size = UDim2.new(0.66, 0, 1, 0)}):Play()

        -- Paso 3: Cargando hub... con SPINNER animado (3s delay)
        task.wait(0.5)
        rows[3].txt.Text = "Iniciando hub..."

        -- Mostrar y animar el spinner mientras espera
        local r3 = rows[3]
        if r3.spinner then
            TweenService:Create(r3.spinner, TweenInfo.new(0.25), {TextTransparency = 0}):Play()
            -- Animar spinner: rotar simbolos
            local spinFrames = {"?","?","?","?","?","?","?","?"}
            local spinActive = true
            task.spawn(function()
                local sf = 1
                while spinActive do
                    r3.spinner.Text = spinFrames[sf]
                    sf = (sf % #spinFrames) + 1
                    -- Pulso de color en el spinner
                    TweenService:Create(r3.spinner, TweenInfo.new(0.18, Enum.EasingStyle.Sine),
                        {TextColor3 = C_GLOW}):Play()
                    task.wait(0.18)
                    TweenService:Create(r3.spinner, TweenInfo.new(0.18, Enum.EasingStyle.Sine),
                        {TextColor3 = C_ACCENT}):Play()
                    task.wait(0.18)
                end
                -- Ocultar spinner al terminar
                if r3.spinner and r3.spinner.Parent then
                    TweenService:Create(r3.spinner, TweenInfo.new(0.2), {TextTransparency = 1}):Play()
                end
            end)

            task.wait(3)
            spinActive = false
        else
            task.wait(3)
        end

        r3.dot.BackgroundColor3 = C_CHECK
        TweenService:Create(r3.check, TweenInfo.new(0.15), {TextTransparency = 0}):Play()
        r3.txt.Text       = okTexts[3]
        r3.txt.TextColor3 = C_CHECK
        task.spawn(function()
            TweenService:Create(r3.check, TweenInfo.new(0.1), {TextColor3 = C_WHITE}):Play()
            task.wait(0.1)
            TweenService:Create(r3.check, TweenInfo.new(0.25), {TextColor3 = C_CHECK}):Play()
        end)
        TweenService:Create(progressBar, TweenInfo.new(0.6, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            {Size = UDim2.new(1, 0, 1, 0)}):Play()
        -- Borde brilla intenso al completar
        TweenService:Create(stroke, TweenInfo.new(0.3, Enum.EasingStyle.Sine), {Transparency = 0, Color = C_CHECK}):Play()

        task.wait(0.7)

        -- ============================================================
        -- ANIMACION DE SALIDA FACHERA: escala up + fade out + slide up
        -- ============================================================
        TweenService:Create(uiScale, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 1.08}):Play()
        task.wait(0.15)
        TweenService:Create(uiScale, TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {Scale = 0.6}):Play()
        TweenService:Create(rect, TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
            BackgroundTransparency = 1,
            Position = UDim2.new(0.5, -210, 0.5, -160),
        }):Play()
        TweenService:Create(stroke, TweenInfo.new(0.3), {Transparency = 1}):Play()
        TweenService:Create(backdrop, TweenInfo.new(0.35, Enum.EasingStyle.Sine), {BackgroundTransparency = 1}):Play()
        for _, r in ipairs(rows) do
            TweenService:Create(r.check, TweenInfo.new(0.2), {TextTransparency = 1}):Play()
            TweenService:Create(r.txt,   TweenInfo.new(0.2), {TextTransparency = 1}):Play()
        end
        TweenService:Create(headerLbl, TweenInfo.new(0.2), {TextTransparency = 1}):Play()
        TweenService:Create(copyLbl,   TweenInfo.new(0.2), {TextTransparency = 1}):Play()

        task.wait(0.45)

        _loadBlinkActive = false  -- detener loop de parpadeo antes de destruir
        pcall(function() sg:Destroy() end)
        if type(onComplete) == "function" then
            onComplete()
        end
    end)
end

_ZerqonLoadingScreen(function()
    abrirHub()
end)


-- == FIX TEXTO OSCURO: asegurar visibilidad en labels de AuroraToggle sin pisar el gradiente cyan ==
task.spawn(function()
    repeat task.wait(0.1) until _G._hubReady
    local _Players = game:GetService("Players")
    local _lp = _Players.LocalPlayer
    local _hubGui = (game:GetService("CoreGui"):FindFirstChild("f") or _lp.PlayerGui:WaitForChild("f", 10))
    if not _hubGui then return end
    local _mainF = _hubGui:FindFirstChildOfClass("Frame")
    if not _mainF then return end

    local function _fixLabel(obj)
        if obj:IsA("TextLabel") then
            local p = obj.Parent
            while p and p ~= _mainF do
                if p.Name and #p.Name >= 16 and p.Name:sub(1,16) == "AuroraToggleRow_" then
                    -- Solo forzar visibilidad, NO cambiar TextColor3 para preservar el gradiente cyan
                    obj.TextTransparency = 0
                    break
                end
                p = p.Parent
            end
        end
    end

    -- Fijar los que ya existen
    for _, obj in ipairs(_mainF:GetDescendants()) do
        pcall(_fixLabel, obj)
    end

    -- Fijar los que se agreguen al cambiar de tab
    local _fixBusy = false
    _mainF.DescendantAdded:Connect(function(obj)
        if _fixBusy then return end
        _fixBusy = true
        task.spawn(function()
            task.wait()  -- diferir un frame sin usar task.defer (evita re-entrancy)
            if obj and obj.Parent then
                pcall(_fixLabel, obj)
            end
            _fixBusy = false
        end)
    end)
end)




-- ================================================================
-- == MOBILE KNIFE BUTTONS v6
--
-- BOTON EQUIPAR: equipa el knife desde el backpack.
-- BOTON LANZAR (Throw): nuevo flujo mobile con Silent Aim integrado.
--   Flujo al tocar Throw:
--     1. ThrowCharge (delay hasta que termine)
--     2. ThrowHold   (delay hasta que termine, o 0.3s si no existe)
--     3. En cuanto entra en fase ThrowHold -> el siguiente tap en
--        el boton Throw dispara ThrowKnife + FireServer (KnifeThrown)
--        con el target del Silent Aim.
--   Una vez terminado ThrowKnife la secuencia se resetea.
--   No se puede volver a disparar hasta que ThrowKnife termine.
-- ================================================================
task.spawn(function()
    local UIS = game:GetService("UserInputService")
    if not UIS.TouchEnabled then return end

    local Players        = game:GetService("Players")
    local RunService     = game:GetService("RunService")
    local lp             = Players.LocalPlayer
    local pg             = lp:WaitForChild("PlayerGui", 15)
    if not pg then return end

    -- ----------------------------------------------------------------
    -- HELPERS
    -- ----------------------------------------------------------------
    local function getChar() return lp.Character end

    local function getHum()
        local c = getChar()
        if not c then return nil end
        local h = c:FindFirstChildOfClass("Humanoid")
        return (h and h.Health > 0) and h or nil
    end

    local function findKnifeInChar()
        local c = getChar()
        if not c then return nil end
        for _, v in ipairs(c:GetChildren()) do
            if v:IsA("Tool") and (
                v:HasTag("Weapon_Knife") or
                v.Name == "Knife" or
                v.Name:lower():find("knife")
            ) then
                return v
            end
        end
        return nil
    end

    local function findKnife()
        local c  = getChar()
        local bp = lp:FindFirstChildOfClass("Backpack")
        if c then
            for _, v in ipairs(c:GetChildren()) do
                if v:IsA("Tool") and (
                    v:HasTag("Weapon_Knife") or
                    v.Name == "Knife" or
                    v.Name:lower():find("knife")
                ) then
                    return v, "char"
                end
            end
        end
        if bp then
            for _, v in ipairs(bp:GetChildren()) do
                if v:IsA("Tool") and (
                    v:HasTag("Weapon_Knife") or
                    v.Name == "Knife" or
                    v.Name:lower():find("knife")
                ) then
                    return v, "bp"
                end
            end
        end
        return nil, nil
    end

    -- ----------------------------------------------------------------
    -- Estado BOTON EQUIPAR
    -- ----------------------------------------------------------------
    local _equipFired = false
    local _lastEquipT = -999
    local EQUIP_CD    = 0.35

    local function doEquip()
        local now = os.clock()
        if now - _lastEquipT < EQUIP_CD then return end
        if _equipFired then return end
        _equipFired = true
        _lastEquipT = now
        local hum = getHum()
        if not hum then _equipFired = false; return end
        local knife, loc = findKnife()
        if not knife then _equipFired = false; return end
        if loc == "bp" then
            pcall(function() hum:EquipTool(knife) end)
        end
        task.defer(function() _equipFired = false end)
    end

    -- ----------------------------------------------------------------
    -- ESTADO DEL BOTON LANZAR (maquina de estados)
    --
    -- IDLE       -> al tocar Throw: empieza ThrowCharge
    -- CHARGING   -> reproduciendo ThrowCharge; al terminar -> HOLDING
    -- HOLDING    -> reproduciendo ThrowHold (o esperando); el siguiente
    --               tap en Throw dispara -> THROWING
    -- THROWING   -> reproduciendo ThrowKnife + FireServer; al terminar -> IDLE
    -- ----------------------------------------------------------------
    local THROW_STATE = "IDLE"   -- "IDLE" | "CHARGING" | "HOLDING" | "THROWING"

    -- Sincronizar con global para que el slash handler pueda leerlo
    local function _setState(s)
        THROW_STATE = s
        _G._mobileThrowState = s
    end

    -- Delays entre animaciones (en segundos)
    local DELAY_AFTER_CHARGE  = 0.05   -- pausa entre ThrowCharge y ThrowHold
    local DELAY_AFTER_HOLD    = 0.05   -- pausa entre ThrowHold y ThrowKnife
    local DELAY_HOLD_FALLBACK = 0.30   -- espera si ThrowHold no existe

    -- ----------------------------------------------------------------
    -- Helpers de animacion (usa el mismo sistema que KnifeSA)
    -- ----------------------------------------------------------------
    local function getAnimator()
        local c = getChar()
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        return hum and hum:FindFirstChildOfClass("Animator")
    end

    local function loadAndPlay(knife, animName, looped, speed)
        -- Carga y reproduce una animacion del KnifeClient
        local kc = knife and knife:FindFirstChild("KnifeClient")
        if not kc then return nil end
        local animObj = kc:FindFirstChild(animName)
        if not animObj then return nil end
        local animator = getAnimator()
        if not animator then return nil end
        local ok, track = pcall(function()
            return animator:LoadAnimation(animObj)
        end)
        if not ok or not track then return nil end
        track.Priority = Enum.AnimationPriority.Action
        track.Looped   = looped or false
        if track.IsPlaying then
            pcall(function() track:Stop(0) end)
            task.wait()
        end
        pcall(function()
            track:Play(0.05)
            track:AdjustSpeed(speed or 1.0)
        end)
        return track
    end

    local function stopTrack(track)
        if track then
            pcall(function()
                if track.IsPlaying then
                    track.Looped = false
                    track:Stop(0.05)
                end
            end)
        end
    end

    local function waitForTrack(track, maxSecs)
        -- Espera hasta que el track termine o pase maxSecs
        if not track then return end
        local length = 0
        pcall(function() length = track.Length or 0 end)
        -- Esperar a que la pista realmente empiece a reproducirse
        local t0 = os.clock()
        repeat task.wait(0.016) until track.IsPlaying or (os.clock()-t0 > 0.3)
        -- Re-leer length despues de que esta reproduciendose (mas preciso)
        pcall(function() length = track.Length or length end)
        local waitSecs = math.max(0.1, length)
        if maxSecs and waitSecs > maxSecs then waitSecs = maxSecs end
        local done = false
        local conn
        conn = track.Stopped:Connect(function()
            done = true
            pcall(function() conn:Disconnect() end)
        end)
        local t1 = os.clock()
        while not done and (os.clock() - t1) < waitSecs + 0.1 do
            task.wait(0.016)
        end
        pcall(function() conn:Disconnect() end)
    end

    -- ----------------------------------------------------------------
    -- Obtener CFrames para el FireServer del KnifeThrown (Silent Aim)
    -- Usa _KnifeSA_getBestTarget si esta disponible (KnifeSA activo),
    -- fallback al look vector del personaje.
    -- ----------------------------------------------------------------
    local function buildThrowCFrames(knife)
        local myChar   = getChar()
        local myHRP    = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHRP then return nil, nil end

        local throwOrigin = myHRP.Position + Vector3.new(0, 1.5, 0)
        if throwOrigin.Y < 0.5 then
            throwOrigin = Vector3.new(throwOrigin.X, 0.5, throwOrigin.Z)
        end

        -- Intentar usar Silent Aim si esta activo
        local targetPos = nil
        if KnifeSAState and KnifeSAState.enabled and type(_KnifeSA_getBestTarget) == "function" then
            local target = _KnifeSA_getBestTarget()
            if target and target.Character then
                local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                local tHum = target.Character:FindFirstChildOfClass("Humanoid")
                if tHRP and tHum and tHum.Health > 0 then
                    -- Prediccion de movimiento si esta disponible
                    local pred = nil
                    if type(_KnifeSA_getPredictedPos) == "function" then
                        pcall(function()
                            pred = _KnifeSA_getPredictedPos(tHRP, target.Character)
                        end)
                    end
                    targetPos = pred or tHRP.Position
                    -- Clamp vertical
                    local minY = math.max(0.3, tHRP.Position.Y - 1.5)
                    if targetPos.Y < minY then
                        targetPos = Vector3.new(targetPos.X, tHRP.Position.Y + 0.5, targetPos.Z)
                    end
                end
            end
        end

        -- Fallback: apuntar al frente del personaje
        if not targetPos then
            targetPos = throwOrigin + myHRP.CFrame.LookVector * 30
        end

        local aimVec = targetPos - throwOrigin
        if aimVec.Magnitude < 0.01 then aimVec = myHRP.CFrame.LookVector end
        local aimDir = aimVec.Unit

        local handleCF   = CFrame.new(throwOrigin, throwOrigin + aimDir)
        local backDir    = throwOrigin - targetPos
        local targetCF   = backDir.Magnitude > 0.1
            and CFrame.new(targetPos, targetPos + backDir.Unit)
            or  CFrame.new(targetPos)

        return handleCF, targetCF
    end

    -- ----------------------------------------------------------------
    -- SECUENCIA PRINCIPAL DEL BOTON LANZAR
    -- Se llama la primera vez que se toca Throw (fase IDLE).
    -- Inicia ThrowCharge -> ThrowHold -> espera segundo tap.
    -- ----------------------------------------------------------------
    local function startThrowSequence(throwBtn)
        if THROW_STATE ~= "IDLE" then return end
        local knife = findKnifeInChar()
        if not knife then return end

        -- Solo proceder si KnifeClient existe (tenemos animaciones)
        local kc = knife:FindFirstChild("KnifeClient")
        if not kc then return end

        -- ---- FASE 1: CHARGING ----
        _setState("CHARGING")

        -- Weld del knife a la mano para evitar glitches visuales
        local _knifeWeld = nil
        pcall(function()
            local c         = getChar()
            local rightHand = c and (c:FindFirstChild("RightHand") or c:FindFirstChild("Right Arm"))
            local kHandle   = knife:FindFirstChild("Handle")
            if rightHand and kHandle then
                _knifeWeld = Instance.new("WeldConstraint")
                _knifeWeld.Part0 = rightHand
                _knifeWeld.Part1 = kHandle
                _knifeWeld.Parent = kHandle
            end
        end)

        -- Reproducir ThrowCharge
        local chargeTrack = loadAndPlay(knife, "ThrowCharge", false, 1.0)
        if chargeTrack then
            waitForTrack(chargeTrack, 3.0)
        else
            task.wait(0.4)   -- fallback si no existe la animacion
        end
        stopTrack(chargeTrack)
        task.wait(DELAY_AFTER_CHARGE)

        -- ---- FASE 2: HOLDING ----
        _setState("HOLDING")

        local holdTrack = nil
        local holdExists = kc:FindFirstChild("ThrowHold") ~= nil
        if holdExists then
            holdTrack = loadAndPlay(knife, "ThrowHold", false, 1.0)
            -- No esperamos a que termine: el jugador decide cuando lanzar
            -- Solo esperamos que empiece a reproducirse
            local t0 = os.clock()
            repeat task.wait(0.016) until (holdTrack and holdTrack.IsPlaying) or (os.clock()-t0 > 0.5)
        else
            -- No hay ThrowHold: congelar ThrowCharge en el ultimo frame
            if chargeTrack then
                pcall(function()
                    chargeTrack.Looped = true
                    if not chargeTrack.IsPlaying then chargeTrack:Play(0.05) end
                    chargeTrack:AdjustSpeed(0)
                end)
            end
            task.wait(DELAY_HOLD_FALLBACK)
        end

        -- Ahora el sistema esta en HOLDING.
        -- El segundo tap en Throw (hookThrowRelease) cambiara el estado a THROWING.
        -- Esperamos aqui con un timeout maximo de 8 segundos.
        local waitStart = os.clock()
        while THROW_STATE == "HOLDING" and (os.clock() - waitStart) < 8.0 do
            task.wait(0.05)
        end

        -- Si se cancelo o expiro sin que nadie dispare -> reset
        if THROW_STATE ~= "THROWING" then
            stopTrack(chargeTrack)
            stopTrack(holdTrack)
            pcall(function() if _knifeWeld and _knifeWeld.Parent then _knifeWeld:Destroy() end end)
            _setState("IDLE")
            return
        end

        -- ---- FASE 3: THROWING ----
        stopTrack(holdTrack)
        if chargeTrack then
            pcall(function() chargeTrack.Looped = false end)
            stopTrack(chargeTrack)
        end
        task.wait(DELAY_AFTER_HOLD)

        -- Remover weld antes de lanzar
        pcall(function()
            if _knifeWeld and _knifeWeld.Parent then _knifeWeld:Destroy() end
        end)

        -- Reproducir ThrowKnife
        local throwTrack = loadAndPlay(knife, "ThrowKnife", false, 1.0)

        -- FireServer del KnifeThrown con Silent Aim
        local handleCF, targetCF = buildThrowCFrames(knife)
        if handleCF and targetCF then
            local events = knife:FindFirstChild("Events")
            local knifeThrown = events and events:FindFirstChild("KnifeThrown")
            if knifeThrown then
                -- Bloquear ThrowHold replicado por servidor
                if KnifeSAState and KnifeSAState._blockThrowHoldAfterThrow then
                    pcall(KnifeSAState._blockThrowHoldAfterThrow)
                end
                -- Registrar tiempo de throw mobile para bloquear slash post-throw
                if KnifeSAState then
                    KnifeSAState._lastMobileThrowTime = os.clock()
                end
                -- FIX KNIFE VISUAL: habilitar KnifeClient brevemente para que el
                -- servidor pueda spawnear el ThrowingKnife en workspace.
                -- Sin esto el knife no sale volando aunque el FireServer se ejecute.
                local kc2 = knife:FindFirstChild("KnifeClient")
                if kc2 then
                    pcall(function() kc2.Disabled = false end)
                end
                -- Disparar - probar firmas conocidas de KnifeThrown
                local fired = false
                pcall(function() knifeThrown:FireServer(handleCF, targetCF); fired = true end)
                if not fired then pcall(function() knifeThrown:FireServer(targetCF, handleCF); fired = true end) end
                if not fired then pcall(function() knifeThrown:FireServer(targetCF); fired = true end) end
                if not fired then pcall(function() knifeThrown:FireServer(handleCF) end) end
                -- Volver a deshabilitar KnifeClient despues de un frame
                -- para que no tome control del movimiento del personaje
                task.defer(function()
                    if kc2 and kc2.Parent then
                        pcall(function() kc2.Disabled = true end)
                    end
                end)
            end
        end

        -- Esperar que ThrowKnife termine antes de resetear
        if throwTrack then
            waitForTrack(throwTrack, 3.0)
            stopTrack(throwTrack)
        else
            task.wait(0.6)
        end

        _setState("IDLE")
    end

    -- ----------------------------------------------------------------
    -- HOOKEAR BOTONES
    -- ----------------------------------------------------------------
    local _equipHooked = false
    local _throwHooked = false

    local function hookButtons()
        local gcui = pg:FindFirstChild("GameplayControlsUI")
        if not gcui then return false end
        local tc = gcui:FindFirstChild("TouchControls")
        if not tc then return false end
        local rb = tc:FindFirstChild("RightBar")
        if not rb then return false end

        -- Boton EQUIPAR
        if not _equipHooked then
            local equipBtn = rb:FindFirstChild("EquipWeapon")
            if equipBtn then
                pcall(function() equipBtn.Activated:Connect(doEquip) end)
                _equipHooked = true
            end
        end

        -- Boton LANZAR (puede llamarse "Throw" segun el GameplayControlsScript)
        if not _throwHooked then
            local throwBtn = rb:FindFirstChild("Throw")
                          or rb:FindFirstChild("ThrowBtn")
                          or rb:FindFirstChild("Lanzar")
            if not throwBtn then
                -- Buscar tambien en BottomBar
                local bb = tc:FindFirstChild("BottomBar")
                if bb then
                    throwBtn = bb:FindFirstChild("Throw")
                            or bb:FindFirstChild("ThrowBtn")
                end
            end
            if throwBtn then
                -- Primera activacion (IDLE -> CHARGING) o segunda activacion (HOLDING -> THROWING)
                pcall(function()
                    throwBtn.Activated:Connect(function()
                        if THROW_STATE == "IDLE" then
                            -- Iniciar la secuencia en un coroutine separado
                            task.spawn(startThrowSequence, throwBtn)
                        elseif THROW_STATE == "HOLDING" then
                            -- Segundo tap: disparar el knife
                            _setState("THROWING")
                        end
                        -- En CHARGING o THROWING: ignorar taps extra
                    end)
                end)
                _throwHooked = true
            end
        end

        return _equipHooked  -- exito minimo si equip ya esta hooked
    end

    if not hookButtons() then
        local watcher
        watcher = pg.DescendantAdded:Connect(function(desc)
            local n = desc.Name
            if n == "EquipWeapon" or n == "Throw" or n == "ThrowBtn" or n == "Lanzar" then
                task.wait(0.1)
                hookButtons()
                if _equipHooked and _throwHooked then
                    watcher:Disconnect()
                end
            end
        end)
    end

    lp.CharacterAdded:Connect(function()
        _equipHooked  = false
        _throwHooked  = false
        _setState("IDLE")
        task.wait(0.6)
        hookButtons()
    end)
end)
-- ================================================================
-- == FIN MOBILE KNIFE BUTTONS v6
-- ================================================================